INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun Ya', 'yoksun-ya-ersin-gurdal-2gjmp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırmızıya çalan, parlak yansımalı mehtaba bakmak vardı seninle

      El eleyken içimdekileri bütün derinliğiyle anlatabilmek

      Gözlerine bakarken mutluluktan ağlayabilmek vardı

      Yoksun ya ağlayamam sensizliğe, izin vermez duygular.

      Kapattığın gözlerinle iç çekişini görebilmek vardı seninle

      Yüzündeki tebessümün benim mutluluğumdan doğduğunu düşünmek

      Kalp atışlarını, nefes alışlarının titrekliğinden anlayabilmek vardı

      Yoksun ya anlayamam sensizliği izin vermez duygular.

      Havanın soğukluğunu, senin sıcaklığının yok ettiğini hissedebilmek vardı

      Omzuma yattığında ayın şavkının vurduğu her yanını seyretmek

      Ve o gecenin hiç bitmeme isteğini içimde keşfetmek vardı

      Yoksun ya keşfedemem sensizliği, izin vermez duygular.

      Yıllar sonra hatırlayabileceğim bir geceye sahip olmak vardı seninle

      Bildğim halde, sana aşık olduğumu tekrar anlayabilmek

      Elimi daha sıkı kavradığında bir buseyle karşılığını verebilmek vardı

      Aşk yaşama isteği vardı bende

      Yoksun ya isteyemem senden, izin vermez duygular.', 'Kırmızıya çalan, parlak yansımalı mehtaba bakmak vardı seninle       El eleyken içimdekileri bütün derinliğiyle anlatabilmek       Gözlerine...', ARRAY['Türk Edebiyatı','Şiir','Ersin Gürdal']::text[], 8.5, '{"poet":"Ersin Gürdal","poet_slug":"ersin-gurdal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yoksun-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini Saklama Çiçekleri', 'kendini-saklama-cicekleri-cezmi-ersoz-m96da', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz aşk bahçemizi küçük tuttuk

seninle

içinde güvensizlik ağaçları,

küstüm otları

kendini saklama çiçekleri

Özlem kirli bir kan gibi yüreklerimizi boğmasın

yalnızlık karanllık bir orman gibi

çökmesin içimize diye

biz aşk bahçemizi küçük tuttuk seninle

Önümüzde dokunuşlardan uzak,

İnsafsız ve çok uzun bir kış var diye

koca bir yaz kendini saklama çiçeklerini

suladık durduk yalnızca

Biz aşk bahçemizi küçük

çok küçük tuttuk seninle...', 'Biz aşk bahçemizi küçük tuttuk seninle içinde güvensizlik ağaçları, küstüm otları kendini saklama çiçekleri Özlem kirli bir kan gibi yürekle...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kendini-saklama-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlıyorum Galiba', 'basliyorum-galiba-bayram-karaali-cxoyh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aldığım yudumdun sen; kadehimdeki  olmamış ayva tadı, 

Sonbahar tadlarını  leylak kokularında, şoselerinde ararken, 

Anam güz kavurmasında, kavunda Diyarbekir  kermeli, 

Siyah beyaz resmindi, gözlerin söylüyordu, kelebek yalnızlığını...

İtiraf edeyimmi ey  havva anam, sevgilim, kadınım, aşkım, 

Denizlerin  kayası çarpmadan ayrılmayan, balığın zokası, 

Yakamozun  sarhoş pezevengi güneşin aya kıskanç bakışları, 

Sen; Güneşe yolculuğumun yüzon lirası...

Mart ın 12 sinde birde  yalın kazık gelmemişmiydim? 

Gece oniki saat  vede gündüz? tamı tamına oniki saaat, 

Firavun dediki,  bak evlat; etti, tam yirmidört saat, 

Meşe yaprağı, su teresi, özleyipte kavuşamadığım....

Kartlaşmış ısırgan otu, gözlerin kör edici sütleğeni, 

Ne elimde nede yaprak açtığım   baharlarımdaydı, 

Saklanan, gizlenen, kör olası bir yalnız köpek inlemeseydi, 

Yarasını saran, gece karanlığının bir kurt yalnızlığıydı....

22.04.2002', 'Aldığım yudumdun sen; kadehimdeki  olmamış ayva tadı,  Sonbahar tadlarını  leylak kokularında, şoselerinde ararken,  Anam güz kavurmasında, ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/basliyorum-galiba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlamak', 'baslamak-bayram-karaali-wjsbv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yimibeşten vazgeçtim yahu  anlasana, otuz beş erken, 

Otuzbeşimde güzelmiş meğerse, kırkına bıçak dı bence, 

Yağmurun tırpanıydı, kırtbeşte geçti hozanlarıda, 

Ay çıkardı her zaman nedense dar zamanlarımda..

Bir ağlamaklı türkü olmalı zamane sevdalarımda, 

İsa  yı   kutsuyorum  ben; yalınkılıç  erken akşamımda, 

Bahar selleri nede gürül gürüldür namussuz dut yaprağında, 

Kelebekleri kadar ömürsüz; Göğsümde göremediğim renkleriyle, 

Gününe  sakın  istasyon sayma  ne olur  yetim aşkıyım ben, 

Kuzeyimden geldi beni böyle söyleten kırçıl sakallı, 

Aynı nehir ve göldü yalnızlıklarımıza kan kustuğumuz, 

Ayna keşfedilememişti bebeğim; İyiki varsın dediğimiz..

22.04.2002', 'Yimibeşten vazgeçtim yahu  anlasana, otuz beş erken,  Otuzbeşimde güzelmiş meğerse, kırkına bıçak dı bence,  Yağmurun tırpanıydı, kırtbeşte ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/baslamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşkeler Bol Hayatımda', 'keskeler-bol-hayatimda-bayram-karaali-ec5fn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne çok bol keşke var hayatımda, çöplükler kadar, 

Keşke kaşın bu kadar dik kalkmasaydı hatıralarda, 

Keşke affedeceklerine bu denli katil olmasaydın, 

Nedense sinemdi keşkeler  bozkır istasyonuydu..

Keşkeleri  yitirmem ben asla keşkeler hayatım oldu, 

Gece karanlığı, namussuz yağmurdu nedense keşkelerimle, 

Hoş, sıcak ve bedenimdin, kabuslarımın karanlığı, 

Nede keşkelerin namussuzluğu yalın ve keskin, 

Farkındamısın; kurt uluması kadar gaddardı  gecemde şafağımda, 

Bir eski düşmandı baktığın, kanlın bedel ödediğin, 

Kaşın kalkık bolca  kan doğramada olmasyadı keşke, 

Beni ben eden bir ağlıyaydın, beni ben eden bir havvaydın.

Ağlamalarında havvalığında nerede hangi dağ başında, 

İndik ovalara indik yaya yollara elimizde demir asa, 

Demir çarıklı, Sabrımı olurdu; Musa ne yaptıki? 

İsa geldi; sabrına namert, Keşkelerine bedbaht....

Doymadım keşkelere  nedense, niyeydi bilsem, 

Keşkeleri bol keşkeleri seven bir deli işte, , 

Katıktı yolculuğuma dağarcığımda demir asam, 

Demir çarığımla, adına sevda dediler, yağan yağmurumda, 

Sabahlarına kan kustum, sabahlarımdaki kan öksürmemle, 

Şafak yalnız, şafak sessiz şafak sakindi öksüz ve yetim, 

Adımlarımdaydı keşkeler, sırat köprüsü kadar kıl ince, 

Dayanılmaz keşekelerdi uyandınmı sabahına  bebeğim..

Kırk tas mı sulamalı beni kırk günahla, keşkeler ya, 

Sabahıma geldiğimde gecem kurtlarla gecem keşkelerleydi, 

İtin uğursuzun tek soyuydum, keşkelerim işten bundandı, 

Çınar yaprağı, karga bağırması martı uğuldamasıydı, 

Keşkeler hayatımdı, sabah kahvaltısında, gözlerim yine kanlı, 

Bakmasaydın öyle, Söylemeseydin keşke, uğursuz, namussuza, 

Ben bilirim keşkelerimi, şafak yalancılığında, 

Bırak  gitsin;  eşkiya diyen olsaydın.....

Belki keşkelerimi gönderecektim gelmemecesine, 

Kaşının kalkmasını hep sevdim kızıl saçlım yüreğim, 

Keşke utandıran  olmasaydım, çocukluğum kadar utangaç, 

Babam değildin ki; anamdın sevdalım kardeşim herşeyim..

Söylemeseydin ya utanmazlığımı, utanç içindeyken, 

Anamdın kıymasaydın ya doğurduğuna, evladına

Resmini koymadınmı hiç karşına? yürek resmini? 

Ben sendim, ben senindim, evladın, dostun herşeyin..

Keşkeleri bol bir adam vesselam, nede çok keşkeyle yaşadım, 

Sabah uyanmalarımı bilmezsin sen, ne senle nede sensiz, 

Keşkeler uğursuz hoyrat, gaddar vede sen katilsin, 

Acımasız yürek idamında, bir bilsen içimi öğrenemezsin..

Keşkeler çoookkkk.hemde pazar malı kadar ucuz, 

Kafiyeler şiirimde bile olmamalı derken, hayatın manzumuydu bu, 

Keşkeler bir yalnız ağaç, güneştepede o kadar da şendi güya, 

O çocukluğum kadar seyrettiğim bir kıraç ağaç vede sonsuz.

Keşkelere  inat, Keşkelere dururum demeyin, keşkeler hayat, 

Almasan cıngılında duran üzümü, koparmasan hayatından, 

Basmasan çakır taşa düşmesen boyun üstü anlaşılırmı? 

Keşkeleri yaşatır işte, keşkeler hayat keşkeler gerçek...

Olmasaydı keşke derken, bilenmiydin yasak elmayı, 

Olmasaydı keşke derken bilirmiydin incir yaprağını, 

Olmasaydı keşke derken bilirmiydin güneşi, 

Keşkeler öğretti elmayı, yaprağı ve de güneşi...

Keşkelere inat, Keşkeler sevda, keşkelere borcumuz var, 

Keşkeler öğretmedimmi biz olmayı, keşkelerdi sevdayı yenilemeyi, 

Keşkelerdi ta elmaya, incire güneşe, zührenin ışığına, 

Keşkelerdi bana bunu bana yazdıranlar, sana söyleten...

10.04.2002', 'Ne çok bol keşke var hayatımda, çöplükler kadar,  Keşke kaşın bu kadar dik kalkmasaydı hatıralarda,  Keşke affedeceklerine bu denli katil ol...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/keskeler-bol-hayatimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesik', 'kesik-cemal-sureya-1s562', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sokaktaki adamların gözlerinde yitik

Nasıl oluyor bir türlü anlamıyorum

Arada bir barış arada bir gökyüzü

Her şeyin güzeli aşkla beraber

Kesik kesik

Hiç durmadı aşk dursa bile dünya', 'Sokaktaki adamların gözlerinde yitik Nasıl oluyor bir türlü anlamıyorum Arada bir barış arada bir gökyüzü Her şeyin güzeli aşkla beraber Kes...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kesik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Kadınlar', 'eski-kadinlar-cemal-sureya-bitp0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baktık çıldırmak işten değil 

Söndürüp attık cigaramızı 

Baktık olacak gibi değil 

Bir adam düşündük camların arkasında 

Baktık beyaz pardesülü burunlu 

Bir adam birdenbire peydahlandı 

Kaptığımız gibi şapkamızı eski 

O eski kad
..........
..........', 'Baktık çıldırmak işten değil  Söndürüp attık cigaramızı  Baktık olacak gibi değil  Bir adam düşündük camların arkasında  Baktık beyaz pardes...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eski-kadinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piyale', 'piyale-cemal-sureya-wnxvu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıra hep son kadehe geliyordu 

Dudakların başkalarının masasında lâle 

Ben boynumdaki ipe bir düğüm daha atı 

                                             yordum 

Peşinden
..........
..........', 'Sıra hep son kadehe geliyordu  Dudakların başkalarının masasında lâle  Ben boynumdaki ipe bir düğüm daha atı                                ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/piyale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge Oyunu', 'golge-oyunu-cemal-sureya-m1oxe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gölgeme bak gölgeme 

Amma aşık, amma divane 

Oturmuş kanepesinde gurbet elin 

Kendini seyreder gözlerimde 

Amma aşık, amma divane. 

Gölgene bak senin gölgene 

Amma fakir, amma
..........
..........', 'Gölgeme bak gölgeme  Amma aşık, amma divane  Oturmuş kanepesinde gurbet elin  Kendini seyreder gözlerimde  Amma aşık, amma divane.  Gölgene ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/golge-oyunu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-haci-mehmet-erol-kix8a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne sırça köşk

Ne yakut saray

Ne sağ elimde güneş

Ne sol elimde ay

Ne bir elim yağda 

Ne bir elim balda

Ne anka kuşu, kaf dağı

Ne tarihin altın çağı

Ne yatağım kuş tüğü

Ne yemyeşil yeri, mavi göğü

İSTEMEM

Ne sevindirir bolluk

Ne yerindirir yokluk 

İstediğim sadece

Bir parçacık mutluluk', 'Ne sırça köşk Ne yakut saray Ne sağ elimde güneş Ne sol elimde ay Ne bir elim yağda  Ne bir elim balda Ne anka kuşu, kaf dağı Ne tarihin alt...', ARRAY['Türk Edebiyatı','Şiir','Hacı Mehmet EROL']::text[], 8.5, '{"poet":"Hacı Mehmet EROL","poet_slug":"haci-mehmet-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mutluluk-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısacık', 'kisacik-oguzkan-bolukbasi-7nvg3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Küçük ateşler yakarsın

Ne içindir bilmeden

Ama önce ısınırsın

Anlatmanın kimseye faydası olmadığı öykülerdir

Tek başınasın

Gizlisin kendine bile

Beynin inkarda

Aklın firarda

Yüreğin  el yordamıyla bulur damarlarını, yaşadığını söyler

Hissettiğin herşeyin yaşamak olduğunu

Bin kez talan edilmiş bahçede 

Açan her çiçek korkudur

Ve heyecan varmışım dedirten

İnanmak zordur kokularına baharların

Sonbaharın kışa yaklaşırken', 'Küçük ateşler yakarsın Ne içindir bilmeden Ama önce ısınırsın Anlatmanın kimseye faydası olmadığı öykülerdir Tek başınasın Gizlisin kendine ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kisacik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlemek', 'seni-ozlemek-tevfik-karinca-gw757', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanında olmalıyım, 

Tüm heyecanımla; 

Uzaklıkların hiç önemi olmamalı, 

Seni yaşarken tüm duygularım...

Her yanım sen olmalı, 

Hiçbir şeyi umursamadan

Sevmekten usanmadan.

Başını göğsüme alıp

Yanında olmalıyım', 'Yanında olmalıyım,  Tüm heyecanımla;  Uzaklıkların hiç önemi olmamalı,  Seni yaşarken tüm duygularım... Her yanım sen olmalı,  Hiçbir şeyi u...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-ozlemek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilgim Kime', 'yenilgim-kime-fatih-cunus-9i2s8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yenilgim geri dönemediğim çocukluğuma

Zamana, üzünçlerime

Ya da üzüldüğümü sandığım geçmişe

Yenilgim sana belki de sensizliğe

Varoluşuna veya ansızın yokoluşuna

Kendime ve  benden eksilmene

Yenilgim yazmaya çalıştığım yazgıya

Ve defalarca yazılıp çizilen

Ne idüğü belirsiz yazgıya

Yenilgim başlamadan biten aşka

Devamsızlıktan sınıfta bıraktığım aşka

Karnesi kalp kırıklarıyla dolu aşka

Yenilgim hükmen mağlup başladığım hayata

Eninde ve sonunda yenik düştüğüm hayata

Galibiyet yüzü göremediğim hayata', 'Yenilgim geri dönemediğim çocukluğuma Zamana, üzünçlerime Ya da üzüldüğümü sandığım geçmişe Yenilgim sana belki de sensizliğe Varoluşuna vey...', ARRAY['Türk Edebiyatı','Şiir','Fatih Cünüş']::text[], 8.5, '{"poet":"Fatih Cünüş","poet_slug":"fatih-cunus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yenilgim-kime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişim', 'degisim-tevfik-karinca-622ek', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'değişecek dünya sevginle

tüm umutlar gerçek olacak

hayaller hayal olmaktan

masallar masal olmaktan çıkacak

saracak ellerim seni

bırakmamacasına

gözlerim gözlerinde kalacak

sevginle değişecek dünya

bu yürek hep sana tapacak', 'değişecek dünya sevginle tüm umutlar gerçek olacak hayaller hayal olmaktan masallar masal olmaktan çıkacak saracak ellerim seni bırakmamacas...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/degisim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmasan', 'sen-olmasan-tevfik-fikret-ygnqt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen olmasan... 

Seni bir lâhza görmesem yâhut, 

Bilir misin ne olur? 

Semâ, güneş ebediyyen kapansa, belki vücud 

Bu leyl-i serd ile bir çâre-i teennüs arar, 

Ve bulur; 

Fakat o zulmete mümkün müdür alıştırmak 

Bütün güneşle, semâlarla beslenen rûhu, 

Bu rûh-ı mecrûhu? .. 

Sen olmasan... 

Seni bulmak hayâli olsa muhâl, 

Yaşar mıyım dersin? 

Söner ufûlüne bir lâhza kaail olsa hayâl; 

Soğur, donar, kırılır senden ayrılınca nazar 

Ne hazin 

Gelir hâyât o zaman hem vücûda hem rûha, 

Yaşar mıyız seni kaybetsek âh ben, kalbim, 

Bu kalb-i muztaribim? 

Sen olmasan... 

Bu samîmî bir îtirâf işte; 

Sen olmasan yaşayamam: 

Seninle rabıtamız hoş bir îtilâf işte; 

Fakat bu râbıta hâlî mi rûhu ezmekten? ... 

Akşam 

Gurûba karşı düşündüm sükûn içinde bunu: 

Fenâ değil sevişip ağlamak, fakat heyhât, 

Bükâya değse hayat! ..', 'Sen olmasan...  Seni bir lâhza görmesem yâhut,  Bilir misin ne olur?  Semâ, güneş ebediyyen kapansa, belki vücud  Bu leyl-i serd ile bir çâr...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-olmasan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrim', 'devrim-bulent-gok-c05zt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birgün çıplak ayaklarla geleceğim kapına, 

Yalınayak geleceğim seni aramak için.

Bir gece ansızın kapını çalan kişi olacağım, 

Ve ellerimde yitik umutlarım olacak...

Kapında bekleyeceğim, sen açana dek, 

Yağmura aldırmayıp bekleyeceğim, 

Gözlerim gözlerine dalınca, 

Gözlerini özlediğimi söyleyeceğim...', 'Birgün çıplak ayaklarla geleceğim kapına,  Yalınayak geleceğim seni aramak için. Bir gece ansızın kapını çalan kişi olacağım,  Ve ellerimde ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Gök']::text[], 8.5, '{"poet":"Bülent Gök","poet_slug":"bulent-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/devrim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenikapı Mevlevihanesine Mersiyye', 'yenikapi-mevlevihanesine-mersiyye-nizam-neyyir-cthhd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tarih doksanyedi mayısı idi

işçiler yürümüş

toprak yürümekte idi

son kalıntıları yas bağlamış

ağlamaklı idi

meşum bir el uzanmış

bir mirası yakmakta idi

zaman geçse bile

yüreğim yanmıştı, 

hala yanmakta idi', 'tarih doksanyedi mayısı idi işçiler yürümüş toprak yürümekte idi son kalıntıları yas bağlamış ağlamaklı idi meşum bir el uzanmış bir mirası ...', ARRAY['Türk Edebiyatı','Şiir','Nizam Neyyir']::text[], 8.5, '{"poet":"Nizam Neyyir","poet_slug":"nizam-neyyir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yenikapi-mevlevihanesine-mersiyye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç', 'gec-nizam-neyyir-pgrr7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gül geç gelir

erken gider

gül geç sövgülere

ne kadar geç büyüse de

geçti geçmezlenen gül mevsimi

geçti, bakire dakikalar

sevgililerin mutlu anları

güzel güller', 'gül geç gelir erken gider gül geç sövgülere ne kadar geç büyüse de geçti geçmezlenen gül mevsimi geçti, bakire dakikalar sevgililerin mutlu ...', ARRAY['Türk Edebiyatı','Şiir','Nizam Neyyir']::text[], 8.5, '{"poet":"Nizam Neyyir","poet_slug":"nizam-neyyir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gec-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönemezsin Geriye', 'donemezsin-geriye-hulya-arisan-6so5m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilirmisin 

insan sevdimi, 

ne yapar.

Bilirmisin 

coşkular ne çok 

artar.

Gün gelir 

kanatlanır uçarsın

gün gelir pat diye yere

çakılırsın.

Uzatırsın elini kaldıran

vardır diye. 

Geçmiştir günler artık, 

DÖNEMEZSİN GERİYE...

İstanbul,8 mayıs 2002', 'Bilirmisin  insan sevdimi,  ne yapar. Bilirmisin  coşkular ne çok  artar. Gün gelir  kanatlanır uçarsın gün gelir pat diye yere çakılırsın. ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/donemezsin-geriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-olgun-ergun-wh16o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen varsın ya yanım da

Duyuyorum  ya kokunu

Yaşıyorum ve hissediyorum ya aşkını

Umutsuzca ve umursuzca

Ama olabildiğince  Ben  gibi

Ben gibi seviyorum ya seni

Anlatmadan  yada yazmaksızın 

Sessiz kelimelerle 

İsimsiz dizelerde  yada 

Hiç okunmadık şiirlerde buluyorum ya 

Ne bileyim işte

Seviyorum hepsi bu

(olgun ergün.24.03.2002)', 'Sen varsın ya yanım da Duyuyorum  ya kokunu Yaşıyorum ve hissediyorum ya aşkını Umutsuzca ve umursuzca Ama olabildiğince  Ben  gibi Ben gibi...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ergün']::text[], 8.5, '{"poet":"Olgun Ergün","poet_slug":"olgun-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-146-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitaplar', 'kitaplar-asaf-halet-celebi-m3a6y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kargacık

burgacık

yazılar

yazılar dolu kitaplar

kitaplar dolu yazılar

tüylü tüysüz kargalar

yazılar

yazılar dolusu mürekkep

mürekkepten şekiller

F H

Z U

D W

yarısı kopmuş sicim

yarısı kopmuş kitap

ciltli kitap

ciltsiz kitap

sahifelerdeki yazılar beynimde

beynimdeki yazılar havada

ve harfler muallâkta

yazıların dili yok

benim dilimle söylüyor yazılar

yazıların dili yok

gotik yazılarda ıhlamur

çincelerde çam

hiyeroglifte baykuş

ayak

ve ince adam

mehtapta sarhoş ahûlar

ve yandan bakan göz

ta''lik yazılarda

ve sahifeler bomboş', 'kargacık burgacık yazılar yazılar dolu kitaplar kitaplar dolu yazılar tüylü tüysüz kargalar yazılar yazılar dolusu mürekkep mürekkepten şeki...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kitaplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Romantik Gençliğim', 'romantik-gencligim-asaf-halet-celebi-aq0i3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ejderhalar çıkarıyorum

duvar kovuklarından

alevler çıkarıyorum

yağmur karaltılarında

hazin

yürüyorum

uzattım ellerimi

çok uzaklara gitmiş

yıldızlar düşürmüş gelirken

yıldızsız kalınca gece

uyunur

tavanı yok siyah gök

sırtüstü yere yattım

tavansız göğe düşüyorum', 'ejderhalar çıkarıyorum duvar kovuklarından alevler çıkarıyorum yağmur karaltılarında hazin yürüyorum uzattım ellerimi çok uzaklara gitmiş yı...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/romantik-gencligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Stres Nedir Bilirmisin?', 'stres-nedir-bilirmisin-oguz-adas-09osi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günde yüz elli telefonu cevaplarsan, 

Haksız yere fırça yiyipte susmak zorunda kalırsan, 

Gün boyu çalışanların  didişmelerini izliyorsan, 

Stres nedir bilirsin........

Vasıfsız biri sana müdür yapılmak isteniyorsa, 

Eşekler gibi çalışıp, 

Bir sürü iş başarıp'' ta  bir teşekkür sana çok görülüyorsa, 

İşler üst üste gelip hepsi acil olursa, 

Stres nedir bilirsin........

Günün iyi geçmesi, müdürünün günlük psikolojisine bağlıysa, 

Üç kişi performansı ile çalışman beklenip, sen sadece bir kişiysen, 

Her akşam en erken akşam saat yedi'' de işten çıkabiliyorsan, 

Stres nedir bilirsin........

Oğuz ADAŞ', 'Günde yüz elli telefonu cevaplarsan,  Haksız yere fırça yiyipte susmak zorunda kalırsan,  Gün boyu çalışanların  didişmelerini izliyorsan,  ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Adaş']::text[], 8.5, '{"poet":"Oğuz Adaş","poet_slug":"oguz-adas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/stres-nedir-bilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünceye Düşünce', 'dusunceye-dusunce-yalcin-ergun-kx8k7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu ne çirkef ya Rabbi! Ne denli bir muamma, herkes kendi kendine zehir eder dünyayı

Nasıl bir sıkıntı bu? Nasıl ki bir bunalma, bütün hücrelerimiz dost edinmiş riyayı

Boğazımda bir düğüm yüreğimde daralma, her gece yaşarım bu kabus dolu rüyayı

Üstümde bir ağırlık gözlerimde kararma, kekeleyen sözlerle gizlerim bu sevdayı

Bu irkilme bu buhrân sanki çıkmaz bir sokak, kendi hayallerimizle korkudan titriyoruz

En yakın bildiklerden yedik hep sille tokat, çukuru biz kazıyor yine biz düşüyoruz

Hayat bir girdap olmuş sonu dert sonu batak, çabalayıp bocalayıp iyice batıyoruz

Edep virane düşmüş uzanmış yorgan yatak, tüccar erbabı olduk aşkı da satıyoruz

Paramparça yüreğim yanıyorum biçâre, ağlamak istesem de gözpınarım kurumuş

İsyan etmek faydasız yalvarsam da ne çare, zihnim zaten kendine darılmaktan yorulmuş

Ben gönülden uçarı gönül benden avare, nev-i bahar başında deli kanım durulmuş

Üzgünüm ama yine söz geçmiyor o yâre, neden ki bende hâla baş köşeye kurulmuş...

16.08.1995', 'Bu ne çirkef ya Rabbi! Ne denli bir muamma, herkes kendi kendine zehir eder dünyayı Nasıl bir sıkıntı bu? Nasıl ki bir bunalma, bütün hücrel...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dusunceye-dusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Nişanlım', 'eski-nisanlim-ensar-aktas-s5ovm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ummadığım yerlerde karşıma çıktı

Gözlerimin içine çok derin baktı

Pişmanım diyemedi sadece ağladı

Yıkılmış gibiydi eski nişanlım

Beni çok severdi o bir zamanlar

Aramıza girdi birçok yalanlar

Düşmanımız yoktu, ayırdı dostlar

Yıkılmış gibiydi eski nişanlım

Ağlama dediysem de susturamadım

Elimi uzattıysam da dokunamadım

Dağılmış saçlarını toplayamadım

Yıkılmış gibiydi eski nişanlım

Onun o hallerine dayanamadım

Ogün bugündür heran ağlarım

Unutmak istedim de unutamadım

Yıkılmış gibiydi eski nişanlım

Rotterdam,09.08.1989', 'Ummadığım yerlerde karşıma çıktı Gözlerimin içine çok derin baktı Pişmanım diyemedi sadece ağladı Yıkılmış gibiydi eski nişanlım Beni çok se...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eski-nisanlim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek Kolay', 'gitmek-kolay-ensar-aktas-19eg1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yokluğuna dayanmak çok zor

Hasretinse içimde bir kor

Yakıyor beni, kahrediyor

Gitmek kolay acısını bana sor

Ellerimde titriyordu ellerin

Gözlerimi arıyordu gözlerin

Hatırası vardı o ilk gecenin

Gitmek kolay acısını bana sor

Aşkımız destan olmuştu dillere

Mutlulugumuz sığmıyordu şiirlere

Koşuyorduk seninle güzel günlere

Gitmek kolay acısını bana sor

Nedir sebebi bu değişikliğinin

Sonu mu geldi yoksa sevgimizin

Tüketti beni elveda deyişin

Gitmek kolay acısını bana sor

Rotterdam,30.12.1989', 'Yokluğuna dayanmak çok zor Hasretinse içimde bir kor Yakıyor beni, kahrediyor Gitmek kolay acısını bana sor Ellerimde titriyordu ellerin Göz...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gitmek-kolay-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Arayacaksın Günün Birinde', 'beni-arayacaksin-gunun-birinde-ensar-aktas-744id', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşeceksin sende günün birinde

Kalacak tuttuğun dallar elinde

Kararacak dünyan güzel gözünde

Beni arayacaksın bir ışık gibi

Beni arayacaksın günün birinde

Teselli edecek kimsen olmayacak

Yol gösterecek birisi kalmayacak

Başın dertten hiç kurtulmayacak

Beni arayacaksın bir rehber gibi

Beni arayacaksın günün birinde

Çıkıp gelsem belki de kovacaksın 

İçine bin türlü şüphe sokacaksın

Pişman olup ardımdan koşacaksın

Beni arayacaksın bir çare gibi

Beni arayacaksın günün birinde

Giderek kinin artacak senin yıllara

Ümitle bakacaksın bomboş yollara

Belki de ben ölüp gittikten sonra

Beni arayacaksın bin pişman gibi

Beni arayacaksın günün birinde

Rotterdam,28.07.1989', 'Düşeceksin sende günün birinde Kalacak tuttuğun dallar elinde Kararacak dünyan güzel gözünde Beni arayacaksın bir ışık gibi Beni arayacaksın...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/beni-arayacaksin-gunun-birinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Bana Gelsen Ne Olur', 'bugun-bana-gelsen-ne-olur-ensar-aktas-9oonz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğim aşkınla dolup taşıyor

Anılar hep gönlümde yaşıyor

Hasretin artık sabrımı aşıyor

Bugün bana gelsen ne olur

Uzaklarda senden habersiz

Bir başıma hep çaresiz

Yaşanmıyor sensiz, sevginsiz

Bugün bana gelsen ne olur

Açsamki gözümü karşımdasın

Yadellerde değil yanımdasın

Şu canımdan bir parçasın

Bugün bana gelsen ne olur

Mevsimler değişir bahar olurdu

Akan sular, seller durulurdu

Yuvasız kuşlar mesut olurdu

Bugün bana gelsen ne olur

Rotterdam,30.03.1991', 'Yüreğim aşkınla dolup taşıyor Anılar hep gönlümde yaşıyor Hasretin artık sabrımı aşıyor Bugün bana gelsen ne olur Uzaklarda senden habersiz ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bugun-bana-gelsen-ne-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına', 'i-nadina-emre-ozoran-vv4r4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bak, inadına dolunay var bu gece.

Gözlerindeki gülüşte dilencinin

Umut yok mu? 

Sana gülmek yakışıyor

Biliyorum.  Saklıyorsun.

Hadi, salıver sevinçleri; 

Dağılıp dağılıp gitsinler.', 'Bak, inadına dolunay var bu gece. Gözlerindeki gülüşte dilencinin Umut yok mu?  Sana gülmek yakışıyor Biliyorum.  Saklıyorsun. Hadi, salıver...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/inadina-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-cahit-sanver-z364o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baharımsın gülüm kışlardan kalma, 

Baharlar sana sen bahara yasta.

Gelse de kış gelse de yaz, 

Geçse de ömür palas pandıras, 

Hep gelecek aydınlık

Hep gelecek bir bahar.', 'Baharımsın gülüm kışlardan kalma,  Baharlar sana sen bahara yasta. Gelse de kış gelse de yaz,  Geçse de ömür palas pandıras,  Hep gelecek ay...', ARRAY['Türk Edebiyatı','Şiir','Cahit Şanver']::text[], 8.5, '{"poet":"Cahit Şanver","poet_slug":"cahit-sanver","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bahar-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevdadır Yaşanan', 'bir-sevdadir-yasanan-ali-ayyildiz-x94du', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acılara müptela sayende bu beden

Bir hayalin peşinden gider her zaman

Aşkına ömür boyu hepten şahitlik eden 

Aşkına hüküm giymiş bir sevdadır yaşanan

Sebep ne ki bilinmez seni böyle sevdiren

Senli bir tek an için şu bedenden geçiren

Bir küçük tebessüme ömrü feda ettiren

Anladım ki kalbimde bir sevdadır yaşayan

Böyle olurmuş demek yanıp da dönmek küle

Gönül gitti bir kere dönmüyor tekrar öze

Ne kadar da muhtaçmış bu yürek bir tek söze

Şu bîçare yürekte bir sevdadır yaşayan

Hayal imiş kurduğum kendi kendimce

İmkansız bir umutmuş sevgi kalbimde

Yine de bir volkan gibi gönlümde

Yaşarmış içten içe hiç unutmadan

Şu garip gönlümde bir sevdadır yaşayan', 'Acılara müptela sayende bu beden Bir hayalin peşinden gider her zaman Aşkına ömür boyu hepten şahitlik eden  Aşkına hüküm giymiş bir sevdadı...', ARRAY['Türk Edebiyatı','Şiir','Ali Ayyıldız']::text[], 8.5, '{"poet":"Ali Ayyıldız","poet_slug":"ali-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-sevdadir-yasanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladınmı?', 'anladinmi-cihan-turkmen-ye00l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi anladın mı beni? 

Anlatmak istediğimi 

Bölük pörçük aşk nameleriyle

Ayrılığı anladın mı? 

Ya özlemeyi 

Yıldızlara bakıp 

Hayalinle dans etmeyi, 

Gözlerini, dudaklarını, sözlerini, 

Hepsinden önemlisi 

Beni saran ateş çemberini

                   ANLADINMI?', 'Şimdi anladın mı beni?  Anlatmak istediğimi  Bölük pörçük aşk nameleriyle Ayrılığı anladın mı?  Ya özlemeyi  Yıldızlara bakıp  Hayalinle dan...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anladinmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sihirli Bakışlar', 'sihirli-bakislar-cihan-turkmen-bab7r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bakış aradım gözlerinde; 

                Sevgi dolu, utangaç

                Dokunmak istedim yüreğine; 

                Yüreğimden bir kuş uçurdum

                Bembeyaz bir güvercin

      Uçarak geldi sana, 

                Yüreğim bir garip

                Yüreğim suskun 

                Bir saat vardı eskiden yüreğimde 

                Oda şimdi suskun 

                Geçmiyor saniyeler

Saatlere vurmuyor.

Nedendir bilmem 

Sana bir garip bakar gözlerim

Tunuk ve yaşlı

Zamanın içinde bir masal vardı

Benim masalım

Son sayfasına gelindi artık 

Ya mutlu son

Ya da ölüm var

Bilmiyorum neden? 

Nedir aradığım şey? 

Yüreğimden yüreğine akan nehirler mi? 

Bir masal kahramanı sen mi?', 'Bir bakış aradım gözlerinde;                  Sevgi dolu, utangaç                 Dokunmak istedim yüreğine;                  Yüreğimden bir...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sihirli-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Bir İşkence', 'sensizlik-bir-i-skence-cihan-turkmen-5s2nu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerdesin bilmiyorum

Sesini duymuyorum

Seni çok özlüyorum

Dön artık dön gel bana

Sevdasız olmuyor ki

Zamanım dolmuyor ki

Hasretlik bitmiyor ki

Ne olur sen gel bana

Ellerim kelepçelerde

Düşüncelerim hep sende

Ne olur bu işkence 

Gel de bitsin bir an önce', 'Nerdesin bilmiyorum Sesini duymuyorum Seni çok özlüyorum Dön artık dön gel bana Sevdasız olmuyor ki Zamanım dolmuyor ki Hasretlik bitmiyor k...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizlik-bir-iskence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-cihan-turkmen-yiq8f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sonbahar rüzgarlarıyla 

Dökülen ağaç yaprakları gibisin 

Sararıp solmuşsun birden

Nasıl bana sürüklenmişsin

Kim bilir hangi nehirden

İyiki geldin 

Yoksundum senin sevginden

Bir sevgi şelalesi

Belki bir çağlayan

Yıllardır bir tek sensin beni ağlatan

Ve sevgi herşeydir

Aşksa bilmem nedir? 

Belki acı çekmek 

Belki çok sevmek 

Belki sevgiden ölmek', 'Sonbahar rüzgarlarıyla  Dökülen ağaç yaprakları gibisin  Sararıp solmuşsun birden Nasıl bana sürüklenmişsin Kim bilir hangi nehirden İyiki g...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensizlik-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-cihan-turkmen-re1oc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yorganımı sıkı sar

Üşüyorum bu yaz gününde 

Bu kadar sıcağa rağmen üşüyorum

Sıcacık tenine muhtacım

Seviyorum seni

Seviyorum be...

Bunlar sebep seni görmeye

Cehennem ateşi de olsa üşüyorum

Gel de ısıt beni', 'Yorganımı sıkı sar Üşüyorum bu yaz gününde  Bu kadar sıcağa rağmen üşüyorum Sıcacık tenine muhtacım Seviyorum seni Seviyorum be... Bunlar se...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/usuyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmak', 'unutulmak-cihan-turkmen-rdtul', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doğduğum gün unutulmak

Birer birer silinmek akıllardan

Sitemle haykırmak belki

Ben burdayım diye

Fark edilmek için 

Ömrümü sunmak ellerine

Ve yavaş yavaş ölümü tatmak ellerinde', 'Doğduğum gün unutulmak Birer birer silinmek akıllardan Sitemle haykırmak belki Ben burdayım diye Fark edilmek için  Ömrümü sunmak ellerine V...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/unutulmak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Uzakta', 'cok-uzakta-cihan-turkmen-pphk5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karşımda bir yol var

Ve yolda arabalar ardı sıra 

Ben yokum bende artık

Gidiyorum uzaklara

Bu kahrolası yerden

Bir an için her arabayla 

Bir adım daha

Gidiyorum gözümü açıncaya dek

DÖNMEYECEĞİM', 'Karşımda bir yol var Ve yolda arabalar ardı sıra  Ben yokum bende artık Gidiyorum uzaklara Bu kahrolası yerden Bir an için her arabayla  Bir...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cok-uzakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damga', 'damga-cihan-turkmen-gatl6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şehrin bir sokağı buğulu camlar 

Ateşli birkaç cigara gecenin koynunda

Açlık beni benden alıp savurmakta

Dileğim bir parça ekmek

İş, güç, para ve emek

Sevgi belki de istediğim

Acı dolu mahpusun ardından

Silinmeyen o gecenin hayali

Göz yaşlarımın buğusundan

Kanlı bir çift çocuk eli 

Ve elindeki bıçak namusun koruyucusu

Karşısında namusun satıcısı hayat

Kadını ağlatan bir tek söz “orospu”

Oğlu gözyaşlarına inat 

Vurur bıçağı ve ömrün yarısı

Yarım ömürle belki de 

Ölümü arıyorum', 'Şehrin bir sokağı buğulu camlar  Ateşli birkaç cigara gecenin koynunda Açlık beni benden alıp savurmakta Dileğim bir parça ekmek İş, güç, pa...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/damga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşkiya', 'eskiya-cihan-turkmen-20wdp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağlardayım açım 

Üç gündür açım

Soğuktan donmuşum

Yarı uykulu gözlerde hayalin

Uykusuzum koyversen dalar giderim

Hayalin ıslatır gözlerimi 

Soğuk dondurur, ağırlaştırır

Beni benden alır

Dağın ardı köyümdü 

Nerde ya şimdi bilmiyorum

İdamdan kaçarken 

Ölüme varıyorum

Ama direniyorum', 'Dağlardayım açım  Üç gündür açım Soğuktan donmuşum Yarı uykulu gözlerde hayalin Uykusuzum koyversen dalar giderim Hayalin ıslatır gözlerimi ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eskiya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Vakka', 'umutsuz-vakka-cihan-turkmen-vg1tv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensizlik, kimsesizlik

Ve sonra sen

Erişilmez uzaklarda

Kim bilir hangi limanda

Demir atmış bir gemi misali

Azgın dalgalarla boğuştuğumu

Bilir misin? 

Bu insan ormanında; 

Yapayalnız bir ağaç gibi 

Dalları kurumuş umutsuz bir vaka', 'Sensizlik, kimsesizlik Ve sonra sen Erişilmez uzaklarda Kim bilir hangi limanda Demir atmış bir gemi misali Azgın dalgalarla boğuştuğumu Bil...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umutsuz-vakka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamıyorum', 'bulamiyorum-cihan-turkmen-0rqsp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulamıyorum, bulamıyorum kendi                                         Belki de bendimin ardındayım

Aşamıyorum bendimi                                                 Yenemiyorum insana sevgimi                                 Aldanıyorum, ağlıyorum                                              Seviyorum, seviyorum be 

Niye bu işkence

Her gün doğuşunda beklemek

 Gün batımın da ağlamak senin için

Rüyamda görüp geldiğini, sevinmek, coşmak

 Ve uyanmak ardı sıra, gözü yaşlı

 Niye sensizlik bitmiyor, bilmiyorum

Ama seni deliler gibi seviyorum', 'Bulamıyorum, bulamıyorum kendi                                         Belki de bendimin ardındayım Aşamıyorum bendimi                      ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bulamiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba', 'acaba-sair-scream5-o29jq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün beni sevebilir misin? 

Sana ellerimi uzattığımda 

Avuçlarına alıp sımsıcak nefesinle

Küçücük bir öpücük 

Kondurur musun ellerime, 

Yüreğinde bana yer verir misin? 

Başımı omzuna koyduğumda, 

Okşar mısın saçlarımı ılık nefesinle, 

Fısıldar mısın kulağıma sevgini, 

Küçücük bir öpücük 

Kondurur musun dudaklarıma, 

Gözlerime bakar mısın sevgiyle, 

Benimle ağlar, benimle güler misin? 

HALIT UMIT DIKKER (scream5)', 'Bir gün beni sevebilir misin?  Sana ellerimi uzattığımda  Avuçlarına alıp sımsıcak nefesinle Küçücük bir öpücük  Kondurur musun ellerime,  Y...', ARRAY['Türk Edebiyatı','Şiir','Şair Scream5']::text[], 8.5, '{"poet":"Şair Scream5","poet_slug":"sair-scream5","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/acaba-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün ki İçindeyim', 'dusun-ki-i-cindeyim-cihan-turkmen-xvd69', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tadı yok sensiz gecenin

Umudu yok sensiz geleceğin 

Her kendi halinde hayallerin

İçinde sen sevdiceğim

Şimdi saat belirsiz

Şimdi saatler sensiz

Şimdinin adı belirsiz

Saat gecenin üçü 

Uykusuz gözlerimde 

Senli günlerin düşü

Uyku yok yıldızlar var 

Senin gözlerinle dolu

Geceler bana dar

Dar geliyor odalar

Yürüyorum yollarda 

İsmi yok sokakların 

Birde boş kadehlerle 

Sensizliğin, efkarın

Umulmadık anılar 

Boy gösteriyorlar

Kimi senin gülüşün 

Kimi sensizlikteki hüzün

Unut diyorum sana bensizliği unut

Düşün ki yanındayım

Düşün kalbinin içinde 

Bir alyuvar hücresi

Düşün ki gözlerinde 

Bir damlayım

Ağlamanın öncesi

Unutulmamak için

Kurutulmamak için 

Yalvarıyorum sana 

Şimdi bak yıldızlara 

Ben varım inan orda', 'Tadı yok sensiz gecenin Umudu yok sensiz geleceğin  Her kendi halinde hayallerin İçinde sen sevdiceğim Şimdi saat belirsiz Şimdi saatler sen...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/dusun-ki-icindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşları', 'gozyaslari-cihan-turkmen-g6syx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir damla gözyaşı 

Bir nehir gibi 

Çağlayan gibi

Sen gibi

Duygu dolu

Ardı sıra  aşk

Sevda kokan 

Savaşın kanla yıkanmayan sokağında 

Saklı bir korku gibi sarar 

Bağlar yüreğimi

Ağlatır beni

Bir damla gözyaşı', 'Bir damla gözyaşı  Bir nehir gibi  Çağlayan gibi Sen gibi Duygu dolu Ardı sıra  aşk Sevda kokan  Savaşın kanla yıkanmayan sokağında  Saklı b...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozyaslari-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlığa Dair', 'yanlizliga-dair-cihan-turkmen-senoa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saatlerce bakmak gözlerine 

Anlatmak derdimi

Suskunluğu yok etmek

Kalbimin çarpışındaki dinamit sesleri ile

Ölümlere dur demek 

Ayrılıklara sessiz kalmamak hayatta

Seni seviyorum diyebilmek

Kor olmuş, ateş olmuş umrumda değil

Yeter ki derdimin dermanı sen ol

Yalnız kalmasın şu yoksul yüreğim

Yalnızken boğulup gider gibiyim

Beni yalnız bırakma', 'Saatlerce bakmak gözlerine  Anlatmak derdimi Suskunluğu yok etmek Kalbimin çarpışındaki dinamit sesleri ile Ölümlere dur demek  Ayrılıklara ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanlizliga-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Yaşları', 'goz-yaslari-osman-turkmen-uq1hv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzünler geceleri, 

Coşkular gündüzleri, 

Göz yaşları duyguları anlatır da, 

Sevgiyi anlatacak, 

hiçbir şey yoktur aslında! 

Şu sana yazdığım, 

soluk yüzlü, 

vuslat kokulu şiirler de olmasa! 

Yalnızlığı çoktur çaresizliğin, 

Sevmek tamamda, 

Ya ayrılık! 

Bir de, sensizliğin acısı insana koymasa! 

Göz yaşlarında gizlidir bir çok şey, 

Kimi zaman dışa vurur, 

Çoğu zaman içinde kalır her şey.

Yıkılıyorsa evler, deprem olmuş, 

Sallanıyorsa dünya, kıyamet kopmuş, 

ne fark eder.

Bir senin yokluğun, 

Bir de yokluğunda ağlamak, 

beni kahreder.

Sevgi; 

Hayatın paylaşılması en zor derdi.

Ya bırakılmak, 

Ya terk edilmek, 

Ötesi unutulmak, 

Say ki ölüm! 

İki damla göz yaşıdır gülüm.

İki damla!', 'Hüzünler geceleri,  Coşkular gündüzleri,  Göz yaşları duyguları anlatır da,  Sevgiyi anlatacak,  hiçbir şey yoktur aslında!  Şu sana yazdığı...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/goz-yaslari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Düşlem', 'son-duslem-cihan-turkmen-ll407', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzaklardan bir atmacanın çığlık sesi

Yırtarsa kulak zarlarını

Yıkarsa beyninde ki idam hükmünü

Ağlatırsa seni

Korkutursa hayat

İşte o an bir insan doğar

Adını bilmediğin 

Bir duygu

Bir hüzün kuşatır etrafını

Ve ateşler aşk silahını

Vurur, vurur seni kalbinden

Sen onu terk etmeden 

O seni terk eder

O anda yok olursun 

Kimsesiz kalıverirsin ortada

O buna inat çıkarır atar yüzüğü

İşte bu halkadır seni boğan', 'Uzaklardan bir atmacanın çığlık sesi Yırtarsa kulak zarlarını Yıkarsa beyninde ki idam hükmünü Ağlatırsa seni Korkutursa hayat İşte o an bir...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-duslem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey boş', 'hersey-bos-cihan-turkmen-tmgzt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzaktan bir kasırga gelir

Bulutlar parmağıyla sanki beni gösteriyor

İşte ONU, ONU savurun diyor.

Gülüyorum ama içimde bir sıkıntı var

Bugün de aynı dün gibi

Yine yalnızım.

Adımlar yalnızlıkların derinliğine atılıyor

Her adımda yol biraz daha uzuyor

Nereye gittiğim belirsiz, nereden geldiğim de

Ve umutsuzluklar peşimde

Görüyorum ama nedeyim

Bende elenmişim hayat kavgasından

Artık herşey boş, umudum, tesellim

Canım şişemde...', 'Uzaktan bir kasırga gelir Bulutlar parmağıyla sanki beni gösteriyor İşte ONU, ONU savurun diyor. Gülüyorum ama içimde bir sıkıntı var Bugün ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hersey-bos-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğulmak Üzereyim', 'bogulmak-uzereyim-cihan-turkmen-125gm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boğulmak üzereyim, bu zindanda

Boğulmak üzereyim, çığlıklar arasında

Seviyor muyum? Sevmiyor muyum? 

Boğulmak üzereyim, bu düşünceyle

Göz yaşlarım  suyu kurumuş bir ırmak gibi

Yanaklarımda  akmakta, istek dışı bir yolda

Ve deniz gibi sana kavuşmakta

Kalbimde ta kalbimde

Bilmiyorum bu hisler niye

Kaybolmuş çocuğun göz yaşlarında

                                boğulur gibiyim

Bilmiyorum bilemiyorum', 'Boğulmak üzereyim, bu zindanda Boğulmak üzereyim, çığlıklar arasında Seviyor muyum? Sevmiyor muyum?  Boğulmak üzereyim, bu düşünceyle Göz ya...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bogulmak-uzereyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmeyeceksin', 'bilmeyeceksin-cihan-turkmen-ryt53', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaz geliyor

Ben ıssız bir dağa gideceğim

Ve hep seni, güzel gözlerini düşüneceğim

Sen kim bilir nereye gideceksin 

İsmini duyduğumda “oda kimmiş” diyeceğim

Çünkü seni sevdiğimi bilmeyeceksin', 'Yaz geliyor Ben ıssız bir dağa gideceğim Ve hep seni, güzel gözlerini düşüneceğim Sen kim bilir nereye gideceksin  İsmini duyduğumda “oda ki...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bilmeyeceksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-cihan-turkmen-p7rps', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni

   Kumsallarda

         Islanan

               Kumlara yazmadım

Bir 

  Dalganın 

       Çalkantısıyla 

              Silinmeyesin diye

Ben

   Seni

       Sade

             Sensiz olduğumda özlemedim

Sen yanımdayken 

        Bile 

            Benim özlemimdin', 'Seni    Kumsallarda          Islanan                Kumlara yazmadım Bir    Dalganın         Çalkantısıyla                Silinmeyesin diye ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körebe', 'korebe-cihan-turkmen-6f94p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir karanlık çöker günün ortasında

Güneş tutulur.

Ay ve yıldızlar saklambaç oynar

Benden saklanırlar

Sensizliğimde', 'Bir karanlık çöker günün ortasında Güneş tutulur. Ay ve yıldızlar saklambaç oynar Benden saklanırlar Sensizliğimde...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/korebe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-cihan-turkmen-1cja9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerin bir güneş gibi aydınlatıyor dünyayı

Ve sesin

Bir nefes gibi, 

Ürperiyorum

Bu duygular nedir diye? 

Ama sen 

Bütün masumiyetiyle

           	İÇİMDESİN!', 'Gözlerin bir güneş gibi aydınlatıyor dünyayı Ve sesin Bir nefes gibi,  Ürperiyorum Bu duygular nedir diye?  Ama sen  Bütün masumiyetiyle    ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gozlerin-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Bu Zindan', 'nedir-bu-zindan-cihan-turkmen-5lefz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Burda hasretler büyük

Burda ölümler sessiz

Birde ben varım kaç zaman sensiz.

Konuşmuyor insanlar fısıldıyor

Korkularını kalplerine sindiriyor.

Hepsi birbirinden korkak

Hepsi birbirinden üstün

Bu mahpushanede ölüm bile  tutsak

Beni sorma, sorarsan ki

Ben ölüme tutsak

Ölüm herkesten korkak

Devriye geziyor sessiz adımlarla

Gece yarıları boş koridorlarda

Kim varsa uyumamış geceye inat

Bir tek onlar korkuyor ölümden

Ölümün nefesi yaklaşıyor gece düşünde

İdam sehpası yüksek ayakların değmiyor yere

Korkuyorsun şafakta asılanların çırpıntısında                  Kiminin son istediği bir tane gül

Kiminin bir tek cigara

İşte biri daha gidiyor

Hayatın ilkbaharında

Cellat anlamsız bakıyor

Gökteki bulutlar, 

Gökyüzü ağlıyor

Devrilen sandalyenin kesilmez tangırtısında', 'Burda hasretler büyük Burda ölümler sessiz Birde ben varım kaç zaman sensiz. Konuşmuyor insanlar fısıldıyor Korkularını kalplerine sindiriyo...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nedir-bu-zindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sema-i Mevlâna', 'sema-i-mevl-na-asaf-halet-celebi-36q8q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tennûre giymiş ağaçlar

aşk niyâz eder

mevlâna

içimdeki nigâr

başka bir nigârdır

içimdeki semâ''a

nice yıldızlar akar

ben dönerim

gökler döner

benzimde güller açar

güneşli bağçelerde ağaçlar

''halaka''s-semâvâti-ve''lard''h'' 

yılanlar ney havalarını dinler

tennûre giymiş ağaçlarda

çemen çocukları mahmûr

câaan

seni çağırıyorlar

yolunu kaybeden güneşlere

bakıp gülümserim

ben uçarım

gökler uçar', 'tennûre giymiş ağaçlar aşk niyâz eder mevlâna içimdeki nigâr başka bir nigârdır içimdeki semâ''a nice yıldızlar akar ben dönerim gökler döner...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sema-i-mevlana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seksi Dostum', 'seksi-dostum-sair-cicero-dmm00', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gündüze inat geceye direncimin, geceye inat gündüz yaşantımın tek şahidi, 

Gecemin kör karanlığında çayımla beni yanlız bırakmayan ve yüreği iyi demlenmiş bir çay kadar demli, bir o kadar zelal dostum.

Bizimde yollarımız böyle ayrılacak mıydı.

Benide alacak mıydı bu sistem çarkına.

Farklı ülkelerde içilen çayların buğusundamı arayacaktım seni.

Ayrılırken senden yüzümün halini birdaha görürmüyüm sanki, elinden tek olan oyuncağı alınmış bir çocuktum sanki.', 'Gündüze inat geceye direncimin, geceye inat gündüz yaşantımın tek şahidi,  Gecemin kör karanlığında çayımla beni yanlız bırakmayan ve yüreği...', ARRAY['Türk Edebiyatı','Şiir','Şair Çiçero']::text[], 8.5, '{"poet":"Şair Çiçero","poet_slug":"sair-cicero","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seksi-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıkamışta', 'sarikamista-mustafa-ozke-34rg3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sarıkamıştaydık

önder ben ve sani

ortada ne kamış vardı

ne de kamışın sarısı yani

her yer bembeyazdı

kardı ayazdı üşüyorduk

önder kara hasretini yazdı

bir çekirge sıçradı önümüzden

önder fırladı yerinden

yakaladı hayvanı kanadından

tuttum önderin kolunu

''bırak gitsin'' dedim

geri kalmasın sanatından

önder bir çekirgeye baktı

bir bana bir saniye

kızar gibi oldu

başını öne eğip

düşündü bir saniye

ardından bıraktı kanatlarını

çekirge uçup gitti faniye

öyle bir sıçradı ki

tel örgülerin arasından

hem özgürlüğe doğru

hem bir kere değil

iki kere değil üç kere

bizim ömrümüz geçti

o bir an bile dayanamadı

gün saydığımız yere

çekirge zıplayarak gitti yuvasına

ondan alacağımızı aldık

kapıldık hevesine

ayaz tuttu kar yağmaya vardı

bizi yine yanlızlığımız sardı

önder ben ve sani

uyumadan rüyaya daldık

esnedik, nefes aldık

çekirge biz oldu

biz bir çekirge kadar olamadık', 'sarıkamıştaydık önder ben ve sani ortada ne kamış vardı ne de kamışın sarısı yani her yer bembeyazdı kardı ayazdı üşüyorduk önder kara hasre...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sarikamista-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'korku', 'korku-yasar-kurt-w7uop', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Korkuyorum anne, al beni içine

Alışamadım anne, al beni yine

Büyüdüm anne, evler büyüdü

Büyüdü pabuçlar, yollar büyüdü

Orduya istiyorlar, 

Savaş çıkar diyorlar

Silah veriyorlar anne

Bana öldür diyorlar.

Yat diyorlar anne

Kalk diyorlar.

Beynimi yiyorlar anne, 

Beynimi yiyorlar

Kapat televizyonu anne

Seni de kandırıyorlar.

Oyunu verme anne, 

Oyuna gelme anne.', 'Korkuyorum anne, al beni içine Alışamadım anne, al beni yine Büyüdüm anne, evler büyüdü Büyüdü pabuçlar, yollar büyüdü Orduya istiyorlar,  S...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kurt']::text[], 8.5, '{"poet":"Yaşar Kurt","poet_slug":"yasar-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/korku-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerim', 'siirlerim-arife-atar-kml9c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim şiirlerim hep kısa olur

Başlığı büyük harf

Ortada virgül

Eğer son noktayı 

Koymak istersem

İşte o şiirimin

Eceli olur.........

9..5..1957', 'Benim şiirlerim hep kısa olur Başlığı büyük harf Ortada virgül Eğer son noktayı  Koymak istersem İşte o şiirimin Eceli olur......... 9..5..1...', ARRAY['Türk Edebiyatı','Şiir','Arife Atar']::text[], 8.5, '{"poet":"Arife Atar","poet_slug":"arife-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siirlerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dönemin Şiirleri-1', 'bir-donemin-siirleri-1-ali-rodi-ozkan-imr1g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yitirecek bir ülkem olmadı hiç

Sığınacak bir ülkemde

Bir raslantı değil 

Sana aşinalığım

Sende sahiplendim kendimi

Sende buldum yitik özlemleri

Benim için 

Yalnız öznesi değildin yaşamın 

Deniziydin kıyılarımın

Düşlerimde kayıp giden

Uzaklaştıkça

Herşey sana daha yakın

Bir soluk ötede

Bazen kaçtım

Farklı iklimlere

Güneşin farklı doğduğu günlerin gecesine

Başka ülkeler aradım 

Zifiri karanlıktı her yan

Her yön çıkmaz sokaktı

Bir ürpertiyle geri döndüm

özlemlerim hep diken tarlasında

Kanat çırptı yüreğim

Ama fazla sürmedi

yine senden uzaktım..', 'Yitirecek bir ülkem olmadı hiç Sığınacak bir ülkemde Bir raslantı değil  Sana aşinalığım Sende sahiplendim kendimi Sende buldum yitik özleml...', ARRAY['Türk Edebiyatı','Şiir','Ali Rodi Özkan']::text[], 8.5, '{"poet":"Ali Rodi Özkan","poet_slug":"ali-rodi-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-donemin-siirleri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dönemin Şiirleri-2', 'bir-donemin-siirleri-2-ali-rodi-ozkan-micug', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve gece...

Beynimi sınırlarında zorlayan

Sadece bir sesin bağışlanmasını 

İsteyecek kadar

Yalnız isteklerle dolu sömürü 

                       bir gece.

Ay ışığının düşsel umutları andıran

Parıltıları ile süslenmiş

Kendi yaşamımın aynası gibi

upuzun bir ırmakta 

sürüklenen yorgun bedenimi

kimi zaman

aşinası olduğum 

sıkıştırılmış umutlar coğrafyası(siverek...

kimi zaman 

gençliğimi, kaybettiğim umutları

bulmak sevdası ile

sevdamı kaybettiğim (mersin...

kimi zamanlardaysa

rotasını kaybetmiş bir kaptanın 

şaşkınlığı ile ugradığı

kayıp limanlar 

kısacası

bir insan kendi beynini yerken

yani; 

çürümüşlüğünün nedeni 

kendi kemirgenliği iken

ugrayabileceği, birşeyleri eksiltebileceği

sınırlı zamanlar atlasında bir gecede

sadece

zamana benzeyen akıntıda 

bilinçsizce çekilen küreklerle

ugrayabileceği 

hayatın limanları gibi geliyor

ve bir an bile 

akıntıya karşı 

bedenim bırakmıyorsa kürekleri

bu, ölümü en çok kendi bedenime 

yakıştıramamamdan olsa gerek

ve bir an düşündümde 

sürüklendiğim ırmak 

ya denize ulaşmıyorsa...', 'Ve gece... Beynimi sınırlarında zorlayan Sadece bir sesin bağışlanmasını  İsteyecek kadar Yalnız isteklerle dolu sömürü                     ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rodi Özkan']::text[], 8.5, '{"poet":"Ali Rodi Özkan","poet_slug":"ali-rodi-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bir-donemin-siirleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-ceyhun-yilmaz-4uysr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kaç sabahtır geceye uyanıorum

noldu güneşe aynalarda yokum

dumanı tüten çay bardaklarına dokunuorum

elimi ısıtmıyor

ağlayınca farkettim

gözyaşlarım yanaklarımı ıslatmıyor

yüreğimde bir ağrı

bir tek onu hissediorum

hissedince anlıorum

keşke feda edebilseydim sana

sımsıkı sarılıp güzel saçlarını koklayıp gitseydim 

ölmüşüm ben bebeğim ölmüş 

herkesin korktuğu gün bana bugünmüş.', 'kaç sabahtır geceye uyanıorum noldu güneşe aynalarda yokum dumanı tüten çay bardaklarına dokunuorum elimi ısıtmıyor ağlayınca farkettim gözy...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Adım', 'benim-adim-ceyhun-yilmaz-qr78z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazdığım kadarını da

yazamadım aslında

Seni göremediğim

kadarını sevdim

Işığından aydınlık karanlığım

Sen değil ben sevdalıyım

Merhaba Canım

Hüzün benim Adım', 'Yazdığım kadarını da yazamadım aslında Seni göremediğim kadarını sevdim Işığından aydınlık karanlığım Sen değil ben sevdalıyım Merhaba Canım...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benim-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takvim yapraklarını yırttığım günleri say', 'takvim-yapraklarini-yirttigim-gunleri-say-i-lhan-yuksel-ggl7d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Takvim yapraklarını yırttığım günleri say 

Say sen gideli saat saat gün gün ay ay 

Say ki ne beklemişim yollarını seneler 

Ne gün doğdu bahtıma ne gül açtı bahçeler 

Dibi görülmez sonsuz bir boşluğa bıraktın 

Hayatın baharında neydi bir bakış baktın 

Geceler günler dakikalar saat''ler karıştı 

Tükenmeyen ızdıraplar ard arda yarıştı 

Tükettim be vefasız yoluna ne takvimler 

Güz ayında yaprağın döküldüğü ekimler 

Ne saat''ler ne günler ne aylar tükettim 

Kışlar şakağa kar eken sayılar tükettim 

Her bahar gülden önce açardın yaylalarda 

Kış olur dökülmezdi gülün beyazdın karda 

Güller solarken senin hep güllerin olurdu 

Gülücük saçar kanarya dillerin olurdu 

Işık verir gözlerin bakışlar çevrilirdi 

Zülfüne doladığın yiğitler devrilirdi 

Simsiyah kirpikler''in ok olur kaşların yay 

Güneş gibi doğardın söner görülmezdi ay 

Güller açtın bahar mı? hep sizin yaylalarda 

Ak düşürdüğün şimdi saçlarım beyazlarda 

Su vermiyor çeşmeler su vermiyor kurudu 

Gül açtığında Nar, a yaktığın hayat durdu 

Gülşen''im soldu döktü baharında yaprağım 

Sazlık idi çöl oldu kurudu şu toprağım 

Sorma halimi giydim sen gideli karalar 

Issız kuş uçmaz kervan geçmez oldu buralar 

Bahtıma bir değişmez tuttun kitabe yazdın 

Kara yazdın kalemin beyazdı sen beyazdın 

O gün bu gündür önümü göremez oldum 

Şu yalan hayatın zevkine eremez oldum 

O gidişle dönmedin geri gittin unuttun 

Çölde gölge gibiydin göklerde bir buluttun 

Ayında yol alırdım ışıktı geceleri 

Kışları kılardın bir bahar vardığın yeri 

Gün ettim sen gideli hep günümü gün ettim 

Yollarına durdum kırk sene ömür tükettim 

Taş kesildi yüreğin bağladın zülfüne

Taş insafa gelirken yine duymadın yine 

Seneler geçti ışık vermedi pencereler 

Her gün daha simsiyah kesildi şu geceler 

Ne perdeler açıldı ara verdi geceye 

Yokluğunda ne kapım açıldı kimseye 

Şiirler yazdım sana acı dolu gam yüklü 

Ne acılar çektim daha küçüklü büyüklü 

Ufukları süzdüm sonra hep yollara baktım 

Kendimi şu dönülmez boşluğa bıraktım,', 'Takvim yapraklarını yırttığım günleri say  Say sen gideli saat saat gün gün ay ay  Say ki ne beklemişim yollarını seneler  Ne gün doğdu baht...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/takvim-yapraklarini-yirttigim-gunleri-say-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler Taslak', 'geceler-taslak-yuksel-aykut-mrky3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen dostum olur geceler

Bazende bir kabus gibi çöker üstüme

Gecenin sessizliğinde

Seni düşünürüm

Bir kedi mırıltısı

Yırtar gecenin zifiri karanlığını

Karanlığın içinden süzülüp gelmeni 

Hep hayal ederim

Biliyorum hiç bir zaman gelmeyeceksin

Geceler gibi sende zalimsin sevgilim...

1994

Suruç', 'Bazen dostum olur geceler Bazende bir kabus gibi çöker üstüme Gecenin sessizliğinde Seni düşünürüm Bir kedi mırıltısı Yırtar gecenin zifiri ...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Aykut']::text[], 8.5, '{"poet":"Yüksel Aykut","poet_slug":"yuksel-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geceler-taslak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlacımı Özün Say', 'i-lacimi-ozun-say-nurullah-genc-597zs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir akşam sensizliğim eriyip aktı bende

gözlerinin cemresi karanfildir bedende

kirpiklerin kuşattı bütün mevsimlerimi

şimdi varsın; sızın var duranda, yürüyende

kollarım gül kokulu bir baharı sarıyor

acılar ki, önümde diz çöküp yalvarıyor

ayrılık yapayalnız bir ülkedir evrende

hüzün, terk edilmişlik duygusuyla çaresiz

şimdi varsın; hayatım sende, ölümüm sende

şimdi varsın; sokaklar daha bir sıcak bana

nereye git gidersen; orası ocak bana

bazen bir papatyanın beyaz yapraklarından

bazen bir dolunayın çehresinden bak bana

şimdi varsın; ruhumu okşuyor soframda su

ardımda ne yalnızlık, ne de ölüm korkusu

hayatın hiç sönmeyen kandilini yak bana

o eski fırtınalar şimdi sabâ rüzgarı

hüzün benden habersiz, kuşkular ırak bana

ey benim aynalarda gülümseyen çokluğum

nar tadında umutlar taşıyan çocukluğum

gözlerinin ışığı yayıldı mahzenime

ey benim can sarayım, ey benim eşsiz kuğum

asil tebessümünü düşürdün izlerime

müpteladır gemiler benim denizlerime

gülümsedin; kalmadı kederim, burukluğum

çehresinde hâtıran büyüyor bebeklerin

gizemine âşina varlığım ve yokluğum

lügatini yeniden yazıyorum sevdanın

binlerce çiçek açtı kollarımda yorgunluk

gündönümü ruhuma ayarlandı yeniden

bir çerağdır, yanıyor gittiğin her bahçede

şimdi parmaklarının ucundadır baharım

kutlu bir ülke verdin hayatıma özünden

denizlerde sen varsın; ırmaklarda ben varım

yaprak yine hüzünle düştü ayaklarıma

ağaçlardan boşandı hayatımın acısı

anlamadım: Bu gökler benim göklerim değil

bilemedim: Bu toprak canımda akkor gibi

tutuştum hiç kimsenin yanmadığı yerde ben

meğer ömür vermişim bu belalı derde ben

sen geldin; avuçlarım suyla doldu ansızın

sen geldin; evrenimi kuşattı sevda sızın

ders almayı bilmedim yüreğimden; yorgunum

ne sana, ne kendime, ben dünyaya kırgınım

dikenler saplanmıştı çocukluk günlerime

gençliğim bir ejderha pençelerine mahkum

kırk yaşımda, bin yılın ıstırabıyla yandım

uyudum, o bembeyaz ellerinde uyandım

sen geldin; birbirinden ayrıldı renk ve acı

sen geldin; yine vurdu yüzüme aşk utancı

lâyıktır, her lokmayı yedirseler zehirden

lâyıktır, karlı dağlar çökse başıma birden

akıl, sanki içimde bana düşman bir gemi

kahrın karanlığına gömdü şehlâ gölgemi

göremedim; gönlümden ufkuma sızdı keder

en muamma çöllerde ararken yitiğimi

geldin; altın harflerle yazıldı günün adı

geldin; ruhuma meftûn âvâreler ağladı

ders almayı bilmedim hayattan; bir gün ölüm

öğretir o tekrarı olmayan dersi bana

nasıl da uçtu ömrüm renklerin boşluğuna

dal kırıldı; kökleri çürüdü servilerin

duyamadım gövdenin o esrarlı sesini

karayel bir yanımdan esip durdu öteye

sen geldin; yağmur yağdı içime; bahar geldi

sen geldin; yıllar yılı beklediğim yâr geldi

şimdi varsın, yıldızlar bana bakar derinden

bozkırlarda, çöllerde çiçeklenir ellerin

şimdi varsın, gecenin kan akar gözlerinden

ışıldayan çehresi karardı güzellerin

öteyi görmeyenler bilemez, kimle geldin

sen benim kendi ruhum, kendi özümle geldin

şimdi varsın, varımı varlığında sakladın

dayanılmaz yüreğin esrarlı bir bahçedir

şimdi varsın, içimde ebedi konakladın

zariftir bakışların, bal renklidir, incedir

sensizlik geçmişini anıyor; şimdi varsın

burçlarımda lâmbalar yanıyor; şimdi varsın', 'bir akşam sensizliğim eriyip aktı bende gözlerinin cemresi karanfildir bedende kirpiklerin kuşattı bütün mevsimlerimi şimdi varsın; sızın va...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/ilacimi-ozun-say-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Kalan Bu Şehri Yakmayı Çok İstedim', 'sensiz-kalan-bu-sehri-yakmayi-cok-i-stedim-goksel-yasar-saracoglu-d6d3y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sensiz kalan bu şehri yakmayı çok istedim

mavi bir aleve dönüştürdüm kalbimi bir anda

tutuşturmak istedim beni böyle umarsız

bırakıp gittiğin bu zalim şehri

yakamadım gözlerin dikildi karşıma bir caddenin tam ortasında

inanılmaz güzel bakıyordu gözlerime hafif ıslak

en özel en bilinmeyen türleri açmıştı papatyaların

hatıralarınla titriyordu içim kuşlar kanatıyordu gönlümü

gri bulutlar geçiyordu göğümden 

anlamak üzreydim neron’un roma’yı neden yaktığını

karanlık bir koridor açıldı önümde anlayamadım

yenik düşmüş bir napolyon kadar mutsuzdum aslında

intihara kalkışan hitler kadar çaresiz

yakmak üzreydim ki bu şehri hatıraların

içli bir yağmur gibi boşandı üzerime

kediler geçti birden kavşaklarından şehrin

acı acı miyavladılar gözlerime baktılar kızgındılar kırgındılar

onlar da tutulmuşlar anladım sana bendeki kadar

onlar da terk ettiğin bu şehri çaresiz

yakmak istiyorlar yakamıyorlar

saçların dikildi karşıma bir sokak köşesinde

her telinde parmaklarımın izleri parlıyordu

benzersiz kokunu alıyordu kıvrımlarından rüzgar

gözleri doluyordu saçlarına bakan kedilerin

her biri bir kenarda darmadağın 

çömelip kalıyordu yutkunuyordu

rengi kaçıyordu pencerelerde perdelerin

nereye yürüdüysem bakışın, duruşun, sesin

anladım söndürmeliyim tutuşan yüreğimi

kendimi yakmış olurum yakarsam bu şehri

çünkü sen her şeyinle bendesin', 'sensiz kalan bu şehri yakmayı çok istedim mavi bir aleve dönüştürdüm kalbimi bir anda tutuşturmak istedim beni böyle umarsız bırakıp gittiği...', ARRAY['Türk Edebiyatı','Şiir','Göksel Yaşar SARAÇOĞLU']::text[], 8.5, '{"poet":"Göksel Yaşar SARAÇOĞLU","poet_slug":"goksel-yasar-saracoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sensiz-kalan-bu-sehri-yakmayi-cok-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam Benim', 'anam-benim-suleyman-apaydin-8yb76', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anam benim anam benim

Hasretinden yanan benim

Senden uzak diyarlarda

Gözleri yaş dolan benim

Anam benim anam benim

Sende can bulan bedenim

Varlığında hayat bulup

Yokluğunda solan benim

Bu gün yoksun sen yanımda

Bir sancı var sol yanımda

Lokman hekim etmez fayda

Anam benim anam benim

Sensiz onmaz yaram benim

Gülümserdi hep gözlerin

Şefkat doluydu sözlerin

Acı çektin kan tükürdün

Asılmadı güler yüzün

Anam benim anam benim

Hasretinden yanan benim', 'Anam benim anam benim Hasretinden yanan benim Senden uzak diyarlarda Gözleri yaş dolan benim Anam benim anam benim Sende can bulan bedenim V...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anam-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havva gelin', 'havva-gelin-suleyman-apaydin-8zcvc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Havva gelin ben hiç seni

Unutmadım unutamam

İki kişiye yanarım 

Biri sensin bir de anam

Ömür boyu gün görmeyen

Doya doya gülemeyen

Derdini içine gömen

Biri sensin bir de anam

Acı çektin kan tükürdün

Kimselere diyemedin

Onurundan hiç bir ödün

Göçüp gittin de vermedin

Dert çekip te ağlamayan

Kimselere duyurmayan

Sevgisi hiç azalmayan

Biri sensin bir de anam

Çok şükür ki anam sağdır

Geçmişinde kaldı kahır

Bir sen varsın kahrettiğim

Gün görmeden göçüp gittin

Havva gelin ben hiç seni

Unutmadım unutamam

İki kişi biliyorum

Gönül tahtımda oturan

Biri sensin bir de anam', 'Havva gelin ben hiç seni Unutmadım unutamam İki kişiye yanarım  Biri sensin bir de anam Ömür boyu gün görmeyen Doya doya gülemeyen Derdini i...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/havva-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay', 'ay-olgun-ergun-84uuq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yoksun ya sen 

neyakomozlar geldi bu gece oynaşmaya

nede yüzü gülüyordu ayın

denizde bir garip sanki

memur edasında

bu gün git yarın gel der gibi

yarın mı

bilsemki yarın evet yarın geleceksin 

bütün yarınları beklerdim  senin için

ama gelmedin.

bir dize  dolanmış dilime

bilmiyorum kimin 

belki benim sana yazıp hiç veremedigim bir kaç dize

ben

hani her saba rüzgarında

yüzünde hissettiğin

her yağmur damlasında 

omuzuna düşen

hani yıldızlarla ismini yazan gök yüzüne

hani sadece ve sadece

 kalbini sunabilen sana 

işte o ben

güle yazdım ismini

ve senin  köşküne bıraktım sessizce

sahibi olduğun gönül köşküme

belki gelirsin diye...', 'yoksun ya sen  neyakomozlar geldi bu gece oynaşmaya nede yüzü gülüyordu ayın denizde bir garip sanki memur edasında bu gün git yarın gel der...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ergün']::text[], 8.5, '{"poet":"Olgun Ergün","poet_slug":"olgun-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ay-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-emre-ozoran-iwy7v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki istedin

Ama

Aramadın.

Artık boşver

Bittiğini biliyorduk!', 'Belki istedin Ama Aramadın. Artık boşver Bittiğini biliyorduk!...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/belki-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay', 'ay-emre-ozoran-i57an', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Işığın altındayım, 

Ay ışığının.

Bir köpek havlıyor: 

''Ay ne güzel! ''

Yıldızlar boyuyor ırmağı

Ve ağaçların arasından davullar duyuluyor.

Başka bir köpek havlıyor: 

''Ay çok güzel! ''

Ruhum akıyor taşların arasından, 

Yeniden seviyorum.', 'Işığın altındayım,  Ay ışığının. Bir köpek havlıyor:  ''Ay ne güzel! '' Yıldızlar boyuyor ırmağı Ve ağaçların arasından davullar duyuluyor. Ba...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ay-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarımım', 'yarimim-ugur-seker-vkcgt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zor oldu senden ayrılmak.

Hani beni, otobüs terminalinde

Yapayalnız bırakıp gitmiştinya, 

Gökkubbe başıma yıkıldı sanmıştım.

Dizlerimin bağı çözüldü sanki, 

Biran yıkıldığımı hissettim olduğum yere.

Ardından öylece bakakaldım.

Sanki giderken canımıda götürmüştün, 

Damarlarımdaki kan donmuştu sanki.

Bedenim biranda soğudu, 

Kalbim atmıyor gibiydi.

Gözlerim boş boş bakıyor, 

Beynim karıncalanıyordu.

Birtanem....

Nasılda ''gitme'' der gibi bakmıştın bana.

İşte o an, 

Yüreğinin kanadığını hissettim, yüreğimde.

Beni ne kadar çok sevdiğini, 

Birkez daha gördüm gözlerinde.

Biran herşeyden vazgeçip, 

Senin yanında kalmak istedim.

İnan herşeye razıydım, 

Dönüp bana, gitme deseydin.

Yarımım, canım

Şimdi beraber geçirdiğimiz, 

O güzel günlerin anılarıyla yaşıyorum.

Bazan yaptığımız çılgınlıkları hatırlayıp, 

Gülümsüyor, 

Bazanda o güzel gözlerinin derinliklerinde

Kaybolup gidiyorum.

Çoğu zaman fotoğraflarını alıp karşıma, 

Seninle konuşuyorum sensiz.

Ve kahroluyorum.

Şarhoş olmak, ağlamak istiyorum.

İçmek geliyor içimden, 

Sızana kadar.

Kdınım...

Daha ne kadar dayanabilirim bu acıya, 

Daha ne kadar katlanabilirim sensizliğe, 

Bilemiyorum.

Artık bitsin bu ayrılık, 

Bitsin bu işkence

Ya bana gel de, 

Yada sen çıkıp gel ansızın.

Yarımın yarım kalmasın, kadınım.

26.04.2002

(Gün Batımı)', 'Ne zor oldu senden ayrılmak. Hani beni, otobüs terminalinde Yapayalnız bırakıp gitmiştinya,  Gökkubbe başıma yıkıldı sanmıştım. Dizlerimin b...', ARRAY['Türk Edebiyatı','Şiir','Uğur Şeker']::text[], 8.5, '{"poet":"Uğur Şeker","poet_slug":"ugur-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/yarimim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlerimizi Takdim Ederim', 'evlerimizi-takdim-ederim-bedri-rahmi-eyuboglu-8l1n0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu karşıdaki delikli kutuya ev derler

İnsanoğulları burada yer burada içer

Ve daha tuhaf tuhaf işler görürler

Bunların çoğu ayıp şeylerdir söylenmez

Evlerimizin üstü kapalıdır

Ve bütün şairler gökyüzüne pencereden bakarlar

Halbuki kuş yuvalarının üstü açıktır

Ve kuşlar şiir yazmazlar', 'Şu karşıdaki delikli kutuya ev derler İnsanoğulları burada yer burada içer Ve daha tuhaf tuhaf işler görürler Bunların çoğu ayıp şeylerdir s...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/evlerimizi-takdim-ederim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca', 'karinca-bedri-rahmi-eyuboglu-0ceri', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ulan karınca

46''ncı kata nasıl çıktın

merdivenle mi

asansöre mi bindin? 

ulan insan 

kendini beğenmiş şaşkın

demek senin yaptığını

yapabildiğime şaştın

bahse girer misin her işte

karıncadan üstün olduğuna? 

insan oğlu güldü

sonra 46''ncı katın

pencerelerinden birini açtılar

ikisi birden atladılar

insancık torba kağıdı gibi

patlayıverdi kaldırımda kan revan

karıncaya gelince acelesi yoktu

o daha 42''nci katın önündeydi.', 'ulan karınca 46''ncı kata nasıl çıktın merdivenle mi asansöre mi bindin?  ulan insan  kendini beğenmiş şaşkın demek senin yaptığını yapabildi...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karinca-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelere Sığınmak Kolaydır', 'gecelere-siginmak-kolaydir-mavi-yunus-1lv8m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecelere sığınmak kolaydır

Zor olan günü yaşamak

	Sevda düştüğünde yüreğine...

Gel gör gecelerde zora girer

Sıkışır gönlünde sevgiler.

Zamana sığınmak kolaydır

Zor olan yılları yaşamak

	Sevda düştüğünde yüreğine...

Gel gör zaman uçar gider

Sıkışır gönlünde sevgiler.

Kolaydır aşkı yaşamak

Zor olan sevgiyi yaşatmak

	Sevda düştüğünde yüreğine...

Gel gör aşktır eser geçer

Sıkışır gönlünde sevgiler.

		1 MAYIS 2002

		İlk Saatler......', 'Gecelere sığınmak kolaydır Zor olan günü yaşamak 	Sevda düştüğünde yüreğine... Gel gör gecelerde zora girer Sıkışır gönlünde sevgiler. Zaman...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gecelere-siginmak-kolaydir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevda Türküsüdür', 'bir-sevda-turkusudur-mavi-yunus-plhyj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sevda türküsüdür

Beynimde çalan

Yüreğimde fırtınalar koparan

Bir sevda çiçeğidir

Burnumda tüten

Yüreğimde açıp solan

Bir sevda masalıdır

Her yerde anlatılan

Yüreğimde yazılan

BİR SEVDADIR 

ANLATILMASI EN ZOR OLAN

			1 MAYIS 2002

			İlk Saatler........', 'Bir sevda türküsüdür Beynimde çalan Yüreğimde fırtınalar koparan Bir sevda çiçeğidir Burnumda tüten Yüreğimde açıp solan Bir sevda masalıdır...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-sevda-turkusudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım..', 'askim-mavi-yunus-r4xjw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara bulutlarla kaplı göklerdir

			AŞKIM..

Zirvesini göremediğim dağlardır

			AŞKIM..

Uçsuz bucaksız çöllerdir

			AŞKIM..

Ufukta çizgisiz denizlerdir

			AŞKIM..

İçi paramparça kalbimdir

			AŞKIM..

		2.MAYIS.2002

                        GÜNBATIMI', 'Kara bulutlarla kaplı göklerdir 			AŞKIM.. Zirvesini göremediğim dağlardır 			AŞKIM.. Uçsuz bucaksız çöllerdir 			AŞKIM.. Ufukta çizgisiz de...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Doldun', 'gozlerime-doldun-mavi-yunus-i3v51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerime doldun gizlice

Yüreğime dokundun usulca

Sevincim oldun neşenle

Mutluluksun yumuşacık yüreğinle

Hayatıma girdin hızlıca

Amacım oldun nedense

Sevincim oldun neşenle

Mutluluksun yumuşacık yüreğinle

			6 MAYIS 2002

			İlk Saatler.....', 'Gözlerime doldun gizlice Yüreğime dokundun usulca Sevincim oldun neşenle Mutluluksun yumuşacık yüreğinle Hayatıma girdin hızlıca Amacım oldu...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerime-doldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerim', 'askerim-mavi-yunus-ob3n5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tüfek omuzda yürür

Hazırolda bekler askerim

Bekçisidir ülkemin

Vatanı için ölür askerim

Gözleri uzaklara dalar

Sınırdadır askerim

Güvencesidir ülkemin

Vatanı için ölür askerim

Analar ağıtlar yakar

Yağız delikanlıdır askerim

Gururudur ülkemin

Vatanı için ölür askerim.

		Mavi Yunus		                       8 MAYIS.2002', 'Tüfek omuzda yürür Hazırolda bekler askerim Bekçisidir ülkemin Vatanı için ölür askerim Gözleri uzaklara dalar Sınırdadır askerim Güvencesid...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Martı', 'bir-marti-mavi-yunus-l2o1b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir martının kanadında uçsam göklere

Özlermisin beni 

Bir trenin katarında uzaklaşsam

Beklermisin gelişimi

Rüzgarda savrulup kaybolsam

Ararmısın beni

Dipsiz bir kuyuya düşsem

Çıkarırmısın beni

Ya, kalbimi uzatsam sana

Alıp severmisin.......

			07.MAYIS.2002

			Son dakika', 'Bir martının kanadında uçsam göklere Özlermisin beni  Bir trenin katarında uzaklaşsam Beklermisin gelişimi Rüzgarda savrulup kaybolsam Ararm...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-marti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlenirim', 'huzunlenirim-mavi-yunus-n549p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzünlenirim yıldızsız gecelerde

Ararım bir pırıltı göklerde

			      yüreğimde

Sorarım karanlığa nerelerde diye

Ses çıkmaz gelmezler

Kalbim çarpar o anda

Ben, ben değilimdir

Onlarsız nasıl yaşanır

Ararım, adı varmıdır

		        Yüreğimde

Yıldızdır derler

Oysa, 

Adı sevdadır 

                    Yüreğimde

			08.MAYIS.2002

			İlk Saatler', 'Hüzünlenirim yıldızsız gecelerde Ararım bir pırıltı göklerde 			      yüreğimde Sorarım karanlığa nerelerde diye Ses çıkmaz gelmezler Kalbim...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzunlenirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Yazdıklarımı Sarıya Boyuyorum.', 'butun-yazdiklarimi-sariya-boyuyorum-mine-ozdemirtas-er8vt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece; bütün yazdıklarımı sarıya boyuyorum.

Nerede bir uyuz kedi varsa, o benimdir.

Bütün kanadı kırık kuşlar balkonuma gelsin.

İçimdekileri ıslattım. Tepsiye koyuyorum.

Bu gece; söndürüp yıldızları yere indiriyorum.

Nerede bir topal eşşek varsa, o benimdir.

Bütün gözyaşlarınızı bana verin bu gece.

Yüreğimi havuz yaptım. Demlendiriyorum.

Bu gece; sapsarı yağmurları yağdıracağım.

Nerede bir umut fakiri varsa, o benimdir.

Bütün yaralı ceylanları koyun bahçeme.

Namluya barışı sürdüm. Avlanacağım.', 'Bu gece; bütün yazdıklarımı sarıya boyuyorum. Nerede bir uyuz kedi varsa, o benimdir. Bütün kanadı kırık kuşlar balkonuma gelsin. İçimdekile...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/butun-yazdiklarimi-sariya-boyuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemim Beni Korkutuyor.', 'kalemim-beni-korkutuyor-mine-ozdemirtas-f9pfu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalemim beni korkutuyor bu dağ başında.

Kömür karası mürekkebi var ya

Dal budak sarıyor içime. Gece ayazı gibi.

Parmaklarım acıyor, kurtulamıyorum.

Akrebin kıskacında dilime düşmeyenleri, 

Tutsam çıkaracağım.Gücüm yetmiyor.

O en bilindik kabustaki gibi, çırılçıplağım.

Kurumuş davul derisi kıvamında sessizliğim.

Dokunsam.... Yırtılacağım.

Oysa ki; çeliğe su veriyorum nicedir.

Çölleri suluyorum göklerimde. Ve açım.

Bıraksalar kabuğumu kıracağım

Kan ter içinde kovalıyorum ama; 

Kaçıyor tutamadıklarım.', 'Kalemim beni korkutuyor bu dağ başında. Kömür karası mürekkebi var ya Dal budak sarıyor içime. Gece ayazı gibi. Parmaklarım acıyor, kurtulam...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kalemim-beni-korkutuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durum Vahim!', 'durum-vahim-mine-ozdemirtas-ywcgm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durum vahim. Gölgeler uzadı farkındamısın? 

Kendi derdine düştün nicedir.

Gözyaşı kokuyor ıslak kaldırımlar.

Uyan. Uyan ki vakit gecedir.

Siyah bir şal gibi örtmüşler karanlığı

Işıyan her şeyin üstüne üstüne.

Kuşları, çiçekleri, aşkı yazdık nicedir.

Uyan. Uyan ki vakit gecedir.

Bol sıfırlı sefaleti seyreyle şimdi.

Seyreyle ki; atı alan ecdadını s..eviyor.

Ölüm emri tek hecedir.

Uyan. Uyan ki vakit gecedir.

Hileli tartıdan müebbet yiyeli adalet terazisi; 

Ne açlık ordusu kalmış, ne  de emeğin sesi.

Börtü böcek, baharı, kışı yazdın nicedir.

Uyan. Uyan ki vakit gecedir.', 'Durum vahim. Gölgeler uzadı farkındamısın?  Kendi derdine düştün nicedir. Gözyaşı kokuyor ıslak kaldırımlar. Uyan. Uyan ki vakit gecedir. Si...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/durum-vahim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Ya', 'gittin-ya-ugur-seker-3gf1k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biricik oğlumuz annem diye ağlıyor, 

Sesin kulağımda, yüreğimi dağlıyor, 

Gözyaşımız sel olmuş, coşmuş çağlıyor, 

O mutlu yuvamız virane oldu.

Topraklara gömüldü mutluluk güneşimiz, 

Hüsran oldu hazzımız, bütün neşemiz, 

Öksüz kaldık yavrum gitti annemiz, 

Sevgi dolu dünyamız virane oldu.

Ağla çocuğum hıçkırarak, doyasıya, 

Gelmeyecek birdaha dönmez dünyaya, 

Şimdi oldu artık bir tatlı ruya, 

Yıkıldı gönlümüz virane oldu.

Sen bizim annemiz, sevgilimizsin, 

Kalbimizde yaşıyorsun ölmeyeceksin, 

Gittin biliyoruz dönmeyeceksin, 

Mutlu günlerimiz virane oldu.

Şimdi suskunuz ikimiz birden, 

Senin için hiç birşey gelmez elimden, 

Mahrumuz artık kutsal sevginden, 

Sevgililerin deli divane oldu.

Ocak 1987

(Bu şiir, Ocak 1987 yılında eşini kaybeden ve bir çocuğuyla yalnız kalan çok sevgili dostuma itaf olunur)', 'Biricik oğlumuz annem diye ağlıyor,  Sesin kulağımda, yüreğimi dağlıyor,  Gözyaşımız sel olmuş, coşmuş çağlıyor,  O mutlu yuvamız virane old...', ARRAY['Türk Edebiyatı','Şiir','Uğur Şeker']::text[], 8.5, '{"poet":"Uğur Şeker","poet_slug":"ugur-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gittin-ya-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Yeniden Sevgilim', 'belki-yeniden-sevgilim-metin-usengec-tlo35', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki yeni sevgilerde

Belki yeni aşklarda

Belki yeni hislerde

Belki yeniden sevgilim

Belki yeni umutlarda

Belki yeni hayallerde

Belki yeni acılarda

Belki yeniden sevgilim

Belki başka yarınlarda

Belki başka dünyalarda

Belki çok çok uzaklarda

Yine aynı kalplerde sevgilim..

24-Nisan-2002  04:30

O Güzel Gözlerini Unutmak Yok Sana Söz..', 'Belki yeni sevgilerde Belki yeni aşklarda Belki yeni hislerde Belki yeniden sevgilim Belki yeni umutlarda Belki yeni hayallerde Belki yeni a...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/belki-yeniden-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbe', 'tovbe-ugur-seker-5de1o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidecek kimsem yok, geldim kapına, 

İşte yeniden sığındım sana, 

Merhamet et bu aciz kuluna, 

Ya Rabbim affet, bağışla beni.

Bir ara kaybettim doğru yolumu, 

Şaşırdım birden sağım, solumu, 

Açtım birdaha elim kolumu, 

Allah''ım affet, bağışla beni.

Kabul et duamı tövbem son olsun, 

Günahkar bendenim imanı bulsun, 

İlahi kudretin kalbime dolsun, 

Ya Rabbim affet, bağışla beni.

Sensin yaradan bütün herşeyi, 

Seninle bulur insan neşeyi, 

Yolundan sapanlar çeker çileyi, 

Allah''ım affet bağışla beni.

23.12.1988', 'Gidecek kimsem yok, geldim kapına,  İşte yeniden sığındım sana,  Merhamet et bu aciz kuluna,  Ya Rabbim affet, bağışla beni. Bir ara kaybett...', ARRAY['Türk Edebiyatı','Şiir','Uğur Şeker']::text[], 8.5, '{"poet":"Uğur Şeker","poet_slug":"ugur-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tovbe-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leonardo Da Vinci', 'leonardo-da-vinci-mahmut-talay-galwr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'önünde

oynaşıyor çocuklar

katedralin

son akşam yemeği

çekingen bakışlar altında

bir kadının

ateş çalacak tanrılardan

minicik elleriyle o çocuklar

aydınlığı taşıyacak

çehresine karanlık çağın', 'önünde oynaşıyor çocuklar katedralin son akşam yemeği çekingen bakışlar altında bir kadının ateş çalacak tanrılardan minicik elleriyle o çoc...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Talay']::text[], 8.5, '{"poet":"Mahmut Talay","poet_slug":"mahmut-talay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/leonardo-da-vinci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Yoruldum', 'artik-yoruldum-sadullah-bayar-ec62j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'acı günlerimdeki sevişmlerimin kızı

aşılmaz yllar artık yorsu beni

yordu beni sensizliğe inat yalancı gülüşlerim

asi gençliğimin asi delikanlısıym ben

yalnız sana tutsak, yalnız sana kul köle tabi

                                                                                                          seni yaşarkemal de okumak 

seni dostoyevski de bulmak

hep sana koşmak 

hep seni solumak nefesimle

ve hep seni düşünmek

uykusuz geçirdiğim saatlerin düşlerinde

gerçekten de YORDU BENİ.', 'acı günlerimdeki sevişmlerimin kızı aşılmaz yllar artık yorsu beni yordu beni sensizliğe inat yalancı gülüşlerim asi gençliğimin asi delikan...', ARRAY['Türk Edebiyatı','Şiir','Sadullah Bayar']::text[], 8.5, '{"poet":"Sadullah Bayar","poet_slug":"sadullah-bayar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/artik-yoruldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklın Bir Köşesindeki Kahvahanede', 'aklin-bir-kosesindeki-kahvahanede-i-smail-onat-6949p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', ': : : : : fısıltı: : : : : 

ve kavga, bilinmeyen mânevi hallerde...

         

yollar kavis kavis 

kaybolursa eğer kirpik uçlarında; 

kirpikler, 

gözyaşlarıyla savaşıyordur mutlaka... 

ya vakitsiz bir rüzgâr esmiştir

ya da beklentisiz bekleyişlerdir ağır ağır basan...

...hiç tarifsiz 

tariflerdir; 

takılırlar öylesine soru işaretlerinin kancalarına... 

...takılırlar

...kayıtsızca. 

          tarifsiz, 

              tasvirlerdir.

[sigara molası ve düşünce]

''boş akıntılardaki takıntılarındır onlar, 

 boşluğundaki  keyifsiz doluluğundur şair... 

 sabahları -yeni bir gün- dersin hep, 

 geceleri ‘o gün''ü de bitirirsin uyku vaktinde... 

 dünün bugünündür, 

 bugünün, değişmez yarının... 

...gün ola harman ola şair, gün ola harman ola! '' 

ayak tabanlarınız uyuşur gibidir, 

taban tabana zıt değilsinizdir oysa. 

zıtlık, 

aynılıktadır...

aynılık, 

dudaklarınızın ucunda...

[mola molası ve bir yudum dumansızlık]

...

''iki türlüdür ikilem; 

 arkandan bıçaklanırsın, 

 yüreğin yanar şair...

...yanar dirhem dirhem.

 lâkin onurlanırsın, eğer 

 bıçak göğsünü hedefleyip

 kalbini deşer geçerse...

                   e=mc², 

edebiyatın ne lüzumu var? ''

sözcük yağmurlarıdır  parıldayan 

gece karanlıklarında.

çizdikleri yol; bir nefeste bir hatıradır hep

albümler, düşünselliğin anahtarları

resimler, ''bir zamanlar''ın donuk sesleri... 

ne kahkahalar durmak ister, 

ne de diğer aceleci tavırlar. 

mumlar yavaş yavaş erir, 

ışık yavaş yavaş erir, 

gün yavaş yavaş, 

vücut yavaş, 

akıl yavaş, 

öbürleri, 

sen, 

ben... 

[epik dokumalar, son ara]', ': : : : : fısıltı: : : : :  ve kavga, bilinmeyen mânevi hallerde...           yollar kavis kavis  kaybolursa eğer kirpik uçlarında;  kirpikl...', ARRAY['Türk Edebiyatı','Şiir','İsmail Onat']::text[], 8.5, '{"poet":"İsmail Onat","poet_slug":"i-smail-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/aklin-bir-kosesindeki-kahvahanede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylenceler', 'soylenceler-i-smail-onat-owqbk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '‘sevgili’ numero 1 

dedi ki: 

ellerimi tut, 

tut öylece 

gözlerini 

yüreğime akıt. 

sıcakça, sımsıcak. 

[konuşayım dediydim bir kere ve ilk kere uzun uzun] 

         dedim ki: 

         ellerimde hep eller 

           gözlerim, 

           zaten erimiş yüreklerde. 

           ama, 

           birisi de sensen eğer 

           dostluklarin selamcısı 

           cesur 

           korkaklığında karanlıklar hükmeden... 

          ...tutarım ellerini senin de. 

‘sevgili’ numero 2 öğrendi bunu 

dedi ki: 

saçlarımı okşa 

üfür... 

yavaşça enseme enseme 

terim buz olmadıkça 

tenim seninle 

densizliğimde bunca zaman 

karanlık korkaklığımda hüküm yiyen. 

‘sevgili’ numero 3 heyecanlıydı, çok heyecanlı 

dedi ki: 

koş benimle rüzgâr yamaçlarda 

peşimi bırakma sakın 

ya da peşinde olduğumu 

farketmeden uzaklaşma 

ayağım 

yerde değil artık. 

bir başkası, bir öbür sevgili

dedi ki: 

özlediğim içimde 

sanki kendim o şehirde 

uç benimle gidelim 

ya dostlarım kalmamışsa 

beni yalnız bırakma 

şehrime küsmeyeyim. 

çingene ruhlu sevgili ve de numarasız

dedi ki: 

renkler cümbüş 

çingeneler dans ediyor 

beni bekle ben de dönerken 

gözlerin izlesin 

şarkıya katıl şakraklıkta 

sesin 

nağmeler getirsin. 

küskün sevgili numero bilmemkaç

dedi ki: 

yaram derin kan yok 

hayat bensiz ben hayatsız 

yaşam zevksiz onlar 

yaşamsız varoldukça 

kendi kendine karanlıkta 

ışık söndüren bir mumsuz gibi. 

                   ve ben kendi kendime

                     dedim ki: 

                 saygıdan sözcükler 

                 sevgiden destanlar... 

                dut yapraklarında tırtıllar 

                 artık kelebek olsalar 

                 uçsalar hafif hafif

                 rengârenk konsalar 

                 günışığı yakmasa 

                 mum hiç erimese 

                 eller tutuşmaktan 

                 terlemese 

                 taşısak birşeyleri 

                 birlikte biryerlere. 

                       o ütopya...

                                   erişilmez... 

                                           erişilse... 

[hepsi-ne- birden tek tek/ayrı ayrı, çok sesli -solo halinde-]

dedi ki: bekle(me) ! 

dedim ki: bekleme!', '‘sevgili’ numero 1  dedi ki:  ellerimi tut,  tut öylece  gözlerini  yüreğime akıt.  sıcakça, sımsıcak.  [konuşayım dediydim bir kere ve ilk ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Onat']::text[], 8.5, '{"poet":"İsmail Onat","poet_slug":"i-smail-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/soylenceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak', 'toprak-i-smail-onat-6c0l8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'toprak...

       çıplak ayağımı 

                üzerine bastığımda, 

                        çıplak bedenimi

                                gömesim geldiği...', 'toprak...        çıplak ayağımı                  üzerine bastığımda,                          çıplak bedenimi                               ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Onat']::text[], 8.5, '{"poet":"İsmail Onat","poet_slug":"i-smail-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/toprak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yolu', 'sevgi-yolu-erol-sen-dj3x0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yolların sonuna  ulaşmak

Bitmez tükenmez düşüncelerle

Yollar değil düşüncelerde ki

Yolların bağlandığı umut

Sevginin yollarında kaybolanlar

Bağlanmak için köprü ararken

Köprüler çıkmaza yapılmış

Sevgi köprüyle bağlanmıyor ki

Sevenin yolu sevgi yoluysa

Taş kalbin yolu arnavut kaldırımı

Amaçsız geçen hayatlarda

Yol bile yok sevgiye, aşka ve umuda...

10.05.2002', 'Yolların sonuna  ulaşmak Bitmez tükenmez düşüncelerle Yollar değil düşüncelerde ki Yolların bağlandığı umut Sevginin yollarında kaybolanlar ...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geldim', 'sana-geldim-mehmet-batihan-vphxp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapalı bir kutuydum, 

Açıldım sana geldim.

Hab-ı gaflet içreydim, 

Uyandım sana geldim.

Koptum can dostlarımdan, 

Dermankâr cananımdan, 

Ol ana ocağından, 

Ayrıldım sana geldim.

Kızıltepe’den Konya’ya, 

Açıldım ben deryaya, 

Çıktım sonra karaya, 

Durulup sana geldim.

Ey Mevlâna’m şâh-ı pîr, 

Bırakmadın bende kir, 

Kölelikten ettin mîr, 

Ram olup sana geldim.

Şaşkındır şimdi Mehmet, 

İlinden içti şerbet, 

Kopsa da şol kıyamet

Gamsızım sana geldim.', 'Kapalı bir kutuydum,  Açıldım sana geldim. Hab-ı gaflet içreydim,  Uyandım sana geldim. Koptum can dostlarımdan,  Dermankâr cananımdan,  Ol ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Batıhan']::text[], 8.5, '{"poet":"Mehmet Batıhan","poet_slug":"mehmet-batihan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-geldim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama Sebebi', 'yasama-sebebi-mehmet-batihan-3llsd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ansızın bir ağırlık çöker üstüme, 

Bir çığ gibi belimi büker, 

Sensiz olduğum zaman, 

Deniz gözlerine bakardım eskiden, 

Bazen sıcacık

Bazen kaplan gibi ürpertici

Ve hançerden daha keskin

Bazen de

Anlamsız gülüşüne bakardım

Ama bilmelisin ki, 

En mutlu yıllarım onlardı.

Yıllanmış bir şarapsın ki

Kalbime muhabbetle dolan, 

Şimdi senden bana 

Hayal meyal bir simadır kalan.

Sen gittin gideli

Gecelerim zindan oldu

Gel artık! 

Senden sonra sabah sefalarım da kalmadı, 

Busenle uyanmıyorum artık! 

Seyretmez oldum, 

Ne tepeden doğuşunu

Ne gurupta batışını

Güzelim güneşimin

Yatağım da dört duvar ki 

Buzdan soğuk

Bülbüllerin sesi bile boğuk

O eski sıcaklık yok, 

Zindan hayatı yaşıyorum, 

Sensiz geçen her gece

Seni düşünüyorum her hece

Bir gonca misali kapanmışım

Yabancı ellerde değil 

Kendi diyârımda kayboldum, 

Gölgenin ardında kaldım, 

Dargın değilim ama

Gel artık! 

Kitap okumalarım da eskisi gibi şen değil

Coşmuyorum artık, 

Seninle nehir gibi coşardım.

Belki hep peşinden koşardım

İnan sevda çiçeğim

Hayatımın en mutlu anları onlardı

Sonunda elini tutuyordum ya! 

Bir pınar serinliğinde

Yumuşacık

Pamuk gibi 

Tüm yorgunluğumu atardı

Haaa! Bilmem dedim mi? 

Korkaklık edip

İntiharı falan düşünmem

Nice âşık sevdiği için ölümü denedi 

Nicesi de öldü

Ama o belirsiz karanlığı seçmem

Ben seni farklı bir şekilde sevdim

Ve senin için farklı davranacağım

Lafın kısası

Ben sevdiğim için ölmem

Sevdiğim için YAŞARIM', 'Ansızın bir ağırlık çöker üstüme,  Bir çığ gibi belimi büker,  Sensiz olduğum zaman,  Deniz gözlerine bakardım eskiden,  Bazen sıcacık Bazen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Batıhan']::text[], 8.5, '{"poet":"Mehmet Batıhan","poet_slug":"mehmet-batihan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/yasama-sebebi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun Sancısı', 'kursun-sancisi-mustafa-ozke-r2ond', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'varsa yüreğinde bir kurşun sancısı 

tütüyorsa çayında gurbetin 

iliğine işlemişse kar soğuğu 

ve titremişse damarındaki kan 

sarılsan da seni ısıtmaz parkan 

git en iyisi kuru ekmeğini çorbana ban 

günler bitmiyor diye kederlenme 

kapat gözlerini sen geçiyor san 

uykun geldiyse de gezinme ortalıkta 

ser uyku tulumunu 

git bir kayanın dibinde yat 

yıldızlar olsun üzerindeki yorgan', 'varsa yüreğinde bir kurşun sancısı  tütüyorsa çayında gurbetin  iliğine işlemişse kar soğuğu  ve titremişse damarındaki kan  sarılsan da sen...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kursun-sancisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köpek Hayâller', 'kopek-hay-ller-atilgan-alemdar-hty1v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hani nerede diye soracak olsam

bir kuytuya sinmiştir köpek hayâllerim

döktüğüm nehirlerin denizi nerede

nerede duvardaki kan izleri ellerimin

diye soracak olsam

bir kuytuya sinmiştir köpek hayâllerim

hesabı vardır bakılacaksa eğer

her kalemi bir sarhoş serzenişi tutmuştur

her neredeyse şimdi yok bu hayâller

izi yoktur dünden gözlerimin

belki yenilmiş belki de yenilenmiştir

bir kuytuya sinmiştir köpek hayâllerim

ya sen olsan ne olacaktı

gider miydim

aklım ermiyor

intihar gibi cevapsız bir soru bu

kusulan onlarca çocuklardan sonra

böyle acımasız konuşmak doğru mudur

doğrudur

ki hırsız dediler bana biliyorsun

sana gül çaldığım için

deli dediler

mecnun dediler

sapık dediler kapına gül attığım için

bahçene şiir yağdığım için

biliyorsun

neler dediler ve bunların cevabını verecek olan

korkarım haysiyetini sende bırakan

dinim, imanım duvardaki kafam benim

gece körü cigaralarım

gizli sevda buğularım

canım

yani tüm soruların eksiksiz cevabı

hayata dair

bir kuytaya sinmiştir köpek hayâllerim

takvimde dört yıl bitti

doksansekiz yirmidokuznisan''dan ikibiniki iki mayıs''a

bir de takvim var

gençlikle ihtiyarlık bir mi

bunu demek istemezdim

istemezdim ama neyleyim

mağdur olan benim bu sevdada

ezilmişim

eksik kalmış ezgim

ezgimin kalbi yarım

kalbin yarım mı diye sormadan bu böyle değil diyecek kadar  [çocuk akıllı olan ezgi]

hayâllerimi köpek etmiştir

kimsenin tercih etmeyeceği birşey bu

zehir gibi

gerçi ben zehirkeşim

bunu senelerce, ...senelerce evvel demiştim

demiştim ya neyleyim

bu gün öldüm ve son kez

ve bir kez bile ellerini tutamadan

bu elin uğruna

kendinden vazgeçmiş olsa da bunu bilmeyen

bir kuytuya sinmiştir köpek hayâllerim

boşluğa düşmenin bir sonucu değildi üstelik

sana ilk taptığım gün 

cennetteydim

ki cennette hürdü hayâllerim

köpekler köpeğimdi ben köpek değildim

cennetteydim

sana ilk taptığım gün

bu gün gibi hafızamda

bilir misin

istanbul'' da deniz vardır

ankara'' da deniz yoktur

bilir misin 

yalvarıyorum bilir misin artık

bilir misin

kalbim bilir misin artık

bil artık yalvarıyorum

sen acı bir dişsin içimde

gereği düşünülmüş düşsün içimde

çünkü yıllardır ömrüme yön veren hayâllerim

bu gün son derece haysiyetsiz bir biçimde

ne yaptığı belirsiz

bir şey yapıp yapmadığı

kimin umurunda

soracak olsam 

bir kuytuya sinmiştir köpek hayâllerim

şimdi nerede diye soracak olsam

kalkıp peşine düşecek olsam

ölecek olsam

ellerimden tut desem

içim acıyor

yanıyor

dizlerimin dizi yok

gözlerimin gözü

alnımda yazı yok desem

alnımda yazı

aynı senin gibi gaddardır ey aşkın ezgisi

ezgim

(kalbim)

merhametin her zerresini terk etmiştir

gitmiş

bir kuytuya sinmiştir köpek hayâllerim

Allah beni kahretsin bitmiştir köpek hayâllerim', 'hani nerede diye soracak olsam bir kuytuya sinmiştir köpek hayâllerim döktüğüm nehirlerin denizi nerede nerede duvardaki kan izleri ellerimi...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/kopek-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Uzun Bir Gündü Aşka Dönüyordum', 'cok-uzun-bir-gundu-aska-donuyordum-i-lhan-berk-ug0hr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok uzun bir gündü aşka dönüyordum 

Çok uzun, yavrum, çok uzun seni sevmekten 

İşte diyordum ilk öpüş işte masmavi yarığın 

İşte yedisi sabahın ve ıslak ağzının 


..........
..........', 'Çok uzun bir gündü aşka dönüyordum  Çok uzun, yavrum, çok uzun seni sevmekten  İşte diyordum ilk öpüş işte masmavi yarığın  İşte yedisi saba...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"i-lhan-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cok-uzun-bir-gundu-aska-donuyordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biterse Dünya', 'biterse-dunya-oguzkan-bolukbasi-p6owc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ya  birgün hayat biterse

bir çocuk doğacaksa bitimden bir yıl önce

ve yaşayan çocukların hayallerini kim alacak

ne olacak milyarlarca insan bitişi beklerken', 'ya  birgün hayat biterse bir çocuk doğacaksa bitimden bir yıl önce ve yaşayan çocukların hayallerini kim alacak ne olacak milyarlarca insan ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/biterse-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nigari', 'nigari-i-lhan-berk-5p6ck', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nigâri, bir kâğıdı bir kalemi sevdi. Padişahları gördü Gala-

ta''dan. II. Selim''le ava çıktı.

	I.François''yı, V.Charles''ı çizdi.

	Büyük dedesi gibi satranç oynadı. Bir deniz kitabı yazdı.Bu-

lunamadı.

	Karanfili sevdi. Bunun için  Barbaros''un, II. Selim''in  eline

karanfil verdi.

	

	Kanuni''yi I. François''ya yazacağı mektubu düşünürken gör-

dü. Kanuni  onun için düşüncelidir. Gezdiği yerde yeşil bir  dal var-

dır.

	Padiş
..........
..........', 'Nigâri, bir kâğıdı bir kalemi sevdi. Padişahları gördü Gala- ta''dan. II. Selim''le ava çıktı. 	I.François''yı, V.Charles''ı çizdi. 	Büyük dedes...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"i-lhan-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nigari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zerrece Adamlık', 'zerrece-adamlik-edip-cangonul-x4q0x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Silmeyin ulan gözyaşlarınızı, 

Bu değil erkeklik.

Ne kadar niceldir 

Ya da nitel; 

Döktüğünüz menilerin yanında, 

İki damla su.

Oysa o sedef zerrecikler de saklıdır; 

Adamsanız 

Varsa duygularınız

İnsansanız 

Ve duyabiliyorsanız

Ne acı, 

Ne haz; 

biberdir yaşam da, 

Ateşte kararmış, 

Yeşil

Yada kızıl, 

Pul pul', 'Silmeyin ulan gözyaşlarınızı,  Bu değil erkeklik. Ne kadar niceldir  Ya da nitel;  Döktüğünüz menilerin yanında,  İki damla su. Oysa o sedef...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zerrece-adamlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sever miydim', 'sever-miydim-edip-cangonul-qshuq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sever miydim seni

           Türküler kadar

Anamı sevmeseydim

Gelir miydim hiç

Sıla yakmasa yüreğimi

             Yollarca...

Ayrılır mıydım ölürcesine

              Fukara, 

              Aç, 

              Devrimci...', 'Sever miydim seni            Türküler kadar Anamı sevmeseydim Gelir miydim hiç Sıla yakmasa yüreğimi              Yollarca... Ayrılır mıydım...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sever-miydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-edip-cangonul-lk8e0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hani

Seni dağlara çağırdıydım 

İşte o gece.

Bir keklikten geldi selamın

Yanında bir üveyik.

Epey hellaştıktan sonra

Senden dolayı

Senden gayrı.

Kekliğe dedim ki

Nasılsa sen bizim keklik

Yolun düşerse tez zamanda

Yan komşuya

Selam

De ki selam etti yar sana

Ya üveyik dedim

Yolun uzun

Gider dönersen eğer benden önce

Ardına

Dağların ardına

Yanına

Nazlı yarin yanına

De ki selam etti yar sana

Turna sordu

“ey erenler 

ya ben dönersem üveyikten önce”.

dedim; 

ya turna

avazı Ali turna

yar ki duymamış benim avazım

sen iletebilir misin

bende ki sevda sesini

hasretim

sevdalıyım', 'hani Seni dağlara çağırdıydım  İşte o gece. Bir keklikten geldi selamın Yanında bir üveyik. Epey hellaştıktan sonra Senden dolayı Senden gay...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hani-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahın Körü Rubaisi', 'sabahin-koru-rubaisi-edip-cangonul-d3kxm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne gece, 

Ne onun bir vakti.

ne güneş ucunu gösterdi 

ne ay ışıttı.

yukarı tükürsen ay, 

aşağı tükürsen güneş

işte eyle seviyem

kör sabahlarda

yada alacakaranlıkta', 'Ne gece,  Ne onun bir vakti. ne güneş ucunu gösterdi  ne ay ışıttı. yukarı tükürsen ay,  aşağı tükürsen güneş işte eyle seviyem kör sabahlar...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sabahin-koru-rubaisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün ""D"" Hali', 'olumun-d-hali-edip-cangonul-mak6s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İsmin en güzel hali

      İyelik hali

Ya ölümün

Yalnız

    Bir başına mı

Yoksa herkesin “iyi bilirdik” dediği mi

En iyisi her ikisi

Ya en kötüsü

Bir sürü zevatı ortasında bir hıyar gibi yatarken

                              Başında da bir hıyar ağası

Sen sarhoş

Hıyarağası zom

İyi bilirdik diyenlerinse 

alkol yüzdesi

orta halli.

müşteki; 

Tanrı hıyar ağasından, 

Alkol cümlemizden.', 'İsmin en güzel hali       İyelik hali Ya ölümün Yalnız     Bir başına mı Yoksa herkesin “iyi bilirdik” dediği mi En iyisi her ikisi Ya en kö...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olumun-d-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenmeyen Gidiş', 'beklenmeyen-gidis-seda-omercikoglu-5bfge', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'takvimden bir yaprak daha koptu

günler alabildiğine acımasız

bir sonamı yaklaştırıyor

zaman bu kadar mı soğuktu

yüzünü göreyim dedim ilk önce

sonra bencillik diz boyu

benim olsun istedim

ona göre bu çok zordu

ağlamayacaksın bu gidişe

damla akmayacak gözünden

gözden akmayan damla

kalbe akar bu doğruydu

güzel günler geçti onunla

heyecan verici, tutkulu, kıskanç

dürüst olursak sevmişim be

farkına varmadan delice

gitme vakti gelince

gözler birbirine kitlenince

utanmadan haykıracağım kalbine

SEVMİŞİTM SENİ ALABİLDİĞİNE....(16 MART)', 'takvimden bir yaprak daha koptu günler alabildiğine acımasız bir sonamı yaklaştırıyor zaman bu kadar mı soğuktu yüzünü göreyim dedim ilk önc...', ARRAY['Türk Edebiyatı','Şiir','Seda Ömercikoğlu']::text[], 8.5, '{"poet":"Seda Ömercikoğlu","poet_slug":"seda-omercikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beklenmeyen-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Tutarsa Güneşi', 'kim-tutarsa-gunesi-gulsah-culha-q2scn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğumu, filizlerimi 

Yeşerten tohumlarımın

Toprağa ekildiğim andır.

Gözüm ilk açılışında 

Güneşi gördü

Bir de giydirildiğim kanları

İlk defa toprağı kokladım

Bir de anamın terini.

Sonra teninin nasırlı kokusunu 

Babamın.

Yüreğim, o kanlardan

Ateşinin rengini

Umudunu, o güneşten

O topraktan

güvenini aldı

Şefkatini o ana 

o baba, emeğini

Gücünü o tohum verdi.

Serpildim Anadolu''nun

Bereketli yeşillerinde! 

Umudum, ekin olma 

Yolunda.

Derken, yoğruldum

Emekçilerin ağıt dilli

Gözyaşlarıyla! 

Asillerin sünger sunan 

Çoraklığı

Soldurdu kır çiçeklerimi...

Koşarken güneşin peşinden

Düştüm

suyu gördüm

Ekmeği, tuzu 

bir de taşı.

koynuma dolandıkça 

Yılanlar

Dilime sitemlerin

En hırçını.

Sinenleri anladım, sinsilerle

Ama ben sevgi adına

Zalimler! ..

Emek, insan adına.

Ben baş kaldırıyorum

Hadi bakalım, 

Güneşi Kim Tutarsa! ..', 'Doğumu, filizlerimi  Yeşerten tohumlarımın Toprağa ekildiğim andır. Gözüm ilk açılışında  Güneşi gördü Bir de giydirildiğim kanları İlk defa...', ARRAY['Türk Edebiyatı','Şiir','Gülşah Çulha']::text[], 8.5, '{"poet":"Gülşah Çulha","poet_slug":"gulsah-culha","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/kim-tutarsa-gunesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim derdi ki...!', 'kim-derdi-ki-gokhan-oktem-itby3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim derdi ki bir tanem bensiz yaşayacaksın

Bir bilinmez hiç olup ömrümden çalacaksın

Var mı elleri hüznün dillenir mi sevdalar

Sorsam hatırlamazsın yolda kalan yadigar

Bir çelimsiz damlaydık havadayken dağıldık

Geçirgen ve  saydamdık, suya hasret ayrıldık

Tırpan yemiş sevdaydık, yıldızlar gibi kaydık

Süzülüp yağacakken birden meçhule aktık

Kim derdi ki bir tanem güneşsiz açacaksın

Zemheri karanlıklar içine doğacaksın

İsterdim ki bahtının yıldızı hep parlasın

Lakin, bilirim elbet bensiz yaşayacaksın



11,05,202,  İstanbul', 'Kim derdi ki bir tanem bensiz yaşayacaksın Bir bilinmez hiç olup ömrümden çalacaksın Var mı elleri hüznün dillenir mi sevdalar Sorsam hatırl...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kim-derdi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-sait-ferhat-ozmen-hcaif', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlıktan sıkıldım en başında.

Sıkıldığımı her düşündüğümde, 

Önce yalnızlığıma kızdım, 

Sonra kendime...

Sonra kızdım yine kendime, 

Yalnızlığıma kızmama.

Yalnız değildim aslında

Sen vardın hayatımda...', 'Yalnızlıktan sıkıldım en başında. Sıkıldığımı her düşündüğümde,  Önce yalnızlığıma kızdım,  Sonra kendime... Sonra kızdım yine kendime,  Yal...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizligim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey İçin', 'hersey-i-cin-sait-ferhat-ozmen-idkae', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben aştım; anlatmaktansa, 

Anlanılmayı hedefliyorum artık.

Nefes aldığımda yaşadığımı hissetmek gibi, 

Seni sevmek benim için.

Ya da damarlarımda kanın gezindiğini bilmek gibi, 

Keza belki de ateşi olmayan sigara gibi.

Bana yaşadığımı hatırlattığın, yaşattığın

Ve paylaştığın için 

Sağol....', 'Ben aştım; anlatmaktansa,  Anlanılmayı hedefliyorum artık. Nefes aldığımda yaşadığımı hissetmek gibi,  Seni sevmek benim için. Ya da damarla...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hersey-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksan', 'yoksan-sait-ferhat-ozmen-sfe9k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşam denen zaman süresindeki

Göz kırpma süresi kadar olan zamanda

Eğer sen olmayacaksan

Ben hayatımın tamamını bir kalemde silerdim.', 'Yaşam denen zaman süresindeki Göz kırpma süresi kadar olan zamanda Eğer sen olmayacaksan Ben hayatımın tamamını bir kalemde silerdim....', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yoksan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-burakcan-avci-v0ktu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canım annem seni çok severim

Mayısın ikinci haftası pazar günü

Anneler gününde daha çok  severim

Anneler günün kutlu olsun.', 'Canım annem seni çok severim Mayısın ikinci haftası pazar günü Anneler gününde daha çok  severim Anneler günün kutlu olsun....', ARRAY['Türk Edebiyatı','Şiir','Burakcan Avcı']::text[], 8.5, '{"poet":"Burakcan Avcı","poet_slug":"burakcan-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/annem-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu kenti terketmeliyim', 'bu-kenti-terketmeliyim-arif-altunbas-nmxdr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vurgun yemiş alanlardan büyülü sokaklardan

Savaşcı yüreğimi ve kimliğimi alarak

Omuzlarımda dağ gibi bir vebal ile

Bu kenti onurluca terketmeliyim 

Ashabı Keyf uykularından uyanarak

İçimin yangınlarını karlar ile yuğurmalıyım

Katledilen kimliğimi 

Kaybolan değerlerimi yeniden bularak

İşgal olan kalemi yeniden feth etmek için

Bir gün mutlaka geri dönmek üzre

Bu kenti  terketmeliyim

Ankara,24,08.1980', 'Vurgun yemiş alanlardan büyülü sokaklardan Savaşcı yüreğimi ve kimliğimi alarak Omuzlarımda dağ gibi bir vebal ile Bu kenti onurluca terketm...', ARRAY['Türk Edebiyatı','Şiir','Arif Altunbaş']::text[], 8.5, '{"poet":"Arif Altunbaş","poet_slug":"arif-altunbas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-kenti-terketmeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidebilirsin', 'gidebilirsin-ahmet-selcuk-i-lkan-alk7l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Madem ki içinde o ateş söndü

Bir daha yakmadan gidebilirsin

Aklımda kalmasın bu son bakışlar

Yüzüme bakmadan gidebilirsin

Yıllardır verdiğin kederi görme

Üstüme yıktığın kaderi görme

Ömrümden çaldığın günleri görme

Beni de görmeden gidebilirsin

Sen düşün yaranı kimler saracak

Sen düşün gönlünü kim avutacak

Bir an önce kaybol oldu olacak

Bir veda etmeden gidebilirsin

Demek ben suçluyum bir tek sen haklı

Ben zalim bir düşman sense zavallı

En güzeli alıp beni asmalı

Beni affetmeden gidebilirsin

Zorlama kendini veda etmeye

Zorlama gözünden yaşlar dökmeye

Mecbur da değilsin birşey demeye

Hiç bir şey demeden gidebilirsin....', 'Madem ki içinde o ateş söndü Bir daha yakmadan gidebilirsin Aklımda kalmasın bu son bakışlar Yüzüme bakmadan gidebilirsin Yıllardır verdiğin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidebilirsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötülüğe Dair', 'kotuluge-dair-mustafa-ozke-ndvqg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'akrep kuyruğunda zehir

ateş yanında kuru barut

kelle kesen bir cellat

olsan ki kan emen bir sülük

ne kazanırsın hayattan

yaşarken iyilik

bak bir yanda barış var

bir yanda kelleciler

bir yanda iktidar

bir yanda hülleciler

bir yanda küpçüler

bir yanda lüpçüler

herşey bir yanda

ne yazar barut olsun

zehir olsan kimin umurunda

kim diken cellatın elbisesini

kim keser sülüğün nefesini

kim duyar hıçkırığını ağlarken

kim gömer öldüğünde yalnızsan seni

gün gelip devran dönecek

iyiler de gülecek bir gün

akrep ateşe düşecek

barut yanıp kül olacak

kuruyacak sülüğün kanı

cellatın da başı kesilecek

yaptığı yanına kalmayacak kimsenin

kötülük de içine girecek biçtiği kefenin', 'akrep kuyruğunda zehir ateş yanında kuru barut kelle kesen bir cellat olsan ki kan emen bir sülük ne kazanırsın hayattan yaşarken iyilik bak...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kotuluge-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuz', 'uykusuz-ahmet-selcuk-i-lkan-ql0ty', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saatler sabahı çalıyor yine

Bir gece lambası bir ben uykusuz

Kulağım hep senin ayak sesinde

Bir şu kaldırımlar bir ben uykusuz

Yaralı yüreğim her an pusuda

Şafakla dönersin hani olur ya

Şimdi bütün şehir derin uykuda

Bir şu yaralı gözler bir ben uykusuz

Bir tek o şahitti son akşamında

Yeniden yanarım her yanışında

Ben gibi kimsesiz köşe başında

Bir sokak lambası bir ben uykusuz

Nöbetteyim sokaklarda

Gözlerim hep şafaklarda

Sense benden uzaklarda

Bir gece bekçisi bir ben uykusuz.....', 'Saatler sabahı çalıyor yine Bir gece lambası bir ben uykusuz Kulağım hep senin ayak sesinde Bir şu kaldırımlar bir ben uykusuz Yaralı yüreği...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uykusuz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalan Aşkım', 'yarim-kalan-askim-hulya-arisan-04qv5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayal miydin gerçek miydin

daha bilemeden, 

kopardın kendini benden

allak bullak oldum birden.

Yaşayamadan aşkımı

bitiriverdin kendiliğinden.

Yarım kalan duygularım

çöktü kabus gibi yüreğime.

Anılarım 

yeter mi? 

bu yara 

kapanır mı? 

Kapanmaz bilirim, 

onunla yaşamayı öğrenmeliyim.

Senden gelen acıları,

hep sevdim istemeden...

Istanbul,8 mayıs 2002', 'Hayal miydin gerçek miydin daha bilemeden,  kopardın kendini benden allak bullak oldum birden. Yaşayamadan aşkımı bitiriverdin kendiliğinden...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yarim-kalan-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-mehmet-akif-i-nan-co3b2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kapalı çarşı büyür gider

Ben gönlümden başka yerde olamam

Piyano üstüne birkaç söz yani

Aşksız ve müziksiz herşey anlamsız

Şefkatten terlikler sergilenmeli

Bir çocuk yanağı ayaklarında

Varla yok arası yürüyen ilgi

Tereddüt heykeli bir sinemadır

Suskunluğu bölen kızgın bir sitem

Unutulmuş vitrinde pol ve virjini

Huzur limanına uğrar mı bilmem

Sonsuza yönelen vapurlarımız

Anı galerisi kutlu İstanbul

Fatih''ten asılar sürdürmektedir

Sokaklar insanlar hep bize küstü

Deniz kenarında bir öğle üstü', 'Bir kapalı çarşı büyür gider Ben gönlümden başka yerde olamam Piyano üstüne birkaç söz yani Aşksız ve müziksiz herşey anlamsız Şefkatten ter...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif İnan']::text[], 8.5, '{"poet":"Mehmet Akif İnan","poet_slug":"mehmet-akif-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarnıç', 'sarnic-mehmet-akif-i-nan-279jq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adağı olduğum gülücüğüne

Gör ne ucuz pazardır

Yeni bir bakışla kavradın beni

Barış mı kavga mıdır

Sürsün bitmesin bu onurlu ilgi

Bu çağın çıkmazıdır

Bir kuru sarnıçtır sensiz hayalim

Candır aşkın bedeli

Ey dil ey kalbimin öksüz çocuğu

Azığın ağıt senin

Gözlerin içimin tutukevidir

O bir özge meydandır

Düşlerim seninle kuşatılmıştır

Ağzım değmez eline', 'Adağı olduğum gülücüğüne Gör ne ucuz pazardır Yeni bir bakışla kavradın beni Barış mı kavga mıdır Sürsün bitmesin bu onurlu ilgi Bu çağın çı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif İnan']::text[], 8.5, '{"poet":"Mehmet Akif İnan","poet_slug":"mehmet-akif-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sarnic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melce', 'melce-mehmet-akif-i-nan-02ei6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kâse su gibi dökülse kuma 

Kuramlar kollayan dik başlı aklım 

Rüzgârın başıma verdiği şekil 

Yol olsa içimin ormanlarında 

Unutsam eşyanın gürültüsün 

Rengini suların tadını gülün 

Günleri bir secde hızıyla geçip 

Erişsem mahşere bir iftar gibi 

Genişle ey kalbim kardan sözlerle 

Ayıkla ve yıka pıhtılarını', 'Bir kâse su gibi dökülse kuma  Kuramlar kollayan dik başlı aklım  Rüzgârın başıma verdiği şekil  Yol olsa içimin ormanlarında  Unutsam eşyan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif İnan']::text[], 8.5, '{"poet":"Mehmet Akif İnan","poet_slug":"mehmet-akif-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/melce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şan', 'san-mehmet-akif-i-nan-hu7zf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüya gibi atlar ve erler vardı

Her bahar yürürdü düşman üstüne

Ülke coğrafyası bir dilim vardı

Yunusun Galibin soylu gergefi

Şanlı gözyaşları yıkardı içi

Yağmurla dönülür dualar vardı

Babalar amcalar kardeşler vardı

Anneler dayılar halalar vardı

Düğünler hamamlar halaylar vardı

Üstünde yol alan destanlarımın

Edepti yoğuran güzelliğimi

Zekattı üreten zenginliğimi', 'Rüya gibi atlar ve erler vardı Her bahar yürürdü düşman üstüne Ülke coğrafyası bir dilim vardı Yunusun Galibin soylu gergefi Şanlı gözyaşlar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif İnan']::text[], 8.5, '{"poet":"Mehmet Akif İnan","poet_slug":"mehmet-akif-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/san-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağın Babası', 'topragin-babasi-mehmet-akif-i-nan-zmvsb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eylemin o önder çocuğu büyür

Evrenin sebebi en son ellerde

Alnında sürekli secde gülleri

Sevgi donanması denizlerinde

Yağmur olsun diye saçar göklere

Elinde biriken dualarını

Ve nur yatağında kılıçla bekler

Sonsuza açılan hicret aşkına

Bilge anahtarı has neslin kökü

Zülfikar çağlardan çağlara nehir

Toprağın babası kucakta uyur

İki güzel iki kumru iki er

Kıyanın hesabı nicolur bilmem

Dinmeyen bir hüzün bir kandir sızar', 'Eylemin o önder çocuğu büyür Evrenin sebebi en son ellerde Alnında sürekli secde gülleri Sevgi donanması denizlerinde Yağmur olsun diye saça...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif İnan']::text[], 8.5, '{"poet":"Mehmet Akif İnan","poet_slug":"mehmet-akif-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/topragin-babasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir Gazeli', 'sehir-gazeli-mehmet-akif-i-nan-dewc8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her eylem yeniden diriltir beni

Nehirler düşlerim göl kenarında

Ey deprem gel yetiş bu şehirlerin

Doğayı çarptıran konumlarına

Doğ ey güneş erit taştan adamı

Ve kurut taşları diken elleri

Babamın gölgesi koruyor beni

Oh ne güzel şehir bu eski şehir

Dönüştür ey kalbim bahçeli eve

Anlamı ezen o makinaları

Kurtuluş haberi olsun dünyaya

Ayırma üstümden bir an gölgeni', 'Her eylem yeniden diriltir beni Nehirler düşlerim göl kenarında Ey deprem gel yetiş bu şehirlerin Doğayı çarptıran konumlarına Doğ ey güneş ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif İnan']::text[], 8.5, '{"poet":"Mehmet Akif İnan","poet_slug":"mehmet-akif-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sehir-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Sakın', 'aglama-sakin-elif-atici-bpsab', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sakın ağlatma gözlerini

Sanma ki göz yaşın olacak

Yanaklarından sızan

Düşlerim, umutlarım gizli

Deniz gözlerindeki derinlerde

Düşün ki; 

Ağladığında

Damlayan  her yaşta

Gözlerindeki ben

Bir de; 

Deli sevdam  akacak...', 'Sakın ağlatma gözlerini Sanma ki göz yaşın olacak Yanaklarından sızan Düşlerim, umutlarım gizli Deniz gözlerindeki derinlerde Düşün ki;  Ağl...', ARRAY['Türk Edebiyatı','Şiir','Elif Atıcı']::text[], 8.5, '{"poet":"Elif Atıcı","poet_slug":"elif-atici","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aglama-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Benim Şiirim', 'bu-benim-siirim-ahmet-selcuk-i-lkan-0mdnx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duyduğun her yerde beni hatırla

Bu benim şiirim bu benim şarkım

Dinle ki kanatsın o taş kalbini

Bu benim şiirim bu benim şarkım

Yabancı kollarda gezip durdukça

Başını yastığa koyup daldıkça

Bir daha çalıver beni andıkça

Bu benim şiirirm bu benim şarkım

Bırak da süzülsün yaşlar gözünden

Acı bir pişmanlık dursun yüzünde

Sana bir sitem var her bir sözünde

Bu benim şiirim bu benim şarkım

Aşkımdan armağan her bir satır sana

Maziyi yeniden yaşatır sana

Nasıl sevdiğimi anlatır sana

Bu benim şiirim bu benim şarkım.', 'Duyduğun her yerde beni hatırla Bu benim şiirim bu benim şarkım Dinle ki kanatsın o taş kalbini Bu benim şiirim bu benim şarkım Yabancı koll...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-benim-siirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ Gölgesi Yalnızı', 'dag-golgesi-yalnizi-ramazan-topoglu-p2xfe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün ufukta soldu

Dağ gölgesi yalnızıyım

Bu nehrin suyu bulandı, göl küskünüyüm

Yorgunum 

Nehrin öte yakası çağırıyor

Gün ufukta doğdu

Tan yeri ağarması şaşkınıyım

Şehrin huyu bozuldu, çöl düşkünüyüm

Yolcuyum

Bir masal  şehrinin yeni sokağı çağırıyor

Özlenilen eski zamanlar

Dağ bulutları vaktinde sümbülî gökyüzü, yağmurda  çoban 

Ve hatırlamaktan korkulan sen

Bir ara kendiliğinden aklıma düşer misin

Tükeniyorum bilmiyor musun

Gün ufukta soldu

                 Dağ gölgesi yalnızıyım

Gün ufukta  doğdu

                Tan yeri ağarması şaşkınıyım

Nehrin suyu bulandı, 

                                  Göl küskünüyüm

Şehrin huyu bozuldu, 

                                  Çöl düşkünüyüm

Sonunda 

Sonunda şehir olmayan ormanda kaybolmalıyım', 'Gün ufukta soldu Dağ gölgesi yalnızıyım Bu nehrin suyu bulandı, göl küskünüyüm Yorgunum  Nehrin öte yakası çağırıyor Gün ufukta doğdu Tan ye...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Topoğlu']::text[], 8.5, '{"poet":"Ramazan Topoğlu","poet_slug":"ramazan-topoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dag-golgesi-yalnizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakın - Uzak', 'yakin-uzak-ceyhun-yilmaz-v7qoo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalk git diyorum içimden kendime, kalk git uzağa

Kulağındaki müzik bitene kadar yürü, ağladığın kadar koş

Aya dokunana kadar yürü uzaklaş, düştüğün yer yakınlarına uzak olsun', 'Kalk git diyorum içimden kendime, kalk git uzağa Kulağındaki müzik bitene kadar yürü, ağladığın kadar koş Aya dokunana kadar yürü uzaklaş, d...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yakin-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazar', 'yazar-ali-i-ldeniz-gulyb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ozan yazar gözleri buğulu, 

Elinde kırık kalemi...

Beyaz düşünceler yazar kara sayfalara, 

Yorgun nasırlı elleri...', 'Bir ozan yazar gözleri buğulu,  Elinde kırık kalemi... Beyaz düşünceler yazar kara sayfalara,  Yorgun nasırlı elleri......', ARRAY['Türk Edebiyatı','Şiir','Ali İldeniz']::text[], 8.5, '{"poet":"Ali İldeniz","poet_slug":"ali-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yazar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-abdullah-yuce-20wca', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilki bu gün ayrılık var ufukta

Özlem içimde koor.

Bana sorma sebebini güzelim 

Gözlerine sor.

Önce bir düşün! 

Akıl yaştamıdır başta mı? 

Sonra yum gözlerini

Yum ve uyan.

Uyan bildiğin gerçeklerden! 

Dal düşler bahçesine istersen.

Veya kenetle gözlerini gözlerime, 

Lütfen düşle benimle...

Fakat hazır ol! 

Bir kırık kalp görmeye

Bir teselli vermeye hazır ol.

Çünkü sayende canım

Düş bahçemde artık pembe değil bulutlar.

Sayende battı güneş

Sayende soldu umutlar.

yazık, 

Yazık sayende canım

Artık ne açacak gonca gül

Ne ötecek bülbül var...

Garip değil mi? 

Hem özlem dolu gözlerim

Hem de göz yaşım sel.

Bir dileğim kaldı senden

Büyü de gel...', 'Bilki bu gün ayrılık var ufukta Özlem içimde koor. Bana sorma sebebini güzelim  Gözlerine sor. Önce bir düşün!  Akıl yaştamıdır başta mı?  S...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yüce']::text[], 8.5, '{"poet":"Abdullah Yüce","poet_slug":"abdullah-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ozlem-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak', 'yasak-ceyhun-yilmaz-qsh9d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimselere söylemeden çıktım yola

Sabahtan bile erken, güneşe hissettirmeden

Kimsesizliğim merak eder mi diye düşündüm seni

Dolmabahçe''de bir çay söyledim kendime ve garsona rağmen ikinci bir çay sana

Senin içmediğin çayına bakarak düşündüm seni

İstanbul''a yakalandım sensizliğimle, 

Ne var bunda canım o da yasak değil yaa...', 'Kimselere söylemeden çıktım yola Sabahtan bile erken, güneşe hissettirmeden Kimsesizliğim merak eder mi diye düşündüm seni Dolmabahçe''de bir...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yasak-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eldiven', 'eldiven-ceyhun-yilmaz-xuv7p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Demirden soğuk ellerin

Bakışlarında kar yağışı

Soğuktan yanan sözlerin sahibi sen

Belki hep bu yüzden

Senli her cümlede bir eldiven', 'Demirden soğuk ellerin Bakışlarında kar yağışı Soğuktan yanan sözlerin sahibi sen Belki hep bu yüzden Senli her cümlede bir eldiven...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/eldiven-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Öyle Çok Sevdim Ki', 'seni-oyle-cok-sevdim-ki-burak-altinsoy-u6ahk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni öyle çok sevdimki, 

gönlümden her sen damlasını sökmek, asırlar sürüyor

Sana o kadar çok taptımkl, tanrım bile artık, kulum demiyor.', 'Seni öyle çok sevdimki,  gönlümden her sen damlasını sökmek, asırlar sürüyor Sana o kadar çok taptımkl, tanrım bile artık, kulum demiyor....', ARRAY['Türk Edebiyatı','Şiir','Burak Altınsoy']::text[], 8.5, '{"poet":"Burak Altınsoy","poet_slug":"burak-altinsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/seni-oyle-cok-sevdim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akvaryum', 'akvaryum-ceyhun-yilmaz-yzlc5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessizce seviyorum seni

Söylesem de duymazsın zaten

Senin gözlerin gibi bakıyorum sana

Senin bana bakmadığın gibi

Dokunmuyorum sana

Zaten tutmak istesem de

Yapamam kıyamam sana

Dokunduğumda öleceksin biliyorum

O yüzden seni hep

Bir camın ardından seviyorum', 'Sessizce seviyorum seni Söylesem de duymazsın zaten Senin gözlerin gibi bakıyorum sana Senin bana bakmadığın gibi Dokunmuyorum sana Zaten tu...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/akvaryum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-ceyhun-yilmaz-6j4vp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonbaharın en eylül''ü içimde, 

Her bastığım kuru yaprak

sen olup o eski şarkıyı hatırlatıyor bana; 

Kolumda senden çaldığım tebessüm uyutup büyütüyorum onu, 

Bir namussuz rüzgar peşimde, 

Saçlarımı ensemden okşayıp yanağımdan öpüyor gülümsetiyor beni

sen yoksun ve sensin her şarkıda ağlayıp üzüldüğüm

Böyle mi bitecekti bu şiir birtanem böyle mi bitecekti bu şiir

son hecesi hüzün...', 'Sonbaharın en eylül''ü içimde,  Her bastığım kuru yaprak sen olup o eski şarkıyı hatırlatıyor bana;  Kolumda senden çaldığım tebessüm uyutup ...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sonbahar-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Çiçeği', 'sevgi-cicegi-ceyhun-yilmaz-ysdmg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sardım sarmaladım

kimse görmeden getirdim eve

kapattım pencereleri

güneş almasın diye..

şimdi büyüyor...öylece bakıyor bana

Yalnızlığım

yapayalnızlığım

yalpalayan yalnızlığım', 'sardım sarmaladım kimse görmeden getirdim eve kapattım pencereleri güneş almasın diye.. şimdi büyüyor...öylece bakıyor bana Yalnızlığım yapa...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-ceyhun-yilmaz-lu596', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman mı geç kalıyor

Sen mi dokunamaz oldun zamana

Bu kadar geç kalmazdı selamın

Doğan güneşe mahçup etmezdin beni

Şu ağaçları bana güldürmezdin', 'Zaman mı geç kalıyor Sen mi dokunamaz oldun zamana Bu kadar geç kalmazdı selamın Doğan güneşe mahçup etmezdin beni Şu ağaçları bana güldürme...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zaman-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam', 'selam-ceyhun-yilmaz-yc1eo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahlar da soğudu, 

Bir ayaz var ki insanların tebessümü donmuş.

Sıcak bir selam söyledim ortaya.

Herkes ayrı bir köşeye kaçtı.

Bunlar neden böyle? 

Hepsi mi sana aşık? 

Benim gibi...', 'Sabahlar da soğudu,  Bir ayaz var ki insanların tebessümü donmuş. Sıcak bir selam söyledim ortaya. Herkes ayrı bir köşeye kaçtı. Bunlar nede...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/selam-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiciv', 'hiciv-abdullah-oztemiz-1umh9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'HİCİV(kemer sıkma)

Kabzımal sebze, kasap et kaçırır

Ahmedin hakkını Mehmet kaçırır

Uyarak emre sıkarken kemeri

Şaşırıp altına millet kaçırır.', 'HİCİV(kemer sıkma) Kabzımal sebze, kasap et kaçırır Ahmedin hakkını Mehmet kaçırır Uyarak emre sıkarken kemeri Şaşırıp altına millet kaçırır...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztemiz']::text[], 8.5, '{"poet":"Abdullah Öztemiz","poet_slug":"abdullah-oztemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hiciv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-melike-kordon-4mcmj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Son bahardaki yapraklarda 

Dökülür mü hep yüreklerden sevdalar? 

Rüzgar hep hasret lemi eser? 

Uzak diyarlara yolculuk varken

Bu sevdalı gönlüme nasıl söz geçer? 

Yüreğimde her satıra 

Kazıdım seni mısra mısra

Senide götürüyorum mısralarımda, bir tanem

En ağır yük buruk hasretin sırtımda

Geceler, 

Efkarı bende gizli

Heceler, 

Ayrılık diyor, gözyaşlarıyla ıslak

Hasretin bulutlarıyla sisli.

Elimde senden kalma bir tütün kokusu

Yıldızlar geliyor birde benimle, 

Sevdamızla izli

Yüreğimdeki her mısrada 

Senide götürüyorum bilmediğim uzaklara

Bir tek yüreğim kalıyor benden 

Penceremde sana akmış gözyaşım

Sensiz acıklı bir değirmen olurda, 

Döner başım

Sevdamızı iz yapmış yıldızlara

Yüreğimizde tutsak vebayı söyleyeceğim

Yıldızlar duyacak haykırışlarımı

Yürekle sözleşme olmaz

Titreyen ellerde

Kelepçe durmaz deyip

Yıldızlara sevdamızı mühürleyeceğim

Sanma kan çanağı gözlerimle gülüyorum

Ne öldürüyorum içimdeki filizi

Ne de büyüyorum

Veda etmek yoktu ama

Seni alıp omzuma

Sensiz bir diyara

Seninle gidiyorum

Sevdamızla izli yıldızlarda

Bizli bir türkü çınlıyor

Dilim takıldı bu türküye sonunda

Kulaklarına fısıldıyorum şimdi haykırışlarımla

                                                         ELVEDA...', 'Son bahardaki yapraklarda  Dökülür mü hep yüreklerden sevdalar?  Rüzgar hep hasret lemi eser?  Uzak diyarlara yolculuk varken Bu sevdalı gön...', ARRAY['Türk Edebiyatı','Şiir','Melike Kordon']::text[], 8.5, '{"poet":"Melike Kordon","poet_slug":"melike-kordon","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/elveda-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Özürlüğünde Saklısın', 'kendi-ozurlugunde-saklisin-melike-kordon-cqlff', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık yolları dolaş

Sislerini dağıt düşlerinin 

En derin karanlıklarda bile 

Işıldıyor gözlerin senin 

Aydınlığı da dolaş benim için 

Güneş iliklerine kadar girsin

Ben o güneşle sarılacağım 

Düşlerinin bir deli saatinde

Sol koluna yaslanmış olacağım

Bütün güzellikleriyle kainat senin

İstediğin yerde durabilir ellerin

Gülüşün rüzgarla dağları dolaşabilir

Kendi özgürlüğünde saklısın

Gözlerim seni, sadece yıldızlardan görebilir

Gözlerinde yanmış küllerimi

Gülüşünün gezdiği dağlara salıverdim

Bir gülüşe, bin külümü verdim

Gülüşünün yorgun düştüğü toprağa

Gönlümün dikenli beyaz gülünü verdim

Işıldasın gülüşün gökyüzünde şimdi

Büyülü dumanın gönlünce tütebilir

Dumanlı yollarda bilir misin

Yalnız beyaz güller bitebilir

Güzel düşler konuştu fırtınasıyla

Şimdi serin bir yer esebilir

İki kalp susamıştı bilmediği bir suya

Şimdi damlalar buharlaşabilir

Su buharıyla dolaşsın gözlerin

Gülüşün yolumu bir sis olup kesebilir

Asi gülüme damlaların, çiğ olup düşebilir

Kendi özgürlüğünde saklısın

Gözlerim seni, sadece yıldızlarda görebilir', 'Karanlık yolları dolaş Sislerini dağıt düşlerinin  En derin karanlıklarda bile  Işıldıyor gözlerin senin  Aydınlığı da dolaş benim için  Gün...', ARRAY['Türk Edebiyatı','Şiir','Melike Kordon']::text[], 8.5, '{"poet":"Melike Kordon","poet_slug":"melike-kordon","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kendi-ozurlugunde-saklisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-abdullah-yuce-fpzgj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlat deyince kendimi anlatamam! 

Belki abartırım, 

Göklere çıkartırım yanılırsın! ..

Belki de vururum yeden yere

Yazık olur.

Eğer kaşım gözüm, 

Boyum posumsa merakın? 

Eh, o belki olur, 

Anlatırım elbet. 

Fakat, aynada ne gördümse! ...

Kimi ruh halimle sorarım aynalara 

Nasıl dayandılar, 

Neden çatlamadılar? 

Kimi zaman aah çekerim, 

Nerde o eski aynalar? ...', 'Anlat deyince kendimi anlatamam!  Belki abartırım,  Göklere çıkartırım yanılırsın! .. Belki de vururum yeden yere Yazık olur. Eğer kaşım göz...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yüce']::text[], 8.5, '{"poet":"Abdullah Yüce","poet_slug":"abdullah-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aynalar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kral Mezarı', 'kral-mezari-melike-kordon-7n5re', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Issız gecenin zifir saatleri, 

                                 gözlerin yok.

Soğuk her baktığım çehre, 

                                gülüşün  yok.

Gözyaşımdan başka gökyüzünde damla yok.

Kolum yok sensiz, 

Kanadım yok 

Bu dünyada zaten, 

                   sensiz yaşamaya yüzüm yok.

Gönlümün yanardağı, 

İki gözüm yok! 

Bir deli fişeği sevdim

Gözleri, yeşeren kırlar gibi

Sözleri hem küskün hem azarlar gibi

Tac oldu başıma

yoldaş oldu savaşıma

Secdeye durdum sanki

Kurban oldum bir damla gözyaşına

Bir okyanusa karınca düşüp 

                               nasıl boğulmuşsa

Bende boğuldum o  zümrüt okyanusta

Can verdim, 

O, deli – yeşil çırpınışta

Bir kral mezarındayım şimdi 

                           yüreğimde prensim büyüdü

Gönül devletimin başına geçti.

Veliahtım, ilk hükümdarlık kararını 

                                   beni gözlerinde yakarak seçti.

O zümrüt gözleri yıldızlardan kıskanırdım ben 

Bir gülüşüyle güller yollarına eğilirdi

Ben gönül kralımın ilk fermanıyım

Ben ölünce yaşayacaksa 

                            onun dermanıyım     

Bir kral mezarındayım şimdi 

İki gözüm! 

Gönül sözüm! 

Benim gecem gündüzüm! 

İki dudağının arasındaki fermanla öldüm ben

Sen ağlama diye yalandan hep güldüm ben.

Cellat beni gözlerinin denizine itti 

Zümrüt bir denizdeyim şimdi 

O, kralı kendi gözlerime gömdüm

Ben kralı önce sevdim, sonra öldüm

O gözlerle hem ağladım, hem güldüm

Bin kere gelsem dünyaya 

Bin kerede fermanla ölecek olsam 

Gözlerine inatla yürüdüm.

Yine de, 

Zümrüt gözlerinde ölürdüm.', 'Issız gecenin zifir saatleri,                                   gözlerin yok. Soğuk her baktığım çehre,                                  gül...', ARRAY['Türk Edebiyatı','Şiir','Melike Kordon']::text[], 8.5, '{"poet":"Melike Kordon","poet_slug":"melike-kordon","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/kral-mezari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar Şehri', 'mezar-sehri-melike-kordon-1ldhx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece oldu mu ok fırlıyor yayından

Karanlığı bulutlar ardına saklanmış

Bir uğultu kaplıyor 

Ateş bir pençe gönlümü dağlıyor 

Ne var bu şehirde böyle? 

Bana kabuslar gördürten

Nerden esiyor bu sinsi rüzgar? 

Bu hangi yalnız dağın soğuğu böyle? 

Bu kezzap hangi buluttan yağıyor? 

Ne var bu şehirde böyle? 

Badem ağaçlarını kurutan

Sol kaşımdakinden başka bende ben bırakmayan

Bu şehirde ne var? 

Girdiğim kapılar 

Uzun gıcırtılarla kapanıyor üstüme 

En kaz nerde? 

İçimdeki hangi ur böyle

Gözlerimi kör eden 

Bu duman ağrısı gökkuşağı kimin 

Neden dört taraf gözyaşına bulanmış

Ve neden ölüm kokuyor bu şehir? 

Yollar uzadıkça uzadı önümde

Çığlığın geldiği mezarı, bulana kadar! 

Soğuk bir mermere yazmışlar: 

“Bu şehirde yalnız senin ölmüş bir sevdan var! ”', 'Gece oldu mu ok fırlıyor yayından Karanlığı bulutlar ardına saklanmış Bir uğultu kaplıyor  Ateş bir pençe gönlümü dağlıyor  Ne var bu şehird...', ARRAY['Türk Edebiyatı','Şiir','Melike Kordon']::text[], 8.5, '{"poet":"Melike Kordon","poet_slug":"melike-kordon","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mezar-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parsellenmiş Adam', 'parsellenmis-adam-melike-kordon-mxw6y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Girdabında gece bütün karanlıkların

Kasırgası yüreğimde yalnızlıkların

Adın, zehir dilimde

Bir başka kadın yüreğinde

Gözlerin en acısı şarapların

Kokun vuslatı akşamların

Bu geceye, adınla! 

Gözyaşıma, yüreğimdeki kadınla

Hançer vuruyorum! 

Nefesinle dalgalanmışken

Gülüşüne dünyalar adıyorum

Çatlıyor adına andıkça dudaklarım

Ey! 

Busemin alnına gölge yaptığı adam, 

Söyle 

Sensiz bu yangını ben nerde saklarım?', 'Girdabında gece bütün karanlıkların Kasırgası yüreğimde yalnızlıkların Adın, zehir dilimde Bir başka kadın yüreğinde Gözlerin en acısı şarap...', ARRAY['Türk Edebiyatı','Şiir','Melike Kordon']::text[], 8.5, '{"poet":"Melike Kordon","poet_slug":"melike-kordon","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/parsellenmis-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yokken', 'sen-yokken-melike-kordon-d7bf6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soğuk oldu iklimlerin cümlesi, sen yokken 

Ay ışığı sönük yıldızların yanında 

Yıldızlar bir içli keman çaldı yokluğunda 

İnledi nağmeler, sevdan gönlüme çöktü sen yokken

Bir asi başım var, fırtınalar durmuyor

Damlalar usulca süzüldü sokaklarımda 

Bu yürek, kim bilir kaçıncı dolan bacında

Seherler, geceler gibi karanlık, sen yokken 

Ömrümüzün kaç baharı kış oldu bilir misin? 

Kaç zemheri dondu gözyaşım yanaklarımda

Savamadım ben, bu kaçıncı yalan sevda? 

Adam gibi sevmeye hasret kaldım, sen yokken 

Yokluğun acı acı söylediğim dudaklarımda 

Bu yürek sırtını dayamış ayrılıklara 

Bir garip ıslık çalıyor duyuyor musun? 

Şu erik ağacının dallarında

Ağaçlar çiçek açmaz oldu, sen yokken 

Dilim söylemez oldu 

Yüreğim dolu dolu çarpmaz oldu 

Ömrüm viran oldu, sen yokken

Sen yokken ah sen yokken 

Ne acılar dolandı dilime 

Ne günahlar dizildi fikrime 

Gittin ya hani o karanlıklar şehrine 

Kendime gelmedim ben, sen yokken

Kaç zaman geçmiş 

Zaman ayrılıklara süzgeçmiş

Mühürlüyorum sensiz geçen yılları şimdi 

Hepsi nafileymiş 

Ben benden gittim

Ben aklımı firar ettim, sen yokken

Şimdi buruk hasret akşamlarında 

Yokluğun, senden kalan tek hatıra 

Gözlerini, yıldız yaptım karanlıklarıma 

Kaç geceyi sıkarak avucumda erittim, 

                                              Sen yokken.

Kara kışlar boranlar sardı umutlarımı 

Yıldırımlar coşturdu gri bulutlarımı 

Sen kokan hasret bahçelerinde 

Kokladığım kaç gül toprak oldu, sen yokken 

Sessiz bir bahar günündeyim şimdi

Sensiz buruk ömürdeyim şimdi 

Bir gün beyazlara bürünsem bile 

Olmayacaksın biliyorum, şimdiki gibi 

Duvağımda papatyanın dalı, sensiz solacaksa bile

Dünyaları değişmem, doyamadığım gözlerine

Bu gece vakti nerden dolandın dilime

Hasretin var ya 

Zehir zemberek gecelerde 

Yaşarken ölürdü beni, bin kere

Yakamozlardan şarkılar seçtim sana yüzlerce

Sararmış yapraklara hüzün ektim güzlerce 

Ömrüme adadım da gözlerine

Gitmedi gözlerin, gözlerimin önünden, 

                                                    Sen yokken.', 'Soğuk oldu iklimlerin cümlesi, sen yokken  Ay ışığı sönük yıldızların yanında  Yıldızlar bir içli keman çaldı yokluğunda  İnledi nağmeler, s...', ARRAY['Türk Edebiyatı','Şiir','Melike Kordon']::text[], 8.5, '{"poet":"Melike Kordon","poet_slug":"melike-kordon","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/sen-yokken-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tayfa', 'tayfa-melike-kordon-694c1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türküdür, damarlarımda çınlayan kanım 

Kör gecede titriyor, kimsenin bilmediği yanım

Yanıp gidiyor, tütünümde gönlümce

Aynı tutsaklık 

Aynı kasırgalar var ya

Bu şehirde beni sarhoş eden

O garip tütsü var ya

Çaldı gözümün bebeğinden uykuyu

Bu gök duvarlarda selamladım

Karanlığın kıskacındaki kuytuyu

Sızlar durur yüreğimde

Karanlıkla gece sevişince

Bu çözemediğim bilmece

Yılların törpülediği yüreğim

Kelepçelerde, nasıl çözeyim

Yıllarımı yaksam

Anılarımda yanar mı? 

Hatıralardan küller savursam 

Yinede bu yara kanar mı? 

Tütünümün ucundaki köz gibi

Tutkularımı yaksam, 

Gonca gülde mutluluk, dalını kırar mı? 

Tütsüsüyle sarhoş olduğum 

Seherinde berduş olduğum

Kirpiğimde uykuyu çalan

Bu mayhoş gecede var ya

Yüreğimde kanatlanıyor bir kanarya

Bu pusulası kırık teknede

Belki bir gün demir atar bu tayfa

“Bitir” der “dalgalar”

Bu liman son durak

Halatlarıyla beni iskeleye bağlar

Susuzluğumu dudaklarımdan akarak

Deryalar ki dalgalanır yüreğimde

Anılar ki izleri durur hecelerimde

O son iskeleye demir atana kadar

Göz yaşımla deryalar dolana kadar

Kırık dökük tekneyim yüreğimin denizinde

Ay ışığı şahit, bu mührün gizine

Yanıp gidiyor tütünümde gönlümce

Bilmediğim o son iskeleye selam olsun

Azrail den önce teknem, 

                     Dalgalarla kıyıya vursun', 'Türküdür, damarlarımda çınlayan kanım  Kör gecede titriyor, kimsenin bilmediği yanım Yanıp gidiyor, tütünümde gönlümce Aynı tutsaklık  Aynı ...', ARRAY['Türk Edebiyatı','Şiir','Melike Kordon']::text[], 8.5, '{"poet":"Melike Kordon","poet_slug":"melike-kordon","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/tayfa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı', 'yanilgi-abdullah-yuce-7thz4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ruhu çocuk kalmış, 

Görüntüsü yirmili.

Aslen otuzuna merdiven dayamış biri...

Vaktiyle hayal etmiş bir evim olsun.

Sonra param, 

Yok arabam...

Zengin olmak mutlu olmak sanırmış

Çalışmış, 

Ha babam de babam...

Gün gelmiş hepsi olmuş, 

Umduğundan bile çok.

Ama yok, 

Beklediği aşk

Özlediği huzur yok.

Belliki çok yanılmış

Hemde çok...', 'Ruhu çocuk kalmış,  Görüntüsü yirmili. Aslen otuzuna merdiven dayamış biri... Vaktiyle hayal etmiş bir evim olsun. Sonra param,  Yok arabam....', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yüce']::text[], 8.5, '{"poet":"Abdullah Yüce","poet_slug":"abdullah-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanilgi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-melike-kordon-hfejy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızım

Yalnızlığım kalabalığın gürültüleriyle dolu

Bu sonbahar doldurmuş 

                 Karşımda uzayan yolu

Yalnızım

Yalnızlığım esaretimin gardiyanlarıyla dolu

Kelepçelerde berduş gönlümün sızlayan kolu

Bir çırpınış, yüreğimde martı var sanki 

İçimdeki kalleş bir yalnızlığın kini

Ellerim tutuştu, 

Saçımı bile yüzümden, çekemez oldum ben

Vakit 

Hasretlerin vakti

Şehir

Küflü acıların şehri

Ben bu serseri dümene söz geçiremedim ki 

Akıyor iki gözümün şakağından ümitlerim 

Sensiz ne geceyi, ne de gündüzü beklerim 

Bir gün belki olur dileklerim 

Belki de sıcak bir sızıyla kanar bileklerim

Yalnızım 

Soğuk dört yanım

Gök duvarların sessizliğiyle sayıklarım

Varsa bu berduş dünyanın, 

                           Anasını ben satayım.

Bu sarhoş gecelerde

İçtikçe yüreğimde zabdedemediğim denizlerde

Boğuluyorum artık

Dizime kadar geldi sanki kederden bir balçık.

Bu yalancı yıldızların 

Yalancı ışığına da başlarım

Ağrıdan sancıdan kalkmıyor başlarım

Yok artık bu son! 

Bir sana ölürsem

Sanmayın ki, bu lanet hayata yeniden başlarım.

Dişlerim arasında 

Kekre bir acının tadı var.

Dört yanımda yalnız onun gözleri

Ve dilimde adı var.

Bu taşlara mühür olsun gözyaşım

Yangınlarda benim bu garip başım

Sensiz, boğazımdan geçmeyecek aşım!', 'Yalnızım Yalnızlığım kalabalığın gürültüleriyle dolu Bu sonbahar doldurmuş                   Karşımda uzayan yolu Yalnızım Yalnızlığım esare...', ARRAY['Türk Edebiyatı','Şiir','Melike Kordon']::text[], 8.5, '{"poet":"Melike Kordon","poet_slug":"melike-kordon","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yalnizim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-melike-kordon-5ma0c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çözülür mü bilmecesi

                           Bu yürek atışının? 

Amansız vebaya kucak açışımın

Öleceğimi bile bile, içmek aşkının zehrini

Tutar yanı var mı? 

Seni bıçak yarası gibi saplayışımın? 

İki gözümü kan çanağı sandım seninle 

Gündüz gözünü, zifir karalığı sandım

Aşkının dar ağacında asılı kaldım

Ben viran dağının volkanında kaldım 

Bende seni aşktan anlar, adam sandım! 

Çölde serap bildim seni

Çatlak dudaklarımı serabınla ısıttım.

Ben kurak gönlündeki, yalancı seraba kandım.

Böyle bir bahar günü olacakmış demek 

Dudaklarımın yalancı seraba vedası

Yine o taşlı yolda kalacakmış demek 

                   Hasretimin amansız vebası

Deli gönlüm, 

                   Bu şehrin gecelerinde eritti buzul gözlerini

Usulca aktı yaramızdan, 

                 Aşkımızın irini

İstemem artık ne ölünü, ne dirini! 

Bu gece ayrılığın zifaf gecesi

Hayallerim, ak gelinliğim oldu

Zaten sade onlardı beyaz olan

Gözyaşımdan, 

                  Damladı kırmızı kan! 

Deli gönlüm sen bu acıların

                                 Hangisine yan? 

Vakit kuşluk oldu ama

Kuş uçmaz, kervan geçmez oldu gönlümden

Ayrılığın gecesinden sonra

Farkı kalmadı ölümün dirimden

Nasıl kalkacağım ayağımın üstüne yeniden? 

Hiç döner mi sandın, 

Aşkınla ölüme giden

Anladım, 

          Bu yaraya merhem yok ellerinden

Deli gönlüm yeniden başla sen, 

                                   YENİDEN!', 'Çözülür mü bilmecesi                            Bu yürek atışının?  Amansız vebaya kucak açışımın Öleceğimi bile bile, içmek aşkının zehrini...', ARRAY['Türk Edebiyatı','Şiir','Melike Kordon']::text[], 8.5, '{"poet":"Melike Kordon","poet_slug":"melike-kordon","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yeniden-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-ugur-seker-3ca7v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar, 

Bir araya gelmek için deli olurken, 

Şimdi ayrılmanın yollarını arıyorsun.

Biliyorsun sana ne kadar yangın olduğumu, 

Seni ne kadar çok sevdiğimi.

Her seferinde beni aşağılıyor, 

Yavaş yavaş öldürüyorsun.

Kaç defa ayrıldın benden, 

Kaç defa elveda dedin.

Sonra özürler dileyip, 

Sana çok haksızlık ettim, 

Affet beni dedin.

Ben kaç defa senin için

Ölümlerden döndüm.

Ama artık gerçekten, 

Ayrılık vakti geldi gülüm.

Verdiğimiz o sözler, 

Ettiğimiz yeminler, 

Unutuldular şimdi, 

Birer birer.

Artık iki yabancı, 

İki ayrı insan olacağız.

Ne sen benim yarımım, 

Ne ben senin yarımın, 

Değiliz artık.

Git, ardında seni çok seven, 

Yıkılmış bir insan bırakarak.

Ne olur, ayrılığımıza sebep, 

Kaderimizmiş deme.

Git artık, 

Mutluluk umduğun, 

Ve kendine Yeni bir yarım bulacağın

Yadellere.

Ben seni bekleyeceğim, 

Son nefesimi verene kadar.

Birgün dönmek istersen bana, 

Ve bıraktığın yerlerde bulamazsan eğer, 

Mahşerde ara beni GÜLÜM...

01.05.2002', 'Bir zamanlar,  Bir araya gelmek için deli olurken,  Şimdi ayrılmanın yollarını arıyorsun. Biliyorsun sana ne kadar yangın olduğumu,  Seni ne...', ARRAY['Türk Edebiyatı','Şiir','Uğur Şeker']::text[], 8.5, '{"poet":"Uğur Şeker","poet_slug":"ugur-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gulum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Olmasaydı', 'ya-olmasaydi-ersan-yaraskan-rvyah', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ya olmasaydı hava gerçek 

Yıllardır neyi koklayacaktık

Ya olmasaydı mavi gökyüzü

Kime anlatacaktık göz yaşlarımızı.

Ya olmasaydı güzel

Kötüyü kim anlayacaktı

Ya olmasaydı kağıt

Kalem olacak mıydı

Olmasaydı gözler

Nasıl görünürdü hayatın renkleri

Mavisi, yeşili, çamuru

Ya olmasaydı

İnsanlar anlar mı üzüldüğümü

Görmeseler göz yaşlarımın düştüğünü

Yada duyabililer mi konuşmasam

Gelir mi son nefes

Hiç nefes almasam bile

Bulabilir misiniz

Yeşilin para 

Mavinin duman

Çamurun ise doğanın bıraktığı son armağan olduğunu

Görebilir misiniz

İçmeden sarhoş olanları

Yemeden doyanları

Yaşamadan ölenleri

Duyabilir misiniz 

Bağıran gözlerin şarkılarını

Kimi aşk söyler, kimi hicran

Kimi boş söyler, kimi isyan

Yalan olmasaydı

Nasıl korunurdu büyük aşklar

Çıplaklık olmasaydı 

Nasıl bağlanırdı

Sevgi dediğiniz iplikle mi

Ya ben, ben olsaydım

Bana da bir iplik verir miydiniz

Ya ben olmasaydım...', 'Ya olmasaydı hava gerçek  Yıllardır neyi koklayacaktık Ya olmasaydı mavi gökyüzü Kime anlatacaktık göz yaşlarımızı. Ya olmasaydı güzel Kötüy...', ARRAY['Türk Edebiyatı','Şiir','Ersan Yaraskan']::text[], 8.5, '{"poet":"Ersan Yaraskan","poet_slug":"ersan-yaraskan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ya-olmasaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-oguzkan-bolukbasi-cs9g3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani rüyalarımızın heryerinde mutluluk vardı

Soğanı kırıp cücüğünü yiyen dağdaki çoban gibi

İçim ürperdi, yüreğim kıpır kıpır gözlerim yandı

Günbatımlarını seyrederken saçların yaktı mağribi

Hani elimi uzattığımda yanımdaki sen miydin

Yoksa yıllara hüzün katan acı bir sitem miydin

Yaprak rengi gözlerinle uçuşup giden miydin

Gel artık gel bekletme göründü hayatın, denizin dibi

Hani sessizliğin karanlık korkularını yenmiştik

Sevgiyi sevgiyle besleyip biz herşeye direnmiştik

Bilir misin tutulmayacak ne yeminler vermiştik

Aşktır inan bana bedenin ve evrenin sahibi

Hani bir dünya sabahında ekmeği bölüşmüştük

Martıları besleyip neşeyle gülüşmüştük

Kaçamak bakışlarla birkaç kez öpüşmüştük

Sanırdık yalnız bizdik mutluluğun talibi

Hani benimle uyanırdın yeniyetmelik gündüzlerine

Içinde bir sıcaklık yüzünde bir duayla gökyüzlerine

Zaman hoyratça süzülürken ömrümün güzlerine

Anılar alır götürür geri getirmez bu garibi', 'Hani rüyalarımızın heryerinde mutluluk vardı Soğanı kırıp cücüğünü yiyen dağdaki çoban gibi İçim ürperdi, yüreğim kıpır kıpır gözlerim yandı...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hani-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Aşklar Ki', 'o-asklar-ki-oguzkan-bolukbasi-ixuzb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deniz dedim, gök dedim

Mavi heyecanlarda sürüklendim durmaksızın

Sen hep uzak limanlardaydın, erişilmez

Seni göre göre, seni seve seve, seni ölesiye özledim

Şimdi o aşkları arıyorum, o aşkları tek başına yaşanan

Bir sır gibi yüreğin içlerinde saklanan

Gözgöze gelmelerde manalar aradığımız

O aşklar ki

Binlerce günbatımı geçse de üzerinden

Anmaya doyamadığımız

Unutmaya kıyamadığımız', 'Deniz dedim, gök dedim Mavi heyecanlarda sürüklendim durmaksızın Sen hep uzak limanlardaydın, erişilmez Seni göre göre, seni seve seve, seni...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/o-asklar-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isırgan Çiçeklerinden Hicivler', 'isirgan-ciceklerinden-hicivler-abdullah-oztemiz-n0n0c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sudan ne bilir Hartum''a dair

Issız çöle, kızgın kuma dair

Biz samyeli estirdik ufukta

Çok şey biliriz hortuma dair.

         *               *                *

Derviş ödül bırakmaz

Kırgın gönül bırakmaz

Bir kez tozuttu muydu

Mangalda kül bırakmaz.

       *              *             *

Uyanık çok hükumetin bizde

Bir saat sonra uykusu geldi

Gidenin icraatı yolsuzdu

Yolsuzu gitti YOLLUSU geldi.

      *             *              *', 'Sudan ne bilir Hartum''a dair Issız çöle, kızgın kuma dair Biz samyeli estirdik ufukta Çok şey biliriz hortuma dair.          *              ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztemiz']::text[], 8.5, '{"poet":"Abdullah Öztemiz","poet_slug":"abdullah-oztemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/isirgan-ciceklerinden-hicivler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicivler', 'hicivler-abdullah-oztemiz-llt6h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalemin laçka yazdığın laçka

Şişli katlansa gözyumar Maçka

Bunca yıldır yazıp çizip durdun

Ne çıkardın geğirtiden başka

     *        *         *

Çok kafiri ettim ehli iman

Hicvim ile eyleyip perişan

Nef ''i si benim bu çağda hicvin

Kimdeyse mühür odur Süleyman.

     *        *           *

Dün hicvime sıçrayan bu çirkef

Hicvimle bugün olur müşerref

Nüktemle bekada zevk ederler

Nef ''i, Neyzen, Süruri, Eşref.

      *         *           *

Yaşar üç beş kuruş alınca para 

Sayısız kurt üşüştü bir kaşara

O kadar çok şişirdiler ki öğüp

İnce Mehmet kalın gelir Yaşara.

      *           *             *     

Güç bulursun yitirdiğin umudu

Sence yok bilginin kayıt kuyudu

Yeniden yazdığın UYARMALAR'' ı

Okuyanlar horul horul uyudu.

Abdullah Öztemiz Hacıtahiroğlu.

(Hicivlerinden birkaç örnek.)', 'Kalemin laçka yazdığın laçka Şişli katlansa gözyumar Maçka Bunca yıldır yazıp çizip durdun Ne çıkardın geğirtiden başka      *        *     ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztemiz']::text[], 8.5, '{"poet":"Abdullah Öztemiz","poet_slug":"abdullah-oztemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hicivler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararım Seni', 'ararim-seni-ahmet-selcuk-i-lkan-aamj1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akşam erken çöker yalnızlığıma

Sokak sokak gezer ararım seni

Hasretin gönlümün yangınlarında

Alev alev yanar ararım seni

Gözyaşlarım kurur yanaklarımda

Hüzünlü bir ıslık dudaklarımda

Sigaram sabahlar parmaklarımda

Nefes nefes çeker ararım seni

Gölgen düşer sanki hep yollarıma

Adım adım yürür izlerim seni

Bir çılgın özleyiş girer kanıma

Yudum yudum içer ararım seni...', 'Akşam erken çöker yalnızlığıma Sokak sokak gezer ararım seni Hasretin gönlümün yangınlarında Alev alev yanar ararım seni Gözyaşlarım kurur y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ararim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-erkan-kavas-efzat', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne olur bir dakika bekle, 

Hani eskiden coca-cola kapaklarını, 

Biriktiridim ya, 

Şimdi de sensiz geçen günleri, 

Biriktiriyorum...', 'Ne olur bir dakika bekle,  Hani eskiden coca-cola kapaklarını,  Biriktiridim ya,  Şimdi de sensiz geçen günleri,  Biriktiriyorum......', ARRAY['Türk Edebiyatı','Şiir','Erkan Kavas']::text[], 8.5, '{"poet":"Erkan Kavas","poet_slug":"erkan-kavas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ne-olur-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim', 'i-sterdim-nevzat-gurmen-23tz2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seninle şu yağmuru dinlemek isterdim

yerdeki toprak kokusunu hissetmeyi

ıslak yapraktan suyun düşmesini

uzaktaki tekerleğin suda çıkardığı sesi

omuzuma yaslandığında soluğunu 

ağlamanı dinlemek isterdim

ben sessiz otururken

saatlerce konuşmanı, konuşmanı

arada dönüp bana bakmanı isterdim

söylediğim türküyü dinlemeni

duygulandığını görmeyi

ellerinle dudaklarımı kapatmanı

bilmiyorum ki

çok şey mi istediğim', 'seninle şu yağmuru dinlemek isterdim yerdeki toprak kokusunu hissetmeyi ıslak yapraktan suyun düşmesini uzaktaki tekerleğin suda çıkardığı s...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isterdim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiran-ı Mesdud', 'siran-i-mesdud-yusuf-pangal-yxa1b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seyyiâtın seyfine şikâr olunduk, 

Tâb''a şikest olmuş şirânız biz.

Silahımız sindir bizim bilmeyiz târiz; 

Reng-i sayyâd ile giriftâr olunduk.', 'Seyyiâtın seyfine şikâr olunduk,  Tâb''a şikest olmuş şirânız biz. Silahımız sindir bizim bilmeyiz târiz;  Reng-i sayyâd ile giriftâr olunduk...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siran-i-mesdud-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-mehmet-ali-cibikli-gj977', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün anneler günü, 

Bak sensizim ben yine.

Çok özlüyorum dünü, 

Nerelerdesin anne? ...

Bir küçücük bebektim, 

Tutardın ellerimden.

Nereden bilecektim? 

Ne anlardım sevmekten? 

Kalbime aşıladın, 

İnsanları  sevmeyi.

Kötülüğü dışladın, 

Sevmedin kötüleri.

Kötüyü ve iyiyi, 

Hepsini sen öğrettin.

Mutsuzluğu, sevgiyi, 

Yaşamı sen sevdirdin.

Gece gündüz demeden, 

Kucağında büyüttün.

Saçlarımı okşarken, 

Dizlerinde uyuttun.

Kalbinin köşesinde, 

Sonsuz sevgiler yaşar.

Ne ararsam hep sende, 

Ne varsa hep sende var.

Sensiz yaşamak haram, 

Sensiz olmadı yine.

İşte kanıyor yaram, 

Seni özledim anne.

Al beni kollarına, 

Kalbim sevinçle dolsun.

Beni tekrar kucakla, 

Benim bayramım olsun.

Bugün anneler günü, 

İçim buruk, perişan...

Sen ferah tut gönlünü, 

Seni sevdim her zaman...', 'Bugün anneler günü,  Bak sensizim ben yine. Çok özlüyorum dünü,  Nerelerdesin anne? ... Bir küçücük bebektim,  Tutardın ellerimden. Nereden ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/anne-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-ahmet-hani-xwss6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senden sora dağlar mene qaldı, 

Dağlar boyu dağlar mene qaldı, 

Gözler – iki ağlar- mene qaldı, 

Sölmüş sarı bağlar mene qaldı.

Köçdi bahar efsus xezan oldu, 

Gündüz, gece ya her zaman oldu, 

Bülbül kimi sehmim feğan oldu.

Senden sora dağlar mene qaldı, 

Gözler – iki ağlar – mene qaldı.

Tebriz - 8 september 2000', 'Senden sora dağlar mene qaldı,  Dağlar boyu dağlar mene qaldı,  Gözler – iki ağlar- mene qaldı,  Sölmüş sarı bağlar mene qaldı. Köçdi bahar ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ana-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayı', 'sayi-ceyhun-yilmaz-y47ls', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her doğum günümde 

bir yıllık hüzün aklıma gelir.

her aşkta ayrılık kesin

sevmedim hiç sayıları, rakamlara ağladım.

baban öldü dediler

on''dan geriye ilk defa saydım.', 'her doğum günümde  bir yıllık hüzün aklıma gelir. her aşkta ayrılık kesin sevmedim hiç sayıları, rakamlara ağladım. baban öldü dediler on''da...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-i-smail-kadare-xlurg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birkaç damla yağmur cama düştü, 

Ve ben, ben özledim seni

İkimiz de aynı şehirde yaşıyoruz, 

Nadir görüşüyoruz...çok nadir.

Ve bana çok garip geldi, çok.

Nasıl çatıp geldi bu sonbahar, bu sabah! 

Kapanmış göklerde leylekler yok, 

Gökkuşağı yoktur yağmurlar arasında.

Ve Heraklitos''den o eski mısra, 

Bugün aklıma geldi, lanet olsun! 

''Yaşayanlar beraberdir dünyada, 

Ölüler ise  ayrı durur...''

Hangi rüyaya daldık böyle kötü, 

Ve kalkamıyoruz  şimdi? ! 

Birkaç damla yağmur cama düştü, 

Ve ben...ben özledim seni...

Türkçesi Alban Tartari', 'Birkaç damla yağmur cama düştü,  Ve ben, ben özledim seni İkimiz de aynı şehirde yaşıyoruz,  Nadir görüşüyoruz...çok nadir. Ve bana çok gari...', ARRAY['Türk Edebiyatı','Şiir','İsmail Kadare']::text[], 8.5, '{"poet":"İsmail Kadare","poet_slug":"i-smail-kadare","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozlem-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustos', 'agustos-ceyhun-yilmaz-5043b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'garip bir ağustos tadı damaklarımda

hiç yaz gibi değil bu mevsim

yaz ben gibi değil..

ya ağustoslar bozuldu..

ya da ağzımın tadı', 'garip bir ağustos tadı damaklarımda hiç yaz gibi değil bu mevsim yaz ben gibi değil.. ya ağustoslar bozuldu.. ya da ağzımın tadı...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/agustos-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adres', 'adres-ceyhun-yilmaz-9rmm3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'arkamı döndüğümde yüzüme geç

kaçarken tut beni

yorma kendini beni tanımak için

beni sorma sevgisiz sokağın sakinlerine

bilmezler içine atılarak büyütülen kayıp aşıkların adreslerini', 'arkamı döndüğümde yüzüme geç kaçarken tut beni yorma kendini beni tanımak için beni sorma sevgisiz sokağın sakinlerine bilmezler içine atıla...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/adres-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay', 'cay-ceyhun-yilmaz-wv9yq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sabah kalkınca

beni anlamayışının iğneli yalnızlığı

geldi aklıma

hazır hüznüme harmanladım onu

bak

şiir oldu sana', 'sabah kalkınca beni anlamayışının iğneli yalnızlığı geldi aklıma hazır hüznüme harmanladım onu bak şiir oldu sana...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cay-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessüm', 'tebessum-ceyhun-yilmaz-awys6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'en mutlu anlarımda

bir dert içimde

gülsem kahkaham sırıtır tebessümlerin içinde

anlatsam derdimi anlatamam ki..

herkesin güldüğünü bilmek kolay ama

kimsenin ıslanmadı ki gözleri benim kadar', 'en mutlu anlarımda bir dert içimde gülsem kahkaham sırıtır tebessümlerin içinde anlatsam derdimi anlatamam ki.. herkesin güldüğünü bilmek ko...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tebessum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahçup', 'mahcup-ceyhun-yilmaz-pv634', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'adımın bazı kağıtlarda

adının altına yazılması bile artık beni

mutlu ediyorsa

bu benim utancım değil', 'adımın bazı kağıtlarda adının altına yazılması bile artık beni mutlu ediyorsa bu benim utancım değil...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mahcup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokuş', 'yokus-ceyhun-yilmaz-eo7m7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'saçlarından ödünç ver

dört bahar geçti

çiçek kokusu öpmedim

çok oldu mutluluktan vazgeçeli...

gülüşünden ver

ömrümden al', 'saçlarından ödünç ver dört bahar geçti çiçek kokusu öpmedim çok oldu mutluluktan vazgeçeli... gülüşünden ver ömrümden al...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yokus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaklaş', 'yaklas-ceyhun-yilmaz-cxdg5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her yeni aşkta kandırdın beni gönül

hepsi güneş kadar sıcaktı ama

hiçbiri yoktu yanımda geceleri

acı bana artık gönül

ben vazgeçtim sevmekten...

biraz da sen üzül', 'her yeni aşkta kandırdın beni gönül hepsi güneş kadar sıcaktı ama hiçbiri yoktu yanımda geceleri acı bana artık gönül ben vazgeçtim sevmekte...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yaklas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Pantolon', 'kisa-pantolon-ceyhun-yilmaz-clgsi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'korkma artık küçük çocuk

kimse üzemez seni

sen hüznü öpmedikçe

kimse gelemez sana

sen birilerinden gitmedikçe

korkma artık küçük çocuk

büyümezsin zannederdin

bak

büyüdün işte', 'korkma artık küçük çocuk kimse üzemez seni sen hüznü öpmedikçe kimse gelemez sana sen birilerinden gitmedikçe korkma artık küçük çocuk büyüm...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kisa-pantolon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamallık', 'hamallik-cihan-derebeyli-8dpro', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu dünya hamallık, 

Doğumum anama, 

Yaşamam bana

Aşkım sana, 

Ölümüm cenazemi taşıyanlara...', 'Bu dünya hamallık,  Doğumum anama,  Yaşamam bana Aşkım sana,  Ölümüm cenazemi taşıyanlara......', ARRAY['Türk Edebiyatı','Şiir','Cihan Derebeyli']::text[], 8.5, '{"poet":"Cihan Derebeyli","poet_slug":"cihan-derebeyli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hamallik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet', 'evet-deger-ulas-turan-ho1z1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu kaçak yıllar içinde, 

Acıtan başka ne kaldı diye 

Geçmişi yoklayıp durduk. 

Kimi zaman başka düşlerin, 

İçsiz haykırışını taşıdık. 

Diyorsun ya; 

Bu zaman dinlendiğim, 

Ayrılışlarıdır, 

Solup gitmedikten sonra, 

Senin olduğun her yer, 

Bir yokluk manifestosu gibi... 

Ne tarafta bıraktık? 

Kaçırdığımız otobüs seferlerini 

Ve nasıl oluyor da, 

Her şeye aynı gülemiyoruz... 

Şimdi dinlemediğim şarkıları, 

Başa alıyorum... 

Okumadığım kitapları aralıyorum... 

Yoksul çocukları daha çok özlüyorum... 

Gece aceleydi seninle, 

Gün tenhaydı ki 

Her bakıp çevirdiğin, 

Bir caddenin sıcak yalnızlığı 

Ve içinden gecen hep sen... 

Geç kaldık seninle, 

Erken ayrıldık çocukluğumuzdan... 

Çocuk... 

Ellerini ver hadi, 

Gülebildiğim gerçek sende... 

Çocuk, 

Gülüyorsam eğer, 

Bu kentte değilim... 

Ağlıyorsan sende geçmişe, 

Ellerini ver hadi, 

Yakarışlarını dindir... 

Artık büyüdün sende, 

Karanlıktan korkmuyorsan eğer; 

Kötü adamları anlıyorsan artık, 

Büyüdün yokluk içinde. 

Büyüdün, 

Var olarak...', 'Bu kaçak yıllar içinde,  Acıtan başka ne kaldı diye  Geçmişi yoklayıp durduk.  Kimi zaman başka düşlerin,  İçsiz haykırışını taşıdık.  Diyor...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/evet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostun Adı', 'dostun-adi-bayram-karaali-tsga6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nede çok kolay kandırılırdım çocukluğumda, 

Hep kızardım fırlatır atardım kendimi sokak ortalarına, 

Anlardım büyükleri, anlardım küçükleri, anlardım kandıranları, 

Gider koşardım yorgan altı ağlamalarıma yalnız ve mutlu... 

Beni ben anlamıştı, içimdeki ben içimdeki ihtiyar... 

Çocuktum, yalnızdım, anlamazdım, kapımdaki söğüt ağacı, 

Tırnaklarımı yemedim ben, yüzümde asık olmadı, güleçtim, 

Yorganına  sorun çocukluğumun...Yalnızdım... 

Ben; içimdeki benle yalnız kavgalı kardeş bazen serkeş, 

Git başımdan be adam içimde ben olan ben, sen bile yoktun, 

Kavgada geldin, tetik çekmemde elimdin, 

Sevdamda hüzün, aşkımda kavgacı, İhanettin... 

İçimdeki ben; yalnızdın kavgada, aşkta, sevdada, 

Tomurcuğun güleç yüzlere merhaba deyişinde, 

Sabaha şafak kurşununu indirirken, gelincik güleçliği, 

Ağır bir dosttun, adın YALNIZLIKTI...

Bayram KARAALİ

10.04.2002', 'Nede çok kolay kandırılırdım çocukluğumda,  Hep kızardım fırlatır atardım kendimi sokak ortalarına,  Anlardım büyükleri, anlardım küçükleri,...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dostun-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur, İstanbul Ve Sen', 'yagmur-i-stanbul-ve-sen-fahrettin-ozdemir-eecx2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eminönünde dolaştım dün

Gök delinmiş gibi yağmur yağıyordu

İskelede yürüdüm biraz.

Satıcılar bağrışıyordu her tarafta, 

Oraya buraya koşuşturan insanlar vardı.

Yağmurdan kaçıyordu kimisi..

Ben kaçmadım; 

Islandım doya sıya

Ve seni düşündüm.

Ömre bedel gülüşün geldi aklıma.

Ben de gülümsedim.

İnsanlar merak etti, 

Durup duruken neden güldüğümü; 

Yağmur, İstanbul ve sen, 

Daha keyifli ne olabilirdi ki?', 'Eminönünde dolaştım dün Gök delinmiş gibi yağmur yağıyordu İskelede yürüdüm biraz. Satıcılar bağrışıyordu her tarafta,  Oraya buraya koşuştu...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Özdemir']::text[], 8.5, '{"poet":"Fahrettin Özdemir","poet_slug":"fahrettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yagmur-istanbul-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bulduğum Yer', 'seni-buldugum-yer-fahrettin-ozdemir-vd33w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben, bu her tarafından, 

Yalnızlık fışkıran, 

Bir aralık gecesi, 

Küçük bir kar tanesinin, 

Gözbebeklerinde titreyen

Gecelerde buldum seni.', 'Ben, bu her tarafından,  Yalnızlık fışkıran,  Bir aralık gecesi,  Küçük bir kar tanesinin,  Gözbebeklerinde titreyen Gecelerde buldum seni....', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Özdemir']::text[], 8.5, '{"poet":"Fahrettin Özdemir","poet_slug":"fahrettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-buldugum-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni', 'bekle-beni-suna-gunes-nsp5h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her zaman bekledin beni

gündolsun dünyaya gelsin diye

gözünü acıp gülsün diye

dişleri görünsün diye

sacları tarasın diye

büyüsün yürüsün diye

hayata hazırlansın diye

hayatı güzel yaşasın diye

giderkende sessiz gittin

habersiz ağlamasın diye

şimdi orada bekliyorsun

bir gün kollarına gelecek diye

hangi anne bu beklemekten vaz geçer

bırakıp gider geleceğini bilemese', 'her zaman bekledin beni gündolsun dünyaya gelsin diye gözünü acıp gülsün diye dişleri görünsün diye sacları tarasın diye büyüsün yürüsün diy...', ARRAY['Türk Edebiyatı','Şiir','Suna Güneş']::text[], 8.5, '{"poet":"Suna Güneş","poet_slug":"suna-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bekle-beni-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Yılllarım', 'yorgun-yilllarim-ugur-oguz-sahin-8e9zw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anıların gölgesinde yıllar var

Yaşadığımız bir sürü günahlar sevaplar

Hayatın olgunluğunda değerlenir anlamlar

Ancak o zaman unutulur kötü hatıralar

Ne yapalım kaderi yazmak elimizde değil ki

Anlamı yok ulaşamadığımız değerlerin

Kanunu mu var sevmenin sevilmenin

Tarifini hangimiz yapabildik kaybettiklerimizin

Akan bir nehir misali bakmadık mı ardından gidenlerin

Şerefe şerefe deyip sonunda kim bilir kaç kapağını açtık kaç şişenin.', 'Anıların gölgesinde yıllar var Yaşadığımız bir sürü günahlar sevaplar Hayatın olgunluğunda değerlenir anlamlar Ancak o zaman unutulur kötü h...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yorgun-yilllarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muradına Erdin mi', 'muradina-erdin-mi-ugur-oguz-sahin-lzsce', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlamadın beni sıradan sevmek değildi benimki

Yağmur akşamlarında damlalar bestelerdi güftemi

Hüzünle boşalırken gökyüzü yaşarken hayalini

Anlamadım bir veda bile etmeden çekip gidişini

Nasırlaşmış halkalara sen de ekledin bir yenisini

Akşamlar mavi gecelerde buluşur yıldızlarla 

Kayıp giden yıldızlar gibi gömdüm seni bağrıma

Tut dedim ellerimi yerimiz olsun bu gönül dağında

Anlamadın beni anlamadın duygularımı ne çaba sarf ettin ki

Şimdi şarkılar hüzünlendi hatıralar sitemli muradına erdin mi', 'Anlamadın beni sıradan sevmek değildi benimki Yağmur akşamlarında damlalar bestelerdi güftemi Hüzünle boşalırken gökyüzü yaşarken hayalini A...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/muradina-erdin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'canim-babam', 'canim-babam-ugur-oguz-sahin-6ikm6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Selâmünaleyküm

Baba ben geldim oğlun Uğur Oğuz

Nasılsın iyimisin

Yanındayım babacığım

Yanı başında baş ucunda

Bak torunlarını getirdim

Oğuz Enes de yanımda

Baba ne olur konuşsana her zamanki gibi

Beni karşına oturtup konuştuğun gibi

Duyarlar diye mi çekiniyorsun

Bak hiç kimseler yok burada

Hiç olmazsa bir şeyler fısılda

Küstün mü yoksa bana

Hâlâ derslerime çalışmayıp

Yine gazozuna maçtan

Geldiğimi mi sanıyorsun

Heyhat baba

Üsküdar bitti

Çok istedim ama futbolcu olamadım

Senden sonra söndü hayalim suya düştü

Olurlarsa şimdi umudum torunların

Baba sen bizi bıraktığın günden sonra

Oğlun o çok istediğin sanat okulunu bitirdi

Diplomamı çok görmek istemiştin

Bir de sanatkâr diplomam var baba

Ama sana görmek nasip olmadı

Zaten şu anda üniversite diplomaları da

Bir işe yaramıyor baba

Baba canım babacığım doyamadım sana

Hasretliğini gideriyorum hep

Toprakta uzanan o canım boylarında

Enes üzerini örten çimenleri koparıyor

Çocuk aklı ya dedemin üzerini örtmüşler diyor

Oğuz dokuz yaşında buruk bir şekilde seyrediyor seni

Aynı sen hayata gözlerini kapatıp giderken

O zaman amcası gibi şimdi o''da aynı yaşta

Baba en sonunda dileğin oldu ya

Kavuştun annene o''da yanı başında

Dünyada en sevdiğin varlıkla

O tonton babaannemle yan yana

Baba...bugün babalar günü

Alacağın olsun yine göstermedin kendini ya

Dokuz denizlere baş vurup bir gün görmeyen baba

Şimdi sormaya hazırlanacaksın biliyorum

Artık sorma harçlığın var mı diye

Var baba her şeyim var

Çok şükür kimseye muhtaç değilim

Mevla''m çorbamızı tüttürüyor

Daha ne olsun ki

Ha baba sana hediye alıp gelmedim

Ama sen hiç hediye istemezdin ki

Aslında karşıydın da böyle günlere

Onun için hediye alıp gelmedim sana baba

İki tane aslanım yavru aslanlarını

Torunlarını getirdim sana

İkisi de yakışıklı mı yakışıklı

Şimdiden kızlar göz kırpıyor onlara

Baba ama bu kadar yeter hadi baba

Ne olur bir şeyler fısıldasana

Tam yirmi beş sene geçti duymadım özledim

Ah bir derinden de gelse duysam bir kelamını

Hâlâ ne sesin çıkıyor ne de soluğun

Ha unutmadan baba

Fenerbahçe şampiyon oldu bu sene

Torunlarının ikisi de Fenerbahçe''li doğdu

Gol gol diye bağırıp ellerinde bayrak sallıyorlar şimdi

Baba sen bırakıp gittiğinden beri bizi

Her şey çok zordu toz pembe değildi

Çok zorda kaldık çok yokta

Hani giderken de çok şükür ki maaşın kalmıştı

Ya o da olmasaydı ne yapardık biz

Yattığın yerler nur mekânın Cennet olsun baba

Hatırlıyor musun bir gün yine konuşuyorduk

Bak oğlum helal lokma yedirdim size demiştin

Ancak kıt kanaat geçindirmeye çalıştım sizi

Dünya malım yok size bırakacak

Hiç bir şeyim olmadı demiştin

Sizlere en büyük miras helal bir onur bıraktım

Baba ah benim canım babam

Sen rahat uyu kabrinde rahat ol

Milletin çocukları bırakılan mirasları yedi bitirdi

Bir görsen şimdi yağmalıyorlar memleketi

Ama senin bıraktığın helal onurunun üzerine

Hiç kuşkun olmasın hep helal onur eklendi

Senin yaptığın gibi çocuklarında haramı elleriyle geri itti

Ve helal lokmayla yaşamaya devam etti

Baba hayatımızda hiç bir şey değişmedi

Hâlâ aynı semtteyiz yaşantımız yine mütevazı

Servetimi soracak olursan

Hani sen herkes sorunca söylediğin gibi

Öğrettiğin o tekerleme her seferinde yine aynı

Çorbamız kaynıyor başımıza yağmıyor

Elhamdülillah vücudumuzda sıhhatte

Bunların üçünün yanında Dünya serveti ne ki

Baba öyle değil mi canım babacığım

Hiç bir şey eksilmedi her şey senin öğrettiğin gibi

Evet babacığım galiba elveda vakti

Hadi gülümse canım babam ben göremem ama

Torunların belki hisseder belki görür seni

Allahaısmarladık babaanne Allahaısmarladık baba

Canım babacığım

Yalnız kalacağız diye sakın üzülmeyin

Hiç yalnız değilsiniz hep bizimlesiniz

Hep torunlarınızın dilindesiniz

Toprağın koynunda olsanız da

Hep gecemde gündüzümde

Hep gözlerimi kapatınca uykumda

Dünyadaki tüm sevgiler bir yana sen bir yana

Bir tanem aşkım her şeyim yaşama varlığım

Yaşatanım sensin sensin baba...', 'Selâmünaleyküm Baba ben geldim oğlun Uğur Oğuz Nasılsın iyimisin Yanındayım babacığım Yanı başında baş ucunda Bak torunlarını getirdim Oğuz ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":110,"source_url":"https://www.antoloji.com/canim-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlerden Bir Gün', 'gunlerden-bir-gun-huseyin-cayikli-gn5yr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kacgundur uyku girmiyor gozlerime 

dostlar geliyor acil durumlarda 

bana goz kulak oluyorlar.

icimdeki enkazi kaldirmaya calisiyorlar.

sacma sapan oluyor gokyuzu

dun aksam denizi gorecektin cok guzeldi

bir mavi ki hic sorma turkuaz vardi 

yakamozu gorseydin

ben gordum yine sarhos oldum.

okul hayatimda rezalet denilecek kadar kotu

ailesel problemler icimde ki sikinti birazda maddiyat.

bu aralar nedensiz uyaniyorum terleyerek

belkide havalardandir.

belkide sendedir

nerden bilersin

deprem gibi hayat ve enkazi kaldi

ben ve arkadaslarin yardimiyla kaldirmaya caliyoruz

silemiyoruz izlerini.

ne yapalim icimiz buruk biraz yalnizlik

birde sensizlik var...

kac gecedir ruyama girmiyorsun hayret ediyorum

bu kadar nefret etmene gerek yok...

arada sirada ugra ruyalarima

merak etme kotu soz soyleyemem orada arkadaslarda gelmez.

sen ve ben..

biliyormusun yaz geldi cayir cimen yollarda yuruyoruz.

bu demekki ayrilik 

bu demekki gunesimiz yok artik

hayatimiz duzene girdi...

diyecegim ama diyemiyorum

rum radyolari gece efkarli caliyor

birde aci keman sesi yokmu 

herneyse canini siktim

benden bu kadar birazda sen anlat 

ben uyuyacagim ruyama gel beklerim...', 'kacgundur uyku girmiyor gozlerime  dostlar geliyor acil durumlarda  bana goz kulak oluyorlar. icimdeki enkazi kaldirmaya calisiyorlar. sacma...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gunlerden-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nevruz''a', 'nevruz-a-mehmet-akif-ersoy-3k88h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İhtiyar amcanı dinler misin, oğlum, Nevruz? 

Ne büyük söyle, ne çok söyle; yiğit işde gerek.

Lafı bol, karnı geniş soyları taklid etme; 

Sözü sağlam, özü sağlam, adam ol, ırkına çek.

Hilvan, 15 Teşrînisânî 1348

(15 Kasım 1932)', 'İhtiyar amcanı dinler misin, oğlum, Nevruz?  Ne büyük söyle, ne çok söyle; yiğit işde gerek. Lafı bol, karnı geniş soyları taklid etme;  Söz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nevruz-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Kuşum', 'gece-kusum-ercan-karakas-mld4h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'E, n zor anında karşıma çıkttın 

R, enk  saçtın hayatıma yaşamıma 

C.an verdin şu cansız bedenime 

A, şık oldum delice tutuldum ben sana 

N, e olur sende bırakma son verme hayatıma yaşamıma', 'E, n zor anında karşıma çıkttın  R, enk  saçtın hayatıma yaşamıma  C.an verdin şu cansız bedenime  A, şık oldum delice tutuldum ben sana  N,...', ARRAY['Türk Edebiyatı','Şiir','Ercan Karakaş']::text[], 8.5, '{"poet":"Ercan Karakaş","poet_slug":"ercan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gece-kusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız', 'yildiz-gamze-yildirim-pu37q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatımdan her kopup gidene, 

bir de umutlarıma, 

bir yıldız tuttum, 

kendimce…

İçinde bir sürü rağmen olan, 

Garip, 

adı konmayan bir masalın, 

hüzünlü anlatımının siyahlığında, 

gülümseyen bir yıldızdın, 

mavice…

Özledim, döndüm yüzümü göğe.

Kah haykırdım, kah fısıldadım.

Dertleşip, söyleştikçe

Korkup, saklandın ürkekçe, 

Siyaha, simsiyaha kesti gökyüzü

Ne mavi, ne yıldız kaldı, 

Mevsim kara mı ne? 

Kalbim tekledi, çaresizliğim üşüştü yine, 

Avuçlarımdaki özlemi, 

Ağaran şakaklarıma bastırdım, 

ıslak bir ağrı oldun birden bire, 

kopup gittin gizlice, 

Canım yandı 

yüreğime batan yıldız

pek sivrice…

Bir yıldız söndü, 

Bir ben ağladım 

sessizce...', 'Hayatımdan her kopup gidene,  bir de umutlarıma,  bir yıldız tuttum,  kendimce… İçinde bir sürü rağmen olan,  Garip,  adı konmayan bir masal...', ARRAY['Türk Edebiyatı','Şiir','Gamze Yıldırım']::text[], 8.5, '{"poet":"Gamze Yıldırım","poet_slug":"gamze-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yildiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanemsin', 'birtanemsin-metin-usengec-5sqnr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasretinle yanıyor

Sevgine doyamıyorum

Çok kocaman özlüyor

Dünyalar kadar seviyorum..

Kasım-2001

Aylar Geçse de Yıllar Geçse de Bir Ömür Böyle Geçse de Ben Seni Unutamam..', 'Hasretinle yanıyor Sevgine doyamıyorum Çok kocaman özlüyor Dünyalar kadar seviyorum.. Kasım-2001 Aylar Geçse de Yıllar Geçse de Bir Ömür Böy...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/birtanemsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-metin-usengec-k4mot', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz Dünyam Bomboş Birtanem

Gecelerim Uzun Karanlık

Gündüzlerim Özlemle Dolu

Sensiz Dünyam Anlamsız Birtanem

Bir Elmanın Yarısı Sıradan Bayağı

Nefessiz Güneşsiz Değersiz

Sensiz Kalbim Bomboş Birtanem

Ne Varlığı Belli Ne Yokluğu

Sahipsiz Sevgisiz Sensiz

Kalbim Sana Sevgiyle Dolu Birtanem

Sığmıyor Sevgin Yüreğime

Bugünde,Yarında,Gelecekte..

29-Aralık-2001/05:30

Söyle Yar Beni Unuttun mu; Kopardın mı Yüreğinden..', 'Sensiz Dünyam Bomboş Birtanem Gecelerim Uzun Karanlık Gündüzlerim Özlemle Dolu Sensiz Dünyam Anlamsız Birtanem Bir Elmanın Yarısı Sıradan Ba...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensiz-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Sevgi', 'sonsuz-sevgi-metin-usengec-4sewb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgin sonsuz bende 

Kalbimde en derinde 

Özlemin tüm bedenimde 

Taşıyor sığmıyor sevgin yüreğime 

Canımsın ta içimde 

Çok sevdim birtanem çok 

Allah sonumu hayır eyleye..

Ocak-2002 

Ben Seni Hep Benim Bilmek İsterim; Seninle Yaşayıp Seninle Ölmek İsterim..', 'Sevgin sonsuz bende  Kalbimde en derinde  Özlemin tüm bedenimde  Taşıyor sığmıyor sevgin yüreğime  Canımsın ta içimde  Çok sevdim birtanem ç...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sonsuz-sevgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seveceğim', 'seni-sevecegim-metin-usengec-vcn4u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle yada böyle

Doğru yada yanlış

Güzel yada çirkin

Zengin yada fakir

İyi yada kötü

Az yada çok

Yakın yada uzak

Hayal yada gerçek

Açıkça yada gizli

Evli yada bekar

İyi günde kötü günde

Hastalık da sağlık da

Tanısam da tanımasam da

Arasan da aramasan da

Bulsam da bulamasam da

İster sarıl ister darıl

İster öp ister öpme

Öpsem de öpemesem de

Görsem de göremesem de

Kızsan da kızmasan da

Konuşsan da konuşmasan da

Haklı yada haksız

İstesen de istemesen de

istesem de istemesem de

Ayrılsak da ayrılmasak da

İster sev ister sevme

Sevsen de sevmesen de

Seni seveceğim..

12-Ocak-2001/21:00

Söz Dinlemez Deli Gönlüm İlle de sen İlle de Sen..', 'Öyle yada böyle Doğru yada yanlış Güzel yada çirkin Zengin yada fakir İyi yada kötü Az yada çok Yakın yada uzak Hayal yada gerçek Açıkça yad...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seni-sevecegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlığın Yeter', 'varligin-yeter-metin-usengec-6j1sj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece Senle Yatmasam

Sabah Senle Kalkmasam

Seni Çok Özlesem Sarılmasam  Öpmesem

Gözlerine Bakmasam Ellerine Tutmasam

Bana Çok Uzak Olsan Hep  Yanımda Olmasan

Sana Hiç Dokunmasam Sana Hiç Doyamasam

Canımsın  Sen Benim Seni Çok Seviyorum...

Hayalinle Yaşayıp   Hasretinle Yansam da 

Varlığın Beni Yaşama Bağlayan

Her zaman İçimdesin Her zaman Kalbimdesin..

Ocak-2002

Sevmişim Seni Bir Kere Vazgeçemiyorum..', 'Gece Senle Yatmasam Sabah Senle Kalkmasam Seni Çok Özlesem Sarılmasam  Öpmesem Gözlerine Bakmasam Ellerine Tutmasam Bana Çok Uzak Olsan Hep ...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/varligin-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum', 'ozluyorum-metin-usengec-nqyo6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni çok özlüyorum

Sesini,gülüşünü özlüyorum

Senle konuşmayı özlüyorum

Senle paylaşmayı özlüyorum

Seni çok hem de çok seviyorum..

Ocak-2001

Senle Çok Daha Güzel Olurdu..Birtanesi..', 'Seni çok özlüyorum Sesini,gülüşünü özlüyorum Senle konuşmayı özlüyorum Senle paylaşmayı özlüyorum Seni çok hem de çok seviyorum.. Ocak-2001 ...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ozluyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani İnsan', 'hani-i-nsan-metin-usengec-cbyvb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani insan olacağını bilir ya olunca kabullenmek istemez

Hani insan öleceğini bilir ya ölmek istemez

Hani insan sevince kaybedeceğini bilir ya kaybetmek istemez

ve yolun sonuna geldiğimizi hissediyorum..biliyorum..

Ama seni kaybetmek istemiyorum..

Şubat-2001

Sende Kaldı Yüreğim..', 'Hani insan olacağını bilir ya olunca kabullenmek istemez Hani insan öleceğini bilir ya ölmek istemez Hani insan sevince kaybedeceğini bilir ...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hani-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Ömürlük Sevdim', 'ben-seni-omurluk-sevdim-metin-usengec-qn3q0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben seni sevdim; gecelerce seni düşündüm bitanesi

Ben seni sevdim; yokluğunda ağladım gecelerce bitanesi

Ben seni sevdim; yokluğunda uyumadım gecelerce bitanesi

Ben seni ömürlük sevdim..ya sen beni? 

Şubat-2001

Dağları Aşarım Ben Taş Kalbini Aşamam..', 'Ben seni sevdim; gecelerce seni düşündüm bitanesi Ben seni sevdim; yokluğunda ağladım gecelerce bitanesi Ben seni sevdim; yokluğunda uyumadı...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ben-seni-omurluk-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadım', 'anlatamadim-metin-usengec-kcytp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canım,hayatım,bitanem,sontanem,herşeyim

sevgilim,tatlım,aşkım

aşkım-aşkım,yayamasım,uykucum

dünyalar tatlısı kedim,biriciğim

öpüyorumm,2 dak durmadan kocaman öpüyorummm

seni özlüyorum,seni çok özlüyorum

seni çok kocaman özlüyorum

seni seviyorum seni çok seviyorum

seni dünyalar kadar seviyorum

diyorum..

yinede içimden geçenleri kelimelerle ifade edemiyorumm..

Ocak-2002

Gülüm Sensiz Yaşanmıyor..', 'Canım,hayatım,bitanem,sontanem,herşeyim sevgilim,tatlım,aşkım aşkım-aşkım,yayamasım,uykucum dünyalar tatlısı kedim,biriciğim öpüyorumm,2 dak...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anlatamadim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Birtanem', 'canim-birtanem-metin-usengec-w5plm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özleminle dolu bir günde

Uçtun gittin elimden

Bilsen ne çok üzüldüm

Çırpındı çaresiz yüreğim

Nasıl dayanırım ben buna

Herşeyimdin sen benim

Sensiz bomboş dünyam

Tek mutluluğumdun sevgimdin

Sen benim tek sevdiğimdin

Şimdi sahipsiz bir yürek

Nasıl çarpar sensiz

Nasıl dayanır bu acıya

Geceler sensiz çok zor

Ayrılık acısı çok zor

Sonu karanlık bir yol

Hayalin gitmez gözümde

Acın dinmez gönlümde

Sevgin bitmez içimde

Kalbim hep seninle..

Mart-2002

Unutmayı İstesem de Yüreğimden Silemedim..', 'Özleminle dolu bir günde Uçtun gittin elimden Bilsen ne çok üzüldüm Çırpındı çaresiz yüreğim Nasıl dayanırım ben buna Herşeyimdin sen benim ...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/canim-birtanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nankör Sandığım Zaman', 'nankor-sandigim-zaman-tufan-turan-r0yuk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocuksu bir heyecan, 

Seni arayan gözler, 

Tutmayı bekleyen eller; 

Ve nankör sandığım zaman...

Ki ne çabuk da unutmuşum; 

Seni bana gösterdiği anı...', 'Çocuksu bir heyecan,  Seni arayan gözler,  Tutmayı bekleyen eller;  Ve nankör sandığım zaman... Ki ne çabuk da unutmuşum;  Seni bana gösterd...', ARRAY['Türk Edebiyatı','Şiir','Tufan Turan']::text[], 8.5, '{"poet":"Tufan Turan","poet_slug":"tufan-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nankor-sandigim-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öncesi Yok, Sonrası Yok', 'oncesi-yok-sonrasi-yok-tufan-turan-fswln', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne öncesi oldu, 

Ne de sonrası olacak...

Benim için hep tek kalacak.

Hiçbir zaman çıkmadı dudaklarımdan ''Keşke''

sana dair, 

Bende ''İyi ki'' vardı sana olan sevgimde.

Sebepsiz değil sevgim, 

Belki sadece karşılığı yok bu hayatta.

Ama bırak yorulsun kalbim uğruna, 

Elbet bir gün karşılığını bulacaktır uğrunda...', 'Ne öncesi oldu,  Ne de sonrası olacak... Benim için hep tek kalacak. Hiçbir zaman çıkmadı dudaklarımdan ''Keşke'' sana dair,  Bende ''İyi ki'' v...', ARRAY['Türk Edebiyatı','Şiir','Tufan Turan']::text[], 8.5, '{"poet":"Tufan Turan","poet_slug":"tufan-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oncesi-yok-sonrasi-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karların ve Sislerin Kralı Ve Okyanusun Sevgili Oğlu', 'karlarin-ve-sislerin-krali-ve-okyanusun-sevgili-oglu-sair-lautr-amont-734vn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '... Mario ve ben kumsal boyunca ilerliyorduk. Uzayın çeperlerini yarıyor ve kıyının çakılları üzerinde kıvılcımlar saçıyordu boyunları gergin atlarımız. Harmanilerimizde şişiyor ve ikiz başlarımızın saçlarını geriye savurtuyordu yüzümüzü döven karayel. Çığlıkları ve kanat vuruşlarıyla bize fırtınanın yaklaştığını boş yere haber vermeye çalışıyor ve haykırıyordu martı; “ böyle delice dört nala nereye gidiyor bunlar? ”. Hiçbir şey konuşmuyorduk; düşler içinde bu çılgın koşunun kanatlarına bırakmıştık kendimizi; Albatros gibi hızla geçtiğimizi gören önünden akıp giden, her zaman birlikte oldukları için o zamanlar kendilerine takılmış olan adlarıyla o “iki gizemli kardeş” i gördüğünü zanneden balıkçı çabucak haç çıkarmaya çabalayarak, derin bir kayanın altına saklanıyordu inmelenmiş köpeğiyle birlikte. Korkunç bir savaş, zıpkının iki düşman ülkenin göğsüne saplamakla tehdit ettiği ya da kolera sapanıyla, bütün kentlerin üzerine çürüme ve ölüm fırlatmaya hazırlandığı sırada, yeryüzünde, bulutların arasında, büyük felaket dönemlerinde ortaya çıkan bu iki insan hakkında garip şeyler anlatıldığını duymuştu kıyı sakinleri. Kasırgalar çıktığında, kum yığınları ve kör kıyılar üzerinde geniş kara kanatlarını yayan bu iki hayaletin, büyük doğa değişimleri sırasında, benzersizliği ve görkemi kuşakların bitimsiz zincirinin şaşkınlığına yol açan ölümsüz bir dostlukla birleşmiş durumda, yüceliklerini sergileyen kara ve deniz cinleri olduklarını doğrulayıp, ciddi bir tavır takınarak kaşlarını çatıyordu en yaşlı enkaz yağmacıları. İki And akbabası gibi yanyana uçan bu iki hayaletin, güneşe komşu hava katmanları arasında özekdeş çemberler çizerek süzülmeyi sevdikleri; bu yörelerde ışığın en saf özellikleriyle beslendikleri ama kentlerin ortasında, gizlice, kin ve kıskançlık hançerleriyle birbirlerini kalleşçe öldürmedikleri zamanlarda, savaşın kükrediği alanlarda birbirlerini kılıçtan geçiren ve kendileri gibi yaşam dolu ama canlılar sıralamasında kendilerinden birkaç basamak aşağıda bulunan varlıklarla beslenen acımasız halkaların yaşadığı insanlı kürenin kendinden geçmişçesine dönüp durduğu o ürkütücü yörüngeye doğru dikey uçuşlarının yönünü çevirmeye kolay kolay karar vermedikleri söyleniyordu. Ya da, vahiylerin ayetleriyle, insanları pişmanlığa yönlendirmek amacıyla, uzaklığı yüzünden küçük bir top gibi görünen belli belirsiz bir gezegenin, kendi iğrenç yüzeyinden yükselen yoğun bir cimrilik, gurur ve sırıtma gazlarının ortasında devindiği yıldızsal bölgelere doğru büyük kulaçlarla yüzmek kararını aldıkları zaman, anlaşılmamış ve rezil olmuş iyi yürekliliklerine acı acı dövünmek fırsatlarını kaçırmıyorlar ve özeksel yer altı teknelerinde fokurdayan o sönmeyen ateşi korumak için yanardağların dibine, ya da insan p.çlerine oranla kendilerine birer iyilik örnekleri gibi gelen en acımasız uçurum canavarlarına ilişkin düş kırıklığına uğramış görüşlerini dinlendirmek için deniz dibine dinlenmeye gidiyorlardı. Uygun karanlığıyla gece inince, kızıl somaki doruklu yanardağ ağızlarından, deniz dibi akıntılarından yukarılara yükseliyorlar ve insan papağanlarının munkabız dübürünün ıkınıp durduğu taşlı oturağı çok gerilerinde bırakarak, iğrenç gezegenin boşlukta asılı karaltısı gözden yitinceye dek uzaklaşıyorlardı. O zaman, acılarını paylaşan yıldızların ortasında, Tanrı’ nın gözü önünde, başarısızlığa uğrayan girişimlerine üzülen toprak meleği ile deniz meleği ağlayarak birbirlerine sarılıyorlardı! .. Isınmak isteyen gece rüzgarı saz kulübenin çevresinde ıslıklarını duyurur, ve ölü dalgaların getirdiği deniz kabuğu parçalarıyla temeli kuşatılmış bu dayanıksız duvarları bütün güzüyle sarsarken, gece toplantılarında, kapı ve pencereleri kapalı odaların ocakbaşlarında kıyı balıkçılarının fısıltıyla anlattıkları o anlatılmaz ve boş inanç ürünü söylentileri elbette biliyordu Mario ve onun yanında dörtnala at koşturan kişi. Konuşmuyorduk. Birbirini seven yürekler ne söyleyebilir birbirine? Hiç. Ama herşeyi dile getiriyordu sözlerimiz. Ben ona harmanisine daha iyi sarınmasın söylüyordum; o, atımın kendi atından çok fazla uzaklaşmış olduğuna dikkatimi çekiyordu.; Birimiz ötekinin hayatına kendisininki kadar ilgi duyuyordu; Gülmüyorduk. O bana gülümsemeye çalışıyor ama ben ölümlülerin zekalarının büyük bunalımlarının yönünü uygunsuz bir gözle değiştiren sfenkslerle sürekli olarak ilgilenen düşüncenin oyduğu korkunç izlerin yükünü taşıyan yüzünü görüyordum. Girişimlerinin işe yaramadığını görerek bakışlarını başka yöne çeviriyor, dünyasal gemini öfkenin ağzıyla ısırıyor, ve biz yaklaştıkça uzaklaşan ufka bakıyor. Bana gelince, bir ece gibi, zevklerin saraylarında ilerlemekten başka bir şey istemeyen parlak gençliğini ona anımsatmaya çalışıyordum. Ama, o, sözlerimin bir deri bir kemik ağzımdan güçlükle çıktığını, ve benim gençlik yıllarımın, şölen sofralarında ve altın balkımalarıyla, hayal kırıklığının acı zevkleriyle, yaşlılığın iç bulandırıcı kırışıklıklarıyla, yalnızlığın ürküntüleriyle ve acını yalımlarıyla satın alınmış solgun aşk rahibesinin uykuya daldığı atlas yataklarda dolaşan umarsız bir düş gibi hüzünlü ve duygusuz geçtiğini fark ediyor. Girişimlerin işe yaramadığını görerek, onu mutlu edemeyişime şaşırmıyordum; işkence aletlerini kuşanmış olarak, korkunçluğun göz kamaştırıcı aylası içinde görünüyor bana Kadiri Mutlak; gözlerimi çeviriyorum ve biz yaklaştıkça uzaklaşan ufka bakıyorum... Kıyı boyunca dört nala gidiyor atlarımız, sanki insan gözünden kaçar gibi... Benden daha genç Mario; havanın nemi ve köpürerek bize ulaşan tuzlu su, soğuğun dokunuşlarını getiriyor dudaklarımıza. “dikkat et! dikkat et! ” diyorum ona, “kapat dudaklarını, birbirine sıkı sıkı yapıştır; teninde yakıcı yaralar açan çatlağın sivri cırnaklarını görmüyor musun? ” Gözlerini alnıma dikip dilini oynatarak yanıtlıyor beni; “ evet görüyorum onları., yeşil cırnakları; ama onları uzaklaştırmak için ağzımın doğal durumunu bozmayacağım. Bak bakalım, yalan söylüyor muyum? Mademki sadece Tanrı’nın iradesi böyle, uyacağım ona. En iyisi onun iradesinin gerçekleşmesi.” Ve ben haykırdım; “ hayranlık duyuyorum bu soylu öç alışa.” Saçlarımı yolmak istedim; ama o ban engel oldu sert bir bakışla ve ona saygıyla boyun eğdim. Geç  olmuştu, ve kayanın girintilerine oyulmuş yuvasına dönüyordu kartal. Bana dedi ki; Harmanimi sana vereyim. Soğuktan korunman için; benim gereksinimim yok ona.” Onu yanıtladım; “ Vay haline, söylediğini yapacak olursan. Benim yerime bir başkasının acı çekmesini istemem, özelliklede senin.” Yanıtlamadı, haklıydım çünkü, ; ama ben, sözlerimin çok ağır kaçan vurgusu nedeniyle avutmaya çalıştım onu... Kıyı boyunca dört nala gidiyor atlarımız, sanki insan gözünden kaçarmış gibi... Başımı kaldırdım, kocaman bir dalganın kaldırdığı bir gemi pruvası gibi, ve ona dedim; “Ağlıyor musun? Sana soruyorum KARLARIN VE SİSLERİN KRALI. Gözyaşı görmüyorum kaktüs çiçeği gibi güzel yüzünde, ve gözkapakların kuru, tıpkı sel yatağı gibi; ama gözlerinin gerisinde, boynunu kocaman bir akrebin ısırdığı saflığının içinde kaynadığı kan gibi bir tekne görür gibi oluyorum. Kazanı ısıtan ateşin üzerine çullanıyor azgın bir rüzgar, ve onun karanlık yalımlarını senin kutsal gözçukurundan dışarı yayıyor. Pembeleşmiş alnına yaklaştırdım saçlarımı ve bir yanık kokusu duydum, yanmışlardı çünkü. Kapat gözlerini; çünkü, volkanın lavları gibi yanan yüzün kül benzeri dökülecek avucuma yoksa.” Ve, o, elinde tuttuğu dizginleri umursamadan bana dönüyor, ve zambak gözkapaklarını denizin gelgitleri gibi ağır ağır indirip kaldırarak acımayla bakıyordu bana. Gözüpek sorumu yanıtlamak istedi ve şöyle konuştu; “Kaygılanma benim için. Tıpkı ırmaklarının buharlarının tepenin yamaçlarından tırmanması ve doruğa varınca da bulutlar oluşturarak havaya yükselmesi gibi, haklı bir nedene dayanmaksızın ağır ağır çoğalan benimle ilgili kaygıların imgeleminin üzerinde kederli bir serabın yanıltıcı bir varlığını oluşturuyor. Kafatasımın kızgın bir kömür başlığının içine sıkıştığı izlenimini duyumsuyorsam da, inan ki gözlerimde ateş yok. Bence, başımızın üzerinden geçen rüzgarın iniltilerinden başka bir şey olmayan şu çok zayıf ve belirsiz çığlıklardan başka bir şey duymadığıma göre, teknede nasıl kaynasın saflığımın bedeni? Bir sivri kıskaçlı akrebin parçalanmış gözevimde yurtlanması olanaksız bir şey; bence bunlar, göz sinirlerimi ezen güçlü kıskaçlar. Ne var ki, tekneyi dolduran kanın, son gece uyurken, görünmez bir celladın akıttığı kanım olduğunu düşünüyorum ben de senin gibi. Uzun süre bekledim seni, OKYANUSUN SEVGİLİ OĞLU; ve evimden içeri giren Kimse’yle gereksiz bir boğuşmaya girişti uyuşuk kollarım... Evet, ruhumun vücudumun sürgüsüyle kilitlenmiş olduğun, ve insan denizinin dövdüğü kıyılardan uzaklara kaçmak ve sonsuz mutluluğun yarıkları ve uçurumları arasında insan dağ keçilerini ara vermeksizin kovalayan mutsuzlukların solgun sürüsünün görünümüne daha fazla tanık olmamak için serbest kalamayacağını duyumsuyorum. Ama, yakınmıyorum. Yaşamı bir yara gibi karşıladım, ve intiharın yarayı iyileştirmesini yasakladım. İsterim ki, sonsuzluğun her anında bu açık çatlağı görsün yaratıcı. Ona verdiğim cezadır bu. Tunç ayaklarının hızını azalttı atlarımız; bir yabandomuzu sürüsünün baskınına uğrayan bir avcı gibi titriyor bacakları. Söylediklerimizi dinlemeye kalkışmamaları gerek. Dikkatlerini yoğunlaştıra yoğunlaştıra zekaları gelişebilir ve belki o zaman anlayabilirler bizi. Vay hallerine; çünkü daha çok acı çekerler! Gerçekten, insanlığın süt domuzlarını düşün yalnızca: Kendilerini evrenin öteki yaratıklarından ayıran zeka düzeyi, sayısız acıların çaresiz bedeline karşılık olarak verilmiş gibi değil mi onlara? Benim gibi yap, gümüş mahmuzların gömülsün atının böğürlerine...” Kıyı boyunca dört nala gidiyor atlarımız, sanki insan gözünden kaçarmış gibi.', '... Mario ve ben kumsal boyunca ilerliyorduk. Uzayın çeperlerini yarıyor ve kıyının çakılları üzerinde kıvılcımlar saçıyordu boyunları gergi...', ARRAY['Türk Edebiyatı','Şiir','Şair Lautréamont']::text[], 8.5, '{"poet":"Şair Lautréamont","poet_slug":"sair-lautr-amont","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/karlarin-ve-sislerin-krali-ve-okyanusun-sevgili-oglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alfabetik Aşk', 'alfabetik-ask-tacettin-cetin-oz901', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ansızın rüyalarıma girmeni seviyorum

Belalı gecenin ortasında

Cesurca seni seviyorum demek istiyorum

Çıkıp bir gün karşına

Denize karşı iki tek atıp

Elele geçerek mahalleden 

Fiyaka satmak istiyorum gökyüzüne 

Göstermeden içimizdeki hüznü 

Hastalanmış hayallerimizide alıp 

Ilık bir yaz yağmuru altında 

İliklerime kadar ıslanmak istiyorum seninle 

Jiletinine ismini yazdığım sigara paketinde 

Kora özlem duyan birkaç sigarayı içip

Lanet yağdırırken sensizliğe 

Meyhane kokan akşamlarda 

Ne olurdu yanımda olsan demek istiyorum istemeden 

Orda bir sen var uzakta biliyorum 

Ölümüne benim olan 

Parıldadığını sana yıldızların ortasında 

Rastlayıpta açılamadığım 

Seviyorum diyemediğim 

Şarkılarda dinlediğim 

Ta uzaklarda bir sen var orda biliyorum

Uzanıpta Erişemediğim 

Ürkek bakışlarında 

Vakitli vakitsiz ağladığım 

Yazdan kalma güneşin altında 

Zehir zemberek aşkların ortasında 

 ''Ğ'' kadar şanssız hiçbir şeye başlayamayan bir ben var burda görüyormusun', 'Ansızın rüyalarıma girmeni seviyorum Belalı gecenin ortasında Cesurca seni seviyorum demek istiyorum Çıkıp bir gün karşına Denize karşı iki ...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Çetin']::text[], 8.5, '{"poet":"Tacettin Çetin","poet_slug":"tacettin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/alfabetik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Seni Sildim Silgilerimle', 'yalniz-seni-sildim-silgilerimle-tacettin-cetin-kxxrg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çocukluğumun en üşüdüğüm yazlarıydı 

seni sevdiğim yazlar 

nüfus dairesinde kaydı olmayan bir çocuktum senin gözünde 

hiç doğmamış 

yani doğmuşta doğduğundan habersiz 

ben seni çok iyi biliyordum 

ezberimdeydin babamın öğrettiği keraat cetveli gibi 

iki kere ikilerin yanına eşittir koyup hep seni yazıyordum 

ve sonra siliyordum babam gelince 

üşüyordum kavuran güneşin altında 

sizin mahalleden geçerken 

top oynamaya hep sizin mahalleye geliyordum 

bahçenize kaçan topun peşinden ilk ben koşuyordum 

belki çıkıp azarlarsın diye 

ben kaleci oluyordum bütün maçlarda 

bahçenizin kapısıyla yolun ortasına taş koyup 

ama hiç gol yemiyordum sen bakarken 

sadece üşüyordum 

akasyanızın bahçeden dışarı fırlamış dalları altında 

sizin mahallenin bakkalına geliyordum ekmek almaya 

sonra soluk soluğa varıyordum eve 

babamdan azar işitmiyim diye 

ben seni çok iyi biliyordum 

ezberimdeydin babamın öğrettiği keraat cetveli gibi 

iki kere ikilerin yanına eşittir koyup seni yazıyordum 

ve sonra siliyordum babam gelince 

şimdi ise acıyorum harcadığım onca silgiye', 'çocukluğumun en üşüdüğüm yazlarıydı  seni sevdiğim yazlar  nüfus dairesinde kaydı olmayan bir çocuktum senin gözünde  hiç doğmamış  yani doğ...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Çetin']::text[], 8.5, '{"poet":"Tacettin Çetin","poet_slug":"tacettin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yalniz-seni-sildim-silgilerimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim', 'neyleyim-abdullah-yuce-0vxvp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tufanlar koptu bende derinden! 

Parçalandı yüreğim kim bilir kaç yerinden

Harabolmuş yine kalbim, bıkmışken kaderinden

Derdimi anlatmayan dili neyleyim? 

Haberin yok aşkımdan, sevda yeli senden ırak

Bir beni savuruyor bırakmayarak

Arş''a kadar yükselsemde yıldızları sayarak

Saçlarını okşamamış yeli neyleyim? 

Bir Gül ki yıllar yılı olsa başımın taacı

Yine o gül ki bana, çektirmese tek acı

Gece gündüz olsada dertlerimin ilacı

Sevdiğim, Senden gayrı gülü neyleyim? 

Bu hayat selinde dalamazsak derine

Atar bizi dünyanın başka başka yerine

Azrail çıkmasada bir benim seferime

Seni benden ayıran seli neyleyim? 

Koşup tutmak istesem bulup tutamam

Söküp atmak istesem kalpten atamam

Bu hasretle ölürsem kabirde de yatamam

Söyle eey sevdiğim seni neyleyim? ...', 'Tufanlar koptu bende derinden!  Parçalandı yüreğim kim bilir kaç yerinden Harabolmuş yine kalbim, bıkmışken kaderinden Derdimi anlatmayan di...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yüce']::text[], 8.5, '{"poet":"Abdullah Yüce","poet_slug":"abdullah-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neyleyim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-erhan-meydan-73sbe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bizmiyiz..? 

yasanılanlardaki, 

bizmiyiz..? 

düsünülenlerdeki, 

bizmiyiz..? 

hayallerdeki, 

biz mi..? 

biz kimiz ki...', 'bizmiyiz..?  yasanılanlardaki,  bizmiyiz..?  düsünülenlerdeki,  bizmiyiz..?  hayallerdeki,  biz mi..?  biz kimiz ki......', ARRAY['Türk Edebiyatı','Şiir','Erhan Meydan']::text[], 8.5, '{"poet":"Erhan Meydan","poet_slug":"erhan-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/biz-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-yalgin-ornek-jn26v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kantin sonbaharının

Geniz yakıcı çikolata kokusunda

Dumanların arasından kaçamak bakışlı

Bir gözkaçırmacaydı sana sevdam...

Olmazdı ya; 

Bir baksan uzunca, derin, deniz yeşili, 

Tüm o çikolata kokusu yeşil koksa bir anda.

Gök yeşil olsa, 

İnsanlar yeşil...

ve sen hala baksan

Ben gözlerimi kaçırsam da...

Olmazdı ya...

Gecenin karanlığı sararsa saçlarından

Girsem o sarı dehlize, 

Dolaşsam, yorulsam, 

Kaybolsam...

Nasılsa sana çıkacak tüm yollar

Kaybolduğumu umursamasam...

Ağlamaya hasret cansıkıntılarımı

Buluştursam gülüşünle.

Belki de bana hiçbir zaman öyle gülümsemeyeceğini anlasam, 

Gülüşüne dalsam, 

Doyasıya ağlasam...

Bir kantin sonbaharının

Geniz yakıcı yeşil kokusunda

Dumanların arasından kaçamak bakışlı

Bir gözkaçırmacaydı sana sevdam...

Ve ben; 

Gözlerini kaçırıp

Kendini senden kaçıramayan bir adam...', 'Bir kantin sonbaharının Geniz yakıcı çikolata kokusunda Dumanların arasından kaçamak bakışlı Bir gözkaçırmacaydı sana sevdam... Olmazdı ya; ...', ARRAY['Türk Edebiyatı','Şiir','Yalgın Örnek']::text[], 8.5, '{"poet":"Yalgın Örnek","poet_slug":"yalgin-ornek","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Kulesi', 'kiz-kulesi-cigdem-simsek-u6413', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sahildeyim...! 

Zar zor bulutları aralayıp, 

Gülüşlerini denize bırakan güneş göründü.

Eve işte oradaydı...

Yüreğimin, İstanbul’un incisi

Bir yandan güneş açıyor, yüzüm gibi.

Deniz ha bire kıpırdanıyor, duygularım gibi.

Sahile dalgalar vuruyor, tutkularım gibi.

Kız Kule ’m öylece bekliyor, sevdam gibi.

Bekle gönül bekle...

Bir gün sende güneş olup açacak, 

Sahil olup dalgaları kucaklayacaksın.

Ve Kız Kulesi gibi bu AŞKI yaşayacaksın...', 'Sahildeyim...!  Zar zor bulutları aralayıp,  Gülüşlerini denize bırakan güneş göründü. Eve işte oradaydı... Yüreğimin, İstanbul’un incisi Bi...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kiz-kulesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördüğüm (I)', 'kordugum-i-aysun-elagoz-3hge1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşünceler düğümlenir gece yarıları, 

Sinsi karanlıklar beynimi talan eder

Nefesim düğümlenir

Ağlayamam ki...', 'Düşünceler düğümlenir gece yarıları,  Sinsi karanlıklar beynimi talan eder Nefesim düğümlenir Ağlayamam ki......', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kordugum-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördüğüm (II)', 'kordugum-ii-aysun-elagoz-s2vs1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne çekip gidişin dert olur içime, 

Ne yokluğun  biçare kılar beni.

Şaşkınlığım, 

Nereye saklayacağımı bilemeyişimden

Biriktirdiğim özlemleri...', 'Ne çekip gidişin dert olur içime,  Ne yokluğun  biçare kılar beni. Şaşkınlığım,  Nereye saklayacağımı bilemeyişimden Biriktirdiğim özlemleri...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kordugum-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördüğüm (III)', 'kordugum-iii-aysun-elagoz-zp1qf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vakitsiz yağmurlar gibidir gözyaşlarım

Yüreğime attığın kördüğümden damlayan.

Sanki ben değilim, 

Gözlerim değil, 

Yüreğimdeki kördüğüm 

Hiç durmadan ağlayan...', 'Vakitsiz yağmurlar gibidir gözyaşlarım Yüreğime attığın kördüğümden damlayan. Sanki ben değilim,  Gözlerim değil,  Yüreğimdeki kördüğüm  Hiç...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kordugum-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımında', 'gun-batiminda-fatih-cinar-7abyn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni bir gün batımı kızıllığında sevdim

ve bir sabah aydınlığında kaybettim

sen benim deniz ortasında yakalandığım bir fırtınada

sığındığım limandın

sen benim dağım nehirim denizimdin

sen benim şehir kalabalığından sıkılıp geldiğim

doğal bir köydün

hiç bozulmamış telefonsuz elektiriksiz

keşke seni hiç sevmeseydim

seni bir gün batımı sevdim

tüm duygularımla battı güneş

sen şehirlerden daha kalabalık çıktın

ve çağdaşlığın azizliğine uğramış

bir köy gibiydin

keşke seni hiç sevmesydim

hiç görmeseydim batan günü', 'seni bir gün batımı kızıllığında sevdim ve bir sabah aydınlığında kaybettim sen benim deniz ortasında yakalandığım bir fırtınada sığındığım ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-batiminda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Sevemem! ..', 'sevemem-mustafa-engin-karatay-sky51', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Âvârelik alnımızın yazısı değil ya gerçi, 

Ama şimdi sıfatımız olmuş...

Beni sırtımdan vuruşunun, 

Ânî bir şekilde, hiç bir açıklama yapmadan terkedişinin, 

Yüreğimdeki tahribâtının eseri, meyvesi olmuş...

Yokluğunun acısı değil ki bu

Hasret ve özlem hiç değil

Düpedüz satılmışlık acısı...

Dolaştım bu akşam İstanbul''u; 

Ne Sâhil''deki Fasıl tat verdi, 

Ne Sultanahmet''deki Nargile

Yine aynı çiçekçi çocuk geldi

Fakat bu sefer elindeki güller dâhi küskündü

Uzattım elimi bir Tomurcuk Gonca seçmek için, 

Sanki yüreğime saplanan bir Hançer vardı

Gözyaşlarım aktı tomurcuğun üstüne...

Sonra götürdüm, Meydan''da ilk konuştuğumuz yere bıraktım

Âdetâ mezar üstüne bırakılan çiçekler gibi...

Ayasofya''da bir hüzün

Sultanahmet küskün

Sanki İstanbul mâtem tutuyordu...

Tahammüllerimi alt-üst edercesine zorlayan acına dayanamadım

Bir şeyler beni sürüklüyordu Ayvansaray Sırtları''na

Yürüdüm, yürüdüm, yürüdüm...

Başıboş

Sessiz

Sensiz

Orada da canlandı bütün hâtırâlarım

Bu nasıl ızdırâb? 

Bu neyin belâsı? 

Ne yaptım ki ben, revâ gördün bütün bunları? 

Beyazıt Meydanı''nda İki âşık gördüm, çaylarını yudumluyorlardı

Onları seyre daldım

İçimi çektim

Artık nefesim ciğerlerime batıyordu

Katlanması ne zormuş meğer

Çöktüm yere

Saçlarımı yerinden sökercesine yolmak istedim

Fakat ne çâre? 

Neyi geri getirir ki? 

Neyi? ..

Oysa, Zülfün''deki  bir teli Dünyâlar''dan kıskanırdım

Bir tebessümün için, ölüme meydân okurdum

Uğruna her şeyimi fedâ etmedim mi? 

O parlayan gözlerin, içimdeki alevlerin kıvılcımı değil miydi? 

Yüzlerce dilber bir araya gelse, 

Titrek sesindeki bir çift söz kadar coşturabiliyor muydu beni? 

Nasıl yapabildin ki bunu bana? 

Nasıl? 

Nasıl? ..

Şimdi İstanbul mahzûn

Ben dertli

Tertemiz aşkım kederli

Yüreğim tartamıyor acıları

İnsâfım, vicdânım heder oldu

Sevemem artık kimseyi, seni sevdiğim kadar! ..

Hattâ seni bile sevemem, seni sevdiğim kadar! ..

Sevemem! ..

29.04.2001    İstanbul-Aksaray   01:50', 'Âvârelik alnımızın yazısı değil ya gerçi,  Ama şimdi sıfatımız olmuş... Beni sırtımdan vuruşunun,  Ânî bir şekilde, hiç bir açıklama yapmada...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/sevemem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşkiya Dünyada Eşkiya Olmak', 'eskiya-dunyada-eskiya-olmak-fatih-cinar-dy4ev', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'eşkıya dünyada eşkıya olmak

ne zor''dur bilirmisin? 

korkarsın tan yeri ağarırken

bazen yıldızlar aydınlatır

bazende hayalindeki bir çift mavi göz karanlığı

serseri gecelerde dost kaldırımları yürürken

eşkıya dünyada eşkıya olmak

acılarla bilemek gerek 

sevdalarla körlenen yüreği

bileklerinin fırat gibi geniş

kanının fırat gibi serin

duygularının fırat gibi derin olması gerek

keder tablolarına tuval olan yüzünü

hergün aynalarda görmen gerek

bu eşkıya dünyada eşkıya olmak için

eşkıya dünyada eşkıya olmak

kozlarını oynamak dünyaya karşı

namlunun ucundaki bedeninle

kafa tutmak sefalete yokluğa

bir cümle namerde ve şerefsize 

zorda olsa dayanmak zorda olsa

inadına gülmek güzel''dir

dünyanın zorbalığına

hemde katıla katıla hemde kahkahayla', 'eşkıya dünyada eşkıya olmak ne zor''dur bilirmisin?  korkarsın tan yeri ağarırken bazen yıldızlar aydınlatır bazende hayalindeki bir çift mav...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/eskiya-dunyada-eskiya-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turan', 'turan-ziya-gokalp-3ssea', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nabızlarımda vuran duygular ki tarihin

Birer derin sesidir, ben sahifelerde değil

Güzide, şanlı, necip ırkımın uzak ve yakın

Bütün zaferlerini kalbimin tanininde

Nabızlarımda okur, anlar, eylerim tebcil.

Sahifelerde değil, çünkü Atilla, Cengiz

Zaferle ırkımın tetviç eden bu nasiyeler, 

O tozlu çerçevelerde, o iftira amiz

Muhit içinde görünmekte kirli, şermende; 

Fakat şerefle numayan Sezar ve İskender! 

Nabızlarımda evet, çünkü ilm için müphem

Kalan Oğuz Han''ı kalbim tanır tamamiyle

Damarlarımda yaşar şan-ü ihtişamiyle

Oğuz Han, işte budur gönlümü eden mülhem: 

Vatan ne Türkiyedir Türklere, ne Türkistan

Vatan, büyük ve müebbet bir ülkedir: Turan', 'Nabızlarımda vuran duygular ki tarihin Birer derin sesidir, ben sahifelerde değil Güzide, şanlı, necip ırkımın uzak ve yakın Bütün zaferleri...', ARRAY['Türk Edebiyatı','Şiir','Ziya Gökalp']::text[], 8.5, '{"poet":"Ziya Gökalp","poet_slug":"ziya-gokalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Yaprak', 'yesil-yaprak-asik-sefai-gf2q7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeşil yaprak döndüğünde gazele 

Yazın ardı güz görünür sevdiğim 

Ayrılırken kaşım çatmam güzele 

Belki acı söz görünür sevdiğim 

Bilir misin sevda neden turnanın 

Diyarından kaçıp giden turnanın 

Yükseklerden uçup giden turnanın 

Sinesinde köz görünür sevdiğim 

Nazar eyler enginlerden yüceler 

Garip gönlüm simdi neyi heceler 

Çoban yıldızına hasret geceler 

Bu sevdalar az görünür sevdiğim 

Dağı yaran göğü ağlatan vardır 

On sekiz bin rengin cümlesi yardır 

Varlığın yokluktur yokluğun sırdır 

Her zerresi toz görünür sevdiğim 

Sefai''yem gecelere hilal et 

İster cemal eyle ister celal et 

Bir lokma ekmeğin yedim helal et 

Ölüm bize tez görünür sevdiğim! 

Aşık Sefai', 'Yeşil yaprak döndüğünde gazele  Yazın ardı güz görünür sevdiğim  Ayrılırken kaşım çatmam güzele  Belki acı söz görünür sevdiğim  Bilir misin...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yesil-yaprak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönül', 'deli-gonul-asik-sefai-cns1v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Verselerde dünya mali istemem

Seni ister deli gönül hep seni

Köskü saray neki çali istemem

Seni ister deli gönül hep seni

Lokma lokma yutkundugum asimda

Gündüz hayalimde gece düsümde

Bir garip sevdadir döner basimda

Seni ister deli gönül hep seni

Senin için daglar asar türküler

Senin için yara deser türküler

Senin için tutsak düser türküler

Seni ister deli gönül hep seni

Yunus''un denizde yüzdügü gibi

Koyun kuzusuna gezdigi gibi

Asigin askina yazdigi gibi

Seni ister deli gönül hep seni

Yagmur bulutlari döktügü anda

Daglarin dumani çöktügü anda

Sabahin günesi söktügü anda

Seni ister deli gönül hep seni

Daglara yürürken yörük kervani

Varligin yoklugun sensin devrani

Ne istersin diye gelse fermani

Seni ister deli gönül hep seni

Rüzgar vursa sari aliç sallansa

Elmalarin yanaklari allansa

Ala çördük tadin alip ballansa

Seni ister deli gönül hep seni

Kiyametmi kopar murada ersem

Bagban olup goncalarini dersem

Nerde el örmesi bir kilim görsem

Seni ister deli gönül hep seni

Garip SEFAI''yem gam kapisinda

Muhabbetim haktir dem kapisinda

Elif dergahinda mim kapisinda

Seni ister deli gönül hep seni', 'Verselerde dünya mali istemem Seni ister deli gönül hep seni Köskü saray neki çali istemem Seni ister deli gönül hep seni Lokma lokma yutkun...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/deli-gonul-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nilüfer', 'nilufer-abdullah-yuce-rfbt6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çiçekle bahar olmaz diyorlar! 

Yalan mı söylüyorlar? ..

Yok canım, 

Anla işte! 

Her çiçekle bahar olmaz demek istiyorlar.

Eh, 

Öyleyse doğru söylüyorlar, 

Her çiçekle bahar olmaaaz...

Pekii, 

Peki niye Nilüfer yok diyorlar? 

Neden onu bana vermiyorlar? ...

Belki de beni pek sevmiyorlar! 

Yok yok, 

Onlar benim derdimi bilmiyorlar

Bu yüzden Nilüfer yok diyorlar! 

Allahım! 

Varsın bilmesinler.

Varsın beni pek sevmesinler.

Ama ne olur

Ne olur Nilüfer yok demesinler, 

O''nu benden gizlemesinler...

Aman Allahım! İşte, 

İşte bi çiçekçi daha.

Gidip hemen sormalıyım

O''nu bulmalıyım, 

O''nu mutlaka bulmalıyım...

-Kimse yok mu? 

Çiçekçi bey.

-Buyrun efendim ne arzu edersiniz? 

-Şey, 

Nasıl anlatsam bilmem? 

Son ümidim sizsiniz.

Siz bu şehirdeki en son çiçekçisiniz.

Sakın hemen yok demeyin

Bi bakın isterseniz.

Biraz düşünün ha, 

Ne dersiniz? ..

Eğer  sizde yok derseniz beni kahredersiniz.

Sakın yok demeyin! 

Var deyin...

Hatta senin için saklamıştım deyin

Sonra isteyin benden, 

Bütün varımı isteyin

Ya da canımı isteyin...

-Aaa, tabii efendim, 

Tabii ki var.

Dilediğiniz her şey var.

Karanfiller  Goncagüller  Menekşeler, 

Laleler  Leylaklar Sümbüller, 

Daha neler neler.

Hatta  Hanımeli, Camgöbeği

Peygamber çiçeği...

Kaynana dili bile var.

-Yeter kardeşim, yeter! 

Sen onların hepsini boşver.

Bana sadece Nilüfer ver

Sadece Nilüfer...

-Nilüfer mi? ... 

Nilüfer yok efendim.

-Hayır olamaz, 

Olamaz! 

Nilüfer var, biliyorum.

Ben en çok O''nu seviyorum

İllada Nilüfer istiyorum! ..

-Peki size Sümbül versem

Yahut Gül versem? 

-Hayır, 

Hayır gülemem, 

Yani Gül istemem.

Hem bence Nilüfer, binlerce Gül''e bedel.

(Allahım! 

Allahım Nilüfer var biliyorum

O''nu çok seviyorum.

Senden yardım diliyorum

Yardım et Allah''ım yardım et  ölüyorum...)   

-Lakin, Nilüfer çiçekçide olmaz efendim.

O en çok suyu sever.

Derelerde, Sulu yerlerde biter.

Belli ki hep özgür olmak ister, e....

-Yeter yeter yeter.

Nilüfer''siz hayat zaten ölümden beter.

Bi de bu işi sulandırıp, 

Zihnimi bulandırıp, 

Beni boş yere kandırıp durma! 

Benim Bildiğim Nilüfer Gönlümde biter.

Eh, bazende böyle çekip gider ama, 

Olsun, 

Hayali bile yeter.

Hem  sen, 

Çiçekçiyim diyorsun

Nilüfer''i bilmiyorsun

Nilüfer yok diyorsun.

Ya yalan söylüyorsun, ya hata ediyorsun! ... 

Evet evet, belliki hata ediyorsun

Çünkü var, biliyorum

Ben en çok O''nu seviyorum

İlla da Nilüfer istiyorum..

-Haklısın kardeşim, Nilüfer var! 

Buna ben de inandım.

Senin bu haline ben bile yandım.

Sonra sakın! 

Sanma ki çiçekçi olduğumdan utandım

Sende de suç var! ... 

Niye bana sorarsın? 

Belli ki Nilüfer''i yanlış yerde ararsın.

Dedim ya, 

Nilüfer çiçekçide olmaz....

-Haklısınız! 

Dert benim tasa benim.

Sizi ne hakla üzerim? 

Özür dilerim, çok özür dilerim.

Şimdi ben boynumu büker

Arkamı döner çeker giderim....

-Haklı, 

Adam galiba haklı! 

Nilüfer şimdi kimbilir nerdedir? 

Belki bu bitmez yolun taşlarında, 

Belki de biten bi filmin başlarındadır.

Kim bilir? 

Belki de benim göz yaşlarımda...

Ama bilsem ki, 

Bilsem ki şu telefonun tuşlarındadır...', 'Bir çiçekle bahar olmaz diyorlar!  Yalan mı söylüyorlar? .. Yok canım,  Anla işte!  Her çiçekle bahar olmaz demek istiyorlar. Eh,  Öyleyse d...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yüce']::text[], 8.5, '{"poet":"Abdullah Yüce","poet_slug":"abdullah-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":122,"source_url":"https://www.antoloji.com/nilufer-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğurlar Olsun', 'ugurlar-olsun-ceyhun-yilmaz-oiee9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaç gecedir

borçlu giriyorum geceden sabaha

Kumdan ekmekler yapıyorum kendime

Sonra dalga sesi sürüyorum ekmeğime

Olmadı

Sensiz uyanmamak için

bu gecede uyunmadı

Gittiğinden beri ağlamadım

Çünkü o gözyaşları

yüreğimde durduğu sürece 

Senin adın aşk bende

Haberin olsun! ...

Bu sabah hüngür hüngür ağladım

İçimde ne kadar sen varsa

Bir bir uğurladım...', 'Kaç gecedir borçlu giriyorum geceden sabaha Kumdan ekmekler yapıyorum kendime Sonra dalga sesi sürüyorum ekmeğime Olmadı Sensiz uyanmamak iç...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ugurlar-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-ceyhun-yilmaz-m397u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüzgarı seviyorum en çok

Çünkü bir rüzgar seviyor beni

Ensemden okşayıp

yanağımdan öpüp gidiyor

Ne zaman öpüceğini bilmeden

hep seviyorum rüzgarı

hep essin istiyorum bir rüzgar

Rüzgarı seviyorum en çok

Güneş açsa eriyorum

Yağmur yağsa ıslanıyorum

Rüzgarı seviyorum en çok

Ben en çok rüzgarı seviyorum ya

Sen rüzgarsın galiba', 'Rüzgarı seviyorum en çok Çünkü bir rüzgar seviyor beni Ensemden okşayıp yanağımdan öpüp gidiyor Ne zaman öpüceğini bilmeden hep seviyorum rü...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruzgar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-onur-hanic-oqde7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Serde erkeklik var

İtiraf edemem kendime bile

Korktuğumu, kaçtığımı

Heyecanımı; 

Sen de ben de görmesem de

Ağladığımı.', 'Serde erkeklik var İtiraf edemem kendime bile Korktuğumu, kaçtığımı Heyecanımı;  Sen de ben de görmesem de Ağladığımı....', ARRAY['Türk Edebiyatı','Şiir','Onur Haniç']::text[], 8.5, '{"poet":"Onur Haniç","poet_slug":"onur-hanic","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/itiraf-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Biliyor -2-', 'kus-biliyor-2-erdinc-ozdemir-txgdx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir orman

Dallarında bir piyano

Tuşlarında sözcükler

Kuş bekliyor

Ormanın derin okyanuslarında

Yirmibeş kuruşluk sinemalar

Kuş bekliyor

Farklı bir dalın yapraklarında

Bavulsuz bir aşk

Kuş bekliyor

Kare bir dalda

Sodyumun simgesi nedir

Kuş bekliyor

Ağaçların tepesinde

Can Yücel

Kuş beklemekten yorulup

Uykuya dalmış', 'Bir orman Dallarında bir piyano Tuşlarında sözcükler Kuş bekliyor Ormanın derin okyanuslarında Yirmibeş kuruşluk sinemalar Kuş bekliyor Fark...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Özdemir']::text[], 8.5, '{"poet":"Erdinç Özdemir","poet_slug":"erdinc-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kus-biliyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Değil', 'i-lk-degil-deger-ulas-turan-hgc2v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen yalın hayalleri 

Aynalarda tutsak bıraktın 

Yalnızlığa sığınarak. 

Bilsen bukağısı paslı ömrüme 

Tek bahçe sığdıramam, 

Sen ardımı kanatırken. 

Bir sigara yakıyorum 

Gecenin aydınlığına 

Göğsüm kanıyor, saramıyorum. 

Belki güneyi sarıyorum 

Doğuya tutunarak 

Ve teselliyi geceye bırakıp, kapatıyorum perdeyi...', 'Sen yalın hayalleri  Aynalarda tutsak bıraktın  Yalnızlığa sığınarak.  Bilsen bukağısı paslı ömrüme  Tek bahçe sığdıramam,  Sen ardımı kanat...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilk-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sor', 'bana-sor-ahmet-tufan-senturk-17gj9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BANA SOR

Gurbet nedir, hasret nedir, aşk nedir? 

Çekmeyen ne bilsin, onu bana sor...

Döğme (*)   nedir, yemlik nedir, aş endir? 

Yemeyen ne bilsin, onu bana sor...

Çoban oldum, dağda keçi otlattım, 

Yarı gün aç, yarı günü tok yattım, 

Ben derdimi dağa, taşa anlattım

Neler çektim, neler gördüm, bana sor...

Geyecek (**) , hem ahlat(***) , gilik (****)   ve arpa, 

Şalgalama, pancara ve sonra turpa, 

Keçiler aç susuz, oğlaklar körpe, 

Kimler ne yer, ne içerdi, bana sor...

Kışın sıcak külde gilik pişirdim, 

Nohut kavurgasını döktüm deşirdim, 

Tüfek, talşal uçan kuşu düşürdüm, 

Açlık ne, avcılık nedir,  bana sor...

Kırıktı kanadım, kırıktı kolum, 

Dokuz yamalıydı giysim ve çulum, 

Toroslardan aştı, kış günü yolum, 

Soğuk nedir, tipi nedir, bana sor...

*     yabani armudun döğülüp yenen unu

**    üveze benzer dağ meyvesi

***   yabani armut

**** meşe palamutu', 'BANA SOR Gurbet nedir, hasret nedir, aşk nedir?  Çekmeyen ne bilsin, onu bana sor... Döğme (*)   nedir, yemlik nedir, aş endir?  Yemeyen ne ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tufan Şentürk']::text[], 8.5, '{"poet":"Ahmet Tufan Şentürk","poet_slug":"ahmet-tufan-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bana-sor-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barışa Özlem', 'barisa-ozlem-ahmet-tufan-senturk-f4eh6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Size sesleniyorum cümle insanlar! 

Ne olursa olsun dininiz, milliyetiniz, 

Bırakın kavgayı, kini, garezi, 

Atın silahları ellerinizden

Nedir bu çabanız...öldürmek için? 

Ne istiyorsunuz birbirinizden? 

Suda balıklar tedirgin, 

Gökte yıldızların rahatı kaçtı, 

Bir gün yıkılacak ihtiyar dünya, elinizden...

Karıncaları görüyorsunuz, 

Ağaçları, kuşları görünüyorsunuz, 

Dağlar söz atmıyor birbirlerine, 

Bu dünyada her şey yerli yerinde, 

Ama biz varız ya insanoğlu, 

Hepsi şikayetçi bizden...

İnsan doğduğuna pişman, 

Unuttuk sevmeyi, sevilmeyi, 

Bir çaba ki bitip tükenme bilmez, 

Dünyada kardeşçe yaşamak lazım, 

Neden korkuyoruz birbirimizden..', 'Size sesleniyorum cümle insanlar!  Ne olursa olsun dininiz, milliyetiniz,  Bırakın kavgayı, kini, garezi,  Atın silahları ellerinizden Nedir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tufan Şentürk']::text[], 8.5, '{"poet":"Ahmet Tufan Şentürk","poet_slug":"ahmet-tufan-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/barisa-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyin Varsa', 'beyin-varsa-ahmet-tufan-senturk-ttg5m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hepinizin ciğerini bilirim, 

Hepinizin yüreğini bilirim, 

Anlarsınız ya, her nasılsa.

Güçlüsünüz, görkemlisiniz, 

Ola ki, gençsiniz, güzelsiniz, 

Pırıl pırıl ayakkabılarınız, 

Tertemiz, ütülü giysileriniz, 

Ya içiniz.

Yerinde kafanız, kulaklarınız, 

Ağzınız, burnunuz, gözleriniz, 

Dinleyin, size sesleniyorum, 

Kulaklarınız duyarsa, 

Hepinizin beyninin içini bilirim, 

Başınızda beyin varsa...', 'Hepinizin ciğerini bilirim,  Hepinizin yüreğini bilirim,  Anlarsınız ya, her nasılsa. Güçlüsünüz, görkemlisiniz,  Ola ki, gençsiniz, güzelsi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tufan Şentürk']::text[], 8.5, '{"poet":"Ahmet Tufan Şentürk","poet_slug":"ahmet-tufan-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/beyin-varsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Türkan', 'soyle-turkan-ahmet-tufan-senturk-yoo52', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SÖYLE TÜRKAN

Bir türkü söyle ki bildiğim dilden

İçinde olmasın hicran, yine hicran

Önce anam ölmüş, sonra babam

Dokunaklı sözler ağlatır beni

Öksüz büyümüşüm Türkan! 

Bir dağ köyünde doğmuşum

Öyle bir dağ köyü ki şehirden uzak

Sen bilmezsin, ben anlatamam

Yüksektir dağları, başı dumanlı

O dağların çocuğuyum

Benim de başım dumanlı

Dumanlı Türkan...

Bir türkü söyle de unuttur bana

Yokluğu, hasreti, çocukluğumu

Bir dağ türküsü olsun, pervasız, hoyrat

Su sesi, kuş sesi ve senin sesin

Bir koro başlasın şöyle keyfince

İçinde olmasın hicran, yine hicran

Söyle Türkan...', 'SÖYLE TÜRKAN Bir türkü söyle ki bildiğim dilden İçinde olmasın hicran, yine hicran Önce anam ölmüş, sonra babam Dokunaklı sözler ağlatır ben...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tufan Şentürk']::text[], 8.5, '{"poet":"Ahmet Tufan Şentürk","poet_slug":"ahmet-tufan-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/soyle-turkan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamzelim', 'gamzelim-selim-aksehirli-646wv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerini ver elime

Lutfen inan bu gunlume

Ihtiyacim var sevgine

Mutluluk vereceyim her gunune', 'Ellerini ver elime Lutfen inan bu gunlume Ihtiyacim var sevgine Mutluluk vereceyim her gunune...', ARRAY['Türk Edebiyatı','Şiir','Selim Aksehirli']::text[], 8.5, '{"poet":"Selim Aksehirli","poet_slug":"selim-aksehirli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gamzelim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gamzelim', 'ben-gamzelim-selim-aksehirli-7q7f8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yureyime serdim umitleri

Unutmadim o gunleri

Seni tanidigimdan beri

Gulmeyi ogrendim, Gamzelim

Ask ne bilmezdim

Bos der gecerdim

Kalbimi sana verdim

Tek seni sevdim, Gamzelim', 'Yureyime serdim umitleri Unutmadim o gunleri Seni tanidigimdan beri Gulmeyi ogrendim, Gamzelim Ask ne bilmezdim Bos der gecerdim Kalbimi san...', ARRAY['Türk Edebiyatı','Şiir','Selim Aksehirli']::text[], 8.5, '{"poet":"Selim Aksehirli","poet_slug":"selim-aksehirli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-gamzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali Kemal''e', 'ali-kemal-e-ziya-gokalp-h9eis', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(ziya Gökalp Malta''da sürgünde iken, Ali Kemal''in yazdığı

düşmanca yazılara bu şiirle cevap vermiştir.) 

Ben Türküm! diyorsun, sen Türk değilsin! 

Ve İslamım! diyorsun, değilsin İslam! 

Ben, ne ırkım için senden vesika, 

Ne de dinim için istedim ilam! 

Türklüğe çalıştım sırf zevkim için, 

Ummadım bu işten asla mükafat! 

Bu yüzden bin türlü felaket çektim, 

Hiç bir an esefle demedim: Heyhat! 

Hatta ben olsaydım: Kürd, Arap, Çerkes; 

İlk gayem olurdu Türk milliyeti

Çünkü Türk kuvvetli olursa, mutlak, 

Kurtarır her İslam olan milleti! 

Türk olsam olmasam ben Türk dostuyum, 

Türk olsan olmasan sen Türk düşmanı! 

Çünkü benim gayem Türkü yaşatmak, 

Seninki öldürmek her yaşatanı! 

Türklük, hem mefkurem, hem de kanımdır: 

Sırtımdan alınmaz, çünkü kürk değil! 

Türklük hadimine ''Türk değil! '' diyen

Soyca Türk olsa da ''piçtir'', Türk değil!', '(ziya Gökalp Malta''da sürgünde iken, Ali Kemal''in yazdığı düşmanca yazılara bu şiirle cevap vermiştir.)  Ben Türküm! diyorsun, sen Türk deği...', ARRAY['Türk Edebiyatı','Şiir','Ziya Gökalp']::text[], 8.5, '{"poet":"Ziya Gökalp","poet_slug":"ziya-gokalp","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ali-kemal-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurt ile Ayı', 'kurt-ile-ayi-ziya-gokalp-jos9l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kurt kocadı, kötürüm oldu, 

Bunu sezen bir genç atı

Yakaladı kurdu yoldu, 

Dedi: ''Haydi tüysüz dayı, 

Yürü, yine yiğitlik sat; 

Dar et bize yeşil yurdu! ''

Piçlerine dedi: ''Fırsat

Kaçırmayın, boğun kurdu! ''

Zavallı kurt öldü, inde

Beş yavrusu kaldı öksüz

Fakat bir kaç yıl içinde

Bunlar birer yiğit, gürbüz

Kurt olarak saldırdılar, 

Yeşil yurttan ayıların

Vücudunu kaldırdılar.

Çocuklarım ibret alın: 

Her bugüne var bir yarın!', 'Kurt kocadı, kötürüm oldu,  Bunu sezen bir genç atı Yakaladı kurdu yoldu,  Dedi: ''Haydi tüysüz dayı,  Yürü, yine yiğitlik sat;  Dar et bize ...', ARRAY['Türk Edebiyatı','Şiir','Ziya Gökalp']::text[], 8.5, '{"poet":"Ziya Gökalp","poet_slug":"ziya-gokalp","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kurt-ile-ayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram gelmiş, neyime', 'bayram-gelmis-neyime-suat-oktay-g3v5b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aman kimseye söylemeyin 

bugün arefe, yarın bayram. 

deliye her gün ya, 

garibana bir, 

bilemedin iki ya da üç gün.. 

Aman kimse bilmesin yarın bayram, 

çocuklar, çocuk gibi sevinecek. 

cicilerini geceden hazır edecek, 

bayram namazına mütakiben, önce kabirler 

ziyaret edilecek sonra el öpüp bahşiş 

toplama yarışı başlayacak. 

bilmesin kimse, 

bugün arefe, 

yarın bayram, ertesi ve ertesi gün de. 

Bayram öncesi telaş, telaş öncesi arefe 

Tepsi tepsi baklava pişirecek(ti)  annem, 

yanına bir de sütlaç 

ve akşam misafirler için kaymaçina 

ama önce çorba, fırında kurufasulye 

ve etli pilav, yenecekti... 

noolursunuz kimse bilmesin bugün arefe, 

yarın bayram. 

Çocuklar gelmesin bana el öpmeye, 

utanırım, boş göndermeye, 

ya da evde yokum demeye. 

ben işsiz bir yazar çizerim, 

bayram gelmiş neyime. 

Sevgim var, versem el öpenlere 

beğenirler mi acep? 

Sevgi para etmiyor, 

işsiz yazara kimse eyvallah demiyor 

al sevgini sok bi tarafına. 

bayram öncesi bugün. 

noolursunuz kimseye söylemeyin. 

bilmesin, yazarın (hala)  işsiz olduğunu. 

Gülyüzünün arefeden solduğunu...

Bugün arefe, yarın...

..bayram gelmiş neyime! 

15 aralık 2001/ ramazan bayramı arefesinin sabahı.', 'Aman kimseye söylemeyin  bugün arefe, yarın bayram.  deliye her gün ya,  garibana bir,  bilemedin iki ya da üç gün..  Aman kimse bilmesin ya...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bayram-gelmis-neyime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramın Olsun', 'bayramin-olsun-suat-oktay-y7dbq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bayramın olsun, beni öptüğün gün.

Yüreğin sevgi, sevgin benle dolsun.

Ben, hani seni öpen, 

dudaklarına sihir konduran adam 

hani sesimi duyduğunda içini titreten ses

Bayramın olsun, beni tanıdığın gün

çocuksu bir gülüş, 

huzur veren bir tebessüm

ya da rüya gibi.

sihiri kucaklasın, 

bayram öncesi arefe olsun, 

beni tanımadan geçen ömrün

bayramın olsun her gün.

ben yanında oldukça 

sevinsin ruhun

masum bir çocukça

bayramın olsun senin de.

çünkü bana hergün bayram

sen yanımda oldukça.

15.12.01', 'Bayramın olsun, beni öptüğün gün. Yüreğin sevgi, sevgin benle dolsun. Ben, hani seni öpen,  dudaklarına sihir konduran adam  hani sesimi duy...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bayramin-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-suat-oktay-1h6vg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğinin orta yeri, 

gül bahçesi gibi; 

sımsıcak busen, 

dokunsan, öpsen... 

sen annem, sen, 

senden gayrı yar, yine sen...

gelsen, görsen

sevsen beni annem... 

sen sevsen, 

yüreğinin ortayerine gömsen, 

gül bahçendeki kelebek

uçmadan son bir defa

sarsan, koklasan annem...

ben ağlasam, 

sen silsen gözyaşlarımı,

ağlarken titrese dudaklarım,

haykırsa yüreğim,

anne, annem, anneciğim; 

''gittiğin yere beni de götür''

geldiğim yerdir gittiğin yer, biliyorum,

kimseye söyleyemiyorum...', 'Yüreğinin orta yeri,  gül bahçesi gibi;  sımsıcak busen,  dokunsan, öpsen...  sen annem, sen,  senden gayrı yar, yine sen... gelsen, görsen ...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/annem-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkyardım Bilgisi', 'i-lkyardim-bilgisi-akif-kurtulus-s1knk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'temizyürek''li mahmut''a 

bütün bir aşkyılı kapıştın siniruçlarınla 

güneşe, kış geldiğinde yer açmak için 

damarlarını ürküterek vücudunu dolaşan kanın 

umurunda olmadı başka hayatları sürçmesi

CESARETİN, ALAY KONUSU OLDU 

ELİNİ KORKAK ALIŞTIRANLAR ARASINDA 

sen de cesur sandın onları 

korkunu anlayacak kadar 

göğüs kafesimdeki yetimim! 

artık malmumu gibi keman yaylarına sürtüyorlar seni 

sen ki hazırdın buna da: 

jangarbarek milesdavis hacıtaşan ve yaylılar 

bir bir boğulurken '' bırakırsan ölürüm '' gürültülerine

HAZIRDIN SADECE BİR SES İÇİN ALDANMAYA

BÖYLECE DÜNYA DERİN OYUKLAR AÇTI SENDE 

kendi kalplerini bile stetoskopla dinleyenler 

buna derinyara diyerek katkı yaptılar literatüre 

ve güncelleşti ilk yardım çantası 

gazetelerin eki olacak kadar 

hem aşk, bazen sargı bezi olmanı ister üçüncü kişiye 

bir başkasının doktoru olmak  

kaldı ki en ciddi yoludur sağlığımızı korumanın 

'' neyin var '' sorusunu ilk soran

bir bilen olur: kim ne kadar aşk ve güçten kalmış 

kabul defteri açılır, kayıt yapılmış, gözlük camı buğulanmıştır

beyaz önlüklülerin vilayetin önünde legale çıktığı bu saatlerde 

tababetin temel bilgisidir, GÖZYAŞLARINI YERALTINDA TUTMAK

AVUCUMUZUN  İÇİNDE OYNADIĞIMIZ  İKİ TAŞ BİLE EZEBİLİR BELKİ BİZİ 

yine de her zaman huzur verir

psikiyatri kliniklerinde ziyaretçi olmak 

çünkü acımak duygusu da bir haraç değil midir 

BIÇAĞI SAPINDAN TUTMAYA ALIŞMIŞ OLANLAR

AĞZINDA YAŞAYANLARDAN BİR ARMAĞAN GİBİ ALIRLAR BUNU

gözler göstere göstere doldurulur 

ve boşalır patlayan flaşlarla 

PATLAR KALB

boşalır başını oraya koymuş doktor', 'temizyürek''li mahmut''a  bütün bir aşkyılı kapıştın siniruçlarınla  güneşe, kış geldiğinde yer açmak için  damarlarını ürküterek vücudunu dol...', ARRAY['Türk Edebiyatı','Şiir','Akif Kurtuluş']::text[], 8.5, '{"poet":"Akif Kurtuluş","poet_slug":"akif-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ilkyardim-bilgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Kaderinde Var', 'askin-kaderinde-var-selim-aksehirli-9hx33', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seven gonuller bir olsada

Dokulen yapraklar solsada

Sevgiler sonsuz olsada

Ayrilik, askin kaderinde var

Birgun guler, birgun aglar

Birgun sever, birgun yanar

Ne biliyim artik, 

Ayrilik, askin kaderinde var', 'Seven gonuller bir olsada Dokulen yapraklar solsada Sevgiler sonsuz olsada Ayrilik, askin kaderinde var Birgun guler, birgun aglar Birgun se...', ARRAY['Türk Edebiyatı','Şiir','Selim Aksehirli']::text[], 8.5, '{"poet":"Selim Aksehirli","poet_slug":"selim-aksehirli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askin-kaderinde-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Geçtikce', 'zaman-gectikce-selim-aksehirli-swopn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günler su gibi akıyor

Su desen, durmak bilmiyor

O zaten zamanı hatırlatıyor

Zaman geçtikce, içim kararıyor

Huzurum yok, ah bir bilsen

Guvenecek insan yok, ah bir gorsen

Tutunacak dal yok, ah bir tutabilsem

Zaman gectikce, kayboluyorum', 'Günler su gibi akıyor Su desen, durmak bilmiyor O zaten zamanı hatırlatıyor Zaman geçtikce, içim kararıyor Huzurum yok, ah bir bilsen Guvene...', ARRAY['Türk Edebiyatı','Şiir','Selim Aksehirli']::text[], 8.5, '{"poet":"Selim Aksehirli","poet_slug":"selim-aksehirli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zaman-gectikce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamzelim Benim', 'gamzelim-benim-selim-aksehirli-2y8f0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Guzelligine  kiyamayan

Gozlerine dayanamayan

Sana yanan

Ben, Gamzelim

Yureyime serdim umitleri

Unutmadim o gunleri

Seni tanidigimdan beri

Gulmeyi ogrendim, Gamzelim

Ask ne bilmezdim

Bos der gecerdim

Kalbimi sana verdim

Tek seni sevdim, Gamzelim', 'Guzelligine  kiyamayan Gozlerine dayanamayan Sana yanan Ben, Gamzelim Yureyime serdim umitleri Unutmadim o gunleri Seni tanidigimdan beri Gu...', ARRAY['Türk Edebiyatı','Şiir','Selim Aksehirli']::text[], 8.5, '{"poet":"Selim Aksehirli","poet_slug":"selim-aksehirli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gamzelim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-selim-aksehirli-ls6ew', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eger beni gorursen, bana sarilip opermisin 

Sararmisin beni eskisi gibi

Opermisin beni oyle derinden

Seni seviyorum deyip beni kollarinda sikarmisin

Sana bir demet gul versem

Koklarmisin onlari derinden

Bana bes saniye bakip

Senden ayrilmam dermisin

Dalarmisin gozlerime, bes saniyeden fazla

Ya beni taniyamassan, 

Tanidiktan sonra bana kosarmisin

Askimi unutmadim, unutamadim dermisin', 'Eger beni gorursen, bana sarilip opermisin  Sararmisin beni eskisi gibi Opermisin beni oyle derinden Seni seviyorum deyip beni kollarinda si...', ARRAY['Türk Edebiyatı','Şiir','Selim Aksehirli']::text[], 8.5, '{"poet":"Selim Aksehirli","poet_slug":"selim-aksehirli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eger-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batan Güne', 'batan-gune-erol-sen-1gwnu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün batarken gündüzden

Karanlığa akar düşünceler

Yaşanan gündeki hayatlar

Işık olur geceye

Belki kandil belki fener

Aydınlatınca hayatların gece ışığını

Yıldızlar ve ay da şahit aydınlığa

Gönüller bir başka gün batımına...

13.5.2002', 'Gün batarken gündüzden Karanlığa akar düşünceler Yaşanan gündeki hayatlar Işık olur geceye Belki kandil belki fener Aydınlatınca hayatların ...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/batan-gune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Çocuktuk', 'biz-cocuktuk-mustafa-ozke-3e1zp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seksen öncesiydi 

biz çocuktuk 

aklımız ermezdi herşeye 

geceleri silah sıkarlardı 

gündüzleri çekirdeklerini toplardık 

askerler geçerdi yanımızdan 

onlara el sallardık 

peşlerinden koşardık 

karnımız acıkırdı 

fırında ekmek beklerdik 

tüp kuyruğunda akşam ettiğimiz olurdu 

bir kilo şeker için bakkalın evine giderdik 

kuru ekmeğin tadını damağımıza kazırdık 

güvercinler konardı penceremize 

suyla ıslatıp onlarla paylaşırdık 

bir kara zeytini üçe bölerdik 

gravyer peyniri iki öğünde yerdik 

ne bulursak ona şükrederdik 

sokaklarda yalınayak gezerdik 

yollara kömürle çizgiler çizerdik 

aklımız ermezdi herşeye 

biz çocuktuk 

seksen öncesiydi...', 'seksen öncesiydi  biz çocuktuk  aklımız ermezdi herşeye  geceleri silah sıkarlardı  gündüzleri çekirdeklerini toplardık  askerler geçerdi ya...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/biz-cocuktuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıksın', 'isiksin-deger-ulas-turan-kzue8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne anlamışsak kardır hayatta, 

Geleceğe ne kadar güvenmişsek kardır. 

Övünçlerimiz öyle mahmurdur ki, 

Sevginde yaşamayı kılar 

Unutma, 

Işıksın sen...', 'Ne anlamışsak kardır hayatta,  Geleceğe ne kadar güvenmişsek kardır.  Övünçlerimiz öyle mahmurdur ki,  Sevginde yaşamayı kılar  Unutma,  Işı...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/isiksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuhaf', 'tuhaf-deger-ulas-turan-v9mx9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tuhaf olan, 

Yaşamı içinde sindirip 

Kokuşan ruhunu 

Süslemeye çabalamasıydı. 

Her son 

Bir yalan ertesi. 

Salık heyecan içinde, 

Komplike düşünceler tutsağı. 

Ve kabulsüz doğruların 

Işığından kaçan, 

Yabancı bir ev sahibi 

Tuhaf değil yaşadığında hayat.', 'Tuhaf olan,  Yaşamı içinde sindirip  Kokuşan ruhunu  Süslemeye çabalamasıydı.  Her son  Bir yalan ertesi.  Salık heyecan içinde,  Komplike d...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tuhaf-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzkarası', 'yuzkarasi-necip-fazil-kisakurek-5qgjv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni şafak vakti bir el dürtükler: 

İdam mahkumu, kalk, bekliyor savcı! 

Zindan avlusunda öter düdükler; 

Bir güneş doğar ki., zakkumdan acı...

İpten indirilir, yine uslanmam, 

Bela...Bela bende yakıcı şehvet...

Bir olur, ateşi görmemle yanmam; 

Dipsiz uçurumda kaçılmaz davet.

Bak nasıl silinir bu yüz karası; 

Elimde, ölümü öldüren silah, 

Alnımda tozpembe secde yarası, 

Lugat kitabımda tek isim: Allah...', 'Beni şafak vakti bir el dürtükler:  İdam mahkumu, kalk, bekliyor savcı!  Zindan avlusunda öter düdükler;  Bir güneş doğar ki., zakkumdan acı...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuzkarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilekçe', 'dilekce-sadettin-kaplan-69z6v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilen beni ben sanır,

                          Bilse beni utanır.

                          Ne falcı beni tanır,

                          Ne gösterir fal beni...

İzler bin ifrit beni, her gün ''sendeniz'' diye,

Bin yola sürdüm atı, Yârab ''senden iz'' diye,

Kandırdı İblis beni, ''ben dağ, sen deniz'' diye; 

Bin parçaya ayırdı koştuğum kumsal beni...

                           Geçmedim eleğimden,

                                Pişmanım dileğimden,

                                    Çöz bağı bileğimden; 

                                         Sal beni! ..

Zehri ilaç yerine sundular ''uslan'' diye,

Sırtımı uçuruma verdiler ''yaslan'' diye,

Büyüttüm gözlerimde kediyi ''aslan'' diye; 

Öfkenin sahrasında çıldırttı çakal beni! ..

                            Yaydan çıkmış okum ben,

                                 Kalıbımda yokum ben,

                                      N''olur bedenim de sen

                                           Kal beni! ..

Ulu yolculuğuma yok iken hazırlığım,

Artmakta günden güne körlüğüm sağırlığım,

Çökertti dizlerimi gereksiz ağırlığım; 

Bunca yıl taşımaktan bıktı bu hamal beni...

                             Kapılıp da fendine,

                                 Bağlandım kemendine,

                                     Köle etti kendine

                                         Mal beni...

Akşamına uzanıp sabahından gönlümün,

Uçurdum mürşidini dergâhından gönlümün,

Beni sorumlu tutup günahından gönlümün; 

Ne sofî selâm verir, ne arar abdal beni...

                              Zararımdır uttuğum,

                                  Aklımdır uyuttuğum,

                                      Taşımaz şu tuttuğum

                                          Dal beni...

Ayağıma dolanan yılan oldu huzurum,

Kahroldu iyiliğim övüldükçe kusurum,

Ne olur ya İsrâfil,  bir an farzet ki ''Sûr''um; 

Ebedî bir hayatın şafağında çal beni! ..

                              Bu son dilekçem sana,

                                    Uyamadım zamana,

                                         Yârab, el uzat bana; 

                                            Al beni! ..', 'Bilen beni ben sanır,                           Bilse beni utanır.                           Ne falcı beni tanır,                           ...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Kaplan']::text[], 8.5, '{"poet":"Sadettin Kaplan","poet_slug":"sadettin-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/dilekce-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lâl ve Gül', 'l-l-ve-gul-emre-gumusdogan-ybfi9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bilmediğim şarkıların ezgisine 

karışıyor yazamadığım sözcükler 

kronikleşti uykusuzluğum 

böbreklerimdeki sancı kadar 

usumda sarkaç gibi 

yitik anılarımı saklayan 

sinir uçlarıma asılı çan 

tükendi direncim bağışla beni 

neresine sığınsam 

topu topu bir yalnızlığım var 

geçtiğimiz alev kızıllığından 

geriye kalan 

lâl ve gül 

sökemedim göçebe ağrıyı 

esmer gecelerimden 

şaklıyor susuşlarımda 

kötü büyülerin kamçısı 

intiharların şah dediği gerçek 

bahar fırtınası -umutkıran- 

yaralanan baktığım aynalarda 

kendini gizleyen suretim 

kırgın değilim 

kalbimde gülden bir çizik 

fetihten sonra terkedilmiş ülkeyim 

anımsanan 

aşk ve zûl', 'bilmediğim şarkıların ezgisine  karışıyor yazamadığım sözcükler  kronikleşti uykusuzluğum  böbreklerimdeki sancı kadar  usumda sarkaç gibi  ...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/lal-ve-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair Üçleme', 'aska-dair-ucleme-emre-gumusdogan-be31j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I - dağların ıtırı 

bir düşte çıktık içimizdeki yokuşları 

uçurtmalar ekip kederimize 

ellerimizde nar bereketi... 

dağların ıtırıydı üzerimize 

bahar yorgunluğu gibi çöken 

terimiz akarken köklerine 

geceyi resimlerdi sesin 

- hem var hem yok olduğumuz - masal dilince 

sevdalarda han duvarıydık... 

II - özlem 

özlemin kaç halini söylesem 

yüzünde gezinir ellerim 

kum tükenir saatimde 

ne zaman o anlamlı sessizliği 

kilitlesek gözlerimize 

bir meltemde batık kalırız... 

III - o kent 

seni tanıdığım kentte 

çürümüş bir halatın ucunda - iskelede - 

sesin bekliyor beni... 

çöreklenende kapımıza açaray 

bağ makası bileklerimizde 

budanalım aşka 

işportaya düşmeden 

yaşadık ve yenildik aşka... 

küskünlüğümüz yok kendimizle 

- şimdi o kent - yüzümüz gibi eskir bizimle...', 'I - dağların ıtırı  bir düşte çıktık içimizdeki yokuşları  uçurtmalar ekip kederimize  ellerimizde nar bereketi...  dağların ıtırıydı üzerim...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aska-dair-ucleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Düşündün mü', 'hic-dusundun-mu-emre-gumusdogan-yxn4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bilirim akşamın eğrildiği yeri 

çiçekli dal bakışlarından 

ve güneşi öpmüş dudaklarından 

inadına sarı sarmaşık gülce 

gelirsin sokağa sızarak yırtmacından 

bakışın rahminde gelişir aşk 

sözün tılsımında duldasında dokunuşun 

ay taşar yatağından 

sahi ay neden taşar yatağından 

hiç düşündün mü 

konuşur gülüşür susarız mahcup 

yaşamı eksilterek usanmadan 

akarsın gecenin yivinden 

aydınlığa gömülen yıldızlar gibi 

usuldan çekip gitsen de 

yakınmam yokluğundan 

açık bırakılmış pencerelerden 

şiirime sinersin 

sahi neden şiir kokarsın şiirim sen... 

hiç düşündün mü', 'bilirim akşamın eğrildiği yeri  çiçekli dal bakışlarından  ve güneşi öpmüş dudaklarından  inadına sarı sarmaşık gülce  gelirsin sokağa sızar...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hic-dusundun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dünya İki Beden Dar Bana', 'bu-dunya-i-ki-beden-dar-bana-emre-gumusdogan-epdrk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mumyaladı tanrı 

antik kentte su yüzüne vuran cesetini 

çubuğunu tutuşturdu 

dolarları vaftiz eden - beyaz adam - 

Musa adına bir yahudi 

porselen dişlerini temizledi 

kürdana yapıştı Filistinli çocuğun kemikleri 

kendini astı konduğu dalda saksağan 

kriz bitti dedi kerizlere 

alkış aldı politikacı 

savunmayı yerinde buldu mahkeme 

- tüylü doğmalıydı yetimler de - 

kapattı panjurlarını köstebek 

ölü çocuk doğdu 

prematüre demokrasiden 

dadanmış haramiler genç kadının terine 

çakallar turnuvası düzenlediler 

dişiliğini kırbaç niyetine kullanan kadın 

okşadı küvetten çıkardığı bacağını 

küme düştü hergelenin biri yatakta 

- bu sahne bir filmden - 

globalleştikçe orospulaştık dedi 

bir eşcinsel 

mahallenin orospusu aysel 

tam da konuşulurken mahalle kahvehanesinde 

alanlardan ayak sesleri geliyordu 

esnedi tembel demokrat 

- katılmak ya da katılmamak - işte bütün mesele 

böyle işkence görmemişti 

gençliğini - Ziverbey - de bırakan adam 

fırlattı kumandayı ekrana 

bu dünya iki beden dar bana 

kirli sakalıyla Che 

ta şuramda ağladı...', 'mumyaladı tanrı  antik kentte su yüzüne vuran cesetini  çubuğunu tutuşturdu  dolarları vaftiz eden - beyaz adam -  Musa adına bir yahudi  po...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bu-dunya-iki-beden-dar-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gülüm', 'gel-gulum-sair-khan-n4i8c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat kahpe bir gemi, kader zorunluluk zamanı, 

Bu gemide inse de başıma hep hüzün taşları, 

İçime bent yapsam da kanlı gözyaşları, 

Ama sen doğdun ve senin adını 

Senin uğruna senin umuduna tüm nakışları

İlmik ilmik attım hadi ne olur gel gülüm

Yollar uzun engebeli, yağmurlu fırtınalı

Mazime dönüp bakıyorum ellerim gönlüm hep kanlı

Sadece seni özler ey güzelliği olmuş şanı

Gel ne olur dikenli bahçemin gülü ol.

Damarlarımda çağlayan misali akan kanım oldun

Bir inilti  bir acı, bir sıkıntı gönülde oldun, 

Kanlı Gözyaşı oldun şakaklarımda

Damla damla  gel ne olur Ey sevgili

Ölüm kol gezse de sokaklarımda yanı başımda

Hayattan kesmişsem de ümidi 

Zehirde olsa elinden özlemişim içmeyi katranı

Ne olur aşkım azrail den önce gel', 'Hayat kahpe bir gemi, kader zorunluluk zamanı,  Bu gemide inse de başıma hep hüzün taşları,  İçime bent yapsam da kanlı gözyaşları,  Ama sen...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gel-gulum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacaksın Heredot', 'aglayacaksin-heredot-adnan-ates-8kay1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey! Mağaralar şehri, 

Bizansın şövalyeleri

Moğol`un orduları

yağmalayamadılar seni

Dağlarına kar düştü

mirasına kondular

hayırsız evlatların.

ikibine bir kala

projeler cizdiler

volt ve amper için

Seni duymadılar.

Varıp gitmezmisin

Bosfor`a

kardeşin Bergama`ya

akşam haber bülterinde

belki görür mebus bey, 

sabah gider kürsüye mebus bey, 

atar yumruk mebus bey.

Kartpostallar kaldın

gönlümüze sığdıramadık seni.

ikibinli yıllara

adağımız oldun.

Sorun yoktu sende

evvel zaman içinde.

Sende çevre vardı

geçmiş zaman kipinde

Sen günlerini sayarken

acep neyin peşinde? 

Her şeyine rağmen

Arkeolok yok! 

Yaşasın enerji sorunu.

Çevre örgütleri yok? 

Kahrolsun enerji sorunu.

Anlatıyordu seni

ibn-ü Ezrak-Farıki

Hısn-ı Keyfa`da nazırlık günlerini.

Bitiremiyordu seni, 

Derviş Mehmed`in oğlu

Enderunda okurken bile

rastlayamadı

senin gibi musikiye.

Nedimlik yaparken sarayda

seni anlatıyordu, 

padişah murad`a

Unkapanı`nda doğmuştu, 

kendini sende bulmuştu, 

yedi düvel gezmişti, 

misalini görmemişti.

Hanlar hamamlar gördü

senin gibisini görmemişti.

Ey! Mezopotamya kapısı

şantiyeler pusu kurmuşlar

dağlarına ovalarına.

Bekleyeceksin dozerleri, 

formenleri ve işçileri.

Kesecekler yolunu Dicle`nin

setler kurup duvarlar örecekler.

Dicle seni boğacak

ihanete uğrayacaksın.

Yüzyılların Dostu, 

zor günlerin dostu, ab-ı hayatın/Dicle

senin brütüs`ün olacak

Sezar olup hancerleneceksin

Söylense idi inanmiyacaktın.

Dicle dost`tur kardeştir

diyecektin.

Raman sessiz kalmaz diyecektin.

Dicle ne yüzle varır El-Cızir`e

Fırat ne diyecek? 

Ama gel gör ki

senide kapalı zarf usulü

hisselediler, hisettirmeden.

saman aldınta Dicle`yi yürüttüler üstüne

Antik şehir dediler, 

Hellen görmüş dediler.

Görücüye çıktın seni sevenine vermediler.

Ağla Ey! Efes

ve sen Ey! Kapadokya.

Ey! Hasuni, kardeşinizi öldürdüler

Ey! Edessa ve Tuşpa, Nisibis ve Martropolis.

Ve Ey! Sevdalıları

sevdanız sulara gömüyor

sedası kesiliyor

bir daha gelmemek üzere', 'Ey! Mağaralar şehri,  Bizansın şövalyeleri Moğol`un orduları yağmalayamadılar seni Dağlarına kar düştü mirasına kondular hayırsız evlatların...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ateş']::text[], 8.5, '{"poet":"Adnan Ateş","poet_slug":"adnan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/aglayacaksin-heredot-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Hamileyim', 'ben-sana-hamileyim-faik-uretmen-ubnby', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sana hamileyim; 

Sevda yüzlü çocuklara gebe, 

Sen git, hiç durmadan

Kürtajlar yaptır kalbine...', 'Ben sana hamileyim;  Sevda yüzlü çocuklara gebe,  Sen git, hiç durmadan Kürtajlar yaptır kalbine......', ARRAY['Türk Edebiyatı','Şiir','Faik Üretmen']::text[], 8.5, '{"poet":"Faik Üretmen","poet_slug":"faik-uretmen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ben-sana-hamileyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ki...', 'ask-ki-emre-gumusdogan-i9f5n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aşk ki... sevebilmekse umutsuzca umudu 

özlemekse serüveni belirsiz yağmurları 

yanmasıysa suyun damar çeperlerimde 

bir çıngısı yetiyorsa bakışlarının yangınlarıma... 

bil ki yüreğimde damıtıyorum 

son şiirimsin... 

sunağına koymuş başımı... 

ya kal mevsimler ötesinde / boşlukta 

bir meteor gibi zamansız... 

sözcükler yükle kehanetine 

bölüştüğümüz düşlerden 

tamamlayamadığım yanımda 

bir masaldan diğerine 

büyüttüğüm imgeler gibi 

ağulu... şaşkın... 

ya da gitme kendini unutup unutup da içimde 

gövermiş peynir rakı tadında 

süz mavileri mavilerden 

güneş ektiğimiz tenlerden 

süzülen terler adına 

bölüştüğümüz ekmeğin şarabın hatırına 

göğüsleri ak köpüklü rahvan atları 

sal damarlarına...', 'aşk ki... sevebilmekse umutsuzca umudu  özlemekse serüveni belirsiz yağmurları  yanmasıysa suyun damar çeperlerimde  bir çıngısı yetiyorsa b...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce', 'i-nce-atilgan-alemdar-mtxbf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'denize düş-ince ay 

karanlık boyunca ben 

bende bir ay-dünlük 

gözlerimde çifte dolunay

denize düş-ünce ay 

karanlık boyunca ben 

bende bir ay-dınlık 

gözlerimde çifte dolunay

denize ince bir ay düşünce 

karanlık boyu bence 

bende dünlük bir ay 

gözlerimde çifte dolunay

seni düşleyince', 'denize düş-ince ay  karanlık boyunca ben  bende bir ay-dünlük  gözlerimde çifte dolunay denize düş-ünce ay  karanlık boyunca ben  bende bir ...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ince-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben İki Kişiydim O Yaz / Göl Mevsiminde', 'ben-i-ki-kisiydim-o-yaz-gol-mevsiminde-emre-gumusdogan-hfzif', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben iki kişiydim o yaz / göl mevsiminde 

tek tek ve bütün 

birisi sendin kesin 

içimdeki boşluğu aşarak 

yerinde kullanılan onurlu bir sözcük gibi 

kuruluyordun cümlelerime 

imgeler değildi artık hamağımı sallayan 

incelten zamanı 

ve büyüten geceyi geceden öteye 

geceden ötesi 

nar çiçeği sabahlara taşınan 

tetiği çekilmiş yaşamdı 

ben iki kişiydim o yaz / göl mevsiminde 

birisi sendin kesin 

birisi sıyrılmıştı kendisinden çırılçıplak 

-çıplaklık gelişimizde ve gidişimizde vardı 

ölmeye başlardı her şey daha ilk adımında- 

çıplaktık... kendimizdik... 

başlangıcı olmayan masallarda 

çiğnenmiş kimlik ve kişiliklerimizden uzak 

korkuyorduk... yalnızdık şaşkın ve şaşırtıcı 

bir basmada desendik... tek tek ve bütün 

tenimize güller döşerdi güneş turuncu adımlarıyla 

genç kız nefesi kadar sıcak 

sıcaktı hazirandı yazdı 

çıplaktık... zamanı atmıştık eski bir giysi gibi sırtımızdan 

zaman yoktu... 

zaman yoktu belki de... 

mine çiçekleri miydi zaman / kısa ve dolu 

damarlarımızda yavaş yavaş akan 

bazan susar kendini örterdi kendisiyle 

zaman yoktu / belki de 

anılardı... anılarda yüzlerdi 

ıslak kayıp bir kent gibi suda 

sazdı göl mevsiminde zaman 

taş binalardı iri tokmaklı kapılardı 

zaman durmuştu İznik''te 

belki de zaman yoktu 

ama ben iki kişiydim o yaz / göl mevsiminde 

birisi sendin kesin 

birisi kendini yaratıyordu sil baştan...', 'ben iki kişiydim o yaz / göl mevsiminde  tek tek ve bütün  birisi sendin kesin  içimdeki boşluğu aşarak  yerinde kullanılan onurlu bir sözcü...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ben-iki-kisiydim-o-yaz-gol-mevsiminde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sesinle Sev', 'beni-sesinle-sev-emre-gumusdogan-sos5v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''saklı sular''ımda aralık bir kapıda duran fotoğrafım (*)

nasıl anlatsam / gözlerimde naftalinli yalnızlık 

çıplak bir balkon gibiyim / şubat üstelik 

birazdan ay dallarını çarpacak pencereme 

köylü kızın eteğine topladığı 

ham erik tadına alışamadığım geceler 

yozlaşmışlık kirlilik 

beni sesinle sev 

sesim eksik 

gideceği yönü unutmuş toy bir bulut gönlüm 

şubat üstelik ve ay penceremde 

badem çiçeği erkenci anılar / uç verir 

-anılar ki eski kesik- 

o arsız müzik kemire dursun geceyi 

bilirim her aşk sonrakine tetik 

beni sesinle sev 

sesim eksik 

anımsar mısın 

dünyanın en yosması iken koynumda 

teninde yonca biçtiğim geceler 

çoruhlaşırdın / sınanırdı nefesim 

şimdiki aşklar ultrasonik 

sevişmeler sanal / orgazmlar sentetik 

beni sesinle sev 

sesim eksik', '''saklı sular''ımda aralık bir kapıda duran fotoğrafım (*) nasıl anlatsam / gözlerimde naftalinli yalnızlık  çıplak bir balkon gibiyim / şubat...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/beni-sesinle-sev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yanılgıysa Söyle', 'bir-yanilgiysa-soyle-emre-gumusdogan-ec1p3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'okşandıkça çoğalan fesleğen tenlim 

hangi kirpiğine ay oturmuş 

iğde ılgın yalımları yapraklarında 

hangi öpüşlerin tınısı dudaklarında 

kaç baharım yandı bakışının çıngısıyla 

hangi mevsimsiz dönencelerde yuvalanmış 

fotoğraftan taşan gözlerin 

suydun... içemediğim 

koyaklarımdan akıp giderken 

yetinmezliğimiz eskirdi usumuzda 

sen hep vardın / meraklı çocuktun gözlerimde 

saçların çağlarıma akardı 

ben kıyıda doğmuştum 

martı kanadı çizerdi ufkumu 

bir çiçek gibi delicesine yalnızlıkla yeşerirdim 

sen hep vardın / meraklı çocuktun gözlerimde 

yeni anlamlar yüklemek istediğimde bakışlarına 

gözlerin fotoğraftan taşardı 

gözlerin geceydi 

gece kadın gibi kollarımda 

köpüklerini söndürürdü avuçlarıma 

bir yanılgıysa söyle 

sen hep vardın / geceydin / kollarımdaydın 

meraklı çocuktun gözlerimde...', 'okşandıkça çoğalan fesleğen tenlim  hangi kirpiğine ay oturmuş  iğde ılgın yalımları yapraklarında  hangi öpüşlerin tınısı dudaklarında  kaç...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-yanilgiysa-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batarken', 'gun-batarken-ask-i-memn-5s95w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tüm kainat boyun büker 

sular çağlar gün batarken

cismim neş''e ile güler

ruhum ağlar gün batarken

bir kızıllık sarar arşı 

söylenir yalnızlık marşı

kederlerim bana karşı

rüchan sağlar gün batarken

kimi bir çiçek adına 

kimi şanlı ecdadına 

kimi nazlı bir kadına

gönül bağlar gün batarken

yakamozlar vurur göle

şarkı söyler bülbül güle

sanki çırılçıplak çöle 

döner dağlar gün batarken', 'tüm kainat boyun büker  sular çağlar gün batarken cismim neş''e ile güler ruhum ağlar gün batarken bir kızıllık sarar arşı  söylenir yalnızlı...', ARRAY['Türk Edebiyatı','Şiir','Aşk-ı Memnû']::text[], 8.5, '{"poet":"Aşk-ı Memnû","poet_slug":"ask-i-memn","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-batarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıktı Sular', 'karanlikti-sular-emre-gumusdogan-pe81j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sedef kutuydu gözleri / içime baktı 

mayıstı ay vardı karanlıktı sular... 

tutunur gibi bir küpeşteye 

içime baktı 

asılı kaldı bakışları 

yılların zıpkın yarasında / kanattı 

gece uzun geldi / içim ıslandı 

atamadım kendimi sokağa 

ölümün saksısına dikildim 

yeni yağmurlarla yeşeremem ki...', 'sedef kutuydu gözleri / içime baktı  mayıstı ay vardı karanlıktı sular...  tutunur gibi bir küpeşteye  içime baktı  asılı kaldı bakışları  y...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/karanlikti-sular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Aslında Kendimize Sürgündük', 'biz-aslinda-kendimize-surgunduk-emre-gumusdogan-9q47c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'anlaşıldıkça karmaşıklaşan yaşamın 

tenhalığını sorgulardık 

kendimizi kapattığımız açmazlarda 

intiharlar maviliğini salardı bileklerimize 

kaçınılmaz sanırdık 

oysa derinlikler vardı ufkumuzda 

çıkışlar vardı 

boğulurken sığlığın anaforlarında 

kimdik kendimizi kendimizle aldattığımız geceler 

dizeler almasa da susukunluğumuzu 

ayrı avuçlarda yeşerirdi gerçek 

mevsimlere taşınırdı yarım öyküler 

bir umut çoğalırdı herşey tükenirken 

saydam bir soluk gibi alıp verdiğimiz 

günleri yaralardık ivediliğimizden 

birde sakıncalı yanımız vardı 

sakınırdık kendimizi kendimizden 

sakınırlardı herkesi bizden 

muhbirlik vardı ihanet vardı 

sorguladığımız ve sorgulandığımız geceler 

serserice güncemize düşerdi 

şizofren kuyularda yitirmiştik gözlerimizi 

bakamazdık yılları aralayıp anılara... kördük... 

kuşatılmıştık... 

uçurtmalar değin özgürdük 

gitmeliyiz derdik 

demirlerimizin pas tuttuğu limandan 

gitmeliyim gitmelisin gitmeli herkes 

kendinden kaçıp kendine... 

ve gittik 

kapattığımız kapıların ardında kendimizi bıraktık 

kendimizi bulduk açtığımız kapılarda 

sadece yüzler eskidi albümlerde 

biz aslında kendimize sürgündük 

şimdi 

onaralım demiyorum yaşamın kırık dökük yanlarını 

yaratalım yeniden 

geç kalmış değiliz 

hatta erken 

yontuların bile dili umarı varken 

irkilirken kasıklarımızda doğum sancısı 

doğuralım kendimizi kendimizden', 'anlaşıldıkça karmaşıklaşan yaşamın  tenhalığını sorgulardık  kendimizi kapattığımız açmazlarda  intiharlar maviliğini salardı bileklerimize ...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/biz-aslinda-kendimize-surgunduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-emre-gumusdogan-qozvr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu akşam masada 

bir sen 

bir gül 

bir de Ege var 

Ege üç yaşında 

gözleri yakamozlu bir kız 

gözleri 

Akdeniz mavisine yatmış 

mor mercanlar 

Gemlik''te 

güneş ışıkları 

/son kez su içmeye yönelen 

marallar gibi ansızın/ 

körfeze yönelirken 

gülüşlerin 

mevsimsiz çiçekler 

açıyor şiirlerimde 

o an düşüyor 

özlemin kırağısı kaldırımlarıma 

şaşakalmış el oluyorum kürelerinde 

rotasından çıkmış öpüş 

suskunluğuma başkaldırıyor anılar 

kızıyorum kahrolası ellerime 

rüzgar gibi geçti diye saçlarından 

kanatlarına anason sinmiş bir martı gibi 

gecerken gökleri çoğaltarak yüreğimden 

yaşlı bir kestane ağacı gibi 

duruyorum masanın poyrazında 

ve masada 

bir sen 

bir gül 

bir de Ege var', 'bu akşam masada  bir sen  bir gül  bir de Ege var  Ege üç yaşında  gözleri yakamozlu bir kız  gözleri  Akdeniz mavisine yatmış  mor mercanla...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bu-aksam-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-sair-x-factor-lovo4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin en koyu renginde 

Gökte bir yıldız kayar 

Bilirsin o an herkes bir dilek tutar 

Bende farkında olmadan seni tutmuşum 

Oysa yıldızlar tutulamaz unutmuşum 

Ben mehlika yıldızını çok severim ve süreyya yı 

Hatırladığımda unutmayı 

Unuttuğumda bile sana şiir yazmayı 

Ben mevlanadan öğrendim insanları anlamayı 

Ve yunustan sevgiyle bağlanmayı 

Bir üveyik kuşundan sevgiyi aşkı 

Depemde öğrendim yıkılmayı 

Ve her yıkılışımda dimdik ayakta durmayı', 'Gecenin en koyu renginde  Gökte bir yıldız kayar  Bilirsin o an herkes bir dilek tutar  Bende farkında olmadan seni tutmuşum  Oysa yıldızlar...', ARRAY['Türk Edebiyatı','Şiir','Şair X_factor']::text[], 8.5, '{"poet":"Şair X_factor","poet_slug":"sair-x-factor","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yildizlar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gülüş', 'bir-gulus-sair-x-factor-odnvm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gün bütün gülücukleri sana göderiyorum 

Güneş kadar değil ama yüreğimin sıcaklığında 

Beni tanımaya çalışma senin bildğin kadarım 

Ben seninle bu gün değil bir ömür varım 

Bu gün 9 nisan yüreğim seninle yeniden doğacak 

Ömrümün ilk değil ama en güzel baharı belkide 

Bütün gülücüklerimi sana gönderiyorum sevgiyle 

Senin adın hep unutmadıklarımın arasında olacak 

Adın hep akılda olcak dün gece seninle uyudum 

Bu gün uyandığımda yüreğimde senin adınıbuldum 

Farkında değilsin biliyorum, ben senin oldum 

Ben seni bütün gülüşlerde, şiirlerde seviyorum..', 'Bu gün bütün gülücukleri sana göderiyorum  Güneş kadar değil ama yüreğimin sıcaklığında  Beni tanımaya çalışma senin bildğin kadarım  Ben se...', ARRAY['Türk Edebiyatı','Şiir','Şair X_factor']::text[], 8.5, '{"poet":"Şair X_factor","poet_slug":"sair-x-factor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-gulus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sana Şiirlerim', 'hep-sana-siirlerim-sair-x-factor-nnj8f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu kalbimden geçenleri sana anlata bilsem 

İşte o zaman en güzel şiirleri sana yazardım 

Kim bilir bir şiirin arkasına saklanır 

Yüreğimdekileri sana şiir diye yazardım 

Belki şiirimin başlığı olmazdı 

Ama sonu da hiç gelmezdi 

Her seferinde çok güzel dersin 

Sana yazıldığını bilmeden teşekkür edersin 

Oysa şiirlerimin arkasına saklandığımı 

Şiirlerimden başkası bilmezdi 

Ömrümün şiirine ilk kez istedim dokunmak 

Ve bir üveyiğin kalbinde ki..Dedim. 

Aşkların en güzelini çalmak 

Bir şirin ardına da sana varmak istedim 

Bir şarkıda der ki 

'''' Nefes almak hüner değil 

Seninle ölmek istiyorum '''' 

Oysa ben seninle ölmek değil 

Seninle hayatı göze almak istiyorum 

Kim bilir bir şiirin arasına saklanır 

Yüreğimdekileri sana şiir diye yazardım 

Şiirlerimin arkasına saklandığımı 

Şiirlerimden başkası bilmezdi 

Dedim ya bu şiirlerin sonu hiç gelmez di 

Geceleri seni düşünür sana şiir yazar 

Her gecenin sabahında güneşi yakalardım 

Sevgilerin en güzelini yüreğimden süzer 

Her gün batımın da sana ağlardım', 'Şu kalbimden geçenleri sana anlata bilsem  İşte o zaman en güzel şiirleri sana yazardım  Kim bilir bir şiirin arkasına saklanır  Yüreğimdeki...', ARRAY['Türk Edebiyatı','Şiir','Şair X_factor']::text[], 8.5, '{"poet":"Şair X_factor","poet_slug":"sair-x-factor","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hep-sana-siirlerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haketmedim', 'haketmedim-sadullah-bayar-vg0xv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çamurdan batak, sevgiden uzak

ve kandan sıcak bir anda terkettim  çocukluğumu

yeni vazgeçmişken çamurlu sokaklarda

çelik çomak oynamaktan

körpecik yüreğim  sığmaz oldu bedenime

çocukluğumdan tek hatırladığım

önü delik ayakkabılarım

ve komşumuzun oğlundan aldığım lastik bir toptu zaten

yo! hiç kimseye suç bulmuyorum

yalnız isyan ediyorum.

ben bu hayatı hak edecek ne yapmıştım ki? 

şerefice yaşarken hep kaybettiğim için mi? 

yoksa şerefsiz bir kurşun gibi patlamaya 

hazır olduğum için mi? 

haketmemiştim elbet 

şerefsizce çalıp cırpmayı

köprü altında bali çekmeyi

yahut parasızlık yüzünden ekmek çelmeyı

hayır idam sehpasında ter dökmeyi haketmemiştim elbet

çocukluğum hasretim, 

çocukuğum gözyaşlarım, 

çocukluğum nice yırtılan, tarih kitabımınsayfalarındaki geçmişim

haketmemiştim elbet

isteksiz bir biçimde çocukluğumdan vazgeçmeyi

nice haketmeyenler gibi...', 'çamurdan batak, sevgiden uzak ve kandan sıcak bir anda terkettim  çocukluğumu yeni vazgeçmişken çamurlu sokaklarda çelik çomak oynamaktan kö...', ARRAY['Türk Edebiyatı','Şiir','Sadullah Bayar']::text[], 8.5, '{"poet":"Sadullah Bayar","poet_slug":"sadullah-bayar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/haketmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerim', 'hayallerim-oner-ozer-2pizm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni senden uzakta

Sensiz yaşıyorum

Görmediğim halde

Seni düşünüyorum

Hayallerime sığdıramıyorum

Ellerimi uzatıyorum

Tutamıyorum

Konuşmak, sesini duymak istiyorum

Bir sessizlik çöküyor

Ardından koşuyorumYakalayamıyorum

Kaçıyorsun

Saklanıyorsun

Gecelerin sessizliğine

Gecelerin dostluğuna

Sığınıyorum

Hayallerime hasretimi ekliyorum

O kapkara gecelerde

Tek dostuma sarılıyorum

Seni senden uzakta

Sensiz yaşıyorum

Seni senden uzakta

Sessizce yaşıyorum', 'Seni senden uzakta Sensiz yaşıyorum Görmediğim halde Seni düşünüyorum Hayallerime sığdıramıyorum Ellerimi uzatıyorum Tutamıyorum Konuşmak, s...', ARRAY['Türk Edebiyatı','Şiir','Öner Özer']::text[], 8.5, '{"poet":"Öner Özer","poet_slug":"oner-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hayallerim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-oner-ozer-v8s55', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Olmuyor olmuyor

Sensiz olmuyor

Sessiz kalınmıyor

Aşka boşver denmiyor

Aşığa söz geçmiyor.', 'Olmuyor olmuyor Sensiz olmuyor Sessiz kalınmıyor Aşka boşver denmiyor Aşığa söz geçmiyor....', ARRAY['Türk Edebiyatı','Şiir','Öner Özer']::text[], 8.5, '{"poet":"Öner Özer","poet_slug":"oner-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/olmuyor-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Arıyorum', 'ne-ariyorum-oner-ozer-i1bks', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neyi arıyorum bu hayatta

Aşkımı, sevgiyimi, mutluluğumu.

Kaybederken kazanacakmıyım

Yoksa

Kazanırken kaybedecekmiyim.

Bilmiyorum.

Kararsızım.

Aramalımıyım kazanmak için

Çalışmalımıyım kaybetmemek için.

Ne dersin dostum

Ne yapmalıyım?', 'Neyi arıyorum bu hayatta Aşkımı, sevgiyimi, mutluluğumu. Kaybederken kazanacakmıyım Yoksa Kazanırken kaybedecekmiyim. Bilmiyorum. Kararsızım...', ARRAY['Türk Edebiyatı','Şiir','Öner Özer']::text[], 8.5, '{"poet":"Öner Özer","poet_slug":"oner-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ne-ariyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Benim', 'ask-benim-semih-unal-5ekti', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurtulus yok sevdan gönlümdedir, 

Ayrilamaz bu kalpten, 

Yüregin günes gibidir, 

Solamaz aniden bensiz, 

Yüregimdeki sessiz çigliklari duyabilmen için, 

Gönlünün kulagi olmali, 

Askimi anlayabilmen için, 

Gözlerinde bir damla yalan olmamali, 

Ben dertlilerin türküsüyüm, 

Yanik yanik Anadolu '' nun bagrinda söylenirim, 

Ben gariplerin dostuyum, 

Her bir garip düsmesinde dillenirim, 

Öyle ya mertlik nehrinde yüzmek nasip degildir herkese, 

Yürek ister bu yollar, 

Herkes yürüyemez bu yolda dolu dizgin, 

Aski sevmekle komaz bizim kitabimiz, 

Yüreginde hissetmen lazim aski, 

Ancak o zaman hak edersin sevgiyi, 

Dedim ya ben dertlilerin türküsüyüm, 

Ahmet aganin dilinde, 

Ayse bacimin gönlünde söylenirim, 

Ben hak yolcusuyum, 

Dogruluktur benim hamurum, 

Sevda nedir iyi bilirim ben, 

Ask nedir iyi bilirim, 

Ben dostluklarin mekaniyim, 

Gurbet acisi çekenlerin sag koluyum, 

Ben dertlilerin türküsüyüm, 

Ezelden ebede söylenirim, 

Ben askta yarali, sevgide galibim, 

Çünkü sevdaliyim ben, 

Karanliklarin azminden kurtulan tek savasçiyim ben, 

Ölüme ferman okurum, 

Okumu tam yürege dokurum, 

Dedim ya ben dertlilerin türküsüyüm, 

Mehmet aganin dilinde, 

Fatma bacimin gönlünde söylenirim, 

Ask benim. Aski sen bana sor gülüm!', 'Kurtulus yok sevdan gönlümdedir,  Ayrilamaz bu kalpten,  Yüregin günes gibidir,  Solamaz aniden bensiz,  Yüregimdeki sessiz çigliklari duyab...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ask-benim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Sözleri', 'askin-sozleri-semih-unal-rbr1n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç zaman geçti sensiz kaç zaman, 

Birakip gittin beni hiç acimadan, 

Öyle sevdim oysaki ben seni, 

Sativerdin aski kalbin sizlamadan.

Solmayan sevdamdin sen benim, 

Sönmeyen aleviydin gözlerimin, 

Güzel günleri yasamak varken, 

Aglatip beni çektin gittin erkenden.

Amansiz gidisin bir anda yikti beni, 

Nedir askinin sözleri yitirdikleri, 

Ahimi aldin da rahat gittin mi? 

O sözlerin bir kursun vurdu yüregimi.

SeMiH ÜNAL', 'Kaç zaman geçti sensiz kaç zaman,  Birakip gittin beni hiç acimadan,  Öyle sevdim oysaki ben seni,  Sativerdin aski kalbin sizlamadan. Solma...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askin-sozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Son Sevgilim...', 'bu-son-sevgilim-semih-unal-jyxsz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu son sevgilim.

Bu veda bu fasil, 

Çalan bu müzikte son, 

Kucakla sevgilere çekilen süngülerin ucunda, 

Namlularin soguklugunu hissetmek...

Iste sevgili bu mektubumda son, 

Son olan her sey son, 

Seninle dogan günes, 

Seninle batan yalnizlik, 

Siir kokan gecelerde; 

Omzuna yaslanan basin çilesi de son, 

Zamansiz kalbimi oksayan keskin biçakla, 

Vurgun yapan sensizligimde son, 

Ayrilik kokusuna eklenen özlemlerin, 

Vuslatla; uzak diyarlara firari, 

Kanatsiz uçan sevgi dolu gönüllerde son, 

Ahu zar-i tutmus güllerin gülmeleri, 

Kenetlenmis sevgilerin yeniden serzenisi de son, 

Yalnizlik bestelerinin senin için çalmasi da son, 

Keskelerin birlesip sel gibi akmasi da son, 

Keskin naralarin yüregimin soguk duvarina çarpmasi, 

Daglar da son bir gayretle kardelenin açmasi, 

Rüzgara karisan “seni seviyorum” sözcüklerinin alevlenmesi de son.

Her sey son bulacak, 

Sevgiler, Asklar, Tutkular.

Bir ben kalacagim, 

Bir de solmayan sevdam.

Sen de son olacaksin, 

Sonsuz olan “ask” kalacak.

Kim bilir belki oda bir gün [son] bulacak....

SeMiH ÜNAL', 'Bu son sevgilim. Bu veda bu fasil,  Çalan bu müzikte son,  Kucakla sevgilere çekilen süngülerin ucunda,  Namlularin soguklugunu hissetmek......', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bu-son-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Ya!', 'gittin-ya-semih-unal-s1pu1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gittin ya, 

Baharim karla örtüldü, 

Gülistan soldu mahvoldu, 

Çileler birlesti akar gider bir sel oldu, 

Yüzün eskimedi hala karsimdasin, 

Sen gittin gideli ellerin agzi lafla doldu, 

Beni yalniz sandilar, 

Halbuki ruhum sen doluydu, 

Gittin bir tanem ne yapayim, 

Dur diyemezdim ki sana, 

Yapma bu sevgiye kiyma diyemezdim ki, 

Biliyordum sende beni seviyordun, 

Iste asil isin garip yönü de bu ya, 

Neden gittin anlamis degilim hala, 

Lisanim yetmez miydi sana, 

Benle kalmana, 

Yalnizligim törpüler hasret gecelerini, 

Sonbahara kendini adamis askimiz, 

Zalim yillara baglanmis kalmis, 

Zaman bizi aldatmis birakmis, 

Sende beni vurup gitsen hiç acimaz inan, 

Gittin iste ne yapayim, 

O masum bakisli gözlerin, 

Riya dolu oldugunu nereden bilirdim, 

Gülüsüne aldanirdim halbuki ben senin, 

Sarkilari hep senin için ezberler, 

Senin için notalara dökerdim, 

Ama yine kiymet bilmedin, 

Gittin bitirdin iste ne yapayim, 

Yalvarsamiydim yoksa sana deli gibi, 

Yok yapamazdim ben böyle densizligi, 

Sizlansam da olmazdi asla böyle, 

Hasretin içimde biterdi o zaman, 

Yalvarmak benlik degil bir tanem, 

Olmadi iste divane gönül, 

Gitti sevgili, ne yapabilirsin, 

Hiç.

SeMiH ÜNAL', 'Sen gittin ya,  Baharim karla örtüldü,  Gülistan soldu mahvoldu,  Çileler birlesti akar gider bir sel oldu,  Yüzün eskimedi hala karsimdasin...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gittin-ya-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-semih-unal-na1ed', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum, 

Seni sende seviyor ve seni doya doya seviyorum, 

Sevmeyi seven herkesi seviyorum, 

Dalinda açan çiçegi, 

Dertlere gülen yüzleri, 

Dagda açan kardeleni de seviyorum, 

Sevmeyi seviyorum, seni seviyorum.

Masum bakislarla dalan gözleri, 

Gök yüzündeki yildizlari, 

Gündüzleri dogan günesi, 

Yalnizligima vurulan kelepçeleri seninle seviyorum, 

Seni seviyorum, 

Bestelerdeki matem havasini, 

Yüzündeki tebessüm sicagini, 

Ayin yüzüne vuran isik parçaciklarini seninle seviyorum, 

Seni seviyorum, 

Zindan gecelerimi gündüz yapan periyi, 

Hayati dertlerle donatan insanlari, 

Tarlada kazma sallayan ayse nenemi, 

Sende seviyorum, 

Seni seviyorum, 

Sensiz siirleri seninle seviyorum, 

Sarkilarda ben hep seni ariyor hep seni hayal ediyorum, 

Meleklerle gökyüzüne uçmasini, 

Derin naralar atmasini simdi daha çok seviyorum, 

Çünkü seni seviyorum.

Özlemlerimi seviyorum, 

Gelecege umutla bakan özlemlerimi, 

Hasretimi simdi daha çok seviyorum, 

Çünkü hasreti sana besliyorum, 

Seni sende yasamayi seviyorum, 

Seni seviyorum, 

Sevme hissini yaratani senden ötürü seviyorum, 

Sevmeyi sevmek yapan gözlerini seviyorum, 

Sensiz geceleride bazen seviyorum, 

Bana sensiz olamayacagimi anlatiyor yalniz geceler, 

Ve seninle ölmesini ne kadar seviyorum bilemezsin, 

Neden mi? 

Çünkü Seni Delicesine Seviyorum, 

Seni Seviyorum.

SeMiH ÜNAL', 'Seni seviyorum,  Seni sende seviyor ve seni doya doya seviyorum,  Sevmeyi seven herkesi seviyorum,  Dalinda açan çiçegi,  Dertlere gülen yüz...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/seni-seviyorum-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Kızım', 'benim-kizim-sahbaz-hulusi-soo8m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim kızım

İmzasını atar

Adresini bulur

Seyahat acentalarının 

Adreslerini bilir

Polisi - jandarmayı tanır

Gazete - dergi okur

Modayı yakından

Takip eder

Kur’an kursunu da bitirmiştir

Kaç subay

Kaç doktor 

Kaç avukat istemiştir

Namusludur

Saygılıdır

Yumurta ve kahve pişirir

Namazlarını aksatmaz

Her Cuma yasin hıfzeder

Temiz giyinir

Dişlerini  fırçalar

İmrendirir

Misafir odasına

İtalyan koltuk takımı 

Almıştır

Müslüman 

En iyisine layıktır

Ehliyeti var

Televizyon programlarından 

Araba sahibi olmuştur

Kültürlüdür

Eşitlikten yanadır

Kuma istemez

Ama küçük kaçamaklara 

Göz yumar

Hoş görülüdür

Hakiki demokrattır

Oyunu atar

Medenice mirastan 

Payını alır

Şehirde 

Apartmanda oturur

Bu kadar olsun 

İlk okulu birincilikle bitirmiştir

Kafalıdır

Kral istemeyen

Bir kraliçedir

Benim kızım

Benim kızım', 'Benim kızım İmzasını atar Adresini bulur Seyahat acentalarının  Adreslerini bilir Polisi - jandarmayı tanır Gazete - dergi okur Modayı yakın...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/benim-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halkım', 'halkim-sahbaz-hulusi-14n93', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tarihçiler

Hayır hasenat sahipleri

Çeşmeciler tulumbacılar

Ve Fosforlu Cevriye

Ve bu devirde sultan ve bezirgan olamayanlar

Motel işletmecileri

Teşvik alanlar

Kırkından sonra eve kapananlar

Namaza başlayanlar

Teneşir  meraklıları

Viyagra kullananlar

Evden kaçan kızlar

Akşam içip sabah oruç tutanlar

Evinde porno kaseti bulunan tecrübeli delikanlılar

Kolunda damga  bulunmayan Madamlar

Bir gecelik manitalar

Kumaya karşı çıkanlar

Abdest bozup alamayanlar

Yine de din hakkında konuşanlar

Aç aç seyredenler

Dolmuşa binip inenler

Fordçular 

İftar sofrasına katılan zenneler

Dönmeler lezbiyenler

Unvan sahipleri

Ününü satanlar

Önünü satanlar

Zevkine yatanlar

Ömrünü satanlar

Rol gereği yapanlar

Sanatçı olanlar

Böbrek satıcıları

Ruh satıcıları

Dert alıcıları

Medyumlar

Muskacılar 

Mumcular

Çaput bağlayıcıları

Kaput alıcıları

Yasin okuyucuları

Yatır ziyaretçileri

Pornocular

Akşamcılar

Bir verip bin alanlar

Taşıyıcılar

Alıcılar

Lokaller

Dernekler

Kuş sevenler

Düş sevenler

Duş sevenler

Kilot giyenler

Etekle yetinenler

Yaşa 

Var ol

Gece bitiyor

Fazla karıştırma

Demokrasi var

Metin ol', 'Tarihçiler Hayır hasenat sahipleri Çeşmeciler tulumbacılar Ve Fosforlu Cevriye Ve bu devirde sultan ve bezirgan olamayanlar Motel işletmecil...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/halkim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek Tut', 'dilek-tut-oguzkan-bolukbasi-29ivb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir dilek tut 

yum gözlerini, zamanı unut

eğer beni isterse umuda açılan yürek

kaldır başını aç gözlerini

benimdir, tependeki bembeyaz bulut', 'bir dilek tut  yum gözlerini, zamanı unut eğer beni isterse umuda açılan yürek kaldır başını aç gözlerini benimdir, tependeki bembeyaz bulut...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dilek-tut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki At', 'i-cimdeki-at-sahbaz-hulusi-srr5y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yılgın bir çığlık düştü içimden 

Yılgı bir çığ düştü içimden

İçimde koşan bir at tökezlendi

Ben hep içinde koşarım

İçimde kurşunlarımın insanları

İçimden göz kırparım

Gözlerimle yapacak işlerimi

Gönlüme yüklerim hep

Hep böyle yaparım', 'Yılgın bir çığlık düştü içimden  Yılgı bir çığ düştü içimden İçimde koşan bir at tökezlendi Ben hep içinde koşarım İçimde kurşunlarımın insa...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/icimdeki-at-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk', 'cocukluk-oguzkan-bolukbasi-y53y2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bahçemiz vardı

bir kamerya ortasında, 

bir masa sıralandığımız etrafında

babam ekmek keserken

annem çorbalarımızı koyardı

bahçemiz zambak

çorbamız misk kokardı

mazeretimiz yoksa misafir gelirdi

ya da biz misafirliğe giderdik

hafta sonları sinemaya bilet alınır

tonlarca çitlek çitlenirdi

zaman zaman nasihat edilir

okumamız gerektiği söylenirdi

mühendis veya doktor olmak önemliydi

                         ve uslu çocuk

bağırarak oynardık sokak ortasında

Ayten hanım çıkar kızardı

belli ki o gürültüde çocuğu uyanırdı

bayram günlerinde Kırıkkale, 

çocuklara boyanırdı.', 'Bir bahçemiz vardı bir kamerya ortasında,  bir masa sıralandığımız etrafında babam ekmek keserken annem çorbalarımızı koyardı bahçemiz zamba...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cocukluk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karaköy', 'karakoy-sahbaz-hulusi-2j7mk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Abi

Topuklarına bastığın 

Ayakkabılarını boyatırken 

Karaköy’de görmüşler seni 

Kardeşim 

Senin neydi işin orada 

Diyebilirsin 

Ben orada tombala çektiririm

Boyacılık yaparım

Marlboro satarım

Duman satarım

Manzara satarım

Herkesin 

Yer altı çarşısından 

Bir dükkan alması 

Mümkün değil mi

Sermaye ister 

Beceri ister 

Çevre ister

Hediye ister

......', 'Abi Topuklarına bastığın  Ayakkabılarını boyatırken  Karaköy’de görmüşler seni  Kardeşim  Senin neydi işin orada  Diyebilirsin  Ben orada to...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karakoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sekreter', 'sekreter-sahbaz-hulusi-3xgz6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sekreterim olmalıydı

Becerikli iş bitirici

İkna kabiliyetli yalan makinesi olamalıydı

Kalkan olmalıydı bana

Sekretersiz bir yere gelinmeyecekti

Sekretersiz bir yaşam çekilmeyecekti

Beni rahatlatmaktı görevi

Eğlendirmekti

Kapalı kapıları açmaktı

Bir şeker bir lokum bir çukulata

Bir kraker bir kurabiyeydi

Bir karanfildibir dildi bir dudaktı

Geceleri arasıra beni yoklamalıydı

Sekretersiz yaşam çekilmeyecekti

Sekretersiz bir yere gelinmeyecekti', 'Bir sekreterim olmalıydı Becerikli iş bitirici İkna kabiliyetli yalan makinesi olamalıydı Kalkan olmalıydı bana Sekretersiz bir yere gelinme...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sekreter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Perisi 1', 'masal-perisi-1-oguzkan-bolukbasi-u3yvu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen bir masaldın

devleri, cadıları olmayan

bir masal perisiydin

hiç ölmeyen

hiç solmayan

	bir çiçek

	tepelerinde karlı dağların

	ulaşılmayan

masal bu ya

bir deli sevdalı çoban

	aşıkmış o masal perisine

seyredermiş uzaktan

	korkarak ulaşmaktan, öylesine

masal perisi

bir gün güvercin olurmuş

başka birgün gökyüzü

yağmur yüklü bir bulut toprağı doyuran

peşinde bir kaval sesiyle

	o deli sevdalı çoban

	kuzulara söylermiş onu

	ağaçlara

	çimenlere

	türkülere

kuzular dile gelmiş, ağaçlar, çimenler ve türküler

“masal perisini alıp götürdüler, görmedin” demişler

o günden sonra çobanı, hiçbir yerde görmemişler', 'sen bir masaldın devleri, cadıları olmayan bir masal perisiydin hiç ölmeyen hiç solmayan 	bir çiçek 	tepelerinde karlı dağların 	ulaşılmayan...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/masal-perisi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Perisi 2', 'masal-perisi-2-oguzkan-bolukbasi-ta2jl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dokununca değneğinle sulara, denizlere, 

can geliyor kurumuş yapraklara 

yazılan şiirlere

hüznü atınca yürekten raksedip uçuyorum

açılıyor yelkenlim dönülmez enginlere

masallar yazıyorum, masallar dinliyorum her yerde

sendeki insan sıcaklığı devadır bilki her derde

yanımda olsan ne güzel 

hayatı doğuran her seherde

sana kuçak açıyorum ulaşmak için sevgilere', 'dokununca değneğinle sulara, denizlere,  can geliyor kurumuş yapraklara  yazılan şiirlere hüznü atınca yürekten raksedip uçuyorum açılıyor y...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/masal-perisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berber Sadi', 'berber-sadi-sahbaz-hulusi-pp88k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anam dikiş makasıyla 

Saçlarımı ilk kestiğinde 

Yeri -göğü yıkmıştım

Anam mengene gibi ayaklarıyla

Bütün hareketlerimi engelleyip

Tutsak etmişti beni

Saçımdaki makas izlerine 

Aynaya bakıp bakıp ağlıyordum

İlk berbere gidişimde 

Açık saçık artist resimleri

Ayıp işaretlerle karşılaştım

Herkesin bir sevgilisi olduğunu

Bir  futbol takımım  tuttuğunu

Berberlerin kasabanın 

Haber merkezi olduğunu öğrendim

Artık büyüyordum

Berberlere 

Daha sık uğramaya 

Başladım

Yakışıklı olmak istiyor

Sır olan konular konuşuyorduk

Alıp satmaktan

Gece yatmaktan 

Okul okumaktan

Fakirlikten kurtulmaktan

Askerlikten delikanlılıktan

Şarkıcılardan rol yapmaktan

Çalım yapıp gol atmaktan

Tiyatrodan sanattan derken

Berber Sadi ile tanıştık

Berber Sadi 

Her rolün adamıydı

Gerçek bir

Halk tiyatrocusuydu

Her zaman dediği gibi

Kurtarmalı bu çocukları bu sokaklardan

Kötü arkadaşlıklar edinmekten

Bazen ümitsizliğe düşer

Üzülür  kırılır hayıflanır

Kızı İrem 

Biricik varlığı

Veliaht Ahmet

Arkadan geldi

Kadro tamamdı

Roller dağıtıldı

Hayat zaten bir tiyatroydu

Kamera

Kurthamzalı Ormanlı

Oradan Bahçeobaşı çalıklı

Durutlu

Öğle yemeği

Domata kaşası', 'Anam dikiş makasıyla  Saçlarımı ilk kestiğinde  Yeri -göğü yıkmıştım Anam mengene gibi ayaklarıyla Bütün hareketlerimi engelleyip Tutsak etm...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/berber-sadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-sahbaz-hulusi-h2o9i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey su

Ey gök armağan

Damla damla ayet

Sure sure rahmet

İnsanlığa inen 

Gök kitabı

Gök semazeni

Gök haberi

Kadife el

Toprağın firuze örtüsü

Senin serinliğin 

Toprağımızı yeşertecek

İnsanımızı sevindirecek

Kalplerimizi sükuna erdiren

Tekrar tekrar yağan zikir 

Damlaların cezbesi

Toprağın yanık sesi

Çöller 

Dağlar taşlar

Ot ve böcek

Gül ve bülbül

Yılanı çiyanı emziren

Ayrım yapmayan gök memesi

Cömert el

Kurtlar kuşlar

Senden memnundur

Şifa kaynağımız

İbret aynamız

Gök yankımız

Gök uyarıcımız

Yaşam pompamız

Şahdamarımız

Onaran salgımız 

Hem can 

Hem cananımız

Ne bahar sensiz gelir 

Ve ürün sensiz güler

Ne dane 

Ne saman 

Ne kiler

Sensiz eder

Ey yiğitten

Daha yiğit

Yenilmez bir pehlivan

Şükrün galip bileği

Vahşi ve koşan 

Tutsak olmaz

Özgürlük çağlayanı

Senin düştüğün yerde 

Şelaleler meydana gelir 

Değişimin soylu berraklılığı

Yeşil ve enli şırıltı

Dinlendiren dirilten

Bestenin bitmeyen koşusu

Bu gün kııymetini bilmeyen 

Bir gün gelir ilaç olarak bulamaz

Derya göl ırmak beğenmeyen

Şişede balık olarak serumla yaşar

Şişenin kırıldığı yerde 

Sur diplerine 

Karton kutulara

Viraneliklere 

Hastane odalarına 

Hayır kurumlarına 

Su hırsızlığına 

Hücrelere düşer

Pırangalanır

Bir Yermük gününde 

Özverinin ne anlama geldiğini

Kardeşçe beller

Suyun ne manaya geldiğini çözersin 

Şimdilerde aradığımız

Derinlere çekilmiş

Hayat ve şifa suyumuzdur

Dün Osman’ın 

Yahudiden satın aldığı

Rume kuyusu

Halka vakıf yapılırken 

Bugün Manavgat’ın suyu

Damarlarımızdan bir kan gibi

Şırıngayla çekilmek istenmektedir

Bir damla suyu

Çok gören kimse ise

Müslümanların başına 

Emir olmak isteyen  kimsedir

Esirgenen kimse

Rasul evlatlarıdır

Özgürlüğü livata ile eşitleyen 

İnsanı kirleten bu çağa

Suların 

Gazabı laneti intikamı

Nasıl çağrılmasın

Bu çağı 

Sudan başka

Kim ve ne temizleyebilir

Bu ayyaş çağın başına

Bir kova su dökecek yok mudur

Yitirdiğimiz su uygarlığına

Geri dönmeden 

Temizlenmemiz arınmamız

Ayakta durmamız 

Mümkün değil

Aklı aradığını zannetmek

Suyu tekrar bulmadan 

Alkol ile olacak iş değil

Su uygarlığının çocukları

Ey bir damla sudan yaratılan 

Bir damla suda özetlenen insan

Bildin mi

Bir damla sudan sevgili yaratıldı

Bir damla sudur 

Babamız Adem’den bize kalan 

Bir damla sudur

Geriye bırakacağımız

Bir damla sudur 

Bir damla sudur', 'Ey su Ey gök armağan Damla damla ayet Sure sure rahmet İnsanlığa inen  Gök kitabı Gök semazeni Gök haberi Kadife el Toprağın firuze örtüsü S...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/su-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek', 'ekmek-sahbaz-hulusi-k8o9d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ademe dünya 

Bir elma olarak gösterildi

Artık elmayı Adem 

Kendi yetiştirecekti

Kendi emeğinden başka 

Bir ekmek yiyemeyecekti

Ademe ekmek 

Dane olarak verildi

Her dane isimlendirildi

Adını duyan

Çağrıldımı gelirdi

Ekmek 

Rüzgarın önünde 

Savrulan bir 

Yaprak değildi

Damla damla terden 

Pırlanta ve inci gibi dizilir

Bir künyeydi

Künyenin bir yüzünde 

“Hiçbir kimse 

Elinin emeğinden başka 

Hayırlı bir şey yememiştir”

Künyenin diğer yüzünde 

“Allah’tan başka 

Galip yoktur”

Yazılıydı

Ademin görevi koşmaktı

Didinip çalışmaktı

Huzur içinde 

Olduğunu söyleyip

Elini uzattığın yerde

Ekmek bulmak 

Mümkün değildi

Olağanüstü hal 

Özenciyle yaşıyorsun

Ne danede gözün 

Ne ekmekte terin 

Ne yemekte tuzun var

Peygamber sevgisi

Taşıyan kimse

Zorluklara katlanmayı bırak

Bu yolda ölüp ölüp 

Tekrar dirilmek ister

Dünya ve öte dünya 

Ağdırılmaması gereken 

Bir terazinin 

İki  kefesiydi

Tövbe 

Her zaman  geçerliydi

Üretim kısmına 

Kaydedilirdi

Sabır deneyimden 

Geçmek demekti

Uzmanlaşma konusunda 

Direnip becermekti

Uzmanlaşmak

Bir bilimdi

Bir buyruktu 

Bir kifayeydi

İçimizde yaşayan

Beyinsizlik de 

Kifayeyi görmemişlikti

Gayba inanıp harcayan 

Rıza yolunda 

Ve yokuşunda 

Cennet kapısının

Altın anahtarını tutan

Yakut ve mercandan 

Bir ele sahipti

Aşırıya gitmek 

Hezimet ve yenilgiydi

Önemli olan 

Dengeydi

Sen olda yap demek

İşin gevezeliğiydi

Dünya 

Zalimin cenneti

Mazlumun 

Cehennemi miydi

Altta kalanın 

Canı mı çıksındı

Yoksa 

Tırnağı olan mı 

Başını kaşısındı

Kaynaklar sınırlı

İhtiyaç sınırsız

Bölüşümü kim yapacaktı

Sınırsız aç olan 

Nasıl doyacaktı

Kavgasız ve gürültüsüz

Barış içinde 

Nasıl yaşanacaktı

Kavga 

Bölüşümde mi 

Olacak

Aç 

Bölüşümü 

Nasıl yapacak

Tokluğa

Muhtaç bir aç

Nasıl 

Üretime koşacaktı

Bulduğun 

Hamam tasındı

Yitik 

Bir malındı

Elinde kalan 

Kendini kandırdığındı

Canındı 

Malındı

Şükür 

Devamlıydı

Bedir’de 

Yener

Uhut’ta 

Yenilir

Mekke’de

Sevinirdi

Savaş sürerdi

Ve sürecekti

Ekmek 

Gerekirdi

Ekmek 

Serveti

Temsil ederdi

Güvenlikti

Esenlikti

Hukuktu

Huduttu

Ekmek

Bir babaydı

Babalıktı

Baba hakkıydı

Mama teri 

Ana sütüydü

Ekmek 

Babaların yüreklerine 

Akan

Bir göz yaşı 

Kulakları çınlatan

 		  Çığlıktı

İnsan onurunun

Hamuruydu

Doyuranı 

Helal lokmasıydı

Ekmek

Yaralıyan

Yıldıran

Susturan 

Bıktırandı

Cennete 

Yaklaştıran

Cehennemlik 

Bir tamahtı

Zaaftı

İnsan etinden 

Ve derisinden geçinen

Bir kasap

Bir kavaftı

İnsanı batıran

Hanım artığıydı

İflah olmaz

Bir israftı

Ter yanığıydı

Ekmek

Nimetti

Mübarek bir azıktı

Rızıktı razılıktı

Sınav kazanmaktı', 'Ademe dünya  Bir elma olarak gösterildi Artık elmayı Adem  Kendi yetiştirecekti Kendi emeğinden başka  Bir ekmek yiyemeyecekti Ademe ekmek  ...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":169,"source_url":"https://www.antoloji.com/ekmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-mehmet-tektanil-yxclb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana ''İyi misin? '' diyorlar, 

Sadece susuyorum, 

Bir tepki bekliyorlar, 

Bomboş gözlerle gülümsüyorum, 

Hatta gülümsemiyorum da ben abartıyorum, 

Aslında sadece küçük bir tebessüm var yüzümde, 

Bir zamanlar şen kahkaların çıktığı o yüzde sadece bir tebessüm kalmıştı, 

Olsun bu da bana yeter, diyorum, 

Hiç değilse onlara gerçeği söylemek zorunda kalmıyorum, 

''Sensizim, mutsuzum.''demiyorum, 

Çünkü sensizliği sadece senle paylaşmak istiyorum, 

Onu, birgün gelip sadece sana haykırmak istiyorum, 

Kimbilir, belki o gün geldiğinde bütün dünyaya iyiyim diye haykırırım, 

Tekrar eski şen kahkalarımla ve en önemlisi senle belki yine coşarım, 

Bekliyorum ben bitanem bekliyorum, 

O gün hiç gelmese de ben bekliyorum...', 'Bana ''İyi misin? '' diyorlar,  Sadece susuyorum,  Bir tepki bekliyorlar,  Bomboş gözlerle gülümsüyorum,  Hatta gülümsemiyorum da ben abartıyo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tektanıl']::text[], 8.5, '{"poet":"Mehmet Tektanıl","poet_slug":"mehmet-tektanil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sessizlik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sonbahardı', 'bir-sonbahardi-ugur-oguz-sahin-rydfd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gökkuşağından köprü kurdum

Kalbimden kalbinin çıkmaz sokağına

Uzunca bir zamandır seni bekliyordum

Sonbahar yapraklarının kucağında

Kaderimmiş meğer sürüklenmek

Alnıma yazılmış besbelli doğduğumda

Sonbahar yapraklarıyla hatırlarım seni

Yıllar önce yağmurlu bir akşam da unutulduğumda', 'Bir gökkuşağından köprü kurdum Kalbimden kalbinin çıkmaz sokağına Uzunca bir zamandır seni bekliyordum Sonbahar yapraklarının kucağında Kade...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-sonbahardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Halimiz Ne', 'bu-halimiz-ne-ugur-oguz-sahin-rc6fe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutlu bir aşka başladık

Nice özlemlere dünya açtık

Sonunda fark edemedik çok yazık

Bir fırtınaymış meğer gelen bu ayrılık

O hayalleri seninle birlikte kurmuştuk

Umutlara beyaz güvercinler uçurduk

Ne adaklar adadık bilmem ki nerede yanlış yaptık

Nasıl nazar değdi bize ne oldu anlamadık...', 'Mutlu bir aşka başladık Nice özlemlere dünya açtık Sonunda fark edemedik çok yazık Bir fırtınaymış meğer gelen bu ayrılık O hayalleri seninl...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-halimiz-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerisi Yalan', 'gerisi-yalan-ugur-oguz-sahin-cjwif', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykusuz ve uzun gecelere yollarımız

Hep günahkârlar elinde erir yaşayamadıklarımız

Hicran yarasıdır yarım kalan mutluluklarımız

Kara kışlar gibidir hep biten sevdalarımız

Sancılarda kıvranır ateşlerle yükselir acılarımız

Didinip çabalarız sevgi yumakları sararız

Dolar boşalır içimizda arzularımız duygularımız

Hepsi bir avuç mutluluk gerisi yalan yaşadıklarımız', 'Uykusuz ve uzun gecelere yollarımız Hep günahkârlar elinde erir yaşayamadıklarımız Hicran yarasıdır yarım kalan mutluluklarımız Kara kışlar ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gerisi-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-deger-ulas-turan-9unay', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir rüya gördüm dün gece, 

Şehrim uykuya dalarken. 

Kan kızılı salkımlardan damlayıp akan 

Bin türlü halini mey edip sunuyordu. 

Elleri nasırlı 

Elleri kan rengi 

İhtiyar bir kadın.

Gözlerin den damlayanı.

-İç dedi. 

Sonsuzluk var uyanırsan...', 'Bir rüya gördüm dün gece,  Şehrim uykuya dalarken.  Kan kızılı salkımlardan damlayıp akan  Bin türlü halini mey edip sunuyordu.  Elleri nası...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ruya-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-deger-ulas-turan-e0yil', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba, 

Geceden geçen sessiz hayalim. 

Merhaba sana 

Ve kentin sokaklarındaki adımlarına... 

Aynı sokağın başında duruyorsun 

Hiç bıkmadan, 

Sarhoş adımlarını kolluyorsun. 

Öfkeni yeniyorsun bekleyerek.

Susarak, susayarak…

Sabrına hayret edip,

Bilmeyerek çoğalıyorsun…', 'Merhaba,  Geceden geçen sessiz hayalim.  Merhaba sana  Ve kentin sokaklarındaki adımlarına...  Aynı sokağın başında duruyorsun  Hiç bıkmadan...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/merhaba-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorum', 'geliyorum-deger-ulas-turan-fp6al', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlemektir tüm niyetim korkma, 

Karşısına ne çıkar diye sormadan 

Usanmadan özlemek, sana gelirken. 

Suskunluğumsun, 

Dudaklarımdan dökülemeyen 

En alımlı şarkılarımsın. 

Susmak sana ulaştırıyor 

Ve özletiyor seni 

Daha nice geceyi koynuna alarak, 

Tutuşturuyorum sigaramı. 

Özlemek, 

Yolların bitmeyen uzaklığıdır. 

Hiç dinmeyen usançların sonunda.

Seninle süslenmesi 

Gece seferlerinde bütün peronların. 

Ve koşmak hiç yorulmadan, 

Yalınayak yüreğini çıldırtarak. 

Koşmak, 

Sana şehrine 

Bahçelerinde yetişen çiçeklerine.', 'Özlemektir tüm niyetim korkma,  Karşısına ne çıkar diye sormadan  Usanmadan özlemek, sana gelirken.  Suskunluğumsun,  Dudaklarımdan döküleme...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/geliyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi Yalanlar', 'adam-gibi-yalanlar-yasar-sezen-r2dgt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık sarhoş şiirler yazmayı bıraktım

Adam gibi bir şeyler  yazmak istiyorum

Ne bir aşkın deli rüzgarları başımda

Ne de memleketin derin meseleleri içimde

Adam gibi bir şeyler anlıyor musun? 

Şöyle bahardan bahsedeyim

Kardelenlerin solup çiğdemlerin açtığı bir bahardan

Kurak bir yazdan bahsedeyim

Ama bütün dalları meyve vermiş olsun

Birazda güzden bahsedeyim sana güzden

Her düşen sarı yaprak yaşamdan bir gün olsun

Yok yok kış dan bahsedeyim sana

Şöyle iliklerine kadar ayaz, kar

Ve yırtık palton

O beyaz gelinliğin üstünde bir kara leke olsun

Sana adam gibi bir şeylerden bahsedeyim tamam mı? 

Ama içinde ne “sen” olsun nede “ben”

Ne senin tekme tokat bıraktıkların bende

Nede benim göz yaşlarım, yağmur misali

Ne memleketimin buğday tenli insanları olsun içinde

Nede buğdayları yakanlar

İtiraf ediyorum ben bir yalancıyım, 

Çünkü; 

Ne “sen” eksik olursun nede “ben” bu şiirlerde

Ne senin bana  çektirdiklerin

Nede benim çektiklerim eksik olur

Ne buğday teli insanlar

Nede buğdayları yakanlar eksik olur

Bu gözü kör olası şiirlerden anlıyor musun?', 'Artık sarhoş şiirler yazmayı bıraktım Adam gibi bir şeyler  yazmak istiyorum Ne bir aşkın deli rüzgarları başımda Ne de memleketin derin mes...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Sezen']::text[], 8.5, '{"poet":"Yaşar Sezen","poet_slug":"yasar-sezen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/adam-gibi-yalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düş Gördüm Anne', 'bir-dus-gordum-anne-yasar-sezen-9tmgv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir düş gördüm anne

Bir gülüş gördüm

Seni gördüm düşümde

Bir tek seni gördüm anne

Özlemini gördüm yalnızlığımın öbür  adını

Bana açtığın kollarını gördüm anne

“Koş” diyordun.Koşuyordum.

Koştukça çoğalıyordu tepeler

Uzuyordu yollar koştukça

Çıplak ayaklarıma dikenler batıyor

Boğazım kuruyor tenim yanıyordu susuzluktan

Ve ben “anne su” diyordum

Sonra sen

Sen beyazlara bürünmüş bir kalabalık içinde

Al bir gömlek giymişsin

Beni “kuzum” diye çağırıyordun

Bende seni arıyordum

Belki kokundan bulurum diye

O koca kalabalık içinde tam bulmuşken seni

Ağarıverdi gömleğin rengi

Ve artık her nefeste adım adım  uzaklaşıyordun benden

İşte o anda uyanıverdim uykudan

Böyle bir düş gördüm anne

Seni yordum düşümde

Bir tek seni gördüm ANNE!', 'Bir düş gördüm anne Bir gülüş gördüm Seni gördüm düşümde Bir tek seni gördüm anne Özlemini gördüm yalnızlığımın öbür  adını Bana açtığın kol...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Sezen']::text[], 8.5, '{"poet":"Yaşar Sezen","poet_slug":"yasar-sezen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-dus-gordum-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleyim Sana', 'geleyim-sana-yasar-sezen-dfgjn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana bir mektup yaz geçmiş yıllardan

İçinde kokun olsun, içinde sevdan

Yalnızlık kapını çaldığı zaman

İmdat etsin mektubun geleyim sana

Dünya dertlerini topla başına 

Ağlayıver bir gün aldırmadan yaşına

Bir gece ansızın girersem düşüne 

Adım adım çağır beni geleyim sana

Zemheride karlardan, o aşılmaz dağlardan

Tozlu toprak yollardan 

Kan kırmızı güllerden

Bir koku gönderde geleyim sana

Gün olur devran dönerse

Kalbimde ışık sönerse 

Acılar omzuma binerse

Feryat edip çağırsam

Söyle sende gelir misin? Gelir misin bana?', 'Bana bir mektup yaz geçmiş yıllardan İçinde kokun olsun, içinde sevdan Yalnızlık kapını çaldığı zaman İmdat etsin mektubun geleyim sana Düny...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Sezen']::text[], 8.5, '{"poet":"Yaşar Sezen","poet_slug":"yasar-sezen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/geleyim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Ama', 'git-ama-yasar-sezen-lkyz8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşte zaman geldi apansız  ve amansız

Birazdan arkanı dönüp gideceksin

Beni böyle öksüz ve yetim bırakıp

Birazdan arkanı dönüp gideceksin

Gözlerimdeki yaşlara hiç aldırmadan	

Git, git ama

Gözlerin burada kalsın

Ben onları sevdim zaten seni hiç sevmedim ki

Demek gerçekten gidiyorsun ha

Git, git ama

Yüreğimi de götür

Biliyorsun o sensiz yaşayamaz

Yük olmaz sana, korkma

Başına dert açmaz

Oturur bir köşede uzaktan uzağa sever seni

Ha bir de

Şu bavulu bırak

Bana söylemiyorsun biliyorum ama

Ona bir ömürlük anıları doldurdun değil mi? 

Sen taşıyamazsın, yük olur ağır gelir sana

Düşünsene koca bir bavul dolusu hatıra

Bırak bende kalsın

Ben götürür eve bırakırım onları

O dört duvar içinde onlara da bir yer buluruz herhalde

Haydi zaman geldi

Git, ardına bakmadan git

Ama son bir defa, yalanda olsa

“Seni Seviyorum” de öyle git', 'İşte zaman geldi apansız  ve amansız Birazdan arkanı dönüp gideceksin Beni böyle öksüz ve yetim bırakıp Birazdan arkanı dönüp gideceksin Göz...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Sezen']::text[], 8.5, '{"poet":"Yaşar Sezen","poet_slug":"yasar-sezen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/git-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşinci Mevsim', 'besinci-mevsim-hamit-sairoglu-cia9b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben; 

Erguvan ağaçlarındaki son çiçek.

Güzel bir kızın gönlünde açan, 

Kırmızı gül.

İçli bir delikanlının hayalindeki

Son arzu...

Ve...

Ben, duymak istediğiniz, 

Son mısrayım.

Ben; 

Acı bir duman gibi, 

               Nefesinizde, 

Buruk bir şarap gibiyim, 

                                Testinizde.

Ben; 

Mutlu bir gecenin sabahında, 

En güzel rüya; 

Mutsuz bir günün akşamında, 

Daldığınız hülyayım.

Ben; 

En içli ve yanık türkü, 

Terkedilmiş sahillerdeki yankı, 

Nisan akşamlarındaki burukluk, 

Ağaç gövdelerinde unutulakalmış, 

İki çizgi - Bir ok.

Park kanepelerinde uyuklayan, 

                                       Özlemim.

Ben; 

Cebinizde taşınan, 

Birkaç tel saç, 

Örselenmiş fotoğraflarda, 

Gülümseyen bir yüz; 

Ben en körpe, 

Ben en güzel anıyım.

Ben; 

Çoban kavalındaki nağme, 

Bülbül sesindeki içlem, 

Gül tomurcuğundaki, 

Duru kızıllığım ben.

Ben; 

Yazarı bilinmeyen, 

Asırlardır dilden dile okunup, 

Hiç eskimeyen, 

En eski, 

Ve en güzel kitabım.

Öyle ki; 

Kötü ellerde örselenip, 

Gernef misali dokunan, 

Adem''den Havva''ya fısıltıyla okunan, 

Gönüllerinize atılan ağım ben.

Ben; 

Kader ipliğinde kalan, 

                                           Son düğüm, 

Dargın gönüller arasında, 

Henüz kopmamış olan, 

                                           Son bağım.

Bazan kirli bir masaya, 

Adım yazılır.

Mısra, 

               Mısra.

Dilek taşlarına; 

Anılarım kazılır, 

Satır, 

                Satır.

Bazan, 

                Bir gözün başında, 

Bazan, 

                Duru bir suyun akışında, 

                Bulursunuz beni.

Ben; 

Yıkık balkon altında çalınan, 

Son serenat, 

Başbaşa kaldığınız zamanki

                                   Fısıltı; 

Yalnız biten gecelerdeki

                                  İniltiyim.

Ben; 

Mevsimlerin en güzeliyim.

Beşinci mevsim derler adıma; 

Orada güller açar, 

                                    Hiç solmıyan.

Orada bülbüller öter, 

                                 Hiç susmıyan.

O mevsimde, 

Yoktur, 

Ne acı, 

Ne keder, 

Bir güncük de olsa; 

Orada yaşamanın mutluluğu yeter.

Ben; 

Sizin içinizdeki, 

                                    Bitmiyen senfoni.

Ben; 

Senin gönlündeki, 

                                    Burukluk.

Ben; 

Onun dünyasındaki, 

                                   Ölümsüzlük.

Ben; 

Hayat zincirinde kalan, 

                                 Son halka.

Ben en güzel yaşantı, 

Ben; 

Aşkım,  AŞK.', 'Ben;  Erguvan ağaçlarındaki son çiçek. Güzel bir kızın gönlünde açan,  Kırmızı gül. İçli bir delikanlının hayalindeki Son arzu... Ve... Ben,...', ARRAY['Türk Edebiyatı','Şiir','Hamit Şairoğlu']::text[], 8.5, '{"poet":"Hamit Şairoğlu","poet_slug":"hamit-sairoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/besinci-mevsim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuba Seni Ne Kadar Sevdiğimi Bir Bilsen Çıldırırsın', 'tuba-seni-ne-kadar-sevdigimi-bir-bilsen-cildirirsin-yasar-sezen-jmh1b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tarifi imkansız duygulardayım sevdiğinin ilk akşamında

Umudum oldun, dünyada kalma sebebim

Bak yüreğim nasıl çarpıyor 

Aşkının her damlasında dolup dolup boşalıyor gözlerim

Senin her gülüşünde bayram ilan ediyorum yüreğimde 

Ellerimle çiziyorum baharı gökyüzüne 

Ne var ki sen bazen ağlıyorsun; işte o zaman

İnadına daha çok seviyorum seni

Ne dünyada ne ahrette

Ellerini bırakmayacak diye ellerim

Kaderin elerimize attığı her düğümde

Ayaklarımıza vurduğu her prangada 

Duyduğun, duymadığın her aşk-ı hicazda

Ağlamaklı olsa da gözlerin, yüreğine, yüreğine

Rahmeti yağacak sana olan sevgimin 

Seni  sevdikçe yüreğime damlıyor göz yaşların

Ellerimde sevda gülleri büyütüyorum

Ve onları senin göz yaşlarınla suluyorum

Demet demet göz yaşı toplayacağım sana güllerden 

İçlerinde benim göz yaşlarımda olacak 

Ğayrı ağlamayasın diye gülücükler serpiştirdim içine

İlk yürek yangınım değilsin belki ama son olacaksın diye

Mahşere giden yolda yüreğimde  sevdam 

İçimde ışık olacaksın diye 

Bir bilsen seni ne kadar sevdiğimi

İnan ki gülüm hayatın alt üst olur

Rahat uyuyamazsın geceleri

Ben senin için, sevgin için varım 

İçin için hep senin için varım

Lütfüne sığındırdım ruhumu

Sen farkında değilsin ama bedenim bende ruhum senle

Ellerini uzatsan dokunur ellerime

N’olur uzat uzat ellerini

Çiğdemler gibi açılacaksın bir gün

Işıl ışıl parlayacak taç yaprakların

Laleler kıskanacak senin güzelliğini

Durup bekleyeceksin, bekledikçe güzelleşeceksin 

Issız bir uçurum kenarında yalnız kalacaksın sonra

Rüyalar göreceksin, rüyalar aşka dair

Issızlığı büyüyecek uçurumun birden

Rasgele bir yolcu gelip koparacak seni yerinden

Sen gözün yaşlı, boynun bükük giderken, ben 

Islak gözlerimle ardından bakıyor olacağım

Neden mi? Çünkü ben sensizliğe mahkum olacağım', 'Tarifi imkansız duygulardayım sevdiğinin ilk akşamında Umudum oldun, dünyada kalma sebebim Bak yüreğim nasıl çarpıyor  Aşkının her damlasınd...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Sezen']::text[], 8.5, '{"poet":"Yaşar Sezen","poet_slug":"yasar-sezen","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/tuba-seni-ne-kadar-sevdigimi-bir-bilsen-cildirirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Akıp Gidiyor', 'zaman-akip-gidiyor-mavi-yunus-zvql7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman akıp gidiyor hesapsızca

Yaşananlar kayıp gidiyor zamanda

Tekrarı yok istesende, zorlasanda

Keşke demenin faydası yok

Yaşa yaşayabildiğin yere kadar

Sev sevebildiğin kadar

Zaman bekler ardında

Aç kurtlardan farksız

Alır elinden güzellikleri

Tüketir sevgileri, doymaz

Tekrar ister

Tekrarı yok istesende, zorlasanda

Yaşa yaşayabildiğin yere kadar

Sev sevebildiğin kadar

                                   10.MAYIS.2002

                                    İlk Saatler........', 'Zaman akıp gidiyor hesapsızca Yaşananlar kayıp gidiyor zamanda Tekrarı yok istesende, zorlasanda Keşke demenin faydası yok Yaşa yaşayabildiğ...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-akip-gidiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Sitem*', 'dosta-sitem-bayram-tunca-4ty0j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin uğrunda akıttığım terim vardı

Senin uğrunda akıtacak kanım vardı

Uğrunda, verebileceğim canım vardı

Sana dağlar gibi hüsnüzannım vardı

Ah yıktın derya gibi olan hüsnüzannımı

Verdiğin o cevabınla, dondurdun kanımı

Daha Azrail’den önce aldın sanki canımı

Gerekse severek vermem damla kanımı

Kıssalarınızdan, çok mu çok hisse aldım

Dost bildiklerime, derdimi anlatamadım

Ne edem seni hakiki dostum sanmıştım

Belki, derde derman olursun sanmıştım

Bu aşkla çok derin ümit deryasına daldım

Ah bir bilseniz, ne hayaller kurup durdum

Ulaşabilmek için, kuş gibi çırpınıp durdum

Ama şimdi de bir ayçiçeği gibi burkuldum

Sözleriniz jilet gibi bileklerimi kesti benim

Ümitlerim pare pare olup yok oldu benim

Zonk zonk atıyor beynim, titriyor bedenim

Hiç olmadı, halimden anlayan bir sevenim

Çoğaldı, iş işten geçince nasihat edenlerim

Bir iyiliği için, kırk dereden su getirtenlerim

Sağolsunlar merhem için ipe un serenlerim

Ah nerede benim hakiki candan sevenlerim

Eğer ki gülüyorsam elbet bir güldüren vardır

Eğer ki ağlıyorsam elbette bir ağlatan vardır

Böyle yazıyorsam elbette bir yazdıran vardır

Her insanoğlunun dost ve düşmanları vardır

Yazacaklarımı tam yazamadım, kalemim tutuldu

Söyleyeceğimi tam söyleyemedim, dilim tutuldu

O ret cevabınız karşısında, elim/ayağım tutuldu

Zaten bu yetim şairin elinden ne zaman tutuldu

05.05.2002-11.55', 'Senin uğrunda akıttığım terim vardı Senin uğrunda akıtacak kanım vardı Uğrunda, verebileceğim canım vardı Sana dağlar gibi hüsnüzannım vardı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dosta-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borçsuz Kul Yok*', 'borcsuz-kul-yok-bayram-tunca-bqwco', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aslında her insan benim gibi borçlu doğuyor

Bu öyle bir borç ki, kefil bile kabul edilmiyor

Bazılarının vadesi uzun, bazısının kısa oluyor

Her insanoğlu kendi borcunu canıyla ödüyor

10.05.2002-10.10', 'Aslında her insan benim gibi borçlu doğuyor Bu öyle bir borç ki, kefil bile kabul edilmiyor Bazılarının vadesi uzun, bazısının kısa oluyor H...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/borcsuz-kul-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-osman-oguzhan-4xqio', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Parmağımda senin yüzüğünün izleri

Issız gecelerde yalnızlığımın ayak sesleri

Nereme atsam acı veriyor dertleri kederleri

Artık istesemde kalamam GİDİYORUM.

Rivayet eder dururlar ayrılıktan

Ağlar durur biri kara bahtından

Sabır taşı kırıldı duyuldu sesi ta maraştan

Ellerini uzat son defa GİDİYORUM.

Verselerde kalamam artık dünyayı

Gideceğim artık bölmeyin bu tatlı rüyayı

İlk ve son kez seyredeyim semayı

Leyla ile mejnuna ferhat ile şirine GİDİYORUM.

Ektim ama biçemedim dünya malını

Rol imiş hepsi çok çektim kahrını

Laleler hep bekleye dursun baharını

Ellerim bom boş gönlüm dolu GİDİYORUM.', 'Parmağımda senin yüzüğünün izleri Issız gecelerde yalnızlığımın ayak sesleri Nereme atsam acı veriyor dertleri kederleri Artık istesemde kal...', ARRAY['Türk Edebiyatı','Şiir','Osman Oğuzhan']::text[], 8.5, '{"poet":"Osman Oğuzhan","poet_slug":"osman-oguzhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidiyorum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annelerin Cazibesi+', 'annelerin-cazibesi-bayram-tunca-n5u6e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tahlil ettim anne kelimesini

Hayran kaldım o iki hecesine

Çözemedim sırlı bilmecesini

Sordum, o kelimeyi nicesine

Sevgi, şefkat kaynağıdır dendi 

Ceylan gözlü, tatlı sözlü dendi

En iyi sabır kahramanıdır dendi

Kime sorsam en güzeldir dendi

Asırlardır kulaklarda yankılandı

Ömür boyu belleklerde saklandı

Hayat en güzel anneyle tatlandı

Evlatlar anne rızasıyla paklandı

Kim görse büyülenir çehrelerini

Çok hayran bıraktılar nicelerini

Çözemedi, hiç kimse cazibelerini

O verdi, onların bu meziyetlerini

Şefkatleri güneşten bile sıcaktır

Güneşin sıcaklığı tenimizi ısıtır

Annemizin sıcaklığı içimizi ısıtır

Anneler olmasa kim içimizi ısıtır

Ne vakit, gülen bir anne görsem

Güller açar gönlümün bağlarında

Bülbül gibi öterim onun bağrında

O vakit yıldız gibi parlar gözlerim

Ne zaman bir anne feryadı duysam

Mutlaka ağlayan çocuk gelir aklıma

Bakmayın benim böyle durduğuma

Gamlıdır gönlüm, nemlidir gözlerim

Anne elinin değdiği yerlerde, gül biter

Elinin değmediği yerde, dikenler biter

Onun bulunduğu yuvada duman tüter

Şairin burnunda da anne hasreti tüter

Bitsin artık şu cihandaki savaşlar yeter

Öksüz kalıp da olmasın çocuklar heder

Dünyada, ağlamasın artık tüm anneler

Bayram da yazmasın artık böyle şiirler

Şairin lâl ü güher de olsa sönük kalır sözü 

Onun anne hasretiyle hicranlıdır gözü özü

O anne hasretiyle ciğerini akkorda közler

Bayram yıllarca annesiyle vuslatını gözler

12.05.2002-15:50

''Aşk Ateşten Gömlek''', 'Tahlil ettim anne kelimesini Hayran kaldım o iki hecesine Çözemedim sırlı bilmecesini Sordum, o kelimeyi nicesine Sevgi, şefkat kaynağıdır d...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/annelerin-cazibesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Acısı*', 'ayrilik-acisi-bayram-tunca-etp6w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yoktur, bu dermansız derdimizin ilâcı

Çok dolandım cihanı, yok bunun ilâcı

Siz bari, beyhude dolanmayın yok ilâcı

Ancak, bizzat tadılırsa, anlaşılır bu acı

Her kul, eninde sonunda tadar bu acıyı

Kimi çok erken, kimi geç tadar bu acıyı

Şair, çok erken tadanlardandır bu acıyı

Kim bizzat yaşarsa, o an anlar bu acıyı

Nasıl ki yenilen baharat acıları, çeşit çeşittir 

Hayattaki acılar da aynen öyle çeşit çeşittir

Kimi anne, kimi baba, kimi eş, kimi dost acısı

Ama bunlardan en acısı da O’nun ayrılık acısı

12.05.2002-15.50', 'Yoktur, bu dermansız derdimizin ilâcı Çok dolandım cihanı, yok bunun ilâcı Siz bari, beyhude dolanmayın yok ilâcı Ancak, bizzat tadılırsa, a...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayrilik-acisi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Numaralı Peron', 'on-numarali-peron-ahmet-rasim-f741u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Otogar’da, on numaralı peronda, 

Gözleri Turkuaz mavisi, 

Saçları başak sarısı, 

Saatin 14 olmasını bekliyor bir bayan.

Yüreği acı yüklü, 

Ne simitçinin bağırması, 

Ne otobüs muavininin telaşı, 

Çekmiyor ilgisini.

Limandan esen rüzgar değil, 

Ateş sanki.

Kavuruyor bedenini, 

Gözleri dolsa da ağlayamıyor, 

Geride bıraktıklarını düşünüyor.

Kendi için yanan yüreği düşünüyor.

Vakit tamam.

“Aşağıda yolcu kalmasın” diyorlar, 

İstemese de binmeyi, 

Ayakları geriye gitsede, 

Bir külçe gibi atıyor kendini koltuğa, 

Ürkek bakışlarla seyrediyor çevreyi, 

Bir daha görebilecekmiyim diyor kendine, 

Ve! 

On numaralı perondan ayrılış, 

Otobüs geniş bir daire çiziyor, 

Kendini uğurlamaya gelen kimse yok, 

Sallanmıyor ne bir el, ne bir mendil.

Doğduğumda nasıl yalnızsam, 

Şimdide öyle diye düşünüyor, 

Ama bilmiyor, 

Kendi için bir yerlerde, bir yüreğin attığını, 

Bir çift gözden, 

Hiç kimse için akmayan yaşların, 

Kendi için aktığımı, 

Kendi mantığına göre doğru yaptıklarının, 

Onun için ölüm olduğunu, 

Bilmiyor, onun kendi için ölümü göze aldığını, 

Git GÜLÜM, yolun açık olsun, 

Yalnız değilsin, 

Bilesinki bu yürek te senle gidiyor, 

Kimse senin kadar sevilmedi.', 'Otogar’da, on numaralı peronda,  Gözleri Turkuaz mavisi,  Saçları başak sarısı,  Saatin 14 olmasını bekliyor bir bayan. Yüreği acı yüklü,  N...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Rasim']::text[], 8.5, '{"poet":"Ahmet Rasim","poet_slug":"ahmet-rasim","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/on-numarali-peron-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Aşkı Verde Git İstersen Gene', 'bana-aski-verde-git-i-stersen-gene-fidan-gunes-lwjir', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ansızın gelir aniden kaybolursun, ne yaptığını sanırsın sen bana, beni benden alır gidersin kendi alemine, 

Var mı başka senin gibisi sanırsın, özlemin adı sen, sevginin sonsuzluğu sen.

Sen bendeki ben benliğimden kaçan sen. 

Nasıl olacak bilmiyorum seni özlüyorum, hiç böyle olmamıştı içimi ürperten aşk bu korkutan aşk. 

Gelsen ne çıkar sanki sensiz olacağıma senli olurum bir süre gene git istersen bana aşkı ver de. 

İçimde kalamazdı böylesi güçlü duygular bir şekilde sana verilmeliydi bu yürek.

Çektiği acılar, duyduğu özlem hissedilen aşk olmalı. 

Bu kadar acımasız olamazsın yar. Bırakamazsın beni böyle bir başıma.

Sana sormalıyım aşkı almalıyım senden. 

Sonum senle olmalı sensiz olacağıma senli olmalıyım bir süre ve sen gene istersen git bana aşkı ver de.

Yitirilen duygular böyle yavan yaşanmamalı yeniden bulunmuşken, yeniden doğmuşken dünyaya böyle olmamalı bu kadar duygusuz olamazsın yar.

Bitirilmiş defterler tekrar açılırken tekrar şiirler yazılırken sevgiliye böyle gidemezsin aniden geldiğin gibi. 

İçimi ürpertir seni görmek, boşver dünyayı ben seni ararken buldum gerçek mutluluğu içimdeymişsin meğer.

Sevgisiz yaşamaktansa, acıtsa da yüreğimi senin aşkın sonuçta aşk ya yaşadıklarım.

Gelsen ne çıkar sanki sensiz olacağıma senli olurum bi süre gene git istersen bana aşkı verde

Fidil', 'Ansızın gelir aniden kaybolursun, ne yaptığını sanırsın sen bana, beni benden alır gidersin kendi alemine,  Var mı başka senin gibisi sanırs...', ARRAY['Türk Edebiyatı','Şiir','Fidan Güneş']::text[], 8.5, '{"poet":"Fidan Güneş","poet_slug":"fidan-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-aski-verde-git-istersen-gene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimi Yumuyorum', 'gozlerimi-yumuyorum-mavi-yunus-lyavi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerimi yumuyorum

Yüreğim açık sonuna kadar

Hayalin doluyor, kapatıyorum sımsıkı

Gözlerimi yumuyorum

Kollarım açık dünyalar kadar

Hayalin doluyor, sarılıyorum sımsıkı

Gözlerimi yumuyorum

Yüzün yüzüme değiyor

Titriyor dudaklarım, öpüyorum sımsıkı

Gözlerimi açıyorum

Sen yoksun

Ağlıyorum sırılsıklam

                   13.Mayıs.2002

                    Son Saatler....', 'Gözlerimi yumuyorum Yüreğim açık sonuna kadar Hayalin doluyor, kapatıyorum sımsıkı Gözlerimi yumuyorum Kollarım açık dünyalar kadar Hayalin ...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerimi-yumuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Saati Gelip Çatmış', 'ayrilik-saati-gelip-catmis-mavi-yunus-9n12b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrılık saati gelip çatmış

Bahaneler sıradan

Adımlar yere çakılmış

Nedir bizi bağlayan

Kördüğüm olmuş gönüller

Çözülmez uğraşsan

Anılar ağır gelir

Ama taşırsın yolun sonuna

Acıtsa da taşlar canını

İnce ince kanarsın

Yüreğim der ki; dur gitme

Hayat çeker seni nafile

                         13.Mayıs.2002

                          Son Saatler...', 'Ayrılık saati gelip çatmış Bahaneler sıradan Adımlar yere çakılmış Nedir bizi bağlayan Kördüğüm olmuş gönüller Çözülmez uğraşsan Anılar ağır...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrilik-saati-gelip-catmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilal (r.a.)', 'bilal-r-a-adem-gunes-i0st1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ezan okunuyor yine, aklima nereden geldin Bilal? 

Gaiplerden mi geliyor acep bu ilahi haber? 

Kulaklarimi tikasam, beynimde haykiriyorsun Bilal! 

Allah-u ekber, Allah-u ekber.

Bu gün her minareden senin sesin yukseliyor, 

Gözlerimde yas, dislerim dudaklarimi kemiyor, 

Dayanacak gücüm kaladi, kokun O´na benziyor Bilal, 

Allah-u ekber, Allah-u ekber

Söylesene n´olur söyle, O nasil dinlerdi sen ezan okurken? 

Söylesene Bilal, görür müydün ellerini O dua ederken? 

Cok görme yaniyoruz, bir kere daha seselen Bilal, 

Allah-u ekber, Allah-u ekber.

Anlatsana, nasil oluyordu O önde siz arkada namaza durmasi, 

O emri verdiginde Ebu Bekr´in alnini secdeye vurmasi, 

O Kur´an okurken, Ömer´in dag kadar kalbinin durmasi Bilal, 

Allah-u ekber, Allah-u ekber.

Susma ya Bilal, sen susunca dünya durdu saniyorum, 

Aklimi yitirdim, kendimi senin sesinde buluyorum

Dünya umrumda degil, O´nu cok ozluyoruz Bilal, 

Allah-u ekber, Allah-u ekber.', 'Ezan okunuyor yine, aklima nereden geldin Bilal?  Gaiplerden mi geliyor acep bu ilahi haber?  Kulaklarimi tikasam, beynimde haykiriyorsun Bi...', ARRAY['Türk Edebiyatı','Şiir','Adem Güneş']::text[], 8.5, '{"poet":"Adem Güneş","poet_slug":"adem-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilal-r-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '19 Mayıs''da Samsun', '19-mayis-da-samsun-huseyin-duzbasan-0qflz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün ne güzel Samsun

Güneş daha aydınlık

Genç, ihtiyar, kadın, kız, 

Ulusca Samsun''daydık

Bin dokuz yüz on dokuz

19 Mayıs bu gün

Atatürk''ün Samsun''a

Ayak basmıştı bu gün

Kurtuluş Savaşı''nı

Atam bu gün başlattı

Bandırma vapuruysa

Şanlı bir görev yaptı

Karadeniz Türklerle

Ege''ye uzanacak

İzmir limanınızda

Esaret son bulacak

İnönüler Sakarya

Kocatepe''ye destan

Yazılmaya başladı

İşte bu gün Samsun''dan

Mayıs ayı denince

Aklıma Samsun gelir

Her 19 Mayıs''ta

Tüm Türkiye şenlenir

Türk gençliği Atanın

Her zaman gözbebeği

Onlara bağlı derdi

Ulusun geleceği

Bu bayram Türk gencine

Ata''nın armağanı

Atamı saygıyla an

Onu bir daha tanı

                                               

 15/05/2002', 'Bu gün ne güzel Samsun Güneş daha aydınlık Genç, ihtiyar, kadın, kız,  Ulusca Samsun''daydık Bin dokuz yüz on dokuz 19 Mayıs bu gün Atatürk''ü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Düzbasan']::text[], 8.5, '{"poet":"Hüseyin Düzbasan","poet_slug":"huseyin-duzbasan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/19-mayis-da-samsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-huseyin-cayikli-fshor', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'artik icimi sizlatacak kimse yok...

herkes gitti.

buyuk kavgalar oldu

ve hepsi bitti...

ask hayati kisacik bir romanmis

simdi anliyorum yalnizligi mi? 

yalniz kalan bir yanimi goruyorum

beraber yuruyoruz yollarda

o seni animsatiyor

hic ummazdim

sonbaharda bir yaprak bir hediye gibiydin

ve sen dahil kimse yok hayatima

hayatima dair cok siirler yazildi benim.

cok aci cektiler 

ben kendi yuzumden aci cekiyorum.

herkes gitti

ve yalnizlik arti yine yalnizlik

ve

kahrolasi

karanlik odalar 

ve maviduvar...', 'artik icimi sizlatacak kimse yok... herkes gitti. buyuk kavgalar oldu ve hepsi bitti... ask hayati kisacik bir romanmis simdi anliyorum yaln...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalnizlik-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '23 Sentlik Asker', '23-sentlik-asker-nazim-hikmet-ran-snjwz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '23 Sentlik asker

Mister Dalles, 

sizden saklamak olmaz, 

hayat pahalı biraz bizim memlekette.

Mesela iki yüz gram et alabilirsiniz, 

                                                                  koyun eti, 

                                                Ankara''da 23 sente, 

                            yahut iki kilo kuru soğan, 

                            yahut bir kilodan biraz fazla mercimek, 

                            elli santim kefen bezi yahut, 

                            yahut da bir aylığına

                                   yirmi yaşlarında bir tane insan.

erkek, 

ağzı burnu, eli ayağı yerinde, 

üniforması, otomatiği üzerinde, 

yani öldürmeğe, öldürülmeğe hazır, 

belki tavşan gibi korkak, 

         belki toprak gibi akıllı

                   belki gençlik gibi cesur, 

                             belki su gibi kurnaz

                                      (her kaba uymak meselesi) , 

belki ömründe ilk defa denizi görecek, 

belki ava meraklı, belki sevdalıdır.


..........
..........', '23 Sentlik asker Mister Dalles,  sizden saklamak olmaz,  hayat pahalı biraz bizim memlekette. Mesela iki yüz gram et alabilirsiniz,         ...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/23-sentlik-asker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülbeyaz', 'gulbeyaz-tolga-acar-f9q04', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüzünü göremedim ama, 

Kalbinin güzelliği yeter

Sesini duyamasam da, 

O sanki içimde titrer; 

Sen kimsin bilmiyorum, 

Nereden buldun beni

Bir tek şunu diyorum, 

”Artık bırakmam seni”

Sevgim mekan tanımaz, 

Nerde olsan farketmez

Emin ol ki gülbeyaz, 

Bendeki ateş sönmez!', 'Yüzünü göremedim ama,  Kalbinin güzelliği yeter Sesini duyamasam da,  O sanki içimde titrer;  Sen kimsin bilmiyorum,  Nereden buldun beni Bi...', ARRAY['Türk Edebiyatı','Şiir','Tolga Acar']::text[], 8.5, '{"poet":"Tolga Acar","poet_slug":"tolga-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulbeyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Nota', 'huzunlu-nota-fatih-irak-5zcca', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüzünlü bir notanın gözyaşlarından 

Ağlamanın gülmek olduğu bir zaman

Ve bir müzisyen ki

Çaldığı notanın hüznü zaman

Zamanın ağlamaklı olduğu bir an

Ağlayan herşeye inat seyir defteri yaşam

Yaşamaksa hayatı solumak

Nefeslerindeki gözyaşlarından

Herşeyin başı, 

Yaşamın hatta

Ve ağlamanın ne olduğu belirsiz gözyaşların 

Ağlamayı bilmemek bir başlangıç

Ama gülmenin başı ağlayan gamzelerin

Ağlamanın gülmek olduğu bir zaman 

Bizi karşılayan soluklarımız ve yaşam

Yaşamaksa hayatı solumak

Hüzünlü bir notanın gözyaşlarından..............', 'Hüzünlü bir notanın gözyaşlarından  Ağlamanın gülmek olduğu bir zaman Ve bir müzisyen ki Çaldığı notanın hüznü zaman Zamanın ağlamaklı olduğ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Irak']::text[], 8.5, '{"poet":"Fatih Irak","poet_slug":"fatih-irak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzunlu-nota-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ar', 'ar-sahbaz-hulusi-4i1mj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soğuk demir 

Bir izmarit

Arayanı olmadı

Dil ucuyla soruldu

Sık boğazını

Adı geçmesin ölümün

Ekmek ve onur

Kavgada baş tacı

Bilek gücüyle değil

Seda ile dövüştü

Hüzün pişman olmaktan uzak

Geri dönmek sevdamıza ar olur

Kimse yerinden oynatamaz

Yarin çatık kaşlarını

Başını dizini duvarları dövdüğün

Aynalar sevdadan kırılıp-dökülmeli

Süslen genişler yerin hep gözde olursun

Yarin yanında bakımlı ve arınanların yeri var', 'Soğuk demir  Bir izmarit Arayanı olmadı Dil ucuyla soruldu Sık boğazını Adı geçmesin ölümün Ekmek ve onur Kavgada baş tacı Bilek gücüyle değ...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmistim Seni', 'sevmistim-seni-ahmet-ruzgar-1o24e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilemessin sana verdigim degeri, 

Göremessin seni sana gülümden gül, gözümden esirgememi, 

Ahh güzelim askim suskun, vurgunsa icimde sitemi, 

Halbuki harbi harbi sevmistim seni.

Bir yangin bir agit bu ask hepmi böyle hepmi cilemi, 

Bir kitabdir okursun okursun yasamadan sevilmeyi, 

Ve noktalar virgül pesine dizilir sorular yorar beynini, 

Iyi düsünürsün anlar bilirsin sevmistim sevmistim seni.

Kimseleri koymadim senin yerine hic kimseleri, 

Gözümde nur gönlümde cira misali yaktim yaktim geceleri, 

Oof of caresizim careler icinde, tükenip solan güller gibi, 

Oysaki sevmistim seni isterdim sende sevseydin beni.

Allahina kitabina yemin olsun alacaktim alacaktim seni, 

Bas koymustum yoluna yasatacaktim sultanlar gibi, 

Kaderin cilvesi bu olsa gerek vurdu yerden yerlere beni, 

Cekermisin gidermisin ne kadar sevmistim bilsen seni', 'Bilemessin sana verdigim degeri,  Göremessin seni sana gülümden gül, gözümden esirgememi,  Ahh güzelim askim suskun, vurgunsa icimde sitemi,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Rüzgar']::text[], 8.5, '{"poet":"Ahmet Rüzgar","poet_slug":"ahmet-ruzgar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmistim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Bir Muska Gibi', 'islak-bir-muska-gibi-mustafa-yildiz-2-te4h3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I. 

Evet gençtim ve fakat

bunun bir tek aynalar farkındaydı; 

sonra olan oldu ve birden

bir sabah uyandığımda 

o benim herkesten - evet yanlış duymadınız – 

o benim herkesten sır gibi 

içerisinde bir imparatorluk sakladığım; 

o benim nice geceler boyu kaf dağının

ardındaki prensesi kurtarmak için

at binip kılıç kuşandığım

nice ejderhalarla savaşıp, bitap

zaferler kazandığım gençliğim

kırılan bir aynanın arkasındaki sırda 

-ansızın- sırra kadem bastı. 

Bunu gördüm! 

II. 

Ne ki, 

geride yalnızca her kılıç darbesini

vefakar bir aşığın boynundaki ıslak

bir muska gibi taşıyan 

yaralı bir yürek kaldı; 

o imparatorluk günlerimden kalma 

yıkık bir anıt gibi, 

mağrur ve mahzun.

Evet, bunu da gördüm! 

III. 

Öyleyse ne yapmalıyım ben; 

ne yapmam gerek şimdi; 

öyle ya 

kırılan kırılmış bir kez; 

ve bundan böyle, -evet bundan böyle-

bu bakir sırrıma sırdaş olup

sonra bir sabah

-ansızın- kırılan ayna misali

kırılan gençliğimden geriye, ıslak 

bir muska gibi 

göğsümde taşıdığım yaralı 

bir yürek kaldığını söyleyecek kadar

cesur davranmamın kime ne yararı olur, 

söylemiş olmaktan başka.

IV.

Ama tut ki ben

göçebeliğimden kalma bir pervasızlıkla

güpegündüz 

–evet hem de güpegündüz-

kalabalık bir caddenin kenarında durup

şehrin küstah ve müstehzi insanlarına

söyledim bunu; 

sormazlar mı bana o vakit: 

Yaralı bir yürek 

hangi yaraya merhem olur.

V.

İşte o vakit 

size / ne 

diyebilirim: 

hiç / bir 

yaraya merhem olmayan ıslak

bir muska gibi göğsümde taşıdığım

o yaralı yüreğimi oracıkta bırakıp

giderken verdiğim bu savsak cevap, 

-sadece yüreğimi orada bırakıp gittiğim için-

hangi yarasız, 

hangi kurak

hangi çorak yüreği göğertir: 

hiç / BİR YÜREĞİ belki...', 'I.  Evet gençtim ve fakat bunun bir tek aynalar farkındaydı;  sonra olan oldu ve birden bir sabah uyandığımda  o benim herkesten - evet yanl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız 2']::text[], 8.5, '{"poet":"Mustafa Yıldız 2","poet_slug":"mustafa-yildiz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/islak-bir-muska-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatlarına Karanfil Kokusu Sinmiş Kuş', 'kanatlarina-karanfil-kokusu-sinmis-kus-mustafa-yildiz-2-ulo2q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş batmışsa eğer 

gece en onulmadık yerden yaralar kuşları, 

çünkü...  evet çünkü

geceye karşı savunmasızdır kuşlar; 

zira kimse görmez o an

hangi görünmez yaralar

hangi kuşların

hangi görünmez yanlarını acıtır

Çünkü, gece hain

gece zalim

gece ihanet kokar; 

ve kimse bilmez o an

neden, gecenin ihanetinden 

camın ardındaki

küçük çocuk kartpostalları değil de

kanatlarına karanfil kokusu sinmiş

kuşlar korkar. 

Oysa 

“güneş yerinde duruyor” demiş Rilke; 

iyi de, 

orda öylesine duran güneş

hangi kuşun 

hangi kararan yanlarını ışıtır

gece vakti

cansız kartpostallardan başka

Şimdi sorarım size ey eşhas-ı ferhan

her şeyin sükutla örtüldüğü bir çağda

geceden 

bir camın ardındaki 

çocuk kartpostallarının değil de

niçin kuşların korktuğunu sorabilen

kaç kişi kaldı şunun şurasında 

kaç kişi kaldı

kaç kişi

kaç

kaçınmadan sorabilen çıkarsa eğer

ben ona

ardıç ağacının dallarından topladığım

kanatlarına karanfil kokusu sinmiş

kuşlarımı vereceğim

kartpostallar yerine', 'Güneş batmışsa eğer  gece en onulmadık yerden yaralar kuşları,  çünkü...  evet çünkü geceye karşı savunmasızdır kuşlar;  zira kimse görmez o...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız 2']::text[], 8.5, '{"poet":"Mustafa Yıldız 2","poet_slug":"mustafa-yildiz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kanatlarina-karanfil-kokusu-sinmis-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Robot Resim', 'robot-resim-ali-galip-yx1ng', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'biliyor her tünelin  hançeri var

külüne benzeyen sanık

tüm yoklamalarda olan

çaldığı ıslık yuğ gibi durur her faninin üstünde

silah kaçırır gölgesizlere

utanır, ihbar eder

nöbetini uzatan çocuğu', 'biliyor her tünelin  hançeri var külüne benzeyen sanık tüm yoklamalarda olan çaldığı ıslık yuğ gibi durur her faninin üstünde silah kaçırır ...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip']::text[], 8.5, '{"poet":"Ali Galip","poet_slug":"ali-galip","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/robot-resim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Organ Bağışı', 'organ-bagisi-ali-galip-g7gfi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Madem kanyak şişeleri bir bekçinin içinde intihar etti 

Madem ki kör itlerini ruhuma gömdün

İntihar depoladım kilometre taşınsa

Şarapnellerini bağışla  da git', 'Madem kanyak şişeleri bir bekçinin içinde intihar etti  Madem ki kör itlerini ruhuma gömdün İntihar depoladım kilometre taşınsa Şarapnelleri...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip']::text[], 8.5, '{"poet":"Ali Galip","poet_slug":"ali-galip","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/organ-bagisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu sabah', 'bu-sabah-gokhan-oktem-detzc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sabah

Penceremden utangaç süzülen

Yanık görüntüsünden mahcup

Yalnız ve sabırsız  yükselen 

Güneşe karşı durdum.

Akşamdan kalma tesiri hala süren

Ve gecenin izlerini gizleyen gözlerimi

Her sabah bana bir güneş doğuran

Karşı kıyıya vurdum.

Bu sabah 

Seviye bir kuş uçurdum

A kuşum

Bir kanadında asırlık özlemim

Bir kanadında ağlayan gözlerim...

Yükün ağır yolun uzun

Kanat çırp karşı semalarda süzül

Vur kendini güneşin doğduğu yere

Bu sabah 

O balçık hüznüme sonsuzluğu ekledim

Evet, en çok da bu sabah

Bir çağrın gelir diye bekledim

Ses verseydin

Ellerimi kanda koyar 

Yüreğimi söker yine gelirdim

Sen sükut içinde belirsiz

Ben hayal içinde bedbaht

Sen karşı kıyıda bensiz...

Ben bir kuşun kanadında seferi 

Bu sabah da

Dönüşünü bekledim 

Çaresiz...

15,05,2002, İstanbul', 'Bu sabah Penceremden utangaç süzülen Yanık görüntüsünden mahcup Yalnız ve sabırsız  yükselen  Güneşe karşı durdum. Akşamdan kalma tesiri hal...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bu-sabah-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-deger-ulas-turan-3l7h3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne anladın sen hayattan, 

Bu kadar umarsızken 

Harcanan birikimlerinde 

Ne anlarsın, 

Yoldaşının çektiği acı sende sızlamazken. 

Aşklar her an olur, 

Olur bunlar ardı ardına. 

Ama bir aşk kalır yarına tek 

Ve onurludur sonuna dek 

Aynı yoldan geçen yüz binlerle. 

Şimdi mevsim aşkları ıslatır 

Öyle aşklar vardır, 

Her mevsim dayanır. 

Öyle hasretler tutuşturur yüreğini 

Sabır sende payidar dır. 

Dayan sende yüreğim yarına inanarak, 

Umut elindeyken, 

Güneş bu gün sende daha da parlak 

Verimli toprakların açan asalet çiçekleriyle 

Umut sende, çiçek ve toprak. 

Yarına titrek uzanmasın elin, 

İnan sende kesin zaferin 

İnadına sevmek budur 

Başarmak inançla, 

Seni umuda davet eden yürekle olur.', 'Ne anladın sen hayattan,  Bu kadar umarsızken  Harcanan birikimlerinde  Ne anlarsın,  Yoldaşının çektiği acı sende sızlamazken.  Aşklar her ...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/umut-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak', 'islak-deger-ulas-turan-6ca8r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derin duruşunda ne bulursun, 

Gecenin ahengine kapılıp. 

Öyle ki zaman bizi heceye mahkûm kılar 

Ve en aymaz dakikasında saattin, 

Susmak bilmeyen şarkıları dökülür. 

Sen şarkıları dinle, 

Yarın güneş şiirle başlar. 

Baharın tam ortasında, 

Fütursuz bir yağmur yağar 

Anlamazsın, geçen saatin derin hecesini. 

Bir ırmak kenarına oturup, 

Beklersin yağmur dinsin 

Beklettiğin kadını düşünerek, 

Kitapların ıslanır 

Ellerinde kaybolur zaman.', 'Derin duruşunda ne bulursun,  Gecenin ahengine kapılıp.  Öyle ki zaman bizi heceye mahkûm kılar  Ve en aymaz dakikasında saattin,  Susmak bi...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/islak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-ahmet-gokpinar-zc77z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GARİP

Oturmuş köşeye gözleri nemli

Elinde kadehi yüzü kederli

Felek ona da varmış halinden belli

Hem ağlıyor hem yazıyor garip.

				

Ne arayanı var nede soranı

Zindandan farksız olmuş dünyası

İçtiği her kadeh sabır duası

Genç yaşta hayata küsmüş garip

Bazen uzaklara dalıp gidiyor

Kim bilir neler hayal ediyor, 

Arada bir kaderinden ah çekiyor, 

Belki de Ölümü bekliyor Garip		

Hayatı Karanlık yerde geçer

Yüreği kırılmış kadehe benzer

Yüzüne nefretle bakmayın yeter, 

Bir çiçek misali solmuş garip, 

Elinde bir kalem ağzında sigara

Dert yanıyor garip halini sorana, 

Bir ağıt tutturmuş akan göz yaşlara

Feryat eden bülbül olmuş garip, 

Gözlerini kapayıp yürür yolda., 

Kim bilir neler kurar kafasında

Gezer durur hayal dünyasında

Gerçek hayata susamış garip	



                                    Ahmet Gökpınar', 'GARİP Oturmuş köşeye gözleri nemli Elinde kadehi yüzü kederli Felek ona da varmış halinden belli Hem ağlıyor hem yazıyor garip. 				 Ne aray...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gökpınar']::text[], 8.5, '{"poet":"Ahmet Gökpınar","poet_slug":"ahmet-gokpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/garip-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıradan', 'siradan-bahar-gul-acar-4mcpc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İlk değil yaşamın bu sıradanlığa tanık oluşu, 

Bir ömür harcadıysak beraberce harcadık.

Sen yada bir başkası...

yada benden başkası..

değiştiremez sözcüklerin kaderini. 

İtinayla yazılsak da, 

bir çırpıda okunsak da...

elden ele dolaşıp, 

ve bir köşeye atılsak da her mektup gibi...

İlk olmayacak asla yazdıklarımız..

birgün bile olsa yaşamışlığımız, 

bir kaç satırdır işte eni konu...

anlata anlata biteremediğimiz insanlığımız.', 'İlk değil yaşamın bu sıradanlığa tanık oluşu,  Bir ömür harcadıysak beraberce harcadık. Sen yada bir başkası... yada benden başkası.. değişt...', ARRAY['Türk Edebiyatı','Şiir','Bahar Gül Açar']::text[], 8.5, '{"poet":"Bahar Gül Açar","poet_slug":"bahar-gul-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siradan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Nasıl Unutabilirim Sevgili..', 'seni-nasil-unutabilirim-sevgili-bahar-gul-acar-wmwwu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni nasil unutabilirim....

Sevgilim... 

Insan fethettigi daglari unutabilir mi? 

Zirvelerinde karlarin hic eksik olmadigi, 

Buzullarin sicak denizlerle kucaklastigi eteklerdeki, 

Ofke ve sevginin, 

Kotumserlik ve umudun, 

Korku ve cesaretin, 

Durmaksizin catistigi kiyilari.... 

Seni nasil unutabilirim, 

Sevgilim.... 

Yilan gibi kivrila kivrila akan, 

Derin caylarin kestigi, 

Vadilerinde mese yetisen daglarin, 

Giderek yukselen yamaclarinda, 

Ardic, sedir ve goknar’a yer verdigi, 

Doruklarin, doruklara hukmettigi yerleri... 

Seni nasil unutabilirim, 

Sevgilim....

Gozlerindeki huzursuzlugun, 

Kalbime hancer gibi saplandigi, 

Gulumsemelerinle saklamaya calistigin, 

Buz gibi bakislarinin, 

Omrunun baharinin, 

Kahroldugu mutsuzlugu simgeledigini... 

Seni nasil unutabilirim, 

Sevgilim.

Sana verdigim umudun, 

Sonunda butun umutlari yok ettigini...

Affet beni...', 'Seni nasil unutabilirim.... Sevgilim...  Insan fethettigi daglari unutabilir mi?  Zirvelerinde karlarin hic eksik olmadigi,  Buzullarin sica...', ARRAY['Türk Edebiyatı','Şiir','Bahar Gül Açar']::text[], 8.5, '{"poet":"Bahar Gül Açar","poet_slug":"bahar-gul-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seni-nasil-unutabilirim-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrimden Şehrine', 'sehrimden-sehrine-mehmet-caner-sumengen-qndh1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şehrimden şehrine, bitmez yollar var 

Gönlümden gönlüne, sevgim varsın yar 

Belki bir gün seni görürüm diye 

İçimde saklanmış, sonsuz umutlar. 

Ömrümü ömrüne, ekle desem az 

Kalbimi kalbine, kölen diye yaz 

Belki bir gün seni görürüm diye 

Ölüme koşsam da, canım acımaz. 

Uzaktan uzağa, aşka kandım ben 

Açıktan açığa, sana yandım ben 

Belki bir gün seni görürüm diye 

Leyla''sız Mecnun''u kendim sandım ben...', 'Şehrimden şehrine, bitmez yollar var  Gönlümden gönlüne, sevgim varsın yar  Belki bir gün seni görürüm diye  İçimde saklanmış, sonsuz umutla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sehrimden-sehrine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşkın Susmasıydı', 'bir-askin-susmasiydi-mehmet-caner-sumengen-ovqnw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir aşkın susmasıydı, örümcek ağı ören, 

Düşünce duvarımı bu bağlamda eskiten.

Bir aşkın susmasıydı, elimi kana süren, 

Işıldar gözlerimi ağlattıran yeniden.

Bir aşkın susmasıydı, zamana acı veren, 

Sancılı doğum gibi hep inleten, inciten.

Bir aşkın susmasıydı, kalbime batan diken, 

Ömrümü an an değil, asırlaca eriten...', 'Bir aşkın susmasıydı, örümcek ağı ören,  Düşünce duvarımı bu bağlamda eskiten. Bir aşkın susmasıydı, elimi kana süren,  Işıldar gözlerimi ağ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-askin-susmasiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'La Peregrina', 'la-peregrina-murat-umit-ezb5t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vakitsiz bir karanlık bu

Düşlerimi paramparça eden o kurt

Etlerimi sana mı bıraktı? 

Ölüme değil

Yaşama sokulgandım ben

Bahara şaşardım güze değil

O sırtıma saplanan demir parçası

Parmaklarınmıydı yoksa? 

Bırakma  beni böyle

Mat et, sır et, rezil rüsva...

Bir çocuğun gülüşünden mahrum et

Ölüme topal bırakma beni böyle.', 'Vakitsiz bir karanlık bu Düşlerimi paramparça eden o kurt Etlerimi sana mı bıraktı?  Ölüme değil Yaşama sokulgandım ben Bahara şaşardım güze...', ARRAY['Türk Edebiyatı','Şiir','Murat Ümit']::text[], 8.5, '{"poet":"Murat Ümit","poet_slug":"murat-umit","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/la-peregrina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O'' nu Sen Yaratmışsın', 'o-nu-sen-yaratmissin-abdulkerim-capar-q3fmv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sezgin’e

Günler geçmiş, aylar ardından

Yıllar teker teker 

Ellerinde bir ışıltı

Yüreğin ellerinden beter.

Beklediğin yer haram olmuş bedenine

Hep bir adım ileri

Usanmadan yılmadan

Çocuklar doğurmuşsun, nurtopu gibi

Hepsinin adı aynı.

Dar gelir olmuş yüreğine hayat

Peşinden gitmişsin bereketli yağmurların

Uzaklaştıkça yaklasmışsın

Hiç sonlanmayacak gibi

Batmayacakmış gibi güneş

Hiç bitmeyecekmiş gibi

Çalışmışsın.

Yorulduğun da olmuş bazen

Almışsın o zaman eline sazını

Dertli dertli çalmışsın.

Şiirler biriktirmişsin

Hep umutlu şiirler, geleceğe dair.

Her kelimesi itina ile seçilmiş.

Her kafiyede mükemmele yaklaşmışsın.

…

Sevgili’yse bihaber bunlardan.

O varken anlam kazandı görünse de herşey

O yokken yapmışsın.

O’nu sen yaratmışsın…

28.05.2001', 'Sezgin’e Günler geçmiş, aylar ardından Yıllar teker teker  Ellerinde bir ışıltı Yüreğin ellerinden beter. Beklediğin yer haram olmuş bedenin...', ARRAY['Türk Edebiyatı','Şiir','Abdulkerim Çapar']::text[], 8.5, '{"poet":"Abdulkerim Çapar","poet_slug":"abdulkerim-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/o-nu-sen-yaratmissin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorumluluk', 'sorumluluk-nizar-kabbani-w44mz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I.

Sorumludur gözlerin, sevgilim

Aleme dökülen her bir yağmurdan

Ve her bir ağaçtan ormanda yetişen

Sorumludur gözlerin yazılmasından şiirin

İnci ve sedefin teşekkülünden

Olgunlaşmasından sevgi ve cinsiyetin

Ve büyümesinden çocuklarla çiçeklerin

Gündüzün abasından gecenin çıkmasından

II.

Sorumludur gözlerin dönüşünden bu evrenin

Işığın seferinden ve değişiminden renklerin

İklimin vaziyetinden

Ve kıvamından denizlerdeki maviliğin

Sorumludur gözlerin, sevgilim

Baharda tarlaların giyindiği her şeye karşı

Ormanlarda ateşin tutuşturduğu her şeye karşı

Ve her şeye karşı, şehirlerde nehirlerle dolup taşan

III.

Sorumludur gözlerin, sevgilim

Bu dünyadan; doğudan batıya kadar

Kuzeye ve güneye kadar

Sorumludur balıkların hicretinden

Dönmesinden yıldızların

Bitkilerin sürgün vermesinden

Hayatın sürekliliğinden

Soluklanmasından günbatımında hülyaların

Sorumludur sarkıtılan ipten

Ve koza yapmasından ipekböceğinin

Sorumludur parlayan yahut ışıyan her şeyden

Konandan yahut uçandan

Sorumludur gözlerin, sultanım

Arzın dönmesinden

Ve istikbalinden milletlerin

Çeviren: İlyas Altuner', 'I. Sorumludur gözlerin, sevgilim Aleme dökülen her bir yağmurdan Ve her bir ağaçtan ormanda yetişen Sorumludur gözlerin yazılmasından şiirin...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sorumluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Gidiyorum Böyle', 'nereye-gidiyorum-boyle-nizar-kabbani-80fbv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık farkında değilim, nereye gidiyorum böyle

Her gün.. hissediyorum, çok yakınsın

Her gün, oluyor yüzün bir parça

Hayatımdan. Ömür bereketleniyor daha

Şekiller daha bir güzelleşiyor

Daha bir kutsallaşıyor eşya

Akıp durdun gözeneklerinde tenimin

Çiğ taneleri gibi öylece dolaşıyorsun

Zor geliyor yokluğuna alışmak

Yanında olmak daha da zor

Ne çok, ne çok sevmekteyim seni, hatta

Senden de fazla; ruhum bile şaşıyor buna

Mesken edinmiş gözlerinin bahçelerini şiir

Olmasaydı gözlerin, şiir yazılmazdı hiç

Sevdiğimden beridir dönüyor yıldızlar

Daha bir saf oluyor gökler, daha bir geniş

Çeviren: İlyas Altuner', 'Artık farkında değilim, nereye gidiyorum böyle Her gün.. hissediyorum, çok yakınsın Her gün, oluyor yüzün bir parça Hayatımdan. Ömür bereket...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nereye-gidiyorum-boyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hıçkırık', 'hickirik-mustafa-ozke-ar6cg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'doksanbeşin ayazıydı

sabahın köründe kaldırdılar bizi

gökyüzü ısırganotu gibi oturdu içimize

karabulutlar taş gibi düştü başımıza

üşürken ürperirken

ayrılık saatini koydular karşımıza

takvim yapraklarını birlikte yırttığımız

kahırlı günlerde of deyip geçtiğimiz

aynı kaptan soğuk çorba içtiğimiz

kemik kıran soğuğuna isyan ettiğimiz

arkadaşlarımızdan ayrılacaktık

kolay değildi bu, çok zordu

yüreğimizdeki ateşti, kordu

görevli gelip adımızı sordu

açtılar kapıyı dışarıda yangın vardı

öyle bir kucaklaştık ki

gözyaşlarımız birbirine karıştı

ayrılık değildi sanki

bu bir sevgiliye yakarıştı

han kapısı gibi yerden

iğne deliğinden çıkar gibi çıktık

kardeş değildik ama

dostların hatırlayacağı bir hıçkırıktık', 'doksanbeşin ayazıydı sabahın köründe kaldırdılar bizi gökyüzü ısırganotu gibi oturdu içimize karabulutlar taş gibi düştü başımıza üşürken ür...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hickirik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Sonbahar', 'her-sey-sonbahar-omer-karatepe-5o0xw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'umut 

bir telli dosya

ve ütopyadır sence 

bir ceninin

tarihin şiirini yazması

aşk tanımaz kimliğini 

kaç gün akşamı bulur teninde

hangi büyü

hangi tılsım

saklar gerçeğini

tapınacak bir tanrı arar

ölümün yaklaştığını anlayan sesin

dostuna türküler yakarsın

ihbarıdır bu

birazdan almaya gelecekler

sonbahardır her şey

sonbahardır her şey

umut bir telli dosya

usunun arşivinde çürüyen

sonbahardır her şey

korkarım ki taklidiyim

benden önce düşen bir yaprağın

ve 

sorgusudur aslında 

yazılan her mısra

yere düşen bir yaprağın

sonbahardır her şey', 'umut  bir telli dosya ve ütopyadır sence  bir ceninin tarihin şiirini yazması aşk tanımaz kimliğini  kaç gün akşamı bulur teninde hangi büyü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karatepe']::text[], 8.5, '{"poet":"Ömer Karatepe","poet_slug":"omer-karatepe","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/her-sey-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar Ve Sen', 'kuslar-ve-sen-cihan-turkmen-8by0b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kuşlar güneşe, 

ben sana aşığım 

kuşlar güneşe, 

ben sana ulaşamıyorum

ve kuşlar güneşe giden yolda; 

kanat çırparken ölüyorlar, 

bense özlemler arasında 

hergün başka bir güneşte 

                                      YANIYORUM......', 'kuşlar güneşe,  ben sana aşığım  kuşlar güneşe,  ben sana ulaşamıyorum ve kuşlar güneşe giden yolda;  kanat çırparken ölüyorlar,  bense özle...', ARRAY['Türk Edebiyatı','Şiir','Cihan Türkmen']::text[], 8.5, '{"poet":"Cihan Türkmen","poet_slug":"cihan-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kuslar-ve-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam Ortasında Hayatın', 'tam-ortasinda-hayatin-i-smail-ozabaci-yvslt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'eğer ölmeden geldimse

bu yaşıma

bir bu kadar daha yaşamalıyım; 

ki

tam ortasında bulayım seni

hayatın

ki benim hayatım olasın...

ki öylesin', 'eğer ölmeden geldimse bu yaşıma bir bu kadar daha yaşamalıyım;  ki tam ortasında bulayım seni hayatın ki benim hayatım olasın... ki öylesin...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tam-ortasinda-hayatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşlarım', 'arkadaslarim-oguzkan-bolukbasi-m7d8b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şarkı sözleri satarlardı

	sokak sokak, 

kapağında ya Zeki Müren

	ya Adnan Pekak

en son şarkıları

	bağıra bağıra okuyarak

yirmibeş kuruş verir bir tane alırdım, 

ne kolaydı çocuk beynimin ezberinde tutmak

sonra en tepesinde kaletepenin

bir şişe gazozla efkarlanmak

kimin sesi güzeldi bilmiyorum

Haluk eşlik ederdi, dümbelek çalarak

ben şiir yazardım

Harun resim yapardı

bir hülyası vardı

	anlatırdı ağlayarak

başka zaman hiç ağladığını görmedim

ağlamaya bıraktım

	gözyaşını da silmedim

duygulu çocuklardı benim arkadaşlarım

duyguları nerede kaldı şimdi onların

Ahmet öylesine gururlu

dans etmek istediğinde sevdiği kız, 

öyle sessiz dururdu

severdi

ama reddederdi

ne şaşırırdı bu işe Cevat, 

ne şaşırırdı bilseniz, 

kendini anlatamadan başka bir yere göçtü kız

  heyhat

bir Metin vardı, 

mavi boncuk gözleriyle

ne turlar atardı, mahallemizde

Metin’den bir iz bile yok elimizde

çok havalıydı

en son duyduğumda

Sarıyer kaymakamıydı

 ya amiral Nezih, 

amiral gemisi cüssesiyle o can çocuk

o heybetli

şimdi rahmetli, 

kulağımızda yankılanır sözü, sohbeti

duygulu çocuklardı benim arkadaşlarım

duyguları nerede kaldı şimdi onların



çoğuyla aynıydı okullarımız

ve hatta çoğuyla aynı sınıflarımız

tembellerimiz, çalışkanlarımız

makine kimya’da çalışırdı babalarımız

tatar Yüksel’in babası noterdi, 

tatar Yüksel’de bizle gezerdi, 

bir kızı severdi hatırlarım

onun yüzünden dayak yerdi

kafir

çok fazla içerdi

son gördüğümde gözleri bomboştu

belli ki yine içmiş, yine sarhoştu

hayata böyle katlanıyordu

düğünlere gider, 

limonata içer, kuru pasta yerdik

kız kıza dans edenleri seyrederdik

o zamanlar

dans etmeyi pek bilmezdik

biz leyleklerin getirdiği 

ufacık çocuklardık

sevdayı yaşamaya korkardık

sadece hayal kurardık.', 'şarkı sözleri satarlardı 	sokak sokak,  kapağında ya Zeki Müren 	ya Adnan Pekak en son şarkıları 	bağıra bağıra okuyarak yirmibeş kuruş veri...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/arkadaslarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağı', 'gokkusagi-resit-sipahi-u0ucm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir çakmak karanlığa gözlerin

karakışa bir aydınlık bahar yüreğin

karakalem hayatıma 

bir kusursuz gökkuşağı güleryüzün', 'bir çakmak karanlığa gözlerin karakışa bir aydınlık bahar yüreğin karakalem hayatıma  bir kusursuz gökkuşağı güleryüzün...', ARRAY['Türk Edebiyatı','Şiir','Reşit Sipahi']::text[], 8.5, '{"poet":"Reşit Sipahi","poet_slug":"resit-sipahi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gokkusagi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne''lere', 'anne-lere-sitki-dursel-3s96t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'büyümeyi isterdim önceleri

ufak tefek kızmalarından

kurtulmakiçin

nereden bilirdim özleyeceğimi

kendimi mum gibi eritip

o senli günleri yadedeceğimi 

anne söylesene nerden bilirdim

hesaba katmamıştım gurbet elleri

 ham meyveyi dalından koparan

adamda ciğer koymayan bu viranelleri 

ilkin hesaba katmamıştim anne

anne dua edermisin gene benim için

hasta olsam koşar gelirmisin ta buralara

oğlum oğlum sararmısın kollarına

nane çayı yapıp bana içirirmisin

anacığım her şey ama her şey 

senin gönlünce olsun

dualarımız  birbirimize kalkan olsun

kısa bir süre ayrılacakda olsak

buluşacağımız gün çok kısa olsun

gurbet ellerinden senin yurduna, 

avuçlar dolusu selam olsun', 'büyümeyi isterdim önceleri ufak tefek kızmalarından kurtulmakiçin nereden bilirdim özleyeceğimi kendimi mum gibi eritip o senli günleri yade...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Dürsel']::text[], 8.5, '{"poet":"Sıtkı Dürsel","poet_slug":"sitki-dursel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anne-lere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ariadne''nin Yakınması', 'ariadne-nin-yakinmasi-friedrich-nietzsche-cfun5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kim ısıtır, kim sever beni daha?

Sıcak eller uzatın bana!

Yürek mangalları uzatın bana!

Vurulup düşürülmüş çırpına çırpına, 

can çekişenler gibi, ayakları ovuşturulan,

sarsılmışım, ah! Bilinmeyen ateşlerle yana yana,

sen peşimdesin, ey Düşünce!

Adlandırılamaz! Açıklanamaz! İğrenç!

Sen, ey bulutların ardındaki avcı!

Yerle bir olmuşum senin şimşeklerinle,

sen alaycı göz, dikmişin gözünü bana karanlıklardan!

Yatıyorum öyle,

kıvrılarak, çırpınarak, işkencesiyle

bütün sonsuz ezaların,

vurdun beni

sen ey zalim avcı,

sen ey tanınmaz - T a n r ı...

ur, daha derine vur!

Bir kez daha, haydi vur!

Kopar, parçala bu yüreği!

Niye bu işkence

körelmiş oklarla?

Neye göz koydun böyle,

usanmadın mı bu insan işkencesinden,

acı vermekten haz duyan Tanrı şimşeği gözlerle?

Öldürmek değil istediğin,

yalnızca eziyet, eziyet etmek mi?

Bana - niye eziyet ediyorsun,

sen, ey acı vermekten haz duyan tanınmaz Tanrı?

Ha ha!

Usul usul sokuluyorsun

böylesi gece yarısında? ...

Ne istiyorsun?

Konuş!

Üstüme geliyorsun, sıkıştırıyorsun beni,

Ha! Çok yaklaştın yanıma!

Soluğumu duyuyorsun,

yüreğimi dinliyorsun,

kıskanç seni!

   - neden kıskanıyorsun beni?

Git! Defol!

O merdiven de niye?

İçeri mi girmek istiyorsun,

yüreğime tırmanmak,

en mahrem

düşüncelerime tırmanmak?

Utanmaz! Tanınmaz! Hırsız!

Ne çalmak istiyorsun?

Ne gözetlemek istiyorsun?

Ne işkencesi etmek istiyorsun?

Sen ey işkenceci!

sen - Cellat - Tanrı!

Yoksa köpek gibi,

taklalar mı ataydım karşında?

teslim mi olaydım, kendimden geçerek

sevginle - sırnaşarak?

Boşuna!

Sürdür batırmanı!

Zalim diken!

köpek değilim - avınım yalnızca senin,

zalim avcı!

en gururlu esirinim,

en ey bulutların ardındaki haydut...

Konuş artık!

Ey şimşeklerin ardına gizlenen! Tanınmaz! konuş!

Ne istiyorsun, ey Eşkiya... b e n d e n?

Nasıl?

Fidye mi?

Ne istiyorsun fidye diye?

Çok iste - böylesi yaraşır gururuma!

ve az konuş - böylesi yaraşır öteki gururuma!

Ha ha!

Beni - istiyorsun ha? beni?

herşeyimle beni? ...

Ha ha!

Ve işkence ediyorsun bana, delisin ya işte, 

gururumu kırıyorsun işkencenle?

S e v g i ver bana - kim ısıtır ki beni daha?

kim sever ki beni daha?

sıcak eller uzat bana,

yürek mangalları uzat bana,

bana, yalnızların en yalnızına,

buzunu ver ah! yedi kat donmuş buz,

düşmanları bile

düşmanları özlemeyi öğreten,

ver, evet, teslim et,

ey zalim düşman

bana - k e n d i n i!

Kaçıyor!

Bu kez o kaçıyor,

tek yoldaşım,

en büyük düşmanım, tanınmazım benim,

Cellat-Tanrım benim! ...

Hayır!

gel geri!

bütün işkencelerinle birlikte geri gel!

Bütün gözyaşlarım

sana akıyor,

yüreğimin son alevi

seni aydınlatıyor.

Gel, geri gel,

tanınmaz Tanrım! A c ı m   benim!

       son mutluluğum benim! ...

(***)', 'Kim ısıtır, kim sever beni daha? Sıcak eller uzatın bana! Yürek mangalları uzatın bana! Vurulup düşürülmüş çırpına çırpına,  can çekişenler ...', ARRAY['Türk Edebiyatı','Şiir','Friedrich Nietzsche']::text[], 8.5, '{"poet":"Friedrich Nietzsche","poet_slug":"friedrich-nietzsche","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/ariadne-nin-yakinmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-fatin-hazinedar-0hxbu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman gök gürlese

Korkuyla uyanırdım odamda

Korkumun yarısını anneme

Yarısını babama paylaştırıp

Küçücük bir yer bulurdum

ortalarında.

(Haziran 2000)', 'Ne zaman gök gürlese Korkuyla uyanırdım odamda Korkumun yarısını anneme Yarısını babama paylaştırıp Küçücük bir yer bulurdum ortalarında. (H...', ARRAY['Türk Edebiyatı','Şiir','Fatin Hazinedar']::text[], 8.5, '{"poet":"Fatin Hazinedar","poet_slug":"fatin-hazinedar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korku-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu akşam', 'bu-aksam-gokhan-oktem-65whg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu akşam

Gün aşırı yorgunlukların kabardığı yerde

Zaman doluyor.

Ses ver ey deli gönlüm

Bak iliklerinden abıhayat fışkırıyor

Nene gerek bu vakitsiz başın alıp gitmeler

Söyle kime inat akan suya karşı kürek çekmeler...

Kuş değilsin semalarda süzülesin özgürce

Suda balık hiç değilsin av olursun sinsice

Bihabersin yüreğinden, söylesem de inanmazsın

Bak karşı ki kıyıda bir körpe sevda soluyor

Bir el etsen yaşayacak

Bir göz etsen kopup sana gelecek

Görmez misin? 

Her firarın bir isyanı boğuyor. 

Bilmez misin? 

Güneşin battığı yerde 

Akşam oluyor.

16,05,2002, İstanbul', 'Bu akşam Gün aşırı yorgunlukların kabardığı yerde Zaman doluyor. Ses ver ey deli gönlüm Bak iliklerinden abıhayat fışkırıyor Nene gerek bu v...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bu-aksam-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sersefil Yaradılış', 'sersefil-yaradilis-ulas-sarican-oybjm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çözümlenemeyecek bir çarpım gibiyim

Sensiz olamıyorum

Sossuz bir makarna gibi 

Tatsız tuzsuz oluyorum

Titriyor, hıçkırıyorum

Ama üşümüyor ağlayamıyorum

kesilmiş bir odun parçasıyım

Hissizleşiyorum! ! ! !', 'Çözümlenemeyecek bir çarpım gibiyim Sensiz olamıyorum Sossuz bir makarna gibi  Tatsız tuzsuz oluyorum Titriyor, hıçkırıyorum Ama üşümüyor ağ...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Sarıcan']::text[], 8.5, '{"poet":"Ulaş Sarıcan","poet_slug":"ulas-sarican","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sersefil-yaradilis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Yansıması', 'zaman-yansimasi-ulas-sarican-ifaqz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'saat kaç bilmiyorum 

bilmekte istemiyorum

zaman denen kavrama

esir olmak istemiyorum

günler haftalar aylar geçiyor

zaman geri gelmiyor

ağlamalar unutuluyor

gülüşler hatırlnmıyor

ucunu kaçırsakta hayatın

güzel anlarını

dondurmak istiyorum

beceremiyorum! ! !', 'saat kaç bilmiyorum  bilmekte istemiyorum zaman denen kavrama esir olmak istemiyorum günler haftalar aylar geçiyor zaman geri gelmiyor ağlam...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Sarıcan']::text[], 8.5, '{"poet":"Ulaş Sarıcan","poet_slug":"ulas-sarican","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zaman-yansimasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Sesi', 'gecenin-sesi-ulas-sarican-erpkv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duygusuz yoğun gece

Islak penceremden ufka dalıyor

Geceyi dinliyorum

Kulağımda tınılar

Yıldızlar dans ediyor

Ay onlara eşlik ediyor

Birden bir düdük

Dikkatim dağalıyor

Bekçi Musa bu

Asayiş berkemal

Duruluyorum

İzlemeye başlıyorum 

Gecenin sinsiliği

Üzerime çöküyor

Düşler kuruyorum

Olmayacağını biliyorum

Sonra sen görünüyorsun

Serseri öpüşler başlıyor

Çılgın itiraflar

Ağlamalar inlemeler

Daralıyor

Bunalıyorum', 'Duygusuz yoğun gece Islak penceremden ufka dalıyor Geceyi dinliyorum Kulağımda tınılar Yıldızlar dans ediyor Ay onlara eşlik ediyor Birden b...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Sarıcan']::text[], 8.5, '{"poet":"Ulaş Sarıcan","poet_slug":"ulas-sarican","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gecenin-sesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum', 'ruhum-ulas-sarican-4wd9k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşlüyorum

Korkusuz bir ikizim mi var

Yoksa ruhummu kaçıyor

Ruhumu kaybediyor

Korkuyorum

Benden kaçamıyor

Zincirle bağlı bana

Benden ne kadar uzaklaşırsa

O kadar ruhsuzlaşıyorum', 'Düşlüyorum Korkusuz bir ikizim mi var Yoksa ruhummu kaçıyor Ruhumu kaybediyor Korkuyorum Benden kaçamıyor Zincirle bağlı bana Benden ne kada...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Sarıcan']::text[], 8.5, '{"poet":"Ulaş Sarıcan","poet_slug":"ulas-sarican","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ruhum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-nizamettin-dereci-rk7i8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ankara, 

Çölün ortasında beton binalar, 

Bodro mahkümü insanlar.

Ruhumu sıktıkça sıkar, 

Gülmekten uzak sahte kahkahalar.

Neyini bekleyeyim? hani gelse dediğin bir şey.

Yazını da kışını da bilirim.

Ne kışın kartopuna, 

Ne yazın menekşene değdi elim.

Bir hicran alır beni götürür uzaklara

Bir çekilmez dert oldun  benim için ankara', 'Ankara,  Çölün ortasında beton binalar,  Bodro mahkümü insanlar. Ruhumu sıktıkça sıkar,  Gülmekten uzak sahte kahkahalar. Neyini bekleyeyim?...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ankara-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünceler', 'dusunceler-erol-sen-zxpuv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umudun tükenmişse zamana

Gündüzle gecenin farkı

Aydınlık ve karanlıksa

Düşünceler yine de aynıysa

Zamanın çaresi düşünceyse

Var git düşüncelere...

17.05.2002', 'Umudun tükenmişse zamana Gündüzle gecenin farkı Aydınlık ve karanlıksa Düşünceler yine de aynıysa Zamanın çaresi düşünceyse Var git düşüncel...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dusunceler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevdanın Öyküsü', 'bir-sevdanin-oykusu-mahmut-sami-gurpinar-w8i64', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni ilk gördüğüm anda

Kapıldım rüzgarına

O güzelim saçlarına, bağlandım kaldım.

Sensiz günler hayatımın zindanı

Ölsemde bırakmam sevdamı

Bakmaya doyamam gözlerine

Senin o güzel sözlerine

Sensin benim hayatımın anlamı

Hatırlarım o güzel yılları

Dolaşırken sensiz o çamlığı

Ağaçlar bile üzülüyor sen olmayınca

Bülbüller ötüyor bir yanımda

Sen benim kanımda, canımda

Sanki her yanımda

Senin sevdan her zaman başımda

Ilık bir yel esti pencereden

Bir çığlık yükseldi kalbimden

Sanki bir rüya gibiydin sen

Bir acı hissettim en derinden

Pencereden baktım seni göremedim

O güzel yüzünü sevemedim

Senin o gözlerine bakamadım

Aşkınla tutuştum yandım.', 'Seni ilk gördüğüm anda Kapıldım rüzgarına O güzelim saçlarına, bağlandım kaldım. Sensiz günler hayatımın zindanı Ölsemde bırakmam sevdamı Ba...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Sami Gürpınar']::text[], 8.5, '{"poet":"Mahmut Sami Gürpınar","poet_slug":"mahmut-sami-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-sevdanin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-mustafa-sureyya-sezgin-epa3j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nankör olmamam gerekli

Biliyorum...

Aslında varlığınla şanslıyım

Bu dünya da senin ile kadınım! ..

Zaman zaman sorguluyorum yaşamımı

Senden başka kim katlanırdı, 

Benim sonu gelmez kaprislerime? 

Kim dayanırdı, 

Deli gönlümün heveslerine? 

Ve kim teselli verirdi, 

Körpe umutlarını uçuran

Bu kocaman çocuğa? 

Biliyorsun, 

Çoğu zaman sevdalanırım, 

Zaman zaman aldanırım.

Ama tüm gerçekliğinle

Sen yanımdasın kadınım! ..

(İstanbul,16.05.2002)', 'Nankör olmamam gerekli Biliyorum... Aslında varlığınla şanslıyım Bu dünya da senin ile kadınım! .. Zaman zaman sorguluyorum yaşamımı Senden ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kadinim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Hep Sensin', 'yuregimde-hep-sensin-mehmet-ali-cibikli-712r9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İtfaiyeci olsan, yine söndüremezsin, 

Her geçen gün büyüyen, içimdeki yangını.

Seni sevdim bir kere, geri döndüremezsin, 

Unutmam mümkün değil, unutamam adını.

Sevdana tutsak oldum, bakışın beni yaktı, 

Suçum mu büyük benim, cezam neden bitmiyor? 

Ben sana bağlanmışım, sevdan gönlüme aktı, 

Hep seni hayal ettim, hayalin de yetmiyor.

Hasretin buram buram, yakıyor yüreğimi, 

Sevdayı çeken bilir, ancak böyle sevilir.

Bilemezsin sen bunu, duyamazsın sesimi, 

Aşkın ne olduğunu, sevmeyen nerden bilir? 

Sen her zaman benimsin; rüyamda, hayalimde, 

Kalbim seninle dolu, seninle çok mutluyum.

Dayanacak gücüm yok, derman kalmadı bende, 

Ne olur anla beni, ben de Allah kuluyum.

İstersen sevme beni, zorla güzellik olmaz, 

Her seven sevilecek diye bir kural yoktur.

Yüreğini açık tut, belki ümidim solmaz, 

Seversin belki bir gün, yine Allah büyüktür.

Sevsen de sevmesen de, seni hep seveceğim, 

Alnımın yazısı bu, seni bana yazmışlar.

Senden kopmam imkansız, nasıl terkedeceğim? 

Yüreğimde hep sensin, bir de senin sevgin var.', 'İtfaiyeci olsan, yine söndüremezsin,  Her geçen gün büyüyen, içimdeki yangını. Seni sevdim bir kere, geri döndüremezsin,  Unutmam mümkün değ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yuregimde-hep-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylediğim Şarkılar', 'soyledigim-sarkilar-mustafa-sureyya-sezgin-evcak', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda mıydı o? 

Gözlerinden akan

Ve ardımdan sel olan

Hüznün...

Doluyum yine bugün

Bir tek varlığının

Sardığı duygularla.

Yığılmış özlemleri, 

Benliğimde dünün

Bugün söylediğim şarkılarda.

(İstanbul,20.06.1995)', 'Sevda mıydı o?  Gözlerinden akan Ve ardımdan sel olan Hüznün... Doluyum yine bugün Bir tek varlığının Sardığı duygularla. Yığılmış özlemleri...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/soyledigim-sarkilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk mıydı O?', 'ask-miydi-o-mustafa-sureyya-sezgin-utdyi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk mıydı o? 

Bir tutam sevda için

Deli nehirler gibi

Gözlerinde sel olan.

Aşk mıydı o? 

Bir siyah bakış için

Dudaklarında inleyip

Ayrılık bestesi yapan.

Söyle aşk mıydı o? 

Bir tatlı gülüş için

Kıvılcımla tutuşup

Gönlümüzde kor olan.

(İstanbul,31.07.1995)', 'Aşk mıydı o?  Bir tutam sevda için Deli nehirler gibi Gözlerinde sel olan. Aşk mıydı o?  Bir siyah bakış için Dudaklarında inleyip Ayrılık b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-miydi-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahara Doğru', 'sonbahara-dogru-mustafa-sureyya-sezgin-f664x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aysel, gel yanıma

Otur dizi dibime

Tatlısıyla, acısıyla

Eğrisiyle, doğrusuyla

Sıralayalım bir ömür boyu

Yaşadıklarımızı birbirimize.

Yılları devirdik

Sırt sırta seninle.

Artık ağardı saçlarımız

Ama yitirmedik sevgiyi ve umudu.

Çiçek açtı yuvamızda

Buram buram

Sevgi kokan çocuklar.

Aysel gel yanıma

Otur dizi dibime, 

Bak artık yorulduk.

Kaybolma göz önünden

Sımsıkı sarıl bana

Sonbahara doğru koyulduk! ..

(İstanbul,31.07.1995)', 'Aysel, gel yanıma Otur dizi dibime Tatlısıyla, acısıyla Eğrisiyle, doğrusuyla Sıralayalım bir ömür boyu Yaşadıklarımızı birbirimize. Yılları...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sonbahara-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirimdeki Hüzün', 'siirimdeki-huzun-mustafa-sureyya-sezgin-s8z0m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilme... Bilme...

Ne  Olursun! ..

Esrarı bozulur sonra

Şiirimin içindeki hüznün.

Öylesine

Belleğimdeki yüzün

Doluya koysan olmuyor...

Boşa koysan yine olmuyor! ..

Üç, beş değil ki, 

Kaybedilen o körpe yıllar

Özlesen de artık yaşanmıyorlar...

(İstanbul,07.08.1995)', 'Bilme... Bilme... Ne  Olursun! .. Esrarı bozulur sonra Şiirimin içindeki hüznün. Öylesine Belleğimdeki yüzün Doluya koysan olmuyor... Boşa k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siirimdeki-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyeceğim Özleyeceksin', 'ozleyecegim-ozleyeceksin-erol-sen-r7ha7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdiğini inkar edemeyen bu gönül

Egoist tavırlardan uzak benliğim

Aslanlar gibi haykırır gerçekleri

Utanmadan ağlamadan ama inatla 

Sevgiyi örtmekle sevgi tükenmiyor

Verilen değerlere insafsız inkarlar

Kalpler sızlarken yazılan satırlara

Bu kadar dolu yaşanmış sevgiye düşen damlalar

Yeni AŞK ararmı kalpler 

Aramak aşka ihanet sevgiye ihanet

Buruk duygular yaşıyor gönüller 

Bir gün aklına düşersem beni anlayacaksın

Umuda açılan kapıları kapatan gönlün 

Anahtarı ulaşılmazlara atarken

Sevginin aşkın kalbini hançerledi

Elleri bile titremeden

Sanıyormusun ki gönüller tamir olur

Sanıyormusun ki bu gönül başka sevgiler ister

İnanç kaleleri bir bir yıkılmışken

Küsmüşken sevgilere

Özlemler olmasa bu şiirler de olmazdı

Saklı kalan sevgiler açılmazdı pervasızca

Söylenen sözler mısralara dökülmezdi

Ya aşk  yazılan güller...

17.05.2002', 'Sevdiğini inkar edemeyen bu gönül Egoist tavırlardan uzak benliğim Aslanlar gibi haykırır gerçekleri Utanmadan ağlamadan ama inatla  Sevgiyi...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ozleyecegim-ozleyeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamayacaksın', 'unutamayacaksin-erol-sen-hxkxk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boğazın deniz kokusunda

Yediğin balığın tadında

Attığın kahkahanın feryadında

Aşkımızı hatırlayıp beni UNUTAMAYACAKSIN

Yaşanmışlıklar bitmişse

Aşk nağmeleri susmuşsa

Sevgiler tükenip yüreklerden silinse bile

Geçmişi hatırlayıp beni UNUTAMAYACAKSIN

Verilen sözler sunulan vaatler

Kulağa fısıldanan tatlı sözler

Hepsi şu an unutulmuş olsa bile

Sen yine de beni yaşayıp UNUTAMAYACAKSIN

Yatağında diken, rüyalarında kabusum

Kağıdında hüzün, kaleminde mutsuzluğun

Gözlerin buruk, kalbin kırık, hayaller yıkık

Geçmişi yaksan da beni asla UNUTAMAYACAKSIN...

16.05.2002', 'Boğazın deniz kokusunda Yediğin balığın tadında Attığın kahkahanın feryadında Aşkımızı hatırlayıp beni UNUTAMAYACAKSIN Yaşanmışlıklar bitmiş...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unutamayacaksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşla-ma!', 'tasla-ma-elif-atici-4xlyq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tavır koymaz, gülüp geçeriz 

Ağlanacak hallerimize

Kimin eli belli değil 

Hangimizin cebinde.

Dul muş, yetim miş,  fakir miş

Bana ne kardeşim, 

Biz mi istedik  sanki

Kerizler sürünsün diye.

Siyasilerde ise aynı nakarat

Hani yatım, hani katım? 

İlle de koltuğum

Rüşvet olmaz dostum 

Onu çaktırmadan

Yan cebime koyun.

En iyi çoban benim, 

Oy lar buraya

Sürüye katılan pişman olmaz 

Koyunlar, sandık başına sıraya 

hatırlılar! 

Sizleri alalım, gelin buraya

Devlet sınavı mı? 

Ehline bırak işi

Olmuş bil, takma kafaya

Çoğumuzun dileği

Rakıya, sigaraya gelmesin zam.

Çakır keyif olalım, 

Keyfimize dokunmayın aman! 

Uyuyan güzellere döndük

Millet çe biz

Bebelerimiz bile borçlu, 

Öyle de olurmu? demeyin hiç.

Memur mitinglerde

Çalar boş tencere

İşçiler boş yere mi sürünür grevlerde

Emekli dersen, ezelden çileli

Üç beş kuruş için, 

Emekçilerimiz kuyruklarda ölmemeli.

Esnafa bakarsak kepenk kapatmakta, 

Yazar kasalar sinirleri hoplatmakta.

Boş verin vekillerim...

Çiçek sulayın siz! 

Umutlarımızı toprağa gömdük

Ne yazık ki biz.

Bırakın arkadaşlar yatalım yine

Uykuya devam...

Hırsızlar, hortumcular, bankacılar

Güvendik sizlere

Kasalarımızı boşaltmayın aman.

İşine gelmediyse okuyup

Sakın deme ''TAŞLA-MA''

Unutma sakın! 

Fakirin tenceresi unuttu

Kaynatmıyor haşlama...

Hala diyorsak bize dokunmayan yılan, 

Uyanalım arkadaşlar zehirliyorlar her an.

Ülkemin insanları refahta olmalıydı

Atam halimizden utanç değil, 

Kıvanç duymalıydı...', 'Tavır koymaz, gülüp geçeriz  Ağlanacak hallerimize Kimin eli belli değil  Hangimizin cebinde. Dul muş, yetim miş,  fakir miş Bana ne kardeşi...', ARRAY['Türk Edebiyatı','Şiir','Elif Atıcı']::text[], 8.5, '{"poet":"Elif Atıcı","poet_slug":"elif-atici","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/tasla-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahardır Her Şey', 'sonbahardir-her-sey-omer-karatepe-ndgek', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'umut 

bir telli dosya

ve ütopyadır sence 

bir ceninin

tarihin şiirini yazması

aşk tanımaz kimliğini 

kaç gün akşamı bulur teninde

hangi büyü

hangi tılsım

saklar gerçeğini

tapınacak bir tanrı arar

ölümün yaklaştığını anlayan sesin

dostuna türküler yakarsın

ihbarıdır bu

birazdan almaya gelecekler

sonbahardır her şey

sonbahardır her şey

umut bir telli dosya

usunun arşivinde çürüyen

sonbahardır her şey

korkarım ki taklidiyim

benden önce düşen bir yaprağın

ve 

sorgusudur aslında 

yazılan her mısra

yere düşen bir yaprağın

sonbahardır her şey', 'umut  bir telli dosya ve ütopyadır sence  bir ceninin tarihin şiirini yazması aşk tanımaz kimliğini  kaç gün akşamı bulur teninde hangi büyü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karatepe']::text[], 8.5, '{"poet":"Ömer Karatepe","poet_slug":"omer-karatepe","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sonbahardir-her-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihatler', 'nasihatler-charles-bukowski-6tvbx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yeniden patlarken rüzgar denizden

toprak isyan ve kaosla lekelenirken

dikkatli kullan seçenek kılıcını

unutma

5 yüzyıl

veya 20 sene önce bile

asil denebilecek şeyler

şimdilerde daha ziyade 

boşa harcanmış eylem oluyor

bir kez yaşanıyor yaşam, 

oysa bir dolu şansı var tarihin

insanların aptallığını kanıtlayabileceği

öyleyse dikkatli ol derim

asil görünen herhangi bir

ideal

niyet

ya da eylem konusunda

bu ülkeden yana ol ya da aşktan

veya sanattan, sakın kapılma anın yakınlığına

yada koparılmış çıçek gibi kuruyacak bir

güzelliğe

ya da devlete; 

aşk, evet, ama evlilik görevi gibi değil, ve gözün açık olsun

kötü gıda ve aşırı çalışmaya; 

bir ülkede yaşaman gerekir, evet, 

ne var ki aşk ne kadının düzenidir

ne de ülkenin; 

acele etme, ve iç gerektiğince

ki kalabilesin yarına

çünkü içki, içenin yeni

bir yaşama şansına 

ulaştığı bir

yaşam tarzıdır, dahası, derim ki

mümkün olduğunca yalnız yaşa; 

çocuk yap yapacaksan

ama büyütme zahmetinden kaçınmaya

çalış; bedenindeki

yada ruhundaki

canı almaya çalışmadıkça düşman

sesli yada fiziksel

küçük tartışmalara girme, 

sonrada öldür gerekiyorsa; 

ve ölmek zamanı geldiğinde

bencil olma; 

masrafsız olduğunu düşün

ve gittiğin

yeri; 

ne utanç izi olsun ne başarısızlık

ne de bir

hüzün çağrısı

patlarken rüzgar denizden

akıp

gider zaman

yumuşak huzurla yıkayarak

kemiklerini

charles hank bukowski', 'yeniden patlarken rüzgar denizden toprak isyan ve kaosla lekelenirken dikkatli kullan seçenek kılıcını unutma 5 yüzyıl veya 20 sene önce bil...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/nasihatler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazıları Delirmez', 'bazilari-delirmez-charles-bukowski-mtayk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bazıları hiç delirmez

ben, bazen koltuğun arkasında

3-4 gün boyunca yattığım olur

orda bulurlar beni

melaikeymiş derler

sonra gırtlağımdan aşağı

şarap döküp

göğsümü ovarlar

yağ serperler üzerime

sonra kükreyerek kalkarım

atıp tutar, köpürürüm

onlara ve evrene küfreder

bahçeye kadar kovalarım

sonra kendimi çok iyi hisseder

tost ve yumurtanın başına otururum

bir şarkı mırıldanıp

aniden

pembe besili bir balina gibi

sevimli olurum

bazıları hiç delirmez

ne korkunç hayat sürüyorlardır

allah bilir

charles bukowski', 'bazıları hiç delirmez ben, bazen koltuğun arkasında 3-4 gün boyunca yattığım olur orda bulurlar beni melaikeymiş derler sonra gırtlağımdan a...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bazilari-delirmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-murat-cicek-a347q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O geceler boyu seni düşünmek yok mu? 

Kahrediyor beni.

Seni sensiz yaşamak o kadar ızdırap ki! 

Anlatamam.

Dün yine hayallerimdeydin 

Oturduk seninle, konuştuk uzun uzun

Havadan, sudan bahsettik 

İkimizden bahsettik 

Geleceğimizden, mutluluğumuzdan, 

Aşkımızdan bahsettik.

O kadar güzeldin ki, 

Hayaline bile aşık oldum.

Sonra bir çay bahçesine gittik seninle 

Sen bana bir şeyler anlatıyrdun, 

Bense senin güzelliğini süzüyordum.

Dudakların o kadar güzeldi ki 

Ağzından çıkan her bir kelime 

Bir müzik fısıltısı gibi geliyordu kulaklarıma.

Ne söylediğinin farkında bile değildim.

Zaman geçip ayrılğa koşar adımlarla ilerliyordu.

Ve bir horoz öttü ansızın, gözlerimi açtım 

Ve sensiz bir güne başlamanın o tarifsiz acıları içinde 

Sabahın ilk ışıkları ile kendimi boş sokaklara attım. 

(18.01.1998/pazar-saat: 02: 06)', 'O geceler boyu seni düşünmek yok mu?  Kahrediyor beni. Seni sensiz yaşamak o kadar ızdırap ki!  Anlatamam. Dün yine hayallerimdeydin  Oturdu...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ruya-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya 2', 'ruya-2-murat-cicek-1ergl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün yine bomboş sokaklarda dolandım.

Yalnız ve çaresiz 

Seni aradım bulamadım 

Yağmurlarla ıslandım

Ve bir gök gürültüsüyle uyandım

Rüya da olsa seni SEVDİĞİMİ anladım.

(26.11.1996/Salı)', 'Dün yine bomboş sokaklarda dolandım. Yalnız ve çaresiz  Seni aradım bulamadım  Yağmurlarla ıslandım Ve bir gök gürültüsüyle uyandım Rüya da ...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ruya-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya 3', 'ruya-3-murat-cicek-tew8c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum

Ellerini tutuyor, saçlarını okşuyorum.

Gözlerin nemli, gözlerin buğulu bakıyor 

Derinlere daha derinlere dalıyorum

Birden bir sessizlik giriyor araya 

Sessizlik! Sessizlik...

Ve bir ses duyuyorum 

    

        UYAN! ...', 'Seni düşünüyorum Ellerini tutuyor, saçlarını okşuyorum. Gözlerin nemli, gözlerin buğulu bakıyor  Derinlere daha derinlere dalıyorum Birden b...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruya-3-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara', 'sigara-rasit-biyikli-i583p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sigarayım içilmeye hazır

Duruyorum paketin içinde

Bir  tek al eline…

Sonra çıkart kibritini yak beni

Bir nefes çek dolayım ciğerine

Üfle sonra beni havaya

Bekleme bir nefes daha çek

Onuda savur boşluğa

Hadi hiç bekleme

Bir daha bir daha

İki dudağının arasında tut

Beni, bitene kadar

Bırak orada kalayım…

Direniyorum tükenmemeye

Ne çare sonum yaklaşıyor

Ve.. işte o an geldi

Ateşim izmarite dokunmakta

Bittim…

Lütfen, atma beni yere

Acı! ! ! 

Kalbime basan olur

Bak masada kültablası duruyor

Uzat elini koy bir köşesine.', 'Bir sigarayım içilmeye hazır Duruyorum paketin içinde Bir  tek al eline… Sonra çıkart kibritini yak beni Bir nefes çek dolayım ciğerine Üfle...', ARRAY['Türk Edebiyatı','Şiir','Rasit Biyikli']::text[], 8.5, '{"poet":"Rasit Biyikli","poet_slug":"rasit-biyikli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sigara-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ay-tutulmasi', 'ay-tutulmasi-claudio-lopez-ox3ah', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşka kefil mi gerek? 

Gönlüm zengindir benim.

Bütünüyle senin bu yürek! 

Söze şahit mi gerek? 

Sözüm doğrudur benim.

Geldim, seviyorum diyerek! 

Yeni aşklar neyime? 

Ruhuma Gülay gerek.

Ruhum onun oldu giderek! 

Derde derman mı gerek? 

Gönüle ferman mı? 

Gerçekten sevdim, isteyerek! 

Geceden kaybolur ay, 

Geceye ay mı gerek.

Gönlüme sordum çekinerek, 

Sana Gülay mı gerek? 

Gece içindir ki ay, 

Benim içindir Gülay.

Benim içimdir Gülay, 

Gönüle Gülay gerek! 

                                       16.06.2001', 'Aşka kefil mi gerek?  Gönlüm zengindir benim. Bütünüyle senin bu yürek!  Söze şahit mi gerek?  Sözüm doğrudur benim. Geldim, seviyorum diyer...', ARRAY['Türk Edebiyatı','Şiir','Claudio Lopez']::text[], 8.5, '{"poet":"Claudio Lopez","poet_slug":"claudio-lopez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ay-tutulmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor İş Beklemek', 'zor-i-s-beklemek-omer-avsar-oieuy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zordur beklemek sabır ister

dügümlenir söylenecek sözler

hep yaşlı olacak akan gözler

yarına kalacak tüm güzellikler

bilinmeze kurulacak zaman

hayaller kuracaksın durmadan

allaha açacaksın ellerini

kavuştursun diye sevenleri

düşe kalka ögreneceksin sevmeyi

sevipde beklemeyi severken ölmeyi

belki döküleceksin yapraklar gibi

lazım hepsi tıpkı yaşamak gibi...', 'zordur beklemek sabır ister dügümlenir söylenecek sözler hep yaşlı olacak akan gözler yarına kalacak tüm güzellikler bilinmeze kurulacak zam...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zor-is-beklemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Künyem', 'kunyem-ozan-arif-o7fej', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tevellüt; kırkdokuz, adım Arif`tir. 

Soyadım kütükte Şirin bilinir.

Giresun, Alucra, Hapu köyünden, 

Soyumu sopumu sorun bilinir. 

Ozan diye tanır tanıyan beni, 

Gönlümde yaşatmam garezi, kini, 

Ve lâkin memleket, millet haini

Olanlarla aram serin bilinir

Siz sakın sanmayın el vurdu bana; 

Öpmeye kalktığım el vurdu bana, 

Bülbül idim bülbül, gül vurdu bana, 

O yüzden dertlerim derin bilinir

Hakkımda istenen ceza çok benim.

İpe de çekseler, korkum yok benim.

Allah`a çok şükür, alnım ak benim.

Bekleyin... Sabredin... Durun bilinir

Ben Arif`im, baba bildim devleti.

Benim işim uyandırmak milleti.

Söylediğim bu destanın kıymeti, 

Bugün bilinmezse, yarın bilinir.', 'Tevellüt; kırkdokuz, adım Arif`tir.  Soyadım kütükte Şirin bilinir. Giresun, Alucra, Hapu köyünden,  Soyumu sopumu sorun bilinir.  Ozan diye...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kunyem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum', 'ariyorum-yusuf-yanc-8xepg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karamanoğlu Mehmet Bey''i arıyorum 

Göreniniz, bileniniz, duyanınız var mı? 

Bir ferman yayınlamıştı; 

''Bu günden sonra, divanda, dergahta, bargahta, mecliste, 

meydanda Türkçe''den başka dil konuşulmaya'' diye, 

Hatırlayanınız var mı? 

Dolanın yurdun dört bir yanını, 

Çarşıyı, pazarı, köyü, şehiri, 

Fermana uyanınız var mı? 

Nutkum tutuldu, şaşırdım, merak ettim, 

Dolandığınız yerlerdeki Türkçe olmayan isimlere, 

Gördüklerine, duyduklarına üzüleniniz var mı? 

Tanıtımın demo, sunucunun spiker, 

Gösteri adamının showmen, radyo sunucusunun diskjokey, 

Hanım ağanın first lady olduğuna şaşıranınız var mı? 

Dükkanın store, bakkalın market, torbasının poşet, 

Mağazanın süper, hiper, gros market, 

Ucuzluğun damping olduğuna kananınız var mı? 

İlan tahtasının bilboard, sayı tabelasının skorboard, 

Bilgi alışının brifing, bildirgenin deklarasyon, 

Merakın, uğraşın hobby olduğuna güleniniz var mı? 

Bırakın eli, özün bile seyrek uğradığı, 

Beldelerin girişinde welcome, 

Çıkışında goodbye okuyanınız var mı? 

Korumanın, muhafızın body guard, 

Sanat ve meslek pirlerinin duayen, 

İtibarın, saygınlığın prestij olduğunu bileniniz var mı? 

Sekinin, alanın platform, merkezin center, 

Büyüğün mega, küçüğün mikro, sonun final, 

Özlemin, hasretin nostalji olduğunu öğreneniniz var mı? 

İş hanımızı plaza, bedestenimizi galeria, 

Sergi yerlerimizi center room, show room, 

Büyük şehirlerimizi mega kent diye gezeniniz var mı? 

Yol üstü lokantamızın fast food, 

Yemek çeşitlerimizin menü, 

Hesabını adisyon diye ödeyeniniz var mı? 

İki katlı evinizi dubleks, üç katlı komşu evini tripleks, 

Köşklerimizi villa, eşiğimizi antre, 

Bahçe çiçeklerini flora diye koklayanınız var mı? 

Sevimlinin sempatik, sevimsizin antipatik, 

Vurguncunun spekülatör, eşkiyanın mafya, 

Desteğe, bilemediniz koltuk çıkmaya sponsorluk diyeniniz var mı? 

Mesireyi, kır gezisini picnic, 

Bilgisayarı computer, hava yastığını air bag, 

Eh pek olasıcalar, oluru, pekalayı okey diye konuşanınız var mı? 

Çarpıcı, önemli haberler flash haber, 

Yaşa, varol sevinçleri oley oley, 

Yıldızları star diye seyredeniniz var mı? 

Vırvırık dağının tepesindeki köyde, 

Cafe shop levhasının altında, 

Acının da acısı kahve içeniniz var mı? 

Toprağımızı, bayrağımızı, inancımızı çaldırmayalım derken, 

Dilimizin çalındığını, talan edildiğini, 

Özün el diline özendiğine içiniz yananınız var mı? 

Masallarımızı, tekerlemelerimizi, atasözlerimizi unuttuk, 

Şarkılarımızı, türkülerimizi, ninnilerimizi kaybettik, 

Türkçemiz elden gidiyor, dizini döveniniz var mı? 

Karamanoğlu Mehmet Bey''i arıyorum, 

Göreniniz, bileniniz, duyanınız var mı? 

Bir ferman yayınlamıştı... 

Hayal meyal hatırlayıp da, sahip çıkanınız var mı?', 'Karamanoğlu Mehmet Bey''i arıyorum  Göreniniz, bileniniz, duyanınız var mı?  Bir ferman yayınlamıştı;  ''Bu günden sonra, divanda, dergahta, b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Yanç']::text[], 8.5, '{"poet":"Yusuf Yanç","poet_slug":"yusuf-yanc","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/ariyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğin Yere', 'gidecegin-yere-halil-soyuer-ttujl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gideceğin yere beni de götür 

Sorana derdimin dermanı dersin. 

Götür de istersen sokakta yatır 

Elimde gönlünün fermanı dersin 

Adını iğneyle işle derime 

Kölemdir desen de gitmez arıma 

''Bunlar ne? '' derlerse mektuplarıma 

Mahvolmuş bir ömrün romanı dersin 

Duysalar da coşup çağladığımı 

Bilmezler sana bel bağladığımı 

Görenler olursa ağladığımı 

Fırat''ın en coşkun zamanı desin.', 'Gideceğin yere beni de götür  Sorana derdimin dermanı dersin.  Götür de istersen sokakta yatır  Elimde gönlünün fermanı dersin  Adını iğneyl...', ARRAY['Türk Edebiyatı','Şiir','Halil Soyuer']::text[], 8.5, '{"poet":"Halil Soyuer","poet_slug":"halil-soyuer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidecegin-yere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Sen', 'ben-ve-sen-erman-mert-celik-xcnh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ve sen

Hiç uymuyorduk birbirimize

Ben ve sen yan yana geldiğimizde

Ben sevda birikintisiyle dolu,                                                                                                              Eski yıpranmış ve bana bir beden büyük gelen

Bir ceket giydiğimi hissediyordum

Ben ve sen...! 

Hiç tanımlayamadım sedamızı

Sanki sen kindin ben sevgi

Çok sonra fark ettim

İkimizin de aynı petekte bal yaptığını

Çok sonra fark ettim...! 

Beni inciten ilk şeyin

Sevdan olduğunu....

Ama nafile...! 

Ben ve sen

Artık ayrı dünyaların insanıydık...! 

ERMAN MERT ÇELİK', 'Ben ve sen Hiç uymuyorduk birbirimize Ben ve sen yan yana geldiğimizde Ben sevda birikintisiyle dolu,                                       ...', ARRAY['Türk Edebiyatı','Şiir','Erman Mert Çelik']::text[], 8.5, '{"poet":"Erman Mert Çelik","poet_slug":"erman-mert-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-ve-sen-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonun Şiiri', 'sonun-siiri-sari-pisi-qk8q9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dönüşü olmayan son gidiş bu

Ne bir el sallayan var ardından

Ne de bir elveda diyen

Son bir selam çakıp yaşananlara

Merhaba demek yeni bir hayata

Belki öksüz yine tek başına

Ama yüreğimiz hep birlikte

                                   Elveda Belde', 'Dönüşü olmayan son gidiş bu Ne bir el sallayan var ardından Ne de bir elveda diyen Son bir selam çakıp yaşananlara Merhaba demek yeni bir ha...', ARRAY['Türk Edebiyatı','Şiir','Sarı Pisi']::text[], 8.5, '{"poet":"Sarı Pisi","poet_slug":"sari-pisi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sonun-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustu', 'sustu-halil-soyuer-mh66r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün sabah bir kişi çıktı karşıma

Ömründeki yıllar kaç dedi, sustu.

Nasılda yıkılmış üstüne zaman, 

Ne biçim ağarmış saç dedi, sustu.



Siz kimsiniz dedim, , necisin nesin? 

Halinden besbelli, endişelisin.

Neden kısık kısık çıkıyor sesin? 

Belli ki utandı hiç dedi sustu.



Olma dedi, Martta yağan kar gibi

Dalında her mevsim meyve  ver gibi

Serçe gibi değil, kartallar gibi

Her zaman yüksekte uç dedi, sustu.



Kimseye sır verme dedi boş yere

Bir avuç yağmurla bulanır dere

Her sabah gözünü güzel günlere

Ölünceye kadar aç dedi, sustu.



Başına ağ örmüş, yıllar aklarda

Varına çiğ düşmüş dedi; yoklada

Bekleme, kendinden kaç dedi, sustu.



Gün gelir çıktığın yerden inersin

Gün gelir, geldiğin yere dönersin

Bazen yenilirsin, bazen yenersin

Hayat bir bitmeyen maç dedi, sustu.', 'Dün sabah bir kişi çıktı karşıma Ömründeki yıllar kaç dedi, sustu. Nasılda yıkılmış üstüne zaman,  Ne biçim ağarmış saç dedi, sustu. Siz kim...', ARRAY['Türk Edebiyatı','Şiir','Halil Soyuer']::text[], 8.5, '{"poet":"Halil Soyuer","poet_slug":"halil-soyuer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-abdullah-yuce-9gr6d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzaklara uzanır muhabbet

Uzakları görür gönül! 

Sıcaksa yürek

''Yürekten''

Isıtır uzakları.

Dost engel tanımaz.

Uzaklara meydan okuyor

Seni selamlıyorum', 'Uzaklara uzanır muhabbet Uzakları görür gönül!  Sıcaksa yürek ''Yürekten'' Isıtır uzakları. Dost engel tanımaz. Uzaklara meydan okuyor Seni se...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yüce']::text[], 8.5, '{"poet":"Abdullah Yüce","poet_slug":"abdullah-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gonul-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serin Geceler', 'serin-geceler-abdullah-yuce-8qb1l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani uyku tutmuyor ya beni

Anladım sebebini sevgilim.

Gözlerin gitmiyor gözlerimden

Gün bitmedi sanıyorum.

Bu serin gecelerde ben, 

Gözlerinde kaybolup  aşkınla yanıyorum.

Seni seviyorum

Seni seviyorum.', 'Hani uyku tutmuyor ya beni Anladım sebebini sevgilim. Gözlerin gitmiyor gözlerimden Gün bitmedi sanıyorum. Bu serin gecelerde ben,  Gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yüce']::text[], 8.5, '{"poet":"Abdullah Yüce","poet_slug":"abdullah-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/serin-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Say ki!', 'say-ki-mehmet-karatas-ie69b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ilık ılık bir sevda akar yüreğime,

Say ki dağlar oynar yerinden,

Yalçın kayalar parçalanır.

Korkarım...

İhanetler, acılar gelir aklıma

Kaçarım...

Say ki volkanlar patlar yüreğimden

Geceler kabusum olur,

Çıldırırım...', 'Ilık ılık bir sevda akar yüreğime, Say ki dağlar oynar yerinden, Yalçın kayalar parçalanır. Korkarım... İhanetler, acılar gelir aklıma Kaçar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/say-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadığım Hayat Dersleri', 'anlatamadigim-hayat-dersleri-muhtesem-oksel-u07a1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kız tanıdım, 

Umut doluydu kalbi, 

Masumdu gözleri.

Bir kız tanıdım, 

Hayat onun için

Siyah ve beyazdan ibaretti.

Bir kız tanıdım, 

Sadece kendiyle ilgili, 

Değiştirebileceğini düşünen her şeyi.

Acaba ben de onun gibi miydim? 

Bulutlar üstünde uçan.

Ne zaman anladım? 

Hayatın ibaret olmadığını

Siyah ve beyazdan.

Ne zaman fark ettim? 

Grilerin varlığını.

At gözlüğü müydü? 

Yoksa pembe bir gözlük müydü? 

Bana düşündüren

Her şeyi değiştirebileceğimi, 

Her güçlüğü yenebileceğimi.

Ne zaman yedim ilk kazığı? 

İlk defa ne zaman kaybettim? 

Ne zaman bitti masumiyet çağı? 

Her çöküşün ve bitişin ardından

Kim bilir kaç kez dirildim.

Bir kız tanıdım, 

Bir midyenin içinde

Bir inci gibiydi.

Daha bilmiyordu, 

İçinde yaşadığı denizi.

Bir kız tanıdım, 

Bir kozanın içinde

Bir ipek böceğiydi.

Bekliyordu kelebek olmayı

Ve umuyordu kırlarda uçmayı

Bir kız tanıdım, 

Daha yaşıyordu masumiyet çağını.

Söylemek, anlatmak isterdim, 

Daha neler göreceksin diye.

Anlatamadım, kıyamadım.

O midyenin içinde bir inciyken, 

O kozada bir kelebek olmayı beklerken, 

Anlatsam da anlamayacaktı, 

Anlatsam da inanmayacaktı.', 'Bir kız tanıdım,  Umut doluydu kalbi,  Masumdu gözleri. Bir kız tanıdım,  Hayat onun için Siyah ve beyazdan ibaretti. Bir kız tanıdım,  Sade...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/anlatamadigim-hayat-dersleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin ve Kediler', 'guvercin-ve-kediler-duygu-gunkut-p6a9p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kentimde aç kalan güvercinler, 

Sobeler beni penceremde

Sabaha karşı

Kediler kaçıncı uykuda, 

Ekmek kırıntıları doyurmaz

Ne siz güvercinleri, 

Ne de kediler memnun yumurtalarınızdan.

Bana kalmış

Uykusuzluk

Güneş doğumları

Ve az da özlem, 

Kurdu kuşa yedirmeyen.', 'Kentimde aç kalan güvercinler,  Sobeler beni penceremde Sabaha karşı Kediler kaçıncı uykuda,  Ekmek kırıntıları doyurmaz Ne siz güvercinleri...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guvercin-ve-kediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Sen', 'yalniz-sen-sait-ferhat-ozmen-r8rxc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimi yakan sevgin kadar

Sıcak olsaydı güneş, 

Sana özlemim kadar

Yüksek olsaydı Kaf Dağı, 

Senin olduğun kadar

Erişilmez olsaydı mutluluk

Ve sen gibi, 

Senin kadar olsaydı

Bir Allah''ın kulu, 

Ben seni sevmekten yine de vazgeçmezdim.

Ama seni sevdiğim kadar 

Güneşi, Kaf Dağı''nı ve mutluluğu da severdim.

Oysa ben şimdi sadece

SENİ SEVİYORUM....', 'Yüreğimi yakan sevgin kadar Sıcak olsaydı güneş,  Sana özlemim kadar Yüksek olsaydı Kaf Dağı,  Senin olduğun kadar Erişilmez olsaydı mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalniz-sen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Kirli Devirde', 'su-kirli-devirde-kamil-aydemir-twqff', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her şeyin para olduğu şu kirli devirde

bilmem ki ne buldun bende

yüzemesin bolluklar içinde

kazancım alınterimle

yürekten sevmeler kalır geriye

aşk sarhoşu olmak istiyorsan takıl

para her şey değil diyen

benim gibi bir deliye', 'her şeyin para olduğu şu kirli devirde bilmem ki ne buldun bende yüzemesin bolluklar içinde kazancım alınterimle yürekten sevmeler kalır ger...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/su-kirli-devirde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdadır', 'sevdadir-suleyman-apaydin-4mj4g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak çocuğum iyi dinle

Son dersimdir bu sizinle

Avucuna al da bir bak

Üstünde durduğun toprak

Atatürk''ten armağandır

Vaz geçilmez bir sevdadır

Dere tepe şu düz bayır

Yeşil ova sarı bozkır

Çanakkale Seddilbahir

Her zerresi bir destandır

Atatürk''ten armağandır

Vaz geçilmez bir sevdadır

Gaziantep Şanlıurfa

Diyarbakır yeşil Bursa

Edirne Van Kars Ardahan

Uçtan uca bütün vatan

Atatürk''ten armağandır

Vaz geçilmez bir sevdadır

Ülkemizde çağa dönük

Ne var ise hep aydınlık

Bilim sanat ve hürriyet

Çağdaş laik cumhuriyet

Atatürk''ten armağandır

Vaz geçilmez bir sevdadır

Kaldır da başını bir bak

Gökyüzü ne kadar berrak

Özgürlüğünün simgesi

Ay yıldızlı kızıl bayrak

Atatürk''ten armağandır

Vaz geçilmez bir sevdadır

Hurafeden kurtulduğun

Yüzünü güneşe döndüğün

Uygarlığın özgürlüğün

Ne varsa sahip olduğun

Atatürk''ten armağandır

Vazgeçilmez bir sevdadır

Sakın bunları unutma

Kol kanat ger sen yurduna

Bilmeyene masal gelir

Masal değil bir destandır

Atatürk''ten armağandır

Vazgeçilmez bir sevdadır', 'Bak çocuğum iyi dinle Son dersimdir bu sizinle Avucuna al da bir bak Üstünde durduğun toprak Atatürk''ten armağandır Vaz geçilmez bir sevdadı...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sevdadir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni İstiyorum', 'ben-seni-i-stiyorum-sait-ferhat-ozmen-rx428', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok özledim seni

Bendeki seni.

Kokun geliyor burnuma, 

Sesin zaten hep kulağımda.

Sevgini de hissediyorum

Aslında ruhumda.

Ama yetmiyor hiç biri...

Ben sana doymak istiyorum, 

Doyurmanı beni.

Ben seni istiyorum, 

Hissettirdiklerinin  yanında bedenini, tenini, 

Seni istiyorum, 

Ben seni istiyorum.......', 'Çok özledim seni Bendeki seni. Kokun geliyor burnuma,  Sesin zaten hep kulağımda. Sevgini de hissediyorum Aslında ruhumda. Ama yetmiyor hiç ...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-seni-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Günlerim', 'huzunlu-gunlerim-ozcan-nevres-kjqbr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüzünlü Günlerim

Hüzzam şarkılarının nağmeleri 

Bir hüzün seli gibi akarken gönlüme

Nice olumsuzluklar dizilir 

Gözlerimin önüne

Karlar beyaz bir çarşaf gibi

Serilince kentin üstüne

Soğuyan hava olumsuzlukları yığdı 

Altından kalkılamasın diye

Minik kuş buz altındaki yemi 

Var gücüyle gagaladı 

Alamadı

Balkonlara uçtu bir kırıntı bulurum umuduyla

Sert poyrazda savruldu oradan oraya

Zor attı kendini kuytu bir yere

Donup ölmektense

Açlığı çekti sineye

Sefa koymuşlardı çocuğun adını

Tüm ömrü sefalı geçsin diye

Dilek tutmadı

Çocukluğunu yaşayamadan

Sokaklarda buldu kendini

Açlık ve sefalet içinde

Umutlar sokaklarda tükenince

Tinerler baliler oldu umudu

Soğuk bir gecede yorgun bedeni

Yokluğa yoksulluğa dayanamadı

Minik kuş kadar bile olamadı

Sıcak  bir mekan bulamadı

Teslim oldu soğuğa 

Daha fazla direnemedi

Sabaha karşı buldular cansız bedeni

Vah! ! ! Yazık oldu dediler

Bu zamansız ölümdeki nedeni 

Bilmek istemediler

Bir de utanmadan 

Çocuklar ölmesin derler

Hani nerede bu sosyal devlet

Hani nerede yardımseverlik adına

Televizyonlarda boy gösterenler

Vah! ! ! Demekle döner mi gidenler

Giden gider kalan sağlar bize yeter

Bu düzen böyle kurulmuş

Değiştirmeye kimin gücü yeter

			Özcan NEVRES', 'Hüzünlü Günlerim Hüzzam şarkılarının nağmeleri  Bir hüzün seli gibi akarken gönlüme Nice olumsuzluklar dizilir  Gözlerimin önüne Karlar beya...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/huzunlu-gunlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Diye', 'sen-yoksun-diye-ozcan-nevres-mgins', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen Yoksun Diye

Gönlüme bir hüzün çöktü yine

Yanımda sen yoksun diye

Varlığına alışmışım ki öylesine

Yokluğun dağ gibi çöküyor üstüme

Ayrılık neden zor böyle

Neden yokluğun çekilmez oluyor

Mutluluğum sanki dizlerinin dibinde

Bazen ölümü düşünüyorum

Ölmekten çok, ama çok korkuyorum

Ölmekten değil sevgilim 

Senden ayrı kalmaktan korkuyorum

			Özcan NEVRES

25 Şubat 2002', 'Sen Yoksun Diye Gönlüme bir hüzün çöktü yine Yanımda sen yoksun diye Varlığına alışmışım ki öylesine Yokluğun dağ gibi çöküyor üstüme Ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-yoksun-diye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim Sende Tutsak', 'duslerim-sende-tutsak-kamil-aydemir-5xzof', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'siyahlar giyinmişsin baştan sona

çıplaklığın kadar yakışmış inan sana

bendeki yerin başkası dolduramayacak kadar derin

perdenin açık kalan yerinden

içeri sızan ışık gözlerin

dudakların kor

memleketimden de güzelsin

sana doymak zor

ateşini alayım dudaklarından

dişiliğin dökülüyor her yanından

kendimi kurtaramıyorum o gizemli halinden

göbeğinin çukurunda mutluluk soframızı kusak

düşlerim sende tutsak', 'siyahlar giyinmişsin baştan sona çıplaklığın kadar yakışmış inan sana bendeki yerin başkası dolduramayacak kadar derin perdenin açık kalan y...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/duslerim-sende-tutsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuz Geceler', 'uykusuz-geceler-ozcan-nevres-cx5ti', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uykusuz Geceler

Sensizliğe alışamadığım bu yatak

Neden bana böylesine düşman

Isınamıyorum bir türlü

Üşüyorum ölesiye

Hissediyor musun

Nasıl da takırdıyor dişlerim

Seni düşleyeceğim yine

Umutsuz ve umarsız

Hayaline sarılacağım sımsıkı

Yüreğimde

Sımsıcak seller oluşacak 

Sana akacakmış gibi

Hayallerim taşa çarpmışçasına

Bir sırça gibi param parça olduğunda

Kutupların ayazında kalmışçasına

Üşüyeceğim iliklerim donacak

Kalkıp çıkacağım

Kentin ıssız sokaklarına

Sokak köpekleri ters ters bakacaklar bana

Hırlayıp havlayacaklar

Kim bu dercesine

Sarhoşun biri 

Kırk yıllık dostummuş gibi

Sokulacak yanıma

Abi, bir sigara versene diyecek

Sigara paketini uzatacağım ona

Çakmağının ışığında

Uzun uzun süzecek beni

Belki de diyecek

Bu da bizden biri

Gel be abi oturalım şuraya

Sana anlatacağım ne dertlerim var

Bir vefasızı sevdim bir zamanlar

Beni terk ettiğinden beri 

Hep içerim unutana kadar

Neylersin be abi 

Unutabilmenin var mı başka çaresi

Terk edilmişliğim yetmezmiş gibi 

Oturup teselli vereceğim ona

Sigaralar yakılacak peş peşe

Paket boşalıp bittiğinde

Gün ağarmış olacak

İyi uykular dileyeceğiz birbirimize

Yitik umutlarımız peşimizde

Evlerimize yöneleceğiz

Onda, akşam olsa da

Yine meyhaneye gitme

Bende ise sana kavuşma özlemi

Bir meyhanenin

Sigara ve anason kokulu havasında

Unutmak mümkün olsaydı seni

İnan bana sevgilim

Balık olurdum kadehlerde

Ben ağlamakta buldum 

Sensizliğe katlanmanın yolunu

Sensiz geceler öylesine uzun

Bu gecenin sabahı var mı

Bilemiyorum

Belki de bu gece

Göz yaşlarımda boğulurum

Ve seni

Sensiz yaşamaktan kurtulurum

			Özcan NEVRES', 'Uykusuz Geceler Sensizliğe alışamadığım bu yatak Neden bana böylesine düşman Isınamıyorum bir türlü Üşüyorum ölesiye Hissediyor musun Nasıl ...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/uykusuz-geceler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Sürtünerek Geçiyor Yaralarıma', 'hasretin-surtunerek-geciyor-yaralarima-kamil-aydemir-f7475', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dermanlığa görmek

uzaktan uzağa sevmek yetmiyor

mektupların saçların gibi üzerimi örtmüyor

vadisine akan su gibi akmalıyım

çiçek bahçesi bedenine

uğrarken en mahrem yerlerine

tabuların sınır gibi dikilmemeli önüme

mutluluğu dinlemeliyim kalbinden

uzanıp göbeğin çukuruna

gözgöze gelmeler

sevgiyi sözcüklere yüklemeler yetmiyor

kiraz dudaklarını ver dudaklarıma

hasretin sürtünerek geçiyor yaralarıma', 'dermanlığa görmek uzaktan uzağa sevmek yetmiyor mektupların saçların gibi üzerimi örtmüyor vadisine akan su gibi akmalıyım çiçek bahçesi bed...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hasretin-surtunerek-geciyor-yaralarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hor Kullandın Sevgimi', 'hor-kullandin-sevgimi-kamil-aydemir-uh0k4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ihanetine yataklığa serdin yokluğumu

oysa gidişim dönüşsüz değildi

ilk değil bizimkisi

nice aşklar kirli yüreklere yenildi

bakışlarınla eşmeseydin beni kanamazdım şimdi

yaşamın mutsuzlar sokağından

çekip alamıyorum kendimi

hor kullandın sevgimi

yanlışlarına tosladıkça kendini

mendilliğe uzatırım yine de

sevgi tarlası yüreğimi

sevgim sana yetmedi mi', 'ihanetine yataklığa serdin yokluğumu oysa gidişim dönüşsüz değildi ilk değil bizimkisi nice aşklar kirli yüreklere yenildi bakışlarınla eşme...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hor-kullandin-sevgimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arılar', 'arilar-kamil-aydemir-86qwc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'arıların sırrı nedir

çiçekler nasıl etkilenir

şu çelimsiz ufacık böcekten

arılar rüşfetçidir

bal gibi rüşfet alır

konduğu her çiçekten', 'arıların sırrı nedir çiçekler nasıl etkilenir şu çelimsiz ufacık böcekten arılar rüşfetçidir bal gibi rüşfet alır konduğu her çiçekten...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/arilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkmayın', 'korkmayin-kamil-aydemir-9dtsx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'o güzellikler nerde kaldı

insanlığımızı kimler koparıp aldı

her günün aynasında

kendinize bakında halinize ağlayın

gözlerinizin ucuyla geğil

yaşamı yüreğinizle kucaklayın

çocukları kanatan acıları

dipsiz kuyulara atmak için

yaşamın her yerinden toplayın

insanlığa çıkıyorsa

yürüdüğünüz yoldan korkmayın', 'o güzellikler nerde kaldı insanlığımızı kimler koparıp aldı her günün aynasında kendinize bakında halinize ağlayın gözlerinizin ucuyla geğil...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/korkmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Seni Seviyor', 'canim-seni-seviyor-sait-ferhat-ozmen-5b0r3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canım seni istiyor biliyor musun? 

Bazen sadece sesini duymayı, 

Bazen sıkı sıkı sarılmayı, 

Bazen de doya doya koklamayı....

Ama canım hep seni istiyor biliyor musun? 

Bir ''merhaba'' idin önce bende, 

Sonra ara sıra merhaba dediğim, 

Daha sonra merhaba demeden duramadığım, 

Şimdi bir merhabanın yetmediğisin.

Canım seni istiyor biliyor musun? 

Sana ''seni seviyorum '' bile diyemiyorum artık, 

Uzaktan herkes sever biliyorum.

Sana ''ama sen benim hep yanımdasın'' diyemiyorum, 

Seni ara sırada olsa yalnız bıraktığımı biliyorum.

Seni özlediğimi biliyorum, 

Ama sana bu özlemi anlatacak kelimeleri bulamıyorum.

Canım seni istiyor biliyor musun? 

Ama ne sesini, ne nefesini, ne de bedenini; 

Canım benliğini yanımda istiyor biliyor musun? 

Canım sabah kalktığımda kokunu duymak, 

Gece yanımda nefesini hissetmek istiyor

Biliyor musun? 

Ve bildiğini bilmek

Ama bir şey yapamamak beni hergün öldürüyor.

Biliyor musun? 

Canım seni istemeye korkuyor ama

Canım seni istiyor, 

Canım seni seviyor

BİLİYOR MUSUN...! ! !', 'Canım seni istiyor biliyor musun?  Bazen sadece sesini duymayı,  Bazen sıkı sıkı sarılmayı,  Bazen de doya doya koklamayı.... Ama canım hep ...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/canim-seni-seviyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendi Oğlum', 'efendi-oglum-kamil-aydemir-fbw7j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kahvaltısını ellerimle hazırladın

oğlumu okula gönderdim

o günden beri camda asılı kaldım

barış''ım her gece rüyalarıma giriyor

- anne kaç yıl oldu da

mezarıma bile gelmedin- diyor

babası kahrından konuşmuyor

bacısının yanaklarına gamzeleri düşmüyor

oğlumun çok sevdiği buğda gevreği

artık evimizde pişmiyor

hukukçu olmasına bir ayı vardı

canlıları yaşatmanın yollarını arardı

karanlığı sazıyla yarardı

hüzünleri (ni)   türkülerle sarardı

akşamları sokaklarda

çocuklarla top oynardı

kitaplarla evliydi

silahları hiç sevmezdi

ne kadar da haklıymış

oy için

kültablasında kül bırakmayanlara güvenmezdi

polis otosunda görmüşler en son

yıllar geçti oğlum evine dönmedi

aramadığım yer kalmdı

cumartesi annelerine katıldım

sessizliği yırtarcasına bağırdım

hiçbir cezaevinden sesi yükselmedi

çocuk gibi ağladım savcı bey

ömrümde ilk kez yalvardım

polisler sanki bize düşman

oy verdiklerimizin kapısını çaldım 

oldum pişman

unutma ki ben bir anayım ana

daha nasıl anlatayım derdimi sana

efendi oğlum uzat yardım elini bana

hiç olmasa yavrumun mezarını bileyim

benim yaşadıklarımı hiç bir ana yaşamasın

budur son dileğim', 'kahvaltısını ellerimle hazırladın oğlumu okula gönderdim o günden beri camda asılı kaldım barış''ım her gece rüyalarıma giriyor - anne kaç yı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/efendi-oglum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Olursa', 'sabah-olursa-tevfik-fikret-jmr1m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu memlekette de bir gün sabah olursa, Halûk,

Eğer bu memleketin sislenen şu nâsiye-i

Mukadderâtı, kavî bir elin kavî, muhyî

Bir ihtizâz-ı temâsıyla silkinip şu donuk,

Şu paslı çehre-i millet biraz gülerse... O gün

Ben ölmemiş bile olsam, haya pek ölgün

Bir irtibâtım olur şüphesiz; -O gün benden

Ümîdi kes, beni kötrüm ve boş muhîtimde

Merâretimle unut; çünkü leng ü pejmürde

Nazarlarım seni mâziye çekmek ister; sen

Bütün hüvviyet ü uzviyyetinle âtîsin:

Terennüm eyliyor el an kulaklarımda sesin! 

Evet, sabah olacaktır, sabah olur, geceler,

Tulû-i haşre kadar sürmez; akıbet bu semâ,

bu mâi gök bize bir gün acır; melûl olma.

Hayatta neş e güneştir, melâl içinde beşer,

Çürür bizim gibi... Siz, ey fezâ-yı ferdânın

Küçük güneşleri, artık birer birer uyanın! 

Ufukların ebedî iştiyâkı var nûra.

Tenevvür... Asrımızın işte rûh-ı âmâli; 

Silin bulutları, silkin zılâl-i ehvâli; 

Ziyâ içinde koşun bir halâs-ı meşkûra.

Ümidimiz bu: Ölürsek de biz, yaşar mutlaka.

Vatan sizinle, şu zindan karanlığından uzak! 

Günümüz Türkçesi...

Bu memlekette de bir gün sabah olursa, Haluk,

Eğer bu memleketin sislenen alın yazısı

Dirençli, dinç bir elin güçlü, canlılık verici

Dokunmasındaki titremle silkinip, şu donuk,

Şu paslanan yüzü halkın biraz gülerse... - O gün

Ben ölmemiş bile olsam, hayata pek ölgün,

Pek az ilişkim olur kuşkusuz; - o gün benden

Ümidi kes; beni kötrüm ve boş muhitimde

Bütün acımla unut; çünkü kör, topal, tükenik

Bakışlarım seni geçmişte görmek ister; sen

Bütün etin, kemiğin, kimliğinle yarısın:

Ve şarkılar gibi hep hep kulaklarımda sesin...

Evet, sabah olacaktır, sabah olursa, geceler

Geçer, kıyamete dek sürmez; en sonunda bu gök

Bu mavi gök size bir gün acır; usanma sakın.

Hayata neş''e güneştir, usanç içinde kişi

Çürür bizim gibi... Siz, ey yarın uzaylıların

Küçük güneşleri, artık birer birer uyanın! 

Tükenmez özlemi vardır ufukların ışığa,

Işık, ışık... Bugünün işte ruhu, özlemi bu; 

Silin bulutları, silkin o korku gölgesini,

Koşun ışıklar içinden o kutlu kurtuluşa.

Ümidimiz bu; ölürsek de biz, yaşar mutlak

Vatan sizinle şu zindan karanlığından uzak! 

Günümüz Türkçesine Aktaran: Ahmet Muhip Dıranas', 'Bu memlekette de bir gün sabah olursa, Halûk, Eğer bu memleketin sislenen şu nâsiye-i Mukadderâtı, kavî bir elin kavî, muhyî Bir ihtizâz-ı t...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sabah-olursa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuğla', 'tugla-mustafa-sureyya-sezgin-8axiq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ülkemin geleceği

Benim ellerimde.

Eğer çocuğumun kafasını

Düzgün tuğlalarla örersem.

Ülkenin geleceği

Senin ellerinde

Eğer çocuğunun kafasını

Düzgün tuğlalarla örersen.

Ülkemizin geleceği

Bizim ellerimizde

Eğer kafalarımız

Düzgün tuğlalarla örülüyse.

(İstanbul,19.08.1995)', 'Ülkemin geleceği Benim ellerimde. Eğer çocuğumun kafasını Düzgün tuğlalarla örersem. Ülkenin geleceği Senin ellerinde Eğer çocuğunun kafasın...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tugla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalıyız Yar...', 'sevdaliyiz-yar-mustafa-sureyya-sezgin-lh5hd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinde

Sevda okunuyor bu gece.

Oysa ellerim zincirli

Dokunamıyorum yüzüne...

Bu gece, 

Bakışlar kadeh kadeh

Hüzünler yudum yudum.

Sevdalıyız, sevdalıyız yar...

Ah neye yarar! ..

Yüreğin yok etmesin 

Aklını sakın.

Sen istersen

Bir başka bedeni sar yarın.

Salıver beni

Gideyim önünde

Sonbahar rüzgarının...

(İstanbul,22.08.1995)', 'Gözlerinde Sevda okunuyor bu gece. Oysa ellerim zincirli Dokunamıyorum yüzüne... Bu gece,  Bakışlar kadeh kadeh Hüzünler yudum yudum. Sevdal...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdaliyiz-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anı', 'ani-mustafa-sureyya-sezgin-zaf09', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duygularım, 

Özlemlerim, 

Umutlarım

Sen de odaklaştığında, 

Şiir oluyor.

Duyuyorum, 

Yaşıyorum, 

Gizliyorum, 

Anı oluyor.

(İstanbul,25.08.1995)', 'Duygularım,  Özlemlerim,  Umutlarım Sen de odaklaştığında,  Şiir oluyor. Duyuyorum,  Yaşıyorum,  Gizliyorum,  Anı oluyor. (İstanbul,25.08.19...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ani-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Roman', 'roman-mustafa-sureyya-sezgin-y9zua', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dön şöyle, 

Arkana bir bak, 

Geçmiş bir rüya gibi.

Yaşadık mı acaba, 

O sevdalı günleri? 

Gönül bahçelerinden

Devşirdik mi gülleri? 

Zaman yolcusuyuız biz, 

Anılar döşenirken

Geçtiğimiz yollara, 

Tüm yaşadıklarımız

Benziyor bir romana.

(İstanbul,25.08.1995)', 'Dön şöyle,  Arkana bir bak,  Geçmiş bir rüya gibi. Yaşadık mı acaba,  O sevdalı günleri?  Gönül bahçelerinden Devşirdik mi gülleri?  Zaman y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/roman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Sevda', 'suskun-sevda-mustafa-sureyya-sezgin-8yf7j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Söylemek istediğim

Çok şeyim var sana.

Fakat nasıl söyleyebilirim, 

Nasıl anlatabilirim ki

Bu çapraşık ortamda? 

Eğer konuşmaya başlarsam, 

Dile getirirsem sevgimi, 

Ne olur dinleme sakın

Anında sustur beni...

(İstanbul,28.08.1995)', 'Söylemek istediğim Çok şeyim var sana. Fakat nasıl söyleyebilirim,  Nasıl anlatabilirim ki Bu çapraşık ortamda?  Eğer konuşmaya başlarsam,  ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/suskun-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyimser Şiir', 'i-yimser-siir-deral-baran-55bgv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göğe değmeli ellerimiz

Kardeşçe 

Tutkuyla  sarılmalı 

Sevgiliye 

Koklarken ayırt etmemeli 

Gülü karanfili zambağı

En düşman hallere 

Gülümseyebilmeli 

En yalın haliyle 

Yaşamalı..dosdoğru, yalansız

Sevebilmeli karanlığı da 

Aydınlık gibi...

Deral 

18 mayıs 2002 ist', 'Göğe değmeli ellerimiz Kardeşçe  Tutkuyla  sarılmalı  Sevgiliye  Koklarken ayırt etmemeli  Gülü karanfili zambağı En düşman hallere  Gülümse...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iyimser-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Just In Time', 'just-in-time-mustafa-sureyya-sezgin-99y7e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni gördüm

Ve işte o zaman

''Just in time! ..''

Dedim, kendi kendime.

Toplam kalite gerekliydi

Seninle en azlarda uyuşmaya.

Böylece, 

Sürekli gelişmeye başladım.

Geliştim ve geliştim...

Ama sen olduğun yerde

Aynı masada kaldın.

Şimdi artık, 

Seni küçümsüyorum

Dilini bile anlamıyorum

Dünyalarımız ayrı seninle

Çünkü ben Mozart dinliyorum...

(İstanbul,13.09.1995)', 'Seni gördüm Ve işte o zaman ''Just in time! ..'' Dedim, kendi kendime. Toplam kalite gerekliydi Seninle en azlarda uyuşmaya. Böylece,  Sürekli...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/just-in-time-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Yoksun?', 'neden-yoksun-mustafa-sureyya-sezgin-bc92z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yoksun bu gece neden? 

Başım yine bir hoş

Çılgın kalabalığın ortasında

Sensiz sıralar bomboş.

Özlemlerim ve umutlarım

Neden hepsi senden yana? 

Şiir oluyor duygularım

Alıştım mı yoksa sana? 

Bir tiyatrodur yaşam inan! ..

Kah durulur, kah çağlarız

Kaptırdı mı kendini insan

Ya güler ya ağlarız.

(İstanbul,16.10.1995)', 'Yoksun bu gece neden?  Başım yine bir hoş Çılgın kalabalığın ortasında Sensiz sıralar bomboş. Özlemlerim ve umutlarım Neden hepsi senden yan...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neden-yoksun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Dediğin', 'siir-dedigin-mustafa-sureyya-sezgin-oda2o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiir dediğin, 

Duyguların ötesinde olmalı.

Vurgulamalı tek sözcükle; 

Seni, beni

Ve bu koskoca evreni! ..

Şiir dediğin, 

Düşünürken seni, 

Damarlarımdan boşanmalı

Kan gibi! ..

Sen dediğim bir tanem! ..

Şiir olmalısın

Dudaklarımdan düşmeyen

Ve kalemimin ucunda tükenmeyen! ..', 'Şiir dediğin,  Duyguların ötesinde olmalı. Vurgulamalı tek sözcükle;  Seni, beni Ve bu koskoca evreni! .. Şiir dediğin,  Düşünürken seni,  D...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siir-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel N''olur Yar!', 'gel-n-olur-yar-semih-unal-jatei', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aldırmadan çileye derde öyle gel, 

Nefretinle öfkeni körükle öyle gel, 

Sabrına zamansız değerse bir el, 

O zaman hırsını aşta öyle gel.

Kederime ortak olda öyle gel, 

Allah’a kul olda öyle gel, 

Bana gelmen için engelsem eğer, 

Çiğne beni ezde öyle gel.

Sevgini dünya ya haykırda öyle gel, 

Servetini aşk eyle öyle gel, 

Sen sende riyalarını aşta kendine gel, 

Rüzgara bırak kanatlarını, bana uçta gel.

Dön güneşe yüzünü gecenle gel, 

Bir çiçeğe mutluluğu verde öyle gel, 

Ağlayan gözlere merhem olamasan da, 

Bir nebze şefkat bırak kalplere öyle gel.', 'Aldırmadan çileye derde öyle gel,  Nefretinle öfkeni körükle öyle gel,  Sabrına zamansız değerse bir el,  O zaman hırsını aşta öyle gel. Ked...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-n-olur-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmura Yürüyorum', 'yagmura-yuruyorum-semih-unal-4fxk8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine yağmur yağıyor, 

Bardaktan boşalırcasına düşüyor üstüme, 

Dudaklarımda düğümlenen kelimeler, 

Yağmura koşup yine bana dönüyor, 

Ve ben yağmura yürüyorum.

Çaresiz çırpınışlarım bir fayda vermiyor artık, 

Esrarına kapılıyorum damlaların, 

Gülümsüyorum ölüme ben, 

Aldanıyorum efsunkar bakışlara, 

Kimi zaman boşa söylenen aşk sözleriyle ürperiyorum, 

Ve ben yağmura yürüyorum.

Çisil çisil gözlerime akıp gidiyor, 

Sel oluyor yüreğime yağmur, 

Seninle dolan efkarımı ona anlatıyorum, 

Sende, sende benimle yağ gönüllere diyor, 

Ama ben yapamıyorum, 

Kopamıyorum senden, 

Ve ben yağmura yürüyorum.

Kaçıyorum hatıralardan, 

Birer birer vuruyorlar beni can evimden, 

Gözlerin beni öldürüyor  her bakışında, 

Kan ağlıyor gözlerim kimi zaman, 

Şimdi yağmur olup yağmak vardı, 

Zindan gecelerde gül gibi açmak vardı, 

Vazgeçtim ben, 

Susuyorum, 

Ve ben yağmura yürüyorum.', 'Yine yağmur yağıyor,  Bardaktan boşalırcasına düşüyor üstüme,  Dudaklarımda düğümlenen kelimeler,  Yağmura koşup yine bana dönüyor,  Ve ben ...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yagmura-yuruyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Sancısı', 'ayrilik-sancisi-semih-unal-oivbc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün erken kalkmadım, 

Uyuyamamıştım sabaha kadar, 

Gecenin esrarına maniler buluyor, 

Kendimce kendimi avutuyordum, 

Ağzımı bıçak açmıyor, etrafıma şen gülücüklerimi saçmıyordum, 

Dostlarım sorar oldu “neden suskunsun” diye, 

Bilemezlerdi ki gül gibi soldum birden bire, 

Yok bir şey dercesine cevapladım.

Anlıyan keskin bakışlarını bana yöneltip; 

Hep bir ağızdan “yoksa? ” dediler, 

Evet yüzümdeki ayrılığın izleri anlaşılıyordu, 

“Boş ver unutursun” diyorlardı bana, 

Senin kıymetini bilmediyse yaşayamaz oralar da, 

Ben ise yine sineme çekilip, 

Sokak lambasının altına geçtim bir ara, 

Hafiften yağmur yağıyordu, 

Ben sigara üstüne sigara yakıyor, 

Bir an bile durmayan dudaklarım, 

Hep “ayrılık” şarkılarını söylüyorlardı, 

Oysaki ne güzel hayallerimiz vardı senle, 

Üniversiteyi aynı okulda okuyacaktık, 

Özlemlerimizi kederlerimizi hep paylaşacak, 

Derdimizi dert saymayıp doyasıya sevecektik? 

Ama araya olacağını tahmin ettiğim gibi bir bahane koyacaktın! 

“gönül sohpet ister kahve bahane” derler ya, 

işte seninkisi de o hesap! 

Tamam! ! ! Bitti artık.

Bu tokadın acısını unutmam ben, 

Geriye dönülmez benim kitabımda, 

Yoktur riyakar düşler hayallerimde, 

“sevmeki sevilesin” diye boşuna dememişler gülüm.

Hadi git! 

Uğurlar ola, 

İmkanım olsaydı sevdiğim, 

Sensizliği delik deşik eder, 

İbret olsun diye aşklara, 

Asardım ulu orta meydanlara, 

Bu sevgiye yeniden başlamak mı? 

Hayır.

Acı çekmek zevkli bir şey değil, 

Acıyı ben zaten her em hissediyorum yüreğim de, 

Şu fani dünya da gülecek olsaydım, 

Doğarken ağlamazdım....', 'Bu gün erken kalkmadım,  Uyuyamamıştım sabaha kadar,  Gecenin esrarına maniler buluyor,  Kendimce kendimi avutuyordum,  Ağzımı bıçak açmıyor...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ayrilik-sancisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitsin Artık!', 'bitsin-artik-semih-unal-h451s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine sensiz bir güne başlıyorum.

Her günde böyle geçer ya, 

Ben daha yeni bitti sanıyorum, 

Belki de bana uzak olduğun içindir, 

Her gün yüzün görüyor olsaydım dayanamazdım, 

Çıldırırdım belki bu işkenceden kurtulamazdım, 

Hayata küsmeler senin içindi, 

Mehmet’le döğüşüm de, 

Sınıfta kalışımda öyleydi, 

Gülümsememde, koşar adımlarla sana ulaşma arzumda, 

Her şeyim senin içindi.

Neden terkettin inan hala anlamış değilim, 

Bu senin yaptığın yargısız infaz, 

Gülüyorsun hala öylemi? 

Seni sevmek bu kadar gülünç olmamalıydı, 

Bilmem ben mi yanlış düşünüyorum, 

Yoksa hayat mı palavra atıyor, 

Yoksa gerçeklere kurulan pusu çok mu umutlu, 

Aldanma dünyanın velvelesine bir tanem, 

Herkes ölümlü bu dünyada, 

Gelip geçici, 

Kimse demir atamamış ki sen ölümsüz kalasın, 

Gel etme yakma kendini, 

Çok üzdün beni bu şu yalan dünyada ama ahiretini de yakma arada, 

Pişman olursun ama iş işten geçer gülüm, 

Ne olur beni düşünmesen de, kendini düşün, 

Taş kalbin o kadar da gaddar olamaz, 

Ne “sanane” mi? 

Pekii cananım, 

Allah hidayet versin ne diyeyim, 

Korktuğum başıma geldi, 

Güller sana açardı oysa geceleri, 

Kardelenler sana gayret ederdi, 

Sevgimize imrenirlerdi, 

Goncalar açmadan, bizi seyre dururlardı, 

Gözler bizi aradı mutlu günler de, 

Gök kubbe aşkımıza ağlardı, 

Ne günlerdi ama o zamanlar daha bi severdin beni, 

Ayrı gözle bakardın bana, 

İnsan yerine koymazdın beni, 

Sen meleksin derdin her bana bir gül verişinde, 

Gülümüz solmasın diye dua ederdik Rabbimize, 

Zamana direnişimiz uzun sürmedi, 

İşte bak yenildik kurtulamadık, 

Neyse gülüm, 

Nede olsa ben bi hiçim senin gözünde, 

Neden yalvarayım ki artık sana, 

Herkes kendi bildiği yola, 

Uğur ola, uğur ola...', 'Yine sensiz bir güne başlıyorum. Her günde böyle geçer ya,  Ben daha yeni bitti sanıyorum,  Belki de bana uzak olduğun içindir,  Her gün yüz...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bitsin-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-semih-unal-xt8qw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kara yazılar yazılmış alnıma

Sevdam hırsını aştı bu gece

Sen ki deva olmadın şu zahir yarama

Sükunetin çığlıkları ezdi bu gece

Bu dert sensiz biter mi sandın

Kalbimdeki yara diner mi sandın

Gözlerin gözlerime bakar mı sandın

Matemin sevinci sildi bu gece

Bulutlar geçerdi gözüm önünden

Kara çığlıklar delerdi sessizliği

Sevinçle hüznü bir arada yaşarken

Hasretim hüznümü yitirdi bu gece

Bahtımdır bu kara yazım

Ama olmadım hiçbir zaman zalim

Aşktan geldi aşka gider bu gönül

Sevdam benliğimi yaktı bu gece

Kararım karar dönülmez gayrı bu yoldan

Karşıdan bir dağ uzanırdı ovalardan 

Sessiz bir çığlıktı kopan o civardan

Aydınlık karanlığı örttü bu gece

Artık hüzün yoktu şiirlerimde

Annemdi benim o günlerde desteğimde

Sözüm sözü dökülmeyecekti dudağımdan

Mantığım duygularımı sezdi bu gece

Birde yarim vardı her dem beni sorardı

Kokum duyar hemen bana koşardı

Ve lakin gözlerinde hülyalar vardı

Hasretim çilemi körükledi bu gece

Şeytanım muradına erdiğinde

Melekler semada üzüldüğünde

Peygamberim gelin ümmetim dediğinde

Ufkum bir, bir açıldı bu gece.! ! !', 'Kara yazılar yazılmış alnıma Sevdam hırsını aştı bu gece Sen ki deva olmadın şu zahir yarama Sükunetin çığlıkları ezdi bu gece Bu dert sensi...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bu-gece-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kir', 'kir-semih-unal-ebbf1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düştüm yine yollara, 

Yürüyorum nereye giderim bilmem, 

Anlasam ki bir mekanım var, 

Hemen gider uyurum bir an, 

Sendeki yaram bende kalan tek şey, 

İşte bu yüzden küskünüm sana, 

Ben kirliyim, sen kirlisin, insanlar kirli.

Yutkunamam bile düğümlenir boğazımda, 

Arda kalan sözlerim tükenir, 

Gayretimi sana gizlerim ben sana sözlenirim, 

Duyamazsın her lahza sokağının başında beklediğimi, 

İşte bu yüzden küskünüm hayata, 

Hayat kirli, sözler kirli, dünya kirli.

Taşıyacak halım kalmadı bu yüke, 

Gayret ederim etmesine ama boş bir bilmece, 

Sende gelsen belki anlamlı kelime, 

Ama sende yoksun ben kime dilene, 

İşte bu yüzden küskünüm yarınlara, 

Yarın kirli, dün kirli, bu gün kirli.

Yağmura dur diyemem sevdiğim, 

Akar napam ben ıslanam altında, 

Ya kanım akarsa duymazsa sevdalar, 

Ha birde düzmece imiş o duygular, 

Duygular onlarda ağlatıyorlar, 

Meğerse hepten yalanmış sevdalar, 

İşte bu yüzden küskünüm sevdaya, 

Sevda kirli, umut kirli, aşk kirli...', 'Düştüm yine yollara,  Yürüyorum nereye giderim bilmem,  Anlasam ki bir mekanım var,  Hemen gider uyurum bir an,  Sendeki yaram bende kalan t...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Git Ölüm', 'var-git-olum-semih-unal-4cf0c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Var git ölüm! 

Sana bir can borcum olsun, 

Var git bu beden aşksız olsun.

Sana koşan bir ömür olsun, 

Sensiz bir hayat, sende bir can olsun, 

Var git ölüm, 

Sana bir can borcum olsun.

İstersen kal gitme, 

Benden olsun çaylar, 

Olmasa da olmaz ama bu sevdalar, 

Sende olmasan bu canda kıymet bilmezler, 

Var git ölüm, 

Sana bir can borcum olsun.

Kal desem de kalmazsın ölüm, 

Bu canı Allah''a feda eder gönlüm, 

Namlusu göğsüme saplı kalsa da 

Bu gününe her an şükreder gönlüm, 

Ölüm dahi bozamaz bu gölgesi zulmün, 

Var git ölüm, 

Sana bir can borcum olsun.

Sultanımı aldın benden yetmedi mi? 

Sen bana nice kötülükler ettin, 

Damla damla sel oldu yüreğim aktı sana, 

Yetmez mi benden çaldığın hatıralar, 

Yetmez mi bana sapladığın ızdıraplar, 

Yetmedi mi? 

Var git ölüm, 

Sana bir can borcum olsun.

Öderim merak etme...', 'Var git ölüm!  Sana bir can borcum olsun,  Var git bu beden aşksız olsun. Sana koşan bir ömür olsun,  Sensiz bir hayat, sende bir can olsun,...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/var-git-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum', 'sustum-semih-unal-lk5q3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gün gök kızgın, 

Bulutlar yine hüzünlüydü...

Gecelerin esrarı çıkıyordu su yüzüne, 

Matem sevgileri zambaklarla uçuyordu göklere, 

Çocuklar ellerine alamıyorlardı oyuncaklarını, 

Analar gülemiyordu eskisi gibi, 

Yine yağmur yağıyordu gökten, 

Bu gün gök kızgın, 

Bulutlar yine hüzünlüydü.

Savaş çığlıkları yine kulaklarım da kopuyordu, 

Namlular bana doğru siper alıyordu, 

Babam kardeşlerimle beraber kaçıyordu, 

Goncalar gülemiyordu eskisi gibi, 

Yine ateş yağıyordu gökten, 

Bu gün gök kızgın, 

Bulutlar yine hüzünlüydü.

Namertler yakıyordu her tarafı acımadan, 

Güller küskündü güneşe hiç bakmadı o zaman, 

Funda ağaçlarım ziyan oldu açmadan, 

Gülücükler soldu, güller kurudu, 

Yine bomba yağıyordu gökten, 

Bu gün gök kızgın, 

Bulutlar yine hüzünlüydü.', 'Bu gün gök kızgın,  Bulutlar yine hüzünlüydü... Gecelerin esrarı çıkıyordu su yüzüne,  Matem sevgileri zambaklarla uçuyordu göklere,  Çocukl...', ARRAY['Türk Edebiyatı','Şiir','Semih Ünal']::text[], 8.5, '{"poet":"Semih Ünal","poet_slug":"semih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sustum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağır!', 'bagir-murat-cetin-2w1ul', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya kör, dünya sağır 

Bir çocuk iç çekiyor ağır ağır 

Kuru da olsa bir dilim ekmeğe muhtaç 

Kurtulacaksa insanlığın, utanma bağır! 

Dünya kör, dünya sağır 

Can veriyor bir çocuk ağır ağır 

Yurdunu çiğnetmedi, şehadette 

Rahatlayacaksa kalbin, utanma bağır! 

Dünya kör, dünya sağır 

Kan veriyor bir çocuk ağır ağır 

Çökmüş enkaz altında, yarım 

Dinecekse gözyaşın, utanma bağır! 

Dünya kör, dünya sağır 

Filizleniyor bir çocuk ağır ağır 

Rahmetle mi anacak, bilmem bizi? 

Yazılıyor tarihin, utanma bağır! 

Utanma bağır aynaya bak sonra 

Dünyaydın sen, sen kör, sen sağır 

Utanır belki insanlığın, hadi bağır 

Kayarken gökte bir bir yıldızların 

14/12/2000', 'Dünya kör, dünya sağır  Bir çocuk iç çekiyor ağır ağır  Kuru da olsa bir dilim ekmeğe muhtaç  Kurtulacaksa insanlığın, utanma bağır!  Dünya ...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bagir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '5 kala', '5-kala-murat-cetin-g40et', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir avuç iç sıkıntısı yüreğimde 

umuda umutlanan gözlere ev sahibi 

hedefi bilmeyen bir ok hayat denilen 

bende hayatı fırlatmak için gerilmiş yay 

hay aksi hay 

...

kas çalışıyorum 

surak asmak için 

an''a alışıyorum 

kesip atmak için 

ecele yılışıyorum 

hemen gitmek için 

..... 

... 

çayımı yudumluyorum 

cinnete beş kala

01/05/2002', 'bir avuç iç sıkıntısı yüreğimde  umuda umutlanan gözlere ev sahibi  hedefi bilmeyen bir ok hayat denilen  bende hayatı fırlatmak için gerilm...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/5-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun', 'sen-yoksun-umit-bahadir-f6uwr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben  sana 

Kum gibi, 

Su  gibi, 

Damarda  kan  gibi, 

Akarken

En muhtaç  olduğum  zamanlarda

Sen yoksun   Ayçiçeği 

Ben sana 

Açken,

Susuzken,

Peşmür de iken, 

Boyun  eğmişken,

Şiirler  dizmişken,

Rüyalara  mahkumken, 

Özlemişken  tutkuyla  hasretle

En  muhtaç  olduğum   zamanlarda

Sen  yoksun  ayçiçeği

Ben  sana  ait 

Tenine 

Terine

Kokuna

Ela gözüne

Tatlı Sözüne  

Asi  Özüne

Hafif  çatlamış  dudağına

Dolgun  ak  tenli  gerdanına 

Yandan  ayrılan  saçına

Tutkunken

En muhtaç  olduğum zamanlarda

Sen yoksun Ayçiçeği', 'Ben  sana  Kum gibi,  Su  gibi,  Damarda  kan  gibi,  Akarken En muhtaç  olduğum  zamanlarda Sen yoksun   Ayçiçeği  Ben sana  Açken, Susuzke...', ARRAY['Türk Edebiyatı','Şiir','Ümit Bahadır']::text[], 8.5, '{"poet":"Ümit Bahadır","poet_slug":"umit-bahadir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-yoksun-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazamıyorum', 'yazamiyorum-mustafa-engin-karatay-snkfm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar sevgilim, bizim aşkımız vardı 

Şimdi tükendi birden, güzel günlerin ardı 

Aşk sâde bende kaldı, üstüme hüzün sardı 

Her şeye rağmen yine, sana kızamıyorum... 

Acılarla bezeyip, nasıl da çekip gittin? 

Aşkım sürse de sana, benim gözümde bittin 

Beni sensiz kalmaya, mahrûmiyyete ittin

Şu perişân hâlimi, hâlâ bozamıyorum... 

Her yerde hâtırân var, kolay kolay silinmez 

Anlatmış olduklarım, yaşanmadan bilinmez 

Bir insanın yüreği, bu kadar da dilinmez 

Sana ağır sözüm var, lâkin yazamıyorum...

10.12.2000    Landsberg    09: 40', 'Bir zamanlar sevgilim, bizim aşkımız vardı  Şimdi tükendi birden, güzel günlerin ardı  Aşk sâde bende kaldı, üstüme hüzün sardı  Her şeye ra...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yazamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-asik-sefai-6xpmb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ham isem atese atin

Hak közüne çekilirim

Dariysam harmanda yakin

Hak közüne çekilirim yar

Fitne düsürür dillere

Zulüm gelir bülbüllere

Dünayayi koydum ellere

Hak sözüne çekilirim yar

Sevdaliyim sevdaliyim

Amma bana yar degil

Asikar etmedim lakin sir degil

Senin için ölmek bana ar degil

Yollar uzadikca kervanim sensin

Lokmanim ilacim dermanim

Sensin ey güzel

SEFAI''yem imanima

Haber edin mihmanima

Yeter ettiler canima

Gökyüzüne çekilirim yar', 'Ham isem atese atin Hak közüne çekilirim Dariysam harmanda yakin Hak közüne çekilirim yar Fitne düsürür dillere Zulüm gelir bülbüllere Dünay...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Eyler', 'nice-eyler-asik-sefai-eqok8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Feryat figan arsa çikar

Garip daglarda bu gece

Bülbülün dili tutulur

Viran baglarda bu gece

Kurtla kuzu güden yolcu

Gelen yolcu giden yolcu

Biliyon mu neden yolcu

Ölüm saglarda bu gece

Zincir mi vurulmus kola

Konussaydi biraz ola

Yasanmis mi acep ola

Eski çaglarda bu gece

Nanay dedi nanay dedi

Toy kuruldu nanay dedi

Herkes deli diyor amma

O herkese nanay dedi

SEFAI gitmem yurdumdan

Gitsem ölürüm derdimden

Daha gitmeden ardimdan

Nazlim aglarda bu gece', 'Feryat figan arsa çikar Garip daglarda bu gece Bülbülün dili tutulur Viran baglarda bu gece Kurtla kuzu güden yolcu Gelen yolcu giden yolcu ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nice-eyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarsa Yaramı', 'sarsa-yarami-asik-sefai-948pm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cemali dolunay gözleri bela

Kaslari bir hançer sarsa yarami

Gönül avgahinda sözleri bela

Tetik düsürmeden vursa yarami

Ilaci dermandi sanan gönlümü

derdi yudum yudum kanan gönlümü

Gülü kapristandi yanan gönlümü

Deyinki daglardan sorsa yarami

Ya devleti tanirsin

Ya devletsiz kalirsin

Ya soyunu bilirsin

Yada soysuzlasirsin

Isteyenler yunus desin

Isteyen varsa yavuz

Özümüzde alplik yatar

Gönlümüzde dervişlik

Türk-islam davasini yasarken

Bozkurtcasina azatlanmis daglarda

Ne istiyorsunuz beyler belami! 

SEFAI''yem ehli tarik gezerim

Ayaklari yarik yarik gezerim

Senelerdir gönlü kirik gezerim

Bir tabib gelsede sarsa yarami', 'Cemali dolunay gözleri bela Kaslari bir hançer sarsa yarami Gönül avgahinda sözleri bela Tetik düsürmeden vursa yarami Ilaci dermandi sanan ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sarsa-yarami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kimin?', 'bu-kimin-ahmet-kuruoglu-38reb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz konuşuyorsak

Bu kimin sessizliği? 

Biz birşeyleri paylaşıyorsak

Bu kimin hiçbirşeyi? 

Biz mutluysak

Bu kimin mendili? 

Biz birer yabancıysak

Bu kimin sevgisi? 

Biz eğer tanışıyorsak

Bu kimin gözleri? 

Biz birbirimize benziyorsak

Bu kimin maskesi? 

Söylermisin güzel kız? 

Biz hala daha aynı yolda yürüyorsak

Bu kimin ''sensizliği''?', 'Biz konuşuyorsak Bu kimin sessizliği?  Biz birşeyleri paylaşıyorsak Bu kimin hiçbirşeyi?  Biz mutluysak Bu kimin mendili?  Biz birer yabancı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kuruoğlu']::text[], 8.5, '{"poet":"Ahmet Kuruoğlu","poet_slug":"ahmet-kuruoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-kimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Değiliz', 'yalniz-degiliz-ahmed-arif-t828q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ufka vardık ki artık

Yalnız değiliz sevgilim.

Gerçi gece uzun,

Gece karanlık

Ama bütün korkulardan uzak.

Bir sevdadır böylesine yaşamak,

Tek başına

Ölüme bir soluk kala,

Tek başına

Zindanda yatarken bile,

Asla yalnız kalmamak.

Şafakları ben balığa çıkarım

Akan akmayan sularda

Benim, bütün tezgahlarda paydosa giden

Bir bahar akşamı dünyada.

Ben dört duvar arasında değilim

Pirinçte, pamukta ve tütündeyim,

Karacadağ, Çukurova ve Cibalide.

Zehirli kör yılanları

Ve sıtmasıyla

Gün yirmidört saat insan avında

Karacadağda çeltikler.

Bir kız çocuğunun gözyaşı gibi

-  Ayak bileklerinde bir dizi boncuk,

Sol omzunda nazarlık,

Dağ başında unutulmuş üşümüş,

Minicik bir aşiret kızının  -

Damla-damla, berrak olur pirinci.

Kamyonlarla, katır kervanlarıyla

Beyler sofrasına gider...

Çukurovam,

Kundağımız, kefen bezimiz

Kanı esmer, yüzü ak.

Sıcağında sabır taşları çatlar,

Çatlamaz ırgadın yüreği.

Dilerse buluttan ak,

Köpükten yumuşak verir pamuğu.

Külhan, kavgacıdır delikanlısı,

Ünlü mahpusanelerinde Anadolumun

En çok Çukurovalılar mahpustur,

Dostuna yarasını gösterir gibi,

Bir salkım söğüde su verir gibi,

Öyle içten

Öyle derin,

Türkü söylemek, küfretmek,

Çukurova yiğidine mahsustur...

Tütünü bilir misin? 

"Kız saçı" demiş zeybekler,

Su içmez her damardan,

Yerini kolay beğenmez,

Üşür

Naz eder,

Darılır

İki parmak arasında kıyılmış,

Bir parçası var kalbimin

İncecik, ak kağıtlara sarılır,

Dar vakit yanar da verir kendini.

Dostun susan dudağına...

Sokaklardan,

Kıyılardan,

Gök mavisinden,

Ekmeğinden,

Canevinden ayrı düşmeye

Yani bütün hasretlerin kahrına

Ve zehrine çaresiz kalmaların,

İlk nefesi Hızır gibi yetişir

Cibalide sarılan cıgaranın...

Tütün isçileri yoksul,

Tütün işçileri yorgun,

Ama yiğit

Pırıl - pırıl namuslu.

Namı gitmiş deryaların ardına

Vatanımın bir umudu...', 'Bir ufka vardık ki artık Yalnız değiliz sevgilim. Gerçi gece uzun, Gece karanlık Ama bütün korkulardan uzak. Bir sevdadır böylesine yaşamak,...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Arif']::text[], 8.5, '{"poet":"Ahmed Arif","poet_slug":"ahmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/yalniz-degiliz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum İşte', 'unuttum-i-ste-ahmet-selcuk-i-lkan-96xzo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O senli yıllara bir çizgi çekip

Gönül defterini kapattım işte

Hasretle yanmaya değmezsin deyip

Gözümde yaşları kuruttum işte

Şimdi bu pişmanlık bimem ki niçin

Kaybeden sen oldun yan için için

Unutmaz demişsin sen benim için

Aldandın sevgilim unuttum işte

Sevgisiz yanar mı sevda ocağı

Belliydi bu aşkın yok olacağı

Söndürdüm içimde o yanardağı

Yaralı gönlümü avuttum işte...', 'O senli yıllara bir çizgi çekip Gönül defterini kapattım işte Hasretle yanmaya değmezsin deyip Gözümde yaşları kuruttum işte Şimdi bu pişman...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unuttum-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Seninle Ya Sensiz', 'ya-seninle-ya-sensiz-ahmet-selcuk-i-lkan-lpw4b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya hep ya hiç sevgilim

Ya seninle ya sensiz

Olamaz başka biri

Ya seninle ya sensiz! 

İstersen al at beni

İstersen yarat beni

Dağ gibi deniz gibi

Ya seninle ya sensiz! 

Olmasa da sevenim

Ağlayanım gülenim

İlk sözüm son yeminim

Ya seninle ya sensiz! 

İstersen sevme beni

İstersen bekle beni

Taş gibi toprak gibi

Ya seninle ya sensiz! 

Yalnız bir mevsim değil

Yalnız bir bahar değil

Her zaman her yerde bil

Ya seninle ya sensiz! 

İstersen öldür beni

İstersen güldür beni

Gün gibi güneş gibi

Ya seninle ya sensiz! ...', 'Ya hep ya hiç sevgilim Ya seninle ya sensiz Olamaz başka biri Ya seninle ya sensiz!  İstersen al at beni İstersen yarat beni Dağ gibi deniz ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ya-seninle-ya-sensiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Yıldızım', 'sabah-yildizim-ahmet-selcuk-i-lkan-2dhm4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey benim doğmayan sabah yıldızım

Geceler mi uzak sen mi uzaksın? 

Ne zaman bitecek bu yalnızlığım

Umutlar mı uzak sen mi uzaksın? 

Bil artık sabrımın sabrı da bitti

Seninle gelen aşk sensiz terketti

Çalmadın kapımı çalmadın gitti

Ellerin mi uzak sen m uzaksın? 

Sen misin ''ben miyim'' kimmiş yalancı

Nasıl yaşarız biz bize yabancı

Böyle bir ayrılık ne kadar acı

Yolların mı uzak sen mi uzaksın? 

Dilime marş ettim eyvahlarımı

Söyle de bileyim günahlarımı

Işıksız bıraktın sabahlarımı

Gözlerin mi uzak sen mi uzaksın?', 'Ey benim doğmayan sabah yıldızım Geceler mi uzak sen mi uzaksın?  Ne zaman bitecek bu yalnızlığım Umutlar mı uzak sen mi uzaksın?  Bil artık...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sabah-yildizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle Evlenir misin?', 'benimle-evlenir-misin-ensar-aktas-qxedu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boyun boyuma huyun huyuma uygun 

Soyun soyuma suyun suyuma uygun 

Gözlerim bakar sana, kalbim hep baygın 

Vurgunum sana, benimle evlenir misin? 

Ömürlerimizi birleştirelim gitsin 

Bu ilişki mutluluklarla bitsin 

Sevenler bizim gibi sevsin sevilsin 

Aşığım sana, benimle evlenir misin? 

Evlenirsek hiç ayrı kalmayız 

İnan birbirimizi hiç kırmayız 

Yaşımız geçse de biz genç kalırız 

Vurgunum sana, benimle evlenir misin? 

Adem ile Havva''dan kalmış miras 

Sevmişiz mutlu olalım biraz 

Kış gelmeden, bitmeden bu yaz 

Aşığım sana, benimle evlenir misin? 

Rotterdam,31.07.1989', 'Boyun boyuma huyun huyuma uygun  Soyun soyuma suyun suyuma uygun  Gözlerim bakar sana, kalbim hep baygın  Vurgunum sana, benimle evlenir mis...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benimle-evlenir-misin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Natalie', 'natalie-mustafa-sureyya-sezgin-zd6ub', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben birini seversem

Şiir yazarım ona Natalie

Umut yüklü, özlem dolu.

Ben birine küsersem, 

Hüzün ve kederlerle ağlar şiirlerim.

Bu yaşam biter ve ben göçersem Natalie

Ne sevgi kalır geride, ne dostluk

Ne de dargınlık.

Yalnızca hasretle susamış, 

Bir yığın sevdalarım

Göz yaşı döker ardımdan.

Ve bir gün ben unutulursam Natalie 

Belki şiirlerle anılır adım.

(İstanbul,18.05.2002)', 'Ben birini seversem Şiir yazarım ona Natalie Umut yüklü, özlem dolu. Ben birine küsersem,  Hüzün ve kederlerle ağlar şiirlerim. Bu yaşam bit...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/natalie-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Don Kişot Gibi', 'don-kisot-gibi-osman-kuyumcu-cxrv9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DON KİŞOT GİBİ 

Çöl nasıl gözlerse yolunu bir top taze bulutun

Aklın öyle Mecnun, asılı duruyor gurbetin çengelinde, 

Aklın, göğün yedi bir katında mevsimlik bir giysi 

Döşemişsin çöl sarısı gözlerini tozlu yollara, 

Dudakların Kerem, 

Öpülmekten değil özlemekten 

Özlemişsin, akkorlarda yanıp kavrulmakta sevdan

Sevdan çöl susuzu Mecnun

Sevdan kimin umurunda

Kem rüzgarlar, koparıp düşürse bir telini saçının 

Bir savaş sebebi bilirsin bunu yiğit şövalyem

Kılıç-kalkan kuşanıp binersin sıska atına

Karşında bin bir başlı ejderhalar

Kuvvetin gülünç, acınası, 

Çaresiz değilsin ama...

Dövüşmek kutsal, yaşamaktan, yaşatmaktan 

Sevda ışımaktaysa ucunda kan tünelinin...

Bunu en iyi sen bilirsin

Kimin umurunda.

Yüzün Nuh tufanı

Yarin asi gözlerinde belirse bir damla yaş

Deprem gibi bir şey olur 

bir kenar ülkesinde üçüncü dünyanın...

Sessizce devrilir içindeki çınarlar

Kimin umurunda

Savaş kaçınılmaz, yenilgi mutlak...

Sıkı tut yüreğini Don Kişot’um, sıkı

Umutların bittiği yerde o bitmez, tükenmez hayallerin

Bilirsin ki “en hızlı at senin Rocinante’n 

En güzel kadın Dulcinea’ndır.”

Yel değirmenlerine inat...

Susmaların mavzerdir sevdalım

Patlar yüreğimin ta orta yerinde

Ürker karlı dağlarda börtü böcek 

Çatal boynuz geyikler kalbinden vurulur.

Susma, ne olursun! 

Sen susarsan türküler ölür

Pınarlar küser.	

Çığlıkların arş-ı ala

İstediğin kadar bağır

Çıkmaz sesine eş

İnatçı, çetinsin.

Ne fayda.

Bütün kulaklar sağır. 

Yarin seni sevmez mi oldu artık

Yüzünde yüzün, gözünde gözün mü yok

Bir dağ çiçeğine bulaşmış yüreğin 

üşümekte mi Ağustos ortasında

Dünyanın sonu belki senin için

Tükenmiş çarelerin, uykuların haram, 

Düşlerin delik deşik 

Elinde elin, dilinde dilin yok.

Yeri göğü çökertse çığlığın

Yarim yarim çağırsan

Küskün bir sevdadır yankılanan 

güvendiğin dağlarda.

Yerden göğe hakkın var koparmakta kıyametleri

Vakitsiz savaşlar ilan edersin yel değirmenlerine

Sevda hak götürmez, bütün hesaplar boşuna.

“Yiğitlik sevdaya bir adımlık yol” değil artık, 

Giden gider kar düşmüş incecik yollarına

Sevdayı kanla yumazlar, sevdayı sevdayla yumalı

Durma öyle, 

At kendini yeni bir sevdanın uçkun kollarına', 'DON KİŞOT GİBİ  Çöl nasıl gözlerse yolunu bir top taze bulutun Aklın öyle Mecnun, asılı duruyor gurbetin çengelinde,  Aklın, göğün yedi bir ...', ARRAY['Türk Edebiyatı','Şiir','Osman Kuyumcu']::text[], 8.5, '{"poet":"Osman Kuyumcu","poet_slug":"osman-kuyumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/don-kisot-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oluşum', 'olusum-mustafa-sureyya-sezgin-ndltl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ses yoktu, 

Renk yoktu başlangıçta.

Benim gibi yalnızlığı bilen

Yalnızca bir Tanrı vardı, 

Ve bir tek söz vardı önceleri.

Kelimeler güçlüdür.

Sevdalar da öyle.

Sonra; “Ol” dedi.

Evrenin ulu mimarı.

Bir tek sözcük yetiverdi.

Resim oluştu, heykel oluştu.

Ateş oluştu, gül oluştu, 

Bülbül oluştu, sevda oluştu.

Sözcükler ard arda dizilip, 

Şiir oluştu.

Hareketlendi her biri

Müzik oluştu.

“Adem” denilen 

Yokluk aynasına baktı sonraTanrı

Sen yansıdın, ben yansıdım.

Biz bir tek varlıktık oysa

Bu bakışla binlere bölündük.

Ayrı gayrı bilmezken

Sen olduk,  ben olduk. 

Sevmek istedik, sarılmak istedik; 

Sorguladık yaşamı

Aşkı öğrendik, nefreti öğrendik

Hasreti öğrendik, acıyı öğrendik.

Her birini

Bir diğerinin uzantısı bildik.

Yalnız  su mu boğar, ateş mi yakar? 

Gönlüne bir kor gibi düşen aşk ile

Hıçkırık boğar, sevda  yakar.

 (İstanbul,18.05.2002)', 'Ses yoktu,  Renk yoktu başlangıçta. Benim gibi yalnızlığı bilen Yalnızca bir Tanrı vardı,  Ve bir tek söz vardı önceleri. Kelimeler güçlüdür...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/olusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairlerin Silahı Şiirleridir', 'sairlerin-silahi-siirleridir-ensar-aktas-7mvyd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şairler derdini şiirlerle anlatır

Bazı dostlar duyar, bazısı duymaz

Aşıkların kalbinde bir alev vardır

Kimi seven anlar, kimisi anlamaz

Mısralarda saklıdır herbir duygular

Okurken anlaşılır bütün satırlar

Şairlerin tek silahı şiirleridir

Aşığın halinden yalnız aşığı anlar

Rotterdam,10.08.1989', 'Şairler derdini şiirlerle anlatır Bazı dostlar duyar, bazısı duymaz Aşıkların kalbinde bir alev vardır Kimi seven anlar, kimisi anlamaz Mısr...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sairlerin-silahi-siirleridir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustuğumda Duy Beni', 'sustugumda-duy-beni-osman-kuyumcu-kdavh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SUSTUĞUMDA DUY BENİ



Adını rüyalara sakladım.

Kirpiklerimin ucunda gülen resmin

Kulaklarımda güzeli söyleyen dilin

Seni seviyorum.

Bu imkansız.

İmkansızı seviyorum

Bu sen.

Yüreğim çarmıhlarda

Kelimeler ağzımda un ufak

Seni sustuğumda duy beni

Elim desem elsiz.

Dilim desem, dilsizim.

Bir dağın yalnızlığında

yitirmişken gençliğimi

Seni buldum.

Gitme 

Sen gidersen

Kaçkar’ın çiçekleri yetim

Yavru serçeler öksüz kalır

Uzanamadığım

Mundar diyemediğim.

Bir şehir harabesi gibi

Gömdüm içime her anını

Yirmili yaş ilahelerinin

Seni seviyorum

Bu delilik.

Deliliği seviyorum.

Bu karasevda.

Gençliğimi al

Zoraki bayramlarda yitirdiğim

Teber görmemiş düşlerim pare pare

Yabanıl sunalarla yüreğim.

Bir yılmaz şövalyesi eski sevdaların.

Sevdam kanar gül renginde

Seni seviyorum.

Gitme.

Sen gidersen

Bilir misin? 

Ne olur? 

Gitme.

Çapraz ateş arasında silahsızım

Siperim de yok.

Gitme.

Sen gidersen

Kıyametim olur.', 'SUSTUĞUMDA DUY BENİ Adını rüyalara sakladım. Kirpiklerimin ucunda gülen resmin Kulaklarımda güzeli söyleyen dilin Seni seviyorum. Bu imkansı...', ARRAY['Türk Edebiyatı','Şiir','Osman Kuyumcu']::text[], 8.5, '{"poet":"Osman Kuyumcu","poet_slug":"osman-kuyumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/sustugumda-duy-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sevdiğini Biliyorum', 'beni-sevdigini-biliyorum-ensar-aktas-fh8g2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni sevdiğini biliyorum

Üzmek istemediğini biliyorum

Çok özlediğini de biliyorum

Sende biliyorsun ki

Bunun için yaşıyorum

Sevgine layık olmak için varım

Sensizliğime tesellim sensin

Yoksa hasretine nasıl dayanabilirdim

Yokluğuna nasıl katlanabilirdi yüreğim

Rotterdam,16.08.1991', 'Beni sevdiğini biliyorum Üzmek istemediğini biliyorum Çok özlediğini de biliyorum Sende biliyorsun ki Bunun için yaşıyorum Sevgine layık olm...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beni-sevdigini-biliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '24 Saat Seni Düşündüm', '24-saat-seni-dusundum-ensar-aktas-tl259', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün yine

Kalktığımda seni düşündüm

Yerken, içerken

Gezerken, çalışırken

Hep seni düşündüm

Hep hayallerini gördüm

Zaten dün yatmadan önce de

Hep seni düşünmüştüm

Gece ıssızken, soğukken

Karanlıkken, sensizken

Hep seni düşünmüştüm

Rüyamda da seni görmüştüm

Rotterdam,21.08.1991', 'Bugün yine Kalktığımda seni düşündüm Yerken, içerken Gezerken, çalışırken Hep seni düşündüm Hep hayallerini gördüm Zaten dün yatmadan önce d...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/24-saat-seni-dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizim Sensiz', 'caresizim-sensiz-ensar-aktas-bhwhe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yuvasız bir kuşun

Sessizliği kadar

Sessizim sensiz

Çaresizim

Ellerini tutmak

Varken ellerimle

Yüzüme koymak

Zor geliyor bana

Güneşten kavrulup

Solan bir gül gibi

Yalnızım sensiz

Çaresizim

Gözlerine bakmak

Varken gözlerimle

Hayallerine dalmak

Zor geliyor bana

Bir yarısı erimiş

Kardan adam gibi

Hastayım sensiz

Çaresizim

Koşmak, sevişmek

Varken seninle kırlarda

Haberini beklemek

Zor geliyor bana

Fırtınaya kapılmış

Bir gemi gibi

Batmaktayım sensiz

Çaresizim

Hep senle olmak

Aşkınla dolmak varken

Hasretine dayanmak

Çok koyuyor bana

Çaresizim sensiz

Çok çaresiz

Rotterdam,10.10.1991', 'Yuvasız bir kuşun Sessizliği kadar Sessizim sensiz Çaresizim Ellerini tutmak Varken ellerimle Yüzüme koymak Zor geliyor bana Güneşten kavrul...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/caresizim-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek', 'gitmek-burak-ben-q7163', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çok zor şeydir, 

sabahın amalığında, 

yanında iki saatlik uykunla, 

elin kolun başkasının gibi, 

yatağın sıcağı sinmiş pjamalarını çıkartmış, 

keskin bir grilikte terketmek.

ki yoldasındır artık, 

ciğerlerinde uyku öncesinin dumanı, 

yol sarhoş, sen sarhoş

dönüp durur öteden beriye

çok zor şeydir...

kargalar açlığını hissetmeden

uyurgezer ağaçlar eşliğinde

bir şehirden

film koptuğunda kendini bulacağın

hiç hayal etmediğin o şehire

çok zor şeydir terketmek.

ki terketmişsindir artık

artık seni uyuşuk sabahlar, 

sarhoş akşamlar beklemektedir.

bilirsin ve yavaş yavaş yitirirsin.', 'çok zor şeydir,  sabahın amalığında,  yanında iki saatlik uykunla,  elin kolun başkasının gibi,  yatağın sıcağı sinmiş pjamalarını çıkartmış...', ARRAY['Türk Edebiyatı','Şiir','Burak Ben']::text[], 8.5, '{"poet":"Burak Ben","poet_slug":"burak-ben","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gitmek-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun', 'olsun-huseyin-cayikli-jn899', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'içinde bana dair ne kaldı

gözyaşların hala akıyor mu? 

yoksa gülüyormusun...

yoksa birisi mi var? 

öldün mü kaldın mı? 

kötü haber olsa tez gelir? 

ama sen nerelerdesin

ne arıyor ne soruyorsun

telefonların yok artık.

arayıp kısa tutmuyorsun.

yosun ve deniz al senin olsun

benden bu kadar

uzulme

bitirdin ama askı silemezdin

ama aşk olsun

yasadıgımız aşk yanımıza kar olsun...

bu şiir benden sana ufak bir anlayıs olsun...', 'içinde bana dair ne kaldı gözyaşların hala akıyor mu?  yoksa gülüyormusun... yoksa birisi mi var?  öldün mü kaldın mı?  kötü haber olsa tez ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiste Terk Edilmis Bir', 'sevmiste-terk-edilmis-bir-cem-gumus-tgvny', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gunler geciyor saniyeler kadar hizli 

 Onumuz acik ilerliyoruz IHTIYARLIGA dogru 

 Nerede diyoruz o eski gunler

 Leyla lar asli, lar harcadilar bizi

 Yuzyillardir suruyor bu! 

 Ortasi bos kalmis sevdamizin

 Rotasi yanlis bir gemi gibi 

 Gozumuz kor bizim gormez

 Ugultular duyar sadece kulagimiz

 Unutuluyoruz birer birer', 'Gunler geciyor saniyeler kadar hizli   Onumuz acik ilerliyoruz IHTIYARLIGA dogru   Nerede diyoruz o eski gunler  Leyla lar asli, lar harcadi...', ARRAY['Türk Edebiyatı','Şiir','Cem Gümüş']::text[], 8.5, '{"poet":"Cem Gümüş","poet_slug":"cem-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevmiste-terk-edilmis-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Nakarat', 'ayni-nakarat-cem-gumus-y0woi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kavusacagimiz o ilk gun 

 Sana soz veriyorum

 Senin serefine kaldiracagim

 Ve seni icecegim ilk kadehte 

 Rakiyi degil seni icerken 

                          sarhos olacam

 Cicegi degil seni koklayacagim

 Ve hasretle derinden 

                    kucaklarken seni 

 Gozlerin yasaracak aglayacaksin! 

 Ellerin tuttugunda  ellerimi 

                         sarinca simsiki 

 Bir volkan gibi patlayacak 

   yuregimin sesi 

 Saracak dort bir yani cigligi 

                                     yuregimin 

 Tekrarlanan nakarati 

 BITIR BU GURBETI GEL ARTIK! !', 'Kavusacagimiz o ilk gun   Sana soz veriyorum  Senin serefine kaldiracagim  Ve seni icecegim ilk kadehte   Rakiyi degil seni icerken         ...', ARRAY['Türk Edebiyatı','Şiir','Cem Gümüş']::text[], 8.5, '{"poet":"Cem Gümüş","poet_slug":"cem-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayni-nakarat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayana', 'anlayana-mustafa-sureyya-sezgin-3szch', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep kavgayla iş bitmez

Döner döner durursun

Tek başına yürümez

Sonra pişman olursun.

Önce sorunu belirle, 

Sonra çözümü üret.

Katılımcı fikrinle

Toplumunu ilerlet.

Yeni çözümler ara

Bu kalite az sana

Güzelliği yakala

Sivrisinek saz sana.

(İstanbul,06.11.1995)', 'Hep kavgayla iş bitmez Döner döner durursun Tek başına yürümez Sonra pişman olursun. Önce sorunu belirle,  Sonra çözümü üret. Katılımcı fikr...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anlayana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapıt', 'yapit-mustafa-sureyya-sezgin-x4h9o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşam bir süreçtir

Tıpkı ham meyvanın

Zamanla olgunlaşması gibi

Sen de olgunlaşacak

Ve sonunda

Bütünleşeceksin evrenle.

Sevmelisin tüm varlıkları.

Soluk alırken an be an

Paylaşmayı

Ve birlikte yaşamayı

Öğrenmelisin.

Su birikintilerinde değil, 

Okyanusların derinliklerinde

Yüzmeyi düşünmelisin.

Sen aydınlıksan, 

Sırtını dönmeden

Işık saçmalısın karanlıklara.

Yermeyi değil, 

Önce sevmeyi öğrenmelisin.

İşte o zaman sen

Olgunlaşmış bir esersin! ..

(İstanbul,12.12.1995)', 'Yaşam bir süreçtir Tıpkı ham meyvanın Zamanla olgunlaşması gibi Sen de olgunlaşacak Ve sonunda Bütünleşeceksin evrenle. Sevmelisin tüm varlı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yapit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Çocuk', 'aglama-cocuk-mustafa-sureyya-sezgin-qhdi8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlama artık çocuk, 

Ağlama yaşın değil! ..

Rüzgar yaman eserse

Onun önünde eğil.

Gülermiş insan işte, 

Bazen ağlarmış da, 

Gülmeni de gördüm ben

Senin ağlamanı da.

Billurlaşmış yanağından, 

Süzülen iki damla yaş

Hayatın gerçeği bu

Ne olur artık anla! ..

Ağlatma artık çocuk

Ağlama yaşım değil! ..

(İstanbul,29.01.1996)', 'Ağlama artık çocuk,  Ağlama yaşın değil! .. Rüzgar yaman eserse Onun önünde eğil. Gülermiş insan işte,  Bazen ağlarmış da,  Gülmeni de gördü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aglama-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cik', 'cik-mustafa-sureyya-sezgin-ip2d0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günaydın Yağmur dedim.

Somurtmadı, '' cik '' dedi.

Elimi uzattım sevdim

Kanatlarını gerdi.

İnce hesabı yoktur

Sevilince şımarmaz, 

Hünerleri pek çoktur

Başladı mı hiç susmaz.

İnsan değil bir kuştu

Sevgiden anlıyordu.

Karşılık beklemeden

Mutluluk saçıyordu.

Yaşamı yudumlarken

Düşünüverdim bir an, 

Bir ders çıkarıyor muyuz

Şu ufacık varlıktan? 

(İstanbul,15.02.1996)', 'Günaydın Yağmur dedim. Somurtmadı, '' cik '' dedi. Elimi uzattım sevdim Kanatlarını gerdi. İnce hesabı yoktur Sevilince şımarmaz,  Hünerleri p...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sitem Rubaisi', 'son-sitem-rubaisi-husrev-hatemi-bqx9h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm''ü muştulamana gerek yoktu

Yakınlığını biliyordum onun, 

Yüreğimi neden muştalayıp durdun? 

Çoktan beri yastaydı ve yorgun......', 'Ölüm''ü muştulamana gerek yoktu Yakınlığını biliyordum onun,  Yüreğimi neden muştalayıp durdun?  Çoktan beri yastaydı ve yorgun.........', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-sitem-rubaisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında Sahte', 'aslinda-sahte-hakan-sengorun-09nav', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bir ışığım korkakça bakan karanlığa ait

zamanın ötesindeki yaşamların anlık mutluluklarını

saklayan renklerdeki sıcaklığım; 

Bulunması güç bir düş gibi, daha vahşi  bir sessizliğin ortasında elleri kanayan bir yolculuğum sana doğru...

Senin var olduğun anlarda içimdeki uçurumun kenarında oturup baktım yüzüne düştü düşecek melodiler, renkler

Bebekleri uyutan seslerdi uyandıranda öyle öldürende, 

Sihirli ölümlerin cennetteki hikayelerini anlatırım senin sahteliğindeki acıya 

Kırılmış ışıklara ağladım ben yanlızca kaç türlü ölüm var senin düşlerinde durmadan tekrarlanan kelimelerin çığlıklarını duydum ben bir sessizliktim

Sana aittim senin kadardım nerden bakarsan bak sana uzaktım 

Korkaklığındı içimi acıtan yaşama dair ama yaşamda cesur değildi hiç bir zaman en az senin kaçtığın kadar kaçtı oda senden 

yinede bir sessizliğin ışığıydım ben.', 'Ben bir ışığım korkakça bakan karanlığa ait zamanın ötesindeki yaşamların anlık mutluluklarını saklayan renklerdeki sıcaklığım;  Bulunması g...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aslinda-sahte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mimarın Şiiri', 'mimarin-siiri-doga-bulut-rglzl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'perdelerin rengi degismeye basladi

sanirim aksam oluyor

masamin isigi beyaz beyaz baterken gozlerime

egilmekten isigin uzerine

belim inim inim inliyor

ardindan aydinlanmaya baslayor perdeler

gozlerimden yaslar akiyor

titreyen kollarim

artik uzanmak istiyor...', 'perdelerin rengi degismeye basladi sanirim aksam oluyor masamin isigi beyaz beyaz baterken gozlerime egilmekten isigin uzerine belim inim in...', ARRAY['Türk Edebiyatı','Şiir','Doğa Bulut']::text[], 8.5, '{"poet":"Doğa Bulut","poet_slug":"doga-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mimarin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğuş', 'dogus-can-yucel-cmlg0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anamın amına kar yağdı

Sonra öyle bir güneş doğdu ki güneş', 'Anamın amına kar yağdı Sonra öyle bir güneş doğdu ki güneş...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/dogus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum Dışarı Kaçtı', 'dostum-disari-kacti-can-yucel-ai7oe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocuğum ben

İlk kez buldum, gördüm gölgemi

Ben nereye o oraya

Alkışlıyorum alkışlıyor

Gülüyorum gülüyor, 

Bir benden büyük oluyor bir küçük, 

Nereden geldi, bir daha gider mi ki? 

Gitti bile kapıyı açıverince ninem, 

Neden ağladığımı anlamıyor koskoca kadın!', 'Çocuğum ben İlk kez buldum, gördüm gölgemi Ben nereye o oraya Alkışlıyorum alkışlıyor Gülüyorum gülüyor,  Bir benden büyük oluyor bir küçük,...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dostum-disari-kacti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek mi?', 'sevmek-mi-onur-karanak-riouo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni sevmek mi? 

Vızıltılı bir şarkının çalması.

Gözlerimden akan bir damla yaş...

Seni sevmek mi? 

Bahar bekleyişi

Lalelerin üzerindeki güneş lekeleri...

Seni sevmek mi? 

Kırık bir iskele sesi

Avucumdan düşen bir mana...

Seni sevmek mi? 

Gecelerin arkadaşlığı

Sabahların kıyısındaki dünya...

Hep bu mudur dediğim? 

Seni sevmek mi? 

Son bir gecenin üzerinden düşen rüya...', 'Seni sevmek mi?  Vızıltılı bir şarkının çalması. Gözlerimden akan bir damla yaş... Seni sevmek mi?  Bahar bekleyişi Lalelerin üzerindeki gün...', ARRAY['Türk Edebiyatı','Şiir','Onur Karanak']::text[], 8.5, '{"poet":"Onur Karanak","poet_slug":"onur-karanak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevmek-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burası Asker Ocağı', 'burasi-asker-ocagi-riza-aslan-kxri0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'karlı bir dağın 

fırtınası dinmeyen

tipisi bitmeyen

ha dondum ha donacağım 

dediğin

güneşe yakın

ama bir okadar uzak

doruğu gibi burası

burası

benliğinin senden kaçtığı

düşüncelerinin anlamını yitirdiği

geçmişinin 

gözleri yaşlı geride kaldığı

bir yer burası

burası

kalabalık içinde

yalnız olduğunu bildiğin

zorunluluktan doğan beraberliklere

paylaşım dediğin

bir yer burası

burası

anlamsızlara anlam verdiğin

artık yeter dediğin bir anda

bağıramayıp yutkunduğun

artık bitti dediğin bir anda

bitmediğini bilmediğin

bir yer burası

burası 

yılara inat oluşturduğun

birikimlerinin

beş kuruş değer etmediği

sevdiğinin

sevdiklerinin gözünde tüttüğü

dokunup koklamak varken

bir çiçeği

onu ezdiğin

yok ettiğin

bir yer burası

burası 

asker ocağı

ne ana kucağı

ne baba oçağı

asker ocağı

burası...

16 - 05 - 2002 

saat: 12.20

25. Kısım', 'karlı bir dağın  fırtınası dinmeyen tipisi bitmeyen ha dondum ha donacağım  dediğin güneşe yakın ama bir okadar uzak doruğu gibi burası bura...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/burasi-asker-ocagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biter Ama Nasıl', 'biter-ama-nasil-riza-aslan-t5p3a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'biter...

ama nasıl

ama biter

üzülerek, sıkılarak

tükenerek 

biter...

zaman geçer

giden gün ömürdendir

giden gitmiştir

üzülerek, sıkılarak

tükenerek biten

ömürdendir

geçtiğine sevinilen

her gün

giden ömürdendir.

08 - 05 - 2002 

Çarşamba', 'biter... ama nasıl ama biter üzülerek, sıkılarak tükenerek  biter... zaman geçer giden gün ömürdendir giden gitmiştir üzülerek, sıkılarak tü...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biter-ama-nasil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede Kalmıştık', 'nerede-kalmistik-riza-aslan-nb8zc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'nerede 

kalmıştık

bizi bizden eden

o yaman ayrılıktan sonra

07 - 04 - 2002 

saat: 19.17', 'nerede  kalmıştık bizi bizden eden o yaman ayrılıktan sonra 07 - 04 - 2002  saat: 19.17...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nerede-kalmistik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçer mi?', 'gecer-mi-riza-aslan-p0uzl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'geçer mi bilinmez? 

yaşanmadan anlaşılmaz

hani dışardan kışlanın 

kapısından bakmaya benzemez

asker olmak

07 - 04 - 2002 

Saat.19.17', 'geçer mi bilinmez?  yaşanmadan anlaşılmaz hani dışardan kışlanın  kapısından bakmaya benzemez asker olmak 07 - 04 - 2002  Saat.19.17...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gecer-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağır İşçi', 'agir-i-sci-riza-aslan-0k7m5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'saniyeler 

ağır bir işçinin

yorgunluğu gibidir

yavaştır geçmez

günler

asır gibidir

sabahın ilk ışıklarında 

başlayan gün

gecenin sonlarına doğru

ihtiyar bir insan gibi

belini büker', 'saniyeler  ağır bir işçinin yorgunluğu gibidir yavaştır geçmez günler asır gibidir sabahın ilk ışıklarında  başlayan gün gecenin sonlarına d...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/agir-isci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamı Yok Şu An', 'anlami-yok-su-an-riza-aslan-r8xoj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'neden demenin

anlamı yok şu an

yaşarsın ya hani bazen

hani kader dersin ya 

yapamadıklarına

iş de bu da 

öyle bir şey', 'neden demenin anlamı yok şu an yaşarsın ya hani bazen hani kader dersin ya  yapamadıklarına iş de bu da  öyle bir şey...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anlami-yok-su-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devam Eden Hayat', 'devam-eden-hayat-riza-aslan-dc3fo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'devam eden hayatın

o farkedilmez

- aslında farkedilen sınırında -

yaşamın o anlaşılamaz 

karmaşasında

dışarıda devam eden bir

hayat olduğunu bana

şu nereye gittiğini 

bilmediğim

- aslında nereye gittiğinin

hiçbir önemi olmayan- 

şu arabalar hatırlatıyor.

07 - 04 - 2002', 'devam eden hayatın o farkedilmez - aslında farkedilen sınırında - yaşamın o anlaşılamaz  karmaşasında dışarıda devam eden bir hayat olduğunu...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/devam-eden-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değerini Bilemezsin', 'degerini-bilemezsin-riza-aslan-23gt0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'değerini bilemezsin

kaybetmeden hiç bir şeyi

ayrı kalmadan

ayrılığın ne olduğunu

bilemezsin

yitirmeden anlayamazsın

geride kalanların 

özlemini', 'değerini bilemezsin kaybetmeden hiç bir şeyi ayrı kalmadan ayrılığın ne olduğunu bilemezsin yitirmeden anlayamazsın geride kalanların  özlem...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/degerini-bilemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Uğraşılar', 'tum-ugrasilar-riza-aslan-cudwa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tüm uğraşılar

ayakta dimdik

ve sorunsuz kalmak için

tüm uğraşılar 

bir günü daha 

bitirebilmek için

bir gün

bir gün daha derken

yedinci güne geldilk

yedi gün 

yedi uzun gün

09 - 04 - 2002', 'tüm uğraşılar ayakta dimdik ve sorunsuz kalmak için tüm uğraşılar  bir günü daha  bitirebilmek için bir gün bir gün daha derken yedinci güne...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tum-ugrasilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim', 'sen-benim-riza-aslan-y5zx1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen benim farklı bir yanımsın

yokluğunda değerimi bilemediğim

sen benim göremediğimi

sandığım zamanlardaki

o ışıl ışıl parlayan gözlerimsin

sen benim varlığımsın

yitirdiğimde insanlara

küstüğüm

sen benim yaşama nedenimsin

şimdi olmasanda yanımda

beni düşündüğünü bildiğimsin

sen benim

şu zamansız geçen

tren vagonlarındaki

sadace bana el sallayan

sevdiğimsi

17 - 04 - 2002 

Saat: 18.53', 'sen benim farklı bir yanımsın yokluğunda değerimi bilemediğim sen benim göremediğimi sandığım zamanlardaki o ışıl ışıl parlayan gözlerimsin ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-benim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüdüm Ben', 'yurudum-ben-engin-namli-ygain', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatın eğri yollarını düzleyerek 

Üstünden çile kervanını yürüttüm ben 

Yorgun bedenimle zorlukları yenerek 

Mecalsiz gönlümde dertle nöbet tuttum ben 

Titreyen caddelerin dar kaldırımında 

Kar ile tipi kavga ederdi bağrımda

Mor güller açardı elimde ayağımda

Sendeleyerek ak zamana yürüdüm ben 

Omuz üstümde baş, ayak üstümde beden 

Ömrümce eşlik ettiler kar kış demeden 

Sabırla, azimle çıktılar her çileden 

Cefadan alındım sefaya konuldum ben

Uyku benim ferahlık tahtımdı her gece 

Huzur cümlesini anardım hece hece 

Uyanınca dünyaya rahatım bilmece 

Çöze çöze öğrendim keyfe büründüm ben', 'Hayatın eğri yollarını düzleyerek  Üstünden çile kervanını yürüttüm ben  Yorgun bedenimle zorlukları yenerek  Mecalsiz gönlümde dertle nöbet...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yurudum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Qarqa ve Qartal', 'qarqa-ve-qartal-ahmet-hani-maiws', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağac üste iki qarqa

Yuva saldı.

Birin öldürdüler ancaq

Biri qaldı.

Qaldı yalqız 

Qara qarqa

Oldu sonsuz.

Belelikle yaşayış

Çatdı sona

Qarqalara.

-

Dağ başında

İki qartal 

Yuva saldı

Biri uçdu

Biri qaldı

Ve Uçan

süretile

Qüdretile

Yürüş etdi sürüye

Aldı payın

Qalxdı göye.

Dağ başında

Neçe qartal 

Yuva saldı.

15 july  1996', 'Ağac üste iki qarqa Yuva saldı. Birin öldürdüler ancaq Biri qaldı. Qaldı yalqız  Qara qarqa Oldu sonsuz. Belelikle yaşayış Çatdı sona Qarqal...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/qarqa-ve-qartal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senizm', 'senizm-erdal-sen-0p6ca', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sabahları sensiz uyanıyorsam 

geceleri uyumak büyür gözümde

ve mutluysam seni aramaktan

seni bulmak da böyle bir şeydir işte...', 'sabahları sensiz uyanıyorsam  geceleri uyumak büyür gözümde ve mutluysam seni aramaktan seni bulmak da böyle bir şeydir işte......', ARRAY['Türk Edebiyatı','Şiir','Erdal Şen']::text[], 8.5, '{"poet":"Erdal Şen","poet_slug":"erdal-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/senizm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Mahzuni', 'koca-mahzuni-sabit-i-nce-u9yfh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Halkın ozanıydı, halktan biriydi, 

Göçtü bu dünyadan Koca Mahzuni.

Başkaldıranların yiğit eriydi, 

Geçti bu dünyadan koca Mahzuni.

Elinde sazıyla durmadı gezdi, 

Korkmadan haykırdı gerceği yazdı.

Belli ki dünyadan usandı, bezdi, 

Uçtu bu dünyadan Koca Mahzuni.

Kalem eğilmedi, sazı susmadı, 

Yıllarca söyledi sesin kesmedi, 

Tehditlerle, hapislerle pusmadı, 

Taştı bu dünyadan Koca Mahzuni.

Evrensel düşündü, hakkı savundu, 

Umutla yaşadı, o hep avundu.

Dizlerine vurdu, çokca dövündü, 

Koştu bu dünyadan Koca Mahzuni.

“Bazen Şerif oldu, bazı Mahzuni, ”

kullanmadı ne mezhebi, ne dini

huzurlu geçmedi onun bir günü, 

kaçtı bu dünyadan Koca Mahzuni.

İnce bir insandı sevgi doluydu, 

Aşkın badesiydi, dostluk yoluydu, 

Çağımızda sanki Hazret’ Aliydi, 

Çoştu bu dünyadan Koca Mahzuni.

Kayseri 18.05.2002  Aşık İnce(Sabit İnce)', 'Halkın ozanıydı, halktan biriydi,  Göçtü bu dünyadan Koca Mahzuni. Başkaldıranların yiğit eriydi,  Geçti bu dünyadan koca Mahzuni. Elinde sa...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/koca-mahzuni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki de Aşk...', 'belki-de-ask-adnan-durmaz-vr65g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki de aşk vardır

Benim hiç bilmediğim

Gece vardiyalarında

Karanlığa ışık gibi yayılan

Yorgun bir gülüştür

Çok uzak çöl yolculuklarından

Hırsızlayın bir hilâl

Ki masallara saklanmış

Tanımlanamayan-

Ve en azından kendimi

Uçurumlarında deneyeceğim

Çocukçadır

Ki dünyanın tüm çocukları

Hiç mi hiç düşünmeden

Katılıverirler oyuna

Bu yüzden

Karanlık dalların altında

Bir haziran akşamı

Pür gizem olarak oturan kadın

Ansızın özler çocukluğunu

Hayvancadır

Yâr kokusu eser rüzgâr

Ve bir bakış

Bir cenneti talanlar

Belki de aşk vardır

Şiirle miirle falan avutamadığım

Bir ömrü savurduğum yoluna

Koşup koşup tutamadığım...

Adnan DURMAZ', 'Belki de aşk vardır Benim hiç bilmediğim Gece vardiyalarında Karanlığa ışık gibi yayılan Yorgun bir gülüştür Çok uzak çöl yolculuklarından H...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/belki-de-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimde Sen', 'gozlerimde-sen-aziz-nesin-uycu9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu siiri sevdigim kiza yazmisim', 'bu siiri sevdigim kiza yazmisim...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesin']::text[], 8.5, '{"poet":"Aziz Nesin","poet_slug":"aziz-nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/gozlerimde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cam Kırıkları', 'cam-kiriklari-ahmet-cappola-c83ml', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göğsümde binlerce cam kırıkları

Ne kadar uğraşsam da nefessiz kalıyorum

Yokluğun dudağımda kan tadı, 

Başka bir tat alamıyorum.

Soldu renkleri gök kuşağının, 

Dört mevsim griye döndü gökyüzü 

Şimdi, aynalarda bir ihtiyar sureti

Ve kadim ziyaretçisiyim mezarlığın, 

Sokakta korkulup kaçılan deli, 

 Ve umutsuz aşığıyım aydınlığın', 'Göğsümde binlerce cam kırıkları Ne kadar uğraşsam da nefessiz kalıyorum Yokluğun dudağımda kan tadı,  Başka bir tat alamıyorum. Soldu renkle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Cappola']::text[], 8.5, '{"poet":"Ahmet Cappola","poet_slug":"ahmet-cappola","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cam-kiriklari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatsam Derdimi Anlar mısınız', 'anlatsam-derdimi-anlar-misiniz-ali-ayyildiz-3tx6b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu ne kargaşa, bu ne curcuna 

Beni dertlere boğdu bu keder 

Bütün millet kendi halinde 

Kederim kalbimi yakar da gider 

Bir köşeye çekilmişim gözlerimde nem 

Anlatsam derdimi anlar mısınız? 

Sensiz, günlerimde bir sonsuz elem 

Kahrolsam halime ağlar mısınız? 

Birbiri ardına dizildi keder 

Gönlüm bir aşkın peşinden gider 

Ne olur anlayın beni, bu sefer 

Kaybolan benliğim güler de gider 

Sonunda isyanım sel oldu taştı 

Kalbimi bir kor misali yaktı 

Sevdam sonunda bendimi aştı 

Hayalin bendimi yıkar da gider', 'Bu ne kargaşa, bu ne curcuna  Beni dertlere boğdu bu keder  Bütün millet kendi halinde  Kederim kalbimi yakar da gider  Bir köşeye çekilmişi...', ARRAY['Türk Edebiyatı','Şiir','Ali Ayyıldız']::text[], 8.5, '{"poet":"Ali Ayyıldız","poet_slug":"ali-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlatsam-derdimi-anlar-misiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Küflenmiş', 'yuregim-kuflenmis-ali-ayyildiz-nhejq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğim küflenmiş bu sonbahar

Beynimde örümcekler ağ yapmış

Param parça olmuş bu kalbim

Bunca yıl, tek sana aldanmış

Karanlıkta mahsur kalmışım

Gözlerimde sadece hayalin kalmış

Derin hülyalara dalmışım

Hayalim bile sana aldanmış', 'Yüreğim küflenmiş bu sonbahar Beynimde örümcekler ağ yapmış Param parça olmuş bu kalbim Bunca yıl, tek sana aldanmış Karanlıkta mahsur kalmı...', ARRAY['Türk Edebiyatı','Şiir','Ali Ayyıldız']::text[], 8.5, '{"poet":"Ali Ayyıldız","poet_slug":"ali-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yuregim-kuflenmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerimin Perisi', 'hayallerimin-perisi-osman-fatih-33sxy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen hayallerimin perisi                                                                 Güzel gözlerini dik yine gözlerime                                               O tatlı gülümsemeni takın                                                              Ve ellerimi ısıt tüm sıcaklığınla.                                                     Sensizliğimin acısını yanaklarından,                                            Hasretimi teninin kokusundan çıkarayım.                                    Parmaklarımı kenetleyip parmaklarına,                                       Omuzuma yatışını seyredeyim yine.                                             Saçlarının kokusu salınsın burnuma                                             Ve her solukta seni çekeyim ciğerlerime.', 'Sen hayallerimin perisi                                                                 Güzel gözlerini dik yine gözlerime                  ...', ARRAY['Türk Edebiyatı','Şiir','Osman Fatih']::text[], 8.5, '{"poet":"Osman Fatih","poet_slug":"osman-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/hayallerimin-perisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Akıl Çağı', 'siirin-akil-cagi-musur-kaya-canpolat-86ji8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Noksansız olmalı ''''Hayat Bilgisi'''' ozanın

Uzak tutmalı şiirden yanılgıları

Sohbetlerde kalmalı yalan yanlış

Özlü doğruları kaydetmiyorsa

Kalemi kırılmalı yazanın

Ozan tüm bilgileri özümsemeli

Yaratıcı işleve engeldir ezbercilik

Yüzbinlerce deneyimi insanlığın

Yansılmalı onun sevgi gücünde

Geleceği ''''kahin'''' gibi görebilmeli

Haber vermeli doğanın gizlerinden

Nasıl kurtulur toplumun ve insanın yarını

Bir ses mi geliyor doğa üstünden

Bir belirtimi var bilimin görmediği

Dizeler hızlanmalı bilinmezin izinden

Çağdaş karmaşası duygulanmanın

Şiirin hasında çözümlenmeli

Ne kadarı aklın ve yüreğin payı 

Ne kadarı gerçek ne kadarı düş

Ustası olmalı ozan bu denklemi kurmanın 

Aydını özkültürü hazırlar biçimde, özde

Ozanı olmak daha da zor başka kültürün

Sanatta yersel nirengi yüceltir evrenseli

Şiirse öz suyudur yaşamın derinliğe yürümüş

Sızmazsa dizelerden bir damla yaş olur gözde', 'Noksansız olmalı ''''Hayat Bilgisi'''' ozanın Uzak tutmalı şiirden yanılgıları Sohbetlerde kalmalı yalan yanlış Özlü doğruları kaydetmiyorsa Kal...', ARRAY['Türk Edebiyatı','Şiir','Müşür Kaya Canpolat']::text[], 8.5, '{"poet":"Müşür Kaya Canpolat","poet_slug":"musur-kaya-canpolat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/siirin-akil-cagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm', 'omrum-oguz-atalay-q0acp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güneşin kavurucu sıcağı altındayım

hava yanıyor, uzaklarda bir yerde

bense avlunun önünde

hayallerim önümde

tıngır mıngır geçerken bir fayton

evin önünden

topun peşinden koşarken çocuklar

terkedilmişliğinde yanlızlığın ben

sevgisizliğinde dünyanın

savaşın ortasında açmış bir gül gibi

öylesine masum öylesine çaresiz

                        ve...! 

öylesine bir mavzerin ucunda ömrüm

şarapnel parçası saplanmış gönlüm

                                          Alim

                  1 Mayıs 2002', 'güneşin kavurucu sıcağı altındayım hava yanıyor, uzaklarda bir yerde bense avlunun önünde hayallerim önümde tıngır mıngır geçerken bir fayto...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Atalay']::text[], 8.5, '{"poet":"Oğuz Atalay","poet_slug":"oguz-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/omrum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Annem', 'canim-annem-oguz-atalay-e6ong', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorum bunlar hep aynı sözler

Ama sana olan duygularımı anlatmaya anlatmaya zor yeter

Seni canımdan bile çok, 

Seviyorum CANIM ANNEM

Önce karnında taşıdın

Yetmedi sırtına aldın

Bir derdine bin dert kattın

Seviyorum seni ANNEM

Yokluğunu düşünemem

Sensiz bir gün geçiremem

Sen olmazsan ben gülemem

Bir tanemsin CANIM ANNEM

Bizleri sensiz bırakma 

Canını boş yere yakma 

Zarar gelse tek saçına

Dayanamam CANIM ANNEM.

    Canım annem seni çok ama çok seviyorum 

             OĞLUN:     Oğuz ATALAY(alim_)

                   12/05/2002(Anneler Günü)

                         12 Mayıs 2002', 'Biliyorum bunlar hep aynı sözler Ama sana olan duygularımı anlatmaya anlatmaya zor yeter Seni canımdan bile çok,  Seviyorum CANIM ANNEM Önce...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Atalay']::text[], 8.5, '{"poet":"Oğuz Atalay","poet_slug":"oguz-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canim-annem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazmadım mı?', 'yazmadim-mi-sabit-i-nce-wjttc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğumdan bugüne dağı, bayırı, 

Senin için gezmedim mi sevdiğim.

Bu sevdanın kime olmuş hayırı, 

Bile bile azmadım mı sevdiğim.

Aşkın sarhoşudur divanelerde, 

Yastığım taş oldu viranelerde, 

Senin için içtim meyhanelerde, 

Çoşup, taşıp sızmadım mı sevdiğim.

Her şeyimle sana sevdalandımsa, 

Aşkın ile çok hayale daldımsa, 

Bir kalemle bir kağıdı buldumsa, 

Hep adını yazmadım mı sevdiğim.

İnce haykır duysun bu feryadını, 

Özenerek yarattın o kadını, 

Nerde bulduyusam aşkın tadını, 

Mısra mısra dizmedim mi sevdiğim.

25,03.2002 Kayseri Sabit İnce', 'Doğumdan bugüne dağı, bayırı,  Senin için gezmedim mi sevdiğim. Bu sevdanın kime olmuş hayırı,  Bile bile azmadım mı sevdiğim. Aşkın sarhoşu...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yazmadim-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verdim', 'verdim-sabit-i-nce-3sfhj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Mustafa Yaralı’ya-

Kalleşi kafana takma diyorsun, 

Mertleri namerde çatanla derdim.

Edep ve erkandan bahsediyorsun, 

Varımı, yoğumu bir sele verdim.

“Hayvanlar üzülür, onlar üzülmez”

Namert bilinir de, mertler sezilmez.

Unutma ki ak’a kara yazılmaz, 

Kemiksiz dilleri bir dile verdim.

Gül olsam da bülbül konmaz dalıma, 

Kargalar tuzaklar dizsin yoluma, 

Hakkın kalemini aldım elime, 

Canımı, serimi bu yola verdim.

Ayıplar içinde insanlık olmaz, 

Haksızlık yapanın yanına kalmaz.

Yalanla, dolanla yiğitler yılmaz, 

Bütün varlığımı bir pula verdim.

Hakkımı haksıza yutturmam asla, 

Bu zevki onlara tattırmam asla.

Helale haramı kattırmam asla, 

Benliğim bu yola bir köle verdim.

“Bire yüzü, yüzü bine” bindirse, 

gökten yıldızları tek tek indirse, 

ben dönmezem tüm alemi sindirse, 

sadece kısacık bir mola verdim.

Bir Yaralı yeter bize yanmaya, 

Mecalim yok iki yüze kanmaya, 

Utansam da İnce adın anmaya, 

Kalemi Sabitdir bir kula verdim. 

1.3.2002 Kayseri Sabit İnce', '-Mustafa Yaralı’ya- Kalleşi kafana takma diyorsun,  Mertleri namerde çatanla derdim. Edep ve erkandan bahsediyorsun,  Varımı, yoğumu bir sel...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/verdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Urfa''ya Düştü', 'urfa-ya-dustu-sabit-i-nce-w1hgp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömür bitip devrildi, 

geçti gençliğim geçti.

felek çarkım çevirdi, 

yolum Urfa''ya düştü.

Şu ömrümün sonunda, 

gezdim Urfa yolunda.

kelepçe yok kolumda, 

hapsim UrfaU''ya düştü.

Şu ince''nin halları, 

uzar Urfa yolları.

İbrahim sofraları, 

Rızkım Urfa''ya düştü.

Urfa Sabit İnce', 'Ömür bitip devrildi,  geçti gençliğim geçti. felek çarkım çevirdi,  yolum Urfa''ya düştü. Şu ömrümün sonunda,  gezdim Urfa yolunda. kelepçe y...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/urfa-ya-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükendim', 'tukendim-sabit-i-nce-0s7d0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dillerim Allah''dan dilleri durur, 

Karşimda somurtur öyle oturur.

O yar oklarını kalbime vurur, 

Yeter dayanamam, tükendim, bittim.

Bu da bizim çilemizmiş nidelim, 

Her daim Allah''a niyaz edelim.

Vakit çok uzak mı? Biz de gidelim, 

Yeter dayanamam, tükendim, bittim.

İNCE birgün çile dolacak elbet, 

Ah deyip saçını yolacak elbet, 

Bu feryatlarımı duyacak elbet, 

Yeter dayanamam, tükendim, bittim.

4.11.1994', 'Dillerim Allah''dan dilleri durur,  Karşimda somurtur öyle oturur. O yar oklarını kalbime vurur,  Yeter dayanamam, tükendim, bittim. Bu da bi...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tukendim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terminalde', 'terminalde-sabit-i-nce-m8v2q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimi yolcusunu bekler, 

Terminalde, terminalde. 

Kimisi derde dert ekler, 

Terminalde, terminalde. 

Aşklar biter, aşklar başlar, 

Sel olur da akar yaşlar.

Hasret biter, hasret başlar, 

Terminalde, terminalde.

Otobüsler sıra, sıra

Kalplerde açılır yara, 

Asker yollar atar nara, 

Terminalde, terminalde.

Gidene eller sallanır, 

Sevgi tatlanır, ballanır.

Nice yürekler dağlanır, 

Terminalde, terminalde.

Yolculuklar burda başlar, 

Otobüsler kalkar, işler.

Hayallere konur taşlar, 

Terminalde, terminalde.

Yakın yola giden gelir, 

İnce hasret nedir bilir.

Kimi acılarla kalır, 

Terminalde, terminalde. 

23.9.2001 Kayseri Sabit İnce', 'Kimi yolcusunu bekler,  Terminalde, terminalde.  Kimisi derde dert ekler,  Terminalde, terminalde.  Aşklar biter, aşklar başlar,  Sel olur d...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/terminalde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dosta Mektuplar 15', 'bir-dosta-mektuplar-15-ozcan-nevres-pse8h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Dosta Mektuplar 15

Bahar geliyor dostum bahar

Bu gün bahçemi gezdim 

Yeni bir hevesle

Aylar olmuştu gezmeyeli

Diktiğim fidanlar var ya

Gözler kabarmış

Yakındır  belenmeleri yeşile

Her yıl  hazan mevsiminde

Sararmış yapraklar savrulurken 

Ölümü çağrıştırır sanki

Nasıl da üzülür insan

Baharda biter hüzünler

Yeni bir doğuşun sevinci başlar

Bu gün baharla birlikte

Yeni doğmuş gibiyim

Elimle diktiğim fidanlar

Bu yıl ürün verecekler

Koca kış ihmal etmiştim onları

Yabani otlar sarmış kökleri

Hele tavı gelsin yerin

Vuracağım çapayı derin derin

Yelda’yı Ayten’i düşleyeceğim

Çapayı kafalarına vurur gibi

İkisini de otlarla gömeceğim

İhanetlerinin bedelini ödetir gibi

Dün gece yine onları gördüm düşümde

İkisi de gel diyorlardı

Kim bilir benden yine ne istiyorlardı

Unutamıyorum be dost o iki haini

Aldatılmak mı etmişti beni  onların esiri

Yoksa bir türlü alışamadığım 

İçime sindiremediğim yalnızlık mı

Yazsana bana dostum yazsana

Kadınsız nasıl yaşadın bunca yılı

Anlattıkların belki umarım olur

Kadınsız yaşamayı öğretir bana

Hoşça kal sevgili dost hoşça kal

Tez zamanda aydınlat bu dostunu

		Özcan NEVRES

		23 Mart 2002', 'Bir Dosta Mektuplar 15 Bahar geliyor dostum bahar Bu gün bahçemi gezdim  Yeni bir hevesle Aylar olmuştu gezmeyeli Diktiğim fidanlar var ya G...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bir-dosta-mektuplar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznün Bekler mi Beni', 'huznun-bekler-mi-beni-i-smail-ozabaci-z894l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hüznün bekler mi beni

avuçlarımda mavi bir kan varken

ve granit kokarken her yağmur sonrası 

toprak

ki seni toprak rengi bir hayalle düşünürken

hüznün bekler mi beni

bir şehirde...

sonra

bir cemre gibi düştün içime

büyüdü gözlerimde aşkın

hep yokuş yukarıydı hayatım

düştüğümde, 

duraksadığımda, 

molalarımda

hüznün bekler mi beni

şimdi gitmek zamanı sevgili

şimdi kalmak zamanı

gözlerinden süzülen kahverengi aydınlıkta

şimdi susmak zamanı..

söyleyemediğimde, 

anlatamadıgımda, 

sustuğumda..

hüznün bekler mi beni

bilmiyorum kaç gecedir

bir bilinmez rüyadayım

ki her sabah seninle uyanmaktayım

adını andığımda, 

seni sayıkladığımda, 

yandığımda, 

hüznün bekler mi beni

bak yine hüzün var gözlerimde

bak ellerim soğuk bir mayıs gecesi

bak yüreğim yarım sensiz

hüzün varken gözlerimde, 

ellerim soğukken

sensiz yarımken

hüznün bekler mi beni bir şehirde

avuçlarımda bir kristal

beyaz bir gül gözyaşın..

gözyaşın, kristal

yavaşça düştügünde ellerimden

tutmak güç

susmak zor

uykudasın belki

belki yalnızsın

gözyaşın merak belki

belki özlem gözyaşın..

seni özlediğimde

merak içindeyken başka bir şehirde

hüznün bekler mi beni

benim seni beklediğim gibi..

şimdi çocukluğumu bırakıp bir karadeniz kentinde

yanına geliyorum

eksik bir benle

eksik bir damla gözyaşıyla sana uzanıyorum

çaresiz ellerimi

geri çevirme

ve sor

hüznün bekler mi beni

bir şehirde..

bir şiir yazılır

bir öykü okunur 

bir film izlenir 

sanırdım

oysa sensiz bir şiir

oysa sensiz bir öykü

oysa sensiz bir film

anlamsız gelirmiş bana

ve sorgulanırmış dev yalnızlığım

yokluğunda..

şimdi bir yıldıza soruyorum seni

söyle

hüznün bekler mi beni

başka bir şehrin gecesinden

yeni bir güne uyanmanın ümidiyle

seni düşünüyorum...

ve

seni seviyorum bekleyen hüznünle...

(bir pazar akşamı)', 'hüznün bekler mi beni avuçlarımda mavi bir kan varken ve granit kokarken her yağmur sonrası  toprak ki seni toprak rengi bir hayalle düşünür...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/huznun-bekler-mi-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurum', 'yagmurum-ugur-oguz-sahin-kzn6b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen hep yağdın durmadan yağardın çılgın gibi

Hep ıslattın beni ıslattın kirpiklerimi

Birikintilerinde kağıttan kayıklar yapardım

Yüzdürürdüm hayallerimi

Hep sadık kaldım sevgine

Hayallerimde bile yalanı sevmedim ki

Islak ıslak yürürken sokaklarda

Hep üşüttüm yüreğimi düşlerimi

Yine de vaz geçemedim senden tiryakin oldum

Düşürmedim dilimden sevgini

Yağardın iliklerime kadar ıslatırdın beni

Konuşmazdın susup beklerdin öfkemin geçmesini

Yine de ben seni severdim be

O çılgınlığını yağmanı gürlemeni

Ben farklı bakardım

Onlar farklı seyreder düşünürdü seni

Onlar bazen sıradan severdi seni

Bense sende melankoli

Onlar bir şey anlamazlardı

Oysa ben

Damarlarımda hissederdim seni

Özlemin dikerdi ayağa beni

Beklerdim çisil çisil gelişini

Yağmadığın zamanlar da oldu elbet

Seyrettim siyah bulutlarla geçişini

Yine de bir hüzün olurdu bende

Tenimde hissetmediğimde seni

Öylece bulutlara takılırdı gözlerim

Seyrederdim yağmadan gidişini

Öyle tiryakilik yaptın ki bende

Beklerdim topraktaki kokunu nefesini

Hadi yağ bir tanem yağ pencereme vur

Belki de uykuda olurum haber ver gelişini', 'Sen hep yağdın durmadan yağardın çılgın gibi Hep ıslattın beni ıslattın kirpiklerimi Birikintilerinde kağıttan kayıklar yapardım Yüzdürürdüm...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yagmurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsay Bir Rüyaydı', 'varsay-bir-ruyaydi-ugur-oguz-sahin-36k55', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir aşk yaşandı seninle

Farkında değildik bu hicranın

Ne baharın ne de hazanın

Mutluluk hep avuç içlerimizde saklı kaldı

Hep anlamsızca peşinden koştuk zamanın

Hangimiz değerini bildik var olmanın

Bir gayesi olmalıydı yaşamanın

Ne aşına tuz koyabildik

Ne de tadı kaldı damağın

Bir toz bulutu gibi savrulduk

Hep önünden geçtik bu çarkın

Söz dinletemedim kalbine sevgine

Şimdi kavursun seni göz yaşların ve ahım

Kapıları açtığında tek tek odaların

O zaman yüzüne çarpacak

Soğukluğu duvarların

Sıkacaksın yumruklarını

Uyuşacak parmakların

Yüreğinde yankılanacak haykırışların

Hadi git yüzünü göster aynalara eğer varsa

Utancın alıkoyacak seni

Bitecek karşı koymaların

Anlatacaklarından korkacaksın aynaların

Sakın sakın

Bir aşk yaşadık deme seninle

Varsay bir rüyaydı bir düştü de

Demek ki yaşamadık

Yaşıyamadık gönül gönüle

Yaşayabilseydik eğer

O kadar kolaymı silinirdi her şey

Tek kalemde o şehla gözlerde

Evet bir aşk yaşadık seninle

Yalanlarla birlikte

Sen yalandın sevinçler yalan

Zamanlar yalan yaşandı

Yaşadığımız mevsimler hep yalandı

Şimdi geceler matemde

Yıldızlar mağdur ay saklandı

Yalanlarla dolu da olsa

Çekip gidişin vardı ya

Yaşattın hatıraları kaç kez

Kalbe vuran sancılar gibi

Hatırladıkça bizi

Ruhumda derinleşir o yaranın sesi

Ve daha bir başka sarılırım yalnızlığa

Unutmak isterim çekilen çileleri

O sessiz gidişini', 'Bir aşk yaşandı seninle Farkında değildik bu hicranın Ne baharın ne de hazanın Mutluluk hep avuç içlerimizde saklı kaldı Hep anlamsızca peşi...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/varsay-bir-ruyaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bana Bağlayan', 'seni-bana-baglayan-serhan-karaduman-dxlx6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bana bağlayan

Gözlerindi, her kaçırdığında heveslendiren

Çocukça gülümseyişin di

Senmiydin yoksa periler miydi ürperten

Yıllar sonra kapımdan giren

Geri döndü işte dedirten

Sendin o güler yüzlü 

Ve parıltısı kapının eşiğinden süzülen

Ağlama bebeğim

Sen ki benim nedenim

Bana her gelişinde aynı yüzle

Aynı buğulu ses; 

Karşılarmı bilmem

Ama sensin şu kısa ömrü

Bana cennet eden

Ağlama bebeğim

Seninle sen olmalıyım daha

Sana yaklaşmalıyım

Neden sorusunu bırakmamalıyım

Sarılmalıyım doymayana dek

Ve benim kalmalısın

Sadece sessiz değil

Her neden olursa ki gidişin 

Tek kaçış olmaz kainattaki

Ben de olurum sırada…', 'Seni bana bağlayan Gözlerindi, her kaçırdığında heveslendiren Çocukça gülümseyişin di Senmiydin yoksa periler miydi ürperten Yıllar sonra ka...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-bana-baglayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanış', 'uyanis-mustafa-sureyya-sezgin-dkikp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve işte, 

Uzaksın benden! ..

Kendi gücünle

Gökyüzünün derinliklerine

Kanat çırpıyorsun.

Ben yok olsam da yavaş yavaş

Sen büyüyorsun.

Tohumlar meyveye dönüşürken

Varlığının bilinci oluşuyor.

Ve işte, 

Uzaksın benden! ..

Sevgi tarlalarında sere serpe

Gün yavaşça batıyor.

Sana elveda derken, 

Bir insan yeşeriyor! ..

(İstanbul,16.02.1996)', 'Ve işte,  Uzaksın benden! .. Kendi gücünle Gökyüzünün derinliklerine Kanat çırpıyorsun. Ben yok olsam da yavaş yavaş Sen büyüyorsun. Tohumla...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uyanis-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-gokhan-oktem-8xjy9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl anlatılır bilmem ki yalnızlık

Bilene de hodri meydan diyemem, aşar beni

Ben kendi yalnızlığımı dökerim ancak dizelere

İsteyen, üstüne pay çıkartır kendince

Ne dilim döner ne de gücüm erişir

Ki zaten niyetlide değilim daha ileriye gitmeye

Aslında anlatılabilir mi yalnızlık

Ondan bile emin değilim sahi

Yalnızlık; yaşanır insanın kendi tekliğinde

Çöker alaca karanlık bir hiçlik

İfadesiz yüklenir

Ruhun belisizlik merkezine

Yalnızlık 

Yalın bir hiçlik

Mutlak bir teklik

Ve zamanda bitmeyen bir boşluk bırakır 

Bir boşluk ki zamansızlık değerinde

Ve yaşam bir kısırdöngüdür, yaşanır 

Bir hiçlik

Bir teklik 

Ve bir boşluk ekseninde....

Dahası anlatılır gibi değil, 

Yaşayan bilir kendince...	

19,05,2002, İstanbul', 'Nasıl anlatılır bilmem ki yalnızlık Bilene de hodri meydan diyemem, aşar beni Ben kendi yalnızlığımı dökerim ancak dizelere İsteyen, üstüne ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalnizlik-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maltepe Akşamında', 'maltepe-aksaminda-ugur-oguz-sahin-cssur', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul''u seyrediyorum kuş bakışı Maltepe''den

Gönlümde sen gözlerimde sen

Yaktım bir hasret sigarası

Şimdi alaca bir kızıllık

Gök yüzü eteklerinde

Sevgini işliyorum kat kat

Gönül peteklerimde

Bulutların yüzü şu an sana benziyor

Bakınca sanki bana gülüyor

Hasretin yükselirken içimde

Yavaş yavaş karanlık çöküyor

İstanbul o kadar sonsuz ki

Sevginin yüceliğine benziyor

Nereye gitsen nereyi gezsen İstanbul bitmiyor

Bendeki aşkına benziyor

Yaşadıkça daha çok istiyor

İstanbul ruhumda öten bülbül gibi

Tadına doyulmuyor

Akşam olduğunda yandığında

Tek tek odaların ışıkları

Sanki güzel bir kadın boynunda

Altın gerdanlık gibi parlıyor

Bir işim olsa bir yere gitsem

Ayrılsam gözlerinden kısa da olsa

Sanırım uzun ayrılıklar yaşıyorum

Gurbet var aramızda

Şu İlkbahar başlangıcında

Maltepe akşamında

Yine tüttürdüm seni sigaramda

Kaynattım duygularımda

Ve tam karşımda çamlar arasında

Sanatoryum Süreyya Paşa

Ne hastalar şifa buldu

Ne yıldızlar söndü orada

Uzan çamlıklardan in sahile

Bulursun kendini Küçükyalı''da

Yürürken sahil boyu

Uğraşır insan hep hatıralarla

Ne mutluluklar yaşandı kim bilir

Ne umutlar söndü bu yollarda

Bugün günlerden Cumartesi Nisan''ın yedisi

İnsanlar mutsuz umutsuz çaresiz

İliklerinde yaşıyor ekonomik krizi

Aşkım İstanbul''um 

Belki de tam değilsin benliğimde

Hadi yaşayabilirsen yaşa

Aşkı sevgiyi yüreğinde bu krizde

Suç bende değil affet

Seni sever gibi görünenlerde

Çok çileler gördük yaşadık seninle

Hadi buna da kader de

Aşkım İstanbul''um bugünlerde geçer

Yarın devadır her derde', 'İstanbul''u seyrediyorum kuş bakışı Maltepe''den Gönlümde sen gözlerimde sen Yaktım bir hasret sigarası Şimdi alaca bir kızıllık Gök yüzü etek...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/maltepe-aksaminda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var mı Yaşatanınız', 'var-mi-yasataniniz-ugur-oguz-sahin-8aj6u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmurun toprağın tenine değişi var ya

Hiç içinize çektiniz mi o andaki kokuyu

Şöyle bir kapatıp gözlerinizi

Yaşadınız mı sevdiğinize benzer bu coşkuyu

Toprağın susuzluğunu giderişi var ya

Özlemle hasretle yağmuru bir solukta içine çekişi

Kulaklardaki melodiye susamış nağme gibi

Toprağın sanki yağmura derin bir hazla sevgilim deyişi

Toprak yağmura sarılır yağmur toprağa

Yağmur koynundadır artık toprağın

Toprak doruğunda yaşatanın

Siz ne yaşadınız ne yaşattınız

Var mı sizin de yaşatanınız', 'Yağmurun toprağın tenine değişi var ya Hiç içinize çektiniz mi o andaki kokuyu Şöyle bir kapatıp gözlerinizi Yaşadınız mı sevdiğinize benzer...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/var-mi-yasataniniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pembe Sayfalar', 'pembe-sayfalar-ugur-oguz-sahin-hbzki', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nerde bana tek tek açtığın pembe sayfalar

Kapandı bitti mi sandın gönüldeki yaralar

Hâlâ silinmedi hâlâ bir leke ruhumdaki karalar

Zamanla açıldı mesafeler açıldı kapanmaz aralar

Bilmiyorum nasıl ne zaman ne şekilde çıktın karşıma

Aşk fırtınalar koparmıştı gözlerde o kalem kaşlarda

Ziyan oldu ömrün yarısı sana tutuklu yaşlarda

Yeşiller umut olsa ne fark eder artık o yaşlı ağaçlarda

Güz geldi rüzgârlar esti yerlerde kırılan dallar

Tükenen zamanlar eski hazzı yok hani o sevgili yağmurlar

Sarardı tozudu pembe sayfalar sarardı o yeşilim yapraklar

Hep yarım kaldı hayaller hatıralar

Gülmedi güldürmedi vefasız yıllar', 'Nerde bana tek tek açtığın pembe sayfalar Kapandı bitti mi sandın gönüldeki yaralar Hâlâ silinmedi hâlâ bir leke ruhumdaki karalar Zamanla a...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/pembe-sayfalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buralı Değilim Ey Memleket', 'burali-degilim-ey-memleket-erdem-ozbek-54ejf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buralı değilim ey memleket

Tanımazsın gurbet öykülerine aforoz edilen yüzümü, 

Gözlerin hangi sokağına sığar bilmezsin

Ama ben bilirim göçebelere sunduğun yerleri

Her şehirde aynıdır bodrum katları

Yolum nice unutmalardan geçmiştir

Geçmiştir ama geçmişi bağışlamaz gelecek

Bu yüzden anılar getirdim sanada

Emektar voltalarımın peşine takarak

Kurşun kalemim ve ellerimde yanımda

Biliyorum artık hiç kimse bulamıyor beni

Kimse bilmiyor nereye gömülür bir şair

Meyhanelerin boyu kısa

Şehirlerse çok derin

Ve kılıfına uymaz bir yalnızlıktır kalbime krizlediğim

Bu ne kaçmak nede kaybolmak değildir

Kaderiyle mahpusçuluk oynayan 

Gelincikten bozma bir kadın var yalnızca

Dört ayda bir yüzünü görmek için

Baharlara taşınır dururum nicedir

Ama nedense hiç sevişmedim gözbebekleriyle

Ne zaman soyunsam kirpiklerimden

Adı fuhuş olur aşkın

Ve bir kovlanmış adam kalırım geride

Göçebe bir ütopyalı gibi geliyorum ey memleket

Kalıcı değilim

Karasular insede beynine insanın

Öyle uzun uzadıya kimsesiz kalmaz umutlar

Elbet yine çok şey beklerim yelkovanlardan

Akrepleri boylarından uzun işlere karışsalarda her vakit', 'Buralı değilim ey memleket Tanımazsın gurbet öykülerine aforoz edilen yüzümü,  Gözlerin hangi sokağına sığar bilmezsin Ama ben bilirim göçeb...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özbek']::text[], 8.5, '{"poet":"Erdem Özbek","poet_slug":"erdem-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/burali-degilim-ey-memleket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalardaki Sihir', 'aynalardaki-sihir-ugur-oguz-sahin-2jjm2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gittiğin günden beri içimde acın hatıra kalan

Yaşattıkların güzeldi hatırlanan gerisi yalanmış yalan

Zamansız kuşlar gibiydin dallarda soluklanan

Apansız gelişlerin değil istediğimdi hep gönlümde olman

Dön bak maziye hep mutsuzluklar hep unutulanlar

Suçlu arıyorsak eğer sadece insanlar

Suşsuz olan masum yıllar

Çiçeği koparana kadar çekilir cefalar

Dökülür dilden bin bir türlü kelamlar

Hevesler son bulduğunda 

Bahçeler kimin umurunda

Ayrılıkları yaşatır bukalemunlar

Hiç değişmez sevgi denizleri

Niceleri yaşar bu çileleri

Dünya yedi bucuk milyar insan

Dörtte üçünün yaralı kalpleri

Kim duymuş kimin sesini

Kim tamam yaşamış sevgisini

Gerçekleştirmiş düşlerini

Sonunda geçtik aynaların karşısına

Gördük değişmeyen kendi gerçeğimizi

Kim farkında oldu yandığının yanıldığının

Acaba kim sildi aynalardaki sihri', 'Gittiğin günden beri içimde acın hatıra kalan Yaşattıkların güzeldi hatırlanan gerisi yalanmış yalan Zamansız kuşlar gibiydin dallarda soluk...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aynalardaki-sihir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Odalar', 'huzunlu-odalar-ugur-oguz-sahin-mr45n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorgun bir akşamın hüzün sofrasındayım yine

Soğuk bir kış gecesiyle koyun koyuna

Odam yalnız odam kimsesiz kim yok ki kasvetsiz

Hep o sırlarla dolu odalarda gönülleri kelepçeleriz

Hep yandık çıra gibi nice seviler ardından

Sevmedik mi deli gibi karşılıklı karşılıksız çaresiz

Kim çıktı bu yanan gönüllerden anlayan

Acaba kaçımız ağladık kaçımızın ardından

Bir anlayan oldu mu yaşanandan ziyan olan zamandan

Hangi çiçeği çok sevdik hangi kırda koştuk

Hangimizin haberi oldu o yalnız ovalardan

Aslında çoğumuz yalnızız

Farkımız yok o hüzünlü odalardan', 'Yorgun bir akşamın hüzün sofrasındayım yine Soğuk bir kış gecesiyle koyun koyuna Odam yalnız odam kimsesiz kim yok ki kasvetsiz Hep o sırlar...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/huzunlu-odalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEÇHUL  Şarkılar____________________', 'mechul-sarkilar-ugur-oguz-sahin-bp1l8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün bitecek o sevda şarkıları

Tutacak seni eskittiğimiz yolların ahı

Göz bebeklerin büyüyecek korkuların yükselecek

İstesen de yaşayamazsın o arzuları

Yokluklar ıstıraplar kapını çalacak hep

Çok arayacaksın yaşadığın mutlulukları

Kapında sevgiye aç sana muhtaçken bir zamanlar

Ne çabukta unuttun boş bıraktığın avuçlarımı

Duydum ki şimdi de senin başında çaresizlik girdapları

Bazen ters teper hayatın hayallerin hesapları

Kimin güftesi kimindir bestesi belli olmaz

Bir gün sana da dinletirler o meçhul şarkıları', 'Bir gün bitecek o sevda şarkıları Tutacak seni eskittiğimiz yolların ahı Göz bebeklerin büyüyecek korkuların yükselecek İstesen de yaşayamaz...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mechul-sarkilar--siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahzuni''ye', 'mahzuni-ye-atabay-guveloglu-w4p1e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu ne zamansız gidişti, 

Saz kırıldı, kalem düştü.

Gerçek değil sanki düştü, 

Yerin dolmaz ey Mahzuni...

Yakışmadı ölüm sana, 

Herkesi ağlattın baksana.

Yüreklerin ortasında, 

Yerin dolmaz ey Mahzuni...

Halkın gerçek ozanıydın, 

Ezilenlerin ağzıydın.

Söyleyeni, yazanıydır, 

Yerin dolmaz ey Mahzuni...

Selam olsun, saygı olsun, 

Görüşlerin gerçek olsun.

Bir gün çık gel ne olursun

Yerin dolmaz ey Mahzuni...', 'Bu ne zamansız gidişti,  Saz kırıldı, kalem düştü. Gerçek değil sanki düştü,  Yerin dolmaz ey Mahzuni... Yakışmadı ölüm sana,  Herkesi ağlat...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mahzuni-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senim', 'senim-sadullah-bayar-kpw4x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimi kelimeler anlatmaz duygularımızı

Hüzün olur sevgim

Ama şuda varki, umudum

Yarın sensın, sen mutluluksun

Bense senim.', 'Kimi kelimeler anlatmaz duygularımızı Hüzün olur sevgim Ama şuda varki, umudum Yarın sensın, sen mutluluksun Bense senim....', ARRAY['Türk Edebiyatı','Şiir','Sadullah Bayar']::text[], 8.5, '{"poet":"Sadullah Bayar","poet_slug":"sadullah-bayar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/senim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyada Çok Güzel Şeyler Var...', 'dunyada-cok-guzel-seyler-var-ozkan-mert-33i9o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dünyada çok güzel şeyler var...

Çok güzel şeyler var dünyada...

Ben mesela bir sokak tanırım İzmir''de

          yere düşen inci taneleri gibi dökülür denize.

Ekvator''da, Quito kentinde uykulu sokaklar

          çok kızarlarsa dağlara açılırlar birdenbire.

Zaten akşam kırmızı düşer o dağlara.

Amazonların derinliklerinde akan nehirlerde

bembeyaz bir orkide büyür: 

         o kadar güzel ve keskindir ki kokusu

             çılgın bir tay gibi koşuşturur kalbimizin

kıyısında.

Kalbimiz zaten tüm çiçeklerin aynası.

Ay''dan Yeryüzüne bakılınca

Yalnızca ''Çin Seddi'' görülürmüş. Hayır! Yanlış.

Ben baktım: Palandöken dağında açan                                               bir gelinciği gördüm.

Ve havada uçuşarak sevişen

bir çift kelebeği.

Ben ne köprüler tanırım.

Siz de tanırsınız mutlak: İşte Boğaz köprüsü! 

                    Ne zaman boş kalsa yıldızları arar

geceleyin.

Gündüzleri neler neler çeker şu insanlardan

 ve yüzüne çarpıp geçen martılardan...

Biliyorum bir gün çekip gidecek belki, 

Nereye bilinmez? 

Ama Boğaz''dan daha güzel nereye yakışır ki? 

Ben öyle kentler tanırım ki

memesi sütyenden taşmış

          genç bir kız gibi uyanırlar sabahları.

Güneşin ilk ışıklarıyla öpüştüklerinde

           kırmızı bir gül gibi açarlar yeryüzünde.

Ve zaten her kent başka bir kente açılır bir köşesinden.

Ben ne şairler tanırım ateş gibi: İşte Arthur Rimbaud! 

Sarhoş Gemi''yi yazdı denizi görmeden.

              Yaşamın okyanuslarında yıkadı sözcüklerini.

Ne kadar çok güzel kadın var dünyada...

Esmer, sarışın, çukulata renginde

             hepsi birbirinden güzel, birbirinden alımlı.

Gergin yumuşak tenlerinde

        İmparatorluklar kuruldu, imparatorluklar çöktü.

Bir öpücükleriyle ihtilaller başladı...

Zaten kadınlar ve aşk olmasa

            yaşamaya değer miydi bu dünya? 

            Kime okurduk bu şiiri? 

Öpücük dedim de aklıma geldi: 

           Bir sevgilim var dünya güzeli.

Ne zaman baksam gözlerinin içine

           yıldızların üzerine düşüyorum

                              sımsıkı sarılsam da dünyaya.

Beni zaten hep güzellikler sarhoş etti.

Ey Şair! Güzel sözlerle, büyülü sözcüklerle

            kandırırsın kullarımı, diyor koca tanrı: 

Ben yalnız güzel şeyleri mi yarattım? savaşları, 

       açlıkları, ölümleri, ayrılıkları... ben yaratmadım mı? 

Sen yarattın elbet tanrım! Onların hesabını

sen ver kullarına.

Ben''se güzel şeyler anlattım

                 hiçbir şey beklemeden insan kardeşlerime: 

Hiç olmazsa bu şiiri okurken

                              mutlu olsunlar diye.

Buysa suçum: Hazırım! 

              Cayır cayır yanmaya cehenneminde

Özkan Mert', 'dünyada çok güzel şeyler var... Çok güzel şeyler var dünyada... Ben mesela bir sokak tanırım İzmir''de           yere düşen inci taneleri gib...', ARRAY['Türk Edebiyatı','Şiir','Özkan Mert']::text[], 8.5, '{"poet":"Özkan Mert","poet_slug":"ozkan-mert","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/dunyada-cok-guzel-seyler-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözlük', 'sozluk-selami-ozturk-v3iri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğimi söylemek istiyorum…

Hangi kelimelerle anlatacağım bulamıyorum….

Bütün sözlükleri arıyorum…

Sana ait olanı bulamıyorum…', 'Seni sevdiğimi söylemek istiyorum… Hangi kelimelerle anlatacağım bulamıyorum…. Bütün sözlükleri arıyorum… Sana ait olanı bulamıyorum…...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sozluk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Çocukları', 'sokak-cocuklari-selami-ozturk-ea0mw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sokak çocukları

Onlar yalnızlığın rıhtımından 

yola çıkan gemilerin garip yolcusu, 

Onlar umutsuz dünyalarının tek suçlusu, 

Onlar sevgi kavramının üvey yavrusu, 

Onlar karanlık ve soğuk sokakların yalnız çocukları, 

Ya bizler, 

Görürken nefret ettiğimiz, 

Sevmediğimiz, 

Tiksintiyle baktığımız

Bu insanlar için ne yaptık.... 

Bunun karşılığı bir hiçse 

ben neyim sorusunun yanına? koymayı unutmayın...', 'Sokak çocukları Onlar yalnızlığın rıhtımından  yola çıkan gemilerin garip yolcusu,  Onlar umutsuz dünyalarının tek suçlusu,  Onlar sevgi kav...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sokak-cocuklari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanla', 'zamanla-selami-ozturk-zipjd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umutlar tükenirken gün ve gün

Benim yine aynı yerde yüreğim üzgün

Gözyaşlarım süzülürken damla damla

Kimbilir unuturum senide zamanla', 'Umutlar tükenirken gün ve gün Benim yine aynı yerde yüreğim üzgün Gözyaşlarım süzülürken damla damla Kimbilir unuturum senide zamanla...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zamanla-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgulama', 'sorgulama-mustafa-sureyya-sezgin-010r7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hangisi doğru, 

Okşamak mı, dövmek mi? 

Ağlamak mı, gülmek mi? 

Her şey beyninizde kilitli! ..

Hangisi güzel, 

Sarılmak mı, dönmek mi? 

Sevmek mi, sevilmek mi? 

Algılayın gönlünüzce evreni! ..

Hangisi gerçek, 

Yaşamak mı, ölmek mi? 

Cennet mi, cehennem mi? 

Çözün kilitleri artık kafalardan! ..

İsterseniz her şey doğru, 

Ve isterseniz her şey yanlış.

Anahtar siz de gizli, 

Tanrı size bağışlamış! ..

Yaşam size bağımlı, 

Günler geçerken bite bite...

Sorgulayın dünyanızı, 

Nedir acaba relativite? 

(İstanbul,26.02.1996)', 'Hangisi doğru,  Okşamak mı, dövmek mi?  Ağlamak mı, gülmek mi?  Her şey beyninizde kilitli! .. Hangisi güzel,  Sarılmak mı, dönmek mi?  Sevm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sorgulama-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kokusu Soldu Gülün', 'kokusu-soldu-gulun-emre-gumusdogan-iz9qu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'göverdikçe gönenen sevdaydık 

yüreğimizde sarkaçlı saat tiki 

söyle ne kaldı ki 

bozdursan para etmez sözlerden 

ne kaldı soruyorum 

hercainin yırtık renginden 

yağmurları paslanmış buluttan 

bir de böğürtlen çalılarından ve sisten 

zaman yadsırken düşlerimizi 

serseri bir umarsızlık değil mi 

biriktirdiğimiz dağarcığımızda 

kendimizi öğüttüğümüz değirmenlerimizde 

iki bıçak gibi birbirine bilenmiş 

kıyılarımızda fırtına tanrıları 

uyandığımız sabahlar 

kokusu solmadı mı önce gülün 

kapı önüyüz tenha akşamların tünediği 

küflendi zaman 

saksısını yitirmiş sardunyadan söz etme bana 

ayrılıklardan ya da özlemlerden 

çıkmaz sokak gibi geçerken içimizden 

tabulardan söz etme bana 

tabular ki gül makası 

en güzel masallarımızı budayan', 'göverdikçe gönenen sevdaydık  yüreğimizde sarkaçlı saat tiki  söyle ne kaldı ki  bozdursan para etmez sözlerden  ne kaldı soruyorum  hercain...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kokusu-soldu-gulun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın Sesi', 'ayriligin-sesi-emre-gumusdogan-r8x3h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'döverken kıyılarımı karadeniz yeşili 

bir boyuttan diğerine 

gemiler / kıyısız ve ışıksız / 

yüzer çilingir sofralarımda 

taşır zamanı kırılgan dallarım 

yaşlı bir zeytin ağacı olurum 

marmarada 

zehirli sarmaşıktır saçların 

dolanır gecelerime 

kor ırmaklar akar içimde 

kirpiklerimden kalkan yağmur bulutları 

çiçeğe durur 

geleceğin aynasında 

en ince nağmesinde 

kopan bağlama teli gibi 

martı çığlıkları yükselir gözlerinden 

derinlerime inen sokaklara 

kurar barikatını 

ayrılığın sesi birikir 

yalnızlık sarnıcımda', 'döverken kıyılarımı karadeniz yeşili  bir boyuttan diğerine  gemiler / kıyısız ve ışıksız /  yüzer çilingir sofralarımda  taşır zamanı kırıl...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayriligin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut', 'unut-mustafa-sureyya-sezgin-qkmaw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unut bütün sözlerimi, 

Gözlerimi de unut.

Yaşananı

Yaşanmamış, 

Söyleneni

Söylenmemiş say.

Kalmasın hiç yüreğinde

Küçük olsa da bir umut, 

Özleneni sen unut! ..

(İstanbul,01.03.1996)', 'Unut bütün sözlerimi,  Gözlerimi de unut. Yaşananı Yaşanmamış,  Söyleneni Söylenmemiş say. Kalmasın hiç yüreğinde Küçük olsa da bir umut,  Ö...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/unut-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiy Gibi Düşersin Tenime', 'ciy-gibi-dusersin-tenime-emre-gumusdogan-xzecu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çiy gibi düşersin anılarıma 

kuşluk vakitlerinde 

kumrular çatılarda sevişir 

yiter yasemin kokulu öğlenler özleminde 

koyu gölgelere sığınsa da suskunluğum 

isyan kesilirim 

çiy gibi düşersin yüreğime 

gün batımlarında 

göl kıyısına bir çınar kondururum 

hüznü sağar güneşin son deminden 

yoksulluğumu paylaşır... acılarımı... 

çoğalır gönenirim 

çiy gibi düşersin tenime 

sabaha karşılarda 

tenimi sorgular tenin 

yaşanmamış hazlar harmanlanır 

tütsü kokan çarşaflarda 

yapraklarında oğul veririm 

çiy gibi düşersin gözlerime 

yokluklarında 

savdana mı bilenirim', 'çiy gibi düşersin anılarıma  kuşluk vakitlerinde  kumrular çatılarda sevişir  yiter yasemin kokulu öğlenler özleminde  koyu gölgelere sığıns...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ciy-gibi-dusersin-tenime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştü Kargısı Umudun', 'dustu-kargisi-umudun-emre-gumusdogan-5wf4v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'küçük göller vardır 

dağlarımda / derin / 

yükleyip kirpiklerime hüznü 

içinde yansır silüetin 

tükettim üleştire üleştire 

yaşam sunaklarında çocuk gülüşümü 

gizil dönencelerde 

bilinmez kıyılara çarpıyor 

yorgun mevsimlerimi zaman 

kent sokaklarında yitti ıslıklarım 

yağmaladı martılar 

kıyılara çarpan son güneşlerimi 

bozgun var 

düştü kargısı umudun', 'küçük göller vardır  dağlarımda / derin /  yükleyip kirpiklerime hüznü  içinde yansır silüetin  tükettim üleştire üleştire  yaşam sunakların...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dustu-kargisi-umudun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılma (1)', 'yanilma-1-mustafa-sureyya-sezgin-kw918', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlayacaksın küçüğüm, 

Gün gelince sen de anlayacaksın.

Bugün, 

Gözünde büyüttüğün

Ve insanları süsleyen

Baştan çıkarıcı değerlerin, 

Yaldızlı ve parlak

Çekiciliğine kanarak, 

Hüsranı yudum yudum

Yaşayacaksın.

Anlayacaksın küçüğüm, 

Gün gelince sen de anlayacaksın.

Kendi iç dünyanın zenginliği ile

Severken tüm yaratılanları, 

Bu mısraları okuyacak, 

Belki de ağlayacak

Acılarla yoğrulacak, 

Pişecek ve olgunlaşacaksın.

Güzelliklerin görüntüde değil, 

İçerilerde olduğunu

Bir gün terkedilince

Sen de anlayacaksın! ..

(İstanbul,12.03.1996)', 'Anlayacaksın küçüğüm,  Gün gelince sen de anlayacaksın. Bugün,  Gözünde büyüttüğün Ve insanları süsleyen Baştan çıkarıcı değerlerin,  Yaldız...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yanilma-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fasıl', 'fasil-mustafa-sureyya-sezgin-xpwno', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yumuşak bir kadın sesi

Yüreğimi titreten, 

Alıp beni bu günden

Gençliğime götüren.

''Hasır'' da fasıl var bu gece, 

Beni inleten şarkı

N i h a v e n t ! ..

İçelim bir kadeh daha

Bitmesin bu muhabbet! ..

(İstanbul,30.03.1996)', 'Yumuşak bir kadın sesi Yüreğimi titreten,  Alıp beni bu günden Gençliğime götüren. ''Hasır'' da fasıl var bu gece,  Beni inleten şarkı N i h a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/fasil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdacan I', 'sevdacan-i-ahmet-can-akyol-ls5de', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bekliyordum Sevdacan

Ve sen tanış bir merhabayla çıkageldin

Vakit ıssızdı ve mahmur

Şafak nazlı bir çizginin koynunda uyuyordu

Ve güneş sanki üşengeç sabahlarıma

İlk kez böyle yakın duruyordu

Ben bitap ve uykusuzdum

Ve yılların vebali abanmışken omuzlarıma

Ben azalmışlığımla çok daha çok

Sıcacık gülüşünün seyrinde yeniden

Yeniden doğuyordum

Hazan gözlerimde ışıklar eriyordu

Bu belki senin bana sayısız ilklerden sonra ilk gelişindi

Bu belki senin şair yüreğime hoş gelişindi', 'Bekliyordum Sevdacan Ve sen tanış bir merhabayla çıkageldin Vakit ıssızdı ve mahmur Şafak nazlı bir çizginin koynunda uyuyordu Ve güneş sank...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevdacan-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esrarın Gözlerindi', 'esrarin-gozlerindi-ahmet-can-akyol-qt720', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Esrarın gözlerindi

Açtıkça renginde binbir ışık

Kırpışa kırpışa suskunluğu öğrendi

Ama ben ne bilirdim ki

Gülüşün nar gibi diriyken

Kirpiklerindeki gölgenin

Umudumu üşüteceğini', 'Esrarın gözlerindi Açtıkça renginde binbir ışık Kırpışa kırpışa suskunluğu öğrendi Ama ben ne bilirdim ki Gülüşün nar gibi diriyken Kirpikle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/esrarin-gozlerindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın', 'varsin-ahmet-can-akyol-opcja', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varsın

Devasa bu sevda

Bir kuşun kanadına sığınmış desinler

Oysa senin çağlayıktan süzüp aşkı

Beni bulman olay değildi

Ve benim gönlümdeki sevda

Daha kolay değildi tutkulardan

''Ya ben ya kavga'' demiştin alev gözlüm

Ama bilemedin ki

Ben ikisini de içebilirdim

Aynı kaptan', 'Varsın Devasa bu sevda Bir kuşun kanadına sığınmış desinler Oysa senin çağlayıktan süzüp aşkı Beni bulman olay değildi Ve benim gönlümdeki s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/varsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Kimseyi Bu Kadar Sevmedim Ben', 'hic-kimseyi-bu-kadar-sevmedim-ben-ahmet-can-akyol-ss3to', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç kimseyi bu kadar sevmedim ben

Bir de hiç bu kadar başım belalı olmadı

Sensizlik neydi acaba

Seninle bir bütün ne

Ne zaman yok saydıysam doğrularımı

Uslanmaz bu yürek beni felaketlere sapladı

Rengimi masmavi bir geceye verende bile

Ellerime sen değdin

Sen böldün rüyalarımı

Çünkü senden önce

Çözümsüz denklemlerde bu kaçıncı demeden

Yalnızlığımı bölüp iki ayrı zamana

Ağladığım da oldu / güldüğüm de

Soylu bakışların ardı sıra', 'Hiç kimseyi bu kadar sevmedim ben Bir de hiç bu kadar başım belalı olmadı Sensizlik neydi acaba Seninle bir bütün ne Ne zaman yok saydıysam ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hic-kimseyi-bu-kadar-sevmedim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlusun', 'suclusun-ahmet-can-akyol-bsn15', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O gün bütün sözleri geçip

Düşlerimi incittin kız

Hassas yerime vurdun

Aklımı çeldin

Üstelik hiç bir şey sormadın

Suçlusun', 'O gün bütün sözleri geçip Düşlerimi incittin kız Hassas yerime vurdun Aklımı çeldin Üstelik hiç bir şey sormadın Suçlusun...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/suclusun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehir Bir Aşktı', 'zehir-bir-askti-ahmet-can-akyol-uwfci', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kontras olmak füme gecelerde

Aklına gelmezdi kimselerin / aşkolsun

Bu yüzden şiirli şarkılı çoğul sohbetleri unutup

Başı boş bıraktık sözcükleri

Çünkü camları öperken yağmur

Firari rüzgarların seyri bize uzaktı

Çünkü sonu hüzün de olsa

Yaşanmak istenen

Bedeli peşin

Zehir bir aşktı

Kaçınılmazdı.....', 'Kontras olmak füme gecelerde Aklına gelmezdi kimselerin / aşkolsun Bu yüzden şiirli şarkılı çoğul sohbetleri unutup Başı boş bıraktık sözcük...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zehir-bir-askti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdacan II', 'sevdacan-ii-ahmet-can-akyol-5ur7e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Peki seni Sevdacan

Seni nasıl anlatmalı

Sözcükler yetmez seni anlatmaya

Şiirler çaresiz şarkıya döner

Daralır yüreğim sevdana tutsak

Buzullar ortasında yangın gibisin

Efsane nedir ki yaşanan günde

Hayallerle süslenen masal nedir ki

Gerçeğin yalana döndüğü yerde

Bir varolup kaybolan serap gibisin

Bir bıçak gibisin iki yanı keskin

Ekmek gibisin bana su gibisin

Dokunamıyorum sana sığamıyorum

Saramıyorum seni kahroluyorum', 'Peki seni Sevdacan Seni nasıl anlatmalı Sözcükler yetmez seni anlatmaya Şiirler çaresiz şarkıya döner Daralır yüreğim sevdana tutsak Buzulla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevdacan-ii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birşeyler Söyle', 'birseyler-soyle-ahmet-can-akyol-ej2ia', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haydi birşeyler söyle sesime sesin değsin

Ezgilensin soluğun şarkılansın dillensin / söyle

Söyle

Ve

Uzaklarda olsan dahi

Hatırım için bırak herşeyi

Bırak herşeyi yitirilen günleri düşün

Ve yitirilecek olan yürek dilleri

Çünkü hiçbir silah güçlü değildir sevgi kadar

Hiç bir sevgi güzel değildir senin gibi', 'Haydi birşeyler söyle sesime sesin değsin Ezgilensin soluğun şarkılansın dillensin / söyle Söyle Ve Uzaklarda olsan dahi Hatırım için bırak ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/birseyler-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzündür Aşk', 'huzundur-ask-ahmet-can-akyol-cdn1f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık gel sen bunları yok say

Artık git sen bunları yaşanmamış bil

Sözüne sadık kal

Ve sen ''hiç bir şeyin kaçkını'' olma

Ama

Yine de unutma

Esmer düşlerimde ak bir güneştin ve doğurgan

Bu yüzden seni beter sevdim Sevdacan

Asırlar da geçse

Yalan yok bu sözümde

Pişmanlık da

Biraz sevinçse

Biraz da gözyaşıdır yüreklere tutunmak

Ne olur artık vurma beni

Uzaklaş

Bundan böyle benim için hüzündür aşk!', 'Artık gel sen bunları yok say Artık git sen bunları yaşanmamış bil Sözüne sadık kal Ve sen ''hiç bir şeyin kaçkını'' olma Ama Yine de unutma E...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzundur-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ken', 'ken-erhan-meydan-7qbj8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni sever-

ken

seni içer-

ken

seni düşünür-

ken

seni özler-

ken

seni gelir-

ken

seni bekler-

ken

seni düşler-

ken

seni ogrenir-

ken

seni okur-

ken

seni yazar-

ken

seni diliyor-

ken

seni seviyor-

ken

seni tanıyor-

ken

sen-

ken

ben-

ken 

biz-

ken', 'seni sever- ken seni içer- ken seni düşünür- ken seni özler- ken seni gelir- ken seni bekler- ken seni düşler- ken seni ogrenir- ken seni ok...', ARRAY['Türk Edebiyatı','Şiir','Erhan Meydan']::text[], 8.5, '{"poet":"Erhan Meydan","poet_slug":"erhan-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyaretçi', 'ziyaretci-mine-ozdemirtas-zmns0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar; bir aşığım vardı. Deli mi deli. 

Her sabah; elleri cebinde; köşede beklerdi beni. 

Başına değerken; duvardan sarkan hanımeli. 

Islık çalardı. Esmerdi. Çenesinde çukuru vardı. 

Simsiyahtı gözleri. Kömür gibi bakardı. 

Bu sabah, uzaklardan gelen bir adam; 

Tam köşe başında durdu, düşündü ve gülümsedi bir an. 

Başına değdi hanımeli, sarkarak duvardan. 

Esmerdi. Üstelik;  çenesinde çukuru vardı.

Elleri cebinde; bir zaman, usulca  ıslık çaldı.', 'Bir zamanlar; bir aşığım vardı. Deli mi deli.  Her sabah; elleri cebinde; köşede beklerdi beni.  Başına değerken; duvardan sarkan hanımeli. ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ziyaretci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Don Kişot', 'don-kisot-mine-ozdemirtas-xeudg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Don kişot yel değirmenlerine karşı.

Kem bakışlar, Nazar ve sabır taşı.

Yalın kılıç dalıvermek savaş meydanına,

Ya da susmak.

İçimin uçları arap saçı

Başıma açtığın dertlere bak.

Yaz ve kış ya da dört mevsim temizliği.

El ele verseler kentin çöpçüleri.

Kaldırabilirlermi bu pisliği.

Çiğ yemedimki karnım ağrısın.

Aşağı tükürene sakal,

Yukarı tükürene bıyık.

Dağıttım doğruları,

Bir yanda gururum, bir yanda ben.

Tam ortamızda sen varsın.', 'Don kişot yel değirmenlerine karşı. Kem bakışlar, Nazar ve sabır taşı. Yalın kılıç dalıvermek savaş meydanına, Ya da susmak. İçimin uçları a...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/don-kisot-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Zamana Sığdı Yaşamak', 'dar-zamana-sigdi-yasamak-mine-ozdemirtas-87r9y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dar zamanıma sığdı yaşamak.

Vakit azdı sevdaya.

Boş günüme gelse;  şöyle ağız tadıyla 

Ballandıra, ballandıra 

Yürekler dolusu,  severdim ama; 

dedim ya 

Hiç fırsatım olmadı ki.

Kaçmaktan kovalamaya.

Bu; köhnemiş kanayan kente 

Esir düşmüşken bol kepçe 

Bir sabah; bir de akşam 

Hüzün basıyor iyice.

İşte; o hassas anlarda 

Ölesiye acıyorum. 

Hem yetim; hem öksüz; 

Kimsesiz duygulara', 'Dar zamanıma sığdı yaşamak. Vakit azdı sevdaya. Boş günüme gelse;  şöyle ağız tadıyla  Ballandıra, ballandıra  Yürekler dolusu,  severdim am...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dar-zamana-sigdi-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Dokundun İşte', 'yine-dokundun-i-ste-mine-ozdemirtas-inaj4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine dokundun işte.......titreyen ellerinle

Çatlamış toprağımın, susamış dikenine.

Geçmişe özlemlerin tüterken gözlerinde; 

Kıyamam.....ağlıyorsun. İçini çeke çeke.

Şimdi harman yerinde şiirler... hazan geldi diye.

Dökülüyorlarken birer birer. Aralarında işin ne? 

Şairin pınarı bir gün kurursa diye

Kıyamam...... ağlıyorsun. İçini çeke çeke

Sana idi mısralar. Sana ve sevgiye.

Aşk  elbet ki var.... Geçmişten âti’ye

Daha yeni  yeni başlıyorken, Bu telaş niye? 

Kıyamam......... ağlama içini çeke çeke.', 'Yine dokundun işte.......titreyen ellerinle Çatlamış toprağımın, susamış dikenine. Geçmişe özlemlerin tüterken gözlerinde;  Kıyamam.....ağlı...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yine-dokundun-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağ Bozumu', 'bag-bozumu-mine-ozdemirtas-nheir', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdilerde 

Her yerde plastik koltuklar var biliyorsun. 

Sanki, 

Oturak yerim... oturağını hep yanında taşıyor. 

Ben tosbağa değilim istemiyorum. 

Sıkıldım. 

Artık mevsim bağbozumuna koşuyor 

Yaz güneşi göç etmeden az önce 

Bana bir kır kahvesi bul, ne olursun! 

Dimdik bir yamaçta 

Ya da ince bir derenin kenarında 

Hiç farketmez.

Ama; mutlaka! 

Masası ve sandalyeleri tahtadan olsun. 

Düşünsene! 

Sımsıcak bir köy ekmeğini paylaşıyoruz. 

Tulum peyniri, ballanmış incir... Çardak altında 

Asma yapraklarının arasında gülümseyen 

Bir salkım kara üzüm 

Taze ceviz içi ve... şarap. 

Biliyorum gülüyorsun. 

Sence şarap yerine ayran olmalıydı değil mi? 

Plastik sandalye sendromu bu. 

Ya da; kültür karmaşası.Ne dersen de. 

İstersen; teşhisin, bunalım olsun. 

Kent soyluluğumun; 

Bağbozumuna soyundum. 

Daha ne olsun?', 'Şimdilerde  Her yerde plastik koltuklar var biliyorsun.  Sanki,  Oturak yerim... oturağını hep yanında taşıyor.  Ben tosbağa değilim istemiy...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bag-bozumu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Giden Düşlerim, Yine Sensiz Döner', 'sensiz-giden-duslerim-yine-sensiz-doner-mine-ozdemirtas-gw26w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O orman kenarındaki, kulübeye

Sensiz giden düşlerim;

Yine sensiz döner.

Odun kıran bir adam,

Ve onu seyreden bir kadın.

Ne zaman düşledik bunları ? 

Ya da; ne zaman yaşadık.

Hiç bir şey anlamadım.

İçimde bir ses,

Üçgünlük ömrü bir günde tüketttin der.

Beni deli eder.

Yaşanmamışlıkların tümüne,

Kanat uçurur martılar.

Gerçekler yığılır önüme.

Umutlara yağmur yağar.', 'O orman kenarındaki, kulübeye Sensiz giden düşlerim; Yine sensiz döner. Odun kıran bir adam, Ve onu seyreden bir kadın. Ne zaman düşledik bu...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensiz-giden-duslerim-yine-sensiz-doner-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdim Bitmiyor', 'derdim-bitmiyor-asik-sefai-so8j2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daglarin çilesi bitti

Benim derdim bitmiyorki

Bülbül goncasina öttü

Benim derdim bitmiyorki

Senin ile alem baska

Gözlerin düsürür aska

Görmeseydim seni keske

Benim derdim bitmiyorki

Sanki abu-hayat içti

Kanat vurup göge uçtu

Aklim isyan edip kaçti

Benim derdim bitmiyorki

Yerin gögün fermani o

Su gönlümün kervani o

SEFAI''nin dermani o

Benim derdim bitmiyorki', 'Daglarin çilesi bitti Benim derdim bitmiyorki Bülbül goncasina öttü Benim derdim bitmiyorki Senin ile alem baska Gözlerin düsürür aska Görme...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/derdim-bitmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan mıydın Gerçekten', 'yalan-miydin-gercekten-i-lyas-altuner-n9q2j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I.

Kaç kez dolaştıysam yollarda tek başıma

Bulamadım yalnızlığı, ah senin yüzünden

Bir çiçek boynunu büküp bana mı bakmış ki

Aylaklığımı dert edinip de ilenmiş mi sokaklar

Oysa ben kurtulmayı yeğlerken senden

Yine hayalinle karşılaştım her akşam

Adımlarımdaydın, kaçamıyordum

Gözlerimin yeri kestiği yerde saçların vardı

Her bir teli birer bukağı olmuşçasına

Sarıyordu bu soğukta gövdemi ateşin

Seni kaybetmeye çıkıyordum her akşam

Her akşam toz duman buluta bürünürdü veda

Her akşam vedamı doğradın çekinmeden

Kaldırım taşlarına tutunmuştun işte

Bırakmıyordu ellerin yakamı sıyrılıp giderek

Büyütmedin yalnızlığımla açan karanfilleri

Yarama diken örttün her akşam

Her akşam ay doğar güneş batımında

Her akşam yalnızlığımı karanlıkta bıraktın

Evet evet, sendin yüreğimi taşlayan alçak

Yüreğim ki, sensizliği dua yapıyordu her akşam

Her akşam, sabahı haber veren elçi

Her akşam sabahımı alıyordun gecemi çalarak

Oysa ben, sensizliği yeğliyordum

II.

Ne zaman dolaştıysam yollarda yalnız başıma

Yine sen çıkıyordun önüme karaltı olarak

Ne güne dek sürecek bu ikilem

Sularken bahçesini semanın çılgın bir sağanak

Sen kimin bahçıvanısın ki, yüreğime kor yağdırdın

Yalnız dolaşmak istedim her akşam

Her akşam, sokakta sükuneti mahmuzlar

Her akşam bastığım taşlarda çınladın

Sensiz olmayı yaşarken kaldırım kenarlarında

Ağaç gölgesinden rüzgarla eserek üşüttün

Ve de ürküttün yalnızlığı her akşam

Her akşam, dantel örer boşluğu tığ edinip

Her akşam kalbime kendinle hüznü dokudun

Hançereyi düşman saplar dostun yüreğine

Kuzum, sen uslanmak bilmez misin

Kahırdın, çileni örttün her gece üstüme

Alnımı rüzgara çaldım bir zaman

Istıraplarımı kaldırıma yaygı yaptım

Yediğim lokmaya bulaştın toz olup çökerek

Bir kaya parçası kapatırsa yolumu eğer

Anladım ki, yoluma yüreğinle ket vurdun

Katran döktün avuçlarıma, böyle muzlimsin

Avuçlarımı yalnızlığa açtım her akşam

Her akşam, birer buse kondurur yıldızlara

Her akşam yıldızımı söndürdün

III.

Hangi vakit dolaştıysam yollarda tek başıma

Karşıma sen çıkıyordun bin bir kılığa bürünüp

Bildim, İblis neden kandırırmış kalpleri

Bu telaşe, korkarım yangına çevirecek

Üşütecek buz olarak bir ara beni

Saracaktır hayalin etrafımı o zaman

Neden çıkmadın sanki karşıma bu akşam

Bu akşam ölüm kokuyor arzın çemberi

Bu akşam neden kinin duraksadı

Yoksa, yalan mıydın gerçekten', 'I. Kaç kez dolaştıysam yollarda tek başıma Bulamadım yalnızlığı, ah senin yüzünden Bir çiçek boynunu büküp bana mı bakmış ki Aylaklığımı der...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/yalan-miydin-gercekten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağırın Gelsin Akşamlar', 'cagirin-gelsin-aksamlar-i-lyas-altuner-yduxc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çağırın gelsin akşamlar

Bulanık yağmurların ardı güneştir

Şatafatlı karanlıklarıyla

Ey üstümüze örtülen siyah gece

Yıldızların neden okşuyor başımı

Neden bağrına basıyor beni korkular

Çağıralım gelsin akşamlar

Sabah daha erken doğacak

Yarılır gökyüzü çatlamış toprak gibi

Şimşekli kılıçlarıyla yağmurun

Beyaz tenim örtüşür kapkara bulutlarla

Akşamdır ıstırap dolu

Ve sabahtır geceye maya çalan

Şımarık yıldızlar bulutlarla evli

Evler var yanı başımda

Evler ki, mum ışığıyla aydın

Bir yağmur özgürlüğüyle öylece

Sabahı bekliyorum

Çağırın gelsin akşamlar

Toz bulutu yükselsin üstümüzden

Soğuklar işlesin tenimize

Dondursun kanımızı akşam

Örsün bizi gece kasvetli karanlığıyla

Bu akşam bir piramit aşkına

Kahır geçidi sunsun Mısır sarayı

Karsın bizi taşlar arasına

Ölüm marşı çalsın rüzgar', 'Çağırın gelsin akşamlar Bulanık yağmurların ardı güneştir Şatafatlı karanlıklarıyla Ey üstümüze örtülen siyah gece Yıldızların neden okşuyor...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cagirin-gelsin-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Makara', 'makara-i-lyas-altuner-z6h1d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen sar makaranı yine

Ben de dolanayım

Devam edelim kaldığımız yerden aşka

Amacım suyu burmak değil

Yoksa usluyum ben de her çocuk gibi

Kutsal çamurla sıvalı ellerim

Söndürüyorum

Yangın var yüzümde 

Sen

Sarıyorsun ya kanımı makaraya

Çığırtkan bir sessizlik

Ve çıldırıyorsun saçmalarımla

Can ellerimde titriyor

Islak zihinlerle dolu kör kuyu

Yine bir Yusuf’a gebe

İşte benim işkence içinde son Yusuf

Sen de Potifar’a zengin cariye

Hangi masala konu oluruz, bilemiyorum

Bir ip sarkıyor yukardan

Bir iple esaret sarkıyor

Yine sarıyorsun beni

Kanlı gömleğimle paslı makaraya

Yine suları buruyorum

Hadi sar beni

Bir daha sar duygusuz kalbine

Ve kar ki, piramit yükselsin kanımdan', 'Sen sar makaranı yine Ben de dolanayım Devam edelim kaldığımız yerden aşka Amacım suyu burmak değil Yoksa usluyum ben de her çocuk gibi Kuts...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/makara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nora Lisa ve Aşkın Ölümü', 'nora-lisa-ve-askin-olumu-i-lyas-altuner-i139i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'NORA LİSA VE AŞKIN ÖLÜMÜ

I. FASIL

Nora Lisa; güller kadar ahenkli

Kalbime saplanan bir kuş kanadı

Hayatın busesi pembecik renkli

Aşkından yüreğim sevda ağladı

Nora Lisa; güller kadar ahenkli

Eritir gönlümü gökte mavi ay

Kalplerde buzullar aşka dönüşür

Fırlatır okunu üstüme bir yay

Kalbimdeki sevgi kanla örtüşür

Eritir gönlümü gökte mavi ay

Sevgilim, konuşma! Sesin duyulur

Nora Lisa, sana bakmamam gerek

Seni her görüşte kalbim oyulur

Bu aşk ömür boyu sürüp gidecek

Sevgilim, konuşma! Sesin duyulur

Leylak kokuları, tertemiz toprak

Ruhuma üfleyip durur baharı

Bir aşk öpücüğü ve sarhoş yaprak

Senden haber verir gönül diyarı

Leylak kokuları, tertemiz toprak

İncitir gönlümü hazin bakışın

Kordan bir ok olmuş yakarcasına

Düştü üstüme ak çiçeği kışın

Yangına susamış bakarcasına

İncitir gönlümü hazin bakışın

Halka halka geçer saatler, Nora

Titrek ışıkların altında kaldık

Masmavi aydınlık dönüşür mora

Çek bakışlarını, gün bitti artık

Halka halka geçer saatler, Nora

Akşamın sefası bir başka olur

Konar gönüllere bembeyaz kuşlar

Şu zavallı aşık derinden solur

Kanar yüreği de akmaya başlar

Akşamın sefası bir başka olur

Nora Lisa, kaldır kirpiklerini

Çevir gözlerini nemli gözüme

Gökten bir el siler gönül kirini

Sevdalı gözlerle bir baak yüzüme

Nora Lisa, kaldır kirpiklerini

Utanarak geçme yanımdan, Lisa

Daha dinlemedin benden şiirler

Çevirip yüzünü de boğma yasa

Bu güzel türküyü yazsın şairler

Utanarak geçme yanımdan, Lisa

Zamanla büyürmüş aşk gönüllerde

Kahpe ayrılıklar yasaklanırmış

Tomurcuklar açan beyaz güllerde

Sevgi, yavaş yavaş yapraklanırmış

Zamanla büyürmüş aşk gönüllerde

Utangaç bakışlar ve süzülen göz

Haber verir bana masum gülüşle

Ağzından çıkacak o rindane söz

Öldürür sevinçten, sıcak öpüşle

Utangaç bakışlar ve süzülen göz

Nora Lisa; güller kadar ahenkli

Kalbime saplanan bir kuş kanadı

Hayatın busesi pembecik renkli

Aşkından yüreğim sevda ağladı

Nora Lisa; güller kadar ahenkli

II. FASIL

İsmiyle müsemma olmuştu sevda

Yoksa onu ben mi öyle sanmıştım

Bir güldürür ve bir ağlatır ya da

Ben mi bir sevip de bir usanmıştım

İsmiyle müsemma olmuştu sevda

Lütuftur kerem bahşeden lisan

Yıpranmış lügatin ne anlamı var

Çağlar üstü olsa inleyen figan

Gönül yaralıysa, mutlaka susar

Lütuftur kerem bahşeden lisan

Yas tutarmış gönül, bundan kime ne

Girift sokakları bilmez ayağım

Labirent sıvalı sevda evine

Girdim ama, bulup yol çıkamadım

Yas tutarmış gönül, bundan kime ne

Asilik ruhta var, inkarı olmaz

Sen de en az benim kadar asisin

Bilmez misin, aşkın diyarı olmaz

Ta öbür ülkeden geliyor sesin

Asilik ruhta var, inkarı olmaz

Sudur tüm varlığın gerçek kaynağı

Ateş yanar, gönür islenir durur

Atın üstümden şu lanet toprağı

Bir hava genzime duman uçurur

Sudur tüm varlığın gerçek kaynağı

Azaldıkça yollar, uzar mesafe

Bakışlarım ufka cefa taşıdı

Gönlünde gizlenen ayarsız kefe

Yüreğimi katran ile kaşıdı

Azaldıkça yollar, uzar mesafe

Leyyin bir kelamla nezaket gelse

Kalbimin atışı birden dururdu

Söyler misin kuzum, bu aşk değilse

Sevda sahiline nasıl vururdu

Leyyin bir kelamla nezaket gelse

Taşınması güçtür elde cevherin

Güzellik dışarda mutlak pas tutar

Göğsüme dayanan soğuk mavzerin

İğnesi, bilirim kalbinde yatar

Taşınması güçtür elde cevherin

Uçarı zihinle dolaştım seni

Saatin kadranı firakı vurdu

Ayrılık, galiba aşkın kefeni

Yüzüme ateşten küller savurdu

Uçarı zihinle dolaştım seni

Nora Lisa, sebep neydi ezadan

Hangi hain kandırdı seni böyle

Ümitler boşluğa ağdı fezadan

Kanadımı neden kırdın ki böyle

Nora Lisa, sebep neydi ezada

Eskiyen arzular birden döküldü

Yapışmaz yarama sahte sevgiler

Birden yüreğimden ismin söküldü

Aşkım, karanlık bir yerde iniler

Eskiyen arzular birden döküldü

Resmiyle müsemma olmuştu sevda

Yoksa onu ben mi öyle sanmıştım

Bir güldürür ve bir ağlatır ya da

Ben mi bir sevip de bir usanmıştım

İsmiyle müsemma olmuştu sevda

III. FASIL

Vaveyla kopmakta semadan yere

Meskun gönül yine kanadı hasıl

Arzdan Arş''a varan uzun öndere

Okudu aşk ile bir dahi fasıl

Vaveyla kopmakta semadan yere

Esridi yüreğim, sağnak olacak

Kupkuru toprağı ezecek yağmur

Cilasız avcuma leke çalacak

Ateşimle hayat bulacak çamur

Esridi yüreğim, sağnak olacak

Aşk ölür mü deme, işte ölüyor

Yalnız benim değil, senin de suçun

Nasıl ki bir şehit Arş''ta gülüyor

Zararı mı vardı aşka orucun

Aşk ölür mü deme, işte ölüyor

Şimdi yalnızca ben, yalnız ben varım

Firakın savurdu beni dağlara

Oysa yalnızlıktan ne çok bizarım

Takıldım enginde zalim ağlara

Şimdi yalnızca ben, yalnız ben varım

Kanımda donunca sıcak nefesin

Dirildi kalbimde olanca şikar

Sesime alevle yaklaştı sesin

Vücudum yandıktan başka ne çıkar

Kanımda donunca sıcak nefesin

Itır güzel kokar, yakarsan şayet

Gönlümün kokusu göğe uzandı

Sevgi ayetinde edilen lanet

Sanma ki banadır; yalnızlıktandı

Itır güzel kokar, yakarsan şayet

Nora Lisa, işte ölüm boğazda

Ayrılık ölümdür sevgili için

Aşkı tütsüleyen çetrefil nazda

Hayır yoktur, bilsen, ayrılık niçin

Nora Lisa, işte ölüm boğazda

Ölmek, olmak değil; kanma dervişe

Cam gibi içinde donar elbet can

Deniz kenarından ufka gidişe

Viran kiliseden alkış tutar çan

Ölmek, olmak değil; kanma dervişe

Leyla''yı saraya, Mecnun''u çöle

Hapseden katili kim durduracak

Mel''anet fışkıran kahırlı göle

Asa ile hangi Musa vuracak

Leyla''yı saraya, Mecnun''u çöle

Üstümde gafletten örülü sükun

Ayrılık damarı kalbimde hortlar

Hangi kitapta ki böyle bir kanun

Vuslat yaprağını dişler aç kurtlar

Üstümde gafletten örülü sükun

Mısralar kan gölü, kelimeler kan

Artık ışık vurmaz, perdeler kara

Firakın ölüme sarıldığı an

Aşklar kurşun sıkar hayata, zira

Mısralar kan gölü, kelimeler kan

Ünledi vaveyla semadan yere

Meskun gönül yine kanadı hasıl

Arş''tan arza inen uzun öndere

Okudu aşk ile bir dahi fasıl

Ünledi vaveyla semadan yere', 'NORA LİSA VE AŞKIN ÖLÜMÜ I. FASIL Nora Lisa; güller kadar ahenkli Kalbime saplanan bir kuş kanadı Hayatın busesi pembecik renkli Aşkından yü...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":184,"source_url":"https://www.antoloji.com/nora-lisa-ve-askin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bir Harap', 'ah-bir-harap-i-lyas-altuner-h0ux8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AH BİR HARAP

Ah bir harap

Dinginliğime nağme vuran

Yine hayalimin raksı ensemde

Yarına ne kaldı bugünden

Dönmek mi

Kalsın bağrımda bir ukde olarak

Düne hayal kuran

Ah bir hülya

Gözlerimde kımıldayan ağrı

Bakınca geceye yumulacak

Derin ve içine kapanık

Bir nakış şimdi kalbimde uyuyan

Kalkmak mı

Nasıl uyanayım bu ateşin rüyadan

Esrara yapılırken çağrı

Ah bir serap

Sükuta ahenk çalan alkış

Ruhumdaki incecik tebessüm

Bir yaprak hışırtısı

Bütün sükunetiyle inliyor hayat

Söylemek mi

Yetmiyor mu ki bunca şarkı

Ve geceye sükunlu bakış

Ah bir harap

Bu akşamla tenhalaşan gönül

Son deminde gecenin

En son mırıldanışını terennüm ediyor

Ki, neredeyse sabah olacak

Yaşamak mı

Mahkum mu olayım tekrar güneşe

Ne tatlıdır gecede ölüm

Ve de bir bukle siyah gül', 'AH BİR HARAP Ah bir harap Dinginliğime nağme vuran Yine hayalimin raksı ensemde Yarına ne kaldı bugünden Dönmek mi Kalsın bağrımda bir ukde ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ah-bir-harap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Caddeler', 'caddeler-i-lyas-altuner-dfooj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Caddeler mahremliğe gebe

Başına güneş geçmiş kaldırımların

Yalnız bir çocuk

Zamana asmış mahzun yüzünü

Kim bilir, belki de 

Çıldırmış olmalı ona göre sokaklar

Bir hararet ezikliği var

Tekleyip durur bedenleri güneş

Su yalnızlığı kadar sıcak

Son umudu da tükenince toprağın

Boynunu büker bir dilenci gibi

Yorgun ağaçlar

Çöker kaldırıma soyluca 

İnsanların umursuz bakışları arasında

Caddeler mahremliğe gebe

Açıkça soluyor nefesini kaldırımlar

Yalnız, bir kadın

Bakışlarını bir kuru ekmeğe satıyor

Açarak ellerini sokağa

Dua edercesine

Hayata lanet bağışlayarak

Bir cadde köşesinde', 'Caddeler mahremliğe gebe Başına güneş geçmiş kaldırımların Yalnız bir çocuk Zamana asmış mahzun yüzünü Kim bilir, belki de  Çıldırmış olmalı...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/caddeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Yağıyor Bembeyaz', 'kar-yagiyor-bembeyaz-i-lyas-altuner-brrtx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kar yağıyor bembeyaz

Üşüyerek bekliyorum yolları

Güneş topluyorum bacalardan

Kardan adam yapan çocuklar

Kardan bir sen yapamayacaklar

Kızaklı ihtiyar

Gemi indiriyor göğsüme sanki

Ben seni özlüyorum karda

Kar utanıyor hatırana yağmaktan

Kar yağıyor bembeyaz

Çocuk kalbi değmiş yüzümle

Ellerim duada

Kar, beyaz çiçeğidir özlemin

Yine çarmıha geriliyor gözlerimde bir İsa

Yine bir çiçek esmerleşiyor

Kardan adamlar yerlerde

Seni yitirdiğimi anımsatıyor bana

Gelirsen saçların karla örülü

Sana söz, bozmayacağım

Kar yağıyor bembeyaz

Benim yüzüm kanıyor

Çekingen yağmurlar yüzümde saklı

Utanıyor iffetimden mevsim

Bembeyaz örtüyor beni

Uçuşurken havada bir sarı yaprak

Kuşların gagasında bayram havası

Güneş saklanan bacalar

Beyaz duyguları kirletiyor

Çocukların elleri soğukla sarılı

Benim kalbim özleminle üşüyor

Kar yağıyor bembeyaz

Bir güvercin zikriyle yüce

Samanyolu kadar dipsiz şimdi dünya

Hayat salıncakta mesrur

Kaçıyorum nefrete dolanarak

Çünkü kar yağıyor güneşe

Soğuklar zafer takı

Sinem bu elemle garip', 'Kar yağıyor bembeyaz Üşüyerek bekliyorum yolları Güneş topluyorum bacalardan Kardan adam yapan çocuklar Kardan bir sen yapamayacaklar Kızakl...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kar-yagiyor-bembeyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müfsit İnat', 'mufsit-i-nat-i-lyas-altuner-9iey6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buddha’nın kıvrak yargıcı

Su yürütür yüzüme

İnce ve berrak

Kanamam, imkanı yok

Ey saçları dağınık bela

Kalbim sofi değil

Bu müfsit inadı bırak', 'Buddha’nın kıvrak yargıcı Su yürütür yüzüme İnce ve berrak Kanamam, imkanı yok Ey saçları dağınık bela Kalbim sofi değil Bu müfsit inadı bır...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mufsit-inat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrılar Göğsümde Boğulur', 'tanrilar-gogsumde-bogulur-i-lyas-altuner-m3mha', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanrılar ölmez diyorsun

İşte öldü yüreğimdeki sevinç ilahesi

Saadet bitti mi şimdi

Koşunca içi burkulur çocuğun

Bu yüzden olacak

Kaç gecedir sayıklamalarım

Hep tanrıların ölmesinden

Nusret çelengi yerlerde mahkum

Mesrur olamam bir daha

Celalli bir alemin çocuğuyum

Kanat çırparak göklerden yana 

Bir anda düştüm dağların yüzüne

Bulutlar kırbalarını başımdan

Aşağı ters çevirdi üstüme birden

Esrikleşip bedbaht vücudum

Sayıklamalardan uyandı

Ağlama duvarı sessiz

Susturmuş çünkü bendeki figan

Öylesine düalisttir yüreğim

Daha ne zamana kadar

Gönül yüzüne aksi çarpar

Gazi yağmurlarıyla ıslanmış göğün

Tanrılar göğsümde boğulur', 'Tanrılar ölmez diyorsun İşte öldü yüreğimdeki sevinç ilahesi Saadet bitti mi şimdi Koşunca içi burkulur çocuğun Bu yüzden olacak Kaç gecedir...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tanrilar-gogsumde-bogulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dipnot', 'dipnot-i-lyas-altuner-lv2ic', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rab Yasu’ya düşülen dipnotu

Öldürdüm asarak bir çarmıhta

Artık ne bir Yasu

Ne de bir Aziz Pavlus

Kör kuyuya gömdüm onları

İkisini birden

Meryem Ana’nın ruhu 

Varsın yaksın içimi

Paslı çivileri ki teslisin

Acıtmayacak ruhumu bundan böyle

Çünkü yok imanım benim

Ne teslise, ne de

Matta’nın çürümüş yazıtına

İşte böyle asiyim', 'Rab Yasu’ya düşülen dipnotu Öldürdüm asarak bir çarmıhta Artık ne bir Yasu Ne de bir Aziz Pavlus Kör kuyuya gömdüm onları İkisini birden Mer...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dipnot-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkümüzü Kimse Bozamaz', 'turkumuzu-kimse-bozamaz-i-lyas-altuner-bk6tf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Firakımıza müebbet yazılı

Hayata küsmüş zaman aksanıyla

Türkümüzü kimse bozamaz

Sanma yağmur yağdırır tozlu yüzüne 

Kin yüklüdür şimdi hava

Bir zulmetin hatırasıdır kararan bulutlar

Ceylan çevikliğinde güzellik portresi

Suretini ihanete değişmiş görünür

Ancak yine de sen

Kanımda açan kır eglantini

Damarlarımda beni besliyorsun

Palazlanır yanaklarında sanki

Şark’ın tozlu yanaklarındaki buse

Ak yüzü Selahaddin’in kılıcının

Kılıç sallamakta üzerine eğilen korkuya 

Ey içimde konaklayan İstanbul

Ne bu nefret kokan çilingir

Ne de bende pervaz olan yarım asır

Hiçbiri söyleyemez türkümüzü

Yalnız sen söyleyeceksin', 'Firakımıza müebbet yazılı Hayata küsmüş zaman aksanıyla Türkümüzü kimse bozamaz Sanma yağmur yağdırır tozlu yüzüne  Kin yüklüdür şimdi hava ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/turkumuzu-kimse-bozamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Gibi', 'masal-gibi-i-lyas-altuner-ojzvf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sal gözyaşlarını

Ya sel olur yanık bağırda

Ya da bir ev yıkılır

Uzakta

Çok ötede palazlanmakta bir ateş

Uzat korkusuzca elini

Isın 

Bak, ufka doğdu hüzün

Bu, toprak kadar çemenli su 

Sessizliğini hatırlatır akışın

Bir ben, bir de insanlar

Aksimiz çarpar kamçı kıvraklığında

Sen

Çatma kaşlarını böyle suya

Bu siyah, bu kara perde

Gözlerinde dalsın uykuya', 'Sal gözyaşlarını Ya sel olur yanık bağırda Ya da bir ev yıkılır Uzakta Çok ötede palazlanmakta bir ateş Uzat korkusuzca elini Isın  Bak, ufk...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/masal-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Badem Çiçeği', 'badem-cicegi-koksal-demir-c4pja', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'badem çiçeği gördün mü hiç

bir ruya kadar pembe

bir gölge kadar gerçek

tıpkı sevdam gibi

uzatsan elini

avucuna düşüverecek

aşk; 

kış ortasında baharı beklemkti

bir çift ela istanbul uğruna 

nice bağdatlar fethetmekti

gece yarısı

odana dolan hazin bir ayışığı

yarım kalmış bir şiir belki

ya da hüzzam bir şarkının

son notası demekti

ızdırabını çekerdik

ıslak kirpiklerinin her gece

ağlaşırdık güllerle

saba dek, sessizce

şimdi o gecelerden kalan

sinede ebedi matem, 

gül yapraklarında ebedi nem

sevdam zamansız, 

ümidim yersizdi; Bilirim

benim bahar zannettiğim

fırtına, tipi, karmış

unutma

badem çiçekleri erken açarmış.....', 'badem çiçeği gördün mü hiç bir ruya kadar pembe bir gölge kadar gerçek tıpkı sevdam gibi uzatsan elini avucuna düşüverecek aşk;  kış ortasın...', ARRAY['Türk Edebiyatı','Şiir','Köksal Demir']::text[], 8.5, '{"poet":"Köksal Demir","poet_slug":"koksal-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/badem-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Sevgilim', 'kucuk-sevgilim-ugur-seker-0q2e3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüyalarım sensin şimdi, hayallerimde; 

Yalnızca sen varsın şimdi kalbimde, 

Mutlu bir tebessüm varsa gözlerimde, 

Seni eserin küçük sevgilim.

Hüznün yerini mutluluklar aldıysa, 

Yüreğim yeniden aşkı bulduysa, 

Hazan mevsiminde çiçek açtıysa, 

Senin eserin küçük sevgilim.

Birde aşık oldum sevgiden başka; 

Yürek dayanırmı bu güzel aşka; 

Öyle bir duyguki, inan bambaşka; 

Senin eserin küçük sevgilim.

Ne kadar güzelmiş mutluluk meğer; 

Aşkın benim için dünyalar değer; 

İkinci baharı yaşıyorsam eğer; 

Senin eserin küçük sevgilim.', 'Rüyalarım sensin şimdi, hayallerimde;  Yalnızca sen varsın şimdi kalbimde,  Mutlu bir tebessüm varsa gözlerimde,  Seni eserin küçük sevgilim...', ARRAY['Türk Edebiyatı','Şiir','Uğur Şeker']::text[], 8.5, '{"poet":"Uğur Şeker","poet_slug":"ugur-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kucuk-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum Diyorsun', 'gidiyorum-diyorsun-ozcan-nevres-6rnv1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GİDİYORUM DİYORSUN

Gidiyorum diyorsun 

Bir daha dönmemek üzere

Gizlemeye çalıştığın o göz yaşların ne

Unutacağım seni diyorsun

Hem de bir daha anmamak üzere

Unutmak ve unutulmak ne acı

Sevenlere ölümü bile eder baş tacı

Ne sen ilk terk edensin

Ne de ben son terk edilen

Ne de yitik umutlara 

Son göz yaşlarını döken

Git ama sakın dönme bana

Göz yaşlarını akıtma boşuna

Mutluluk nedense yakışmadı sana

Seni ne kadar sevdiğimi biliyorsun

Belki de 

Seni sensiz yaşayamayacağımı sanıyorsun

Yazık ki aldandığını bilmiyorsun

Her şeyimi alıp götürsen de sevgilim

Yeter bana bende kalan hayalin 

			Özcan NEVRES

			22 Mart 2002', 'GİDİYORUM DİYORSUN Gidiyorum diyorsun  Bir daha dönmemek üzere Gizlemeye çalıştığın o göz yaşların ne Unutacağım seni diyorsun Hem de bir da...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gidiyorum-diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olmuş Bu Dünyanın Haline', 'ne-olmus-bu-dunyanin-haline-ozcan-nevres-34m88', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu Dünyanın Hali Ne Böyle

Ne  olmuş bu dünyanın haline 

Ne saygı kalmış nede sevgi

İnsancıklar elinde maskara olmuş 

Kimi cebinde üç beş kuruşu var diye

Sanır dünyayı satın aldığını

Kimi sanır okuyup ta adam olduğunu

Kimi yönetici olmuş, 

Neyi yönettiği belli değil. 

Yönetiyorum dediği yer iflas etmiş

Kalmamış üç beş müşterisi

Ona buna hart hurt eder

Tıpkı müdürlükten emekli

Umumi tuvalet bekçisi gibi

			Özcan NEVRES', 'Bu Dünyanın Hali Ne Böyle Ne  olmuş bu dünyanın haline  Ne saygı kalmış nede sevgi İnsancıklar elinde maskara olmuş  Kimi cebinde üç beş kur...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-olmus-bu-dunyanin-haline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Neyim?', 'ben-neyim-mahzuni-serif-wz1mw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünya kainat''tan kopup gelirken

Adem miyim hayvan mıyım? ben neyim? 

Adem ile Havva vücut bulurken

Cennet miyim? Şeytan mıyım? Ben neyim? 

İdris Nebi biçer iken hülleyi

Yüksekten geçerken insanlık payı

Muhnaci aşarken ulu deryayı

Gemi miyim? Kaptan mıyım? Ben neyim? 

Döküldü gazelim çürüdü bağım

Yıllar evvel göçmüş köyüm bucağım

Bugün doğdum varım, yarın da yoğum

Aradaki yalan mıyım? Ben neyim? 

Kimler akıllanmış? Kimler bunamış? 

Eyüp derde düşmüş, cahil kınamış

Mevlam İbrahim’i boşa sınamış

Kasap mıyım? Kurban mıyım? Ben neyim? 

Aramızda yatar eroğlu erler

Erleri ne bilir köroğlu körler

Bana bu ellerde Mahzuni derler

Merdan mıyım? Mervan mıyım? Ben neyim? 

Şaşkınım, düşkünüm, perişanım, ne haldeyim

Arıyorum, soruyorum kendimi, 

Ben kimim? Ben neyim?', 'Dünya kainat''tan kopup gelirken Adem miyim hayvan mıyım? ben neyim?  Adem ile Havva vücut bulurken Cennet miyim? Şeytan mıyım? Ben neyim?  İ...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ben-neyim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Gördüğümde', 'seni-gordugumde-ozcan-nevres-hoegq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SENİ GÖRDÜĞÜMDE

Sahil gazinosunda otururken, 

Gözlerim takıldı gözlerine

Gözlerindeki hüzün, 

Beni götürdü ihanetler dünyasına 

Terk edilmişlik miydi gözlerinde harelenen

Terk edilmenin acısını bilirim

 Kaç kez tattım o acıyı bilemezsin 

Yıkıldı dünyam, altında kaldım. 

Bir enkaz ki, altından kalkamadım

Gözlerin umut verdi, dirildim

Ver elini güzelim tutuşalım el ele 

Gidelim buralardan çok uzaklara

Güneşin batmadığı 

Umutsuzluğun, yitikliğin olmadığı, 

Yeni bir dünya bekliyor bizi

Biraz tez olalım

Dedikoducular, karaçalılar, 

Fırsat bulamasınlar aramızı bozmaya.

			Özcan NEVRES', 'SENİ GÖRDÜĞÜMDE Sahil gazinosunda otururken,  Gözlerim takıldı gözlerine Gözlerindeki hüzün,  Beni götürdü ihanetler dünyasına  Terk edilmiş...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-gordugumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararlar Beni', 'ararlar-beni-mahzuni-serif-6p8ey', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güvenme dünyada malım var diye

Acep insan mıyım sorarlar beni

Halımdan anlamaz cahiller niye

Her biri bir yandan yorarlar beni

Hoşlar meclisine girdim hoşlandım

Aşkın ateşine düştüm haşlandım

Dallarımda meyve döktüm taşlandım

Ya niçin gövdemden kırarlar beni

Döndü gitti Hak yolunu övenler

Pişman olup dizlerini dövenler

Bir lokmaya nice bana sövenler

Ah Mahzuni diye ararlar beni', 'Güvenme dünyada malım var diye Acep insan mıyım sorarlar beni Halımdan anlamaz cahiller niye Her biri bir yandan yorarlar beni Hoşlar meclis...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ararlar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşu Boşuna', 'bosu-bosuna-mahzuni-serif-d5pwg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevlam bana ömür vermiş

Boşu boşuna, boşu boşuna

Bedenime bir can girmiş

Boşu boşuna, boşu boşuna

Gelmişim ben boşu boşuna

İsa Meryeme''mi kaldı? 

Musa asa''dan ne buldu? 

Süleyman bir sultan oldu

Boşu boşuna, boşu boşuna

Saltanatı boşu boşuna

Su akar deryaya varır

Derya damlayı çıkarır

Gökyüzünde yağmur olur

Damlaları boşu boşuna

Yağmur yağar boşu boşuna

Gâhi gittim gahi geldim

Aradım kendimi buldum

Bir Mahzuni Şerif oldum

Boşu boşuna, boşu boşuna

Yaşamışım boşu boşuna', 'Mevlam bana ömür vermiş Boşu boşuna, boşu boşuna Bedenime bir can girmiş Boşu boşuna, boşu boşuna Gelmişim ben boşu boşuna İsa Meryeme''mi ka...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bosu-bosuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşmi Siyahım', 'cesmi-siyahim-mahzuni-serif-pa6hs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte gidiyorum çeşmi siyahım

Önümüze dağlar sıralansa da

Sermayem derdimdir servetim ahım

Karardıkça bahtım karalansa da

Haydi dolaşalım yüce dağlarda

Dost beni bıraktı ah ile zarda

Ötmek istiyorum viran bağlarda

Ayağıma cennet kiralansa da

Bağladım canımı zülfün teline

Sen beni bıraktın elin diline

Güldün Mahzuni''nin berbat haline

Mervan''ın elinde parelense de', 'İşte gidiyorum çeşmi siyahım Önümüze dağlar sıralansa da Sermayem derdimdir servetim ahım Karardıkça bahtım karalansa da Haydi dolaşalım yüc...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cesmi-siyahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz geçecek Ömrü Düşünürüm', 'sensiz-gececek-omru-dusunurum-ozcan-nevres-ubasf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SENSİZ GEÇECEK ÖMRÜ DÜŞÜNÜRÜM

Anılar diken diken tırmalar yüreğimi

Olumsuzluklarla kapılanır tüm umutlarım

Yaşam anlamını kaybeder, ölümü ararım

Sensiz geçecek ömrü düşünürüm, 

Yaşadığıma üzülürüm

Gök yüzünde ışıl ışıl yıldızlar, 

Göz kırptılar, neden yalnızsın dediler.

Denizdeki yakamozlar

 Usumca şekillendiler gönlümde.

Karşıdaki Rodoslulardan kalma kalede, 

Seninle el ele gezdiğimiz, 

O güzel günlerimizi anımsadım yine

İlk kez orada öpmüştüm seni

Yapma diye nasıl da direnmiştin? 

Tırnaklarınla yanağımı çizmiştin

Yanağımdan akan kanı, 

Ağlayarak silmiştin

Yeminler etmiştin, 

Beni senden ölüm ayırır, 

Aşkımız ölümsüz olacak diye

Ağaçlara, kayalara kazımıştık adımızı

Yan yana

Hıçkırıklarla boğulan sesini, 

Kaderin çizdiği yoldan ayrılamayız, 

Kader bizi mahkum etti biri birimize

Dediğin o mutlu günlerimizi, 

Unutamıyorum, unutamıyorum.

Yalanmış ettiğin tüm yeminler.

Sen şimdi bir başkasının koynunda, 

Kim bilir kaçıncı uykudasın? 

Ve mutlusundur da

Bense, 

Yalnızlığımla baş başayım.

Kahrolmuş, umutsuz ve uykusuz.

Gün ışımaya başladı.

Yakamozlar, revnaklar yok oldular.

Yorgun kent uyanıyor yavaş yavaş.

Uyumaya gidiyorum, 

Yitik umutlarım peşimde.

Özcan NEVRES', 'SENSİZ GEÇECEK ÖMRÜ DÜŞÜNÜRÜM Anılar diken diken tırmalar yüreğimi Olumsuzluklarla kapılanır tüm umutlarım Yaşam anlamını kaybeder, ölümü ar...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sensiz-gececek-omru-dusunurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıran Kırana', 'kiran-kirana-mahzuni-serif-yrmcn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürü bre bol mezarlık

Her gün de varan varana

Kahrolası koca dünya

Birbirin kıran kırana

Gayrı çekemem bu nazı

Kış temsil edemez yazı

Kör olmuş insanın gözü

Gerçeği soran sorana

Mahzuni nedir bu zulüm

Kalmadı takatım halim

En sonunda vardır ölüm

Kendini yoran yorana', 'Yürü bre bol mezarlık Her gün de varan varana Kahrolası koca dünya Birbirin kıran kırana Gayrı çekemem bu nazı Kış temsil edemez yazı Kör ol...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiran-kirana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayalar Kadı Olurdu', 'kayalar-kadi-olurdu-mahzuni-serif-gy6we', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kayalar kadı olurdu

Akıllar yaşta olsaydı

Yeşil mezar türkü söyler

Keramet taşta olsaydı

Güle bülbül konar mıydı

Öter öter bunar mıydı

Bahar çiçek sunar mıydı

Kabahat kışta olsaydı

Toprak olur ağa paşa

Gelde şu dünyada yaşa

Düşmezdi gardaş gardaşa

İstanbul muşta olsaydı

Beni gören birşey sanmaz

Dünyayı içenler kanmaz

Mahzuni''nin kalbi yanmaz

Sevdası başta olsaydı', 'Kayalar kadı olurdu Akıllar yaşta olsaydı Yeşil mezar türkü söyler Keramet taşta olsaydı Güle bülbül konar mıydı Öter öter bunar mıydı Bahar...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kayalar-kadi-olurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Demeden', 'elveda-demeden-ozcan-nevres-vqq61', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ELVEDA DEMEDEN

Gidiyorum bu kentten kimseye veda etmeden.

Yine döneceğim bu kente, gönül istemese de.

Bilemesiniz nedir beni bu kente böylesine bağlayan. 

Torun hasretidir bu hiç dayanılmayan. 

İple çekeceğiz yazın gelmesini, 

Bu hasretlik tez bitsin diye.

Yaz günlerinde kavuşacağız biri birimize.

Denize gireceğiz, kumsalda oynayacağız.

Kumdan kaleler yapacağız, eğleneceğiz birlikte.

Denizden çıkıp eve gittiğimizde.

Huysuzlaşacak yine beni gezdir diye.

Elimden tutup arabamızın park edildiği yere, 

İte kaka sürecek beni, gözyaşlarını koz edecek.

Arabamıza binip çalıştırdığımda, 

Göz yaşları dinecek.

Teybi gösterecek, şunu çalıştır diyecek.

İki şarkı arasındaki boşlukta, 

Torpidoyu tekmeleyecek çalışsın diye.

Gece el ele tutuşup yürüyeceğiz.

Trafiğin yasak olduğu aşıklar yolunda 

Özgürlüğüne kavuşacak.

Yalnız koşmanın tadını çıkaracak doyasıya.

Banklardaki aşıkları gösterecek, bak dudak diye.

Esin kaynağımdır banklarda, 

Kumrularcasına sevişen aşıklar. 

Uzun sürecek şiir severlerden ayrılığım.

Harç bitti yapı paydos dercesine.

Elveda demeyeceğim sizlere, 

Sonsuza kadar ayrılışı anlatır bu kelime.

İlham kaynaklarıma kavuşunca yine. 

Merhaba, ben geldim diyeceğim, 

Tüm şiir sevenlere. 

				Özcan Nevres', 'ELVEDA DEMEDEN Gidiyorum bu kentten kimseye veda etmeden. Yine döneceğim bu kente, gönül istemese de. Bilemesiniz nedir beni bu kente böyles...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/elveda-demeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Ulaşabilmek', 'sana-ulasabilmek-ozcan-nevres-56bkh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SANA ULAŞABİLMEK

Aşabilmeliyim engelleri

Ulaşabilmeliyim sana

Ellerini avuçlarıma almalıyım

Ruhumda ürpertiler yaratan

 Üç kelimelik cümleyi

Kulağına fısıldamalıyım

Seni ölesiye seviyorum

Sonra, kollarımı dolamalıyım boynuna

Ben de seni 

Ölesiye seviyorum demelisin

Ölümsüz olmalı aşkımız

Delice sevişmekle geçmeli ömrümüz

Umut güzel şey

Oysa benim umutlarım

 Doruklarda asılı kaldı

Ulaşmak istiyorum

Doruklarda kalan umutlarıma

Ulaşamıyorum

Yabancısıyım artık

Özlemlerimin, umutlarımın

Ve seninle yaşama tutkularımın

				Özcan NEVRES', 'SANA ULAŞABİLMEK Aşabilmeliyim engelleri Ulaşabilmeliyim sana Ellerini avuçlarıma almalıyım Ruhumda ürpertiler yaratan  Üç kelimelik cümleyi...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sana-ulasabilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palmiye Gazinosunda', 'palmiye-gazinosunda-ozcan-nevres-bm6cd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Palmiye Gazinosunda

Ne zaman yolum düşse İzmir’e

Ayaklarım sürükler beni

Palmiye gazinosunun olduğu yere

Hep boş olur oturduğumuz  masa

Sanki bizi beklercesine

Sırtımı dönüyorum tüm masalara

Yitikliğimi yalnızlığımı gizlercesine

Kadehler boşalır peş peşe

Kadehlerden seni içercesine

Sisler oluşur düşüncelerimde

Seni boğmak istercesine

Mutlu olduğumuz günler var ya

Daha dünmüş gibi dizilir gözlerime

Ne ister bu garson böyle 

İkide bir dikilir tepeme

Bir isteğin var mı, ne yersin diye

Bilmez ki ıstırabım meze 

Göz yaşlarım içkiden öte

Anılarım yoldaşım

Bir başka yere yok kaçışım

Bak yine o hüzzam şarkı çalıyor

Yüreğim dağlanıyor içim kararıyor

Ölümüme kefen biçiyorum

Ama sensiz gidemem ki bir yere

Umutla bekliyorum

Belki de gelirsin diye

		Özcan NEVRES

24 Mart 2002', 'Palmiye Gazinosunda Ne zaman yolum düşse İzmir’e Ayaklarım sürükler beni Palmiye gazinosunun olduğu yere Hep boş olur oturduğumuz  masa Sank...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/palmiye-gazinosunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Beni Konuşayım', 'birak-beni-konusayim-mahzuni-serif-v96ng', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bende bir insan oğluyum

Bırak beni konuşayım

Bir başım bir beynim vardır

Bırak beni konuşayım

Düşüneyim, danışayım

Beni öldürüp ağlama

Böyle bulanıp çağlama

Yazık kolumu bağlama

Bırak beni konuşayım

Düşüneyim, danışayım

Senin dilin benim dilim

Yakışmaz insana zulüm

İnsanım hayvan değilim

Bırak beni konuşayım

Konuştukça düşüneyim

Ya sen niçin düşünürsün

Düşündükçe boşanırsın

Halk demeye üşenirsin

Bırak beni konuşayım

Hep gerçeğe ulaşayım

Düşünen cahil olamaz

Cahil kendini bilemez

Can gider fikir ölmez

Bırak beni konuşayım

Cahilliği biz yenelim

Mahzuni halk için ölsün

Ben giderim dostlar kalsın

Koltuk sana sizin olsun

Bırak beni konuşayım

İnsan gibi yaşayayım

Yaşadıkça düşüneyim.', 'Bende bir insan oğluyum Bırak beni konuşayım Bir başım bir beynim vardır Bırak beni konuşayım Düşüneyim, danışayım Beni öldürüp ağlama Böyle...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/birak-beni-konusayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozanın Aşkı', 'ozanin-aski-ozcan-nevres-n445r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni gördüm bugün

Kaldığın pansiyondan çıkıyordun.

Günaydın dedin bana

Gözlerinin içi gülüyordu. 

Arkandan baktım uzun uzun

Gönlümü kapladı yine 

O yokluk denen hüzün. 

Nice yıllar oldu, 

Aşktan sevgiden uzak kaldığım.

Ruhumda dayanılmaz bir arzu

Yıllardır aradığın 

İşte bu diyordu.

Sevmek, sevilmek

Hiç ölmeyen bir tutku.

Nasır tutmuş gönlümde 

Bir fırtına gibi estin. 

Ellerimde 

Ellerini tutmanın

Dayanılmaz arzusu. 

Umutla bekledim seni

Ya gelmezse korkusu

Karabasanlar gibi 

Çöktü gönlüme

Geldin...

Çok eski bir aşkın

Küllenmiş ateşini açarcasına

Arayıp buldun beni

Sımsıcak sevgi dolu yüreğinle

Yaz aşkıydı aramızdaki biliyorum

Yaz yağmuru gibi tez bitecek 

Gün gelecek

Ölesiye arzulayacağım seni

Yokluğun bir kabus gibi 

Çökecek benliğime. 

Hayalimde canlanacak

O gülüşün ve güzelliğin.

Yüzümdeki sımsıcak nefesin

Yokluğun çıldırtacak beni.

		

  			Özcan NEVRES', 'Seni gördüm bugün Kaldığın pansiyondan çıkıyordun. Günaydın dedin bana Gözlerinin içi gülüyordu.  Arkandan baktım uzun uzun Gönlümü kapladı ...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ozanin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamaya Geldim', 'yasamaya-geldim-mahzuni-serif-wmpjm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamaya geldim ben de dünyaya

Elimden kolumdan bağlama beni

Komşular gidiyor yıldız''a ay''a

Dağların başında eğleme beni

Körpecik aklımı kandırma boşa

İnsanlar benzemez beyinsiz kuşa

Avareyim diye etme temaşa

Bir dilim ekmeğe bağlama beni

Mahzuni nedendir geri kaldığım

Hakkın olmayanı çalıp aldığın

Kimse bilmez kimin nasıl olduğun

Hastayım götürün sağlama beni', 'Yaşamaya geldim ben de dünyaya Elimden kolumdan bağlama beni Komşular gidiyor yıldız''a ay''a Dağların başında eğleme beni Körpecik aklımı kan...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasamaya-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur Evindeki Sitem', 'huzur-evindeki-sitem-ozcan-nevres-hpp4d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilseydim bu dünyanın temelinin

Nankörlükler üstünde kurulmuş olduğunu

Ant olsun koymazdım taş taş üstüne 

Ne evliliği düşünürdüm ne de çocuk sahibi olmayı

Ot gibi yaşardım, iz bile bırakmazdım geride

Pişmanlıklar yararsız, dönüş yok geriye

 Bir yılı geride bırakıp yeni yıla girdiğimde bile

Ne aradılar, ne de sordular nasılsın diye

Kuşku duydum, gecenin ilerlemiş saatinde

Doktor, eczane dolaşan ben değil miydim diye

Geçti o günler kaldı çok gerilerde

Korkuyorlardır belki de, onlara muhtaç olurum diye

Korkmasınlar, en çaresiz olduğumda bile

Hiç birine eğilmeyeceğim, son nefesimde bile

				Özcan NEVRES', 'Bilseydim bu dünyanın temelinin Nankörlükler üstünde kurulmuş olduğunu Ant olsun koymazdım taş taş üstüne  Ne evliliği düşünürdüm ne de çocu...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/huzur-evindeki-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karnım Tok Benim', 'karnim-tok-benim-mahzuni-serif-8ow2h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ta ezelden ırgat oğlu ırgatım

Beylik gibi asaletim yok benim

Bulgur yerim su içerim kime ne

İt yalına şükür karnım tok benim

Höllükte büyüdüm, beşikte yattım

Emeksiz şerefi sevene sattım

Zehir zıkkımı memede tattım

Dostlarımdan düşmanlarım çok benim

İliğimden çıkmaz tezek dumanı

Gün oldu aş yaptım çayır çimeni

Çektiğimde kırk yamalı tumanı

Sevgilimdir tüfek benim ok benim

Bir fidan ki kesilince bitmez mi? 

Dallarında nice kuşlar ötmez mi? 

Bir yiğide bir kör ocak yetmez mi? 

Neme gerek kömür benim kok benim

Mahzuni''yi mengeneye germişler

Baş ucuna sorgucuyu dermişler

Ölsün diye bana ceryan vermişler

Zencirimi yakar gider şok benim.', 'Ta ezelden ırgat oğlu ırgatım Beylik gibi asaletim yok benim Bulgur yerim su içerim kime ne İt yalına şükür karnım tok benim Höllükte büyüdü...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karnim-tok-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tılsım', 'tilsim-deniz-kaya-iwqhe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgarın buğulu tılsımı okşasada içimi, 

Gözlerinde kaybolur hüzün nağmeleri, 

Tarifsiz acımasızlar yakar bedenimi, 

Dalar gider gözlerim sonu olmayan sensiz çıkmazlara, 

Unuttuğun derin benlikler sonum olsada elinden, 

hüzünlü bakışlar, manasız çıkmazlar, derin umutlar ve unutulmayan gerçekler, hayal dünyamın vazgeçilmez gayeleri olmuştur.biraz onlarla, biraz denizlerle, birazda can yakan gerçeklerleyim.onlar acımasızca yaksada bedenimi, hayatın çıkmazları hep onlarda saklı...unutmamalıyız ki kötü günlerin sonunda elbet güzel günler başlar!', 'Rüzgarın buğulu tılsımı okşasada içimi,  Gözlerinde kaybolur hüzün nağmeleri,  Tarifsiz acımasızlar yakar bedenimi,  Dalar gider gözlerim so...', ARRAY['Türk Edebiyatı','Şiir','Deniz Kaya']::text[], 8.5, '{"poet":"Deniz Kaya","poet_slug":"deniz-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tilsim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-mahzuni-serif-r8ast', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kader böyle imiş böyle yazılmış

Gidiyorum kara gözlüm ağlama

Mezarımız gurbet ele kazılmış

Gidiyorum dudu dilim ağlama

Ceylan bakışını üzme boşuna

Kurbanlar olayım gözün yaşına

Keder yakışmıyor hilal kaşına

Gidiyorum kara gözlüm ağlama

Emanet eyledim benli kuzumu

Arkalarda koyma benim gözümü

Getir ver çalayım kırık sazımı

Gidiyorum kara gözlüm ağlama

Mahzuni Şerif ''im yollar göründü

Garip başım dertten derde büründü

Fadime''m duvağın yerde süründü

Gidiyorum kara gözlüm ağlama.', 'Kader böyle imiş böyle yazılmış Gidiyorum kara gözlüm ağlama Mezarımız gurbet ele kazılmış Gidiyorum dudu dilim ağlama Ceylan bakışını üzme ...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aglama-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Bahar Yağmurları', 'son-bahar-yagmurlari-ozcan-nevres-kgppf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor ince, ince

Çıkıp yürüyeceğim gönlümce.

Doyasıya ıslanacağım, 

Sensizliğimin ateşini söndürsün diye.

Islak kaldırımlarda yürüyorum, 

Ayaklarımdan çıkan, 

Şap, şap sesleriyle.

Su birikintileri, 

Gümüş renginde parlarken, 

Kamaşan gözlerim seni aradı, 

Bomboş kaldırımların üstünde.

Tek tük insanlar vardı çevremde, 

Benim gibi ıslanmayı göze alan.

Kara bulutlar, 

Kabus gibi çöküyor, 

Dolu, sağanak ne varsa, 

Boca ediyor üstüme.

O tek tük insanlar kaçışıyorlar, 

Daha fazla ıslanmasınlar diye.

Bir ben kaldım kaldırımda, 

Birde etrafımda uçuşan, 

Hazan yaprakları.

Haykırmak istiyorum, 

Eyyy bulut, 

Sağanak, dolu yetmez bana.

Aşk ateşi bu, 

Nasıl anlatayım sana? 

Yetmez bu ateşi söndürmeye

Ne yağmurun, ne dolun.

Şimşekler kör etse gözlerimi, 

Yıldırımlarınla yansa her yanım.

Hiç kalır yanında, 

Şu yüreğimdeki aşk ateşinin.

		Özcan NEVRES', 'Yağmur yağıyor ince, ince Çıkıp yürüyeceğim gönlümce. Doyasıya ıslanacağım,  Sensizliğimin ateşini söndürsün diye. Islak kaldırımlarda yürüy...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/son-bahar-yagmurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-gokhan-oktem-35wzk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tepemde sonsuz akan 

Rengi maviden kızıla çalan

Ve dağınık, pamuk bulutlar üstünde 

Gündüz uykuya yatan

Yıldızlar

Ayaklarımın altında

Biraz çimen

Biraz toprak

Biraz yeşil biraz ıslak

Ve kafi uzakta

Tam göz hizamda 

Biraz nehir biraz orman

Hepsinde biraz eksik 

Hepsinde biraz varım

Çok şükür 

Hala 

Bahtiyarım...

20,05,2002, İstanbul', 'Tepemde sonsuz akan  Rengi maviden kızıla çalan Ve dağınık, pamuk bulutlar üstünde  Gündüz uykuya yatan Yıldızlar Ayaklarımın altında Biraz ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-mustafa-sureyya-sezgin-fi8lz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün güzel masallar

Önce gözlerde başlar.

Sancılanır duygular

Sonra yürek kıpırdar.

Yıldızlanan gözlerle

Nefesler sık solunur.

Kenetlenen ellerle

Adı sevda konulur.

(İstanbul,30.03.1996)', 'Bütün güzel masallar Önce gözlerde başlar. Sancılanır duygular Sonra yürek kıpırdar. Yıldızlanan gözlerle Nefesler sık solunur. Kenetlenen e...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/masal-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kadın...', 'o-kadin-mustafa-sureyya-sezgin-tj5jd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Önce yaşayacağım seni

Gözlerini ve sözlerini, 

İşleyeceğim benliğime.

Prangaya vurup hasreti, 

Yüreğimin taşkınlığından

Buruk tatlar alarak

Bir şiir yazcağım.

Adını, 

'' O kadın '' koyacağım.

(İstanbul,30.03.1996)', 'Önce yaşayacağım seni Gözlerini ve sözlerini,  İşleyeceğim benliğime. Prangaya vurup hasreti,  Yüreğimin taşkınlığından Buruk tatlar alarak ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/o-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancı', 'sanci-mustafa-sureyya-sezgin-2052s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaman bir duygudur sevda.

Büyüterek içinde yalnızlığını

Kıpırdayan her gölgede, 

Savrulursun! ..

Mum gibi titrek umutlarınla

Karanlıkları delmek uğruna, 

Çabaladıkça kahrolursun! ..

Her yüreğin bir sevdası vardır

Ve her sevdanın bir gönül yarası.

Unutmaya çalışmak, 

Bir aldatmacadır ancak.

Sakin duran yüreğin, 

Görünüşte küllenip, 

Bir ele göz ile alevlenip

Ansızın sancılanır geceyarısı! ..

(İstanbul,24.05.1996)', 'Yaman bir duygudur sevda. Büyüterek içinde yalnızlığını Kıpırdayan her gölgede,  Savrulursun! .. Mum gibi titrek umutlarınla Karanlıkları de...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sanci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoluğunda', 'yolugunda-ozcan-nevres-2sj6w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluğunda

Geceleri ayaz olur kış ayları

Sensiz yattığım yatak inadına soğuk

Hayaline sarılmak istesem de

Hayalin yatağımdan da soğuk

Uykusuzluk yine uykusuzluk

Olmayan sürülerimin koyunlarını 

Denizdeki martıları saydım bir bir

Hesap tutmadı uyuyamadım

Sabahın ilk ışıklarında

Başımı alıp düşsem yollara

Yoldaş olsam yoldaki yayalara

İhanetini anlatsam onlara

Halimden anlayan olur mu

Gülüp geçerler mi bilmiyorum

İyisi mi gitmeliyim salaş bir meyhaneye

Meyhanenin alkol kokan buğulu havasında

Tüm umutlarımı boğmalıyım

Seninle birlikte 

	  Özcan Nevres

19 Ocak 2002  SİLİVRİ', 'Yokluğunda Geceleri ayaz olur kış ayları Sensiz yattığım yatak inadına soğuk Hayaline sarılmak istesem de Hayalin yatağımdan da soğuk Uykusu...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yolugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-ozcan-nevres-igh6t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YOLLAR

Uzayıp giden yollar

Kimi sevgilileri kavuşturan

Kimi de sevenleri ayıran yollar

Bilinmeze uzanan dönemeçli yollar

Üzerinde ölümüne yarışılan

En acı ölümlere neden olan yollar

Trafik magandası sollamış önündeki aracı

Karşıdan gelenler için ne kadar acı

Yok olup gitmek zekası kıt biri yüzünden

Sen mi yarattın onları 

A soysuzun soysuzu

Yaşamaktı elbette onların da arzusu 

			Özcan Nevres

7 Aralık 2001', 'YOLLAR Uzayıp giden yollar Kimi sevgilileri kavuşturan Kimi de sevenleri ayıran yollar Bilinmeze uzanan dönemeçli yollar Üzerinde ölümüne ya...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yollar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözülüş', 'cozulus-mustafa-sureyya-sezgin-vxjw8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', ''' Aman... aman... sakın! .. '' deme bana; 

Mutlu edecekse seni bundan sonra, 

Artık şiirler yazmayacağım sana.

Susamışken sevgiye ve umuda, 

Gözlerinin derinliklerine dalmayacağım, 

Omuzlarına bir yük ise eğer, 

Hatırını bile sormayacağım! ..

Öğretemediysem sana bunca zaman

Gülümsemeyi ve sevmeyi, 

'' Seviyorum! .. '' diyebilmeyi, 

Bir daha adını anmayacağım! ..

(İstanbul,24.05.1996)', ''' Aman... aman... sakın! .. '' deme bana;  Mutlu edecekse seni bundan sonra,  Artık şiirler yazmayacağım sana. Susamışken sevgiye ve umuda,  ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cozulus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit ateşi', 'kibrit-atesi-mustafa-ozke-0ja9g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sensizlik bir barut gibi kuduruyor içimde 

bir kibrit ateşine saklan da gel ne olur 

içimdeki barutu patlat aniden 

kavuşmak varsa kaderde yeniden', 'sensizlik bir barut gibi kuduruyor içimde  bir kibrit ateşine saklan da gel ne olur  içimdeki barutu patlat aniden  kavuşmak varsa kaderde y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kibrit-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Mavim', 'deli-mavim-erol-sen-nk4oi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalp kırık yürek buruk

Masmavi gözlerde umutsuzluk

Neden solgun yüzün? neden bu mutsuzluk? 

Hayat senin deli mavim yeter bu kırgınlık

Sevgi sevene sunulur

Göz yaşları aşk için akıtılır

İhanet affedilmez herkesce bilinir

Sevgine sahip çık deli mavim

Deniz mavisi gözlerde hüzün olmasın

Yüreğin sevgiyle dolsun

Ömrün uzun gönlün bol olsun

Sen sevgiyi hak edensin deli mavim

Değmeyenlere isyan etmek niye

Seviyorsa gönlün sevsin kime ne

Delice sevmek, derinden sevmek sende

Hayat senin deli mavim sev gönlünce

Boşver mutsuzluğu, umutsuzluğu

Güldür yüzünü, doldur gönlünü

Mavi gözlerin aşk ile parlasın pırıl pırıl

Biliyorum deli mavim gülmek sana yakışır...

19.05.2002', 'Kalp kırık yürek buruk Masmavi gözlerde umutsuzluk Neden solgun yüzün? neden bu mutsuzluk?  Hayat senin deli mavim yeter bu kırgınlık Sevgi ...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/deli-mavim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-erol-sen-bwk5s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlık acısını kadehlerde aramak niye

İçtikçe dertler bitecekmi sence? 

Güne gün eklenir çileler çekilir

Sevgiye duyulan özlem bitermi söyle

Seviyorsan sevgine sahip çıkacaksın

Teselliyi geçmişte aramayacaksın

Aşkını, gururunu, gönlünü, ömrünü

Sevgiliye adayıp mutlu olacaksın

Bitti diyorsun biten nedir ki? 

Sonlar sözcüklerde saklı, gönül dinlemez ki

Boşa acı çekme haykır sevgini

Sevgiliye sevgini söylemek le dil aşınmaz ki

Ela gözlerde buldun mutluluğu

Onunla tattın doyumsuz aşkını

Bu inat, bu nefret, bu gurur neden

Seviyorsun işte saklama aşkını söyle...

20.05.2002', 'Yalnızlık acısını kadehlerde aramak niye İçtikçe dertler bitecekmi sence?  Güne gün eklenir çileler çekilir Sevgiye duyulan özlem bitermi sö...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nasihat-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzakta ki Sevgiliye', 'uzakta-ki-sevgiliye-erol-sen-eptc6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yollar uzak olsa da kalbim hep seninle

Varlığını hissetmek seni sevmek bence

Ömrüm seni beklemekle geçse bile

Seni sevmekten vazgeçmeyeceğim

Aramızda engeller olsa bile

Kalbimizdeki aşk ateşi hiç sönmeyecek

Ellerim ellerinde, gözlerin gözlerimde olmasa bile

Bu garip gönlüm seni hep sevecek

Yıllar geçse ümitler tükense

Ayrılık acısı gönlüme çökse

Saçlarda aklar, gözlerde yaşlar

Seni bana getirecek biliyorum yıllar

Aşk bir yalan, sevgi mühim olan

Sen de buldum sevgiyi ben inan

Sensizlik acısı sardı tüm benliğimi

Seni çok sevdiğimi bilmelisin sevgili...

21.05.2002', 'Yollar uzak olsa da kalbim hep seninle Varlığını hissetmek seni sevmek bence Ömrüm seni beklemekle geçse bile Seni sevmekten vazgeçmeyeceğim...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uzakta-ki-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama...', 'babama-ozhan-hakan-f1zup', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adını yazmadım senden sonra, 

yangınından kaçırıp gözlerimi 

resmine hiç bakmadım. 

Her sabah 

yokluğunla ıslanan saçlarımı okşadım 

şefkatine özenip... 

Senin kıyılarından 

yelkenlerime üfleyerek açıldım 

umutsuzca 

umut deryasına. 

Adını yazmadım senden sonra 

resmine hiç bakmadım. 

takvimler şaşırdı senden sonra

büyümedi hiç bir umut

ben de büyümedim gittiğinden beri

bak bıraktığın yaştayım hala

yine de hayatın uzağındayım artık 

ve bir hayat uzağındayım. 

Ondandır küreklerine hiç asılmadım hayatın 

bir dalga beni atar diye kıyılarına. 

Adını yazmadım senden sonra 

resmine hiç bakmadım... 

dost eli puşt eline karıştı baba

sancılar birikti bak avuçlarımda

oysa

''yaşlı bir sevgilim bile olmadı göğsünde ağlamak için'' 

ve hiç bir yaşım olmadı

ıslak yaş günlerimde

yazgım hüzün güzergahı baba...

Adını yazmadım senden sonra 

resmine hiç bakmadım...

Korkarım...Sana gecikmekten, 

Korkarım... 

Sensiz bir gün daha yaşayabileceğimden 

ve korkumu unutmak için 

türküler söyler, 

Kürtçe ağlarım. 

Ama acı, 

her dilde aynı tadı veriyor korkarım... 

Hüzünler biriktirir, 

gizli gizli ağlarım. 

Hayat beni -ağ-lar... 

Hayat beni bağlar baba

Hayat beni avlar.....korkarım....

bak bıraktığın yaştayım hala

yol yordam acemisi

saklanır yastığıma

gelemezdim ardından

çocuktum... o yolları bilmezdim.....

... korkarım baba...

Gittiğine değil, 

beni de götürmediğine ağlarım... 

21.05.2002 

*Babamın ölümünün 13.yılı anısına...', 'Adını yazmadım senden sonra,  yangınından kaçırıp gözlerimi  resmine hiç bakmadım.  Her sabah  yokluğunla ıslanan saçlarımı okşadım  şefkati...', ARRAY['Türk Edebiyatı','Şiir','Özhan Hakan']::text[], 8.5, '{"poet":"Özhan Hakan","poet_slug":"ozhan-hakan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/babama-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-caner-caylak-5glv7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nerede kaldı fırtına

yabancılaştı insanlar

delilik  düştü aklıma

güller zamansız açtılar', 'nerede kaldı fırtına yabancılaştı insanlar delilik  düştü aklıma güller zamansız açtılar...', ARRAY['Türk Edebiyatı','Şiir','Caner Çaylak']::text[], 8.5, '{"poet":"Caner Çaylak","poet_slug":"caner-caylak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/firtina-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Denizsin ki', 'oyle-bir-denizsin-ki-mustafa-ozke-3agwf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'öyle bir denizsin ki 

tuzun dudaklarımı kavuruyor 

kanım damarıma sığmıyor 

gözlerimi yakıyor dalgaların 

yakamozların gönlümü avutuyor 

bedenim derinlere dalıyor 

daldıkça deniz beni içine alıyor 

geriye bana ölmek kalıyor 

istemem 

cesedim sürüklenmesin sahile', 'öyle bir denizsin ki  tuzun dudaklarımı kavuruyor  kanım damarıma sığmıyor  gözlerimi yakıyor dalgaların  yakamozların gönlümü avutuyor  bed...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oyle-bir-denizsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek Kokan Ceset', 'cicek-kokan-ceset-atilgan-alemdar-83hta', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ölümü zamansız gelince

mükâfatı çiçek kokmak oldu

ellerinin içinde yalnızlığıyla

karanlıkta bulunan bir cesetin

suçlanacak kadar anlamlı

cezalandırılacak kadar kahpe

terkedilecek kadar kendisinin

değildi o kız

o kızda bir çiçek vardı

eşsiz, uyku uyanıklık arası

çocuğa sadece bir isyandı

yalnızlık makamında yansıyan

``suçlanacak kadar anlamlı

  cezalandırılacak kadar kahpe

  terkedilecek kadar benim

  değilsin``

yaşadı yıllarca, yaşamaktan çok

renksiz ve kokusuz gezindi durdu

sonunda bir karanlığa

çiçek gibi açtı, kendi gibi soldu 

ölümü zamansız gelince

mükâfatı çiçek kokmak oldu

ellerinin içinde yalnızlığıyla

karanlıkta bulunan bir cesetin', 'ölümü zamansız gelince mükâfatı çiçek kokmak oldu ellerinin içinde yalnızlığıyla karanlıkta bulunan bir cesetin suçlanacak kadar anlamlı cez...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cicek-kokan-ceset-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amerika Katil', 'amerika-katil-mahzuni-serif-9uumd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün insanlık adına

Amerika katil katil

Kanun yapar kendi teper

Amerika katil katil

Vietnam''ın suçu nedir? 

Hür yaşamak ayıp mıdır? 

Atom patlat ister kudur? 

Amerika katil katil

Türk Milleti Türk Milleti

Nerden gelmiş elin iti? 

Bu gidişin sonu kötü

Amerika katil katil

Birgün gramlar bir olur

Kilodan hakkını alır

Zalim olan bela bulur

Amerika katil katil

Mahzuni Şerif uyuma

Gün geldi çattı akşama

Bizden selam Vietnam''a

Amerika katil katil', 'Bütün insanlık adına Amerika katil katil Kanun yapar kendi teper Amerika katil katil Vietnam''ın suçu nedir?  Hür yaşamak ayıp mıdır?  Atom p...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/amerika-katil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döğüşmeyin Yiğitler', 'dogusmeyin-yigitler-mahzuni-serif-ean0h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşa doğüşmeyin bizim yiğitler

Sizi vurduranlar vurulmuyor ki

Kim bilir nerde hangi koltukta

Kömürde tarlada yorulmuyor ki

Aynı baba dölü ölen öldüren

Ölenle öldüren iti güldüren

Yokmu idi bunu size bildiren

Vur diyenler burda görülmüyor ki

İşçiyi işçiye düşüren zalım

Boynumuzda boza pişiren zalım

Bu kadar bardağı  taşıran zalım

Gözümüz önüne serilmiyor ki 

Yeni adı çıkmış sağ ile sol''un

Tarihte borcu yok kullara kulun

İki yanı birdir yattığın çulun

Bilirsin ölenler dirilmiyor ki

Mahzuni der nedir hak''kın davası

İnsana benzer mi köpek mayası

Ah tükenip bitsin sınıf kavgası

Sınıfsız bir okul kurulmuyor ki.', 'Boşa doğüşmeyin bizim yiğitler Sizi vurduranlar vurulmuyor ki Kim bilir nerde hangi koltukta Kömürde tarlada yorulmuyor ki Aynı baba dölü öl...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dogusmeyin-yigitler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar', 'bir-zamanlar-hakan-akyurt-mc160', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar duygusaldım bende sizin gibi, 

Sevdiğim bir kız, bir kafe ve şarkılar vardı..

Yaşım onsekiz, ondokuz belkide yirmi idi.

Liseden üniversite''ye geçen bir gençtim; 

Bende sizin gibi.... 

Bir zamanlar duygusaldım bende sizin gibi, 

Gülerken içten, ağlarken içten, severken gönülden severdim.

Zaman alıyordu sanki içimdeki tüm güzellikleri, 

Umutsuzca yalan dünya''ya alışan bir genç oldum; 

Bende sizin gibi....

Bir zamanlar duygusaldım bende sizin gibi, 

Artık ne gönülden sevdiğim bir kız, ne de bir kafe kaldı.

İçtenlikle gülmeyi, ağlamayı ve sevmeyi unuttum.

Ben ve şarkılar kaldı gençlikten geriye, tıpkı tüm; 

Anne ve babalar gibi....', 'Bir zamanlar duygusaldım bende sizin gibi,  Sevdiğim bir kız, bir kafe ve şarkılar vardı.. Yaşım onsekiz, ondokuz belkide yirmi idi. Liseden...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-zamanlar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yolculuk', 'son-yolculuk-kursat-demir-3emt8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazar arabalarının

Kontaklarına bağlıdır

Emperyalizmin yıldızları...

Ve son yolculuklarında

Aynı cadde üzerinde

En az beş Mc Donalds''ın önünden geçer; 

Bayraklarından kurtulan tek yıldıza

Ayın eşlik ettiği

Tabutları..!', 'Yazar arabalarının Kontaklarına bağlıdır Emperyalizmin yıldızları... Ve son yolculuklarında Aynı cadde üzerinde En az beş Mc Donalds''ın önün...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Demir']::text[], 8.5, '{"poet":"Kürşat Demir","poet_slug":"kursat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/son-yolculuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Petrol', 'petrol-kursat-demir-003k9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ortadoğu''da

Kimi meydanlar da

Üzerine benzin dökülüp

Yakıldıkça Amerikan bayrağı, 

Sinirden çılgına dönüyordur

Amerikalılar...

Eee kolay değil, 

Hazır petrol

Göz göre göre

Ziyan oluyor...', 'Ortadoğu''da Kimi meydanlar da Üzerine benzin dökülüp Yakıldıkça Amerikan bayrağı,  Sinirden çılgına dönüyordur Amerikalılar... Eee kolay değ...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Demir']::text[], 8.5, '{"poet":"Kürşat Demir","poet_slug":"kursat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/petrol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemedim Dilencileri', 'sevemedim-dilencileri-kursat-demir-55czl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öğrenciyken

Hiç sevmedim dilencileri...

Tamamlanamamış kitaplarıyla

Karanfil''de yürürken bir öğrenci, 

Allah sevdiğine kavuştursun diyerek

Duygularını sömürmelerini...

Öğrenciyken

Hiç sevemedim dilencileri...

Yokluklara ve

YÖKlüklere rağmen okuyan

Bütün gençler gibi..!', 'Öğrenciyken Hiç sevmedim dilencileri... Tamamlanamamış kitaplarıyla Karanfil''de yürürken bir öğrenci,  Allah sevdiğine kavuştursun diyerek D...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Demir']::text[], 8.5, '{"poet":"Kürşat Demir","poet_slug":"kursat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevemedim-dilencileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahlaksız Gençler', 'ahlaksiz-gencler-kursat-demir-d8p1w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şans getirmesi için

Keçiören''in boynuna asılan

Büyük bir at nalıdır

Fatih Caddesi...

İlk kez bir kızı öptüğüm günü hatırlıyorum da

Nasıl da yardım ve yataklık yapmıştın bize

Bir kez olsun titremeden.

Kuytu köşelerinde öpüşen

Liseli Aşıklarına

Ahlaksız gençler olarak bakılsada artık, 

Çocukluğuma ait 

Hayat dolu bir aşk türküsüsün

Keçiören...

Sahi ahlaksızlık mıdır öpüşmek? 

Yok canım...

Birbirinin itfaiyesidir çünkü sevgililer.

Öpüşmeler; 

Birbiri için alevlenen iki yüreğin

Dudaklarını ıslatarak

Yangın söndürme çalışmalarıdır

Bir aşkın...

Kusura bakmayın ama

Ahlaksız gençleri çoğaldıkça

Güvercinlerinin kanat seslerinden

Aşk melodileri yükselir

Bu ülkenin...', 'Şans getirmesi için Keçiören''in boynuna asılan Büyük bir at nalıdır Fatih Caddesi... İlk kez bir kızı öptüğüm günü hatırlıyorum da Nasıl da ...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Demir']::text[], 8.5, '{"poet":"Kürşat Demir","poet_slug":"kursat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ahlaksiz-gencler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faili Meçhul Sabahlar', 'faili-mechul-sabahlar-kursat-demir-8avoq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben hiçbir zaman basılmayacak

Kitaplar biriktirdim

Senin gibilerin

Düşlerime yaptığı işgaller sonucu oluşan...

Ve hepsinin sayfalarına

Yüzlerce ayraç bıraktım

Bulamıyorum çünkü

Hangi aşkın nerede kaldığını...

Yazmaya başladım sayende

Belki birgün senli bir sabahta

Uyanmak ümidiyle...

Örneklerde de görüldüğü gibi

Yazı yazanlar

Faili meçhul sabahlar da uyanırmış

Akdenize Bir Kısrak Başı Gibi Uzanan

Memleketimde...', 'Ben hiçbir zaman basılmayacak Kitaplar biriktirdim Senin gibilerin Düşlerime yaptığı işgaller sonucu oluşan... Ve hepsinin sayfalarına Yüzle...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Demir']::text[], 8.5, '{"poet":"Kürşat Demir","poet_slug":"kursat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/faili-mechul-sabahlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Ertesinde', 'sensizlik-ertesinde-mine-ozdemirtas-mr6dr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sabah ektiğin çiçeklerdeyim.

Yastığın yorganın..buruşmuş çarşafın

Demini almış diyerek içtiğin çaydayım.

Mektubum, şiirim...kalemim, tuşlarım

Sana çıkan uzun kısa her yoldayım.

Uzat elini tut saçlarımdan

Dile ne dilersen...seninim diyen

Senin kadınından.

Yanıbaşımda ol..nefesin nefesimde

Ve UNUTMA.......ektiğin çiçekleri sula

Sulaki sana çiçek vereyim 4 mevsimde

Adını andıkça çırpınmada yürek

Esaret altında sürünerek.

İnliyorum. Gittikçe büyüyen özlemlerin kafesinde. 

Bilmelisin ki; yokluğunu sevmiyorum

Sensizlik ertesinde.', 'Bu sabah ektiğin çiçeklerdeyim. Yastığın yorganın..buruşmuş çarşafın Demini almış diyerek içtiğin çaydayım. Mektubum, şiirim...kalemim, tuşl...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizlik-ertesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğin Moruna Siyah Benekler Konduruyorum', 'sensizligin-moruna-siyah-benekler-konduruyorum-mine-ozdemirtas-ca2ky', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karapus.......oturmuşum yokluğunun üstüne 

Sensizliğin moruna; siyah benekler konduruyorum 

Sonbahar döndü dolaştı yine geldi.

Yapraklar sararıyor ve heyecanlar soluyor işte. 

Yarınları bugünden eskitiyoruz biliyorsun. 

Kayıyor ellerimizden, biz oluşumuz 

Bugün; dünden daha çok değil mi ayrı kalışımız? 

Ve......yarından daha büyük özlemimiz 

Sen; köşende hüznü şekillendirirken 

Ben... senin şekillerini isimlendiriyorum 

Oyalanıyoruz işte.....gözlerimiz kapalı.

Kımıldamaya korkuyoruz ama görmelerdeyiz 

Duyuyorum, bir yerlerde ziller çalıyor.

Ve senin de duyduğunu biliyorum.

Artık nefes nefese değiliz.Çünkü inmelerdeyiz 

Bitiyor mu? .......demeye; varmıyor dilim 

Sevdasızlığından korkuyorum.

Karapus oturmuşum yokluğunun üstüne 

Kaçınılmaz sonu; Siyaha boyuyorum...', 'Karapus.......oturmuşum yokluğunun üstüne  Sensizliğin moruna; siyah benekler konduruyorum  Sonbahar döndü dolaştı yine geldi. Yapraklar sar...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sensizligin-moruna-siyah-benekler-konduruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pembeden Griye... Dönüyor Düşlerim', 'pembeden-griye-donuyor-duslerim-mine-ozdemirtas-zuvaw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nicedir; ''ben'' yok ya ortalarda 

Günleri kovalarken gecelerim; 

Uyuştu kamaştı hissetmiyor, 

Zamana tutunan ellerim. 

Nicedir; ''ben'' yok ya ortalarda 

Kekeleyip dururken hecelerim; 

Rüzgar dalga fırtına derken, 

Suya iniyor gibi yelkenlerim.

Nicedir; ''ben'' yok ya ortalarda 

Paslanıp küflenirken zincirlerim; 

Siyah beyaza küsüyor, 

Pembeden griye......... dönüyor düşlerim', 'Nicedir; ''ben'' yok ya ortalarda  Günleri kovalarken gecelerim;  Uyuştu kamaştı hissetmiyor,  Zamana tutunan ellerim.  Nicedir; ''ben'' yok ya ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pembeden-griye-donuyor-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babakale Akşamları 1', 'babakale-aksamlari-1-zeki-ergin-7bvr1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '___Babakalelilere sevgilerimle

Bababurnunda

gün suya düşerken

döner balıkçılar balıklarıyla limana

akşamcıların

ikinci kadehlerine yetiştirir

her çeşidinden

dönerken balıkçılar limana

ikinci kadehler kalkar

sevgiden

sevdadan 

ve dostluktan yana

poyraz poyraz eser yürekler

zeytin zeytin bakarsın

gün oralara yaslanırken

alıp başını gidemezsin

sevdam sevdana yaslanırken

kırçiçekleri süslüyor masamı

bu akşam

türküler süslüyor soframı

binlerce yılın zenginliği

Anadolu sevdam süslüyor

yüreğimi

_babakale ara02

_sevgiliye isyan yt:haz04', '___Babakalelilere sevgilerimle Bababurnunda gün suya düşerken döner balıkçılar balıklarıyla limana akşamcıların ikinci kadehlerine yetiştiri...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/babakale-aksamlari-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Kulem''e Giderken', 'kiz-kulem-e-giderken-cigdem-simsek-u677y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dümeni kırık, kedi gemimdeyim.

Rotam Kız Kulesi...

Yol alıyorum.

Düşünsene hafif  bir rüzgarda saçlarım karışıyor.

Çekilmekte olan güneş, 

Yavaş yavaş martılara veda ediyor.

Tek tek ışıkları yanmaya başlayan evlerde, 

Kim bilir ne telaşlar var.

Belki biraz üşüyeceğim

Olsun yüreğimdeki ateş, 

Yeniden yeniden ısıtır beni.

Boğaza söyle bir bakacağım ve

Gözlerimi Kız Kulemden hiç ayırmayacağım

Tüm boğazın buğusu üzerini kaplamış, 

Sanki Kız Kulem duvağını takmış gelin oluyor.

Git gide ona yaklaşmak, 

Her ayrıntısını kaçırmadan içime işlemek, 

Bana göre sanatların en güzeli...

Daha sonrasını yazmak benim için düş ötesi.

Kız Kulemle karşı karşıya, göz göze olmak

Dokunmadan, sadece hissetmek, 

Çıkarsızca sevmek...

Onu uzaktan sevmek.

Bana göre aşkların en güzeli...', 'Dümeni kırık, kedi gemimdeyim. Rotam Kız Kulesi... Yol alıyorum. Düşünsene hafif  bir rüzgarda saçlarım karışıyor. Çekilmekte olan güneş,  Y...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kiz-kulem-e-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen miydin?', 'sen-miydin-cigdem-simsek-6uay6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen miydin? İçime usulca sokulan

Sessizce kanımda dolaşan...

Hayatım, nefesim, ışığım

Sen miydin? Çukurlarla dolu yolda

Elimden tutan...

Sen miydin? Karanlıkta gözlerime

Nur olan...

Sen miydin? Boş hayat telaşımda

Amacım olan...

Sen miydin? Her elveda deyip gidişinde

Yeni günle birlikte tekrar merhaba diyebildiğim...

Sen miydin? Yapayalnız kaldığımda

Hasretle koşup sarılabildiğim...

Sen miydin? Yanlışlarımda bile

Doğru olup gelen...

Sen miydin? Başımı omzuna yaslayıp da

Ağlayabildiğim...', 'Sen miydin? İçime usulca sokulan Sessizce kanımda dolaşan... Hayatım, nefesim, ışığım Sen miydin? Çukurlarla dolu yolda Elimden tutan... Sen...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-miydin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçende Bir Gül Olayım', 'bahcende-bir-gul-olayim-cigdem-simsek-onn1c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kadar zor mu sevmek, inanmak? 

Bir demet sevgi alamaz mıyım senden

Bahçelerin benimken.

Güllerin en kırmızısını koklamışken

Hele hele o gülleri dermişken...

Soldurmasak olmaz mı? 

Taze bir gül durur ya bahçede

Yaprakları öylesine diri.

Beni sadece sen seyreyle, sen kokla

İçine çeke çeke kokla

Tut nefesini, hep ciğerinde içinde kalayım.

Öfkenle bir solukta atma beni içinden

O zaman ben de sıradan bir gül, 

Solgun; goncaya çıkmamış bir gül olurum.

İzin ver de sana tomurcuklanayım, 

Aşkımın ilk baharında.

Kara kışları görmeden, 

Senin topraklarında filizleneyim, 

Kök salayım içine, derinden derine...', 'Bu kadar zor mu sevmek, inanmak?  Bir demet sevgi alamaz mıyım senden Bahçelerin benimken. Güllerin en kırmızısını koklamışken Hele hele o g...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bahcende-bir-gul-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-cigdem-simsek-v8f51', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir Kardelen çiçeğiyim

Bağımsız tek başıma

Tertemiz karların içinde, mutlu...

Diğer çiçekler baharda açarken gözlerini, 

Ben soğukla sevişiyorum.

Yüksek dağ yamaçlarını süslüyorum.

Erişilmesi, görülmesi güç.

Her zaman gökyüzüne yakın

Dallarım ruhumla dalgalanıyor

Kimselere dokunmadan

Ben bir Kardelen çiçeğiyim

Beyaz ve özgür

Ta ki yaz gelip de  karlarım eriyinceye dek 

O zaman yavaş yavaş ölüyorum...', 'Ben bir Kardelen çiçeğiyim Bağımsız tek başıma Tertemiz karların içinde, mutlu... Diğer çiçekler baharda açarken gözlerini,  Ben soğukla sev...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kardelen-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibiyim', 'gibiyim-cigdem-simsek-fm1kz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzaktan sana bakıyorum

Ellerimi uzatsam, 

Avuçlarıma alacakmış gibiyim.

Biraz daha yaklaşıyorum, 

Bir çırpıda çıkacak gibiyim.

Yanına vardığımda; 

Ne zor, ne büyüksün.

Sana ulaşamayacakmış gibiyim.

Sen kalbimin en yüksek dağısın.

Ne olur karlı yamaçlarında, 

Bu küçücük KARDELEN’ e de bir yer ver

Senden başka dağda yaşayamayacak gibiyim.', 'Uzaktan sana bakıyorum Ellerimi uzatsam,  Avuçlarıma alacakmış gibiyim. Biraz daha yaklaşıyorum,  Bir çırpıda çıkacak gibiyim. Yanına vardığ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gibiyim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir misiniz?', 'bilir-misiniz-cigdem-simsek-ka7t7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elinde sönmüş bir mumla karanlıkta oturmak, 

Yanan bir şöminenin karşısında üşümek, 

Nasıldır bilir misiniz? 

İçim kan ağlarken; 

İnsanların karşımda gülüşlerini seyretmek, 

Nasıldır bilir misiniz? 

Ben ki! Donuk ve ilgisiz kapkara dünyamda

Doğanın renklerini düşünüyorum.

Görmeden hayal etmek

Nasıldır bilir misiniz? 

Karanlığım mutsuzluğumdan, 

Üşümem ilgisizliktendir.

Taa ki sen ellerinde bir demet aşk çiçekleri ile, 

gönül kapıma gelinceye dek.

İnsanın sevgiyle sarılması, 

Arzuyla öpülmesi

Ne güzel şeymiş bilir misiniz?', 'Elinde sönmüş bir mumla karanlıkta oturmak,  Yanan bir şöminenin karşısında üşümek,  Nasıldır bilir misiniz?  İçim kan ağlarken;  İnsanların...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilir-misiniz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadakat', 'sadakat-cigdem-simsek-02j8w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim kalıplarıma uymaz

Uzun gelir harfleri

Ben deli dolu, yaramaz bir kızım

Çılgın fikirli, haylazım

Sadakat; bağlamaz beni

Kim bu zamana kadar, 

Birine körü körüne sadık kalmış ki! 

Geç bunları geç...

İnsana tek sadık olan gölgesidir.

Ama hayır o bile geceleri aldatır bizi

Karanlığın soğuk kollarıyla.

Sadakat; zor gelir bana... 

Uyamam kurallarına

Ben özgür ve kavramsızım

Keyifli oyuncaklarım hep insanlar oldu

Sıkılmadan oynadım onlarla.

Bir gün de Tanrı oynadı benimle

Bir sevgi tohumu attı içime, 

Apansız büyüdü.

Tanıdıkça onu; sadakatin ne anlama geldiğini öğrendim

Sevgiyle eş değermiş.

Sadece sevgisine değil, ona da sadığım.

Ben artık akıllı, uslu ve bağlı biriyim.', 'Benim kalıplarıma uymaz Uzun gelir harfleri Ben deli dolu, yaramaz bir kızım Çılgın fikirli, haylazım Sadakat; bağlamaz beni Kim bu zamana k...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sadakat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alaca Karanlık', 'alaca-karanlik-cigdem-simsek-jjjzf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alaca karanlık vakti

Zor zaman geldi çattı

Kıyametler kopacak

En körpe, en hain gönüllerde

Gizem, ihanet ve yalan kardeş oldular

Zor geçinen ama ayrılmayan

Şafak söküyor...

Yalan ve kara yüzleri aydınlatmak için

Zaman duruyor bulutların arasında

Koş yakala mavilikleri, 

Nafile...

Yine de alaca karanlık vakti.', 'Alaca karanlık vakti Zor zaman geldi çattı Kıyametler kopacak En körpe, en hain gönüllerde Gizem, ihanet ve yalan kardeş oldular Zor geçinen...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alaca-karanlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hain Kader', 'hain-kader-cigdem-simsek-b0r8p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden? Soruyorum neden? 

Neden bende sevdiğimle sevilmedim? 

Aşk tacını gönüllü ellerle giymedim.

Soruyorum sana hain kader; 

Niçin beni gaddar kalplerin zindanlarına attın? 

Çirkin kelimelerin noktasıyım...

Oysa ki ben...! 

En güzel, en temiz sözcükleri, 

En canlı renkleri ifade etmek isterdim.

Yemyeşil ağaçların yapraklarından süzülen, 

Yağmur damlacıkları olmak isterdim.

Baharda topraktan fışkıran narin bir filiz olup, 

Sonrada güneş ve su olup

Sevgim ile onu büyütmek isterdim.

Evet hain kader...! 

Sayende şimdi bir avuç gökyüzüne muhtaç

Ziftli zindanlarında çürüyorum...', 'Neden? Soruyorum neden?  Neden bende sevdiğimle sevilmedim?  Aşk tacını gönüllü ellerle giymedim. Soruyorum sana hain kader;  Niçin beni gad...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hain-kader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Sen', 'sadece-sen-cigdem-simsek-jwz42', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen çıkışımdın; 

Bu mutsuz, bu gereksiz yoldan.

Sen ışığımdın; 

Bu köhne, bu loş batağımdan.

Sen ellerimdin; 

Saçlarını okşadığım, belini doladığım, 

Sen kanımdın; 

Damarlarımda dolaşan, bana hayat veren.

Sevincim, hayalim, umudum sendin

Sadece sen! ! ! 

Kalbimde taze kanayan bin güldün

Gözümün ışığı, sevgimin acısıydın

Artık mahvoluş nedenimsin

Hayata küsme nedenimsin 

Sadece SEN! ! !', 'Sen çıkışımdın;  Bu mutsuz, bu gereksiz yoldan. Sen ışığımdın;  Bu köhne, bu loş batağımdan. Sen ellerimdin;  Saçlarını okşadığım, belini do...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sadece-sen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalim Aşkın', 'hayalim-askin-cigdem-simsek-mh4v0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgin sonsuzluğun ışığı.

Bir demet çiçek bahçelerimde, 

Bir hece dudaklarımda, 

Bir damla yaş gözlerimde, 

Tatlı bir ürperti tenimde, 

Yaşanamadı sözler buğulu gözlerde, 

Garip bir düş rüyalarımda, 

Baş kaldırışım özgürlüğümde.

Dalgınlığım yollarına.

Ellerim sonsuzluğa, 

Ben sana muhtacım.', 'Sevgin sonsuzluğun ışığı. Bir demet çiçek bahçelerimde,  Bir hece dudaklarımda,  Bir damla yaş gözlerimde,  Tatlı bir ürperti tenimde,  Yaşa...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayalim-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek', 'bir-tek-cigdem-simsek-52ys3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Giderken...

Çantama ilk ismini koydum.

Sonra anıları toparlayıp yerleştirdim.

Alamadığım bir tek sesin vardı duvarlarda, 

Silemediğim bir tek kokun vardı tenimde, 

Unutamadığım bir tek aşkın vardı gözlerimde.

Kalbimde seninle, sensizlik diyarına gidiyorum', 'Giderken... Çantama ilk ismini koydum. Sonra anıları toparlayıp yerleştirdim. Alamadığım bir tek sesin vardı duvarlarda,  Silemediğim bir te...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-tek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-cigdem-simsek-dk0vq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve artık yeniden seviyorum: 

Kainattaki canlıları, 

Çiçekten bal alan arıları, 

Ahenkle yüzen balıkları, 

Gökyüzünde süzülen kuşları, 

Sevmeyi bilen insanı.

Düşünüyorum ve yeniden seviyorum

Çünkü seni seviyorum...', 'Ve artık yeniden seviyorum:  Kainattaki canlıları,  Çiçekten bal alan arıları,  Ahenkle yüzen balıkları,  Gökyüzünde süzülen kuşları,  Sevme...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Hayalleri', 'sevgi-hayalleri-cigdem-simsek-zilpb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerimde aşk çiçekleri

Gittiğinde bomboş bir sevgi sepeti

Kalbimde kanayan ayrılık dikenleri

Artık yaşatır bizi sevgi hayalleri...', 'Ellerimde aşk çiçekleri Gittiğinde bomboş bir sevgi sepeti Kalbimde kanayan ayrılık dikenleri Artık yaşatır bizi sevgi hayalleri......', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgi-hayalleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Aşığım', 'aska-asigim-cigdem-simsek-q9omr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben aşka aşığım.

Her yüz farklı, 

Her gönül farklı, 

Her seviş, her bakış, her gülüş farklı.

Ben aynıyım.

Ve ben aşka aşığım...', 'Ben aşka aşığım. Her yüz farklı,  Her gönül farklı,  Her seviş, her bakış, her gülüş farklı. Ben aynıyım. Ve ben aşka aşığım......', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aska-asigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-cigdem-simsek-jsku5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk ellerimin boş avuçları

Donuk gözlerimin kurumuş gözyaşları

Susan dudaklarımın son heceleri

Unutulmuş yüzümün silik resmi

Reddedilmiş kalbimin en güzel aşkısın...', 'Soğuk ellerimin boş avuçları Donuk gözlerimin kurumuş gözyaşları Susan dudaklarımın son heceleri Unutulmuş yüzümün silik resmi Reddedilmiş k...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-cigdem-simsek-mpohq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç düşündün mü? 

Kuşların gökyüzünde konabilecekleri bir dal yok.

Sevginin dalları bulutlara değmiyor.

Onun için hep yer yüzüne inerler...', 'Hiç düşündün mü?  Kuşların gökyüzünde konabilecekleri bir dal yok. Sevginin dalları bulutlara değmiyor. Onun için hep yer yüzüne inerler......', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kuslar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeden', 'gitmeden-cigdem-simsek-1wn0c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu diyardan gitmeden, 

Sevgini yitmeden, 

Gönlümü etmeden gitme.', 'Bu diyardan gitmeden,  Sevgini yitmeden,  Gönlümü etmeden gitme....', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gitmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban Oldugum', 'kurban-oldugum-asik-sefai-v693x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Niye yüzünü asarsin

Gözüne kurban oldugum

Sineme ates salarsin

Közüne kurban oldugum

Tavaf etseydim bin kere

Kimse bilmez kabem nere

Ayagin bastigin yere

Tozuna kurban oldugum

Destur eyle göz degmesin

Yazlar yoldan eylemesin

Sen söyle eller demesin

Sözüne kurban oldugum

Günes dogar ay tutulur

Yedi koça toy tutulur

Cemalina soy tutulur

Özüne kurban oldugum

Sabret güzel sabret hele

Gönlüm sökün etti dile

Sefai kapinda köle

Özüne kurban oldugum!', 'Niye yüzünü asarsin Gözüne kurban oldugum Sineme ates salarsin Közüne kurban oldugum Tavaf etseydim bin kere Kimse bilmez kabem nere Ayagin ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kurban-oldugum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sabah Ankarada Yağmur Var', 'bu-sabah-ankarada-yagmur-var-fatih-cinar-95vow', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu sabah ankarada yağmur var

ayaklar telaşlı alınlar terli

gözlerim bulutlarla arkadaş olmuşlar

yine hüzzam notalarda gönlümün teli

bu sabah ankarada yağmur var

iğne atsan yere düşmez kızılayda

evlerin saçaklarından sevdalar damlar

bir yanım cephede can verir diğer yanım barışta

bu sabah ankarada yağmur var

gece yolcuları evlerine gitmekte aheste

arap kızı camdan bakmıyor başımda yalnızlıklar

siyah saçlar yerlerini beyazlara terketmekte

bu sabah ankarada yağmur var

şimşekler çakar fırtına kopar beynimde

güneş desen ancak senin gözlerinle doğar

gökkuşağı açar dağlarda senin bedeninle

bu sabah ankarada yağmur var

düşüncen pranga düşüncen kelepçe

mahpus kokuyor odamdaki dört duvar

hayalin yetmez oldu gelde sarayım gönlümce

bu sabah ankarada yağmur var

karşıyakada ıslanmakta sessiz gemi yolcuları

sıla gurbet tadında  neolur gel artık yar

yoksa banada mesken olacak o geminin kamaraları', 'bu sabah ankarada yağmur var ayaklar telaşlı alınlar terli gözlerim bulutlarla arkadaş olmuşlar yine hüzzam notalarda gönlümün teli bu sabah...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-sabah-ankarada-yagmur-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tozunu Ele Vermem', 'tozunu-ele-vermem-asik-sefai-m316i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senki güzeller sahisin

Özünü ele vermem

Damla idim göl eyledin

Sözünü ele vermem

Gündüz güne tutsak düstüm

Zindanlara eyvallah

Kara gecenin isigi

Yüzünü ele vermem

Derdim vardir dolu dizgin

Günüm geride kaldi

Bulutlarim çile yüklü

Derdi üstüme saldi

Saçlarimdaki bu aklar

Rengini senden aldi

Ocaginda yanan benim

Közünü ele vermem

Nefesin kabrimin tasi

Saglari yük eyledi

Güz ayi yaprak dökümü

Baglari yük eyledi

Zerre kadar SEFAI''ye

Daglari yük eyledi

Cekerim sonuna kadar

Tozunu ele vermem!', 'Senki güzeller sahisin Özünü ele vermem Damla idim göl eyledin Sözünü ele vermem Gündüz güne tutsak düstüm Zindanlara eyvallah Kara gecenin ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tozunu-ele-vermem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanar', 'yanar-asik-sefai-w5qu5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Turaba düstü gönlüm

Ne bilsin nerde yanar

Kimisi orda yanar

Kimisi burda yanar

Kavusani görmedim

Ne ondan geçen duydum

Kimi ateste üsür

Kimisi karda yanar

Kabristana seslendim

Ela gözdeki nazar

Sahmeran bakisli yar

Kaderim kara yazar

On sekizbin sarayin

Kapisinda bergüzar

Kimi asikar eder

Kimisi sirda yanar

Karanlikta yedi renk

Karayi seçti gözüm

Doganayda matem var

Secdegahtadir yüzüm

Sevdasi bende gizli

Hakikat benim özüm

Urgan vurun boynuma

SEFAI''m darda yanar!', 'Turaba düstü gönlüm Ne bilsin nerde yanar Kimisi orda yanar Kimisi burda yanar Kavusani görmedim Ne ondan geçen duydum Kimi ateste üsür Kimi...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yanar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessümün', 'tebessumun-elif-kerenciler-ozm1c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yükseklere uzanmaya çalıştı deliliğim 

kayboldu kalabalıklarda 

hafif tebessüm içerdi yüzünün hali

boynunda en sevdiğim halkalardan

sarılasım gelir...

12.04.2002

Biga m.n.''ye', 'yükseklere uzanmaya çalıştı deliliğim  kayboldu kalabalıklarda  hafif tebessüm içerdi yüzünün hali boynunda en sevdiğim halkalardan sarılası...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tebessumun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-gokhan-oktem-np0bg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I.

Bekleyişlerim bekleyiştir hani

bir asrı aşar 

sabırsa kainata koysan almaz...

II.

Ateşi ve ihaneti gördüm

Yüreğimi yakan 

ateşin kendisi değil

ona biçtiğimiz kızıllığı

ve ihanet 

ateşten de sıcak

III.

Hüzün ayak altımda dolaşır

ve ben her daim uyku sersemiyim

Vakitli vakitsiz

düşüşlerim ondandır...

IV. 

Ben soluk alışlarımda atan 

Ben susuşlarımda çağlayan

ve zemheride 

kendi etimle, kemiğimle ısınan

bir yok oluşun efendisiyim...

V. 

İhanet

kör bir bıçaktır

Sapından kanlar akan

Ve yanan yürek

ihanete zamansız bir mekandır

bu dünyada yeri olmayanların sığınağı

Ve ölüm bir dengedir

ihanetin kör keskinliğinde kanayan...

VI. 

Sanma ki zaman sen olduğun için var

Ömür dediğin zamana asılı bir kelledir

Sen olmadan önce geçen zaman

senin varlığının da üstündedir...

VII.

Olmak; birinin olmaksa eğer

o biri olmalı önce kendince

Ve kendince olabilen biri

olmuştur artık başka birince...

VIII. 

Yağmurum ol

Islak bulutlardan damla damla koparak

söndür bu sonsuz ateşimi

Ya da göz yaşım ol

yüreğimin dili dönmeyince 

sığınayım sana

ya başımdan aşağı

ya gözümden...

ak ve karış 

kimliğime...

21,05,2002, İstanbul', 'I. Bekleyişlerim bekleyiştir hani bir asrı aşar  sabırsa kainata koysan almaz... II. Ateşi ve ihaneti gördüm Yüreğimi yakan  ateşin kendisi ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/kimlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Müzik Ölümüm Benim', 'bu-muzik-olumum-benim-emre-gumusdogan-jb92z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şarabın buruk Serkis* 

üzümleri doymamış yaşama 

yıllandıkca artmış acısı 

başka bir tat veriyor 

bu akşama 

yıllar öncesine sürüklüyor beni 

gençliğimin 

bol yıldızlı akşamlarına 

Nüsapel''le** otururduk 

bağ evinde / yine burada / 

soframızda kavun peynir 

bir de şarabımın olurdu 

işte o geceler Serkis 

şu kerevete oturur 

uzun uzun konuşurduk 

bir müzik vardı sesinde 

konuştukça 

içimde isimsiz senfoniler bestelenirdi 

bir mutluluk yeşerirdi zehirli 

sonra ay doğar yürürdü 

okşardım saçlarını 

ateş böcekleri toplardım gözlerinden 

pervaneler kaynaşırdı ışıkta 

kuş tüyü yatak istemezdik 

ilk gençlik yıllarımın ateşiyle sarardım 

kollarıma yük yosma değildi 

ve öyle güzel öperdi ki 

bir gün Serkis 

şahinler vurdu o''nu 

akbabalar götürdü 

işte yine Serkis 

başladı o müzik 

bu müzik ölümüm benim 

o besteledi bu senfoniyi 

çalıp duruyor 

gecenin uzağından / derinden / 

yine yeşeriyor içimde zehirli mutluluk 

bu boşluk 

yıldızların ardındaki boşluk 

Serkis bir sigara verir misin 

(*)   serkis, ermeni kökenli erkek isim 

(**)   nüsapel, ermeni kökenli kadın ismi', 'şarabın buruk Serkis*  üzümleri doymamış yaşama  yıllandıkca artmış acısı  başka bir tat veriyor  bu akşama  yıllar öncesine sürüklüyor beni...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bu-muzik-olumum-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorulma', 'yorulma-aytac-altinok-7j3vw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin uzağı her düşlediğinde, bırak kendini

Kendinde kalanları ve kanayan yanlarını

Rüzgar nasılsa bir yerlere götürür umutlarını

Yine de yorulma, düşersen de kırılma

İçinde yarattığın boşluğu anımsa, boşluk bırakanları

Ve seni sonsuz derinliklere atan insafsızları

Yine de büyüt içindeki haylaz çocuğu 

Her an kucakla ve sarmala yüreğinle ama yorulma

Sen ki ne büyük düşler öldürmüşsün içinde

Sen ki ne hayaller yakmışsın nice evler ısıtma uğruna

Sen ki yüreğini yıldızlara emanet etmiş sen...

O gün gelecek geldiğinde tanrı aşkına Yorulma...', 'Gözlerin uzağı her düşlediğinde, bırak kendini Kendinde kalanları ve kanayan yanlarını Rüzgar nasılsa bir yerlere götürür umutlarını Yine de...', ARRAY['Türk Edebiyatı','Şiir','Aytaç Altınok']::text[], 8.5, '{"poet":"Aytaç Altınok","poet_slug":"aytac-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yorulma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davun', 'davun-i-smet-ozel-24ndk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uç benim boynumun soytarısı

kirle her cemreyi bana doğru olan

unuttum güçbela soluyan perdeleri

dudaklarımı ısırdıkça kabaran akşam

unuttum onu da.

Zaten bir tanım değil midir

tavsayan düşüp kalkmalara

hüznün hacanası diye bildiğim akşam

bir tanım değil midir o kıyısız ellerimiz

fırça çekmeye doğru ölümün bacısına

parmak atmaya doğru şiir okuyaraktan

aşk -bir tanım değil midir-

kusturucu güzellikler ardından.

Her tanım bir ağı parçalıyor gibi çevremizde

azgın atlar boşandıkça sesimin avlusundan

uç benim boynumun soytarısı

dölle ovalı yüreğimi akarsuyunnan

göğsümde serinleyen akçıl kuşların

esirgeyen bağışlayan DİRENME''nin adıyla

indir koynumun yılgısını mor bulutların ordan

indir, indir de

geceleyin dupduru bir iniltiyi

bağrımdaki sağırlıkla değiştirmeye doğru-

Fırlamayım, bıktım tanımlanmaktan.

Leş yiyen akçıl kuşları sevrim çünkü

akçıl gçmen kuşları çünkü

çünkü özentisiz taşra yanakları

gibi çarşılara ilşkin

firegili göklerin altında olmak gibi

yatırları severim

paskalya tatilini.

Her tanım zorlu kilitlerdir belki de

çaput yıldızları aşka dayalı duran

uç benim boynumun soytarısı

böğrümde avrupalı atları koşuşturan

aşkım, tanımım, yanaşmam.', 'Uç benim boynumun soytarısı kirle her cemreyi bana doğru olan unuttum güçbela soluyan perdeleri dudaklarımı ısırdıkça kabaran akşam unuttum ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/davun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Şiir', 'zor-siir-deral-baran-mpu1d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni tarif etmek ne zor şey

Aya inat 

Seni anlatacam yıldızlara 

Araya girse de kara bulutlar..

Ne zor şey 

harfleri kelime yapmak

Adına Venüs demek için

Vakitsizce özlemek 

Sahipsiz şehirleri

Ne zor şey..

Bilmediğin yollarda 

yürümek

sana varabilmek için...

deral

21 mayıs 2002 ist', 'Seni tarif etmek ne zor şey Aya inat  Seni anlatacam yıldızlara  Araya girse de kara bulutlar.. Ne zor şey  harfleri kelime yapmak Adına Ven...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zor-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELVEDA', 'elveda-metin-arifogullari-ulaww', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ELVEDA

Uzaklarda mahsun mağrur bakışını özledim.

Dikenli yollarda adım adım atışını özledim.

Çıkıpta birgün karşıma canım deyişini özledim.

Elveda nazlı çiçeğim Berivan.

Her akşam oturupta sohbetini özledim.

Çiçeklere bakıpta silüetini özledim.

Yollara bakıpta hasretini özledim.

Elveda nazlı çiçeğim Berivan.

Elveda aşk çiçeğim Berivan.

Elveda elveda elveda elveda..', 'ELVEDA Uzaklarda mahsun mağrur bakışını özledim. Dikenli yollarda adım adım atışını özledim. Çıkıpta birgün karşıma canım deyişini özledim. ...', ARRAY['Türk Edebiyatı','Şiir','Metin Arifoğulları']::text[], 8.5, '{"poet":"Metin Arifoğulları","poet_slug":"metin-arifogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/elveda-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Flaş', 'flas-can-yucel-7a4w1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökgürültüsünden korkup yamacıma sokulan sevgilime

Sarıl bana, sarıl, öp, öp, öp beni, dedim

Baksana allah yıldırımlarıyla resmimizi çekiyor!', 'Gökgürültüsünden korkup yamacıma sokulan sevgilime Sarıl bana, sarıl, öp, öp, öp beni, dedim Baksana allah yıldırımlarıyla resmimizi çekiyor...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/flas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbe', 'tovbe-can-yucel-w2dv7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dayak cennetten çıkmışmış

Öyleyse eğer önlem almak gerekir

Bir daha düşmemek için cennete

Burda yediğimiz dayak yeter', 'Dayak cennetten çıkmışmış Öyleyse eğer önlem almak gerekir Bir daha düşmemek için cennete Burda yediğimiz dayak yeter...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tovbe-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Bir Hikaye İşte', 'aci-bir-hikaye-i-ste-fidan-gunes-c56y5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bebeğim gittin miniğim.

Seni öpüp koklayamadım, bağrıma basamadım 

Seni Seviyorum diyemedim. 

Süt veremedim sana, sütten kesemedim.

Gecenin karanlığında senin çığlıklarınla uyanamadım. 

İçimde kaldın bebeğim. 

İsmin bile hazırdı; 

Kız olursan Elif, erkek olursan Ahsen koyacaktım. 

Patikler öremedim sana, 

Gül kokunu süt kokunu duyamadım. 

Gittin bir ilkbahar günü, 

Dünyaya gelemeden ne olduğunu bilemeden.

Biliyorum beni cennetin kapısında bekliyorsun.

Ama sana gelemezsem küsermisin bana bebeğim.

Kaç bahar geçti üzerinden, sen yoksun. 

Bu hayat bana dar geliyor sana gelmek istiyorum. 

Sana bebekler misketler alacaktım.

Oyuncak arabalar biriktirecektin, 

Lüle lüle saçlarını örecektim okula giderken

Beyaz kurdelalar takacaktım saçlarına 

Ya da jöleyle tarayacaktık saçlarını

Genç bir kız, zıpkın gibi delikanlı olacaktın

Melek gibi bir gelin, yakışıklı bir damat olacaktın

Fakat hiçbirşey göremeyeceğim sana ait olan 

Gittin bebeğim gittin, sensiz kaldım hayatta. 

Sana annelik yapamadım bebeğim. 

Seni seviyorum bebeğim, bekle beni geleceğim birgün.

Fidil 

21.05.2002', 'Bebeğim gittin miniğim. Seni öpüp koklayamadım, bağrıma basamadım  Seni Seviyorum diyemedim.  Süt veremedim sana, sütten kesemedim. Gecenin ...', ARRAY['Türk Edebiyatı','Şiir','Fidan Güneş']::text[], 8.5, '{"poet":"Fidan Güneş","poet_slug":"fidan-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aci-bir-hikaye-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğün', 'dugun-mustafa-sureyya-sezgin-b8usz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çalın, gülün oynayın

Pembeye boyayın dünyayı, 

Yarını hiç sormayın

Şimdi mutluluk zamanı.

Birileri üzülecek, 

İş oluruna varınca

Suskun diller çözülecek, 

Bu sihir bozulunca.

(İstanbul,29.07.1996)', 'Çalın, gülün oynayın Pembeye boyayın dünyayı,  Yarını hiç sormayın Şimdi mutluluk zamanı. Birileri üzülecek,  İş oluruna varınca Suskun dill...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dugun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-mustafa-sureyya-sezgin-q1s4i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gideceğim bir gün elbet

Geldiğim gibi bu diyardan! ..

Kucaklarken tüm evreni

Bir hıçkırık seli ile uğurlanacak, 

Artık yüreğim kıpırdamıyacak.

Birileri benden haber soracak, 

Bir varmış, bir yokmuş diyeceksin.

Dikilen güller göğsümde solacak, 

Kendini boşlukta hissedeceksin.

Gideceğim bir gün elbet, 

Geldiğim gibi bu diyardan! ..', 'Gideceğim bir gün elbet Geldiğim gibi bu diyardan! .. Kucaklarken tüm evreni Bir hıçkırık seli ile uğurlanacak,  Artık yüreğim kıpırdamıyaca...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yolculuk-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nefes Gibi', 'bir-nefes-gibi-mustafa-ozke-lp1er', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir nefes gibi çektim seni içime

Bir nefes gibi taşıdım bedenimde

Kanım damarlarıma tırmandı

Ayaklarım duracağımı sandı

Bedenim tutuştu yandı

Bir nefes gibi çektim seni içime

Kalbim çarpmaktan usandı', 'Bir nefes gibi çektim seni içime Bir nefes gibi taşıdım bedenimde Kanım damarlarıma tırmandı Ayaklarım duracağımı sandı Bedenim tutuştu yand...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-nefes-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-mustafa-sureyya-sezgin-bq7m1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülümse bahar gözlüm, 

Acılara gülümse, 

Bedelidir mutluluğun

Yaşadığın hüzünse.

Gülümse gönül sözlüm, 

Hüsranlara gülümse.

Açılacak her çiçek, 

Bugün için düğünse.

Bir güneşle doğacak

Ve sonunda solacak

Yitirdiğin her güne

Her acıya gülümse.', 'Gülümse bahar gözlüm,  Acılara gülümse,  Bedelidir mutluluğun Yaşadığın hüzünse. Gülümse gönül sözlüm,  Hüsranlara gülümse. Açılacak her çiç...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulumse-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-deral-baran-chfe1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şair olmak için 

Bütün harfleri satın aldım 

Yinede 

Bir türlü adını 

Yazamadım...

Deral 

22 mayıs 2002 ist.', 'Şair olmak için  Bütün harfleri satın aldım  Yinede  Bir türlü adını  Yazamadım... Deral  22 mayıs 2002 ist....', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sair-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-fusun-aydinci-oyfee', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliniyordu güz mevsiminin yaptıkları, 

Önce yağmur oldu, aktı gitti umutlar

Ardından yapraklar yaşamdan vazgeçti.

Bir sıkıntıdır aldı yürüdü yüreklerde, 

Kaygısızca tersine sardım ayları

ben bu sene......', 'Biliniyordu güz mevsiminin yaptıkları,  Önce yağmur oldu, aktı gitti umutlar Ardından yapraklar yaşamdan vazgeçti. Bir sıkıntıdır aldı yürüd...', ARRAY['Türk Edebiyatı','Şiir','Füsun Aydıncı']::text[], 8.5, '{"poet":"Füsun Aydıncı","poet_slug":"fusun-aydinci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sonbahar-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Sevmek Yasakmış', 'bize-sevmek-yasakmis-sair-tarik-5nr3d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizde düştük bir güzelin ardına

Umutlara kapılmış bir günün sabahında

Aşkınla ne halde geldim bak yanına

Sevdamın çığlıkları yükseliyordu yüreğimde

Bize sevmek yasakmış sevilmek gibi

Ne sevmeyi hakkettik ne de sevilmeyi

Şu dünya üzerinde değil gülmeyi 

Ağlamamdı hep sevdiğimin dileği', 'Bizde düştük bir güzelin ardına Umutlara kapılmış bir günün sabahında Aşkınla ne halde geldim bak yanına Sevdamın çığlıkları yükseliyordu yü...', ARRAY['Türk Edebiyatı','Şiir','Şair Tarık']::text[], 8.5, '{"poet":"Şair Tarık","poet_slug":"sair-tarik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bize-sevmek-yasakmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Yetmez', 'biri-yetmez-veli-cetinkaya-z7tvw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİRİ YETMEZ

Özlem duymak hep sevenin işidir

Var olmanın temelinde, bir erkek bir dişidir.

Bunu sorsan bir SOFTA''ya

Der ki tanrı işidir.

Tanrı tektir.....! 

Erkek dişi fark etmez

Bana sorsan; Çoğalmaya bir tek cinsiyet yetmez.

Veli Çetinkaya

ANTALYA', 'BİRİ YETMEZ Özlem duymak hep sevenin işidir Var olmanın temelinde, bir erkek bir dişidir. Bunu sorsan bir SOFTA''ya Der ki tanrı işidir. Tanr...', ARRAY['Türk Edebiyatı','Şiir','Veli Çetinkaya']::text[], 8.5, '{"poet":"Veli Çetinkaya","poet_slug":"veli-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/biri-yetmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Yürek', 'deli-yurek-veli-cetinkaya-h8ott', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Volkanı andırır yar bakışların

Nice canlar yakar hoş gülüşlerin

İncilere benzer güzel dişlerin

Deli yürek senin bütün düşlerin.

Aklımı başımdan alıverdin sen

Ansızın kanıma giriverdin sen

Ne yöne estiğin bilemedim ben

Yelkenime dolan fırtınamsın sen.

Sürükleyip dur okyanuslarda 

Sök dömenimi, at derin sulara

İstersen dinlendir tenha koylarda

Bana hayat veren serserimsin sen.

Veli ÇETİNKAYA 

Mart 1999 Antalya', 'Volkanı andırır yar bakışların Nice canlar yakar hoş gülüşlerin İncilere benzer güzel dişlerin Deli yürek senin bütün düşlerin. Aklımı başım...', ARRAY['Türk Edebiyatı','Şiir','Veli Çetinkaya']::text[], 8.5, '{"poet":"Veli Çetinkaya","poet_slug":"veli-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/deli-yurek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazim', 'mazim-kamuaran-uzun-dacxl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Temiz Mazim Oldu Talan

Anladımki Dünya Yalan

Sevgi Ateşinden Kalan

Saklamıştım Küller Seni

Pınarların Akışından

Kubbelerin Nakışından

Gençliğimin Bakışından

Saklamıştım Güller seni', 'Temiz Mazim Oldu Talan Anladımki Dünya Yalan Sevgi Ateşinden Kalan Saklamıştım Küller Seni Pınarların Akışından Kubbelerin Nakışından Gençli...', ARRAY['Türk Edebiyatı','Şiir','Kamuaran Uzun']::text[], 8.5, '{"poet":"Kamuaran Uzun","poet_slug":"kamuaran-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı Bir Tanem', 'olmadi-bir-tanem-murat-cicek-5rmxi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olmadı bir tanem, senden ayrı yaşayamam 

Deniz mavisi gözlerini 

Buğday sarısı saçlarını 

O bembeyaz ellerini unutamıyorum

Seni unutmak, seni hatırlatıyor bana 

Odamın dört duvarında senin hayalin 

Bedenimin yarısı sensin 

Damarlarıma dolmuş aşkın 

İstesemde sensiz olamıyorum 

Yokluğun pek fazla bir şey ifade etmiyor 

Zaten seninleyken bile sensizdim 

Umursamıyordun ki beni 

Peki niye bu kadar çok istiyorsun 

''UNUTMA MI'' seni

(28.04.1997)', 'Olmadı bir tanem, senden ayrı yaşayamam  Deniz mavisi gözlerini  Buğday sarısı saçlarını  O bembeyaz ellerini unutamıyorum Seni unutmak, sen...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olmadi-bir-tanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-murat-cicek-561pm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaktığım her sigaranın, 

dumanında hayalin

Çektiğim her nefes, 

soluğumdasın.

Yıllanmış şarap gibi yakıyorsun içimi

Sen benim gecelerimin en güzel sarhoşluğusun.', 'Yaktığım her sigaranın,  dumanında hayalin Çektiğim her nefes,  soluğumdasın. Yıllanmış şarap gibi yakıyorsun içimi Sen benim gecelerimin en...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hayal-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıl Dönümü', 'yil-donumu-murat-cicek-72kud', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gecede sensizim

Dünkü gibi 

Gözlerim duvarları geziyor 

Seni arıyorum 

Gözlüyorum; 

Bu şehrin tüm sokaklarını 

Sanki sen geleceksin 

Bu gece ölümünün yıl dönümünü kutluyorum.

(26.11.1996)', 'Bu gecede sensizim Dünkü gibi  Gözlerim duvarları geziyor  Seni arıyorum  Gözlüyorum;  Bu şehrin tüm sokaklarını  Sanki sen geleceksin  Bu g...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yil-donumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Yıl Dönümü', 'olumun-yil-donumu-murat-cicek-jsiri', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gecede sensizim

Dünkü gibi 

Gözlerim duvarları geziyor 

Seni arıyorum 

Gözlüyorum; 

Bu şehrin tüm sokaklarını 

Sanki sen geleceksin 

Bu gece ölümünün yıl dönümünü kutluyorum.

(26.11.1996)', 'Bu gecede sensizim Dünkü gibi  Gözlerim duvarları geziyor  Seni arıyorum  Gözlüyorum;  Bu şehrin tüm sokaklarını  Sanki sen geleceksin  Bu g...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olumun-yil-donumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorum', 'agliyorum-hasan-ozemek-tirlz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin için ağlıyorum, 

En saf gözyaşlarımla..

Sensizliğin yalnızlığını, 

Güneşsiz günlerde duyuyorum en fazla, 

Seni bulmak mavilerde özlemim, 

Odamın serin loşluğunda, 

Dopdolu hayalin..

Dudağıma götürdüğüm kadehte sen varsın, 

İşte..yalnızım, 

Sensizliğin yalnızlığı içimde..

Ne gözlerime gülen gözlerin, 

Ne saçlarımı okşayan ellerin var..

Gözlerim ıslak, 

Mahsun yüzün ve gözlerin, 

Seni hatırlıyorum.

Yüreğimde eskimeyen sevginle, 

Sana koşmak istiyorum..

Ve....

Doyasıya  ağlıyorum...', 'Senin için ağlıyorum,  En saf gözyaşlarımla.. Sensizliğin yalnızlığını,  Güneşsiz günlerde duyuyorum en fazla,  Seni bulmak mavilerde özlemi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/agliyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağın Doğuşu', 'topragin-dogusu-murat-cicek-sj6nz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprak, 

mis kokulu toprak

yeşil saçlı toprak

bilmeyiz hiç kıymetini.

Ezeriz ayaklarımızla 

basrız hiç düşünmeden.

Acırmı ki canın bilmeyiz, 

tepiniriz üstünde acımadan.

Kimi gün baltalarız sırtından 

Kimi gün kürek saplarız bağrına 

Ve hiç düşünmeden beton yığınları 

dökeriz suratına 

Kapatırız üstünü, güzel gözlerinin 

Hiç düşünmeden seni.

Sensin bu evrenin çıkılmaz yokuşu 

Kıyamet olacak senin, 

Ey toprağın doğuşu.

(30.11.1996)', 'Toprak,  mis kokulu toprak yeşil saçlı toprak bilmeyiz hiç kıymetini. Ezeriz ayaklarımızla  basrız hiç düşünmeden. Acırmı ki canın bilmeyiz,...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/topragin-dogusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-murat-cicek-2oicv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen öğrettin bana doğruyu 

Gösterdin yalanı yanlışı

Üşenmeden verdin sevgini

Sensiz olamam anne

Sana borçluyum sonunda 

Bekliyorum seni yolunda 

Canımı veririm uğruna 

Sensiz olamam anne

Sen gösterdin bana sevgiyi 

Sen öğrettin bana saygıyı

Hep istedin sen iyiyi

Sensiz olamam anne', 'Sen öğrettin bana doğruyu  Gösterdin yalanı yanlışı Üşenmeden verdin sevgini Sensiz olamam anne Sana borçluyum sonunda  Bekliyorum seni yolu...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anne-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavilerde Bulacak', 'mavilerde-bulacak-hasan-ozemek-mwwv3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıplak gecelerdeyim, 

Yalınayak bir güneşin kovaladığı, 

Bu gecelerin karanlığına, 

Çiğ damlası gibi düşen hayalsin sen..

Biliyorum, 

Yaşam ayrılıklarla dolu.

Hayallerimde hayalini, 

Sende kendimi buluyorum.

Hasretim hep ellerine, 

Gel diyorum sana tükenen umutlarla, 

Gel ısıtsın alevlerin  donmuş hislerimizi, 

Sen benimsin diyeceğim güne kadar, 

Koşacağım ardından..

Mavilerde bulacak gözlerim gözlerini...', 'Çıplak gecelerdeyim,  Yalınayak bir güneşin kovaladığı,  Bu gecelerin karanlığına,  Çiğ damlası gibi düşen hayalsin sen.. Biliyorum,  Yaşam ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mavilerde-bulacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-murat-cicek-uoo50', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey gözünü sevdiğim İstanbul''um

Bir zamanların en gözde tutkusu

Her şairin yüreğindeki buğusu 

Yahya Kemal misali bir zamanların aziz İstanbul''u

İstanbul''u dinliyorum gözlerim kapalı 

Ama biz şu an o duyguları taşımıyoruz 

Çünkü! Bu istanbul o İstanbul değil 

Bu insanlar o insanlar değil 

O zaman ki güzelliklerin sahibi 

Bu şehir değil.

(31.05.1995)', 'Ey gözünü sevdiğim İstanbul''um Bir zamanların en gözde tutkusu Her şairin yüreğindeki buğusu  Yahya Kemal misali bir zamanların aziz İstanbu...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/istanbul-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir ve Sen', 'bu-sehir-ve-sen-murat-cicek-sfr3z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkımı şarkılara yazıp

Her an seni dinliyorum 

Gözlüyorum her köşesini bu şehrin

Her sokağında seni bekliyorum 

Didik didik ediyorum her yerini 

Sokaklarda, caddelerde geziyorum 

Seni senden habersiz 

Her köşe bucakta arıyorum 

Bu şehrin sessizliğini dinliyorum

Sensizliğimi ve senden mahrum kalışımı

İnan herkesten seni soruyorum 

Yoksunluğumu ve unutup yalnızlığımı

Bu şehrin her köşesinde kokun var 

Seni nasıl bulacağımı bilmiyorum 

Ve bu bana ne kadar acı versede 

Seni sensiz dinliyorum, 

Seni çok ama çook SEVİYORUM.

(31.05.1995)', 'Aşkımı şarkılara yazıp Her an seni dinliyorum  Gözlüyorum her köşesini bu şehrin Her sokağında seni bekliyorum  Didik didik ediyorum her yer...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-sehir-ve-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-refik-recep-pelit-dh3f5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatırladım sabahlarının aydınlığını, 

Issız ovaların kucağındaydı  adın 

Kaybolmuş bir kırlangıçın kanadında

Yolunu kaybetmiş bir rüzgardaydı nefesin, 

Saçlarının ışıltısıydı gözlerimi kamaştıran

Rüzgarındaki serinlikti seni çekici kılan.

Özledim Gecelerinin gizemliliğini, 

Çekingenliği, sana karşı aciz kalmayı 

Sessizliği boğan senin ince sesindi

Bakamazdım, gözlerim kamaşırdı 

Bir martının bembeyazındaydı rengin 

Bir asır geçti sanki yokluğunda 

Tam bir asırdır sensizim hatıralarımda 

Hala karanlık gecelerin zifirindeyim

Hatırımdan çıkarmak hala çok zor seni, 

İçimde aşkım ve iyileşmeyen mel''un yarası 

Rüzgarlardaydı neşeli sesin, ferah kokun, 

Rüzgarlarla anıyorum, Artık Yoksun.', 'Hatırladım sabahlarının aydınlığını,  Issız ovaların kucağındaydı  adın  Kaybolmuş bir kırlangıçın kanadında Yolunu kaybetmiş bir rüzgardayd...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruzgar-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne 2', 'anne-2-murat-cicek-tzmvs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dertler, kederler üstüste geldi

Ayrılık acısı bağrımı deldi

Geçmez günler, ömür tükendi

Gurbette başı boş kalmışım anne

Hasretlik canıma artık tak etti 

Dost bildiklerim bir bir terk etti

Yüreğimde bin bir sancı beni kahretti 

Gurbette başı boş kalmışım anne

Sakın ha üzülme, ağlama halime 

Ben unuttum dostları, kaldım kendimle 

Böyle perişan, aç, susuz, sefaletle

Gurbette başı boş kalmışım anne

(04.01.1999)', 'Dertler, kederler üstüste geldi Ayrılık acısı bağrımı deldi Geçmez günler, ömür tükendi Gurbette başı boş kalmışım anne Hasretlik canıma art...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anne-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryat Figan Arşa Çıkar', 'feryat-figan-arsa-cikar-asik-sefai-jwj86', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Feryat figan arsa çikar

Garip daglarda bu gece

Bülbülün dili tutulur

Viran baglarda bu gece

Kurtla kuzu güden yolcu

Gelen yolcu giden yolcu

Biliyonmu neden yolcu

öÖüm saglarda bu gece

Zincirmi vurulmus kola

Konussaydi biraz ola

Yasanmismi acep ola

Eski çaglarda bu gece

Nanay dedi nanay dedi

Toy kuruldu nanay dedi

Herkes deli diyor amma

O herkese nanay dedi

SEFAI gitmem yurdumdan

Gitsem ölürüm derdimden

Daha gitmeden ardimdan

Nazlim aglarda bu gece', 'Feryat figan arsa çikar Garip daglarda bu gece Bülbülün dili tutulur Viran baglarda bu gece Kurtla kuzu güden yolcu Gelen yolcu giden yolcu ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/feryat-figan-arsa-cikar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turnam', 'turnam-osman-oztunc-ftzve', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dağları tardım geldim körbela

Veysel karan''a vardım kerbela

dedi dergahtan şaşma şer bela

döner başımda döner turnalar

yüksel turnam yüksel Hakka varalım

erenler şehrinde divan duralım

ayrılık zor olur sultan göçerler

nur verdi sır eyledik hellallaşalım

devr-i şan sırrı eylerse beyan

kamil olur mu cahil sözüne uyan

sırra ergah ol, ateşlerde yan

yanar savrulur döner başımda turnalar

yüksel turnam yüksel vermeden ara

açılan yaranı aşıklar sara

cahiller gölünü eğlenmeden geç

divan-ı mahşerde gelek yan yana', 'dağları tardım geldim körbela Veysel karan''a vardım kerbela dedi dergahtan şaşma şer bela döner başımda döner turnalar yüksel turnam yüksel ...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turnam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Kavgalarımız', 'bizim-kavgalarimiz-kagan-altindal-pg5ef', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskiden ben böylemiydim...

Deli doluydum.

Deli rüzgarlar gibi eserdim.

Kavgalar yapardık, 

Küçük kavgalar ama

Büyük amaçlar için

Dövüp, dövülmekten korkmazdım.

Geceleri sokağa çıkıp

Bağıra bağıra türküler söylerdim.

Alırdım sazımı elime, 

Sazımı parçalarcasına bağırarak, 

Türklüğümün türküsünü okurdum

Kedilere, köpeklere, bir de o karanlık sokağa...

Kavgalarımızda şüphe olmazdı bizim.

Şahıs için kavgamız olmazdı bizim.

Bazen döver, bazen dövülürdüm. 

Hatta bazen alırdım tabancamı elime, 

Bir deli fişek gibi atlardım sokağa, 

Ama o insanların bakışlarıyla ezilince, 

Koyardım belime o delikli demiri.

Kavgalarımız vatan içindi bizim, 

Dövsek de, dövülsek de vatan sağolsun.', 'Eskiden ben böylemiydim... Deli doluydum. Deli rüzgarlar gibi eserdim. Kavgalar yapardık,  Küçük kavgalar ama Büyük amaçlar için Dövüp, dövü...', ARRAY['Türk Edebiyatı','Şiir','Kağan Altındal']::text[], 8.5, '{"poet":"Kağan Altındal","poet_slug":"kagan-altindal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bizim-kavgalarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamak', 'anlamak-sabri-gurbuz-jelat', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ANLAMAK

Bir mısra

Bazen bir hayat

Sırlı kutu gibi gelir karşına

Çözemessin

Ellerin 

Bir perdeyi yoklar

Açılmadıkça sima

Göremezsin

Suya

Atılıveren bir taş

Dalgalanır da gelir sahiline

Silemezsin

Gözyaşı

Her kapıyı zorlasa da

Bir düşdür aşk

Giremezsin

Ömür

Son demiyle gelince

Tüm beden el-pençe

Dönemezsin

Sana 

Her soluğumla seslendim

Benim için sen başkasın

Bilemezsin

Bıraktım

Ellerim ve dillerimdeki herşeyi

Kalbimi alıp da gidiyorum

Duyuramazsın

Ve işte hayat seninle

Ben ise toprağı besliyorum

Anladıysan beni

Gel, seni bekliyorum

    Sabri (30.08.1999)', 'ANLAMAK Bir mısra Bazen bir hayat Sırlı kutu gibi gelir karşına Çözemessin Ellerin  Bir perdeyi yoklar Açılmadıkça sima Göremezsin Suya Atıl...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/anlamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyin Var', 'neyin-var-oguzkan-bolukbasi-n4a6h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İhtimali sonsuzdur

Yaşamın yolunda önüne çıkanların

Eğer düşlerin varsa

Şaşırma 

Görmediğin resmini çizersin karşı kıyıların

Tüm limanlar senin olur

Rüzgarlar şişirir yelkenlerini

Adlarını bile bilmediğin

Hangi sevdalarda izin kalmıştır

Hangi yangınlara körükle koşmuşsundur

Hangi türküde coşmuş

Hangi kadehde yorulmuşsundur

Hepsi unutulur

Bir anlamlı öpüşün yoksa canını yakan

Bir şimşek yoksa ruhunda çakan

Cilveli nazlara sırtını dönmüşsen

Üşümemişsen 

Bana anlatacak neyin vardır

Aşkı tanımamışsan', 'İhtimali sonsuzdur Yaşamın yolunda önüne çıkanların Eğer düşlerin varsa Şaşırma  Görmediğin resmini çizersin karşı kıyıların Tüm limanlar se...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/neyin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemiyorum', 'bilemiyorum-mustafa-sureyya-sezgin-9ixgc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni seviyorsam

Olmazı ne oldurur? 

Seninle aydınlıksam

Güneşi kim soldurur? 

Seni çok özlüyorsam

Hasret nasıl doyurulur? 

Düşünüyorsam seni

Sürekli ve amansızca, 

Yürek nasıl kavrulur? 

Seninle birlikteyken

Çıkmazlardan ne çıkar? 

Çok karışığım inan

Seni senle yaşarken.

Bilinmezlere giriyor, 

Çözemiyorum.

Bir ömrü sensiz yaşamayı

Düşünemiyor, 

Bilemiyorum! ...

(İstanbul,07.10.1996)', 'Seni seviyorsam Olmazı ne oldurur?  Seninle aydınlıksam Güneşi kim soldurur?  Seni çok özlüyorsam Hasret nasıl doyurulur?  Düşünüyorsam seni...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bilemiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toplantı', 'toplanti-mustafa-sureyya-sezgin-y2kjj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dedi...

Dedim...

Dedik...

Bir sidik yarışıydı bu, 

Hep birlikte kirlettik...

(İstanbul,07.10.1996)', 'Dedi... Dedim... Dedik... Bir sidik yarışıydı bu,  Hep birlikte kirlettik... (İstanbul,07.10.1996)...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/toplanti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maksat Muhabbet Olsun', 'maksat-muhabbet-olsun-mustafa-sureyya-sezgin-wj2g9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hepsi sıkı fıkı dosttular

Önümde şakalaştılar.

Vallahi kötü niyetleri yoktu.

Ercan kırk yaşını geçmiş, 

Çoluk çocuk sahibi, 

Neşesini ve muhabbetini

Göstermek için sanırım, 

İçinden geldi

Poposunu okşadı

Yirmiikilik Selma''nın.

Attı elini Okan

Ayşe''nin ince boynuna

Hediye etmek için hepatitini

Çekti kendine doğru

Ve bir ısırık aldı

Kızın yarım sandiviçinden

Bulaşmışsa ağzına

Hepatit armağan kızdan.

Kadehler içki dolsun

Maksat muhabbet olsun.

Şöför Ahmet''in

Merdiveni dayalı ellisine

Yemeklerden pilici seçer

Karşılaştıkça Nalan''la

Baba şefkatiyle

Dokunur kızın saçlarına

Gezindirir elini omuzlarında.

Uğur, yirmilik delikanlı

Espiri ve neşe onda

Eli işte gözü oynaşta.

Bugün var yarın yoksa

Ne zarar gelir ki oğlandan? 

Kimin eli

Kimin cebinde demeyin

İnsanlık öldü mü abi, 

Bunda ne kötülük var sanki? 

Maksat muhabbet tabii! ..

(İstanbul,17.11.1996)', 'Hepsi sıkı fıkı dosttular Önümde şakalaştılar. Vallahi kötü niyetleri yoktu. Ercan kırk yaşını geçmiş,  Çoluk çocuk sahibi,  Neşesini ve muh...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/maksat-muhabbet-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acının Rengi', 'acinin-rengi-adnan-yucel-bzcrk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '..ey acılara tat veren güzellik

Yüreğimize hoşgeldin

Geldin de

Çiçekli dallara döndürdün öfkemizi

Artık ister dolu yağsın ömrümüze

İsterse kar

Biz ki bildikten sonra sevmeyi

Bütün sabahlar

Acı renginde olsa ne çıkar', '..ey acılara tat veren güzellik Yüreğimize hoşgeldin Geldin de Çiçekli dallara döndürdün öfkemizi Artık ister dolu yağsın ömrümüze İsterse k...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yücel']::text[], 8.5, '{"poet":"Adnan Yücel","poet_slug":"adnan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/acinin-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Seni', 'seviyorum-seni-ayhan-aktas-ezwxs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bana ettiğin telefondan sonra garip bir şey oldu bana.

anlam veremiyorum, şiirler daha bir guzel cıkıyor dılımden, 

artık bende korkuyorum, gerceklerden, 

radyoda dillenen şarkılar dudaklarımı kurutuyor, 

ürkütüyor gözlerimden akacak yaşları, 

anlatamıyorum geceye duygularımı, 

off da off

Sanırım bende seviyorum seni..', 'bana ettiğin telefondan sonra garip bir şey oldu bana. anlam veremiyorum, şiirler daha bir guzel cıkıyor dılımden,  artık bende korkuyorum, ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Aktaş']::text[], 8.5, '{"poet":"Ayhan Aktaş","poet_slug":"ayhan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seviyorum-seni-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın ve Su', 'kadin-ve-su-mustafa-ozke-t9ens', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kadın

bardaktaki karanfil

susuz

bırakmayacaksın

kadın

saksıdaki karanfil

topraksız

bırakmayacaksın

kadın

karanfil gibi

su verdikçe

güzelleşir

kadın

çelik gibi de

su verdikçe

sertleşir

kadın

su ve karanfil

toprak ve çelik

ayarını iyi yapacaksın', 'kadın bardaktaki karanfil susuz bırakmayacaksın kadın saksıdaki karanfil topraksız bırakmayacaksın kadın karanfil gibi su verdikçe güzelleşi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kadin-ve-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayan Yıldız', 'kayan-yildiz-osman-turkmen-zla2j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir Mart gecesinde, kayınca yıldız, 

İçim yine sensiz ve yine yalnız, 

Mart Kedisi kadar, yorgun ve arsız, 

Hep seni bekledim, gelmeyenimdin.

Yıldız kadar afet, yıldızdan uzak, 

Mevsimsiz çiçeğim, herşeyi bırak, 

Sen tehlikeli yol, sevgiye tuzak, 

Vurmanı bekledim, imkansızımdın.

Yıldızla beraber, çok şeyler kaydı, 

Söyleyecek olsam, gece uzardı, 

O geceye şahit, tek kişi vardı, 

Bilmesin istedim, suskunluğumdun.

Her yıldız bir yalan, umut dolu hiç, 

Tutmayan dilekler, gizli bir sevinç, 

Ve sevdam o gece, yüreğimde linç, 

Olmasın istedim, imkansızımdın.', 'Bir Mart gecesinde, kayınca yıldız,  İçim yine sensiz ve yine yalnız,  Mart Kedisi kadar, yorgun ve arsız,  Hep seni bekledim, gelmeyenimdin...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kayan-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıt''a', 'kit-a-seyh-galib-cdr92', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer desem ki hevalar açıldı geldi behar

Murad oldur ki benimle mahabbet eyledi yar

Ya söylesem ki çemen goncelerle doldu

odur garez ki tebesümle söyledi dildar', 'Eğer desem ki hevalar açıldı geldi behar Murad oldur ki benimle mahabbet eyledi yar Ya söylesem ki çemen goncelerle doldu odur garez ki tebe...', ARRAY['Türk Edebiyatı','Şiir','Şeyh Galib']::text[], 8.5, '{"poet":"Şeyh Galib","poet_slug":"seyh-galib","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kit-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlığın Adaleti', 'yanlizligin-adaleti-ersan-yaraskan-o0gst', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir an gelir ki dünyaların sığdığı

Dakikaları isminle anılabilir ancak

Öyle özel anlar vardır ki hazinelerin anahtarı

Bilirsin ki artık senin olacak

Bazı anlar vardır ki yalnızlığında

Anlarsın kimse kalmayacak yanında

Bazı anlar vardır aklına gelmez yakalanacağı

Ardından yine yalnızlık yaşanacak

Bazen rakı gibidir değişik renklerde

Kendi dünyanı yaratır

Bazen gitmeyeceğinden korkar insan

Bir kere düşünce yaşı yanaklarını yakarak

Anlarsın ki gerisi sende kalacak

Terazisi yoktur öyle kolay değildir

Biraz sarhoş eder adamı

Gerisi sabah ki baş ağrısı

Her anını paylaştığın hayatının

Sana kalan düşünme payıdır bazen

Bazen ise bir define saklarsın içine 

Sen bile bulamazsın kaybolursun kendinde

Hayatının en özel anlarını

Orda bırakmak zorunda kalırsın dışarı çıkarken

Misafir kabul etmez hiçbir zaman

Sadece sen olursun ve bir başkasının olmadığını 

Anlayana kadar bir oyundur geride kalan

Bundan sonrası ise hayat dedikleri bir yaşam

Sınır çizilmemiştir bu ortak ve kimsesiz memlekete

Girdiğin yeri bulamazsın çıkışlar ise 

Bazen bir kelime bazen de  kendin kadar uzaktır

Cevabını bildiğin her soru serbesttir

Bilmediklerin ise kaybettiğin zamanın yanına kar kalır

Bir başka hayattır 

Aynı havayı soluyan milyarlarca hem cinsinden

Bir farkın olmadığını kanıtlayana kadar

Memlekettir dedim kendi içinde her şeyi söylemek mümkün

Dışarıda ise bildiğin kadar

Yalnızlığın yalnızlık özelliğini taşıyan

Yalnız bazı zamanlardır

Uyumadan birkaç saniye önce 

Uyandıktan sonraki birkaç saniye

Geri kalan yalnızlıklarımızı 

Bozan etkenler vardır elbet

Bazen sigaradır bazen de hesap sorduğumuz duvarlar

Dışarıdaki dünya ve içersi, kapılar hep açıktır

Anahtarları paspasın altında

Bir oyun oynarız kimsesizliğin sessizliğinde

Kalp atışlarımızı dinleriz eriyip giden aynanın seyrinde

Hiçbir şeye ihtiyacımız yoktur 

Ne bir besteye 

Şarkı söylemek için

Nede bir düşmana 

İki tarafı da biz oynarız

Bu yüzden ya hep kazanır yada hep kaybederiz yalnızlığımızda

Bir sembole gerek duymadan hissetmektir bazen

Yada bir isim yazmaya gerek yoktur yalnız kalmış oklu kalbin içine

Sevgi vardır hüzün vardır sinir ve benzeri duyguların anlatımıdır

Var olmak yada hayalini kurmak arasında ince ve uzun bir çizgidir

Bir sonraki yalnızlığınızla sınırlı duygularınızın 

Ölçüt bilmez haykırışlarıdır içinizde 

Bir telefon sesine kadar uzun ve ince bir sessizlik parmaklarınızın ucunda

Başlayan her şeyin bir sonu vardır ya

Size verilen her şeyin bir gün alınacağını sizin dışınızda herkes bilir

Yalnızlık böyle değildir işte sonu ve sonsuzu çizginin kalınlığına endeksli uzunluğunda gizlidir

Boş verememektir aldırmayanlara olan isyanınızdır içinizde kabaran 

İçinizdeki duvara bir çivi çakıp yeni bir resim asmaktır

Ardı ardası bitmeyen temiz sayfaların her açılışında çıkardığı sestir

Kelimeleri, bildiğiniz her şeyi bir poşete koymaktır

Sizi düşünmeyenleri düşünmek zorunda kalmak

Düşünenleri ise canlandırmaktır kırmızı ışıkta

Sona yaklaşmanın en hızlı yoludur bir adım bile atmadan

Zamanın hızını görmektir çekilmiş siyah beyaz fotoğraflarda 

Bunlar gibi sınırlı her kavramı sınırsız kılmaya çalışırken

Hayatın son dönemecine getirir insanı

Soluduğu havanın kıymetini anlatıp

Bir kaç öğüt  verip yeni bir hayatı paylaşmaya gider

Ve son olarak bir şey fısıldar meleklerden hemen önce

Sen hiç yalnız kalmadın çünkü hep ben vardım yanında......', 'Bir an gelir ki dünyaların sığdığı Dakikaları isminle anılabilir ancak Öyle özel anlar vardır ki hazinelerin anahtarı Bilirsin ki artık seni...', ARRAY['Türk Edebiyatı','Şiir','Ersan Yaraskan']::text[], 8.5, '{"poet":"Ersan Yaraskan","poet_slug":"ersan-yaraskan","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/yanlizligin-adaleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Hergün Yazıyorum Arasıra Sende Yaz', 'sana-hergun-yaziyorum-arasira-sende-yaz-refik-recep-pelit-klcqb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sorularla doluydu zihnimin her hücresi

Sorsam olmuyor bir kararda durmuyor

Zeka aklın sermayesi derler ya atalar

Savsam da olmuyor, Sualleri çözmüyor

Açılmıştı kapanan kapıların bir çoğu

Dediler Işık arıyorsan yolun olsun hep doğu 

Gideyim artık dedim Buralar çok soğudu 

Mevsimlerde dönek, yerlerinde durmuyor 

Ömür sermayedir, kullanmasını bilene 

Sevgiyi neşret kimseye nefret bileme 

Elimde olsa selam gönderirirdim son yarime

Gidenler dönmüyor, ateş ise bir türlü sönmüyor, 

Bahar geldi erik ağaçları oldu bembeyaz, 

Sana hergün yazıyorum arasıra sende yaz, 

Neşe vermiyor artık ne cümbüş nede saz, 

Şarkılar susmuyor, Sesim eskisi gibi çıkmıyor.', 'Sorularla doluydu zihnimin her hücresi Sorsam olmuyor bir kararda durmuyor Zeka aklın sermayesi derler ya atalar Savsam da olmuyor, Sualleri...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-hergun-yaziyorum-arasira-sende-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müfred ve Beyitler', 'mufred-ve-beyitler-seyh-galib-xgd47', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1.

Çeken piyaleyi Pa-der rikab olup gidiyor

Gelen bu meclise mest ü harab olup gidiyor

2.

Vücud-ı pakin  Alla''a emanet eyledim anın

Gönül eğlencesi can paresibir dil -nüvazım var

3.

Gele bir devr ki bu galibi yad eyleyeler

Fırsat- ı sohbeti ahbab  ganimet bilsin', '1. Çeken piyaleyi Pa-der rikab olup gidiyor Gelen bu meclise mest ü harab olup gidiyor 2. Vücud-ı pakin  Alla''a emanet eyledim anın Gönül eğ...', ARRAY['Türk Edebiyatı','Şiir','Şeyh Galib']::text[], 8.5, '{"poet":"Şeyh Galib","poet_slug":"seyh-galib","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mufred-ve-beyitler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma Sakın!', 'unutma-sakin-omur-torun-om9af', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayallerim vardı benim; 

Ümitlerimi verdiğim.

Bir dünya kurmuştum; 

Ömrümü feda ettiğim.

Senden tek dileğim, 

Sımsıcak sevgiydi sevgilim

Çünkü delice sevmiştim seni; 

Belki anlayamadım seni, 

Veya anlatamadım kendimi

Ama gerçekten sevmiştim seni...

Beni daima hatırla, Unutma sakın, 

Sevgim, ruhum sende kalsın

Birer hatıra diye saklarsın

Belki beni sevgiyle anar

Belkide için için ağlarsın...

Hatırlamak istemesende beni

Yaban eller alsada seni

Seni çok ama çok sevdiğimi

Sakın Unutma sevgilim! ...', 'Hayallerim vardı benim;  Ümitlerimi verdiğim. Bir dünya kurmuştum;  Ömrümü feda ettiğim. Senden tek dileğim,  Sımsıcak sevgiydi sevgilim Çün...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/unutma-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Artık', 'sev-artik-omur-torun-rh8rw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seveceksen sev artık

Yeter bu çektiğim, 

Acı, bilinmez şu halime

Seveceksen sev artık

Canımı yitirdin

Sevgimi bitirdin

Dayanılmaz zulmünle, 

Seveceksen sev artık

Yaşamak artık çok zor

Sensiz geçen gecelerde

Yine ağlıyorum sessizce, 

Seveceksen sev artık...', 'Seveceksen sev artık Yeter bu çektiğim,  Acı, bilinmez şu halime Seveceksen sev artık Canımı yitirdin Sevgimi bitirdin Dayanılmaz zulmünle, ...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sev-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığa Doğru', 'karanliga-dogru-omur-torun-3iejg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürüyorum yine bir gece vakti

Yalnız başıma...

Kimseler yok etrafımda

Her yer sessiz, karanlık, 

Yıldızların kaydığı bu gecede

Yine seni düşünüyorum

Gökyüzüne bakıp...

Kimbilir belki sende beni düşünüyorsundur

Uyku girmemiştir gözlerine

Hatta sende hatırlıyorsundur

Geçen güzel günleri...

Özlüyorsundur belki sende beni

İnsan hayal ettikçe yaşar

Bende seni hayalliyorum

Belki bana dönersin diye

Sende seviyorsan eğer beni

Hiç düşünmeden gel sevgilim, 

Çünkü karanlığa doğru giden umutlarıma

Bir güneş gibi doğacaksın...

Geç olmadan gel SEVGİLİM

Bekliyorum! ...', 'Yürüyorum yine bir gece vakti Yalnız başıma... Kimseler yok etrafımda Her yer sessiz, karanlık,  Yıldızların kaydığı bu gecede Yine seni düş...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karanliga-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-omer-avsar-xhw8j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'olmayan zamanın geçmeyen vaktinde

sonsuzluklar ülkesinin ta ötelerinde

hiç kimse ve hiç bir şeyi düşünmeden

yaşamak istermiydin yanında sevdiginde

bir tarafda mutluluk dolaşsa

bir tarafda yarin senle olsa

aşkın şarabı ikinize dolsa

içermiydin elinden sonsuzluga

kavuşmak sevgiliye beklemekse

bin bir güçlüge göğüs germekse

umudu hiç yitirmeden sevmekse

beklermiydin onu ömür geçsede', 'olmayan zamanın geçmeyen vaktinde sonsuzluklar ülkesinin ta ötelerinde hiç kimse ve hiç bir şeyi düşünmeden yaşamak istermiydin yanında sevd...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soru-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Tasviri', 'olumun-tasviri-selami-atan-rf4qc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaşanmış  koca  bir

                                  yıl

yaşanmış  koca  bir

                                   an

 

ve  saat  sonu   vurunca

ısırmaya  hazır  bekleyen

koskoca  bir

                    YIL 

                           AN

            Eylül  1998', 'yaşanmış  koca  bir                                   yıl yaşanmış  koca  bir                                    an   ve  saat  sonu   vurun...', ARRAY['Türk Edebiyatı','Şiir','Selami Atan']::text[], 8.5, '{"poet":"Selami Atan","poet_slug":"selami-atan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olumun-tasviri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun Sonu', 'yolun-sonu-selami-atan-rrmld', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hangi  oyunu  oynadın ki  bize

                       uçurumda  kayboldu  gölgen...

Hangi  toprak  kucakladı   seni...

Zamansız...

Amansız...

Apansız...

Yoksa  sen  miydin 

                       haritalarda  ülkesini  arayan 

                                            avare  sürgün...

Oysa  bir  ülke  gizlenirdi  hep

                          baştan  sona   gökkuşağı...

Bir  solukluk  nefes  bile

                           sende  bulurdu   ölümsüzlüğü...





Biz

Yani  sürgün  yurttaşlar

Yani  hangi  ``Duvar``a  çarpsak

                           soluğu: çığlık

Çığlığın  yankısı: 

                             ÇİRKİN  KRAL...







Güzel  boyalı  çirkeflerin   kıyısında

                                     çirkindin  gerçekten...

Despot  demokratlara  inat

                          kraldın   yine  de...

Utanırdı  ölüm...

Uyanırdı  yaşam...







Biz

Yani  dilsiz  hatipler

Yani  hangi   ``Arkadaş``ı   kucaklasak

                            sohbeti: acı

Acının  ortağı: 

                         ÇİRKİN  KRAL...







Savaşın  karşılığı  barıştı  sende...

Tutsaklığın   özgürlük...

Esaret  bağlarında   gül   olmaktansa

özgürlük   dağlarında  diken  olmaktın...

Güle  bülbül  eyledin  gönlünü...

Dikene  güvercin...







Biz

Yani   tutsak  özgürler

Yani  hangi  ``Umut``a  tutuklu  kalsak

                                     sevdası: güneş

Güneşin  ışığı: 

                         ÇİRKİN  KRAL...







Hoşçakalsız   bir  vedaydı

                                     sahipsiz  el  sallamaların...

Hiçbir  dilde

hiçbir   veda  şarkısında 

                           bulunmaz  mı  izin...

Sonsuzluğun  bir  sonu  yok   muydu  sende...

Bir  krala  yakışır  mıydı

                        gözyaşı  denizinde  boğulmak...

Ölümün  sessiz  mıknatısı

                         nasıl  çekti  kendine  seni...

Azrail`e  mi  yarenlik  edecektin

                          bilinmezler  okyanusunda...







Biz

Yani  güzel  soytarılar

Yani  hangi  ``Sürü``yü  otlatsak

                            korkusu: deprem

Depremin   şiddeti: 

                                  ÇİRKİN  KRAL...







Aşkın  tapınağından  mı  içtin

                o  erişilmez  iksiri...

Yoksa  yarına  mı  sakladın

                 yarım  kalmış  düşlerini...

Sonrası

                  bir  muamma...

Sende  gizli  bir  tarih...   







Biz

Yani  hangi ``Yol``a  çıksak

                       sonu: ölüm

Ölümün  geçersizliği: 

                                        ÇİRKİN  KRAL...', 'Hangi  oyunu  oynadın ki  bize                        uçurumda  kayboldu  gölgen... Hangi  toprak  kucakladı   seni... Zamansız... Amansız.....', ARRAY['Türk Edebiyatı','Şiir','Selami Atan']::text[], 8.5, '{"poet":"Selami Atan","poet_slug":"selami-atan","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/yolun-sonu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müebbet', 'muebbet-ozgur-erdogan-xmism', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölümcül 

            hastayım.

Sebebim sensin, 

ilacım sen.

Bir gün daha yaşayamam

sıcak gözlerini görmesem.

Müebbet 

            mapusum.

Dışarda; 

ama aslında sensiz, 

dört duvar arasında, 

içerdeyim.

Suçum seni sevmek, 

cezam sensizlik.

Ne kadar adını bağırsam da, 

hayat, 

            ölümüne sessizlik... 

    

(11/02/2001 - İzmir)', 'Ölümcül              hastayım. Sebebim sensin,  ilacım sen. Bir gün daha yaşayamam sıcak gözlerini görmesem. Müebbet              mapusum. D...', ARRAY['Türk Edebiyatı','Şiir','Özgür Erdoğan']::text[], 8.5, '{"poet":"Özgür Erdoğan","poet_slug":"ozgur-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/muebbet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Kere', 'kac-kere-cezmi-boztas-wd6uj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaç kere bu haneye baharında kar yağdı, 

Kaç kere soğuk kışta erken çiçekler açtı, 

Kaç kere yaz mevsimi sonbahara karıştı, 

Gün oldu dört mevsimi birtek günde yaşadım.

Cezmi Boztaş          (23.05.2002) Elazığ', 'Kaç kere bu haneye baharında kar yağdı,  Kaç kere soğuk kışta erken çiçekler açtı,  Kaç kere yaz mevsimi sonbahara karıştı,  Gün oldu dört m...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Boztaş']::text[], 8.5, '{"poet":"Cezmi Boztaş","poet_slug":"cezmi-boztas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kac-kere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta', 'usta-cezmi-boztas-6qyvd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nereye kadar sürer bu acı, bu yalnızlık.

Yolun sonu nerdedir? Nerede usta? 

Bitmez mi hiç, kahrolası haksızlık

Huzur nerde kalır? Hak nerde usta? 

Hep bize mi düşer hayatın tozu toprağı

Herkese gonca güller bize yaprağı, 

Kolay mıdır dindirmek akan ırmağı, 

Umman nerde kalır? göl nerde usta? 

Kahır bizim olmuş, keder bizdedir, 

Tükenmiş de hayaller, umut sözdedir.

Ateş düşmüşde yanar.gönül közdedir.

Sevda nerde kalır? Aşk nerde usta? 

Usanmışız artık hayat yolundan, 

Gözde yaş kalmamış, hep ağlamaktan.

Ayak düşman bedene düşmüş takattan.

Takat nerde kalır? güç nerde usta?', 'Nereye kadar sürer bu acı, bu yalnızlık. Yolun sonu nerdedir? Nerede usta?  Bitmez mi hiç, kahrolası haksızlık Huzur nerde kalır? Hak nerde ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Boztaş']::text[], 8.5, '{"poet":"Cezmi Boztaş","poet_slug":"cezmi-boztas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/usta-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-ahmet-kuruoglu-93k84', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Büyüme be küçüğüm büyüme 

Hayat harcar seni

Dönüş yok bir daha bebekliğe

Sonra özlersin eski günleri.

Özlersin misketlerini 

Biberondan süt içmeyi

Özlersin o hiçbirşeyden

Haberinin olmadığı günleri

Üzülüp ezileceksin

Bazen isyan ediceksin

Keşke keşke Allahım

Büyümeseydim diyeceksin.

Dertlerin olacak

Anlatamayacaksın

Kafan karışacak

Anlamayacaksın

İşte küçüğüm sen o zaman

''Büyümenin''

Ne demek olduğunu

''Anlarsın''.

Büyüme be küçüğüm büyüme 

Sen hep küçük kal böyle

Gel büyük sözü dinle 

Kapılma boş hayallere.

Sen bilmezsin küçüğüm 

Hayat ne kadar zalimdir

Yüzündeki masum gülücüğün

Bilki gelip geçicidir.

Neyse, hadi yat beşiğine 

Uyku vaktin geçti yine

Nenni benim güzel bebeğime 

Nenni benim tatlı küçüğüme.', 'Büyüme be küçüğüm büyüme  Hayat harcar seni Dönüş yok bir daha bebekliğe Sonra özlersin eski günleri. Özlersin misketlerini  Biberondan süt ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kuruoğlu']::text[], 8.5, '{"poet":"Ahmet Kuruoğlu","poet_slug":"ahmet-kuruoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kucugum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seveceğim', 'sevecegim-mehmet-ali-cibikli-r3lye', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bensizliğe alış, sen yavaş yavaş, 

Gün gelecek bir gün, ben gideceğim.

Gözlerin hep nemli, neden arkadaş? 

Neyse söyle bana, ben bileceğim.

Alev alev yandı, aşkın ruhumda, 

Deli gibi sevdik birbirimizi.

Doymadık biz bize, sevdik her defa, 

Gönüllere yazdık bu sevgimizi.

Yoruldu bakışlar, yoruldu kalpler, 

Her gün sevişmekten, yorgun düştük biz.

Gün gelir de bir gün, gidersem eğer, 

Yüreğinde saklı kalsın sevgimiz.

Başucumda öyle ağlayıp durma, 

O güzel gözlerden akmasın yaşlar.

Nedir benim halim, nasıldır sorma, 

Sensizlik ruhuma çökmeye başlar.

Sensizlik içimde, bir büyük sancı, 

Sanırım yakında, ben gideceğim.

Ben yolumda yolcu, sen burda hancı, 

Ölünce de seni, çok seveceğim.', 'Bensizliğe alış, sen yavaş yavaş,  Gün gelecek bir gün, ben gideceğim. Gözlerin hep nemli, neden arkadaş?  Neyse söyle bana, ben bileceğim. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevecegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Saklı', 'bende-sakli-mahmut-bingul-aybjr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık tarifsiz bir acı var içimde

Adı bilinmeyen

Gizlenmiş yüreğimin derinliklerine

Belki de yokluğunun acısıdır 

                                         yüreğimdeki.

Boşluğudur sevginin.

Bel ki de 

bağrına gireceğim toprağın

özlemini duyuyorum şimdiden

belki de ayrılığa dayanamayan gönlümün 

taşıyamayacak kadar ağırlaşan anılarından.

Anılar artık soğuk 

Kalbimi titretiyor

Üşüyorum! 

Bende saklı bir şeyin kalmasın senin

üşütüyor beni 

kalbimi titretiyor.

Dayanamıyorum! 

Dayanamıyorum! 

                      

                              Êylül 2001', 'Artık tarifsiz bir acı var içimde Adı bilinmeyen Gizlenmiş yüreğimin derinliklerine Belki de yokluğunun acısıdır                            ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bende-sakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzellik', 'guzellik-sair-konficyus-pwce2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herşeyin bir güzelliği vardır, herkes görmesede...', 'Herşeyin bir güzelliği vardır, herkes görmesede......', ARRAY['Türk Edebiyatı','Şiir','Şair Konfiçyüs']::text[], 8.5, '{"poet":"Şair Konfiçyüs","poet_slug":"sair-konficyus","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/guzellik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Değil', 'sana-degil-gokhan-ozmen-vy7ew', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana değil sitemlerim kendime

Ağlıyor gözlerim dermansız derdime

Ayrılık kor gibi düştü

Aşk dolu yüreğime

Kuytu köşelerde ağlamam sana değil

Her şarkıda hatırladığım sen değilsin

Kalbimin sahibi sen olamazsın

Sana değil arayışım sana değil

Dolaşırım ararım divane 

Benim sevdiğim dünyada birtane

Özlem duyuyorum o eski günlere

Sana değil özlemim sana değil

Hasretim sana değil sevdama

Girmeye korkuyorum artık boş odama

Eremedim bir türlü muradıma

SANA DEĞİL kahroluşum SANA DEĞİL............', 'Sana değil sitemlerim kendime Ağlıyor gözlerim dermansız derdime Ayrılık kor gibi düştü Aşk dolu yüreğime Kuytu köşelerde ağlamam sana değil...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Özmen']::text[], 8.5, '{"poet":"Gökhan Özmen","poet_slug":"gokhan-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-degil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-arif-erdem-oktay-adpuw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kandırmıyor ciğerimi dost

İçtiğim her bir sigara

Ve aldatmıyor artık arkadaş sohbetleri bile

Ben şimdi kafamı hangi taşlara

Yüreğimi hangi yollara vurayım

Ne yapayımda seni unutayım

Artık sende biliyorsun 

Ben sevmeyi sende öğrendim

Yalnızlığı senden sonra.................', 'Kandırmıyor ciğerimi dost İçtiğim her bir sigara Ve aldatmıyor artık arkadaş sohbetleri bile Ben şimdi kafamı hangi taşlara Yüreğimi hangi y...', ARRAY['Türk Edebiyatı','Şiir','Arif Erdem Oktay']::text[], 8.5, '{"poet":"Arif Erdem Oktay","poet_slug":"arif-erdem-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevmek-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harabım', 'harabim-sureyya-turkmenli-91fpv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gene sırılsıklam olmuşum dinmeyen yağmurlardan, 

ne yardan vefa var, nede gelen bahardan, 

yalnız hatıralar kalmış çekip giden o yardan, 

    gün geçtikçe büyüyor içimde ıstırabım

    bu gece özleminle biraz daha harabım.

Beklerken seni, gülleri soldu elimdeki demetin, 

çok bekledim, çok özledim, ama sen gelmedin, 

anladımki şiir gözlüm sen sevmedin, özlemedin, 

    hasretinle tükendi kadehimde şarabım

    bu gece özleminle biraz daha harabım.

Umutlara tutunmak bu acılar denizinde, 

ve aramak seni, gökyüzünde, yer yüzünde, 

Bu şehrin her köşesinde, gecesinde, gündüzünde, 

     ben bulamadım onun için perişanım

     bu gece özleminle biraz daha harabım.

Gönlüm özlenen istasyona varamadan yoruldu, 

kapı, kapı, aşk dilendi, her kapıdan kovuldu, 

hangi dala el attıysa, güz gelmeden kurudu, 

     anladım_ki bu dünyada, sen bana, ben sana haramım

      bu gece özleminle biraz daha harabım.

Sen gideli oynamamış yerinden hatıraların taşı, 

sen gideli kurumamış gözlerimin hicran yaşı, 

sen gideli sensiz kaldım  budur gönlüm telaşı, 

     sen gideli sevemedim, perişanım, hüsranım

      bu gece özleminle biraz daha harabım...', 'Gene sırılsıklam olmuşum dinmeyen yağmurlardan,  ne yardan vefa var, nede gelen bahardan,  yalnız hatıralar kalmış çekip giden o yardan,    ...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Türkmenli']::text[], 8.5, '{"poet":"Süreyya Türkmenli","poet_slug":"sureyya-turkmenli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/harabim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-omur-torun-rkqro', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir günüm daha geçti yar sensiz

Bu nasıl yaşamak söyle; kadersiz

Ölürüm yolunda yar şimdi sensiz

Bırakıp giderken hiç mi sevmedin

Nasıl unuturum geçen günleri

O tatlı bakışlı kara gözleri

Aşkını, kalbini o güzel sözleri

Bırakıp giderken hiç mi sevmedin

Neyleyim ben bu alemde sensiz

Bu nasıl sevmekti söyle; şerefsiz

Şiirler yazarım ben şimdi sensiz

Bırakıp giderken hiç mi sevmedin', 'Bir günüm daha geçti yar sensiz Bu nasıl yaşamak söyle; kadersiz Ölürüm yolunda yar şimdi sensiz Bırakıp giderken hiç mi sevmedin Nasıl unut...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-omur-torun-3ncci', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlıklar içinde gizemli bir rüya

Sonsuzluğa giden bir yol sanki, 

Hiç bilinmeyen bir sır, 

Ulaşılmayan bir yer, 

Seni görüyorum şimdi

Senin olmadığın o yerde

Bu garip ıssız gecede...

Yarım kalan şiirlerim gibi

Bu rüyada bitti ne yazık! 

Sana dokunamadan

O güzel gözlerine bakamadan

Bu rüyada bitti işte!', 'Karanlıklar içinde gizemli bir rüya Sonsuzluğa giden bir yol sanki,  Hiç bilinmeyen bir sır,  Ulaşılmayan bir yer,  Seni görüyorum şimdi Sen...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruya-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-omur-torun-mekwn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gece vakti yine

 Dalmıştım hayallere

 Hatırlayıpta seni

 Ağlamışım öylesine

 Canlandı hayallerimde

 O tatlı bakışların

 Süzüldü göz yaşlarım

 Karanlığın içinde

 Bilsen nasıl sevmişim

 Seninle olan herşeyi

 Çiçek gibi açmışsın 

 Kurumuş yüreğime', 'Bir gece vakti yine  Dalmıştım hayallere  Hatırlayıpta seni  Ağlamışım öylesine  Canlandı hayallerimde  O tatlı bakışların  Süzüldü göz yaşl...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gece-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam Seni', 'unutamam-seni-omur-torun-n8v8p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep hayallerimde gördüğüm

O güzel gözlerini

Unutmak mümkün mü söyle

Seni bir anda böyle! 

Dayanmak çok zor, senin yokluğuna

Unutmak bir yana, o güzel gözlerini

Yaşamak seninle bir hayal oldu

Sev beni birtanem unutamam seni...', 'Hep hayallerimde gördüğüm O güzel gözlerini Unutmak mümkün mü söyle Seni bir anda böyle!  Dayanmak çok zor, senin yokluğuna Unutmak bir yana...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unutamam-seni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözbebeğim', 'gozbebegim-omur-torun-59eo3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu şiiri yazarken, 

Yine sen hayalimde

Yıldızların ışığı altında

Ağlıyorum sessizce

Hatırlıyormusun; 

O son bakışmalarımızı, 

Deli dolu anılarımızı, 

Konuştuğumuz son sabahı...

İşte o zaman; 

Dünyalar yıkılmıştı üzerime

Hançer saplamıştın yüreğime

Hatırlıyormusun gözbebeğim.

Anlıyormusun beni; 

Sensiz geçen günlerimi

O kaybolan yıllarımı

Biliyormusun gözbebeğim...', 'Bu şiiri yazarken,  Yine sen hayalimde Yıldızların ışığı altında Ağlıyorum sessizce Hatırlıyormusun;  O son bakışmalarımızı,  Deli dolu anıl...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozbebegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Riyakar', 'riyakar-suleyman-apaydin-e3wd6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ettigin duanin bir hükmü yokki

Gönlün yaptigini onaylamazsa

Seni bagislayan tanri bulunmaz

Kirdigin gönüller onarilmazsa

Camide cumada en ön saftasin

Dilinde bir dua riyalardasin

Senin gibisinden Tanri saklasin

Bir yoksul eline düsecek olsa

Kafir ilan ettin cümle alemi

Parselleyip sattin kat kat cenneti

Her aksam yedigin bir yoksul eti

Dogruluk taslarsin bir soran olsa

Verdigin fetvalar hep cikarina

Sözün gecmez kizin ile karina

Tek namuslu benim diyecen amma

Boynuzlar kapidan gececek olsa', 'Ettigin duanin bir hükmü yokki Gönlün yaptigini onaylamazsa Seni bagislayan tanri bulunmaz Kirdigin gönüller onarilmazsa Camide cumada en ön...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/riyakar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Günlerim', 'sensiz-gunlerim-omur-torun-phwub', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz günlerim geçmiyor biliyormusun.

Sabahları kalkıyorum

Elimi yüzümü yıkıyorum

Ayna''ya baktığımda

Hep seni görüyorum

Üstümü giyinirken bile

Seni düşünüyorum

Ve her an ismin dilimde...

Kahvaltımı yaparken

Televizyon seyrederken

Sen geliyorsun aklıma 

Ve başlıyorum ağlamaya...

Okula gidiyorum

Aklımda yine sen

Keşke yanımda olsan diyorum

Gözlerine baksam

SENİ SEVİYORUM desem

Aşkımı anlatsam diyorum sana, 

Öğretmen kaldırıyor

Soru soruyor, bilemiyorum

Ama ne bilsinki hep seni düşünüyorum, 

Yokluğundan acı çekiyorum...

Ve sonunda ders bitiyor

Eve geliyorum, 

Hep seni görmek umuduyla

Pencerene bakıyorum

Yoksun...

Bir günüm daha sensiz, 

Ve çaresiz olarak geçiyor...', 'Sensiz günlerim geçmiyor biliyormusun. Sabahları kalkıyorum Elimi yüzümü yıkıyorum Ayna''ya baktığımda Hep seni görüyorum Üstümü giyinirken b...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sensiz-gunlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilsen', 'bir-bilsen-omur-torun-reu2p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şehrin bütün sokakları

Dar geliyor artık bana

Her köşe başında

Düşlüyorum hayalini

Pişmanlıklarla dolu gecelerde

Yine seni istiyorum

Bütün umutsuzluklarıma inat

Yine seni seviyorum...

Zifiri karanlığın içinde, 

Hafiften esen rüzgar

Ve göz yaşlarımla, 

Dökülen yağmur

Ağlıyor benimle, 

O ıssız gecede...

Bir bilsen seni nasıl sevdiğimi, 

Uykusuz gecelerimi

Anlasan sevgisiz kalmanın

Acısını...

Bir bilsen sevgilim!', 'Bu şehrin bütün sokakları Dar geliyor artık bana Her köşe başında Düşlüyorum hayalini Pişmanlıklarla dolu gecelerde Yine seni istiyorum Bütü...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-bilsen-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmiştim', 'seni-sevmistim-omur-torun-9pwd3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sevmiştim ben, 

Çiçeğin suyu sevdiği gibi

Seni sevmiştim ben, 

Ferhatın  şirini sevdiği gibi

Öylesine sevmiştim ki seni, 

Etin tırnaktan ayrılamayacağı gibi

Sevgin içimi ısıtıyor, 

Garip bir huzur veriyor bana

Seni sevmiştim sevgilim

Öylesine sevdim ki; 

Bir günüm bile geçmiyor sensiz

Hayal ederim hep senle yaşayacaklarımızı

Bilmezdimki bu hayallerle ağlayacağımı

Bilmezdimki bu çilelerle haykıracağımı

Öylesine kapıldım ki güzelliğine

Kendime gelemedim...

Öyle yücesinki gözümde

Ben bile ulaşamıyorum sana

Öyle yücesinki sevgilim

Ben bile göremiyorum seni...', 'Seni sevmiştim ben,  Çiçeğin suyu sevdiği gibi Seni sevmiştim ben,  Ferhatın  şirini sevdiği gibi Öylesine sevmiştim ki seni,  Etin tırnakta...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-sevmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz 2', 'sensiz-2-omur-torun-w7krn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmem ki sensiz nasıl yaşarım

Kalbimdeki bu ateşle ne yaparım

Ayrılığın bana zor geldi ama

Kararlıyım ben seni unutmayacağım

Sensiz, sensiz yanıyor gönlüm

Ne zaman, ne zaman sever bu gönlün

Ne olurdu ayrılmasaydık

Sevseydik birbirimizi fani hayatta

Hiç hesapta yoktu ayrılık bize

Bir anda gittin sözümüz varken.', 'Bilmem ki sensiz nasıl yaşarım Kalbimdeki bu ateşle ne yaparım Ayrılığın bana zor geldi ama Kararlıyım ben seni unutmayacağım Sensiz, sensiz...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensiz-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değdimi', 'degdimi-suleyman-apaydin-n6by6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte geldik gidiyoruz

Dönüp baktın mı ardına

Bunca döküp kırdıkların

Değdi mi ki yaptığına

Selam vermedin bir kula

Katkın olmadı yoksula

Battın çıkar çamuruna

Değdi mi ki battiğına

Burnun değdi Kafdağına

Küstün sağına soluna

Var mı tek dostun dünyada

Ettiğine değdi mi ya', 'İşte geldik gidiyoruz Dönüp baktın mı ardına Bunca döküp kırdıkların Değdi mi ki yaptığına Selam vermedin bir kula Katkın olmadı yoksula Bat...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/degdimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Öğrendim', 'senden-ogrendim-omur-torun-j43a5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden öğrendim; 

Sevipte, sevilmemeyi

Senden öğrendim; 

Ağlayıpta gülmemeyi

Senden öğrendim; 

Hayatın acı gerçeklerini, 

Senden öğrendim; 

Özleyipte kavuşamamayı

Her türlü ızdırapları

Senden öğrendim sevgilim...', 'Senden öğrendim;  Sevipte, sevilmemeyi Senden öğrendim;  Ağlayıpta gülmemeyi Senden öğrendim;  Hayatın acı gerçeklerini,  Senden öğrendim;  ...', ARRAY['Türk Edebiyatı','Şiir','Ömür Torun']::text[], 8.5, '{"poet":"Ömür Torun","poet_slug":"omur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/senden-ogrendim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-suleyman-apaydin-cg4p5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir hata etti ki gönül

Dayanilir gibi degil

Ben derim ki vaz gec gönül

O der bana mümkün degil

Kolay degil zordur isim

Iyi degil bu gidisim

Basima bir dert almisim

Cekilecek bela degil

Aldirmayin feryadima

Gitmez bu cile yadima

Sitem uslanmaz gönlüme

Derdim yardan yana degil', 'Bir hata etti ki gönül Dayanilir gibi degil Ben derim ki vaz gec gönül O der bana mümkün degil Kolay degil zordur isim Iyi degil bu gidisim ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sitem-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Uçar Aşk Kalır', 'soz-ucar-ask-kalir-mustafa-ocak-3xvn5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kimin yazgisina murekkep olsam

onceme ve sonrama ayrilir sayfalari

fotograflar kadar ciddi ve anlamlidir

ucurulan sozleri kalan asklari

her yanlis kendinden doner

reddetmek icin teyit gerekse de

zamanin askisinda sallanir

sebeplere borclanmaksizin yasananlar

yasananlar anilmakla yoksul ve bicare

bir sabah unutulmus bir yuzle

gunesin dogum gunune

               davetsiz katilirlar', 'kimin yazgisina murekkep olsam onceme ve sonrama ayrilir sayfalari fotograflar kadar ciddi ve anlamlidir ucurulan sozleri kalan asklari her ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ocak']::text[], 8.5, '{"poet":"Mustafa Ocak","poet_slug":"mustafa-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soz-ucar-ask-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertli Gelin', 'dertli-gelin-suleyman-apaydin-mrv0s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yadellerde bir çaresiz gelinim

Tanrıdan gayrısı bilemez halim

Ben mi çok güçsüzüm gurbet mi zalim

Kendi kaderimden kaçamam anam

Eksik olsun arabası parası

Viran olsun Almanya''sı Gera''sı

Bizim köye benzemiyor burası

Derdimi kimseye açamam anam

Almanya denilen umut kapısı

Mermer sutunları taştan yapısı

Yollarımı bağlar gümrük kapısı

Sınırdan kağıtsız geçemem anam

Dıs kapıya vurup gider kilidi

Yitirdim ben kimliğimi dilimi

Bekliyorum bir acısız ölümü

Kapıları kırıp kaçamam anam', 'Yadellerde bir çaresiz gelinim Tanrıdan gayrısı bilemez halim Ben mi çok güçsüzüm gurbet mi zalim Kendi kaderimden kaçamam anam Eksik olsun ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dertli-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akla Çıkan Söz', 'akla-cikan-soz-mustafa-ocak-2bix8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aklim delirmenin tarihi

dallarindan kenetli

gogun bileklerine

yapraklarini desenleyen

uzak iklimler

sen oluyorsun yagmurun adiyla

ve ruzgarsa sana donuyor

senden estigi zaman

dusu dusuncenin sesiyle

birgun cagirdigimda

havai fisekler takilacak

yillarimin ardina

koklerim yeti$ecek

toptagin nefesine

ya$li bir sen olacagim

genc bir ciglik agzimda', 'aklim delirmenin tarihi dallarindan kenetli gogun bileklerine yapraklarini desenleyen uzak iklimler sen oluyorsun yagmurun adiyla ve ruzgars...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ocak']::text[], 8.5, '{"poet":"Mustafa Ocak","poet_slug":"mustafa-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/akla-cikan-soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım (1)', 'kadinim-1-mustafa-sureyya-sezgin-3h1dp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duygularını

İçine gömüyorsun, 

Üzülüyor, 

Kıskanıyorsun

Ve bazen de

Hırçınlaşıyorsun.

Nasıl düşünürsün

Senden vazgeçeceğimi, 

Gönlümü

Başkalarına verebileceğimi? 

O kadar kolay mı

Yeni dünyalar kurmak

Ve doyumsuz hayalleri, 

Gerçek yerine koymak? 

Ne olur ağlama artık

Akan göz yaşlarına yazık.

Masum bir güzellikse özlenen, 

Çocuksa ve duruysa duygular

Gitgide kapanıyorsa yarınlar

Bu özlemleri

Saklamanın ne yararı var? 

Kırılmamalı onurun.

Düşündükçe diyorum ki, 

Bir sanattır

Seninle yaşamak inan! ..

Yoğunlaşmış duygularda

Yaşanır sevinçlerimiz

Ardından gelen kahırlarda

Çiçek açar mutluluklar.

Kadınlık gururun, 

Belirgenleşirken an be an

Yağmur olur, 

Sel olur göz yaşların

Ve bora olur ardından öfken! ..

Neler geçer kafandan

Neler düşünürsün bilmem ben.

Seni sonsuz seviyorum inan

Hiç karşılık beklemeden.

Bedeninde uzantım, 

Paylaştığım yaşantım, 

Sen benimsin kadınım! ..

(İstanbul,22.11.1996)', 'Duygularını İçine gömüyorsun,  Üzülüyor,  Kıskanıyorsun Ve bazen de Hırçınlaşıyorsun. Nasıl düşünürsün Senden vazgeçeceğimi,  Gönlümü Başkal...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kadinim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Polisi', 'turk-polisi-huseyin-duzbasan-pn93w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Asker sınırda bekçi

Polisim yurt içinde

Türkün yenilmez gücü

Vardır onun gücünde

Gece gündüz demeden

Yılmadan görev yapar

Ulusuyla el ele

Oluyor çelik duvar

Soğuk sıcak tanımaz

Uzaklar ona yakın

Atamın izindedir

Hata yapmayın sakın

Mal ve can güvenliği

Hep onlardan sorulur

Türk polisi ne bıkar

Ne işinde yorulur

Kanunsuzlara karşı

Mağdurlardan yanadır

Şehitlik son mertebe

Herşeyi vatandır

Türk polisi çok yaşa

Sana güveniyoruz

Bizim için sen varsın

Seni çok seviyoruz

                  15.05.2002', 'Asker sınırda bekçi Polisim yurt içinde Türkün yenilmez gücü Vardır onun gücünde Gece gündüz demeden Yılmadan görev yapar Ulusuyla el ele Ol...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Düzbasan']::text[], 8.5, '{"poet":"Hüseyin Düzbasan","poet_slug":"huseyin-duzbasan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/turk-polisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-fusun-aydinci-ye929', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ritmi bozmadan yaşayacaksın.

Üzüntüler de sevinçler kadar kısa süreli olacak.

Herşeyin bir sebebi olduğunu kabulleneceksin.

Gelmeler kadar gitmelerden de keyif alacaksın.

Tıpkı günün batışı, yağmurun rengi gibi.

Sıkıntılar olacak, üstesinden geleceksin, 

yüreğin sızlayacak zaman zaman

küçük bir çocuğun gülümsemesiyle son bulacak.

Mucizelere inanacaksın.

Yaşam böyle devam edecek.

Notalardaki ahenk gibi............', 'Ritmi bozmadan yaşayacaksın. Üzüntüler de sevinçler kadar kısa süreli olacak. Herşeyin bir sebebi olduğunu kabulleneceksin. Gelmeler kadar g...', ARRAY['Türk Edebiyatı','Şiir','Füsun Aydıncı']::text[], 8.5, '{"poet":"Füsun Aydıncı","poet_slug":"fusun-aydinci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasam-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süleymaniye', 'suleymaniye-ekrem-kaftan-rnp6j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vururken kubbelere fecrin kızıl nurları

Semâdan nice melek inip aştı surları

Her birinin gâyesi bir tek Süleymâniye

Arttı kanat sesleri hep sâniye sâniye

Gafletten uzak gözler abdestlerle yıkandı

Bu saatte yeryüzü ilâhî nûra kandı

Açıldı cümle kapı meleklerle, beşere

Değmeden yürüdüler, ayaklar sanki yere

Uçtu minarelerden kuşlar gümüş kanatla

Geldi yine Kânûnî muhteşem saltanatla

Oturdu en ön safta mihrâbının önüne

Beş asırdır hazırdı böyle kudsî bir güne

Ardında cihanları titreten büyük ordu

Tekbîrler getirerek göğü titretiyordu

Sokuldu ak sakallı bir nefer ta yanına

Dedi; Süleymâniye, sunduğum fermanına

Asırlardır bakarım türbemden eserime

Halbuki hasretim ben mezardaki serime

Bu bayram saatinde halimi arz ederim

Ferman buyur Sultân’ım başsız nere giderim

Şaşırıp Ulu Hâkân, Sinan’ın sözlerine

Sual dolu gözlerle baktı tâ gözlerine

Gördü ki mîmârının başı ayrı vücuddan

Gelmişti sanki Sinan gözü yaşlı Uhud’dan

Ferman etti “Ey Mimar gel otur sağ yanıma

Gücü yetse bu millet girer benim kanıma

Bu bayram saatinde hâlini arz et Rabb’e

İnler senin derdinden hem âsumân, hem kubbe”

Muhteşem Süleyman’ın gözlerinde yaş vardı

Yere düşse bir damla mükevvenât ağlardı

Kapandı secdelere beş asır sonra yine

Alemler kapanırdı Süleyman’ın pâyine

Seyrederken bu hâli müezzin mahfilinden

Döküldü nice şiir bu şâirin dilinden

Hani kalkmıştı perde üstad Yahya Kemâl’e

Getirdi Rabbim beni Üstad’daki o hâle

Açıldı birer birer nice şanlı zamanlar

Geçti ordu başında, Yavuz’lar, Süleyman’lar

Söğüt’ten açılan yol, aştı dağlar, denizler

Şahadet hasretiyle parlıyordu benizler

Üsküdar önlerinde kişneyen yağız atlar

Mohaç’a uçmak için takındılar kanatlar

Girdi bir gece vakti Niğbolu’ya Yıldırım

Düştü Sırp’ın kalbine ateş yüklü yıldırım

Yirmi bir yaşındaki Fatih’in sevdâsıyla

Yol verdi cümle surlar şuh dilber edâsıyla

Tuna’nın sularında serinledi gâziler

Şahadetin zevkinden hep inledi gâziler

Daldıkça küffâr ile akıncılar her cenge

Kavuştu cümle cihan nur dolu bir âhenge

Hasretti yedi tepe kubbelerin aşkına

Kubbeler yükselirken girmedi kılıç kına

Yürürken ordu-millet Avrupa’nın kalbinde

Kubbeler yürüyordu ayağının dibinde

Eğildi karşısında cümle Haç’lar hilâlin

Tattı çan kuleleri acısını melâlin

Şanlı Süleymaniye ufkunda İstanbul’un

Yükseldi elleriyle nefer esvaplı kulun

Yalnız kubbeler vardı parlayan ufuklarda

Adalet gördü cihan o mağrur kavuklarda

Karadan bu yürüyüş süredursun Nemçe’ye

Denizlerde Barbaros baş eğdirdi kaç beye

Leventlerin nârâsı karıştı top sesine

Geçti bu top sesleri göklerin ötesine

Rüzgârlar teslim oldu Fetih’in esrârına

Yelken açtı Barbaros İstanbul diyârına

Bergüzâr diye sundu, Tunus’u, Cezayir’i

Gülzâr oldu Sultân’a, Adalar’ın her biri

Yemen’den Estergon’a koşan atlar çatladı

Barbaros donanmayla ufukları atladı

Ne haşmetti Allâh’ım dininde bu yükseliş

Titretirdi küffarı akın akın her geliş

Varna’dan Estergon’a, Eğri’den ta Uyvar’a

Nal sesleri akardı gökleri yara yara

Viyana önlerinde duyulan top sesleri

Kesti cümle âlemde korkudan nefesleri

Bu orduydu Allah’ın övdüğü Türk Ordusu

Bu orduydu küffârın bildiği tek korkusu

Nerede kurulursa Humâyûn namlı otağ

Saadet doluyordu yaşanacak cümle çağ

Taşınca Tekbîr sesi kubbelerden göklere

Tarihin perdesinden çekilip indim yere

Kaç asırdır bu Tekbîr göz yaşıyla çağlıyor

Süleyman hasretinden cümle ümmet ağlıyor

Devlet-i Âli Osman el çekeli dünyadan

Çekilmiyor bir lâhza küfrün eli dünyadan

Afganistan, Filistin, Çeçenistan kan dolu

Kutlu Süleymaniye bu sabah hicran dolu

Bir bayram sabahının neş’esinden eser yok

Ya Rabbi bu dünyada mü’mine neden yer yok

Sordum Ulu Mabed’de bu suali kendime

Dinlediğim bu Tekbir neden hep lime lime

Ne zaman gelecektir bir Süleyman âleme

Ne zaman son verecek Ümmet’teki eleme

Ulu mabed hissedip içimdeki azâbı

Gösterdi ihtişamla Hakk’tan inen kitâbı

Dedi, benim bânîm de mîmârım da kul idi

Onların nazarında hazineler pul idi

Sarılıp Yaradan’ın İlâhî kitâbına

Düşmediler hiç biri dünyanın hesâbına

Şimdi yatmaktadırlar dizlerimde her biri

Zannetme ki ölüdür, asıl onlardır diri

Bu bayram sabahında uyandırıp ümmeti

Hakk’a iltica ile isteyip de rahmeti

Can verip Hakk yolunda şahâdet nedir bilin

Hak zafer va’d ediyor, bana zaferle gelin...

16 Aralık 2001

Ramazan Bayramı’nın 1. Günü

1 Şevval 1422

Saat: 16.02', 'Vururken kubbelere fecrin kızıl nurları Semâdan nice melek inip aştı surları Her birinin gâyesi bir tek Süleymâniye Arttı kanat sesleri hep ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kaftan']::text[], 8.5, '{"poet":"Ekrem Kaftan","poet_slug":"ekrem-kaftan","theme":"Türk Şiiri","is_hero":false,"total_lines":110,"source_url":"https://www.antoloji.com/suleymaniye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar ve İstanbul', 'bahar-ve-i-stanbul-ekrem-kaftan-m6yhl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Irmakların altında başka ırmaklar akar

Pervane olur gökler bir kerre görmek için

Bu şehre dalga dalga nice bayraklar akar

Uçuşur kubbelerden bir zerre görmek için

Erguvanlar sabırsız ve laleler mağrurdur

Sümbüller mütebessim, menekşeler yorgundur

Gül her zaman taptaze ve daima vakurdur

Gönüller yârden önce İstanbul’a vurgundur

Kucaklayıp nice gül güler Süleymaniye

Abdest alan kulların gözyaşı kubbe olur

Nasib olmaz elbette böyle aşk her faniye

O küçük türbesinde Sinan’ım habbe olur

Bırak biraz ağlasın başını eğip yere

Kaç asır kan damlatan muhtedi Ayasofya

Şahiddir Sultanahmed ondaki bu kedere

Cennet Gül’ü Fatih’in mabedi Ayasofya

Güvercin duaları yükselen Eyyüb Sultan

Hakk’a teslim olarak tevazu üzre bekler

Eğilir huzurunda her cülusda bir Hakan

Tarihi tesbih gibi dizerek gelecekler

Uzakta Çamlıca’yla yarışır Yeni Cami

“O senin iki tepen bir kubbeme dar gelir” 

Gün olur deryalara karışır Yeni Cami

Ezan sesi duydukça sanki bana yâr gelir

Hâlâ terlemektedir ayakta Yavuz Selim

Kim bilir beklediği Ol Resul-i Zîşan’dır

Feyz almaz mı Allah’ım o mes’ud kuldan dilim

İbret verip ümmete bir an olsun utandır

Fatih’in medresesi yıkılır hicran ile

Ne kuş vardır damında ne Kuşçu göğe bakan

Buluşmaz kaç asırdır Sada-ı Kur’an ile

Her hücresi karanlık bulunmaz kandil yakan

Özletir ahireti yemyeşil mezarlıklar

Eskimez yazıların altında kimler yatar

Hükümsüzdür toprakta her türlü pazarlıklar

İmanlı gönüllere dem-be-dem ibret katar



Cehennem korkusu mu ağlatır çeşmeleri

Kalmamış bir damla yaş o â’mâ gözlerinde

Hangi sevda gönülden dağlatır çeşmeleri

Kesilmiş sineler taş, o â’mâ gözlerinde

Çeşmelerin gözüne sürünsün bir gonca gül

Bağrındaki yarayı râyihası kapatsın

Açılsın ufuklarda sulara doyunca gül

Ve gidip ol Ravza’da Pa-yi Resûl’e yatsın

Gözleri ufuklarda aşkı arar Mihrimah

Sarılıp ağlayarak Celi Sülüs hatlara

Yeniden doğar belki güneş gibi her sabah

Bırakıp gitmez bizi binip iyi atlara

Bekler Şeyh Hamdullah’ı elinde hokka ile

Bir ibadet zevkinde Veli Sultan Bayezid

Sığmamış hiçbir zaman ondaki sevda dile

Kalem gibi yaralı ağlayan Can Bayezid

Bu güzel mabedleri cennete al Ya Rabbi

Savrulmasın o günde hallaç pamuğu gibi

Cennetlik kullarını zikrine Sal Ya Rabbi

Sen’sin elbet güzelin, güzelliğin Sahibi', 'Irmakların altında başka ırmaklar akar Pervane olur gökler bir kerre görmek için Bu şehre dalga dalga nice bayraklar akar Uçuşur kubbelerden...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kaftan']::text[], 8.5, '{"poet":"Ekrem Kaftan","poet_slug":"ekrem-kaftan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/bahar-ve-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil De Öyle Git', 'bil-de-oyle-git-erol-elmas-fwqb0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinden akan yaşlar dinince

Bir de benimkini sil de öyle git, 

Yüreğinde yanan ateş sönünce

beni de kalbinden sil de öyle git.

Ömrüne ömrümden günler vereğim

Aşkın bahçesinden güller dereğim

Elleri sevmesin sefil yüreğim

Sen gel, lime lime dil de öyle git.

Ben iki rahmetten birini seçtim, 

gönül kefenimi elimle biçtim

Aşkının uğruna sırattan geçtim

Sen bunu böylece bil de öyle git.', 'Gözlerinden akan yaşlar dinince Bir de benimkini sil de öyle git,  Yüreğinde yanan ateş sönünce beni de kalbinden sil de öyle git. Ömrüne öm...', ARRAY['Türk Edebiyatı','Şiir','Erol Elmas']::text[], 8.5, '{"poet":"Erol Elmas","poet_slug":"erol-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bil-de-oyle-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleme', 'bekleme-talip-aydemir-79hbd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşünme beklerken yaz kuraklığını

Dağların arkasında yağmurlar yağıyor

Düş ülkesinde bir efendi yapmış konağını

Yüzünde beklemek adına şarkılar

Islatmış toprağı ağlamaklı göz

Bir toprak kokusu sarmış havayı

Savaşlar içinde ölümü bekliyor çoçuk

Sarmış kendisini bekleme örtüsüne...

........................................................

..........................................................', 'Düşünme beklerken yaz kuraklığını Dağların arkasında yağmurlar yağıyor Düş ülkesinde bir efendi yapmış konağını Yüzünde beklemek adına şarkı...', ARRAY['Türk Edebiyatı','Şiir','Talip Aydemir']::text[], 8.5, '{"poet":"Talip Aydemir","poet_slug":"talip-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bekleme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp YIldız', 'kayip-yildiz-yilmaz-erdogan-60459', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonbaharın serin esen rüzgarlarında

Sabahın güneşi, akşamın ayışığında

Arıyorum! 

Kaybettim geceyi ve gündüzü

Yokluğun acıydı hançer misali

Sözlerin acıydı kurşun misali

Ahirette arar bulurum seni

Kendimi unutup unutmam seni', 'Sonbaharın serin esen rüzgarlarında Sabahın güneşi, akşamın ayışığında Arıyorum!  Kaybettim geceyi ve gündüzü Yokluğun acıydı hançer misali ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kayip-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yara', 'yara-mustafa-engin-karatay-35ohs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bayramlar dizildi, geçti sırayla 

Değişti nöbetler, sıtma-sârayla 

İnledim, sızlandım hep bu yarayla 

Eridim kahrımdan, mumlara döndüm 

Rüzgârda savrulan kumlara döndüm 

Devrilen Mevsimler, ağıtlar yaktı 

Kışlarım, Bahar''a ümîdsiz baktı 

Biri, diğerine enkaz bıraktı 

Baykuşlar tüneyen, damlara döndüm 

Azrâil görmeyen sâmlara döndüm 

Yaylıma tutuldum kederle, gâmla 

Uyudum sancıyla, uyandım kam''la 

Kan doldu yüreğe hep damla damla! .. 

Güneş''i doğmayan tanlara döndüm 

Vîrâne, harâbe hanlara döndüm 

Dağdayûş İfrit''tir, mislime nedret 

Bir nefes içinde, Bin tâne nefret 

Ya sus, Eyyûb gibi sâdece sabret; 

Ya da İblîs gibi, ha bire küfret! 

Arınmaz, pâklanmaz rânlara döndüm 

Kızıl çanak dolu kanlara döndüm... 

25.02.2002    Münih    01: 35', 'Bayramlar dizildi, geçti sırayla  Değişti nöbetler, sıtma-sârayla  İnledim, sızlandım hep bu yarayla  Eridim kahrımdan, mumlara döndüm  Rüzg...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yara-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayıs yağmuru', 'mayis-yagmuru-mustafa-ozke-2m8vz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece Adana''ya yağmur yağdı 

Mayıs''ın ortasında da yağmur mu yağarmış 

Demek ki yağarmış 

Hani Nisan yağmurlarını bilirdim 

Hani Nisan yağmurlarında ıslanan aşıkları bilirdim 

Demek ki Mayıs''ta da yağmur yağarmış 

Demek ki Mayıs''ta da yağmur vururmuş cama 

Ama ne yalan söyleyeyim 

Aşıkları gezerken görmedim pencereden 

Yağmurda gezmek Nisan''a mı ait nedir 

Yoksa aşıkların Nisan''da gezmesi nedendir', 'Dün gece Adana''ya yağmur yağdı  Mayıs''ın ortasında da yağmur mu yağarmış  Demek ki yağarmış  Hani Nisan yağmurlarını bilirdim  Hani Nisan ya...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mayis-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***İnsanım', 'i-nsanim-dilsade-gungor-zr4r8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya ağlıyorum katılasıya

Ya gülme krizindeyim

Ya uçuyorum düşlerimin kanadında

Ya kabuslarımın dehlizindeyim

Ya balık sırtında gözlerinin renginde

Ya kelebek kanadında saçlarının sarı çiçeğindeyim

Ya değneğin iki ucunda 

Ya hurilerin kucağındayım

Ya lanet yiyor kin kusuyorum

Ya meleklerin duasındayım

Ya çok sevdim ölesiye

Ya ölesiye nefret ettim

Aşırı uçlarda gel-gitlerdeyim

Boş ver anlama tanıma sevme

Kendimi anladım tanıdım sevdim mi? 

Yalnızlığın yüreğinde unutulmuş

Yüreğimin rüyalarında kaybolmuşum

Baş edemezsin ne akıllı ne deliyim

Sorarsan gurur girdabına gömülmüşüm', 'Ya ağlıyorum katılasıya Ya gülme krizindeyim Ya uçuyorum düşlerimin kanadında Ya kabuslarımın dehlizindeyim Ya balık sırtında gözlerinin ren...', ARRAY['Türk Edebiyatı','Şiir','Dilşade Güngör']::text[], 8.5, '{"poet":"Dilşade Güngör","poet_slug":"dilsade-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/insanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-adnan-unay-tn0yc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine hüzün buhranı, yine ayrılık...

Bir buse ardından ne ses ne seda...

Kalbimde ateş vardı tam iki yıllık, 

Ona da acımadı, dedi ''Elveda''

Yağmur yağıyordu,  yüzüme baktı.

Hem gökte, hem kalbimde şimşekler çaktı.

Son sözünü söyledi, dünyamı yıktı, 

Beni sevmiyormuş dedi ''Elveda''.

Elini uzattı, dayanamadım.

Sıcaktı elleri, bırakamadım.

O son dediğini unutamadım.

Başı yere eğildi, dedi ''Elveda''.

Usulca evinin yolunu tuttu, 

Dilinde o bizim şarkımız yoktu, 

Son kez geri dönüp halime baktı, 

Sırılsıklam olmuştum, dedi ''Elveda''.

Bir sigara yaktım ayrıldık diye, 

Bir kolyem kalmıstı ondan geriye, 

Aklıma o geldı, baktım kolyeye, 

Taa içimden bir ses dedi ''Elveda''.

Dün cam kenarına bindim son kere

Belki camdan onu görürüm diye, 

Buğulu camlara titrek elimle, 

Ağlayarak yazdım ''Sana elveda''.

Bir kişiyi sevdim,  ''Elveda'' dedi.

Ona ömrümü verdim, beni sevmedi, 

Bu aynı fasıllar canıma yetti, 

Öyle olsun hayat, sana elveda! ! !', 'Yine hüzün buhranı, yine ayrılık... Bir buse ardından ne ses ne seda... Kalbimde ateş vardı tam iki yıllık,  Ona da acımadı, dedi ''Elveda'' Y...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ünay']::text[], 8.5, '{"poet":"Adnan Ünay","poet_slug":"adnan-unay","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/elveda-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılarım Dağlara- Özgür Çağrı', 'sarkilarim-daglara-ozgur-cagri-orhan-kotan-d27j7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana yalan söyleyemem

Darılırsın yavrucağım

Ağabeyin bir gün dağdan döner

Giden gelmez, geri dönmez

Bilmiyormusun yavrucağım

Sen üzülme, sıra bende

Gideceğim yavrucağım

Elverir ki çoşku

Haylaz çocuklarını boğazlamasın

Avunmak elbette kolaydır

Şehri yiğit bir türkü gibi dolaşmak

Dağlara destanlar, düşünmek kolaydır

Hapislere bir sevinç çığlığı gibi düşmek

Kızların diri gögüslerinde

Matbaalarda

Ve kongre zabıtlarında dünyayı tazelemek

Yeryüzüne depremler düşürmek

Çünkü binlerce militanın rüzgarlı macerası

Bir kurşun bile değildir namusun mavzerine

Gönlün kahpeliğine tutsaksın açıkçası

Asıl savaş alanı suskundur arkadaş

Sahipsizdir

Asıl savaşcılar afyonlu, mütevekkil

Öyleyse

Şehrin girdabında çalkalanan zulüm

Halkın şanlı isyanına işaret değil

Bodrum duvarlarına öfkeli yazıları

Tırnaklarınla kazıyorsan da

Sana yalan söyleyemem 

Darılırsın yavrucağım

Ağabeyin bir gün dağdan döner

Giden gelmez, geri dönmez

Bilmiyormusun yavrucağım

Sen üzülme, sıra bende

Gideceğim yavrucağım

Bulvara dökülen bildiriler

Harcanan bunca emek, bunca değer

Fokurdayan metal potası

İşleyen rotatifler

Cesetleri iğnelemek gibi birseydir

Ve zaman usulca göz kırpıp telaşına

Homurdanarak çekip gitmiştir

Yani bu

Aşağılık bir dramdır artık

Çünkü jarjuruna

Boş kovanları dolduran adam

En azından kendinden utanmalıdır

Yani yetsin diyorum

Şarkılarınızı dağlarıma sürün diyorum

Uzatın ellerinizi diyorum

Uzatın tanışalım

HELALLAŞALIM....', 'Sana yalan söyleyemem Darılırsın yavrucağım Ağabeyin bir gün dağdan döner Giden gelmez, geri dönmez Bilmiyormusun yavrucağım Sen üzülme, sır...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kotan']::text[], 8.5, '{"poet":"Orhan Kotan","poet_slug":"orhan-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/sarkilarim-daglara-ozgur-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Bilim Olsaydı', 'siir-bilim-olsaydi-huseyin-erdol-v90lj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eğer bilim olsaydı şiir

bırakırdı kuzu bulutlarının peşinden koşmasını 

eğer bilim olsaydı şiir

uzaklara açılan yelkenliden sormazdı gitmeyi 

eğer bilim olsaydı şiir

alevler arasında aramazdı o gülüşü

eğer bilim olsaydı şiir

vaz geçerdi yıldızlarla şarkı söylemekten

eğer şiirsiz kalsaydı bilim 

yedinci yağmur altında

dans edemezdi dağın ardındaki alevlerle

24-05-2002

_________________________________', 'eğer bilim olsaydı şiir bırakırdı kuzu bulutlarının peşinden koşmasını  eğer bilim olsaydı şiir uzaklara açılan yelkenliden sormazdı gitmeyi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdöl']::text[], 8.5, '{"poet":"Hüseyin Erdöl","poet_slug":"huseyin-erdol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dusmanam-dusmanlik-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Kaybetmet', 'gunesi-kaybetmet-levent-kizildag-th3qw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yine doğmana bak güneş.

Boşver benim 

durumuma.

En çok sevdiğimdi 

o benim.

Sevgim, 

herşeyimdi, 

O''nu kaybettim.

Seni de 

kaybetmek istemem', 'Sen yine doğmana bak güneş. Boşver benim  durumuma. En çok sevdiğimdi  o benim. Sevgim,  herşeyimdi,  O''nu kaybettim. Seni de  kaybetmek ist...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gunesi-kaybetmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost ve Gözyaşı', 'dost-ve-gozyasi-levent-kizildag-1fhf9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En beklemediğim anda

Vurdular beni

Dostlarım, 

Meze oluyor

Şiirime şimdi

Gözyaşlarım.', 'En beklemediğim anda Vurdular beni Dostlarım,  Meze oluyor Şiirime şimdi Gözyaşlarım....', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dost-ve-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gönlüm', 'bu-gonlum-levent-kizildag-inenw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ateşli bir hastalıktan yeni kalkmış gibiyim.

Gökten deli dolu gelip de, 

Camlara vurduğunda dağılan

Bir yağmur damlası gibi

Şaşkın bu gönlüm.

Gecenin gözleri ışıl ışıl olsa da, 

Ilk kez gören biri gibi

Hayran bu gönlüm.

Yeni doğan bir çocuk kadar yaşam dolu, 

Ama bir o kadar da

Yorgun bu gönlüm.

Sarı karanlıklar boyu

Uzayıp giden çöllerde

Aniden fışkıran pınar gibi

Coşkun bu gönlüm.', 'Ateşli bir hastalıktan yeni kalkmış gibiyim. Gökten deli dolu gelip de,  Camlara vurduğunda dağılan Bir yağmur damlası gibi Şaşkın bu gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık', 'gel-artik-levent-kizildag-7md6s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmem, hala böylemisindir.

Sanki yüzyıl oldu görüşmeyeli.

Dudaklarında ince bir tebessüm..

Bir okyanus gibiydi gözlerin, 

Sır vermez derin gizemli.

Kimi görsem, 

Biraz sana benziyor.

Sanki sen çıkacaksın

Yaklaştığım her köşeden.

Gel ve sev artık..

Umut mevsimleri geçmeden.', 'Bilmem, hala böylemisindir. Sanki yüzyıl oldu görüşmeyeli. Dudaklarında ince bir tebessüm.. Bir okyanus gibiydi gözlerin,  Sır vermez derin ...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gel-artik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Geldim', 'i-ste-geldim-evren-yortucboylu-tkpf6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün yazacam arkadaş durdurma beni

Herkes yazmış ne var ne yok tutma beni

Üzülünce yazmışlar, sevinince yazmışlar

Rakı gibi bişey bu, artık istesem de 

Bırakamam ben bu şiiri

Tamam belki kafiye uyduramam

Anlam katamam bu mısralara

Ama ne olur bırak ta bari 

Bu şekilde dökeyim içimi

Ne fayda veriyor şu sigara

Ne de içtiğim onca bira

Bunlar kesmez oldu beni

Şimdi burayım işte yazıyorum bu şiiri

Ne düşünür okuyan hiç düşünmedim

Dün beni yine meyhaneye çağırdılar, gitmedim

Hayattan kopmadım, bitmedim, bitemezdim

Evet buradayım, işte bakın, ben de geldim

Dün abbası okudum defalarca

Elime aldım yüreğimi ağladım dakikalarca

Saydım kaç güneş var yukarıda

Nihayet yanınıza gelebildim sonunda

Bu son dörtlük gerisi saçma olur gari

Sonunu getirebileyim bu şiirin bari

Kimse okumasa da beğenmese da bana kâfi

Beni de aranıza kabul edin, ne olur abi

Evren Yortuçboylu', 'Bugün yazacam arkadaş durdurma beni Herkes yazmış ne var ne yok tutma beni Üzülünce yazmışlar, sevinince yazmışlar Rakı gibi bişey bu, artık...', ARRAY['Türk Edebiyatı','Şiir','Evren Yortuçboylu']::text[], 8.5, '{"poet":"Evren Yortuçboylu","poet_slug":"evren-yortucboylu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/iste-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otobüs', 'otobus-evren-yortucboylu-bg4rr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yapraklar dökülüyordu yere

Ama ne çare gittin işte bi kere

Dön diyemem sen kendin istedin

Git de diyemem ölümüne sevdim

Giderken arkana bakma sakın

Katilim olursun, öldürür beni aşkın

Hadi artık çabuk ol geldi vakti

Bitsin. Ölüm mü var ucunda sanki? 

sanan öyle dedim o gün ama inanma

Gözlerimden akmayan yaş boğmuştu beni o anda

Otobüs çıktı gitti gardan

Artık ne bekleyebilirim bu hayattan.

(Kevser Tuba Ak''a atfolunur...)', 'Yapraklar dökülüyordu yere Ama ne çare gittin işte bi kere Dön diyemem sen kendin istedin Git de diyemem ölümüne sevdim Giderken arkana bakm...', ARRAY['Türk Edebiyatı','Şiir','Evren Yortuçboylu']::text[], 8.5, '{"poet":"Evren Yortuçboylu","poet_slug":"evren-yortucboylu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/otobus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennemin Dibinden Selam', 'cehennemin-dibinden-selam-mehmet-tan-ivmtf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşanılacak, dayanılacak yer değil burası

hasret gibi, 

hasretin gibi! 

bir günah işledim şunun şurası

bedeli tonlarca ağır

nefret gibi, 

nefretin gibi! 

burası çok sıcak inan

birşeylere ihtiyacım var

sevgin gibi, 

şefkatin gibi! 

cehennemin dibinden selam BEBEĞİM

güzel anılarla acıya dayanıyorum

kızımız gibi, 

senin gibi..! 

SENİ SEVİYORUM..!', 'yaşanılacak, dayanılacak yer değil burası hasret gibi,  hasretin gibi!  bir günah işledim şunun şurası bedeli tonlarca ağır nefret gibi,  ne...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cehennemin-dibinden-selam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıyor Gibisin', 'taniyor-gibisin-aysun-aksu-46vsw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni tanıyor gibisin

Korkularımı, düşlerimi, biliyor gibi

Çok uzaklardasın ama

Yakınımda hissediyorum seni

Korkuyorum, bazen senden

Karşında, şeffaf cam gibiyim

Kalın perdeler kapatamıyor beni

Kızıyorsun bazen bana hissediyorum

Bazende, yargılıyor gibisin

Ama sen beni, bende seni

Görmesekte birbirimizi

Ruhlarımız, tanıyor birbirini', 'Beni tanıyor gibisin Korkularımı, düşlerimi, biliyor gibi Çok uzaklardasın ama Yakınımda hissediyorum seni Korkuyorum, bazen senden Karşında...', ARRAY['Türk Edebiyatı','Şiir','Aysun Aksu']::text[], 8.5, '{"poet":"Aysun Aksu","poet_slug":"aysun-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/taniyor-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinmeyi Bilenlerin Şiiri', 'sevinmeyi-bilenlerin-siiri-afsar-timucin-kr3gu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevinç bizim güneşte üzümlerden 

Sabah işe giderken 

Düş diye süzdüğümüz güzelliktir 

Başını döndürür bekletirsen 

                     Ortanca çiçeğinin gölgesine 

                     Bize görünmeden sığınıveren 

                     Küçücük bir böceğin çıtırtılı sessizliği 

                     Simgesidir bitmez çabamızın 

                     Seni sevmek gibidir 

Çınar sanki mektubunu getiren 

o güleç ve dalgacı arkadaştır 

Naneler üstünde yatacağımız halı 

Derenin sesi tren sesidir. 

                     Aşk bizim her dokunuşta 

                     Ölür gibi sarsıldığımız şeydir.', 'Sevinç bizim güneşte üzümlerden  Sabah işe giderken  Düş diye süzdüğümüz güzelliktir  Başını döndürür bekletirsen                       Orta...', ARRAY['Türk Edebiyatı','Şiir','Afşar Timuçin']::text[], 8.5, '{"poet":"Afşar Timuçin","poet_slug":"afsar-timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevinmeyi-bilenlerin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağacın İkinci Türküsü', 'agacin-i-kinci-turkusu-afsar-timucin-0pn8l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Açıklara çıkalım boğulmamak için

Günün kuytu yerleri şimdi harap

İçimizde bir ezgi inceden inceye

Bizi kendimize bağlarken akşam olur

Karanlığı gümüş rengine boyar mehtap

Oturup uzun uzun konuşsaydık

Sevişmek nasıl olsa gene olur iyi kötü

Bir ıhlamur sıcaklığı yayılırken odamıza

Her şeyi ince ince düşünseydik

Ölümü kırgınlığı inceliği en başta

Bütün eksiklerimize gülüp geçerek

Belki de boşa geçti onca zaman

Bu da bir tür geçip gitme duygusudur

Ne güzel olurdu yeniden başlasak

Ne yapsan en başa dönülemiyor

Ne yapıp yapıp dalı unutmalı

Rüzgârla yere düşen sarı yaprak', 'Açıklara çıkalım boğulmamak için Günün kuytu yerleri şimdi harap İçimizde bir ezgi inceden inceye Bizi kendimize bağlarken akşam olur Karanl...', ARRAY['Türk Edebiyatı','Şiir','Afşar Timuçin']::text[], 8.5, '{"poet":"Afşar Timuçin","poet_slug":"afsar-timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/agacin-ikinci-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rrzincanda', 'rrzincanda-burhan-kamali-x2itb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Munzura kar yağar

Erzincana yağmur

Dışarda mevsim ilk bahar

Benimde içimde hazan var

Bir yanımda sarı yapraklar durur

Diğer yanımda göçmen kuşlar uçuşur

Mevsimlerim değişmez hep güz olur', 'Munzura kar yağar Erzincana yağmur Dışarda mevsim ilk bahar Benimde içimde hazan var Bir yanımda sarı yapraklar durur Diğer yanımda göçmen k...', ARRAY['Türk Edebiyatı','Şiir','Burhan Kamalı']::text[], 8.5, '{"poet":"Burhan Kamalı","poet_slug":"burhan-kamali","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/rrzincanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müseddes-i mütekebbir', 'museddes-i-mutekebbir-seyh-galib-zv898', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tedbirini   terkeyle   takdir hüda''nındır

Sen yoksun o benlikler hep vehm ü gümanındır

Birden bire bul aşkı bu tuhfe bulanındır

Devran olalı devran erbab-ı safanındır

Aşıkta keder neyler gam halkı cihanındır

Koyma kadehi elden söz pir-i muganındır

Meyhaneyi seyrettim uşşaka mataf olmuş

Teklif ü  tekellüften  sükkanı maaf olmuş

Bir neşe gelüp meclis bi havf u hilaf olmuş

Gam sohbeti yad olmaz meşrebleri saf olmuş

Aşıkta keder neyler gam halkı cihanındır

Koyma kadehi elden söz pir-i muganındır

Ey dil sen o dildara layık mı değilsin ya

Da''va-yı mahabete sadık mı değilsin ya

Özrü nedir Azra''nın Vamık mı değilsin ya

Bu gam ne gezer sende aşık mı değilsin ya

Aşıkta keder neyler gam halkı cihanındır

Koyma kadehi elden söz pir-i muganındır

Mahzun idi bir gün dil meyhane i ma''nade

İnkara döşenmiştim efkar düşüp yade

Bir pir gelüp nagah pend etti alel- ade

Al destine bir bade derd ü gamı ver bade

Aşıkta keder neyler gam halkı cihanındır

Koyma kadehi elden söz pir-i muganındır

Bir bade  çek efzun kap mecliste zeber-dest ol

Atma ayağın taşra meyhanede pa- best ol

Alçağa akar sular Pay i huma düş mest ol

Pür cuş olayım dersen Galib gibi düş mest ol

Aşıkta keder neyler gam halkı cihanındır

Koyma kadehi elden söz pir-i muganındır', 'Tedbirini   terkeyle   takdir hüda''nındır Sen yoksun o benlikler hep vehm ü gümanındır Birden bire bul aşkı bu tuhfe bulanındır Devran olalı...', ARRAY['Türk Edebiyatı','Şiir','Şeyh Galib']::text[], 8.5, '{"poet":"Şeyh Galib","poet_slug":"seyh-galib","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/museddes-i-mutekebbir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölünün Kıyıları', 'olunun-kiyilari-erdem-bayazit-yp09v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'M.Akif İnan''a

Gök boşanarak üstümüze

Bizi ıslak saçlarından geçirir karanlığın

Gece siyah bir at olur da uçar

Uykumuzun soluyan denizine.

Babalar ölümü dengede tutar

Seçerek en sağlam vakti arabasına.

Şimdi o araba uçuyorsa

Bir Asya çölünü kanat yaparak

Ey üstümüze gelen

Ey çocukların gözlerinden dökülen

Ölümü konuşan damla damla

Ey beklediğimiz her an

Ey bize son sözü muştulayan

Bizi bulan şahdamarımızda

Ey sürücüleri babalarımız olan.

Bir an dudaklarıyla

Değen alnımıza masmavi

Bir güvercin kanadı gibi

Ey annelerin sesi

İçimizde savrula savrula

Yağan bir bahar yağmuru gibi

Çağırırdı oğullarını yola

Ben işte o zaman

Saygı ile ve güvenerek

Selamlayacağım önden gideni

Yılanlar tüylerini dökerken

Eğerken dağlar başlarını önlerine

Birinin yeşil yaprağı kutsaması gerek

Birinin akan suyu tutması

Altında durarak gökten boşananın

Sonra yükselterek sesimi konuşacağım.

Sen dur burda ey insan

Duy içinde tutuşan ormanı

Ve yakıştırmasını bil üstüne ey ademoğlu

Usta bir makasla biçilen toprağı.

Ankara, Türkocağı,1968', 'M.Akif İnan''a Gök boşanarak üstümüze Bizi ıslak saçlarından geçirir karanlığın Gece siyah bir at olur da uçar Uykumuzun soluyan denizine. Ba...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/olunun-kiyilari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Sayfaları', 'kus-sayfalari-erdem-bayazit-owdcz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir tren atılır kurşun gibi geceye 

Demir gibi gök yüklü tren karanlığın ürpertisine girerken 

Ötede kuşlar derlenir ana olurken bir gün doğumuna 

Kent horozlarla uyanır sularla gerinir zamana 

geçerken ezanla 

Sayfalar sayfa olurken Kuran''la 

Bir kuş yağmuru boşanır bilmediğim bir yerden 

Bir boranın patladığı bir yerden', 'Bir tren atılır kurşun gibi geceye  Demir gibi gök yüklü tren karanlığın ürpertisine girerken  Ötede kuşlar derlenir ana olurken bir gün doğ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kus-sayfalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Yağmur Yağsa', 'ne-zaman-yagmur-yagsa-altug-can-aldanmaz-fsy4w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umuttan merdivenler dayadım çoban yıldızına 

Yine de eremedi yüreğim yüreğinin hizasına

Gözlerim bakakaldı mavi, korkak semaya

Ellerim bomboş kaldı, lanet ettim dünyaya

İşte bir bulut geliyor bilinmez bir diyardan

Mutlak haber getiriyor ya ölümden ya yardan

İnceden bir yağmur fısıldıyor önce kulağıma

Bir bildiği var belli, süzülüyor yanağıma

Bak bildim işte hep senden bahsediyor

Rengini senden almış, buram buram sen kokuyor

Gözlerinden doldurmuş şu kocaman göğsünü

Senin yüreğinden almış rengindeki hüznü

Anlat şimdi ey bulut, bana gözlerinden bahset

Damla damla gir gönlüme istersen yine kahret

Bu yağmur, ipek saçlarından süzüldü sanki

Bu bulut, anılarda kalmış bir ömürdü belki

Kimsesiz gecelerimde yegane düşümdü ölmek

Gözyaşlarımızla dolan bu havuzda can vermek

Bulut henüz susmadı, yağmur hala yağıyor

Ayaklarımın ucundan oluk oluk aşk akıyor

Bıraktım işte kendimi, eriyorum yudum yudum

Dudağımda aynı şarkı, gözlerimde son umudum

Bir avuç su oldum, karıştım ben de bu sele

Gidiyorum sonsuzluğa, elimde son resmin ile

Yıldızlara dayadığım merdiven, ulaşmadı aşk sahasına

Ama pes etmedim, bulutla geliyorum, ölüm pahasına

Kurtuluşun yok, nereye gitsen geleceğim peşinden

Hangi kılığa girsen tanırım, nefes alıp verişinden

Bazen kaldır başını göğe, küskün bir bulut görürsün

Halime ağlamasan bile belki biraz üzülürsün

Bir gün kavuşurum sana, bir damla su halinde

Süzülürüm saçlarından yanağına, bir tebessüm içinde

Sel gibi yağarım üstüne, ne vakit hüzünlensen

Bir olup gözyaşınla akarız içine, sen bir istesen

Ben seni unutamam, içimde bir parça sen var

Sen de benden kopamazsın, elinde bütün bir ben var

Bazen yağmur yağar, nemlendirir saçlarını

İşte o anlar hatırla, sınır bilmez aşığını

Sonunda hayal bitti, başladı yine gerçek savaş

Ama inan her yağmurda, düşecek elime bir damla yaş...', 'Umuttan merdivenler dayadım çoban yıldızına  Yine de eremedi yüreğim yüreğinin hizasına Gözlerim bakakaldı mavi, korkak semaya Ellerim bombo...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Can Aldanmaz']::text[], 8.5, '{"poet":"Altuğ Can Aldanmaz","poet_slug":"altug-can-aldanmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ne-zaman-yagmur-yagsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebep Ey', 'sebep-ey-erdem-bayazit-hg8jg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ürperir tabiat, üfleyince rüzgârı derin gök soluğu

Ulu ses dokununca çarka

Düşer ölümün gölgesi eşyaya.

Başlar eşyada hareket kurtulmak için kendinden

Daha öteye geçmek için arınmak gibi elbiseden

Yakalar ölümsüzlüğün sonsuz ipini

Sonra ses olur

Zamanın idrak incisi ses döner, döner, döner de

Yönelir sebebe

Sebeb ey! 

Sesi damarla çizer

Mutlak sözü damarda kanla çizer

Uzar bir göz ağrısının gecesi uçsuz bir nehir gibi

Bir bebeğin ilk hecesi düşer ağzından ansızın ve bulur

Sonra toprak sıkışır sıkışır taşar da renk olur tarla da

Günesin çarpılmış elçisi Van Gogh´la gelir önümüze

Portakalla yayılır karanfilde tutuşur karar kılar denizde

Renk denizde karar kılan ebedi tarla olur.

Renk başkaldırırken helezonlar çizerken ses

Som fatih su fetheder tabiatı

Döner döner döğünür eritir dağları yobaz kayaları

Daha der sığmaz kabına yönelir göğe teslim olur

Ve düşerken toprağa çağırır

Sebeb ey! 

Her sabah bütün bitkiler iştahlı bir çocuktur

Emer, emer, emer toprak anayı

O sultan hazinesi o hep veren sonsuz cömert anayı

Yeşil hayat, kırmızı hareket, sarı sabır emer

Ve beyaz iman çizer sesini

Tamamlar kavisini

Sebeb ey!', 'Ürperir tabiat, üfleyince rüzgârı derin gök soluğu Ulu ses dokununca çarka Düşer ölümün gölgesi eşyaya. Başlar eşyada hareket kurtulmak için...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sebep-ey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diriliş Saati', 'dirilis-saati-erdem-bayazit-qf76j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey bir emre hazırlanan simsiyah gecede 

Karanlığı emip emip de gebe kalan 

Ey her depremden sonra biraz daha doğrulan 

Herkesin 

Veba girmiş bir şehrin hem halkı 

Hem seyircisi olduğu bir günde 

Ey düştüğü yerden kalkmaya hazırlanan ülke. 

Her damlası bir zafer müjdecisi 

Bir posta eri gibi 

Yağmur yüzümüze değince 

Çıkacağız yola. 

Çıkacağız yola 

Hesap günü gelince 

Yağmur yüzümüze değince 

Güneş bir mızrak boyu yükselince.', 'Ey bir emre hazırlanan simsiyah gecede  Karanlığı emip emip de gebe kalan  Ey her depremden sonra biraz daha doğrulan  Herkesin  Veba girmiş...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dirilis-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta Korkan İdamlıklar', 'karanlikta-korkan-i-damliklar-erdem-bayazit-br8er', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak sabah olmuş

Sağ elim kement gibi bak sana uzattım

Ben karanlığım korkma ben karanlığım

Sessiz sabahların korkak idamlıkları kalkın

Ben sizi mavi sabahlara sararım.

Yeni bir çağa giriyoruz bakın

En serseri bombalar ensesinde kimsesizliğin

Öcünü kusuyor önünüze

Bunalan sessizliğin.

Ey sarı benizli idamlıklar kalkın

Yeni bir çağa giriyoruz bakın.

Beyaz çarşaflarla al kanlar donarsa

Senin kanın donarsa benim kanım donarsa

Ben serin mezarlara muştular götürürüm.', 'Bak sabah olmuş Sağ elim kement gibi bak sana uzattım Ben karanlığım korkma ben karanlığım Sessiz sabahların korkak idamlıkları kalkın Ben s...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/karanlikta-korkan-idamliklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Altında Hüzün Denemesi', 'kar-altinda-huzun-denemesi-erdem-bayazit-khkjm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyanın en uzun hüznü yağıyor, 

Yorgun ve yenilmiş insanlığımızın üstüne. 

Kar yağıyor ve sen gidiyorsun, 

Ağlar gibi yürüyerek gidiyorsun, 

Belki bulmağa gidiyorsun kaybettiğimizi

O insan ve tabiat çağını. 

Dön bana ve dinle! 

Kuşlar uçuşuyor içimde.

Loş bir keman solosu gibi 

Kuşların uçuştuğunu içimde, 

Dön bana ve dinle. 

Karanlık denizlerin dibinde, 

Birtakım incilerin olduğunu 

Birtakım incilere ve hatıralara 

Neden bağlı olduğumuzu unutma. 

Duy beni ve dinle! 

Denizler boğuşuyor içimde. 

Unutma diyorum ama sen anla, 

Anlat bizim de yaşamak istediğimizi onlara...', 'Dünyanın en uzun hüznü yağıyor,  Yorgun ve yenilmiş insanlığımızın üstüne.  Kar yağıyor ve sen gidiyorsun,  Ağlar gibi yürüyerek gidiyorsun,...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kar-altinda-huzun-denemesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-erdem-bayazit-pmr6p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Burçlarında ceylan taşıyan yücelere ey 

Ayın hüzün saati gözlerinden 

Kuytu yerlerine sümbüller dökülen 

Nergisler açan eteklerinde 

Göklerden muştular indiren güvercinleriyle 

Dorukları bembeyaz yaşmaklarıyla 

Güneşe uzanan ağaçlarıyla 

Zamanı hiç geçmeyecekmiş gibi donduran 

Ey bir yanıyla derin sulara dayanan 

Ey dağlar nerdesiniz ey. 

Kim bizi senden koparan 

Hangi ses çağıran bulvarlara 

Dengemizi bozan intihar vitrini bulvarlara', 'Burçlarında ceylan taşıyan yücelere ey  Ayın hüzün saati gözlerinden  Kuytu yerlerine sümbüller dökülen  Nergisler açan eteklerinde  Göklerd...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/daglar-361-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-erdem-bayazit-otaev', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık beni parktaki ağaç bile anlamıyor

Siyah kedinizin kuyruğunda sallanan zaman

Bir zamanlar sevinçle giyindiğim

Ak bir güvercin kanadı gibi gururla giyindiğim

Temiz ve mavi giysim değil artık.

Yalnız imkansızlığı mı anlatır bir bulut

Yağmaya hazır bekliyorsa gökyüzünde.', 'Artık beni parktaki ağaç bile anlamıyor Siyah kedinizin kuyruğunda sallanan zaman Bir zamanlar sevinçle giyindiğim Ak bir güvercin kanadı gi...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/soru-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-erdem-bayazit-57mm3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu şehirden gidiyorum 

Gözleri kör olmuş kırlangıçlar gibi 

Gururu yıkılmış soyatlar gibi 

Bu şehirden gidiyorum. 

İnsanlar taş gibi bana yabancı 

Ağaçlar bensiz hüküm giyecek bulvarda 

Bir tanbur bir yalnızlığı anlatıyorsa 

O ışıksız pencereden 

Ben onu duymuyor gibiyim 

Bir ağaç ölüyorsa kapınızın önünde 

Ben onu bile duymuyor gibiyim. 

Bu şehirden gidiyorum 

Gömerek geceyi içime 

Sabahın hüznünü beklemeden 

Gidiyorum bu şehirden.', 'Bu şehirden gidiyorum  Gözleri kör olmuş kırlangıçlar gibi  Gururu yıkılmış soyatlar gibi  Bu şehirden gidiyorum.  İnsanlar taş gibi bana ya...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/veda-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evrenin Efendisine', 'evrenin-efendisine-erdem-bayazit-yeifu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyanın ağırlığına eklesek yıldızları ayı güneşi,

Gene de ağır basarsın ey kalbim 

Ey kalbimin güneşi…', 'Dünyanın ağırlığına eklesek yıldızları ayı güneşi, Gene de ağır basarsın ey kalbim  Ey kalbimin güneşi…...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/evrenin-efendisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-erdem-bayazit-yhpv3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allah elçilerinden sonra en büyük insana 

Bir orman gibi büyür içimde sevmek 

İçimde insan bir mahşer gibi kararırken 

Ey her suça ortak çıkan kalbim.', 'Allah elçilerinden sonra en büyük insana  Bir orman gibi büyür içimde sevmek  İçimde insan bir mahşer gibi kararırken  Ey her suça ortak çık...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevmek-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-erdem-bayazit-vz3jy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gidip bir gelerek durmadan 

Ay ışığını soluyan ey deniz ey o denizin dibi 

Sonra büyüten yalnızlığını kanayan yalnızlığına kalbim gibi.', 'Bir gidip bir gelerek durmadan  Ay ışığını soluyan ey deniz ey o denizin dibi  Sonra büyüten yalnızlığını kanayan yalnızlığına kalbim gibi....', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yalnizlik-1670-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramak', 'aramak-erdem-bayazit-6z7xn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey hep bir kelime arayan kalbim

Sonra arayan tekrar arayan kalbim', 'Ey hep bir kelime arayan kalbim Sonra arayan tekrar arayan kalbim...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/aramak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmak', 'susmak-erdem-bayazit-5zev2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey sesimi keskin bir bıçak gibi 

Kınında saklayan çağ 

Ey sabırla bileyen günlerimi.', 'Ey sesimi keskin bir bıçak gibi  Kınında saklayan çağ  Ey sabırla bileyen günlerimi....', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/susmak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercinler', 'guvercinler-erdem-bayazit-yxel5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ağaç bir mezartaşını yutuyordu çarşıkapıda

"İçimizde kıpırdanırken İstanbul"

Bir çocuk mabedlerin susamışlığını satıyordu

Sesini hatırlayamadığımız bir su testisinde

Güneş sanki günahımızdı üstümüzde.

Sonra bu güvercinler niye varlar

Bir anıyı yaşatmak için mi

Ölümsüz bir ses mi taşımak için ötelere

Avuç içlerinde camilerin.

Çarşıkapı 1966', 'Bir ağaç bir mezartaşını yutuyordu çarşıkapıda "İçimizde kıpırdanırken İstanbul" Bir çocuk mabedlerin susamışlığını satıyordu Sesini hatırla...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guvercinler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soluyan Deniz', 'soluyan-deniz-erdem-bayazit-njpmt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çığlık düştü karanlıklardan

Issız denize

Ses beton gibi buz tutuyordu

Bir takım gölgeler gidip geliyordu

Ay ışıkları gidip geliyordu

Deniz yaralı bir tay gibi soluyordu.

Kim bizi çeken ayaklarımızdan

Suyun yumuşaklığına

Yerin katılığına

Göğün karanlığına.

Bir göz bizi denetliyor - bu muhakkak

Bir çığlık boğuluyor denizde - bunu iyi duyuyoruz

Bir ışık kesiyor karanlığı bir ustura ağzında

Bilmediğimizi anlıyoruz

Görmediğimizi seziyoruz

Yeni bir çağa çıkıyoruz saçlarımızdan.', 'Bir çığlık düştü karanlıklardan Issız denize Ses beton gibi buz tutuyordu Bir takım gölgeler gidip geliyordu Ay ışıkları gidip geliyordu Den...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soluyan-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Koşusu', 'sabah-kosusu-erdem-bayazit-ub1bi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk güneşi duyuyoruz etimizde

Derimizde ansızın kaçak bir rüzgar yakalıyoruz

Bir serinliyoruz bilseniz bir serinliyoruz

Her gün gidip beş vakit

Denizi öpsek yeridir.

Bir karınca durmuş yaşamayı anlatıyor

Bir dinliyor böcekler görseniz bir dinliyor

Bir çoban yıldızları sayıyor

Bir arabacı şapkasını atıyor havaya.

Sabah oluyor yalınayak koşuyoruz yeni bir çağa

Derin asfaltları duyuyoruz

Sıcaklığını duyuyoruz

Bazen bir serinlik doluyor içimize

Ayaklarımızdan

Göğü kapatan çatıları yıkıyoruz ellerimizle

Ve şunu iyi anlıyoruz

En iyisi yürüyerek gidilir yaşamağa.

İstanbul, 1960', 'İlk güneşi duyuyoruz etimizde Derimizde ansızın kaçak bir rüzgar yakalıyoruz Bir serinliyoruz bilseniz bir serinliyoruz Her gün gidip beş va...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sabah-kosusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşçağ Savaşçıları', 'gunescag-savascilari-erdem-bayazit-n38lt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinde gök sancısı 

İçlerinde okyanus uğultusu uzun mızraklarla 

yararak karanlığı 

Gelip dayandılar şehrin sivrilmiş tırnaklarına 

Çarpık dudaklarıyla kırpılmış saçlarıyla 

Soyguna uğramış yüzleriyle 

Barbar ellerin işgal ettiği sonra terk ettiği 

Harabe kadınlar 

Gidip gidip gelirlerdi camekanlı çarşıda 

Bu kirazı kim yer kim satar 

Hangi savaştan arta kalmış bu çocuklar. 

Sonsuz devirleri aşarak savaşçılar geldiler 

Ve akşamın ipini kestiler 

Gece putun üstüne devrildi put yere devrildi 

Yanlış pazarlara sürülmüş yılgın uykusu şehrin 

Ortasından bölündü. 

Kollarını derin balkonlara dayamış bilinçleri 

ustura savaşçılar 

Taradılar gözleriyle ağır ağır şehrin saçlarını 

Ayıkladılar bir bir bitlerini 

Fosfor ellerini uzatarak balkonun uçsuz uzantısından 

Yanan şehri tuttular 

Şu bizim atımızdır deniz hipodrom 

Nehrin yatağını öp sen ey savaşçı 

Birikinti gölleri geç apartmanları geç kaldırımları 

Bir bir ayıkla mezarları. 

Güneşçağ öncüleri yolları tuttu dua erleri tuttu 

Yüzleri Mekke ülkesi gözleri Medine çeşmesi 

Elleri altınçağ mimarı.

Ankara 1966', 'Gözlerinde gök sancısı  İçlerinde okyanus uğultusu uzun mızraklarla  yararak karanlığı  Gelip dayandılar şehrin sivrilmiş tırnaklarına  Çarp...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gunescag-savascilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-gokhan-ozmen-1rrkw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Garip kaldım bu diyarda neyleyim 

Kimlere anlatayım, derdimi söyleyeyim

Kafamı hangi taşlara vurayım

Kimse beni anlamıyor Annem

Ağlıyorum hıçkırıkla dinmek bilmiyor

Birisi de gelipte göz yaşımı silmiyor

Gözlerim her yerde seni arıyor

Gelde kurtar beni Annem

Herkes bir telden çalıyor

Her geçen bir darbe vuruyor

Yokluğun beni kor gibi yakıyor

Nerdesin! nerdesin Annem

Hiç kimse yerini tutmuyor 

Hasretin içimde dinmek bilmiyor

Ben ağlarken herkes gülüyor

Seni çok özledim Annem

Bu hasret bitse gelsem yanına 

Hiç durmadan bassan beni bağrına

Canımı veririm o an uğruna

Gözlerim takvimden inmiyor Annem......', 'Garip kaldım bu diyarda neyleyim  Kimlere anlatayım, derdimi söyleyeyim Kafamı hangi taşlara vurayım Kimse beni anlamıyor Annem Ağlıyorum hı...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Özmen']::text[], 8.5, '{"poet":"Gökhan Özmen","poet_slug":"gokhan-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/annem-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen giderken', 'sen-giderken-gokhan-ozmen-i0fuh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen giderken çok şey söyleyecektim 

Kelimeler boğazımda düğümlendi

Ayrılmayalım diye boynuna sarılıp ağlayacaktım

Kahretsin! ! ! gururum engelledi........', 'Sen giderken çok şey söyleyecektim  Kelimeler boğazımda düğümlendi Ayrılmayalım diye boynuna sarılıp ağlayacaktım Kahretsin! ! ! gururum eng...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Özmen']::text[], 8.5, '{"poet":"Gökhan Özmen","poet_slug":"gokhan-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-giderken-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürüp Gelen Çağlardan', 'surup-gelen-caglardan-erdem-bayazit-p97au', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeryüzü bana mescit kılındı

Ant verdim toprak şahit tutuldu

Her sabah her öğle her akşam

İkindiyle yıkanarak yatsıyla donanarak

Seslerden bir sesle fırınlanıp

Sulardan polatlanan benim.

Geldim durdum önünde işte bir anıt gibi

Sıyırarak sırtımdan bir yılan giysisini.

Evet bir hançer ağacı gibi büyüyor içimde acı

Dağlardan bir dağ gibi kabaran yüreğimde.

Kargaların sırtlanlarla anlaştığı bir günde

Bir yabancı fırtınaya tutulan yapraklarım

Kudüs''te Mescid-i Aksa''da

Belki bir batı karanlığında Topkapı''da

Yangına uğramışsa

Duymaz olmuşsa kulaklarım göklerin muştu sesini

Elbet kıracağım bir gün bu ihanet kelepçesini

Çün defterler açılıp hesap soruldukta

Yetimin hakkı soruldukta yoksulun hakkı soruldukta

Milletim omuz omuza verip

Kıyama duruldukta.

Gündüzler nasıl beklerse gecenin bitmesini

Sabırla söküyorum bu tarih gecesini.

Yüreğim usul usul vuruyor Kafkasyalım

Namludan yeni çıkmış sıcacık kurşun gibi

Dağlılar dağlar gibi ormanlar ordu gibi ağaçlar asker gibi

Bir şimal rüzgarı değil bir Şamil fırtınası

Tutsaklık haritası değil bir zafer coğrafyası

Can pazarında Azerbeycan''da

Bir türkü işliyor nakışını kalbimin üstüne

"Kurban olayım ayına ayına yıldızına"

Bir ucundan dünyanın öbür ucuna

Kan olup dolaşan damarlarımda

Arabistan''da Pakistan''da Türkistan''da

Şu anda

İran''da Afganistan''da.

Gecelerden bir gece en kesin bir tarih gecesini

Delecek elbet yangına uğramış gözlerim

İçimde kayalaşan bu güç bu savaş birikintisi

Sağdan sola kavisler çizerek

Ak bir kağıt üstünde dolaşır gibi

Dolaşan Asya''yı Afrika''yı Amerika''yı

Sonra bir solukta geçerek üstünden Avrupa''nın

Avrupa''nın Rusya''nın.

"Yememiştir hiç kimse

Elinin emeğinden daha hayırlısını"

diyerek

Şafak gibi alınlara terle yazılmış

Hakkın mutlak ölçüsünü

Elbet benim işçilerim çekecek

Emeğin kutsal direğine.

O ışık ki düşer bir zenci yüreğine

Birden aydınlık kazanır zulme uğramış bütün yürekler

Onulmaz Hint ağrısına tükenmez Çin sancısına

İsyanın Macarcasına ezilmenin Çekoslavakcasına

Yanmanın Polonyacasına direnmenin Vietnamcasına

Gerillanın Arapçasına

Yetişecek elbet benim müjdeci sesim.

Ey insan ey şimdilerde hep bir beklemeye duran

Duy zaman içre sürüp gelen bu sesi

Sürüp gelen çağlardan çağlara

Renk veren tarihe yeşil çağlayan

Savaşçı yüreğinden savaşçı yüreğine

Cezayirden senegalden

Yüreğimin içine Boğaziçine

Kelimelerden bir kelime diken yeryüzüne.

Dünyanın kalbini dinle geliyor adım adım

Dallar meyvaya dursun toprak tohuma dursun

İnsan barışa dursun selama dursun zaman

Sabır savaş zafer. Adım: MÜSLÜMAN', 'Yeryüzü bana mescit kılındı Ant verdim toprak şahit tutuldu Her sabah her öğle her akşam İkindiyle yıkanarak yatsıyla donanarak Seslerden bi...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/surup-gelen-caglardan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrildik', 'ayrildik-huseyin-cayikli-2evl0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ayrilidik 

bana derdi seni ben adam edecegim

sinemalara giderdik

alti parmakta burc sinemasi 

dile olsada konussa

tophane 

ve tabiki 38 numara

on yedi yasinda kocaman bir kadindi

cocukca bir gulumsemesi vardi

agladigini gordum icim ezildi? 

aglamasini istemedim

ama agladi

bende uzdum

hatalar yaptim

cok kirilgandi

ben de 

gurur onda iyimserlik var di? 

benimde cok hatalarim oldu? 

uzdum

simdi inaniyorum

beni terkettiginden beri 

anladim ki

ben adam oldum

dedigini yapti

ben nerden anlayayim gidecegini

gittikten sonra adam oldun

eger sevecekseniz

hatalar yapmayin

unutmayin

ben adam oldum...', 'ayrilidik  bana derdi seni ben adam edecegim sinemalara giderdik alti parmakta burc sinemasi  dile olsada konussa tophane  ve tabiki 38 numa...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ayrildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapışkan', 'yapiskan-anil-can-86d8l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'elele tutuşmak gibi geldi başta

o ilk tutuş heyecanlı şeker tadında

demek ki çiğnerken anlamamışım

şekerli sakız olduğunu

şekeri bittiğinde anladım

elini bıraktığımı ve

bıraktıklarımın yapış yapış olduğunu', 'elele tutuşmak gibi geldi başta o ilk tutuş heyecanlı şeker tadında demek ki çiğnerken anlamamışım şekerli sakız olduğunu şekeri bittiğinde ...', ARRAY['Türk Edebiyatı','Şiir','Anıl Can']::text[], 8.5, '{"poet":"Anıl Can","poet_slug":"anil-can","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yapiskan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay', 'kolay-tevfik-basar-urrxg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sensiz nedense

hep dalgalari hatirliyorum.

Ruzgarli bir havada

riskli gezintilere yol acan 

Denizcilere.

Nedense 

hep sorguladigim engeller var.

Sana dogru yururken

Aski yasamak 

benim icin

Bu kadarmi zor

ne dersin

Yoksa biz mi olamiyor.

Ben halbuki 

Bu biz kelimesini

ne kadar da kolay agzima almistim.

Ne kadar da kolay.', 'Ben sensiz nedense hep dalgalari hatirliyorum. Ruzgarli bir havada riskli gezintilere yol acan  Denizcilere. Nedense  hep sorguladigim engel...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Başar']::text[], 8.5, '{"poet":"Tevfik Başar","poet_slug":"tevfik-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kolay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzanmak', 'uzanmak-tevfik-basar-kaija', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahcelere uzanmak

kolejli gencler gibi

bahar senliklerinde

Bir ben uzanamadim

seninle yan yana.

Keske hayati kolaylastirabilsek

belki o zaman daha cok

ve de daha rahat vakit bulabiliriz

uzanmaya bahcelere.

Hem uzanmaya hemde hayal etmeye

ikimiz uzerine.', 'Bahcelere uzanmak kolejli gencler gibi bahar senliklerinde Bir ben uzanamadim seninle yan yana. Keske hayati kolaylastirabilsek belki o zama...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Başar']::text[], 8.5, '{"poet":"Tevfik Başar","poet_slug":"tevfik-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uzanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ismin', 'ismin-tevfik-basar-fhqw3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sakin 

Ama sakin ismini

Kendin gibi gorme

Onun gibi olamazsin

Onunla ayni kefeye

koyma kendini

ovunme bile.

Yeterki rahat birak

birak da bana anlattiklariyla ovunsun.', 'Sakin  Ama sakin ismini Kendin gibi gorme Onun gibi olamazsin Onunla ayni kefeye koyma kendini ovunme bile. Yeterki rahat birak birak da ban...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Başar']::text[], 8.5, '{"poet":"Tevfik Başar","poet_slug":"tevfik-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ismin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cep Telefonu', 'cep-telefonu-tevfik-basar-wr5wu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cep Telefonu

geleli Turkiyeye

daha az ariyorsun beni.

Bilmiyorum belki

ulasilmasi iletisim kurmak icin

zor olaninmi degeri artiyor.

Yoksa

acalemi olu her dakika beni aramak

yokken ortada bir sey.

Ben mi kusuyum teknolojiye

seni benden uzaklastiriyor

yada baska anlamlar katiyor diye 

Benligine.', 'Cep Telefonu geleli Turkiyeye daha az ariyorsun beni. Bilmiyorum belki ulasilmasi iletisim kurmak icin zor olaninmi degeri artiyor. Yoksa ac...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Başar']::text[], 8.5, '{"poet":"Tevfik Başar","poet_slug":"tevfik-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cep-telefonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Aşkım', 'i-lk-askim-hakan-akyurt-o9q0d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kız severdim eskiden, gözleri kara.

Parlak saçları omzunda geceden yana.

Bana bir baktı mı, kalbim hızla çarpardı, 

Sevmiştim onu ben, o benim ilk aşkımdı.

El ele tutuşarak gezerdik sokaklarda, 

Unutarak dünya''yı dalardık yarınlara.

Cilveliydi sözleri beni benden alırdı, 

Sevmiştim onu ben, o benim ilk aşkımdı.

Ayrılık varmış meğer, şu zalim dünya''da.

Hatıralar kalır sadece, sevgiden yana.

Artık yanımda yok, o aşkımız kalmadı.

Sevmesemde şimdi ben, o benim ilk aşkımdı...', 'Bir kız severdim eskiden, gözleri kara. Parlak saçları omzunda geceden yana. Bana bir baktı mı, kalbim hızla çarpardı,  Sevmiştim onu ben, o...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilk-askim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanama', 'kanama-edip-cangonul-ly4di', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yırtılır çeperler

Hırsından, 

Bazı kör bir bıçak yarası.

Tanrıya da yorsan olur, 

İnanmamak da elinde.

Akar karanfiller, 

Akar kızıl gül.

Akarlar

Dost, kardeş

Bir el basar

Bastırır

Zalim

El elidir

Karanfiller tutar kızıl gülün elini

Çepere kireç

Çepere kum

Çepere su

Çeperde beton olurlar

Kardeş dostluğunu bilmez

Oğul can’lığını

El eli

Elin eli', 'Yırtılır çeperler Hırsından,  Bazı kör bir bıçak yarası. Tanrıya da yorsan olur,  İnanmamak da elinde. Akar karanfiller,  Akar kızıl gül. Ak...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kanama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Nöbetleri', 'yalnizlik-nobetleri-selcuk-akcay-381pn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kendi ellerimle gömmek seni; 

hayallerimizi rafa kaldırıp 

karanlığıma dönmek, 

unutmak tüm yiteni.

hakim olmak gözlerimden dökülene, 

bastırmak sızlayan yüreğini elinle, 

tüm bunlar olurken dönüp gitmek, 

sanki erkenden ölmek.

pişmanlıklar yargılar beynimi

sorgular başlar, zaman zaman

elim telefona gider bir an

o an unuturum tüm geçeni', 'kendi ellerimle gömmek seni;  hayallerimizi rafa kaldırıp  karanlığıma dönmek,  unutmak tüm yiteni. hakim olmak gözlerimden dökülene,  bastı...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlik-nobetleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Kolay Sevemedim', 'ben-seni-kolay-sevemedim-selcuk-akcay-mdls6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben seni kolay sevemedim

her hatırladığımda

acı verdi aşkın.

gözlerinin büyüsüne her kapıldığımda, 

yüreğimde sızlayan yerleri gezdi, 

titreyen yarı donuk ellerim.

aşkın umut; umudun yaşamak olduğunu, 

yalnızlığımda sıcacık ellerine dokunduğumu, 

beni düşünürken gözlerinde bir damla yaş olduğunu, 

kolay farkedemedim.

el ele dolaştığımız caddede son kez bakışırken, 

soğuk havaya bağladım gözünden akan yaşları.

ellerin ellerimi terkederken, 

kolay bilemedim ayrılığın kalbine açtığı yarayı.

her düşündüğümde sadakatli sesini

mecbur eden neydi dedim, çağırdığında

ansızın bana gelişini, 

rüyalarıma girdiğinden beri, 

inan ben kolay sevemedim seni.

bakışlarında bir deryayı aradım.

çoğunlukla sevgiden fazlasını.

ben kolay sevemedim seni.

unutamadım da.

sevdan damarlarımda dolaştı her zaman.

soluduğum havada sen vardın, 

ne vakit aklıma geldiğinde

yaşamanın sen olduğunu anladım.

ben kolay sevemedim seni.

unutamadım da.

zaten kaç zamandır yaşamıyorum.

aklımın bir ucunda düşünceler, 

hep sana yoğunlaşıyor.

sesin kulaklarımda yankılanıyor.

ben kolay sevemedim seni.

haksızlıklar, zorbalıklar karşısında, 

direndim koruyarak, sevdiğimi.

çoğu zaman hayatı buldum, 

bu yüzden sevdim kömür karası gözlerini.

ben kolay sevemedim seni.

unutamadım da...

S.A. (26,12,2001)', 'ben seni kolay sevemedim her hatırladığımda acı verdi aşkın. gözlerinin büyüsüne her kapıldığımda,  yüreğimde sızlayan yerleri gezdi,  titre...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ben-seni-kolay-sevemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-selcuk-akcay-i0141', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bugün bir parça koptu kalbimden. 

o parçaya senin adını verdim.

ayrılırken ellerin ellerimden, 

ben umutlarımı yollarına serdim.

şimdi hatırımda senden kalan, 

sıcacık gülüşün ve ellerin.

ok misali kalbime saplanıyor, 

başıbaoş sensiz düşüncelerim.', 'bugün bir parça koptu kalbimden.  o parçaya senin adını verdim. ayrılırken ellerin ellerimden,  ben umutlarımı yollarına serdim. şimdi hatır...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bugun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşları', 'gozyaslari-selcuk-akcay-u9uw1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'camlarda yapayalnız, biçare bakıyorsun.

dev dalgaları yarıp sana gelsem, 

sana maziden bir anı getirsem.

tükenmez gözyaşın içime akıyor.

ne yapsam, nereye gitsem

dertler hançer gibi kalbime batıyor.

gelip gözyaşlarını ellerimle silsem, 

tükenmez gözyaşın içime akıyor.

gece olup rüyalarına girsem, 

seni bir düşte sevsem, 

yüzünde ufacık bir hüzün görsem, 

tükenmez gözyaşın içime akıyor.

sarı bir yaprak olup camına düşsem, 

teninde yabancı eller görsem, 

ne zaman beni unuttu desem, 

tükenmez gözyaşın içime akıyor.', 'camlarda yapayalnız, biçare bakıyorsun. dev dalgaları yarıp sana gelsem,  sana maziden bir anı getirsem. tükenmez gözyaşın içime akıyor. ne ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozyaslari-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-oguzkan-bolukbasi-w3cpj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ölüm kadar güzelsin yaşamak kadar acı

hayat kadehinde kalan en son damlasın

ben kadehin içinde kadeh bana yabancı

için siz o damlayı bana birşey kalmasın', 'ölüm kadar güzelsin yaşamak kadar acı hayat kadehinde kalan en son damlasın ben kadehin içinde kadeh bana yabancı için siz o damlayı bana bi...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olum-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sofu Baba', 'sofu-baba-mahzuni-serif-opvth', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gücenme ey sofu baba 

Biz aşığız kör değiliz 

Ver bir selam al merhaba 

İkiliğe yar değiliz 

Hudey hudey pir aşkına 

Yol verin gitsin şaşkına 

Adaletsiz padişahın 

Canavar girsin köşküne 

Adem olan adem sever 

Adalete boyun eğer 

Kul hakkı dünyayı değer 

Biz cana kıyar değiliz 

O o o o o o meyhaneci 

Şarab''ın bugün çok acı 

İnsanlar konar göçerler 

Kimi hoca kimi hacı 

Gider Kul Mahzuni gider 

Gider dostu tavaf eder 

Benim bildiğim bu kadar 

Biz cahile uyar değiliz 

Hudey hudey hür aşkına 

Biz içeriz pir aşkına 

Adaletsiz Hükümdarın 

Ateşler düşsün köşküne 

O o o o o o meyhaneci 

Bugün şarab''ın çok acı 

İnsanlar kabe misali 

Gelen derviş giden hacı.', 'Gücenme ey sofu baba  Biz aşığız kör değiliz  Ver bir selam al merhaba  İkiliğe yar değiliz  Hudey hudey pir aşkına  Yol verin gitsin şaşkın...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sofu-baba-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gol Gol', 'gol-gol-mahzuni-serif-euqdu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bal gibi yan tuttun 

Hakemliği unuttun 

Seyiciyi uyuttun 

Bu giren gol gol 

Meşin topta şike var 

Arasında leke var 

Takımlarda şike var 

Bu giren gol gol 

Top köşeden geliyor 

Tam ortayı buluyor 

Madem ağı deliyor 

Bu giren gol gol 

Yandan akın başladı 

Savunmaya başladı 

Kaptan topu tuşladı 

Bu giren gol gol 

Yüksek ücreti aldı 

Hakem yapar kahvaltı 

İmkan yoktur penaltı 

Bu giren gol gol 

Mahzuni hakem topal 

Bizimki korku nifa 

Oyun bitti düdük çal 

Bu giren gol gol', 'Bal gibi yan tuttun  Hakemliği unuttun  Seyiciyi uyuttun  Bu giren gol gol  Meşin topta şike var  Arasında leke var  Takımlarda şike var  Bu...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gol-gol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Softalar', 'softalar-mahzuni-serif-iloor', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey Arapça okuyanlar 

Allah Türkçe bilmiyor mu? 

İngilizce Franzısca 

Bize hitap kılmıyor mu? 

Çalışanlar geri kalmaz 

Çalışmayan bir halt bilmez 

Yalnızca fikirler ölmez 

Peygamberler ölmüyor mu? 

Bizimdir bu bahçe, bağlar 

Bizimdir bu yeşil dağlar 

Canı sağ olsun softalar 

Ayakkabı çalmıyor mu? 

Dost gezer dostluk bağında 

Biz olur bizlik dağında 

Gavurun Merih çağında 

Alem bize gülmüyor mu? 

Bir bülbül getirmez yazı 

Yalnızca bülbül avazı 

Mahzuni korkmadan sazı 

Kainat''a çalmıyor mu?', 'Ey Arapça okuyanlar  Allah Türkçe bilmiyor mu?  İngilizce Franzısca  Bize hitap kılmıyor mu?  Çalışanlar geri kalmaz  Çalışmayan bir halt bi...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/softalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eseri Gördüm', 'eseri-gordum-mahzuni-serif-giju6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben ağlamam On Kasım''da 

O''nu, her gün diri gördüm 

Ölene dek göreceğim 

Doğalıdan beri gördüm 

Halka, vermişti canını 

Hak''tan almış ünvanını 

Atmış, Osmanlı şanını 

Samsun''da bir eri gördüm 

Matemin doyurmaz beni 

Minnetim kucaklar seni 

Bize cennet gibi yeni 

Verdiğin eseri gördüm 

Ulu Atam, inan buna 

Düşkünler hayrandır sana 

Mazlum Milletler adına 

Sendeki zaferi gördüm 

Ne hikmet, varıdı sende 

Güneştin, doğdun cihanda 

Bin yılların ötesinde 

El bastığın, yeri gördüm 

Mahzuni yoluna düştüm 

Nice nice engel aştım 

On Kasım''da kaybetmiştim 

Daha şimdi geri gördüm', 'Ben ağlamam On Kasım''da  O''nu, her gün diri gördüm  Ölene dek göreceğim  Doğalıdan beri gördüm  Halka, vermişti canını  Hak''tan almış ünvanı...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/eseri-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Doktor', 'aci-doktor-mahzuni-serif-81b01', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Berçenek''ten yaya geldim 

Amman doktor bak bebeğe 

Beşiğini elden aldım 

Yandım doktor bak bebeğe 

Yıkık yuvam kara yasta 

Yalvarırım eşe dosta 

Annesi bebekten hasta 

Amman doktor bak bebeğe 

Kuru soğan yağsız aşım 

Yırtık bağrım açık başım 

Bir şey değil vatandaşım 

Amman doktor bak bebeğe 

Allah için bir merhem çal 

Öldürür beni bu vebal 

Param yok ceketimi al 

Amman doktor bak bebeğe 

Mahzuni Şerif çobandır 

Meskenim dumanlı dağdır 

Bebektir amma insandır 

Amman doktor bak bebeğe', 'Berçenek''ten yaya geldim  Amman doktor bak bebeğe  Beşiğini elden aldım  Yandım doktor bak bebeğe  Yıkık yuvam kara yasta  Yalvarırım eşe do...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aci-doktor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yatar Ağlarım', 'yatar-aglarim-mahzuni-serif-cck2u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün benim yeşil bağım kurudu 

Dolu vurdu yapraklarım çürüdü 

Benim de saz tutan elim var idi 

Şimdi bir köşede yatar ağlarım 

Benim ile lokma yiyip içenler 

Gölgemin altında konup göçenler 

Sizi zalim dar günümde kaçanlar 

Ben kendi kendime çatar ağlarım 

Çırpına çırpına bir yuva kurdum 

Bebeği görmedim kundağı gördüm 

Derya''da boğuldum karaya vurdum 

Çileden çileye bakar ağlarım 

Mahzuni Şerif''im budur ahvalim 

Zamane bozulmuş insanlar zalim 

Kıyamete kadar gider bu halim 

Sabır edip matem tutar ağlarım', 'Bugün benim yeşil bağım kurudu  Dolu vurdu yapraklarım çürüdü  Benim de saz tutan elim var idi  Şimdi bir köşede yatar ağlarım  Benim ile lo...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yatar-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardiyan', 'gardiyan-mahzuni-serif-naksb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam oldu yine hapis kitlendi 

Demir perdeleri çekme gardiyan 

Ne yar''dan haber var ne mektup salan 

Bi de sen belimi bükme gardiyan 

Bizi seven dostlar şimdi çekildi 

Gam tarlama dert kesavet ekildi 

Umuduma yeni fidan dikildi 

Kırık dallarımı yakma gardiyan 

Mahzuni Şerif'' im iki yüzlüler 

Yaktı yüreğimi bağrım sızılar 

Fadimem yol bekler ağlar kuzular 

At mektubu belim bükme gardiyan', 'Akşam oldu yine hapis kitlendi  Demir perdeleri çekme gardiyan  Ne yar''dan haber var ne mektup salan  Bi de sen belimi bükme gardiyan  Bizi ...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gardiyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-mahzuni-serif-k8sqs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana hasret, sana hayran gönlümüz

Sarı saçlım, mavi gözlüm nerdesin

Bu gemi bu ''Kara Deniz'' 

Sarı saçlım, mavi gözlüm nerdesin

Kara peçe, yakışmıyor kullara

Kurban olam şu gittiğin yollara

Hele uyan bir bak bizim hallara

Sarı saçlım, mavi gözlüm nerdesin

Bulutlar teriden, dağlar kokundan

Sarhoştur Mahzuni, senin kokudan

Bir daha gel gel ha Samsun''dan

Sarı saçlım, mavi gözlüm nerdesin', 'Sana hasret, sana hayran gönlümüz Sarı saçlım, mavi gözlüm nerdesin Bu gemi bu ''Kara Deniz''  Sarı saçlım, mavi gözlüm nerdesin Kara peçe, ya...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerdesin-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Su', 'sen-su-mehmet-latif-i-nanc-q8hv3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesini sevdaya bırakan su

Usandım dünyadan, hep gelecek korkusu

Ne zaman bir bakışa hırslansam

Ansızın takılıp gölgemin gölgesine

Düşüp yüz üstü, suskunluğuma küserim 

Ela edana takılınca da aklım

Neyse deyip yürek kesemi büzerim

İlk defa üşüdüğümü sezinliyorum bu yazda

Zehir mavisi gözler yakıyor ayazda

En dipten yakarışlar tıkalı boğazda

Rakseder hislerim kopuk telli sazda...

                                                 Haziran-99', 'Sesini sevdaya bırakan su Usandım dünyadan, hep gelecek korkusu Ne zaman bir bakışa hırslansam Ansızın takılıp gölgemin gölgesine Düşüp yüz ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Latif İnanç']::text[], 8.5, '{"poet":"Mehmet Latif İnanç","poet_slug":"mehmet-latif-i-nanc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Bulutları', 'kara-bulutlari-sair-gunisigi-sd9sm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DOLUNAY vakti

Şavak vakti

Derimi keser

 Kar bulutları

Yogunlaşmış zaman dipsiz kuyuya

Nezaman yaz vakti yaprak kurusa

Güneşe gölge kar bulutları

en kalın damarı kurumuşsa sevinin

Arılık estirir serin serin

Gönlü bogar çölde kar bulutlar

KAPILARINI kapamışsa bahar

kavurmuşsa ortalıgı rüzgar 

Gökyüzünden deli deli bakar

Severken girer gözüme kar bulutları

HASRETİM bitmez

Ömrüm yetmez

Yüregimi yer

Kar bulutları.', 'DOLUNAY vakti Şavak vakti Derimi keser  Kar bulutları Yogunlaşmış zaman dipsiz kuyuya Nezaman yaz vakti yaprak kurusa Güneşe gölge kar bulut...', ARRAY['Türk Edebiyatı','Şiir','Şair Günışığı']::text[], 8.5, '{"poet":"Şair Günışığı","poet_slug":"sair-gunisigi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kara-bulutlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Günü Değil!', 'sevmek-gunu-degil-yusuf-pangal-ay4u0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bahar manzumesi gülüşün çiçeklere...

Korkak bir yaz akşamı...Esiyorken rüzgarın; 

Bin bir mana her bakış, kendinden ürkeklere.

Pür cesaret dağıtır savurduğun baharın.

Elveda ey gökyüzü, elveda taze bahar! 

Bin korku bin velvele getirdiğinde rüzgar.

Çiçeklerim açsa da senden dökülünce kar; 

Sevmek günü değil bu! Belki olursa, yarın.', 'Bir bahar manzumesi gülüşün çiçeklere... Korkak bir yaz akşamı...Esiyorken rüzgarın;  Bin bir mana her bakış, kendinden ürkeklere. Pür cesar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevmek-gunu-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutum Ne Çare Gözlerini', 'unutum-ne-care-gozlerini-ahmet-arican-rgonb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırlıyorumda ''araya yol girince''

''unutursun beni'' diyen sendin

benimde cevabım

''nasıl unuturum''

''unutamam'' olmuştu.

yine de unuttuğum söylenemez

ama bir farkla; 

ilgim o ilgi değil, 

sevgim o sevgi mi? 

aşk mı? kalbimde dirhemi bile olmayan

Belki de hepsi palavra

hiç bir his kalmadı sana karşı

sadece boş gözlerle resmine bakıyorum

ne kadar zorlasam da kendimi faydasız

sen de benim için ötekilerden birisin

vefasız, hayırsız, sadece bir kız....

unuttum ne çare artık gözlerini

gülebilirsin güzelim

haklıydın sen kazandın

bunda da yandin beni....

MaskADAM

ilker bartu', 'Hatırlıyorumda ''araya yol girince'' ''unutursun beni'' diyen sendin benimde cevabım ''nasıl unuturum'' ''unutamam'' olmuştu. yine de unuttuğum söyl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Arıcan']::text[], 8.5, '{"poet":"Ahmet Arıcan","poet_slug":"ahmet-arican","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/unutum-ne-care-gozlerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affedemem', 'affedemem-ahmet-arican-w9w5g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aksa gözyaşların delice coşan sel suyu gibi

Kurusa göz pınarların çölde susuz kuyu gibi

Kirpiklerin yapış yapışda olsa birtanem

O an arkamdan boşuna yalvarma; dönemem..! 

Kıraç toprak gibi susuzluktan çatlasa her yanın

Bir yağmura hasret damarlarından çekilse kanın

Bir akşam vakti Azrail almaya gelse de canın

Son sözün Affet! olsa da Affedemem...! 

13.10.1986', 'Aksa gözyaşların delice coşan sel suyu gibi Kurusa göz pınarların çölde susuz kuyu gibi Kirpiklerin yapış yapışda olsa birtanem O an arkamda...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Arıcan']::text[], 8.5, '{"poet":"Ahmet Arıcan","poet_slug":"ahmet-arican","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/affedemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmi Saklı 2', 'i-smi-sakli-2-ahmet-arican-ya7u2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen şarkı söylerken, sesin

duvarlara çarpar, titrerdin

gözlerinden dökülen nağmeler

boncuk boncuk...

uzandım tutamadım, 

hala hafızamdasın

ve hala

unatamadım....', 'Sen şarkı söylerken, sesin duvarlara çarpar, titrerdin gözlerinden dökülen nağmeler boncuk boncuk... uzandım tutamadım,  hala hafızamdasın v...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Arıcan']::text[], 8.5, '{"poet":"Ahmet Arıcan","poet_slug":"ahmet-arican","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ismi-sakli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittim İşte', 'gittim-i-ste-ahmet-arican-d5yng', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidiyorum işte güzelim mutlu oldun mu? 

Artık seni sürekli rahatsız eden de kalmayacak

Israrla gelmeni isteyen...

Israrla seni bekleyen de olmayacak

Bundan sonra üzülmeyeceksin bir tanem

Gidiyorum istemeye istemeye...

Gidiyorum bir yığın boşlukla beraber yüreğim

Artık istesem de gelemeyeceğim

Milyonlarca saati sensiz geçireceğim

Nede olsa alıştırdın artık beni buna

Ama yine de her şeye rağmen

Mutluyum demek geliyor içimden

Yalnızlığın buruk hüznü

Bir zehir gibi otursa da mideme

Ve çevrem de

Gördükçe onca mutsuz insanı

Mutsuz olduğumu söylemek 

İsyan olmaz mı kaderime

Kocaman yüreğine emanet ediyorum seni

Kötülük gelmez o yerden bilirim

Ama insanlar güvenemem bir türlü

Çılgınca arzudan başka şeyi olmayan insanlara

Aşk diye tanımlanan o ikilem duygulara

Kendime bile güvenemem de bazen...

Sana güvenirim iki gözüm bir tanem

Sana güvenirim yüreğim

Ama korkarım ki soğukluk girdi girecek

Yol ıraksa gönülden de ırak olunur bilmez misin

Belki bitmez ama azalacaktır sevgimiz

Artık haftada bir de olsa hatırlamaz olacaksın

Mesajların kesilecek bir bıçak gibi

Belki de bir yığın kuşkular saracak bizi

Irak olunca gönüller...

Kuruyacak sevgi denizi

Gel diyebilecek cesareti bile bulamayacağız kendimizde...

Gurur! Kahrolası gururumuz engelleyecek bizi

Bundan sonra konuşabilirsin

Sustun! Sustun çünkü hep yanımda

Sustum! Ben de sustum konuşamadım

Takılı kaldı kelimeler boğazımda

İçime attım kızgınlığımı öfkemi

İçime attım büyük nefretimi

Nefretimle dolu sevgimi

Üzdük birbirimizi durmadan

Üzüldük sonra boş yere çocuklar gibi

Oysa! 

Sabahları zor eder oldum 

sebepsiz seni üzdüğüm dakikalardan sonra

hata aramak istemiyorum

belki ikimiz de hatalı

belki de hiç

ama yine de ısrar edersen

birlikte olmayı istemek hataysa eğer

yada buna dersen günah

ben çok büyük hata işledim

çok büyük günah

çünkü seni ilk tanıdığım andan beri

seni istedim

sürekli tüm benliğimle 

seni düşledim

çok cimrisin güzelim çok cimri

ben sonuna kadar açmışken gönül evimi

sen dirhemle bile vermedin sevgini

korktun mu..? 

sakladın mı..? 

belki her ikisi de 

belki de sadece 

hiç...! 

yakındık sözlerde 

yakındık gözlerde

peki ya gönüllerde...? 

sordun mu bana efkarımın büyüklüğünü

konuşamamamın hüznünü

yo...

hayır..! 

kaçtın sürekli kaçtın

tartışmaktan kaçtın

kaçtın haklı olduğumu biliyordun

haklısın dememek için kaçtın

gidiyorum işte

bir yığın cevapsız soruları da alarak bavuluma

açmayacağım orda kesinlikle bu bavulu

biliyorum açarsam

ya kafayı üşüteceğim 

yada senden vazgeçeceğim

senden vazgeçmek mi...! 

nasıl söyler bunu elim 

asla....

bu belki hiçbir zaman yapamayacağım şey

sana saygım sevgimden yoğun

ve seni ölesiye seviyorum

belki görülmez

belki duyulmaz

ama anlatılmaz gülüm

anlatılamaz

artık gülebilirsin

ve hatta alayda edebilirsin

okurken yazdıklarımı

nasılda dalgamı geçtim diyebilirsin

kızmam

darılmam

inan buna

yeter ki gerçek olsun

yeter ki bana karşı

tek samimi davranışın bu olsun.....', 'Gidiyorum işte güzelim mutlu oldun mu?  Artık seni sürekli rahatsız eden de kalmayacak Israrla gelmeni isteyen... Israrla seni bekleyen de o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Arıcan']::text[], 8.5, '{"poet":"Ahmet Arıcan","poet_slug":"ahmet-arican","theme":"Türk Şiiri","is_hero":false,"total_lines":105,"source_url":"https://www.antoloji.com/gittim-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-ahmet-arican-sa1re', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dünya artık kocamış dostum

dünya kocamış artık

ve biz unutsak ta ortak bağlarımızı

ve birbirimizi tanıyamasak ta

ve giderek yüzlerimiz, 

benzemese de gerçeğe

yada 

hasret kalsakta gülmeye

çekirdeksel tebesüm

yeterki özgür olsun.....', 'dünya artık kocamış dostum dünya kocamış artık ve biz unutsak ta ortak bağlarımızı ve birbirimizi tanıyamasak ta ve giderek yüzlerimiz,  ben...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Arıcan']::text[], 8.5, '{"poet":"Ahmet Arıcan","poet_slug":"ahmet-arican","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dunya-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlar mısın... (Rumuzlar)', 'hatirlar-misin-rumuzlar-erdal-gisi-0prfk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahar çiçekleri derdik... mor-sarı 

Ebemkuşağı doğardı yağmurdan 

Mevsimler daha iki değildi 

Dua ederdik uyumadan... 

Sen ata hayrandın ben ceylan 

Bir rüzgar eserse güneydoğudan 

Hatırlar mısın...

Herşey basitce başlar 

Bir fikir dünyayı yakmaya gider 

Bir tohum çınara 

Bir kedi aslana inkilap eder 

Açmamış karanfil görürsen eğer 

Hatırlar mısın...

İstanbul sisli yine

Pazar sabahı kadar sessiz 

Karşında ağlıyor gül

Nargile çekerken halsiz... 

Vapur sirenleriyle 

Bir hayal dolarsa kimsesiz 

Hatırlar mısın...

Merakın mı... zevkin mi bilmem 

Başını çekersin cellat elinden 

Kapılar açılır 

Kitabevimidir sohbet evi mi 

Gelinciğe benzer kapağın rengi 

Sözleri görürsen 

Hatırlar mısın...

Herşeyin eskidiği anlar olur 

Dolaşırsın odanda buğu buğu 

Elin Furkan''a dokunur 

Yusuf suresi... 

''sabrı cemil'', Yakub''un tek sermayesi 

Kokusuyla avunur 

Hatırlar mısın...

Koca şehir bastırır yalnızlıkla

Tıpkı deniz gibi sahile atar

Dalgalar da martılar da yabancı...

Birliklte yudumlamak için bir fincan

Bir dost gerek şimdi budur ilacı...

Derken...

Ürkek bahanelerin göz kırpar 

Korkular olursa gönlünün harcı

Hatırlar mısın...

Güneş burçlarda döner... 

Hergün fallarını okurdu biri

Kararsızdı ikizler...

Çaresizlik intiharı 

Akrebin kaderi der bilenler

Hatırlar mısın... 

Eflatun yaban rengi

Eflatun bir tutkuydu

Güneş bile doğarken

Eflatun umutluydu

Kimbilir senin için hangi renk uğurluydu...

Hatırlar mısın... 

Şimdi İstanbul nere

Hala var mısın... 

Hatırlar mısın...

Yoksa unutmak mı erdem bilemem 

...

2002', 'Bahar çiçekleri derdik... mor-sarı  Ebemkuşağı doğardı yağmurdan  Mevsimler daha iki değildi  Dua ederdik uyumadan...  Sen ata hayrandın ben...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/hatirlar-misin-rumuzlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matem Yüklü Martılar', 'matem-yuklu-martilar-mahmut-sami-gurpinar-2mnrq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Havada soğuk bir sessizlik

Ay sanki soluk bir ışık yayıyor

Kuşlarda bilinmeyen bir belirsizlik

Sanki bu gönül seni arıyor

Gri bir matem yüklü havada

Hava karanlık ve yorgun

Sanki dolaşıyorum yaylada

Sanki deniz biraz durgun

Sanki matem yüklüydü martılar

Sabahın ilk ışıklarıyla göründüler

Sanki dertli bir türkü çaldılar

Ve gecenin karanlığına büründüler', 'Havada soğuk bir sessizlik Ay sanki soluk bir ışık yayıyor Kuşlarda bilinmeyen bir belirsizlik Sanki bu gönül seni arıyor Gri bir matem yükl...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Sami Gürpınar']::text[], 8.5, '{"poet":"Mahmut Sami Gürpınar","poet_slug":"mahmut-sami-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/matem-yuklu-martilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Yusuf', 'deli-yusuf-huseyin-kerim-ece-ddna3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Herkesin rüzgârı özgür derler de, 

Damgalıdır yine yeli Yusuf’un, 

Yüryüzü denizi geniştir amma, 

Bir damla tutamaz eli Yusuf’un, 

Kalın bir çizgidir umut duvarda, 

Sevda can çekişen bir kuştur karda, 

Kimi hamuduyla deve yutar da; 

Urgandan sayılır teli Yusuf’un, 

Hayal bir renk, göğün yedi katında, 

Açacak gül müdür onun bahtında? 

Bunca kederin ve yükün altında, 

Ya sabır haykırır beli Yusuf’un, 

Bu kadîm kanunun hükmü açıkmış, 

Böyle mirası kim, kime bırakmış? 

Bakın hele; adı mecnuna çıkmış, 

Halkın arasında! deli Yusuf’un.

Derler ki büyüktür bu işin bedeli Yusuf! 

Dünyanın halidir, aldırma be deli Yusuf! 

19/2/2002 

Zaandam', 'Herkesin rüzgârı özgür derler de,  Damgalıdır yine yeli Yusuf’un,  Yüryüzü denizi geniştir amma,  Bir damla tutamaz eli Yusuf’un,  Kalın bir...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deli-yusuf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyum Ele Geçmez Ufuktur', 'doyum-ele-gecmez-ufuktur-huseyin-kerim-ece-valfo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umut şehlâ gözlü, bir ceylandır ormanlarda

Koşturur peşi sıra müstesna zamanlarda 

Yalancı fecre doğru çizgidir uzun emel

Aynalarda dolaşan binbir hayâle bedel

Islanırken gururla derin göz bebekleri

Bir kabuğu doldurmaz binlerin emekleri

Kim çıkar yarına, kim çözer bu düğümleri? 

Bahar hüzünlü ise, rüzgâr da bir serseri? 

Ne oldu bilmiyorum, isterken sonsuzluğu? 

Damla su yok, gidermek üzere susuzluğu, 

Uzay fethetmek için ederken binbir yemin

Gökler sarsılır, titrer ayak altında zemin, 

Gelen gidiyor, giden geri dönüp bakmıyor, 

Öyle bir pençe ki bak, tutunca bırakmıyor, 

Gördün; doyum dediğin ele geçmez ufuktur, 

Ve her insan, biraz da, büyümeyen çocuktur.

28/2/2002 

Zaandam', 'Umut şehlâ gözlü, bir ceylandır ormanlarda Koşturur peşi sıra müstesna zamanlarda  Yalancı fecre doğru çizgidir uzun emel Aynalarda dolaşan ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/doyum-ele-gecmez-ufuktur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehtap Suya Yakın', 'mehtap-suya-yakin-huseyin-kerim-ece-1pt19', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ufuklar gecelerde arar da mehtâbını, 

Gönlüm o an seyreder kâinat kitabını, 

Gülünce fecir, doğar dallarda tomurcuklar, 

Elele tutuşmuş, oynuyorken çocuklar, 

Bu, rüya ülkesinin hiç solmayan sesidir, 

Muştu haberi değil, muştunun kendisidir, 

Mehtâb suya yakın, su duyguları ıslatır, 

Tatlı bir nağme ile başlar suda her satır, 

Baharın gözlerinde aranan ab-ı hayat, 

Müstesna bir duaya durmaktadır kâinat, 

Saadet fırçasıdır, izi her bir resimde

Bir sabaha uyanır gülücükler içimde, 

Canlandırır da ruhu bir kekliğin ötüşü, 

Bütün günü ısıtır bir bebeğin gülüşü, 

Adını emerek bir yıldızın bakışından

Dosta destan yazılır suların akışından...

1/3/2002 Zaandam

[email protected]', 'Ufuklar gecelerde arar da mehtâbını,  Gönlüm o an seyreder kâinat kitabını,  Gülünce fecir, doğar dallarda tomurcuklar,  Elele tutuşmuş, oyn...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mehtap-suya-yakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyir', 'seyir-huseyin-kerim-ece-yvhrt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir nehir boyunca geçen zamanın

İmzası duruyor yanaklarımda

Ağını örmüş de hevâ ve heves, 

İpliği dolaşmış parmaklarımda

Bir lâbirent gibi içiçe yollar

Yol işaretleri topraklarımda

Yanar sulardaki aynanın yüzü

Feryadı yükselir tırnaklarımda

Yol uzun, azık az, menzil ötede

Hiç takat kalmamış ayaklarımda

Umarken hem günün uzamasını

Ay ışığı doğmuş şakaklarımda.

Yağmurda beklerken yol ayrımında

Yıkıldı gökyüzü evin damında

İnci arayanlar tenha sularda

Ruhu kaybettiler başka kenarda

Deniz şahididir bitkin bir yüzün

Her kapıyı çalar yaşanmış hüzün

Kim gezer sevdanın ak sahilini

Kim çözer tutkunun çetrefilini

Sorulara nerde cevap bulunur

Ölüme ne zaman kardeş olunur

Açılır esrardan bir bir perdeler

Öteden bir davet bize de gel der.

Gidenler buradan erken gittiler

Şimdi hayalleri duruyor safta

Kanserli hastaya hüküm verilmiş

Herşey tamam, şimdi sıra itlafta

Karanlık bastırdı, yönler karıştı

Leylâ’ya giden yol hangi tarafta

Endam aldatıcı, özde bir şey yok

Herkesin ünvanı yazık ki lâfta

Hani zenginliğin billûr sarayı

İflasın hesabı eski bir rafta

Hiç bir şey yerinde durmuyor, heyhat

Anılar bekliyor bir fotoğrafta.

Tutunduğum dallar demirden midir? 

Yosunla sarılan ham beden midir? 

Ne oluyor gökte, ne çatırdıyor? 

Bütün gölgeler o yana gidiyor

Nefesler tutuldu, gözün feri yok, 

Bir atımlık barut, bir çekimlik ok

Zaman çevriliyor, vakit akıyor

Herkes bir hayale dönmüş bakıyor

Yıldızlar fezada bir salkım üzüm

Ve evde bekliyor sevgili ölüm

Ne yâr kalır burda, ne dost selâmı

Hayatın gelecek bir gün devamı.

26/3/2002 Zaandam', 'Bir nehir boyunca geçen zamanın İmzası duruyor yanaklarımda Ağını örmüş de hevâ ve heves,  İpliği dolaşmış parmaklarımda Bir lâbirent gibi i...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/seyir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıya Aşina Bir Yüzün İfadesi', 'aciya-asina-bir-yuzun-i-fadesi-huseyin-kerim-ece-siwy3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Havanın karardığı andır yürekteki söz

Hangi resime baksam çeviriyor yüzünü

Saçlarımı yakıyor mendilimde sönmüş köz

Aynalar çoğaltınca unutulmuş bir hüznü

Bulutun ağladığı geceyi bulamadım

Sana giden yol nedir, nasıldır; bilemedim

Göğsümü açtım aya karşı hep ayazlarda

Ufuktaki kızıllık gitmedi hayalimden

Ve titredim, yutkundum, en derin niyazlarda

Sudaki halka bile etkilendi halimden

Bulutun ağladığı geceyi bulamadım

Seherin dudağından sabahı alamadım

Seni aradım yine kelebeğin renginde

Bir gülücük bûsesi bulur muyum diyerek

Kırıldı merdivenler, mesafeler; derinde

Kapılarda yoruldum ağıtlar söyleyerek

Bulutun ağladığı geceyi bulamadım

Senin kaldığın yerde, nedense kalamadım

Açılsın derken bugün okyanusun perdesi

Sular durulmaz oldu aktığı yatağında

Can dostun çok yakından geliyorken hoş sesi

Şimdi sürgün menzilim, sesinin uzağında

Bulutun ağladığı geceyi bulamadım

Gel dese de yıldızlar, oraya gelemedim

Kartalın pençesinde serçenin emelleri

Yağmur yerine kara lekeler gökyüzünde

Celladımı sorarsan; daraltıyor çemberi

İp koptu kopacak bir insafsızın sözünde

Bulutun ağladığı geceyi bulamadım

Gelsin diye kimseye bir haber salamadım

Bebeği öksüz koyan kurşuna lânet olsun

Hangi hoyrat eldir ki, kısar bülbül sesini

Bu nasıl bir gidiştir yüreğe hasret koysun

Yarı yolda bıraksın yolcunun hevesini

Bulutun ağladığı geceyi bulamadım

Efkârın tozlarını aynadan silemedim

Hüzün, cenderesiyle yoklarken gündüzümü

Sorarlarsa bu nedir? Derim ki işim budur

İhanet örüyorsa ateşten bir düğümü

Çare yok, yol göründü; işte gidişim budur

Bulutun ağladığı geceyi bulamadım

Mehtabın uykusunu yüzünde bölemedim

Bulayım derken onu; işgal edilmiş evler

Süvarisi vurulan küheylân at gibiyim

Susuzluk âhâ döndü; suyun başında devler

Dağı kökten yıkılmış garip Ferhat gibiyim

Bulutun ağladığı geceyi bulamadım

Şirin’e yol verecek dağları delemedim

22/4/2002 Amsterdam-Zaandam', 'Havanın karardığı andır yürekteki söz Hangi resime baksam çeviriyor yüzünü Saçlarımı yakıyor mendilimde sönmüş köz Aynalar çoğaltınca unutul...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/aciya-asina-bir-yuzun-ifadesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötelerden Gelecek Misafir', 'otelerden-gelecek-misafir-huseyin-kerim-ece-jchtf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelmedin, kelepçeli kaldı odada ruhum, 

Buzlar bile eridi, ağrılara koyduğum, 

Penceredeki serçe suskunluktan savruldu, 

Olmayışın, turuncu yataklardan soruldu, 

Gelmedin; bahçedeki çiçekler susuz kaldı, 

Gelmedin; uzaklarda el sallayan azaldı, 

Gelmedin, yutamadım demli sıcak çayımı, 

Gelmedin, ıssız koydun gönlümde sarayımı, 

Sabah oldu, kuşluk aralandı; gelmedin, 

Göz bebeği bakmaktan yaralandı; gelmedin, 

Ey aylardır, yıllardır beklenen nazlı yolcu! 

Kapıda görünüver, alnı beyazlı yolcu! 

Çiçek Güneşten değil, beklemekten kavruldu, 

Gözlerimiz, yollara baka baka yoruldu, 

Müjdeni duyuyoruz, her tarafta işaret

Bu ne gelişti böyle; yıllar süren bir hasret! 

Sevdin mi oraları, tatlı mıdır intizâr? 

Güz gitti, kış da geçti, bak bitmektedir bahar, 

Yatağın hazır, yerin hazır, elbisen hazır, 

Elinden tutmuyor mu senin, boz atlı hızır? 

Sen ki hoş bir muştusun yılların ötesinden

Sen tatlı bir nağme, sevincin bestesinden

Artık hasrette koyma bizi, böyle biçare, 

Gelmedin, yalnız kaldı içimizde minare, 

Ellerimiz semada, dua dua üstüne

Gelmedin; sorayım mı, nedir bunca bahane? 

Bak, günlerin arkası kesiliyor camlarda

Takvim elde bitiyor, gözümüz rakamlarda, 

Ey adını demeyen, tatlı misafirimiz, 

Sen aziz, müjden aziz, gelişin bile aziz! 

Sana güllerden yatak yaptık, hiç duymadın mı? 

“Gelmeyen bir sevgili” yoksa senin adın mı? 

Ne olur, daha fazla bekletme bekleyeni, 

Biz hepimiz hazırız karşılamaya seni, 

Gel artık ufuklardan, dağların mor ardından, 

Gel artık, tatlı çocuk, bilinmezlik yurdundan, 

Seni özlemle öyle kucağıma sarayım

Seninle bayramların mevsimine varayım, 

Gel ki, taze çiçekler atayım kundağına! 

Gel ki, tatlı öpücük koyayım yanağına! 

Gözlerinle, akşama doyumca konuşayım! 

Senin sevginle engin tenhaları aşayım! 

Gel ki, viran olmasın vuslatın bahçeleri, 

Gel ki, hiç boş kalmasın gülücüklerin yeri, 

Yüzüm hasretle sırıl sıklam oldu, gelmedin, 

Mevsimler geçti, yine akşam oldu, gelmedin, 

Balkonlarda hepimiz çıkıp bekleyelim mi? 

Ne dersin, yola ipek halı döşeyelim mi? 

Ey sesi bülbül bebek, gül bebek, sünbül bebek, 

Ey eli gönül, yüzü melûl, sabrı tahammül bebek

Beklenmesi heyecan bebek, gözü mercan bebek, 

En içten canân bebek, candan içre can bebek, 

İşte yüreklerimiz döküldü denizlere

Söyler misin, ne zaman geleceksin bizlere? 

Bir yeşil dal üstünde bekliyor son kelebek, 

Gel artık ey ay yüzlü, nazlı, sevimli bebek, 

Bugün yarın gelmezsen, ey tatlı ve can bebek

Hasta olacak, hasta olacak yarım yürek.

15/5/2002 Zaandam', 'Gelmedin, kelepçeli kaldı odada ruhum,  Buzlar bile eridi, ağrılara koyduğum,  Penceredeki serçe suskunluktan savruldu,  Olmayışın, turuncu ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/otelerden-gelecek-misafir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülden Mi Bıktın Bülbülden Kahroldun', 'gulden-mi-biktin-bulbulden-kahroldun-huseyin-kerim-ece-z9hnl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani söz vermiştin ya, bir nevruz maviliğinde, 

Niçin kapı önünde yüzyıllarca beklettin? 

Önce gölgenle bayram tebriği gönderdin de

Sonra adını aldın, bu diyarı terkettin, 

Unuttun gözümdeki o derin intizarı, 

Beyazı siyah yaptın, sarayı zindan ettin, 

Dağların şarkısını kekliklerle söylerdim, 

Hüznü, bir de kederi bana hep sen öğrettin

Bulutları taşırdım da hiç ah vah etmezdim, 

Sen beni bir damlacık bakış ile terlettin, 

Teslim olmazdım kara zincirine feleğin, 

Kalbinle esir aldın, gülüşünle altettin, 

Bütün itirazları kilitledim kuyuya, 

Sen benim kabulümdün, benim için evettin, 

Niçin bakmıyorsun ey elinde nergis olan? 

Gülden mi bıktın, yoksa bülbüle mi kahrettin? 

Bahçıvan gitmiş, bahçe kimsesiz kalmış bugün, 

Aşkı filizleyen bu yeri kime devrettin? 

Ben seninle sınanır, seninle bilinirdim, 

Sen bana bir imtihan, bir çile, bir âfettin, 

Sözcük okuyamazdım sevda kitabında bil, 

Sen varlığınla bana o iklimi bellettin, 

Tutuldum şûlene de hislerim zincirlendi, 

Sen kendine hürriyet, bana da esarettin, 

Kusurum çoktur, dilim deli deli konuşur, 

Umarım bu şaşkını sen peşinen affettin.

4/3/2002 Zaandam', 'Hani söz vermiştin ya, bir nevruz maviliğinde,  Niçin kapı önünde yüzyıllarca beklettin?  Önce gölgenle bayram tebriği gönderdin de Sonra ad...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gulden-mi-biktin-bulbulden-kahroldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayacağını Umarım', 'anlayacagini-umarim-huseyin-kerim-ece-568xi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bildin mi ey dost yürek şehrinde ne oluyor? 

Uykuyu denizlere bırakanla anlarsın

Sahraya yolcu ol, sor ne demektir yalnızlık, 

Bir köşede sessizce ağlayanla anlarsın

Bilme içimden hangi bulutun geçtiğini

Beni, sana dökülen çağlayanla anlarsın

Sen değerlisin, hoşsun ey dost gönlümde; bunu

Sana sakladığım sır armağanla anlarsın

Ağlamayı unutan toprağa bakma sakın

Beni gözü yaşlı bir âsumanla anlarsın

Sana varan yolları açmak için devlerle

Tam binbir gün savaşan kahramanla anlarsın

Şimdi garip duruşum anlaşılmaz ise de, 

Hele bir sabret, beni sen zamanla anlarsın

Hiç ızdırap çektin mi, hiç bekledin mi yolu? 

Baksan, belki beni her perişanla anlarsın

Kimsesiz koyma desem, anlar mısın, Nevbahar? 

Beni bağrı yanık bir garibanla anlarsın

İçten sözlerimde gül kokusu duyar mısın? 

Bahçeye gel, sevdayı bahçıvanla anlarsın

Takvim tükenir, vâde tamam olur ufukta, 

Elbet o zaman beni kabristanla anlarsın

Bu sevgi ikliminde yediveren gül biter

Anlarsan; belki o an gülistanla anlarsın.

15/3/2002 Zaandam', 'Bildin mi ey dost yürek şehrinde ne oluyor?  Uykuyu denizlere bırakanla anlarsın Sahraya yolcu ol, sor ne demektir yalnızlık,  Bir köşede se...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anlayacagini-umarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla Gazeli', 'leyla-gazeli-huseyin-kerim-ece-503eu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çölde Kays’tan bir deli-dolu Mecnun çıkaran

Uğrunda can verilen bildik Leylâ değil mi? 

Akla, aşka teslim ol dedirten çağrılarla

Damıtılmış gibi, o yüz mücellâ değil mi? 

Gezdiği sahralarda gözlerinin rengini

Kuma sordum, dedi ki: koyu elâ değil mi? 

Şikâyetin mi var, ey bu çetin yola düşen? 

Bu uğurda başına gelen âlâ değil mi? 

Razıyım demiştin ya Leylâ’dan gelenlere, 

Bununla imtihan ol, bu bir belâ değil mi? 

Varsın ayağın taşa değsin, çöl susuz kalsın

Başım-gözüm üstüne, hep pekâlâ değil mi? 

Hayallerin büyürken kervan sessizliğinde

Ufukta yankılanan, uzak sıla değil mi? 

Açılır nice kapı, Yusuf kuyuda kalmaz,

Sebepleri yaratan Yüce Mevlâ değil mi? 

Hem telaşlar biter, tükenir endişeler,

Herkes için son durak, o musâllâ değil mi? 

25/3/2002 Amsterdam', 'Çölde Kays’tan bir deli-dolu Mecnun çıkaran Uğrunda can verilen bildik Leylâ değil mi?  Akla, aşka teslim ol dedirten çağrılarla Damıtılmış ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/leyla-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharın Bir Adı da Yar', 'baharin-bir-adi-da-yar-huseyin-kerim-ece-af9xt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollar sana gider sessiz

Çiçekler sende eğleşir

Sahili kucaklar deniz

Senin adınla söyleşir

Uzaktan bir mektup gelir

Mavi kuşun adresine

Cemre şiire yönelir

Irmak hiç dönmez tersine

Bir çiğdem renginde hayat

Ekler kalbe sonsuzluğu

Dağ delmeye gitsin Ferhat

Sevgi keser susuzluğu

Baharın bir adı da yâr

Yapraklarda şekillenmiş

Gönül sevdayla bahtiyâr

O, yıllarca beklenenmiş.

18/3/2002 Zaandam', 'Yollar sana gider sessiz Çiçekler sende eğleşir Sahili kucaklar deniz Senin adınla söyleşir Uzaktan bir mektup gelir Mavi kuşun adresine Cem...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baharin-bir-adi-da-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğazımı Yakan Hıçkırık', 'bogazimi-yakan-hickirik-huseyin-kerim-ece-i5iiu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Titreyişim sana doğru akıyor

Seni arıyorum kuş yuvasında

Önüme devlerin yüzü çıkıyor

Bir ışık gülse de gök ovasında

Onu da görünmez bir el yıkıyor

Ey dost, içli bir sitem duyarsan

Bu, aşkın sunduğu hazin komuttur

Bil ki feryadımdır adını koyan

İstersen resmini bana unuttur

Yine de yollara düşerim yayan

Acı bir hicrandır kalpte kırıklar

Kimse bu ağıtı anlamıyor yâr

Karşıma çıkıyor aykırılıklar

Kalbim bile beni dinlemiyor yâr

Boğazı yakarken bu hıçkırıklar.

27/3/2002 Zaandam', 'Titreyişim sana doğru akıyor Seni arıyorum kuş yuvasında Önüme devlerin yüzü çıkıyor Bir ışık gülse de gök ovasında Onu da görünmez bir el y...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bogazimi-yakan-hickirik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahın Gülen Yüzü', 'sabahin-gulen-yuzu-huseyin-kerim-ece-3zdiy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufkun sessizliğinde sabahın gülen yüzü

Senin ak ellerinde ulaşır bir aynaya

Sen gülerken açılır gökyüzünde hâleler, 

Kucaklar ışığıyla hem yokuşu, hem düzü

Bir sükût mevsiminde büyüyorken lâleler

Paylaşır yüreğimde ufka çıkan gündüzü

Senin fotoğrafındır kuşatan hayalleri

Rengârenk çiçeklerin toptan dökülsün suya

Bir ışıklı sofrada panayırlar kurulsun

Hangi göz kapağında erir kuşluğun feri? 

Tepede yine bizim uçurtmamız yorulsun

Hiç gitmesin önümden yüreğinin feneri

Açılsın perde perde denizlerin rüyası

Dilek taşına dönsün beni bekleyen kaya

El sallasın rüzgâr, mektup taşısın kuşlar, 

Dilerim yok olmasın gözlerinin vefası

Sana selâma durur içimdeki yokuşlar

Bekliyorken fecirde bu seyrin muhtevası

Bir kırlangıç anlatsın servilerin rengini

Bahar, yeşilliklerle tutuştursun bir maya

Her bir damlada yeni tomurcuklar dirilsin

Ak teraziler tartsın bu muştunun dengini

Bütün hesaplar mavi denizlere verilsin

Bulayım bakışında hayatın ahengini

Gözdeki en son damla seninle kıvam bulsun

Ceylanlar da seninle göz kırpsınlar sevdaya

Yolcular azığını hem seninle paylaşsın

Suyum senin gölgende bir gül gibi durulsun

İsterse vebâlin her bir zindana ulaşsın

Senin adına aşkın suçu benden sorulsun

8/5/2002 Zaandam', 'Ufkun sessizliğinde sabahın gülen yüzü Senin ak ellerinde ulaşır bir aynaya Sen gülerken açılır gökyüzünde hâleler,  Kucaklar ışığıyla hem y...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sabahin-gulen-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Saygı', 'olume-saygi-erdem-bayazit-dmtv2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölüm bir melek elinde gelir 

Ve öper usulca çocuk yüzleri. 

Belki bir gün kurtuluruz 

Karıncaların yolunu şaşırtan ince rüzgarlarla 

Kaplumbağaların hasret kaldığı derin tepelerde 

Çocuk gibi bakalım mavi sulara 

Şehirlere bakalım insanlığımızı eskittiğimiz 

Sislerden dumanlardan yollara atılan 

mısır koçanlarından 

Belki tutarız birgün belki kurtarır bizi 

Simsiyah saralım bezlerle dağları rüzgarları 

Gül bahçeleri ağlasın 

Dallarda salınan çocuk salıncakları ağlasın 

Kırmızı balonlar bizsiz kaybolsun gökyüzünde. 

Haydi sığının şehirlere 

Kabuğunuza çekilin yorganınızı çekin üstünüze 

Kalsın titrek ve mavi elleriniz 

Bekleyin geliyor ölüm usulca 

Usulca girer koynunuza.

Çamlıca 1959', 'Ölüm bir melek elinde gelir  Ve öper usulca çocuk yüzleri.  Belki bir gün kurtuluruz  Karıncaların yolunu şaşırtan ince rüzgarlarla  Kaplumb...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olume-saygi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Vakitleri Yaşamak İhtiyar Evlerde', 'olu-vakitleri-yasamak-i-htiyar-evlerde-erdem-bayazit-vwbn2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duvarları çatlak 

Tavanı dökülmeye hazır 

Temelinde bitlerin karıncaların ince bacaklı böceklerin 

gezindiği 

İhtiyar evlerde 

Zamanı çekip üstümüze 

Örtüyoruz kirli ve açık yerlerimizi. 

Bir şey mi var 

Sandık diplerinde saklanan merdiven altlarında 

unutulan 

Ahır köşelerine atılmış paslı çivilerine asılmış duvarların 

Nedir bizi bağlayan bütün bunlara ve geçen zamana. 

Siz oturdunuz mu hiç kıldan ince uçurumlarda 

Biz yatıyoruz her gün beli bükülmüş duvar diplerinde 

Uykumuz ürkek ceylanlara benziyor 

Bazan yorgun taylara. 

Biz sessiz ve kaygan zaman üstünde 

Unutmuş ve aldırmaz görünüyoruz 

Gıcırtılı merdivenlerden çıkan ölümü. 

Biliyoruz işliyor saat tıkır tıkır 

Her yerde ve her şeyde 

Sesini çizerek sonsuzluğa 

Tıkırtıların kımıltıların ve uzayan ağaçların. 

Ve aklın dar yalnızlığında

Maraş 1958', 'Duvarları çatlak  Tavanı dökülmeye hazır  Temelinde bitlerin karıncaların ince bacaklı böceklerin  gezindiği  İhtiyar evlerde  Zamanı çekip ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olu-vakitleri-yasamak-ihtiyar-evlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgelere Dair', 'golgelere-dair-erdem-bayazit-9b9e0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suların karardığı bir çağda birtakım günah yüklü

gemiler harekete hazırdı / iyice biliyorum

gölgeler vardı / kalın tasmaları vardı gölgelerin /

ürkek sesler suları yarıyordu / bakıyorsunuz

kuşlar bayağı gülüyordu / karanlık gölgeleri

ürkütüyordu / onlar bağlı olmayı hoş

görüyorlardı / korkarken ölümü düşünüyorlardı

muhakkak.

Kafaları kalındı belliydi

Gözleri kalındı belliydi

Kulakları kalındı belliydi

Aslında kafalarının kalın olması / gözlerinin kalın olması

önemliydi onlar için / incelik dedin mi kötülük

geliyordu akıllarına.

Onlar bir gemiye bindiler

- ben ona günah yüklü gemi dedim

Onlar oturup tasmalarından ötürü gönendiler

- ben onlara gölge dedim

Halbuki bana bakıp yadsıyorlardı / benim onları

tasmalarından ötürü küçük gördüğüm belliydi /

benim onları başında ve sonunda sevdiğim

belliydi / ama anlaşamadığımız muhakkaktı.

İşte ben bu noktada durdum

Denize baktım iyi dedim

Korkulu dağlara baktım iyi dedim

Doğrusu hep doğaya bakıp iyi diyordum.

Ama gölgeler giysilerle ilgileniyorlardı / utanıyordum

Hep araçlardan söz ediyorlardı / ben utanıyordum

Sonra bir çağ geldi / baktım kafamda karıncalar vardı /

sonra yapılardan yollardan bıkmıştım / ıssız

sokaklar beni ürkütüyordu / kötü meydanlarda

boğuluyordum / suları borulara almalarına

kızıyordum / hele hele hep düğmelere basıp

yaşamalarına çok çok içerlemiştim / sonra

kalkıp afrikaya gittim / ohh afrikaya.

Maraş 1958', 'Suların karardığı bir çağda birtakım günah yüklü gemiler harekete hazırdı / iyice biliyorum gölgeler vardı / kalın tasmaları vardı gölgeleri...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/golgelere-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Bir Başlangıç', 'guzel-bir-baslangic-murat-engin-ozdemir-t44jr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutların söndüğü bir gün

Tıpkı suyun yangını söndürdüğü gibi

Ben yangınların çocuğuyum

Bir damla su bile 

Bir anda söndürebilir ateşimi

Ama acı

Ama tatlı

Sonuçta güzel bir başlangıçtı', 'Umutların söndüğü bir gün Tıpkı suyun yangını söndürdüğü gibi Ben yangınların çocuğuyum Bir damla su bile  Bir anda söndürebilir ateşimi Ama...', ARRAY['Türk Edebiyatı','Şiir','Murat Engin Özdemir']::text[], 8.5, '{"poet":"Murat Engin Özdemir","poet_slug":"murat-engin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guzel-bir-baslangic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrin Ölümü', 'sehrin-olumu-erdem-bayazit-0d7e0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Giriş: 

Duvarlar çıkıyor önüme 

Şehrin mahpus yüklü duvarları 

Hiçbir sır kalmamış ardında hiçbir duvarın 

Nereye gitti diyorum benim elbisem nerede 

Şehir soyunmuş diyor biri 

Şehrin elbisesini çalmışlar 

Bütün şehir çöküyor yüzünde bir insanın 

Şehir boğuluyor içinde insanların kan gibi bir sesle 

Mor bir kabus çöküyor üstümüze 

Parkta son ağaç da ölüyor intiharı hatırlatan bir ölümle 

Veda çizgisi 

Kalabalık toplanıyor büyük meydanlara 

------------ Aşka veda 

İnsanlar geçiyor yollardan 

------------ İnanca veda 

Şehir kapanıyor içine 

------------ Toprağa veda 

Dolaşıyor bir heykelin taştan eli üstlerinde insanların 

Kuşlar göç ediyorlar bulutlar göç ediyorlar 

Yüzünde son gülümseme kaybolurken çocukların 

------------ İnsana veda 

Bir gezgin adam 

Bir adam belki de en çok bir rüzgardır şimdi 

Sisli yabancı gölge gibi gezgin bir rüzgar 

Şehri bir yabancı gibi dolaşıyor 

Şehrin mabetleri bir bir tükeniyor 

Başlıyor içinde sonsuz susuzluk 

Avuçların içi terliyor. 

Kaos 

Kirli yollar kapansın sular akmasın deniz 

sığmasın kabına 

Gün batmasın aydınlatsın yüzlerde 

umutsuz mahkumluğu 

Makineler çalışsın taşlar yarılsın ortalarından 

Anneler ağlamasın çocuklar gülmesin 

Gök çöksün toprak başkaldırsın su sussun 

Ağaçlar durmasın bütün saatler dursun 

Durmasın ulu rüzgar şehri göklere savursun. 

Durum 

Makinalar bir elin baş parmağını çarmıha geriyorlar 

Akıl bir akreptir intihara hazır. 

Anı 

Bizim ellerimiz vardı şimdi onlar nerede 

Kadife gibi okşardık çocuk yüzlerini şimdi onlar nerede 

Şehirde evler olurdu sıcak odaları olurdu evlerin 

Sığınacak yatakları olurdu bu bizim yatağımız derdik 

Bayram günleri donanırdık su gibi yumuşardı 

yüreklerimiz 

Camilere dolardık tüm olmaya ererdik 

Biz vardık şimdi o biz nerede. 

Bitiş 

O en öksüz köşesine sığındığımız yalnızlığın 

Yalnızlığın teselli çiçekleri üstümüze 

Göçen son kuşların sedef gagalarından dökülür 

Şehir bir mahşer gibi içimizde ölür.

 

 1968 

 İstanbul', 'Giriş:  Duvarlar çıkıyor önüme  Şehrin mahpus yüklü duvarları  Hiçbir sır kalmamış ardında hiçbir duvarın  Nereye gitti diyorum benim elbise...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sehrin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Duvarlar', 'karanlik-duvarlar-erdem-bayazit-5y9z7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I.

Önünü alamıyorum bu kör gidişlerin yollarda 

Herkes bir yere gidiyor önünü alamıyorum 

Çaresiz direniyorum bu dönüm noktalarında kimse 

elini uzatmıyor 

Bir gürültülü yaşamağa gidiyor dünya boşalan 

bir deniz gibi 

Bu sesler ormanında kaybolan bir çağ bu. 

Nereye gitsem hep apartmanlar çıkıyor önüme 

Alıp başımı duvarlara çarpıyor bu yollar 

Gidip gelmelerim bu dar sokaklarda 

İnsanların koşup dolduğu bu dar yapılarda 

Bir kısır döngüye girmek için bütün çabalar 

Biz bunun için mi geldik. 

II. 

Kara ağaç gibi bağlıyım katı bir çağ bu 

Her şey bir makine düzenine gidiyor 

- düzen diyorlar beni çağırıyorlar - 

Irmak yatağına sığınıyorum sınırlı bir çağ bu 

Baktığımız her şeyde bir yalan kabuğu 

Bir mercek düzenine bağlanıyor gözlerimiz. 

III. 

Şu zaman çıkmazında alıp beni bir altmış yaşa 

bağlıyorsunuz 

Doğmadan ölüme yöneldik gerisi yok diyenler var 

Sınırlı yıl oyunlarına inananlar var 

Sizin güveniniz bir güneş düzeninde 

Ben mezarların karanlık çağına dayanıyorum 

Bir ağacı büyütüyorum her yerimle 

Bir ağacı uyguluyorum - her şey bir ağaç düzeninde - 

Yerde gökte ve her her yerde 

Dallarında ben ağacın incecik köklerinde 

Boğuluyorum - bağlanıyorum - 

Ben mezarların karanlık çağına dayanıyorum. 

IV. 

Şu dar odanın katı yalnızlığında 

Ve her şeyin çıplaklığında 

Durup bir pencereyi deniyorum 

Gizliliğin dışına çıkıyorum 

Araçların 

İnsanların 

Şehrin ve meydanların ve kalabalığın ve herşeyin 

İçimde yalnız ve yapraksız 

Bir kavak ağacı büyüyor - Çıplak ve göğe doğru - 

Ama küskün ama yalnız ama yapraksız ve uzun 

Bir ağlama duvarı bu. 

Yatak ve yorganın kuru yalnızlığında 

Ve aklın dar yalnızlığında 

Şehrin ve herşeyin 

Ve kalabalığın yorgunluğunda 

Saçların ve parmakların 

Ve gözlerin ve gecenin bu bulanık çağında 

Ve aynaların sığ görünümünde 

Bunalıyorum. 

V. 

Susmanın kalesine sığınıyorum 

Önümde karanlıktan duvarlar 

Sırtımda insan yüklü bir gök var.

Maraş 1959', 'I. Önünü alamıyorum bu kör gidişlerin yollarda  Herkes bir yere gidiyor önünü alamıyorum  Çaresiz direniyorum bu dönüm noktalarında kimse  e...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/karanlik-duvarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-mehmet-atilla-maras-29t10', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yol gidiyorum otobüsteyim

kulağımda titreşen uğultulu sesteyim

kırlar dönüyor, köyler dönüyor, çınarlar

sema yapıyor başım

sema yapıyor kırlar.

Muhalif bir düşünçe peyda olmuştur

çünkü bahardır, 

kanın kınından boşaldığı zamandır

anılar mevsimidir ömrüm vay.', 'Bir yol gidiyorum otobüsteyim kulağımda titreşen uğultulu sesteyim kırlar dönüyor, köyler dönüyor, çınarlar sema yapıyor başım sema yapıyor ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Atilla Maraş']::text[], 8.5, '{"poet":"Mehmet Atilla Maraş","poet_slug":"mehmet-atilla-maras","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bahar-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil', 'dil-mehmet-atilla-maras-wctx8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonsuz geniş bir alanın

bir yanı kızgın güneş

sancak sancak gölge bir yanı

ve aklımızda çok önemli bir anı

yıldızları seyrederek uyuduğumuz

o parlak yaz geceleri..

Şimdi bu yıldızsız gök nasıl mavi

ne demek postacı, mektup, kuş, muş

bildiğimiz dünya kaybolmuş

ah şimdi biz

hangi dili konuşuyoruz

güzelim hangi dili...', 'Sonsuz geniş bir alanın bir yanı kızgın güneş sancak sancak gölge bir yanı ve aklımızda çok önemli bir anı yıldızları seyrederek uyuduğumuz ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Atilla Maraş']::text[], 8.5, '{"poet":"Mehmet Atilla Maraş","poet_slug":"mehmet-atilla-maras","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-osman-oztunc-jk9cj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'nereden başlasam, nasıl söylesem

aşk yaşanır anlatılmaz ki

ne saçı, ne gözü, ne de gölgesi

aşk insanoğlunun kendisi gülüm

olunmaz dertlere gülüp geçerken

bir tatlı sevince günlerce yanıp

işinde, okulda veya kahvede

aklımın bir yerinde hep o var demek

bazen yıldızlara, bazen güneşe

bazen karanlığa kafa tutmaktır.

ranzama uzanıp ızdırap içinde

uyuyup uykusuz uyanmaktır.

bir kere gönlüme düşerse bu ah

alışır, tutuşur, yanarsın eyvah

bazen sevap, bazen gizli bir günah

aşk insanoğlunun kendisi gülüm.

onu her gördüğünde renginin

kızarıp dilinin tutulduğu an

dizlerinin bağı çözülür ya birden

kalbinin hızlı hızlı vurmasıdır.', 'nereden başlasam, nasıl söylesem aşk yaşanır anlatılmaz ki ne saçı, ne gözü, ne de gölgesi aşk insanoğlunun kendisi gülüm olunmaz dertlere g...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hava Soğuk', 'hava-soguk-nazim-hikmet-ran-bnahj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hava puslu, soğuk

Kırlar koyu, kırmı
..........
..........', 'Hava puslu, soğuk Kırlar koyu, kırmı .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hava-soguk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darmadağın', 'darmadagin-osman-oztunc-15uy5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sevdaya duran rıhtımın

meçhule vuran ahdımın

gamla yoğrulan bahtımın

güzergahı darmadağın

kader ızdırap ağını ömrüme örer gibi

mutluluk senin neyine gerek der gibi

bu ızdırap tiyatrosu

sanmayın kaldı kadrosu

sevdamın gönül ordusu

karargahı darmadağın', 'sevdaya duran rıhtımın meçhule vuran ahdımın gamla yoğrulan bahtımın güzergahı darmadağın kader ızdırap ağını ömrüme örer gibi mutluluk seni...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/darmadagin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issız Bir Görüşme', 'issiz-bir-gorusme-mansur-balci-mdpua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben bir  gece kaçağıyım gündüzün gözünde uyuyan

geceden sakladığım bir damla düşle gülümsüyorum

benden isteme kırılgan aynalarımı, yanarsın

çünkü ben

bir asya masalı yanılgısıyım

çarpıldığı gecelerin umuduyla ıslanmış

uykularımda dolaşma, yanarsın

çünkü ben 

o basit iğde kokusunu kaybettim düşümde

senin yüreğinden ürkütüldüğünde güvercinlerim

mevsimerimden sürüldüm şakacı aşklar

sen soyun şimdi kendine

soyun ve zamanı acımadan örsele

geceni gül suyundan bir kapıyla arala

uçurt adamı uykularından 

gecene ölü balıklar üşüşür/ay günü batar', 'ben bir  gece kaçağıyım gündüzün gözünde uyuyan geceden sakladığım bir damla düşle gülümsüyorum benden isteme kırılgan aynalarımı, yanarsın ...', ARRAY['Türk Edebiyatı','Şiir','Mansur Balcı']::text[], 8.5, '{"poet":"Mansur Balcı","poet_slug":"mansur-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/issiz-bir-gorusme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızım', 'kizim-suleyman-apaydin-qlayy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüner yüksek uçmak değil

Gösterişe verme meğil

Asil olan seven gönül

Yok sevgiden yüce kızım

Hep sevgiden çalar sazım

Salt dostuma geçer sözüm

Eğer geçer ise nazım

Gönül kırma kazan kızım

Bir gün dara düşer isen

Rüzgar olup eser isen

Karıncayı susuz görsen

Sulamadan geçme kızım

Malın olsa Karun kadar

Namın olsa dünya tutar

Sefil görsen yerde yatar

Tut elinden kaldır kızım

Kaç yaşında olursan ol

Gençliği sen gönlünde bul

Yaşlanmaz ki seven gönül

Kıymetini bilsen kızım

Benim tatlı nazlı kızım

Hem baharım hem de yazım

Yaradandan tek niyazım

 Mutlu görmek seni kızım

Elbet bir gün susar sazım

Duyulmaz olur avazım

Benim sana tek mirasım

Sevmek olsun sevmek kızım', 'Hüner yüksek uçmak değil Gösterişe verme meğil Asil olan seven gönül Yok sevgiden yüce kızım Hep sevgiden çalar sazım Salt dostuma geçer söz...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kizim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum-2', 'oglum-2-suleyman-apaydin-j7jue', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alem hırsız arsız olsa

Yalan dolan arşı tutsa

Çevrende kimse kalmasa

Sen yolundan dönme oğlum

Bela senden güçlü olsa

Dönüp arkana dolansa

İki elin kanda olsa

Hakkı yerde koma oğlum

Gammaz ile madrabazdan

Yalancıyla kumarbazdan

Saygısızla düzenbazdan

Yollarını ayır oğlum

Çaresizle güçsüzleri

Yetim kalan öksüzleri

Aşka düşen gönülleri

Hor görme de kayır oğlum

Sevgisizle saygısızdan

Vefasızla vicdansızdan

Yolda koyup giden dosttan

Gelmez sana hayır oğlum

Yaşadığın yıl boyunca

Mağrur olma tüm ömrünce

Ağırlığın olsun önce

Havalanıp uçma oğlum

Düşer isen bir gün dara

Sarsa seni elem tasa

Baldırandan acı olsa

Gerçeklerden kaçma oğlum

Ne şan şöhret ne mal ne mülk

Ne dünya''da sefa sürmek

Benim için en büyük zevk

Mutlu görmek seni oğlum

Saçlar bir gün ağaracak

Yolcu menzile varacak

Benden sana tek kalacak

Sevmek olsun sevmek oğlum', 'Alem hırsız arsız olsa Yalan dolan arşı tutsa Çevrende kimse kalmasa Sen yolundan dönme oğlum Bela senden güçlü olsa Dönüp arkana dolansa İk...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/oglum-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayan Benim Aslan Babam', 'dayan-benim-aslan-babam-suleyman-apaydin-09zxg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne çalışır ne okurum

Her şeyi hazır bulurum

Yoktur benim bir sorunum

Yeter bana benim havam

Dayan benim aslan babam

Kız daracık tayık ister

Oğlan yeni nayık ister

Hanımın parfümü canel

Sana uyku durak haram

Dayan benim aslan babam

Üç vardiye primlidir

Gurup akort verimlidir

Mesaiye adın bildir

Kabarık dursun cüzdan

Dayan benim aslan babam

Arabamız katımız yok

İnci elmas takımız yok

Marmaris''te yatımız yok

Biraz daha para kazan

Dayan benim aslan babam

Kuaföre diskoteğe

Düğünlere davetlere

Gerdanlığa küpelere

Yetmiyor ki senin paran

Dayan benim aslan babam', 'Ne çalışır ne okurum Her şeyi hazır bulurum Yoktur benim bir sorunum Yeter bana benim havam Dayan benim aslan babam Kız daracık tayık ister ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dayan-benim-aslan-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alara', 'alara-suleyman-apaydin-k9cwj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprağa cemre düştü

Bahar uyandi erken

Erikler çiçek açtı

Sen dünya''ya gelirken

Nisan mayıs haziran

Temmuz agustos derken

Bulutlar gölge oldu 

Sen güneşte gezerken

Ne çabuk geçti aylar

Eylül ekim kasımlar

Karakış yaza döndü

Gözlerin gülümserken

Aralık ocak şubat

Sıfır on diyor saat

Baktım ki onsekiz mart

Sen yaşına girerken

Bu gün senin yaşgünün

Selam eş dost herkese

Karanfile zambağa

Kızıl güle nergise', 'Toprağa cemre düştü Bahar uyandi erken Erikler çiçek açtı Sen dünya''ya gelirken Nisan mayıs haziran Temmuz agustos derken Bulutlar gölge old...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/alara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru Kipi Şiirleri', 'soru-kipi-siirleri-asli-durak-ou632', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-1-

yaza hazırlamak için 

kışın gömerler kayıkları denize 

bu gün yatırıldığım hüzün 

deniz midir gözleri umut çiziği güne? 

-2-

ayak değmemiş yağmur ormanlarına 

düş eğimi uzaklıkta bozkırda 

açarken tomurcuk

söylesene çocuk nerelidir yüreğin? 

-3-

hangi renktir yalnızlık? 

sevdalar ne renk? 

ille de kırmızı mıdır aşk? 

belki de mavi 

kanadında uçurduğu için uçuk mavi 

ya renksiz bırakılmış 

boya kitabıysa yaşam? 

-4-

coşup taştıkça içim dışıma 

nereden çıkıyor 

bu iki ayaklı 

kurutma kağıtları? 

-5-

kunt bir çember mi aklın simgesi? 

dik açılı kutularda mı kilitli duygular? 

yorgun sesler salınırken köşelerinde 

nerelerde gizlenir üçgenler?', '-1- yaza hazırlamak için  kışın gömerler kayıkları denize  bu gün yatırıldığım hüzün  deniz midir gözleri umut çiziği güne?  -2- ayak değmem...', ARRAY['Türk Edebiyatı','Şiir','Aslı Durak']::text[], 8.5, '{"poet":"Aslı Durak","poet_slug":"asli-durak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/soru-kipi-siirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem', 'bilmem-coskun-oren-6xyy0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bugün yağmur var istanbul da 

havada kara bulutlar

artık sadece yanaklarım değil

istanbulun sokaklarıda ıslak', 'bugün yağmur var istanbul da  havada kara bulutlar artık sadece yanaklarım değil istanbulun sokaklarıda ıslak...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Ören']::text[], 8.5, '{"poet":"Coşkun Ören","poet_slug":"coskun-oren","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bilmem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-mahpiya-wichasta-yvqgf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sende gördüm, 

     Bir insanın kelimelerle anlatılamayan çekiciliği olabileceğini

          Ve kendini kaptırmanın imkansızlığını.

Seninle yaşadım, 

     Mavinin dinginliğini, kırmızının ateşini, yeşilin huzur vericiliğini

          Ve seninle renklendi dünyam, renkler seninle anlam buldu.

Seninle tattım, 

     Aldatmanın huzursuzluk veren heyecanını

          Ve zevk aldım kaçamak sevişmelerden.

Sende gördüm, 

     Cinselliğin bu kadar yoğun olabileceğini

          Ve doyasıya yaşattın bana anlatılamaz doyumsuzluğu.

Seninle sürdü, 

     Yaşamın tüm güzellikleri, beraberliğin vazgeçilemezliği.

          Ve bir gün ne yazık, her şey bitti.

Senden öğrendim, 

     Aldatırken aldatılmayı, kandırılmayı

          Ve gözyaşlarıyla yalanların birlikte bu kadar uyumlu olabileceğini.

Sen gösterdin, 

     İnsanın kalbinin de ağrıyabileceğini, 

          Ve sevginin nefrete, saygının tiksintiye dönebileceğini.

Sen öğrettin, 

     Kimseye güvenmemeyi, arkanı dönmemeyi

          Ve her an bir ihanete uğrayabileceğini.

Sen bitirdin, 

     Sana olan sevgimi, saygımı, güvenimi...

          Ve tüm hislerimi sen bitirdin güzelim, sen bitirdin...', 'Sende gördüm,       Bir insanın kelimelerle anlatılamayan çekiciliği olabileceğini           Ve kendini kaptırmanın imkansızlığını. Seninle ...', ARRAY['Türk Edebiyatı','Şiir','Mahpiya Wichasta']::text[], 8.5, '{"poet":"Mahpiya Wichasta","poet_slug":"mahpiya-wichasta","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sana-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlar Prensi', 'karlar-prensi-aykut-bababalim-qqqnc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'buralara ilk kar düştü 

seni hatırladım 

soğukluğun muydu bana hatırlatan, 

bir kış günü reddedilişim mi? 

ama sevmedim 

çabuk erir kar tanesi 

bir fakirin sevdası 

alnının tek karası 

karların kiri pası 

işte ben 

karlar prensi 

mutsuzluğun efendisi 

aşkın gerçek sahibi 

neyim var bundan başka? 

yalan yok 

mahkumum aşka', 'buralara ilk kar düştü  seni hatırladım  soğukluğun muydu bana hatırlatan,  bir kış günü reddedilişim mi?  ama sevmedim  çabuk erir kar tane...', ARRAY['Türk Edebiyatı','Şiir','Aykut bababalim']::text[], 8.5, '{"poet":"Aykut bababalim","poet_slug":"aykut-bababalim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karlar-prensi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Ertesi Bir Aşkla', 'mevsim-ertesi-bir-askla-i-smail-ozabaci-xptvt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mevsim ertesi bir gecedeyim

Zifri bir karanlığın ortasında ellerim

Sol yanımda bir sızı

Ve bilinmez bir neden daldı gözlerim...

Son kullanma tarihi geçmiş

Hüzünlerimi çıkardım gün yüzüne

Ağarmakta olan geceye sürdüm bi nebze

Sonra sabah olmasını bekledim

Biraz ilkbahar, biraz toprak karıştırıp

Yüreğimin tuvalinde

Gözlerinin rengini elde etmeye çalışıyorum şimdi

Rüyalarımda,ellerini,yüreğini arıyorum

           Hayallerde

               Ay yüzünü

                   Ne kadar özlediğimi düşünüyorum...

Mevsim ertesi bir gecedeyim şimdi

Kendimi yoruyorum

Çiçek isimleri ezberliyorum

Seni daha kolay  tarif etmek için

Aklıma düşmen hoşuma gidiyor

Ki hiç çıkmaman

Düşündürüyor beni..

Şimdi soğuk bir yaz mevsimi bu şehirde

Ben seni mevsim ertesi bir aşkla bekliyorum', 'Mevsim ertesi bir gecedeyim Zifri bir karanlığın ortasında ellerim Sol yanımda bir sızı Ve bilinmez bir neden daldı gözlerim... Son kullanma...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mevsim-ertesi-bir-askla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşkın Anafikri', 'bir-askin-anafikri-gursel-karaca-uqx3i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen sınıfa girince

sınıfın rengi değişiyor

gözlerinin renginde bir yeşil! 

heryer ve herşey

sanki sen oluyor

sen sokağa çıkınca

sokağın rengi değişiyor

leş gibi bir istanbul

binbir renkli çiçek oluyor! 

sen konuşmaya başlayınca

kelimelerim anlamını yitiriyor

başım dönüyor

                  yüreğim çarpıyor

senin gözlerin 

bir aşkın çığlığı oluyor! 

sen bir hikayeye konu olunca

aşkın rengi değişiyor

ve senin anafikrin 

gözlerinin renginde bir dünya oluyor!', 'sen sınıfa girince sınıfın rengi değişiyor gözlerinin renginde bir yeşil!  heryer ve herşey sanki sen oluyor sen sokağa çıkınca sokağın reng...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Karaca']::text[], 8.5, '{"poet":"Gürsel Karaca","poet_slug":"gursel-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-askin-anafikri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Talan Yalandı O Zamanlar', 'talan-yalandi-o-zamanlar-selami-atan-gkhh5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kısa  pantolonlu  eşkiya  sevdalardan

Uzun  namlulu  gölgeler  çalınırdı

                                 uykusuz  gecelerime...

Uyanırdım

-aslında  uyanıktım-

Düş  sanırdım

kardelenleri  ağustos  sıcağında

gülleri 

bir  de  parktaki  çoçukları

sonra  soframdaki   katığı...

Ay  vururdu  pencereden

Ben  efkarlanırdım...

Bir  sigara  dumanı   özgürlüğüne

ve  Dicle  yanlızlığına  gömülürdü

                    talihsiz  kavuşmalarım..

ve  tarihsiz  gelgitlerim..

Devriye  dolaşırdı  hasret...

Yürek  pusudaydı...

Oysa  devşirilmişti  bütün  aşklar

Bütün  yalınlar yalnızlıklara  çıkardı  yanlışlıkla

Ben  ölüme  inat  sevdalanırdm...

Sonra  ayrılırdım  yaşama  inat...

Susardım...

Ağlardım...

 

Aşk  yalandı  o  zamanlar...

Zaman  talandı  o  zamanlar...

 

Güneş  tebessümleri seçilirdi

                        ayın  solgun  yüzünde...

Sesi  bıçaklarla  kesilmiş

                        nara  kırıntıları  kalırdı

                                    dudaklarımın  arasında...

Sessizliğimin  sesi  dökülürdü

                          bembeyaz   sayfalara...

Kararırdı  sayfalar...

Cümleler  tutuşurdu...

Kalem    cesaretinde    kelimeler

                  afaroz  edilirdi  dilimden...

Ben  ``konuş``  derdim...

Yankısı  ``sus``  olurdu...

Susardım...

Ağlardım...

 

Umut  yalandı  o  zamanlar...

Zaman  talandı  o  zamanlar...

 

Başka  diyarlardan

başka  denizlerden

başka  dünyalardan  kopardı

sürgün  yüreklerin  sessiz   fırtnası...

Kırış  kırış  olmuş  ellerin  karasında  gizliydi

                       yokluğun  kanlı  kınası...

Dedelerimden  miras  kalmıştı

                sırtımdaki    kirli  hançer...

 

Kurt  bakışlı,  yarasa  gecelerinde 

ışıl  ışıl parlardı  hançer...

Ben  yakamoz  düşlerdim...

Ve  kendi  ışığımda

                kendim  kararırdım...

Kendi  denizimde

                 kendimi  boğulurdum...

Su  isterdim  dost  elinden

Susardım...

Ağlardım...

 

Dostluk  yalandı o     zamanlar...

Zaman  talandı  o  zamanlar...

 

Bir  kırlangıç   kanatlanırdı

                  gözlerimin  kıyısından...

Bir  yarasa  tam  başucumdan...

Dalgalar  sahile

gözyaşları  gözbebeklerime  vurup  geçerdi...

Yüreğim  parelenirdi...

Alev  alev  yanardı...

Ateşinden  Kaf  Dağı

Küllerinden  Anka  Kuşu  olurdu...

Yanardım...

Bir  el  aradım  boşlukta

bir  yürek

bir  gülücük...

Kucak  açardım uzak  deryalar  gibi...

Kollarım  serap  olurdu...

Susardım...

Ağlardım...

 

Sevgi  yalandı   o   zamanlar...

Zaman  talandı   o   zamanlar...

                            MAYIS  2002', 'Kısa  pantolonlu  eşkiya  sevdalardan Uzun  namlulu  gölgeler  çalınırdı                                  uykusuz  gecelerime... Uyanırdım -...', ARRAY['Türk Edebiyatı','Şiir','Selami Atan']::text[], 8.5, '{"poet":"Selami Atan","poet_slug":"selami-atan","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/talan-yalandi-o-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayışsız Hayat', 'anlayissiz-hayat-huseyin-cayikli-vqlet', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'doksan 99 yaziydi

kurak bir iklim...

insanlar uzerinde sicaklik vardi...

ve sabah ki gazetelere yetisecek 

az sonra adli flas haber gececek mansetler vardi.

Az sonra kadar olume az kaldi

olumun tedavulden kalmis kokusunu insanlar duyuyordu birde azrail...

icine isledi doksan dokuz yilini

ne dostlar ne asklar yitirildi...

cimenler uzerinde ki goz yaslari silinmedi.

ve sabah ki gazeteler mansetlerinde bir sehirden bir sehre nasil gidileceginin haritasini yayinliyorlardi...

olum denize ramak kalmisti...

yaklastikca dev dalgalarin sansursuz sevismeleri goruluyordu...

ne kadar icersek acisi o kadar gecer gunler kapima dayandi

ne kadar ictikce bir  o kadar aci cektim...

ne bilinmedik asklar yitirdim enkazlarda 

koca koca cinarlar devrildi onumde

yinede boyun egmedim

sarildim yaprak gibi agaca

bir baktim ki sarmisik olmusum...suruklenmisim

sabah ki gazateler bir olumun nasil oldugunu manset yaptilar

ve televiyonda flas haberler geciyordu

marmaranin buyuk korfezi yikildi

yer kukremisti tanridan baska kurtaracak yoktu...

dayanak siginacak kimse yoktu...

mahser alaninda ki insanlik ikinci olumu tadiyordu

ve sabah gazetelerinde ki son manset soyle gecmisti

binlerce insan oldu 

bir insan bir sehre dogru goc etti bir daha da donmedi...', 'doksan 99 yaziydi kurak bir iklim... insanlar uzerinde sicaklik vardi... ve sabah ki gazetelere yetisecek  az sonra adli flas haber gececek ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/anlayissiz-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlarımız', 'yarinlarimiz-mehmet-ali-cibikli-jxcv7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman gözüne, uyku girmezse, 

Başını yastıktan, şöyle bir kaldır.

Beni düşün bir an, zahmet olmazsa, 

Duyduğun her kuşku, birer masaldır.

Düşünme yarını, yarınlar bizim, 

Hiç şüphen olmasın, kuşku duyma hiç.

Önü hep aydınlık, bu sevgimizin, 

Ömrümüzce bizim olacak sevinç.

At gönlünden şimdi, karamsarlığı, 

Sevgiler yerleşsin, artık gönlüne.

Yaşamayalım biz, bu yalnızlığı, 

Mutluluk çıkacak, her an önüne.

Sen ve ben! İkimiz, yarınlarımız, 

Biz bize, el ele, mutlu olacak.

Gittikçe artacak, duygularımız, 

Gönlümüz sevgiyle, aşkla dolacak.', 'Ne zaman gözüne, uyku girmezse,  Başını yastıktan, şöyle bir kaldır. Beni düşün bir an, zahmet olmazsa,  Duyduğun her kuşku, birer masaldır....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yarinlarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun Sonu', 'yolun-sonu-kadircan-keskinbora-z9437', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş battı, sönüyor feri son ışıkların

İndi koyu perdesi şimdi karanlıkların.

Yok artık ne beklentim, ne umutlu bir yarın, 

Ne özleyip, sesimi duymayı bekleyenim, 

Ne başımın düştüğü sevgili omuzların.', 'Güneş battı, sönüyor feri son ışıkların İndi koyu perdesi şimdi karanlıkların. Yok artık ne beklentim, ne umutlu bir yarın,  Ne özleyip, ses...', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yolun-sonu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-kadircan-keskinbora-aj78c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceler soğuk

Geceler yalnız

Geceler elemli

Geceler hatırlatır seni özlediğimi.', 'Geceler soğuk Geceler yalnız Geceler elemli Geceler hatırlatır seni özlediğimi....', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/geceler-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Katığı', 'can-katigi-kadircan-keskinbora-1get5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevinçli bir zamandı

Benim için dün akşam, 

Bir tutam mektup almış, 

Bütün gece okumuştum.

Gelen bunca mektuptan, 

Desem ki: 

''Seninkiydi coşturan''

''Seninkiydi can katan'' desem

İnan.

İnan: 

Ne temiz hava solumak

Ne cenneti seyretmek; 

Hatırlanmaktır, 

İnsana yaşadığını hatırlatan.', 'Sevinçli bir zamandı Benim için dün akşam,  Bir tutam mektup almış,  Bütün gece okumuştum. Gelen bunca mektuptan,  Desem ki:  ''Seninkiydi co...', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/can-katigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teklif', 'teklif-kadircan-keskinbora-nisi5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? 

Özledim seni

Ellerini, 

Sohbetini, gözlerini, 

Ve o filozofça laflarını.

Bir şeyler yapsak mı senle

Yazılmayacak gibi.

(Eylül 88)', 'Biliyor musun?  Özledim seni Ellerini,  Sohbetini, gözlerini,  Ve o filozofça laflarını. Bir şeyler yapsak mı senle Yazılmayacak gibi. (Eylü...', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/teklif-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-seyh-galib-zg67a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokmuş bir aha ey gül- i rana tahammülün

Bağrın ne yaktın ateş- hasretle bülbülün

Yek-rengdir zeban-ı hakikatte hüsn ü aşk

Bang-i hezar şu''lesidir ateş-i gülün

Duzah-nişin-i ateş-i fakr olduğun kalur

Ey ahiret-harab tehidir tevekülün

Tekrarlarla şüpheleri daniş anlama

Gel arif ol ki ma''rifet olsun tecahülün

Merdanelik asaleti meydanda bellidir

Hayber günü babasını kim sordu Düldül''ün

Galib maarifin de sefası değer veli

Canan vasfıdır hele aslı tegazzülün', 'Yokmuş bir aha ey gül- i rana tahammülün Bağrın ne yaktın ateş- hasretle bülbülün Yek-rengdir zeban-ı hakikatte hüsn ü aşk Bang-i hezar şu''l...', ARRAY['Türk Edebiyatı','Şiir','Şeyh Galib']::text[], 8.5, '{"poet":"Şeyh Galib","poet_slug":"seyh-galib","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gazel-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatın Aşkı', 'anlatin-aski-tolga-acar-teqi3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzel bir yaz akşamı, 

Bahçemde açmış güller, 

Haydi anlatın aşkı, 

Naz etmeyin bülbüller.

Yarim bugün doğmuştu, 

Hatırlar mısın rüzgar? 

İçim bir hoş olmuştu, 

Haber vermişti kuşlar.

Artık dünya ne güzel! 

Mutluluklar çok yakın.

O’dur bana tek güzel, 

Allah’ım bozma sakın.', 'Güzel bir yaz akşamı,  Bahçemde açmış güller,  Haydi anlatın aşkı,  Naz etmeyin bülbüller. Yarim bugün doğmuştu,  Hatırlar mısın rüzgar?  İç...', ARRAY['Türk Edebiyatı','Şiir','Tolga Acar']::text[], 8.5, '{"poet":"Tolga Acar","poet_slug":"tolga-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlatin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencerede Aydınlık', 'pencerede-aydinlik-huseyin-kerim-ece-8ahk4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabahı beklemenin zorlu bedeli mi var? 

Her saat yıla benzer, her dakika bir mevsim, 

Niçin sarmıyor beni, yaban mıdır uykular? 

Bu yorgunluğu şimdi nasıl izah edeyim? 

         Yalnızlığın çehresi o ay yüzlü ıssızlık

         Ufuklarda oynayan mavera renkli ışık

Bir adım atayım (mı)     öteler ötesine? 

Yoksul konuklar müjde taşısınlar odama

Renkler selâm göndersin, kuşlar uçuşsun yine

Hüznümün resimleri dizilsin sessiz cama

         Ve duvarda gülpembe uzun saçlı sarmaşık

         Gecenin fotoğrafı yorgun, bitkin, kırışık

Sabah uzun bir emel gece içinden geçen

Fecir gözlerde muştu, yeşillikler ötesi

Zaman kımıldayan su, yüreklerde göllenen

Bitiş noktası nedir, hangi gün ve neresi? 

         Yolculuk kısa değil ve nice bin hazırlık

         Nerede doğar hicran, nerede biter azık? 

Vakit dursun, gitmesin ay dağların ardına

Nasıl olsa geceler doğumlara gebedir

Kar yağsın, beyaz umut dolsun yürek yurduna

Beklediğin konuklar eminim gelecektir

         Bir beklenti, bir umut rüzgârla ılık ılık

         Ve işte penceremde özlenen o aydınlık...

                                 5/Nisan/1998 – Zaandam', 'Sabahı beklemenin zorlu bedeli mi var?  Her saat yıla benzer, her dakika bir mevsim,  Niçin sarmıyor beni, yaban mıdır uykular?  Bu yorgunlu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/pencerede-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Mevsimler', 'beyaz-mevsimler-huseyin-kerim-ece-adeo5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1-Büşra

Gül senin bağrında bir bahar olur

Muştu sende büyür, gün seninledir

Mektuplar seninle okunur hergün

Seninle geceler dönüşür nura

Adın bir bitimsiz azık sandığı

Yüzün aynaların en koyu rengi

Bir kelimen binbir selâmdır vakte

Bir sözün diriltir binlerce gülü

Bakışın bitmeyen umuttur bana

Ve her gün yeniden yeşeren sabah

Defterimde senin adın yazılı, 

Odamda yalnızca senin nefesin

Ak renkli bir bahar gördüm izinde

Korkular peşpeşe çekildi gitti

                &&&

2-Davet

Açıldı kapılar bayram yerine

Söyleyin gül gelsin, karanfil gelsin

Yine dost selâmı yüklensin sular

Ufukta sallanan bin mendil gelsin

Hüzün sussun, sözler ağıt olmasın

Muştular seninle hep sebil gelsin

Seninle uyansın bahçem yeniden

Tadlarla beraber zencefil gelsin

Varsın yağmur yağsın, sel olsun dünya

Varılacak o en son menzil gelsin

Engeller tükensin, yollar açılsın, 

Koyu karanlıklar hep zelil gelsin, 

Gün yeniden yusun nefsin kirini

Adını özgürce diyen dil gelsin

Senin olmadığın yer sükût gibi

Yalnızlığı delen nur kandil gelsin

Tutku denizinden âzâde gönül, 

Sevda bu iklime müstakil gelsin, 

Bilirim yol uzun, azık yetersiz, 

Bana yol öğreten bir delil gelsin, 

Bekliyorum ey dost, vakit sırdaşım, 

Umudu saklayan o zembil gelsin, 

İntizar; çekilir gibi değil hiç, 

Sûra üfleyecek israfil gelsin, 

Bu tutku bağbân’dan şahit istemez, 

Gerekse; yürekten bin kefil gelsin, 

Bu sevdanın nerde hasmı varmış ki? 

Söyleyin, yeniden ebâbil gelsin, 

Senden gelen hoştur, razıyım ey dost, 

İster beyan, ister çetrefil gelsin, 

Dalgalar kırılsın, köpükler sussun

Seni beklediğim o sahil gelsin

Yıldızlar dökülsün bir bir yollara

Sevdalı yürekler selsebil gelsin, 

                &&&

3-Haber

Koyu karanlıklar dağılır gider, 

Muştu kıvılcımı yalar yüzümü, 

Seninle birlikte sofra kurarız, 

Seninle beraber firar ederiz.

İşte gökyüzü hep sana açıktır, 

İşte takvimlerde yazılı ismin, 

Ne zaman aynalar sana bakarlar? 

Sular ne zaman bir parıltı sunar? 

Heybelerde güneş varsa; adındır, 

Çocuk gülüşünde sen görünürsün, 

Sabah rüzgârına sorular sordum, 

Ev senin kokunla doludur dedi, 

Senin hayalinde saklıdır servet, 

Neyleyim mücevher; inci ve mercan, 

Ben senin sevdanla bahar gibiyim, 

Başka mevsimleri özlemez oldum, 

İşte burada bir ahittir sözüm, 

Seninle sürecek bu yürüyüşüm.

4-Bekleyiş

Başaklarda bahar simgesi varsa; 

Söyleyin yüreğe hep sünbül gelsin.

Yabanda kalmasın sevdalı yürek, 

Senin nefesinle kor gönül gelsin, 

Çiçek donanması, lâle, menekşe, 

Yüzünde bin renkli taze gül gelsin, 

Haddimi bilirim hem, sen gelince; 

Bu gönül önünde tenezzül gelsin, 

Kapım sana açık, çoktan beridir, 

Kaldırdım perdeyi, varsın tül gelsin, 

Yokluğunu içtim, karardı ufkum, 

Müjdeni yüklenen ak ampül gelsin, 

İzin verirsen,  ben çıkarım yola, 

Yeterki öteden bir düldül gelsin, 

Bilirim ki bu bir çetin sınavdır, 

Çilenin alnında mor püskül gelsin, 

Bir alaz yoklarken gönül bağını, 

Vuslat durağında soğuk kül gelsin, 

Bu hüznü taşımaz bu aciz yürek, 

Söyleyin, feryada bin bülbül gelsin, 

İsterse tükensin yolda azığım, 

Söyleyin oradan tevekkül gelsin, 

Hatıran bu yerde diriltir canı, 

Sen yoksan; derim ki: tahammül gelsin.

5. Sevinç

Seni andım yine dostla beraber

Seni ısmarladım güvercinlere

Topladım renkleri bir gül resminde

Aydınlık devşirdim haberlerinden

Bir yazı, bir mektup, bir uzun kelâm

Kuşatır alnımı senin adına

Beraber gidelim vardığın yere

Seni ezberlesin gözlerim yine

Bir koku duyayım derin izinden 

Hasretim yalnızca sana yönelsin

Ey bir anlam gibi yüreği saran

Bitmeyen sevdanın en son adresi

Bak, sana uçurdum gönül kuşumu

Gökyüzü seninle masmavi kalsın

                       

                             2/Mayıs/1998  Zaandam', '1-Büşra Gül senin bağrında bir bahar olur Muştu sende büyür, gün seninledir Mektuplar seninle okunur hergün Seninle geceler dönüşür nura Adı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":112,"source_url":"https://www.antoloji.com/beyaz-mevsimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yaz', 'bu-yaz-abdulkadir-akgunduz-vmory', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökten bir mavi kestim senin için; 

Bir yıldız kopardım geceden, bembeyaz...

Artık başlayabiliriz herşeye yeniden; 

Artık başlayabiliriz sevgilim, bu yaz...

Bu yaz kalbimizden doğacak güneş; 

Bu yaz kavuracak bizi her gece...

Bu yaz sevgi beleş, bu yaz aşk beleş! 

Bu yaz bize ithaf sadece...', 'Gökten bir mavi kestim senin için;  Bir yıldız kopardım geceden, bembeyaz... Artık başlayabiliriz herşeye yeniden;  Artık başlayabiliriz sev...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Akgündüz']::text[], 8.5, '{"poet":"Abdülkadir Akgündüz","poet_slug":"abdulkadir-akgunduz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin', 'neredesin-abdulkadir-akgunduz-bwwi4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben böyle değildim ki! 

Huzurum, neredesin? 

O kadar eğildim ki! 

Gururum, neredesin? 

Ne amansız yüktür bu! 

Dağlardan büyüktür bu! 

Cinnete dönüktür bu! 

Şuûrum, neredesin! 

Çığlık çığlık yüreğim, 

Arşı titreteceğim! 

Neredesin emeğim, 

Göz nurum, neredesin? 

Gök karanlık, yer yaban...

Bir adam, bin şaklaban! 

Yâ Rab, nuruna kurban

Olurum, neredesin?', 'Ben böyle değildim ki!  Huzurum, neredesin?  O kadar eğildim ki!  Gururum, neredesin?  Ne amansız yüktür bu!  Dağlardan büyüktür bu!  Cinnet...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Akgündüz']::text[], 8.5, '{"poet":"Abdülkadir Akgündüz","poet_slug":"abdulkadir-akgunduz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neredesin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek İster..', 'yurek-i-ster-ugur-seker-nyuw3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün seviyorsun, birgün hakaret, 

Birgün gerçekcisin, birgün kehanet, 

Ayrılmak için binbir mazeret, 

Bulunca beni terkedecekmisin? 

Biliyorumki sende beni çok seviyorsun, 

Aslında ayrılmayı hiç istemiyorsun, 

Bu aşka kırk dereden su getirtiyorsun, 

Ferhat gibi dağları deldirecekmisin? 

Aklın başka diyor yüreğin başka, 

Yazık edeceksin bu güzel aşka, 

Birde falcılara inanmasan keşke, 

Beni böyle terkedip gidecekmisin? 

Birgün mutluluk veriyor gülen gözlerin, 

Birgün kahrediyor acı sözlerin, 

Yüreğimdeki izler inan çok derin, 

Bu acıya birgün son verecekmisin? 

Neyi eksikti aşkımızın bitirdin böyle, 

Sevgimemi inanmadın hadi susma söyle, 

Her yüreğin harcı değil sevda çekmek öyle, 

Aşk ağırdır, sen bu yükü çekecekmisin? 

Huzur bulacakmısın terkettiğinde? 

Geç kalmış olursun farkettiğinde, 

Gerçekler kafana takettiğinde, 

Beni bıraktığın gibi bulacakmısın', 'Birgün seviyorsun, birgün hakaret,  Birgün gerçekcisin, birgün kehanet,  Ayrılmak için binbir mazeret,  Bulunca beni terkedecekmisin?  Biliy...', ARRAY['Türk Edebiyatı','Şiir','Uğur Şeker']::text[], 8.5, '{"poet":"Uğur Şeker","poet_slug":"ugur-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yurek-ister-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Budur İşte', 'hayat-budur-i-ste-muhtesem-oksel-ou1vi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Camları sildiğinde, 

Yağar yağmur sadece.

Açmaz güneş birdenbire, 

Canın gezmek istediğinde.

Bulamazsın otobüs gideceğin yere, 

O saatte.

Sular akmaz çeşmeden, her istediğinde.

Boşuna bekleme yıkanacağım diye.

Çalışamazsın gece, 

O şevk geldiğinde.

Yanmaz lambalar, hiç ümit etme.

Çıkmaz elbisenden o leke.

Şaşırma senedin borsada taban çekince.

Anlamaz sevdiğin seni bir an bile.

Katlan oğlum, hayat budur işte.

Her isteğin olmaz, her istediğinde.', 'Camları sildiğinde,  Yağar yağmur sadece. Açmaz güneş birdenbire,  Canın gezmek istediğinde. Bulamazsın otobüs gideceğin yere,  O saatte. Su...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayat-budur-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim', 'bekleyecegim-bahadir-yildirim-uh7ek', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ömür yetmiyor seni sevmeye

İstersen uğruna giderim ölmeye

Ayrıldığım an hasretin görmeye

Sni seviyorum aşığım bir tanem yalnız sana

Beynimden vuruldum ilk gördügümde

Yüreğim burkuldu son dediginde

Seni sevdiğimi her düşündüğümde

Senin de beni sevmeni bekleyeceğim', 'Bir ömür yetmiyor seni sevmeye İstersen uğruna giderim ölmeye Ayrıldığım an hasretin görmeye Sni seviyorum aşığım bir tanem yalnız sana Beyn...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Yıldırım']::text[], 8.5, '{"poet":"Bahadır Yıldırım","poet_slug":"bahadir-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bekleyecegim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-mehmet-sevili-6hj07', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kainat bir ağaçtıri meyvesi beşer, 

Her gün binlercesi toprağa düşer, 

İnsanoğlu bu dünyada bir gün yaşar, 

Ebedi bir âleme göç eder bir gün.', 'Kainat bir ağaçtıri meyvesi beşer,  Her gün binlercesi toprağa düşer,  İnsanoğlu bu dünyada bir gün yaşar,  Ebedi bir âleme göç eder bir gün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sevili']::text[], 8.5, '{"poet":"Mehmet Sevili","poet_slug":"mehmet-sevili","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/insan-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Guvenemem', 'guvenemem-asik-cemocan-q6tx8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasil Guveniyim Sana

Yurek Yarasi Biraktin Bana

Askini Yalanla Yuruttun

Butun Sevdami Tukettin

Severmiyimki Yar Artik

Gonlulde Yurekte Batik

Deldin Sen Yuregim

Beni Acilara Birakip

Asik Cemo Kaldin Yalanlara

Dayanmaz Yurek Bunca Aciya

Karadir Bu Bahtim Kara

Kanar Yurek Yana Yana', 'Nasil Guveniyim Sana Yurek Yarasi Biraktin Bana Askini Yalanla Yuruttun Butun Sevdami Tukettin Severmiyimki Yar Artik Gonlulde Yurekte Batik...', ARRAY['Türk Edebiyatı','Şiir','Aşık Cemocan']::text[], 8.5, '{"poet":"Aşık Cemocan","poet_slug":"asik-cemocan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guvenemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toreler', 'toreler-asik-cemocan-gp1r5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Haber Geldi Koyumden

Alacaklar Seni Benden

Aramiza Girdi Toreleri

Yakti Bunca Gonulleri

Duydumda Tutamadim Goz Yasimi

Duvardan Duvara Vurdum Basimi

Sanki Aldilar Alin Terimi ASIMI

Acimadan Aldilar ASKIMI

Artik Haram Bana Yasamak

Aglarim Hep Mektubunu Okuyarak

Olurum Hep Hatirlayarak

Unutmassak Olmayacak

Asik Cemo Aglasin Dursun

Yeterki Yarim Gulsun

Soyleyin Care Yok Unutsun

Alin Yazimizmis Mutlu Olsun', 'Haber Geldi Koyumden Alacaklar Seni Benden Aramiza Girdi Toreleri Yakti Bunca Gonulleri Duydumda Tutamadim Goz Yasimi Duvardan Duvara Vurdum...', ARRAY['Türk Edebiyatı','Şiir','Aşık Cemocan']::text[], 8.5, '{"poet":"Aşık Cemocan","poet_slug":"asik-cemocan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/toreler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Non Dolet 4', 'non-dolet-4-husrev-hatemi-vuggu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Terket kederi çürüyüşe ey yüreğim! 

Toplanmasın ürünü, sürünsün tarlalarda, 

Sürünsün ürünü ayak altında; 

Kalsın tarlalarda keder...

Ay doğsun gece üstüne tarlaların, 

Ay doğsun, Ay doğsun...

Evet Ay doğsun, 

Ay hep böyle üzerimde dönse...

Sevgi kalıcı, İnanç kalıcı, 

Çürüyen sâdece bedense, 

Terket kederi, çürüsün ey yüreğim.', 'Terket kederi çürüyüşe ey yüreğim!  Toplanmasın ürünü, sürünsün tarlalarda,  Sürünsün ürünü ayak altında;  Kalsın tarlalarda keder... Ay doğ...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/non-dolet-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salınım', 'salinim-mustafa-sureyya-sezgin-rkfp4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir varmış

Bir yokmuş derken, 

Ömrümüz tükeniverdi.

Hiç farkında değilken

Çocuklar büyüyüverdi.

Ama hala dipdiri

Bir gönül taşıyoruz.

Girince açmazlara

Hayata gülüyoruz.

Düşünce üretiyor

Hala beynim.

Belleğim, 

Üç yüz altmış dereceyle

Çevreyi tarayınca, 

Odaklayınca 

Olaylara zihnimi

Karamsarlaşıyorum.

Böyle anlarda

Duru ve temiz görüntülere

Takılıyorum.

Çok sıkılırsam

Boşluğa açılıyorum.

Sonsuzlukta Dünya çok küçük, 

Çok anlamsız görünüyor.

Sorun diye bir şey yok sanki.

Yalnızca bir yuvarlak

Beynimde sürekli dönüyor.

zaman ona kilitlenmiş

Hiçlikten varlığa, 

Varlıktan hiçliğe

Salınım yapıyor.

Bir görünüyor

Bir kayboıluyor varlığım.

Bazen acı, 

Bazen buruk

Tatlar duyumsuyorum.

Bugünümü çizen hangisi

Çıkaramıyorum! ..

(İstanbul,13.12.1996)', 'Bir varmış Bir yokmuş derken,  Ömrümüz tükeniverdi. Hiç farkında değilken Çocuklar büyüyüverdi. Ama hala dipdiri Bir gönül taşıyoruz. Girinc...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/salinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüsn ü Aşk''tan', 'husn-u-ask-tan-seyh-galib-6bp91', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tarz-ı selefe takaddüm ettim

Bir başka lügat tekellüm ettim

Ben olmadım ol güruha pey-rev

Uymuş beli Gencevi''ye Hüsrev

Billah bu özge maceradır

Sen bakma ki defteri beladır

Zannetme ki şöyle böyle bir söz 

Gel sen dahi söyle böyle bir söz 

Erbab- suhan tamam ma''lum

İşte kalem işte kişver-i rum

Gördün mü bu vadi-i kemini

Divan yolu sanma bu zemini

Engüşt-i hata uzatma öyle

Beş beytine bir nazire söyle

Az vaktte söyledimse anı

Na- puhteliğin değil nişanı

Gördük nice şahlar gedalar

Bir anda yapar onu babalar

Gencinede resm-i nev gözettim

Ben açtım o genci ben tükettim

Esrarını mesneviden aldım

Çaldım beli miri malı çaldım

Fehmetmeğe sen de himmet eyle

Ol gevheri bulda sirkat eyle

Çok görme bu hikmeti beyanım

Tevfika havale eyle canım

İn dem ki  zi şairi eser nist

Sultan-ı suhan menem diger nist', 'Tarz-ı selefe takaddüm ettim Bir başka lügat tekellüm ettim Ben olmadım ol güruha pey-rev Uymuş beli Gencevi''ye Hüsrev Billah bu özge macera...', ARRAY['Türk Edebiyatı','Şiir','Şeyh Galib']::text[], 8.5, '{"poet":"Şeyh Galib","poet_slug":"seyh-galib","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/husn-u-ask-tan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yük', 'yuk-mustafa-sureyya-sezgin-1jvoo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen, sevgimi taşıyamazsın inan! ..

Ağır gelir yüreğine bu coşku, 

Ezilir üzülürsün.

Nasıl katlanabilirsin ki, 

Körpe ve pembe umutlarının

Narin ve kanatlı duygularının

Üstünü örterse varlığım? 

Sen sevgimi taşıyamazsın inan! ..

Yılların susuzluğu ile alevlenen

Bağrımı göğsüne dayadığımda

Tutuşur ve yanarsın! ..

Dokununca bedenime

Sarsılır ve çökersin.

Henüz değilken vakit geç, 

Sen sevgimi taşıyamazsın inan, 

Hadi gel bu sevdadan vazgeç! ..

(İstanbul,17.12.1996)', 'Sen, sevgimi taşıyamazsın inan! .. Ağır gelir yüreğine bu coşku,  Ezilir üzülürsün. Nasıl katlanabilirsin ki,  Körpe ve pembe umutlarının Na...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüntü', 'goruntu-mustafa-sureyya-sezgin-c4t4t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşam deneyimi

Sezgilerle beslendiğinde, 

Geleceği görüntüleyen

Beyindeki ışınımdır belki de...

Sanki, 

Kaderinin senaryosu önümde, 

Okuyorum geleceğini

Ve görüyorum, 

Bir kafese gireceğini...

Belki de yazılan budur.

Bugün, 

Mutluluk saçarken sen

Nasıl derim sana dur? 

Umutların büyük büyük, 

Küçük omuzlarına 

Aldığın bu ağır yük

Solduracak yüzündeki

Pembe açan gülücükleri

Ve sen, 

O eski sen olmayacaksın artık.

Ezildiğini bile bile

Bu yaşananlar kader diye

Katlanacaksın ömür boyu

Bitmeyecek bir çileye! ..

Ve bir gün, 

Gerçeği arayacaksın.

Dönüp ardına baktıkça

Belki de ağlayacaksın...

Saçların ağaracak, 

Ancak, 

Yaşam geçmiş olacak

Geride bir resim gibi

Kucak kucak

Yığılı anıların kalacak...

(İstanbul,19.01.1997)', 'Yaşam deneyimi Sezgilerle beslendiğinde,  Geleceği görüntüleyen Beyindeki ışınımdır belki de... Sanki,  Kaderinin senaryosu önümde,  Okuyoru...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/goruntu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-mustafa-ozke-5xvk4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Babam diyorum

Çocukken hep bana nasihat ederdi

Kendi düşen ağlamaz derdi

Bu sözü dedem öğretmiş ona

Hep merak ederdim

Atalarımız söylemeseydi bu sözü

Her düşen ağlamayacak mıydı

Ağlayacaktı elbet

Demek ki düşüp ağlamış atalarımız

Sonra da görmüşler hatalarını

Yaşamışlar hayatın gerçeklerini

Ardındakiler hata yapmasın diye

Kendi düşen ağlamaz demişler

Bu sözle önemli mesajlar vermişler

Ne söyledilerse iyi söylemiş atalarımız

Zaten onları dinlemediğimiz için

Her geçen gün artıyor hatalarımız', 'Babam diyorum Çocukken hep bana nasihat ederdi Kendi düşen ağlamaz derdi Bu sözü dedem öğretmiş ona Hep merak ederdim Atalarımız söylemeseyd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nasihat-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Beyaz', 'siyah-beyaz-mustafa-sureyya-sezgin-1uu1k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ay buluta giriyor

Umut umutsuzluğa, 

Gündüz geceye dönüşüyor.

Bu gece, 

İçim acıyor...

Yüreğim daralıyor.

Yaşamın renkleri 

Solarak

Siyah beyaz oluyor.

Bu görüntü, 

Sevincimi örtüyor.

Ağzımda anlayamadığım

Buruk bir tat var.

Yarın güneş yine doğacak

Ve ben yeniden

Yaşıyor görüneceğim.

Artık, 

Bu hep böyle olacak.

Bakmayın

Gözlerimin güldüğüne

Siz nasıl bileceksiniz? 

Yüreğimin kanadığını, 

Yüzümün arkasını

Nereden göreceksiniz? 

Bütün yaşadıklarım

Benziyorken düğüne, 

Yıllar geçip giderken

Gülümserim ölüme...

(İstanbul,02.02.1997', 'Ay buluta giriyor Umut umutsuzluğa,  Gündüz geceye dönüşüyor. Bu gece,  İçim acıyor... Yüreğim daralıyor. Yaşamın renkleri  Solarak Siyah be...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/siyah-beyaz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Coşku', 'cosku-mustafa-sureyya-sezgin-wg5e9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dur bakalım deli kız! ..

Bu ne acele bu ne hız? 

Duyguların zinciri mi olur? 

Biliyorum sen zincirlesen bile, 

Durduramazsın

Alır başını gider onlar.

Ama daha

Yaşayacağın, tadacağın

Ve anlayacağın

Çok şey var...

Yarınlar kucak kucak

Hepsi de yaşanacak, 

Ömrünün yarısı hüzün

Yarısı mutluluk olacak! ..

(İstanbul,04.02.1997)', 'Dur bakalım deli kız! .. Bu ne acele bu ne hız?  Duyguların zinciri mi olur?  Biliyorum sen zincirlesen bile,  Durduramazsın Alır başını gid...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cosku-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Güzel', 'ey-guzel-hadi-i-stanbullu-repij', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey güzel dön bana yüzünü

Kaçma benden, bak ben buradayım 

İşte karşında

Sana ellerimi uzatmış, 

Büyük bir istekle tutmak istiyorum seni

Kavramak, sarılmak içten...

Bir olmak tek olmak yek vücut olmak için

Gözlerim gözlerine öyle sakin

Öyle içten bakıyor ki

İçinde sanki kendimi görüyorum

Huzur buluyor rahatlıyorum

Tüm saflığın temizliğinle seni görüyorum

Bir olmak tek olmak yek vücut olmak için.

Ellerinin sıcaklığını

Tüm bedenimde hissediyorum

Tatlı bir titreme geçiyor vücudumdan

Sanki sular boşalıyor

Yukarılarım dan aşağılarıma

Başka hiçbir şey düşünmüyorum

Yalnız sen

Tüm benliğimde

Yalnız sen

Temizliğin saflığın güzelliğinle... 

Bir olmak tek olmak yek vücut olmak için...', 'Ey güzel dön bana yüzünü Kaçma benden, bak ben buradayım  İşte karşında Sana ellerimi uzatmış,  Büyük bir istekle tutmak istiyorum seni Kavr...', ARRAY['Türk Edebiyatı','Şiir','Hadi İstanbullu']::text[], 8.5, '{"poet":"Hadi İstanbullu","poet_slug":"hadi-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ey-guzel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramak', 'aramak-sair-cukurkoprulu-plr9o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni aramaya çık nezihe 

bilip bilmediğin yerlerde

yazın sıcağında veya kışın soğuğunda

bahçemize tarla kuşları konduğunda

Ben uzaklarda değil yanındayım

bazen oturma odasında

bazen mutfaktayım

ve bazende dışarı çıkmaktayım 

bahçemize tarla kuşları konduğunda.', 'Beni aramaya çık nezihe  bilip bilmediğin yerlerde yazın sıcağında veya kışın soğuğunda bahçemize tarla kuşları konduğunda Ben uzaklarda değ...', ARRAY['Türk Edebiyatı','Şiir','Şair Çukurköprülü']::text[], 8.5, '{"poet":"Şair Çukurköprülü","poet_slug":"sair-cukurkoprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aramak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-hadi-i-stanbullu-pmkah', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlümde sen

İçimde sen

Kalbimde sen

Hep sen varsın

Karşımda

Yanımda

Yöremde

Her yerimde

Nereye baksam nereye gitsem

Hep sen sen sen...

Biliyorum uzaklardasın şimdi

Belki sende özledin beni

Belki bazen aklına geliyor hayalim

Ama ben seni hiç unutmadım

Bir tanem hep yanımdasın

Hep sen sen sen', 'Gönlümde sen İçimde sen Kalbimde sen Hep sen varsın Karşımda Yanımda Yöremde Her yerimde Nereye baksam nereye gitsem Hep sen sen sen... Bili...', ARRAY['Türk Edebiyatı','Şiir','Hadi İstanbullu']::text[], 8.5, '{"poet":"Hadi İstanbullu","poet_slug":"hadi-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 02.00 Kimsecikler Yokmu', 'saat-02-00-kimsecikler-yokmu-selim-ucari-pqenw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'perdenin arkasında görünen karartı 

zebanilerin kralı 

lavarartus''un oğlu çamdikanski mi acaba, 

tam seçemiyorum.. 

kırmızı perde 

beyaz tülün içlerine kadar girmiş 

çiçek motiflerine 

tecavüz ediyor hiç durmadan 

karartı şaklatıyor parmağını 

ve sevgilileri geliyor 

birer birer yan odadan.. 

niğdelemence ve karmendianas 

çok güzel değiller 

ama seksapaliteleri 

ömrümün üçte ikisini götürüyor 

feryat figan gidiyor üçte ikim... 

gramajını artıyor karanlık 

yavaş yavaş 

inler cinler periler başlıyorlar 

geleneksel zifiri eğlencelerine 

hah ha hah HA HA HA.... 

buzul kayaları gibi terim 

usul usul terkediyor derimi 

anlıyorum 

nankörlük kol geziyor gece de.. 

bu odanın 

lambaları yok mu, var 

peki düğmesi nerede o zaman 

ulaşamıyorum.. 

çıtların hepsi çıtlamış 

hiç çıt kalmamış kulağımı okşayan 

duyamıyorum... 

çığlıklar artıyor 

çığLIK, çıĞLIK, ÇIĞLIK 

demek ki perde 

devam ediyor tecavüze 

çamdikanski sevgililerini 

elden geçirmeye başlamış 

odamın içinde 

inİM iNİM İNLİYOR gece... 

aman tanrım olan oldu 

kalbim hızlandırdı adımlarını 

dörtnala kaçıyor 

göz kapaklarım da kitlendi 

açılmamak için 

gözümün beyazına 

ana avrat küfrediyor... 

o değil de 

zebanilerin kralı lavarartus gelirse 

o zaman hepten boku yedik 

biliyorum.. 

onun için de lambanın düğmesine 

biran önce ulaşmak gerek 

çabalıyorum... 

gecenin eğlencesi 

bir türlü bitmek bilmiyor 

hah ha hah HA HA HA.... 

titreterek bedenimi 

devam ediyor, devam ediyor.. 

en sonunda da 

aklım ruhum herşeyim 

bir kürek mahkumunun 

umutsuz haykırışlarına dönüşüyor... 

okuduğum bütün dualar 

bir bumerang misali 

attığım gibi geri dönüyor 

svıs, svIS, SVIS... 

ama atmaya devam ediyorum 

yusuf, yuSUF, YUSUF......', 'perdenin arkasında görünen karartı  zebanilerin kralı  lavarartus''un oğlu çamdikanski mi acaba,  tam seçemiyorum..  kırmızı perde  beyaz tül...', ARRAY['Türk Edebiyatı','Şiir','Selim Uçarı']::text[], 8.5, '{"poet":"Selim Uçarı","poet_slug":"selim-ucari","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/saat-02-00-kimsecikler-yokmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üfürmeler- Toplu', 'ufurmeler-toplu-selim-ucari-z9alk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'asparagas bir bulutun 

serpiştirdiği yağmur damlaları bunlar, 

yanılmamak lazım kandırılmamak gerek... 

önemli haykırışlarımızın, 

sabaha faydası çok olabilir.. 

amma velakin, 

üstüne oturduğumuz dikensiz gül bahçesinin 

iştahımızı kaçırtmaması için elden ne gelir.. 

maalesef koca bir hiç, koskocaman bir hiç.. 

* * * 

sen, 

geceleri zindan, yatağı mezar olan sen, 

güzel dostum, kır çiçeğim, nar tanem gel otur yanıma.. 

fırsatları kimin kaçırdığından bahsedelim istersen, 

gözlerinin içindeki korkuyu büyütelim beraber, 

duymak istemediğin gerçeklerini, 

kulağına fısıldamak için buradayım ben zaten.. 

hadi yaklaş, 

tam yerine geldin çok şanslısın.. 

sen, 

geceleri zindan, yatağı mezar olan sen, 

böyle yıllar yılı, vicdan azabı içinde mi yaşayacaksın.... 

* * * 

eminim, 

aynada yansıyan şu siluetin 

yaşadığının bir onaylaması gibi sanki senin... 

evet, 

kesin bu sensin, 

yaşıyorsun ve capcanlısın, 

bunlar ellerin, bunlar da gözlerin, 

başka bir güce ihtiyacın yok gibi sanki senin... 

* * * 

yorgunuz, 

senle kaybetmişiz herşeyimizi, 

umutsuz bir aşk için feda eylemişiz kendimizi.. 

biz, 

ikimiz, 

sonradan pişman olan bir mermi gibiyiz... 

yalnızız, 

çok yalnızız, 

dilini parçaladığı balığın, 

son duasını okuyan bir oltaya dönmüş bakışlarımız.. 

ve artık, 

bakamıyoruz yüzlerimize, 

bir zamanların, sudan ak güneşten parlak yüzlerimize... 

yorgunuz, 

senle yoketmişiz geçmişimizi, 

eskinin çılgın söylevleri gibi unutmuşuz kendimizi...', 'asparagas bir bulutun  serpiştirdiği yağmur damlaları bunlar,  yanılmamak lazım kandırılmamak gerek...  önemli haykırışlarımızın,  sabaha fa...', ARRAY['Türk Edebiyatı','Şiir','Selim Uçarı']::text[], 8.5, '{"poet":"Selim Uçarı","poet_slug":"selim-ucari","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ufurmeler-toplu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-gulay-atilay-00yya', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEVMEK

Sevmek, 

Çok özlemekmiş. 

Sevmek, 

Özel bir kalpte yer etmekmiş. 

Sevmek, 

Ayrı zamanlarda 

Farklı yerlerde bile 

Çok sevilenle olabilmekmiş. 

Sevmek, 

Acı çekmekmiş. 

Sevmek, 

Ayrılıkta bile sevgi bulabilmekmiş. 

Bu öyle böyle birsey değil; 

Sevmek, 

Ezilmek kahrolmakmış

Sevmek, 

Yaşarken ölmekmiş.

     Gülay Atilay', 'SEVMEK Sevmek,  Çok özlemekmiş.  Sevmek,  Özel bir kalpte yer etmekmiş.  Sevmek,  Ayrı zamanlarda  Farklı yerlerde bile  Çok sevilenle olabi...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevmek-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmin kaldı..', 'resmin-kaldi-gulay-atilay-suqge', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'RESMİN KALDI...

Resminden bana bakan bir yüzün kaldı 

Simsiyah bir çerçevede 

Ama hiç eksilmedi gülümsemen

Bir oda dolusu sevgin kaldı 

Duvarlar bembeyaz sevgimin saflığı gibi 

Sana olan aşkım gibi tertemiz.. 

Gözlerin gelir aklıma, kapatsam gözlerimi 

Ellerini tutmak isterim, tutarım nefesimi..

Sen yoksun.....

Fakat hayallerimde.

Ağlıyorum sen hala susuyorsun..... 

Sevecen ellerinle dokunuyorsun 

Sadece sus! ! ! yeter artık ağlama diyorsun.. 

Sanki sesin geliyor kulağıma...

Herşey çok yakın duyduklarımla gördüklerimle 

Sen yoksun sadece resmin kaldı elimde.... 

Bir oda dolusu sen; bir yürek dolusu sen

Sadece sen! ! 

GÜLAY ATİLAY', 'RESMİN KALDI... Resminden bana bakan bir yüzün kaldı  Simsiyah bir çerçevede  Ama hiç eksilmedi gülümsemen Bir oda dolusu sevgin kaldı  Duva...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/resmin-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tamam Yavrum, Meleğimiz yok; Ama Yağmurumuz Var', 'tamam-yavrum-melegimiz-yok-ama-yagmurumuz-var-charles-bukowski-vzek2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sera etkisi deyin ne derseniz deyin 

eskisi gibi yağmıyor işte yağmur. 

özellikle büyük kriz zamanındaki 

yağmurlar geliyor aklıma. 

kuruş para yoktu ama bolbol 

yağmur vardı. 

öyle bir gece veya bir gün 

değil, 

7 gün ve 7 gece 

YAĞARDI 

ve Los Angeles''in yağmur ızgaraları 

bu kadar çok yağmuru emebilecek 

şekilde yapılmamıştı 

ve yağmur KALIN 

ve KARARLI 

ve DÜZENLİ yağardı 

ve damlaların çatılara çarpışını 

oradan da oluk oluk 

toprağa akışını DUYARDINIZ 

ve DOLU, 

büyük BUZDAN KAYALAR 

patlayan 

oraya buraya saçılan havada uçuşan; 

ve yağmur 

kısaca 

DURMAZDI 

ve bütün çatılar akardı - 

evin her tarafına 

tencereler, 

kapkacaklar serilir 

TIP TIP sesleri bütün eve yayılırdı; 

ve kaplar boşaltılır, 

boşaltılır 

ve tekrar boşaltılırdı. 

kaldırımların üstünden geçerdi yağmur, 

bahçelerin içinden; ve merdivenleri tırmanıp 

evlere girerdi. 

el bezleri vardı, banyo havluları, 

ve yağmur genelde 

tuvaletlerden girerdi: köpüre köpüre, kahverengi, küçük girdaplarla 

ve külüstür arabalarla dolu olurdu sokaklar 

güneşli bir günde 

marş basmayan arabalarla, 

ve işsiz adamlar 

sanki canlılarmış gibi duran o eski arabaların 

can çekişmelerine bakarlardı 

pencereleri önünden; 

işsizler, 

yenik bir zamanın yenik insanları 

hapsolurdu evlerine 

karıları ve çocukları 

ve kedi köpekleriyle. 

kediler ve köpekler 

dışarı çıkmamak için diretir 

evin garip garip yerlerine 

pisliklerini bırakırlardı. 

işsiz adamlar 

bir zamanlar güzel olan karılarıyla 

evde tıkılıp kalmış olmaktan 

çıldırırlardı. 

korkunç tartışmalar yaşanırdı 

haciz ihtar mektupları 

kondukça posta kutularına. 

yağmur ve dolu, bezelye kutuları, 

yavan ekmekler; kızarmış 

yumurta, rafadan yumurta, haslanmış 

yumurta; fıstık ezmesi 

sandviçleri, ve her tencerede 

görünmez bir tavuk. 

babam, kesinlikle iyi biri olmayan babam 

her yağmurda, en iyi ihtimalle, 

annemi döverdi, 

kendimi üzerlerine atardım, 

bacaklar, dizler, 

çığlıklar 

ta ki 

birbirlerinden 

ayrılana kadar. 

''Gebertic''em seni, '' bağırırdım ''Bi'' kez 

daha vurursan ona öldürürüm seni! '' 

''Çabuk bu orospu çocu''unu 

çıkar burdan! '' 

''hayır, Henri, annenin 

yanında kal! '' 

evet, bütün evler kuşatma altındaydı 

fakat sanırım bizim evdeki dehşet 

ortalamanın üstündeydi. 

ve geceleri 

uyumaya çalıştığımızda 

yağmur yağmaya devam ederdi 

ve karanlıkta 

suların odama girmemesi için 

cesurca direnen penceremden 

ayın yağmur sularıyla bulanık 

görüntüsünü seyrederken 

Nuh''u hayal ederek 

ve Gemisini 

tekrar oluyor galiba 

diye düşünürdüm. 

hepimiz düşünürdük 

bunu. 

ve sonra, birdenbire, 

dinerdi yağmur. 

galiba hep 

sabaha doğru 

5,6 sularında dinerdi, 

huzur çökerdi her yere, 

ama tam bir sessizlik değil 

çünkü hala devam ederdi 

tip 

    tip 

        tip 

      sesleri 

ve sonra sis ve duman 

dağılırdı 

ve sabah 8''de 

gözleri kamaştıran sapsarı bir güneşışığı 

düşerdi yeryüzüne, 

Van Gogh sarısı - 

çılgın, köredici! 

ve ardından 

sağanaktan kurtulan 

çatı olukları 

güneş altında 

genleşmeye başlardı: 

PENG! PENG! PENG! 

ve herkes kalkıp dışarı bakardı 

hala yağmuru içine çeken 

bahçeler 

hiç bu kadar yeşil olmamış 

bir yeşil içinde 

ve kuşlar 

bahçelerde 

deli gibi cıvıldayan kuşlar, 

7 gün 7 gecedir 

yere konup da 

adamakıllı bir şey yiyememiş 

tohum yemekten 

bıkmış  kuşlar 

solucanların 

toprak üstüne çıkmasını beklerlerdi, 

yarı boğulmuş solucanların. 

kuşlar solucanları önce topraktan çekip 

havaya kaldırır 

sonra da midelerine indirirlerdi; 

karatavuklar ve serçeler olurdu. 

karatavuklar serçeleri uzaklaştırmaya 

çalışır 

ama serçeler, 

açlıktan delirmiş, 

daha küçük ve çabuk, 

kendi paylarını 

kotarırlardı. 

erkekler verandada durur 

sigaralarını içerlerdi, 

şimdi kapı kapı dolaşıp 

büyük olasılıkla hiç bir kapı ardında 

bulamayacakları bir 

iş arayacaklarının, 

büyük olasılıkla çalışmayacak arabalarını 

çalıştırmaya uğraşacaklarının 

bilincinde. 

ve bir zamanlar güzel olan 

karıları 

banyoya girer 

saçlarını tarar, 

makyajlarını yapar, 

dünyalarını tekrar 

biraraya getirmeye çalışırlardı, 

onları saran korkunç mutsuzluğu 

unutmaya çalışarak, 

kahvaltı için 

ne hazırlasam diye 

telaşlanarak. 

ve radyo 

okulların 

açıldığını söylerdi. 

ve 

ardından 

işte ben 

yine okul yolundaydım, 

yollarda kocaman 

su gölcükleri, 

tepemde yeni bir dünya gibi 

güneş, 

evde annemler, 

okula 

zamanında vardım. 

Bayan Sorenson bizi 

''bugün tenefüs yok, 

yerler çok ıslak'' 

diyerek karşıladı. 

çocuklar ''AOF'' 

bağırdı bir ağızdan. 

''fakat tenefüs saatinde 

çok farklı birşey 

yapacağız, '' dedi, 

''ve çok zevkli 

bir şey! '' 

hepimiz merak ettik 

bu çok zevkli şeyin 

ne olduğunu 

ve o iki saat 

Bayan Sorenson 

dersini anlatmaya 

devam ederken 

bir türlü geçmek bilmedi. 

Küçük kızlara baktım, 

çok tatlı ve temiz ve 

dikkatli görünüyorlardı, 

uslu ve dik 

oturuyorlarken sıralarında 

ve saçları 

Kaliforniya 

güneşi altında 

çok güzeldi. 

sonra tenefüs zili çaldı 

ve hepimiz eğlenceyi 

beklemeye koyulduk. 

ardından Bayan Sorenson sınıfa seslendi: 

''şimdi ne yapacağız 

biliyor musunuz, birbirimize 

yağmur sağanağı sırasında 

neler yaptığımızı anlatacağız! 

en ön sıradan başlayıp 

arka sıralara doğru devam edeceğiz! 

hadi Michael, sen başla! ...'' 

ve hepimiz 

hikayelerimizi 

anlatmaya başladık, Michael başladı 

ve herkes sırayla kalkıp devam etti, 

ve sonra farkettik ki 

hepimiz yalanlar söylüyorduk, tamamen 

yalan sayılmaz ama 

çoğunlugu yalandı 

ve oğlanlardan bazıları pis pis 

gülmeye başladığında kızlar onlara 

kötü bakışlar fırlattı ve 

Bayan Sorenson ''tamam! '' diye bağırdı 

''tam bir sessizlik istiyorum! 

Siz merak etmeseniz de 

ben 

neler yaptığınızı 

öğrenmek istiyorum! '' 

böylece biz de hikayelerimize 

devam ettik 

ve hepsi de hikayeydi. 

bir kız gökkuşağı 

ilk çıktığında bir ucunda 

Tanrı''nın yüzünü 

gördügünü söyledi. 

bir tek hangi ucu olduğunu söylemedi. 

bir oğlan oltasını 

pencereden sarkıtıp 

bir balık yakalayıp 

kedisini 

beslediğini söyledi. 

hemen hemen herkes 

bir yalan uydurdu. 

gerçek 

fazla acı 

ve utandırıcıydı. 

sonra zil çaldı 

ve tenefüs bitti. 

''teşekkür ederim, '' dedi Bayan 

Sorenson, ''hepsi çok 

hoştu. 

yarına kadar 

yerler 

kurur ve 

kullanılabilecek 

hale gelir.'' 

çocuklardan bir 

gürültü koptu. 

küçük kızlar 

dimdik ve uslu 

oturuyorlardı, 

çok tatlı ve 

temiz ve 

dikkatli, 

saçları dünyanın bir daha 

asla göremeyeceği bir güneşin 

ışıkları altında 

çok güzel 

görünüyordu. 

ve', 'sera etkisi deyin ne derseniz deyin  eskisi gibi yağmıyor işte yağmur.  özellikle büyük kriz zamanındaki  yağmurlar geliyor aklıma.  kuruş p...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":286,"source_url":"https://www.antoloji.com/tamam-yavrum-melegimiz-yok-ama-yagmurumuz-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gücendiğim -1-', 'gucendigim-1-mutlu-celik-p4267', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne vardı saçını dökecek

Be koca çınar, 

Gücendiğim sen değilsinki 

Gücendiğim sonbahar.', 'Ne vardı saçını dökecek Be koca çınar,  Gücendiğim sen değilsinki  Gücendiğim sonbahar....', ARRAY['Türk Edebiyatı','Şiir','Mutlu Çelik']::text[], 8.5, '{"poet":"Mutlu Çelik","poet_slug":"mutlu-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gucendigim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gücendiğim -2-', 'gucendigim-2-mutlu-celik-0cytf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saçın ağarmış koca çınarım

Sonbahar gitti gücendirerek.

