INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avşa', 'avsa-mustafa-sureyya-sezgin-pmjrm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni serin koynuna alan

Ey çıplak bedenli bakire! ..

Kuşlarının

Ve cırcır böceklerinin sesini

Gizleyiver! ..

Sıyırma vücudunu fistanından.

Örtsün endamını peçeler! ..

Yoksa, 

Bodrum gibi, 

Marmaris gibi, 

Senin de ırzına geçer, 

Doğanın katilleri! ..

(İstanbul,23.07.1998)', 'Beni serin koynuna alan Ey çıplak bedenli bakire! .. Kuşlarının Ve cırcır böceklerinin sesini Gizleyiver! .. Sıyırma vücudunu fistanından. Ö...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/avsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi', 'hadi-naside-gokturk-dhufb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir şehrin siyah saçlarını örüyorum

beyoğlu kalabalık bir karanlıkta

gözlerimde perdesiz bir gece var

çiçekler son karanfillerini saklamış gözyaşlarımın tuzundan

belli ki aşkın kimyası ağır

belli ki çapraz aşkın yolları dar

yani

yorgun gözlerimin yeşili

yani

besmeleler dudaklarımda yorgun

benden gizli bir tebessüm içinde hayat

yalnızlığım yorgun

kalbim kançanağı sağanaklarında özleminin

seni seviyorum diyorum kendi kendime

seni seviyorum 

seni seviyorum

çık gel 

kendini al gel bana

her nerdeysen ve ne haldeysen çık gel

sensizliğin acısını başkalarından saklamaktan yoruldum

istemediğim halde gülümsemenin bende yarattığı ihanetten

istemediğim anlarda denizi seyretmekten

istemediğim içkileri içmekten

bana ait olmayan sarhoşlukları yaşamaktan

ve sensiz bir sabaha uyanmaktan yoruldum

çık gel

çık gel ki ellerim ısınsın

çık gel ki başkalarına verdiğim cevaplar güçlensin

çık gel

çık gel ki azrail utansın

çık gel

sensizliğin şehrinde ateşe veriyorum saçlarımın beyazını

sabrımın rengi siyah sanırdım oysa

sanki yüreğim avucumda

sanki her sabah pişmanlığını anlatan

bir mektup atılacak kapımın altından

sanki senin için verdiğim kavgalardan insanlar utanacak

sanki yanılmamışlığımın gecesi sabah olacak

sanki seni sevmemin sonucu

sensizlik olmayacak

çık gel

çık gel akşamlarımın akşam sefası rengince

çık gel aşka inanmayanların yüzünü kızartırcasına

çık gel 

bir daha gtmeyecekmişcesine', 'bir şehrin siyah saçlarını örüyorum beyoğlu kalabalık bir karanlıkta gözlerimde perdesiz bir gece var çiçekler son karanfillerini saklamış g...', ARRAY['Türk Edebiyatı','Şiir','Naşide Göktürk']::text[], 8.5, '{"poet":"Naşide Göktürk","poet_slug":"naside-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/hadi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-murat-i-lgun-xic3j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güne  dön  yüzünü

ardında  dünler  kalsın

geç  patlamış  tohum  say  kendini

toprağı  avuçla

yeniden  başla  yaşamaya

dün  ensenden  tutarsa

aldırma

bitmiştir

çekemez  seni  kendine

anılarda  sakın  ağlama

bir  bebeğin  ilk  çığlığına  sarıl

umut  işte  orda

sakın  unutma

geç  patlamış  tohum  say  kendini

merhaba de  hayata.', 'Güne  dön  yüzünü ardında  dünler  kalsın geç  patlamış  tohum  say  kendini toprağı  avuçla yeniden  başla  yaşamaya dün  ensenden  tutarsa...', ARRAY['Türk Edebiyatı','Şiir','Murat İlgün']::text[], 8.5, '{"poet":"Murat İlgün","poet_slug":"murat-i-lgun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yeniden-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçerim sokakları', 'gecerim-sokaklari-omer-faruk-gunay-5njy9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'geçerim sokakları

