INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavaş yavaş eriyip gittiğimi göreceksin', 'yavas-yavas-eriyip-gittigimi-goreceksin-omer-faruk-gunay-uiuvz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yavaş yavaş eriyip gittiğimi göreceksin

