INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-yunus-ors-ji6u8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hic konuşmadan yüzüne bakmak                                  bakarken gözleriden kalbine akmak                      herseferinde başbaşa kalmak                              benseninledogmak dogmak istiyorum                             ellerini tutmak saçlarını okşamak                                           senin yoluna ölmek ölmek istiyorum                                     seniseviyorum canım anlamalısın?', 'hic konuşmadan yüzüne bakmak                                  bakarken gözleriden kalbine akmak                      herseferinde başbaşa ka...', ARRAY['Türk Edebiyatı','Şiir','Yunus Örs']::text[], 8.5, '{"poet":"Yunus Örs","poet_slug":"yunus-ors","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ozlem-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Yakanların Selamı', 'gunesi-yakanlarin-selami-i-lhan-berk-q1qut', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zevk duyulmaz oldu, buranın rüzgârlarından

Hayat soldu bir günün enginlerinde yine.

Selâm! Sonsuzların yorgun gönüllerine

Selâm: Güneşi içeren çocukların diyarından! ...

Bir ateş yakalım ki geçmesin hatta 
..........
..........', 'Bir zevk duyulmaz oldu, buranın rüzgârlarından Hayat soldu bir günün enginlerinde yine. Selâm! Sonsuzların yorgun gönüllerine Selâm: Güneşi ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"i-lhan-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gunesi-yakanlarin-selami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Çok Özledim', 'seni-cok-ozledim-murvet-arslan-663gv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykusuzum bu gece

Eski şerkıları dinledim

Ağladım yatağımda

Üzülme, sensizde yaşanıyor bu hayat; 

Hava sıcak, yaprak bile kıpırdamıyor burada

Sensizlikten üşüyen beni ısatımıyor ki güneş, 

Bir gün daha geçti, 

Her dakika aklımda sen varsın

Aramıyorum sormuyorum diye kırılma bana

Seni o kadar özledimki anlatamam

Seni sensiz yaşacak kadar içimde hissediyorum özlemini

Bahçeye bir gül diktim ismi sen

Senin hasretinle, benim gözyaşımla büyüyor

Yüzümdesahte bir tebessüm, gözlerim dolu, kirpiklerim nemli

Hayat seninle güzel, seninle anlamlıymış

Yaşıyormuyum şimdi? 

En güzel aşk şarkılarını yanlız dinliyorum

Yastığıma sarılıp hıçkıra hıçkıra ağlıyorum

Kimse bilmiyor içimdeki seni

Her yanlız kaldığımda seni yaşıyorum

Gezdiğimi yerleri bir daha geziyor

Ağzımdan dökülen üç kelime oluyor

''''SENİ ÇOK ÖZLEDİM''''', 'Uykusuzum bu gece Eski şerkıları dinledim Ağladım yatağımda Üzülme, sensizde yaşanıyor bu hayat;  Hava sıcak, yaprak bile kıpırdamıyor burad...', ARRAY['Türk Edebiyatı','Şiir','Mürvet Arslan']::text[], 8.5, '{"poet":"Mürvet Arslan","poet_slug":"murvet-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-cok-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran', 'haziran-i-lhan-berk-f4sq5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'My love is like a red, red rose (e.e.cummings)

Kırmızı kırmızı bir güldür aşkım

İnce yüzünüzde. Kırmızı. Korkunç.', 'My love is like a red, red rose (e.e.cummings) Kırmızı kırmızı bir güldür aşkım İnce yüzünüzde. Kırmızı. Korkunç....', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"i-lhan-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/haziran-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikaye', 'hikaye-i-lhan-berk-lj364', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şey bir gece içinde oldu

Sabahleyin her şey tamamdı.

Bu gördüğünüz gökyüzü

İlk defa gelip yerini aldı

Gökyüzünün gelmesiyleydi

Dünyada büyük bir değişiklik oldu

Mesela, ovalar daha o gün

Yalnızlıklarını unutuverdiler

Bu şimdi elsiz ayaksız gibi duran gece

O zaman ağaca yürüyen bir su gibi geliyordu

Gökyüzünün hemen ar
..........
..........', 'Her şey bir gece içinde oldu Sabahleyin her şey tamamdı. Bu gördüğünüz gökyüzü İlk defa gelip yerini aldı Gökyüzünün gelmesiyleydi Dünyada b...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"i-lhan-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hikaye-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
