INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peranın Eski Bİr Sokağında', 'peranin-eski-bi-r-sokaginda-i-lhan-berk-r751k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kuşlar kalkıyor Aya İrini üstünden 

Bir sap ot kulaklarının arkasında. 

Ben sonunda burdasın işte diyorum kendi kendime 

Burda eski bir atlasın kesiştiği yerde. 

Bir kedi gözlerini dikmiş s
..........
..........', 'Kuşlar kalkıyor Aya İrini üstünden  Bir sap ot kulaklarının arkasında.  Ben sonunda burdasın işte diyorum kendi kendime  Burda eski bir atla...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"i-lhan-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/peranin-eski-bir-sokaginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Dedim Def o Denizler Aldı Beni', 'siz-dedim-def-o-denizler-aldi-beni-i-lhan-berk-th25r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siz dedim de f, o denizler aldı beni.

Sabah haliniz o eski suları geçtim.

Helene''nin baktığı denizlerde Paris''dim.

Yeni sesler buldum, renkler, diller yeni

Kral yalnızlı
..........
..........', 'Siz dedim de f, o denizler aldı beni. Sabah haliniz o eski suları geçtim. Helene''nin baktığı denizlerde Paris''dim. Yeni sesler buldum, renkl...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"i-lhan-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siz-dedim-def-o-denizler-aldi-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Isıtır Ellerini', 'yuregim-isitir-ellerini-i-smail-ozabaci-7m15s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasta bir dört mayıs akşamı, 

''iyiyim'' diyebilmek sana

başın omuzlarıma düşmüşken

yıldız koparabilmek gökyüzünden..

yüregimin sıcaklığıyla elini ısıtmaya çalışmak

olsa gerek aşk dedikleri..

ve sattlerce kalma isteği bir bankta

başın omzumda, elin elimde

ki yüreğin taa yüreğimde; 

sevgili; 

gözlerimin içine baktığında gördüğün tebessüm

ay yüzünün, yansımasıdır içimde

ve kahverengi bir aydınlıktır, 

sana attığım her adımda

önümü aydınlatan ışık..

özlemim, 

vuslatım, 

açlığım, 

kavgam, 

direnişim

umudum, 

susuzluğum

kısaca hayatım sanadır

hadi uzat ellerini 

yüreğim ısıtır..', 'Hasta bir dört mayıs akşamı,  ''iyiyim'' diyebilmek sana başın omuzlarıma düşmüşken yıldız koparabilmek gökyüzünden.. yüregimin sıcaklığıyla e...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yuregim-isitir-ellerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözlerin', 'sozlerin-mehmet-ali-cibikli-3j4z1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bahar yeli gibi, 

Esip geçtin apansız.

Sen gidince gönlümde, 

Duygular kaldı cansız.

Dönüp baktım maziye, 

Hatıranla avundum.

Bir hayalin bir de sen, 

Yokluğunda kayboldum.

Bir rüzgarın önünde, 

Savrulan yaprak gibi.

Tutunacak dalım yok, 

Öyle çaresizim ki.

Tutunacak dalımdın, 

Ben seninle yaşardım.

Canımdın herşeyimdin, 

Sen varsan ben de vardım.

Ne sen varsın yanımda

Ne de güzel gözlerin.

Kulaklarımda çınlar, 

''Sevdim'' diyen sözlerin.

07.06.2002', 'Bir bahar yeli gibi,  Esip geçtin apansız. Sen gidince gönlümde,  Duygular kaldı cansız. Dönüp baktım maziye,  Hatıranla avundum. Bir hayali...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılardaki Hüzün', 'sarkilardaki-huzun-ozcan-nevres-3fwnd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçli bir şarkının nağmeleri geliyor uzaktan

Seni alıp getiriyor bana dalga dalga

Terk edip gittiğinden beri 

Hiç bitmedi bu kara sevda

Bak yine sahilde 

Buluştuğumuz yerdeyim

Yakamozlarda aradım seni

Usumca şekillensin diye

Ne yakamozlar kalmış denizde

Ne de sen vardın revnakların içinde

Yokluğun dağ dağ büyüdü gönlümde

Ayrılırken tez unutursun demiştin

Aşk ta biter hasrette günün birinde

Unutamadım seni sevgilim unutamadım

Sensiz yaşamaya hiç alışamadım

Gözlerimde yaş boğazımda bir düğüm

Boğuluyorum sevgilim boğuluyorum

Ölümü düşledim bu gece

Karanlık denizin karanlık dalgalarının içinde

Çırpındım durdum delicesine

			Özcan Nevres

7 Haziran 2002', 'İçli bir şarkının nağmeleri geliyor uzaktan Seni alıp getiriyor bana dalga dalga Terk edip gittiğinden beri  Hiç bitmedi bu kara sevda Bak y...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sarkilardaki-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinde', 'yureginde-sair-mimra-w31j4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmurun yeni ıslattığı taze toprağın kokusunu duyduğunda aklına ben 

gelmek isterim.Ya da gözlerin denizin maviliğine daldığında... uzakta, ufuk 

çizgisinde sadece dumanı görünen o geminin içinde benim olduğumu düşünmeni 

isterim. 

Küçük bir meyhanede, rakıya balığını meze yapıp içerken ve birbiri ardına 

özlem şarkılarını dinlerken yanında ben olmak isterim.Çakır keyif olup, 

masadan kalktığında, sokakta hafif hafif sallanarak yürürken de... 

    Beni hatırlamak istersen, her yeni doğan günle birlikte çıkarım karşına 

, güneş olur ışığımla aydınlatırım seni.Buram buram bir  kahve kokusu 

olurum. 

Sokakta oynayan çocukların sesinde, işe gitme telaşına düşmüş insanların 

gözünde, yere düşmüş yaprakların çıtırtısında bulursun beni. 

    İstersen, duyduğun her ses beni hatırlatacaktır sana. Bazen bir kuş 

olup 

öterim pencerende. Bazen bir seyyar satıcı olup kapında bağırırım.Bazen bir 

tren gibi tıkırtılarla geçerim önünden.Sözlerini ezbere ve söylemekten asla 

bıkmadığın şarkı olurum. Sen o şarkıyı değil beni söylersin aslında. 

Beni görmek istersen hep karşında olurum. Gökyüzündeki beyaz bulutların 

arasındayım ben. Başını yukarı kaldırman yeterli beni görebilmek için. 

Yolda rastladığın herkes benimdir aslında. Dostlarına selam verirken o 

selamı ben alırım. Komşunun hatırını sorarken aslında bana''Nasılsın? '' 

demişsindir. 

Benimle çıkarsın yola her sabah, akşam eve benimle dönersin. Gittiğin her 

yere gelirim seninle.Sen yorulduğunda yorulurum ben de. Sen oturduğunda 

oturur, kalktığında kalkarım. Eğer istersen  bütün gece başucunda saçını 

okşarım sen uyurken. Yüzünde gülümsemeyle uykuya dalışını izlerim. 

Bana dokunmak istersen bir çiçeğin yaprakları olurum ben. Yeşilin, 

kırmızının, sarının mavinin en canlısındayım. Elini uzattığın her yerdeyim. 

Dokunmak istersen bana kendine dokun. Dudaklarındaki ateşim, tenindeki 

sıcaklık... 

Vücudunu ürperten rüzgarım ben. 

Hiç gitmedim ben. Oradayım, beni görmek, bana dokunmak, beni hatırlamak 

istediğin yerde. 

Yüreğinde...', 'Yağmurun yeni ıslattığı taze toprağın kokusunu duyduğunda aklına ben  gelmek isterim.Ya da gözlerin denizin maviliğine daldığında... uzakta,...', ARRAY['Türk Edebiyatı','Şiir','Şair Mimra']::text[], 8.5, '{"poet":"Şair Mimra","poet_slug":"sair-mimra","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yureginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizilik', 'sensizilik-umit-berk-xx03l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seviyorum işte

bilemeyeceğin kadar

herşeyi silip

sana gelecek kadar

sensizliği yaşamak 

güneşin hiç açmadığı

gecelerin hiç bitmediği

günleri yaşamak gibiydi

Duygularım o kadar yoğunki

sürekli seni seviyorum 

diye haykırmak istiyorum

Haykırıyorum işte ''Seni Seviyorummmm''

Ayrılıklar olmasa 

değerler anlaşılmazmış

yeter artık 

ben senin değerini çoktan anladım

O güzel dudaklarımı

yumuşacık ellerini

güzel yüreğini 

çok ama çok özlüyorum

Duygularım o kadar yoğunki

sürekli seni seviyorum 

diye haykırmak istiyorum

Haykırıyorum işte ''Seni Seviyorummmm''

Sen benim ilk ve tek aşkımsın

Seninle 1 an yeter bana

mutlu olmam için

Beni sensiz bırakma ne olur

Seni sitiyorum

yeter artık çektiklerimiz

atyık mutlu olmalıyız

hadi gel ne olur

Duygularım o kadar yoğunki

sürekli seni seviyorum 

diye haykırmak istiyorum

Haykırıyorum işte ''Seni Seviyorummmm''', 'Seviyorum işte bilemeyeceğin kadar herşeyi silip sana gelecek kadar sensizliği yaşamak  güneşin hiç açmadığı gecelerin hiç bitmediği günleri...', ARRAY['Türk Edebiyatı','Şiir','Ümit Berk']::text[], 8.5, '{"poet":"Ümit Berk","poet_slug":"umit-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sensizilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Bahar Her Mevsim', 'gozlerin-bahar-her-mevsim-bulent-ozcan-8tuh8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiirin yüreğine giden yol, 

Senin gözlerinden geçer...

Eğilir gökte yıldızlar, 

Serin ışığından içer...

Bir düş ülkesi gözlerin, 

Kirpiğinde kuşlar uçar...

Gözlerin bahar her mevsim, 

Güler güller hazla açar...

7 Mayıs 2002, 

Enfield Island Village, Londra', 'Şiirin yüreğine giden yol,  Senin gözlerinden geçer... Eğilir gökte yıldızlar,  Serin ışığından içer... Bir düş ülkesi gözlerin,  Kirpiğinde...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerin-bahar-her-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Böyle Laz Hüseyin', 'i-ste-boyle-laz-huseyin-yavuz-sevinc-2ar3c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte böyle laz Hüseyin

Tanımıyorum seni, 

Benzer kadınları sevdik sadece, 

İki iyi arkadaştılar.

Ve ''seçilen'' değil ''seçen'' olmayı seviyorlardı

Bizi değil..

Narindi benimki, seninkini görmedim, 

Kanardı avuçlarım okşayınca, 

Zalimdi, sivriydi dili

Bilirdim dönünce sırtımı bitecek işim; güvenmezdim.

Kendiside söylerdi

''Benden yana değilmiş tercihi''..

Ama yinede çok sevdim

Elimden başkası gelmezdi..

Bilmem sevdinmi sende benim kadar? 

Vefasız sözlerle ezildimi yüreğin? 

Mutlu oldunmu çocuklar gibi tuttuğunda elini..

Anlatsana laz Hüseyin sende ben gibi, 

Ümitle beklermiydin gecelerce günleri? 

Sen kazığı yedin, ben yemek üzereyim..

Aynı kaderi paylaşıyoruz bence, 

''Sevmek''boş laf, ''Vefa'' bir semt..ne garip

Nasıl kurtulmalıyız sence?', 'İşte böyle laz Hüseyin Tanımıyorum seni,  Benzer kadınları sevdik sadece,  İki iyi arkadaştılar. Ve ''seçilen'' değil ''seçen'' olmayı seviyorla...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sevinç']::text[], 8.5, '{"poet":"Yavuz Sevinç","poet_slug":"yavuz-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iste-boyle-laz-huseyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün Yüküsün', 'gonlumun-yukusun-muammer-erkul-j0k5z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlümün yüküsün! ..

Sen ''gönlümün'' yüküsün, omzumun değil! ..

Sen canıma yarasın tenime değil! ..

.....

Yürekte taşınan sırta ağır gelir mi? ..

§

Sen; çeşmibülbül duruşlum, ışık yüzlüm... Sen; nefesimin rüzgarı... Sen; akarsuyum, durugölüm! .. Sen; 

Ceylan kaçışlım...

§

Harman sıcaklarımda, terlemiş bir cam bardak gibi gülsene bana...

Saklandığın fidanların ardından çıkıp, yine gelsene bana...

Ve yapışıp en susuz yerime, susuzluğunu kandırsana; zaten kandırılmayı umduğun, sanki hayalî bir çeşme başında! ..

.....

Avuçlarıma konsana yine, ürkütmekten ürktüğüm bir mavi kuş gibi...

Derin bir soluk alsana sonra; kaşlarının ve kirpiklerinin üstünde dolaşırken parmağım...

§

Kelebeğim; 

Sarsana kanatlarının hepsini üstümüze! 

Veya, ikisini ödünç verip kanatlarından; uçursana beni de peşin sıra, gözlerinin derinlerinde! .. 

§

Sen gönlümün yüküsün, sırtımın değil...

Yani, tenimde görünmeyen bir yarasın; 

İçimde büyüyen! ..

.....

Yani bir ''bülbül gözü'' gibi güzel, ama bir kristal gibi kesici; 

Bakışlarımdan aldığın her ışığı binbir renge çeviriyorsun sanki bir renk skalası gibi... Sonra da incecik ve uzuun ipek iplikleri gibi başında savuruyorsun ''saçlarım'' diye! ..

Yani sana değen her ışık, bin renge dönüp yansıyor bana! ..

.....

Yani, içimde savruluyorsun.

Ve savruldukça saçların, içimde rengârenk kanıyor; canımın kesikleri! ..

§

Sırtımın değil; canımın yüküsün benim...

Motorumsun; içimdeki sesini ninni gibi dinlediğim...

Veya çalmanı beklerken, tik-taklarınla hayallere daldığım, saatimsin! ..

.....

Vaktimiz, ne zaman gelecek? ..

...........

(Çeşm-i bülbül)  çeşmibülbül; ''bülbül gözü'' demektir, ve ''kristal'' kelimesinin bir önceki adıdır...

muammer erkul

08.06.2002

cumartesi', 'Gönlümün yüküsün! .. Sen ''gönlümün'' yüküsün, omzumun değil! .. Sen canıma yarasın tenime değil! .. ..... Yürekte taşınan sırta ağır gelir mi...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erkul']::text[], 8.5, '{"poet":"Muammer Erkul","poet_slug":"muammer-erkul","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gonlumun-yukusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-murvet-arslan-8mrol', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Giden gitmiştir kalan kalmayı tercih etmiştir.

Giden nezaman karar vermiştir? 

Kalan neden engellememiştir? 

Nezaman bitmiştir paylaşımlar? 

Beraberlik bile yanlızlık olmuştur nezaman? 

Neden solmuştur vazodaki güller? 

Kalpler birbirine küsmüş, 

Eller tutmuyormuş artık diğerini, 

Yüzlerdeki tebbessüm gözlerdeki yaş olmuş.

Ayrılık dökülüyor dillerden.

Eşlik ediyor yağmur içlerinde çakan şimşeklere.

Giden alıp anılarını koyulur yola.

Kalandır aslında bitiren, 

Buyüzden yanlız kalmıştır zaten...', 'Giden gitmiştir kalan kalmayı tercih etmiştir. Giden nezaman karar vermiştir?  Kalan neden engellememiştir?  Nezaman bitmiştir paylaşımlar? ...', ARRAY['Türk Edebiyatı','Şiir','Mürvet Arslan']::text[], 8.5, '{"poet":"Mürvet Arslan","poet_slug":"murvet-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrilik-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut...', 'bir-umut-aysun-elagoz-kutsj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir umut, bir umutsuzluk

Diye atıyor yüreğim.

Gelip giderken yürek dalgalarım.

Oysa ne umut, ne umutsuzluk

Yaşadıklarım...', 'Bir umut, bir umutsuzluk Diye atıyor yüreğim. Gelip giderken yürek dalgalarım. Oysa ne umut, ne umutsuzluk Yaşadıklarım......', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-umut-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'mahser', 'mahser-sair-mimra-sa7hm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herkezin senden kaçtığı gün

Gözlerim seni arıyordu hasretle

Acısını bastırmak için dünyanın bir nebze

Arıyordum seni kürsi denen o sonsuzluğun içinde

Sen kürsi''de çöle atılmış bir katre gül gibiydin

Bense simsiyah, küçük bir akrep

Aradım seni aşkın olduğu yerlerde

Umutsuz bir şekilde yüreğime ektiğim çiçekle

Bir baz kuşu çıkageldi gayb''dan

Nerdir derdin dedi? Anlattım...

Mahkemeyi kübr''a git dedi

Her fani geçecektir oradan

Vardığımda oradaydın

Hesap veriyordun divana

Bir umutsuzluk çökmüştü üzerine

Gözlerinden süzülen yaşlarla

Götüreceklerdi seni

Cehenneme, o dipsiz kuyuya

Atacaklardı seni, bensiz

Olamazdı..! 

İsyan ettim o an Hak''ka 

Hakmıdır ya Rab, verdiğin ceza bu kula

Yakılır mı bu gözler 

Bir günah uğruna

Haktır dersen ya Rab

Alırım Şeytanın ordusunu ardıma

Yürürüm meleklerinin üzerine

Yaratırım kıyameti, mahşerin içinde

Diş bilerim Azraile

Yıkarım sıratı, dağıtırım divanı

O''nun uğruna

O gözlerin uğruna

Kezzap dökerim 

Ona çirkin diyen Hurilerin yüzüne

Gözlerini deşerim

Ona göz koyan gilmanların hepsinin

İzin ver ya Rab

Binsin burağs, süzülsün cennetine

Azabını ben çekeyim

Yeterki dokunmasınlar o mahsun güzele

At beni cehennemine 

Ateş olup yanayım

İçimdeki yangını

Cehenneminle söndüreyim

İzin ver ya Rab

Onu son kez göreyim

Beni cehenneme süren gözleri

İzin ver son kez göreyim

Dersen ki değer mi bu gözler uğruna

Yıkarım cehennemini, haykırırım sana

bin kezde ölsem dirilsem

Yine de değer ya Rab! 

İnancım sana sonsuz, aşkımsa O''na..!', 'Herkezin senden kaçtığı gün Gözlerim seni arıyordu hasretle Acısını bastırmak için dünyanın bir nebze Arıyordum seni kürsi denen o sonsuzluğ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mimra']::text[], 8.5, '{"poet":"Şair Mimra","poet_slug":"sair-mimra","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/mahser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen Ağlayasım Gelir', 'bazen-aglayasim-gelir-mahmut-sami-gurpinar-5i0q5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen ağlayasım gelir, gece uyandığım zaman

Kimsesiz çocuk gibiyim işte o an

Sanki dünyada değilim başka bir alemde

Sensiz içimde yine bir figan

Evet yine bazen ağlayasım gelir

Bu acı dolu akşamda

O kendini iyi bilir

Dünyamı yıktı bir bakışta', 'Bazen ağlayasım gelir, gece uyandığım zaman Kimsesiz çocuk gibiyim işte o an Sanki dünyada değilim başka bir alemde Sensiz içimde yine bir f...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Sami Gürpınar']::text[], 8.5, '{"poet":"Mahmut Sami Gürpınar","poet_slug":"mahmut-sami-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bazen-aglayasim-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklar ve Sen', 'sokaklar-ve-sen-mahmut-sami-gurpinar-nfcwt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koşasım gelir bu yağmurlu akşamda

Gecenin soğuk karanlığında

Kaybolmak isterim o karanlıkta

Ve ömür boyu sevda sokağında

Birşeyler kopar içimden sanki

Senin gittiğin anda

Aşk otobüsü geçer kalbimin, berisinden sanki

Hiç durmadan gittiği zamanda

Sokaklar sessiz, durak boş artık

Çünkü sen yoksun burada

Dizlerim belime kadar balçık

Senin olmadığın zamanda', 'Koşasım gelir bu yağmurlu akşamda Gecenin soğuk karanlığında Kaybolmak isterim o karanlıkta Ve ömür boyu sevda sokağında Birşeyler kopar içi...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Sami Gürpınar']::text[], 8.5, '{"poet":"Mahmut Sami Gürpınar","poet_slug":"mahmut-sami-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sokaklar-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağrımda Bir Ateş', 'bagrimda-bir-ates-orhan-gencebay-cygil', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bağrımda bir ateş var ne bileceksin

Ölsemde ne duyacak ne göreceksin

Hep seninle yaşadı öldü deseler

Aşkından öldüğümü bilmeyeceksin

Belki biraz üzülüp kim diyeceksin

Sevmek öyle güçlü ki benim gücüm yetmiyor

Gönlüm sanki delirmiş ihtirası bitmiyor

Sev diyemem ki gel diyemem ki

Elim kolum bağlanmış çöz diyemem ki

Yıllardır yaşadım sen diye diye

İstesen de bu aşkı öldüremem ki', 'Bağrımda bir ateş var ne bileceksin Ölsemde ne duyacak ne göreceksin Hep seninle yaşadı öldü deseler Aşkından öldüğümü bilmeyeceksin Belki b...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bagrimda-bir-ates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buyudum', 'buyudum-huseyin-cayikli-13077', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaktigim sigara gibi yaniyor vucudun.su andan elimde ve ben dumanini izlerken hayatimizin film seridi gibi gectigini goruyorum.inanamiyorum ne aptalca yerlerde hata yapmisim ne kadar sacmalamisim ne kadar az yol almisim.Ben hala annesinin elinden tutmak isteyen cocukmusum da yillar acimasiz davranmis beni buyutmus.oysa biz annemle izmitte fethiye caddesinde gezerken elimde ki dondurmayi dusurdugumde birisinin bana tekrar o dondurmadan alacagini bilerek gonul rahatligiyla yiyebiliyordum.cunku cocuktum.buyudum yillar acimasiz zamandan bizi gecirdi elimizde ki insanlari kacirdigimizda bir daha donemeyeceklerini anladim.buyumustum annemi dusunuyorumda...fedakarliklarin ve benim aptalca yaptigim yalnisliklarim ama aramizda ki o bag o kopmayan o simsicacik yakinlik.Ben buyudugumu asla kabul etmedim  cunku buyudugunde kaybediyorsun.Aslinda dogum gunlerimden nefret ederim yine yaslandik dedigim olmamistir ama icimde bir gun kirkli yillari kutlayacaksin...belkide ellileri...altmislari her gun olume biraz daha yaklasmak ve yaninda kimse olmamak bu aci veriyor.Hayatimda ki her gun beni terkeden kadina benziyor bir dahada geri donmuyor...Buyudugumu yalniz kaldigimda anladim sevdigim kadinlarin birisi terk edince anneme gidip agladigim gun annemin benle dertlesmesiyle buyudugumu hissettim.Anladim ki Nufus cuzdanim yalan soylemiyor...Polisler artik sen cocuksun demiyor.Buyudum arka sokaklara yikilmis enkazlari birakirken babamin arkamdan kostugunu gordum...Sokak afisleri anlatiyordu halimi.Bir tiyatro oyunu gibiydi hayat bende onun bas rolunde ki sahis...Oyunun bir sorunu vardi perde kapanmiyordu.o zaman anladim her dogum gunum perdeyi yavas yavas kapattigina.Bu oyunun sonu olmadigini ve icinde Istanbul denen bir sehirin olmadigina inandiriyorum.Ben Bursayi da seviyordum.Tophanesini de unutmazdim altiparmagin sinemalarini ve nalbantoglunun soguk karli bir gunde kestanesini unutamam.Birde o gunden...bir gun evvel alti tane alinmis bir gul.Bursayi da unutamazdim, Istanbulu da...mesala izmiti unuttum sevdiklerimin olmesiyle gitsemde koymuyor geceleri susayarak uyanmiyorum o sehirde...gitmek bile gelmiyor zaten gitmiyorum.Bir gun korkuyorum ki kortuklarim basima gelmistir Bursa dan kopucagim diye nitekim koptum sevdigim kadinin gitmesiyle oraya da veda ettim.Kala kala yasadigim yer kibris kaldi.Hayatimin en guzel oyununu oynuyorum.Bu oyunun adini duymadiysaniz.size soyluyorum adi yalnizlik...', 'yaktigim sigara gibi yaniyor vucudun.su andan elimde ve ben dumanini izlerken hayatimizin film seridi gibi gectigini goruyorum.inanamiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/buyudum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gayrısına Mecalsiz', 'gayrisina-mecalsiz-bahri-guler-gylur', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gayrısına Mecalsiz

vedaların artık, bittiği zaman, 

sevdiğimiz kadar sadık sabaha, 

çocuklar, çimenler, su ve uçurtma, 

umrumuzda pinhan, ne şan, ne paha.

karanlık evimde, serin ziyafet, 

gözlerin bahçelik, sır ellerinde, 

kuşluk üstü vefa, ikbal, kıyamet, 

sırrını taşırsın, göz sellerinde.

şefkatin mi kalmıs, aşkın mı sönmüş, 

kaldığımız handa, sabır, payanda, 

ünlediler heyhat, maziler ölmüş, 

hayaller asmışım, affet rüyanda.

bırak saklı kalsın, düsüm, aşımız, 

yatayım kuştüyü, konağımızda, 

kaldır beni, taşa, çarpsın başımız, 

karalık kalmadı, yanağımızda.

diyeyim ki, sebep, de ki bana sus, 

kalmasın dağlarda, ne kar ne de nam, 

sevdiğim gözlerin, bulutlar ve pus, 

silelim defterden, şevk nedir ne gam.

bir zamanda bozkır dedim kapılar, 

kaynağın basinda, şavkın al dedi, 

ucubeydi hanlar, sanki beni sar, 

diyen kollarındi, gayri ''gül'' dedi.

                            Bahri Güler', 'Gayrısına Mecalsiz vedaların artık, bittiği zaman,  sevdiğimiz kadar sadık sabaha,  çocuklar, çimenler, su ve uçurtma,  umrumuzda pinhan, ne...', ARRAY['Türk Edebiyatı','Şiir','Bahri Güler']::text[], 8.5, '{"poet":"Bahri Güler","poet_slug":"bahri-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gayrisina-mecalsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin''den', 'derin-den-bahri-guler-h8xln', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşamüstü, perdelerde, yaklaşıyor karanlık, 

Başı-gözü kırıldıkça, pekleşiyor yarenlik...

Bozkır tenhalarında, zor sabahlara azık, yolda kalmış yolcunun rüyası, 

Elde kalan öksüzlük uğultularının acısı adedince keyfediş, gel-gitlerin yamacı, 

Mey ve cümbüş, raks ve af maskelerinin adedi, 

                      Yarım nefes sultanım, sana hafif yollu geçeriz bu kez, 

                                    Aç omuzcağızının derin damarlarını

                                                duvara dayanmış hünsa, 

                                                          kokusuz, 

                                                               saf..

Sonra yemyeşil bir yosun deresinin iştihasıyla pür-dikkat, 

Hırsız korkusu, hain uğultusu, masum nefesiyle gür ve soluk, 

Çocuklar anne babasız kalmakta akşamın şu incecik vaktinde, 

                      gün akşama akarken derin ve sabırsız

                           omuzdan gelen kanım, ılık ılık,         

                                    dur, durabilirsen, 

                                         fesat, al, 

                                              sat...

Efelik de kalmamış buraların sevgi rakkasalerinde, 

Çanağımızdaki beyaz renkli aşımızın tadı belirsiz, nefessiz kalmış sütümüz, 

Sözümüzde durmadık, şimdi savaş kıtlığında koyun koyuna yatan biz, 

                                                                                           Bi-çare akşamlarda, 

Kumar kadar karışık  ve dönüşsüz bir ihtimalin karanlık çözümü, akşamlar, 

Hani tütün de bitmiş, hani makamlar yan yatmıs gemilere benzer, kaptan kadar 

                                                                          korkularımızla

ey yar-ı zalim, 

artık bedelini ödedik diye kalkıp giderken meydanlıklardan arka sokaklara

hançerin keskinliği ve zehrin sıcaklığı kana karışır karışmaz dönemedik boğuk, 

sesler birbirine karışınca sirenler, morglar, bayram sabahları ve hekimde hasta, 

                       

                                          aldandık

artık içinde kalamayacağımız sökülen çadırların sırttaki yara kadar samimi hevesinde, 

düştük yollara, kervanlari kıran tül renginin peşinde ve dedikoduyla vurgun sevdalık işinde, 

kimseye de verilecek hesabımız yok saba yelinden gayri, haydi gayri durmasın işcemiz, nazımız, 

                                             söndük....', 'Akşamüstü, perdelerde, yaklaşıyor karanlık,  Başı-gözü kırıldıkça, pekleşiyor yarenlik... Bozkır tenhalarında, zor sabahlara azık, yolda kal...', ARRAY['Türk Edebiyatı','Şiir','Bahri Güler']::text[], 8.5, '{"poet":"Bahri Güler","poet_slug":"bahri-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/derin-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüllenin Şiiri', 'hullenin-siiri-bahri-guler-arpvl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yürekleriyle iniverdiler gökten sevdayla yiğitler, 

Ateşti naralar, korkular dağlara kaçıştı, 

Sebepleriyle,  devirdiler hakkı yazardı divitler, 

Güneşti çerağlar, merdane, bendine bakıştı.

Beyazlar içinde indi meydana kumandan, 

Almıştı tardını, kaçmıstı temkinle zamandan, 

Ya cinnetti bu, ya sır ya da imandan, 

Vururdu leventler, sırrı derd-i sebebin biniyle.

Askeri bakardi, andı, mahşerin resmiydi, 

Şarkını garbını, sundu, devlerin hasmıydı, 

Bilirlerdi sarasını, yaydı, okların cismiydi

Coşardı yigitler, sırrı merd-i alemin şeniyle.

Namları yürüdü, dündü, toyların dengiydi, 

Anladı düşmanı, aydı, hilkatin rengiydi, 

Durmuştu zamanı, oydu, saylerin dengiydi, 

Yumdular gözlerin, sırr-ı herk-i hüllenin yeniyle..

                                                                             

taleplerin boşluk gibi sardığı

        yanında, yamacında, korkusuz, 

anlat, diyorsun bana nağmeleri..

         sebepsiz, sultasız, damarımda

varken bana atadan, asıldan

         mirasım, oltaları saldım şimdi, 

çalar ziller, binasında huzur

         mabedinin, binasıdır kıyas, 

neyi görmüş gözlerin, aşkın kadar

         kör olsun zemheri kadıları, 

kadın olmak kadar sebepsiz

         ve bulut kadar belirsiz

sağır duyguların akşamında

         yargılarsın aşkı, elinde kadeh, 

dalgalara bakarak daldığın öfke

         düşlerin yanıltır bir gun, 

belki, öylece, deyip te sunduğum

         an cismimi…

             _hayır_ 

dersin, alamam akşam buğusunu, 

         imbiklerde kanayarak bulduğum

türküler boğulur, yüksek hislerin

         yorulur belki bir güz sonrasi, 

plansız ve mekansız hislerin, 

        düstüğü yerde vurulan tekmelerin

neşesi, ve bencilligi tadinda, sus, 

           _sen de vur_ 

oysa neye bina etmişim ucuz

        kokulu dağ kevenlerinin sesini, 

üç yaz önce gömdüğün adamı, 

        rüzgarların işvesi, sırrımın tadıyla

          _al _

bir zaman paylaşamadığım aşkının, 

        taze isyanıyla tanık olduğumuz

adalet ve mehmur gözlerimizle, dar, 

        beni kaybeder cellatlar

        _manidar –

bir zaman atların sesiyle ve kuş

        nefesleriyle daldığım masmavi

göllerden selam, uzaklık, makinaların

        gürültüsüyle yere yıkılan kavağın

pamukları adedince uzağa üfledi 

       _beni _

ihtimallerin yonttuğu aşklar ve 

      yuvalar, ağaç kurtlarının midesinde

sıcak ve paslı akşamlarda 

      _kaniyor _

söylemese de derdini düşlerim

                                 bilmedin, 

       od’um yaniyor...', 'Yürekleriyle iniverdiler gökten sevdayla yiğitler,  Ateşti naralar, korkular dağlara kaçıştı,  Sebepleriyle,  devirdiler hakkı yazardı divit...', ARRAY['Türk Edebiyatı','Şiir','Bahri Güler']::text[], 8.5, '{"poet":"Bahri Güler","poet_slug":"bahri-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/hullenin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla', 'damla-kagan-altindal-qn19r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alev alev yanan yüreğim sönmez suyla

Akıl kalmamış şu başımı ez taşla

Bir güzel söz söyle de bağrımı ısla

Gönlümün sultanı sensin Damla...

Senin için dinlemem emir, ferman

Benim yarama sevgin tek derman

İki şeye yanarım; biri sen, diğeri vatan

Benim çarem sensin Damla...

İstesen de vazgeçmem ben senden

Yanacağımı bilsem de ebediyyen

Allah''ın emri, peygamberin kabliylen

Bana helal olmanı isterim Damla...', 'Alev alev yanan yüreğim sönmez suyla Akıl kalmamış şu başımı ez taşla Bir güzel söz söyle de bağrımı ısla Gönlümün sultanı sensin Damla... S...', ARRAY['Türk Edebiyatı','Şiir','Kağan Altındal']::text[], 8.5, '{"poet":"Kağan Altındal","poet_slug":"kagan-altindal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/damla-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışmıyor', 'yakismiyor-kagan-altindal-gc1uh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aramızdan çekilsin huzuru bozan

Kötüyü öven, yoksula kızan

Haksızlığa ferman yazan

Yanımızdan gitsin kuyumuzu kazan.

Beraber iş yapılmaz bir fosille, imansızla

Konuşup anlaşılmaz bir hainle, vicdansızla

İktidara çıkılır mı ulan bir şerefsizle, kansızla

Oyun oynadınız üç hilalle, bozkurtla, oyumuzla.', 'Aramızdan çekilsin huzuru bozan Kötüyü öven, yoksula kızan Haksızlığa ferman yazan Yanımızdan gitsin kuyumuzu kazan. Beraber iş yapılmaz bir...', ARRAY['Türk Edebiyatı','Şiir','Kağan Altındal']::text[], 8.5, '{"poet":"Kağan Altındal","poet_slug":"kagan-altindal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yakismiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liyakat', 'liyakat-bunyamin-uyanik-6k1ne', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanlar tanıdım, yıldızlar gibiydiler

Hepsi parlıyordu, hepsi gökteydi

Ama ben, seni güneşim seçtim

Bir güneş için bin yıldızdan vazgeçtim...

                                         02-12-1997', 'İnsanlar tanıdım, yıldızlar gibiydiler Hepsi parlıyordu, hepsi gökteydi Ama ben, seni güneşim seçtim Bir güneş için bin yıldızdan vazgeçtim....', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Uyanık']::text[], 8.5, '{"poet":"Bünyamin Uyanık","poet_slug":"bunyamin-uyanik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/liyakat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağ Yanım', 'sag-yanim-oropa-seni-1k8bg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ya sen gelirsin aklıma

ya da bulunurum ortamında

sağ omzumdan bir ses; 

-Allah sahibine bağışlasın, bize de nasip etsin 

diye söylenir durur.

derken ortaya atılır soldaki ses; 

-ne gönül eğlendirilir bu kızla, 

ah bir ortam olsa da konuşulsa.

gözlerin çıktığında karşıma 

eğilir aniden sağ yanım

nedendir bşilirim elbet

her aklımı aldığında 

sağ yanım, 

daha ağır basar sola inat.

içimi ısıtır bu duygu.

seninle 

ömür boyu...', 'ya sen gelirsin aklıma ya da bulunurum ortamında sağ omzumdan bir ses;  -Allah sahibine bağışlasın, bize de nasip etsin  diye söylenir durur...', ARRAY['Türk Edebiyatı','Şiir','Oropa Seni']::text[], 8.5, '{"poet":"Oropa Seni","poet_slug":"oropa-seni","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sag-yanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüllenin Şiiri 2', 'hullenin-siiri-2-bahri-guler-dtisw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kabahatlerin kahir nehirlerde sabırla sükuna soyunduğu, acısını kaybeden bakışının keçi yollarında ikindi renkleriyle kaymaya başladığı, başları eğik olacak beyaz ayaklarının, 

sürgünlere koşup, keskin ithamların işvesiyle aydınlattığın kilerimizde, az gidilip uz bulunan sarı zamanlara gölgelik kabullenişlerinin öfkelerimize ağlayacak, kışlık-dışlık, unların, 

kazıkların ucunda görüverdim kelleni, sabah saltanatıyla sallıyordu kahkülünü rüzgar, bekleseydin, rüyasında, darağıcıydın lağımcının, ellerin tetikte, bi-kararsın, bi-çare, koynunda saklıydı, 

bilmem, çok zamanı kalmamış yagmurun, cemreye, dogrulttun tüfengi, tenin dununda patladı akşam, hatta sanmıştım ki ruhun Balkan''ın çekinik yaylalarında, kanın çekilecek, düşüp, üşüyeceksin, 

sana gelecek sesler saçından, kaşından, bir de ağlayacak harda buharıin, derin bir heves ve dalgın bir nefes gibi sanacak durduramadığın zamanı, yumuşak topraklarda yatacak cenin, 

                                                                                          ___yaşayacaksın ___

anlamların bağlamıyor savaşımı, geçitlerde kaldı gazilerin kolu, kanadı

buymuş sırrın, merdin günaşımı, soneler de doldu, sızıların seli, inadı

sabahların aşermiyor gülüşümü, tanelerde yoldu, dizilerin, yalı, iradı….

eksik de kalıverecek, neydi ki geceye ettiğin yemin, bağdad’ın saban nasırıyla oğuşan ellerine baktın mı gururunla, kaşlar, 

kalktın mı cevapsız kalan naaşın başından, selamsız, kutsuz, kusursuz, ve haydi oturalım hesabın değirmenine, 

kubbeyi ciddeler savunsun, azarsız, düstüm derdi derunuma, şimdi kendimce, icarsız, sultasız, zamansız, ve teninden gayri mezarsız…

azığımı, saltanatımı, akçemi, 

el yordamı düşlerimi bile çalmış, 

mavilik meshedersen özgürlüğün 

                                                  kanadını, 

	sabah hanedanının öksüz

	güreşlerine düşüvermiş  iffetinin gölgesi

	sesler, hapsedivermiş yorgunluğun abus 

çehresini, imtina ile sübut bulmus

beyaz çarşafların kirli ışığı...

mahpusluğu, kaderimi, isyanımı, 

kalemimi bile çalmıs sırma saçlı engerek, 

olsun, nefesim yeter korkmadan aşkın 

                                      güzelliğinden, 

pusular eylenmiş ve tuzaklarda kalmış

billur gözyaşı, nazlı zamanlarımla bozmuş büyüsünü 

papatya, 

kire attığım iftiranın sabrınaymış feraset, 

bakışında celseler yakmışım  ey Leyla, 

senedine gül goncalar, bezmişim..

dokunurken yapraklarına devranın, 

                                      aşk okumuş, şek dizmişim, 

mey imiş bastığın, kaçtığın, sen mişim, izmişim...', 'kabahatlerin kahir nehirlerde sabırla sükuna soyunduğu, acısını kaybeden bakışının keçi yollarında ikindi renkleriyle kaymaya başladığı, baş...', ARRAY['Türk Edebiyatı','Şiir','Bahri Güler']::text[], 8.5, '{"poet":"Bahri Güler","poet_slug":"bahri-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hullenin-siiri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimdensetron', 'kimdensetron-bunyamin-uyanik-xx14x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen benim kardiak arrestimsin ve de çaresi

Dijitaller anlamaz halimden 

Atropinler yaban kalır.

Evet, tam şuramda, sol yanımda

Künt bir ağrısın ama lokalize değil...

Hayır doktor bey, çöktükçe değil, 

İşte böyle çektikçe ağrıyor bu imansız iskemi.

Seni bana intravenöz, oral versinler

Sağ gluteal bölgemden intra mural versinler

Yeter ki versinler aldırmadan kontrendikasyonlarına

Sabah, öğle, akşam her özlemden sonra...

Aldırmam bağımlılığına, emetikliğine

Yokluğunun anksiyetesinden iyidir varlığının şuur bozukluğu.

Tek derdim; reçetesiz vermiyor baban

Ve bir o kadar da zor bir ömür boyu

Seni oda sıcaklığında saklamam...

Almaya gücüm yetmez kullanmaya kıyamam

Namerde spesifik, bana yan tesirlisin.

Gavur malı değilmisin ölürümde kullanmam...

                                           15-12-1999', 'Sen benim kardiak arrestimsin ve de çaresi Dijitaller anlamaz halimden  Atropinler yaban kalır. Evet, tam şuramda, sol yanımda Künt bir ağrı...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Uyanık']::text[], 8.5, '{"poet":"Bünyamin Uyanık","poet_slug":"bunyamin-uyanik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kimdensetron-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-oropa-seni-rownh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yağmur yağdığında ağlarım yalnızca

yani yalnızca sana

...anlasana

tam beş bahar geçti 

dört de yaz ardından.

ardından ağlayan beş kış 

savrulup, solup giden beş güz.

ve bir parça da gençliğim.

yani anlayacağın 

büsbütün elli yedi ay bıraktım 

gözlerimin gözlerine 

en son değdiği yere.

yağmur ol gel.

afet ol gel.

ecelim  ol gel.

hasretin değil sen gel...', 'yağmur yağdığında ağlarım yalnızca yani yalnızca sana ...anlasana tam beş bahar geçti  dört de yaz ardından. ardından ağlayan beş kış  savru...', ARRAY['Türk Edebiyatı','Şiir','Oropa Seni']::text[], 8.5, '{"poet":"Oropa Seni","poet_slug":"oropa-seni","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-sair-mimra-m3out', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çünkü aylardan Eylül... 

     Bir yol ayrımına gelir hayatlar... Herkesin kendine yeni yollar aramaya başladığı andan beri, her adım geçmişe doğru da atılır, bir kez daha. Kendimizi yeniden yazmaya, yalnızlığa alışmaya doğru çıkılan bir yolculuktur bu. Belki de bu yüzden “ayrılık ayrıldığımız yerde değil” gideceğimiz yerde karşılar bizi. 

   Rakı masaları kurulacak sonra o kumsala, kadehler başa kalkacak, çok uzaklardan bir kahkaha duyulacak, sahibi bulunmayacak... Sular çekilecek ayaklarımızın altından, kurak bir iklime çıkılacak... Akıl kendini savunacak, yazdan kalan her şeyin hesabını verebilecek; hepsini mi? Belki hayır! Ama ona da akıllıca bir çözüm bulacak, ama Aşk akla hiçbir mevsim uğramayacak... 

    Çocuklar gibi gülücükler dağıttığımız o sular bizi boğacak, ay ışığı göz yaşlarımıza vuracak, tenin tuzu kuruyacak hatırlandıkça o anlar, nefesler tutulacak...

    Sanki tüm şiirler Eylül’de çıkıyor gibi hissettiğimden mi ne, Eylül’ü anlatırken bile dilim dizelere teşne... Oysa ayrılıktı anlatmak istediğim, nedense Eylül geliyor diye. Ayrılıkların da bir mevsimi yok mu gerçekten, hem niye hazan mevsimin de? .. Hani şu dökülen yapraklara özentisinden mi, ama bir  yaprak da tutunduğu dalı bilmez mi? 

    Peki nedir ki ayrılık; hem de Eylül’de? 

    Bir yol ayrımına gelir hayatlar... Herkesin kendine yeni yollar aramaya başladığı andan beri, her adım geçmişe doğru da atılır bir kez daha... Kendimizi yeniden yazmaya, yalnızlığa alışmaya doğru çıkılan bir yolculuktur bu... Belki de bu yüzden “ayrılık ayrıldığımız yerde değil” gideceğimiz yerde karşılar bizi... 

    Takvimlerin ayrılmayı gösterdiği zamanlar ansızın gelmez... Bir gün değil, bir ömürdür ayrılığı besleyen... Yaşadıkça seçtiğimiz yolların başka bir iklime çıktığını gördüğümüzde anlarız, ayrılmakla ayrı olmayı ayırmamız gerektiğini... 

    Her şeyi paylaşmak üzerine verilmiş sözlerden geri dönme değildir ayrılık; kurduğumuz cümlelerin artık ayrı olmasıdır. Ondan, onlardan yada ötekilerden... Evet bir yol ayrımıdır bu, adresini bilmesek de o yolda olmakla oraya doğru gitmeyi karıştırırız birbirine... Çünkü bu yolculuğun 

azığıdır anılarımız, göz yaşlarımız ve yan yana durduğumuz o eski fotoğraflarımız... Ve için için biliriz ki, hiçbir söz teselli etmez bizi bu yolculukta; çünkü ayrılık aşkın kısa kesilmiş bir resim altıdır... 

    İşte Eylül o resmin altında hazırlanır her şeye, siz de bir yaprak gibi beklersiniz başınıza gelecekleri. Sadece ayrılıklara değil her şeye sizin de yüzünüz sararır belki, düşününce en çok hani nerede o heyecanlarınız, birkaç 

aya kalmaz biraz daha örtünürsünüz... Hani nerede çırılçıplak koştuğunuz o eski kumsallarınız! .. 

    Ağaçların altında şimdi nasılda yalnızsınız... Eylül durdurur belki de, hep bütün bir yaz ne de çok konuştunuz, her şeyi istemeye alışıklara hiçbir Eylül yetmez... Evlere, işlere dağılınır, pencereler kapanır, örtüler ağırlaşır, yataklara sığınılır... Eşyalar yerini yadırgar evde, halılar ayaklar altına alınır, koltuk yüzleri yalvarır... Eylül diretir değişimde, 

eskiler atılır... 

    Uzun yollardan dönen eski dostlar hatırlanır, anılar alınır-satılır... En çok anlatılan yollardır, o meşhur geceler kendimize saklanır. Gece oldu mu sesler de değişir evde, çocuklar henüz yatmamıştır, bir anne avaz avaz bağırır, sökükler dikilir, kocalar uğurlanır... Şehrin terk edilmeye müsait ekabir sokaklarında itişmeye başlanır... Eylül’e yetişmek zordur çünkü, ardından gelecek her şeye temkinli olunur... 

    Bedenin yazla görüşü son bulur, Eylül acımasız bir gardiyan gibi “bitti! ” diye kapılara vurur, çeken sizi havalandığınız o ara yazdan, ağaçlar üzerinize kapanır... Çünkü Eylül’dür en ince, en hoyrat, en ağır hesapların 

bilançocu... O’na hep borçlu kalınır... Ve ışıklar hepten sararır... 

    Belki de bu yüzden “ayrılık ayrıldığımız yerde değil” gideceğimiz yerde karşılar bizi...', 'Çünkü aylardan Eylül...       Bir yol ayrımına gelir hayatlar... Herkesin kendine yeni yollar aramaya başladığı andan beri, her adım geçmişe...', ARRAY['Türk Edebiyatı','Şiir','Şair Mimra']::text[], 8.5, '{"poet":"Şair Mimra","poet_slug":"sair-mimra","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eylul-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'None', 'none-sair-mimra-krxs1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu an, o kadar ağırım ki; 

Sanki bir kuşun kanatlarında, 

Rüzgarla irkilen bir tüy gibi... 

Şu an, o kadar yaralıyım ki; 

Sanki oradan oraya çarpan, 

Bir rüzgar gibi... 

Yüksek dağları aşıp, 

Engin vadilerden geçip, 

Pencerenden içeriye girecekmiş gibi... 

Bir özlem... 

Sanki asırlar geçmiş, 

Tam ben sana geleceğim zaman 

Dakikalar yorulmuş, 

Saatler durmuş gibi... 

Tam güneş açacak derken, 

Birden yağmurlar yağdı yüreğime. 

Öyle bir taştılar ki; 

Sanki bir kayık olsam, 

Sana gelecekmişim gibi... 

Rüzgarın sana getirmek istediği 

Bir yaprağım şu an, 

Sararıp solduğu halde, 

Dalından kopamayan. 

Yatağım kabir, 

Yollar sanki sırat köprüsü... 

Korkuyorum her adımımda 

Bir sonraki adımda, 

Ölümle kucaklaşacakmışım gibi... 

Günler asır olsaydı geçerdi şimdiye... 

Bugün 19 Nisan 

Daha 20`sine çook var... 

O kadar çok ki bilemezsin. 

Dört duvar tabut. 

Mezarım olsan, 

Getirseler beni sana... 

Yurdumun ortasında bir yurtta 

Evrenin diğer ucundaki, 

Bir gezegen kadar 

Uzağım yaşamaya... 

Özlemişim yosun kokusunu, 

Daha önce hiç koklamamış gibi... 

Ufukta...En uzakta, 

O yelkenleri yırtık gemi, 

Benim işte... 

Sallanıyorum oradan oraya 

Dalgalar bile sürükleyemiyor beni. 

Demirlemişim buraya kendimi... 

Yüreğim öyle kan ağlıyorki 

Köpekbalıkları çevremde. 

Üzerine arı konan 

Bir bahar çiçeği gibi çaresiz, 

Kimsenin koklamak istemediği... 

Açmadan soldum daha. 

Kıştan sonra hazan gelir mi hiç? 

Nerede bahar, nerede yaz... 

Nerede umutlar? 

Sen nerdesin? 

Neredesin...', 'Şu an, o kadar ağırım ki;  Sanki bir kuşun kanatlarında,  Rüzgarla irkilen bir tüy gibi...  Şu an, o kadar yaralıyım ki;  Sanki oradan oraya...', ARRAY['Türk Edebiyatı','Şiir','Şair Mimra']::text[], 8.5, '{"poet":"Şair Mimra","poet_slug":"sair-mimra","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/none-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-ahmet-muhip-diranas-4ferm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevdiğim güzel vardı, bu evrenden vazgeçti; 

Sevdiğini yitirenin hali nice olur belli.

Fidan boylum, güvercin bakışlım, şimdi n''etmeli? 

Sevip kokamadım, doyamadım; benden vazgeçti.

Benim varımdı o, benim tadım, benim ereğim; 

Direğimdi, kırıldı da çöktüm, bir oldum yerle.', 'Bir sevdiğim güzel vardı, bu evrenden vazgeçti;  Sevdiğini yitirenin hali nice olur belli. Fidan boylum, güvercin bakışlım, şimdi n''etmeli? ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhip Dıranas']::text[], 8.5, '{"poet":"Ahmet Muhip Dıranas","poet_slug":"ahmet-muhip-diranas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/agit-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
