INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dosta Mektuplar 16', 'bir-dosta-mektuplar-16-ozcan-nevres-fbmcn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir Dosta Mektuplar 16

Dost Diktiğim fidanlar ağaç oldu

Dalları yıkılırcasına meyve doldu

Meyveleri toplayıp götürüyorum pazara

Müşteri bol cebim doluyor para

Horoz ölür gözü çöplükte derler ya

Benim de gözüm körpe kadınlara

Yaş yetmiş iş bitmiş derler ama

Yetmişe varmaya üç beş yılım var daha

Geçende bir kadın geldi benim tezgaha

Yaşı kırka varmasına var daha

Sordu çoluk çocuk yok mu

Hep seni tek görüyorum burada

Dedim yapayalnızım bu dünyada

Zor dedi yalnızlık hele bu ilerlemiş yaşta

Takıldım ona çok gencim daha

Saymazsan geceleri yaşım otuzunda

Güldü bir görseydin gülüşünü

İçim cız etti eridim bittim

Ya senin yaş kaç saymazsan geceleri

Dedi yirmiye varmaya epey var daha

Ya sende çoluk çocuk kaç tane

Kaçırdım tireni evlenemedim daha

Ah dedim ah kader utansın

Neden daha önce çıkmadın karşıma

Hayıflanma dedi tren kaçmadı daha

Yaştansa sıkıntın takma sakın kafana

Yaşın ne önemi var gönüller bir olsun

Niyetin ciddiyse evlenirim seninle

Tantanaya gerek yok sade bir nikah yeter

Şaşkınlıktan dilimi yutacaktım

İnanamadım söylediklerine

Dalga geçiyor sandım

Dedi satacak bir şeyin kalmamış topla tezgahı

Sevinçten uçacaktım tez kapattım tezgahı

Bindik benim külüstüre 

Tez ulaştık sahildeki gazinolardan birine

Açtırdık bir yedi yüzlük bolca da meze

Yedik içtik keyfimiz yerinde. 

Akşam oldu hava karardı

İçimi acı bir hüzün sardı

Vedalaşıp ayrılacaktık

Ya bu da ötekiler gibi terk ederse 

Hadi dedi götürsene beni evine

Duyduklarıma inanamadım döndüm serseme

Sordum evime mi dedin anlamadım

Şaşıracak ne var bunda

Evin varken otele gidecek değiliz ya

Bindik benim külüstüre çıktık yola

Bu işin sonu nereye varacak hayır mı ola

On gün oldu sürüyor birlikteliğimiz

Nikahtan yok söz ettiğimiz

Bir hinlik var mı bu işte bilmiyorum

Hoşca kal dost olacakları yine yazarım

       			Özcan Nevres

8 Haziran 2002', 'Bir Dosta Mektuplar 16 Dost Diktiğim fidanlar ağaç oldu Dalları yıkılırcasına meyve doldu Meyveleri toplayıp götürüyorum pazara Müşteri bol ...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/bir-dosta-mektuplar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Bir Oda', 'sessiz-bir-oda-menderes-iskin-zhpup', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sessiz bir oda

Odada bir kaç eşya

Masa, yatak ve bir sürü kağıt

Tavanda asılı bir urgan

ucunda asılı bir adam

Adamın önünde diz çökmüş bir kadın

elinde sıkı sıkıya bir kağıt

Kağıtta iki satır yazı

iki damla da gözyaşı

''Yolcunun dinlenmesidir ölüm, 

her işin sonudur.

Keşke hayat gözlerin kadar güzel olsaydı.''

Sessiz bir odada

Sensizliğin tam ortasında..', 'Sessiz bir oda Odada bir kaç eşya Masa, yatak ve bir sürü kağıt Tavanda asılı bir urgan ucunda asılı bir adam Adamın önünde diz çökmüş bir k...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sessiz-bir-oda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözden Öteye Hiç Geçemedim.', 'sozden-oteye-hic-gecemedim-menderes-iskin-1roqe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sözden öteye hiç geçemedim.

Gidemedim kelimelerin önüsıra

Varamadım gönlüne, ateşimi yakamadım.

Olmadı bitanem, olmadı işte, edemedim



Ne desem bilmem ki sana, ne eylesem

Benim de dili yok kalbimin, 

Ben de lal olmuşam

Bilsen, ne kadar bizarım, keşke bilsen.', 'Sözden öteye hiç geçemedim. Gidemedim kelimelerin önüsıra Varamadım gönlüne, ateşimi yakamadım. Olmadı bitanem, olmadı işte, edemedim Ne des...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sozden-oteye-hic-gecemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birbirine Aşksayan kişiler', 'birbirine-asksayan-kisiler-menderes-iskin-u4mm9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biz ne volkanlar gördük, taşan taşan, bir avuç küle dönen

Ne aşklar, ne sevdalar, ne masallar dinledik

Ne dudaklar tanıdık, ne ağlayanlar gördük 

Nice sözler, nice vaatler, nice yalanlar 

Hepsi de ağızlara meze olmuş

Meleklere yaraşan belki ama gerçekle hiç örtüşmeyen.



Biz ne dereler gördük, taşan taşan, ırmaklara karışan

Ne anlar, ne heyecanlar, ne acılar paylaştık

Ne dilekler tuttuk, ne yeminler ettik

Nice hayaller, nice planlar, nice dualar

Hiç birisi de bizim olamayan

İnsanlara yabancıl belki ama birbirine aşksayan.', 'Biz ne volkanlar gördük, taşan taşan, bir avuç küle dönen Ne aşklar, ne sevdalar, ne masallar dinledik Ne dudaklar tanıdık, ne ağlayanlar gö...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birbirine-asksayan-kisiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk, Kör Karanlık Bir Kuyu Sevgili', 'ask-kor-karanlik-bir-kuyu-sevgili-menderes-iskin-tiq2t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk, kör karanlık bir kuyu sevgili

Karanlığında sadece benim olduğum.

Bu öyle bir karanlık ki, 

gözüm kapatıp uyuyamıyorum.

Çünkü benim karanlığımda sadece sen varsın sevgili

Bir karanlıkta kendimi, 

diğerinde yitik sevdamı arıyorum.

Hayallerimi ise aynı karanlıkta kaybettim, 

hakeza bulamıyorum..



Aşkın öylesine duruyduki sevgili

Kalp atışlarımın attığı noktam, 

nefes almamı sağlayandı.

Sevginin resmettiği sevgili, 

sevginin yöneltildiği sevgiliden farklıydı.

Aşk adresini yitirmiş bir sevgiydi bende

Sevgi ise benim sende fani olduğumdu.

Aşkın sahip olduğum tek şeydi sevgili..

Ama o tekşey.. O birşey, benim herşeyimdi.', 'Aşk, kör karanlık bir kuyu sevgili Karanlığında sadece benim olduğum. Bu öyle bir karanlık ki,  gözüm kapatıp uyuyamıyorum. Çünkü benim kara...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-kor-karanlik-bir-kuyu-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürsem Yüzün Yüzüme', 'sursem-yuzun-yuzume-menderes-iskin-4jdl1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sultanahmet, Eyüpsultan

Beşiktaş, Şirinevler

Semt semt, karış karış 

Gezsek şehr-i İstanbul''u

Yine eskisi gibi..



Bahçelievler''de, Beyazıt''ta

Gece, gündüz fark etmeden

Yolumuzu şaşırsak birdaha

Öylece kala kalsak

Yine eskisi gibi..



Ortaköy''de kumpirle

Haydarpaşa''da oltayla

Tavla elde Yıldız''da

Olsak sarmaş dolaş

Yine eskisi gibi..



Pişti oynayak sizde

Ya bulaşığına, ya yemeğine, 

Bir sen yensen, bir ben yenilsemJ

Oynasak, gülüşsek, coşsak keşke

Yine eskisi gibi..



Tavuk, mantar, sebze alsak

Birlikte yemekler hazırlasak

Bir beden, bir yürek olsak

Mum ışığında başbaşa

Yine eskisi gibi..



Ayın 25’lerini kutlasak

Ben yine sms atsam

Yüzlerce, binlerce sms atsam

Sevgimi anlatsam sana

Yine eskisi gibi..



Doğum günün gelse yine

Tatilya’ya gidebilsek

Masal dinlesek ağaçtan

Fal baktırsak, tünele girsek

Yine eskisi gibi..



İstiklal''de yağmura

Metrolarda ablana

Kapı önünde komşuya

Yakalansak birdaha

Yine eskisi gibi..



Adalar’da Yıldız''da

Çamlıca''da Haliç''te

Çıksak Pierre Lotti''ye

Piknik yapsak, çay içsek

Yine eskisi gibi.. 



Papatya falı baksak

Bir ben baksam 

Bir sen baksan

Seviyor sevmiyor oynasak

Yine eskisi gibi..



Vapurla Adalar’a

Trenle Zeytinburnu''na

Otobüsle Çorlu''ya

Gitsek hep birlikte

Yine eskisi gibi..



Gülhane''de, Çamlıca''da

Çingenelerden, dilencilerden

Çiçek satan her meretten

Kaçsak köşe bucak

Yine eskisi gibi..



Otobüste, tramvayda

Metroda, duraklarda

Yapsam dedikodunu

Boyacı çocuklarla

Yine eskisi gibi..



Olivium''da, Çemberlitaş''ta

Kadir Has''ta, Cineplex''te

Profilo''da, …..

Filmden filme koşuşsak

Yine eskisi gibi..



Eminönü''nde balık ekmek

Kokoreç Ortaköy''de

Döner ekmek Kadıköy''de

Yesek yesek doymasak

Yine eskisi gibi..



Sarayburnu''ndan balıkçıları

Üsküdar''dan martıları

Geceleyin yıldızları

Seyretsek, seyrine dalsak

Yine eskisi gibi..



Bryan Adams söylese

Kollarımda sen olsan

Dans etsek gece boyunca

Çeksek kafaları son defa 

Yine eskisi gibi..



Yeni Türkü''yü Harbiye’de

Tiyatroda Trova''yı

Fuarda Noyan''la

Dinlesek, izlesek, konuşsak

Yine eskisi gibi..



Bakırköy’de limanda

Kadıköy’de rıhtımda

Bulduğumuz her fırsatta

Sevgimizi yinelesek

Yine eskisi gibi..



Sofi ile başlasak

Nietsche’yle devam etsek

Okusak okusak okusak

Not tutup, birbirimize anlatsak

Yine eskisi gibi..



Anlatsam maviliğini gökyüzünün

Işığın kendini, enerji kaynaklarını

Kepler’i, Newton’u, Cavit Arf’i

Detaylarına kadar anlatsam

Yine eskisi gibi..



Sokrates’den konuşsak

Diogenes’ten, evrimden, Darwin’den, 

İlk nedenden, İslam’dan

Adem’le Havva’dan konuşsak

Yine eskisi gibi..



Altımızda araba, arkamızda karavan

Yanında bir tekne, bir de motorsiklet

Hayallerimizde olsa bile

Tekrar Mısır''a gitsek

Yine eskisi gibi..



Nevşehir''e, Pamukkale’ye

Ağrı''dan, Ayber’e

Her dağına, her yaylasına yurdun

Çıksak karavanımızla

Yine eskisi gibi..



İskele sancak desek

Teknemiz alabora

Adını''da Melek koysak

Aşsak denizleri

Yine eskisi gibi..



Newyork''ta, Chicaco''da

Ev olsak, ocak kursak

İki gönül, iki sarhoş

USA yolunu tutsak

Yine eskisi gibi..



Nişanlansak, evlensek

Biri erkek, biri kız

Çocuk sahibi olsak

Kamp kursak, ateş yaksak

Yine eskisi gibi..



Sen ağlasan, ben ağlasam

Ben ağlasam, sen ağlasan

Derdi dertle yoğursak

Dünyaya meydan okusak

Yine eskisi gibi..



Sürsem yüzüm yüzüne

Değsem tenim tenine

Tutsam elim eline

Öpsem dudaklarından

Yine eskisi gibi..



Sarsam ince beline

Dalsam deniz gözüne

Kursam hayallerimi

Yazsam şiirlerimi

Yine eskisi gibi..



Seni seviyorum desem

Seni seviyorum desen

Tekrar tekrar söz versek

Tekrar tekrar sarılsak

Yine eskisi gibi..



Benimle evlenir misin, desem

Bir daha evet, desen

Mutlu olsak, güvensek

Bir daha inansak

Yine eskisi gibi..', 'Sultanahmet, Eyüpsultan Beşiktaş, Şirinevler Semt semt, karış karış  Gezsek şehr-i İstanbul''u Yine eskisi gibi.. Bahçelievler''de, Beyazıt''ta...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":160,"source_url":"https://www.antoloji.com/sursem-yuzun-yuzume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevda Türküsüydü Varlığın', 'bir-sevda-turkusuydu-varligin-menderes-iskin-vwbky', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sevda türküsüydü varlığın..

Masal tadında, inanılabileni oynayan

Hiç yoktu saklanacak yerim.. 

Kaçamadım..

Kah şiir ben oldum, sen söyledin

Kah şiir sen oldun, ben söyledim

Bir sevda türküsüydü varlığın..

Kısa soluklu.. uzunluktan yoksun..



Bir ecel türküsü oldu yokluğun..

Ölüm tadında, inanılamayanı oynayan

Hiç olmadı saklanacak yerim.. 

Bulamadım..

Kah şiir ben oldum, o söyledi

Kah şiir o oldu, ben söyledim

Bir ecel türküsü oldu yokluğun..

O benden, ben de senden yoksun.', 'Bir sevda türküsüydü varlığın.. Masal tadında, inanılabileni oynayan Hiç yoktu saklanacak yerim..  Kaçamadım.. Kah şiir ben oldum, sen söyle...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sevda-turkusuydu-varligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-menderes-iskin-ah628', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün ağlayasım var sevgili..

Bir bilsen ne çok..

Çok çile çektim be gülüm.. 

hem de ne çok..

Hiç yere.. Ölüm gibi..

Tek bıçaktım..

Tek bendim sevgili.. tek..

Neredeydin sen haa.. neredeydin.

Çok beklettin beni be sevgili.. 

Bir bilsen ne çok..



Aşk ateşten bir gömlek sevgili

Bilemedim giymesini..

hem de hiç..

Yandım yok yere.. yaktı..

Her gün daha derine.. ama hergün..

Acımasızca sevgili.. acımasızca..

Öğrendim yana yana sevmesini.. 

Yana yakıla.. yakıla yana..



Sevmek çok acıymış be sevgili..

Bir bilsen.. bir bilebilsen.. ne çok..

Çok özlettin kendini..

Çok özledim be sevgili.. çok özledim..

Sesini.. kokunu.. sevgini.. ve seni.

Bir bilsen..bir bilebilsen.. ne çok..



Dön artık be sevgili.. 

Dön.. ne olur..

Sensizlik ölümden acı..

Acı, ölümden sessiz sevgili..

Bir dönsen.. ah bi dönsen..

Dönsen diyorum artık..

Yalnızlığıma.. hayallerime.. ve bana..

Dönsen..

Ne olur..', 'Bugün ağlayasım var sevgili.. Bir bilsen ne çok.. Çok çile çektim be gülüm..  hem de ne çok.. Hiç yere.. Ölüm gibi.. Tek bıçaktım.. Tek bend...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sevgiliye-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme kal', 'gitme-kal-menderes-iskin-f3w7d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidersen, ne gündüzüm kalır ne de gecem

Günah dolar, hem gündüzüm hem de gecem

Hala hayallerimde, hala sen varsın

Kalbime kazılmış adın; gitme kal.



Gidersen cehennem olur sonrası

Bakar kör olurum, kör bakarım; gitme kal.

Kime sorar, nerede bulurum seni

Gidersen ölüm gelir üstüme; gitme kal', 'Gidersen, ne gündüzüm kalır ne de gecem Günah dolar, hem gündüzüm hem de gecem Hala hayallerimde, hala sen varsın Kalbime kazılmış adın; git...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gitme-kal-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük', 'dortluk-menderes-iskin-imh1z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yunus demiş malda yalan mülkte yalan 

Var birazda sen oyalan, sen kovalan

Ölüm tek gerçek dünyaysa yalan

Kal birazda sen soluklan, sen yuvalan.', 'Yunus demiş malda yalan mülkte yalan  Var birazda sen oyalan, sen kovalan Ölüm tek gerçek dünyaysa yalan Kal birazda sen soluklan, sen yuval...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüyüm Ben, İnsanlar Arasında..', 'oluyum-ben-i-nsanlar-arasinda-menderes-iskin-rqe8t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölüm bir pencere, gece karanlığında

Bakar korkarsın, korkar bakar, 

Yıldızlar altında, geceden geceye

Sen ona sinersin, o içine dolar.



Dost olmaz kimseye, yalnızlığından

İçten içe gülerken haline, 

Aslında göz kırpar, sinsice ölüme.

İnançsızlık, boşvermişlik ve ölüm

Herkesin karşısında titrediği kader! 

Seni sevmek güzelim, ölümden de beter. 



Yalnızım ama insanlar arasında

Sensizim hala, batık dünyamda

Hiç solumuyor, yaşamıyor gibiysem eğer

Ölmeden evvel ölmüşüm ben, 

Yaşarken ölmüşüm! 

Ölüyüm ben, insanlar arasında..', 'Ölüm bir pencere, gece karanlığında Bakar korkarsın, korkar bakar,  Yıldızlar altında, geceden geceye Sen ona sinersin, o içine dolar. Dost ...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oluyum-ben-insanlar-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Sevinci', 'yasamak-sevinci-menderes-iskin-apnz5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluk gibi, üzüntü gibi 

Ölüm kadar belki, sevgi kadar

Anlar vardır, 

Hasrete tabi, zulümlere gebe

Şahıslar vardır, 

Zamana çile dokuyan, onla mücadelede.



Bilirim, zordur yaşamak sevinci

Yakında sanırsın oysa uzaktadır

Uzakta sanırsın oysa yakındadır

Aşk gibidir, yanar yakar içinde de 

Sen kaçmadıkça, ne o seni kovalar

O kaçmadıkça, ne de sen onu.', 'Mutluluk gibi, üzüntü gibi  Ölüm kadar belki, sevgi kadar Anlar vardır,  Hasrete tabi, zulümlere gebe Şahıslar vardır,  Zamana çile dokuyan,...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasamak-sevinci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bana Bırakın', 'beni-bana-birakin-menderes-iskin-o8qi4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlama anam, ağlama sende, sana kıyamam.

Yas tutma babam, benim için yas tutma, buna dayanamam.

Unutma sevdiğim, sakın beni unutma, sana doyamam.

Ağam, bacım, gardaşım, gece, karanlık ve yalnızlığım

Beklemen artık, beklemen beni, geri dönemem.

Bin kere değil, bir kere ölmek istiyorum

Yaradanın ateşiyle yıkanmak istiyorum

Bırakın sevdiklerim, hayallerim beni bırakın

Bırakın yakamı artık, beni bana bırakın..', 'Ağlama anam, ağlama sende, sana kıyamam. Yas tutma babam, benim için yas tutma, buna dayanamam. Unutma sevdiğim, sakın beni unutma, sana doy...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beni-bana-birakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acizmendi', 'acizmendi-menderes-iskin-k26vc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölü gibi diri

Diri gibi ölü

Yaşayan ölü

Yaşamayan diri

O bir aciz

O bir mendi.', 'Ölü gibi diri Diri gibi ölü Yaşayan ölü Yaşamayan diri O bir aciz O bir mendi....', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/acizmendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun Yokluğu', 'onun-yoklugu-menderes-iskin-n4ie0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutluydum, gururluydum onunla

Güçlüydüm, umut doluydum

Yarınlarım onundu

Hayallerimde hep o vardı

Yarı dalgın, yarı baygın

Kaybolup giderdim gözlerinde



Güzel bir yüzü vardı, 

Deniz gözleri, bahar teniydi sanki

İncecikti beli, yumuşacıktı elleri

O benim kara kaşlımdı :)

Seside güzeldi hani..

Mizacı sertti ama

Fena sarsardı bir bakışı



Önce telefonlar kesildi

Sonra selam sabah

İki sevgili, birbirine yabancı

İki yabancı, birbirine sevgili olmuştuk

Gel zaman, git zaman

Sonunda bizide buldu ayrılık.



O gitti, yalnızlığım geldi

Günlerce yedi beni, yedi durdu 

Yedikçe kudurdu, yedikçe vurdu

Kanıma susamıştı hain 

Hasta köpekler gibi saldırdı

Birlikte yaşamayı öğrendik sonunda ama

Ne o beni anladı, ne de ben onu.



Varlığında, benliğimi kaybetmiştim

Yokluğunda, varlığım da elimden gitti

Hiç birşey acıtamadı beni, acıtamazdı

Onun yokluğu kadar

Anlatmak isteyip anlatamadım

Söylemek isteyip duyuramadım ama

Onu çok sevmiştim ben

Onu çok sevmiştim..', 'Mutluydum, gururluydum onunla Güçlüydüm, umut doluydum Yarınlarım onundu Hayallerimde hep o vardı Yarı dalgın, yarı baygın Kaybolup giderdim...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/onun-yoklugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yoktun', 'bir-yoktun-menderes-iskin-2vfet', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yoktun

Güneşim battı, 

Gülüm soldu

Bir yoktun

Yangın çıktı, 

Külüm kaldı

Bir yoktun

Neşem kaçtı, 

Ağlıyorum

Sadece, bir yoktun

Bir..

Senden önce nasıl yaşamışım

Senden önce nasıl 

Bilmiyorum..', 'Bir yoktun Güneşim battı,  Gülüm soldu Bir yoktun Yangın çıktı,  Külüm kaldı Bir yoktun Neşem kaçtı,  Ağlıyorum Sadece, bir yoktun Bir.. Sen...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-yoktun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-menderes-iskin-72f8e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bağlanmadım hiç kimseye

Sevemedim senin kadar.

Özlemedim hiç kimseyi

Seni özlediğim kadar

Kaybetmekten, yalnızlıktan

Ne ölümden, ne ecelden

Esen yelden, gelen selden

Hiç korkmadım hiç! 

Hiç bu kadar.', 'Bağlanmadım hiç kimseye Sevemedim senin kadar. Özlemedim hiç kimseyi Seni özlediğim kadar Kaybetmekten, yalnızlıktan Ne ölümden, ne ecelden ...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hic-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bir Ben Tanırım', 'beni-bir-ben-tanirim-menderes-iskin-d4ite', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni bir ben tanirim 

birde beni yaratan

Bana bir ben lazimim 

birde beni anlayan

Beni kimler anlamadi ki, 

Sen mi anlayacaksin', 'Beni bir ben tanirim  birde beni yaratan Bana bir ben lazimim  birde beni anlayan Beni kimler anlamadi ki,  Sen mi anlayacaksin...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/beni-bir-ben-tanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İste Sevgili', 'i-ste-sevgili-menderes-iskin-dgsno', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canımdan can

Kanımdan kan iste

İste vereyim sevgili

Yeter ki sen iste

Kanımı iste, canımı iste.



Köle değil, kul olmuşum

Bahtı kara el olmuşum

Herşey bitti, bitti amma

Dilerim, senin beni sevdiğin 

Dilerim gerçek olsun.', 'Canımdan can Kanımdan kan iste İste vereyim sevgili Yeter ki sen iste Kanımı iste, canımı iste. Köle değil, kul olmuşum Bahtı kara el olmuşu...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iste-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazar Dururum', 'yazar-dururum-menderes-iskin-24bkk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmez hiç kimse

Benim şiir yazdığımı

Doğan güneşle başlarım

Batana kadar

Her gece

Her gündüz

Yazar dururum



Kuşlar vardır şiirlerimde

insanlar kadar

Böcekler, balıklar, ağaçlar

Azcık ondan, azcık bundan

Farklı zamanlarda

Farklı mekanlarda

Yazar dururum. 



Karadır gözlerim benim, 

Kömür karası

Sevdim mi tam severim

Sevdim mi inadına

Dedim ya, gözüm karadır benim

Yazar dururum hep yeniden

Yazar dururum.', 'Bilmez hiç kimse Benim şiir yazdığımı Doğan güneşle başlarım Batana kadar Her gece Her gündüz Yazar dururum Kuşlar vardır şiirlerimde insanl...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yazar-dururum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zoraki sevgili', 'zoraki-sevgili-menderes-iskin-8v4dc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmesende

İstemesende

Zorda olsa

Kolayda olsa

Amacın

Mutlu olmaksa

Bende olmalıyım

Hayallerimde olmali

Hem hayatında

Hem de hayallerinde.', 'Sevmesende İstemesende Zorda olsa Kolayda olsa Amacın Mutlu olmaksa Bende olmalıyım Hayallerimde olmali Hem hayatında Hem de hayallerinde....', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zoraki-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zoraki sevgili (1)', 'zoraki-sevgili-1-menderes-iskin-v472e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen varsın

Çocuklarım var

Evimizde var

Arabamızda.

Herşeyim var

ama herşeyim! 

sadece

sensizlik yok

Hem hayatımda

Hem de hayallerimde.', 'Sen varsın Çocuklarım var Evimizde var Arabamızda. Herşeyim var ama herşeyim!  sadece sensizlik yok Hem hayatımda Hem de hayallerimde....', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zoraki-sevgili-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Ve Sessiz', 'sensiz-ve-sessiz-menderes-iskin-3tpph', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vakit yine geldi, 

Karanlık büründü.

Hasretin buram buram, 

Ağlamaklı gökyüzü

Buralar hep böyleydi zaten, 

Hep hüzünlü.

Şehir yine sessiz, 

Şehir yine sensizdi çünkü.', 'Vakit yine geldi,  Karanlık büründü. Hasretin buram buram,  Ağlamaklı gökyüzü Buralar hep böyleydi zaten,  Hep hüzünlü. Şehir yine sessiz,  ...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensiz-ve-sessiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapanabilir artık iki gözüm', 'kapanabilir-artik-iki-gozum-menderes-iskin-3e02i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bitti herşey, bitti desende, 

İki ceşme, iki gözün.

Beni sevmediğini söylesende, 

Dilinin ucunda saklı, 

Henüz söylenmemiş, bir çift sözün.



Kolay olmayacak seni unutmam, 

Belki de her gece ağlayacağım.

Kendimden geçtim zaten, 

Seni sana bıraktım, 

Aşkta gurur olmaz ki iki gözüm.



Dünya dediğin büyük bir yalan, 

Sende yalansın sevginde yalan

Var mı bu dünyada gayrı kalan. 



Ömrümün son demlerindeyken, 

Yavas yavas aci çektirmekse niyetin, 

Tek nefeste ölürüm bunu bilesin.



Ağlamaklı artık, ağlamaklı dünyam

Dönülmez yolun yolcusu oldum.

Bir ilktin bu bedende, 

Sonuncusuda (baharımda)  sen oldun.



Bitti herşey, bitti sonunda

Kapanabilir artık, iki gözüm.', 'Bitti herşey, bitti desende,  İki ceşme, iki gözün. Beni sevmediğini söylesende,  Dilinin ucunda saklı,  Henüz söylenmemiş, bir çift sözün. ...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kapanabilir-artik-iki-gozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muradımı kaybetmişim, dünüm bugünüm ve yarınlarımla', 'muradimi-kaybetmisim-dunum-bugunum-ve-yarinlarimla-menderes-iskin-zp4kp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni aradım seni andım bu gece

Eskileri bekledim unutulmuşluğumda

Nefes nefes üstüne

İçime doldurdum seni

Sayıkladıkça saldırdı ayrılık canavarı

Eskitilmiş aşkların

Varolmayan muhafızı..

İçime pusu kurmuş

Yaşlılığım, inançsızlığım ölümü kovalamakta

Oyunlaştırılmış hayatım

Ruhunu arıyor bedenim

Umrumda değil ki dünya

Muradımı kaybetmişim, dünüm bugünüm ve yarınlarımla..', 'Seni aradım seni andım bu gece Eskileri bekledim unutulmuşluğumda Nefes nefes üstüne İçime doldurdum seni Sayıkladıkça saldırdı ayrılık cana...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/muradimi-kaybetmisim-dunum-bugunum-ve-yarinlarimla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Sönmez Yangınlar', 'yuregimde-sonmez-yanginlar-menderes-iskin-snygo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğimde sönmez yangınlar, 

İsyanım dağlara kadere geçmez karar

Kar kaplarmış her dağı büyüklüğü kadar

Yeter ya Rab yeter, ne zaman gelecek bahar? 

Neden bu kadar etrafım karla kaplanmış 

Ah kar...', 'Yüreğimde sönmez yangınlar,  İsyanım dağlara kadere geçmez karar Kar kaplarmış her dağı büyüklüğü kadar Yeter ya Rab yeter, ne zaman gelecek...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yuregimde-sonmez-yanginlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimiş fotoğraf', 'eskimis-fotograf-menderes-iskin-2nxa8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dayanılmaz acılar, 

İçten yanmalar, 

L..

Engelli mesafeler

Kader dedikleri...



Dertli dünyalar

İsimsiz sokaklar, 

Lirik şahsiyetler

Aşk dedikleri, 

Ve ben...

Eskimiş bir fotograf

Rüyana hasret uyumakta.', 'Dayanılmaz acılar,  İçten yanmalar,  L.. Engelli mesafeler Kader dedikleri... Dertli dünyalar İsimsiz sokaklar,  Lirik şahsiyetler Aşk dedik...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eskimis-fotograf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimsin', 'benimsin-menderes-iskin-ogq52', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan, 

Mutsuz olduğunu düşündüğü kadar mutsuz

Yalnız olduğunu düşündüğü kadar yalnız

Çirkin olduğunu düşündüğü kadar çirkin

Aptal olduğunu düşündüğü kadar aptaldır.



Sen, 

Özel olduğunu düşündüğün kadar özel

Aşık olduğunu düşündüğün kadar aşık

Senin olduğunu düşündüğün kadar senin

Benim olduğunu düşündüğün kadar benimsin.', 'İnsan,  Mutsuz olduğunu düşündüğü kadar mutsuz Yalnız olduğunu düşündüğü kadar yalnız Çirkin olduğunu düşündüğü kadar çirkin Aptal olduğunu ...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/benimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk demek', 'ask-demek-menderes-iskin-51ngg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk demek

Hayal kurmak demek

Başucunda, aynı yastıkta

Kanatlanip uçmak demek

Daldan dala, pervasizca



Aşk demek

Kenetlenmek demek

Ruh gibi, bir bedende

Özgür olmak demek

Bahar gibi, bir çiçekte



Aşk demek

Hasret çekmek demek

Umut dolu, her nefeste

Gözyaşı dökmek demek

Her şarkıda, her seferde



Aşk demek

Yaşamak demek

Bir ömürde, bir ömürce 

Yaşlanmak demek

Bir gönülde, bir gönülle



Aşk demek

Ben demek

Seninle, hep yanında. 

Sen demek

Benimle, her anımda.', 'Aşk demek Hayal kurmak demek Başucunda, aynı yastıkta Kanatlanip uçmak demek Daldan dala, pervasizca Aşk demek Kenetlenmek demek Ruh gibi, b...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ask-demek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsan Da Olmasan Da', 'olsan-da-olmasan-da-menderes-iskin-ksn7j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tüm acılar geçer zamanla 

Mutlu olmalısın mutlaka

Hayatinda ben

Olsamda olmasamda.



Sadece senin kalacağım

Hep sevip, hiç unutmayacağım

Hayatımda sen

Olsanda olmasanda.', 'Tüm acılar geçer zamanla  Mutlu olmalısın mutlaka Hayatinda ben Olsamda olmasamda. Sadece senin kalacağım Hep sevip, hiç unutmayacağım Hayat...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olsan-da-olmasan-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Unutursun', 'sende-unutursun-menderes-iskin-vdhga', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonuçta..

Binmişiz bir aşk sandalına

Kader bu hiç güven olmaz 

Kazığını sivriltir, 

Acılar denizinde bir başına, 

El oluruz dileğim bir gün gelir.



Bugün güneş batsada, 

Yarın yeniden doğar

Ayrılık kader olmuşsa

Kul ne yapar

Böyle gelmişse böyle gider

Sende unutursun dileğim bir gün gelir', 'Sonuçta.. Binmişiz bir aşk sandalına Kader bu hiç güven olmaz  Kazığını sivriltir,  Acılar denizinde bir başına,  El oluruz dileğim bir gün ...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sende-unutursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık ve Gökyüzü', 'karanlik-ve-gokyuzu-menderes-iskin-pan9x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzüne bakmak, ama nereye kadar? 

Bağrındadır hayatın tüm anlamlılığı, 

Derinliklerinde saklıdır yaşamın sırları. 

Ay, yıldızlar, karanlık.. 

Bir ürperdidir salınır benliklerimize. 

Saklamaya çalışır gizlerini.



Kim demiş ki hayat anlamlıdır? 

Gökyüzünden bihaber midir bunu söyleyenler. 

Neden gece bu kadar karanlık?

Ulaşılamazlık var, bilinmezlik var, ama neden? 

Kim bilir..



Bakmak gökyüzüne, ama nereye kadar? 

Kümeler, sistemler, galaksiler..

Sonunda vardır yine karanlık.

Düşünenler birşeyin çok iyi farkındadır

Hayatın anlamsızlığı bu karanlıkta saklıdır.', 'Gökyüzüne bakmak, ama nereye kadar?  Bağrındadır hayatın tüm anlamlılığı,  Derinliklerinde saklıdır yaşamın sırları.  Ay, yıldızlar, karanlı...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanlik-ve-gokyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben De Seni Hiç Sevmedim ki', 'ben-de-seni-hic-sevmedim-ki-menderes-iskin-1zf72', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben seni hiç sevmedim

Ben seni hiç sevemedim ki

Eskileri bekledim unutulmuşluğumda

Nefes nefes eceldi içime çektiğim

Yalnızlıktı ilmik ilmik sana ördüğüm

Sadece hayallerim vardı yanımda

Birde sana dair üç beş satır

Satsan satılmaz, atsan atılmaz

Malum aşk pazarı bu 

Dürüstlük para yapmaz.

Ve sen unutulmuş aşkımın varolmamış şairi

İçimden kovamadığım gönül taciri

Çok su aktı bu çeşmeden, 

Çok geç kalındı belki

Ama ben seni hiç unutmadım

Ben seni hiç unutamadım ki.', 'Ben seni hiç sevmedim Ben seni hiç sevemedim ki Eskileri bekledim unutulmuşluğumda Nefes nefes eceldi içime çektiğim Yalnızlıktı ilmik ilmik...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-de-seni-hic-sevmedim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altılık', 'altilik-menderes-iskin-5idg3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En kötü günlerde bile kendime

Vasiyet bıraktım ölüm nafile

içinde kalmışsa benden geride

Yas tutup inleme dönmem geriye

O eski anilar seni birakmaz

Ruhun istemesede bedenin kaçamaz', 'En kötü günlerde bile kendime Vasiyet bıraktım ölüm nafile içinde kalmışsa benden geride Yas tutup inleme dönmem geriye O eski anilar seni b...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/altilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yap Yapabilirsen', 'yap-yapabilirsen-menderes-iskin-2obr8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tartış tartışabilirsen

anlaş anlaşabilirsen

karşındaki sen olunca

terk et terkedebilirsen



ölme yaşayabilirsen

dayan dayanabilirsen

hayalini hatıralarından

sil silebilirsen



ayrıl ayrılabilirsen

unut unutabilirsen

senin olan o gözlerden

vaz geç vazgeçebilirsen



kal kalabilirsen

sev sevebilirsen

senin için atan yüreğimden

kopma daha vakit varken



sar sarabilirsen

öp öpebilirsen

sana mecbur bu bedeni

bırakma eğer istersen



döv dövebilirsen

söv sövebilirsen

seni seven şu gönlümü

affet affedebilirsen', 'tartış tartışabilirsen anlaş anlaşabilirsen karşındaki sen olunca terk et terkedebilirsen ölme yaşayabilirsen dayan dayanabilirsen hayalini ...', ARRAY['Türk Edebiyatı','Şiir','Menderes Işkın']::text[], 8.5, '{"poet":"Menderes Işkın","poet_slug":"menderes-iskin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yap-yapabilirsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavan Dünya', 'yavan-dunya-menderes-iskin-sx8z7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalan dünya herkes yalan

