INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hep Vardin Hep Tek Kaldin Kalbimde', 'sen-hep-vardin-hep-tek-kaldin-kalbimde-menderes-iskin-y4mwu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitmek bilmez yaslar oldun gözümde

