INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaptım', 'yaptim-reha-basogul-w8mlp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arkasına bakmadan gitmek dedim

gözucuyla bile dönmemek dedim aşka

sihirli kavanozların kokusunda

kızgın yüreklerin sesi bağrımda dökülü kaldı.

irkildi bedenim eziklikte 

gösterişten uzak barajlar aşsam da

bir minik kalp kapakçığında beslenen

gergin sinirlerde kaybettim soluğunu

ölümcül günün yıldönümü bugün

karların izinde bulamadığım sesini

gözlerindeki ışığın aydınlatmadığı çadırımda

yumruklarımı  başıma vurup ağladığım gündü tam bugün.

seneler gezindi zamanda 

 sen bir türlü gezinemedin kaldın dilimde

bir uçurum astı, çiviledi beni 

bilinçsizce aradım adını anacak bir takımyıldızını silüetinde

çok sessiz düşler ve arkadaşların

ne kadar sevgi açtın yapraklarında sonraları

bir hata, bir sıla kadar olamadı gülümsemen

son anında ''üzülme sakın'' demen

ne sözler verdim anılarıma

ne kalın kitaplar bitirdim uğruna

anlatamadığım aşkımdın

şimdi ise tutunamadığım dalım

oysa ki bir dağ daha bekliyordu bizi

bir şarkı daha söyleyecektik orada

bir tepede daha adımızı yazacaktık karlara

bir hayal daha yeşerecekti ay ışığında

nokta dedin oysaki bütün bunlara

beni bana hapsettin yas kokan odalarda

az geçmedi o zaman

az düşmedi yere kan

şimdi sen ordasın ve kimi zaman ellerimde

ve kimi zaman beslediğim kelimelerimde

hiç kızmadın bana biliyorum

ve arkankandiler hiç sormadı bana seni

sen bir gelindin beni ormanlardan soran

bir gemiydin açılan okyanusumda yelken açan

bir suydun özümü sevgiyle boğan

bir ruhtun bedenden öte olan

şimdi burada ve yılları yanıma alarak

istediğin gibi 

bir mum bir gül ve bir kırçiçeği

en sevdiğin ses olan cırcırböcekleri

az zaman kaldı doğumuna

buluştuğumuz zaman asacağım fotoğrafını

gel kal diye dönme yıldızlara

verme artık leylaklarını, sinme artık kazağıma 

gel artık tekrar yüreğime

ve gözüm ol yeniden bedenimde

dudaklarımı karıştırsın yüzün

önünü görmez olsun öksüzün

biçimsizim biter geçer oyalarına

yaptığın ebrulara dalar düşerim

senimi ararım boyalı sularda

belki olur benden bir tane daha

''üzülme'' dedin, ''gül'' dedin son boşlukta

''hatan yok'' dedin ''seviyorum'' dedin

''özleme'' dedin, ''beni doğada büyüt'' dedin

''yaptım'' dedim, her gün için için

her gün senin için...', 'Arkasına bakmadan gitmek dedim gözucuyla bile dönmemek dedim aşka sihirli kavanozların kokusunda kızgın yüreklerin sesi bağrımda dökülü kald...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/yaptim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülizar', 'gulizar-reha-basogul-dkazm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni senden geçirendir sevgilin

beni bedenimden alandır sevincim

harfleri sayılarla mı birleştirdin

işte senin sevgilinin sevincidir bu zikrin

korku değildir geri gelişimin sebebi

muhabbete dalmasın aynadaki akisi

su akar gibi yol dener seni

aşk yoksa damlamaz gerisi

meşgale ararsa sende veledin

içine ulaşmasın çatık kaşlı cemalin

versen ona bir kuş yeter veledin için

yuva yapmayı unutma sakın kuş için

mumların önü gibi ol ki yanmayı öğrenesin

yan ki alevinin ne olduğunu bilesin

duman gibi yükselsin nedenin

karıştırma nedenini sakın kendin için

kelebeklerle yaşa ki gör çelimsizi

bil ki ilerde kanat çırpacak aşk delisi

kimi zaman kozadaki böcek ol ki sussun emelin

kimi zaman binbir rengi ol ki dönsün dilin 

hüzün ararsa yüzün, yüz gün ver kendine

bulamamışsan teraziyi yüz gün bile hikaye

sözünü gözünden sakla ki aksın elin

elini kimseden saklama ki çalmasın çirkin

bir gün gelecek fırtınaya sarılacaksın

gün gelecek meltemlerde havalanacaksın

her çeşmeye uygun bir musluk ol ki fırtına olasın

Bir elbiseye sökük ol ki meltem olasın.

her arayışta yeni bir deryaya açılır gemin.

her gemiye yeni bir kaptan alır için

her kaptan gibi yeni bir ufuk arar ilmin.

her ufuk da başka bir senle bir olur gönül çizgin', 'seni senden geçirendir sevgilin beni bedenimden alandır sevincim harfleri sayılarla mı birleştirdin işte senin sevgilinin sevincidir bu zikr...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gulizar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Damarda Tıkandım', 'i-cimdeki-damarda-tikandim-reha-basogul-60jeu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'herşey peygamberdevesinin kendini dişisine kurban etmediği bir dalı kırmasıyla başladı.

Ve ardından yusufçuklar kaçırdı yumurtalarını bataklıklardan...

Ardıç kuşlarına niye saldıramadı kartal o gün, 

niye sinemedi gelincikler çukurlarına

bukelamunlar niye renk vermediler

ve koalalar neden yaprak aramadılar gecenin soğuğunda? ? ? 

tanrının zekasını kıskanmışımdır hep

çılgınca mı? 

kıskançlık ve tanrı...

çözüm ne peki söyle, anlat hadi balarısı? 

''çakıltaşlarının sevişmesiyle doğmuştum ben

avlarım mağaramda hazırdı evlatlarıma

bir kayadan akan kanla

yayıldı zekanın sarmaşıkları yeryüzüne

Deniz akrepleri sığ sulara saldırdı sonra

medcezirlerle çoğaldılar toprakta

telef oldu köpük kusan balıklar

bir kere azmışlardı korkunç yaratıklar 

kömür suratlar az durmadı yerinde

istilalar başgösterdi azgın sularda

tüyler havalandı kadavra kokulu çağda

kapandı yaralar bir süre de olsa

zeka nefes aldı....

kafataslarını algıladı ışık yarımyamalak

bela geliyordu usulcana

çırpınarak

korkusuzca...

çenelerin donduğu bir yörede

bir aile aldı eline çiviyi

sürüyle bitti gösterileri

sürüyle yüzüldü derileri....

killere boyandı alınlar

boncuklar takıldı boyunlara

izinsiz mideler kalktı ayağa

çöpler birikti tepelerde buram buram

ırk savaşçıları çalışmaya başladı

ihtiraslar büyüttü gözbebeklerini, tıpkı bebek gibi

silkinemedi zeka

anlatamadı derdini bir türlü

akınlar oldu bir sonraki gün

çığlar düştü üstüne

lavlar aktı yerine

dayandı üşümedi, üşütmedi evlatlarını

gece yol aldı

sabah kalkamadı yerinden

karanlık kilimlerle uçtular etrafa

çocuklar ağladı beşiklerde 

heykeller uyandırdı sabahı

neşeli çığlıklarla büyüdü ormanlar

el işi görgüler kazandı yarını

ama zekayı iyileştiremedi bir türlü

ıslak bıyıklarla üstün geldi peçeler

kalın ciltler hükmetti hayata

ama bir çıra idi aradığı sonun

küller düştü okyanuslara

kolonilerce arı geldi bir araya

sığırların kuyruklarında buluştular daima

saklandı bilgiler gizli yerlere

ayaklar bulamadı onu bir türlü

çılgın heyacanlar ritm tuttular

ateşler etrafında kaçırdılar nesilleri

özlemediler berilerini

düşünemediler gerisini

ve zeka ayırdı onları

izlediler birbirini 

ama birleşmedi türleri

selim basiretler gırtlağa düğümlendi''

ıhlamurlarım kaynamıştı artık

süzüldüm kartalların sırtında

çömleklerim kurumadı ama güneşte

özgürlük haykıramadı yerin dibinden

zeka kayboldu yerinden.....

Babil''deki dilimi arıyorum

suskunluğun özünü

izlerin bedelini

tanrının dilini...

şeytanı bile affettim.

sansa da dost benle 

yalan mı kaldım onla bir ömürde 

yok oldu bağrıma basınca nedense

kıskandım seni her zaman

sayılarını göstermedin sakladın kaldın

terli çarşaflarda görüntün gözlerime indi

kuru toprakta ağırlığın bedenime bindi.

çelişkilerini bile çözdüm

ne kadar dost olduğunu

sözlerinin beni çağırdığı

içimdeki damarda tıkandım.

Babil''de kaybettiğim dilimi özlüyorum

suskunluğun özünü

izlerin bedelini

tanrının dilini...', 'herşey peygamberdevesinin kendini dişisine kurban etmediği bir dalı kırmasıyla başladı. Ve ardından yusufçuklar kaçırdı yumurtalarını batakl...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/icimdeki-damarda-tikandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni', 'bekle-beni-reha-basogul-piyph', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırık bir cam kürenin dışından bakan sen

hep silgi darbeleri yemiş bir kağıdı andırmışsan bana

kirli pencerelerden gözkırpmışsan karlara

gördüklerini işlemişsen ellerime

kale kapılarıma dayanmışsa güllerin

bir tabloda hayat vermişsen oğluna

kazdığın çukurlar cennete açılıyorsa bir zaman

matemler yakışıyorsa ruhuna

yıldızlar şahit oluyorsa yalanlarına

annemi çalmışsan geleceğimden

gözlüğümü değiştirmişsen aynayla

yapraklara günahlarımı yazdırmışsan

masallarda cadıları kollamışsan

sevgilileri kırık okla avlamışsan

ölüleri boğmuşsan toprağında 

selleri salmışsan ceddime

filizleri doğarken kavurmuşsan

ceninleri doğmadan kaçırmışsan

insanı insana satmışsan yüzsüzce

yalnızlar vadisine göç ettirmişsen onları

haykırmaları zevke saymışsan

çanları kılıcıma bulamışsan

yüzüğüme mühürlemişsen adını

vaktimi eskitmişsen karanlıklarda

sana söyleyecek son lafım: 

bekle beni kurutacağım soyunu', 'Kırık bir cam kürenin dışından bakan sen hep silgi darbeleri yemiş bir kağıdı andırmışsan bana kirli pencerelerden gözkırpmışsan karlara gör...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bekle-beni-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşının Anlamı', 'gozyasinin-anlami-reha-basogul-41n3s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sırra kadem basmış bir çağrı

Uzaklardan bir çilli horozun türküsü

Gün ışığının aydınlık yüzü

Çaresizliğin yıkılmaz gücü

Akreple yelkovanın seviştiği bir an dokundu bana

Açtım yüzümü dünyaya şeytanın ısıttığı yatakta

Engin bir melekler kentine doğru 

Açtım yelkenlerimi özgürce, tutkuyla

Bir ufacık cep kitabından daha azı mı

Hayır bu bir kelimede gizli bir kapı olmalı

Sukunetle dinledim onu sürünerek

Çelme takılan bir atlet gibi yorgunca

Sahipsiz bir bebeğin haykırmasıydı benimki

Sade, solgun ve üzgün

Bir kapıyı bulmuştum ya şimdi

Artık yaşlı bir çiftçiye dönmüştüm, belli

Başladı şerit geçmeye 

Dağların yücelik merasimi 

Nehirlerin hız talimi 

Toprağın sade gösterisi 

Ormanların inanılmaz rengi 

Titreyen kuşların önünden göz kırparak aldım acıyı

Açların arkasından acımasızca güldüm

Zalimlerle aşık attım

Etimi isteyenlere ruhumu sattım

Bir arınma mıydı bu

Yoksa tanrının lütfu muydu gaipten gelen

Rahiplerle imamları atlatıp

O boyutun zebanileri mi beni bekleyen

Sizi bilmem ama ben gördüm oraları

Cennetin heybetini

Cehennemin derinliğini

Sorun şu ki acıları dindiremiyorum hiçbir kuytu inde 

Bir gün bir gece bir an

Sizi bekleyenleri düşünün 

Önce gözünüzün önünden geçenleri 

Sonra niye gözyaşınızın aktığını', 'Sırra kadem basmış bir çağrı Uzaklardan bir çilli horozun türküsü Gün ışığının aydınlık yüzü Çaresizliğin yıkılmaz gücü Akreple yelkovanın s...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gozyasinin-anlami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küller', 'kuller-reha-basogul-3icxf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kısık sesle bir çığlık attım cihana

Ağlamaya başladım yalnızlıktan sonsuzluğa giden yolda

Gülücükler saçan hüzünlü palyaçoyu aradım gül bahçelerinde

Ama ızdırabın ölümü hepsinden acımasızdı

Kırık bir oku çıkardım gönlümde

Saf sütü kustum sonunda içimden

Olta attığım kırmızıya beyaz bulaştırdım.

Günleri afaroz ettim mağaralarda

bir kılıç aldım elime

ve biçtim sazlıkları

ölümle burun buruna gelenleri

kafasını kopararak kurtardım

İşte gücün adını koyan sen

Bana verdiğin gözleri

bu uğurda akıttım

Kanımı şerefine kaynattım

Sisin kokusunu

Yaramın tuzunu sevdim

İliklerimdeki soğukluğunu

Kalbimdeki deriyle sakladım

Ellerim yüzüne değdiği her an 

Bİr filizin yandığını gördüm

Seni yoketmek isterken

Köpeklerini besledim

O bebekleri arıtan bir kase biliyorum

Yünle kaplanan bir elbise

ÇArşafla kaplanan bir alın

Bunlar benim sana hediyem olsun.

Ancak, 

Bilmelisinki 

Bu savaş benim değil

Herkesin

Ama Sen beni ilk sıralardan tanıyacaksın

Ve son sıraya geldiğinde adımı anacaksın.', 'Kısık sesle bir çığlık attım cihana Ağlamaya başladım yalnızlıktan sonsuzluğa giden yolda Gülücükler saçan hüzünlü palyaçoyu aradım gül bahç...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kuller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum Sözler Uğruna...', 'masum-sozler-ugruna-reha-basogul-lfp2q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözlerin ok sayıldığı yıllarda büyüdüğüm ben

Kızgın korların fırsat olduğu sokaklarda

Paçavraların gururla taşındığı o zamanda

Bir çocuk olarak elime aldım kemanı

Biriktirdiğim pullarda resmimi gördüm 

Kardan adamın gözlerinde acıyı

Çalan okul zillerinde küfrü şakıttırdılar adıma

Ve o çocuk bu sefer aldı çanı eline

Her köşe başında salladım onu sağa sola

Etrafımdaki gülümsemeleri indirdim yarıya

Kuytu köşelerdeki sahipsizleri gösterdim onlara

Bir aşkı başlattı bir ufak melodiye kanarak

Özgürlüğün şarkısı oldu o sonraları

Artık bir ırmağın şırıltısı almıştı bayrağı

Küçük sincaplar taşıdı bir süre

Sonra o yaşlı adam gördü sonu

Yılların kuyusunu kazmaya başlamıştık yavaş yavaş

Sahipsiz sözcüklerimi bağışlamıştım artık

Adresler önüme yığılmıştı ağırcana

Geldiğim yer öksüz kalmıştı şimdi

Bitmedi dedim, işte o an

Yıkamazsınız beni, kalacağım o okların ucunda

bir bülbül bekliyor şimdi yarını

dönüşümü erteleyin kıymayın bana

Ve mazgallar gibi suyumu çektiler

İçimdeki sanatı körelttiler

Artık prangalarla yaşıyordum

Fikri benden çekip alıp götürdüler

Bu cehennemin sıcağını anlatır bana

MEzar taşının soğukluğundan farklıdır hani

Böceklerin tırmalamasından

Gözlerinin akmasından

Bir yaşam şarkısıdır işte bu

Bilemezsin çanların kimin için çalacağını

Ruhunun efendisi olma uğruna

Sadık hizmetkar olarak yaşarsın şeytanın

Kırgınlıkları atsaydım eğer üzerimden

Sevgimi köreltseydim hizmetkarlara

Yalnızlığı salsaydım kalabalığa

Şimdi o paçavraları gururla taşırdım söyle ona', 'Sözlerin ok sayıldığı yıllarda büyüdüğüm ben Kızgın korların fırsat olduğu sokaklarda Paçavraların gururla taşındığı o zamanda Bir çocuk ola...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/masum-sozler-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Cuma', 'i-lk-cuma-reha-basogul-ig5pf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorgun bir akşamüstü bu

sıradan bir kaderin oynandığı ilk cuma

sahiller, sokaklar ve yılanlar yine orada bekliyor onu

kendimin çaresini arıyorum bezmeden, düşmeden

bir çizgi görüyorum ilk başta uzaktan

Biraz yakınlaşınca çukurlukları seçebiliyorum

Ve büyüyor gitgide

ışığa da ihtiyaç yok, hissedebiliyorum çünkü

evet bir yaşamın gözyaşlarının bıraktığı izler bunlar gözlerimin altında

her gün bir savaşta bayrağını kaybeden askeri oynamak gibi bir anı yaşadığım oralarda

bir nilüfer yaprağında yıllardır süzülmek kadar çaresiz, bir o kadar da güzel

nedir istediğim senden benim

kuytu köşelerde para verdiğin dilenciler kadar açsın bu hayata

eğer bir müzisyenin bestelediği hüzün nağmelerinde yaşıyorsan hala

dönüp bakma orada çalana, çünkü duydukların senin ölüm çığlıkların 

işte bu yüzden belki yok etmeliyim o izleri oradan

o izleri kimbilir, kırdığım şişelerle beni bekleyen adadaki, zamanı bilen birine ulaştırmalıyım 

bir çeltik daha atmaz belki artık

uçların adamı olduğum yıllar

kezzapların sıcaklığını tadardın

doğanın sana verdiği her şimşek

çevrene koyduğun önyargılar kadar yüklüydü

anlayamadım işte, biraz akılmış ihtiyacım olan

o izlerin gördükleri

nedense bir bebeğinki kadar

haketmiyorum işte ondan, 

her gördüğümde acı veriyor maalesef

Sandaldaki aşıkları bilir misin

hani kuğuları seyredeler de koklaşırlar

ve sonra aşkı anladık diye bakarlar beraber sudaki akislerine

bilmezler ki baktıkları gördükleri, yaşadıkları aşk değil

Sıradan kaderin ilk cuması

yine istanbul, yine bir ayna

Bu sefer zorlanmadan çıkan sıradan bir gözyaşı daha hızlı damlıyor

Belki yüzümdeki izlerin arttığındandır 

Ona sormalı sebebini

Nedersin hayat kardeş, çok mu hızlı akıyorsun artık ha?', 'Yorgun bir akşamüstü bu sıradan bir kaderin oynandığı ilk cuma sahiller, sokaklar ve yılanlar yine orada bekliyor onu kendimin çaresini arıy...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ilk-cuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evrensel Korku', 'evrensel-korku-reha-basogul-d488i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'durduk yerde buhranlandın akşam akşam

yanık günün tuzunda eridim 

yılan gibi kıvrıldın gönlümde 

okyanusa sarıldım üstümü örtmeden 

çizgiler neydi teninde

fırtanın izleri mi yoksa acının darbeleri mi

yorgun düşmanla ikinci bir savaş niye

zamanı uçur gönlünde, ara kendini bende

yangınları say bahrında

kıvrıl hücrelerinde hızlıca

damarlarındaki şarkılarına meze ol 

sazlıkları ara kanının son damlasında

yalnız bir çocuk düşün kalbinde

ulaşmadığın, bilmediğin birini

kendini hapsettiğin ama tutuklu kalmak istediğin

ona var, onu hisset çaresini bilmeden, umursamadan

ezgileri gördün mü orda

kılıcınla kesebildimi her birini

taşın ağırlığını bildin mi üstünde

ucunu çözelebildin mi ipin

kızdın mı bana, aradın mı beni tutsaklığımda

nice yürek eskittin başka maphuslarda

oysa ki bakmadın hiç içine

sormadın beni kendine

uçurtmaları hatırlatma bana, 

dönen fırıldakların haddi hesabını

hafızama yenik düşürdün

saf gülücükleri gösterdin, kirletmeden

yıkıl karşımdan diyemeden 

içimde filizlendin herzaman, aniden 

sen kimdin beni üzmeden anan

yaşlandıkça küçülten, soruldukça yanıltan

tanıyamadım seni bir türlü

nolur yine gel, yine uğra bana...', 'durduk yerde buhranlandın akşam akşam yanık günün tuzunda eridim  yılan gibi kıvrıldın gönlümde  okyanusa sarıldım üstümü örtmeden  çizgiler...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/evrensel-korku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz Karanlığı Kulağına Fısıldarsa...', 'temmuz-karanligi-kulagina-fisildarsa-reha-basogul-19e2x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sıradan bir Temmuz zifirisi

ne hatırlatır ki insana, 

gökyüzüne baktığında

yalnızlık burcu şekillenir mi? 

sonsuzluğa dalarsın

çaresizce, 

dosta nameler dökülür kalbinden

hilalin kıvrımlarını çizerken

aydınlanır birden zihnin

zifiri boştur gördüğün, 

ışığın sonsuzluğunu

yüzsüzce araklarsın yüreğine

sırdaş bellemişindir yıldızları

soğuk denizle dalgalanır anıların, 

yıkımların erimiştir İstanbul''da

kalemin dansöz olmuştur elinde.

kozmos''un bütünlüğü kulaklarında çınlar her an

damarlarındaki kan üzülür taşamadığına

akar taşanlar kuru bir kağıtla

anladığın zaman olsun be dostum.

sihire inanmışındır artık

sızmışsındır sineye, 

gözlerin fırça olmuştur 

renklerini seçersin kubbeden

gökyüzünün Temmuz karanlığında...', 'Sıradan bir Temmuz zifirisi ne hatırlatır ki insana,  gökyüzüne baktığında yalnızlık burcu şekillenir mi?  sonsuzluğa dalarsın çaresizce,  d...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/temmuz-karanligi-kulagina-fisildarsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-reha-basogul-iw4jx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her gece bir mum ışığı arar oldum, 

kayboldum.

beni bende bırakmak istemeyenlerden kaçtım, 

şanslıydım.

gecesiz düşünemez oldum, 

korktum.

geçmişte şiirden nefret edendim, 

sevildim.

ikiyüzlülüğü sorguladım kalanlarla, 

umutlandım.

içimi keşfetmekten yoruldum, 

dinlendim.

her gece soluksuz bir kitabı soludum, 

boğuldum.

çok bebeğin kalbine ok attım, 

vuruldum.

her gece yılanların koynuna girdim, 

sarıldım.

her doğumda uyanık kaldım, 

üşüdüm.

hayatı olduğu gibi kabul edemedim, 

kızdırdım. 

üç şey istedim gözlerim açıkken: 

herşeyi bilmek

her bildiğimi paylaşmak

ve başarmak, 

yanıldım. 

çekindim bahşedilen yirmidokuz harften, 

aradım.

su içtim, 

yoğruldum.

Ve ben her gece yazamadım, 

uyudum...', 'Her gece bir mum ışığı arar oldum,  kayboldum. beni bende bırakmak istemeyenlerden kaçtım,  şanslıydım. gecesiz düşünemez oldum,  korktum. g...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ayna-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş mü Gerçek mi?', 'dus-mu-gercek-mi-reha-basogul-kg3r7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fırıldağı olan 10 yaşında bir çocuktu

Her sabah çıkar dağlara, rüzgarı ağırlardı.

Rüzgar ise döverdi fırıldağı

Çocuk sevinirdi.

Kadın, dertliydi çocuk okumalıydı

Baba hastaydı, zaman acımasızdı.

Günler acele ediyordu 

Acılar ise beklemiyordu günü.

Fırıldak, çocuk için cennetti.

Doğa bunun farkındaydı.

Onu üzemiyor, tatlı esintisini bağışlıyordu.

Zaman çocuk için durmuştu.

Kadın yanıldı, çocuk okumıyacaktı.

Baba, kabrin soğukluğunu bahrına basmıştı.

Horoz ötmemişti sabah onun için belliydi.

Belki sıla başlamıştı. 

Islak kabuslar yanılmadı.

Çocuk fırıldaktan vazgeçti; 

Tarlalar terledi.

Arpanın derdine düştü kadın.

Son yaklaşıyordu

Yağmurun soğuk elleri toprağı avuçladı. 

Toprak nehirle tanıştı.

Arpa kadına veda etti.

Çocuk, isyancıydı.

İçi yaslıydı.

Kadına koştu.

Kadın arpadan vazgeçti. 

Mutluluk buydu ikisi için

Kaybedilen çoktu ama 

Elindekiler kimsede yoktu.

Onlara artık sonsuz sevgi yaverdi.', 'Fırıldağı olan 10 yaşında bir çocuktu Her sabah çıkar dağlara, rüzgarı ağırlardı. Rüzgar ise döverdi fırıldağı Çocuk sevinirdi. Kadın, dertl...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dus-mu-gercek-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Hava ''denemesi''', 'uzun-hava-denemesi-ali-riza-erdem-ycxd1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'iklimler geçti üstümden 

mezarımın yeri kayboldu 

yarin gözyaşları varken 

yağmurlar ıslatır oldu 

çiçeklerimi kuruttular 

otlarımı hep yoldular 

beni kefensiz koydular 

yardan ayrı bıraktılar 

bilseydim hiç ölürmüydüm 

ben bu cana kıyarmıydım 

bir yağlı ipin ucunda 

saatlerce kalırmıydım', 'iklimler geçti üstümden  mezarımın yeri kayboldu  yarin gözyaşları varken  yağmurlar ıslatır oldu  çiçeklerimi kuruttular  otlarımı hep yold...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Erdem']::text[], 8.5, '{"poet":"Ali Rıza Erdem","poet_slug":"ali-riza-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzun-hava-denemesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalleş Arap Atları', 'kalles-arap-atlari-siar-sata-pibsi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kalbimden vurdular beni kalleş arap atları

kalleş arap atları bir de üzerime çıkıp tepindiler

ayakları nallarının gölgesinde bir kara tepe gibiydi

uçuk sarı mı desem yeleleri

bir hazin buğday biçimi mevsiminde kaşıntıma gelmişler

olsa gerek, ellerim, kollarım bütün gövdem

başakların arasında bir yabancı gezgindi

itelediğim bütün taneler birer kurşun

kalleş arap atları

ah ben! 

bilseydim kalleşliği, hissetseydim

ve yakalayabilseydim gözlerinden fırlattıkları

inceuzun nal çivilerini, at sinekleriyle

anlaşabilseydim

atlara belli etmeden

bir başka mevsimin dul kalmış masumiyeti olabilecektik

arap atları

kalleş

şimdi yürüsem de desem ki titrek akşamüstü ölülerine

üşümüşler

öncekilerin öldürdüğü birkaç ölümün sahibiydiniz

...itiraz

yo, yo, ölüler sahip olamazlar hiçbir şeye

ölüm de desen bir sahiplik

fazla bir yüktür bize

desem ki sahip olamadığınız bir ölüme

tenha kalmış düşlerin taraçasından uzanmışken

yüksek

siz hiç öldürdünüz mü bir kalleş arap atını?', 'kalbimden vurdular beni kalleş arap atları kalleş arap atları bir de üzerime çıkıp tepindiler ayakları nallarının gölgesinde bir kara tepe g...', ARRAY['Türk Edebiyatı','Şiir','Şiar Şata']::text[], 8.5, '{"poet":"Şiar Şata","poet_slug":"siar-sata","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kalles-arap-atlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-siar-sata-jgdcp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Suya düşer bir damla

Su dalgalanır

Bakar küçük çocuk dalgalara

Ufak gemisi yalpa yapar, şekerleri düşer

Yosunlar arasındaki kurbağa zıplar

-Gel der küçük çocuk, yakalar kurbağayı ve öper

Hiçbir şey olmaz

Suya düşer bir damla

Su dalgalanır', 'Suya düşer bir damla Su dalgalanır Bakar küçük çocuk dalgalara Ufak gemisi yalpa yapar, şekerleri düşer Yosunlar arasındaki kurbağa zıplar -...', ARRAY['Türk Edebiyatı','Şiir','Şiar Şata']::text[], 8.5, '{"poet":"Şiar Şata","poet_slug":"siar-sata","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cocuk-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıyorum', 'birakiyorum-yavuz-turhan-z2f6h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bırakıyorum...

Yaşayamadığımız, bundan sonrada yaşayamayacağımız, 

acılarımla dönüyorum  hayatıma.

 Yokluğun; bir kapı aralığı kadar

boşluk yaratacak.

Yinede bir gün kapanacaksın.

Acılarım, kapının öbür yanında kalacak.

Bir bir kapanan kapıların ardında, 

yine, yalnız kendimle olacağım..', 'Seni bırakıyorum... Yaşayamadığımız, bundan sonrada yaşayamayacağımız,  acılarımla dönüyorum  hayatıma.  Yokluğun; bir kapı aralığı kadar bo...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/birakiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dizeler 3', 'dizeler-3-yavuz-turhan-u76bh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğim, hala yüreğinde; 

Kanıyor...

       Isınıyormusun...

______________________________________________

       Ben senin İLK''indim...

       Sen benim SON''um oldun...

______________________________________________

       Seninle yaşadıklarım, 

                                   yüzyıl gibi...

       Şimdi yalnızım, 

                                   binlerce yıldır...

______________________________________________

        Fotoğraflarda yüzüme bak; 

Sen kaçtın gözüme.

        Kimse çıkaramaz....', 'Yüreğim, hala yüreğinde;  Kanıyor...        Isınıyormusun... ______________________________________________        Ben senin İLK''indim...   ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dizeler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Ve Şairlere', 'sana-ve-sairlere-mehmet-polat-ii-jpbdc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana; 

Bilmem hangi mısrayı versem sana 

Hangi şarkının neresine kursan tahtını 

Hangi çocuğun iç çekişi değmeli sevdana 

Kurşunlardan hangisi vurmalı yureklerimizi 

Serilir birgün göğümüze yıldızlar

Vurulur yürekleri cellatların

Milyon tane at koşar yüreklerimizde 

Milyon kere sever seni milyon kere ölürüm

Ey şairler, 

Küstah bir çocuğum ben 

Ve de asi

Yüreğim malzemedir divanlarınıza 

Boynum kılıçlarınıza amade, 

Ona bir şiir yazdım, 

Ya bozun bu oyunu

Ya da vurun düşsün boynumu.....', 'Sana;  Bilmem hangi mısrayı versem sana  Hangi şarkının neresine kursan tahtını  Hangi çocuğun iç çekişi değmeli sevdana  Kurşunlardan hangi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Polat II']::text[], 8.5, '{"poet":"Mehmet Polat II","poet_slug":"mehmet-polat-ii","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-ve-sairlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onursuzunum', 'onursuzunum-cemal-sureya-d4ve7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha nen olayım senin, 

Onursuzunum.
..........
..........', 'Daha nen olayım senin,  Onursuzunum. .......... .............', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/onursuzunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Muyum?', 'mutlu-muyum-tolga-baydar-g5vuo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Mutlu musun? '' diye soruyor birileri bana

Cevap veremiyorum onlara

Ne halde olduğumu ben de bilmiyorum

Mutlu muyum? 

Nasıl mutlu olunur ki, yanında yar olmayınca? 

Nasıl mutlu olunur ki, dudaklar yanaşmayınca? 

Nasıl mutlu olunur ki, iki ten buluşmayınca? 

Nasıl mutlu olunur ki, vücutlar sarılmayınca? 

Nasıl mutlu olunur ki, gözler karşılaşmayınca? 

Nasıl mutlu olunur ki, yar yanında olmayınca? 

Gülüyorum, sadece gülüyorum halime

Bu sonu hazırlayan ben, başka ne yapabilirim ki? 

Var mı acaba, azap veren derdime bir çare? 

Mutlu olmak benim de hakkım değil mi ki? 

Sevmek, sevilmek, istediğim şey mi ki? 

Yoksa, sadece gönül eğlendiricisi mi istiyorum? 

Ben ne istediğimi biliyor muyum ki? 

Mutlu muyum? 

Hayır, değilim

Mutlu değilim, hiç bir zaman da olmadım

Mal, mülk, tok karın, yanımda beni sevenler! 

Ama içimde bir acı, kemiriyor beynimi

Salak gibi ediyor ruhaniyetimi

Mutlu değilim

Olamam da

Çözümü imkansız bir problemim ben

Anlaşılması zor bir komposizyon

Net bir görüntüsü olmayan fotoğraf

Akıcılığı olmayan bir filmin karesi

Ve sonunda

Gülizar makamında bir şarkıyım ben

Kararı siz verin bakalım

Mutlu muyum ben?', '''Mutlu musun? '' diye soruyor birileri bana Cevap veremiyorum onlara Ne halde olduğumu ben de bilmiyorum Mutlu muyum?  Nasıl mutlu olunur ki,...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mutlu-muyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-mehmet-ali-cibikli-kl3gf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adını kalbime, çok zor yazmıştım, 

Dedim ki ne unutur, ne silerim.

Seni kendime  sevgili sanmıştım, 

Seni sevmek boşmuş, özür dilerim.

Sen de sevdin sandım, demek aldandım, 

Meğer hepsi yalan, hepsi boşuna.

Tatlı bakışlara bakıp da kandım, 

Geç olsa da anladım en sonunda.

Karanlık dünyamın güneşiydin sen, 

Ruhumun en derin köşelerini 

Aydınlatır, ısıtırdın istesen.

İstesen saçardın neşelerini.

Olmadı, istemedin sen de beni, 

Ruhum da, kalbim gibi öksüz kaldı.

Her şeyden çok fazla sevmiştim seni, 

Seninle yaşamak sanki masaldı.', 'Adını kalbime, çok zor yazmıştım,  Dedim ki ne unutur, ne silerim. Seni kendime  sevgili sanmıştım,  Seni sevmek boşmuş, özür dilerim. Sen d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/masal-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seninle Mutluydum', 'ben-seninle-mutluydum-oguzkan-bolukbasi-w8ao8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir ayazdı üşüyordum

seni düşündüm

sabah vakti gün vuruyordu denize

çaylar yeni demlenmiş

ocak üzerinde hayatın buharı

ruhum bardaklardan taşmış

ağlıyordum

sen vardın

ben seninle mutluydum aşk

ama sen 

hiçbirşeye yetmiyordun', 'bir ayazdı üşüyordum seni düşündüm sabah vakti gün vuruyordu denize çaylar yeni demlenmiş ocak üzerinde hayatın buharı ruhum bardaklardan ta...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ben-seninle-mutluydum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
