INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiziliğin Yamacında', 'kimsesiziligin-yamacinda-hasan-sabah-nawcm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çılgın zamansızlıklar

Sabahın şafağında gizli, 

Dildeki hınca vuruk

Gönüldeki sevdasızlık

Yaşananlar hep sizli, bizli.

*****

Bir başka şehrin kayalıklarına

Kabuk bağlamış yosun

Yabancı bir el uzanmış yalnızlıklara

Gecenin ayazına vurgun

*****

İhtiyar bir serzeniş

Megalomanca bir söyleniş

Hep aynı anlarda kümelenmiş, 

Tenhalıklarda doğmuş tufan

Kalabalıklarda yitirilmiş.

*****

Eh diye başlayan cümleler kurmuş 

En dar anlarında aşık

Söylemiş, söyleyememiş

Dil ne ki dudaklar mühürlenmiş.

*****

Uçurum yürekli aşıklar

Kimsesizliğin yamacında beklerken, 

İnsancıl seslere aldanmış

Yarınlardan düşen kırgınlıklara ağlamış

******

Yarımca bir hayat, 

Yaşamın diğer yüzünde

Kan son kez damlarken toprağa

Çamura saklanmış, 

Sessizlikler çıldırmış.', 'Çılgın zamansızlıklar Sabahın şafağında gizli,  Dildeki hınca vuruk Gönüldeki sevdasızlık Yaşananlar hep sizli, bizli. ***** Bir başka şehri...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sabah']::text[], 8.5, '{"poet":"Hasan Sabah","poet_slug":"hasan-sabah","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kimsesiziligin-yamacinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim, Çocukluğum', 'sevgilim-cocuklugum-baki-ayhan-t-cvw0a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bakışların terk edilmiş bahçeler gibiydi

sevgili çocukluğum

sevgilim, çocukluğum benim

başımdan atamadığım paslı bir taçsın

dallarında korkuyla gezindiğim bir ağaç

uykuların tedirgin yolculuklar gibiydi

hiçbir yere gitmeyen bir trenin penceresinde

kendini derin kuyulara hapsettin

yağmur kuşlarının gökkuşağına sürtünmesiydi

aramızda uzanan sessizliğin

anılarını unutmaya kararlı bir sarrafın

uğradığı haksızlıkları bağışlaması gibiydin sen

sevgili çocukluğum benim

sevgilim, çocukluğum

bu bulanık suyla birlikte yaşamak zorundasın

kime ne

hangi hayatın kaçıncı sayfasında kaldığın', 'bakışların terk edilmiş bahçeler gibiydi sevgili çocukluğum sevgilim, çocukluğum benim başımdan atamadığım paslı bir taçsın dallarında korku...', ARRAY['Türk Edebiyatı','Şiir','Baki Ayhan T.']::text[], 8.5, '{"poet":"Baki Ayhan T.","poet_slug":"baki-ayhan-t","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgilim-cocuklugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Gürültüsüzlük', 'derin-gurultusuzluk-baki-ayhan-t-ren89', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sakin olmayı öğrendim senden

duru sulara bakmayı

bir ermiş gibi pas tutmuş kapıların ardında

kendimle buluşmayı

sessiz kalmayı öğrendim senden

sevinçlerde ve büyük acılarda

yerine ulaşmayan bir mektup gibi

kendime dönmeyi

soruları cevapsız bırakmayı öğrendim senden

bir budala gururuyla dolaşmayı anılarda

yeri unutulmuş, 

hiç umulmayan bir yerde bulunmuş

yanlış ağaçlarda bitmiş yapraklar gibi

yabancılaşmayı

zamanı hissetmemeyi öğrendim senden

küçük hırçınlıklarına yenilirken insanlar

sessizce girdim ve öyle çıktım içinden

ateşler içindeyken

susuzluğumda yangınları içerken

bu derin gürültüsüzlük

senden', 'sakin olmayı öğrendim senden duru sulara bakmayı bir ermiş gibi pas tutmuş kapıların ardında kendimle buluşmayı sessiz kalmayı öğrendim send...', ARRAY['Türk Edebiyatı','Şiir','Baki Ayhan T.']::text[], 8.5, '{"poet":"Baki Ayhan T.","poet_slug":"baki-ayhan-t","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/derin-gurultusuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Cinayeti', 'guz-cinayeti-baki-ayhan-t-rkqi6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sizin

adını güz koyduğunuz bir anınız oldu mu

bitti mi sonra yavaş yavaş

suyun taştan süzülüşü gibi

bakışı gibi

karanlıkta uykulu bir kuşun

adını güz koyduğunuz anınız

sizi karşıladı mı uykusuzluklarda

ulaşılmaz bir kuytuluk

uçucu bir gülümseme duruluğunda? 

size soruyorum bu soruyu! 

böyle bir anınız yoksa

adını güz koyduğu bir anısı yoksa insanın

neden bakar ki korkuyla

uzaklara? 

güz

bir mevsimmiş gibi davranıyor herkese

çocukluğumun ilk cinayeti!', 'sizin adını güz koyduğunuz bir anınız oldu mu bitti mi sonra yavaş yavaş suyun taştan süzülüşü gibi bakışı gibi karanlıkta uykulu bir kuşun ...', ARRAY['Türk Edebiyatı','Şiir','Baki Ayhan T.']::text[], 8.5, '{"poet":"Baki Ayhan T.","poet_slug":"baki-ayhan-t","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guz-cinayeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkı Dostum''a', 'siki-dostum-a-salih-ozalasan-bicx5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün gönlümde hava, parçalı bulutlu

Hatta yağmur yağıyor, sağanak sicim gibi

Şimşekler çakıyor, dinmiyor gök gürültüsü

Ve, fırtınalar arasında bir ses, o ses senin sesin

Tatlımı tatlı, şekerpare neki yanında

Ilıkmı ılık, meltem tadında

Uzatsam elimi, çok yakınsın

Gülümseyen gözlerle duruyorsun karşımda

Bak şimdi bende gülüyorum söylediğime

Karşımda dediğim çok uzakta aslında

Ama olsun kızmasını bilmeyen seni

Sevgi dolu seni, tanıdım odamdaki ekranda

Görmesemde yağmur olup yağdığını biliyorum

Kurumuş çatlamış suya hasret topraklara

Görmesemde mendil olduğunu biliyorum

Gözlerden akan sicim gibi yaşlara

Sen çok özel ve çok güzelsin biliyorum

Yüreğinde GÜNEŞ''in parlaklığı

Sana mutluluk, sana saadet diliyorum

Tanrımdan senin için 

gönlünden geçeni vermesini istiyorum

Güzel olan herşeyi

Sana vereceğini adım gibi biliyorum', 'Bugün gönlümde hava, parçalı bulutlu Hatta yağmur yağıyor, sağanak sicim gibi Şimşekler çakıyor, dinmiyor gök gürültüsü Ve, fırtınalar arası...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/siki-dostum-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Beste', 'son-beste-salih-ozalasan-gv910', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sevda şarkısı yazdım

Aşkın hançeri saplı yüreğime

Sana olan özlemimi kattım

Hüzünle inleyen nağmelerine

Notalar ağlıyor sessiz sessiz

Hep hüznü katmışım sözlerine

Boğazımda bir hıçkırık

Karışıp gitmiş sazımın tellerine

Sayfalara dökmek istedim

Gördümki kanımı katmışım mürekkebe

Tüylerim ürperdi korkuyla irkildim

Delirmişim sanırım ben bu ne böyle be? ! .

Böylede şarkımı olur

Mutluluktan tek satır yok güftede

Oysa sevmek mutluluk değilmi

Kavuşmak olmasada sonunda

Yırtıp attım, kopardım sazımın tellerini

Sonra bir dikişte içtim

Kan damlamış mürekkebi

Belki serseriyim, belkide birazcık deli

Ama karar verdim

Hüzünsüz yapacağım son bestemi

Söyleyende dinleyende mutlu olacak

Aşık olmak artık benide mutlu etmeli

03-07-2002 Saat 12.00', 'Bir sevda şarkısı yazdım Aşkın hançeri saplı yüreğime Sana olan özlemimi kattım Hüzünle inleyen nağmelerine Notalar ağlıyor sessiz sessiz He...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/son-beste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Bir Kez', 'son-bir-kez-pervin-adalioglu-2etzr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum ne kadar uzaksın bana

Şu an ne kadar sıcaksındır kimbilir sarılmış hatıralarına

Mahzun mahzun bakıyorsundur

Şimdi eline geçen her resme

Görebiliyorum; 

O buğulu gözlerinin masumluğu değilmiydi içimi parçalayan 

Bir çocuk gibi küskünlüğün değilmiydi beni deli eden.

Perdenin arkasına gizlenmiş izliyorsun 

Sokaktan geçen her sevgiliye

Biliyorum; 

Öyle yakınsınki aslında sen bana

Görebilmek değil hissedebilmekte bana yakınlığın.

Sen varsın her mısrasında şiirlerimin

Sana kaldırdığım bütün kadehlerimde

Sensizliğin acısını içtiğim her yudumdasın.

Her yudumda içimdeki ben sana çırpınır.

Süresizce...

Görmeden hatta doyumsayamadan seni

Uzatmışken ellerimi dokunamadan sana

son bir kez...

Yapayalnız bırakıp gittin beni

Bu acımasız bomboş sokaklarında

Yorgun kentin...', 'Bilmiyorum ne kadar uzaksın bana Şu an ne kadar sıcaksındır kimbilir sarılmış hatıralarına Mahzun mahzun bakıyorsundur Şimdi eline geçen her...', ARRAY['Türk Edebiyatı','Şiir','Pervin Adalıoğlu']::text[], 8.5, '{"poet":"Pervin Adalıoğlu","poet_slug":"pervin-adalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/son-bir-kez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hileli Anılar Terazisi', 'hileli-anilar-terazisi-baki-ayhan-t-jgsly', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yağmurun kıyısına yığılmış bulutlara

aralığa, kasımdan kaçan aralığa

masalların mutlu sonuna

bakarken

birdenbire fark eder insan: 

gümüş bulaşmıştır

hileli anılar terazisine

bir adam

antikacı dükkanına bakar gibi kente

bir kadın

esrarlı bir aynaya bakar gibi kente

bir ben

boşluğa bakar gibi kente

bakarken

birdenbire fark eder zaman: 

karanlık bulaşmıştır

hileli anılar terazisine

aşkın umutlardan arındığı

yağmurun bitip yolların başladığı

iç ısıtan selamların yalnızlığa taşındığı

bakarken

birdenbire fark edilir nedense: 

tekbaşınalık bulaşmıştır

hileli anılar terazisine', 'yağmurun kıyısına yığılmış bulutlara aralığa, kasımdan kaçan aralığa masalların mutlu sonuna bakarken birdenbire fark eder insan:  gümüş bul...', ARRAY['Türk Edebiyatı','Şiir','Baki Ayhan T.']::text[], 8.5, '{"poet":"Baki Ayhan T.","poet_slug":"baki-ayhan-t","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hileli-anilar-terazisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dehliz', 'dehliz-baki-ayhan-t-gwr5m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sizi

ateşli bir uyku gibi uyudum önce

rengini şaşırmış

aşk kırmızısı bir gül penceremde

sonbahar

bol bir yüzük gibi fırladı parmağımdan

çarptı bütün köşelerine

bir köşeli aşk ikliminin

''aşk imiş her ne var alemde''

aşkın bu alemde yok pusulası

ateşli bir uyku gibi uyurken sizi

tarihin dehlizlerinde', 'sizi ateşli bir uyku gibi uyudum önce rengini şaşırmış aşk kırmızısı bir gül penceremde sonbahar bol bir yüzük gibi fırladı parmağımdan çarp...', ARRAY['Türk Edebiyatı','Şiir','Baki Ayhan T.']::text[], 8.5, '{"poet":"Baki Ayhan T.","poet_slug":"baki-ayhan-t","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dehliz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluktaki Rüyam', 'sonsuzluktaki-ruyam-mehmet-davran-u8r3o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün gelecek, 

Yaşamla Ölüm arasındaki farkı tadacağım.

Karınca misali evrim geçirip, 

Göğe uçacağım.

Toprağa gireceğim.

Bağırıp, çağırıp duyuramayacağım sesimi, 

Yazıya döküp, 

Aleme ibret olsun diyeceğim, 

Günün birinde.

Bir gün gelecek, 

Nefretle sevgi arasındaki farkı tadacağım.

Mecnun misali sevip gönlümde, 

Dağları deleceğim Ferhat gibi.

Yemyeşil bir çiçek olacağım, 

Tek bir tohumdan türeyip, 

Gökkuşagı renginde sümbüller açacağım.

Selvi ağacı olacağım, 

Kendi mezarımın başında, 

Türküler söyleyeceğim, 

Kıble rüzgarlarında.

Ve bir gün gelecek, 

Tekrar dirileceğim.', 'Bir gün gelecek,  Yaşamla Ölüm arasındaki farkı tadacağım. Karınca misali evrim geçirip,  Göğe uçacağım. Toprağa gireceğim. Bağırıp, çağırıp...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Davran']::text[], 8.5, '{"poet":"Mehmet Davran","poet_slug":"mehmet-davran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sonsuzluktaki-ruyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akçalar', 'akcalar-salih-ozalasan-xp3no', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün sana şöyle bir baktım

Ölümsüz şairin baktığı gibi

Yedinci tepeden ey AKÇALAR

Yeşile boğulmuşsun

Yazın başka kışın başka

Baharın anlatılamaz ki 

Yeşil fışkırıyor bağrındaki her taşta

Bir yanını yaslamışsın

Nazlı yare yaslanır gibi

Salınıp giden dumanlı dağlara

Bir yanında deniz misali göl

Martı sesleri karışıp gidiyor yakamozlara

İnsanı seven insanların

Gülüp oynayan masum çocukların

Taşın yirmidört ayar altın

Bereket fışkıran toprağın

Meydanında salınır

Üçyüz yıllık abide çınarın

Bu toprak benim 

Doğduğum toprağım

TÜRKİYE bir cennet amma 

AKÇALAR benim 

İlk ve son durağım

04-07-2002 Saat 17.20', 'Bugün sana şöyle bir baktım Ölümsüz şairin baktığı gibi Yedinci tepeden ey AKÇALAR Yeşile boğulmuşsun Yazın başka kışın başka Baharın anlatı...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/akcalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasta..', 'hasta-yavuz-sevinc-g4g0b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hastadır şimdi sevdam..

Güzelim yüzü solgun, 

Dudaklarında acı bir tebessüm..

Öylece yatmakta..

Denize karşıdır penceresi bilirim, 

Dün elele yürürken kıyısında, hani..

Kızmıştı bana tuttum diye elini..

Beni görür düşlerinde şimdi, bense yaşarım onu nefes nefes..

İnan bana narin çiçeğim, 

-Karışamayız takdirine Tanrının-lakin..

Daha iyi olacaksın eskisinden, 

Yeniden sahilden çakıl taşları toplayıp, 

Yeniden sevişeceğiz geceler boyu  yorulmacasına..

Kavga bile edeceğiz yeniden..

Bekle sevdam, sabret güzel çiçeğim..

İyileşeceksin yeniden...', 'Hastadır şimdi sevdam.. Güzelim yüzü solgun,  Dudaklarında acı bir tebessüm.. Öylece yatmakta.. Denize karşıdır penceresi bilirim,  Dün elel...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sevinç']::text[], 8.5, '{"poet":"Yavuz Sevinç","poet_slug":"yavuz-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Topallıyorum', 'topalliyorum-mahir-turkyilmaz-7524o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimden giderken öyle bir boşluk yarattınki, 

yüreğinin bile dolduramayacağı

Umutlarımla yamadım, 

gelecek umutlarımla.

Ay bile küskün bana

Yıldızlar eskisi gibi parlamıyor.

Uçurumdan düştümde haberim mi yok yoksa.

Yoksa noldu buralara, bana.

Zaman hızlımıydı bu kadar, 

hayallerim bile yetişemez oldu.

Açık bırakmıyorum artık penceremi, 

yatmadan önce kontrol ediyorum; 

yine yönünü şaşırmış, asi bir rüzgar gelip girmesin yüreğime; 

gelecek olan kapıyı kullansın diye.

Zorların peşinde değilim artık.

Hiçbir şehir saklayamaz beni, 

hiçbir yürek taşıayamaz sevgimi.

Gözlerim dolmuyor artık, 

gözyaşlarım çoktan beni terk etmiş.

Herşey okadar olağan gibi

gel görki kabul etmiyor benliğim, 

benliğimi çıkarsam üşürmüyüm acaba

kaybolurmuyum sahte insanları taşıyan

kimsesiz şehirlerde.

Sonbaharda geldi, 

eskisi gibi değil

Birşeyler değişiyor, 

birşeyler kayboluyor içimde

Okadar hızlıki; 

umutlarım bile yetişemiyor.

Karanlıkta değilim artık, 

keşke olsam

Gözlerim gülerdi belki o zaman

Işık olurdum ve hızıyla yetişirdim zamana.

Şimdi yitik yüreğimde yamalarımla

zaman önde ben arkasında

topallıyorum...', 'Yüreğimden giderken öyle bir boşluk yarattınki,  yüreğinin bile dolduramayacağı Umutlarımla yamadım,  gelecek umutlarımla. Ay bile küskün ba...', ARRAY['Türk Edebiyatı','Şiir','Mahir Türkyılmaz']::text[], 8.5, '{"poet":"Mahir Türkyılmaz","poet_slug":"mahir-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/topalliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İm', 'i-m-tuncay-ucar-nwehg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir imgelemi, birmilyon kere beynimin sağınağında bıraktım

Islanmadı.

Islanmadın.

Birmilyon imgelem sağınağına, beynimi bıraktım

Senin selin boğdu...', 'Bir imgelemi, birmilyon kere beynimin sağınağında bıraktım Islanmadı. Islanmadın. Birmilyon imgelem sağınağına, beynimi bıraktım Senin selin...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Uçar']::text[], 8.5, '{"poet":"Tuncay Uçar","poet_slug":"tuncay-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/im-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya Yakalandı Yağmur 1', 'sevdaya-yakalandi-yagmur-1-aydin-karatay-uwm9s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülemedim bir süre 

nedensizdi hayallerim 

kimliksizdi kişiligim 

kişiligim kişiliksizdi

anlayamadım çünkü 

anlatan yoktu.........

aslında anlatamazlardı ya 

inat bu ya bahane işte 

anlayamadım diyemedim bir süre 

sevdaya yakalandı yagmurlar 

ben anlatamadım...............

aslında seni sevmemiştim ben 

seni sevmeyi sevmiştim 

çok uzak degildi benim için yıldızlar 

sen uzak ettin 

kimsesizdim kimsesizdim 

sensizdim 

sevdaya yakalandı yağmurlar 

ben sevdalandım................

birkere bile acılamadık birbirimize 

şöyle adam akıllı niye diye soramadık 

bir bahanesi yoktu aslında 

ikimizde birbirimize 

birde 

sevdaya yakalandı yağmurlar 

sevdaya yakalandı düşlerim

hiç konuşmadık degilmi seninle 

şöyle birer bardak sıcak çay 

yanıda İSTANBUL KONUŞAMADIK DEGİLMİ 

hiç el ele tutuşmadık seninle 

haliçte yürümedik maviye hiç degilmi 

sevdaya yakalandı yağmurlar 

YAĞMURLAR YAKALADI SEVDAMI 

bazen anlamaya çalışırım düzensizligimin

düzenini anlayamam ya olsun 

anlamış gibi sana yorarım hep 

hep aklımdadır İSTANBUL, 

hep aklımdasındır sen 

İSTANBUL gibi

sevdaya yağmur yağdı

yakalandı YAĞMURLAR SEVDAYA..............', 'Gülemedim bir süre  nedensizdi hayallerim  kimliksizdi kişiligim  kişiligim kişiliksizdi anlayamadım çünkü  anlatan yoktu......... aslında a...', ARRAY['Türk Edebiyatı','Şiir','Aydın Karatay']::text[], 8.5, '{"poet":"Aydın Karatay","poet_slug":"aydin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sevdaya-yakalandi-yagmur-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Çeker', 'sana-ceker-ahmet-aka-jlwmf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '/anneme...

Beni benden alıp sana çeker de

Kalkar gözlerinin önünden perde

Cennet ayağının altında durur

Sorma; ‘gideceğim yer hani nerde’', '/anneme... Beni benden alıp sana çeker de Kalkar gözlerinin önünden perde Cennet ayağının altında durur Sorma; ‘gideceğim yer hani nerde’...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sana-ceker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler annesine', 'anneler-annesine-ahmet-aka-jaoe7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana öyle muhtacım

Ekmek kadar, su kadar...

Duaların ilacım; 

Cennet kokusu kadar.', 'Sana öyle muhtacım Ekmek kadar, su kadar... Duaların ilacım;  Cennet kokusu kadar....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anneler-annesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sadece-sana', 'sadece-sana-ahmet-aka-zrxwf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suratımda bir şamar hasretin yorgunluğu

Bahara ne kaldı ki şunun şurasında cân

Benzinde benden kalma bir eylül solgunluğu

Kalbimi delik deşik ediyor bu heyelân

Yıldız yıldız açılmış gözlerin hüzünlere

Saçların gaf dağında biten mor menekşedir

Tutunmuş gidiyorum eskimeyen günlere

Yolculuğum sevdanın götürdüğü yeredir

Duraksız şiirlere düşüyor yaşadığım

Hangi satırdan baksan parantezler kopuyor

Dualara gebeyken çatlayan bu dudağım

Küflü peynirler gibi içten içe kokuyor

Ayaklarım nereye götürürse oraya...

Bir sırça saray gibi düş dünyamdaki çadır

Kimse el uzatmıyor, meyletmiyor paraya

Göz değmemiş hayali satsan bilmem kaçadır', 'Suratımda bir şamar hasretin yorgunluğu Bahara ne kaldı ki şunun şurasında cân Benzinde benden kalma bir eylül solgunluğu Kalbimi delik deşi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sadece-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yar', 'o-yar-ahmet-aka-2e0jt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Feryadımı sağır duydu

İşitmez mi o yâr beni

Bu kahırla bu düşünce

Oylum oylum oyar beni

Ben bir kulum, bir beşerim

Yanılırsam uyar beni

Onun adıyla yaşarım

Hayal kursam duyar beni

Farkın yok desem ırmaktan

Karalara boyar beni

Korkuyorum çağırmaktan

El yerine koyar beni', 'Feryadımı sağır duydu İşitmez mi o yâr beni Bu kahırla bu düşünce Oylum oylum oyar beni Ben bir kulum, bir beşerim Yanılırsam uyar beni Onun...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Figan', 'figan-ahmet-aka-z8tca', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vebalıysam vebalıyım

Vebalim sen değil misin

Hüznün zehirli balıyım

Kovanım sen değil misin

Sen elliysen ben de yüzüm

Yüzünü görmesin gözüm

Hem ateşim hem de közüm

Dumanım sen değil misin

Tutulmazsa vasiyetim

Harap olur vaziyetim

Kendimeyse eziyetim

Figanım sen değil misin

Uykularımı bölmüşüm

Bir dirilip bin ölmüşüm

Yüreğine gömülmüşüm

Mekanım sen değil misin

Düşmeyelim dilden dile

Döneriz sonra kandile

Haydi ne dilersen dile

Sultanım sen değil misin', 'Vebalıysam vebalıyım Vebalim sen değil misin Hüznün zehirli balıyım Kovanım sen değil misin Sen elliysen ben de yüzüm Yüzünü görmesin gözüm ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/figan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yük Trenlerine', 'yuk-trenlerine-ahmet-aka-ajixa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu şehir yiyip bitiriyor

bu şehir çarmıha geriyor bizi

akşam karanlığına ayarlı göz yaşlarımız

ayak uçlarımızda mercan balıkları

ve koptu kopacak kanatlarımız

bırakıp gider gibi kalabalıkları

son sürgün yerimiz burası

bu deniz manzarası olmasa

bütün kahpeliğiyle ele verecek

‘bir yağmur yağsa

bir rüzgar fısıldasa ardından’

içimizdeki çınarı devirecek.

Bu deniz manzarası olmasa

İnanmayacağım orada olduğuna', 'bu şehir yiyip bitiriyor bu şehir çarmıha geriyor bizi akşam karanlığına ayarlı göz yaşlarımız ayak uçlarımızda mercan balıkları ve koptu ko...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yuk-trenlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme...', 'anneme-ahmet-aka-dundg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '/senin bakışlarına endeksliydi yaşamım

sesin, kalp atışlarımın remziydi/

Böyle boynu bükük oluşum neden

Neden çarşı pazar bana yabancı

Yürüdüğüm yollar, içtiğim sular...

İhtiyar falcıdan daha yalancı

Alıp da koynuna ısıtsan beni

‘Donmuşsun çocuğum nerdeydin’ desen

O çıkmaz sokakta, bahçe evinde

Yiten yıllarımı geri getirsen...', '/senin bakışlarına endeksliydi yaşamım sesin, kalp atışlarımın remziydi/ Böyle boynu bükük oluşum neden Neden çarşı pazar bana yabancı Yürüd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anneme-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyanın Kabuğu', 'ruyanin-kabugu-ahmet-aka-8845g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '/Sana dair ne varsa yüreğimde deli kız

onu senden uzaklara götürüyorum/

Son umut da bırakıp gidiyor beni

Sessizlik bir çığlık, yırtınıyor yüreğim

Kaç gel oradan diyorum, senden bir ses gelmiyor

Hüzün kılcal damarlarımda çırpınıyor

Yüzün yavaş yavaş gözlerimi terk ediyor

Sisli manzaralardan artakalan bir buğu

Git başımdan diyorum, ‘fırsat bu fırsat’ diyor

Seçilmeyen rüyanın kırılıyor kabuğu', '/Sana dair ne varsa yüreğimde deli kız onu senden uzaklara götürüyorum/ Son umut da bırakıp gidiyor beni Sessizlik bir çığlık, yırtınıyor yü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ruyanin-kabugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşhis', 'teshis-ahmet-aka-jmaed', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Teşhisini teşhir et yakışmıyor tevriye; 

Tevşihin teshir eder bayram olur terviye.

Silâhların gölgesi serindir, saadettir; 

Taş çıkartır mahzenden semâvata, serviye

Sekanat selâmete ulaştırmaz bilirsin

Bırakıp bîmariyi sen ol artık devriye', 'Teşhisini teşhir et yakışmıyor tevriye;  Tevşihin teshir eder bayram olur terviye. Silâhların gölgesi serindir, saadettir;  Taş çıkartır mah...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/teshis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçu Sevmek Olan Suçluyu Sevdim', 'sucu-sevmek-olan-sucluyu-sevdim-huseyin-kerim-ece-409r0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürekte anıt gibi o tek uluyu sevdim, 

Suçu ona tutulmak olan suçluyu sevdim.

Ellerim kelepçeli, kaç gündür sorgudayım, 

İnan olsun ki ben bu uzun sorguyu sevdim.

Su kayadan dökülür, denizi düşler rüzgâr, 

Renkler içinde onu tutan duruyu sevdim.

Köşklerin hasretinde beklesin kimileri, 

Ben, Yusuf’u saklayan engin kuyuyu sevdim.

Sevmedim silahları ve kavgaları, fakat

Mekke’ye selâm ile giren orduyu sevdim.

Güneş yükselsin, kuşluk vakti olsun ne yazar, 

Düşte onu sunan bu derin uykuyu sevdim.

Çöller damla bekler de yağmur hep nazındadır, 

Yüreği bağ aşkıyla sulayan suyu sevdim.

Bütün umutlar kalsın kafdağının ardında, 

Ben sonsuzu kuşanan en son arzuyu sevdim.

İzler ve renkler sessiz bir iklimde solarken, 

Sadece onu soran en zor soruyu sevdim.

Zincirler kırılsın ve sular salıverilsin, 

Aşkın korunduğu o özel koruyu sevdim.

Sözlükten onu atsam, geriye kaç söz kalır? 

Sevdayı sayıklayan vird’im hû hû’yu sevdim.

O bende var oldukça korkmam yaban ellerden, 

Ondan firak olmayan her tür korkuyu sevdim.

Kalbin med ve ceziri gün gelir derya olur, 

Ölümü vuslat bilen tatlı duyguyu sevdim.

Hasret çile değil ki âh vâh edeyim yine, 

Ben sonsuzu gönlüme oyan burguyu sevdim.

Gülü, leylâkı, nar’ı size bıraktım; çünkü

Aşkı hatırlatan o güzel kokuyu sevdim.

Yürekte bahar gibi konuk uluyu sevdim, 

Ve suçu onu sevmek olan suçluyu sevdim.

15/4/2000    Zaandam', 'Yürekte anıt gibi o tek uluyu sevdim,  Suçu ona tutulmak olan suçluyu sevdim. Ellerim kelepçeli, kaç gündür sorgudayım,  İnan olsun ki ben b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sucu-sevmek-olan-sucluyu-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraflar', 'i-tiraflar-huseyin-kerim-ece-8qrw1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aczimi itiraf ettim kırık kelimelerle

İçimdeki heyecan beşe katlandı, 

Mağrur nefsime aynaya bak dedim, 

Görürsün mesafeyi, görürsün ölçüyü, 

Korku değil biriken değil; belki...

Aczin hazin feryadı, ya da ıssızlığın.

İşte kimse yok kalabalık içinde, 

Ne teselli veren bulunur burada

Ne de sıkıca elimden tutan, 

Ufuk uzakta, ümit uzakta, güven uzakta, 

Nedir başımda dolaşan bulut, anlayamadım, 

Niçin her bakışta bir durgunluk? 

Niçin her çığlıkta binlerce hüzün saklı? 

Gün çevriliyor, büsbütün hâzân başlıyor, 

Güz gelmeden yapraklar dökülüyor birer birer, 

Evlerde matem hiç eksik olmuyor, 

İçimdeki heyecan giderek büyüyor, 

Bir ıslak gömlek gibi sarıyor bedenimi, 

Çığlıktaki o ölçülemez boyut, 

Acziyet yeniden tırmanıyor aynaya, 

Hep onu görüyorum iki kaşımın arasında, 

Hep yolcular görüyorum aynada, 

Ufuktan ufuka sallanan kol gibi, 

Sonra... derin bir düşünce-sonu gelmez endişeler, 

Korku değil bu... bir garip tedirginlik, 

Gece karanlığı ürkütmüyor beni, 

Ama yüreğime akşamın alacası birikiyor, 

Fecir ‘kâzip’ olarak doğuyor, 

Gün geri gelmiyor aştığı yerden, 

Bekleyenler bitkin düşüyorlar, 

Sabahın aydınlık doğuran yüzünü.

Tereddüt bir yağmur gibi ıslatıyor gözleri, 

Ürperti yüreğe arkadaş oluyor, 

Niçin parıldamıyor yıldızlar? 

Niçin ay gitgide küçülüyor ufukta? 

Niçin her geçen dakika boşluğu vuruyor? 

Niçin tutmuyor ellerimi aydınlık? 

Acziyet haykırıyor bütün gücüyle, 

Yalnızlık türküsünü söylüyor.

Yalnızlık bir ufuktur, uzayıp giden, 

Yalnızlık bir denizdir kıyısı olmayan, 

Ne sahil, ne iskele, ne de yeşil orman, 

Ürpertimle beraber yağmurlu bir gün.

Hüznün hatırası ayrılığın sancısıdır, 

Beklemeye duran gözlerim kapı önünde, 

Denize açılan küreksiz sandal gibi, 

Acziyet kendini yeniden duyuruyor, 

Yeniden kapılarım açılıyor sonsuzluğa, 

Bir nöbet başlıyor yeniden...

Hüznün yanıbaşında... şurada.

         25/4/2001 Den Haag-Zandam', 'Aczimi itiraf ettim kırık kelimelerle İçimdeki heyecan beşe katlandı,  Mağrur nefsime aynaya bak dedim,  Görürsün mesafeyi, görürsün ölçüyü,...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/itiraflar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-mehmet-mert-cetin-oczqu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sensizlik, 

kör bir kuyu 

bir düşüyorsun 

her yer karanlık 

göz gözü görmüyor 

tutunmak için bir yer yok 

bir ışık yok 

kıpırdayamıyorsun 

çıkmaya çabalıyorsun, imkansız 

sesi bile çıkmıyor adamın bu kör kuyuda 

imdat diyemiyorsun 

ya gelen sen olmazsan 

ne değişecek 

gene kör kuyu 

gene kör kuyu 

gel artık çıkar beni 

seni özlüyorum', 'sensizlik,  kör bir kuyu  bir düşüyorsun  her yer karanlık  göz gözü görmüyor  tutunmak için bir yer yok  bir ışık yok  kıpırdayamıyorsun  ç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Mert Çetin']::text[], 8.5, '{"poet":"Mehmet Mert Çetin","poet_slug":"mehmet-mert-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensizlik-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-mehmet-mert-cetin-wrebg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yoksun 

yokluğunda fırtınalar kopuyor bebeğim 

yüreğim kopuyor yerinden 

sana doğru 

yoksun 

uçurumlar açıldı ruhumda 

içinde sen 

ve ben', 'yoksun  yokluğunda fırtınalar kopuyor bebeğim  yüreğim kopuyor yerinden  sana doğru  yoksun  uçurumlar açıldı ruhumda  içinde sen  ve ben...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Mert Çetin']::text[], 8.5, '{"poet":"Mehmet Mert Çetin","poet_slug":"mehmet-mert-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoksun-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç ve Aşık Geldim', 'ac-ve-asik-geldim-umut-yavuz-9f8do', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aş olayım sevgine aç kalplere

Yaş olayım yolunu bekleyen gözlere

Kapını aşındırdıysam hoşgör

Ya aç gireyim gönlüne ya aç gideyim

Bülbül olayım sen kokan güllere

Söz olayım seni sayan dillere

Bağban olayım senin gezdiğin bahçede

Ya aç gireyim gönlüne ya aç gideyim

Ateş olayım sana yanan aşıklara

Ateş-i dilden ben de yanayım sana

İçin için, içim erirken böyle

Ya aç gireyim gönlüne ya aç gideyim

Ram olayım sana eren nücuma

Can olayım seni soluyan vücuda

Kurbanın olayım gurbete salma böyle

Ya aç gireyim gönlüne ya aç gideyim

Fecr olayım, sensiz, kara leyale

Sensiz olmak nasıl gelir hayale

Subh-u vuslat, aç koma sefili

Kerem ummanı lutfet aç geldim

Ya aç gireyim gönlüne ya aç gideyim

Gönüller feri, kutlu peri

Bu sefilin, eşiğinde var mı yeri? 

Aç ve aşık geldim, çevirme geri

Ya aç gireyim gönlüne ya aç gireyim

Aç gireyim ne olur aç gireyim...', 'Aş olayım sevgine aç kalplere Yaş olayım yolunu bekleyen gözlere Kapını aşındırdıysam hoşgör Ya aç gireyim gönlüne ya aç gideyim Bülbül olay...', ARRAY['Türk Edebiyatı','Şiir','Umut Yavuz']::text[], 8.5, '{"poet":"Umut Yavuz","poet_slug":"umut-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ac-ve-asik-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Bahar', 'huzunlu-bahar-umut-yavuz-lqjfp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bize yine hüzün mü var bu bahar? 

Bilseniz yürekte kopar, nasıl fırtınalar

Müteessir, yüreğimin çırpınışlarına kanarım.

Anarım, hiç olmayan günleri, özlemle anarım

Bilmem ki; bize kar eder mi bu bahar

Bahardan sonra açan çiçeğin ne anlamı var

Göz yaşlarımla muttasıl suladığım çiçekler

Bilirim baharda elbet filizlenecekler

Lakin, beyhude geçen her lahzada yanarım

Çünkü bilirim, elbet sonu vardır baharın...', 'Bize yine hüzün mü var bu bahar?  Bilseniz yürekte kopar, nasıl fırtınalar Müteessir, yüreğimin çırpınışlarına kanarım. Anarım, hiç olmayan ...', ARRAY['Türk Edebiyatı','Şiir','Umut Yavuz']::text[], 8.5, '{"poet":"Umut Yavuz","poet_slug":"umut-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/huzunlu-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Diyara', 'gel-diyara-umut-yavuz-xurqq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Leyli evvelde haberim geldi yara

Dedim yara: “Yaralıyım gel diyara.”

Gelmedi zira yarin aşkı kalbimde yara

Bilmem ki niye gelmedi ne engeldi yara.

Anladım hasret, gurbete devaymış.

Gurbet açar yarayı, hasret kapatırmış.

Ki hasretsiz sevgiden tat almazmış.

Şu insan ne garip, çileden haz alırmış.

Ey sevgili! Sen dinleme beni, gel aguşuma

Duygu yüklüyüm yine, biraz coştumda.

Bu kadar hasret iyi değil, inanma

Şu ruhum sarardı soldu, sakın geç kalma!', 'Leyli evvelde haberim geldi yara Dedim yara: “Yaralıyım gel diyara.” Gelmedi zira yarin aşkı kalbimde yara Bilmem ki niye gelmedi ne engeldi...', ARRAY['Türk Edebiyatı','Şiir','Umut Yavuz']::text[], 8.5, '{"poet":"Umut Yavuz","poet_slug":"umut-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-diyara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğuna Alışamadım', 'yokluguna-alisamadim-ozcan-nevres-q8uya', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabahı olmayan bir gecede

Çıkıp kentin karanlık sokaklarında dolaştım

Yokluğun sinmiş bu karanlık sokaklara

Ayaklarım sürüklüyor beni 

Her zaman buluştuğumuz kuytulara

Şurada kolumu dolamıştım ilk kez beline

Şurada dudaklarım uzanmıştı dudaklarına

Şurada uzanmıştık serin kumların üstüne

Karanlık kayaların ardında sevişirdik

Kaybolan bir zaman içinde

Zaman nasıl geçerdi anlayamazdık

Kayaların arkasına gittim

Orada sanki seni bulacakmışçasına

İhanetini yaşadım

Mehtabını yitirmiş denizle birlikte

Ben ağlıyorum göz yaşlarım selmişçesine

Belki hırçın deniz de ağlıyordu benimle 

Karanlık denizin hırçın dalgaları

Sahili dövüyordu var gücüyle

Rüzgar ağıt yakıyordu

Yıkılan tüm aşklar üstüne

Kayalar inim inim inliyordu

Hıçkırıklarımı gizlemek istercesine

Neden terk ettin beni neden

Suçum  neydi söylemeden

Hani çok seviyordun beni

Hani terk edersen ölürüm diyordun

Kaç gün oldu sensizliğe mahkum edişin

Mutlu edebildi mi seni terk edişin 

Yalnız değilim bu karanlığın içinde

Mutluluktan uçtuğumuz günlerimizin

Anıları oldu can yoldaşım

Umarsızım yokluğuna alışacağım

Bir gün pişmanlıklarla burkulursa yüreğin

Ne olur dönme bana 

Yine terk edersin diye korkarım

                		

5 Temmuz 2002', 'Sabahı olmayan bir gecede Çıkıp kentin karanlık sokaklarında dolaştım Yokluğun sinmiş bu karanlık sokaklara Ayaklarım sürüklüyor beni  Her z...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yokluguna-alisamadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Ağlıyorsan', 've-agliyorsan-hasan-koruk-96ewz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siyah gözlerine bantlar çekilmişse

Ve ağlıyorsan

Ve ıstırabını duyuracağın kimsen yoksa

Gülüyorlarsa

Anlamıyorlarsa

Ve sen gözlerindeki siyah bantlara isyan ediyorsan

İnanıyorsan isyanın doğruluğuna

Bil ki

Serzenişler yankı bulduğunda nefesinde 

Titreyecek bir kez daha korkaklar

Ve ağlıyorlarsa gözyaşlarına hakim olamadan mazlumlar 

Ve sen bantlara ve gözyaşlarına inat 

Seviyorsan isyanı

Ağlatanlara sorulacaktır mutlak hesabı

Siyah gözlerine bantlar çekilmişse 

Ve ağlıyorsan

Ve ıstırabını duyuracağın kimsen yoksa

Medeniyet dersi veriyorsa canavarlar 

Ve öldürüyorlarsa insanları sokaklarda 

Acımıyorlarsa

Acımayacaksın

Sevmiyorlarsa seni 

Israr etmeyeceksin 

Acının ne denli bir şey olduğunu tattırıyorlarsa sana 

Acıyacağını bilsen de 

Sökeceksin siyah bantları gözlerinden

Acının kamçılayan gücünden destekle 

Acıtacaksın

Acımıyorlarsa insanlarına 

Hesap zamanını bekleyeceksin

Siyah gözlerine bantlar çekilmişse 

Ve ağlıyorsan

Ve ıstırabını duyuracağın kimsen yoksa

Kirletiyorlarsa kadınlarını 

Bebekleri artık ağlatmıyorlarsa 

Çağ sana kalpsizliğini ispata çalışıyorsa 

Sen mazlumların çığlıklarına umarsız olanları 

Umursamayacaksın

Kılıçlar çekildiyse üzerine 

Gülleri bahçelerinde bırakacaksın

Ve karanfilleri hiç ama hiç ağlatmayacaksın', 'Siyah gözlerine bantlar çekilmişse Ve ağlıyorsan Ve ıstırabını duyuracağın kimsen yoksa Gülüyorlarsa Anlamıyorlarsa Ve sen gözlerindeki siya...', ARRAY['Türk Edebiyatı','Şiir','Hasan Körük']::text[], 8.5, '{"poet":"Hasan Körük","poet_slug":"hasan-koruk","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ve-agliyorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlıkları Yutar Oldum', 'cigliklari-yutar-oldum-hasan-koruk-o25oc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çığlıkları yutar oldum

Acıyı gömdüğüm kabirleri bağrımda taşırken 

İsyan yudumlarını içtim Srebrenica ile 

Kızgınlığımın boyutunu bilseydim de 

Lanetlerin uçuştuğu diyarlardan bir lanette ben okuyacaktım

Bilemedim alevlerin bu kadar yakıcı, çığlıkların bu kadar sahih olduğunu

Küçüktüm 

İsyan cümleleri için gerekli olan kelimeleri ararken 

1995’ti

Ve laneti öğrendim ilk 

Boşnakların gözlerindeki cesareti 

Müslümanlardaki korkaklığı

Medeniyetin canavarlığını 

Çığlıkları yutar oldum

Acıyı gömdüğüm kabirleri bağrımda taşırken 

İsyan yudumlarını içtim Srebrenica ile 

Gözyaşlarının acıları dindirmediğini anladığımda ölüyorlardı

Ve çağa kılıç çekiyordum 

Don Kişot cesareti bile kalmayan yeryüzünde 

Utanıyordum

Ellerim yetmiyordu haya duygularımı örtmeye

Acıyı gömdüğüm kabirleri taşırken bağrımda 

İniltilere gülüyordum

Ve kıskaca alınan kalbime inat

Susuyordum

Zalim olmamıştı hiçbir çağ bu kadar 

Toprak hiç bu kadar kan yutmamıştı

Savaşların mübah olduğu başka bir zaman yoktu

Kanın rengi bu kadar hakim değildi hayatımıza 

Çığlıklarla konuşmamıştık hiç

Ve ölüm bu kadar yakın ve acı değildi bize...

Anlamıyordum...

Sana döndüğüm zaman Srebrenica 

Artık kederlenemiyorum

Siyahlaşan kalbim taş kesildi ama 

Çığlılarını göğsümde eritmeyi denemedim hiç, biliyorsun

Ayaklarımı sürüyemedim sana doğru

Ben seni tanıdıktan sonra korktum hesap gününden 

Sana ağladıktan sonra ağlamanın artık hükmü kalmadığına inandım

Ve utandım insanlığımdan 

Ama bil ki Srebrenica 

Çağla hesabımız başladığı zaman 

Gülle geleceğiz yanına

Rengini kanınla yıkadığımız gülle 

Kındaki silahların çokluğuna inat 

Hesap gününü bekleyeceğiz 

Ama bil ki Srebrenica 

Zalim çağ özür dilediğinde senden 

Mağrurluğun semalardan görülecek

Ve korkaklar bakarken yüzüne utanmayacaklar', 'Çığlıkları yutar oldum Acıyı gömdüğüm kabirleri bağrımda taşırken  İsyan yudumlarını içtim Srebrenica ile  Kızgınlığımın boyutunu bilseydim ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Körük']::text[], 8.5, '{"poet":"Hasan Körük","poet_slug":"hasan-koruk","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/cigliklari-yutar-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezerim', 'gezerim-hasan-koruk-t1cou', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her akşam yalnızlığını paylaştığım kader 

Hicranınla iki büklüm yaşar gezerim

Gülendam nasiyelerinde buruk bir keder

Hep seni düşler sana aşık gezerim 

Her saniye aldığım nefes duyduğum haz

Sana meftun gönlümle seni özlerim

Bugün yaşadığım hayat duyduğum sevda

Bir başka duruşunla sana aşık gezerim

Her akşam uçtuğum dünya, gördüğüm rüya

Sana has bakışınla, seni yaşarım

Zihnimde ördüğüm vefalı hülya

Sana dilhun lisanımla sana aşık gezerim

Sen çektiğim çile, yaşadığım gizem

Sen billur dünyanı saklayan beste

Sen özlem dolu hayatta yaşanmamış saniye

Sana tutkun, sana vurgun, sana aşık gezerim.', 'Her akşam yalnızlığını paylaştığım kader  Hicranınla iki büklüm yaşar gezerim Gülendam nasiyelerinde buruk bir keder Hep seni düşler sana aş...', ARRAY['Türk Edebiyatı','Şiir','Hasan Körük']::text[], 8.5, '{"poet":"Hasan Körük","poet_slug":"hasan-koruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gezerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesizlik Sarmalı', 'sesizlik-sarmali-cemal-muhtar-qluph', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hışırdayan heybetiyle

bir çınar gövdesini kemiren, 

gittikçe büyüyen ağzımın

zifiri sessizliğinde

uçuşan ateş böceklerini barındıran karanlığımdayım.

bir umut, 

gözde yeşeren bir damla tomurcuk.

ötesi; 

hiçde hoş olmayan çıkmazlar.

düşüncede kalan, 

sessiz, 

belirsiz umutlar.

beklenen ve sonuç

birbirinden farklı iki arkadaş.

yaşananlar, 

hayale yakın.

gerçekse, 

daha tanıdık bir deyim: 

hayal kırıklığı...

teselliyi yetersiz kılan, 

başka şeyler düşünmekteki tezat.

pembe panjurlu düşler sonrası

el değmemiş bir bedene işkence tahribatı veren kabuslar.

gerçeğe yenik düşen umutlar, 

uykuya direnen gözler gibi.

nefes nefes tüketiyorum; 

polenleri, 

maykları, 

dumanları.

artan

azalan 

kaybolan otomobil sesleriyle

dağıtıyorum sessizliğimi.

05 07 2002', 'hışırdayan heybetiyle bir çınar gövdesini kemiren,  gittikçe büyüyen ağzımın zifiri sessizliğinde uçuşan ateş böceklerini barındıran karanlı...', ARRAY['Türk Edebiyatı','Şiir','Cemal Muhtar']::text[], 8.5, '{"poet":"Cemal Muhtar","poet_slug":"cemal-muhtar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sesizlik-sarmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımlarımla Alışılan Zincirler', 'adimlarimla-alisilan-zincirler-muhammet-umut-dilek-x3caq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aşkları anlatırdım eskiden,                         

ilk aşkları, son aşkları                            

şimdi militan gömleği                               

giydirdim yüreğime.                                 

heyhat ellerim çoktan bağlı                       

habersizce giydirilen                               

deli gömleğiyle...                                  

ödevlerini yapmamış                                 

ilkokul çocuğumuyum?                                

başımı öne eğmiş,                                   

kendime layık gördüğüm,                             

felaketlerimi bekliyorum...                         

                                                    

              hep aşk şiirleri okurdum,             

              sevgili gözlerine bakarak.            

              şimdi boğazımda halkımı boğan ilmik   

              yarıda kesiyor gülüşlerimi bile..     

                                        her özgür

hissedişimde kendimi,                               

             bir şimşek iniyor tepemden.            

                               ikiye bölerek bedenimi.

                                             bir

tarafım aşka devam diyor,                           

                   sırası değil sevmenin            

                                oyalanma diyor diğer

tarafım.                                            

 yırt parçala                                       

     yüzüne gülerek çektikleri                      

                    pembe tülü                      

                          çünkü engellenirse tavafın

                                             mekkede

mekke değildir                                      

      yakın geçmişten bir şair                      

                           ''sen bir devsin''diyor.   

                                    devin ayakları

kesik, kolları bağlı                                 

              artık merhamet dileniyor...           

                             kaç gece uykularımı böler

vicdanım.                                           

kaç gece özgürlük için atılan bi taşta              

sen ol der.                                         

       ama ben korkak, tembel ve miskin              

                                edebiyat parçalar, 

felsefeler böler,                                   

           kendimi hala adam sanırım.......

		

Muhammet Umut Dilek', 'aşkları anlatırdım eskiden,                          ilk aşkları, son aşkları                             şimdi militan gömleği             ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Umut Dilek']::text[], 8.5, '{"poet":"Muhammet Umut Dilek","poet_slug":"muhammet-umut-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/adimlarimla-alisilan-zincirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum Gidecekdin Bir Gün Bu Şehirden', 'biliyorum-gidecekdin-bir-gun-bu-sehirden-muhammet-umut-dilek-pibzq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorum Gidecekdin Bir Gün Bu Şehirden 

		                       biliyorum bir gün bu şehirden

gideccek, mazine  gömeceksin beni...

                              giderken, 

yüreğinde bastırdığın bir sevinç, 

                 benimse gözlerimden alev alev

akarken anılarım, 

buruk bir vedayla yollayacağım seni yuvana........

                                   gitme diye

bağırmak isterken semaya, 

          isteyen sen olmalısın diye yenik

savaşçı guruyla susacağım.

         biliyorum birgün bu şehirden gidecek

mazine gömeceksin

beni.....................................

dudağımıda simsiyah bir ıslıkla yürürken

yavaş adımlarla

fırtınaya küsen yorgun tayfanın yüreğiyle susacağım

                                         gidişnle

soğuk

akşamları giyerceğim sırtıma.                   

acındırmak için düşmek

isteyeceğim hazan yaprağı olup yoluna ama biliyorum

                             sen üzerime basa basa

gideceksin bu şehirden   .............

                           sen başka

güneşlerin kızıllığında gülerken doya doya

                            seni sensiz

gecelerde yaşayan, 

kendini şiirlerinin mısralarına asan, 

                                 buşairi

hiç düşünmeyeceksin..

bazen anılarımın tatlılığında dalarken

hayallere.yokluğun bir yıln gibi sızarak düşlerime

sarhoş acılar içinde kıvranacağım biliyorum..

                                   birgün bu şehirden

gidecek mazine gömeceksin beni......

                           bir gün birileri

etrafını>şatafatlı gecelerde, 

         iltifat kokan ağızların sardığı

                                 ve  yönünü bulamayan

bir göçmen kuşa benzediğinin haberini getirecek

bana... belkide ben hatırlatıldığımda: 

                     aman bir çocukluktu geldi

geçti deediğinin haberini.....

            o mutlu günlerde gizlice koparıp

sakladığım, sonra bir muska niyetine hep  boynumda

taşıyacağım birkaç saç telini öperken

ağlayacağım biliiyorum........

biliyorum bir kez olsun geleceksin bu şehre.

                                       sensiz sana

yazılan şiirlerimi okurken, gülüp geçeceksin

                                   sen

hala oralardamısın diye...

               bu şehrin her köşesinden sen

çıkacaksın sanarak

her kar yağışında lapa lapa                     

her yağmurda sağnak sağnak

aklıma düceksin......bilyorum yalnızlığımla

başbaşa bırakarak  bu

şehirde yaşadığın her günü yanıllgı günleri sayıp

unutacak beni mazine gömeceksin....

		

Muhammet Umut Dilek', 'Biliyorum Gidecekdin Bir Gün Bu Şehirden  		                       biliyorum bir gün bu şehirden gideccek, mazine  gömeceksin beni...       ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Umut Dilek']::text[], 8.5, '{"poet":"Muhammet Umut Dilek","poet_slug":"muhammet-umut-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/biliyorum-gidecekdin-bir-gun-bu-sehirden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-yavuz-sayin-tplxl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün evren kahverengi olmalı 

Yedi rengi birden gökkuşağının

Uzanan her testiye çeşmelerden

Kahverengi dolmalı

Düşün; bahar gelince çiçek, 

Kahverengi açacak.

Bu renkle dokuyacak kelebek ipeğini...

Toprakana aslını koruyacak...

Bütün gelinlerin duvağı, 

Ve yazması anaların, 

kahverengi olacak...

Bilirim bunlar hayal hiçbiri olmayacak; 

Deniz mavi, gül kızıl, saçın sarı, yüzün ak, 

Aklımda kahverengi tek gözlerin kalacak...

                                   (Ankara 2002) asena...', 'Bütün evren kahverengi olmalı  Yedi rengi birden gökkuşağının Uzanan her testiye çeşmelerden Kahverengi dolmalı Düşün; bahar gelince çiçek, ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sayın']::text[], 8.5, '{"poet":"Yavuz Sayın","poet_slug":"yavuz-sayin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayal-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bra Were', 'bra-were-sair-sondxwar-lianl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kiz çon seré çiyané, 

Bra were meydané.

Ma te namus nemane, 

Bra were meydané.

Wexté mezıvıstane, 

Lı me hat ba u barane, 

Rakır çité konane, 

Bra were meydané.

Lı péş berf u baroze, 

Lı pey me şer u taroze, 

Karé me da u doze, 

Bra were meydané.', 'Kiz çon seré çiyané,  Bra were meydané. Ma te namus nemane,  Bra were meydané. Wexté mezıvıstane,  Lı me hat ba u barane,  Rakır çité konane...', ARRAY['Türk Edebiyatı','Şiir','Şair Sondxwar']::text[], 8.5, '{"poet":"Şair Sondxwar","poet_slug":"sair-sondxwar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bra-were-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yat ve Uyu!', 'yat-ve-uyu-sabahattin-ali-ju5u9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu karanlık, bu uzun kış gecelerinde...

Soğuk, buzdan bir perdeyle süslerken camı, 

Dolaşırken birçok siyah gölge odamı, 

Damarımda kurşunlaşıp donarken kanım; 

Yine seni düşünmekle geçer zamanım...

Bu kimsesiz... Bu mahzun kış gecelerinde...

Serpilirken pencereme avuç avuç kar...

İçerimde hicranlardan bir nehir akar...

Karların da lambam gibi rengi sarıdır...

Onlar yırtık bir mektubun parçalarıdır: 

Rüzgar, sana yazdığımı geri getirdi...

Pencereden dondurucu bir nefes girdi...

Rüzgar yaptı her çatıda ayrı bir makam...

Yine senin hayalini gördüm bu akşam...

Hançeremden alev gibi çıktı bu çığlık: 

-Git istemem! .. Git istemem! .. Çık odamdan çık! ..

Ah! .. Ne dedim? . Hayır gitme.. Hayır gitme... Gel! ..

Ben git dedim, dedim ama sen işitme... Gel! ..

Sensin beni en onulmaz yerimden vuran, 

Fakat sensin yine boş ömrü dolduran...

Bu çılgının senden başka muini var mı? ..

Gitme... Beni senden başka kimse anlar mı? ..

Gözlerimi sen ki başka bir ufka açtın...

Nerdesin ya? .. Nerdesin ya? .. Ah neden kaçtın? ..

Yapyalnızım... Etrafımda yok senden bir iz...

Odam sessiz... Dışarda yağan kar sessiz...

Bu geceler dayanılır gibi değil ki...

Ey şimdi bu satırları okuyan bil ki: 

Istıraplar yüz katlı kış gecelerinde...

Fakat kızgın yanardağlar çıksa bağrımda, 

Senin için ben her derde katlanırım da

Derim ki: ''Bu gecelerin ızdırabiyle, 

Ben ağlasam, harap olsam, çıldırsam bile; 

Sen ateşli vücudunla ısınan rahat, 

Yatağında bir rahibe saffetiyle yat...

Yat ve uyu! .. Bu tatlı kış gecelerinde...''

(1928)', 'Bu karanlık, bu uzun kış gecelerinde... Soğuk, buzdan bir perdeyle süslerken camı,  Dolaşırken birçok siyah gölge odamı,  Damarımda kurşunla...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Ali']::text[], 8.5, '{"poet":"Sabahattin Ali","poet_slug":"sabahattin-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yat-ve-uyu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kayıp - Sanık', 'kayip-sanik-mustafa-engin-karatay-p4p45', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben, beni aradım hayli zamandır; 

Nerede kayboldum çıkmadı bilen...

Çoğaldı etrâfta, ne de yamandır; 

Bir meczûb mîsâli hâlime gülen...

Gözlerim kaç gece kaldı uyanık

Atmayan şafaklar yegâne tanık

Ve ben; ben, îdâmı istenen sanık; 

Urgansız, sehpâsız, her sabah ölen...

14.03.2002    Münih-Grosshadern    02: 40', 'Ben, beni aradım hayli zamandır;  Nerede kayboldum çıkmadı bilen... Çoğaldı etrâfta, ne de yamandır;  Bir meczûb mîsâli hâlime gülen... Gözl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kayip-sanik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana Niye Kızdın Ki? ...', 'sen-bana-niye-kizdin-ki-ceyhun-yilmaz-6sbly', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne yani sahiden böyle mi gidiyorsun? 

Ama ben hazır değilim ki sensizliğe

Beslediğim kuşlara ne derim? 

Gitmesen ben belki bekleyemem

Özlediğim iç çekişleri, 

Beklediğim cevapsız telefonları

Ve dünden ağır bugünleri

Yalnız yalnızlıklarla nasıl taşırım ben? 

Sigaramdan duman çıkmazsa birgün

Ben dünden de üzgünüm...

Bilme diye bulutlara aşık gibi bakıyorum gökyüzüne

Sen sev diye nerde başka sevda görsem

Elimle kapatıyorum yüzümü

Sen hiç sormuyorsun hüznümü

Seni seviyorum hep sen bilmiyorsun

Güneş varken ısınmaz her sevginin içi

Soğukta ayırırsın gülümseyişimi

Hüzünden gözleri yağmur rengi bu aşkın

Ağladığında görünmez bu yüzden

Anlamıştım zaten, durmazdın baktığım yerde

Biliyorum olmazdı, kirpiklerin yüzüme değmezdi! 

Bile bile sevdim heyecanlanmayı

Güzeldi, sevgim çok güzeldi

Yüreğimin seni sevmesini sevdim

Sen bana niye kızdın ki? ...', 'Ne yani sahiden böyle mi gidiyorsun?  Ama ben hazır değilim ki sensizliğe Beslediğim kuşlara ne derim?  Gitmesen ben belki bekleyemem Özledi...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-bana-niye-kizdin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahve Gözlerin', 'kahve-gozlerin-erturk-tastan-85gr4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözlerin varya kahve gözlerin

bir bakışta kendimden geçerim

istemem bu an hiç bitmesin

son bulsun gözlerinde bu serseri bedenim

sen kapatırsan kahve gözlerini

beni bir karanlık sarar sanki

işte bundandır gözlerine hayranlıgım

senin kahvece bakışına hastayım

benimde gölerim kahvedir

bakıpta sende gözlerime dalıver

kelimeler birşey ifade etmesin

bırak gözlerimiz herşeyi anlatsın', 'gözlerin varya kahve gözlerin bir bakışta kendimden geçerim istemem bu an hiç bitmesin son bulsun gözlerinde bu serseri bedenim sen kapatırs...', ARRAY['Türk Edebiyatı','Şiir','Ertürk Taştan']::text[], 8.5, '{"poet":"Ertürk Taştan","poet_slug":"erturk-tastan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kahve-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoklugun', 'yoklugun-erturk-tastan-mh4c8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şimdi senin yoklıugunu ben

köne bir odada bir başıma

rutubet kokan duvarlar arasında

içime çekiyorum bir yudum birayla

şu zıkkımda olmasa olmuyor

iki tek atınca havaya giriyorum

birde cıgaramdan çektimmi

işte oan seni unutuyorum

onun içindir sen gittiyinden beri

hergünümü sarhoş geçiriyorum

artık seni düşünmek istemiyorum

bu yüzden beynimi uyuşturuyorum', 'şimdi senin yoklıugunu ben köne bir odada bir başıma rutubet kokan duvarlar arasında içime çekiyorum bir yudum birayla şu zıkkımda olmasa ol...', ARRAY['Türk Edebiyatı','Şiir','Ertürk Taştan']::text[], 8.5, '{"poet":"Ertürk Taştan","poet_slug":"erturk-tastan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yoklugun-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidemezsimn', 'gidemezsimn-erturk-tastan-ejkz3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'biz seninle sıradan

bir aşk yaşamadık biliyorsun

yoklugunda agladıysam

varlıgında güldüysem

şimdi gidemezsin

bana beni anlatmalısın

sonra kendini sunmalısın 

ve büyük sevgimizden 

bahsetmelisin bana

böylece çekip gidemezsin

içimde başlar yangınlar

bir sızı çöker hasta kalbime

seni ararım bütün sokaklarda

yalvarırım dönmen için tanrıya

seni bu şehirde bırakıp gidemem

inanmıyorum gittiyine senin

dönüp geleceksin umudumvar 

yine sevecek yine saracaksın

lakin zaman geçiyor biliyorsun

ölmeden bana dönmeli ve görmelisin', 'biz seninle sıradan bir aşk yaşamadık biliyorsun yoklugunda agladıysam varlıgında güldüysem şimdi gidemezsin bana beni anlatmalısın sonra ke...', ARRAY['Türk Edebiyatı','Şiir','Ertürk Taştan']::text[], 8.5, '{"poet":"Ertürk Taştan","poet_slug":"erturk-tastan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidemezsimn-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapa Gözlerini..', 'kapa-gozlerini-hasim-altunsoy-4u9wi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bilmem kaç bahar yaşatmaya yeter 

suskun rüzgarlar ruhumuzu. 

bilmem kaç yürek bekler 

kapı aralığında akşamların. 

en çaresiz anlarının, 

ve en acımasız sevgilerin, 

sedef kakmalı 

yaldızlı gülücükleriyle ıslanmadan yaşamak... 

ilk dokunuşların adrenalini sinmişse geceye, 

her sabah devam etmekteyse düşlerin, 

kendine kanıtlayamamışsan varoluşunu, 

hala düşlemekteysen 

kaçmaya çalışırken sevgilinin terli yüzünden, 

tek yolu vardır artık bir solukta haykırmanın...', 'bilmem kaç bahar yaşatmaya yeter  suskun rüzgarlar ruhumuzu.  bilmem kaç yürek bekler  kapı aralığında akşamların.  en çaresiz anlarının,  v...', ARRAY['Türk Edebiyatı','Şiir','Haşim Altunsoy']::text[], 8.5, '{"poet":"Haşim Altunsoy","poet_slug":"hasim-altunsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kapa-gozlerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Son', 'bu-gece-son-oguzkan-bolukbasi-msft1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu gece son 

yaşamakta seni aradığım

ve sensiz nelere alışacağım 

onları bulacağım

bu gece son 

seni düşünüp ağlayacağım

yeni hayatlara yelken açacağım

ve son yalanımı da 

bunları sana yazarken söyleyeceğim', 'bu gece son  yaşamakta seni aradığım ve sensiz nelere alışacağım  onları bulacağım bu gece son  seni düşünüp ağlayacağım yeni hayatlara yelk...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-gece-son-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özür', 'ozur-faruk-aysoy-xd2gx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgiler başlar aşkla

Her taraf pembe, 

Gönüller kadife esintisi, 

Dillerde ise sevgi ezgileri...

Bitmez bir ömür boyu, 

Yaşamla sürer gönül yolu, 

Kalbinde kopar fırtınalar, 

Parlar ateş pınarları...

Yalanlarla söner güzelliği, 

Öfkeye dönüştürür herşeyi, 

Ama bitmez, tükenmez aşk çeşmeleri, 

Her ne olursa olsun gönül bekler bir özür ve de sevgiyi...

Bu böyle sürer gider, 

Belki süründürür merhametsiz acılarıyla, 

Belki aşındırır yürekleri amansızca, 

Ama asla dönmez geri bir özür gelmedikçe; af dilenmedikçe...', 'Sevgiler başlar aşkla Her taraf pembe,  Gönüller kadife esintisi,  Dillerde ise sevgi ezgileri... Bitmez bir ömür boyu,  Yaşamla sürer gönül...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlıklar', 'cigliklar-muhammet-umut-dilek-9nlo3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yağmurlarla

söyleşiyorum,                           

döküyorum, dertlerimi gözyaşlarımı.                  

tomurcuklar seviniyor,                              

fidanlar şükür diyor.                               

bir kurşun vınlıyor kulak tozumda                   

filistinli bir çocuk düşüyor,                       

kendi toprağı olan gurbetinde                       

bir bülbül ah vatan diyor......                     

panzerler eziyor,                                   

bir çeçen yüreğini,                                 

panzeri cesediyle parçalıyor,                       

özgürlük katillerini,                               

ölümüyle cezalandırıyor......                       

nükleer artıkların asit yağmurları,                 

sende''TÜKÜR''                                        

TÜKÜR DİYOR DÜNYAYA.....                            

                                                    

            bir genç gömüyor yıllarını,             

            fakülte denilen ''aile şirketlerine''     

            yüreğini parçalarken her gece,          

            aldığı zayıf notları...                 

            yalnız ve soğuk sofrasında, ,            

            pişmanlık zeytinini yerken,             

            bir mantar bitiyor Hiroşimadan...       

            gelecekten sakat çocuklar ağlıyor.      

            anneler umutsuz                         

            sende''TÜKÜR                             

            TÜKÜR DİYOR DÜNYAYA....''                

                                                    

                                                    

                        sokaklar döner bıçaklı

psikopat                        geceler, zilzurna

ayyaş.                               şehri kusmuklara

boğuyor.                              ayaklarım

emrediyor,                                   gözlerini

kapat.                                       gözlerim

koş diyor,                                    uzaklara

koş...                                        okumaya

yollanmış bakireler,                        

fahişelikle paralara doyuyor.                       

çiğ damlası ağlayan çiçekler,                       

sende''TÜKÜR                                         

TÜKÜR DİYOR DÜNYAYA...                              

                                                    

            mecnun leylasından nefret ediyor,       

            aslı göbek atarken zengin evlerde,      

            ferhatler zar sallıyor dağın dibinde... 

            peygamber ''bitir diyor ey RABBİM.       

            kalmadı artık ümmetim,                  

            yıkılsın gökkubbe,                      

            kurulsun mizan,                         

            açılsın cehennem...''                    

            nezaketten ırak şöförlerin sıçrattığı

çamur,           sende''TÜKÜR                        

                 TÜKÜR DİYOR DÜNYAYA..              

                                                    

                             bir çocuk ölüyor,      

                             bir yürek eziliyor,    

                             bir bakire kirleniyor, 

                             bir delikanlı tükeniyor, 

                             bir ferhat psikopat    

                      

bir aslı iffete tokat,                             

bir yerde ölürken açlıktan insanlar,               

biryede altın kaplarda doyar hayvanlar,            

ALLAH''ım ''TÜKÜR                                     

SENDE TÜKÜR DÜNYAYA,                               

ÇÜNKÜ EN SON BEN TÜKÜRECEĞİM....''                   

                 ''İNNA LİLLAH VE İNNA İLEYHİ

RACİUN...''', 'yağmurlarla söyleşiyorum,                            döküyorum, dertlerimi gözyaşlarımı.                   tomurcuklar seviniyor,           ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Umut Dilek']::text[], 8.5, '{"poet":"Muhammet Umut Dilek","poet_slug":"muhammet-umut-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/cigliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mermiden Gülüşün Vardı Senin', 'mermiden-gulusun-vardi-senin-muhammet-umut-dilek-d96ao', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mezarları sevdirirdin hep bana          

           mermiden gülüşün vardı senin.            

          seccade koltuğumda öksüz,                 

         dualar korkatı yüreğimde.                  

        yönünü bilemeyen,                           

       sarhoş anılarla yaşarken,                    

      düşlerimde hep,                               

     mermiden gülüşün vardı....                     

                                                    

                     tanrı çizmiş bıçağıyla,        

                    kaderimi alnıma.                

                   kaçak bir mahkum sayarak beni.   

                  kalabalıktan biri olsamda,        

                 korkak parmaklar gösterir beni.    

                geceler, boğazıma geçirmiş pençesini

                geceler, karanlık gözlerle mermi

kusmakta              madeni hıçkırıklar            

                      kaçırırken uykumu,            

                      tanırım seni ey ölüm          

                      saklanma...                   

                      mermiden gülüşün vardı senin....

                                                    

                                             gücünü

öfkemden alırken,                               hayat

sahnesinin yalan dostları,                    

yalnızlığım, hayatımın tek sırdaşı,                  

senide kaçırır, bu gürültüler...                     

volta atarken paranın yoldaşları,                   

kanaryalarsa hapiste.                               

seslerine takılmış kirli bir çığlık,                

yakıyor mazimin mutluluğunu                         

gel artık usandım,                                  

saklanma ey ölüm                                    

mermiden gülüşün vardı senin...

		

Muhammet Umut Dilek', 'mezarları sevdirirdin hep bana                      mermiden gülüşün vardı senin.                       seccade koltuğumda öksüz,           ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Umut Dilek']::text[], 8.5, '{"poet":"Muhammet Umut Dilek","poet_slug":"muhammet-umut-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mermiden-gulusun-vardi-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Yaşadığımı Sanıyorum', 'neden-yasadigimi-saniyorum-muhammet-umut-dilek-5hy4e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ölü zamanların gezinen cesetinden                   

                  helede yalnızlığın kafesinden     

                                     usanıpta çekip

gitmek                                             

varken,                                            

adımlarımı sayan kaldırımlardan başka               

                                beni ciddiye alan

yokken                                              

neden hala yaşadığımı sanıyorum?                    

                                                    

                      dalga geçerken aynalar,       

                                     tükürürken mazime

                                             

kelimeler,                                          

halatın ucunda sallanarak,                          

               boş boş bakarken çevreme,            

                                zaman vururken davul

tokmağı gibi                                        

       tiktaklarını beynime                         

                    neden hala yaşadığımı sanıyorum?

                                                    

                                          uzanmam

gereken gül mü kaldı?                               

               dinlemem gereken bülbül mü?          

                                       yoksa aşk

sözcüklerimi bekler hala yüreğim?                   

                         ilkbaharmı geri geldi?     

                                         yüreğimi

kışlar mı geri verdi?                               

               hazır yabancıyken her şey bana,      

                                        çekip

gitmeliyim, çekip gitmeli...                         

                 heyhat adımlarım unutmuş gitmeyi,  

                                          ellerimden

yardım bekliyor                                     

       yeniden öğrenmeliyim emeklemeyi....          

                                                    

                            yoksa bir asamı

bulmalıyım?                                         

bir sonbahar ağacından koparıp,                     

                       kurumuş yapraklarından

kurtardığım.                                        

ben mi asa olmalıyım yoksa?                         

                     hala çözemediğim hayatın,      

                                      çirkef

labirentlerini yıkacak....                          

               ayağımı kaydırırken,                 

                       az önceki kelimelerin tükrüğü, 

                                            çözemezken

yüreğimdeki,                                        

iskender düğümünü,                                  

         neden hala yaşadığımı sanıyorum? ...        

                                                    

                              kendim mi güneş

olmalıyım mazime?                                   

          konuşabileceğim bir aymı bulmalıyım?      

                                  hızırlamı gezmeliyim

zamanda?                                           

geçmişime geleceğime hediyelermi göndermeliyim?     

                                 yıkıp yeniden bir

şeyleri                                             

keyfime göre yeniden mi yapmalıyım?                 

                       terkedenleri ellerinden tutup

                                            

yüreğimdemi hapsetmeliyim?                          

            nasılmı yapacağım?                      

                    bilmiyorum.                     

                    insanım işte.                   

                                hala yaşadığımı

sanıyorum.............

		

Muhammet Umut Dilek', 'ölü zamanların gezinen cesetinden                                      helede yalnızlığın kafesinden                                        ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Umut Dilek']::text[], 8.5, '{"poet":"Muhammet Umut Dilek","poet_slug":"muhammet-umut-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/neden-yasadigimi-saniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Bendim', 'o-bendim-muhammet-umut-dilek-qxhwa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'merhamet gözyaşları

akarken                          

gökyüzünden,     

                                 

özlemleri akarken

gözlerinden                        

bilmeceler

sorarak kendine                         

gencecik bir

kız yürüyordu.                                      

    ve ben şahittim,                                

           gerçekten sevdiğine                      

         gökyüzünden saçlarına düşüp,               

        yanaklarından süzülende  BENDİM...          

                                                    

                              

gitmesini söylemişti

yüreğine,                                           

bilmeden yalnızlığın yıkacağını.                    

                   

sarhoş bir bulut olmuştu       

                                   

ağlayacağı anı

bilemeyen                                           

peşinden gidemeyen                                  

         ben şahittim,                              

         çünkü onu götüren zamanda                  

                           kızı bırakmayan mekanda  

                                           BENDİM   

                                                    

                                       

sevdalımıyım,                                       

karasevdalımıyım                                    

yoksa kendini ortaya koyan                       

deli bir kumarbaz mı yım?                   

sorularla çırpınıyordu                              

       

hastasın diyorlardı doktorlar              

                          

çok üzülmüşsün diyorlardı.

                                         

ama

acısıyla mutluydu o                                 

                  şahittim ben buna                 

                               gülüşündeki

mahzunlukta,                                        

intiharındaki                                   

suçlulukta                                         

BENDİM                                              

                                                    

hissettirebilmişmiydi?                              

onu sevdiğini                                       

    söyleyemediğine yanıyordu.                      

                   sevebilirmiydi ki                

                                  oda? ...              

                                  sorularıyla

tutkusunu çarmıha geriyordu.                        

                  ''ya olmazsa                        

                     ne yaparım tanrım! '',             

                              

diyerek kendini ona

örüyordu.                                           

geleceğin ona hazırladığı                           

             sevdiğinin olmadığı hiç bir hediyeyi

istemiyordu.                                        

korkuyordu                                          

ben şahittim                                        

    çünkü                                           

    ona umut verende                                

             dertlerini dinleyende                  

                        onu bu sevgiye sürükleyende 

                                       BENDİM...

		

Muhammet Umut Dilek', 'merhamet gözyaşları akarken                           gökyüzünden,                                        özlemleri akarken gözlerinden     ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Umut Dilek']::text[], 8.5, '{"poet":"Muhammet Umut Dilek","poet_slug":"muhammet-umut-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/o-bendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntiharım', 'i-ntiharim-muhammet-umut-dilek-8gqkz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yalnizliği çaliyor saat tiktakları

bir maestronun kolları gibi, 

akrep yelkovan.

her hareketiyle zamanı siler.

offf yureğimde bir sıkıntı saatli bomba....

önümde bir paket sigara

gayri ihtiyari uzanıyor ona elim

çakmağın sıcak nefesiyle yakıyorum

.benimle birlikte yanan bir şeyolsun diye...

her nefeste açılan bir yara

ve o iğrenç suratı yuzume vuran

aynadaki lanet görüntü; 

sigara dumanıyla puslanmış

yıkılmış bir evin penceresini andıran, 

dört günden beri silinmemiş bir gözlük arkasından bakanyenik gözler...

offf yureğimde bir sıkıntı saatli bomba.....

sigaram tukendi tukeniyor 

bense hala için için yanıyorum.

aynadaki pislikse hala orada

defolup gitmiyor bana inat.

şimdi sırıtıyorda üstelik, 

o yuzuyleki bir acuze-sanat.

ne yapmalıyımki kurtulmalıyım? 

aynayımı kırmalı? ...

ama hayır! ... 

bana görünmek için başka aynalar bulur...

off yureğimde bir sıkıntı saatli bomba....

buldum yoketmenin yolunu; 

benim gözüme görünemeyecek.

ve o pis suratına başkalarına gösterip rahatsız edemeyecek...

nasılmı yapmalıyım? 

tabiiki jiletle

hemen traş takımıma koşuyorum.

işte başka bir niyetle açmayacağım bir jilet..

bu mukaddes görevi yapacak

mukaddes silahı özenle taşıyarak

yerime dönüyorum..

ve aynada bana pis pis sırıtana

biraz sonra başına getireceğim belayı düşünerek sırıtıyorum....

yureğimde hala bir sıkıntı saatli bomba...

saate takılıyor gözlerim..

akrep ve yel kovan aşkını düşünüyorum son kez.

yelkovanın akrebin etrafında dolanarak, 

ona iltifat etmesini 

ama kabullendirememesini..

ama günün yirmi dört saatinde yirmi dört defa sabırla gayretini

merak etme yelkovan 

onun senden ayrılamayacağı anı vereceğim sana az kaldı.. 

saat dördü yirmi geçiyor..

işte vaktidir diyerek saati yere çalıyorum...

tiktaklar sustu artık..

yelkovan akrebin kollarında ölüm uykusunda..

ama benim yureğimde çalıyor hala saatli bomba...

herbirinden özür dilediğim

yuzu açık masaya yatmış 

benden utanan kitaplarımı okşuyorum...

dönüyorum aynadaki lanet görüntüye 

ve gözlerinin içine baka baka 

yavaşça sürüyorum jileti bileklerime...

ince bir sızıyla beraber kızıl bir yol çiziliyor.

ohh sıcak kan kokusu burnuma geliyor 

güzel bir makyaj olur kan kırmızısı diye

aynadakinin yuzune bulaştırıyorum kanımı.

ve dudaklarını boyuyorum.''

''bir öpücük versene tatlım! '' diyorum..

ve aynadki pislik inadına hala sırıtıyor

''bak sararmiş halimle cimbomluyuz işte'' diye...

gül gül diyorum..

bu senin son gülüşündür.

girdin kafese lanet kuş, 

boşa kanat çırpışındır...

''merak etme diyor...

son gülen hep ben olacağım...

üstelik benim ölümüm sana gülmekten olacak..

kopacağınımı sanırsın benden

cehenneminde bile ben olacağım..''

''hayır rabbim diyorum...

bana vereceğin ceza bununla olmasın...''

''boşa yalvarma diyor

zayıflamış gözlerinle iyi bak ben senim, 

sense ben.

iyi bak saçlarım senin dertlerinle döküldü...

uykusuz geçen gecelerinden dolayı gözlerimde moraran bu halkalar...

yaktın kendini gafil 

her defasında yaptığın gibi 

yine yanlışı seçtin...''

''sus diyorum 

son defa sus.

yalvarıyorum.''

hırsla aynayı yere çalıyorum...

ohh yureğimdeki saatli bomba sustu susacak..

sendeliyorum.. 

gittikçe puslanıyor görüntü.

gözlerime siyah bir tul geriliyor.

ömer hayyam şarabı bu olsa gerek diyorum...

ölümde olsa sonuçta kim tatmak istemez bu şarabı..

nerdesin ha? 

nerdesin lanet görüntü..

sustun işte

s u s t u r d u m  s e n i  d u r m a  p i s l i k  s ı r ı t s a n a? 

o h  k a y b o l d u 

y u r e ğ i m d e k i  s a a t  s u s t u 

sus+^&''! %&-----------------------

muhammet umut dilek', 'yalnizliği çaliyor saat tiktakları bir maestronun kolları gibi,  akrep yelkovan. her hareketiyle zamanı siler. offf yureğimde bir sıkıntı sa...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Umut Dilek']::text[], 8.5, '{"poet":"Muhammet Umut Dilek","poet_slug":"muhammet-umut-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/intiharim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yol Sana', 'her-yol-sana-ahmet-aka-zs3oc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her yol sana 

Elin yüzün burada

Kaşın gözün burada

Bir tek mutluluk eksik

Bütün hüzün burada

Odamda resim gibi

Tılsımlı cisim gibi

Her yol sana çıkıyor

Sanki adresim gibi', 'Her yol sana  Elin yüzün burada Kaşın gözün burada Bir tek mutluluk eksik Bütün hüzün burada Odamda resim gibi Tılsımlı cisim gibi Her yol s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/her-yol-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Eller', 'bizim-eller-ahmet-aka-chltb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kekik kokusuna, keklik sesine

Hasretsen çık dağın mor tepesine

Yaylalar, bozkırlar, oy bizim eller

Merhem olur yârin her yaresine

Elde saz, dudakta ney bizim eller

Has baldan yapılmış mey bizim eller

Çık da gel şu bayram arifesine

Şehirler içinde bey bizim eller

Kabul olmuş erenlerin duası

Şifa tatlı suyu temiz havası

Anlatması çok  zor şey bizim eller

Değişmez töresi oldum olası', 'Kekik kokusuna, keklik sesine Hasretsen çık dağın mor tepesine Yaylalar, bozkırlar, oy bizim eller Merhem olur yârin her yaresine Elde saz, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bizim-eller-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Byte', 'byte-sair-bergama-6bynj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dijital bir hadise bu

parmakla sayilir

hata da yapý lsa

geri alinir

sicak islak bir döngü bu

iki ayri ömürle topraklanir

her bölme içinde sekiz parça

birden ikiye kadar sifir dahil

dönerek okuyor

yakılarak yazilanlari

bir çelik bir gümüsü

degmeden izliyor

disindan merkezine dogru

kestirme bir yol ariyor', 'dijital bir hadise bu parmakla sayilir hata da yapý lsa geri alinir sicak islak bir döngü bu iki ayri ömürle topraklanir her bölme içinde se...', ARRAY['Türk Edebiyatı','Şiir','Şair Bergama']::text[], 8.5, '{"poet":"Şair Bergama","poet_slug":"sair-bergama","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/byte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maad', 'maad-sair-bergama-xs5o3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çan -        sağır olmalıydın sen

                Sesin kaynağını ipin çekimine bağlayanlar gibi

                Paslı bir demir gibi salınsam da içinde

                İp adını anlamamın ağırlık noktası sadece

Zemberek -        kör olmalıydın sen buraya bakıp saatini ayarlayanlar gibi

                        Bir ana takılıp kaldığını sansan da beni sana adadılar unutma 

Kule         -        olabildiğiniz kadarsınız ikiniz de

                        Bu ençok benim umurumda 

                         Çünkü her yerden görülebilen benim

                         Sizsiz olamayacağımı düşünseniz de

G              -       amorti edilmiş intiharlarınızdan bıktım

                         espirilerinizi  açıklamanıza gerek yok

Quasimondo  -      kendimi hiç bu kadar  kusursuz hissetmemiştim.', 'Çan -        sağır olmalıydın sen                 Sesin kaynağını ipin çekimine bağlayanlar gibi                 Paslı bir demir gibi salıns...', ARRAY['Türk Edebiyatı','Şiir','Şair Bergama']::text[], 8.5, '{"poet":"Şair Bergama","poet_slug":"sair-bergama","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/maad-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seiza', 'seiza-sair-bergama-q4tdk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir cezadan kurtulanın yaptığıda budur

Kendisine saklayamaz anılarını

Son sözüm bu olmalıydı belki

Flash-back safhasındayım sanırıım ömrümün', 'Bir cezadan kurtulanın yaptığıda budur Kendisine saklayamaz anılarını Son sözüm bu olmalıydı belki Flash-back safhasındayım sanırıım ömrümün...', ARRAY['Türk Edebiyatı','Şiir','Şair Bergama']::text[], 8.5, '{"poet":"Şair Bergama","poet_slug":"sair-bergama","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-adem-tetik-nmhey', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum ne ay ışıiğinda

Nede yıldızların altında

Uzanıp ranzamın tahtalarına

Seni düşünüyorum beni düşümediğin her anında 

Seni düşünüyorum gecenin zifirikaranlığında

Hayalinle baş başa kaldığım heranımda

Seni düşünüyorum attığım voltamda

İçdiğim her sigaramda', 'Seni düşünüyorum ne ay ışıiğinda Nede yıldızların altında Uzanıp ranzamın tahtalarına Seni düşünüyorum beni düşümediğin her anında  Seni düş...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-dusunuyorum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Umutsuzluk', 'i-cimdeki-umutsuzluk-mustafa-sureyya-sezgin-vpfhg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlatması zor içimdeki

Buruk özlemi

Ve yarım kalmış umutlarla

Yudumladığım yoklukları.

Var işte! .. herşey ve herkes

Para, pul, dost, kardeş

Çoluk, çocuk, güzel eş! ..

Bu açlık bu susuzluk

Nedendir içimdeki umutsuzluk? 

İkiye bölünürken benliğim

Kafa tutmak isterim yaşama.

Beynimin sol lobunda gerçekler, 

Sağında pembelikler.

Hadi kır zincirleri! 

Kır Hadi! ..

Kıracaksın biliyorum.

Kurtar özgürlüğünü kavrayacak elleri! ..

Tükenişe yürüyorsun, 

Biliyorsun 

Ve görüyorsun, 

Durduramıyorsun zamanı.

Sahnedeki oyunun konusu belli artık, 

Oyuncular da belli.

Yaş otuzbeş veya elli

Ne çıkar bundan? 

Yak bir sigara

Tüttür dumanını enginlere dalarak

Ve yeni hayallerle oyalanarak! ..

(İstanbul,14.07.1988)', 'Anlatması zor içimdeki Buruk özlemi Ve yarım kalmış umutlarla Yudumladığım yoklukları. Var işte! .. herşey ve herkes Para, pul, dost, kardeş...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/icimdeki-umutsuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgulama (1)', 'sorgulama-1-mustafa-sureyya-sezgin-bf8m4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her duygumu

Her düşlediğimi

Söyleyebilseydim

Nasıl bir biçim alırdı dünyam? 

Kırmızı yine kırmızı, 

Yeşil yine yeşil olur muydu? 

Ağlayanla gülen, 

Ezilenle ezen

Hangi konumlara otururdu? 

Ve hani değer yargılarıyla

İyiye iyi, 

Kötüye kötü derdim? 

(İstanbul,28.10.1976)', 'Her duygumu Her düşlediğimi Söyleyebilseydim Nasıl bir biçim alırdı dünyam?  Kırmızı yine kırmızı,  Yeşil yine yeşil olur muydu?  Ağlayanla ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sorgulama-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keder', 'keder-mustafa-sureyya-sezgin-mgksk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine bir keder aldı bu gece

Bütün benliğimi

Bir hüzün sardı.

Bu gece, 

Sen hayalime gelince.

Gönlüm sonbaharda sandı kendini.

O yeşil yaprakları döktü birer birer.

Halbuki ne ümitlerle yeşermişti onlar.

Şimdi kuru dallar var içimde, 

Batar, 

Birer birer parçalar gönlümü.

Düşündükçe seni, 

Süpürmek istiyorum kuru yaprakları.

Ben baharı özlerken

Yapraklar sararıyor

Sevmiyorum bu sonbaharı...

(Bolvadin,1967)', 'Yine bir keder aldı bu gece Bütün benliğimi Bir hüzün sardı. Bu gece,  Sen hayalime gelince. Gönlüm sonbaharda sandı kendini. O yeşil yaprak...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/keder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah O Gözlerin', 'ah-o-gozlerin-mustafa-sureyya-sezgin-u11tf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soldu bir anda ümitler, 

Bekler her akşam, 

Seni bu gözler...

İki ayrı varlığız, 

Ben ve sevgim.

Sevgim de sen, 

Bense kişiliğimden bıkmışım.

Unutmak istiyorum seni ama, 

Gözlerin gelmese aklıma...

(Bolvadin,1967)', 'Soldu bir anda ümitler,  Bekler her akşam,  Seni bu gözler... İki ayrı varlığız,  Ben ve sevgim. Sevgim de sen,  Bense kişiliğimden bıkmışım...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ah-o-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi Renk', 'yedi-renk-mustafa-sureyya-sezgin-bo0gy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gök kubbeyi delerek geldi

Yedi renk, 

Kimi gözlerini seçti kendine

Kimi dudaklarına yerleşti

Kimi saçlarına...

Rüzgar esintilerinden

Irmak çağlayışlarından

Bülbül şakımasından

Dökülüverdi 

Yedi nota

Kimi gülüş oldu dudaklarına

Kimi şarkı

Kimi inleyiş...

Asırlar yıllara

Yıllar aylara

Ve aylar haftalara bölündü.

Yedi günde oluştu

Bu rengarenk dünyam, 

Yedi kez yattığımda

Seni göreyim diye...

(İstanbul,14.02.1973)', 'Gök kubbeyi delerek geldi Yedi renk,  Kimi gözlerini seçti kendine Kimi dudaklarına yerleşti Kimi saçlarına... Rüzgar esintilerinden Irmak ç...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yedi-renk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzenin Gücü', 'duzenin-gucu-mustafa-sureyya-sezgin-6gnne', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eşilir toprak

Büyük emeklerle.

Toprak eşilir

Tırnaklarla bağrından! ..

Güneşin aleviyle

Damlar terler alınlardan! ..

Tıpkı bir yağmur gibi...

Kadınca sancılanır toprak...

Ve toprak üzerinde bir çiçek, 

Büyür ekinlerin ortasında...

Bu çiçek

Rüzgara, 

Doluya, 

Yağmura gülümseyerek, 

Boy verir ekinlerle birlikte...

Zamanla renklenir yaprakları, 

Alı al, moru mor açarak

Binbir koku saçarak...

Ekin tarlasında, 

Cılız başakların tümü

Hayrandırlar ona

Titrer gönülleri, 

Esirgerler onu

Rüzgardan, kardan, doludan...

Uzaklardan bakarlar, erişmek istemiyle.

Sorarlar sessizce; '' acaba kime? ''

Sancılanır kadınlarımız, 

Ekinlerin ortasında, tıpkı toprak gibi...

Yaşamaya tutkun, kurak umutlarıyla...

Topal, kör, kambur çelimsiz

Ve ardından bir kız doğar, 

Kusursuz! ..

Sevdalanır, Aliler, Memetler, Mustafalar...

Erişmek özlemiyle

Uzaklardan bakarak

Hayallere dalarak, 

Sorarlar; 

''Acaba kime? ''

Sonra...

Döner dünya

Bir kaç kez...

Mevsimler geçer aradan, 

Hasat olunur buğday.

Yoksul eller güçlüye çalışır! ..

Koparılır güzel çiçek! ..

Tüm umutlarıyla, 

Doluyu, fırtınayı unutarak

Güzel bir yerde, 

Yukarılarda, 

Vazolarda! ..

Gelin olmuş

Güzel bir kız

Dillere destan

Bir düğünle beylere...

Topalı köre, körü kambura

Terkederek! ..

Düzenin gücü

Sevgiden de ötede! ..

İşte ekmek! ..

İşte çiçek! ..

Her ikisi de tek elde! ..

K u v v e t l i d e ! ..

(İstanbul,25.06.1976)', 'Eşilir toprak Büyük emeklerle. Toprak eşilir Tırnaklarla bağrından! .. Güneşin aleviyle Damlar terler alınlardan! .. Tıpkı bir yağmur gibi.....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/duzenin-gucu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sihir', 'sihir-mustafa-sureyya-sezgin-liyhr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sihir, büyü, fal, 

Ruhlar, cinler, periler...

Bunlar da olmasa yani

İnsanlar nasıl avunacaklar? 

Arada bir

Kokteyl yapmak gerekli, 

Cinlerle perilerle...

Evde kalmış kızlara; 

''Muradın olacak kızım.''

Elin fakirine; 

''Bol para.''

En kralına bile; 

'' Büyüyeceksin, yükseleceksin, 

Çatlayıncaya, patlayıncaya kadar

Zıkkımlanacaksın.''

Diyeceksin...

Gelin cinler, 

Ey periler! .. Ruhlar gelin...

Sizinle buluşalım, 

Bir açık oturum yapalım.

Belki çıkar yol buluruz

İnsanlığın şu acınacak haline! ..

Kötülerin karşısına gizi çıkarırız.

İyileri sizlerle ödüllendiririz.

Hele bir de, 

Kara sevda problemini

Çözebildik mi..

Deme gitsin, 

Kurtulur bütün dünya! ...

(İstanbul,29.05.1975)', 'Sihir, büyü, fal,  Ruhlar, cinler, periler... Bunlar da olmasa yani İnsanlar nasıl avunacaklar?  Arada bir Kokteyl yapmak gerekli,  Cinlerle...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sihir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Uyurken', 'siz-uyurken-ceyhun-yilmaz-s4e5j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birkaç tanımadık ses gelirse yüreğinizden, 

Belki tanırsınız beni...

Hayatınızın beyaz-güzel sayfalarından, 

Koparılmış olabilir ismim...

Haberinizin olmadığı çay bardaklarına sorun, 

Dudak izlerimden teşhis edebilirmisiniz beni.

Sizi terk etmiş gibi görünsemde, 

Anlayacaksınız gidişimi ayak izlerimden.

Siz uyurken ben! 

Öpüp gittim gözlerinizden! ..', 'Birkaç tanımadık ses gelirse yüreğinizden,  Belki tanırsınız beni... Hayatınızın beyaz-güzel sayfalarından,  Koparılmış olabilir ismim... Ha...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/siz-uyurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadir', 'kadir-yildiray-guney-ydwce', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen Kadiri bilir misin? 

Hani o, balçık tutan geceleri

yar sokağında aydınlatan

yalınayak garibi....

Ve kalabalıklar içinde hayatı

tek başına omuzlamış 

gözü yaşlı galibi...

O ki bazen, 

don yemiş kaldırımlar üstünde

çığırtkan rüzgarın sevgilisi, 

insanlığın aşığı, hakikatin delisi...

Sen Kadiri bilir misin? 

Hani o, güneş emmiş mevsimleri

yanık türküler çağıran

gönlü arsız yiğidi...

Ve çalıntı manalı kelimelerin içinde

yitik sanatı arayan

yüreği darda  Şairi....

O ki, kıraç gönüllere

sevda emanet etmiş, 

güvenin hasat vakti ipe çekilmiş....', 'Sen Kadiri bilir misin?  Hani o, balçık tutan geceleri yar sokağında aydınlatan yalınayak garibi.... Ve kalabalıklar içinde hayatı tek başın...', ARRAY['Türk Edebiyatı','Şiir','Yıldıray Güney']::text[], 8.5, '{"poet":"Yıldıray Güney","poet_slug":"yildiray-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kadir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ele Verme Kendini...', 'ele-verme-kendini-hasim-altunsoy-gvmsn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tuhaf bir maske oldu akşam

bir şeyler kayıyor 

ayaklarımın altından

uzaklaşıyorsun...

yokluğuna doğuyorum şimdi.

daha uzun geçecek geceler, 

ve daha acı

papatyalara bakmak...

kollarımın bağı çözülmeyecek

yüreğe dar gelmeyecek 

can kafesi...

sesin olmayacak

gülüşün

ürkekliğin...

gitme diyemiyorum

gideceksin.

uyanacaksın gerçeklerine.

ben yokluğuna doğarken, 

sen kendini oynayacaksın

sakın ele verme kendini...', 'tuhaf bir maske oldu akşam bir şeyler kayıyor  ayaklarımın altından uzaklaşıyorsun... yokluğuna doğuyorum şimdi. daha uzun geçecek geceler, ...', ARRAY['Türk Edebiyatı','Şiir','Haşim Altunsoy']::text[], 8.5, '{"poet":"Haşim Altunsoy","poet_slug":"hasim-altunsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ele-verme-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Donus Yolu', 'donus-yolu-huseyin-cayikli-xz9pd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'camdan bakiyordum

cok sicak

yalan ayrilikti bu

ve yalan bir yaziydi

mevsimler degisti

anladim yaz geldi 

sokaklarda gezen orospularin sesleri ciglik gibi

igrenc pazarliklari icimi kanatiyor

ve donus yolu

havaalanina kadardi?', 'camdan bakiyordum cok sicak yalan ayrilikti bu ve yalan bir yaziydi mevsimler degisti anladim yaz geldi  sokaklarda gezen orospularin sesler...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/donus-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakim Bey', 'hakim-bey-mehmet-ali-cibikli-oywaz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dinle bak derdimi, ben sana geldim, 

Bir kerecik dinle, sen bana hak ver.

Suçum sevmek benim, birini sevdim, 

Böylesine sevmek, ölümmüş meğer.

Yüz kızartıcı bir suç mu Hakim Bey, 

Sadece onun kalbini çalmıştım.

Mutluyuz ikimiz, yolunda her şey, 

Ben onun olmuştum, onda kalmıştım.

Neden suçlar benim, niçin suçluyum? 

Kader oyununu  bana mı yazmış? 

Nerde kişiliğim, nerde gururum? 

Çektiğim acılar daha mı azmış? 

Masumum Hakim Bey, bırakın beni, 

Suçum sevmek benim, başka suçum yok.

Sevenler anlar, sevenin halini, 

Yanıyor yüreğim, her gün daha çok.

Eğer varsa sende, birazcık sevgi, 

Anlarsın halimi, yazmazsın ceza, 

Duydum ki bir zaman, sen de ben gibi, 

Delice yanmışsın, sevmişsin keza.

İnsaf et Hakim Bey, düştük eline, 

İçim zaten yanık, bir de sen yakma.

Kurtar beni burdan, bak şu gönlüme, 

Yüreğim titriyor, çok kötü bakma.

Son sözüm şu benim, dinle beni bak, 

Ben onu çok sevdim, hem de yürekten.

İster ver cezamı, istersen bırak, 

Hiç pişman olmadım, onu sevmekten.', 'Dinle bak derdimi, ben sana geldim,  Bir kerecik dinle, sen bana hak ver. Suçum sevmek benim, birini sevdim,  Böylesine sevmek, ölümmüş meğe...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hakim-bey-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-mehmet-ali-cibikli-fjdu3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle ben ikimiz, 

Bakışlar hep yukarda.

Eğilmeyiz yere biz, 

Neler varsa orada.

Başımız hep dumanlı, 

Ulu dağlar gibiyiz.

Gururumuz hep canlı, 

Aşka ödün vermeyiz.

Uzayda iki doğru

Parçası gibiyiz biz.

Gelse de ömrün sonu, 

Bir araya gelmeyiz.

Yolumuz ayrı ayrı, 

Herkes kendi yolunda.

Beklemenin yok hayrı, 

Ayrılalım sonunda.

Sana olan sevgimi, 

Verdim gittim birine.

Hiç itiraz etmedi, 

Aldı gitti evine.', 'Seninle ben ikimiz,  Bakışlar hep yukarda. Eğilmeyiz yere biz,  Neler varsa orada. Başımız hep dumanlı,  Ulu dağlar gibiyiz. Gururumuz hep c...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seninle-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlıyor musun? ?', 'anliyor-musun-mustafa-cancer-ibrya', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yıldız parlıyor; 

Sanki gözlerin, 

Dolunay en tepede; 

Sanki gönlün...

Güneş doğuyor sonra; 

Sanki gönlüm, 

Anlıyorsun değil mi? ...', 'Bir yıldız parlıyor;  Sanki gözlerin,  Dolunay en tepede;  Sanki gönlün... Güneş doğuyor sonra;  Sanki gönlüm,  Anlıyorsun değil mi? ......', ARRAY['Türk Edebiyatı','Şiir','Mustafa Cancer']::text[], 8.5, '{"poet":"Mustafa Cancer","poet_slug":"mustafa-cancer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anliyor-musun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanetin Rengi', 'i-hanetin-rengi-nevzat-gurmen-d1xd1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bugün geleceğe

yarın geçmişe ihanet

ödünle beyninden beni

ödülle yüreğinden sil 

affedilmeyen

aşka ihanetin değil

kendine ihanetin var ki

hüznün rengi sarı

ihanetin rengi saçların', 'bugün geleceğe yarın geçmişe ihanet ödünle beyninden beni ödülle yüreğinden sil  affedilmeyen aşka ihanetin değil kendine ihanetin var ki hü...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ihanetin-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yearning', 'yearning-umit-kalender-292m2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yakamoz düşmüş denize 

kalbinin renginde

gözlerin kadar ışıl ışıl

sözlerin kadar alımlı

yüzümü ceviriyorum 

sıcaklığı vuruyor sırtıma

teninin sıcaklığında

ve bir an dudakların geliyor aklıma

suyun öpüşü kadar ipeksi

onun kadar ıslak

kimse bilmiyor seni sevdiğimi

dünyadaki insanlardan baska', 'yakamoz düşmüş denize  kalbinin renginde gözlerin kadar ışıl ışıl sözlerin kadar alımlı yüzümü ceviriyorum  sıcaklığı vuruyor sırtıma tenini...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kalender']::text[], 8.5, '{"poet":"Ümit Kalender","poet_slug":"umit-kalender","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yearning-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Seni', 'sevdim-seni-osman-guzelgoz-z50fg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdim seni

Yüreğimi yakan köz gibi

Kimselere söylenmemiş söz gibi

Sevdim seni

Canımda yaşan öz gibi

Kendimce bakan bir çift güzel göz gibi

Sevdim seni

Gökkuşağımda yedi renk gibi

Hayatıma katılan tatlı bir ahenk gibi

Sevdim seni

Varlığımı nurlandıran sevgili bir eş gibi

Beni ışıtan ısıtan yaşatan güneş gibi

Sevdim seni

Gözlerimi nuryandıran yaş gibi

Her şeyimi paylaştığım sırdaş gibi

Sevdim seni

Beni dirilten soylu bir onur gibi

Kararan bahtıma doğan bambaşka bir nur gibi

Sevdim seni

Seni bende bulup yine sende kaybolur gibi

Bin umut bin özlem vazgeçilmez huzur gibi

Sevdim seni

Gecelerimin hasreti uyku gibi

Kuruyan dudaklarıma sunulan şifalı su gibi

Sevdim seni

Benliğimi yenileyen canlı bir doku gibi

Gönül bahçemi zenginleştiren muhteşem bir koku gibi

Sevdim seni

Çare bekleyen ölümcül bir aşk hastası gibi

Aydınlık şafaklara götüren bir kurtuluş rüyası gibi

Sevdim seni

Mecnun''un uğruna ömrünü verdiği Leylası gibi

Sevgililerin en erişilmezi gibi adamın en hası gibi

Sevdim seni...', 'Sevdim seni Yüreğimi yakan köz gibi Kimselere söylenmemiş söz gibi Sevdim seni Canımda yaşan öz gibi Kendimce bakan bir çift güzel göz gibi ...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sevdim-seni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimin Irmakları Sana Akıyor', 'i-cimin-irmaklari-sana-akiyor-osman-guzelgoz-elrun', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gökyüzü gibi geldin üstüme

Örtündüm sevgini acılarıma

Yüreğim gözbebeklerinde tutsak şimdi

İçimin ırmakları sana akıyor

Şarkılar şiirler seni söylüyor

Varlığın sevinçlerime ortak

Seni düşlesem koynunda gecelerin

Tebessümlerin yanaklarımda gül

Seni düşünsem sabahın sağdıçlığında

Hep yüreğime uzanıverir ellerin

İçimi ırmakları sana akıyor

Şarkılar şiirler seni söylüyor...', 'Bir gökyüzü gibi geldin üstüme Örtündüm sevgini acılarıma Yüreğim gözbebeklerinde tutsak şimdi İçimin ırmakları sana akıyor Şarkılar şiirler...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icimin-irmaklari-sana-akiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tvvin', 'tvvin-umit-kalender-cpqy9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çok uzaklara gidebiliriz hayatım

uzaklara gidebiliriz askım

ama ayrılamayız bitanem

çook zor ayrılma ihtimalimiz

hatta imkansız

çünkü yapışık iki çiftiz 

ayrılmamız birinin ölümü ile olacak ancak', 'çok uzaklara gidebiliriz hayatım uzaklara gidebiliriz askım ama ayrılamayız bitanem çook zor ayrılma ihtimalimiz hatta imkansız çünkü yapışı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kalender']::text[], 8.5, '{"poet":"Ümit Kalender","poet_slug":"umit-kalender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tvvin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ben miyim', 'bu-ben-miyim-osman-guzelgoz-jxyw0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk dokunan ben miyim sana

Seni ilk öpen miyim

Boynundaki kolyen

Kulağında küpen miyim

Suskunken daralan yüreğine

Sabırla su serpen miyim

Söyle gönlümün gül bahçesi 

Sessizliğimin sesi söyle

Her şeyden çok sevdiğin

Ve herkesten çok sevdiğin

Ben miyim

İlk dokunan ben miyim sana

Seni ilk öpen miyim

Suskunken daralan yüreğine

Sevgimle su serpen miyim

Boynundaki kolyen

Kulağındaki küpen miyim

Seni ben ilk öpen miyim

Söyle tebessüm çiçeğim söyle

Seni yeryüzünden ve gökyüzünden

Sevinç ve hüzünden 

Daha çok seven miyim

Bu senin delin bu sana deli

Bu ben miyim...', 'İlk dokunan ben miyim sana Seni ilk öpen miyim Boynundaki kolyen Kulağında küpen miyim Suskunken daralan yüreğine Sabırla su serpen miyim Sö...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-ben-miyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslanmak İstiyorum', 'uslanmak-i-stiyorum-osman-guzelgoz-cwk7k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne istiyorum biliyor musun

Teninin ateşinde yanmak

bedeninin teriyle ıslanmak

gözbebeklerinde sevgiye uyanmak

ve senin sevdanla 

uslanmak istiyorum

Çünkü ben seni

Yeryüzünden gökyüzünden

Sevinç ve hüzünden

Daha çok seviyorum...', 'Ne istiyorum biliyor musun Teninin ateşinde yanmak bedeninin teriyle ıslanmak gözbebeklerinde sevgiye uyanmak ve senin sevdanla  uslanmak is...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uslanmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşalım', 'paylasalim-osman-guzelgoz-ffggo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ver bütün acılarını bana

Tebessümlerimi al

Paylaşalım

Al ellerim senin olsun

Yanımdasın biliyorum

Ber her zaman yanındayım

Ver ellerin bende kalsın

Paylaşalım

Gözlerini gözlerime hapset

Sen benim için bana bak

Ben senin için sana

Bu yangını kimse söndüremez artık

Yüreğimizdeki alevlere baksana

Ver bütün hüzünlerini bana

Al coşkularımı

Paylaşalım...', 'Ver bütün acılarını bana Tebessümlerimi al Paylaşalım Al ellerim senin olsun Yanımdasın biliyorum Ber her zaman yanındayım Ver ellerin bende...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/paylasalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severim', 'severim-osman-guzelgoz-a72e1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevme diyemezsin bana

Severim

Seni ben kendimce

Kadın gibi kız gibi severim

Sevme diyemezsin ki, 

Severim

Aşkına mahkum gibi mecbur gibi

Sır gibi severim

Kendimce seni ben

Kadın gibi kız gibi severim

Çalmak için her gün kalbini

Belki bir hırsız gibi severim

Sevme diyemezsin bana

Severim

Seni ben kendimce

Sevgili gibi yar gibi severim

Yüreğimi ısıtan ışıtan

Taptaze bahar gibi severim

Sevme diyemezsin bana

Severim

Seni ben kendimce

Kadın gibi kız gibi severim

Aşkına mahkum gibi mecbur gibi

Sır gibi severim

Seni ben toprağım

Memleketim gibi severim

Aşkından başka kimsesi olmayan

Öksüz gibi yetim gibi severim

Sevme diyemezsin bana

Severim

Seni ben kendimce

Gökyüzü gibi güneş gibi

Gözlerimdeki nur gibi severim

Yüreğime yağan yağmur gibi

Sonsuzlukta bulduğum huzur gibi severim

Sevme diyemezsin bana

Severim...', 'Sevme diyemezsin bana Severim Seni ben kendimce Kadın gibi kız gibi severim Sevme diyemezsin ki,  Severim Aşkına mahkum gibi mecbur gibi Sır...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Anda, Şimdi', 'ayni-anda-simdi-mustafa-cancer-kpmgu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ALLAH''ım sen ne büyüksün, 

Gökyüzü masmavi, 

Okşayan bir esinti, 

Aynı zamanda terleten bir sıcak, 

Bir tek bulut bile yok, 

Dolunay o kadar parlak ve temiz ki...

Bu gece hiç bitmemeli....

Yine beraberiz değil mi sevgili? 

Hatırlıyorsun değil mi dolunayın sihrini? 

Ben bakacaktım, sen de bakacaktın, 

Hem de aynı anda, şimdi...

Evet! Gördüm seni, gülümsedin yine.

Ah! Ne mutlu bir portre bu! 

Hiç davranma, telefonum kapalı, 

Hatta yanımda bile değil! 

Üzdüm seni biliyorum, 

Ama bir kaç gün idare edeceksin gönlünü, 

Çünkü; beynimde yeni bir trafo arızası var, 

Onarım çalışmaları devam ediyor, 

Dünya ile bağlantım kesik, 

Yanlış anlama ama, jeneratörümde kesik, 

Kalbimin küpürleri de kesik, 

Faturalandı, aşk kurumuna postalandı, 

Biraz bekledi orada, eğlendi, 

Gönlüm biraz sakar olduğu için, 

Yine bir hata yapmış, 

Ne mi olacak şimdi? ! 

Ee tabiiki yine iade! 

Tamiri imkansız bir iade, 

At çöpe gitsin, 

İşte trafo arızasının hikayesi...

Neydi sevgili bu aşkın eşkali? 

Ben ağlayacaktım, sen de ağlayacaktın, 

Hem de aynı anda, şimdi.......', 'ALLAH''ım sen ne büyüksün,  Gökyüzü masmavi,  Okşayan bir esinti,  Aynı zamanda terleten bir sıcak,  Bir tek bulut bile yok,  Dolunay o kadar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Cancer']::text[], 8.5, '{"poet":"Mustafa Cancer","poet_slug":"mustafa-cancer","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ayni-anda-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayali Bile Muhteşem Güzel', 'hayali-bile-muhtesem-guzel-osman-guzelgoz-e1zl5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir resmin olsa şu anda ben de

Bal gözlerinde yaşasa gözlerim seni

Etraflıca bakınsam sana hayranlıkla

Hayali bile muhteşem güzel sevdiğim

Hayal Kahvesi’nde bir gece ellerimde ellerin

Şarkılar söylesek birlikte coşkuyla

Yeryüzünde gökyüzü dinlese bizi

Kıskansa tüm sevgililer bizim sevgimizi

Şiirler okusak seninle diz dize

Şarkılar söylesek coşkuyla göz göze

Aydınlık şafaklar konuk olsa gecemize

Hayali bile muhteşem güzel sevdiğim

Hayal Kahvesi’nde bir gece ellerinde ellerim

Alıp beni benden sana götürsen benliğimi

Teninin ateşiyle yakıp kavursan tenimi

Bedeninin teriyle ıslatsan yine bedenimi

Gözbebeklerinde sevgiye uyandırsan beni

Hayali bile muhteşem güzel sevdiğim

Hayal Kahvesi’nde bir gece ellerimde ellerin

Viyana’da görkemli bir valsle buluşsak

Venedik’te gondol sefasında konuşsak

Şarkılar söylesek birlikte coşkuyla

Yeryüzünde gökyüzü dinlese bizi

Kıskansa aydede ve yıldızlar sevgimizi

Hayali bile olağanüstü güzel sevdiğim

Hayal Kahvesi’nde bir gece ellerinde ellerim

Bir resmin olsa şu anda bende

Bal gözlerinde yaşasa seni gözlerim

Hayali bile inanılmaz güzel sevgilim...', 'Bir resmin olsa şu anda ben de Bal gözlerinde yaşasa gözlerim seni Etraflıca bakınsam sana hayranlıkla Hayali bile muhteşem güzel sevdiğim H...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayali-bile-muhtesem-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Aşkım', 'gel-askim-kenan-ceco-4yr9n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GEL AŞKIM

Gel aşkım

Bir daha gel, amansızca gel

Farklılaşmadan öylece gel

Gel dokun yanlızlığıma

Yak, dağla yüreğimi

Ve korkusuzca fısılda

Fısılda ki uyansın kalbim

Kırılsın manasız inadım

Dağılsın gözlerimde bulutlar

Ve Sonra sevabına öldür

Öldür bendeki umutsuzluğu

Gel...! 

Bir daha gel, habersiz gel

İnadına değişme öylece gel

Gel atıl kollarıma

Uzat elini, uçur

Mahkum et, Zincire vur

Kırbaçla gözlerimi

Ve içir yudum yudum zehrini

İçir ki yok olsun utanılmışlığım

Gel...! 

Bir daha gel, yanıma gel

Bağışla ve öylece gel

Hep gel, coşkun selinle gel

Al.... sürükle ovana

kana kana sustur...', 'GEL AŞKIM Gel aşkım Bir daha gel, amansızca gel Farklılaşmadan öylece gel Gel dokun yanlızlığıma Yak, dağla yüreğimi Ve korkusuzca fısılda F...', ARRAY['Türk Edebiyatı','Şiir','Kenan Ceco']::text[], 8.5, '{"poet":"Kenan Ceco","poet_slug":"kenan-ceco","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gel-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Başına Ölüyorsun', 'tek-basina-oluyorsun-ahmet-aka-e3npa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tek başına ölüyorsun ey şehir 

çıkmaz sokaklara gömülüyorsun 

senin mezarın da işte burası 

en rahat yerini beğenmiyorsun', 'tek başına ölüyorsun ey şehir  çıkmaz sokaklara gömülüyorsun  senin mezarın da işte burası  en rahat yerini beğenmiyorsun...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aka']::text[], 8.5, '{"poet":"Ahmet Aka","poet_slug":"ahmet-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tek-basina-oluyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdin mi Birini?', 'sevdin-mi-birini-kenan-ceco-10l24', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEVDİN Mİ BİRİNİ? 

Sevdim mi birini? 

Bağışlandım  mı hiç? 

Ya da araladım mı kapısını aşkın? 

Tutmaya aciz ellerini uzattın mı? 

Ve park ışıklarında demlendim mi? 

O an haykırıp, kaptım mı şifasını 

Beynimde yankılanırcasına

    “Seni Seviyorum”

Bana katılmalısın, 

Gezmelisin kollarımda 

Mayasız dağ mantarı gibi bitmelisin 

Bardaklarda sıcacık olmalısın 

Yoksa başka aşklarda mı kalsın gözlerim

Sulansın mı bu yüzden

Hiç mi olmasın hoşu 

Patlamış mısır sinemaları gibi 

İçine coşku gömülü heyecan gibi 

Alacaklısı belli olmayan borç gibi 

Yoksa param mı olmaz

Yutkunur muyum soluğumu

Saklı mı tutarım inançlarımı

Törpüler miyim duygularımı

Ya da eksik mi tutarım dileklerimi

Ovuşturur muyum gözlerimi, ağlar mıyım

Durmadan aldatır mıyım kendimi

Vurgun yemiş sözcükler mi söylerim

Tırnaklarımı mı kemiririm

Ya borcumu ödemeden gidersem 

Ya tutuklu kalırsam

Kelepçeleri kim çözecek

Tanrım aklım firarda mı

Yoksa gel-git mi yaşıyorum ay tutulmasında

Mağdur mu kaldım mavi trenin yolculuğunda

Gün ortasında karanlığımı yaşıyorum 

Ben mutsuzum, yada gülemiyorum

Dağ yüksek mi gelir, deniz uzak mı olur

Kalbim kılavuz mudur

İhaneti olur mu dizlerimin

Destekçim olur mu uzanmadığım dalda

Biri üstlenir mi, kimin bu görev

Bugün yoksa yarın olacak mı

Yarın geldiğinde bugün yaşar mı

Hepsini boş mu bırakayım

Daha borcum mu var

Kim yargılar beni, 

Yoksa çaresiz mi kaldım

Ayakta mı öldüm

Ahhhh....

Kimi yaşıyorum şu bedenimde

Kendimi neden bulanıyorum

Düşüncesi neden beni sarıyor

Ve neden çoğul oluyorum bu bedenimde

Neden gökkuşağı gibi renklere 

Babam gibi toprağa özlemi duyuyorum 

Ve neden bulamıyorum soruların cevabını

Neden......................', 'SEVDİN Mİ BİRİNİ?  Sevdim mi birini?  Bağışlandım  mı hiç?  Ya da araladım mı kapısını aşkın?  Tutmaya aciz ellerini uzattın mı?  Ve park ış...', ARRAY['Türk Edebiyatı','Şiir','Kenan Ceco']::text[], 8.5, '{"poet":"Kenan Ceco","poet_slug":"kenan-ceco","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/sevdin-mi-birini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Demeli', 'ne-demeli-kenan-ceco-god7z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir göründün pir oldun

Kaybolup sır odun

Bahçemde gül oldun

Ya dikene ne demeli 

Geçen gün arattırır 

Belki de saptırır

Her umudu ektirir

Ya umutsuzluğa ne demeli 

Her mevsim avuttun 

Yola çıkardın unuttun

Beni sensiz uyuttun

Ya başkasına ne demeli

Ayazda korkuttun

Soğukta döndürdün

Yağmurda ıslattın 

Ya sıcağa ne demeli

Kara kışın yazı var

Rüzgarın tozu var

Gönlümde aşkın izi var

Ya gitmene ne demeli', 'Bir göründün pir oldun Kaybolup sır odun Bahçemde gül oldun Ya dikene ne demeli  Geçen gün arattırır  Belki de saptırır Her umudu ektirir Ya...', ARRAY['Türk Edebiyatı','Şiir','Kenan Ceco']::text[], 8.5, '{"poet":"Kenan Ceco","poet_slug":"kenan-ceco","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-demeli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarif-i AŞK', 'tarif-i-ask-kenan-ceco-i14km', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk saçlarını okşamak değil 

Ellerini tutup ovuşturmak değil

Gözlerine bakıp gülümsemek değil

Aşk bir istektir yok  tarifi

Aşk kol kola gezmez değil

Şehvetlice sarılıp öpüşmek değil

“Seni seviyorum” demek değil

Aşk bir gerçektir yok  tarifi

Aşk yağmurda ıslanmak değil

Rüzgarda dalgalanmak değil

Soğukta üşümek değil

Aşk bir sıcaklıktır yok tarifi 

Aşk masada kumar değil

Kadehlerde kırmızı gül değil

Bir an yaşayıp kaçmak değil

Aşk ömürdür yok  tarifi

Aşk terk edip gitmek değil

Bir başkasını sevmek değil

Unutup kahretmek değil

Aşk bağlılıktır yok tarifi

Aşk dağlarda, çöllerde değil

Görünen bedenlerin iyisinde değil

Savrulan maddiyatta değil

Aşk bende sende ve  ille de yüreklerde', 'Aşk saçlarını okşamak değil  Ellerini tutup ovuşturmak değil Gözlerine bakıp gülümsemek değil Aşk bir istektir yok  tarifi Aşk kol kola gezm...', ARRAY['Türk Edebiyatı','Şiir','Kenan Ceco']::text[], 8.5, '{"poet":"Kenan Ceco","poet_slug":"kenan-ceco","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tarif-i-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizden', 'denizden-huseyin-cayikli-zaynm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'denizin icinde ki midyeleri izliyordum

aklima insanligin geldi 

hic unutamadigim ismin 

ve yalana dair yuzun

o kadar yuksek ki daglar 

o kadar yuce ki

insanligin 

yuzun

gozlerin

hepsini cizdim

hepsini bir resim de yaktim

sonra uzulmemek icin denize 

attim

sen gelmedin

ben yalniz kaldim

ve deniz sahitti 

bana yunus baliklariyla tango yapti...

sen yoktun 

gelmedin...', 'denizin icinde ki midyeleri izliyordum aklima insanligin geldi  hic unutamadigim ismin  ve yalana dair yuzun o kadar yuksek ki daglar  o kad...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/denizden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanırlar Tabiki', 'dayanirlar-tabiki-cengiz-yazici-vjq2f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Annesinden ayrılan bir yavru kedi, 

Yada o kedinin annesi, 

Oğlunu şehid veren bir baba, 

Gurbet gurbet gezen akraba, 

Nasıl dayanıyorsa hasrete, 

Dayanırım tabiki.

Kaç evlilik yıkıldı kimbilir, 

Kimbilir kaç çocuk perişan, 

Dal nasıl dayanıyorsa, 

Yetişdirdiği meyvasının, 

Koparılmasına, 

Ağaç nasılki dayanır, 

Vahşice kırılan bir dalına, 

Dayanırım tabiki.

Henüz dağ yıkılmadıki 

Altında ben kalayım, 

Hem yıkılsa ne olur ki, 

Ben nasılsa ordan çıkarım.

Açlıktan kim ölmüş ki? 

Mezarını kim görmüş ki? 

Nasıl dayanıyorsa, bu millet sancıya, 

Dayanırım tabiki.

Hasta, nasıl ki muhtaçsa, 

İlaçlara, 

Bağrı çatlak toprak, 

Bir damla yağmura, 

Yavrusunu yitiren ana, 

Basıyorsa, mezarını bağrına, 

Sonuçta, vuslat varsa Allah Aşkına.

Dayanılır tabiki, 

Elbette dayanılır.

Ben, neden dayanmıyayım?', 'Annesinden ayrılan bir yavru kedi,  Yada o kedinin annesi,  Oğlunu şehid veren bir baba,  Gurbet gurbet gezen akraba,  Nasıl dayanıyorsa has...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dayanirlar-tabiki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Kupası Hatırası', 'dunya-kupasi-hatirasi-cengiz-yazici-auibv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyan dünya uyan, Türk''ler geliyor, 

Ağır adımlarla, naralarla geliyor.

Kırksekiz yıl, su gibi, geldi geçti bak, 

Dünyanın kupasına, onbir arslan geliyor.

Dikkat et renklerine, kırmızı ve ak, 

Onbirininde başı dik, alnı ak, yüzü pak.

Ardında Atmışbeş milyon can var, 

Sen o renklerdeki ay ile yıldıza iyi bak.

Unutmadık, sizdiniz emen kanımızı, 

Yetmedi, birde barbar taktınız adımızı.

Oysa, bizdik kalkındıran, bir çoğunuzu, 

Olmadı, faizlere saydınız, ödediğimiz borcumuzu.

Sakın unutmayın? biz Türk oğlu Türküz.

Fazla sıkıntı, bize yaramaz, çünkü; Özgürüz.

Biz, bir yol bulur, adımızı illaki duyururuz, 

Sıkmayın bizi, Üzmeyin bizi, 

.......

Geçmişinizi yüzünüze vururuz.', 'Uyan dünya uyan, Türk''ler geliyor,  Ağır adımlarla, naralarla geliyor. Kırksekiz yıl, su gibi, geldi geçti bak,  Dünyanın kupasına, onbir ar...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dunya-kupasi-hatirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Falım', 'falim-cengiz-yazici-aics8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun yoldan, 

Bir haber alacaksın, diyor, 

Bu günkü falım.

Sağlığına, hiç dikkat etmiyorsun, 

Nedir, senin bu halın? 

Sevdiğin diyor, kısa boylu, 

Senin gibi uysal, güzel huylu.

Bir miktarda, para gelecekmiş, 

Miktarı belli değil.

Belli olsa ne olur, 

Senin elin, sıkı değil.

Burcum yükselmiş, 

Bilmem nereye girmiş, 

Oraya girince, 

İnsan, biraz asabi olurmuş.

Fala inanma, falsızda kalma, 

Diyenler için baktım, 

Ben, bu günkü falıma.

Ne işim olmuş ki benim, 

Şansla, falla, parayla, 

İnanmıyorum işte inanmıyorum, 

Ben ilgilenmiyorum, bu yollarla....', 'Uzun yoldan,  Bir haber alacaksın, diyor,  Bu günkü falım. Sağlığına, hiç dikkat etmiyorsun,  Nedir, senin bu halın?  Sevdiğin diyor, kısa b...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/falim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa Nasıl Anlatırsınız', 'yoksa-nasil-anlatirsiniz-cengiz-yazici-2s7rp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretin acısı tarifsiz, 

Yaşamak lazım, 

Yoksa nasıl anlaltırsınız.

Biraz susuzluğa benziyor, 

Çölde olsan katlanırsınız.

Yoksa açlıkmı desem? 

Sanki, oruç tutarsınız.

Yada askerlik mi desem? 

Gün sayarsınız.

Gurbet, sıla, desem? 

Kesin dönüş yaparsınız.

Mideniz bulansa? 

Mutlaka kusarsınız.

Hastalansanız? 

İlaç alırsınız.

Bir yeriniz kangren desem? 

Kesilir yaşarsınız.

Amansız, bir hastalığa yakalansanız? 

ölür kurtulursunuz.

Dipsiz bir kuyuya düşseniz? 

Sürünerekte olsa çıkarsınız.

Dünya kadar borcunuz olsa? 

Yavaşda olsa ödersiniz.

Önünüzde uzun bir yol olsa? 

Yayanda olsa gidersiniz.

Ne bileyim, günlerce uykusuz kalsanız? 

Kıvrılır bir köşede yatarsınız.

........

Hasretin acısı tarifsiz, 

Yaşamak lazım, 

Yoksa nasıl anlaltırsınız.

........', 'Hasretin acısı tarifsiz,  Yaşamak lazım,  Yoksa nasıl anlaltırsınız. Biraz susuzluğa benziyor,  Çölde olsan katlanırsınız. Yoksa açlıkmı des...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yoksa-nasil-anlatirsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Sitemlerim', 'sana-sitemlerim-cengiz-yazici-joq84', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana sitemlerim, 

Belkide ''''en yakın''''hissetmemdir.

Sana serzenişlerim, 

Belki bir gün kaybetmemdendir.

Sana isyanlarım, 

Belki, kendi hatalarıma, kızmalarımdandır.

Sana haykırmalarım, 

Belki yanlış kefaretlerimdendir.

Sana yalvarmalarım, 

Kimbilir? Seni, senden çok, sevdiğimdendir.

Ama ve lakin, 

Sana zarf atamam, 

Politika yapamam, 

Putperest hiç değilim, 

Ben sana, bir tanem, tapamam.

-Yalan.?                                 O ne yenir mi içilir mi? 

-İhanet.?                                Onlar burdan taşındı.

-Sözden dönmek.?              Bir durak ileride.

-Adam satmak.?                  Kitabımda yazmaz.

-Çamura yatmak.                 Burda yağmur yağmaz.

-Laf taşımak.                        Arabanın lastiği patlak.

...............

De get len, ne satıyon sen...', 'Sana sitemlerim,  Belkide ''''en yakın''''hissetmemdir. Sana serzenişlerim,  Belki bir gün kaybetmemdendir. Sana isyanlarım,  Belki, kendi hatal...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sana-sitemlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz Rüzgarlarına', 'karadeniz-ruzgarlarina-cengiz-yazici-bxu2g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karadeniz rüzgarlarına benziyorsun, 

Her zaman, değişik yönden esiyorsun, 

Bir gün çok iyisin, tam kafama göre, 

Bir gün kafa tutup, ahkam kesiyorsun.

Bir anlayabilsem, nerden nasıl estiğini, 

Ah, bir bilebilsem, beni nasıl sevdiğini, 

Kıyamam sana, üzülürüm, beni biliyorsun, 

Hoca misali, sen bindiğin, dalı kesiyorsun.

Unutma! zamansız esen rüzgar, kıtlık getirir, 

Çünkü; önünde ne varsa, siler süpürür.

Hemen, yanı başında duran sevdasını, 

Deli eder şaşırtır, aşılmaz dağlar aşırtır.', 'Karadeniz rüzgarlarına benziyorsun,  Her zaman, değişik yönden esiyorsun,  Bir gün çok iyisin, tam kafama göre,  Bir gün kafa tutup, ahkam k...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karadeniz-ruzgarlarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiden Doğa Adında Biri Vardı', 'eskiden-doga-adinda-biri-vardi-cengiz-yazici-3hfsi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllarca, el birliği ile denizleri kirlettik, 

Yetmedi içinde yüzen, balıkları katlettik.

Farkında olmadan, yavaş yavaş yok ettik.

Denizlere giremedik, balığımızı yiyemedik, 

Aslında kendi belamızı, kendimiz hak ettik.

Kış oldu camlarımız aralayamadık, 

Fabrika bacası dedik, kömür yaktık, 

Egsoz gazı, aerosol, spreylermiş dedik, 

Bir çerçeve için, bir delik delemezken, 

Ozon tabakasını biz, kökünden hallettik.

Ormanlarda yaşayan, bin bir canlı vardı, 

Oradaki hayatta, İlahi bir ahenk vardı, 

Villa, köşk, saray, arsa egolarımız için, 

Biri çıkıpta, bana söylermi, Allah Aşkına, 

Ormanları yakmaya, kimin ne hakkı vardı.? 

Şimdi denizlerimiz, banyoda küvette, 

Oksijenlerimiz, hastahanede tüpler içinde, 

Balıklar sadece seyirlik, camdan kafeste, 

Çiçekler malum, balkonda saksı içinde.

............

Hani...? 

''''Biz doğayı, Atalarımızdan miras değil.Torunlarımızdan ödünç almıştık..! ''''', 'Yıllarca, el birliği ile denizleri kirlettik,  Yetmedi içinde yüzen, balıkları katlettik. Farkında olmadan, yavaş yavaş yok ettik. Denizlere...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/eskiden-doga-adinda-biri-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ballı Maymunum', 'balli-maymunum-cengiz-yazici-zxx3h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen, bastı bacak, 

Demeye kıyamadığım.

Sen, fındık kurdum, 

Hayal kırığım.

Sen, günlerimi ay, aylarımı yıl, 

Yıllarımı, asır yapan, 

Arım, kovanım ballım.

Sonra yine sen, 

Asrımı lahzaya indiren, 

Yaramaz maymunum.

Ve sen, 

Bütün hıncını alır gibi, 

Ayağının altında

İzmarit gibi, ezen.

Ve yine sen, 

Hayatımı enkaza çeviren, 

Yedi noktam fay kırığım.', 'Sen, bastı bacak,  Demeye kıyamadığım. Sen, fındık kurdum,  Hayal kırığım. Sen, günlerimi ay, aylarımı yıl,  Yıllarımı, asır yapan,  Arım, k...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/balli-maymunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısmetimdekiler', 'kismetimdekiler-cengiz-yazici-lc58b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç, peşin fiyatına, taksitle almadım.

Tek bulduğum, kırık ekmek parçalarıydı, 

Başım önümde, gezdiğim sokaklarda, 

Para denen şeye, hiç rastlamadım.

Ekmeğinse, bayatlarıydı kısmetimdekiler, 

Birde, çürükleri ayıklanmış yeşil sebzeler.

Beri yanda, lüks içinde yaşayanlar vardı, 

Diğer yanda, bizim gibi, buna şükredenler.

Hiç, pahalı ayakkabılarım olmadı, 

Aslında, buna özlemimde olmadı.

Gayem ayaklarımın kapalı olmasıydı, 

Bayramlılarımın bile, kenarları patlaktı.

Beyler gibi oturamadım, bir restaurantta, 

Garsonlar, hiç pervane olmadı etrafımda.

Bir, kuru, pilav, cacıkta olsa yeterdi bana, 

Sadece bir çorba içebildim, kürdan ağzımda.

Minnet duyuyorum, ben aslında, 

O ekmek parçalarını, sokağa atanlara.

Düşünüyordum, çünkü biliyordum, 

Benim kadar muhtaçlar, karınca ve kuşlar, 

İşte çöpe atılan.o RIZKLARA.', 'Hiç, peşin fiyatına, taksitle almadım. Tek bulduğum, kırık ekmek parçalarıydı,  Başım önümde, gezdiğim sokaklarda,  Para denen şeye, hiç ras...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kismetimdekiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Dostluklar Vardır', 'hani-dostluklar-vardir-cengiz-yazici-kmdxy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani dostluklar vardır? 

Yumurtanın, ak ve sarısı gibi, 

Birbirlerine karışmadan, 

Bir kabuk içinde, kardeş misali, 

Hesapsız.

Hani dostluklar vardır? 

Kağıt ve kalem gibi, 

Biri yazar, biri kaydeder, 

Hiç kimse, duyamaz bunu, derindir.

Sessiz, sedasız.

Hani dostluklar vardır? 

Yıllardır dilden dile, 

Kulaktan kulağa, nesilden nesile, 

Anlatılır durur, destansı, 

Kitapsız, belgesiz.

Hani dostluklar vardır? 

İçinde, alım satım yapılmaz.

Yapılsada maliyetinedir, 

Komisyon alınmaz.

Benim dostluğum, 

Biraz buna benzer.

Kimse bir şey anlamaz.

......

Emsalsiz, kayıtsız. ÇIKARSIZ..!', 'Hani dostluklar vardır?  Yumurtanın, ak ve sarısı gibi,  Birbirlerine karışmadan,  Bir kabuk içinde, kardeş misali,  Hesapsız. Hani dostlukl...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hani-dostluklar-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-cengiz-yazici-qyknn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece, deli divane yollarda, 

Seni sordum, önüme çıkanlara.

Kimse görmemiş, kimse duymamış, 

Kimbilir, nerdesin sen, hangi taşın altında.

Sokaklar soğuk, sokaklar ıssız, 

Anasız babasız, kuşlar gibi yuvasız.

Hayat, öylesine yavan, öylesine tatsız, 

Kimbilir nerdesin, nerdesin sen vefasız.

Kuşlarım dargın, artık cama gelmiyor, 

İçkimin bile tadı yok, başım dönmüyor.

Bir tek dostum kalmış, sigaram benim, 

Sağ olsun, parmaklarımdan, bir tek o düşmüyor.', 'Dün gece, deli divane yollarda,  Seni sordum, önüme çıkanlara. Kimse görmemiş, kimse duymamış,  Kimbilir, nerdesin sen, hangi taşın altında....', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-ariyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Öğretmen Bir Ders/1', 'bir-ogretmen-bir-ders-1-cengiz-yazici-nui37', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.

Okulun birinde, bir öğretmen vardı, 

Öğrencileri, o öğretmeni çok severdi.

Doğruydu çünkü, üstelik bilge biriydi, 

Ona göre herkes, erdemli olmalıydı.

İşte bu öğretmen, bir ödev verdi bir gün, 

Yarın, herkes bir torba, patates getirsin.

Denileni yaptı öğrenciler, biraz şaşkın, 

Ertesi gün, patates ile doldu her yeri sınıfın.

Dayanamadı öğrencilerden biri, 

Cesaretini toplayıp, öğretmene şöyle dedi.

Öğretmenim, neyimize yarayacak bu ders? 

Onca sınav varken, nerden çıktı bu patates.

Sabredin dedi biraz, daha bitti sanmayın, 

Torbasından herkes, bir patates çıkarsın.

Ve, çıkardığı her patatese, dargın

Olduğu bir kişinin adını yazsın.

Yanlız dedi, sizden bir isteğim daha var, 

Bunlar, nereye giderseniz, yanınızda olsunlar.

Otobüste, yolda, çarşıda pazarda, oyunda, 

Hatta, yatağınızın baş ucunda.

Denilenleri, bir bir yaptı öğrenciler, 

Yanlız, bir kaç günde, bitiverdi patatesler.

Mecburen, birer torba daha aldılar, 

Onlarında üzerlerine, isimler yazdılar.', '. Okulun birinde, bir öğretmen vardı,  Öğrencileri, o öğretmeni çok severdi. Doğruydu çünkü, üstelik bilge biriydi,  Ona göre herkes, erdeml...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-ogretmen-bir-ders-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Öğretmen Bir Ders/2', 'bir-ogretmen-bir-ders-2-cengiz-yazici-0oeih', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her nereye gitseler, yanlarında taşıdılar, 

Lakin, yükleri üç günde, ağırlaşınca, 

Döndü, öğretmenlerine dert yandılar, 

Dediler ki; Öğretmenim yorulduk bittik.

Patates taşımaktan, kanter içinde kaldık.

Bir ders için, bunca eziyet niye, 

Yoksa, öç mü alıyorsunuz, bizden bile bile? 

Yazıktır günahtır, yakmayın canımızı, 

Bir hatamız varsa, lütfen affedin bizi.

Öğretmen, hayır dedi, yok öyle bir niyetim, 

Hayatı, biraz daha iyi anlamanız, tek derdim.

Madem, çok yoruldunuz, öldünüz bittiniz.

Artık, dargın olduklarınızı af ediniz.

Öylede yaptı, bütün öğrenciler, 

Dargın oldukların, bir bir af ettiler.

Af ettikleri patatesleri, tek tek attılar.

En son, atacak patates kalmayınca, güldüler.

İşte dedi evlatlarım, anlatmak istediğimi, 

Bilmem, sizlere anlatabildim mi.? 

Hayatınız boyunca, her hata yapanı, 

Af etmez, biriktirirseniz içinizde, 

Yükten başka, bir şey getirmez bu size.

''''Unutmayın! Af etmek büyüklüktür, 

Af eden, edilenden, çok ama, çok daha büyüktür''''', 'Her nereye gitseler, yanlarında taşıdılar,  Lakin, yükleri üç günde, ağırlaşınca,  Döndü, öğretmenlerine dert yandılar,  Dediler ki; Öğretme...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-ogretmen-bir-ders-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Düne Kadar', 'daha-dune-kadar-cengiz-yazici-upbc5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her gün andığım ismin, 

Birden aklımdan çıkıverdi.

Her gece rüyalarımdaydın, 

Hayret, hafızamdan siliniverdin.

Ehliyetim, tapum, ruhsatım, 

Hatta ve hatta, nüfus cüzdanım.

Bunlardan daha önemliydi, 

Adresin, numaraların, fotoların.

Sayfa sayfa yazdıkların, mesajların, 

Sahilde bir kumamı yazmışım? 

Bir talihsiz dalganla, 

Dümdüz oluverdi.

Sayenizde küçük hanım, 

Aklım şaştı, 

Beynim donuverdi...', 'Her gün andığım ismin,  Birden aklımdan çıkıverdi. Her gece rüyalarımdaydın,  Hayret, hafızamdan siliniverdin. Ehliyetim, tapum, ruhsatım,  ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/daha-dune-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmek, Bilmek, Duymak', 'gormek-bilmek-duymak-cengiz-yazici-l19qs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Görmek istediklerimi görürüm ben, 

Görülmeye değerse eyer.

Duymak istemiyorsam, 

Ağzından çıkan sözleri, 

Yani, yoksa benim için

Hiç bir kıymeti, 

Naralar da atsan, faydası olmaz.

Açıktır kulaklarımın kapısı, 

Ardına kadar.

Harf harf, giren naraların, 

Parağraflar halinde çıkar.

Koklamak istediklerimi koklarım ben, 

Kokusu, koklanmaya değerse eyer.

Gül, gül olacaksa, yerinde olmalı, 

Yoksa, mezarlıkta olmuş, ne fark eder.

Yemek istediklerimi yerim ben, 

Tadına bakılmaya değerse eyer.

Ha, bir kuru ekmek parçası, 

Ya da, dünyanın en pahalı pastası.

Altın tabakta olsa ne farkeder.

Bilmek istediklerimi bilirim ben, 

Öğrenilmeye değerse eyer.

Deymiyorsa, çöpe atarım gider, 

Ne farkeder.', 'Görmek istediklerimi görürüm ben,  Görülmeye değerse eyer. Duymak istemiyorsam,  Ağzından çıkan sözleri,  Yani, yoksa benim için Hiç bir kıy...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gormek-bilmek-duymak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Kadını', 'hayat-kadini-cengiz-yazici-hj4a5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir dost, ziyaretinden dönüyordum, 

Saat, sabahın üçüydü yanlızdım.

Yollar bomboştu, trafikte öyle, 

Canımsa sıkkındı, biraz gaza bastım.

Önümde viraj vardı, işaretler öyle diyordu, 

Yavaşladım, ışıklarda bir bayan duruyordu.

Hayret ettim, bu saatte ne işi vardı? 

Aklımdan, sokağa atılmışlığı geçiyordu.

Durdum yanında, zaten el kaldırmıştı, 

İçkiliydi, ama daha sorhoş olmamıştı.

Atarmısın dedi, beni evime kadar, 

İşim iyi değil, misafirim ol sabaha kadar.

Oturdu koltuğa, açtı camı, yaktı sigarasını, 

Hayat kadınlığından, kazanıyormuş nafakasını.

Anlat biraz dedim, nasıl düştün sen bu yola? 

Boş ver aslanım dedi, karıştırma o tarafını.

Sadece şunu bilki, bu kadar, 

Aç kalan insan, her an, her şeyi yapar.

Ha bu iş, ha hırsızlık, yankesicilik, ha kumar, 

Bizim içimizde, benim gibi neleri var.

Ama dedim, böyle düşünmemelisiniz, 

Şunu unutmayın ki, siz bizden şanslısınız.

Her ne kadar da bu işi yapsanız, 

''''Bir tevbe, bir kırkla, ruhsatlısınız''''

Bir ara, sessizlik oldu arabanın içinde, 

Bir kaç damla, yaş vardı gözlerinde.

Evime yaklaştık dedi, beni sağda bırak, 

Bu can, bu sözlerini hiç unutmayacak.

İndi arabadan, el salladı, teşekkür etti, 

Sonra, karanlığın içinde, kayboldu gitti.

Bir an baktım ardından, bir sesle irkildim, 

''''Seni unutmayacağım yabancı, 

O sözlerin, beni bana, geri getirdi.''''', 'Bir dost, ziyaretinden dönüyordum,  Saat, sabahın üçüydü yanlızdım. Yollar bomboştu, trafikte öyle,  Canımsa sıkkındı, biraz gaza bastım. Ön...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hayat-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Kendinize Bakın', 'siz-kendinize-bakin-cengiz-yazici-fj6lh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç kimseye zararımız olmaz.

Değil zarar, kılına dokunulmaz.

Birileri, bizi tam tersi tanır, 

Bizde, ölenlerin ardından konuşulmaz.

Bir adım daha önündeyiz hayatın, 

Biliriz faydası olmaz, saltanatın.

Millet, cennet peşinde koşarken, 

Biz biliriz, meşakatini kabir hayatının.

Bizde, para için kimse satılmaz, 

Hatta ve hatta, konusu dahi olamaz.

Herkes, şekline gücüne bakarken, 

Bizde bunun, mütealası yapılmaz.

Biz, herşeyi, O''nun rızası için yaparız, 

Yaparızda, sonra bir şey hatırlamayız.

Biliriz, dünyanın bir tarla olduğunu, 

Ondandır, ürünümüzü burda toplamayız.

Her kesin, bir yatırım yeri vardır.Aşikar, 

Kiminin malı mülkü, kiminin, parası pulu var.

Biz biliriz, bunların bir başka''''Sahibi''''var.

İşte O''Sahibin, biz gibi kulları var.', 'Hiç kimseye zararımız olmaz. Değil zarar, kılına dokunulmaz. Birileri, bizi tam tersi tanır,  Bizde, ölenlerin ardından konuşulmaz. Bir adım...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siz-kendinize-bakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Doğruluktur Benim', 'adim-dogruluktur-benim-cengiz-yazici-anilo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adım doğruluktur benim, 

Soy adımsa dürüstlük, 

Yok bunlardan tavizim, 

Olmasamda dört dörtlük

Hiç dünya malım yoktur benim, 

Dünyanın malı benim yüreğim.

Lakin hiç bir işe  yaramaz bilirim, 

Onca topraktan, Fatih''e ne kaldı, mirim.

Bak, cennetler vaad ediliyor, doğruya, 

Yeterki doğru ol, doğru cevap ver soruya, 

Hazır inmişken ömrün yarıya, 

Yeşillerini boyama sen, ellerinle karaya

İnsan bu, kuş misali uçar ya, 

Hayat, bir nefes gibi, alır biter ya, 

Aslında bitmezde, biter gibi gelir ya.

Gerçek hayatlar orada, gerisi sadece angarya.', 'Adım doğruluktur benim,  Soy adımsa dürüstlük,  Yok bunlardan tavizim,  Olmasamda dört dörtlük Hiç dünya malım yoktur benim,  Dünyanın malı ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adim-dogruluktur-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atılmıyor Kalbimden', 'atilmiyor-kalbimden-cengiz-yazici-s1p7a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine, efkar bastı, gönlümü derinden, 

Bilmem, yar anlarmı, gönül halimden.

Şarkılar, kafiyesiz, nakaratsız, 

Boynum bükük, dertlerim notasız.

Çok denedim olmuyor, atılmıyor kalbimden.

Derdim, bir derdim, bin oldu şimdi, 

Sıra sıra dizildi, yüreğimde her biri, 

Hayat boyu peşimde, bir gölge gibi, 

Düş dedim yakamdan, bir türlü düşmedi.

Çok denedim olmuyor, atılmıyor kalbimden.

Sevgisi, yüreğimde, bir çocuk sevgisi, 

Seviyorum demesi, sanki yüreğimin sesi, 

Yüzündeki tebessüm, bir gülün busesi, 

Benim sevdalarım, Ferhat''ların sevdası.

Çok denedim olmuyor, atılmıyor kalbimden.

Şimdi üzerimde, yılların yorgunluğu var, 

Yüreğimde, senin hatalarının, kırgınlığı var.

Ak düşmüş saçlarıma, karlar yağar, 

Sahilde, kopacak fırtınanın, sessizliği var.

Çok denedim olmuyor, atılmıyor kalbimden.', 'Yine, efkar bastı, gönlümü derinden,  Bilmem, yar anlarmı, gönül halimden. Şarkılar, kafiyesiz, nakaratsız,  Boynum bükük, dertlerim notasız...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/atilmiyor-kalbimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katkın Olsun', 'katkin-olsun-oguzkan-bolukbasi-ea9ma', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'biraz sen de gayret et

yalnız olmuyor

bir ucundan tut

hep ben, hep ben olmuyor

kelimeler bitiyor

yoruluyorum

bitti sanırken bakıyorum

çok iş var daha yapacak

sigaram tükendi sigaramı al, 

ateşim yanmıyor bir kibrit çak

alnımda ter birikmiş sil, 

öyle dik durma eğil

harcı karmama yardım et

yapacağın ne varsa sen keşfet

yıkma benim üzerime bu yükü

biliyorsun eminim, kısa değil bu öykü

başlangıçta mıyız 

yoksa sonda mı, onu da bilmiyoruz

yazıp duruyoruz

durup okumuyoruz

okuyup düzeltmiyoruz

ve okutmuyoruz kimseye

korkuyoruz…', 'biraz sen de gayret et yalnız olmuyor bir ucundan tut hep ben, hep ben olmuyor kelimeler bitiyor yoruluyorum bitti sanırken bakıyorum çok iş...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/katkin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma Senden Başka Bir Şey Gelmiyor', 'aklima-senden-baska-bir-sey-gelmiyor-oguzkan-bolukbasi-4bqyt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kelimeler eskiyor neyi nezaman söylesem, 

hepsi sensin

aklıma senden başka birşey gelmiyor, 

desem ki gurbetteyim

türküler uzun, gurbet sensin türküler sen, 

desem ki yalnızım dağlarda 

günler bitmiyor,  yalnızlık sen, 

dağlar sen,  günler sensiz. Aklıma senden başka birşey gelmiyor. Aklımsende, sen yüreğimde, 

yüreğim temaşada gözlerini, 

gözlerin üzüm bağlarında temmuz ayında

bağbozumuna zaman var.

Gözyaşlarımı topluyorum şimdi, üzümler toplanırken şaraba katacağım, en tatlı şaraba senin adını koyacağım ve sarhoş olacağım daha içmeden bir yudum.

Ben böyle bir sevdayı binlerce yıl önce bir kitapta okumuştum, lakin unutmuştum, yaşarken aklıma geldi, oysa yaşanılması mümkünsüz bir masal demiştim okurken o destanı, 

yaşamayan bilemez bu yaşananı, aklıma senden başka bir şey gelmiyor.

Güzellik için sözler arıyorum, aklıma senden başka birşey gelmiyor, konuşacak konular şuradan buradan geçmiş ve gelecekten, aklıma senden başka birşey gelmiyor.Şiir yazmak için oturuyorum, 

içimde coşkular taşıyor, 

 kağıtlara dökeceğim duygularımı kalemim hazır yazacağım ne yazacağım, 

 aklıma senden başka birşey gelmiyor.

Bayram yaklaşıyor şehir cıvıl cıvıl, 

 kalabalıklar sevinçli, hediyeler alacağım bu bayram sevdalarımı giydireceğim, 

aklımda kalanlara kartlar göndereceğim 

aklıma senden başka kimse gelmiyor.

Bir şarkı dinlerken hayal kuruyorum, sigaramı çekiyorum derinden, gözlerim dalıyor, ufukta gün batıyor, biriyle gidip konuşsam diyorum 

aklıma senden başka kimse gelmiyor.

Canım sıkıldığında, efkar bastığında beni, yapayalnız yürümek istemiyorum, birini arıyorum yanımda, 

aklıma senden başka kimse gelmiyor.

Ve yüreğinde papatyalar açan kız yaşamamın sebebini arıyorum 

aklıma senden başka birşey gelmiyor.', 'Kelimeler eskiyor neyi nezaman söylesem,  hepsi sensin aklıma senden başka birşey gelmiyor,  desem ki gurbetteyim türküler uzun, gurbet sens...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aklima-senden-baska-bir-sey-gelmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluşma Planı', 'bulusma-plani-ahmet-cagri-ozsema-7mxtj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer birgün yanında olmazsam 

Ve sen beni ararsan 

Gökteki her yıldızda bulursun beni 

Gökte yıldız yoksa; bulamazsan 

Korkma, ağla... 

Göz yaşlarında bulursun beni 

Olurya ağlayamazsan 

Endişelenme; 

Aynanın karşısına geç 

Gözündeki ışıltıda bulursun beni 

Olurya gözlerin parlamazsa 

Panikleme, gülümse; 

Gülüşündeki sıcaklıkta bulursun beni 

Olur ya gülemezsen 

Heyecanlanma; 

Kapat gözleri, hayal et 

Rüyanda bulursun beni 

Olurya hayal edemezsen 

Düşünme 

Elini kalbine koy 

Her kalp atışında bulursun beni 

Olurya kalbin atmazsa 

Ölmüşsen ve beni bulamamışsan 

Üzülme o zaman 

Ben cenette bulurum seni.....', 'Eğer birgün yanında olmazsam  Ve sen beni ararsan  Gökteki her yıldızda bulursun beni  Gökte yıldız yoksa; bulamazsan  Korkma, ağla...  Göz ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çağrı Özsema']::text[], 8.5, '{"poet":"Ahmet Çağrı Özsema","poet_slug":"ahmet-cagri-ozsema","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bulusma-plani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Hikayesi', 'ask-hikayesi-aziz-bulut-sj80p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eski bir hikaye, bilen bilir, bilmeyen dinlesin

Bu akla değil, gönüle yakarıştır, kalbin inlesin.

Hayata pusu kurmuş kader, gönül neylesin

Döktüğüm yaşları sor da, gözlerim söylesin.

Yaşamak gerek, durma koş dese de, gönlün sesi

Hiç mutlu sonla bitmedi, nasıl başlasın, aşk hikayesi

Kapanmaz açılan yara, bil ki bir ömür

Soran ne bilir, elbet derdimi, yaşayan görür.

Kasırgalar, fırtınalar yolumu kessede, olmaz diye

Haykırırım, sevgiyle büyüttüğüm güllerim, solmaz diye.

12-3-2002', 'Eski bir hikaye, bilen bilir, bilmeyen dinlesin Bu akla değil, gönüle yakarıştır, kalbin inlesin. Hayata pusu kurmuş kader, gönül neylesin D...', ARRAY['Türk Edebiyatı','Şiir','Aziz Bulut']::text[], 8.5, '{"poet":"Aziz Bulut","poet_slug":"aziz-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-hikayesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Bekleyiş', 'umutsuz-bekleyis-aziz-bulut-m8ci6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saçların, rüzgarlar da savrula dursun

Bense, volkanlar da yanıp kavrulayım

Gözlerin, denizler de yaşayan yosun

Bense, akıntılar da sana sarılayım

Sararıp solsa da başaklar buğdaylar

Elbet yetişir baharlar, yağmurlar

Sana hasret kaldı, umutsuz sabahlar

Bense, sensizlikte hülyalara dalayım

Yudum yudum aşk zehri içtim

Kimsesiz geceler, sonsuzluğu geçtim

Anladım ki, yanlız sensin derdim

Bense, beklerimde ilaçlar bulayım

1-7-2002', 'Saçların, rüzgarlar da savrula dursun Bense, volkanlar da yanıp kavrulayım Gözlerin, denizler de yaşayan yosun Bense, akıntılar da sana sarı...', ARRAY['Türk Edebiyatı','Şiir','Aziz Bulut']::text[], 8.5, '{"poet":"Aziz Bulut","poet_slug":"aziz-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umutsuz-bekleyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar Mavi', 'i-ntihar-mavi-yusuf-hayaloglu-4pl5s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağların dorukları dumanlı olur

Geriye dönmez savaşçılar...

Fırtınayla yıkanmıştır ömürleri

Karla yıkanmıştır yüzleri...

Bu yüzden asla vedalaşmaz

Ve kılıçlarında taşırlar şiiri! .

Bu yüzden sevdaları mahzundur

Yürekleri kallavi! 

Alınları ihanet vurgunudur.

Gözleri intihar mavi...', 'Dağların dorukları dumanlı olur Geriye dönmez savaşçılar... Fırtınayla yıkanmıştır ömürleri Karla yıkanmıştır yüzleri... Bu yüzden asla veda...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/intihar-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Şiiri 1', 'sokak-siiri-1-mustafa-hayta-8eucz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sokağın adı yoktu.

Sade bir yaşanmışlık kalmıştı, geçmişinin sularında.

Önceden yağmuru varmış, 

Kurumuş yalnızlığına hayat suyu gibi, 

Her yağmur öncesi koşar adım geçen insanları varmış, 

Bide yalnızlığını paylaştığı bitişik sokaklar.

Gün olmuş, yağmur 

Gün olmuş, dost sokaklar 

Gün olmuş, umutları

Terk etmişler bu karmaşık günlerde.

Yalnız kalmış, yağmur tanesine bile hasret.

Lambaları hayat vermiş geceleri

Yalnız kalmış kalbine, 

Bide son durak otobüsleri.

Arada inermiş, son durak otobüsünden yolcular

Hepsi bir özlemini yitirmiş.

Bu sokağın sonuna gitmiş yolculardan biri, 

Özlemini aramış sokağın sonunda

Bir umudu bulup diğerini unutmuş, 

Bu sokaktaki aranışta, 

Unutulmuş umut sokağın sonunda, 

Sokak almış umudu,  adama yetiştirememiş.

Umudu hırsla içmiş sokak, 

Susamış çatlak yolunun yalnızlığına, 

Hayat versin diye.

Umut bir ışık olmuş, 

Yerleşmiş sokağın en karanlık lambasına.

Sokak o günden beri, 

Aydınlık kalmış, ısıtmış içini ışığın özüyle.......', 'Bu sokağın adı yoktu. Sade bir yaşanmışlık kalmıştı, geçmişinin sularında. Önceden yağmuru varmış,  Kurumuş yalnızlığına hayat suyu gibi,  H...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Hayta']::text[], 8.5, '{"poet":"Mustafa Hayta","poet_slug":"mustafa-hayta","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sokak-siiri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Şiiri 2', 'sokak-siiri-2-mustafa-hayta-wy82q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sokağın adı yoktu, 

  Hep bir şeyler kaybediyordu

  Yaşamının en ilkel çağında.

  Kuruyordu gün geçtikçe

  Issızlaşıyordu kaldırımları

  Artık gün içine çıkamıyordu

  Kaybetmişti içini ısıtan umudunu

  Ona yarını bağışlayan, umudu onu unuttukça

  O yarınlarını kaybediyordu. 

  Yapılması gereken vardı aslında, 

  Anlam veremiyordu tüm bunlara

  Karşı gelmiyordu yaşama

  Mahpusluk bir türküydü aslında yaşamı

  En kahpe acılar onu bulmuştu

  Hep yarı yolda kalmıştı

  En saçma sapanda o vardı

  Boş kaldırımlar ona aitti

  Tüm yolları çatlaktı

  Umursamadı bunları 

  Efkarlı bir dumanda 

  Acımasız bir kavgada

  O hep vardı ve onun adı yoktu

                10.10.2001 (İstanbul)', 'Bu sokağın adı yoktu,    Hep bir şeyler kaybediyordu   Yaşamının en ilkel çağında.   Kuruyordu gün geçtikçe   Issızlaşıyordu kaldırımları   ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Hayta']::text[], 8.5, '{"poet":"Mustafa Hayta","poet_slug":"mustafa-hayta","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sokak-siiri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Şiiri 3', 'sokak-siiri-3-mustafa-hayta-o76eb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sokağın adı yoktu

Acıları gezerdi kaldırımlarda

Güneşi en son şubatta gördü

Kurtulamıyordu topraktan

Mıh gibi çakmıştı insanlar

Onu toprağın üstüne

Bu sokağın adı yoktu

Kaybalmuştu adres defterlerinde

En yakını yalnızlıktı

Son durağın, tek ismiydi

Hep sona kalırdı

Sona kalanı o alırdı

Sondu dertlerin acısı

Sondu karamsarlığın nedeni

Sondu son umudu

Aranışta kaybetmişti 

İlk hırsla kaybetmişti

Tüm kalabalıklarını

Tenha sokaklarda geçen hikayeler

Hep onu anlatırdı

Anlayamazdı onu son umudu

28 Kasım 2001 İstanbul', 'Bu sokağın adı yoktu Acıları gezerdi kaldırımlarda Güneşi en son şubatta gördü Kurtulamıyordu topraktan Mıh gibi çakmıştı insanlar Onu topra...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Hayta']::text[], 8.5, '{"poet":"Mustafa Hayta","poet_slug":"mustafa-hayta","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sokak-siiri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tren Kalkıyor', 'tren-kalkiyor-mustafa-hayta-yn7lt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tren Kalkıyor

Dışarıda bir soğuk beni bekliyor

Paltomu alıp adım atıyorum karanlık sokaklara

Kar yağıyor koca koca 

Bakkala sigara almaya gidiyorum

Soğuk iliğime işlemeye başlıyor

Kar yağıyor üstüme üstüme

Çay demliyorum tazecik

İlk bardağa seni koyuyorum 

İlk sigaramı sana yakıyorum

İlk hece ve tüm türküler sana

Camlar buğulanıyor

Ben sana içiyorum

Kar yağıyor camdan dışa

Yol bekliyor beni

Ben saati bekliyorum

Kar yağıyor bir yandan

İki demir yanyana uzanıyor.

Bütün demir yanlarımla 

Geliyorum sınıra

Bir tünelden geçip diğerine

Ray üzerinde sürüyor yol

Bir yandan seni düşlüyorum

Kar yağıyor demir üstüne

Geziyorum tüm sınırları

Kalıyorum tek başına ben

İlk bardak boşalırken, ilk sigara biterken 

İlk tren giderken

İkincileri başlıyor yanımda

Kar yağıyor içime içime

İkinci bardak daha da soğuk

İkinci sigara daha içilmez

Çekilmezlik içinde çekilmez bir ben

Buz tutmuş yalnızlığım cabaya kaçar

Kar yağıyor yalnızlığıma

Duman takılıyor gözüme

Uzayıp giderken kayboluyor havada

Ben ise sana kayboluyorum uzadıkça

Vücudum soğuğa çekiyor

Aklımda bir hikaye

Elektrik ısıtıyor yalnızlığımı

Sen yanımdasındır aslında

Ve akıl ermez bir hikayesindir

Kar yağıyor koca koca

İkince kez buğulanır cam

Buğu üzerine buğu

Silerim ikisini de tek elimle 

Camda kendimi görürüm

Anlatırım cama derdimi

Kar yağıyor gece gece

Yol vardır gidilmesi gereken

Kar yağıyor yol üstüne

Tıkanır tüm denemeler

Gece karanlıktır

Tüm kibritler ıslanmıştır

Mutsuzdur tüm satırlar

İsyankardır tanıdıklar

Manasızdır sözler

Yanmaz bir türlü sigaralar

Kar yağıyor saçma sapana

Biter ikinciler

Kar yağıyor açlığıma

Gece günü pazara taşımaktadır

Yeniden başlamıştır hayat

Gece gebedir güneşe

Fırından ilk ekmekler çıkar

Kar yağıyor sabaha karşı

Kendime gelirim

Yeni bir çay, ilk bardağa

İlk paketten yakarım efkarımı

Kar yağıyor geçmiş üstüne

Adım atarım yalnızlıktan

Erimiştir tüm kalıplar

Sensizimdir ilk kez

Kaptırırım kendimi nazım türkülerine

Kar yağıyor toprak üstüne

Umut doğurur kalemler

Karın üstünde bir çiçek açar

Gün ağarmış olur

Kar yağıyor geçmişin izlerine

Dönemem sana artık

Ne bir hoşça kal nede veda

Kaybolmuştur ayak izlerim

İçim garibtir

Kan ilk kez pompalanmıştır

Basınç doludur içim, dışım

Kar yağıyor içime içime

Demdi bütün çektiğimiz

Kar yağıyor sigarama

Sevinirsin, üzülürsün okudukça

Ne olur sessiz oku

Senden başka kimseye okuma

Kar yağıyor.....

22 Ekim 2001 İstanbul', 'Tren Kalkıyor Dışarıda bir soğuk beni bekliyor Paltomu alıp adım atıyorum karanlık sokaklara Kar yağıyor koca koca  Bakkala sigara almaya gi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Hayta']::text[], 8.5, '{"poet":"Mustafa Hayta","poet_slug":"mustafa-hayta","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/tren-kalkiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum..', 'bekliyorum-ozgur-altay-56psf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bekliyorum…

Geçti ömürden koca bir yıl daha, etti yirmi

Ne de çok biriktirmişim, 

Durup düşündükçe o ağızdan bir çırpıda çıkan yirmilerin, 

Kim bilir yazıya döksen altından daha kaç tozlu yirmiler çıkar

Beyaz sayfalara, beyaz kalemle yazılmış hikayeler…

Hey gidi dost, heyy! 

Hani bir söz vardı “hayatının baharında..”

Biz ondaymışız da haberimiz yokmuş

Gel dost, gel, 

Bari biz kandırmayalım kendimizi

Ne için yaşıyorduk biz, unuttun mu? 

Elimiz kalem tutmaya başladığından beri, 

Kurşun kalemimizi her yontuşumuzda, 

Hayatımızın kabuğunu soyarmışız meğer…

Dün bir etrafıma baktım, 

Herkes koşturuyor, 

Kimisi iyi bir iş, kimisi eş, kimi de para için çabalıyor ya..

Yalan…

Önce para, 

Hayır hayır, en son..

Aman ne fark eder ki? 

Nasılsa onun için uğraşırken olmadık mı kendimizden, 

Baharımızdan…

Bir gün bakabildik mi mehtaba oturup, doyasıya

Seninle günbatımını seyredecektik dağlarda yaylalarda, ne oldu? 

Üzülme be dostum, ben bile unuttum

Yaşıyoruz ya şükür, 

Elbet ki yaparız bir gün...

Masal..masal..

Bir benim elimde olsa çoktan satmışım bu dünyayı, 

Buranın düzeni bu, böyle çizilmiş yazımız..

Yer: Derin bir kuyu

Zaman: Bir ömür

İnfaz: Beslenme çantanda kırık hayallerin, 

          Mataranda umutların, bu kuyuda sıkışıp kalmak..

Ne zaman çıkarız bu kuyudan, kabuğumuzdan sıyrılıp

Bilemem..

Sen de yarınlarda, bense hiçbir zaman..

Zaten yarınlarda çıkmaz bir sokak değil mi? 

Sen hiç gördün mü yarınların bittiğini? 

Bitmez dostum bitmez, 

Biri biter diğeri başlar..

Ama ben bir yol buldum kendime, 

Hayattan izin almışım, 

Elimde bir kırık kalem, arkamda anılarım bekliyorum..

Oturmuşum bir taşa deryanın semalarında bekliyorum..

Bekliyorum bir şişe gelecek, 

İçinde bir pusula tüm dostlara

Bekliyorum, 

Bekliyorum içinde ne yazdığını bile bile bekliyorum, 

Bir umutla, sadece bir umut..

Bekliyorum, bekliyorum…', 'Bekliyorum… Geçti ömürden koca bir yıl daha, etti yirmi Ne de çok biriktirmişim,  Durup düşündükçe o ağızdan bir çırpıda çıkan yirmilerin,  ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Altay']::text[], 8.5, '{"poet":"Özgür Altay","poet_slug":"ozgur-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/bekliyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişken Dünyanın Sabiti', 'degisken-dunyanin-sabiti-mehmet-caner-sumengen-7u7sq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Değişken bir dünyada ben sabit kalıyorum...

Herkes başka başka severken, 

Ben yine seni seviyorum...

Ah be Gülüm! 

Duysan beni şimdi...

Gözyaşların sel olur, 

İçin kanardı...İçin...

Ayrıldık ayrılmasına ya, 

Ne geçti elimize ikimizde anlamadık.

Bir anlamsızlık silsilesiydi, 

Bir boşluk anıydı, 

Hata ya sen de, ya ben de, ya da hiçbirimizdeydi...

Belki de zaman böyle istedi...

Evet! 

Kıskanılacak dakikaları yaşadık diye, 

Zaman bunu istedi...

Ama bak! 

Unutmadım...

Adın ağzımın besmelesi oldu...

Eksilmedin, arttıkça arttın.

Dedim ya...Hiç unutmadım...

Ve hissediyorum sen de! Sen de! Sen de! ...

Bil ki düşündüğümden daha zor oldu, 

Yokluğunun azabına katlanmak.

Aslına bakarsan eritti, bitirdi beni bu yalnızlık.

Günden güne tüketti, 

Hastalık misali işledi bedenime, 

Acıttı yüreğimi, 

Ok ok saplandı sevdan beynime...

Biz iki kişiyken, yanyanayken ^^sevgi^^ demektik...

Sonsuz paylaşımlı, 

Özenle sürdürülen her birliktelik gibi.

Biz iki kişiyken, yaşam; 

^^Varolmanın tadıydı^^.

Şimdiyse mecburi bir hizmet...

İçimdeki umut taneciklerinin verdiği sabırla, 

Dönersin ihtimaline...

Seversin ihtimaline...

Değişken bir dünyada ben sabit kalıyorum...

Herkes başka başka severken, 

Ben yine seni seviyorum...

Uzakta da olsan, arada sırada da olsa, 

Alıyorum haberini.

Bizi bizli sevenler sağolsun...

Sen de üzgünmüşsün.

Sebebini anlatamadığın bir hüznün gölgesinde, 

Güneş doğmuyor onsuz diyebilecek kadar...

Benim kadar...

Gizlesen de duygularını, 

Senin için de kaygı duyanlar, 

Ne oldu bu kıza diyenler varmış, 

Aynı benim gibi...

Haykırırsın duvarlara sesin duyulmaz, 

Yalvarırsın Allah''a duan kabul olmaz...

İşte dertler denizimden en sert dalgalar, 

Daha başka sayayım mı? ...

Bekliyorum hep de bekleyeceğim...

Rüyalarımda gülerek bana ^^seni seviyorum^^, 

Dediğin günleri görebilmenin tesellisiyle...

Ta ki...Omzuma yaslanıp, 

^^Tüm bunlar kabustu^^ diyeceğin zamana dek...

Kalbimde koruduğum, 

Eskimesine izin vermeyeceğim, 

Dünyalara bedel, 

Mecnun''un Leyla''ya, bülbülün güle duyduğu, 

Doğanın vazgeçilmez duygusu, 

Aşkın, aşkının, aşkımın inancıyla...

Evrenden, bir noktadan, 

Herhangi bir metafizik boyuttan, 

İzim silininceye dek...

Bekleyeceğim...Bekleyeceğim...

Kalbimin ortağısın...

Kalp çıkmazımsın...

Bekleyeceğim...', 'Değişken bir dünyada ben sabit kalıyorum... Herkes başka başka severken,  Ben yine seni seviyorum... Ah be Gülüm!  Duysan beni şimdi... Gözy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/degisken-dunyanin-sabiti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terzi Olsam', 'terzi-olsam-mehmet-caner-sumengen-ypiqu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Terzi olsam...

Elime iğne ipliği alır, 

Aşkınla yırtılan yüreğimi dikerdim.

Gözlerimden gözyaşlarım dinsin diye, 

Yamalar yapar, 

Üstüne bir kördüğüm eklerdim...

^^Sn. Bedirhan Gökçe''ye teşekkürlerimle^^', 'Terzi olsam... Elime iğne ipliği alır,  Aşkınla yırtılan yüreğimi dikerdim. Gözlerimden gözyaşlarım dinsin diye,  Yamalar yapar,  Üstüne bir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/terzi-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk II', 'cocuk-ii-yusuf-ozkay-ccztd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocuk minik bir kız sevdi.

Hayalindeki tek şey mavi panjurlu evdi.

Yüreğinde yanan sönmek bilmez alevdi.

Bir sevdaydı ki sanki koca bir devdi.

Çocuk ağladı minik kız sustu.

Garibim her gün yürek dolusu sevda kustu.

Daha üç gün evvel hayal denizinde yunustu.

Çekildi bir kenara öylece pustu.

Çocuk param parça çocuk perişan.

Kurusun diyordu bu sevda nehri her an

Minik kız anlayamadıki hiç bir zaman.

Ne büyük fırtınaydı o yürekte kopan.

                                           

                                     (14-02-2001 Eskişehir)', 'Çocuk minik bir kız sevdi. Hayalindeki tek şey mavi panjurlu evdi. Yüreğinde yanan sönmek bilmez alevdi. Bir sevdaydı ki sanki koca bir devd...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Özkay']::text[], 8.5, '{"poet":"Yusuf Özkay","poet_slug":"yusuf-ozkay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cocuk-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-yusuf-ozkay-x6f0k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Görmek seni, 

Nisan yağmurlarının şahlanışında

İki ders arası sigara molasında

Sevda ırmağının öbür yakasında, görmek seni.

Bilmek seni, 

İsminin her harfinin alfabesinde

Sıcak tebessümünün gamzesinde

Aşk portresinde duran resminde, bilmek seni.

İzlemek seni, 

Kovalandığından habersiz bir takipte

Farkedemeyeceğin zifiri sessizlikte

Umut gemisiyle sevgi denizinde, izlemek seni.

Yaşamak seni, 

İlk bahar kokan rüzgar sesinde

Gülünde, lalesinde, karanfilinde

Ruhuma haz veren tüm güzelliklerde, yaşamak seni.

Sevmek seni, 

Ateş gözlerinin parıltısında

Nilüfer saçlarının alacasında

Masum bakışlarının saflığında, sevmek seni.

Özlemek seni, 

Yollar uzamaktan yorulduğunda

Fikrime hayalin sorulduğunda

Gönlümde yokluğun tutuştuğunda, özlemek seni.

Beklemek seni, 

Düşünceler bitip tükendiğinde

Gözlerim gözlerinde gezindiğinde

Türküme sen deyip söylediğimde, beklemek seni.

                                     (29-05-2002 Eskişehir)', 'Görmek seni,  Nisan yağmurlarının şahlanışında İki ders arası sigara molasında Sevda ırmağının öbür yakasında, görmek seni. Bilmek seni,  İs...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Özkay']::text[], 8.5, '{"poet":"Yusuf Özkay","poet_slug":"yusuf-ozkay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/seni-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karatutku', 'karatutku-mehmet-yasin-cdnw0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pathos

Sen verdin bu adı bana ayrılırken

adımla gideyim diye gideceğim yere.

Önce bir kaçkınsın: ............

''Gitme'' demektense-

Sonra yerin dibine batsın fantezilerin

kağıt, kalem, bir de çalışma masası istiyorum ben

BİR ŞİİRİ BİR ÜLKEDE BİTİREBİLMEK İSTİYORUM

Açılırken denize son adalıydın sen

ardımdan seslenen: Pathos, 

bizim oradaki bir türküdür beni sevmen, bir dağköyü

artık geriye çıkamay''cağım

Pathos eski bir iççekiş...

Londra''ya inen uçaklara binmeyeceğim

yeraltıtreninin seyahat-kartını sana postalıyorum

cehenneme kadar yolun var istediğin istasyondan.

Suçlarını biliyorsun Pathos

sonra İngilizce açıyorsun kapıyı

Yunanca sevişiyorsun, bitti

ya da Türkçe çağır beni.

Gideceğim, hiçbir aşkın sahibi değil bu ülke

ıssız ada Pathos aşk uğruna cinayet işlenmedi tarihimizde.

Beş parasızım İmroz adasındayım

her yanı denizle çevrili dağbaşı, yurtsuyorum.

(Düşüme dün giriyor, 

Orly''e bırakılıyorum

uçak kalkacağı için öpüşüyoruz sevgilimle

''Ben de Lefkoşa''da doğdum'' diyor, Türkçe diyor ilk kez

gizli iki yeşil yaprak dökülüyor gözlerinden

efkalito ağaçlarını çıkarıyor gömdüğü yerden

büyülü şişelerden sıcak toz bulutlarını...

''Hadi'' diyor, ''biletini ertele de dönelim''

-ineklerin sesleriyle uyandım-

gideceğimden emin olmasa diretmezdi zaten.) 

Pathos ikimizden başka hiç kimse yok dünyada

Türkçe çağır çağıracaksan

Türkçe yok Kıbrıs Cumhuriyeti pasaportunda

-anlamadığım bir alfabeyle yazılı adım-

otel girişinde şişkonun teki pasaporta bakıyor

bakıyor bakıyor ''Nationalité Monsieur? ''

işte bütün mesele.

Bak Pathos

hala Kıbrıs Cumhuriyeti yurttaşıysan iddia ediyorsan

					gideceğim

Çanakkale''den saat 16.00''da gemi kalkacak

ciddi söylüyorum Pathos hep gideceğim sana...

Kendimden ödüm kopuyordu ki şöyle dedin: 

''Artık git sana bağlanmaktan korkuyorum.''

Rezaletin daniskası doğrusu, herkese anlatacağım bunu

bak görürsün, herkese.

Pathos Londra kaç saat ilerde şu an

öyle çok uğraştım ki sana aşık olmak için -yorgunum şimdi-

keşke diyorum bir başka iş tutsaydım.

İster er ister dişi bir insan arıyordum

ben sevmek ve sevilmek istiyordum

-bir de kağıt, kalem ve çalışma masası-

hala sevgi arıyorum Pathos yalnızca sevgi

ve herhangi birisini.

Sana aslında aşık olmadığ''mı düşünmek istemiyorum şimdi

lütfen bana engel ol.

Bu dünyaya nasıl dayanabileceğim Pathos, bilmiyorum

seni düşünerek dans ediyorum son sevgilimle seni düşünerek

Pathos ikimizden başkası olsaydı dünyada

yok işte! 

-acı çekiyorum aşık olmayı başardım sonunda-

Ege''de dolaşıyorum İngilizce konuşarak, herkes bi'' kibar

polisler kimlik sorunca, gene İngilizce

Türkiye''de ne zaman başım sıkışsa Pathos

İngiliz oluyorum, Yunan oluyorum, Türk bile oluyorum.

(İmroz''dan bir düş daha, 

yalan söyledikçe burnu uzamayan Pinokyo

1958 no''lu televizy
..........
..........', 'Pathos Sen verdin bu adı bana ayrılırken adımla gideyim diye gideceğim yere. Önce bir kaçkınsın: ............ ''Gitme'' demektense- Sonra yeri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yaşın']::text[], 8.5, '{"poet":"Mehmet Yaşın","poet_slug":"mehmet-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/karatutku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Kaynanam Gel*', 'gel-kaynanam-gel-bayram-tunca-vnfee', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel kaynana gel çok şikayetim var sana

Bak hele kızın ne hale getirdi damadına

Bazen şikayet edesim geliyor seni O’na

Anam olduğundan kıyamıyorum ki sana

Sen hiç de böyle tanıtmamıştın bu kızını 

Bak, tabibler dahi dindiremiyorlar sızımı

Eğer ki acı söylersem sakın hiç de kızma

Sen, hiç mi anlatmadın, bu hayatı kızına

Onun bu kadar çok çektireceğini bilseydim

Hiç gönlümü yoluna halı gibi serer miydim

Hiç onu bir Ferhat misali çok sever miydim

Acep onu bu kadar çok sevmesem miydim

Şair o günden beri, inleyen dertli bir neydi

Gözyaşı deryaya,  inleyişi de semaya değdi

Bu kızının elinden, dilinden, çektiğim neydi

Biliyorum, bu çektiklerim, alınyazım/çileydi

Hani onun on parmağında ayrı hüner vardı

Ancak beşini gördüm acep başka neyi vardı

Nazı ve acı sözlerinden başka da neyi vardı

Baharımda, kaç kez beyaz gömlek arattırdı

Ona hayatın gerçeklerini anlatmak çok zordu

O, hayatta beni dostlarımdan dahi çok yordu

Önce aşkıyla yaktı, sonra da külümü savurdu

O, çilemle birlikte hayatta yakan ak bir kordu

Gel kaynanam gel  hanemizin has misafiri ol

Gel kaynanam gel gönlümüzün tek sultanı ol

Gel kaynanam gel başıma taç/derdime ilâç ol

Düşünüp/taşındım, yok başka da bir çıkar yol

Zor kaynanam zor, ona laf anlatmak çok zor

İnanmıyorsan gel de yerdeki/göktekilere sor

Yıllarca, bu dert kalbimi akkor misali yakıyor

Damadın şair Bayram senin yollarına bakıyor

10.05.2002-10.10', 'Gel kaynana gel çok şikayetim var sana Bak hele kızın ne hale getirdi damadına Bazen şikayet edesim geliyor seni O’na Anam olduğundan kıyamı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gel-kaynanam-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazı Çizi', 'yazi-cizi-serpentor-the-great-w7iyd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaz''ı

Nerden çikti ki simdi bu sizi

Tam yakaladık derken ansızı

Belki bitirilmemis bi en baş''inda yagmurcuk

Kimbilir belki de dökülmemis bir gözyasinda çocuk

Zamana bürüdük derken zamansızı

Dilsizlikte söz söyleme sanatı

Dinsizlikte banlama çabası kainatı

Özletir ya hep kendisini

Öyleyse istek kipinin hediyesi

  (ki verilmez; alınır) 

Bir ''evet''tense

Haber kipinin hatirasi bir ''hayir''da

Sensizlikte

Daha mı iyi göstersin sevi

Öznesini', 'Yaz''ı Nerden çikti ki simdi bu sizi Tam yakaladık derken ansızı Belki bitirilmemis bi en baş''inda yagmurcuk Kimbilir belki de dökülmemis bir...', ARRAY['Türk Edebiyatı','Şiir','Serpentor The Great']::text[], 8.5, '{"poet":"Serpentor The Great","poet_slug":"serpentor-the-great","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yazi-cizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçücük ve Kocaman', 'kucucuk-ve-kocaman-ahmet-kuruoglu-mcc88', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umarım 

Benim yazarken

''Arkadaşım'' diye ördüğüm 

Harften kaleler 

Güngelir

Sen okurken

Yerle bir oluverirler.

Sana yalnızca dokuz harfin

Arkasında gizlediğim

Kocaman seni gösterirler.

Sana gözlerinin önünde gizlediğim

Küçücük beni gösterirler.', 'Umarım  Benim yazarken ''Arkadaşım'' diye ördüğüm  Harften kaleler  Güngelir Sen okurken Yerle bir oluverirler. Sana yalnızca dokuz harfin Ark...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kuruoğlu']::text[], 8.5, '{"poet":"Ahmet Kuruoğlu","poet_slug":"ahmet-kuruoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kucucuk-ve-kocaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-ahmet-kuruoglu-rw8o9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gitmeliyim...

Çünkü: 

Sana yazdığım satırları

Şuna buna yazdım demekten

Biri hariç bildiğim tüm isimler 

Sonunda tükendi.

Çünkü: 

Alnımda yazmayan yazıyı

Kağıtlara dökmekten

Kıyıda köşede biriktirdiğim tüm harfler

Sonunda suyunu çekti.

Elimde avucumda sadece

Oda yanyana hiç yazamayacağım

İki büyülü kelime ile

Birde mühürlü isim kaldı.

Gitmeliyim...

Çünkü: 

Artık ne yüzüne bakacak yüzüm 

Nede ayakta duracak gücüm kalmadı.

Hoşçakal, hoşçakal...

Arkadaşlık masalımın

Bükük boyunlu 

''Güzel kızı''.

Hoşçakal, hoşçakal...

Denizi olmayan bu diyarın

Toprak kokulu

''Deniz kızı''.', 'Gitmeliyim... Çünkü:  Sana yazdığım satırları Şuna buna yazdım demekten Biri hariç bildiğim tüm isimler  Sonunda tükendi. Çünkü:  Alnımda ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kuruoğlu']::text[], 8.5, '{"poet":"Ahmet Kuruoğlu","poet_slug":"ahmet-kuruoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hoscakal-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer Dilsizmiş', 'meger-dilsizmis-ahmet-kuruoglu-z2mlc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sesim! 

Bak sakın ha titrememelisin

Sizde rahat durun dizlerim

Kalbim ferah olmalısın

Sen günah işlemedin

Hadi harflerim

Özlediğiniz sıraya dizilin

İki gözüm! 

Öyle bakıpta dalıp 

Sonrada kaçıp gitmeyeceksin

Tamamsa, anlaştıksa

Hadi bakalım

Ha gayret dilim

Şimdi tam zamanı

Erircesine çözülmenin

Şimdi son fırsatı

Dilediğince dönmenin

Artık efendisi gibi davranmanın 

Zamanı geldi harflerin

Artık kırmalısın belini

O asi iki kelimenin

Ona artık söylemelisin

Allah aşkına 

Neyin var senin

Biliyorum söylemeyeceksin değil mi? 

Söyleyemeyeceksin

Belki onu birdaha hiç göremeyeceksin

Belkide ömrün peşinden koşmakla

Geçicek keşkelerin

Ama sen yinede söylemezsin değil mi? 

Önceden anlamalıydım

Neyi biliyormusun? 

Hani o dünyanın en çok konuşan

Hiç susmayan

En geveze ağzı varya 

Meğer dilsizmiş

Harflerin efendisi filan değil

Meğer kölesiymiş

Herkese 

Herşeyi söylerde

Sevdiğine

Seni seviyorum diyemezmiş.', 'Sesim!  Bak sakın ha titrememelisin Sizde rahat durun dizlerim Kalbim ferah olmalısın Sen günah işlemedin Hadi harflerim Özlediğiniz sıraya ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kuruoğlu']::text[], 8.5, '{"poet":"Ahmet Kuruoğlu","poet_slug":"ahmet-kuruoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/meger-dilsizmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını İkiniz Koyun', 'adini-i-kiniz-koyun-ahmet-kuruoglu-przrd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Abim YUNUS''a

Yengem NURGÜL''e

Bir gül var ki: 

Rengi, 

Ne sarı 

Nede mavi

Rengi dumanlı gizemli.

Bir gül var ki: 

Anlamı, 

Ne ayrılık

Nede sevgi

Anlamı barındırır tüm hisleri.

Bir gül var ki: 

Adı, 

Ne Songül

Nede Goncagül

Adı NURGÜL.

Nurgül ki: 

Açmamış, 

Ne gülistanda

Nede mor dağında

Filizlenmiş mavilerin anavatanında.

Nurgül ki: 

Bakmazmış hiç, 

Ne tabiatın gökkuşağı kaftanlı kelebeklerine

Nede kainatın en güzel şakıyan sesli bülbüllerine

Çünkü gönülcüğü kayıvermiş

Mavi suların YUNUS balığı kılıklı

Utangaç efendisine.', 'Abim YUNUS''a Yengem NURGÜL''e Bir gül var ki:  Rengi,  Ne sarı  Nede mavi Rengi dumanlı gizemli. Bir gül var ki:  Anlamı,  Ne ayrılık Nede se...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kuruoğlu']::text[], 8.5, '{"poet":"Ahmet Kuruoğlu","poet_slug":"ahmet-kuruoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/adini-ikiniz-koyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soluk Soluğa I', 'soluk-soluga-i-ahmet-telli-dn3ta', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep yanıldı ve yenilgilere uğradı

Ama atıldı yine de serüvenlere

Vakti olmadı acıların hesabını tutmaya

Durup beklemeye, geri dönmelere vakti olmadı.

Yangınlarla geçti ömrü ve hep yalnızdı

- ki onlar daima birer yalnızdılar

Nerde doğmuştu ve ne zaman kopup 

Gitmişti o kentten anımsamıyor artık

Hangi sokaktaydı ilk sevgili ve hala

Sürüp gider mi ilk öpüşmenin esrikliği

Gizlice buluşmaya gelen ve ölürcesine 

Korkular geçiren o kız nerededir şimdi

Sensiz olursam yaşayamam diyen

O liseli kız hangi kentte kaldı

Ve o sarışın

O afeti devran bekler mi hala

Atlas yataklara sererek yaşamanın anlamını

Üşüten bir acıydı belki her ayrılık

Her yolculuk yangınların başladığı yereydi

Ama vakti olmadı hesabını tutmaya

Aşkların, ayrılıkların ve acıların

İstese de kalamazdı vakti gelince 

Geyik sesleri yankılanınca yamaçlarda

Yürek burkulması ve hüzün ve keder

Aralıksız doldururdu acıların bohçasını

Dudaklarında öpüşlerin gül esmerliği

İçinde kıpırdanıp durur ufuk çizgisi

Ay bile soğuktur o zaman 

Bir buz parçasıdır

Çaresiz çıkılacaktır o yolculuklara

Ki bir ömrün karşılığıdır serüvenler

Biraz da serüvendi yaşamak 

Belki yatkındı büyük yolculuklara

Ki serüvenler daima büyük aşklar 

Ve büyük yolculuklarla başlar

Anıları aşkları ve bir kenti 

Bırakıp gidebilirdi apansız

Apansız başlardı yolculuklar

Hangi saatinde olursa günün

Ve hep kar yağardı nedense

Durmadan kar yağardı yol boyunca

Ve nasılsa yok olup giderdi hüzün

Kent görünmez olunca arkada

Ne bir veda sözcüğü dökülürdü dudaklarından

Ne de dönüp bakardı geriye bir kez olsun

Ne zaman yollara düşse biterdi acılar

Gül yüzlü sular fışkırırdı toprağın karnından

Kavaklarsa oynak bir çingene kızı

Her kıpırdanışında açılıverir uzun ince bacakları

Mekan tutmak ve her akşam aynı ufukta

Güneşin batışını seyretmek ölümdür biraz

Ölümdür biraz hep aynı yatakta

Aynı kadınla sevişerek sabaha varmak

Kitapları hep aynı raflara sıralamak

Aynı eşyayı kullanmak eskimektir biraz

Soluk soluğa yaşamalı insan 

Her sabah yeni bir şeyler görebilmeli

Ve cehenneme dönse de bir ömür

Mutlaka bir şeyler değişmeli her/gün

Ey o büyük yolculukların ürperten heyecanı

Okyanus dalgalarının sesleriyle dol bu ömre

Ölüme ve aşka durmadan kement atan

Serüvenlerle geçsin yaşamak

Buz tutmuş bir dünya ortasında 

Yollara düşerdi o hep aynı ıslıkla

Önünde dağlar, uçurumlar

Sarsılan gök, yarılan toprak

Çelik uğultularla burgaçlanırken 

Yaşamak işte öylesine kucaklardı onu

Ve her nasılsa keklik sekişli

Bir aşkın sevinci dolardı yüreğine 

Çıkarıp atardı o zaman deli bir ırmağa

Ne kalmışsa bir önceki serüvenden

Soluk soluğa yaşadı kentleri, aşkları

Bağlanacak kadar kalmadı hiçbirinde

Pervasız bir acemi, bir çılgın

Soyu tükenen bir bilgeydi belki de...

O yalnız kaybetmesini öğrendi ömründe

Avucundan dökülen kum taneleriydi her şey

Ne bir serseriydi ne de yılgın bir savaşçı

Ama kendi kafasıyla düşünen ve hakkında 

Ölüm fermanları çıkartılan biriydi belki 

Sevince deli gibi severdi

Pervasız severdi sevince 

Dövüşmek ancak ona yakışırdı

Ona yakışırdı aşklar ve yolculuklar

Yoktu bağlandığı herhangi bir şey

Bulutlar gibi çekilip giderdi seslerin arasından

Ne bilir ömrün değerini bir çılgın

Yalnızca kendini yaşamayı nereden bilebilir

Ve başarısız eylemler çağında o

Kaçabilir mi binlerce kez ölmekten

Yerleşik yargıları olmadı hiç

Kurmadı güzel gelecek düşleri

Nerede bir yangın, nerede tehlike 

O mutlaka oradaydı birdenbire

Dinsizdi, özgür sayılırdı belki

Ama bağlanmazdı özgürlüğe de

Hiçbir yerde yeterinden çok kalmadı

Beklemedi anılar sarnıcının dolmasını

Şikayetsiz yaşadı yaşadığı her günü

Yoktu yüreğinde pişmanlıkların izi

Ayrıntıların izi kalmamış artık

Üst üste yaşanmakta ayrılıklar

Ve bir bulut gibi sıyrılıp gidilmiştir

Dağların, denizlerin üzerinden

Geride kalan ne varsa soluktur şimdi

Titreyen kandiller gibi sönmek üzeredir

O eski konaklar gibidir anılar

Gül bahçeleri, sessiz koru ve orman

Belki sağanak boşanır apansız

Yüzyıllık bir yağmur başlar

Ve sinsi bir hastalığa dönmeden alışkanlıklar

Yok olup gider her şey, belki kül olur

Hırçın bir okyanustur yürek

Dar gelir ufuk ve mutluluklar çevreni

Anılarsa birer çıban izidir

Yaşanmaz onların ölgün gölgesinde

Durgun bir su gibi aktı mı yaşamak

Ve zaman uysal bir kısrak gibi dinginleşti mi

Anısız kalınmıyor artık ne yapılsa

Kuşatıyor yolları, aşkı ve ömrü

Bekleyişleri kemiren çakal sesleri

Oysa bütün köprüler yakılmalı ayrılık vakti

Ve herhangi bir şeyle eşit olmaksızın

Yollara düşülmeli habersiz ve sessiz

Çürük bir diş gibi kanırtıp kentleri

Dünyanın ağzını kanlar içinde bırakmalı

Bir ömrün olgunlaştıramayacağı 

acemilikler toplamı ve bir çılgın

boyun eğmedi kendine bile

seçme zorunda kalmadı yaşamayı

nasıl bağlanmadıysa yere ve zamana

bağlanmadı kendine de ömür boyu

dağlara tırmana atlar gibi 

soluk soluğa yaşamak istedi dünyayı

bir şahin gibi bulutlara kurdu

dumanlı sevdaların yörük çadırını

sıradan bir gezgin değildi hiç

dövüşür gibi yaşadı yolculukları 

belki korkusuz sayılmazdı büsbütün

korkardı korkulara düşmekten zaman zaman

ve bütün gemileri yakıp

yollara düşerdi o hep aynı ıslıkla

mutlu muydu, hiç düşünmedi böyle şeyleri

umutlardansa nefret etti daima

hep yanıldı ve yenilgilere uğradı

ama atıldı yine de serüvenlere

pervasız bir acemi

soyu tükenen bir bilgeydi belki de 

Ama bir şey vardı yine de

Başarısız ihtilallerden kendine kalan', 'Hep yanıldı ve yenilgilere uğradı Ama atıldı yine de serüvenlere Vakti olmadı acıların hesabını tutmaya Durup beklemeye, geri dönmelere vakt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":152,"source_url":"https://www.antoloji.com/soluk-soluga-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soluk Soluğa II', 'soluk-soluga-ii-ahmet-telli-0obap', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Büyük aşklar yolculuklarla başlar 

ve serüvenciler düşer bu yollara ancak 

Onlar ki dünyanın son umudu 

soyları tükenen birer çılgındırlar 

Ama yaşarlar dünyanın dört bir yanında 

Ölümle alay ederler sanki 

Nerde beklenirse ordaydılar 

bir kez bile gecikmediler ömür boyu 

Neydi onları ordan oraya 

savurup duran şey 

Onları daima yalnız kılan 

neydi bu yaşam denilen gürültüde 

Her dilden bir adları vardı onların 

ama hiçbir ülkenin kimliğini taşımadılar 

Sarışındılar belki de esmer 

yani birçok yüzün bileşkesi 

Ne altın arayıcısıydılar 

ne de aylak bir gezgin 

Vurulup düşseler de her kuşatmada 

serüvencidir onlar ve hiç ölmezler 

Ki onlar hep yalnızdır ve her nasılsa 

Bulurlar heder olmanın bir yolunu 

Onlar ki bu dünyada 

kahraman olmaya mahkumdurlar 

Sislenen anılar kaldı bize onlardan 

renkleri bozulup duran solgun anılar 

Nasıl yazmalı ki silinip gitmesin 

bulutlar gibi çekilmesin gök boşluğuna 

Bileği güçlü ve gözüpek avcılar mıydı 

onları kuşatıp yeryüzü cennetinden atan 

Yoksa kendini tüketen hüzünler miydi 

vurulup düştükçe ışığını karartan 

O serüvenlerin günlüğü tutulmadı 

yazılmadı o insanların destan şiiri 

Parça parça ettirilseler bir kartala 

(ki sanırım böyle oldu sonları) 

Fışkırır yüreklerinden 

başarısız ihtilallerin yangınları', 'Büyük aşklar yolculuklarla başlar  ve serüvenciler düşer bu yollara ancak  Onlar ki dünyanın son umudu  soyları tükenen birer çılgındırlar  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/soluk-soluga-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-bahadir-kaan-ozturk-ur033', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessizlik, alabildiğine sessizlik bana sunduğun.. 

Gecelerimi harcarken sana dair düşlerle, sen bana Umutsuzluğun zehrini uzatıyorsun gümüş kadehlerde.. 

Ve susuyorsun alabildiğine.. 

Sustuğun yerde kırılıyor her şey; bilmiyorsun..

Sabah olmak üzere bu şehirde.. 

Gececi sevdalardan eser yok artık.. 

Çöpçüler sokaklara atılan adilikleri temizleme telâşında, Dillerinde memleketimin yanık ezgileri.. 

Birkaç konsomatris evlerine gidiyor; yüreklerinde kirletilmiş Kadınlıkları, sırtlarında yarım kalmış sevdaların kamburunu Kaşıyorlar.. 

Gözleri, bedenleri hüzün kokuyor; bakamıyorum yüzlerine.. Yeterince hüzün depolamışım.. 

Dağları seğiriyor gözlerim.. 

Yüreğimi bir dağlar anlıyor, gerisi sağır sessizlik.. 

Gerisi adi, kirletilmiş alabildiğine.. 

Şairin dediği gibi; dağların acısı çoktu, acının dağları yoktu..! Sonu ölüm olan bir şarkıya başlamışım lâli.. 

Hep başa sarmaktan yorulduğum kasetin sonunu Dinlemeliyim artık.. 

Yüreğim dayanmıyor verdiği acılara bu izbe mekanın.. Gitmem gereken yerler var biliyorum; ama neresi, nasıl gidilir Bilmiyorum.. 

Kocaman soru işaretleri.. 

Aradığın yol senin de bilmediğin yoldur derken çok haklıymış O adam, şimdi anlıyorum.. 

Yine geceyi rehin bırakıyorum gündüze ve takınıyorum Oyuncakçı amcanın sattığı umut maskelerini.. 

Yüzümden akan hüznü görmesin istiyorum hiç kimse.. 

Ve korkutmasın insanları yüreğimin rengi.. 

Kan sızdıran yaralarıma düş kırıklarımı sarıyorum.. 

Tuz basmışçasına acı veriyor, ama olsun.. 

Ne çıkar ki alışık değil miyim acıya..? 

Gece bitti lâli.. 

Hatırlarsın bir zamanlar çıplak ayaklarla yürürdüm karda.. Soğuğa inat.. 

Buzu dondurmayı öğrenmeye çalışırdım; başarmıştım.. Şimdi sıra ateşte lâli..

Ellerim ateşi yakmayı öğreninceye dek onunla oynamaya Devam edeceğim.. 

Biliyorum söyleyeceklerini..

Sus, konuşma ne olur..', 'Sessizlik, alabildiğine sessizlik bana sunduğun..  Gecelerimi harcarken sana dair düşlerle, sen bana Umutsuzluğun zehrini uzatıyorsun gümüş ...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Kaan Öztürk']::text[], 8.5, '{"poet":"Bahadır Kaan Öztürk","poet_slug":"bahadir-kaan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sessizlik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Çocuk', 'suskun-cocuk-bahadir-kaan-ozturk-o8awy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sokaklarda sahte gülüşler, 

Ve ben karanlığa gidiyorum bu şehirde.. 

Cebimde misketlerim, 

Yüreğimde kan kaybeden bir çocukla.. 

Susuyor çocuk.. 

Konuştukça başıma bela açan o değil mi zaten..? 

Susturuyorum, 

Yüreğine basıyorum acil kanamalı hastalar gibi.. 

A grubu Rh pozitif umutlar arıyorum, 

Oysa herkesin elinde B grubu Rh negatif hüzünler var.. 

Kaçıyorum, 

Yine kaçıyorum..

Adiyim, çocuğu boğazlıyorum.. 

Sonra kimsenin beni bulamayacağı derinliklere, 

Sevgilerin olmadığı o içsel yolculuğa çıkıyorum ben de.. 

Sevgilerim gazoz kapaklarım kadar değerli değil gözünde kimsenin.. 

Ya gerçekliklerim..? 

Onlar yoklar ki..! 

Şarap şişelerinin içine hapsettiğimi sandığım acılar 

Meğer sadece kendi imgelerimmiş.. 

Şişelere bakamıyorum.. 

Odam koksa koksa sigara kokar, 

Oysa bugün matem kokuyor.. 

İçimdeki çocuğa basit bir cenaze töreni tertipliyorum, 

Kimseye haber vermiyorum.. 

Ne de olsa tanıyan yok onu..

Kimsesiz kalabalık, acılara gebeyim.. 

Susuyorum, konuşmayı bilmediğimi sanıyor insanlar..

Susan bir çocuktan daha tehlikeli ne olabilir..?', 'Sokaklarda sahte gülüşler,  Ve ben karanlığa gidiyorum bu şehirde..  Cebimde misketlerim,  Yüreğimde kan kaybeden bir çocukla..  Susuyor çoc...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Kaan Öztürk']::text[], 8.5, '{"poet":"Bahadır Kaan Öztürk","poet_slug":"bahadir-kaan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/suskun-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Öyküsü', 'yasamin-oykusu-mustafa-sureyya-sezgin-dyud1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat bence

Tanrı denilen varlığın

İnsan adını verdiği kuklalarıyla

Oynadığı bir oyundur.

Yüklemiş kuklaların sırtına, 

Geçmiş denilen yük torbasını

Sürüklüyor insancık, 

Kendisiyle birlikte bu ağır yükü

Gelecek dediği, 

Orada mutlu olabileceğini

Umduğu, 

Titrek bir ışığa doğru.

Sırtındaki heybeden ara sıra

Bir iki azık çıkarıyor, 

Yiyip güçlenmek için.

Bunlar, 

Yitirdiği sevgili, kaybettiği gururu...

Meyve diye yiyor, sevgilisinin bakışlarını.

Su diye içiyor, gururunu.

Yeni umutlar uyanıveriyor içinde birden...

Sürükleniyor yaşamın peşinden yeniden...

Taze umutlarla geleceğe doğru.

Bir ara buldum sanıyor mutluluğu.

Duruyor karşında oysa işte! ..

Biraz toprak, 

Bir dikili taş

Ve belki de bir ağaç...

Neylersin, 

Ne düşünürsün bilmem ama, 

Bence yaşamın öyküsü bu...

(Akhisar,03.06.1970)', 'Hayat bence Tanrı denilen varlığın İnsan adını verdiği kuklalarıyla Oynadığı bir oyundur. Yüklemiş kuklaların sırtına,  Geçmiş denilen yük t...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yasamin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Ezanları', 'sabah-ezanlari-esref-anka-dipqk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne alnım yere değer, 

ne ellerim göğerir

yine de

sabah ezanları bana

tarifi imkansız

bir huzur verir

çünkü; 

gecenin sabaha kavuştuğu o vakit

ses verir

benim gibi uyumayan birileri

ve biraz daha çekilir kılar

geceleri

işte o an

yalnız olsam bile ben

yalnızlığımın yalnız olmadığını bilirim

bu sebeptendir ki

bir sabah ezanını

hiç usanmadan

dakikalarca dinleyebilirim.', 'ne alnım yere değer,  ne ellerim göğerir yine de sabah ezanları bana tarifi imkansız bir huzur verir çünkü;  gecenin sabaha kavuştuğu o vaki...', ARRAY['Türk Edebiyatı','Şiir','Eşref Anka']::text[], 8.5, '{"poet":"Eşref Anka","poet_slug":"esref-anka","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sabah-ezanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızız', 'yalniziz-esref-anka-oww1j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bakışımız yalnız, duruşumuz yalnız

haykırışımız, sesimiz yalnız

bir bakıma

çoğul türküler içinde

yalınız.

ama; 

prangasını seven esirler gibi

incitmez, örselemez bizi

yalın yalnızlığımız.', 'bakışımız yalnız, duruşumuz yalnız haykırışımız, sesimiz yalnız bir bakıma çoğul türküler içinde yalınız. ama;  prangasını seven esirler gib...', ARRAY['Türk Edebiyatı','Şiir','Eşref Anka']::text[], 8.5, '{"poet":"Eşref Anka","poet_slug":"esref-anka","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalniziz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Suçlu Değilim', 'ben-suclu-degilim-esref-anka-uye4j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sadece, 

aşkı yaşamak için bir zaman

bir insanı kullanmak değil yaptığım

ben yalnızca, 

bir insanı sevmek için sevgilim

bunca zamandır

aşkı kullandım.', 'sadece,  aşkı yaşamak için bir zaman bir insanı kullanmak değil yaptığım ben yalnızca,  bir insanı sevmek için sevgilim bunca zamandır aşkı ...', ARRAY['Türk Edebiyatı','Şiir','Eşref Anka']::text[], 8.5, '{"poet":"Eşref Anka","poet_slug":"esref-anka","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ben-suclu-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Ölüm', 'kara-olum-esref-anka-g5adi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'uyan küçük bahçemizin küçük çiçeği

bu toprak, bu mezar yüreğine dar

yalan da olsa gülümse şimdi, 

bir ses ver

duyabileceğimiz kadar

şimdi gökyüzünün zamansız kini

üstümüze saldıran

müthiş bir yağmur

bir an evvel gömmek istiyor seni

uyan, 

izin verme ne olur

erken gelip

erken giden kardeşim

bahtı kara, kendi kara ismail

bilirim, 

böyle ölmek güzel ve temiz

ama yaşamak

yine de hor değil

ya sen

gövdeni hapseden bu toprağı

bir gün korkmadan deleceksin, 

yırtıp 

bu sabah giydiğin kefeni

ebedi kalmak üzre

yanıma geleceksin

ya da ben

yeniden görmek için seni

kanatlanacağım

zamansız ölüler diyarına, 

hüznümün beni boğduğu gece

bekle beni

geleceğim yanına.', 'uyan küçük bahçemizin küçük çiçeği bu toprak, bu mezar yüreğine dar yalan da olsa gülümse şimdi,  bir ses ver duyabileceğimiz kadar şimdi gö...', ARRAY['Türk Edebiyatı','Şiir','Eşref Anka']::text[], 8.5, '{"poet":"Eşref Anka","poet_slug":"esref-anka","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kara-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küllendi Yaram', 'kullendi-yaram-esref-anka-tck0p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'düşlerimin beni

o dağın başına çıkardığı

bir gece yarısı

yuvarlanıp düştüm, 

kanadı gönül yaram

işte o an

yanıp kül oldu

ve yarama serpildi

vefalı sigaram

kesmek için kanımı

o günden sonra

ne zaman sigara içsem

acı çekmesin diye vefalı dostum

dumanını içime

daha bir hızlı çekerim

ve sonra külünü

bir gün yeşerir diye

bahçemin en güzel köşesine ekerim', 'düşlerimin beni o dağın başına çıkardığı bir gece yarısı yuvarlanıp düştüm,  kanadı gönül yaram işte o an yanıp kül oldu ve yarama serpildi ...', ARRAY['Türk Edebiyatı','Şiir','Eşref Anka']::text[], 8.5, '{"poet":"Eşref Anka","poet_slug":"esref-anka","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kullendi-yaram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silik', 'silik-esref-anka-q6mqa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hatırlarım, 

adı boyundan uzun

irice bir adam vardı.

...

bir sabah şahit oldum

cumhuriyet caddesinde, 

iki kez yankılandı

iki el silah sesi

ve kanlar içinde

yere serildi 

adamın 

iri, kısa gövdesi.

...

sonra biz

toprak girmesin diye gözlerine

kefenledik 

ve gömdük merhumu

şehrin en kuytu 

en sahipsiz yerine

bir yıl geçmeden aradan

silindi garibin hayali

zayıf hatıralardan.

hatırlamaz oldu kimse.

birkaç yıl sonra, 

adının yazılı olduğu

beyaz mermerin üstündeki

siyah çizgiler

vurdukça yağmur

birer birer silindiler.

şimdi

ne soyu kaldı adamın, ne adı

ne de

babasından alıp da

oğluna bile veremediği

uzun soyadı', 'hatırlarım,  adı boyundan uzun irice bir adam vardı. ... bir sabah şahit oldum cumhuriyet caddesinde,  iki kez yankılandı iki el silah sesi ...', ARRAY['Türk Edebiyatı','Şiir','Eşref Anka']::text[], 8.5, '{"poet":"Eşref Anka","poet_slug":"esref-anka","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/silik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzsüz', 'yuzsuz-eda-unutkan-lf1gu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gündüzler ağlamış

Geceler uykusuz

Bu sevgi denilen

Çok yüzsüz.

Bulutlar göklerle barışmış

Güneş küsmüş

Güneşle bulutlar birbirine düsmüş.

Bir yağmura

Bir çimene

Bir çiçeğe sevdalıyım...', 'Gündüzler ağlamış Geceler uykusuz Bu sevgi denilen Çok yüzsüz. Bulutlar göklerle barışmış Güneş küsmüş Güneşle bulutlar birbirine düsmüş. Bi...', ARRAY['Türk Edebiyatı','Şiir','Eda Unutkan']::text[], 8.5, '{"poet":"Eda Unutkan","poet_slug":"eda-unutkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yuzsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Bebek', 'aglama-bebek-eda-unutkan-l4yiu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlama Bebek

Çarıksız çorapsız

Doğusu, güneyi, kuzeyi, batısı, 

Hepsi birisi

Ankara sokakları

Leş kargaları

Ne olacak insan hakları

Ağlama Bebek

Işte düzen, işte kepçe

Işte işkence

Bunlardan birisini seç

Sen de hesap vereceksin

Işkenceden geçeceksin

Geldiğime pişmanım diyeceksin...', 'Ağlama Bebek Çarıksız çorapsız Doğusu, güneyi, kuzeyi, batısı,  Hepsi birisi Ankara sokakları Leş kargaları Ne olacak insan hakları Ağlama B...', ARRAY['Türk Edebiyatı','Şiir','Eda Unutkan']::text[], 8.5, '{"poet":"Eda Unutkan","poet_slug":"eda-unutkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aglama-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanya', 'tanya-nazim-hikmet-ran-fo22d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zoe’ydi adı 

ismim tanya dedi onlara

(tanya; 

bursa cezaevinde karşımda resmin

bursa cezaevinde, 

belki duymamışsındır bile bursa’nın ismini

bursa’m yeşil ve yumuşak bir memlekettir.

bursa cezaevinde karşımda resmin

sene 1941 değil artık, sene 1945

moskova kapılarında değil artık 

berlin kapılarında dövüşüyor artık seninkiler

bizimkiler

bütün namuslu dünyanınkiler..

tanya; 

senin memleketini sevdiğin kadar ben de seviyorum memleketimi

seni astılar memleketini sevdiğin için

ben memleketimi sevdiğim için hapisteyim

ama ben yaşıyorum 

ama sen öldün

sen çoktan dünyada yoksun

zaten ne kadar az kaldın orada

on sekiz senecik...

doyamadın güneşin sıcaklığına bile...

tanya; 

sen asılan partizan, ben hapiste şair

sen kızım, sen yoldaşım

resmin üstüne eğiliyor başım

kaşların incecik, gözlerin badem gibi

renklerini fotoğraftan anlamam mümkün değil

fakat yazıldığına göre koyu kestaneymişler.

bu renk gözler çok çıkar benim memleketimde de...

tanya; 

saçların ne kadar
..........
..........', 'zoe’ydi adı  ismim tanya dedi onlara (tanya;  bursa cezaevinde karşımda resmin bursa cezaevinde,  belki duymamışsındır bile bursa’nın ismini...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tanya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi', 'gibi-eda-unutkan-qczbe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin için

Içimde bir çırpıntı var, 

Yavru kuşlar yeni yuvadan uçar gibi...

Çığlık çığlığa yüreğim, 

Bana gözünün bebekleri koşar gibi...

Her bakışı bir kurşunu

Yüreğime saplar gibi, 

Tıpkı gökte yıldızlar

Şafağa kayar gibi...', 'Senin için Içimde bir çırpıntı var,  Yavru kuşlar yeni yuvadan uçar gibi... Çığlık çığlığa yüreğim,  Bana gözünün bebekleri koşar gibi... He...', ARRAY['Türk Edebiyatı','Şiir','Eda Unutkan']::text[], 8.5, '{"poet":"Eda Unutkan","poet_slug":"eda-unutkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gibi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Ah', 'ah-ah-eda-unutkan-pleox', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah Karadeniz olsaydım

Ege Denizi olsaydım

Marmara Denizi olsaydım

Insanların bağrında

Sevgi deposu olsaydım

Ah dünyada kral olsaydım

Ah hepsinden önce

Bir insan olsaydım

''Dünyada insanlar kardeştir''

Insanlara dedirtseydim

Elimdeki ekmeğin 

Yarısını paylaşmasını bilseydim

Ah şu dünyada ırkçılığı kaldırsaydım

Ah yarım asırdır arıyorum

Şu ırkçılığı yapan ustaları görseydim

Yaka paça kavga etseydim...', 'Ah Karadeniz olsaydım Ege Denizi olsaydım Marmara Denizi olsaydım Insanların bağrında Sevgi deposu olsaydım Ah dünyada kral olsaydım Ah heps...', ARRAY['Türk Edebiyatı','Şiir','Eda Unutkan']::text[], 8.5, '{"poet":"Eda Unutkan","poet_slug":"eda-unutkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-ah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zina', 'zina-eda-unutkan-oha24', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşık olsam, ayıp derler

Rakı ıçsem, günah derler

Bir güzel sevsem, zina derler

Buna da dünya derler...', 'Aşık olsam, ayıp derler Rakı ıçsem, günah derler Bir güzel sevsem, zina derler Buna da dünya derler......', ARRAY['Türk Edebiyatı','Şiir','Eda Unutkan']::text[], 8.5, '{"poet":"Eda Unutkan","poet_slug":"eda-unutkan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimle Gözlerimi Arıyorum', 'gozlerimle-gozlerimi-ariyorum-eda-unutkan-37te3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazık oldu gözyaşlarıma

Şimdi neredeler

Hangi çimendeler

Hangi denizde

Hangi çiçeğe su olmuşlar

Ellerim dizlerimde

Aynaya bakınca

Ne gözlerimi, 

Ne de gözyaşlarımı tanımaz oldum

Gözyaşlarımı arıyorum

Gözlerimden dökülen yaşlar

Tanımaz oldu gözlerimi

Esmer bir buluta döndüm

Savruluyorum göyüzünde...', 'Yazık oldu gözyaşlarıma Şimdi neredeler Hangi çimendeler Hangi denizde Hangi çiçeğe su olmuşlar Ellerim dizlerimde Aynaya bakınca Ne gözleri...', ARRAY['Türk Edebiyatı','Şiir','Eda Unutkan']::text[], 8.5, '{"poet":"Eda Unutkan","poet_slug":"eda-unutkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerimle-gozlerimi-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başka', 'senden-baska-eda-unutkan-5b0qx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşüme kara toprak

Bırak yalanları

Yeter ki üşütme yılanları, çayanları

Gülü çiçeğe eklersin

Herğün yolumu beklersin

Inanki geç kalmayacağım

Gelirken senden başka

Hiçbir çiçek almayacağım...', 'Düşüme kara toprak Bırak yalanları Yeter ki üşütme yılanları, çayanları Gülü çiçeğe eklersin Herğün yolumu beklersin Inanki geç kalmayacağım...', ARRAY['Türk Edebiyatı','Şiir','Eda Unutkan']::text[], 8.5, '{"poet":"Eda Unutkan","poet_slug":"eda-unutkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senden-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başıma', 'bir-basima-eda-unutkan-iauyt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok pahalı bir şehirde yaşıyorum

Parası bol, insanları şımarık

Sordum ki

Altın satıyorlar, bakırla karışık

Insanlara değil, köpeklere alışık

Işte bir başıma bu şehirde 

Böyle yaşıyorum

Ölümle yaşamın arasında kalmışım

Hangisi önce saldıracak bilemiyorum', 'Çok pahalı bir şehirde yaşıyorum Parası bol, insanları şımarık Sordum ki Altın satıyorlar, bakırla karışık Insanlara değil, köpeklere alışık...', ARRAY['Türk Edebiyatı','Şiir','Eda Unutkan']::text[], 8.5, '{"poet":"Eda Unutkan","poet_slug":"eda-unutkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-basima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-yusuf-ozkay-nieqt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerine hasret kalmak

Ağaçlara ismini kazımak

Güzelliğine şiirler yazmak

Ve beklemek umutla geleceğin günü.

Resmine bakarak senle konuşmak

Sonra geliyormu diye yollara bakmak

Uçan kuşa bile adını sormak

Ve beklemek karanfil seni beklemek.

Bir çiçeğe adını verip onu sulamak

İşte o çiçekte kokunu tatmak 

Gelsin diye tanrıya yalvarmak

Ve beklemek gelmeyeceğini bile bile beklemek.

Delicesine kumsallarda koşmak

Saçlarımı rüzgarlara bırakmak

Senin için hayallere dalmak

Ve bıkmadan usanmadan beklemek.

Anıları gözlerimde canlandırmak

Mazide bir kuş misali uçmak

Kahrolup kafamı duvarlara vurmak

Ve beklemek yine beklemek.

Umut etmek, özlemek

Soranlara bir gün gelecek demek

Hıçkırarak isyan etmek

Ve beklemek güzel gözlüm, seni beklemek.

Gözlerimi bulutlarda gezdirmek

Geleceğin günü düşlemek

Sonra hayaline merhaba demek

Ve beklemek sonsuza dek beklemek.

                                       (30-06-1996 Karaman)', 'Gözlerine hasret kalmak Ağaçlara ismini kazımak Güzelliğine şiirler yazmak Ve beklemek umutla geleceğin günü. Resmine bakarak senle konuşmak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Özkay']::text[], 8.5, '{"poet":"Yusuf Özkay","poet_slug":"yusuf-ozkay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/beklemek-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Rengi', 'askin-rengi-kavel-ozgur-dubbn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'renkleri bölüştürdüler

d

u

y

g

u

l

a

r

a...

aşka siyahı seçmek düştü.', 'renkleri bölüştürdüler d u y g u l a r a... aşka siyahı seçmek düştü....', ARRAY['Türk Edebiyatı','Şiir','Kavel Özgür']::text[], 8.5, '{"poet":"Kavel Özgür","poet_slug":"kavel-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askin-rengi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Yolu!', 'zaman-yolu-abdulkadir-karaman-7g166', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözyaşı ektiğim bu yol...

Kahrını, derdini bir yana bırakıp

ümidime beklettiğim bu yol.... 

Ömrümü tükettiğim bu yol....

sevgimi...sevincimi harcadığım...

Hep özlemini çektiğim bu yol...

Kenarlarına bir bir

kaybolmadan geri dönebilmen için

işaret olsun diye, 

hasretinle kavrulmuş 

kalbimi diktiğim bu yol....

Bilmiyorum kaç kere

duygularımı yama yaptığım

sonra söktüğüm bu yol....

Duâ için, kim bilir belki bedduâ için

istemeye istemeye

diz çöktüğüm bu yol...

Kahredip olan biten her şeye

lânet okuyup sevmeye sevilmeye

hüzün döktüğüm bu yol....

Hayalini perçinleyip 

içimin özlemli çizgilerine

boynumu büktüğüm bu yol...

Korkudan, heyecandan ürktüğüm bu yol...

Demişsin ki; saman yolu! ? 

Biliyorum, sende biliyorsun ki

bu yol zaman yolu...

sabırdan vakitleri; 

bu yolda hasret, hicran bu yolda, 

bu yolda zahmet dolu.

Bekliyorum ve bekleyeceğim 

bozmadan akitleri

tâ kavuşuncaya kadar

gözlerim buğulu buğulu

içimse ümit dolu.

1997 kayseri.', 'Gözyaşı ektiğim bu yol... Kahrını, derdini bir yana bırakıp ümidime beklettiğim bu yol....  Ömrümü tükettiğim bu yol.... sevgimi...sevincimi...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/zaman-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırlangıç', 'kirlangic-mesut-biyik-kq1b9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir dam saçağı bulurum kırlangıçsam

çalı çırpı bir de konacak telgraf telleri

kim bilir belki bir yürek bulurum

sıcağında ısıtırım yüreğimi

her titreyişinde tellerin bilirim

sevgiliye giden telaşlı bir yürek çarpıntısıdır

birkaç damla gözyaşı belki

belki kucak dolusu hasret

siz benim kırlangıç olduğuma bakmayın

ben de bilirim 

kana ne zaman sıcak bir buğunun karıştığını

bilirim ne zaman avuçlar terlenir

ne zaman bütün çiçekler buhur kokar

benim de kalbim pırpırlandı zahir

kanatlarımdan da ziyade bir zaman

bilirim ben de 

eli eline değdiğinde sevgilinin

nasıl saman sarısı olur benzi diğerinin

yani açıkçası

bir kırlangıç da olsam

sanmayın yalnızca yağmuru çağırırım

bilirim yüreği kabartan aşkı 

bilirim en azından sizin kadar

hem siz bilir misiniz ki

tüneyip tellere benim de beklediğim biri var', 'bir dam saçağı bulurum kırlangıçsam çalı çırpı bir de konacak telgraf telleri kim bilir belki bir yürek bulurum sıcağında ısıtırım yüreğimi ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Bıyık']::text[], 8.5, '{"poet":"Mesut Bıyık","poet_slug":"mesut-biyik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kirlangic-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerin Bir Günü', 'askerin-bir-gunu-burhan-kamali-w1uj2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durdurulmuş saatlerin yelkovanında 

Asılı kalmışım

Savrulmuş düşüncelerim

İpi kopmuş uçurtmalar gibi

Ben ise yağmurda unutulmuş sandalye

Özgürlük yanı başımda

Ama dokunamıyorum ona

Uçan kuşlar minareler

Munzurun eteğindeki köyler

Karlı doruklar göçmen bulutlar

Ve masmavi gökyüzü

Her yanım özgürlüklerle dolu

Bir türlü tutunamadığım

Birde özlem rüzgarları

İnsanın içini titreten

Burada güneş munzurdan doğar ve batar

Doğan ve batan her güneş 

Sanki bir yıla eş

Kirli koğuş penceresine çarpar akşamları

Uzak köylerin, kırpışan yıldızların ışıkları

Derin bir sessizlik, gezinir ortalıkda

Ardından ''Koğuş yat! '' çığlığı

Sonra ben ve ranza

Neresine dokunsam buz gibi

Kışın ortası zemheri sanki

Horlama sesleriyle geçirirken geceyi

Günün ilk miracıyla bilikde

Bölünür rüyalar ''Koğuş kalk! ''sesleriyle

O''anlarda Annem geliyor aklıma 

Birde Talha! 

Ah canlarım nasılda özlemişim sizleri

her gün selam gönderiyorum sizlere

Uçan kuşlarla, göçmen bulutlarla

Belki gelir diye 

Hasretimden takvimlerin içine düşmüşüm

bir kurtaranım yok! 

Erzincan burası

Bekliyorum tomurcukdaki yaprakların dökülmesini

Munzurun karlarının erimesini

Ve  tekrar yağmasını

Şimdi içimde en çokda bir sonbahar özlemi

İnsan baharın ve yazın bitmesini istermi

Özlem ya bu çekilirmi? ....', 'Durdurulmuş saatlerin yelkovanında  Asılı kalmışım Savrulmuş düşüncelerim İpi kopmuş uçurtmalar gibi Ben ise yağmurda unutulmuş sandalye Özg...', ARRAY['Türk Edebiyatı','Şiir','Burhan Kamalı']::text[], 8.5, '{"poet":"Burhan Kamalı","poet_slug":"burhan-kamali","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/askerin-bir-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sev', 'beni-sev-cem-veysel-gul-9ju61', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eski günlerdeki gibi sev beni.

İlk gülüşündeki masumiyetle, 

Konuşmalarındaki samimiyetle, 

İlk görüşmemizdeki heyecanla, 

Elimi tuttuğun anki sıcaklığınla sev beni.

Hani birleşince ellerimiz, 

Dur durak bilmeyen yürek sıcaklığımız, 

Kar’da fırtınada içimizi ısıtan, 

O yürek ısısı, o ilk heyecan gibi, 

Her an duymak istediğimiz, 

O güzel ses gibi, tebessüm gibi, 

Yanağıma kondurduğun ilk busede, 

Hatta yan yana yürüyüşlerimizdeki, 

Masumiyet gibi, utangaç tavır gibi, 

Yani eski günlerdeki gibi sev beni.

Beni sev sevgilim.

Sev beni.

Cem Veysel Gül

İstanbul/halkalı

08.07.2002/saat 15: 45', 'Eski günlerdeki gibi sev beni. İlk gülüşündeki masumiyetle,  Konuşmalarındaki samimiyetle,  İlk görüşmemizdeki heyecanla,  Elimi tuttuğun an...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beni-sev-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümle Yaşamak', 'olumle-yasamak-sair-baksencik-nlgc9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dönüş var; 

keskin ani, ve korkutucu 

ne getireceği bilinmez, 

ancak cesaretin varlığından 

cesaret alabilecek 

tek düzelikle alınamayacak bir dönemeç, 

belki varlığın, ayakta kalmışlığın başangıcı; 

bir ihtimal yokluğa bir kapı... 

Hayatın her anında 

yeniden doğmak ve ölmek eşit olasılıkta... 

Madem böyledir her an 

niye korkar ki bunca insan 

Sevilen bir bilinmeze adım atmaktan 

sorarım sana! ! 

Ama sen, 

sen onlara bakma 

kelle koltukta, çıkar kınından yüreğini 

ve ölümüne savaş bu hayatla 

hayat değil, ölüm bile saklanacak bir mekan arasın 

eski-yeni zamanlarda 

sen hayatı kovaladıkça ölüm uzaklaşacak senden 

ölmek yaşamana bir sebepse 

sen yaşıyorsun 

elin kolun bağlı 

ölümü bekliyorsan 

boşuna bekleme derim 

zaten yaşamıyorsun. 

ITU MAÇKA KAMPÜSÜ 

29 Mart 2002 

CUMA', 'Bir dönüş var;  keskin ani, ve korkutucu  ne getireceği bilinmez,  ancak cesaretin varlığından  cesaret alabilecek  tek düzelikle alınamayac...', ARRAY['Türk Edebiyatı','Şiir','Şair Baksencik']::text[], 8.5, '{"poet":"Şair Baksencik","poet_slug":"sair-baksencik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/olumle-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrep Yelkovana Erer', 'akrep-yelkovana-erer-i-brahim-ugur-toprak-j8wqj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüyalar vardır, 

Asla sonu gelmesin dediğin.

Saatler vardır, 

Geçmesini istemediğin.

Günler vardır, 

Hiç geceye ermesin.

Ay doğmasın, 

Güneş batmasın istersin.

Aylar dolmasın, 

Yıllar kaybolmasın dersin.

Yanındayken sevdiğinin, 

Yelkovan dönmesin, 

Akrep ilerlemesin.

Dilersin ki, 

Saniyeler, hatta

Saniseler bile işlemesin.

Ama olmaz.

Zaman durmaz.

Ay Güneşe, 

Akrep Yelkovana erer.

Gündüzler Geceye, 

Aylar Yıllara döner.

Ve sen hala beklersin, 

Bir gece ansızın giden sevgiliyi.

Ama gel gör ki, 

Ne o geri döner, 

Ne de o uğurda kaybettiğin

Güzelim seneler.

04.07.02/Perşembe

     22:52/İzmir', 'Rüyalar vardır,  Asla sonu gelmesin dediğin. Saatler vardır,  Geçmesini istemediğin. Günler vardır,  Hiç geceye ermesin. Ay doğmasın,  Güneş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/akrep-yelkovana-erer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Duvarları', 'aglama-duvarlari-mine-ozdemirtas-yhibx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yol açık, kanal açık / tıkanmış değil oluklar aslında.

Saçaklarımdaki buzlanma yüreğimin ayazından sadece.

Dolunay''ı puslandırırken buz gibi bir gece….

Ayı inindeydi / kürkçünün kürkü kış uykusunda.

Hiç durmadan ağlama duvarları örmeliyim aramıza.

Kurtlar peşimden geliyor / çakallar ise pusuda.

İşim kalmadı çanlarla / vadi''m baştan başa yeşil.

Kutsal sudan içmeyeceğim / yalnızca / günah çıkaracağım ince sazdan.

Eğer ki hırsız / Çaldığı duyguları koymazsa yerine…

Çılgınlığın uzatmalarını oynayacağım birazdan.', 'Yol açık, kanal açık / tıkanmış değil oluklar aslında. Saçaklarımdaki buzlanma yüreğimin ayazından sadece. Dolunay''ı puslandırırken buz gibi...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aglama-duvarlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avcıysan Avcılığını Bil', 'avciysan-avciligini-bil-mesut-biyik-k8p3q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nazlan sen

nazende bir gül tutunsun dudaklarına

gözlerine sabah çiğinin buğusu otursun

dudakların ki kıvrılsın

sessiz akan nehirler gibi

bu eda yakışıyor

yakışıyor her güzellik sana

sitem et

serzenişin yüreğimi hırpalasın

dalgaların kıyasıya dövdüğü mendirek gibi

dayanayım acıtan sözlerine

bu da yakışır

yakışır senin kudretine

somurt

bahçeye diktiğim karanfiller açarken

bahçe duvarının soğuk taşları gibi

surat as bana

en sevdiğim çiçekleri çiğne 

leylakların dallarını kır

her ne kadar yakışmasa da senin sevecenliğine

elini kaldırmışken vur

amaaaa

sakın beni sınamaya kalkma 

arkana deli poyrazı alıp

acemi bir yelkenli gibi

savurma beni fırtınanda

güldürme bana martıları

bir dalgada bitiriver işimi

atacaksan bir kıyıya

baltanı iyi bile

kör nacakla koparma pinçik pinçik

bir hamlede kes dalımı

indir kanadından vurulmuş bir kartal gibi

indir ki görenler sana avcı desinler 

kaya gibi yüreği

sırım gibi bileği var desinler

avcının kudretinden sual olunmaz

lakin sapan taşıyla da ava durulmaz', 'nazlan sen nazende bir gül tutunsun dudaklarına gözlerine sabah çiğinin buğusu otursun dudakların ki kıvrılsın sessiz akan nehirler gibi bu ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Bıyık']::text[], 8.5, '{"poet":"Mesut Bıyık","poet_slug":"mesut-biyik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/avciysan-avciligini-bil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alaattin'' in Lambası', 'alaattin-in-lambasi-mine-ozdemirtas-3f6lj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç bitmeyeceğini sandığım kör bir gecenin, 

Solgun renkleridir uzaklaşan.

Yaklaşırken / usulca ve keyifle

Gecenin varlığından acı duyan genç adam.

Bilmelidir ki

Cinler çıkacak.

Oynaşıp durduğu /  tozlu lambadan', 'Hiç bitmeyeceğini sandığım kör bir gecenin,  Solgun renkleridir uzaklaşan. Yaklaşırken / usulca ve keyifle Gecenin varlığından acı duyan gen...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/alaattin-in-lambasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatır', 'hatir-mehmet-ali-cibikli-gk1pm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En büyük kazıklar, dosttan yenirken, 

Neden hep düşmandan şüphelenilir? 

Mutluluğu bulmak, sevilmek varken, 

Nedir sevgisizlik, ayrılık nedir? 

Aşk ölmek demektir, aşkı uğruna, 

Mutlu olursan aşk, aşktan sayılır.

Dokunmak istersen, suya sabuna, 

Bu aşkın yoluna, bir baş koyulur.

Biz istedik sevdik, birbirimizi, 

Kendimizden binbir, ödünler verdik.

Ümitsiz görsek de, bu sevgimizi, 

Hep elele verdik, delice sevdik.

Ne zaman istersen, çağır sen beni, 

Karanlık ruhunu, aydınlatırım.

Eğer hiç düşünmez, bilmezsen beni, 

Üzülürüm sonra, biter hatırım.', 'En büyük kazıklar, dosttan yenirken,  Neden hep düşmandan şüphelenilir?  Mutluluğu bulmak, sevilmek varken,  Nedir sevgisizlik, ayrılık nedi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah', 'gunah-mehmet-ali-cibikli-13hbs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umulmaz bir anda, tutuştu yürek, 

Kader ağlarını, yine örmüştü.

Aşk acısı üstümde kürek kürek, 

Seni sevdi gönlüm, hataya düştü.

Seni sevdim dedim, hata mı ettim? 

Sevmek yaşamımın birer parçası.

Bütün benliğimi, tümden kaybettim, 

Kendimi kaybettim, ben açıkçası.

Benim dertli başım, çileli başım, 

Çok sevdalar gördü, hep acı çekti.

Damla damla aktı, hergün gözyaşım, 

Ağlayan kaderim, gülmeyecek mi? 

Yaşam buysa eğer, bak yaşıyorum, 

Seni sevmek meğer, öyle zormuş ki! ..

Yüküm çok ağırmış, zor taşıyorum, 

Günahım büyükmüş, hiç bitmez gibi! ..', 'Umulmaz bir anda, tutuştu yürek,  Kader ağlarını, yine örmüştü. Aşk acısı üstümde kürek kürek,  Seni sevdi gönlüm, hataya düştü. Seni sevdim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunah-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adim mi Yuzum mu Ruyalarinda?', 'adim-mi-yuzum-mu-ruyalarinda-huseyin-cayikli-l1vpe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derdim buyuk anlatamam

gece yarisi kalkip 

su icmek ruyamda seni gormem

hayr-a alemet degil

sanirim bavullarim devamli toplu olmasi lazim

bulundugum sehirden biraz uzaklassam

yanina gelsem

sen orada olmasan

Gunes buluta girse sen kumsalda olsan

sahili en guzel  yapan isigin olsan.

bugunlerde cok iciyorum

ama dun aksam ne ictigimi bile hatirlamiyorum

anladim bu aski ben kaybettim

simdi uykunda olsanda beni kendine yasaklasanda

ruyalarinda beni yasakladin mi? 

dusurustce sor bu soruyu? 

uzaklarda olsam da sevmesende

beni unutma?', 'Derdim buyuk anlatamam gece yarisi kalkip  su icmek ruyamda seni gormem hayr-a alemet degil sanirim bavullarim devamli toplu olmasi lazim bu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/adim-mi-yuzum-mu-ruyalarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm ve Oğlum', 'olum-ve-oglum-can-yucel-bncsc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüm ve Oğlum

Ne yaman çiğköfteymiş ki bu ölüm

Şalgam suları iniyor şakaklarımdan 

		ben hala susuyorum

Gözlerimle taşlarcasına bir kör kuyuyu...

	Nerde kaldı bire saka kuşu

	Su gibi bildiğin o su kasidesi? 

Ve dudaklarımı sevsinler

	bir barut bulutuyla sanki

		ortadan biçilmiş bir güneş

Aynı çığlığı mı ezberleyecek dersin

	akşamcılar akşama tövbe edinceye dek

Düzayaktı Attar A''met Efendiden Kartal Baba Tekkesine

Bu seferki yolum ise

	ardımdan gelen kolun

		ölüsıra yürüyen

		 kilden, kirloz bir bayrak

			epiy de yokuş üstelik

				ve giderayak

Sırtına vurmuş yada

	buruşuk bir şipka biberini

Meyvahoşa koşturuyor

	mork çizmeleriyle bir kırkayak

Nasıl koşturduysa tulumbacılar eskiden

			yeşil karga tulumbalarını yangına

Yandım diye böğürmüşüm

Böğrüm yiyince böğrümden

		o çiğköfteyi

			YANDIM

Öylebi kuşaktık ki biz oğlum

	yine de sen ölüyorsun

		boynuna sarılınca ben

Ve o domuz var ya İncildeki

	cümle günahı yüklenip

		uçuruma atlayan domuz

Biz öyle bilem olamıyoruz...

Meşksiz aşklarla senlerin

		başına tacettiğimiz

			o güzelim elmayı

Utanmadan o ulusal

	akbabamıza sunuyoruz

		kellerinizle birlikte

Bu gidişle korkarım

	bi tek ses kalacak bizden

		tıkırtısı farenin

Kendi tahta kuyruğunu kemiren

Cama vurulmuş güneş kırıldı

Nar daneleri döküldü suya

Yandım diye böğürüyorum

Ama bu kırkayak oynunda

Öyle yakın ki ölümle oğlum

Uyak oluvermişler adeta

Ben ne demeye hala

Sözümona bir inci gibi

Acının yanardağ bardağında

Kendi kendime eriyim? 

Oysa bu dünya denen ağacın

Türkiye denen çatağında

Öyle bir oğul var ki oğul

Ölüme değil, ölüme

Yaşanmaya bi ölüm bal

Cama vurulmuş güneş kırıldı

Nar daneleri döküldü suya

Gayrı adam oldu diye babam

Oğlum beni sevse ya', 'Ölüm ve Oğlum Ne yaman çiğköfteymiş ki bu ölüm Şalgam suları iniyor şakaklarımdan  		ben hala susuyorum Gözlerimle taşlarcasına bir kör kuyu...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/olum-ve-oglum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dahası', 'dahasi-salih-ozalasan-sgb42', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğinde iyi duygular

Dudağında güzel sözler

Bakışlarında hep gülümseme

Dahası, Gönlünden geçenler senin olsun

Avuçlarında herzaman bir tutam mutluluk

Özünde saklı kalsın daima doğruluk

Dudağından çıkmadıkca son soluk

Dahası, Sevdiklerin hep seninle olsun

Yüreğin hüznü, kederi, ihaneti asla tanımasın

Ömründe of Allah''ım dediğin bir günün olmasın

Sen bir gülsün goncan dalında solmasın

Dahası, Tüm mutluluklar senin olsun

Sende kalsın sana yakışır güzel olan

Sevgi tütüyor güzel yüreğinde buram buram

İsterimki sen ol tüm gönüllerde sultan

Dahası, Beyaz gelinlik ancak sana yakışır

 (05-07-2002 Saat 14.20)', 'Yüreğinde iyi duygular Dudağında güzel sözler Bakışlarında hep gülümseme Dahası, Gönlünden geçenler senin olsun Avuçlarında herzaman bir tut...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dahasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklarımın Annesi', 'cocuklarimin-annesi-salih-ozalasan-5pwkp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aldanma gözlerimi senden kaçırdığıma

Gönül gözüm hep sana bakıyor

Bakma öyle bağırıp çağırdığıma

Yüreğimde buram buram sevdan tütüyor

Anlatılmaz bir sevda bu

Anne baba sevgili eş hepsi birarada

Yüreğimin her köşesi senin

Bazen espiri yapsamda sana

Sana olan sevgim anlatılamaz

Sadece doyumsuz yaşanır

Gönül bahçeme bazen giren olsada

Çocuklarımın anası

Bu yürekte sonsuza dek kalır

Bu can bu bedenden çıkmadıkca

Alamaz kimse yüreğimdeki yerini

Bazen sitem edip sevmez görünsemde seni

Bilki sevdamın büyüklüğünden 

Çocuklarımın annesi

(06-07-2002 Saat 15.30)', 'Aldanma gözlerimi senden kaçırdığıma Gönül gözüm hep sana bakıyor Bakma öyle bağırıp çağırdığıma Yüreğimde buram buram sevdan tütüyor Anlatı...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cocuklarimin-annesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoktun', 'sen-yoktun-gokhan-ozmen-3sgm9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün her zaman gittiğimiz yerdeydim

Hani şu el ele gezdiğimiz deniz kıyısında 

Ama bu sefer yalnızdım

Ve senden kalan kırık dökük hatıralar

Dalgalar bile farklı vuruyordu kıyıya 

Sanki deniz bile kahrolmuştu ayrıldığımıza 

Senin eksikliğini o bile farketmişti

Her kıyıya çarpışında sanki seni soruyordu

Her şey aynıydı. Dalgaların çırpınışı bile

Bu sefer biz eksiktik yani SEN

Gün batımını izleyip huzur bulduğumuz yer 

Bu sefer her kıyıya çarpışında birşeyler götürüyordu benden

Karanlık çökünce anladım ne kadar hayalperestmişim

Ne kadar acımasızmış dünya...

Ha! söylemeyi unutmuşum.

Bu sefer bir fazlalığım vardı yanımda 

Sıkıca sarılmış olan tütününde sana olan bağlılığım

Usul usul yanan közünde sana olan sıcaklığım

Gözden kaybolup giden dumanında ellerimden uçup giden gülüm 

Yani SEN olan sigaram vardı.

Onu da tutamadım ellerimde seni tutamadığım gibi

Ve sonra oradan ayrıldım

Dün ilk defa lanetler yağdırdım Bu şehre

Sana seni sevdiğimi söylediğim bu şehre 

Beni umutlarımdan, beni hayallerimden, beni hayatımdan

Beni SENden, beni benden eden bu şehre 

Ve ilk defa ölmeyi düşündüm 

Sonra seni hala ne kadar çok sevdiğimi ANLADIM.........', 'Dün her zaman gittiğimiz yerdeydim Hani şu el ele gezdiğimiz deniz kıyısında  Ama bu sefer yalnızdım Ve senden kalan kırık dökük hatıralar D...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Özmen']::text[], 8.5, '{"poet":"Gökhan Özmen","poet_slug":"gokhan-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-yoktun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksildik', 'eksildik-saba-levon-8uyd1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'deniz çeker beni

uyuyamam geceleri

                    korkarım

                                 gözlerimdeki

                                 buz kesen

                                         yürek ağrımdan

                                                  yangınlar

                                                  cehennemler

                                                  celatlar

                                                           ve

                                                            ne

                                                              yürek ağrımda

                                                              büyüttüm

                                                              bir bilsen

                                                                   dilimin

                                                                   dinimin

                                                                   sevgi çağını

                                                                   düşlerimde kalan

                                                                   isa

                                                                   çarmıha gerilmiş

                                                                   bir çılgın

biraz daha eksiliyorum yaşamdan

ve

bir yüz daha kayboluyor 

çocuk yanımdan

yüreğimin nazlı gelini

tek çoğalan yanım sensin biliyormusun', 'deniz çeker beni uyuyamam geceleri                     korkarım                                  gözlerimdeki                               ...', ARRAY['Türk Edebiyatı','Şiir','Saba Levon']::text[], 8.5, '{"poet":"Saba Levon","poet_slug":"saba-levon","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/eksildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çamoluk Türküsü', 'camoluk-turkusu-hikmet-okuyar-ocf6s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdiğim Çamoluk Şöhrete erse, 

            Servetleri bir kuşuna değişmem.

            Bütün güzellikler sıraya girse, 

            Bizimkinin bir kaşına değişmem.

            Dipdiri ortada kızanı, eri, 

            Çamoluk ilginin tam odak yeri.

            Hayata geçmeyen boş gerçekleri, 

            Gençlerimin bir düşüne değişmem.

            Yünleri ip yapsın eldeki iğin, 

            İpe geçirelim ucunu tığın, 

            Düz yolları asfalt olsa da beğin, 

            Yaylamızın yokuşuna değişmem.

            Gurbette sancılı olan hemşehrim! 

            Hiç olmazsa yazın köye gel derim.

            Sazı inletse de ince söylerim, 

            Nazımı çekişine değişmem.



            Betofen, düzüne gelse yabanın

            Her yanı orkestra olsa obanın, 

            Çamoluk’ta kaval çalan çobanın, 

            Size türkü yakışına değişmem.

            Kütük balı nasıl, diye sorsalar

            Çamoluk’ta zenginliği görseler

            Hindistan’ı ceviziyle verseler, 

            Bizimkinin bir dişine değişmem.

            Pikniğin köyünde yap desen gelir

            Vatan-millet için çap desen ölür, 

            Hizmet olsa kadir kıymet de bilir, 

            Şu gurbeti bir taşına değişmem.

            İmamoğlu Çamoluk’tan geçerse

            Şafaklarla ufkumuzu açarsa

            Vade yetim semalara uçarsa

            Sevdasını bir eşine değişmem.

         

            İmamoğlu Hikmet OKUYAR

            Şair-yazar-Gazeteci

            ÇAMOLUK-GİRESUN', 'Sevdiğim Çamoluk Şöhrete erse,              Servetleri bir kuşuna değişmem.             Bütün güzellikler sıraya girse,              Bizimki...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Okuyar']::text[], 8.5, '{"poet":"Hikmet Okuyar","poet_slug":"hikmet-okuyar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/camoluk-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Ölüyüm', 'artik-oluyum-eda-unutkan-n18fj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şarkılarda değilim

Türkülerdeyim

Modacı değilim

Ozanlardayım

Tüm sevgili arkadaşlarıma

Selamlarımı gönderiyorum

Artık gelemen oralara

Neden dersen...

Sağ değilim

Artık ölüyüm', 'Şarkılarda değilim Türkülerdeyim Modacı değilim Ozanlardayım Tüm sevgili arkadaşlarıma Selamlarımı gönderiyorum Artık gelemen oralara Neden ...', ARRAY['Türk Edebiyatı','Şiir','Eda Unutkan']::text[], 8.5, '{"poet":"Eda Unutkan","poet_slug":"eda-unutkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/artik-oluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş', 'tas-rifat-degirmenci-eht48', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'taşlarla doluydu yeryüzü

göktaşları vardı

yukarılarda bir yerlerde...

şimdiyse...

yalnızca duvarlar var

taştan...', 'taşlarla doluydu yeryüzü göktaşları vardı yukarılarda bir yerlerde... şimdiyse... yalnızca duvarlar var taştan......', ARRAY['Türk Edebiyatı','Şiir','Rıfat Değirmenci']::text[], 8.5, '{"poet":"Rıfat Değirmenci","poet_slug":"rifat-degirmenci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tas-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geride Kaldın Sen', 'geride-kaldin-sen-yusuf-hayaloglu-93lws', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Devrilip gidiyorum işte

Geride kaldın sen...

Aşınmış sevdalar gibi

Yıpranmış postallar gibi

Lime-lime, yarasız

Geride kaldın sen...

Kaprislerinle, nazlarınla

Bakışlarınla, sözlerinle

Tutulmayan vaatler gibi

Harcanmış saatler gibi

Tek başına, kararsız

Geride kaldın sen...

Buraya kadarmış güzelim

Boynumda bıraktığın diş izi

Bitmez sandığın aşk denizi

Buraya kadarmış.

Vedalaşmak isterdim oysa

Klasik bir film öyküsü gibi

Ellerini tutup usulca

Son bir kez öpmek isterdim

Kendimi mazur gösterip

Masum ve mağrur bir duruşla

Her şeyi kadere yıkmak isterdim.

Ne gerek var oysa

Yürümeyen birtakım şeylerin

Nedenlerini tartışmaktansa

Asla yürümeyeceğini anlayıp

Bunu hiç konuşmamak

Daha bir yiğitçe değil mi? 

Süzülüp gidiyorum işte

Bela olmadan

Yoluna çıkmadan

Hesap filan sormadan

İncitmeden, acıtmadan...

Bir bileti yırtar gibi

Bir kabuğu atar gibi

Sıyrılıp gidiyorum işte

Geride kaldın sen...

Bir tren penceresinden

Akıp giden bozkırın

Ortasında bir kuru ağaç gibi

Geride kaldın sen...', 'Devrilip gidiyorum işte Geride kaldın sen... Aşınmış sevdalar gibi Yıpranmış postallar gibi Lime-lime, yarasız Geride kaldın sen... Kaprisle...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/geride-kaldin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca Bir Anlık', 'yalnizca-bir-anlik-yusuf-hayaloglu-5vu4u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu derede, bu bulutun gölgesi, 

Yalnızca bir anlıktır.

Bir daha tekrarlanmaz asla, 

Dere gider bir yana, 

Bulut gider bir yana, 

Sen kalırsın ortada.

Son vapurda, bir kadına rastlar, 

Kibarca gülümsersin.

Kaybettin, geri gelmez artık, 

Vapur gider bir yana, 

Kadın gider bir yana, 

Kalbin kalır ortda.

Yalnızca bir anlıktır mutluluk.

Sevdalar, heyecanlar; 

Hepsi bir anlık.

Kalansa, tortusudur hayatın, 

Yalanlar ve acılar; 

Bir de yalnızlık.

Hey koca Yusuf! 

Yusuf''cuk, ah yusufçuk! 

Rüzgarlara savurdun hep, şarkını.

Herkesten saklandın, 

Her şeye gücendin durdun.

Yoruldun, 

İflah etmezsin sen.

Ömrün gitti bir yana

Hüznün gitti bir yana, 

Şiirin kaldı ortada...', 'Bu derede, bu bulutun gölgesi,  Yalnızca bir anlıktır. Bir daha tekrarlanmaz asla,  Dere gider bir yana,  Bulut gider bir yana,  Sen kalırsı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yalnizca-bir-anlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-ceyhun-yilmaz-yd6wr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söyledim, söyleyebildim sonunda...

''Seni Seviyorum'' demekten aciz dudaklarım

Mutlulukla tanıştı ilk defa..

Affet beni..

Çok geç oldu belki ama

İlk kez ta kalbimde hissettim önemini

İlk kez sana söyledim sevgimi..

Affet beni burada olmamalıydı..

Bu kadar geç olmamalıydı..

Biliyorum yine kavuşacağız

Çok geç olmayacak..Üstelik bu kez korkmayacağım

''Seni Seviyorum'' demekten

Bağıracağım hatta, haykıracağım..

Ağlamayacağım, ağlamayacağız..

Sarılacağız yine...

Sonsuza kadar...

Öyle özledim ki gülen gözlerini...

''Seni Seviyorum'' derken

Bak yine söylüyorum, ''Seni Seviyorum''...', 'Söyledim, söyleyebildim sonunda... ''Seni Seviyorum'' demekten aciz dudaklarım Mutlulukla tanıştı ilk defa.. Affet beni.. Çok geç oldu belki a...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-seviyorum-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Vardı', 'ne-vardi-ceyhun-yilmaz-m9ghy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Madem bu kadar büyük aşkımın bile sende sonu var

Var ki çekip gittin

Ayrılığın, hüznün niye sonu yok? 

Nefret oldun bende gide gide

Ne vardı diyorum ne vardı

Geceme gelsen, ay utansa sevincimden

Yıldızlar kıskansa neşemi

Bir gülüşüne ölecek kadar sevsem

Ne vardı...

Ve gecenin bir yarısı

Duymak istemediğim sesin acıttı içimi

Yaktım bir bir yalandan güldüğün

Bütün resimlerini...', 'Madem bu kadar büyük aşkımın bile sende sonu var Var ki çekip gittin Ayrılığın, hüznün niye sonu yok?  Nefret oldun bende gide gide Ne vardı...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-ceyhun-yilmaz-mljzc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vatan borcunu ödemeye gelmişti

Vatanın hiç bilmediği toprağına

Yeşil kıyafetler içinde, elinde kırmızı elma şekerinin eksikliği...

Kırmızı yanaklarında

Yaklaştım yanına

Ne isterse verecektim

Belli, garibandı biraz yüreği

Dedim ki söyle elim avuçlarında

Tuttum...bıraktım ellerini

Elimi cebime attım

Ne kadar param varsa o an verebilirdim ona

Söyledim...canı birşey çekmiş olabilirdi

Söyle dedim ne istersen...

Dile benden ne dilersen...

İstediğini veremezdim

ANNEMİ BABAMI ÇOK ÖZLEDİM! ! 

                                                           19.06.02 BİLECİK', 'Vatan borcunu ödemeye gelmişti Vatanın hiç bilmediği toprağına Yeşil kıyafetler içinde, elinde kırmızı elma şekerinin eksikliği... Kırmızı y...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozlem-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avam Eğlencesi', 'avam-eglencesi-reha-basogul-1g1zx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzüne açılan terasta

biri erkek biri dişi

Sırnaşıyor birbirine iki deli

İnlemelerle başlıyor kokofoni

Sorulmuyor artık esaretin bedeli

Duyulmuyor artık at kişnemeleri

İsteme dedim değil mi sana

Kumandilar''ın uçtuğu yeri

Çıplaklığın mı nüksedecek

Kanatların mı açılacak şimdi? 

Of seni ipekli

Ah seni dantelli

Kanınla yokluyorsun

alışkanlığımın niyetini

Bozma dediğim değil mi sana

Tao''nun sükunetini

Of seni ferli

Ah seni süslemeli

Sürtünmenle kışkırtıyorsun, 

nefsimdeki kudretimi

Açma dedim değil mi sana

Pandora''nın kilidini

Of seni hevesli

Ah seni terli

Dişlerinle soyuyorsun

üstümdeki tek bezi

Oyma dedim değil mi sana

Rodin''in Idollerini

Of seni dövmeli

Ah seni kisveli

Kokunla fırlatıyorsun

salıverdiğim elbiseni

Soyma dedim değil mi sana

Goya''nın kontesini

Of seni işveli

Ah seni şeftali

Arınışınla aşıyorsun

göğsümdeki yükseltiyi

İçme dedim değil mi sana

Soma''nın zehrini

Of seni böğürtlenli

Ah seni lekeli

Dilinle boyuyorsun

tenimin rengini

Tatma dedim değil mi sana

Dionysos''un meyvelerini

   

Of seni kasvetli

Ah seni iksirli 

Kavruluşunla siliyorsun

şeffaflığımdaki nemi

Düşünme dedim değil mi sana

Dosojin''in imgesini

Of seni incili 

Ah seni küpeli

Serpilişinle susturuyorsun

zihnimdeki kelimeleri

Uyandırma dedim değil mi sana

Athos''un rahiplerini

Of seni gizemli

Ah seni ateşli

teslimiyetinle okşuyorsun

gözlerimdeki çaresizliği

Dinletme dedim değil mi sana

Paganini''nin capricelerini

Of seni hararetli

Ah seni pileli

Saçlarınla döküyorsun

damarlarıma kadehi

Duyma dedim değil mi sana

Pan''ın ezgisini

Of seni yabani

Ah seni pençeli

Tırnaklarınla çiziyorsun

sırtımdaki çizgileri

Koklama dedim değil mi sana

Lotus''un mavilisini

Of seni şehvetli

Ah seni öfkeli

ruhunla avuçluyorsun

bedenimdeki yükseltiyi

Hatırlama dedim değil mi sana

Hermes''in düşlemini

Of seni dünyevi

Ah seni kibirli

Dişiliğinle ısırıyorsun

boynumdaki deriyi

Savunma dedim değil mi sana

Epicur''un fikrini

Of seni vahşi

Ah seni sinsi

Uyuşturmanla boğuyorsun

kabarttığım istediğini

Uygulama dedim değil mi sana

Tiberius''un emrini

Of seni asi

Ah seni zilli

Ağırlığınla sarmalıyorsun

kudurttuğum zevki

Bulma dedim değil mi sana

İsis''in kaybettiğini

Of seni işveli

Ah seni yabani

Islaklığınla çalkalattırıyorsun

çıkamadığım girintiyi

Çalma dedim değil mi sana

Amour''un senfonisini

Of seni neşeli

Ah seni tiryaki

Özünle kamaştırıyorsun

Çağlayanımın heybetini

Kutsama dedim değil mi sana

Tagata''nın ayinini

Of seni yahşi

Ah seni kaprisli

Hırsınla değiştiriyorsun

oynadığım sahneyi

Okuma dedim değil mi sana

Aretino''nun sonelerini

Of seni titremeli

Ah seni esrimeli

Uçurumunla tutuşturuyorsun

kasıklarımın kenetlenmesini

Yutma dedim değil mi sana

Min''in yemini

Of seni sevimli

Ah seni lanetli

Tükenmişliğinle öpüyorsun

yanak dayanmış göbeğimi

Özlettirme bana dedim değil mi sana

''Homo sum! '' demeyi

Söylettirme bana dedim değil mi sana

''Plaudite, comoedia finita est. amici! ''

Yaşattırma bana dedim değil mi sana

Kronos''un Avam eğlencesini', 'Gökyüzüne açılan terasta biri erkek biri dişi Sırnaşıyor birbirine iki deli İnlemelerle başlıyor kokofoni Sorulmuyor artık esaretin bedeli D...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":134,"source_url":"https://www.antoloji.com/avam-eglencesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikayem', 'hikayem-hasan-unal-g7n6a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İ nsan için varolmak

n efes almak ile başlar

a dını bile bilmeden başlar nefes almaya

n e olduğunu neden olduğunu bilmeden başlar hayata

m utlaka bir varlığı vardır artık

ı şığı gördüğü andan itibaren

y alnızdır aslında o ilk kısmında hayatın

o ğlum kızım der birileri ama bu onun için bir anlam değildir

r üya misali büyür büyür büyür durmaksızın

u laştığı her dönemde bir yenidir dünya onun için

m eleklik bitip kişi olmaya başladıkça değişir herşey

s oru sormaya başlar ikisinde üçünde

ı lık şeyler için beşine altısına kadar

k orkmadan eller sobayı 

ı sı derecesi yüksek metalde yanınca eli dokunmaz tekrar ona

y aşama girişi başlar okul yıllarıyla

s abah bir yere gider artık akşam döner evine 

a rtık bir numarası vardır onun okulda 

b ir arkadaşı vardır diğerlerinden daha çok sevdiği

u mutları olmaya başlar bisiklet misali

n edenini bilmeden hırs başlar içinde hayata karşı

u laşmak istediği şeyleri vardır artık

d ünya nedir bilir artık

a dına dünya denin evinde bilirki uzaklarda vardır yakınlar kadar

ş aşırır onlarında ilgi duyunca karşı cinsten birşeye 

i lk kez annesi dışında bir karşı cins daha farklıdır diğer insanlardan

i lk kez sebebini bilmeksizin  birisini düşünür yalnızken kendinden çok

r ahat etmek onu görmesine bağlıdır artık süt içmesine değil

y ıllar biraz daha geçince daha farklı olur evren 

a dından masadan sehpadan herşeyden sorular çıkarır

p lanlar başlar hayata dair yalnız yapılan planlar

b ilmeden hayatın ne olduğunu hayatı yenme isteği başlar on altıda on yedide

a rkasına bakmayı sevmez bu dönem 

k afasından geçen herşey doğrudur 

a klına gelmeyen şeyler doğru değildir onun için

y anında kalbinde aklında 

l aflarında gözlerindeki 

ı şıltıda bir delilik ve bir hoyratlık hayatında

m utlaka hayat ona göre atacaktır zarları mutlaka olacaktır dediği

b ir gün hayat kötü zar atar 

a dını bile istemez kimliğinde 

y azan bir isim kimliğinde üçüncü hanede sadece isim olarak vardır artık

ş oklar yaşar hayata dair doğar ölür hergün

a ma bir gün ne olur biliyormusun

i lk kez ama ilk kez bir ocak günü o soğukta ısınır içi ilk kez bir 26 mart günü başlar hayat bitmeyecek sevgisiyle

r üya bitmişti hayat başlamıştır o anlatılamaz güzelliği ile sevgilisinin ve bulmuştur hayatı artık ANLAMINI', 'İ nsan için varolmak n efes almak ile başlar a dını bile bilmeden başlar nefes almaya n e olduğunu neden olduğunu bilmeden başlar hayata m u...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ünal']::text[], 8.5, '{"poet":"Hasan Ünal","poet_slug":"hasan-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/hikayem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dövüşken', 'dovusken-cem-salih-un-nph0w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cok dovustum 

Bundandir dinmek bilmeyen ofkem

Ve huznum o kadar buyuktur ki 

Kocaman bir agizla gulerim, ustunu ortmek icin

Bir kin kustuydular ustume, bir kin

Gogsumu yarip kalbimi istediler, 

Sesimi verdim

Yokluguma bir tuttular varligimi

Bir cehennem sigdirdim o zaman 

İyiyle kotu, dogruyla yanlis arasina

Herkes hakliydi, bana kaldi haksizlik

Kovuldum kavmimden

Ara sokaklarda bir kentin yalnizligina bulastim

Ve cekip aldim yuzumu, butun aynalardan

Cok dovustum

Gogsumdeki kani kurutmadim ben

İyilestirmedim hicbir yarami

Kalbim tum cokluklara inat, cekildi kuytuluklara

Tutamadim

Sonrasi ne hayati kutsayan beklentiler

Ne guzel gelecek dusleri, 

Cekildi kuytuluklara, oylesine maglup

Hircinlik kaldi bana, elim yuzum kin bulasigi

Cozdum zamanin butun milatlarini

Engeregin dilini caldim

Yalnizligini destim kentlerin, ara sokaklarinda

Kavimden kavime dolastim

Paramparca ettim butun aynalari

Her parcada kendime baktim

Butun irmaklarimi saldim, yorgunluga inat 

Yakalandim sonunda

Bir okyanusa bagladilar beni

Cok dovustum 

Yassiz gozlerle baktim, solarken ortancalar

Aldanmadim denizin masmavi yalanina

Ama bulanik bir izdim yalniz, bu dingin okyanusta 

Firtinaya yetmedim

Simdi zorlayin gogsumu, yuzunuzden eksik olmasin kizginliginiz

Hakliliginiz bir kirbac gibi şaklasin sirtimda 

Akitsin zehrini unutkanliginiz

Ve kusun kininizi ustume, butun kininizi kusun

Cok dovustum 

Yakalandim kavimlerin birinde

Bir okyanusa bagladilar beni

Caresiz hakliydi herkes

Bense onulmaz bir yanlislik

Ve butun haksizliklarin toplami', 'Cok dovustum  Bundandir dinmek bilmeyen ofkem Ve huznum o kadar buyuktur ki  Kocaman bir agizla gulerim, ustunu ortmek icin Bir kin kustuydu...', ARRAY['Türk Edebiyatı','Şiir','Cem Salih Ün']::text[], 8.5, '{"poet":"Cem Salih Ün","poet_slug":"cem-salih-un","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/dovusken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku Zaman ve Yenilgi', 'korku-zaman-ve-yenilgi-i-smail-ozabaci-7l88r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir günaydın kadar

yakınında olmak, her sabah

sonra  dinlemek gözlerinden 

yazılmamış bir şiiri

ve üç kavram

korku, 

zaman, 

yenilgi, 

korku ki

sensizlikle başlar içimde

büyüdükçe büyür yokluğun geceleri, 

zaman ki seni bana 

bir yaklaştırır

bir uzaklaştırır

salıncak gibi...

yenilgi

suretimin yansıyıp gelmesi boşlukta

yorgun bir yolcu gibi

üç kavram, 

üç özlem, 

üç şiir, üç kelimeden..', 'bir günaydın kadar yakınında olmak, her sabah sonra  dinlemek gözlerinden  yazılmamış bir şiiri ve üç kavram korku,  zaman,  yenilgi,  korku...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/korku-zaman-ve-yenilgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğa Merhaba', 'dostluga-merhaba-salih-ozalasan-zzk5m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani neredeler

Sevdasından kor alevlerde yandıklarım

Issız gecelerde

İçin için gözyaşı dökdüklerim

İsmini dua edip dilimde

Tanrıya geceler boyu zikir ettiklerim

Bırakıp gitmişler birer birer

Gönlümde baş köşede yer verdiklerim

Sayfalar dolusu şiirler yazdıklarım

İsmine sevda manileri düzdüklerim

Sadık sevgili, sıkı dost sandıklarım

Bırakıp gitmişler birer birer

Yüreğimi önlerine serdiklerim

Bir ben kalmışım gecenin karanlığında

Tek başına herzaman yapayalnız

Elinde bir kalem

Önünde yeni bir sayfa

Bazen isyan edip diyorum ya

Salih bırak artık kimse için yazma

Kır at söz dinlemez kalemini

Son satırı dostlara yaz elveda

Gel görki veda edemediğim

Gerçek bir dost çıktı 

Sanırım sonunda karşıma

(((Dostluğunuz kaybedilmeyecek kadar değerliydi))) 

Diyerek vedama sitem eden

Umudumun bittiği bir anda

Karşıma geçip kükreyen

Ben buradayım kaçmak yok öyle

Al eline kalemini aç yeni bir sayfa

Gerçek dost sıkı dost MERHABA

Merhaba öyleyse bende buradayım.

(09-07-2002   Saat 15.15)', 'Hani neredeler Sevdasından kor alevlerde yandıklarım Issız gecelerde İçin için gözyaşı dökdüklerim İsmini dua edip dilimde Tanrıya geceler b...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dostluga-merhaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-hakan-akyurt-yowes', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıldızlar yakınımdır benim, 

Geceler dost bana..

Yalnızız ikimizde, 

Özlemle bekleyen sevdalılar gibi..

Gece yine kavuşurken gündüzüne, 

Ben ise yine hasretim; 

Sevdiğime...

Sararlar geceleri gökyüzümü, 

Aydınlatırlar adeta gecemi, 

Ama herbiri yalnızdır, 

Herbiri sevdasız; 

Tıpkı ben gibi...

Sohbet ederken her gece, 

Dalıp giderim kendimle..

Sabredemeyen yıldızlara bakarken, 

Dayanamayıp yalnızlığa, 

Kavuşmak için sevdiğine, 

Kayan yıldızlar görürüm...

Özlemi usandırdı beni, 

Yalnızlık bıktırdı artık..

Kavuşmak istiyorum sevdiğime, 

Bitsin istiyorum hasretim, 

Tıpkı sabredemeyen; 

Kayan Yıldızlar gibi...', 'Yıldızlar yakınımdır benim,  Geceler dost bana.. Yalnızız ikimizde,  Özlemle bekleyen sevdalılar gibi.. Gece yine kavuşurken gündüzüne,  Ben...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yildizlar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Bana', 'elveda-bana-kenan-ceco-yhzmt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerim nemiyle bekledi baharı

Kulaklarım avluda 

Sesim dağlarda yankılandı

Tepeden, tırnağa bağlandım

Her mevsimi ılıman

Her geceyi yıldızsız buldum

Ama saatleri ya dakikaları

Bir cana armağan sundum

Elveda bana

Oysa bir günü yaşamak isterdim 

Cebinde yıldızlarla yaşamın kıyısında 

Ellerini uzatıp merhameti azat etmişsin 

Sana bakarken ürpermek yok

Umut etmek, sevilmek

Gülmek bahtım olsun

Ya aşkı ya sevgiyi 

Bir cana armağan sundum

Elveda bana  

Düşlerim ıslanır, kurutamazsın 

Ve şaşkınlığını yaşarsın, hayalını görürsün

Ötesini buldurmadan baygınlığını çekersin

Usulca haz buldurur 

Ne gözde yaşı, ne yüzünde  tebessümü 

Ne de tenindeki titrekliğin acısını 

Belki bahtın kara

Belki bir oyunun sahnesi

Ama yaşamak ya ölüm 

Bir cana armağan sundum

Elveda bana', 'Gözlerim nemiyle bekledi baharı Kulaklarım avluda  Sesim dağlarda yankılandı Tepeden, tırnağa bağlandım Her mevsimi ılıman Her geceyi yıldız...', ARRAY['Türk Edebiyatı','Şiir','Kenan Ceco']::text[], 8.5, '{"poet":"Kenan Ceco","poet_slug":"kenan-ceco","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/elveda-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş', 'savas-erdem-ozbek-k1qw7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yıkılmış bir şehrin ortasında dizlerimi büküp oturmuşum

çığlıklar geliyor fabrika bacalarından 

bir tankın üstünde ölü asker bedenleri

savaşmaktan ziyade ateşin hükmünü sürmüş ama kaybetmişler

yıkıntıların içinde yaşlı bir kadın dolanıyor

elinde torbası bayat ekmek kırıntıları arıyor

sokak köpekleri toz toprak içinde

kurşun izleri, barut kokusu 

ve elinde aşkının resmi

içimdeki savaşın hüznü 

alnımdan akan kan ve şehir

o eski ışıltılı bulvarın ortasındaki havuz

havuzun içinde kumar masası

ruletde ben dönüyorum

ben duruyorum dünya dönüyor

aşk kokuyor silahların içinde

saçlarım pislik içinde

konçlarımın içinde yedek kurşunlar

bir şehri darmadağın eden sevdaya ait şarapneller

kurşun karası bulut

deniz, aşk, sen, duman

koca bir tankın topumu 

yoksa kırışan resimdeki senmisin 

irin toplayan beynime vuran.....

erdem özbek', 'yıkılmış bir şehrin ortasında dizlerimi büküp oturmuşum çığlıklar geliyor fabrika bacalarından  bir tankın üstünde ölü asker bedenleri savaş...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özbek']::text[], 8.5, '{"poet":"Erdem Özbek","poet_slug":"erdem-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/savas-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemem', 'soyleyemem-kenan-ceco-951hm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerim takılır....! 

	Söyleyemem 

İçime düşürürsün bakışlarını

Akıtırsın tenime kızgın ateşini

Farkına varmadan hayallerini görürüm

Söyleyemem

Düğümlenir sözcükler dilime

Bağlanır sancıları umutlarıma

Kuşku sarar her yanımı

Ve düşüncesi azar azar bitirir

Söyleyemem 

Odaları tenha ve ışıksız yaşadığımı

Duvarları durmadan tekmelediğimi

Söyleyemem 

Yalnızlığa duyduğum nefreti

Bu gerçeğe karşılık beklediğimi

Bakışlarının artık aşkı haykırdığını

Söyleyemem

Kalbimin her gün seni demlediğini

Söyleyemem 

Sahte gülüşlerimi, kırılan umutlarımı

Söyleyemem 

Artık tesadüflerin inandırıcı olmadığını

Söyleyemem “Seni Sevdiğimi” Söyleyemem 

Aşkı arkıt seninle yaşamak istediğimi

	Söyleyemem...!', 'Gözlerim takılır....!  	Söyleyemem  İçime düşürürsün bakışlarını Akıtırsın tenime kızgın ateşini Farkına varmadan hayallerini görürüm Söyley...', ARRAY['Türk Edebiyatı','Şiir','Kenan Ceco']::text[], 8.5, '{"poet":"Kenan Ceco","poet_slug":"kenan-ceco","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/soyleyemem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-erdem-ozbek-deda7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ankara''da Bıraktıklarım

saz calar kıs ıklımınde agac dalları

daha bır sert vurur tellerıne, ozlem dolan baharına karsı

yuzun bır kavruk kavruk olur ayazla yatınca

ellerın tutmaz, kavaklar salınır pencerede

bacaların dumanı, 

ve yıkılan evlerın yarım kalan oda duvarları

ıs tutan ocaklar cıkar meydana, 

gece yatakta kıvrılmak sızlanarak, 

hatıra dedıgın sey de boyle olur

kavruk kavruk olur yuregın

ellerın tutmaz, dudakların tıtrer

yıkılan duvarların arkasından bakarsın kendıne

hanı top oynayıp yoruldugun zamanları

elvan gazozunu ıkı elınle ıcısını, 

pazar gunlerı annenın utu kokusu, kolalı yakalar

kısın sert calar huzun mevsımı

daha bır hızlı vurur tellerıne 

bedenını savurup atar kovuklu bır agac govdesıne 

yuzun, gogsun kan kan olur

gurbet de boyledır doyurmaz sehrın ısıkları

ıllakı anneannenın tarhana corbası

komur sobasında kestane

ılla yanan parmagına dıs macunu olmalı

ılla huzun olmalı soyledıgın kıs turkulerınde 

ılla yıtıp gıtmelı bır hayat arkasından doldurdugun gozyaslarıyla

saz calar kıs ıklımınde agac dalları

daha bır sert vurur tellerıne, ozlem dolan baharına karsı

(İçinde benim olduğum bu beden sevda denilen şeyin yaşamı her yönüyle duyumsatan ağırbaşlılığı ve güngörmüş görgüsüzlüğüyle beslenmiştir.) 

erdem özbek 26/11/2001 13: 00', 'Ankara''da Bıraktıklarım saz calar kıs ıklımınde agac dalları daha bır sert vurur tellerıne, ozlem dolan baharına karsı yuzun bır kavruk kavr...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özbek']::text[], 8.5, '{"poet":"Erdem Özbek","poet_slug":"erdem-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ankara-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Gün Bu', 'hangi-gun-bu-kenan-ceco-b1uae', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu hangi yirmi dört saat

Bir karanlık bir aydınlık geçen

Bir ayık bir sarhoş gezilen 

Ya da kaşıksız çorba içilen 

Dur durak geçen gün, düzensiz gün

Bu hangi yirmi dört saat

Bir yağmurlu, bir karlı geçen

Bir barışık bir karışık gezilen

Yada karşılıksız sevilen

Başıboş geçen gün, hain gün

Bu hangi yirmi dört saat

Bir yalan bir dolanlı geçen

Bir boş bir dolu gezilen 

Yada habersiz beklenilen

Sövülen gün pervasız gün

Bu hangi ömür 

Her gün biraz biraz eğilen

Bir onsun bir... 

Yada hiç kimsesiz

Bensiz kalan ömür, benim olmayan ömür', 'Bu hangi yirmi dört saat Bir karanlık bir aydınlık geçen Bir ayık bir sarhoş gezilen  Ya da kaşıksız çorba içilen  Dur durak geçen gün, düze...', ARRAY['Türk Edebiyatı','Şiir','Kenan Ceco']::text[], 8.5, '{"poet":"Kenan Ceco","poet_slug":"kenan-ceco","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hangi-gun-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-erdem-ozbek-170i3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ıcınde yattıgımız bahardan kusanıp gelmıssın bugun

 sesın tıtrek

 yıne gıymıssın sevdıgım karelı gomlegını

 sacların dagınık

gunes yakmıs tenını, dudagında anımsayamadıgım bır ıslık

kus cennetınden calmıssın omzundakı heyecanlı kıpırtıyı

senı sevmek dıyorum

senı sevmek aksamları yastıgıma basımı koydugum 

soguk oldugunda gece uzerıme cektıgım senı sevmek

yazları gezındıgım bahcelerdekı bogurtlen agacları

kuzey ruzgarları sacımı savuran ve senı sevmek

ızmırde aksam olurken tutune katmak senı

kolumdakı saate bakarak dusunmek

denızdekı balık 

yuzume esen meltem 

keske senı bu kadar basıt sevseydım 

keske senı bu kadar basıt....

erdem özbek 10/09/2001 19: 45', 'ıcınde yattıgımız bahardan kusanıp gelmıssın bugun  sesın tıtrek  yıne gıymıssın sevdıgım karelı gomlegını  sacların dagınık gunes yakmıs te...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özbek']::text[], 8.5, '{"poet":"Erdem Özbek","poet_slug":"erdem-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/keske-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh Hastası', 'ruh-hastasi-erdem-ozbek-zw58p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kocaman bir oda

Duvarlar koca kırmızı çiçekli duvar kağıdı

Yatak biraz dağınık, çarşaf kirli

Yanımda bir sehpa var üstü selpak dolu

Karnım çıplak, elim başımın altında

Çoraplarımı çıkarmamışım yatarken.

Sanırım kalçası çok iriydi

Şimdi banyo yapıyor su sesi geliyor buraya

Bende silüeti çoktan parçalanmış, 

Eski radyo eski parçalar çalıyor, onu dinliyorum

Belim çok ağrıyor, desteksiz bir hayat gibi kaba bir ağrı

Banyonun kapısının altından sular çıkıyor 

Rengi kırmızıya çalmış

Kötü kokuyor, lamba zaten az aydınlatıyor

Sırtıma ceketimi alıp çıkıyorum, 

Hava kararmış, şehirde karbonmonoksit kokusu

erdem özbek 29/05/2001', 'Kocaman bir oda Duvarlar koca kırmızı çiçekli duvar kağıdı Yatak biraz dağınık, çarşaf kirli Yanımda bir sehpa var üstü selpak dolu Karnım ç...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özbek']::text[], 8.5, '{"poet":"Erdem Özbek","poet_slug":"erdem-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ruh-hastasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-mustafa-sureyya-sezgin-rf68f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir coşku beliriverir

İçimde ansızın...

Gökyüzünün sonsuzluklarına

Dikerim gözlerimi! ..

Alabildiğine sınırsız, 

Koklarım hürriyeti! ..

Ben varım bu yeryüzünde! ..

Tek başıma bağımsız! ..

En somut gerçek olarak

Tüm insanların ortasında! ..

Ne olurdu biz insanlar, 

Tek vücutta birleşebilsek

Ve beraberce, 

Koklasak hürriyeti

Burcu burcu...

Gülümseyerek yapmacıksız, 

Mutluyuz diyebilsek.

El ele sırt sırta vererek

Bir oyun oynasak.

Adını

Özgürlük koysak! ..

(İstanbul,01.06.1975)', 'Bir coşku beliriverir İçimde ansızın... Gökyüzünün sonsuzluklarına Dikerim gözlerimi! .. Alabildiğine sınırsız,  Koklarım hürriyeti! .. Ben ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ozgurluk-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünerek Uyandım', 'seni-dusunerek-uyandim-mustafa-sureyya-sezgin-ivh7y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşündüm...

Seni ilk gördüğüm o yokluk anını.

Düşündüm...

Seni nasıl sevdiğimi.

Bilmeden, 

Her davranışınla

Ümit doldurdun içimi.

Bir gün, ''Seviyor'' dedim.

Bir gün, ''Sevmiyor'' dedim.

Kızdığını sandım bir ara, 

Sonra yine yaklaştın.

Pırıl pırıl gözlerinle

Gözlerimin içine baktın.

Vuruldum yeniden, 

O siyah, 

O güzel gözlerine.

Bir gün sevdim, 

Bir gün sevmiyorum dedim

Kendi kendime.

Ve nihayet

Yine rüyalarıma girdin.

Bu sabah

Ben yine, 

Seni düşünerek 

Uyandım...

(Akhisar,06.02.1970)', 'Düşündüm... Seni ilk gördüğüm o yokluk anını. Düşündüm... Seni nasıl sevdiğimi. Bilmeden,  Her davranışınla Ümit doldurdun içimi. Bir gün, ''...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-dusunerek-uyandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrolası Gururumuz', 'kahrolasi-gururumuz-mustafa-sureyya-sezgin-g96n8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oyun oynar gibiyiz her zaman

Seninle ikimiz.

İstersek çok samimi

Oluveriyoruz birden.

İşimize gelmediğinde

Görmemezlikten geliyoruz

Birbirimizi.

Tebessümden kaçıyoruz.

Olmazsa zorlarcasına

Lütfen, 

Gülümseyiveriyoruz.

Aslında benim düşündüklerim, 

Senin de kafanı kurcalıyor.

'' Seviyor mu, 

Yoksa sevmiyor mu? '' diye, 

Soruyorsun kendi kendine.

Uzaktan uzağa

Göz ucuyla

Gözlüyorsun beni.

İkimizin de yoksun bulunduğu

Tek şey, 

Biraz cesaret...

Bolca olan, 

Sonuna dek

Dolup taştığımız, 

Duygularımızı onunla susturup

Bastırdığımız, 

Kahrolası gururumuz! ..

(Akhisar,25.02.1970)', 'Oyun oynar gibiyiz her zaman Seninle ikimiz. İstersek çok samimi Oluveriyoruz birden. İşimize gelmediğinde Görmemezlikten geliyoruz Birbirim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kahrolasi-gururumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Olsaydı', 'deli-olsaydi-cengiz-yazici-j8w4p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olsaydı, Hoca olurdu.Göle maya çalmakla.

Yada, Ferhat.Koskoca bir dağı yarmakla.

Ya, Napolyon''a ne demeli, 

Adam, gece gündüz, para saymakta.

Mimar Sinan, sanki çokmu akıllı.? 

Bir balçığın üzerine, hiç cami yapılırmı.? 

Ya piramitleri, yapan şu ustalar, 

Onca kaya, o yüksekiliğe taşınırmı? 

Sanki, Fatih İstanbul''u aldıda iyimi etti.? 

O kadar savaşa, acaba ne gerek vardı? 

Şimdi Fatih''e kaç kişi Fatiha okuyor, 

Bunlar, O''adamın kemiklerini, sızlatıyor.

Hani, şu bizim deli İbrahim paşa, 

Balıklara altın atmazmıydı, 

Kitaplar bunu böyle yazmadımı.? 

Oysa halk, muhtaçken kör kuruşa.

Bak, birde Neron var, adam harbi akıllı, 

Tek kibritle, yakarken koca Roma''yı, 

Bizimkiler bir kutu bitirdi, beni nezle etti, 

Hala yakacaklar, şu külüstür sobayı.

Sen, deli diyeceksen, Darvin''e demelisin, 

Atalarımı, maymunlara benzettiği için.

Yada, Hitler''e deyin mesela, 

Odun yakar gibi, 

Fırınlarda adam yaktığı için.', 'Olsaydı, Hoca olurdu.Göle maya çalmakla. Yada, Ferhat.Koskoca bir dağı yarmakla. Ya, Napolyon''a ne demeli,  Adam, gece gündüz, para saymakta...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/deli-olsaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Zaman Otu Yerim Ben', 'o-zaman-otu-yerim-ben-cengiz-yazici-r80md', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana öyle geliyorki, 

Zaman bitiyor sanki. 

Ya göremezsem seni, 

Tutamazsam ellerini... 

Sesini duymak, 

Resmine bakmak, 

Mektuplarını okumak, 

Mesaj atmak, 

Çağrı bırakmak, 

Bana yetmiyorki. 

Şunun şurasında, 

Adam gibi severken, 

Ortada, bir neden 

Yokken. 

Olur ya, şartlar, 

Değişirse birden. 

Ve sen, çekip gidersen... 

... 

İşte o zaman, ''''OTU'''' yerim ben...', 'Bana öyle geliyorki,  Zaman bitiyor sanki.  Ya göremezsem seni,  Tutamazsam ellerini...  Sesini duymak,  Resmine bakmak,  Mektuplarını okuma...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/o-zaman-otu-yerim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül (2)', 'gonul-2-ensar-aktas-l5c28', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülün ömrü kısa olur, kokladıkça solar derler

Ölümsüzdür benim gülüm, gönül çiçeğim, bilemezler

Ne kadar çok sever koklarsam, o kadar çok açar, güler

Üstüne koklayamam başka çiçekler, gonca güller

Lazım da değil zaten, bana onun tertemiz aşkı yeter

Rotterdam,29.06.2002', 'Gülün ömrü kısa olur, kokladıkça solar derler Ölümsüzdür benim gülüm, gönül çiçeğim, bilemezler Ne kadar çok sever koklarsam, o kadar çok aç...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gonul-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilen', 'bir-bilen-sukru-erbas-as1o1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umduğun inceliğe inmiyorsa söz, 

Çekil suskunluğun tüneklerine; 

Ucuz etme anlamı...

Böyle zamanlarda insan

Çokluk yalnız kalmal
..........
..........', 'Umduğun inceliğe inmiyorsa söz,  Çekil suskunluğun tüneklerine;  Ucuz etme anlamı... Böyle zamanlarda insan Çokluk yalnız kalmal .......... ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-bilen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansizin', 'ansizin-huseyin-cayikli-98lj3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'icim yandi ummadigim yerde gordum

gelmeden tenini gormeden gordum

ayrildigimiz gun cektirmissin galiba resmin

bildigim son konserin

bildigim ve bilmekte oldugum 

son sarkin 

bendim

bitti...

Adin hayalimde biryerde

sanirim gizemli birseydi

herneyse derin mevzudur ask

fazla irdelenmez gun gelir 

ihanetten kirilir kalemin

cok kotu dua ettim senin adina

ama pisman degilim

en kotu duam

hep mutlu ol...

gun gelir karsilasiriz 

birbirimize bakmadan 

yabanci gibi geceriz

gun gelir ben adadan 

biraz kacarim

ve geri donerim

...', 'icim yandi ummadigim yerde gordum gelmeden tenini gormeden gordum ayrildigimiz gun cektirmissin galiba resmin bildigim son konserin bildigim...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ansizin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan', 'uzaktan-muhammet-ferhat-firat-wh8ww', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayın şavkı vurmuş tepeye

Parıl parıl parlar uzaktan

Bin hüzün sardı yine

Ay''ı gören göz var uzaktan

O Ay''ı görenin cemaline

Yüreğim bir nar uzaktan

O cemali Mecnun görse

Leyla ona ar uzaktan

Ayın şavkı vurmuş cemale

Verse Ferhat nazar uzaktan

Şirine verdiği can seve seve

Hep efgan ü zar uzaktan

Yusuf için dudak kesene

Kordur cemal-i yar uzaktan

Ne gerek bunca söze

Anmak adını kar uzaktan

Gecelere sor ki bir kere

Anmasam ey yar uzaktan

Uyku düşman bu gözlere

Şahidim yıldızlar uzaktan

(5 Haziran 2002 Oltu Garnizonu)', 'Ayın şavkı vurmuş tepeye Parıl parıl parlar uzaktan Bin hüzün sardı yine Ay''ı gören göz var uzaktan O Ay''ı görenin cemaline Yüreğim bir nar ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Ferhat Firat']::text[], 8.5, '{"poet":"Muhammet Ferhat Firat","poet_slug":"muhammet-ferhat-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uzaktan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anı Gibi', 'ani-gibi-adil-i-zci-uu6uo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabahı uyandırıp, yeryüzünü, 

Ellerini yıkamış, sabun kokulu

Ardından ekmek almış, taze

Sonra güzelliğine su vermiş aynı ellerle.

Teni haziranda hanımeli, geceden.

Bazen de serinlikte buğday tarlası.

Kokularından biri de bu olsun işte!', 'Sabahı uyandırıp, yeryüzünü,  Ellerini yıkamış, sabun kokulu Ardından ekmek almış, taze Sonra güzelliğine su vermiş aynı ellerle. Teni hazir...', ARRAY['Türk Edebiyatı','Şiir','Adil İzci']::text[], 8.5, '{"poet":"Adil İzci","poet_slug":"adil-i-zci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ani-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asude', 'asude-adil-i-zci-6m5sx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adlarımız bile çoktan eskidi

Ve bir gündü, dehşet içinde anladım: 

Sesleri de artık hiç duyulmuyor

Zaman bu, neleri silmiyor ki! 

Kalbim, bizi en iyi bilen sensin

Anlat ki herşeyimiz ölümlere düşmeden: 

Hep aynı köşelerde oturur, 

Ve bir türlü o güne sığamazdık.

Yazlar, yokuş aşağı gelip geçer, 

Arka odalar poyrazlara dönerdi.

Kadınlar görürdük sabah bahçelerinde

Örtülü müydü yüzleri, sis mi basardı? 

-Belki de bellekte Monet rüyası-

Bahçeler biter, imgeler uzanırdı.

Manastıra dalardık, sıkışıp kalmış ruhlara

Duvarlarında gözler vardı, karşılaşırdık...

Zaman bu, hiç durup beklemez ki

Şimdi belleğimde hep o aynı fısıltı: 

Adlarınız bile çoktan eskidi! Bittiniz!', 'Adlarımız bile çoktan eskidi Ve bir gündü, dehşet içinde anladım:  Sesleri de artık hiç duyulmuyor Zaman bu, neleri silmiyor ki!  Kalbim, bi...', ARRAY['Türk Edebiyatı','Şiir','Adil İzci']::text[], 8.5, '{"poet":"Adil İzci","poet_slug":"adil-i-zci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/asude-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokrat Gibi', 'sokrat-gibi-adil-i-zci-ede87', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilim adamlarını tanı bir bir

Sanatçıları, gelmiş geçmiş

Tarih''e sokul biraz, Felsefe''ye

Ülkeler Coğrafyası''na eğil.

Yazın''a dal, şiirlere

Çok önemli Matematik

Gökbilim''de düşlerin en uzak boyutu.

Bunlardan çıkıp dönünce insan

Bak nasıl geçiyor ölüm ürküsü! 

Bodrum Kalesi''nden bakarken

Ya da Boğaz''ın iki kıyısı arasında

Evrene karışıp var olmak gibi.', 'Bilim adamlarını tanı bir bir Sanatçıları, gelmiş geçmiş Tarih''e sokul biraz, Felsefe''ye Ülkeler Coğrafyası''na eğil. Yazın''a dal, şiirlere Ç...', ARRAY['Türk Edebiyatı','Şiir','Adil İzci']::text[], 8.5, '{"poet":"Adil İzci","poet_slug":"adil-i-zci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sokrat-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-altay-oktem-fprsf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'biz seninle ikimiz şubat gibiydik

kayadan düşsek ağrımazdı bir yerimiz

küçücük bir taş görsek irkilirdik

öyle sıkılırdık ki birbirimizden içimiz kalkardı

bir şiiri tersten okumak bile anlamlıydı

karıncaları başparmağınla ezmek

sinek kanatlarını yakmak o günlerde

hiç boş kalmayan ama hep yalnız

bir otel odası gibiydik seninle

boşuna aldatılırdık, boşuna susardık

boşuna bakardık çöken bir balkondan kendimize

bir anlam veremezdik çekip gitmememize

her aşk

aynıdır zaten çoğalır kan kaybettikçe', 'biz seninle ikimiz şubat gibiydik kayadan düşsek ağrımazdı bir yerimiz küçücük bir taş görsek irkilirdik öyle sıkılırdık ki birbirimizden iç...', ARRAY['Türk Edebiyatı','Şiir','Altay Öktem']::text[], 8.5, '{"poet":"Altay Öktem","poet_slug":"altay-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık', 'yazik-altay-oktem-vc5r8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu şehir beni anlayamaz, yasaksa yasak

ateş söndü! döndü suları çağıran sesin

geri döndü

masum bir öpüşü, umulmaz düştü, yasaksa yasak

ateş söndü! şiddet boşlukları doldurur

barbarlar geri döndü.

kötüyüm. ne mutlu kan yakışır bana

kasketini tarlada unutan bir köylü gibi

sızarım en kirli yerinden zamana

ateş söndü! kollarında acı çekmek ölümümdü

pisim. kara bir sokak kedisiyim bu şehrin kıyısında

alnında jilet yarası taşıyan sevgilim, nemli tanrıçam

her gece taparım o umulmaz yanına

o adsız şehre; ışıksız geleceğe

ateş söndü! kılıcım usulca girdi kınına

prensesim, tiz sesim, pis güneşim

yazık yine döndük kendimize

yazık

yine döndük kendimize', 'bu şehir beni anlayamaz, yasaksa yasak ateş söndü! döndü suları çağıran sesin geri döndü masum bir öpüşü, umulmaz düştü, yasaksa yasak ateş ...', ARRAY['Türk Edebiyatı','Şiir','Altay Öktem']::text[], 8.5, '{"poet":"Altay Öktem","poet_slug":"altay-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yazik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baskın', 'baskin-arif-ay-4vlu0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yağmur bir göçtür

kollara kelepçe vurulunca

kapıda beklenmedik zil sesi

başlarında zulmün simgesi

süzülürler

başlar talan

         göçtür

         evde ağıt/figan

geceyi çöz dağılsın yıldızlar

yitik bir kuş, sürüklenen bir yaprak

hani bizim olan güneş

ah bu dağlanan yürek

hangi dağda yaktığın ateş

bir devir

buğday mühürlenir

kitap sürgülenir

tutuklanır yaşam

yağmur bir göçtür

kollara keleçpe vurulunca', 'yağmur bir göçtür kollara kelepçe vurulunca kapıda beklenmedik zil sesi başlarında zulmün simgesi süzülürler başlar talan          göçtür   ...', ARRAY['Türk Edebiyatı','Şiir','Arif Ay']::text[], 8.5, '{"poet":"Arif Ay","poet_slug":"arif-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/baskin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar Nerde', 'cocuklar-nerde-arif-ay-vog1u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana anlatacaklarım var

otur

bir bardak su biraz zeytin

gözlerin/tüm sevincin

önce sofrayı kur

bak/gördün mü

nasıl sıcacık ekmek

sevenin yüreği/elimin emeği

nerede kaldı bunlar

çocuklara bir bak

-oyundalar/gelirler şimdi

saklama yüzündeki ikircimi

bir çatırtı/zaman durdu

işte oyun

onlar vuruldu

biraz gözyaşı biraz tuz

ekmeğim sokaklarda

sofrayı kaldır', 'sana anlatacaklarım var otur bir bardak su biraz zeytin gözlerin/tüm sevincin önce sofrayı kur bak/gördün mü nasıl sıcacık ekmek sevenin yür...', ARRAY['Türk Edebiyatı','Şiir','Arif Ay']::text[], 8.5, '{"poet":"Arif Ay","poet_slug":"arif-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cocuklar-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnfaz', 'i-nfaz-arif-ay-e7xs1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'mahcup bir cellat gizli bende

her gün yağlar durur ipini

vakti yok infazların

kendi infazda vakitlerin

hızarlara gelemem gayrı

hızarlara da

çürütülmüş bir köküm şura burda

seni düşlemeye gün yetmiyor artık

günler bende bakırçalığı

serin rüzgarlarda saçların

yapraklarda sesin

bin yıldızlı gök yaptım gözlerinden

sevgilim demek için geceme

zor yollardayım

önüm ardım cinnet mahyaları

cam kırıkları dökülüyor ıslıklardan

gül değil yalnızlık bu elden ele

kıyamet habercisi çarşılarda', 'mahcup bir cellat gizli bende her gün yağlar durur ipini vakti yok infazların kendi infazda vakitlerin hızarlara gelemem gayrı hızarlara da ...', ARRAY['Türk Edebiyatı','Şiir','Arif Ay']::text[], 8.5, '{"poet":"Arif Ay","poet_slug":"arif-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/infaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Düşü', 'su-dusu-arif-ay-j21zm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'denize bir şeyler diyor adam

çiviler çakarak denize

gözlerinden

denize bir şeyler diyor adam

deniz sımsıcak Erzurum kan

denizden bir parça

adamın alnına koymalı

belki çoğalır özlemi

rüzgarsa toprağın dansı

gelir esen meltemle

ölüm ıhlamur kokusu

çeker maviliği bir soluk

belki çoğalır özlemi/çoğalır adamın', 'denize bir şeyler diyor adam çiviler çakarak denize gözlerinden denize bir şeyler diyor adam deniz sımsıcak Erzurum kan denizden bir parça a...', ARRAY['Türk Edebiyatı','Şiir','Arif Ay']::text[], 8.5, '{"poet":"Arif Ay","poet_slug":"arif-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/su-dusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'the doors', 'the-doors-rabia-can-ulas-bc9zx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'unutulmuş artık eski şarkılar, 

hiç bir mısra içimizden geçmiyor, 

çatısız akşamlar yıldızların üstümüzde sabahlayışı, 

şiir kitaplarında ayraçlanmış sayfalar, 

hiç bir ezgi bize unutturmuyor ince yazılmış isimleri.

ne kedi mırıltısı ne suyun sesi, 

kesmiyor artık bildik duygusallıkları, 

sana ölelim demiştim yıllar önce ince l de laleneda, 

bir liverpol akşamında çekip gidelim demiştim, 

ben rakı beyazında yüzerken memleketimde, 

sense bir ezanda kaybolurken..

ben sesini duydum minarelerin.ama..

bizi hiç anımsatmayan şarkılar varedildi, 

şimdi kulağımıza her değdiğinde ölüyoruz o sesler..

şimdi çok uzağız birbirimize, 

artık ne suyun ne şiirin nede sesimizin izi var ömrümüzde, 

ama lalenayı her okuyuşunda gözüm, 

izi var bakışlarının dudaklarımda..

kaybetmiş bulvar akşamlarında..

gelen geçen güzel kadınlara yazıyorum yüzünü, 

sen bir tek kadındınya, , 

ben bir çok kadını birleştirerek arıyorum yüzünü..

mutlu ol, , 

the doors dinleyen kadın..', 'unutulmuş artık eski şarkılar,  hiç bir mısra içimizden geçmiyor,  çatısız akşamlar yıldızların üstümüzde sabahlayışı,  şiir kitaplarında ay...', ARRAY['Türk Edebiyatı','Şiir','Rabia Can Ulaş']::text[], 8.5, '{"poet":"Rabia Can Ulaş","poet_slug":"rabia-can-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/the-doors-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'şiirlerden nefret ediyorum', 'siirlerden-nefret-ediyorum-sair-diapunctum-pttum', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne yapıyorsun bilmiyorum

neredesin

kimlerlesin

şu anda 

ne zaman paslanır yürek acısı

ne zaman kopup düşer toprağa

kim karar verir 

aklından geçenleri bilseydim

alın yazından hemen geçip gitmeseydim

inan üzmezdim seni

terkedip gitmezdim

kış günüydü biliyorsun

görülmedik bir kar 

seninse yüreğinde sakladığın bahar

of of

of

sakladığın bahar

benden bir şeyler duymak istemiştin

belki

yanımda olmak 

ama öyle aptalım ki

kimi suçlayacağımı şaşırdım ki

eski sönük bir volkan gibi hissediyorum kendimi

ahdım olsun

andım

olsun

seni bir daha görürsem

seni sevdiğimi söyleyecem

olmaz biliyorum

senin yolun farklı

olmaz olmaz

bilyorum

ama söyleyecem

bıktım çünkü artık

pas doldu içim

çürüdüm 

artık ne kendime faydam ne de başkasına

kamu açığı gibiyim

arpalık gibi yüreğim

hayatım da gördüğüm en muhteşem kadın değilsin

güzel değil ama zeki ayağı değil bu

bana ne zekandan

sen de ne buldum bilmiyorum

evet ben de öyle yakışıklı sayılmam 

göbeğim çıktı birde biliyorum

sana aşık olmam için ojektif bir nedenim yok

ama aşığım

uzun zaman dır aşksızdım

aşık olma ihtimalimi ortadan kaldırmak için herşeyi denedim

kimse bana aşık olmasın

bunu da istedim

bu şiir berbat farkındayım

bende farkındayım şiirde farkında

imla da baştan göçük zaten

zaten ben şair de değilim

şiirim bir şeye benzesin

aptal bir aşık erkek şiiri bu netice de

şiirlerden nefret ediyorum

şairlerden de

hep hüzünlendirir beni

hep hüzünlü anlarda aklıma gelir

hep hüzünlü olanları bana denk gelir

yirmi yedi yaşıma bastım

şimdiye kadar yirmiyedi dolarlık birikimim yok

sevdiklerim oldu

hiç sevgilim olmadı

umutlarım vardı beklentilerim

hiç biri gerçek olmadı

ama hiç bukadar da uzaklaşmamıştı  benden

şimdi öyle bir yere gittilerki

uzaklığını neye benzetsem

bu yazı asla save olmayacak

yazı yazı yası

yas mı tutmalıyım

depresyonda mıyım

yanlız mıyım

kalabalıklar arsında yanlızlık

ne saçma

ama var öyle birşey 

bak senden çıktık yola 

ama durum genellemeye dönüştü

genel olarak 

şu anda nerdesiniz

ne yapıyorsunuz

kiminlesiniz

dinlediğim radyodan sıkıldım hep aynı parçalar 

arada çok sevdiklerim var

edith piaf çalıyor şuan da mesala

her dinlediğim de bu kadını

bombardıma uğramış gibi hissediyorum kendini

san üzerimde akbabalar gibi b/52 ler dolaşıyor

zagreb radyosunda lily marlen   çalmadığı bir zamanda 

doğdum ben

kabul

hem nasıl kabul etmeyeyim ki

pasarofçayı dayasan kabul edeceğim

barutum ıslandı çünkü

tüfeğim regl oldu

imla kuralları sizden tiksiniyorum

embesil lise hocamı hatırlatıyorsunuz bana

hieoroglifi yeğlerdim alfabelere

direk konuya girmiyorlar

nesneler değil imgelerle konuşuyorlar

kiminle konuşuyorsun şimdi

burada gök gürüldüyor

telefonum açık olmaz ama

senden mesaj bekliyor

hayatında bir yanlış numara

bir arkadaşa bakıp çıkacam kadar değerim kalmadı

biliyorum

en kötüsü bence de öyle

seninleyken

roma imparatoru bendim

tüm çocukluk kahramanlarım olmuştum yanında

şimdi bir çiko bir java olunacak bir hikayem bile yok

neredesin

şimdi

yarın

ne düşünüyorsun', 'ne yapıyorsun bilmiyorum neredesin kimlerlesin şu anda  ne zaman paslanır yürek acısı ne zaman kopup düşer toprağa kim karar verir  aklından...', ARRAY['Türk Edebiyatı','Şiir','Şair Diapunctum']::text[], 8.5, '{"poet":"Şair Diapunctum","poet_slug":"sair-diapunctum","theme":"Türk Şiiri","is_hero":false,"total_lines":119,"source_url":"https://www.antoloji.com/siirlerden-nefret-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Vardın', 'sen-vardin-turhan-oguzbas-jh1j7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oysa ben

Roman böyle bitsin istemiyordum

Ne rüzgarlar gönlümüzce esti

Ne ben gitme diyebildim sana

Bir it tarafım vardı belki kahreden

Bir karanlık tarafım sevgiden yana...

Eskiden gecelerim kırık döküktü

Sen yoksun diye

Şarkılar hep yarım kalırdı dudaklarımda

Biri çıkıp ismini söylese deli olurdum

Şimdi ayrılık şarkılarını sever olduk

Oysa ben

Roman böyle bitsin istemiyordum.', 'Oysa ben Roman böyle bitsin istemiyordum Ne rüzgarlar gönlümüzce esti Ne ben gitme diyebildim sana Bir it tarafım vardı belki kahreden Bir k...', ARRAY['Türk Edebiyatı','Şiir','Turhan Oğuzbaş']::text[], 8.5, '{"poet":"Turhan Oğuzbaş","poet_slug":"turhan-oguzbas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-vardin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-tuncay-cakmak-2c3u6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevsim yaz. 

Kırık kalem sende yaz. 

kanıma baktım 

tenim bir kıymığa yenik 

canım bir kurşuna 

düşlerim takılı 

bir asil kuşun kanadına 

sevdim ya kalbden sevdim 

..., sevdim 

lakin bilsin ki birileri 

inadına.., 

İNADINA SEVDALI BU KALB BEŞİKTAŞINA. 

.........................21-05-2002 

.........................', 'Mevsim yaz.  Kırık kalem sende yaz.  kanıma baktım  tenim bir kıymığa yenik  canım bir kurşuna  düşlerim takılı  bir asil kuşun kanadına  se...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Çakmak']::text[], 8.5, '{"poet":"Tuncay Çakmak","poet_slug":"tuncay-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yaz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğütülmeseydi Ayrılık', 'ogutulmeseydi-ayrilik-mustafa-ozke-6r6y0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kum tanelerinin

denize ulaşma vakti...

başlıyor

emzikli kadınların

süt dolu memesinin sancısı...

bir kasık ağrısıdır vuruyor başa

kırılıyor yeldeğirmeninin kanadı

kumlar kavruluyor çölde

deniz çok uzakta

yok gibi kaderde kavuşmak

kırılmasaydı keşke

yeldeğirmeninin kanadı

rüzgar savursaydı sahile

öğütülmeseydi ayrılık', 'kum tanelerinin denize ulaşma vakti... başlıyor emzikli kadınların süt dolu memesinin sancısı... bir kasık ağrısıdır vuruyor başa kırılıyor ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ogutulmeseydi-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyor musun?', 'seviyor-musun-mehmet-ali-cibikli-mpuey', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yokluğun içime, yıkıldı kaldı, 

Bak yine sensizim, anlıyor musun? 

Gözyaşım kalbime, çakıldı kaldı, 

Sen de benim gibi, ağlıyor musun? 

Bir veda busesi, yeter mi sandın? 

Böyle büyük bir aşk, biter mi sandın? 

Sevgin yüreğimden, gider mi sandın? 

Sensiz yaşayamam, biliyor musun? 

Sensizlik içimde, kapanmaz yara, 

Sen yoksan yanımda, düşmüşüm dara, 

Benim gibi yalnız, kaldığın sıra, 

İçin kan ağlarken, gülüyor musun? 

Sen nerelerdesin, ben nerelerde? 

Sen düşürdün beni, böyle bir derde, 

Benden uzaklarda, olduğun yerde, 

Bana mutluluklar, diliyor musun? 

Senden ayrı bana, mutluluk haram, 

Sen yetersin bana, olmasa param, 

Sen benim olmazsan, kapanmaz yaram, 

Sen beni, ben gibi, seviyor musun? 

                     10.07.2002', 'Yokluğun içime, yıkıldı kaldı,  Bak yine sensizim, anlıyor musun?  Gözyaşım kalbime, çakıldı kaldı,  Sen de benim gibi, ağlıyor musun?  Bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seviyor-musun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felekten Bir Gece', 'felekten-bir-gece-mahmut-bingul-5vfk0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ben uyanığım bu şehirde

Bir de sokak lambasının ışığı

Onu koluma taktım

Sokaklarda serseriyiz

Sarhoşuz

Işıkla içtik bu gece

(uç)  tuk bu gece! 

Gecenin sessizliğine küfrettik

Karanlığa tükürdük

Sokaklarda, 

parmaklıkların 

           karanlığa gömülmüş ışıklarını açtık

Şehri uyandırdık

Aydın(lan)  dık bu gece', 'Bir ben uyanığım bu şehirde Bir de sokak lambasının ışığı Onu koluma taktım Sokaklarda serseriyiz Sarhoşuz Işıkla içtik bu gece (uç)  tuk bu...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/felekten-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Özlem', 'sevgiye-ozlem-mahmut-bingul-dggpi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aniden yüreğin hafifler, 

          bir boşluk doğar içinde

          Önce ufaktan bir sancıyla başlar, 

          sonra bütün vücuduna yayılır ateşi.

          Bir hoş olursun, 

          bir insanı kucaklamak, 

                         bağrına basmak istersin, 

          onu kollarının arasına almak istersin.

          İşte o zaman, 

                          yüreğinin sevgiye açlığını hissedersin.

                                                         Ağustos  2000

                                                             Ümraniye', 'Aniden yüreğin hafifler,            bir boşluk doğar içinde           Önce ufaktan bir sancıyla başlar,            sonra bütün vücuduna yayı...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgiye-ozlem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzlenim', 'i-zlenim-mahmut-bingul-rrqrh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yasak bir araziye girdim 

Korka korka! 

Köyümdü! 

Ağaçlar geleceğimi duymuştu

Gelinliklerini giymişlerdi

Tomurcuklarda 

açmanın mücadelesi vardı 

Kuşlarda 

Yuva yapmanın hevesi

Bir şeyler eksikti bu köyde! 

Okul bahçesinde 

oynayan çocukların sesi

Sağır değildim! 

Sırtında su bidonlarıyla 

yokuşu tırmanan kadınları aradım

Kör değildim! 

Çeşmede 

birbirlerinin kafasına 

	su bidonlarını geçiren kadınlar

Neredeydiler! 

Ya sürülerin 

arkasından yükselen toz bulutları! ...

			Nisan 1995 / Ömerli', 'Yasak bir araziye girdim  Korka korka!  Köyümdü!  Ağaçlar geleceğimi duymuştu Gelinliklerini giymişlerdi Tomurcuklarda  açmanın mücadelesi v...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/izlenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancılar Sensiz Gelir', 'sancilar-sensiz-gelir-hakan-sengun-npzlq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluğunda gelir sancılar.

Kırık dökük sandallarla, 

limana girerler senin ardından.

Henüz havada elim

yaş kurumamış yanağımdan

halay çeke çeke mutluluktan

ard arda inerler sandallardan…..

Ne biçim kısmet bu

Bu kader benim değil….

Ne zaman gelse sancılar

Hep uzakta olursun, 

Yada yanımda değil.

Bile bile sancılar

Hep o yokken gelir.

Canım çok yanar 

Canım çok acır 

En çok acıtansa  bunu sevgili bilir

Kimse tanımaz beni, burda kimse yar değil

yar öpüp okşamazsa

Sancılar onsuz gelir.', 'Yokluğunda gelir sancılar. Kırık dökük sandallarla,  limana girerler senin ardından. Henüz havada elim yaş kurumamış yanağımdan halay çeke ç...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sancilar-sensiz-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem, Seni Çok Özledim', 'birtanem-seni-cok-ozledim-sair-birtanem-eo6oo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kulaklarımda sesin

Kalbimde hasretin

Dön artık nerdesin

Birtanem seni çok özledim.

Biliyorum çok uzaklardasın

Denizle, kelebeğinle, aşk böceğinlesin

Özleminle de benim kalbimdesin

Birtanem seni çok özledim.

Düşüncemde, ruhumda, beynimdesin

Geçmiyor zaman artık dönmelisin

Senin için ölen bu adamıda düşünmelisin

Birtanem seni çok özledim.

09/07/2002', 'Kulaklarımda sesin Kalbimde hasretin Dön artık nerdesin Birtanem seni çok özledim. Biliyorum çok uzaklardasın Denizle, kelebeğinle, aşk böce...', ARRAY['Türk Edebiyatı','Şiir','Şair Birtanem']::text[], 8.5, '{"poet":"Şair Birtanem","poet_slug":"sair-birtanem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birtanem-seni-cok-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zoraki Sevdaların Dramı', 'zoraki-sevdalarin-drami-yildiray-guney-txdt2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '....ve sende bu dünyanın ortaksın kaderine, 

yüreğinde yangınlar içine düşeceksin.

çıkamadan bir kalbin en kutsal seferine

çığırtkan sevdaların doğurduğu bebeksin, 

ve kim bilir ne zaman, nasıl büyüyeceksin....

Titriyor gözlerinde yalnızlığın çığlığı, 

temkinsiz o gözlerden yaş olup düşeceksin.

güneşin ötesinde görmeden karanlığı

zoraki sevdaların büyüttüğü bebeksin, 

...ve kim bilir ne zaman aşkı öğreneceksin...

Yükselen tüm değerler harcandıkça ilgiye, 

unutmaki dünya da tek başınasın, teksin.

gül kokulu yüreğin yanıyorsa sevgiye

atılgan cesaretin ağlattığı bebeksin, 

...ve kim bilir ne zaman, nerede güleceksin...', '....ve sende bu dünyanın ortaksın kaderine,  yüreğinde yangınlar içine düşeceksin. çıkamadan bir kalbin en kutsal seferine çığırtkan sevdala...', ARRAY['Türk Edebiyatı','Şiir','Yıldıray Güney']::text[], 8.5, '{"poet":"Yıldıray Güney","poet_slug":"yildiray-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zoraki-sevdalarin-drami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara Akşamı', 'ankara-aksami-erdem-ozbek-jj97t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sana bu karanlık akşamdan sesleniyorum

ankara sensiz bomboş, anlamsız

yanıp sönen ışıklar, ansızın görünen binalar

bir korku var içimde sana dair

belki özlem, belki yalnızlık, belki de aşk

esen bu tatlı rüzgarla birleşiyor ruhum

ne varsa senle ilgili herşey aklımda

uzaksın bana çok uzak

çaresizce bekliyorum gelecek akşamı

ama düşündükçe üzülüyorum

tam sonu gelmişken gecenin

yine seninle uyanıyorum

bitmesinden çok başlamasın istiyorum

bu sensiz ankara akşamı', 'sana bu karanlık akşamdan sesleniyorum ankara sensiz bomboş, anlamsız yanıp sönen ışıklar, ansızın görünen binalar bir korku var içimde sana...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özbek']::text[], 8.5, '{"poet":"Erdem Özbek","poet_slug":"erdem-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ankara-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Edebi Bir Tartışma', 'edebi-bir-tartisma-charles-bukowski-hwq9u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Markov''un iddiasına göre

ruhunu bıçaklamaya çalışıyormuşum

ama ben onun karısını tercih ederdim.

ayaklarımı kahve masasının üzerine koyarım

ve o da der ki, 

ayaklarını kahve masasının üzerine koymana

pek aldırmıyorum

ama bacakları sallanıyor

her an zavallı şey

parçalara ayrılabilir.

ayaklarımı masadan çekmem

ama hala onun karısını tercih ederim.

Markov der ki, bir hendek kazıcısını

eğlendirmeyi tercih ederdim veya bir

gazete satıcısını çünkü bu insanlar

hiç olmazsa nezaket kurallarına uyacak kadar nazik olurlar

Rimbaud ile fare zehiri arasındaki

farkı bilmeseler de.

boş bira tenekem

yere yuvarlanır.

''ölmem gerekmesi hiç mi hiç

canımı sıkmıyor, '' der Markov, 

''bu oyundaki rolüm yaşayabildiğim

kadar iyi yaşamam gerektiğidir.''

yanımdan geçerken karısını yakalarım

elindeki bira göbeğime yaslanır, 

dizleri ve göğüsleri çok güzeldir

ve onu öperim.

''yaşlı olmak pek o kadar kötü değil, '' der, 

ortalığa bir sakinlik çöker ama

önemli olan şudur: 

Sakinlikle ölümü birbirinden ayrı tutmak için: 

asla yaşlı olduğun için gençliğe

aşağılayıcı bir şekilde bakma, 

tecrübeli olduğun için yaşlılığa

asla bilgelik olarak bakma. bir

insan hem ahmak hem de yaşlı olabilir --

böyle birçok insan vardır, bir insan

hem genç hem de bilge olabilir --

çok az insan böyledir. bir insan --

Tanrı aşkı için diye figan ettim, 

''kes sesini! ''

gidip bastonunu aldı ve 

dışarı çıktı.

''onun hislerini incittin'' dedi karısı

''senin büyük bir şair olduğunu sanıyor.''

''bana göre o fazla kurnaz'' dedim

''biraz fazla bilge.''

göğüslerinden birini dışarı çıkarttım

kokunç büyük

güzel

birşeydi.', 'Markov''un iddiasına göre ruhunu bıçaklamaya çalışıyormuşum ama ben onun karısını tercih ederdim. ayaklarımı kahve masasının üzerine koyarım ...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/edebi-bir-tartisma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopsun Dilim', 'kopsun-dilim-salih-ozalasan-2sp7r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni kimse yakmamıştı böyle

Yüreğimin orta yerinden

Ağlamamıştım hiç kimsenin

Etkilenipte böyle sözünden

Yıkılmamıştım hiç bukadar

Kahrolmamıştım söylenen acı sözlere

Yazık hemde çok yazık

Hakedecek ne yapmıştımki bu sözlere

Sevmek cok güzel duygu ve kelime

Sevgiyi yaşamak gerek her gönülde

Anladım meğerse zormuş bu devirde

Kopsun dilim birdaha sevgi olursa sözümde

(10-07-2002 Saat 12.00', 'Beni kimse yakmamıştı böyle Yüreğimin orta yerinden Ağlamamıştım hiç kimsenin Etkilenipte böyle sözünden Yıkılmamıştım hiç bukadar Kahrolmam...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kopsun-dilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşksız Yaşayacağım', 'asksiz-yasayacagim-salih-ozalasan-fb2ip', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu akşam geçmişimi yaşıyorum

Geleceğimi yırtıp attım sayfalardan

Masamda bir şişe sinekli şarap

Teybimde eski bir kaset Gencebay''dan

Odamda koyu bir duman

Bir nefes daha çektim ucuz sigaramdan

Gencebay kaderimin oyunu bu diyorya

Birkaç damla yaş süzülür gözlerimden

Boşalmış şişeleri sayıyorum

Hayret hala niye sarhoş olmamışım

Tam köşede sana ait bir bardak

Boş duruyor içine şarap koymamışım

Koysam onuda ben içeceğim biliyorum

Yeni bir şişe daha şimdi tam çakır keyif

Biraz daha cesaret gelmiş yüreğime

Elimde uzun bir hançer

Yüreğimi sökmeye hazırlanıyorum

Kararlıyım orda aşk''a dair herşeyi kazıyacağım

Artık ben bir berduş bir serseri

Az sonra hüzzam faslı başlayacak

Buğulu ses Müzeyyen abladan

Ve ben duman kaplı izbe odamda

Yemin olsunki aşk''sız yaşayacağım

(10-07-2002  Saat 16.00)', 'Bu akşam geçmişimi yaşıyorum Geleceğimi yırtıp attım sayfalardan Masamda bir şişe sinekli şarap Teybimde eski bir kaset Gencebay''dan Odamda ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asksiz-yasayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daim', 'daim-ahmet-aykol-fi2cy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Suskundum, susmak istemediğim halde

Karar veremem ne konuşmam gerektiğine

Karnım açtı, başım bulanık

Kalbim senle doluydu, suratım asık

Seni gözlerdi gözlerim kapı hep aralık

Kaybettirir hafızamdan kelimeleri gerginlik

Ruhumu acıtır hep, daim sendelik

Tekrar dileyemem senden birliktelik

Ama anlarsın bilirim sen beni 

Ne şiddetlidir bilsen sensizliğin usancı

Bilirsin hala sendeyim ama açmassın kapıyı', 'Suskundum, susmak istemediğim halde Karar veremem ne konuşmam gerektiğine Karnım açtı, başım bulanık Kalbim senle doluydu, suratım asık Seni...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aykol']::text[], 8.5, '{"poet":"Ahmet Aykol","poet_slug":"ahmet-aykol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/daim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Olaydım', 'tas-olaydim-salih-ozalasan-gltdc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün anladımki ben

Taş olmak için taşı sevmeliymişim

Toprağı sevmeliymişim 

Biran önce koynunda yatmak için

Kör olmalıymışım

İhaneti görmemek

Sağır olmalıymışım

Kötü söz duymamak

Kumarbaz olmalıymışım

Dönen oyunları anlamak için

Zalim olmalıymışım

İnsanı üzünce mutlu olan

Katil olmalıymışım

Sevgi dolu yüreğe kurşun sıkan

Yada aptal olmalıymışım

Herşeye gülüp geçen

Oysa ben bir insanım

Topraktan yaradılmış seven bir insan

Yüreğinde sevgi şevkat

Kötülüğe hiçbirzaman yer olmayan

İnsanları karşılıksız sevebilen

Ağlayanla ağlayıp

Gülenle mutlu olabilen

Gönlünde herkese yer verebilen

Topraktan bir can, seven bir insan

Geç olduya sonunda anladım

Yürekten sevmenin yanlış olduğunu

Sevmek denince ya önüne ya sonuna

Mutlaka bir aşkın konduğunu

Oysa ben insanları aşk için değil

Önce insan oldukları için sevmiştim

Bana bir el verene

Ben iki elimi birden vermiştim

Kırılsaydı keşke elim uzatmaz olaydım

Kör olsaydı gözüm keşke

Bunları görmez olaydım

Sağır dilsiz olup keşke hep susaydım

Tanrım neden ben bir insanım? ? ? ? ..

Keşke ıssız bir tepede taş olaydım

Böyle üzülüp kahrolup ağlamaktansa

Razıyım keşke hiç doğmasaydım

Yaşamasaydım bunları

Yüreğimle kavga etmeseydim

Çok pişmanım çok

Keşke insanları sevmeseydim

(10-07-2002 Saat 11.00)', 'Bugün anladımki ben Taş olmak için taşı sevmeliymişim Toprağı sevmeliymişim  Biran önce koynunda yatmak için Kör olmalıymışım İhaneti görmem...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/tas-olaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzlar Parkı', 'umutsuzlar-parki-edip-cansever-chykd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I

Biliyorsunuz parkların

Sizi çağıran tarafları

İnsanın gizli, karanlık köşeleriyle oranlı

Orada saklanıyor onlar

Çünkü her türlü saklanıyorlar orada

Bir yağmur öncesinin loş sokaklarıyla

Dağınık mavisiyle gözlerinin

Sevgi vermez kadın uçlarıyla

Korkuya, sadece korkuya sığınmış olarak

Eskimiş, kurtlanmış ikonlarıyla kiliselerinin

Yalvaran bakışlarıyla - nasıl da sevimsiz -

En kötüsü, belki de en kötüsü

Bir duygu açlığıyla soluyarak

Parklara yerleşiyorlar, parkların

Onları çağıran köşelerine

Bir karıncayı selamlıyorlar, besili, siyah

Bacak aralarından

Çömelmiş, öyle sakin

Selamlıyorlar

"Günaydın" diyorlar atılmış bir kâğıt parçasına

Kuleler yapıyorlar ayak parmaklarından

Birinci katta bir kibrit çöpü oturuyor

Acılar alıp veriyor dünyadan

Dillerini gösteriyorlar, dizkapaklarını

Bir sıkıntı şiiri gibi

Sıkıntı

İşte

Tam orada duruyorlar.

II

Bu kimin duruşu, bu sizin en gülmediğiniz saatlerde

Her cümlede iki tek göz, bu kimin

Ya da kim korkuttu bu kadar sizi

Bu nasıl sevişmek, üstelik bu kadar hızlı

Ya da tam tersine

Boş vermek öperken, severken boş vermek sevmelere

Sulardan ürpermek gibi dokununca,

Ya da ben kimi sarmışım böyle kollarımla

Kime söz vermişim, biraz da unutmak gibi

Denir mi, ama hiç denir mi, iş edinmişim ben

İş edinmişim öyle kimsesizliği

Kendimi saymazsam - hem niye sayacakmışım kendimi -

Çünkü herkese bağlı, çünkü bir yığın ölüden gelen kendimi

Konuşmak? konuşuyorum, alışmak? evet alışıyorum da

Süresiz, dıştan ve yaşamsız resimler gibi.

Ne çıkar sanki sardıysam sizi kollarımla

Unutmak, belki de unutmak olsun diye mi? 

Onu da tatmak gibi

