INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Borcu', 'vatan-borcu-ceyhun-yilmaz-o5n71', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vatan borcunu ödemeye gelmişti

Vatanın hiç bilmediği toprağına

Yeşil kıyafetler içinde, elinde kırmızı elma şekerinin eksikliği...

kırmızı yanaklarında

Yaklaştım yanına

Ne isterse verecektim

Belli, garibandı biraz yüreği

Dedim ki söyle, elim avuçlarında

Tuttum...bıraktım ellerini

Elimi cebime attım

Ne kadar param varsa o an verebilirdim ona

Söyledim...canı birşey çekmiş olabilirdi

Söyle dedim ne istersen...

Dile benden ne dilersen

İstediğini veremezdim

ANNEMİ BABAMI ÇOK ÖZLEDİM! ! 

19.06.02 Bilecik', 'Vatan borcunu ödemeye gelmişti Vatanın hiç bilmediği toprağına Yeşil kıyafetler içinde, elinde kırmızı elma şekerinin eksikliği... kırmızı y...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vatan-borcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme', 'gelme-ceyhun-yilmaz-6adkp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gidiyorum işte, 

bak ne gelmeyişin öksüz ne de yokluğun

gidiyorum işte

hep beklediğin yere

geleceğin varsa da artık gelme

sakın gelme, hiç gelme

ben sana gelene kadar sen kimseye gitme', 'gidiyorum işte,  bak ne gelmeyişin öksüz ne de yokluğun gidiyorum işte hep beklediğin yere geleceğin varsa da artık gelme sakın gelme, hiç g...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gelme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yarası', 'gece-yarasi-ceyhun-yilmaz-64yr4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağrılarım ağrıyor bu gece yarısı

Dertlerim öksüz sahibi yok.

Sensizliğimin yeri boş

Bir kez daha gömdüm, bin kez dahaöldüm

                                              bu gece yarısı

Geçmedi sensizliğim, geçmedi bu gece yarısı

Ve içimde bitmiyor bu gecenin yarası', 'Ağrılarım ağrıyor bu gece yarısı Dertlerim öksüz sahibi yok. Sensizliğimin yeri boş Bir kez daha gömdüm, bin kez dahaöldüm                  ...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gece-yarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-ceyhun-yilmaz-bwwqm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kadar mı kasvetin ey gece! 

Hadi örtsene beni

Ne o yetmiyor mu karanlıkların yoksa

Korkmuyorum artık senden gel

Gel gücün yeterse yıldızlarını üzerime ser', 'Bu kadar mı kasvetin ey gece!  Hadi örtsene beni Ne o yetmiyor mu karanlıkların yoksa Korkmuyorum artık senden gel Gel gücün yeterse yıldızl...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gece-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-ceyhun-yilmaz-6mxqx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'garipliğimden bu halim

ekmeği karpuza katık ederim

beni şimdi görürsen yerde

yanıma gelme

Günlerdir açım gözüm ''çıkma ekmek''te...', 'garipliğimden bu halim ekmeği karpuza katık ederim beni şimdi görürsen yerde yanıma gelme Günlerdir açım gözüm ''çıkma ekmek''te......', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/garip-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak İstanbul', 'islak-i-stanbul-ceyhun-yilmaz-vk531', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gittiğinden beri yalnız yanaklarımdı ıslak

Herkes bana bakardı sokaklarda

Bir gün gelirsen bu şehre...

Herkesten özür dile

Sayende yalnız yanaklarım değil

Artık İstanbul''da ıslak', 'Gittiğinden beri yalnız yanaklarımdı ıslak Herkes bana bakardı sokaklarda Bir gün gelirsen bu şehre... Herkesten özür dile Sayende yalnız ya...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/islak-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçelim', 'i-celim-ceyhun-yilmaz-qeu8r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herkesin olduğu ama kimsenin sana sen diye

                                                     bakmadığı bir yere gidelim

bin kez öp dudaklarımdan kurutma

bir daha gidelim

Ne olucaksa orda olsun, uzakta olsun...

O güneş istediği yerden doğsun gözlerine batsın

                                                             al beni gidelim...

Her gece bir yıldız seçelim

Ayılana kadar içelim', 'Herkesin olduğu ama kimsenin sana sen diye                                                      bakmadığı bir yere gidelim bin kez öp dudakl...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/icelim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözümün Nuru', 'gozumun-nuru-salih-ozalasan-btpr3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benide vurdular yüreğimin ta orta yerinden

Bende ağladım bir çok gece gizli gizli

Ah etmezdim başım dönmese sevgiden

Benimde hatıralarım çizgi çizgi

Sen yaşama benim yaşadıklarımı

Gel birkez dinle sözümü

Şöyle bir karıştır bak eski sayfalarımı

Daha fazla görmek istemem üzüldüğünü

Benim yaptığım hataları sen yapma

İnsan oğlunu Tanrı sanıp tapma

Vakit çok erken kafana takma

Görmek istiyorum artık yüzünün güldüğünü

Son pişmanlık fayda etmez çok üzülürsün

Sen yüreğini dinlersen daima küçülürsün

Daha yolun başı, aşk''a herzaman yürürsün

Anla gözümün nuru senin için üzüldüğümü

Birgün ağlamak ömür boyu yanmaktan daima iyidir

Sanma sakın hint kumaşı bulunmaz biridir

Şimdi zamanı haketmişse cezası verilir

Haydi göster bana artık büyüdüğünü

13-07-2002  Saat 10.20', 'Benide vurdular yüreğimin ta orta yerinden Bende ağladım bir çok gece gizli gizli Ah etmezdim başım dönmese sevgiden Benimde hatıralarım çiz...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gozumun-nuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-salih-ozalasan-jokbt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha çok küçüksün Bebeğim

Hayatı zamanla sende tanırsın

Şöyle bir bak etrafa gönül çiçeğim

Sevmenin mutlu olmaya yetmediğini anlarsın

Toprakta yağmura hasret mevsimler boyu

Sel olup taştığında oda yok ulup gidiyor

İyi bir uyku için geceyi bekleriz gün boyu

Sabahla doğan Güneş insana hayat veriyor

Elimizi yüzümüzü süsleriz bir ömür boyu

Oysa bedenimizi ayaklarımız taşıyor

Gece karanlık gündüz Güneş''li ama

Ancak ikisi birlikte olunca yaşanıyor

Öyle sevgililer gördümki ben

Daha ilk akşamdan boşanıyor

Hayat çok uzun Bebeğim

Ömür sevgiyle değil insanla yaşanıyor

13-07-2002 Saat   11.00', 'Daha çok küçüksün Bebeğim Hayatı zamanla sende tanırsın Şöyle bir bak etrafa gönül çiçeğim Sevmenin mutlu olmaya yetmediğini anlarsın Toprak...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bebegim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahbe Hayat', 'kahbe-hayat-abbas-aydin-029ah', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ah be hayat, 

ya ben erken dogmuşum, 

ya sen geç kalmışsın.

ne zaman bır şey yapmak istesem, 

hep dur dedin, hep bekle dedin.

bekledim yaşım 20 oldu.

ama sana yetmedi, 

yetmez.

gene bekle dedin, 

gene bekle, hep bekle.

bekledim, sırf sen dedin diye, 

sırf muradıma ereyim diye.

ne oldu; 

ne verdin ki bana, 

sonsuz bir sabırdan başka? 

ah be hayat, 

ah be hayat, 

senden alamadım muradımı, 

izin ver baride, 

ölümden alayım.

onuda çok görme bana, 

onuda bekletme, 

onuda kaçırma benden.

ah be hayat, 

senden ne gördüm ki, 

ne isteyeyim.

ne vefanı bilirim, ne vefasızlığını.

ne severim seni, 

nede nefret ederim.

kaçamam senden, 

kıyamam sana, 

sen acımasanda bana.

ah be hayat bana ne verdin  ki, 

ne istiyorsun.

gençliğim büyük bir bedel değil miydi? 

yaşlandım şimdi, 

belimde büküldü, 

kanbur felek sanki, 

sırtıma süzüldü.

son nefesimi vereceğim, 

ama sana değil.

şeytanla pazarlık ederim, 

sana yenilmem.

belki, belki ölürümde, 

bir daha asla dirilmem...', 'ah be hayat,  ya ben erken dogmuşum,  ya sen geç kalmışsın. ne zaman bır şey yapmak istesem,  hep dur dedin, hep bekle dedin. bekledim yaşım...', ARRAY['Türk Edebiyatı','Şiir','Abbas Aydın']::text[], 8.5, '{"poet":"Abbas Aydın","poet_slug":"abbas-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kahbe-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolsuz Yaya', 'yolsuz-yaya-abbas-aydin-7bkom', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'doğdum, 

başladım yürümeye.

ne  nereye gittiğimi biliyordum, 

ne de neyin bana geldiğini.

zifiri bir karanlık geceden alâ, 

mil çekmişti mavi gözlü yayaya.

artık ne deniz mavi idi, ne de gökyüzü, 

dünya boynuzuna takmıştı bir öküzü.

bir öküz ki eşşekten sıska, 

bir öküz ki yolsuz bir yaya.

gece karanlık demek, karanlık gece, 

sormaz nerden geldin, gidersin nereye? 

koşuyoruz istemeden inceden inceye, 

koşuyoruz ince bir yoldan menzile.

hedef on iki, belkide on üç, 

kim bilebilr ki? 

ilerliyor hızla zaman, 

sen yerinde dursan, duracak mı sanki? 

vurmayacak mı hedefi? 

talihin attığı ok hiç seker mi? 

sekipte hedefinden olur mu karavana, 

ah dostum kandırma kendini, 

boşuna amin deme, bu olmayacak dua.

sonumuz hazin, sonumuz belli, 

hedef vurulacak, hayat son bulacak, 

engin nehirler durulacak, 

sakin denizler köpürecek, 

dağlar ovalara, ovalar dağlara özenecek.

ama ya sekerse, ya şaşarsa hedef? 

sonra ne olur, 

sonra kim kalır, kim ölür, kim dirilir? 

sonra ne sorular sorulur, ne cevaplar bulunur? 

ve sonra...

bu olmayacak zamansız dua, 

ancak yakışır yolsuz yolcuya.', 'doğdum,  başladım yürümeye. ne  nereye gittiğimi biliyordum,  ne de neyin bana geldiğini. zifiri bir karanlık geceden alâ,  mil çekmişti mav...', ARRAY['Türk Edebiyatı','Şiir','Abbas Aydın']::text[], 8.5, '{"poet":"Abbas Aydın","poet_slug":"abbas-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yolsuz-yaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reason', 'reason-siar-kadim-vnegg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'öte zaman zamana, zamandan anlara vurur

gelecekten geçene, geçenden geçmişe

kaderin kuşları uçuşur...

zaman anlara hükmünü iletirken, 

gölgesi oluşu hisseden.

karanlık aşka, aşk aydınlığa giderken, 

aydınlanan gök dağlara düşen...

dağların doğası güneş doğuran, 

yer kamçılanırken gözyaşı toprağa yayılan.

gözyaşı toprağa çamur; zamana can, 

kuşların ayaklarına iradesi düğümlenen, 

insan...

bir melek indi göğsüne 

arşa doğru eğilmek ister gibi...

haykıran...kuşlar...an

hak olsun diye zamandan üflenen için...

geri dönüş hazırlığı öte dünyadan...

bir karadeliği anlamak, aklamak için anlaşılan...

ötedünyadan öte; zamandan ana, andan zamana

bir başka anlam...

...neydi anlam... 

yada hangi soru kalıbıydı düşüren, 

görünenine çizdiği işareti?', 'öte zaman zamana, zamandan anlara vurur gelecekten geçene, geçenden geçmişe kaderin kuşları uçuşur... zaman anlara hükmünü iletirken,  gölge...', ARRAY['Türk Edebiyatı','Şiir','Şiar Kadim']::text[], 8.5, '{"poet":"Şiar Kadim","poet_slug":"siar-kadim","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/reason-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastanede Sevda', 'hastanede-sevda-hasan-alperen-i-brahimoglu-buu50', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hastanede ''akşam oldu hüzünlendim ben yine''

Şarkısını söyleyen muzır hemşire Emine

Sana söylüyorum beni dört kulağınla dinle

Acıtmadan iğne yap ve gğraşma benim ile', 'Hastanede ''akşam oldu hüzünlendim ben yine'' Şarkısını söyleyen muzır hemşire Emine Sana söylüyorum beni dört kulağınla dinle Acıtmadan iğne ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Alperen İbrahimoğlu']::text[], 8.5, '{"poet":"Hasan Alperen İbrahimoğlu","poet_slug":"hasan-alperen-i-brahimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hastanede-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Zamanlara', 'tum-zamanlara-yoruk-ali-6lpil', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni

Anlatabilmek isterdim

Tüm zamanlara

Giderdim uzayötesine

Dönerdim

Tüm geçmiş zaman uygarlıkları

Ve ilk insana

Sen ki

Ana gibi şefkatli

Özgürlük kadar doğal

Çiçek kadar çekici

Tanyeri kadar pırıl pırıl ve aydınsın

Sen ki

Bazılarına çözülememiş bir gizem

Ya da zor bir bulmaca

Zaman zaman ölümü yaşayan

Yaşadıkça

Yaşamı yaşanılır kılan

İnsanca yaşama özlemleriyle dolu

Ve fakat onurlu

Milyonlarımdan birisin

Tüm zamanların insanı

Sana merhaba

Hoşgeldin masama ve dünyama', 'Seni Anlatabilmek isterdim Tüm zamanlara Giderdim uzayötesine Dönerdim Tüm geçmiş zaman uygarlıkları Ve ilk insana Sen ki Ana gibi şefkatli ...', ARRAY['Türk Edebiyatı','Şiir','Yörük Ali']::text[], 8.5, '{"poet":"Yörük Ali","poet_slug":"yoruk-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tum-zamanlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüntü', 'uzuntu-yoruk-ali-kngjp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saygın, onurlu, sevecen

Arabesk sevgili

Ağırım sana

Üzgünüm

Senin adına

Oysa çok iyisin

Bana ve başkalarına

Üzgünüm..', 'Saygın, onurlu, sevecen Arabesk sevgili Ağırım sana Üzgünüm Senin adına Oysa çok iyisin Bana ve başkalarına Üzgünüm.....', ARRAY['Türk Edebiyatı','Şiir','Yörük Ali']::text[], 8.5, '{"poet":"Yörük Ali","poet_slug":"yoruk-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzuntu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasım', 'kasim-yoruk-ali-ku362', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kasım ayından

Sana merhaba

Biliyorum

Orada da aylardan kasım

Ne farkeder? 

Seni anımsamak istedim

Yalnızca

Seni

Ve

Aylardan kasımı', 'Bir kasım ayından Sana merhaba Biliyorum Orada da aylardan kasım Ne farkeder?  Seni anımsamak istedim Yalnızca Seni Ve Aylardan kasımı...', ARRAY['Türk Edebiyatı','Şiir','Yörük Ali']::text[], 8.5, '{"poet":"Yörük Ali","poet_slug":"yoruk-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kasim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-yoruk-ali-uvvhf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baharda gel diyorsun

Oysa

Buralarda

Hep bahar var', 'Baharda gel diyorsun Oysa Buralarda Hep bahar var...', ARRAY['Türk Edebiyatı','Şiir','Yörük Ali']::text[], 8.5, '{"poet":"Yörük Ali","poet_slug":"yoruk-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bahar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''nın taşı', 'ankara-nin-tasi-yoruk-ali-uxlj2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ankara''nın

Taşına bak

Bak da

Yüreğini

Gör', 'Ankara''nın Taşına bak Bak da Yüreğini Gör...', ARRAY['Türk Edebiyatı','Şiir','Yörük Ali']::text[], 8.5, '{"poet":"Yörük Ali","poet_slug":"yoruk-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ankara-nin-tasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yankı', 'yanki-yoruk-ali-pflfr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesimin yankıları

Gelse de

Olduğun yerlerden

Sen, sen

Beni duyamazsın', 'Sesimin yankıları Gelse de Olduğun yerlerden Sen, sen Beni duyamazsın...', ARRAY['Türk Edebiyatı','Şiir','Yörük Ali']::text[], 8.5, '{"poet":"Yörük Ali","poet_slug":"yoruk-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yanki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Radyo', 'i-cimdeki-radyo-esra-zeynep-utl4n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir anlık sessizliğim kalmadı

yaslanacak

ne olur gelsin kapatsın

kapatsın artık

içimdeki radyoyu

kim unuttuysa açık.', 'Bir anlık sessizliğim kalmadı yaslanacak ne olur gelsin kapatsın kapatsın artık içimdeki radyoyu kim unuttuysa açık....', ARRAY['Türk Edebiyatı','Şiir','Esra Zeynep']::text[], 8.5, '{"poet":"Esra Zeynep","poet_slug":"esra-zeynep","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/icimdeki-radyo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuzruhu', 'tuzruhu-esra-zeynep-sr0ff', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dikişim tutmuyor kimseye

ancak teğelliyorum kendimi

ancak o''nun iplikleriyle

ruh değil içimdeki tuzruhu

sizi parçalayarak onu tamamlıyorum

mahkemeler kurun bana özel

suçum özrümden büyük

suçum doğaüstü sevmek.', 'Dikişim tutmuyor kimseye ancak teğelliyorum kendimi ancak o''nun iplikleriyle ruh değil içimdeki tuzruhu sizi parçalayarak onu tamamlıyorum m...', ARRAY['Türk Edebiyatı','Şiir','Esra Zeynep']::text[], 8.5, '{"poet":"Esra Zeynep","poet_slug":"esra-zeynep","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tuzruhu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Ekmek Bir Gazete', 'yarim-ekmek-bir-gazete-esra-zeynep-avqb2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün ölümler sanki evim

henüz çıkmışım apar topar

sofanın ışığı açık kalmış

yastıkta başımın izi

aynada hayalim hala

bir mektuba başlanmış

kalemin kapağı yerde

çay bardakta yarım

kendisi içmiş sigara

bütün ölümler sanki evim

yarım ekmek bir gazete

fakat kapısında bayatlıyor.', 'Bütün ölümler sanki evim henüz çıkmışım apar topar sofanın ışığı açık kalmış yastıkta başımın izi aynada hayalim hala bir mektuba başlanmış ...', ARRAY['Türk Edebiyatı','Şiir','Esra Zeynep']::text[], 8.5, '{"poet":"Esra Zeynep","poet_slug":"esra-zeynep","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yarim-ekmek-bir-gazete-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masalcı', 'masalci-i-lkiz-kucur-fe98r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kendi saçlarından asılı delikanlılar

kanlı bir bıçakla yüzüyordu morsularında ölümün

yavaş yavaş sürüldü gölgeleri kentlerden

çünkü yanlış imlasıydılar alışkanlıkların.', 'kendi saçlarından asılı delikanlılar kanlı bir bıçakla yüzüyordu morsularında ölümün yavaş yavaş sürüldü gölgeleri kentlerden çünkü yanlış i...', ARRAY['Türk Edebiyatı','Şiir','İlkiz Kucur']::text[], 8.5, '{"poet":"İlkiz Kucur","poet_slug":"i-lkiz-kucur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/masalci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harami', 'harami-i-lkiz-kucur-jvtd9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç yüzyıl öncesinden yürüdük haramileriz

birden düştü kale kapıları üzerimize

kırmızı kadınlara ulaştık ölüm demek ki

burda bekledi bizi. Kapı kapandı.', 'Kaç yüzyıl öncesinden yürüdük haramileriz birden düştü kale kapıları üzerimize kırmızı kadınlara ulaştık ölüm demek ki burda bekledi bizi. K...', ARRAY['Türk Edebiyatı','Şiir','İlkiz Kucur']::text[], 8.5, '{"poet":"İlkiz Kucur","poet_slug":"i-lkiz-kucur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/harami-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Ötesine Gizlenen', 'gecenin-otesine-gizlenen-i-lkiz-kucur-xjonx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-I-

bana en tuzak tutkularını getirmişsin, ulaşamam yollar çok ıslak

uykuları çalan bir çocuk gibi masumdum

üstelik suçluydun, şarkılar çalmıştın

garip aletleriyle gelen gezgincilerden

yine de bırakabilirmiydik rüzgarda sallanan eski fotoğrafları

-II-

suları düşün bir kez, yolları ne yakın düşer ölüme

ya da eski bir kente sür, yalınayak gelmişse unuttuğun yüzler

mutlak sarı bir çiçek bulacaklardır sulara ilişmeyen

-III-

/Oysa isa''yı biz doğurmadık mı, çarmıha da gerdik

yine de yargılanmadı bedenlerimiz cehennem ateşiyle/

-IV-

bana en uzak tutkularını getirmişsin

deniz kıyısında intiharlarla süsledik ölümü

ulaşamam', '-I- bana en tuzak tutkularını getirmişsin, ulaşamam yollar çok ıslak uykuları çalan bir çocuk gibi masumdum üstelik suçluydun, şarkılar çalm...', ARRAY['Türk Edebiyatı','Şiir','İlkiz Kucur']::text[], 8.5, '{"poet":"İlkiz Kucur","poet_slug":"i-lkiz-kucur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gecenin-otesine-gizlenen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-birhan-keskin-yp5af', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şimdi, bir de buradan baktım sana

senden kaçırdığım

kedere boğduğum anlara.

...

Beni içine al artık

seni mutsuz kılan duyguyu

kırmak istiyorum.

...

Bir yerden aşağı, 

çok aşağı düştüm

zaman: 

solgun ve gri bir koridordu

orada çok üşüdüm.', 'şimdi, bir de buradan baktım sana senden kaçırdığım kedere boğduğum anlara. ... Beni içine al artık seni mutsuz kılan duyguyu kırmak istiyor...', ARRAY['Türk Edebiyatı','Şiir','Birhan Keskin']::text[], 8.5, '{"poet":"Birhan Keskin","poet_slug":"birhan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zaman-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf Sabır', 'saf-sabir-birhan-keskin-is5b9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben, birlikte kıyıya sürüklediğimiz kayıktan

saflığımı ve sabrımı aldım tek

kalanları kumsala göm sen de

yaz boyunca

nasılsa her keder eksilir

kendini doldurarak

sardunyalarla konuşarak çoğalttım

aramızdaki ayrılığı

sayarak çoğalttığım günleri tamamladım

kirpiklerimin arasına çektiğim tülde

yağmur durdu ve şimdi kış bitiyor

oysa kimse yokmuş dışarda

içim dışıma vuruyor

sardunyalara su vermekle unutamadığımız

şeymiş aşk: 

alnından bir günaydın gibi düşürdüğün sabah, 

sağ yanımda unuttuğun keder.', 'Ben, birlikte kıyıya sürüklediğimiz kayıktan saflığımı ve sabrımı aldım tek kalanları kumsala göm sen de yaz boyunca nasılsa her keder eksil...', ARRAY['Türk Edebiyatı','Şiir','Birhan Keskin']::text[], 8.5, '{"poet":"Birhan Keskin","poet_slug":"birhan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/saf-sabir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mağara Çiçeği', 'magara-cicegi-birhan-keskin-qahlo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçağrısıyım bir mağmanın

kopmuş fırtınanın sesi

derini yok, ses gelmiyor bir kuyu.

Çiçeğiyim yaprağını yüzüne

kapatan ağlamanın

havluları topladım, 

şemsiyeyi kapattım

hadi kalk gidelim

serinledi hava, güneş söndü

iyice karanlığa döndü yüzüm

bir mağara çiçeği yürüyor içimde

içli bir bulut geçiyor üstümüzden

kalk gidelim.', 'İçağrısıyım bir mağmanın kopmuş fırtınanın sesi derini yok, ses gelmiyor bir kuyu. Çiçeğiyim yaprağını yüzüne kapatan ağlamanın havluları to...', ARRAY['Türk Edebiyatı','Şiir','Birhan Keskin']::text[], 8.5, '{"poet":"Birhan Keskin","poet_slug":"birhan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/magara-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolanlar İçin Yanıp Durma Ayini', 'kaybolanlar-i-cin-yanip-durma-ayini-birhan-keskin-kbt68', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey ölümden ve hayattan olma çocuk

Suna''yı ve denizi bildin

Şimdi bir başka soru bul kendine

bir yakamoz neden durup durup bir dubayı kovalar

gibi örneğin, 

Ölümden ve hayattan çok bahsettik

suskun, ağızsız, sözsüz

ilahi bir koronun gülümsemesini istiyorum ben

yerli yersiz

hem neden küçük bir gülümseme için

büyük espriler gerekli bize

ve neden cinnet beşinci kattayken yakalar insanı

ve bu mermer insanlar nasıl olur da

romatizmadan bahsederler? 

Ey ölümden ve hayattan olma çocuk

hüt hüt kuşunu ve gözyaşını bildin

peki, niçin bir new york bulur kendine

tatar çağrışımlı ve balkonlu kızlar

saçlarını taşırken çınaraltının serin sabahlarına

ve bir şairin yüzüne niçin kurtlar iner her akşam

durup duruken bir koridor ıssızlığına...', 'Ey ölümden ve hayattan olma çocuk Suna''yı ve denizi bildin Şimdi bir başka soru bul kendine bir yakamoz neden durup durup bir dubayı kovalar...', ARRAY['Türk Edebiyatı','Şiir','Birhan Keskin']::text[], 8.5, '{"poet":"Birhan Keskin","poet_slug":"birhan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kaybolanlar-icin-yanip-durma-ayini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesinle', 'sesinle-zeynep-uzunbay-jv4t2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'mor imgeli deli pardösümün altında

çıplağım, usulca açıyor sesin düğmelerimi

önce o öpüyor omuzlarımdan

adın kapatıyor dudaklarımı

içime eriyor gitmek

mor imgeli pardösüm düşüyor yere

çırılçıplak sarılıyor belime sesin

koşuyor koşuyor yetişemiyoruz ırmağa', 'mor imgeli deli pardösümün altında çıplağım, usulca açıyor sesin düğmelerimi önce o öpüyor omuzlarımdan adın kapatıyor dudaklarımı içime eri...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Uzunbay']::text[], 8.5, '{"poet":"Zeynep Uzunbay","poet_slug":"zeynep-uzunbay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sesinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Yazdım', 'yanlis-yazdim-zeynep-uzunbay-a70ix', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ıslak gözlerine bakıp durma harflerin

deli olurmuş sevdaların ahengi

bir ayağı öbüründen habersiz zaman

mektuplara sığınan gezgin mülteci

olacaksa kuş yaygarası olsun diyor

nasıl olsa bütün sorular hancı

sesimi çarpa çarpa yıkadım yüzümü

tefsirimi yarım bıraktım malum hikayelerin

orta boylu bir yanlış bırakıp hayata

gidecekmiş, gitsin

taze salkım olsun eski şaraba

çıplak kalsın kokusunda gömleği

yakışmıştı oysa, sayfaları akşamın

her anını giyinen yalın zamana

yazdı, derken pat kasım

evet, sıradaki dilekçi

zaten acı tüterdi ısmarlanan sevinçler

üzerlik üzgünüydü kırları çocukluğun

en kaba kahkahasını atsın hayat

şiir adını kaybetmiş her yerde

dargınım gömülen kitaplar kadar', 'ıslak gözlerine bakıp durma harflerin deli olurmuş sevdaların ahengi bir ayağı öbüründen habersiz zaman mektuplara sığınan gezgin mülteci ol...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Uzunbay']::text[], 8.5, '{"poet":"Zeynep Uzunbay","poet_slug":"zeynep-uzunbay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yanlis-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Bahar Yanımdan Geçti', 'bugun-bahar-yanimdan-gecti-cemile-cakir-osqn8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bugün bahar yanımdan geçti

küçük beyaz çiçekleri vardı, yeşilli elbisesi

gökyüzü bir bulutlu, bir maviydi

tomurcuklanan dalda ötüyordu kuş

bugün bahar yanımdan geçti

yanımdan geçti bahar, kaynatıp kanımdaki fokurdayan kazanı

yanımdan geçti bahar, üfleyip damarlarıma bir fırtına

yanımdan geçti bahar, çevirip beni bir rüzgara

yanımdan geçti bahar, bir kor bırakarak avuçlarıma

bugün bahar beyaz çiçeklerle geçti yanımdan

çiçekleri savurup durdu rüzgar

ben de savruldum, ruhum da... o çiçekler arasında

aşık oldum, döndüm çiçekli bir dala

bugün bahar ruhumdan geçti

bir kor bıraktı bana

bir de yangın yeri gibi seni', 'bugün bahar yanımdan geçti küçük beyaz çiçekleri vardı, yeşilli elbisesi gökyüzü bir bulutlu, bir maviydi tomurcuklanan dalda ötüyordu kuş b...', ARRAY['Türk Edebiyatı','Şiir','Cemile Çakır']::text[], 8.5, '{"poet":"Cemile Çakır","poet_slug":"cemile-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bugun-bahar-yanimdan-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumuzun Sığınağı Yok', 'ruhumuzun-siginagi-yok-cemile-cakir-wyowm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ruhumuzun şemsiyesi yok

nasıl korunacağız yağmurlardan? 

kaldırım taşlarını çiğneyip geçen adımlar

aşındırıyor pürtüklü yüzeyleri

inciniyor su birikintilerinde

yağmurdan kalan gecikmiş bir gülümseme

dallarda inatla direnen bir iki sararmış yaprak

yok onların da zamandan korunağı

ruhumuz gibi çırılçıplak ve zavallı

bırakmış geleceğini rüzgara

ruhumuzun sığınağı yok

nasıl korunacağız zamandan?', 'ruhumuzun şemsiyesi yok nasıl korunacağız yağmurlardan?  kaldırım taşlarını çiğneyip geçen adımlar aşındırıyor pürtüklü yüzeyleri inciniyor ...', ARRAY['Türk Edebiyatı','Şiir','Cemile Çakır']::text[], 8.5, '{"poet":"Cemile Çakır","poet_slug":"cemile-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruhumuzun-siginagi-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüntü', 'goruntu-ayhan-gulsoy-fiqcy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ekmek de gelince babayla

Sürgülensin dünyaya kapılar

Ne olur ne olmaz

İz süren var

Zamansız çalınan kapı

Yorulmaz artık hayra

Kim o? Ne istiyorlar

Öyle biri yok burda

Kimse tanımasın, bilmesin

Konuk filan da gelmesin

Silinsin kapılardan isimlikler

Ne olur ne olmaz

İz süren var', 'Ekmek de gelince babayla Sürgülensin dünyaya kapılar Ne olur ne olmaz İz süren var Zamansız çalınan kapı Yorulmaz artık hayra Kim o? Ne isti...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Gülsoy']::text[], 8.5, '{"poet":"Ayhan Gülsoy","poet_slug":"ayhan-gulsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/goruntu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkış', 'cikis-ayhan-gulsoy-9k7g3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıkışan bitkin soluk

Böyle kaç akşam

Düşüp kalır yollarda

Ayak seslerinden

İçine kapandığın sığınak

Utanırken duvarlarından

Sen oralı bile değilsin

Sıkıştığın kapandan

Sevmiyor çoluk çocuk

Sığınakları canım

Dışarda pırıl pırıl gün

Güneşe çıkalım', 'Sıkışan bitkin soluk Böyle kaç akşam Düşüp kalır yollarda Ayak seslerinden İçine kapandığın sığınak Utanırken duvarlarından Sen oralı bile d...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Gülsoy']::text[], 8.5, '{"poet":"Ayhan Gülsoy","poet_slug":"ayhan-gulsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cikis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem Uçurum Doğuracak', 'annem-ucurum-doguracak-cigdem-sezer-fyxx2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'böyle yalnız böyle iyi

bir öyküyü yeni baştan okur gibi

yeniden başlar gibi denize

ama hiç bilmediğim bir denize

yeniden başlar yeniden okur gibi

derindeki sözcükleri

bana bir kazma bana bir

bıçak. suyu ikiye bölüp boğacak

bildiğim tüm öyküleri

böyle dilsiz böyle iyi

ölsem öldüğüm bilinir, kaldım

kapılar üstüme kilitli

gövde mi tin mi öykünün kirli mendili

bana bir kazma bana bir bıçak

bendeki uçurumu rüzgara bırakacak

uçurum dedim de bir avuç kum

hiçbir rüzgara bırakamadığım

iyiyim iyiyim iyi

bir öykü gibi başı sonu belli

hayatın kırık sandalyesine

yerleştirip sözcükleri

kurguluyorum evreni

böyle yalnız böyle suskun böyle iyi

gömdüm mü bir de sözcükleri...

bana bir kazma bana bir bıçak

konuşsam annem uçurum doğuracak', 'böyle yalnız böyle iyi bir öyküyü yeni baştan okur gibi yeniden başlar gibi denize ama hiç bilmediğim bir denize yeniden başlar yeniden okur...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Sezer']::text[], 8.5, '{"poet":"Çiğdem Sezer","poet_slug":"cigdem-sezer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/annem-ucurum-doguracak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoğalmak', 'cogalmak-mevlut-ceylan-az6u5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hüznün ve yüreklerimizin terinden

gecelere öfke işlemeli

öyle sıcak sokakları kalbimin

a canım uzat ellerini

şafak oturmuş gözlerinde

ölüler kanattı düşlerini

toprak terledi ve gömütler

gözlerinde gölgesi ölümün

ölümün bittiği yerde aşk başlıyorsa

iki gözüm kan ağlasın

üstümüzdeyse yıldızlar

çoğalıyoruz

ve ne ağır vurmada kalbim

içinden çıkıyoruz bir dağın

ölümse bütündür dualarda

kanımız yörüngesinde kurşunlar

gizliden duruldu gizliden

ve sen gülüyorsun

bu zulmün ortasında nasıl', 'hüznün ve yüreklerimizin terinden gecelere öfke işlemeli öyle sıcak sokakları kalbimin a canım uzat ellerini şafak oturmuş gözlerinde ölüler...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Ceylan']::text[], 8.5, '{"poet":"Mevlüt Ceylan","poet_slug":"mevlut-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cogalmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-mevlut-ceylan-077b6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Salınan güzellere

Beyaza bürünen gazele

Destan yazsam üstlerine

Bulut solmasına

Ağıt dizeleri yaksa

Sevgili sesi

Can verse ağıta dağ

Korkuyla çarparken bedenler

Yıldırım kurutur yıldızı', 'Salınan güzellere Beyaza bürünen gazele Destan yazsam üstlerine Bulut solmasına Ağıt dizeleri yaksa Sevgili sesi Can verse ağıta dağ Korkuyl...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Ceylan']::text[], 8.5, '{"poet":"Mevlüt Ceylan","poet_slug":"mevlut-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/agit-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-mevlut-ceylan-4mtlc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akrep oyuntuları

Gibi uzun yankı

Ey derviş ey mermi bakışlısı

Kalbimin

Örtünen kuşta göz süzmesi

Ey geceleri beni çeken dağ

Soyunan ağaçlar gibi giydiren

Beni ey kalbimin kelimeleri

Birazdan ey kalbim birazdan

Dingin bir dağa dönüşürsün', 'Akrep oyuntuları Gibi uzun yankı Ey derviş ey mermi bakışlısı Kalbimin Örtünen kuşta göz süzmesi Ey geceleri beni çeken dağ Soyunan ağaçlar ...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Ceylan']::text[], 8.5, '{"poet":"Mevlüt Ceylan","poet_slug":"mevlut-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerinde Ağlayan Çocuk', 'duslerinde-aglayan-cocuk-ayhan-can-utyyv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşındırmak istiyor zamanı

Soluk bir yüz gibi camlarda

Sevdikçe mor oluyor gözleri

Bulutlara dokunsa yağmur yağacak

Bütün valsler o yokken çalıyor

Dikenli tellerden geçemiyor üstelik

Çürük bir elma kokusu var havada

Üşümese gecenin koynuna girecek

O hep yalnızdı deniz gibi

Arandığı bir şey vardı sımsıcak

Cam kırıkları kesti ellerini

Motor kaburgalarında yosunlaştı zaman

Gece düşlerinde ağladı çocuk

Hiç dinmedi sancıları uzun bir şarkı gibi

Alnına düşen bir tutam saç ve hüzün

Hala mızıka çalıyor sağır boşluğa doğru

Uzakta olmaksa kılıç balığı ve deniz', 'Aşındırmak istiyor zamanı Soluk bir yüz gibi camlarda Sevdikçe mor oluyor gözleri Bulutlara dokunsa yağmur yağacak Bütün valsler o yokken ça...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Can']::text[], 8.5, '{"poet":"Ayhan Can","poet_slug":"ayhan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/duslerinde-aglayan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-ahmet-hani-ne1qi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dediler yaz geldi.

sözlükleri varaqladım var idi

yaşayışı varaqladım yox idi

yaz bunu

yaz.

1 march  1996', 'dediler yaz geldi. sözlükleri varaqladım var idi yaşayışı varaqladım yox idi yaz bunu yaz. 1 march  1996...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yaz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta Gölgemi', 'karanlikta-golgemi-oguzkan-bolukbasi-246s2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlıkta gölgemi

Hep ağlayıp neşemi

Sabahlarda gecemi

                     Unuttum', 'Karanlıkta gölgemi Hep ağlayıp neşemi Sabahlarda gecemi                      Unuttum...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/karanlikta-golgemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçların Rengi', 'saclarin-rengi-sicilyali-kemal-iqa3n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saçları sarı benzer püsküle

Düşmüş omuzuna lüle lüle

Gözleri mavi benzer denize

Sçları beyaz eşarpta ak yaz

Seni özledim bana mektup yaz

Bizim bahçenin birinde kiraz

Sen yüzünü aç gülümse biraz

Saçları siyah yüzü gül esmer

Gözleri beni kendine çeker

Ağlıyor esmer gönlümde hançer

İki yanımızı sarmış bir çember

Saçları kumral gönlümde sen var

Aşığım sana bende sevgin var

Dudağım seni sayıklar her an

Onlardan ayrıl artık bana var', 'Saçları sarı benzer püsküle Düşmüş omuzuna lüle lüle Gözleri mavi benzer denize Sçları beyaz eşarpta ak yaz Seni özledim bana mektup yaz Biz...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/saclarin-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Terkettin', 'beni-terkettin-sicilyali-kemal-nzkmq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensizlik gönlüme şad olmuş giderim

Hasretin kalbime çökmüş çekerim

Bir daha dönemem yemin ederim

Kalbimin sahibiydin beni terkettin

Ruhumu aldın birşey demedim 

Ağıtlar yaktım fayda görmedim

Dalımdan koptun sana demedim

Kalbimin sahibiydin beni terkettin

Şiirler yazdım yaranamadım 

Feryatlar ettim başaramadım

Kararı sen verdin düşünemedim

Kalbimin sahibiydin beni terkettin

Sevmek nedir benden öğrendin 

Canın yandıkça bana söyledin

Gönlümüz biridi dara getirdin

Kalbimin sahibiydin beni terkettin', 'Sensizlik gönlüme şad olmuş giderim Hasretin kalbime çökmüş çekerim Bir daha dönemem yemin ederim Kalbimin sahibiydin beni terkettin Ruhumu ...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-terkettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekonomi Tekerlemesi', 'ekonomi-tekerlemesi-burhan-koroglu-33972', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne biliyon bana dair

Nutuk atma şair şair

Babam bir prof''tan mahir

Geliri yüz milyon lira

İktisat tasarruf diyon 

Ekonomi düzeltiyon

Yaw şiş göbek muz mu yiyom? 

Gelirim yüz milyon lira

İşi bilen kaçırıyor 

İsviçre''ye aşırıyor

Bakanla iş pişiriyor

Geliri yüz milyar lira

Taş atıp da kolu yoran

Yoktur şirketler paravan

Günde trilyon kazanan

Veriyor beş milyon lira

İnim inim iniliyor

İntihar mı etsem diyor

Bakkal vergisin veriyor

Borca kaldı yine kira

Dünya Bankası IMF

Teftişteler efe efe

Hiç durur mu TÜFE TEFE

Pula dödü garip lira

Yaptığın işe bak hele 

Teslim oluyoruz ele

Bor madenlerini bile

Satıyon bizde mi sıra? 

Sende yoksa hiç utanma

Bırak yönetsin ''Jhon Amca''

Bağımsızlığa sıçtın da

Haysiyet indi sıfıra! ..

İrtica mirtica dedin 

Elin cebimden çekmedin

Birin verdim bin istedin 

Haklısın, salağım zira', 'Ne biliyon bana dair Nutuk atma şair şair Babam bir prof''tan mahir Geliri yüz milyon lira İktisat tasarruf diyon  Ekonomi düzeltiyon Yaw şiş...', ARRAY['Türk Edebiyatı','Şiir','Burhan Köroğlu']::text[], 8.5, '{"poet":"Burhan Köroğlu","poet_slug":"burhan-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ekonomi-tekerlemesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nev-râh', 'nev-r-h-burhan-koroglu-seknm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merd ana dinür dost ki aça nev-râh

Öyle bir râh ki hem bi-misâl olsun

Hem felaha gitsün muakîb ervâh 

Hem hiç gaz yapmasun pek zülâl olsun', 'Merd ana dinür dost ki aça nev-râh Öyle bir râh ki hem bi-misâl olsun Hem felaha gitsün muakîb ervâh  Hem hiç gaz yapmasun pek zülâl olsun...', ARRAY['Türk Edebiyatı','Şiir','Burhan Köroğlu']::text[], 8.5, '{"poet":"Burhan Köroğlu","poet_slug":"burhan-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nev-rah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Bulmayan Yorgunluk', 'son-bulmayan-yorgunluk-kemal-sarialioglu-aj96h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir hasret midir, çektiğim uyuyamayışıma neden? 

Hasret olduğum sadece, 

Yıllarca önce yitirdiğim ben.

Gözlerim kapanıyor umarsızca, 

Uzun bir günün ve gecenin sonunda.

Beynimin her kıvrımı karşı, 

Gözkapaklarımın yorgunluğuna.

Ölüm korkusu mudur yoksa uyuyamayışımın sebebi? 

Kısa bir süre için dahi, 

İstemeyişinden mi uykuya direnişi?', 'Bir hasret midir, çektiğim uyuyamayışıma neden?  Hasret olduğum sadece,  Yıllarca önce yitirdiğim ben. Gözlerim kapanıyor umarsızca,  Uzun b...', ARRAY['Türk Edebiyatı','Şiir','Kemal Sarıalioğlu']::text[], 8.5, '{"poet":"Kemal Sarıalioğlu","poet_slug":"kemal-sarialioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/son-bulmayan-yorgunluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Hayallerim', 'sensiz-hayallerim-guven-aydin-y5rvv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Film şeridi gibi, 

Canlanıyor hayallerim.

Ömrüme eklenen ömür gibi, 

Canıma can hayallerim.

Koşsak birlikte kırlara, 

Gece dalsak yıldızlara, 

Sensiz geçmeye mahkum yıllara, 

Meydan okur hayallerim.

Sen benim kır çiçeğim, 

Ben seni hep seveceğim, 

İleriye dönük geleceğim, 

Bir sen birde hayallerim.

Uzanmışım dizlerinde, 

Saçlarım okşanır ellerinde, 

Aşkın mavi denizinde, 

Yüzer gider hayallerim.

Güven seni unutamaz, 

Sensiz bir hayat olamaz, 

Hiçbir şeye yaramaz, 

Sensiz hayallerim.', 'Film şeridi gibi,  Canlanıyor hayallerim. Ömrüme eklenen ömür gibi,  Canıma can hayallerim. Koşsak birlikte kırlara,  Gece dalsak yıldızlara...', ARRAY['Türk Edebiyatı','Şiir','Güven Aydın']::text[], 8.5, '{"poet":"Güven Aydın","poet_slug":"guven-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sensiz-hayallerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili! Bir Başka Güzelsin', 'sevgili-bir-baska-guzelsin-omer-hayyam-gk6et', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgili! Bir başka güzelsin bugün, 

Ay gibisin! Pırıl pırıl gülüşün, 

Güzeller yalnız bayram günleri süslenir, 

Seninse bayramları süsler gül yüzün.', 'Sevgili! Bir başka güzelsin bugün,  Ay gibisin! Pırıl pırıl gülüşün,  Güzeller yalnız bayram günleri süslenir,  Seninse bayramları süsler gü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgili-bir-baska-guzelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatım', 'hayatim-guven-aydin-66ses', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yetmişdört ekim ayında, 

Hayata adım attı Güven.

Şavşat’ın Erikli köyünde, 

Dünyayla tanıştı Güven.

Erikli ilkokulu, 

Yüzkırkyedi no’lu, 

Karnesi ortayla dolu, 

Derse hiç çalışmaz Güven.

Artvin’de yattı hastahaneye, 

Fıtık ameliyatı gaye, 

Kış günü Rabattan köye, 

Yürüyerek çıktı Güven.

Akseki; Antalya’nın ilçesi, 

Okulu İmam Hatip Lisesi, 

Çekti gurbetin çilesi, 

Yediyıl boyunca Güven.

Lise birinci sınıf, 

İlk dönemde on zayıf, 

Senin bu yaptığın ayıp, 

Utanmadınmı hiç Güven.

Erikli(Agara)   güzel kötüm, 

Gürcülere dayanır soyum, 

Kısacası ben buyum, 

Benim adım Güven.', 'Yetmişdört ekim ayında,  Hayata adım attı Güven. Şavşat’ın Erikli köyünde,  Dünyayla tanıştı Güven. Erikli ilkokulu,  Yüzkırkyedi no’lu,  Ka...', ARRAY['Türk Edebiyatı','Şiir','Güven Aydın']::text[], 8.5, '{"poet":"Güven Aydın","poet_slug":"guven-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayatim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş Gibiyim', 'sarhos-gibiyim-guven-aydin-wmob7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen benden ırağa tittin gideli, 

İçtim kederleri sarhoş gibiyim.

Bumuydu temiz aşkın bedeli, 

Çektim ağuları sarhoş gibiyim.

Bir saniye çıkmıyorsun aklımdan, 

Fazla kıymet verdim sana canımdan, 

Salkım gibi koparıldım canımdan, 

Ayak altı oldum sarhoş gibiyim.

Akibeti vardır herbir şeyin, 

Zalimin, mazlumun, kölenin, beyin, 

Aşk tarlasında sen bir mayın, 

Ayağımı bastım sarhoş gibiyim.

Alınyazı buna birşey diyemem, 

Ne kadar üzülsem sana kıyamam, 

Aşktan yana bir daha mı? gülemem, 

Çektim acıları sarhoş gibiyim.

Aşkım sürecek ilelebet, 

Düzlüğe çıkarım elbet, 

Gönlüm bedenime zülmet, 

Zülmü yaşadım sarhoş gibiyim.

Güven’in aşktan yana gülmedi yüzü, 

Seçemez oldum bayırı, düzü, 

Karıştırır oldum zemheri, güzü, 

Ayazlara kaldım sarhoş gibiyim.', 'Sen benden ırağa tittin gideli,  İçtim kederleri sarhoş gibiyim. Bumuydu temiz aşkın bedeli,  Çektim ağuları sarhoş gibiyim. Bir saniye çıkm...', ARRAY['Türk Edebiyatı','Şiir','Güven Aydın']::text[], 8.5, '{"poet":"Güven Aydın","poet_slug":"guven-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sarhos-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarimi Göreyim', 'yarimi-goreyim-guven-aydin-1igxd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ufkumu karartan kara bulutlar, 

Açılında bir güneşi göreyim.

Geleceğe ışık saçan umutlar, 

Tez gelinde bende birgün göreyim.

Moralim bozulur baktıkça şafağıma, 

Şu birçak ay bedel yirmiiki yılıma, 

İstanbul da kalan nazlı yarıma, 

Varayımda bir yüzünü göreyim.

Deli gönlüm ne hayaller kurar, 

Issız gecelerden kurtuluş umar, 

Bedenim nöbette ayazda donar, 

Gel teskere ben yarimi göreyim.

Neden? .. Her zaman sevenler ağlar, 

Vatan borcu elimi kolumu bağlar, 

Aramıza giren yüce dağlar, 

Yol verinde ben yarimi göreyim.

Çiçekler açar ilkbaharda, 

Gönül kara sevdalarda, 

Ömrüm geçiyor yollarda, 

Bitin yollar ben yarimi göreyim.

Güven dizeleri askerde yazdı, 

Zaman beş-yedi nöbet saati, 

Uyanığım seher vakti, 

Seher yeli ben yarimi göreyim.', 'Ufkumu karartan kara bulutlar,  Açılında bir güneşi göreyim. Geleceğe ışık saçan umutlar,  Tez gelinde bende birgün göreyim. Moralim bozulur...', ARRAY['Türk Edebiyatı','Şiir','Güven Aydın']::text[], 8.5, '{"poet":"Güven Aydın","poet_slug":"guven-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yarimi-goreyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizi Sormalı', 'sizi-sormali-guven-aydin-e7q5w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok değerli evin fertleri, 

Oğlunuz; Destek kıtaları muhafız eri, 

Her yanımı sardı hasret çemberi, 

Ben burda iyiyim sizi sormalı? 

Burası başkent Ankara, 

Soğuğu kuru, kışıysa kara, 

Nasıl çıkarız bilmem bahara, 

Şimdilik iyiyim sizi sormalı? 

Selam olsun eşe, dosta, herkese, 

Çok yakın kalıyoz burda merkeze, 

Gönül dolusu sevgilerimi sunarım size, 

Burda çok rahatım sizi sormalı? 

Ayanda okuyun bu mektubumu, 

Duyanlar öğrensinler bu yönümü, 

İnşaallah dönceğim gelecek yıldönümü, 

Ben çok iyiyim sizi sormalı? 

Yoktur fazla anlatacak birşeyim, 

Gizlim yoktur açıktadır herşeyim, 

Rahatlıktan yana dört köşeyim, 

Burda çok rahatım sizi sormalı? 

Güven mektubun sonunu bağlasın, 

Dudaklar bükülsün, gözler çağlasın, 

Yumuşak, duygusal ortam sağlasın, 

Ben çok iyiyim sizi sormalı? 

Asker mektubu dediğin böyle olmalı.', 'Çok değerli evin fertleri,  Oğlunuz; Destek kıtaları muhafız eri,  Her yanımı sardı hasret çemberi,  Ben burda iyiyim sizi sormalı?  Burası ...', ARRAY['Türk Edebiyatı','Şiir','Güven Aydın']::text[], 8.5, '{"poet":"Güven Aydın","poet_slug":"guven-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sizi-sormali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirim Allahım', 'bilirim-allahim-sicilyali-kemal-eviqs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözleri sel gibi akmış biriyim

Kulların içinde yalnız biriyim

Cehennem ateşinde yanmış biriyim

Bilirim Allahım seni bilirim

Bu günahkar kulun hiç sevilmedi

Şansı bir olsun terse dönmedi

Hiç sevap etmedi günah işledi

Bilirim Allahım seni bilirim

Dargınım Allahım cümle aleme

Düzgün bir yoldaydım düştüm kedere

Bir güneş doğmazki benim haneme

Bilirim Allahım seni bilirim

Dost bildiklerim beni yedi bittirdi

En kötü günümde yine gelmedi

Korktuğum sen idin yüzüm gülmedi

Bilirim Allahım seni bilirim', 'Gözleri sel gibi akmış biriyim Kulların içinde yalnız biriyim Cehennem ateşinde yanmış biriyim Bilirim Allahım seni bilirim Bu günahkar kulu...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilirim-allahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbe Et', 'tovbe-et-sair-ava-82g16', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arşa çıktığında

Yere eğilip bakma

Sana erişildiğinde

Sevenlerini yarı yolda koyma 

Yanlış zevke erdiğinde

Tövbe etmeyi unutma

Sevdaya tutulduğunda

Karşındaki seni sever sanma

Sen sev güzel dostum

Bunlardan şaşma ha

Dünyadır bu döner durur

Elbette bir gün bu da durur

Elbette bir gün ben ölürüm

Elbette bir gün kıyamet gelir

İşte o zaman; güzel dostum iyi dinle

Ahırette yalan söyleyemezsin

Meleklere rüşvet veremezsin

Aman dileyipte gönül yumşatamazsın

Şeytanı bile kendine dost bulamazsın

Günahını kimseye satamazsın

Cennete sevapsız

Cehenneme günahsız giremezsin

Burası senin bildiğin dünya değildir  çünkü.', 'Arşa çıktığında Yere eğilip bakma Sana erişildiğinde Sevenlerini yarı yolda koyma  Yanlış zevke erdiğinde Tövbe etmeyi unutma Sevdaya tutuld...', ARRAY['Türk Edebiyatı','Şiir','Şair Ava']::text[], 8.5, '{"poet":"Şair Ava","poet_slug":"sair-ava","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tovbe-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Chenneme Gömdüm Senin Sevgini', 'chenneme-gomdum-senin-sevgini-sicilyali-kemal-998lb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmenin günahı acı çekmekmiş

Dostu düşmanı ayırt etmezmiş

Günahım var imiş hepsi seninmiş

Cehenneme gömdüm senin sevgini

Aşıktın sevgilim sen benim ile

Dünyamı karartın sen sevgin ile

Hayatım zindana döndü senin ile

Cehenneme gömdüm senin sevgini

Bağrıma taş bastım sevmeyeceğim

Gönlüme inandım kanmayacağım

Bir daha düşersem kalkmayacağım

Cehenneme gömdüm senin sevgini

Canımdan bezdirdin kızmayacağım

Genede güzeldi anmayacağım

Seni ben unuttum avunacağım

Cehenneme gömdüm senin sevgini', 'Sevmenin günahı acı çekmekmiş Dostu düşmanı ayırt etmezmiş Günahım var imiş hepsi seninmiş Cehenneme gömdüm senin sevgini Aşıktın sevgilim s...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/chenneme-gomdum-senin-sevgini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim', 'neyleyim-sicilyali-kemal-wci3i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başımda dertlerim çoktu

Sevdalı bir yarim yoktu

Dağlarımda karlar çoktu

Neyleyim neyleyim

Dünya derdi bitmez oldu

Gözlerim hep yaşla doldu

Hayatım sarardı soldu 

Neyleyim neyleyim

Feleğin kastı banaydı

Dertleri benden yanaydı

Gözlerim hep uykudaydı

Neyleyim neyleyim

Sevdiğimden uzak kaldım 

Sevdasız biryola daldım

Kandım Allahım hep kandım

Neyleyim neyleyim', 'Başımda dertlerim çoktu Sevdalı bir yarim yoktu Dağlarımda karlar çoktu Neyleyim neyleyim Dünya derdi bitmez oldu Gözlerim hep yaşla doldu H...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neyleyim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Can Borçluyum', 'bir-can-borcluyum-sicilyali-kemal-k9pso', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayata küsmüştüm diriltin beni

Ölüme gitmiştim kurtardın beni

Canımdan bezmiştim gönderdi seni

Bir can borçluyum sen afet beni

İnsana küsmeyi benden

Hayatı sevmeyi senden

Canı cananı hepten

Bir can borçluyum sen afet beni

Kanıma girdi birisi birden

Kurtulamadım o an derdinden

Hayatım geçti onun peşinden

Bir can borçluyum sen afet beni

Maziyi aradım bana ders oldu

Geriye döndüm bana dert oldu

Doğruyu gösteren yine sen oldun

Bir can borçluyum sen afet beni', 'Hayata küsmüştüm diriltin beni Ölüme gitmiştim kurtardın beni Canımdan bezmiştim gönderdi seni Bir can borçluyum sen afet beni İnsana küsmey...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-can-borcluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görseydim Onu', 'gorseydim-onu-sicilyali-kemal-qbdc5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Romantik aşkımı bulsam yeniden

Karşıma çıksada sevsem aniden 

Kör olsun gözlerim baksam yeniden

Razıydım Allahım görseydim onu

Ben böyle kaderi haketedimki

İçimde bir his var dönecek sanki

Uçmayan özürlü bir kuşum sanki

Razıydım Allahım görseydim onu

Canımı yoluna harcayacaktım

Gül gibi koruyup saklayacaktım

Onu hep aşkımla yaşacaktım

Razıydım Allahım görseydim onu

Tabutu geliyor kollar üstünde

Gözlerim sel gibi yaşlar içinde

Alkırmızı yazma kanlar içinde

Razıydım Allahım görseydim onu', 'Romantik aşkımı bulsam yeniden Karşıma çıksada sevsem aniden  Kör olsun gözlerim baksam yeniden Razıydım Allahım görseydim onu Ben böyle kad...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gorseydim-onu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyhaneci', 'meyhaneci-serkan-akoglu-8t6i1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak meyhaneci yine ben geLdim.. 

İki Laf ederiz dedim dertLeşiriz.. 

Eskiden oLduğu gibi karşıLıkLı.. 

Bu akşam yok ama karışmak bana......

Bu akşam sarhoş oLacam meyhaneci.. 

İçim doLu yüküm ağır dertLiyim anLıyacağın.. 

SöyLe kamancıya geLsin çaLsın bıraz yanımızda.. 

FasıL geçeLim beraber eskisi gibi.....

Sen hep aynısın meyhaneci değişmedin biLiyonmu.. 

YıLLara meydan okurcasına haLa burdasın.. 

Ne zaman görsem dimdik ayakta.. 

Kim dartaLsa sıkıLsa koşar geLir yanına.....

HüzünLeri bırakaLım bu akşam içeLim.. 

İnan özLemişim gülmeyi kahkahayı unuttum açıkçası.. 

Dert etme sen yok bekLeyenim arkamda tasaLanma.. 

SıkıLdım bu akşam dört duvar arasında attım dışarı kendimi....

Zaman geçiyor Meyhaneci yıLLar bitirdi beni.. 

O kadar güçLü değiLim meydan okuyayım hayata.. 

Biz geLmisiz dünyaya çiLe dert çekmeye.. 

Bu akşam izin verde sarhoş oLayımm.....

Artık biLiyonmu ağır gelmeye başLadı hayat bana.. 

Tutmuyor ayakLarım kaLmadı derman dizLerimde. 

Dayanacak güç tutunacak daL yok.. 

Son kez bak MEYHANECİ son kez bana.. 

Kapıdan çıkıp giderken son kez bakk BANA........', 'Bak meyhaneci yine ben geLdim..  İki Laf ederiz dedim dertLeşiriz..  Eskiden oLduğu gibi karşıLıkLı..  Bu akşam yok ama karışmak bana...... ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Akoğlu']::text[], 8.5, '{"poet":"Serkan Akoğlu","poet_slug":"serkan-akoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/meyhaneci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey gidi heyyyyyyyy', 'hey-gidi-heyyyyyyyy-serkan-akoglu-zl5ne', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben kendi içimde kaybetmişim kendimi.. 

GündüzLer hüsran oLdu.. 

GeceLer ayaz, RüyaLar hep kabus.. 

İçimde bir burukLuk var nedeni beLirsiz.. 

Ben o eski ben değiLim.. 

Ben beni arıyorumm.. 

Peki ne oLdu bu hınç, bu nefret.bu kin.. 

Kime, kimLere, kendimemi, yoksa hayatamı.. 

BoşaLtmak, kusmak, siLkeLenmek..

Vakit çok geç oLmadan..

YoruLdum, sıkıLdım artık soruLardan suaLLerden! ! ! ! 

Amansız esen bir rüzgarın esaretindeyim.. 

Her yanım virann.. 

Girdaba kapıLdım  boşuna çırpınışLar.. 

Geçen her saat, her dakika bakmaktayım ben.. 

Sararmış benzim, yorgun gözLer umutsuz bakışLar.. 

NefretLe doLmuş kaLbimm.. 

Kendimi tanımaz oLdum.. 

AynaLar küs bana şişeLer dost oLmuşş....', 'Ben kendi içimde kaybetmişim kendimi..  GündüzLer hüsran oLdu..  GeceLer ayaz, RüyaLar hep kabus..  İçimde bir burukLuk var nedeni beLirsiz....', ARRAY['Türk Edebiyatı','Şiir','Serkan Akoğlu']::text[], 8.5, '{"poet":"Serkan Akoğlu","poet_slug":"serkan-akoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hey-gidi-heyyyyyyyy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-ugur-celik-sl2rf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bilinmezliğin sonsuzluğunda kayıpken, 

sırların yedi kat içinden geçti.

aynı topraktan ve sudan, 

ayrı beden kuşandı.

akılla yoğruldu, yolunu seçti

öğrenip bütün ilimleri 

bilgeliğe soyundu

kimi zaman güldü, çoğu zaman ağladı

acılarla kıvrandı, gözyaşına bulandı

en sonunda alıp yüce erdemleri

o zamansız mekanda, 

ulaşmak için ona; 

okyanusa bir damla gibi

düştü o gün yeryüzüne...', 'bilinmezliğin sonsuzluğunda kayıpken,  sırların yedi kat içinden geçti. aynı topraktan ve sudan,  ayrı beden kuşandı. akılla yoğruldu, yolun...', ARRAY['Türk Edebiyatı','Şiir','Uğur Çelik']::text[], 8.5, '{"poet":"Uğur Çelik","poet_slug":"ugur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/insan-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oku ömrünü', 'oku-omrunu-ugur-celik-o17sf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'olanları boşver, dününü unut

bugüne düğüm at, yarını tut.

boşluklarını doldur hayatın, 

yeni ufuklar keşfet.

sayfalarını çevir birer birer, 

oku ömrünü ve de anla...

yanlışları bulup yapıştır zihnine, 

seçerek doğrulardan oluştur öykünü, 

yalanları bırak bir kenara dursun, 

sen yalnızca gerçekleri tut.

rüzgarını al arkana sevdanın, 

yüzünü kaldır gökyüzüne, 

mutlulukla gülümse...

yağarken yağmurlar yanaklarına, 

aşklarına seslen yüksek sesle, 

yankısı ulaşınca sana; 

derin bir nefes al doyunca, 

sevgiye dair bir şarkı söyle...', 'olanları boşver, dününü unut bugüne düğüm at, yarını tut. boşluklarını doldur hayatın,  yeni ufuklar keşfet. sayfalarını çevir birer birer, ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Çelik']::text[], 8.5, '{"poet":"Uğur Çelik","poet_slug":"ugur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/oku-omrunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek bir kelime', 'tek-bir-kelime-ugur-celik-212xi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hayatta bir bağlaç aşklarımız; 

sınırsız umutları sonsuz ayrılıklara bağlayan.

her aşk bir cümle defterimizde, 

her cümle yeni bir özleyiş, 

her özlem tek bir kelime; 

yüreğimize, 

büyük harflerle ve kırmızyla kazınan...

tek bir kelime; 

çiçeklerle süslenip, 

gizli sayfalarda saklanan.

evet tek bir kelime, 

adına binlerce şiir yazılan...', 'hayatta bir bağlaç aşklarımız;  sınırsız umutları sonsuz ayrılıklara bağlayan. her aşk bir cümle defterimizde,  her cümle yeni bir özleyiş, ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Çelik']::text[], 8.5, '{"poet":"Uğur Çelik","poet_slug":"ugur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tek-bir-kelime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bırakmadı Beni Yerlere', 'kim-birakmadi-beni-yerlere-i-lhan-yuksel-fcepm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer yüzümü güldürecek bir haber duysam

Başlıyor mahkemeler ölümler beraatlar

Başımı dinlemeye nerde bir tenha bulsam

Hemencik toplanıyor koşup tüm haşeratlar

Şu ipler şaşmam bende şaşmam bağlı tersine

Hiçmi hiç gülmedim bu gün güleyim be usta

Ya karanlık ya duman inanmam tersine

Kışın kurur şu kanım buz keser ağustosta

Boğazıma doluyor geçirdiği ipleri

Insafsız felek bahtımı kara bağlamış ya

Fırsat bu fırsat deyip geri çözmüyor geri

Ağlar hep şu gözlerim bir kez ağlamış ya

Ey hayatım benim kıl ipe bağlı hayatım

Düşersin kim bilir ne cellatların ağına

Yıkılsam yere atar beni atım hey atım

Sonra sığın feleğin şerefsiz kucağına

Beni kim bırakmadı yerlere bırak sende

Dost gördüm ocağıma incir ağacı diken

İhanettir saplanan çıkmaz söylemesende

Sanmaki dert insanın yüreğinde biriken', 'Eğer yüzümü güldürecek bir haber duysam Başlıyor mahkemeler ölümler beraatlar Başımı dinlemeye nerde bir tenha bulsam Hemencik toplanıyor ko...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kim-birakmadi-beni-yerlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hatırlarım', 'seni-hatirlarim-ugur-celik-7ffqs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne zaman tutsam elimde, 

ayna gülümser bana.

ne zaman baksam aynaya, 

dünya gülümser bana.

çalar geceleri; 

bana bıraktığın ışık, 

gündüzler olur...

aşklar yansır ayrılıklara, 

sonra kırılır yayılır boşluğa, 

seni hatırlarım...

seni hatırlarım; 

kayıp düşlerim fışkırır aynamdan, 

hücuma geçer öğrettiğin duygular, 

damlalar birikir birer ikişer, 

tutamaz kirpiklerim, 

ağlarım...

isyan eder hücrelerim, 

ruhum ayaklanır.

bir mum yanar alev alev, 

gençliğim erir...', 'ne zaman tutsam elimde,  ayna gülümser bana. ne zaman baksam aynaya,  dünya gülümser bana. çalar geceleri;  bana bıraktığın ışık,  gündüzler...', ARRAY['Türk Edebiyatı','Şiir','Uğur Çelik']::text[], 8.5, '{"poet":"Uğur Çelik","poet_slug":"ugur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-hatirlarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Ülkesi', 'masal-ulkesi-ugur-celik-ke2ss', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gittiğim bir masal ülkesi var, 

bu anlattığım onun öyküsü: 

yürüdüğüm toprakta

yağmur sonrasının kokusu, 

aldığım her nefeste

aşkın büyüsü var.

karşımda dağların beyaz süsü, 

yanıbaşımda baharın

bitmeyen sevda türküsü var...

bir dere kenarında

bahçesi akasyalarla dolu

tek katlı bir evim var.

uzanınca çimenlere kulağımda; 

gürül gürül akan suların sesi, 

ağaçlarda ötüşen kuşların

son bestesi var...

nihayet yorgun düşüyor şaşkın bedenim

öylece kalıyorum, 

sonra yavaş yavaş uykuya dalıyorum.

olsada bir masal ülkesi; 

burada da hayallerin bir sonu var, 

gerçeğe dönüyorum! ...', 'gittiğim bir masal ülkesi var,  bu anlattığım onun öyküsü:  yürüdüğüm toprakta yağmur sonrasının kokusu,  aldığım her nefeste aşkın büyüsü v...', ARRAY['Türk Edebiyatı','Şiir','Uğur Çelik']::text[], 8.5, '{"poet":"Uğur Çelik","poet_slug":"ugur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/masal-ulkesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-muhammet-ferhat-firat-eindi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hicranın senin bitmez mi annem

Hep kederlisin, bitmez mi annem

Dert üstüne dert yükler derdine

Bunca dertlerin bitmez mi annem

Görmez misin saçlarında aklar

Bir nur gibi hep başında parlar

Çehren şen ama yüreğin zâr zâr

Nice inlersin, bitmez mi annem

Bastığın toprak gözüme sürme

Sözlerin derman benim derdime

Döktüğün bunca yaş acep niye

Giryân-ı diden bitmez mi annem

Gülüşümüz gülüşün olurken

Gülşende gül gibi olursun sen

Görünmez zahirinde tek diken

Kanar yüreğin, bitmez mi annem

Bak geçiyor günlerin dem be dem

Ama bitmiyor gözlerinde nem

Gözyaşını damla damla silsem

Hüzün günlerin bitmez mi annem', 'Hicranın senin bitmez mi annem Hep kederlisin, bitmez mi annem Dert üstüne dert yükler derdine Bunca dertlerin bitmez mi annem Görmez misin ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Ferhat Firat']::text[], 8.5, '{"poet":"Muhammet Ferhat Firat","poet_slug":"muhammet-ferhat-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/annem-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keklik Sürülerin İhaneti', 'keklik-surulerin-i-haneti-mahmut-bingul-fwb69', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir günden bir güne geçişti

Seni aldıkları zaman.

Anamın feryatları, 

bacımın hawârları içinde 

kör sokaklardan, 

	sürüklenerek götürülüşün.

Ve on dakika sonra! 

Karanlığı uykusundan uyandıran, 

katil seri silah sesleri

ev ev dolaşıp kapıları tırmaladı, 

yankılandı köyün içinde.

Anlamıştı anam, 

yerinde dona kaldı, 

açık kalmış gözlerinden, 

oluk oluk yaş aktı.

Tıpkı babamın, 

kırk kurşun yarasından akan kanı gibi.

Semaya bakmıştı anam, 

Yalvarırcasına, 

	isteksizce.

Nafile! ...

Yıldız çoktan kararını vermişti.

Kaydı yıldız! ...

	Mahzun mahzun 

Arkasından yanık bir iz bırakarak.

Anamın feryadından 

mevzuyu anlamışlardı ‘keklik kardeşler’

gün ışımadan 

çıkmadı kimse yuvasından, 

keklilktiler ne de olsa! 

Gün ışıdı...

Hiçbir şeyden haberi yokmuş gibi

vurdu başını taştan taşa ‘keklik kardeş’, 

			yoldu başını.

Ve nihayet gelmişti akıllarına 

babamı

	-cesedi-

		aramaya! 

Köyün erkek keklikleri 

çıkmışlardı aramaya.

Bulmuşlardı canımı...

   A 

      l

        ç

          a

             k

               l

                 a

                    r! ! ! ...

Oturtmuşlardı bir kayanın dibine

Sırtını kayaya dayamışlardı.

Geride kırk boş kovan kalmıştı! 

Kan kayada.

Beden yüzükoyun yerde

Hemen başının dibinde

kan lekeli şapka

tersine dönmüştü, isyan edercesine.

Rüzgarda dans eden 

canlıymışçasına hareket eden, 

bedeninde canlı kalmış saçlarına 

dokunmak istedim.

Uzattım elimi, 

Elimin önünden tonluk ağırlıkları 

savurur gibi, ağır ağır.

Yetişmemişti elim 

yaşamın belirtisi olan saçlarına ki, 

kulağım bir sesle çınladı! 

Hüzünlü öfkeli bir ses: 

“Dokunmayın otopsi gelecek”

Sırtüstü yatırdılar babamı, 

Sallanıyordu yukarıda eli

		bedeninden izinsiz.

Nâaşın üzerindeyken de 

inat edercesine

dimdik duruyordu eli.

Elveda der gibi! 

Son merasimiydi...

Elveda köyüm, köylüm

		eş dostlarım 

	elveda! ...

çıkarlar dünyasında 

çıkarın yaşamın tadını 

doya doya! ...

		19 Nisan 1997

                                        Ömerli', 'Bir günden bir güne geçişti Seni aldıkları zaman. Anamın feryatları,  bacımın hawârları içinde  kör sokaklardan,  	sürüklenerek götürülüşün....', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/keklik-surulerin-ihaneti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüşme Yok', 'gorusme-yok-mahmut-bingul-l9s3g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hava kapalı bugün 

Görüşme yok! 

Her taraf parmaklık

Her taraf zincirle kenetli

Her taraf karanlık

Ben kapkaranlık

O sadece (ay)  dınlık! 

Sonsuz maviliklerin ortasında

Ve yalnız 

Ve tek başına! ...

01 Eylül 2001', 'Hava kapalı bugün  Görüşme yok!  Her taraf parmaklık Her taraf zincirle kenetli Her taraf karanlık Ben kapkaranlık O sadece (ay)  dınlık!  S...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gorusme-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maktül', 'maktul-mahmut-bingul-dunxt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kim bilir! 

Belki bir gün

ensemde bir sıcaklık hissederim.

Boynumdan akacaktır al sular.

Sahibi malum

	kör bir kurşunun akıttığı

			kanın sıcaklığı.

Raporlarda maktul geçecektir adım

		ki kurşunun sahibi bir eşkıya

üniformalı, 

resmi eşkıya.

Atlaslara gömülen coğrafyada

noktalanmış olacaktır hayat maceram.

Yaşarken maceramın son dakikalarını, 

gözünün içine bakacağım kanlımın

bir gülümseme edasıyla.

Gözümün önünde 

geçmişimin sevinçleri ekrana gelecektir

ve gözkapaklarım 

kirpiklerimi taşıyamaz hale gelecek.

Yuvarlak sarı gözlerimin önü

bir kara sis kümesiyle kaplanacak.

Dizlerim ağırlığımı taşıyamaz hale gelecek.

Titreyecek diz kapaklarım. 

Yerçekimine yenileceğim

galip gelecek Newton.

Diz çökeceğim 

                  ve suya dalar gibi 

             toprağa dalacağım

Akacaktır kanım 

	    kanlımın ayaklarına

yapışacaktır çizmelerine.

Kavmim onu

kan çizmeli olarak bilecektir

ve zamanın şahitliğine 

hesap verecektir.', 'Kim bilir!  Belki bir gün ensemde bir sıcaklık hissederim. Boynumdan akacaktır al sular. Sahibi malum 	kör bir kurşunun akıttığı 			kanın sı...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/maktul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliden Habersiz Yaşlanıyorum', 'sevgiliden-habersiz-yaslaniyorum-mahmut-bingul-lzx1g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden ses geliyor dağlardan! 

Sonsuzluğun yoluna girmişim ben

Dönüşü olmayan bir yola

		-dağlara-

yüreğimin götürdüğü yere gitmişim, 

				gelemiyorum.

Sevgiliden habersiz yaşlanıyorum.

Duygum! 

Git... 

Yâre selam söyle

Kusuruma bakmasın.

Ellerinden tut

O pamuksu elleri okşa.

Beni yarime aratma

Yokluğumu hissettirme ona

Bir mektup misali 

okşa gönlünü.

Ferahlasın.

Gönlü bir tüy kadar hafiflesin

Arılar gibi 

çiçeklerin kalbine konsun.

Gönlünü okşadığın gibi

Özgürlüğe sevdalılar gibi

		dağları dolaşsın.

Umut dağlardadır

Arasın

Belki tarihi meçhul bir günde

bulur beni.

Ama umutsuz, 

sevgisiz bir beden! 

Hatırlar belki güldüğümüzü, 

			ağladığımızı.

Anılar soğuk ve karanlık

Anılar umutsuz ve karamsar

Aşk ise boş! 

                     

1997/Kızıltepe', 'Neden ses geliyor dağlardan!  Sonsuzluğun yoluna girmişim ben Dönüşü olmayan bir yola 		-dağlara- yüreğimin götürdüğü yere gitmişim,  				ge...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevgiliden-habersiz-yaslaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Halin Varsa Gör', 'ne-halin-varsa-gor-zekeriya-oz-5jhvk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözümde kalmadı, bitti değerin

Ne halin varsa gör, gör bundan böyle

Nefrete dönüştü gönlümde yerin

Ne halin varsa gör, gör bundan böyle

Değmezmişsin gülüm dert edilmeye

Aşkınla çürüyüp hergün ölmeye

İstediğin yere git sevilmeye

Ne halin varsa gör, gör bundan böyle

Sanma sensiz ömre ben kahrederim

Sanma ki aşkından çürür giderim

Sana bu hayatta bol şans dilerim

Ne halin varsa gör, gör bundan böyle

İster düşmanımla gönül eğlendir

İster başka aşık bulup dilendir

Unutma son gülen iyi gülendir

Ne halin varsa gör, gör bundan böyle

Garibim, yüzüne bakıp aldandım

Şu gönül tahtıma layıksın sandım

Nazını çekmekten bıktım usandım

Ne halin varsa gör, gör bundan böyle...', 'Gözümde kalmadı, bitti değerin Ne halin varsa gör, gör bundan böyle Nefrete dönüştü gönlümde yerin Ne halin varsa gör, gör bundan böyle Değm...', ARRAY['Türk Edebiyatı','Şiir','Zekeriya Öz']::text[], 8.5, '{"poet":"Zekeriya Öz","poet_slug":"zekeriya-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-halin-varsa-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzin Verirsen Artık Bize Taşınmak İstiyor', 'i-zin-verirsen-artik-bize-tasinmak-i-stiyor-akgun-akova-tzl8c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'alev almış yıldız sesiyle çalınca herhangi bir telefon

sanadır

durma aç

alooo''na karşılık bir tanıdık koku duyarsan, 

                                    gönül borcu var gibi

hani mummutluymuş, sevinçten dili tutulmuş gibi

anla sevdiğim

o''dur

telefon kulübesine ektiğimiz karanfil

büyümüş de, evlendik mi onu soruyor', 'alev almış yıldız sesiyle çalınca herhangi bir telefon sanadır durma aç alooo''na karşılık bir tanıdık koku duyarsan,                        ...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/izin-verirsen-artik-bize-tasinmak-istiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zevkler ve Renkler', 'zevkler-ve-renkler-akgun-akova-wz2x7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zevkler tartışılmaz

eyvallah

ama renkler deyince az durun beyler

onlar öyle bir tartışılır ki

imza: bir kör', 'zevkler tartışılmaz eyvallah ama renkler deyince az durun beyler onlar öyle bir tartışılır ki imza: bir kör...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zevkler-ve-renkler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liman', 'liman-mehmet-fatih-unal-vmjbe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben tarifi imkansız bir limanım

Hiç bir gemi yanaşmaz karasularıma

Kırmızı mendiller sallamaz rıhtımında

Kimse sevmez beni, ben yine de deli gibi severim

Yalnızlığın can sıkar ama ben hiç sıkılmam, o güzeli beklerim

Karşılıksız her aşk beni yıkar

Ben yine de yıkılmam, o güzel günleri beklerim

Mehmet Fatih Ünal', 'Ben tarifi imkansız bir limanım Hiç bir gemi yanaşmaz karasularıma Kırmızı mendiller sallamaz rıhtımında Kimse sevmez beni, ben yine de deli...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Ünal']::text[], 8.5, '{"poet":"Mehmet Fatih Ünal","poet_slug":"mehmet-fatih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/liman-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok', 'yok-yavuz-sayin-80u41', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç bahar daha geçecek

kaç yalancı yaz aradan

Değişecek tüm mevsimler

eskimiş çocuklar 

kaç bilet daha yakacak

çocukluklarından olacak

zira kimseyi beklemez zaman

bir akşam gün batıyorken

melankolik bir gurubun ardından

yalnız gözlerin kalacak

o çocuksu aşkın hatırasından

Asena''ya Ankara(2003)', 'Kaç bahar daha geçecek kaç yalancı yaz aradan Değişecek tüm mevsimler eskimiş çocuklar  kaç bilet daha yakacak çocukluklarından olacak zira ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sayın']::text[], 8.5, '{"poet":"Yavuz Sayın","poet_slug":"yavuz-sayin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yok-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredeyiz Sevgilim', 'neredeyiz-sevgilim-mehmet-fatih-unal-ju7a1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Toprağı benden, gülleri senden

Bir bahçesi var ki aşkımızın

Mevsimler boyu dolaşırız, bitmez.

Kim demiş ki zamanla gül solar? 

Aşık hiç usanırmı sevgiliden

Ne hikmettir bu Yarab, ne güzel! 

Herhalde yeryüzünde değiliz; 

Sahiden biz neredeyiz sevgilim?', 'Toprağı benden, gülleri senden Bir bahçesi var ki aşkımızın Mevsimler boyu dolaşırız, bitmez. Kim demiş ki zamanla gül solar?  Aşık hiç usan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Ünal']::text[], 8.5, '{"poet":"Mehmet Fatih Ünal","poet_slug":"mehmet-fatih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neredeyiz-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Otuz', 'uc-otuz-mehmet-fatih-unal-btsgd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir aralık akşamı sızıverdin gönlüme

Kışım yaza döndü gözlerinde

Saf ve gururlu bir hevesti belki de 

Sen harcadın bu aşkı her mutlu demde

Yazık be karagözlüm

Aşkı üç otuz paraya sattın

Mecnun’un Kerem’in Ferhat’ın ahını aldın

Bu aciz kulu hergün ağlattın

Bir dönüp te bakmadın.

Beni, seni seninle özlerken

Aşk derdime deva beklerken

Sen parayı ben sevgini isterken

Aşkımı üç otuz paraya sattın

Hani ben topraktım sen en güzel gül

O gül soldu kalbimde bunu böyle bil 

Aşkıma st çektim gururum ile

Adımı, beni unut solmuş güllerini kurut

Mehmet Fatih Ünal', 'Bir aralık akşamı sızıverdin gönlüme Kışım yaza döndü gözlerinde Saf ve gururlu bir hevesti belki de  Sen harcadın bu aşkı her mutlu demde Y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Ünal']::text[], 8.5, '{"poet":"Mehmet Fatih Ünal","poet_slug":"mehmet-fatih-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uc-otuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin ölümü', 'sairin-olumu-mustafa-ozke-cpadq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gazetede okudum

bir şair ölmüş

bir şair

şiirleriyle ıslanmış

bir şair

yetmişbirinde uslanmış

haberini yapmışlar

bir sayfaya yaslanmış

demek ki

şair de ölüyormuş

demek ki

şair ölünce de

haber oluyormuş

demek ki

yaşarken yazılan sütunlar

ölünce de doluyormuş

ne mutlu böyle şaire

yücel şimdi

yücelebildiğin kadar yücel

ne diyeyim Ece Ayhan

seni de alıp götürdü ecel', 'gazetede okudum bir şair ölmüş bir şair şiirleriyle ıslanmış bir şair yetmişbirinde uslanmış haberini yapmışlar bir sayfaya yaslanmış demek ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sairin-olumu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Kaç Kötü Adam', 'bin-kac-kotu-adam-yavuz-sayin-8f4rq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bunlar ayrık otları insanlık bahçesinin

Yeni moda piçleri Kabil silsilesinin...', 'Bunlar ayrık otları insanlık bahçesinin Yeni moda piçleri Kabil silsilesinin......', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sayın']::text[], 8.5, '{"poet":"Yavuz Sayın","poet_slug":"yavuz-sayin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bin-kac-kotu-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mukadder Nikah', 'mukadder-nikah-yavuz-sayin-fym27', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğarken nişanlandığım ölümle

 Gittiğin gün nikahımız kıyılır...

ankara(2001)   asena...', 'Doğarken nişanlandığım ölümle  Gittiğin gün nikahımız kıyılır... ankara(2001)   asena......', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sayın']::text[], 8.5, '{"poet":"Yavuz Sayın","poet_slug":"yavuz-sayin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/mukadder-nikah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Sevmekten Hiç Vazgeçmedim', 'ben-seni-sevmekten-hic-vazgecmedim-pervin-beyhan-tektel-99vpn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerimden silemedim ellerini

Gözlerimden kirpiklerini sökemedim

Yüzümden çekebilseydim yüzünü

Yanağıma düşen son damlayla

Nokta koyardım sabrıma

Koyardım koymasınada

Ben seni sevmekten hiç vazgeçmedim

Senden nefret etmek istiyorum bazen

Unutmak kolay geliyor o zaman

Ağlamak istemiyorum

Sevginde sende kalsın sevdanda

Kendi yalanıma kendim bile inanmıyorum

Avuç açmak zor gelsede 

Dilenmiycem seni senden

Uzanmam uzanmasınada 

Ben seni sevmekten hiç vazgeçmedim

Gözlerinden korkamasam

Sevmiyorum diye haykırıcam

Aynalardan korkmasam

Duvarları tırnak tırnak kazıycam

Ne kadar fotoğrafın varsa yerlere atıcam

Uyumak istiyorum geceyi gece gibi

Uyanmak sabah ile birlikte

Rüyalarımdan korkmasam

Sırf sana inat uyuyacağım

Uyurum uyumasınada

Ben seni sevmekten hiç vazgeçmedim

Buluttan korkmasam

Yağmura asılmıycam iplik iplik

Dolu vursa aldanmıycam 

Kar alev alev tutuşsada dağlarda

Yinede umursamıycam

Güneşten utanmasam 

Yıldızlara adını işlemeyeceğim ilmik ilmik

Yollardan korkmasam koşucam

Alabildiğince uzaklaşacağım senden

Sokağından bile geçmeyeceğim

Yemin ediyorum

Gölgenden utanmasam 

Camların altına saklamıycam açılımları

Gecelerden korkmam korkmasınada

Ben seni sevmekten hiç vazgeçmedim

Ellerimin titremeyeceğini bilsem

Sayfaları kapatıcam

Hatta bütün defterleri yakıcam

Dilimi bir susturabilsem

Ne şarkı dinliycem

Ne de senli türküler söylüycem

Dudaklarım inkar etmese

Parmaklarımdan korkmasam

Satır satır yazmıycam

Kırıcam seni yazan bütün kalemleri

Yüreğimden utanmasam

Şu ellerimden kavucam

Yok edicem adının harflerini

Kovarım kovmasınada

Ben seni sevmekten hiç vazgeçmedim

Seni beynimden

Seni ellerimden 

Seni gözlerimden

HİÇ 

Hiç silmedim

Hiç silmedim

HİÇ...', 'Ellerimden silemedim ellerini Gözlerimden kirpiklerini sökemedim Yüzümden çekebilseydim yüzünü Yanağıma düşen son damlayla Nokta koyardım sa...', ARRAY['Türk Edebiyatı','Şiir','Pervin Beyhan Tektel']::text[], 8.5, '{"poet":"Pervin Beyhan Tektel","poet_slug":"pervin-beyhan-tektel","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/ben-seni-sevmekten-hic-vazgecmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sessiz de olsa', 'sessiz-de-olsa-umit-calik-m5nvp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eskimişten gelen düşlerimiz 

gelecekte belki küçük bir gülücük olacak düşlerimiz..

belki hiçbir zaman yaşanmayacak olan 

önce birşeyler ekleyip sonra unutulan 

hani eşitlenen

yada anlatılamayan 

sonra uzun bir gece gibi karşımıza çıkan

''sigara dumanında ''

sonra büyük bir hiddetle söndürülecek olan', 'eskimişten gelen düşlerimiz  gelecekte belki küçük bir gülücük olacak düşlerimiz.. belki hiçbir zaman yaşanmayacak olan  önce birşeyler ekle...', ARRAY['Türk Edebiyatı','Şiir','Ümit Çalık']::text[], 8.5, '{"poet":"Ümit Çalık","poet_slug":"umit-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sessiz-de-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elena', 'elena-ozan-altinors-7enay', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geldim kapına, elena

Sarıl, 

Bir öpücük kondur yanagıma

Sonra elimi tut

Bırakma

Ayrılıktı bu sey

Olmadı

Senindim, sen benim

Unutma

Gördüm, 

Bir damla yas döküldü gözlerinden

Sakın, sakın

Aglama...', 'Geldim kapına, elena Sarıl,  Bir öpücük kondur yanagıma Sonra elimi tut Bırakma Ayrılıktı bu sey Olmadı Senindim, sen benim Unutma Gördüm,  ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Altınörs']::text[], 8.5, '{"poet":"Ozan Altınörs","poet_slug":"ozan-altinors","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/elena-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Şiir', 'son-siir-ozan-altinors-way8z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdiğim bir akşamdın sen

Mavinin keşfedilmemiş yanı

Umudumun son durağıydın

Titreyen kalemimin yazdığı, 

Son şiir

Okuduğum dizenin son satırıydın

Bir akşamüstü yalnızlığında

Seyrettiğim denizin

Kıyıya vuran dalgasıydın

Sigaramdan çektiğim nefes

Unutamadığım şarkının, 

En güzel nakaratıydın

Çaresizliğimde beklediğim ölüm

Öldüğümde unuttuğum, 

Tek anımdın

Bekliyorum...', 'Sevdiğim bir akşamdın sen Mavinin keşfedilmemiş yanı Umudumun son durağıydın Titreyen kalemimin yazdığı,  Son şiir Okuduğum dizenin son satı...', ARRAY['Türk Edebiyatı','Şiir','Ozan Altınörs']::text[], 8.5, '{"poet":"Ozan Altınörs","poet_slug":"ozan-altinors","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-siir-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sivilceli Sevdam', 'sivilceli-sevdam-ozan-altinors-4hl3c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haykırıyorum, 

Sensiz geçen günlerimin, 

Yıkıcı karanlığının ardından

Ayakta kalmayı çok isterdim oysa

Olmadı kolay değil bu

Sensiz geçen onca güne, 

Karşı koymak tek başına

Unutmak, 

Her şeyi bir anda

Yada bir kalemde silmek, 

Maziyi

Kolay olsa sen beni hatırlardın belki

Denize bakınca

İç geçirmezdim gündüzleri

Çok zamandır, 

Aynada gözlerim

Seni hayal ediyorum

Umutlarım kibrit kutusunda, 

Saklı

Gittin işte

Sivilceli sevdam

Dönersen bırakmam! ..', 'Haykırıyorum,  Sensiz geçen günlerimin,  Yıkıcı karanlığının ardından Ayakta kalmayı çok isterdim oysa Olmadı kolay değil bu Sensiz geçen on...', ARRAY['Türk Edebiyatı','Şiir','Ozan Altınörs']::text[], 8.5, '{"poet":"Ozan Altınörs","poet_slug":"ozan-altinors","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sivilceli-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamıyorum', 'aglamiyorum-pervin-beyhan-tektel-78ird', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlamıyorum, ağlamayacağım da

Zincirledim yaşlarımı, 

Gökte ne kadar yıldız varsa

Düşüyor bazıları.

Yarama tuz basıyor

Balık ağlarına dolayıp acılarımı, atıyorum denize.

Kıyıya vuruyor sancılarım

Kumsalı yakıyor dalgalar....ağlamıyorum

İki ben var içimde

Ben ve yalnızlığım

İki ben daha var, 

Susuzluğum ve suskunluğum.

Yüzlerce, binlerce ben var içimde, yüzbinlerce.

Sus konuşma, konuşamam.

Konuşursam mayın döşeli tarla, 

Dinamit tepili kaya gibi patlar, içimdeki benler, 

Buhar olup uçarlar, yağmur olup dalarlar bulutlara

Ettiğim onca yeminime rağmen biriktireceğim.

Ve bozuk para gibi harcayacağım sen ve benleri.

Ağlamıyorum, ağlıyor gibi mi geliyor sesim

Hayır! Hayır, anılar yıkanıyor gözlerimde

Yaktığın, yıktığın, yok ettiğin hatıralar sönüyor

Ağlamıyorum bee... 

Sadece gözeme SEN kaçtı

Yapıştın kirpiklerime, Canım yandı

Hırsımdan, öfkemden kanattım canımı

Seni çıkaramadım ama ağlamıyorum

İki sen var içimde, 

Gözlerin ve ellerin

İki sen daha var

Dudakların ve güneşi tutuşturan yüreğin

Uykumu yaran, Düşümü yoran

Bir çok sen var içimde.

Ağlıyor musun diye sorma

Bütün senleri yakarım yoksa, tavanlar dökülür gecelere

Yanmam pahasına yansamda ağlamıyorum

Ağlamıyorum ya! sahile indim senlere ve benlere inat

Hep oturduğumuz kaya boştu, 

Balıkçı tekneleri demirliydi, denizin ortasında.

Usulca süzüldü bir martı, 

Ağlara doladığım sancılarımı bıraktı yanıma.

Gözünü gözüme dikti dipteki yosun

Sanki...Sanki...

Yok! Yok, sorma, arama, o yok gitti, diyemedim

Cevap veremedim onca cevabın içinde

Soru soramadım onca sorunun içinde.

Ağlamıyorum bee... ağlamıyorum dedim ya

Sadece gözüme sen kaçtı

Yapıştın kirpiklerime

Canım acıyor, yanıyor içimde anılar

AĞLAMIYORUM

Sadece yıldızlar boşaldı zincirinden, 

Rüzgar esiyor, şimşek çakıyor, 

Yıldırımlar düşüyor gözbebeklerime, 

Ağlamıyorum.... ağlamıyorum

Sadece yağmur yağıyor ellerime', 'Ağlamıyorum, ağlamayacağım da Zincirledim yaşlarımı,  Gökte ne kadar yıldız varsa Düşüyor bazıları. Yarama tuz basıyor Balık ağlarına dolayı...', ARRAY['Türk Edebiyatı','Şiir','Pervin Beyhan Tektel']::text[], 8.5, '{"poet":"Pervin Beyhan Tektel","poet_slug":"pervin-beyhan-tektel","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/aglamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz', 'beyaz-lale-muldur-933nf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İz! 

Beyaz bir ülkeden çıkıp gelen ikiz! 

Lacivert çarşaflara buzdan siluetini çizen sonsuzluk

ve giz, Yaklaş! 

Beden nerede parçalandıysa kartallar oradadır. Uykunun

beyaz kum tanecikleri gibi dağıldığı bir gün şeffaf

kanatlar seni yerden kaldıracaklar.

Tuz! Buzu çözen formül, kanallardan akan kar ve pus

Beden nerede parçalandıysa kanatlar oradadır.

Dev kanatların yalayıp geçtiği tuz çölleri, 

kızgın havanın ve tuzun örttüğü, örterek çizdiği figürler, 

prizmatik kuşlar, bale, b
..........
..........', 'İz!  Beyaz bir ülkeden çıkıp gelen ikiz!  Lacivert çarşaflara buzdan siluetini çizen sonsuzluk ve giz, Yaklaş!  Beden nerede parçalandıysa k...', ARRAY['Türk Edebiyatı','Şiir','Lale Müldür']::text[], 8.5, '{"poet":"Lale Müldür","poet_slug":"lale-muldur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/beyaz-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerin Sessiz Çığlığı --UYANSANA--', 'askerin-sessiz-cigligi-uyansana-pervin-beyhan-tektel-3zxeg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyansana baba, uyansana

Bir kez yüzüme baksana, konuşsana

Uzun uzun yollardan geldim sana

Hoşgeldin oğlum, 

Hoşgeldin koçum deyip sarılsana

Teskeremi aldım geldim baba

Sen her zaman demezmiydin

Vatan borcu kutsaldır, 

Vatan borcu Anadır, Babadır, Yardır, Evlattır

Babalar yavrusunu uğurlarsa babadır.

Ben giderken sana geldim baba.

Hakkını helal et dedim........nefesin yoktu.

Ellerin diye öptüm taşına...........soğuktu.

Yüzün diye sürdüm yanağımı..........sanki buzdu

Uyan baba dedim, uyansana

Koçun askere gidiyor, uğurlasana

Alnıma dudaklarını dokundursana.

Bakmadın bile, güle güle yolun açık olsun demedin

Gülümser gibi ağlamadın. Sırtımı da okşamadın.

Ama ben ağladım baba, senin için ağladım.

Babam diye toprağına yalvardım

Bana güç ver dedim, bana kuvvet ver dedim

Bana sırt ver dedim.

Başındaki ağacına, üzerinde gezine karıncalara

Ben gelene kadar babama iyi bakın dedim.

Eğer gelemezsem, 

Sakın babama söyleyip, 

Babamı üzmeyin dedim.

Ben seni emanet ettimde gittim BABA! 

Meğer bizi sevenler senin için severmiş

Etrafımızdaki dostlar, yüzümüze senin, için gülermiş

Nedense senden sonra, bir bir çekiliverdiler

Esenlere 3 kişi gittk baba 3 kişi

Anam, Ağabeyim, ben

Davullar çalınıyordu, gençler havalarda uçuyordu.

Esenler EN BÜYÜK ASKER sesleriyle çınlıyordu

Biz hiç konuşmuyorduk, ne konuşacaktık ki

Birden, 

Çalınan davullara SUSUN  Ddiye bağırasım geldi

Bir an askere gitmekten bile vazgeçesim geldi

Kahrettim vefasız kişilere

Kahrettim hem senin, hem anamın kardeşlerine

Otobüste yer bulunmaz mı baba

Bilete bakıp yerimi bulamadım inan

Anamla, Ağabeyim arkamda kalakaldı

Sadece 2 kişi, yalnız 2 kişi, garip 2 kişi

Erkekler ağlamaz derler baba, erkekler ağlamaz.

Erkekler ağlamaz diyen, belli ki hiç ağlamadı.

Ağabeyimin ağlatışı hala gözlerimin önünde

Ya anam, anam susmuyordu baba.

Hıçkırıklarının sesi benimle askere gitti, 

Anamın gözyaşları benimle silah tuttu, 

Benimle nöbet tuttu, benimle yattı, benimle uyudu

Her telefon açışımda, 

Anamın YAVRUM deyişine yüreğim burkulurdu

18 ay bana 18 yıl gibi geldi de, 

Anama belki 180 yıl gibi uzundu.

Anam yoruldu baba

Senin yokluğunda hem biz, 

Hem de ANAM kavruldu.

Sayılı gün tez geçer derler ya! 

Birde bana sor, 

Hele şafağı geriye saymak var ya! 

Bir türlü bitmek bilmezmiş.

Ben bir tek kendimi yetim bilirdim baba

Meğer ne yetimler, 

Ne öksüzler varmış ta, ben görmezmişim.

Karakolda benim gibi tam 7 askerdik.

Hani senden severdin ya, 

Benim sesimde güzeldi

Sen isterdin ben de söylerdim

Gece olunca arkadaşlarım benden, 

Dertli dertli türküler söylerdi.

Geceler yarim oldu derdim, 

Ayhan anasının toprağını gözlerdi.

Gayrı dayanamam ben bu hasrete derdim, 

Hasan karısıyla yavrusunu özlerdi.

Hatta komutanım bir gün

''ASKER'' gece nöbetlerini azıcık yüksek sesle tut dedi.

Artık bitti baba, artık bitti.

UYANSANA

Hoş geldin oğlum, 

Hoş geldin koçum diyip kucaklasana

Sana teşekkür mektubu getirdim, okusana

Gurur duysana

Boynuma sarılıp dönüşümü kutlasana

Benim için sevinçten ağlasana.

SENİ ÇOK ÖZLEDİM BABA

Uyansana, uyan baba uyansana

SENİ ÇOK ÖZLEDİM...', 'Uyansana baba, uyansana Bir kez yüzüme baksana, konuşsana Uzun uzun yollardan geldim sana Hoşgeldin oğlum,  Hoşgeldin koçum deyip sarılsana ...', ARRAY['Türk Edebiyatı','Şiir','Pervin Beyhan Tektel']::text[], 8.5, '{"poet":"Pervin Beyhan Tektel","poet_slug":"pervin-beyhan-tektel","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/askerin-sessiz-cigligi-uyansana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affettim', 'affettim-pervin-beyhan-tektel-6v8ph', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günlerce düşündüm senden nefret etmeyi

Günlerce, haftalarca, hatta aylarca

Beklerken geri dönmeni

Çığlık çığlık haykırdı içimde isyanlar, 

Kin kusturdum gecelerime

Kan kusturdum hecelerime

Ne kadar isterdim 

SENİ SEVMİYORUM diyebilmeyi

Ne kadar isterdim düşlerimde gülebilmeyi

Yaşanmamış AŞK say diyorsun.

Diyorsun ki beni affet

Ben seni affettim ama

Sen kendini affedebildin mi sevdiğim

Ne zaman yağmur yağsa

Çılgınca ıslandığımız son ilkbahar geliyor aklıma

Ne zaman rüzgar esse, 

Yalancı yalanların doluyor kulaklarıma.

Bulutlar beyaza büründüğünde

Yüzün oturuyor karşıma

Ne kadar isterdim, 

Alaycı bakışlarını silebilmeyi

Ne kadar isterdim gözlerini öldürebilmeyi

Yaşanmamış AŞK say diyorsun.

Diyorsun ki beni affet

Ben seni affettim ama

Sen kendini affedebildin mi sevdiğim

Bizim sahilimizde, 

Bizim kır kahvemizde oturmak, 

Üzmüyor artık beni diyebilmek

Ne güzel olurdu, 

İçtiğimiz çaylar değildi, 

bardaklarımız sarhoştu.

Yarıştığımız dalgalar, elele bizim için koşmuştu.

Ne kadar isterdim, 

Kumsaldaki izini silebilmeyi

Ne kadar isterdim, denizleri söndürebilmeyi

Yaşanmamış AŞK say diyorsun.

Diyorsun ki beni affet

Ben seni affettim ama

Sen kendini affedebildin mi sevdiğim

Günlerce ağladım ağladığıma

Hesabını sordum saatlere

Ay''ın gölgesini mahkum ettim

Örtündüm üzerime.

Bak, yine bahar geldi SEVDİĞİM

Gülüşlerin güldü güllerimde

Düşlerin yüzdü gözlerimde

Zemheri yüreğin, 

Alev aldı tutuştu yüreğimde.

Ne kadar isterdim, 

Yeşillere şarkılar söyletebilmeyi

Ne kadar isterdim, baharları gülümsetebilmeyi

Yaşanmamış AŞK say diyorsun.

Diyorsun ki beni affet

Ben seni affettim ama

Sen kendini affedebildin mi sevdiğim

AFFEDE BİLDİN Mİ?', 'Günlerce düşündüm senden nefret etmeyi Günlerce, haftalarca, hatta aylarca Beklerken geri dönmeni Çığlık çığlık haykırdı içimde isyanlar,  K...', ARRAY['Türk Edebiyatı','Şiir','Pervin Beyhan Tektel']::text[], 8.5, '{"poet":"Pervin Beyhan Tektel","poet_slug":"pervin-beyhan-tektel","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/affettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rıhtıma Dönüş', 'rihtima-donus-umit-yasar-oguzcan-j3ibv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eylüldü... Bembeyaz gemi dönüyordu

Gitgide büyüyordu gövdesi, direkleri

Üşümüş, özlemli yolcular vardı güvertede

Birer deniz feneri misali gözbebekleri

Adam rıhtımdaydı, gemi yanaştı

Atıldı ipler, uzatıldı merdivenler

Ansızın karıştı birbirine

Bekletenler, bekleyenler

Çoğaldı adamın mağrur gözlerinde

Biriktirdiği acı ayların

Birden karışıverdi yüzü

Gittiği gibi dönmemişti kadın

Adam hayretle baktı merdivenlere

Böyle kavuşmak beklemek kadar zordu

Gitti kadın kolunda bir başkasıyla

Adam yine yalnızdı, adam ağlıyordu.', 'Eylüldü... Bembeyaz gemi dönüyordu Gitgide büyüyordu gövdesi, direkleri Üşümüş, özlemli yolcular vardı güvertede Birer deniz feneri misali g...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/rihtima-donus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancıyım Ben', 'yalanciyim-ben-pervin-beyhan-tektel-h8w5j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni unutmak, 

Boynumun borcu olsun.

Adını anarsam eğer, dilim kurusun.

Kalemim kör olsun, sana dair şiirler yazarsam

''YALANCI'' diye bağırıyor içimden bir ses

Yüreğim söz dinlemiyor, sözüm geçmiyor, 

Dilim unuttum dese de, 

Gözlerim yalan söylmiyor, 

Ne sen unutuluyorsun

Ne de anılar seni unutturuyor.

Artık yağmur bildiği gibi yağsın

Yılşdızları toplamayacağım gökyüzünden

İster sussun rüzgar, 

İster delice savursun, 

Sesini sileceğim pencerelerden, 

Perdeyi açmayacağım, 

Güneşle almayacağım seni içeriye

YALANCI diye bağırıyor içimden bir ses

Avuçlarını açta baksana.

Ellerim üşümüyor desem de, 

Gözlerim yalan söylemiyor

Ne sen unutuluyorsun

Ne de anılar seni unutturuyor.

Sürgüne gönderiyorum içimdeki seni, 

Anadolunun en ücra köşesine

Dahası Anadoludan da öteye, 

Kar yağdırıyorum dağlara, 

Dönüşünü engellercesine, 

Yolları kapatıyorum, 

Evlere kapı koymuyorum, 

Kilit vuruyorum tüm girişlere, 

Yalancı diye bağırıyor içimdeki bir ses

Vurgunu sen yedin, inkar etmesene

İstemiyorum dönmeni desemde, 

Gözlerim yalan söylemiyor

Ne sen unutuluyorsun

Ne de anılar seni unutturuyor.

Kavga ediyorum kendi kendimle

Sevmediğin şeyleri yapıyorum

Kahve içmiyorum

Katran karası demliyorum çayımı

Şekerde atmıyorum, 

Sana nispet edercesine.

Bahçedeki bütün gülleri buduyorum.

Yaprağını, dikenini, kökünü bile, 

YALANCI diye  bağırıyor içimden bir ses

Köşede bıraktığın sarıgül de ne

Görmemişim, gözümden kaçmış desem de

Gözlerim yalan söylemiyor, 

Ne sen unutuluyorsun

Ne de anılar seni unutturuyor.', 'Seni unutmak,  Boynumun borcu olsun. Adını anarsam eğer, dilim kurusun. Kalemim kör olsun, sana dair şiirler yazarsam ''YALANCI'' diye bağırıy...', ARRAY['Türk Edebiyatı','Şiir','Pervin Beyhan Tektel']::text[], 8.5, '{"poet":"Pervin Beyhan Tektel","poet_slug":"pervin-beyhan-tektel","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/yalanciyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Aşkım', 'benim-askim-ebru-duman-95wiz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir varmış bir yokmuş 

İşte benim aşkımın öyküsü

Var olması gereken yerde olmayan

Olmaması gereken yerde ortaya çıkan

Aşk işte arkadaşım

Sağı solu belli olmayan

Deli dolu kabına sığmayan

Aşk işte arkadaşım bir şöyle bir böyle

Ama yinede güzel yaşananlar ve yaşanacak olanlar 

08.06.1997', 'Bir varmış bir yokmuş  İşte benim aşkımın öyküsü Var olması gereken yerde olmayan Olmaması gereken yerde ortaya çıkan Aşk işte arkadaşım Sağ...', ARRAY['Türk Edebiyatı','Şiir','Ebru Duman']::text[], 8.5, '{"poet":"Ebru Duman","poet_slug":"ebru-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/benim-askim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madridcafe', 'madridcafe-kucuk-i-skender-233s0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Parmaklarında aşk bakterileri! 

hayatın cüzzamında

kendine yer bulabilmiş biri! 

yüzünü bir izci çadırı gibi kurarken

heybetli hayatların önbahçesinde

sanki biraz kestirme yok serserisi

ağzı tabanca.dudakları namlu, sözleri gece mermisi!', 'Parmaklarında aşk bakterileri!  hayatın cüzzamında kendine yer bulabilmiş biri!  yüzünü bir izci çadırı gibi kurarken heybetli hayatların ön...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/madridcafe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi Sekiz Hasan Paşa', 'yedi-sekiz-hasan-pasa-i-hsan-uncuoglu-q5mrs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akıl''da yetenek yedi hepsine Şuur bohça

Varyok hertarafın hünerin meydan olsa 

Arada şaşı çarpık döner kapılar varsa 

Biri çıkar ki karşına hele arkan yoksa 

Beyaz İpek çuval diye neler koyar sırtına. 

*** 

Bunlara ister inan ister inanma! 

Ağacı kökten sökmek kolaydır sanma 

Kuraldır akıntıya kürek çekersin 

Karşında hınzır ölçüsüz öküz keçiyse 

Kafa göz ses getirir kaç tokmakla kaç çifte. 

*** 

İster inan inanma dayak olurmu haklıya 

Kimin suyu döğülür sarı çinçin havanda 

Ters akar deryalar karar çıkar sana bana 

Hakka bakan güç akıldan noksansa açıkça 

Kuraldır akıntıya tek kürek çekilir çok akıntıya 

Kör tutarsa yoldan aranır Yedi Sekiz Hasanpasa! .', 'Akıl''da yetenek yedi hepsine Şuur bohça Varyok hertarafın hünerin meydan olsa  Arada şaşı çarpık döner kapılar varsa  Biri çıkar ki karşına ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yedi-sekiz-hasan-pasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmesini Biliyorsan Gaziantepli bestekar-şair Erol Güngör şiiri', 'sevmesini-biliyorsan-gaziantepli-bestekar-sair-erol-gungor-siiri-erol-gungor-r9z52', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbindeki sevinç bitmez

Gözündeki ışık gitmez

Değerine övgü yetmez

Sevmesini biliyorsan..

Her sofrada yerin olur

Dostlukların derin olur

İçin daha serin olur

Sevmesini biliyorsan..

Sabahları üzülmezsin

Akşamları süzülmezsin

Yanlış yolda yürümezsin

Sevmesini biliyorsan..

Tatlı dilde sözün olur

Karakterli özün olur

Melek gibi yüzün olur

Sevmesini biliyorsan..', 'Kalbindeki sevinç bitmez Gözündeki ışık gitmez Değerine övgü yetmez Sevmesini biliyorsan.. Her sofrada yerin olur Dostlukların derin olur İç...', ARRAY['Türk Edebiyatı','Şiir','Erol Güngör']::text[], 8.5, '{"poet":"Erol Güngör","poet_slug":"erol-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmesini-biliyorsan-gaziantepli-bestekar-sair-erol-gungor-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Gemi Yaptım', 'aski-gemi-yaptim-ahmet-aykol-8yu2j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkımı gemi yaptım sana yüzüyor 

Göz yaşlarımla oluşturduğum okyanustan sana geliyor

Aç bana güneşini dengem alabora oluyor

Gece fenerim rotam sensin sensiz dünya kararıyor

Fırtınaya aldırmadan ben sana yüzerim

Melekten iyi kalbine kendimi kilitledim

Gökyüzünden güzel gözlerin gece fenerim

Sen benim ışığımsın sensiz serseri mayına benzerim

Yıldızlara seni sordum bilmiyoruz dediler

Aşkım kalbinden gelen sıcaklıkla ilerler

Kayboldum nacizane gönlüm seni bulmak ister

Sevginle yüzüyorum sensiz bu gemi batar gider

Deniz mutlu, aşk mutlu, ben mutlu, sen mutlu musun? 

Sevgi benli, aşk benli, tutku benli, sen benli misin? 

Dünya aşklı, evren aşklı, ben aşklı, sen aşklı mısın? 

İyilik senli, güzellik senli, her şey senli, bende senliyim! 

Seni sonsuza kadar sevmeyi hedeflerim

Seni seviyorum mavilim sen benim tek gerçeğim', 'Aşkımı gemi yaptım sana yüzüyor  Göz yaşlarımla oluşturduğum okyanustan sana geliyor Aç bana güneşini dengem alabora oluyor Gece fenerim rot...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aykol']::text[], 8.5, '{"poet":"Ahmet Aykol","poet_slug":"ahmet-aykol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aski-gemi-yaptim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-ahmet-aykol-6zfsh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ses kimin sesi belli değil

Benim insanlara karşı bir acım var 

Kim gerçek kim değil belli değil

Benim yinede sonsuz şefkatim var', 'Bir ses kimin sesi belli değil Benim insanlara karşı bir acım var  Kim gerçek kim değil belli değil Benim yinede sonsuz şefkatim var...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aykol']::text[], 8.5, '{"poet":"Ahmet Aykol","poet_slug":"ahmet-aykol","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ses-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum', 'mum-ahmet-aykol-a87eg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğan bir güneş yokmu? 

Hepten mi kışa döndüm? 

Mum ışığı ile ısınan bir gönlüm var

Rüzgarlara dayanamadım çoktan söndüm', 'Doğan bir güneş yokmu?  Hepten mi kışa döndüm?  Mum ışığı ile ısınan bir gönlüm var Rüzgarlara dayanamadım çoktan söndüm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aykol']::text[], 8.5, '{"poet":"Ahmet Aykol","poet_slug":"ahmet-aykol","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-ozan-altinors-pvn6y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir gün daha geçtim işte

eylül''dü

yağmurdu, 

getirmediler seni

unutturmaya çalıştırdılar

olmadı

hala gözlerime bakıyordu gözlerin

hala elimdeydi ellerin

umut taşımıştı bir serçe kanadında

geldi, 

kondu avucuma

yoktun yine

uyandım

eylül''dü

yağmur yağıyordu', 'bir gün daha geçtim işte eylül''dü yağmurdu,  getirmediler seni unutturmaya çalıştırdılar olmadı hala gözlerime bakıyordu gözlerin hala elimd...', ARRAY['Türk Edebiyatı','Şiir','Ozan Altınörs']::text[], 8.5, '{"poet":"Ozan Altınörs","poet_slug":"ozan-altinors","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eylul-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-ozan-altinors-cageh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni sevmek, 

çalınmamış bir şarkı

seni sevmek, 

hiç duyulmamış söz

seni sevmek, 

yazılmamış bir şiir

ve seni sevmek, 

ömrümün en güzel

zamanı şimdi...', 'seni sevmek,  çalınmamış bir şarkı seni sevmek,  hiç duyulmamış söz seni sevmek,  yazılmamış bir şiir ve seni sevmek,  ömrümün en güzel zama...', ARRAY['Türk Edebiyatı','Şiir','Ozan Altınörs']::text[], 8.5, '{"poet":"Ozan Altınörs","poet_slug":"ozan-altinors","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-sevmek-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Hala', 'benim-hala-ahmet-aykol-jdw8e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim hala umudum var

Her ne kadar dolara endeksli olsada 

Benim hala umudum var 

Her ne kadar türk lirası değerini aşmasada

Benim hala bir aşkım var

Her ne kadare ABD''nin Türkiye yi sevdiği kadar sevsede

Benim hala gücüm kuvvetim var

Her ne kadar kumandam başkasının elinde olsada

Benim hala özgürlüğüm var

Her ne kadar kafes içimde yaşasamda', 'Benim hala umudum var Her ne kadar dolara endeksli olsada  Benim hala umudum var  Her ne kadar türk lirası değerini aşmasada Benim hala bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aykol']::text[], 8.5, '{"poet":"Ahmet Aykol","poet_slug":"ahmet-aykol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/benim-hala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğme', 'dugme-adnan-ferit-0zf3c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir düğme olmak ne zor.

ne kadar göz alıcı

nekadar hoş olsan da, 

ne kadar ihtiyaç duyulsan da

düğme olmak zordur yaşamda.

en az iki yerinden yaralamışlardır seni, 

ufak ya da büyük.

İki delik.

tamamlayıcı olursun hep

asıl olamazsın.

Aksesuarsındır sonuçta birilerinin yaşamında, 

ya da tam anlamıyla

yaşamda..

bir aksesuarsındır o  kadar.

Acıyla yaşamayı da kabullenmişsindir doğuştan.

boyutu önemsiz

ellerine geçirdikleri ilk iğneyi saplarlar

böğründeki, en az iki delikten birine.

Onlar açmamışmıydı zaten deliği de.

Boş görürler, 

doğru öbürüne yönelirler, 

bir de ordan geçirirler

bir daha

bir daha 

bir daha.

Kanın akmaz ya, 

anlamazlar çektiğin acıyı.

Bununla  da yetinmeyip

dolamaya başlarlar ipi boğazına, 

tur attırırlar etrafında.

İnsafa gelip bıraktıklarında

alırsın belki bir  iki nefes ama, 

kendime geldim dediğin anda, 

daha çok acı verecek gerçeği görür 

ve kabullenmek zorunda kalırsın  oracıkta.

Bir aksesuarsındır artık, 

ihtiyaç gibi dursan da birilerinin yaşamında, 

tüm yaşamda, 

aksesuarsındır artık

yaşamın boyunca..

Gün gelip, 

senden sıkılıp ya da daha göz alıcı bir kurban bulunca

atarlar bir kenara, 

bazen de öyle bir kırarlar ki tamiri imkansız, 

buluverirsin kendini  bir çöplükte.

bittiğini hissetsen de

mutlusundur aslında.

Kurtulmuşsundur artık

bir aksesuar olmaktan bu yaşamda...', 'Bir düğme olmak ne zor. ne kadar göz alıcı nekadar hoş olsan da,  ne kadar ihtiyaç duyulsan da düğme olmak zordur yaşamda. en az iki yerinde...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/dugme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göndere Çekilen', 'gondere-cekilen-ece-aykiz-hdisq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hangi sokağa çıksam

Acemi birliğinden ayrılmış

Ağzı sıkı bir parkayla

Bütün gündüzlerim kararıyor

Ceplerine soktuğumda üşüyen ellerimi

Kaldırıldıkça devlet okullarından

Sevda imgeli dersler

Gül gömütlüğüne katlanır

Göndere çekilmeyen kuğu kalesi

Davasından yargılı yürekler

Güldüğü hiç görülmemiş

Kahraman kılıklı tümcelerin

Vurmuşsa kıyısına sesimizin ölüsü

Orman yangınlarından kalma

Bir tedirginliği tutuşturur

Tarifsiz tikleri yüzümüzün

Güz sınıfı ayaklanmasında

Sırtından yaralanmış bir nehrin

Kalender kağıtlara yazılsa da ilk adı

Hala durur üzerine düştüğüm toprak

Böyle bir gün yeniden koparılmış

İşaret parmağımın tırnağı arasında', 'Hangi sokağa çıksam Acemi birliğinden ayrılmış Ağzı sıkı bir parkayla Bütün gündüzlerim kararıyor Ceplerine soktuğumda üşüyen ellerimi Kaldı...', ARRAY['Türk Edebiyatı','Şiir','Ece Aykız']::text[], 8.5, '{"poet":"Ece Aykız","poet_slug":"ece-aykiz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gondere-cekilen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Coup de Grace', 'coup-de-grace-fadil-kocagoz-q1ka7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çalakalem portrelerimi göndermiştim

hazırlıkları için

bir turnikeden savurmuştum döne döne

yüzlerceaynı mektubu

dönüp bir daha öyle bakamazdım

bütün iyi duruşlarım kadınlarda takılı

gözlerim buğu sersemi

kapladı işte öylece beni kırmadı

hiç görmeden özlediğim kuzgun

dalgalanarak

serildi örttü adımın hecelerini

şimdi başharfler hiç bilinmedik

kalanlarsa kayıp

cümlelerim devamsız eklerim beyaz dişlerde

kilit ve sık soluk

öylece kapandı kızıl dilim', 'çalakalem portrelerimi göndermiştim hazırlıkları için bir turnikeden savurmuştum döne döne yüzlerceaynı mektubu dönüp bir daha öyle bakamazd...', ARRAY['Türk Edebiyatı','Şiir','Fadıl Kocagöz']::text[], 8.5, '{"poet":"Fadıl Kocagöz","poet_slug":"fadil-kocagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/coup-de-grace-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nida', 'nida-fadil-kocagoz-ii1zf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'deliliğe adaylar

benim gibi olun

zaman geçirmeden önce

susun derin derin

gelinleri öpmeden

köprü ustası kesilsin her düşünüz

yeni yetişen kızların mavi gözlerinden

yarı gencin gururuna kurulu

hadi olun deli adaylarım

gelin

kasıklar toplantılarına büyüdünüz

genişlediniz doğurdunuz gezdiniz

dindiniz uslandınız demeden

ve hazırlıkları hiç bitirmeden öylece

hep ilk gün gibi

-o hatırlanmayan ilk nefes çığlık-

rehberimiz olsa desem...

duyuyorum

parçanız bende

derin izlerde buluşuyoruz

belirsiz birşeyler

en sevdiğimiz kutunun açılışı gibi', 'deliliğe adaylar benim gibi olun zaman geçirmeden önce susun derin derin gelinleri öpmeden köprü ustası kesilsin her düşünüz yeni yetişen kı...', ARRAY['Türk Edebiyatı','Şiir','Fadıl Kocagöz']::text[], 8.5, '{"poet":"Fadıl Kocagöz","poet_slug":"fadil-kocagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nida-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keskin Uyak', 'keskin-uyak-nevzat-celik-4sd05', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'düşmezse düşmesin yakamızdan ölüm

bizim de ülkemizde sabah olacak gülüm', 'düşmezse düşmesin yakamızdan ölüm bizim de ülkemizde sabah olacak gülüm...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çelik']::text[], 8.5, '{"poet":"Nevzat Çelik","poet_slug":"nevzat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/keskin-uyak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç', 'saklambac-nevzat-celik-k0hrs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'önüm arkam

sağım solum

          beton

hey toprak

neredeysen çık', 'önüm arkam sağım solum           beton hey toprak neredeysen çık...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çelik']::text[], 8.5, '{"poet":"Nevzat Çelik","poet_slug":"nevzat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/saklambac-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınamak', 'sinamak-nevzat-celik-0tdm2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'biliyorum sokaklarda

kartopu oynuyor çocuklar

üşüdüm acıktım demeden

buz üstünde sınıyorlar

miniminnacık gövdelerini

tam zamanıdır

sınayın çocuklar

sokaklarda her zaman

buz tutmuyor kar', 'biliyorum sokaklarda kartopu oynuyor çocuklar üşüdüm acıktım demeden buz üstünde sınıyorlar miniminnacık gövdelerini tam zamanıdır sınayın ç...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çelik']::text[], 8.5, '{"poet":"Nevzat Çelik","poet_slug":"nevzat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sinamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zindanda Gecenin Önyüzü', 'zindanda-gecenin-onyuzu-nevzat-celik-f4f2d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geceler ayaz olur

geceler yalçın olur

berbat olur hayın

kadın olur be kadın olur

katar katar geçerler de

dişi dişi sekerler de

biri ilişivermez yanına

vay be...', 'geceler ayaz olur geceler yalçın olur berbat olur hayın kadın olur be kadın olur katar katar geçerler de dişi dişi sekerler de biri ilişiver...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çelik']::text[], 8.5, '{"poet":"Nevzat Çelik","poet_slug":"nevzat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zindanda-gecenin-onyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıra', 'cira-derya-colpan-gzafy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'soyunma sesleri sızıyor pencereden.

öyle ya

bir kedi unutamaz bunu

terk edildikçe geri dönen: o

talihsiz bumerang.

kötü huylu bir ur gibi

inletiyor ağacı

ve soba

çıtırtıları diziyor

yeniden sevişmelerin kursağına.

gevşiyor mum

soyundukça.

yine sobada

çıranın öğrettiği bir acı.', 'soyunma sesleri sızıyor pencereden. öyle ya bir kedi unutamaz bunu terk edildikçe geri dönen: o talihsiz bumerang. kötü huylu bir ur gibi in...', ARRAY['Türk Edebiyatı','Şiir','Derya Çolpan']::text[], 8.5, '{"poet":"Derya Çolpan","poet_slug":"derya-colpan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Macuncu', 'macuncu-derya-colpan-rczyy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir uzundalga cızırtısında ikindi.

yer değiştiriyor kentin köpekleri

toplu konutla: tüyden bir gölge/sokuluyor

kapı önlerine - sen

uyuyordun içerde anne! 

evlerimize yapışan sesiyle

macuncu. o renk şarlatanı/kocaman gözbebeklerinde

bir elli kuruş düşlüyor: frenkgömleğimin cebindeki sıkıntı.

bizi kaçırsın diye o tayf

dönüyoruz çevresinde beyaz olana dek

elimizde boş çubukları. saklıyoruz

babamız bilmesin.

kısadalga ikindi. gidip geliyor.

babalar topluca dönünce evlerine

(yağmurdan sonra)

çocukları ele verecek

gözlerindeki gökkuşağı.', 'bir uzundalga cızırtısında ikindi. yer değiştiriyor kentin köpekleri toplu konutla: tüyden bir gölge/sokuluyor kapı önlerine - sen uyuyordun...', ARRAY['Türk Edebiyatı','Şiir','Derya Çolpan']::text[], 8.5, '{"poet":"Derya Çolpan","poet_slug":"derya-colpan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/macuncu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davetsiz Konuk', 'davetsiz-konuk-cihan-oguz-lxjyj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hava soğuk: Kediler mart ayında sanıyorlar - çığlıklarından

anlıyorum. Tiz. Bir müzik gibi ruhuna işliyor

gidip gelen sancı: Acıdan mı doğar gülümseme? 

Saklı bir mücevhere tapınan o asi tahrik

göğsünü bırakıyor geleceksiz nidaya

Gevşek artık gözlerindeki gergin tel: Aşk

bitti, mevsim de. Nisan kimi ayakta karşılamış ki?', 'Hava soğuk: Kediler mart ayında sanıyorlar - çığlıklarından anlıyorum. Tiz. Bir müzik gibi ruhuna işliyor gidip gelen sancı: Acıdan mı doğar...', ARRAY['Türk Edebiyatı','Şiir','Cihan Oğuz']::text[], 8.5, '{"poet":"Cihan Oğuz","poet_slug":"cihan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/davetsiz-konuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıplak', 'ciplak-cenk-koyuncu-05k5s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Örtüleri kaldıralım, herşey çıplak kalsın! 

Zarfsız bir mektup atmak isterdim postaneden

Hayatın cebinde harcanan bozuk parayım

Kim söz eder ki bütünleyemediğim bedenden? 

Eli kulağında gün, gelecektir yalnızlığa

Avucumda saklarım her gece karanlık bir ayışığı

Bu dünya bilmediğimiz bir gecekondu! 

Her yaşayanın içinde yıkım emri var! 

Kalemler kendini yenileyen kelimelerdir, 

Aşk kuyusunu kazıyor yeni bir acıya

Ağlamanın eli kulağında, doğdu doğacak

Çocuk bir tay gibi koşuyor hayata', 'Örtüleri kaldıralım, herşey çıplak kalsın!  Zarfsız bir mektup atmak isterdim postaneden Hayatın cebinde harcanan bozuk parayım Kim söz eder...', ARRAY['Türk Edebiyatı','Şiir','Cenk Koyuncu']::text[], 8.5, '{"poet":"Cenk Koyuncu","poet_slug":"cenk-koyuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ciplak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Fena Olur', 'bak-fena-olur-akgun-akova-tlx9q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir gün ayrılırsak

sevilmekten eskimiş bir renk sanırım kendimi

gözbebeğime bakarım senin yüzüne özgü

gece gece

abone olduğumuz o parkta bulurum kendimi

köşe bankta sırt üstü yatıyorumdur

söylemem gerek mi bilmem, zırlıyorumdur

rıhtımlar dolusu narçiçeği sen

birkaç ton körkütük sen

bir öyle bir böyle sanıyorumdur kendimi

bir gün ayrılırsak

gülkurum, çılgın diye an beni

de ki bulutlanarak, onu sevdim gibi

kellesi kulağı düşüktür şimdi ayrılmışlıktan

göğün beline keman teli sarıyordur

her zamanki gibi

de ki

kulağına doldurduğu denizler seslenip gidiyordur

sözcükleri muz gibi soyuyordur ortalık yerde

yine Şiirzade Akgün Efendi sanıyordur kendini

bir gün ayrılırsak

dövünen çok olur, sevinen daha da çok

takla atanlar olur haber üstüne

göbek atanlar

ülseri azanlar olur

bir gün ayrılırsak

bak fena olur.', 'bir gün ayrılırsak sevilmekten eskimiş bir renk sanırım kendimi gözbebeğime bakarım senin yüzüne özgü gece gece abone olduğumuz o parkta bul...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bak-fena-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeğe Durur Gibi Uyanışım', 'cicege-durur-gibi-uyanisim-akgun-akova-9eo0r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sabah sabah

bir uyandım bir uyandım sormayın

çarşafım yeni ya biraz ondan bilindi

güneşti camdan vuran serseri kılıklı kar bile yağsa

belki bir meleğin sırtını kaşımış

ya da kafayı üşütmüşüm sağımdan kalkarak

hepsi olabilirdi

bugün aybaşı, maaş alacak

talih kuşu başına konacak, ondandır dendi

biri de tutturdu düşümde cenneti görmüşüm

boşversene sen arkadaş

öyle olsa cenneti bırakır da uyanır mıyım hiç

hiçbiri değil dostlar hiçbiri değil

çiçeğe durur gibi uyanışım

akpak sevdamdan

ve böyle bir gün say say bitmez güzelliği', 'sabah sabah bir uyandım bir uyandım sormayın çarşafım yeni ya biraz ondan bilindi güneşti camdan vuran serseri kılıklı kar bile yağsa belki ...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cicege-durur-gibi-uyanisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delinin Ölümü', 'delinin-olumu-akgun-akova-ev528', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ölüm diye mırıldandı gün boyu

sonra duru duru sustu hep

yalan yok, onunla dalga geçtik

nerden bilirdik ki

         sıcak bir kumru ölüsü gördüğünü

hem öyle pek eski değil, dün öğle üstü

ardından gök çıldırmış, bunu gören yok

deyin ki yıllardır bir periye aşk dokurdu yeşimle

enikonu balkonunu cin çarpmıştı, duyardık

daha kötüsü kedisi de düşmüştü damdan

düşmüştü de kalmıştı dokuz canına hayret

bir gezgin çoban yıldızını bırakmış eline, söylerdi

nicedir o yıldız çakardı ela gözünde

bir periye aşk dokuyordu hiç usanmadan

aslanağızları geçiyordu, iğneler, dervişler

fırdöndüler, koyun postları, kor bir yelek

simli gelin telleri, tut ki rüzgar gülleri

ölüyordu

yanında duruyor, garipsiyorduk

         bir delinin de kumru gibi ölebileceğini', 'ölüm diye mırıldandı gün boyu sonra duru duru sustu hep yalan yok, onunla dalga geçtik nerden bilirdik ki          sıcak bir kumru ölüsü gör...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/delinin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vedud', 'vedud-ali-gunvar-cu5q1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey malik-i mülk-ü cihan

vahid ü kanhar

yoktur sana sani

işrak

yandım

ateşlerle dondu toprağım

ve ulandım hiçliğime

ardımsıra

işlediğim günahların yükü

ve geçtim

dayanılmaz acılarla

ırmağından

ve açıldı pencerem

bin ışıltılı bir seherin

                     koyaklarında

ve gördüm afakında çürüyen

                                     günlerimin

ki raksetmedeydi aşkınla

                              gece gündüz

devinen gökler

ve gördüm o tanrısal adı

sırtında mı sırrında mı bilmem

ve apansız çoğaldı

çiylenen dallarımda göç kuşları

ve ilk nur

dökülüp özge dudaklarından

loş çağlayanlarıma

işittim ışıltılı sesini

derinliklerinde yüreğimin

''loş çağlayanların da ben''im''

işrak

ki sorguladın titreyen

görüntüleri yorgun akşamlarla

ve ben

geceyi gözlerken

kırışıklıkları arasından karanlık

                                        denizin

soyut düş fırtınası

yükseltti gövdemi dalgaların

                                ak köpüklerine

işte oradayım, ve birden bire

ayakta ve cansız.

ve kazındı ömrümün boş

saatleriyle gölgelenen vücuduma

o ateş-i cihansuz', 'Ey malik-i mülk-ü cihan vahid ü kanhar yoktur sana sani işrak yandım ateşlerle dondu toprağım ve ulandım hiçliğime ardımsıra işlediğim günah...', ARRAY['Türk Edebiyatı','Şiir','Ali Günvar']::text[], 8.5, '{"poet":"Ali Günvar","poet_slug":"ali-gunvar","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/vedud-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzu Okay', 'arzu-okay-huseyin-alemdar-6vslt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dudaklarım geziniyor gecenin ağzında

güzel ırmak çürüğü pastel bir günahla

beyaz masum ve ıslak

dolunay lekeleri içinde tenim

kasıklarım aşk eziği bir grilikte kirli sanki

dudaklarım ki tüyden öpüş valsi

sen ey jezabel gibim

çocukmuşum gibim gidip geliyorum senle

düşüme

akşamıma

geceme

öptürüyorum seni

hayatım ruj imgesi sinema hazzı şimdi

geçmişime sarkan flu gençliğini seyrediyorum

gece ki mağdur bir dokunuş izi

çocukluğum gülhatmi suskunu elhamra sineması

usulca öpüyorum bembeyaz nilüferlerimi

yüzün ki ne kadar da şiir

- kalbim n''apsın! 

U: İstanbul''da kadınlar uzunboylu

     U gibi güzel', 'dudaklarım geziniyor gecenin ağzında güzel ırmak çürüğü pastel bir günahla beyaz masum ve ıslak dolunay lekeleri içinde tenim kasıklarım aşk...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alemdar']::text[], 8.5, '{"poet":"Hüseyin Alemdar","poet_slug":"huseyin-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/arzu-okay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mandolin Hüznü', 'mandolin-huznu-huseyin-alemdar-t8d50', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şehre tenha sesimi üfledim bu sabah

yüzümde başlayan gün donuğu bir şiirle

ilkokul çocuğu duruluğunda

duran bir gül imgesiyim şimdi

akşamın kırılan aynasında

sahi, ağzı kuş dolu bir çocuk

mandolin mi iştemişti benden

yüzümün bükülmüş göğüne çekildiğim

içimin üşümüş denizlerine döküldüğüm o an

heyy çocuk, çocuk kalbim

anne şefkati tadında bekle biraz daha

her çocuğa bir mandolin düşer belki çok yakında

içim ki mandolin hüznü bir şiirdir artık

tırnaklarını yiyen bir çocuk dalgınlığında

düşmüş balerin beyazlığında içinden ağlayan', 'Şehre tenha sesimi üfledim bu sabah yüzümde başlayan gün donuğu bir şiirle ilkokul çocuğu duruluğunda duran bir gül imgesiyim şimdi akşamın ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alemdar']::text[], 8.5, '{"poet":"Hüseyin Alemdar","poet_slug":"huseyin-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mandolin-huznu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinebeyaz', 'sinebeyaz-huseyin-alemdar-in686', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalpdudak bir şiirdim ben ruj ruj gitmiştin saflığımı

az beyaz zambak az siyah sardunyaydın o vakitler/den

Herşeyim Sensin''le başlamıştın kolye bir imge gibi içimde

Sonra Rüya Gibi''ydin Arzu gibi Günah gibi Çırılçıplak gibim

Sinemagünü pastasını kendi kesen bordo bir bıçaktın bende

Suç ve zaaflardan bir karbon yarayım şimdi senden

şiiri icabı Külebi hazzı rol icabı Paris beyazı

kalbimi kalp çarpmış, aşk ağzım Tezer Özlü kimsesizi

: ben öldüm Arzu''anım, yakam klaket kesiği sinema bıçağı!', 'Kalpdudak bir şiirdim ben ruj ruj gitmiştin saflığımı az beyaz zambak az siyah sardunyaydın o vakitler/den Herşeyim Sensin''le başlamıştın ko...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alemdar']::text[], 8.5, '{"poet":"Hüseyin Alemdar","poet_slug":"huseyin-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sinebeyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinesepya', 'sinesepya-huseyin-alemdar-ltem0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güz kesiği kısa metrajlı bir filmdim ben

veda sözleri acıtırdı içimi tenha vakitlerde

gidip gidip aynalara bakardım ince aynalara

ince aynalar ki donuk birer ince hüzünlerdi bana

kalbim bir tek sinemaydı ya çabucak biterdi her şey

Her şey hayat gibi kısa ve büsbütün Masumiyet işte

ne yapsam olmuyor sicilimde hep bir şeylerin kiri

yüzümün yarısı flashback yarısı sonbahar şimdi

: artık günahı yok kimsenin hayatımın filminde!', 'Güz kesiği kısa metrajlı bir filmdim ben veda sözleri acıtırdı içimi tenha vakitlerde gidip gidip aynalara bakardım ince aynalara ince aynal...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alemdar']::text[], 8.5, '{"poet":"Hüseyin Alemdar","poet_slug":"huseyin-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sinesepya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuh-i Nur', 'kuh-i-nur-i-dris-ozyol-wcnv7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnce adamlar yanardı ince kandillerde

ince kandillerde isli yüzler unuttuk

karanfil incinirdik / bir geyik ağlardı sessiz

bir geyik kucak dolusu karanfil ederdi

eder miydi /

kendi ışığını taşır içinde / pervane

yalnız haşhaş incitmez ellerimi

narenciye kokuyor gözlerim / gözlerindeki kuş yırtılmış ortasından

yırtılmışsa suratına bağırdığım ayna /

katlimdir şiir

her akşam aynı yerden başla bana

ki soyunsun ince adamlar ince yerlerinden

bir bakır akçe miydi tanrı / her duada yeni baştan harcanır

bir yıldız ürker yıldızlığından ki derviştir

ki lamdır

ki mimdir

biter bütün dinlerin bozuk parası

hangi kitap her incil /

ince adamların ince gözlerinde

yürek değil taşıdığım kırlangıç /

iskender''in dağlarımıza girdiği yer

suyu unut / mühürlendi bulutların öfkesi

bu yüzden / kanayan yerlerimde /

onarılmaz bir leke

ince adamlar yıkanır ince mendillerde', 'İnce adamlar yanardı ince kandillerde ince kandillerde isli yüzler unuttuk karanfil incinirdik / bir geyik ağlardı sessiz bir geyik kucak do...', ARRAY['Türk Edebiyatı','Şiir','İdris Özyol']::text[], 8.5, '{"poet":"İdris Özyol","poet_slug":"i-dris-ozyol","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kuh-i-nur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medüz', 'meduz-i-lyas-tunc-gsoeh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'günler de eşeysiz

suskun sularda

eksiliyor artık

hazırla gövdeni

güneşe çıkalım

ey saydam korku

dalgın kartopu

boşuna her şey

cezir başladı

kaç dalga boyuydu

bunca yürüdüğümüz

işte kumsal... tekneler

arsız çocuklar

ve ömrümüz', 'günler de eşeysiz suskun sularda eksiliyor artık hazırla gövdeni güneşe çıkalım ey saydam korku dalgın kartopu boşuna her şey cezir başladı ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Tunç']::text[], 8.5, '{"poet":"İlyas Tunç","poet_slug":"i-lyas-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/meduz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevecen', 'sevecen-i-lyas-tunc-xs1dl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni kollarıma

aldığım zaman

kiremitleri kırmadan

bir çatıyı örtüyor

özenle bir adm

sığınsın diye

yağmurcuk kuşları

bahçeye bakan cephede

geniş tutuyor

saçağı', 'seni kollarıma aldığım zaman kiremitleri kırmadan bir çatıyı örtüyor özenle bir adm sığınsın diye yağmurcuk kuşları bahçeye bakan cephede ge...', ARRAY['Türk Edebiyatı','Şiir','İlyas Tunç']::text[], 8.5, '{"poet":"İlyas Tunç","poet_slug":"i-lyas-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevecen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birinci Qanun', 'birinci-qanun-ahmet-hani-ilyco', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yaşayış ger budur

Yaşayam bele: 

Güle bilmeyem

Yaza bilmeyem

Diye bilmeyem

Seve bilmeyem

Qapıdan gir

Ay ölüm! 

20 august  1993', 'yaşayış ger budur Yaşayam bele:  Güle bilmeyem Yaza bilmeyem Diye bilmeyem Seve bilmeyem Qapıdan gir Ay ölüm!  20 august  1993...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/birinci-qanun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-tugba-bodur-11dk4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'teyibim yine baş ucumda

dinliyorum yine şarkılarımızı

eski günler yok artık....

konuşmuyor taş duvarlar

söylemiyorlar şarkımızı..

umutsuzluk karanlığında

bir ışık ararken

beklerken yarınları çaresizce

yalnızlık yollarında sana yürürken

en kötü anımda bile zamanla yarıştım ben.

fakat verdiğin sözlerin yanı sıra

sen yoksun yanımda

bıkmadım seni beklemekten

korkmadım ne aşktan nede söylenenlerden

çünkü korkuların en büyüğüydü

''sensizlik''

şimdi yaşıyorum o korkuyu

kalbimde.

ama sen yoksun

yine aynı şey ve ben yine

''seni özlüyorum''.', 'teyibim yine baş ucumda dinliyorum yine şarkılarımızı eski günler yok artık.... konuşmuyor taş duvarlar söylemiyorlar şarkımızı.. umutsuzluk...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sensizlik-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanamıyorum', 'i-nanamiyorum-tugba-bodur-3akgt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'cesetin şu an karşımda

inan hiç ağlamıyorum

hiç üzülmüyorum ölümüne

çünkü herşeye gülmeyi

senden öğrendim

ölüme bile.....

hani her zaman derdin ya

-gülde geç

işte her zaman bu dediğini yapıyorum

çünkü bilirim sen ağlamayı sevmezdin 

ağlatmayıda....

benden ayrılırken yine gülmüştün

-aşk ayrılıp kovuşunca daha güzel bekle beni bebeğim.

ama gelmedin bebeğim...

şu an mezarına toprak atarken

bilsen nasıl kahkalar atıyorum

aynı bana dediin gibi

-hiçbirşey ağlamaya değmaz bebeğim.

ama canım acıyor bebeğim.

kahkalarım gözyaşıma karışıyor...

içimden: 

-ölüm mü oda neymiş sen hiç ölmedin ki bebeğim

diyorum.

işte bu yüzden gülmeye çalışıyorum.

çünkü ölüme inanmıyorum

çünkü ölümüne inanmak istemiyorum.

böyle aşka ölüm yok

ölüm yok

biliyorum...........', 'cesetin şu an karşımda inan hiç ağlamıyorum hiç üzülmüyorum ölümüne çünkü herşeye gülmeyi senden öğrendim ölüme bile..... hani her zaman der...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/inanamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kendime Ben Yapmalıyım', 'seni-kendime-ben-yapmaliyim-tugba-bodur-0qmqq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zaman son haddini aşarken

sensiz yarım kalmış her dakikayı santimetrekarelere

bölmeliyim....

bu gece öyle uzun olmalı ki, 

ben sana sende bana doymalısın.

sabaha öyle bir varmalıyız ki, 

aşkımızı tüm asi vücutlara bile inandırmalıyız.

beni bütün şehvetinle öyle bir öpmelisin ki, 

seni içimde içimi sende hissetmeliyim.

bende unutulmaksızın öyle bir anı bırakmalısın ki, 

sensiz yarım kalmış senli gecelerde

doyumsuzca sersefil sevişebilmeliyim.

öyle bir bilinmezlik yaratmalıyız ki, 

bilinmezin bilinirliğinde

yaratırken bilinmezi bilinirliğe

''seni kendime ben yapmalıyım''

senden öyle bir vazgeçmeliyim ki, 

bütün aşkları bile utandırabilmeliyim.', 'zaman son haddini aşarken sensiz yarım kalmış her dakikayı santimetrekarelere bölmeliyim.... bu gece öyle uzun olmalı ki,  ben sana sende ba...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-kendime-ben-yapmaliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-tugba-bodur-ch252', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aslında sen yoksun 

sadece anılar seni dile getiren

aslında kapının çalınışı bile yalan

kapıdaki sen bile.....

ayak seslerini duyuyor gibiyim

yine en beğendiğim ayakkabını giymişsin

ıssız ve sakin yürüyosun

yine hayal misali......', 'aslında sen yoksun  sadece anılar seni dile getiren aslında kapının çalınışı bile yalan kapıdaki sen bile..... ayak seslerini duyuyor gibiyi...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayal-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığa Dair', 'yalnizliga-dair-tugba-bodur-1603g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yapışır yakana yalnızlık

atamazsın bırakamazsın....

gün gelir herşeyini kaybetsende

o sana sadıktır.

herşeye rağmen bırakmaz seni

o artık senin bir parçan

kırdığın kalplerle süslediğin

bir eserindir...

yapılması klay

ama

bozması çok zor olan bir eser

zaman geçer.......

isyan derecesine gelen bu isteğe

sitem edersin

ama 

yinede yalnızsındır

yalnız.........', 'yapışır yakana yalnızlık atamazsın bırakamazsın.... gün gelir herşeyini kaybetsende o sana sadıktır. herşeye rağmen bırakmaz seni o artık se...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizliga-dair-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaretim Yok', 'cesaretim-yok-tugba-bodur-k2xch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yine yollara vurdum kendimi

yürüyorum yollarda

ayaklarım çıplak....

caddeden geçen onca rabayı sayıyorum

delicesine...

kendimi bir arabanın altına atasım geliyor

ama

sürekli vazgeçiyorum....

ölümden vazgeçiyorum diyorum

oysa

vazgeçmek kelimesinin anlmı bile bende bir boşluk yaratıyor..

ayaklarımı çakıl taşlarına vura vura yürüyorum kaşarcasına.....

arkamda korkunç bir boşluk var

geçmişimden korkuyorum

ama

geleceğimde beni ürkütüyor

bu nedenle hiçbirşey

düşünmek istemiyorum

ama yine de bu yolda yürürken

yine bir karanlığın içine doğru ilerlediğimin farkındayım.....

hayattan bir beklentim belli bir umudum yok....

açıkcası hayattan vazgeçmeye cesaretim bile yok.......', 'yine yollara vurdum kendimi yürüyorum yollarda ayaklarım çıplak.... caddeden geçen onca rabayı sayıyorum delicesine... kendimi bir arabanın ...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cesaretim-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-tugba-bodur-0v5tn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni seviyorum

seni sadece kim olduğun için değil

seninle beraberken kim olduğumu anladığım için 

seni seviyorum

saklı kalmış beni ortaya çıkardığın için 

seni seviyorum

elini kalbimin üzerinde hissettiğim zaman

üzüntülerimi alıp onların yerine o sıcaklığı koymayı başardığın için

seni seviyorum.

hayatımı bir tapınağa çevirdiğin ve hergünümü şarkı haline getirdiğin için

seni seviyorum

seni seviyorum çünkü

sen kimsenin başaramadığı şeyi kendimi iyi hissetmemi ve hiçbir zaman olamadığım kadar mutlu olmamı sağlıyorsun.

seni seviyorum çünkü

sen bunları konuşmayla dokunmayla

ve

işaretle değil

kendin olmakla yapıyorsun

seni çok seviyorum......', 'seni seviyorum seni sadece kim olduğun için değil seninle beraberken kim olduğumu anladığım için  seni seviyorum saklı kalmış beni ortaya çı...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-seviyorum-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Evdeyken', 'sensiz-evdeyken-tugba-bodur-3fj63', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şu anda bir hüzün var bu boş evde

artık o ses yok...

kimsesiz biri gibi

istenmez artık bu odalar

yanmaz artık lambaları

basılmaz merdivenlerine

aşk gitmiştir evden

yalnızlık evdedir

yalnız başına

pusudadır.

o ve boş evin odaları

kimsesizdir artık.', 'şu anda bir hüzün var bu boş evde artık o ses yok... kimsesiz biri gibi istenmez artık bu odalar yanmaz artık lambaları basılmaz merdivenler...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-evdeyken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-tugba-bodur-gy05q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalan söyledim onlara

seni seviyorum diye

sahteydi sana

söylediğim şiirler

gözyaşlarımda yalandı

yalnız inan

şu yalansız sözüme

''aslında sen yalandın''', 'yalan söyledim onlara seni seviyorum diye sahteydi sana söylediğim şiirler gözyaşlarımda yalandı yalnız inan şu yalansız sözüme ''aslında sen...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalan-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '....KERVAN''da Kimler.., ,', 'kervan-da-kimler-i-hsan-uncuoglu-5ojw2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boş okumuş hokkabazın biri konuşurken midesinden 

Kendini nereden damgalıyor yok geçerli bir neden         

Rüyabaş a pardon yanlı goygoycu bir hakseven oturur

Bir uydurur atar tutmaz gerçek tarihin bilen yoktur.

***  

Nesli alnında yazılıymış uydurur yüz numaradan ay rupalı

Kim karen..un neresinden içli dışlı can..dar ile bir..rantlı

Kırk yılık dost gibi sarılmış bunlar uçar arka arka ortada

Ney neyden zengin kanca hayaller gezer Dicle Fırat sularında.

***

At martini haspalar beşparmaklı dağlar cicinle inlesin

Yılmaz Fog mesut haçan kayığına binip cyprusta negezersin 

Bir elinin körü saate bakar derki senkör imiş dil fransızca

Alnında soyu yazılı varsa kim cihanda nesinle girer ay rupaya.

***

Aşılmaz demir dağ eritmiş atalar ocakları okyanusa yol açmış 

Cengiz''den Atilla''ya kaç dil kavimler zaman zaman karışmış

Asyadan Türklerdir yayılan hazardan dağlardan kimi ovalara

Kafkas kaçkar ağrı omuzda Anadola boydan boya at oynata oynata. 

ÇIKIN', 'Boş okumuş hokkabazın biri konuşurken midesinden  Kendini nereden damgalıyor yok geçerli bir neden          Rüyabaş a pardon yanlı goygoycu ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kervan-da-kimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tokat', 'tokat-akin-kizil-r9bq5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgi bolluğundasevgisizlikti ahım 

Gerçek Sevgiyi bulamayışımdı kahrım

Arayışımdı hep sonsuz 

sonuçsuzdu bulduklarım

Bir sevgi dilencisiyim bu hayatta

Hep geride kaldım bu sınavda

Sonunda koşup geldim sana

Sen de ay ışığında bir Tokat attın bana', 'Sevgi bolluğundasevgisizlikti ahım  Gerçek Sevgiyi bulamayışımdı kahrım Arayışımdı hep sonsuz  sonuçsuzdu bulduklarım Bir sevgi dilencisiyim...', ARRAY['Türk Edebiyatı','Şiir','Akın kızıl']::text[], 8.5, '{"poet":"Akın kızıl","poet_slug":"akin-kizil","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tokat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müjde', 'mujde-refik-recep-pelit-hmihl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Süzülürken ruhum mavi bir gökyüzünde 

Masmavi gözlerinde beraberdir benimle 

Kavuşuruz belkide seninle günün birinde

ismin var kalbimin en kuytu köşesinde

Görmedim senin kadar güzelini bu ömrümde

Koşardım bir ihtimal ömür boyu peşinde

Altın yaldızlı saçlarında hala ezberimde

Müjde sana! bıraktın beni kor alev içinde', 'Süzülürken ruhum mavi bir gökyüzünde  Masmavi gözlerinde beraberdir benimle  Kavuşuruz belkide seninle günün birinde ismin var kalbimin en k...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mujde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Müebbet', 'gozlerinde-muebbet-yasemin-dogrubakar-zlt4p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin 

Mahrem karanlıkların gece gözlüğü 

Soğuk yanlızlık gecelerinin ebedi mahkumlar hücresi

Ve bir tabutun olabildiğince soğukluğu

Yumma demiştim onları dinlemedin

Kirpiklerine verdin suçu 

Kirpiklerin; 

Pas tutmuş 

Alabildiğince kirli 

Ve anahtarı kırılmış bir hücre kapısı

Çıkışım yoktu bilirdim

Aşkıma verdim suçu

Müebbet yatacağım hazırlıktayım

Dudaklarımı aldım yanıma

Gözlerim yuvalarında 

Avuçlarımsa öksüzdü kıyamadım almaya

Yanıma almadım onlarsız öksüz kalacağını bile bile 

Unutkanlığıma verdim suçu

Tıkılışım hücrelerine

Bir mahkumun tahliye sevinci şekli

Özgürlüğüne kavuşmuş bir güvercin gibi

Katıksız

Yapılanmamış

Saf

Ve çocuksu

Olabildiğince heyecan yüklü

Haklıyım da...

Mahkumiyetim gözlerine çünkü...', 'Gözlerin  Mahrem karanlıkların gece gözlüğü  Soğuk yanlızlık gecelerinin ebedi mahkumlar hücresi Ve bir tabutun olabildiğince soğukluğu Yumm...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gozlerinde-muebbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl Çiçeğim', 'col-cicegim-yasemin-dogrubakar-l9sp0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çöl çiçeğim demiştim adına 

Saftı kalbin 

Sadeydi gülüşün

El değmemiştin 

Yanlızlığa teslimdi bedenin

Ne kavrulmak acı verdi sana 

Ne çöl geceleri 

Alabildiğine savurgan 

Öyle toz duman

Cesaretliydin

Deliydi damarlarındaki kan

Ama bir o kadar da sakindin

Tüm nefretlere karşı unutkan

Çöl çiçeğim dedim sana

Çöl sıcağında beni güneşten çok yakan

Ürkektin aslın da

Aslın korkaktı gerçeğin aynasında

Boy göstermeyi bilirdin güneşe karşı

Salınırdın rüzgar çıktımı

Birde savurdum mu yapraklarını 

Değmeğin derdim güzelliğine

Değmeğin gözlerimin keyfine

Ama dedim ya korkaktın romantizme 

Saçlarını bir tek güneş tarayabilirdi

Dudağına değen bir tek su

Bir tek rüzgarın nefesiydi içine dolan

Ve üzerinde sadece kendi yapraklarının kokusu

Ben tüm kum taneleriydim 

Her rüzgarda sana dokunabilmek için coşkuyla koşan

Her öğün  güneşine suyuna karışıpta aşına katık olan

Ama hiç benim olduğunu kabullenmedi yaprakların

Dört bir yanını çevirmiştim oysa 

Her ne yana baksan ben vardım

Kum tanesi olmuştum uğruna

Ufalanmıştım milyonlarca parçaya

Her an yanında olabilmek adına

Eninde sonunda yapraklarını dökecektin üzerime

Salacaktın o mağrur bedenini tanelerime

Benim olacaktın sonunda 

Bekledim usanmadan

Taa ki yabancı bir el dokunup bedenine

Koparıncaya dek seni benden

Şimdi öyle bir hasrete saldın ki beni

Ne gelen var yerinde ne giden

Burası yaban bir çöl, nadide çiçeğim

Buralarda bir tek sen yakışırdın bana 

Ve bir tek sen sevilirdin böyle kana kana', 'Çöl çiçeğim demiştim adına  Saftı kalbin  Sadeydi gülüşün El değmemiştin  Yanlızlığa teslimdi bedenin Ne kavrulmak acı verdi sana  Ne çöl ge...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/col-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SENİ ÇOK SEVİYORUM', 'seni-cok-sevi-yorum-abdullah-karaduman-es3y7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çöl ben vaha sen, 

Hani tepeleri aşarken, 

Susuz kalmışken ve yanarken, 

Karşıma çıkarsın ya, 

Ben çölüm sen vaha.

Serap mısın yaksa gerçek mi? 

Anlamak ne zor, korkarım yaklaşmaya, 

Sessizlik korkutur ürpertir içimi, 

Ne zordur seni anlamak, 

Ben sonsuzluk, sen umut.

Belki de bir hayalsin, 

Ve ben bir hayal peşindeyim, 

Ama bir hayal bile olsan, 

Seni çok ama çok seviyorum.', 'Çöl ben vaha sen,  Hani tepeleri aşarken,  Susuz kalmışken ve yanarken,  Karşıma çıkarsın ya,  Ben çölüm sen vaha. Serap mısın yaksa gerçek ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-cok-seviyorum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AsLıMdA...', 'aslimda-sair-nhoyth-0mczo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün dünlerden sonra yeniden kelimelere büründüm.

Aslında bugündüm, 

Ne eskitilmiş ne de umuda muhtaç.

Aslında bugündüm ve hatta şu an.

Yalın ve çıplak.

Bütün sınırlardan arındım.

Melekleri kovaladım. 

gözyaşlarıyla kanatlarını yolarken sona kalanın, 

Türkü söylüyordum hiç bilmediğim bir dilde.

Aslında bugündüm.

Yarına az kaldım.

Aslında bugündüm ve hatta şu an.

Sınırlardan arındım.

Ben.

Bir meleğin kanatlarını yoldum.

Bugündüm.

Şu andım.

Beynime bulandım.

Köpekleri kovaladım, kemiklerime sahip çıkıp.

Ve denizler artık kımıldamıyordu, bilenler bilir.

Aslında bugündüm, 

Uykuyla bölündüm.

Şu anı uyandığımda buldum.

Biri burada unuttu sandım.

Ben aslında bugündüm, 

Yarına az kaldım.

Gece gece kelimelere bulandım.

Düne bakıp, yarına uzandım.

Bir sahil kasabasında huzuru aradım.

Aşka cesareti olmayan kızlar tanıdım.

Ve hayatı bir kez daha saygıyla andım.

E alaycı bir tebessüm vardı tabi dudağımdan arta kalan.

Ama ben bugündüm.

Ve hatta şu an.

Uykuya az kaldım.

Düşlere uyandım, 

Melekler hesap sormadı benden düşümde, 

E tabi onlar melek.

Yalnız köpekler kovaladı yine de.

Melekler gibi kaçtım, 

Uyandım.

Ben aslında bugündüm.

Ve hatta şu an.

Az önce uyandım.

Ben aslında aslını arayandım.

Ve hatta kaybolan.

Meleklere yol soran.

Uyuyamayan.

Zırvalayan.

Ben aslında kayboldum, 

Kelimelerin arasında.

Ben aslında bugündüm, 

Dünlerden ve yarınlardan usandım.

Ve hatta şu ana saplandım.

Ben aslında aslıma uzak kaldım.

Ben aslında bin dokuz yüz seksen altı baharıyım…', 'Bütün dünlerden sonra yeniden kelimelere büründüm. Aslında bugündüm,  Ne eskitilmiş ne de umuda muhtaç. Aslında bugündüm ve hatta şu an. Yal...', ARRAY['Türk Edebiyatı','Şiir','Şair Nhoyth']::text[], 8.5, '{"poet":"Şair Nhoyth","poet_slug":"sair-nhoyth","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/aslimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'teLaFFuZ...', 'telaffuz-sair-nhoyth-vah2x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'telaffuzu zor bir kelimeydin

başka bir dilden

dilime girmiş

çok sonra anladım

aslında

dilimdeki o iki hece 

adın 

değilmiş...', 'telaffuzu zor bir kelimeydin başka bir dilden dilime girmiş çok sonra anladım aslında dilimdeki o iki hece  adın  değilmiş......', ARRAY['Türk Edebiyatı','Şiir','Şair Nhoyth']::text[], 8.5, '{"poet":"Şair Nhoyth","poet_slug":"sair-nhoyth","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/telaffuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '! ! ! ! ! ! !', 'sair-nhoyth-h4dnp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '12 yıl oldu. 

birbirine benzeyen günlerin ve birbirine benzemeyen yılların toplamı. 

Elde ben varım. 

Kimi zaman fazlasıyla -az-. 

Kimi zaman yeterinden çok. 

Eskidiklerim peşimden geliyor, günahlar gibi. 

Günahlarım hangi tanrıya onu bile bilmiyorum. 

Az zamanlarla çok zamanlar arasında dengesiz yolculuklar yapıyorum. 

Standartlara uymuyorum. 

Hangi standartlar benim için bilmiyorum. 

Kazanmak istediğim hiçbir -şey- yok. 

Hiçbir kazanç kanamayı durduramaz. 

Ölene kadar ağır yaralı olmak istemiyorum. 

12 yıl oldu. 

Kanama durmuyor. 

Kan kaybediyorum, hiçbir kan kanıma uymuyor. 

Kucağımdayım, kanıyorum, görüyorum, galiba cesaret istiyorum. 

Bedenim ruhuma gün geçtikçe daha çok büyüyor. 

Köpek olmak istiyorum. 

Nedenini bilmesem de. 

12 yıl oldu. 

Geceleri uyuyamadığım 12 yıl. 

Uyuyamadığımdan utandığım. 

Azım oldukça az. 

Kelimeler kadar yetersiz ve kanamalı bütün savaşlarda olduğu gibi. 

Düşmanım, benim. 

Askerim, benim. 

Savaş, benim. 

12 yıl oldu. 

Silahlar susmuyor. 

Ateşkesler bir tutsak öldürüp, savaşa geri döndürüyor. 

Her tutsak bir can. 

Bir can ki yüreğinde derin yaralar açılıp bırakılıyor. 

Savaşımda tutsaklar ölüyor. 

Savaştırmamalıyım. 

Engel olamıyorum. 

Ağır yaralıyım, ölemiyorum. 

12 yıl oldu. 

Zaman 12 yıl önce durdu. 

Uyuyorum farklı rüyalarla. 

Sayıklıyorum: '''' uyansam '''', '''' bi uyansam '''' diyorum. 

Ama geleceğe inat uyuyorum. 

Uyanmak imkansız. 

Düşlerim hep benim. 

Kabuslarım gibi. 

Uyanışlarım kabus. 

Sabahlar kabus. 

Düşlerim, görülmemiş düşlerim. 

Ben hep düşlerim. 

Ellerim var sanki düşlerimde, gözlerim var, ayaklarımda kemiklerim var sanki, 

düşlerimde varım sanki. 

12 yıl oldu. 

Yıldızlara hala ulaşamadım. 

Bütün yıldızları sayamadım. 

Pencerelerim çoğaldı. 

Büyüklü küçüklü pencerelerim oldu. 

Kocaman sahillerim oldu. 

Yıldızlar mı çoğaldı, ben mi sayamadım. 

Oyunum hiç bitmedi, bitmiyor. 

Kanama sürüyor. 

Kanamam dinmiyor. 

Yıldızlar anlıyor, yıldızlar parlıyor ama hiçbir işe yaramıyor. 

Kalbim aynı küçük aynı gürültülü. 

12 yıl oldu. 

Denizler med, denizler cezir. 

Denizler uzaklaşır, denizler yaklaşır, denizler dağları siper eder, 

denizler beni sever, bu hayal benim. 

12 yıl oldu. 

Kuyuya düştüm, dilim tutuldu. 

Aklım yoruldu. 

Hiç ışık yok, kanıyorum, ağır yaralı, ölemiyorum. 

12 yıl oldu. 

Yazmak beni üşenmedi, boşalttı. 

Yazmak beni beğenmedi diretti. 

Kuyuya düştüm. 

Dışarısı düş. 

Yıldızlar zaten düştü, deniz med, ellerim var sanki düşteki gibi, 

gözlerim ağır yaralı, kör olamıyor. 

Kör ölemiyor. 

12 yıl oldu. 

Melekler aklımı aldı. 

Çocuğum, melekler, peri kızları masal mı? 

duvarlar arkasında tanrıda var mı? 

Kuru çiçeklere su versem diyorum bazen. 

Sonra geçiyor içimden geçirdiğim bu sözler, unutuyorum. 

Tırnaklarımı kesiyorum, ağır yaralıyım kanıyorum, tırnaklarım yine uzuyor, 

ben uyanamıyorum. 

12 yıl oldu. 

Günler tatile az var, günler aşklar getirir, günler çiçeklere benzetir, 

günler yemek yedirir, günler elma büyütür, günler yıldız saydırır, 

günler uzadıkça uzar, günler geceleri korkutur. 

Düşümde düş mü uyuduğum. 

12 yıl oldu. 

Uyanık kalınır mı bunca yıl, ay, gün uyumak gerekir, uyumak gelir. 

Uyunur düş görülür, hayal kurulur uyanıp. 

Hayal mi düşümde uyandığım düşte olduğum. 

Duvara yapışmayan fotoğraflardaki gibi denize düşmüş balıklardan birisi görse aynı düşü. 

Balıklardan birisi ben olur mu? 

Ben balık olsam, düşüm gerçek olur mu? 

12 yıl oldu. 

Geciken güneşlerden mutlu olmak kadar mutlu olunacak şeylerde var olmalıydı. 

Gözden kaçmış ve hala görülebilecek yeşil şeyler olmalı veya her ne ise renkleri. 

Tutulacak sapları olmalı. 

Denizler olmalı sonra. 

Denizler çay kaşığı olmalı sapı delikli. 

Kuşlar çaya konmalı, çay denize kavuşmalı. 

Balıkçı olta atmalı, balık kanıyor. 

Balık ağır yaralı, balık ölemiyor. 

Balık olsam diyorum düşüm gerçek olur mu? 

12 yıl oldu. 

Ben balık olamadım. 

Hangi ateşler yanmalı, suya karışmamış bi çocuk olmalı, o çocuk savaşı durdurmalı, 

tutsakları kurtarmalı, tutsakları kurtarmalı, tutsaklar ölmemeli, balık ölemiyor. 

Tırnaklarım uzuyor. 

Kar yağıyor bazen de. 

Elini bi açıyorsun, kar su oluyor, su rakıyla beyaz oluyor, rakı içince sarhoş oluyor, 

sarhoş olunca kar bekliyorsun. 

Yıldızlar her gece çoğalıyor. 

12 yıl oldu. 

Yıldızlar günahlar gibi çoğalıyor, her tanrı kendi yaz-bozuyla hesap yapıyor. 

Deniz cezir. 

Köpek, günleri kemik sayıyor. 

Sanki bacağımda kemik var. 

Kucağımdayım, kanıyorum, ölemiyorum. 

Tutsaklar ölüyor. 

Savaş devam ediyor. 

12 yıl oldu. 

Düş olmalı bu. 

Uyansam 12 yıl önce olacak. 

Tüm çiçekler uyanmamı bekliyor. 

Yıldızlar çiçek kokacak. 

Her renk çiçek. 

Zaman azalıyor birer birer takvimin birinden gün olarak. 

hiçbir peygambere emredilmemiş emir, balıklara geliyor. 

Si____ fa____ la____ re____ mi 

12 yıl oldu. 

Kadınlar türkü söylüyor gece gündüz. 

Çoraplarım kirli ve sınav var bu sabah. 

Eylül olmalı zaman. 

Türküler sarı ve kahverengi. 

Kadınlar içanadolulu, sesleri ithal. 

Kirli çorapların da düşleri var; yıkanmak gibi. 

Çoraplar temizlenmiyor. 

Kemik kanıyor, ağır yaralı, ölemiyor. 

Penc '' ü se 

gazetelerde koca başlıklar 

'''' oğlumuz oldu '''' 

'''' sevincimize ortak aranıyor '''' 

12 yıl oldu. 

Gazetelerde yazmadı. 

Şimdi biraz daha azım. 

Az kaldıkça dişlerimde fırça darbeleri ve ağzımda macun tadı oluşuyor. 

Ağzımda hasat zamanı. 

Ağzım buğday biçiyor. 

Türküler içanadolulu, kadınlar dul, sesleri davetkar. 

Türküler kıpır kıpır, haldeki balıklar teker teker ölüyor. 

Ben ölemiyorum. 

Ağır yaralıyım, kanıyorum. 

Televizyonda mavi-beyaz çizgiler. 

12 yıl oldu. 

Anteni oynatmasam da yıldızlar çoğalıyor. 

Çatalları eksik saydığım gibi yıldızları sayamıyorum. 

Denizler med. 

Yıldızlar cezir. 

Umudetmek kolay mı, güneşe bakmak kadar. 

Sanki bacağımda kemik var. 

Dişlerim kanıyor. 

Ağzım ağır yaralı. 

Balıklar, halde, birer birer ölüyor. 

Televizyonda haber bülteni, tüm sokaklara bahar gelmiş. 

Nergisler 3-0 galip. 

Savaş devam ediyor. 

Bir tutsak daha namlunun ucunda. 

Düşümdeki düşte uyandığım uykuda mıyım hala. 

12 yıl oldu. 

Uyuyorum. 

Köpekleşiyor beyazlar. 

Sarhoş oluyorum. 

Rakı bardağında kar taneleri. 

Haber bülteninde savaş haberleri. 

Sokakta nergisler açmış. 

Tutsak hayata mağlup. 

12 yıl oldu. 

Son tutsakta öldü. 

Savaş sürüyor. 

Kırmızı denizler med. 

Yıldızlar çoğalıyor. 

Köpek kemiği var sanıyor ayaklarımın. 

Balık olsam diyorum; kucağımda ölür müyüm. 

12 yıl oldu. 

Güneşe saatler kala ben daha da azalarak bedenime, 

uykuma hükmeden düşleri kovalıyorum. 

Evime bahar gelsin diye. 

Si____ la____ re____ mi____ do 

Rok yapıyor bilgisayar, yeşil artık mavi, denizler kırmızı. 

Ben hala ağır yaralı, ölemiyorum. 

12 yıl oldu. 

Perdelerim açıldı. 

Gece şehre küskün bana dönük. 

Tutsaklar düşmanıma küfrediyor. 

Düşmanım benim. 

Savaş devam ediyor. 

Balıklar halde. 

Denizler med. 

Denizler kırmızı. 

Köpekler öldü. 

Perdeler pencereden azıcık sağda, azıcık solda. 

12 yıl oldu. 

Yıldızlar çoğalıyor. 

Düşümde. 

Gazetelerde uzay çağının kapıları. 

Yıldızlar gazetelerden bi-haber. 

Uykum haber bülteninde. 

Nergisler galip. 

Tutsak nergisin ucunda. 

Koklayamıyor. 

Koklayamıyorum. 

Tenim ağır yaralı, kanıyorum, ölemiyorum. 

12 yıl oldu. 

Tutsak namlunun ucunda 

nergisler tutsağın bakışında 

çiçek kokusu bakışında 

ellerim ağır yaralı 

gözlerim kanıyor 

bir yanım var ki ölemiyor. 

12 yıl oldu. 

sigaram azaldıkça yıldızlar çoğalıyor. 

ayağımda sanırım kemik var. 

köpek, günleri kemik sanıyor. 

zaman, günleri birer birer, tadına bakmadan yutuyor, 

herhangi bir takvimin az çeşitli mönüsünden yeni günler sipariş veriyor. 

zamanla savaşıyorum. 

tutsaklar denizde. 

denizler cezir. 

yıldızlar çok. 

her renge ihtiyacı var balıkların, balıklar halde teker teker ölüyor. 

12 yıl oldu. 

yengeçler dahil olmadı ölümlere. 

haber bülteninde reklam arası düşlerim. 

uykumda uyandığım düşteki düş müyüm. 

nergisler 3-0 galip. 

kurumuş çiçeklere su vermek fikrindeyim. 

suya rakı karışmış ama olsun. rakı bardağında bi duble kar, 

yağmur ve rüzgarla karışık. 

yağmur yağıyor, yıldızlar çoğalıyor. 

ben sayamıyorum düşlere karışan evcil hayvan ilanlarını. 

matematikten her gece sınıfta kalıyorum. 

çoraplarım ıslak ve kirli. 

türkü söyleyen kadınlarla çamaşır yıkıyorum. 

kadınlar içanadolulu, elleri buruşuk. 

köpek ayağımda kemik arıyor. 

tırnaklarım uzuyor, tutsak alıyor savaş bir can daha. 

12 yıl oldu. 

silahlar susmuyor. 

savaş ağır yaralı, savaş kanıyor, ben ölemiyorum. 

güneşe gölge düşüren yıldızlar gün geçmeden çoğalıyor. 

Gazetelerde uzayın kapıları. 

Bilgisayar rok yapıyor. 

Artık maviler kırmızı. 

kırmızılar işsiz. 

çay kaşığım delikli, mutsuz. 

zamanlardan temmuz olmalı. 

memleket, memleket baharı kaçırmış. 

erik zamanı, balıklarda ölüm telaşı. 

tutsak hayatta, denizler med. 

12 yıl oldu. 

otobüslerde pencere kenarı. 

çay molası dolandırıcı dağ başlarında. 

köpek dağı bekliyor. 

ay yıldızları sayamıyor. 

düşüm balık olmak mı uyanamadığım. 

türküler ağır yaralı, kadınlar ölü. 

denizler kanıyor, ben kandırıyorum. 

12 yıl oldu. 

antende kuş olma telaşı, balıklarda reklam arası, haber bülteninde uyuyorum. 

12 yıl oldu. 

kış geride kaldı. 

Balıkçı olta tutuyor, ateş kokan çocuklar maç çıkışında. 

yıldızlar günahlarım gibi çoğalıyor. 

tanrılar işbaşında. 

ağır yaralıyım, kanıyorum. 

savaşıyorum, tutsaklar nergis kokuyor bakışlarında. 

köpekte eskimeyen kemik sevdası. 

ellerim var sanki, düşümde gözlerim var sanki, sanki kelimeler yeterli....; 

düş bu ya. 

kelimeler savaşıyor. 

aşk tutsaklar alıyor ve yıldızlar durmadan çoğalıyor. 

12 yıl oldu. 

denizler kırmızı. 

kaset bitti, türküler çorap yıkıyor. 

ölü kadınlar güneydoğulu. 

masallar türk ve yıldızlar olabildiğince. 

ağır yaralıyorum kendimi, kanıma kan uymuyor, ben uyuyorum. 

12yıldır, düşümde, 

uyansam bi sabah olacak ki evlere şenlik. ayağımda kemik yok ki. 

12 yıl oldu. 

savaş sürüyor. 

silahlar susmadı. 

tutsaklar ölüyor. 

yıldızları sayamıyorum, günahlarım gibi, yıldızlar çoğalıyor. 

kırmızı denizler med. 

ölü balıklar cezir. 

köpek ayağımda kemik var sanıyor. 

düşler hiç bitmiyor. 

güneş yine gecikti. 

tanrılar ve peri kızları var mı? 

mutlu mu kendini kuş sanan anten? 

uykumda düşümdeki uyandığım düş benim mi? 

12 yıl oldu. 

düşümde balık olamadım. 

kucağımda ölemedim. 

sokağımda çiçekler açıyor, ölü kadın türküleri yemyeşil ortalıkta. 

son tutsak namlunun ucunda. 

penceremde siyah kokan kuş çığlıkları. 

savaş bitmemecesine sürüyor. 

yıldızlar uzak. 

denizler kırmızı. 

ellerim ağır yaralı, kanıyorum. 

kalbim aynı gürültülü, 

çocuk yaşıyor. 

12  yıllık düş mü bu? 

elde ben varım........................ 

................ med................. med...............', '12 yıl oldu.  birbirine benzeyen günlerin ve birbirine benzemeyen yılların toplamı.  Elde ben varım.  Kimi zaman fazlasıyla -az-.  Kimi zama...', ARRAY['Türk Edebiyatı','Şiir','Şair Nhoyth']::text[], 8.5, '{"poet":"Şair Nhoyth","poet_slug":"sair-nhoyth","theme":"Türk Şiiri","is_hero":false,"total_lines":323,"source_url":"https://www.antoloji.com/siir-435-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salıncakta...', 'salincakta-sair-nhoyth-56h2r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geceleyin... 

salıncak vardı ya parkta. 

işte benim aklım; 

o parkta, 

birlikte sallandığım 

küçük arkadaşımda... 

geceleyin... 

aklım, 

salıncakta...', 'geceleyin...  salıncak vardı ya parkta.  işte benim aklım;  o parkta,  birlikte sallandığım  küçük arkadaşımda...  geceleyin...  aklım,  sal...', ARRAY['Türk Edebiyatı','Şiir','Şair Nhoyth']::text[], 8.5, '{"poet":"Şair Nhoyth","poet_slug":"sair-nhoyth","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/salincakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-abdullah-karaduman-ev5jy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah bir bilsen yalnızlığımı

Eriyip tükenişimi görsen

Sanki zindan günler, geceler

Bitmese saatler, bitecek ömür

Belki bir yıla, belki sabaha

Döneceğim inan koşarak sana

Sarılıp öpeceğiö seni doya doya

Sevdiğimi haykıracağım sonsuzluğa

Bitsin artık dinsin bu çile

Hasretle yanmayayım

Ne olur sanki olmasa ayrılık

Mutluluk içinde yaşamak varken

Sen yoksun belki yanımda

Kolllarım boşluğu sarıyor

Ne kadar uzakta olursan ol

Gözlerim hep seni arıyor

Hasret yazılmış alnımıza

Olsun be gülüm olsun

Sayılı gün değilmi sanki

Bitecek birgün, mutlaka bitecek

Bıkmadan usanmadan 

Sonsuza dek seveceğim seni...', 'Ah bir bilsen yalnızlığımı Eriyip tükenişimi görsen Sanki zindan günler, geceler Bitmese saatler, bitecek ömür Belki bir yıla, belki sabaha ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalnizim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samatya', 'samatya-mahir-selcuk-grx1l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Samatya, aşkların yaşanıp, aşkların birleştiği; 

Dünyadaki en renkli ve çiçeklerle dolu gönülde bir vadi.

Belki son gördüğüm yer seni, 

Belki de kalbime saplamak için attığın okun hasret dolu yolculuğu.

Samatya, diyar diyar dolansan da çıkan tek kapı.

Artık sevmiyorum ve istemiyorum sarı yaprakları.

Bir düşün..! 

Altında duygular dolu ceviz ağacı; 

Yaprakla güneşi kesti, yüzünde nur, gülümseme! 

Son bir kadeh gülümseme gönder gönlüme.', 'Samatya, aşkların yaşanıp, aşkların birleştiği;  Dünyadaki en renkli ve çiçeklerle dolu gönülde bir vadi. Belki son gördüğüm yer seni,  Belk...', ARRAY['Türk Edebiyatı','Şiir','Mahir Selçuk']::text[], 8.5, '{"poet":"Mahir Selçuk","poet_slug":"mahir-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/samatya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuyu', 'kuyu-mahir-selcuk-gda8g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlüm aşklardan sonra yaralardan akan kanlar için kuyu oldu.

Bedenim ve ruhum kuyunun kölesi, ip ile kova oldu.

Hareketi amaçsız, bir aşağı bir yukarı; içi kan dolu.

Biraz daldığımda fark ettim; artık eski, gözümde siyah - beyaz

Onca olanlardan sonra zeytin kadar bile tadı olmaz.

Sızı dinmez, ateş sönmez, dil dönmez, göz görmez, kuyu kusmaz.

Çile dedikleri bu olsa gerek, ne bitmez! 

Sus bak duyacaksın dağların sesini, hayat ritmini; 

Rüzgar sesi ve yapraklar başka diyara götürür seni.

Ayaklarının arasından geçerken, seni yoluna çağırdığını farket.

Orada, böcek sesleri seni uyuşturuyor, gücünü kaybettiğini hisset.

O zaman bir birinden farklı iki kapı çıkar karşına, 

İşte o an göreceksin kuyunun kan kustuğunu; 

Ayaklarıma emir veremeyen uyuşmuş beynimle bitireceğim bu yolculuğu!', 'Gönlüm aşklardan sonra yaralardan akan kanlar için kuyu oldu. Bedenim ve ruhum kuyunun kölesi, ip ile kova oldu. Hareketi amaçsız, bir aşağı...', ARRAY['Türk Edebiyatı','Şiir','Mahir Selçuk']::text[], 8.5, '{"poet":"Mahir Selçuk","poet_slug":"mahir-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kuyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Ya!', 'gittin-ya-pervin-beyhan-tektel-az4dm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gittin ya! 

Gidişin yüreğimde derin sızı

İçimin anlatılmazı

Dün bugün

Bugün dünkü takvimlerin koparılmazı

Gündüzün geceye, 

Ayın güneşe aşkı gibi, 

Kanattı yağmur bulutlarını

Gidişin öylesi vurdu, 

Öylesi dağladı yaralarımı

Gittin ya! 

Gidişin cemreler gibi düştü

Sular yandı, toprak yandı

Gökyüzü yıldızları yaktı, yıldızlar gözlerimi, 

Bahar hiç uğramadı, gelen hep sonbahardı.

Çöller Mecnunu, dağlar Kerem''i, 

Aslının sevdası Ferhat''ı yaktı.

Gidişin öyle vurdu, 

Öylesi dağladı yaralarımı.

Gittin ya! 

Gidişin fırtına ekti ellerime, 

Adını yazan dalgalar, kumsalda sarhoştu

Kahvesiz kapandı fincanlar, falcı falcı dolandı.

Karın altından çıkardı başını kardelen, 

Baktı ki zemheri de yalnızdı

Yazlar kışlara, kışlar kuşlara dön diye yalvardı

Gidişin öylesi vurdu, öylesi dağladı yaralarımı

Sen gittin ya! 

Gidişin duygularımın paylaşılmazı', 'Sen gittin ya!  Gidişin yüreğimde derin sızı İçimin anlatılmazı Dün bugün Bugün dünkü takvimlerin koparılmazı Gündüzün geceye,  Ayın güneşe ...', ARRAY['Türk Edebiyatı','Şiir','Pervin Beyhan Tektel']::text[], 8.5, '{"poet":"Pervin Beyhan Tektel","poet_slug":"pervin-beyhan-tektel","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gittin-ya-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Av', 'av-gurcan-gunay-ge53h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Papazkarası gözlerinin 

Kıskanç bakışlarının kıskacında

Yengeçvari kaçıyorum senden

İçim acıyor haykırasıya

Pençende çırpınan 

Zavallı bir serçe gibiyim

Baş edemedim senle

Kaçamadım aşk tuzağından

Ve işte dudaklarında

Son nefesimi veriyorum...

Bu can sana helal olsun!', 'Papazkarası gözlerinin  Kıskanç bakışlarının kıskacında Yengeçvari kaçıyorum senden İçim acıyor haykırasıya Pençende çırpınan  Zavallı bir s...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/av-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Vardır', 'biri-vardir-sair-halim-jt07r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir an bile görmek icin 

Yandığımız biri vardır

Şimdi uzak olsak bile

Kalbimizde yeri vardır

Geliyor mu? Heyecanı

Gittiğinden beri vardır

Şu an eğer insan isek

Onun bunda teri vardır

Her şeyde hatıra kalan 

O`nun bir eseri vardır

Hayallerimizde hep O

Kudsiler serveri vardır

Gönlümün hicrandan yana 

Tasası - Kaderi vardır

Bir an bile görmek için 

Yandığımız biri vardır', 'Bir an bile görmek icin  Yandığımız biri vardır Şimdi uzak olsak bile Kalbimizde yeri vardır Geliyor mu? Heyecanı Gittiğinden beri vardır Şu...', ARRAY['Türk Edebiyatı','Şiir','Şair Halim']::text[], 8.5, '{"poet":"Şair Halim","poet_slug":"sair-halim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biri-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Kardelenim', 'gittin-kardelenim-tugba-bodur-jxkc6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevgili tadıyla sevemeden seni

korka korka tutamadan ellerini

sabahlara kadar dinlemeden sözlerimi

yok olup gidiverdin kardelenim

gençlik çığlığıyla öpeden seni

korka korka saramadan ellerini

sabahlara dek süren sevişmeleri

göremeden gittin kardelenim

sana bin umut bağladım

galiba sen sevemedin sevgilim.', 'sevgili tadıyla sevemeden seni korka korka tutamadan ellerini sabahlara kadar dinlemeden sözlerimi yok olup gidiverdin kardelenim gençlik çı...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gittin-kardelenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak', 'yaprak-tugba-bodur-7yln6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir yaprak olsaydın eğer

insanlara başını bükmüş

kurumuş bir yaprak gibi

düşseydin avuçlarıma

sana hiç acımazdım

bende ezerdim avuçlarımda

süreklerdim seni rüzgar olup

ıslak kaldırımların üzerinde, 

acı çığlığını kimse duyamazdı

rüzgarımın moledisiyle

kaybolsaydın eğer

sonsuzluğun boşluğunda

o zaman gülerdi belki

o hüzün dolu yüzüm.......', 'bir yaprak olsaydın eğer insanlara başını bükmüş kurumuş bir yaprak gibi düşseydin avuçlarıma sana hiç acımazdım bende ezerdim avuçlarımda s...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yaprak-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-tugba-bodur-hrh6i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bugün yağmur yağdı

gözlerim gibi...

düşlerim gibi....

gökyüzünü de karalar aldı

düşünerek sevmiştim

düşünmeden terk etmiştim seni

bir zamanlar....

bin yerinden kırıldı kalbim

şimdi herbiri bir yana dağıldı

sensiz ilk gün gibi bir sigarayla sarhoş oldum

bir çiçekle baharı yaşadım

derken sonbahar kapımı çaldı ya

işte bugün yağmur yağdı

gözlerim gibi....

düşlerim gibi....

senide benide seller aldı......', 'bugün yağmur yağdı gözlerim gibi... düşlerim gibi.... gökyüzünü de karalar aldı düşünerek sevmiştim düşünmeden terk etmiştim seni bir zamanl...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-olur-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-tugba-bodur-n5yk7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir uzak şehirde senin ıslığını çalıyor dudaklarım

hasret siyah bir sır olmuş gözlerimde saklıyor kendini

yüreğimin kuzeyinde tükenmez bir acı

yüreğimin güneyinde kalabalık bir yalnızlık hüküm sürüyor

gökyüzüne bakarak ağlamalıyım

gözyaşlarım içime akmalı

biraz da tanrıya dua etmeliyim

acımı azaltmalı

başka denizlere başka haritalarla

başka gemilerle gitmeliyim...

başka şarkılar kendini mırıldanmalı içimde

başka bir gece başka bir şarap

başka bir şiir bulmalıyım

başka bir vedanın yolcusu olmalıyım

bu vedaya dayanamıyorum....

anılarımımı anıyor yaşadıklarım

yoksa yaşadıklarımmı çağırıyor anıları...

denize bakıyorum bana bakıyorsun

dağlara bakıyorum karşımdasın

sen bile bu kadarını yapmak istemezdin biliyorum

ayrılığın ikinci günü bu

dünü eskittim bugünde bitti

ama 

yarından korkuyorum

yarın var mı.......?', 'bir uzak şehirde senin ıslığını çalıyor dudaklarım hasret siyah bir sır olmuş gözlerimde saklıyor kendini yüreğimin kuzeyinde tükenmez bir a...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/korkuyorum-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yudum Yudum', 'yudum-yudum-tugba-bodur-b1tuf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yudum yudum kana kana içsem sevgini

sevgi sözcükleri sarsa dört bir yanımı

aşkımı anlatsam sana gözyaşlarımla

şimşekler çakar şu gönlümde

okyonuslar taşar

ama yina anlatamam sana

bu ömür sona ermeden

gitmez hatıran gözlerimin önünden

gözlerimde yaşlarla ardından bakarken

seni seviyorummmmmm diyen o tatlı dilin

hoşçakal derken

bir parça kopu verdi yüreğimden

ama üzülme bebeğim

elbet bana döneceksin

kendini yalnız hissettiğinde

birazcık düşün beni

yanındayım.

hissedeceksin.......

söylemeyi unuttum

seni çok ama çok seviyorum.', 'yudum yudum kana kana içsem sevgini sevgi sözcükleri sarsa dört bir yanımı aşkımı anlatsam sana gözyaşlarımla şimşekler çakar şu gönlümde ok...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Bodur']::text[], 8.5, '{"poet":"Tuğba Bodur","poet_slug":"tugba-bodur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yudum-yudum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep uçuyorsun', 'hep-ucuyorsun-kadir-yarali-ogd3b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni her görüşte canım yanıyor, 

Tenime dokunma yaram kanıyor.

Bu yüreğim seni ilaç sanıyor, 

Merhaba demeden hep kaçıyorsun.

Mecnun duysa ne derdi bu tavrına? 

Nice ateş yaktın garip bağrıma.

Ah güzelim, bu gidiyor ağrıma, 

Ben yaralı sense hep uçuyorsun.', 'Seni her görüşte canım yanıyor,  Tenime dokunma yaram kanıyor. Bu yüreğim seni ilaç sanıyor,  Merhaba demeden hep kaçıyorsun. Mecnun duysa n...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yaralı']::text[], 8.5, '{"poet":"Kadir Yaralı","poet_slug":"kadir-yarali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hep-ucuyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusursuz Aşk', 'kusursuz-ask-soner-arica-midcz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık gitme demiycem, zaten iyice hazırsın bu sefer.

Giderken yanında, anılarımızı, umutlarımızı, sevgimide al belki lazım olur.Uzaklara bakardım uysal çocukluğumda, içimde dolmayan derin boşluğumla.Ve denizden gelicek bir gemi bekledim durdum sonra yıldızlara baktım sen sandığım bir yıldıza.Kadınlar, çocuklar, şehirler ve evler tanıdım, çoğunuda sevdim.Aslında çok şey var sevdiğim kavgalar ve savaşlar dışında bir de niye olursa olsun vedalaşma anları.Aşklarımda oldu benim, hem de uğrunda ölebileceğim aşklar, ama en çok seni sevdim.Şimdi gidiyorsun, evet git içmdeki melek sana dua edicek sanırım kahrolmıycam bu veda sahnesine.Sen nasıl gidersen git, içim burkuluyor.Senin baban öldü mü? bu gidiş ölümden daha beter olamaz.Bence şimdi git.Hayır, gitme.Yani git de ışığı kapat ve git.Ben uzanayım şöyle.Evet git, ışıkların hepsi açık olsun ben karanlıktan korkuyorumda, üstümüde örtme bu şefkat de fazla.Hangisi doğru bilmiyorum, seni uğurlayıp öylece kalmak mı yoksa benim uyumamı bekleyip gitmen, benimde sensiz sabaha uyanmam mı.Sen giderken be içimden haykırıcam ''kusursuz bi aşktı bu''diye.Kusursuz bi aşktı benim sana büyüttüğüm sen ne yaşadın bilmiyorum.', 'Artık gitme demiycem, zaten iyice hazırsın bu sefer. Giderken yanında, anılarımızı, umutlarımızı, sevgimide al belki lazım olur.Uzaklara bak...', ARRAY['Türk Edebiyatı','Şiir','Soner Arıca']::text[], 8.5, '{"poet":"Soner Arıca","poet_slug":"soner-arica","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kusursuz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Desinler', 'desinler-bulent-isik-nfuum', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vuslata ermeye gidilen yönde

Çektiğim çileler belki en önde

Vazgeçip nazından Aslına dön de

Sözüme Kerem''in sözü desinler.

İster dumanı ol karlı dağımın

İster dikeni ol gönül bağımın

Henüz yaşanmamış bahar çağımın

Ansızın bastıran güzü desinler.

Merhamet gösterme uyma çağrıma

Eritsin hasretin gitsin ağrıma

Öyle ah çektir ki yanmış bağrıma

Ateş-i aşkının közü desinler.', 'Vuslata ermeye gidilen yönde Çektiğim çileler belki en önde Vazgeçip nazından Aslına dön de Sözüme Kerem''in sözü desinler. İster dumanı ol k...', ARRAY['Türk Edebiyatı','Şiir','Bülent Işık']::text[], 8.5, '{"poet":"Bülent Işık","poet_slug":"bulent-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/desinler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-kadir-yarali-wtwle', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hilal kaşlarına kurban olduğum

Geçiyor mevsimler güz olmadan gel, 

Toprak beni ben toprağı okşarken

Mezarımın üstü toz olmadan gel.

Lüle lüle midir zülüf tellerin? 

Bülbüle benzerdi tatlı dillerin.

Bahçedeki yediveren güllerin, 

Seherde bülbülle öpüşmeden gel.

Gelip görsen nice yaram sarılmaz

Kalbi olan sevdiğine darılmaz.

Gel helalleş hakka gitsem varılmaz

Bedenim kefende büzüşmeden gel.', 'Hilal kaşlarına kurban olduğum Geçiyor mevsimler güz olmadan gel,  Toprak beni ben toprağı okşarken Mezarımın üstü toz olmadan gel. Lüle lül...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yaralı']::text[], 8.5, '{"poet":"Kadir Yaralı","poet_slug":"kadir-yarali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Yıldönümü', 'olum-yildonumu-salih-ozalasan-1phdq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün ömrümün en acı ve en kara günü

Bügün senin bana en yakın en uzak olduğun

Seni elimle toprağın kucağına verdiğim

Yaşamak istemediğim tek ve son kara günüm

Sana en yakın olduğum ve sonra

Senden en uzak kaldığım yaşanması en zor

Hayatımın ilk hatırlayacağım son anacağım

Ağlamakla tanıştığım uzunmu uzun zalimmi zalim bir gün

Seni bugün  dönülmeze uğurladığımız günün senesi

Bugünü yaşamaktansa senden önce ölmeyi nekadar isterdim

Bilemessin bilemessin bilemessin', 'Bugün ömrümün en acı ve en kara günü Bügün senin bana en yakın en uzak olduğun Seni elimle toprağın kucağına verdiğim Yaşamak istemediğim te...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olum-yildonumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımda Özlenecek Arkadaşlar', 'aklimda-ozlenecek-arkadaslar-i-lhami-atmaca-yyavx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni bulduğum yerde kaybediyorum 

kendime bir çıkmaz sokağım 

unuttuğum çok acı var çekip gidiyor gökyüzünde sessizce 

seyrettiğim bulutlar 

ah aman sevgilim terket beni 

yeterince yundum suyunda 

ah aman sevgilim üz beni 

bir parmak dokunuşu bıraktım burnunda 

alıp başımı gitmek isterim 

vakit gelince hüzünle elele 

kaçar gibi kaytarmış bir çocuğun 

ürkek adımlarıyla acele 

yağmurun peşini takip edeceğim 

göğsümde pıtırtılı atışlar 

anneme seni şikayet edeceğim 

dilimde sahte yakarışlar 

ah aman sevgilim gitmeliyim 

başımda çığlıklanan martılar 

kendime esrik garip bir yelim 

aklımda özlenecek arkadaşlar', 'seni bulduğum yerde kaybediyorum  kendime bir çıkmaz sokağım  unuttuğum çok acı var çekip gidiyor gökyüzünde sessizce  seyrettiğim bulutlar ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Atmaca']::text[], 8.5, '{"poet":"İlhami Atmaca","poet_slug":"i-lhami-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aklimda-ozlenecek-arkadaslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Günlük İstanbul', 'bir-gunluk-i-stanbul-kadir-yarali-7cusw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sağ yanımda Sarayburnu

Karşımda Kızkulesi

Birde sen varsın aklımda 

Ah başımın belası.

Gökyüzünde üç beş martı

Sol yanımda Galata

Tutup beni bağlasalar 

Rıhtımda bir halata.

Benliğimde tüm hayalin

Kulaklarımda sesin

Söyle bana ah Karakız

Şeytan mısın sen nesin?', 'Sağ yanımda Sarayburnu Karşımda Kızkulesi Birde sen varsın aklımda  Ah başımın belası. Gökyüzünde üç beş martı Sol yanımda Galata Tutup beni...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yaralı']::text[], 8.5, '{"poet":"Kadir Yaralı","poet_slug":"kadir-yarali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-gunluk-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayamadım', 'aglayamadim-kadir-yarali-bkxlk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim hazırdı, gönlüm naz etti, 

Dün gece bir türlü ağlayamadım.

Bir seldim ah canım tarif edemem! 

Bentleri yok edip çağlayamadım.

Sığmadı bedene ruhum bir ara, 

Baktım etrafıma birisi güle; 

Birtanem bu sevgi düşürdü dile, 

Herşeyi sır ettim ağlayamadım.

Mazim yok ki bana teselli versin, 

Seven yok ki ah can gözyaşım silsin, 

Talih yok ki ben ağlarken o gülsün! 

Ağlamak istedim ağlayamadım.', 'Gözlerim hazırdı, gönlüm naz etti,  Dün gece bir türlü ağlayamadım. Bir seldim ah canım tarif edemem!  Bentleri yok edip çağlayamadım. Sığma...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yaralı']::text[], 8.5, '{"poet":"Kadir Yaralı","poet_slug":"kadir-yarali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglayamadim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Günah Değilmi', 'bana-gunah-degilmi-salih-ozalasan-te0cn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçmişti gönlümde sevda çağı çoktan

Öyle de çok yanmıştıki canım aşktan

Bir gecede çıkardın beni baştan

Söyle bana yazık, bana günah değilmi

Ömür geçmiş yolun yarısı

Kalmamış gücüm çekmeye sevda acısı

Seninle tekrar kanadı yüreğimin yarası

Söyle bana yazık, bana günah değilmi

Gözümde hiç görmediğim hayalin

Kulağımda çınlayan tatlı sesin

Dilimde doğruluğu şüpheli bir isim

Söyle bana yazık, bana günah değilmi

Kahrediyorum niye erken geldim Dünya''ya

Keşke daha önce düşseydim bu sevdaya

Seninle olmak nasip ancak bende rüyaya

Söyle bana yazık, bana günah değilmi

Gel beni sen öldür çektirme acı

Sen öldürki kal daima başımın tacı

Sürünürken düşmanım gülecek buda çok acı

Söyle bana yazık, bana günah değilmi', 'Geçmişti gönlümde sevda çağı çoktan Öyle de çok yanmıştıki canım aşktan Bir gecede çıkardın beni baştan Söyle bana yazık, bana günah değilmi...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bana-gunah-degilmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-salih-ozalasan-mjpwj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana veda etmeye cesaretim yok

Affet veda etmeden gidiyorum

Geldiğim gibi sessiz

Hiç gelmemiş gibi bu sanal aleme

Yüreğimden bir parça

Gözlerimden iki damla gözyaşı

Hatıra bırakıp gidiyorum

İki gözüm arkamda

Yüreğimde kocaman bir acı

Kalbimde seninle gidiyorum

Korku nedir bilmeyen yüreğimde

Tarifsiz bir korkuyla titriyorum

Aslında kaçmak de sen bunun adına

Yüreğimde sen ama

Yinede senden kaçıyorum

Kaçıyorum çünki anladım

Ben seni çok ama çok seviyorum

Mynete artık elveda

Ben ANTOLOJİ.COM''a dönüyorum

Çünki orada korku yok

Her sorana seni sevdiğimi söylüyorum

Seni seviyorum.Seni seviyorum

Y.Tarh   16-07-2002   Saat 9.30', 'Sana veda etmeye cesaretim yok Affet veda etmeden gidiyorum Geldiğim gibi sessiz Hiç gelmemiş gibi bu sanal aleme Yüreğimden bir parça Gözle...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-seviyorum-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Güvercin', 'beyaz-guvercin-salih-ozalasan-znj8o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurlu bir akşamdı

Pençeremde bir kuş sesi

Yorgun bitkin düşmüş kanat çırpmaktan

Kesilmiş nefesi

Titriyor uzak yerden gelmiş belli

Beyaz bir güvercin gözleri boncuk boncuk

Belliki senden haberci

Ayağında küçük bir not

Tüylerinde kokum, 

Gagasında iyi geceler öpücüğü

Ona iyi bak..! ! ! ! 

Şimdi kokun ve notun bende

Onları yüreğimde saklıyorum

Ama beyaz güvercin uçup gitti

Kayboluşunu izledim ardından mahsun

Yüreğim pençelerine takılı

Belki tekrar gelir diye hep bekledim

Belliki bir avcı düşürdü tuzağına

Yüreğim ve beyaz güvercin hala dönmedi

Kimbilir yüreğim pençelerinde

Belki başka yerlere not götürecek

Şimdi her yağmurda gözüm pençerede

Uzaklara bakıp dalıp gidiyor

Şansım yok bunu bende biliyorum

Beyaz güvercin asla dönmeyecek

Y.Tarh   16-7-2002  Saat 11.30', 'Yağmurlu bir akşamdı Pençeremde bir kuş sesi Yorgun bitkin düşmüş kanat çırpmaktan Kesilmiş nefesi Titriyor uzak yerden gelmiş belli Beyaz b...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/beyaz-guvercin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Bela', 'i-yi-bela-salih-ozalasan-q626f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şarkılarım sana şiirlerim sana

Hep sana hep seni yazıyorum

Üzüntüm sana sevincim sana

Heran seninle sensiz yaşıyorum

Sakin bir dereydim akıp giderdim kendi halimde

Bendimi yıktım sel oldum taşıyorum

Yüreğimdeki kıvılcım oldu kor bir alev

Aramızda ne varsa acımadan yakıyorum

Sana yemin sana bela sözü

Ben verdiğim sözleri hep tutuyorum

Dost acı söylermiş der ata sözü

Acıları yüreğime feryadımı sayfalara yazıyorum

Daha yolun başı en baştan başlıyorum

Yok öyle ben korktum artık yazmıyorum

Yazıyorum ve iyibela olarak dönüyorum

Anladım kaçarsam yada susarsam

Yaşarken ölüyorum

Ölmek istemiyorum çünki seni seviyorum

Y.Tarh   16-07-2002 Saat14.00', 'Şarkılarım sana şiirlerim sana Hep sana hep seni yazıyorum Üzüntüm sana sevincim sana Heran seninle sensiz yaşıyorum Sakin bir dereydim akıp...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/iyi-bela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NA''T', 'na-t-hasan-turer-2x2f8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bî-kesem bâdiye-i firkatte yâ Rasûlallah

Kimse bilmez hâlim hakikatte yâ Rasûlallah

Yandı ciğer kebâb oldu âteş-i hicrân ile

Tek kişi yok bana refakatte yâ Rasûlallah

Gerçi bir kıtmîr-i âdîyim kapından ayrılmam

Senin eşin bulunmaz hilkatte yâ Rasûlallah

Dest-i nâ-pâk ile yazdım sana bu na’tı eyvâh

Ol mücrîm benim bu kabahatte yâ Rasûlallah

Derdim bilse dağlar günahım yüklense sırtına

Ber-hevâ olurlar ol saatte yâ Rasûlallah

Garîk-i isyân ben isem medâr-ı rahmet sensin

Bana da hak var mı şefaatte yâ Rasûlallah

Baht-ı siyâhem yetişemedim göçtü son kervân

Rehberim de yok ol seyahate yâ Rasûlallah

Yarın sen de bakmazsan yüzüme işte ol zaman 

Kalırım cezâ-yı kat be katte yâ Rasûlallah

Cehennem-âsâ ızdırâb-ı hecr ile yakma sen

Bırakma beni müfârakatte yâ Rasûlallah

                                          19-12-2001', 'Bî-kesem bâdiye-i firkatte yâ Rasûlallah Kimse bilmez hâlim hakikatte yâ Rasûlallah Yandı ciğer kebâb oldu âteş-i hicrân ile Tek kişi yok ba...', ARRAY['Türk Edebiyatı','Şiir','Hasan Turer']::text[], 8.5, '{"poet":"Hasan Turer","poet_slug":"hasan-turer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/na-t-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yüzlüm', 'ay-yuzlum-salih-ozalasan-7x5aq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülü hep sevdim

Dikeni elimi kanatsa bile

Ama seni çok sevdim

Sözlerin bazen beni kırsa bile

Yüreğimi sana açtım

Oradaki yerini gör diye

Ama ben sana dememiştimki

Kalbim sütten çıkmış ak kaşık diye

Orada yüzlerce boş sayfa varken

Sen hep gittin

Yazılı sayfalara bilmemki niye

Bundan sonra yazacaklarım hep sana

Güzel gözlerin gülsün diye

Olmasın yüreğinde bir nebze hüzün

Ben ağlasamda daima gülsün yüzün

Değişme yalvarırım doğru kalsın sözün

Sözü güzel yüzü güzel AY YÜZLÜM

Y.Tarihi    13-07-2002 Saat 12.10', 'Gülü hep sevdim Dikeni elimi kanatsa bile Ama seni çok sevdim Sözlerin bazen beni kırsa bile Yüreğimi sana açtım Oradaki yerini gör diye Ama...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ay-yuzlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgaların Sessizliği', 'dalgalarin-sessizligi-salih-ozalasan-ph7vn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün gece çok farklı

Yıldızlar bile sanki daha bir canlı

Ay bile bugün bir delikanlı

Yakamoz pırıltısında hayalin saklı

Yüreğimde alabildiğine bir coşku

Dudağımda senin sevdiğin şarkı

Bir başka gece dalgaların sessizliği

İçimde anlatılmaz bir his

Özlemişim ben aşkı

Ve bir martı çığlığı

Sanki aşka davet eder gibi

Belki onun çığlığıda bir şarkı

Sevdiğini dansa davet eder gibi

Seni düşünmek seni yaşamak

Bu gecenin her geceden farkı

Çok mutluyum hemde şaşkın

Bugün doğum günüm sanki

Y.Tarihi  12-07-2002   Saat 15.20', 'Bu gün gece çok farklı Yıldızlar bile sanki daha bir canlı Ay bile bugün bir delikanlı Yakamoz pırıltısında hayalin saklı Yüreğimde alabildi...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dalgalarin-sessizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Siir', 'bu-siir-mehmet-dereli-yzdrd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sana yazıyorum bu şiirimi 

kusuyorum bütüm kinimi 

yakıyorum tüm ümütleri 

vefasızlığına bağışlıyorum bu şiirimi 

güzelim sevdamızın katili oldun 

bir hiç yere bana aşkımıza kıydın 

bembeyaz sayfamızı kirlettin 

kalleşliğine veriyorum bu şiirimi 

kalbimin en derinliğine inmiştin 

herşeyinle benliğime sinmiştin 

sevdamı kalbine kilitlemiştin 

sadakatsızlığına bu şiirim 

şimdi sensizliği yaşıyorum kışımla 

seni düşünüyorum heran hışımla 

mirasını paylaşıyor duygularım ahımla 

hiçyere terk edip gidişine bu şiirim', 'sana yazıyorum bu şiirimi  kusuyorum bütüm kinimi  yakıyorum tüm ümütleri  vefasızlığına bağışlıyorum bu şiirimi  güzelim sevdamızın katili ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dereli']::text[], 8.5, '{"poet":"Mehmet Dereli","poet_slug":"mehmet-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Güzel', 'sevmek-guzel-salih-ozalasan-ut20u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek güzel karşılık görmesende

Yüreğin paramparça gözyaşı döksende

Çığlığın gecenin karanlığını delsede

Sevmek güzel sevdiğin sevmesede

Sevmek yaşamla ölüm arası köprü

Sevdiğinin kabul görür her özrü

Özrün yok bırak artık şu hüznü

Aldırma boşver gününü yaşa

İki elin kandada olsa

Zaman ayır sende aşka

Aşık olmak

Aşık olduğunu sanmak bile banbaşka

Yaşa aşkı yüreğinde buram buram

Olmasın yüreğinde hiç bir zaman tasan

Sen sev gözyaşınada boğulsan

Aşk ile yaşamak inan banbaşka', 'Sevmek güzel karşılık görmesende Yüreğin paramparça gözyaşı döksende Çığlığın gecenin karanlığını delsede Sevmek güzel sevdiğin sevmesede Se...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmek-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiceğim', 'sevdicegim-zekeriya-oz-7mhvn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni yar görüp kendine

Herkesten geç sevdiceğim

Bil ki garibin gönlüne

Sensin ilaç sevdiceğim

Yarama merhem istemem

Kalp kırıcı bir söz demem

İstesemde söyleyemem

Söylemek güç sevdiceğim

Yüce dağlar karla dolmuş

Gönlümse efkarla dolmuş

Gayri ömrüm sonu gelmiş 

Kefenimi biç sevdiceğim

Yollarına gül sereyim

Saçlarını ben öreyim 

Senin yanında ben neyim

Varlığım hiç sevdiceğim

Yara dersen yara bende 

Kara dersen kara bende

Dilek, arzu, istek sende 

Dİlersen seç sevdiceğim

Garip gönlüm senle gülmüş

Mutluluğu senle bulmuş

İşte mecnun sana gelmiş

Kapını aç sevdiceğim...', 'Beni yar görüp kendine Herkesten geç sevdiceğim Bil ki garibin gönlüne Sensin ilaç sevdiceğim Yarama merhem istemem Kalp kırıcı bir söz deme...', ARRAY['Türk Edebiyatı','Şiir','Zekeriya Öz']::text[], 8.5, '{"poet":"Zekeriya Öz","poet_slug":"zekeriya-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdicegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiseleyen Yağmur', 'ciseleyen-yagmur-mahir-selcuk-ggm3y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden? 

Sıkıntın, konuşman, gitmen, acılarım neden? 

Ninni söyleyen güvercindin, niye sustun.Artık yalandır söylediklerin

Kendininde inanmadığı...

Konuşman da yalan gidişin de.

Beynini saran bulutlar seni şaşırtmış, 

Nasıl olduğunu ve nedenini bilmezken.

Bulutlar sulamadığından, 

Saçların güçsüzrüzgarın kölesi.

Gözlerin dağlar olmuş, yükseklik yarışında.

Felek kör etmiş ruhunu acımasızca.

Güvercin yalan söyledi dedim, 

Hayatında ilkkez, bana karşı, kendi bilmezken.

Kimse inanmadı, inatlaştı, gerçeği bilmezken.

Oysa şahitler de vardı, sen bana...

...bana ve tüm hayatına yalan söylerken: 

Şeytanın oyunu olan kilit rüzgar

Ve melek yağmur, anahtar yağmur.

Belki şeytanın kilidini açacak bir anahtar, 

Belki şeytanın kafasını bölen bir balta; 

Ama bir yağmur, çiseleyen yağmur.

Sen son yalanını söylerken ve ağlarken

Rüzgar kuruttu göz yaşlarını.

Yağmur çiseleyince yalan yalan oldu.

Çünkü o zaman gördüm konuşurken ağladığını, 

Çünkü sen konuşurken, ayrılalım derken ağlıyorsan; 

Sözün zorla söylenen yalandır.

Yağmur etkisiz bıraktı rüzgarı, 

Kurutamaz oldu göz yaşlarını.

Çiseleyen yağmurdu seni, bana ve aşka mahçup ettiren.Peki bunlar neden? 

Belki de bir testti benim sana olan aşkımı ölçen!', 'Neden?  Sıkıntın, konuşman, gitmen, acılarım neden?  Ninni söyleyen güvercindin, niye sustun.Artık yalandır söylediklerin Kendininde inanmad...', ARRAY['Türk Edebiyatı','Şiir','Mahir Selçuk']::text[], 8.5, '{"poet":"Mahir Selçuk","poet_slug":"mahir-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ciseleyen-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '31 ocak ve 20 şubat', '31-ocak-ve-20-subat-mahir-selcuk-yoe5r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani insan mutlu olur ya

Bir de umut

Mutluluk ve umut

11 ayı taşıyor üzerinde

Bitmek tükenmek bilmeyen o gücüyle

Işık hiç sönmeden

Ya da birileri söndürmeden ilerlenilen

Bu duygularla doldurulan 11 ay ve başlangış

                           

Yine yeni bir başlangıç ufukta

Yaklaşıyor zamanla, geldi ayağına

Kim bilir ayağın merdivenin hangi basamağında

Ayağını hangisinden çekip, hangisine atmakta!', 'Hani insan mutlu olur ya Bir de umut Mutluluk ve umut 11 ayı taşıyor üzerinde Bitmek tükenmek bilmeyen o gücüyle Işık hiç sönmeden Ya da bir...', ARRAY['Türk Edebiyatı','Şiir','Mahir Selçuk']::text[], 8.5, '{"poet":"Mahir Selçuk","poet_slug":"mahir-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/31-ocak-ve-20-subat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Tanıyor muyum', 'seni-taniyor-muyum-sabri-gurbuz-9hu6m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bedene sahipsin

Elle tutulur

Yürüyüşün, gülüşün var

Yemek de yiyiyorsun

İsmin var, cismin var

Ama nedir farkın

Seni tanıyor muyum

Bana bakmaz

Beğenmez dedim

Cımbızla ümit çıkarttık senden

Bana..

Zamana bıraktım

Her çaresizliğimdeki gibi

Ne yapacağımı bilmiyordum

Bunun prosedurü yoktu da zaten

Hayallerimdeki korkularımdan biri de

Senden kabul görmemdi

Çünkü insan

Hayallerine kavuşmayı ister de

Onlarla nasıl yaşayacağını düşünmez

Mutlu son kavuşmayla bitmez

Filmler hep böyle bitmez mi

Oysa o kavuşma bir başlangıçtır

Birkaç kelimeyle; 

Korkak, tembel

Ve karamsar biriymişim..

(Ve kendine güvenmeyen)

Kendimi teselli ederim

İçimde bir aslan yatıyor diye..

Seni tanıyor muyum

Ben senin etrafındayken

Sen de benim etrafım da mıydın

Gözlerim sana yol ararken

Sen farkında mıydın

Ama ben

Seni tanıyor muydum

Seller heryeri yıkmışken

Yollar sularla bölünmüşken

Ben köprüler aramıyordum

Kurtulmak için

Ben sığınak arıyordum

Kucağında ağlamak için

İşte gece, taht kurdu semaya

Biryerlerde özlemler pencerelerden taştı

Kimileri derdini yıldızlara açtı

Yine aralık bırakılarak kapandı kapılar

Işıklar uykulara kadar süzüldü

Korku, çocukların masumiyetinde söndü..

                 (17-07-2002)', 'Bir bedene sahipsin Elle tutulur Yürüyüşün, gülüşün var Yemek de yiyiyorsun İsmin var, cismin var Ama nedir farkın Seni tanıyor muyum Bana b...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/seni-taniyor-muyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-ahmet-agdere-5cz7l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen gecelerimde benliğimi arıyorum, 

Engin pas tutmuş duygularımın arasında.

Ne fayda, girdikçe arasına kayboluyorum birbir, 

İlle de sen, evet sen diye haykırırken yüreğim...

Seni sevmeyi hasretinde anlamışım, oysa ki; 

Ellerimizin birleşeceği anı iple çekerdim.

Vuslat yüreğimi vurunca ağladı yüreğim...

İlk dokunduğum yeri düşünsene bir kere; 

Yalnızca biz vardık çevremizdeki seslerle.

Onlar sadece bir fondu bizim sevgimiz için; 

Rüyalar alemi: sen, ben ve o fon....

Uğrunda öleceğimi zannederdim birlikteyken; 

Meğersem ayrılıkmış ardından ölümü getiren.', 'Sensiz geçen gecelerimde benliğimi arıyorum,  Engin pas tutmuş duygularımın arasında. Ne fayda, girdikçe arasına kayboluyorum birbir,  İlle ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-ahmet-agdere-et99a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen çağırdın yıldızların ötesinden; 

Senin için geldim bu aleme annem! 

Gözlerim açılırken bir ışıltı derinden, 

Gördüğüm güneş değildi; bu sendin annem! 

İçirdin zemzem gibi mukaddes sütünden, 

Susuzken sen yetiştin imdada annem! 

Sallanırken dünya, düşüyordum beşikten, 

Korkan ben değildim,senin yanında annem! 

Kalem tuttu elim, sözlük oldu kelimelerin; 

Nur ışığında aydınlattın yolumu annem! 

Sevdim! Kıpırdandı senin de hislerin… 

Yan yana çağlayan iki nehirdik annem! 

İlaç görmedi yüreğim doktor elinden; 

Senin gönlünden gördüğü kadar annem! 

Yıkamaz bir yeri gözyaşım selinden; 

Gözlerim sana hasret kalmadan annem!', 'Sen çağırdın yıldızların ötesinden;  Senin için geldim bu aleme annem!  Gözlerim açılırken bir ışıltı derinden,  Gördüğüm güneş değildi; bu ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/annem-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Yazılı', 'adim-yazili-hakan-rodop-qpem3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarmaşıklarda yazılı adım

bir yolcu gemisinin kaptanıyım

ufukta şimdi apaçık hissediliyor

senin yüzünde koşarcasına dalıyorum

                                               sığ denizlere

labirentten yeni çıktım

yeni bir tane istemiyorum

al götür beni buradan

doğduğun serin diyarlara

kaplıcalarda yıkanır ya insanlar

                           tertemiz sabunlarla

aynı bir maymun gibi tutunmuşlardır

                                        sarmaşıklara

korkma! bu işin yarını da var

                bu işin sonrası da var

ezelden beri hiç korkmadım

                                köpeklerden yalandan da olsa

ısırdılar beni bir gün ama

sağ bacağımdan

derin bir yara iziydi gördüğüm

akıyordu kan

yazılı adım o derin kuyularda

silmeye çalışamazsın...', 'Sarmaşıklarda yazılı adım bir yolcu gemisinin kaptanıyım ufukta şimdi apaçık hissediliyor senin yüzünde koşarcasına dalıyorum               ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/adim-yazili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akvaryum', 'akvaryum-hakan-rodop-b2pdi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağınık yatağımda bir küçük akvaryum

              ve içinde binlerce sarışın balık

elimin tersiyle itince

                      sular-seller oluyor

                      dökülüyorlar yastığıma

                      çarşafımda ölüyorlar

ben onların cesetlerinde 

                                  yaşıyorum artık

balık oluyorum

                      yüzüyorum derinlerde

okyanuslara dalıp çıkıyorum

ve bir yerlerde havyar topluyorum

satıyorum kölelere

akşam olunca

kanlı yastığıma başımı koyuyorum

                          güzel düşler içinde

oraya-buraya koşuşturan

                      küçük canlı balıklar

ve havyarlarını yiyen köleler

görerek uyanıyorum

ve yeni bir akvaryum alıyorum

tekrar kırmak için...', 'Dağınık yatağımda bir küçük akvaryum               ve içinde binlerce sarışın balık elimin tersiyle itince                       sular-selle...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/akvaryum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar', 'anilar-hakan-rodop-v6v4y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalnızlıklar geçiyor kalbimden

bir yaralı kuşun ölümü

acıtır yüreğimizi

bilinmez bir dehlizdir

                       kar tanesini görenler

                              için bir mısır tarlası

vahşi sabahlar görmek istiyorum artık

yine bağırsın tavşanlar

akbabalar dört bir yana koşsun

varsın olsun göklerde uçurtmalar

rengarenk bir cümbüşle

yenilsin afiyetle aşkımız

             ben sana git demedim

                              ama gel de hiç

                              bu da benim huyum işte

gözlerim kamaşıyor ışıltından

dur ve kapa bir dakika

                 ellerinle gözlerimi

    hisset beni

anılarla oyalanmanın anlamı yok

hayat bizi istesek de yalanlamayacak

              sen çık git mağaramdan

                     gel tekrar mağarama

               ilkelce sokul yanıma 

                           soyun

çayımın son damlasında

              bırakmıştım kalemi

tekrar yazıyorum şimdi

her nasılsa uyuyakalmışım

dudaklarımda bir garip ıslaklık

ve hücrelerimin titremesi

insan ölürse böyle ölmeli...', 'yalnızlıklar geçiyor kalbimden bir yaralı kuşun ölümü acıtır yüreğimizi bilinmez bir dehlizdir                        kar tanesini görenler ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/anilar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avcı''nın Bisikletli Çocuğu', 'avci-nin-bisikletli-cocugu-hakan-rodop-zbeo4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözüpek bir avcıydı

1500’lerde

şimdi o nerelerde? 

Gün, gece olmak zorunda

gece de gündüz

ayrık otları bitmeli

dört bir yanından

menekşe gözlü bir çocuğun

sürdüğü bisiklette

iki tekerlekte hep aynı yönde döner çünkü

çocuk 

bir yandan biskletini sürerken 

konuşuyordu kendi kendine: 

                       gizli-saklı ne varsa

                                        sizlere anlatamadığım

                                        özür dilerim

                                        dilim söyleyemedi

                                         barışın gelmeyeceğini

                                          biraz daha zamanı olmalı

                                                             yaşamanın değil mi? 

Al, bu renksiz bisiklet senin olsun

inan, çalmayacağım bir daha onu senden 

                     İnanılmaz derecede

                                           attığını vuran 

                                       bir avcıydı

                                             1500’lerde

                      şimdi o nerelerde? ..', 'Gözüpek bir avcıydı 1500’lerde şimdi o nerelerde?  Gün, gece olmak zorunda gece de gündüz ayrık otları bitmeli dört bir yanından menekşe göz...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/avci-nin-bisikletli-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış Olmuş', 'baris-olmus-hakan-rodop-61hf4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Damla damla yağıyor barış evlere

şenlik bir bahar var karşı kıyıda

balıkçılar ve ormancılar kardeş olmuş

hayal dünyasında bile kavgalar olmalı ama

iyi birşeylere hayır değil bu

toprak eskisi gibi sancılar çeksin

solucanlar bağıra çağıra duysunlar

                                        ayak seslerimizi

                                        alkşla çocuklarımızı

eskiden asur medeniyetinin bir üyesiydim

çalgıcılık yapardım

geceleri siz uyurken

ben bir ramazan davulcusuyla arkadaştım

bir ben onu dövdüm çıplak saatimle

kanlı gözlükleriyle bir de o beni

çalış derken annem gene gür sesiyle

25.yüzyılın aktif bir bireyiydim

öğleden sonra neptün’de bir spor karşılaşmasında

yeşil gözlü- hadi bir de – kumral saçlı bir kadınla

aynı yataktaydım

nasıl olsa spor bizsiz de devam edebilirdi! 

çatal, kaşık ve bıçaklarını özenle dizme

bu defa şu mor örtülü, çarpık bacaklı

                                                           masamıza

ağaçlar kesilecek

tüm palamutlar yenilecek

insanlar gece yarısı uyanacak

maç bitecek

ben yine bir yolunu bulup

size karşı çıkacağım nasıl olsa...', 'Damla damla yağıyor barış evlere şenlik bir bahar var karşı kıyıda balıkçılar ve ormancılar kardeş olmuş hayal dünyasında bile kavgalar olma...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/baris-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıçak', 'bicak-hakan-rodop-6o6ro', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her beş yılda bir

bir bıçak yarasını özlerim

keskin ve dişli bir bıçağın

yırtacağı sis perdesini

günlük tutmuyorum uzun zamandır

ama sanki gazetelerde 

                             okumuyor musunuz? 

gerçeği yazmıyorlar hiçbiri

hiçbiri bıçak taşımıyor

ve hiçbirinin sayfaları kanamıyor

alınterini anlatmıyorlar hiçbiri

karar verdim

daha çok yazacağım onların yerine

elimde işe yarayacak bir bıçak

                              var elbette...', 'Her beş yılda bir bir bıçak yarasını özlerim keskin ve dişli bir bıçağın yırtacağı sis perdesini günlük tutmuyorum uzun zamandır ama sanki g...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bicak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanlar Kimin İçin Çalar?', 'canlar-kimin-i-cin-calar-hakan-rodop-utyd8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çanlar çalıyor 

                          duymuyor musun? 

atlı arabalar vardı eskiden

yük taşırlardı

atlar ezilirdi

arabalar eskirdi

arabacı kamçısıyla habire

                                   vururdu atlarına

-	gerçi şimdi de var bazı yerlerde –

hele birde kar yağdığında

dost-düşman kaçarken sığınağına

bir onlar dışarıda

                      hallerine acırlardı

-	sosyete bayanları

                                 hala kürk giysinler

                                 üşümemek için

                                 ellerini sımsıcak saran

                                 eldivenler neden yapılıyor acaba? –

ortalığı toza-dumana katarlardı

bak, sizin için çalıyor çanlar! 

               

                    ÇAN

                    ÇAN

                    ÇAN...', 'Çanlar çalıyor                            duymuyor musun?  atlı arabalar vardı eskiden yük taşırlardı atlar ezilirdi arabalar eskirdi arabac...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/canlar-kimin-icin-calar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gömleği', 'deli-gomlegi-hakan-rodop-iek9s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başlıyor bir sevgi hikayesi

elini tutuyorum

hayasızca öpüyorum seni

dağ dağ olalı böyle bir fırtına hiç görmemiş

böyle anlatıyor köylüler

saçını çözüyorum usulcacık

yağmurlar kıskanıyor beni

saat 4 – geceyarısı

her insanın aklı böyle mi çalışır bu saatte? 

topla elbiselerini

giyin

uçuruma gidiyoruz

bugün onları ziyaret etmemiz gerek

yalnızca o gün tanıyamadım seni

yalnızca o gün

sensiz geçti dünyam

buldum! sen aslında korkuyorsun benden

yarınımdan belki de

ama açıkça söyle

daha buradayım bir süre

                          arabanın gelip götürmesine daha çok var

bu sessizlik kahrediyor beni

gömleğimi getir

             hemen şimdi gideceğim buradan...', 'Başlıyor bir sevgi hikayesi elini tutuyorum hayasızca öpüyorum seni dağ dağ olalı böyle bir fırtına hiç görmemiş böyle anlatıyor köylüler sa...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deli-gomlegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci Çocuk', 'dilenci-cocuk-hakan-rodop-ck1vs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman şekeri eritti

                       döktü pencereden

aşağıda bir dilenci çocuk

              elleriyle yakaladı taneleri

              yıkadı bir güzel

             sundu misafirlerine

ayni dilenci çocuk

-	çocukluğunu hiç yaşamamış

diğer dilenci çocuklar gibi  -

bilmezdi şekerin tadını

acı mı, tatlı mıydı? 

kokladı önce

sonra bir tane götürdü dudağına

ve gözleri kocaman açıldı

yanıyordu yanakları

misafirleri bağırdılar odadan

neden sonra

           şeker eritti zamanı

         ve tane tane aktı pencereden

         yavaşça döküldü yere...', 'Zaman şekeri eritti                        döktü pencereden aşağıda bir dilenci çocuk               elleriyle yakaladı taneleri             ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dilenci-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli ki...', 'belli-ki-ahmet-agdere-atdko', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belli ki geldiğimde usulca yanına,

Aşkınla kavrulacağım bakarken sana.

Dilim olacak gönüle susuz bir vaha,

Eriyip gideceğim dört mevsim bakışta.

Belli ki sense tek bir söz etmeyeceksin,

Aldırmayacaksın söylenen sözlere de.

Defol! olacak sözün,bir de git başımdan! 

Eziyettir bu sözler bana,gözlere de…

Belli ki gideceksin gözlerden uzağa; 

Anlamadan beni, anlatamadan seni... 

Dargın bir insan bırakacaksın ardından, 

Elleri ellerden uzak, kalplerden kalbi…', 'Belli ki geldiğimde usulca yanına, Aşkınla kavrulacağım bakarken sana. Dilim olacak gönüle susuz bir vaha, Eriyip gideceğim dört mevsim bakı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/belli-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Bir Gece', 'garip-bir-gece-hakan-rodop-5g4yx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nedendir bilinmez 

                   bir garip türkü

                   söylemeye başlarken

                   kavak ağaçları

dikiliverdim önünüze

hasretlik çekmeye alışmıştım

                                           nasıl olsa duyulmayacak

ve bir veda eldiveni kuşanarak

                       giriverdim düğününüze

                       gözkapaklarım ağır ağır

                       başlıyor sisleri dağıtmaya

ya elimi tut saatlerce

        ya da git ölesiye

değil bu yürek bunca acıya dayandı

değil özgürlük şarkıları tükendi

değil bu milletten umut kesilmez

değil sen

hiçbiri bu gece açıklamıyor

                       nedir bu mavilik bu kadar

                                                               gökyüzünde

                       nedir toprakları öğüten de

                                çarkları döndüren de

                                    aynı eller ve bacaklardır

                                                                   oysa

dedim ya garip bir gece

ve siz mışıl mışıl uyurken

                                   sıcacık yataklarınızda

ben dağbaşlarında

                        yabani güller topluyorum

siz uyanmadan

                              serpiyorum üstünüze

                                          koklatıyorum

saatler yutuyor zamanı

zaman ise ayıklanmış kum taneleri

başım istemeden düşüyor arkama

şarkıma başlıyorum

devrini doldurdu bu sabah

yarın gece yine geleceğim...', 'Nedendir bilinmez                     bir garip türkü                    söylemeye başlarken                    kavak ağaçları dikiliverdim ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/garip-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-hakan-rodop-eeuq8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boşalıyor kanım akıntıdan

kürekleri ellerimde bir kayıkla

açıktan açığa açılıyorum

ellerim donuyor açlıktan

ve kümelenmiş beyaz bir bulutsu

yokluyor ağzımı

arıyor o eski gizlendiği yeri

kalbim: adını unutmadı ki! 

beynim: sesini duymuş muydu? 

gözlerim: neredesin aykırı bakış? 

sesleniyor yüreğim-yüreğine

kanıyor yeni bir gece

ve sabah doğruluyor şafaktan

al götür beni buradan

yeni özlemler

yeni hülyalar

yeni meltemler

buluşmalı ellerimle

ve senin yiğit gözlerinde

bin yıllık hasret bitsin artık...', 'Boşalıyor kanım akıntıdan kürekleri ellerimde bir kayıkla açıktan açığa açılıyorum ellerim donuyor açlıktan ve kümelenmiş beyaz bir bulutsu ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasret-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastane''de', 'hastane-de-hakan-rodop-2omiw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sargılarımı çözdüler bugün

acayip sarmışlardı

yeni bağlar üretip

                             onları bir balyoz

                             gibi size iletmekti

                             tüm isteğim

neyse gitgide aşağıya doğru kayıyorum

bırakıyorum geçmişi size

işte bu hastane’de

alçıya alındı dilim

katılaştı- yumuşadı- katılaştı

devam etti böylece

ve bir hemşire

elinde bir çekiçle

vurdu boynuma- kırdı

ve bir doktor

geldi yıktı ağzımı

                            açtı- bağırdım

herşey beyazdan

                          siyaha 

                                    maviye

d  ö  n  d  ü            d  u  r  d  u

uyandığımda        ölmüşüm...', 'Sargılarımı çözdüler bugün acayip sarmışlardı yeni bağlar üretip                              onları bir balyoz                             ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hastane-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem', 'kalem-hakan-rodop-9f3wx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Masamın üstünde yıllardır öylesine

               duran zavallı bir mavi kalem

          yazıyor bunları – hayır

değişik bir takım çiziktirmeler

               yaptıktan sonra

         bir kenara fırlatılıp atılmış

         bir ressamın fırçası da 

                                          olabilir

yada eskimoların buz üstünde

               duran kamışları niye olmasın? 

elbiseni çıkardığında gördüğün

     lacivert yakalı bir fanilanın

  markası neyle işaretlenmiş olabilir? 

öfke her zaman iyi değildir

kin de öyle, nefret te

kızgınlıklarımızı

                örtbas etmemiz de gerekmez

hele birde kalem bitmişse

                 fırçanın boyası silinmişse

                 yaz gelmişse eskimolara

                 fanilanın markasından kime ne? 

zafer şarkıları söyle artık sen

ardından gülseler de

yeni bir kalem bulunur ancak böyle', 'Masamın üstünde yıllardır öylesine                duran zavallı bir mavi kalem           yazıyor bunları – hayır değişik bir takım çiziktirm...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kalem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Defter', 'kara-defter-hakan-rodop-rx4j5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tarihin karanlık bölmelerini çizmeli

                  hızla bir köprüden geçmeden önce

yatağım        s  a  l  l  a  n  ı  y  o  r

                                                            gökgürültüsünden

dalıvermeli ıslak düşlere

uç vermeli güneşin topları

                                     üstüste ve 

                                      yanyana

                                      konduğunda

                                      ne fark eder

                                      bir altın anahtar

                                      bulmalı

                                      kapıları açacak

sen gir yine pembe bulutlarına

seni onlar kurtarmayacak

gülünç değil güçlü olmak

canavarlarla çevriliyken bu dünya

gel sen yeni bir tarih yaz

zorbalık adlı kara deftere...', 'Tarihin karanlık bölmelerini çizmeli                   hızla bir köprüden geçmeden önce yatağım        s  a  l  l  a  n  ı  y  o  r         ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kara-defter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-hakan-rodop-d9kv9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görünen o ki çocuklar

babanız bundan böyle

       size masal anlatmayacak

gelirken size

                 bir küçük çocuk gördüm kıyıda

                 başında bir fötr şapka

şimdi gülümsemesinden hatırladım

                       ayni benim küçüklüğüm

herkesin – benden başka – bir küçük bisikleti vardı

işte bu ülkede geçti çocıkluğum

her gece dedemle gittiğim kahvede

ve her gece gördüğüm ayni adamlarla

şakalaşarak büyüdüm ben

elma şekeriyle değil

nazik bir çocuktum ben

                     yaramaz değil

kötüler her nasılsa karanlıktadır hep

ama yalnız siz bilirsiniz

                 öteki yüzünü ayın

şimdi genç delikanlılar geçiyor kapımdan

ağır aksak bir türküyle

ıslanıyor hüzünlerim

görünen o ki çocuklar

babanız bundan böyle

size hiç masal anlatmayacak

rahatça ölebilirsiniz artık...', 'Görünen o ki çocuklar babanız bundan böyle        size masal anlatmayacak gelirken size                  bir küçük çocuk gördüm kıyıda      ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/masal-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matematik Düğünü', 'matematik-dugunu-hakan-rodop-cg5c7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saltanatım uzunca sürdü bu sefer

yeryüzü ince ince dilimlere ayrılsa da

bata çıka koşacak birileri olacaktır

           yatağını toplarken

                          sardunyaları koklarken

                   üzülürken gelen fırtınaya

                          kimsesizler ne yapacak şimdi? 

üç-beş nöbetine giden bir askeri düşün

   ya çok soğuk

               ya da çok sıcakta

          ve mutlaka bir uçsuz diyarda

   göğsünde sevdiğinin resmi de varsa eğer

             kurşunlar yağar üstüne

             sevinir birileri

geliyorum gecenize

                 gözbebeklerim kutluyor düğününüzü

                 ellerim bacaklarım 2x2 şimdi

tutun, tutun, tutunun dallarıma

    çıkıyoruz belki de  7+9 yolculuğuna

matematik yanıltmaz seni

düpedüz ahlaksızsın sevdiceğim

nereden bileceksin

böldüğünü dünyamı! ..', 'Saltanatım uzunca sürdü bu sefer yeryüzü ince ince dilimlere ayrılsa da bata çıka koşacak birileri olacaktır            yatağını toplarken  ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/matematik-dugunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merdiven', 'merdiven-hakan-rodop-p65x3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Merdivenin

                    kenarında yürüyorum

                    ağzım bir karış uzamış

                    sakallarım düşmüş yere – patlamış

uçuruyorum anılarımı gökyüzüne

tesbihe dizerler ya boncukları

tembelce saymak için geceye

öyle bir aykırılık olmalı düşmek

                                                     merdiven’den

ve kalkmak tekrar yürüyerek

                yok yok koşmak lazım

           ASLINDA            AĞZIM VAR

                                         DİLİM, 

                                          KULAĞIM VAR

peki niye söyleyemiyorum

yoksa anılarım mı yetmiyor size? ..', 'Merdivenin                     kenarında yürüyorum                     ağzım bir karış uzamış                     sakallarım düşmüş yere – p...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/merdiven-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede?', 'nerede-hakan-rodop-v8bna', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hey!  yoksulluğumun küçük krallığı

           geride bıraktığım yalnızlık

           ay ışımakta doğudan

           batıdan gelmekte dostlar! 



Hey!  insanlığın büyük aynaları

           söyleyin en vurgun aşk hangisi

           ve nerede kırılır vazolar

           çekik gözlü çocıklar nerede doğar? 

Hey!  serinkanlı volkanların ağızları

           daha ne kadar bekleyeceksiniz

           gemiciler bile döndüler seferden

           işçiler çıktılar madenlerinden

           ve bildiğim tüm kızlar öldüler

Hey!  göğün salkım salkım üstüme

                                              yağan boncukları

            2+2’ nin 5 ettiği ülke yok mu? ..', 'Hey!  yoksulluğumun küçük krallığı            geride bıraktığım yalnızlık            ay ışımakta doğudan            batıdan gelmekte dostlar...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerede-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ona-Son Kez', 'ona-son-kez-hakan-rodop-l62yc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-	Akdoğan Rodop’un Değerli Anısına-

Acının giysilerini topladım yerden

mahzun bir çocuk yüzüydü ölüm

nasılsın diyemeden bir kez daha

hoş geldin çocuğum

ben geçmişten çok şeyler aldım ödünç

damla damla geri vermekteyim şimdi

sarılsaydı ya bir kez daha

hoş geldin çocuğum

kanım ve tüm hücrelerim adını ezberledi

içtiğim her suda görüyorum yüzünü

nolur kızsaydı ya bir kez daha

hoş geldin çocuğum

hayat bitti ------

          ----- mi?  bitmemiştir ama

anılacaksın her sabah şafakta

rahat uyu toprağında

sevgili babacığım...', '-	Akdoğan Rodop’un Değerli Anısına- Acının giysilerini topladım yerden mahzun bir çocuk yüzüydü ölüm nasılsın diyemeden bir kez daha hoş gel...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ona-son-kez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Kabuk', 'olu-kabuk-hakan-rodop-t1ajf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerden çıktı geceyarısı bu oyun

üstümden kalkan bulutların

ardına gizlenmek istemiyorum

yavaş yavaş alınlarımızı

                     birbirine değdirerek

anahtarlarını arıyoruz cennetin

öyle kolay değil ama susmak

                                     her zaman

hele bir de ayın delinmiş ortasında

                balıkçılarla dansederken

                           gülmüşsen bana

hoş geldin – sefa geldin

                bir kiraz ağacı

   ya da bir marul tarlası

                    bizi kapatamaz

   geçmişten uzaklaşıyor sesim

   artık bu ölü kabuk yırtılacak

çaresiz gece yarısını geçti ömrüm

güzelce uyu şu buğday tarlasında

sabaha daha çok şey var anlatılacak...', 'Nerden çıktı geceyarısı bu oyun üstümden kalkan bulutların ardına gizlenmek istemiyorum yavaş yavaş alınlarımızı                      birbir...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olu-kabuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatyalar Ayıklanmak İçindir', 'papatyalar-ayiklanmak-i-cindir-hakan-rodop-ff8j8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Turuncu papatyalarla çevrilmiş

bir bahçeye koşar adımlarla 

                                     giriyorum

geçmişte yaptığım ne varsa

                       şaşırıyorum hepsine şimdilerde

üstelik sigarayı bırakmayı bile düşünüyorum! 

-	tek başına hayatta kalmayı

eminim basit bir böcek te becerebilir

ezilmemek güzel bir şey tamam

ama yetmez doldurmaya bahçeyi –

mor papatyalarla çevrilmiş

bir bahçeden koşar adımlarla 

                                       çıkıyorum

gelecekte yapacağım ne varsa

                     şaşırıyorum hepsine şimdilerde

ve çaldığım papatyalardan birini

                                                     ayıklıyorum

seviyorum

sevmiyorum

seviyorum

sevmiyorum sizi...', 'Turuncu papatyalarla çevrilmiş bir bahçeye koşar adımlarla                                       giriyorum geçmişte yaptığım ne varsa       ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/papatyalar-ayiklanmak-icindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç', 'saklambac-hakan-rodop-t7y25', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir avuç kül ve ıslanmış toprak

vardı ellerinde

saat geceyarısını geçince

üçgen mi yoksa daire miydi

çizdikleri gökyüzüne

saklambaç oynayan çocukların

yüzlerinde yansıyan

bir gülümsemeydi arkadaşlık

bilmeden sundukları birbirlerine

ne güzeldir beklemek bir sevgiliyi

ve sunmak bir çiçeği

daha kaç silgi gerek

silmek için kötülükleri

daha kaç çocuk ağlayacak? 

ellerindeki bir avuç külü

yüreğimizden

ve ıslanmış toprağı

içlerindeki güneşle yıkadılar

yanlarında çocuklarda vardı o zaman...', 'Bir avuç kül ve ıslanmış toprak vardı ellerinde saat geceyarısını geçince üçgen mi yoksa daire miydi çizdikleri gökyüzüne saklambaç oynayan ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/saklambac-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş Arkadaşlarım', 'savas-arkadaslarim-hakan-rodop-6oid9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözümün önünden geçiyor

bir bir yaralılar

                     savaşta

elimiz ellerine uzandı

                           nasıl göremezsin

biz onlarla kardeştik

eğlenmeye vaktimiz yoktu

siz nasıl duymazsınız

                      ölülerin ayak seslerini

                      yüreğinizi parçalayacakmış gibi

                      atıyor mermiler

                                    üstünüze yağıyor

              nasıl dokunamazsınız gözyaşlarıma

yanıyor bak

                 yanıyor saçlarım

sizi bir ben gördüm kulaklarınızı tıkarken

                              ilgisizliğinizi gördüm

                              sağırlığınızı gördüm

askerler çıkıyor tepeye

dikiyor alınterimizi

nasıl, nasıl, nasıl göremezsin bizi

al terimi iç kana kana

şimdi savaş arkadaşlarım yaşıyor 

                                    beynimin içinde...', 'Gözümün önünden geçiyor bir bir yaralılar                      savaşta elimiz ellerine uzandı                            nasıl göremezsin bi...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/savas-arkadaslarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayfalar', 'sayfalar-hakan-rodop-hcnkz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adım adım tırmalarken 

                   sayfalar öyküyü

bir bülbül şakıması olmalı

                             duyulan uzaklardan

girecek koynumuza bir gün: yarın

sesleri yırtılacak tavşanların

                     kavrulacaklar denizlerde

girmek zordur

                       küllerle dolmuş bir bahçeye

toplamak daha zordur

                 papatyaları – tilkilere yedirmeden

ağlamak en kolayıdır

                  sarhoşça gözlerken ufku

her sayfa yırtılır

               ya da kedilerce tırmalanır

biter öyküler

yenileri mutlaka başlamalıdır...', 'Adım adım tırmalarken                     sayfalar öyküyü bir bülbül şakıması olmalı                              duyulan uzaklardan girecek...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sayfalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darmadağın', 'darmadagin-hakan-rodop-ri00t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'parmaklarında asılı 

bir küçük yağmur tanesi

ısıtıyor içimi

güne başlarken 

dışarısı buz misali

yangın yeri

ıslak uğurlar ola diyorsun

beni bırakıp yarınlara

ıslanıyorum

üşüyorum

birden sıcak ılık 

bir kartanesi

alkışlamaya geliyor beni

bense darmadağın

senden uzakta!', 'parmaklarında asılı  bir küçük yağmur tanesi ısıtıyor içimi güne başlarken  dışarısı buz misali yangın yeri ıslak uğurlar ola diyorsun beni ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/darmadagin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gelsene', 'hadi-gelsene-huseyin-poyraz-ise05', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anilar gozumde canlandi yine

Beraber bakalim hadi gelsene, 

Aldirma alemin ne dedigine

Beraber cikalim hadi gelsene...

Ne diye uzersin kalp efendini

Tuketip bos yere beni kendini! 

Sevginin dusmani gurur bendini

Beraber yikalim hadi gelsene...

Yanmasin canimiz pur zehir gibi, 

Isgal altindaki bir sehir gibi, 

Askin deryasina gur nehir gibi, 

Beraber akalim hadi gelsene...

Duruyor saklimda verdigin mendil, 

Karamsar olurmu asigin; sendil

Gonul bahcemize yeter bir kandil

Beraber yakalim hadi gelsene...

Kimleri kul etti hasret kacini! 

Mecnun, Leyla gibi sefkat acini! 

Gorkemli bir yerde nikah tacini

Beraber takalim hadi gelsene...

Huseyin Poyraz', 'Anilar gozumde canlandi yine Beraber bakalim hadi gelsene,  Aldirma alemin ne dedigine Beraber cikalim hadi gelsene... Ne diye uzersin kalp ...', ARRAY['Türk Edebiyatı','Şiir','Huseyin Poyraz']::text[], 8.5, '{"poet":"Huseyin Poyraz","poet_slug":"huseyin-poyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hadi-gelsene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-hakan-rodop-25gav', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gün ağardı bak

dışarıda 

ince

ıslak bir güneş

sarmalıyor geçmişimi

hadi el ver yüreğime

ses ol  bakış ol

niye bu durgunluk 

hayat

boşlukları doldurmak içindir

ya da vazgeçmeden

yeni günün gürültüsünden

kırıntısından bile sevincin

koş

gidebildiğin yere

aşk

senin bildiğin kadar uzakta değildir!', 'gün ağardı bak dışarıda  ince ıslak bir güneş sarmalıyor geçmişimi hadi el ver yüreğime ses ol  bakış ol niye bu durgunluk  hayat boşlukları...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayat-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir-İki', 'bir-i-ki-hakan-rodop-4ppx7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayrılık kuşu önce

bakışlara konar 

sonra dudaklara

talihse zamanın akışı

birileri içinse vurdumduymaz aşkın

savunmasıdır

zaman biter önce-sonrası

hayat bazen gülümser bize

bazen de hüzünlenir

bir kuş sürüsü

yetmez ki sonlandırmaya

onca zamanın doluşu

karanlık bir sevdadır bizimkisi

güneşsiz evler mi daha acıdır

yoksa ayrılıklar mı? 

2.

barış istemiyorum

adı yalnızca bizde saklı

güllere yazıktır

konuşmayan evler 

dilsiz yürekler

paradır barış

yıkıldığında güvenilir olacak

beraber inciteceğiz

tutuldumu kanatları güvercinin 

ay dolduğunda

istemiyorum ben barış

huzurlu geçitler

seni-beni alır götürür

nasıl olsa beraber devireceğiz

bu dünyayı

kuracağız beraber', 'Ayrılık kuşu önce bakışlara konar  sonra dudaklara talihse zamanın akışı birileri içinse vurdumduymaz aşkın savunmasıdır zaman biter önce-so...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-iki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç-Dört', 'uc-dort-hakan-rodop-axjlr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sana beni anlatmışlar

duygularla oynanırsa

bir top misali

nereye kadar

cansız olan herşeyde gözüm var

kıpırdamayan heykellerde

bir yürek kıpırtısı

dışında

altıncı his bu

beni-sana anlatmışlar

gözlerdir ayna olan kalbin

atışı duyulduğunda

ah o eller

titreyen ama

seven sevilen

ah o yürekler

4.

gene bir gün batışı

içimde alevler

neden coşmuyor

gidip gelen çağlayanlar

işleri ne

şarkılar söyle

kulağım şenlensin

doysun hücrelerim

güzelliğinle iç beni 

kaygısızca

nedir bu gürültü

başıma gelen

hadi zamanıdır soyunmanın

bütün kirlerden

eğer kalırsa 

bir damla bile 

geriye dönüşüdür

yakışıdır hepimizi

hadi!', 'sana beni anlatmışlar duygularla oynanırsa bir top misali nereye kadar cansız olan herşeyde gözüm var kıpırdamayan heykellerde bir yürek kıp...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/uc-dort-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Temmuzlar', 'o-temmuzlar-ahmet-uysal-zsd53', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nereye gitsem karşıma çıkıyor ansızın

O temmuzlar, gözlerine benzeyen bir kızın

O temmuzlardı karanlığı sevdiren bana

Parlarken uzaklarda ışığı bir yıldızın

Otlarla, böceklerle uyuduğum günlerdi

Simgesiydim sonsuz bozkırlarda yalnızlığın

Şimdi unuttum bütün adları ve yüzleri

Yüreğimde yangınları kaldı temmuzların

Solumak, bir daha solumak o temmuzları

Güzelliğine vararak çok eski yazların', 'Nereye gitsem karşıma çıkıyor ansızın O temmuzlar, gözlerine benzeyen bir kızın O temmuzlardı karanlığı sevdiren bana Parlarken uzaklarda ış...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/o-temmuzlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş-Altı', 'bes-alti-hakan-rodop-23ndi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dilini yemişler çocuğun bugün

şaşırmış bağıramıyor

uzaktan bile ölemiyor

sıkıntılı geçen günler beni bıraksın

sana yakışır

diğer çocuksa

nerede  oynuyor

bir bataklıkta timsahlarla

geldi çattı toparlanma

çalıyor borusu

aydınlık bir gazete getirin mezarıma

okusun çocuklar

güle oynaya konuşa! 

6.

çizmişler üstünü yoksulluğun

onlar sanki yok

sessiz sessiz

derinden haykırış

üzülmek derinden

herşey var

onlarda herşey

yok

gülmek sevinmek

yorulmamak istemezler mi? 

köleliktir bu moderninden

çağın adı

ey! 21. yüzyıl

eğer sende kabul edersen

haksızlığı bunca

gelme! 

kal olduğun yerde', 'dilini yemişler çocuğun bugün şaşırmış bağıramıyor uzaktan bile ölemiyor sıkıntılı geçen günler beni bıraksın sana yakışır diğer çocuksa ner...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bes-alti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi-Sekiz', 'yedi-sekiz-hakan-rodop-xvcic', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kapı aralığından süzülüyor

çetrefilli aşk

basılmayan kartvizitlerin hepsi

bir yerde alnımıza

yazılan notalardır

okunacak günü geldiğinde

çalışanlar bekliyor 

bak açmış ellerini

kaçırmamak için seni

yürü sende değil kodese bile

nereye istersen

aralığı kapının çıtırdıyor

çıtır da çıtır...

8.

son bu bugünlük

yarın derler ya 

Allah-kerim

bırakmadık şimdiye kadar

varsa yoksa alınteri

yaptığımız iş

ekmek parası abiler

biz anlamayız

gücün kudretin çırpınışını

balığın

dökülünce akvaryum

sen gene de

oku şiirlerini

deme son

alınırlar gücenirler

şuh bir gülüş at

ve devam yarına.', 'kapı aralığından süzülüyor çetrefilli aşk basılmayan kartvizitlerin hepsi bir yerde alnımıza yazılan notalardır okunacak günü geldiğinde çal...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yedi-sekiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaz Daha Eskir', 'bir-yaz-daha-eskir-ali-asker-barut-dwan0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmur yemiş sırılsıklam bir karanfil

Bir tenhalığa gülümsüyor içimde

Henüz silinmemiş bir ay parçası

Çoktan aydınlanmış gökyüzünde

Ah Galata Kulesi! 

Bizanslı sarışın çocuk! 

Yıllardır hüzünle bakıyor denize.

Yükünü boşaltmış bir gemi geçiyor uzaktan

Evlerin denize açık pencerelerinde kadınlar

Ki her biri nasıl da yalnız

Dalıp dalıp gidiyorlar o pencerelerde

Yağmurun içinde ıpıslak bir gökkuşağı

Güvercinle doluyor

Üsküdar çarşısı

''Yalnızlık gittiğin yoldan gelir''

Kana boyanır içimde

Bütün aşk kelimeleri

Günün ilk otobüsüyle son otobüsü arasında

Bir yaz daha eskir! 

Ve ben artık başlasam da

Bitiremem, başladığım hiçbir şiiri.', 'Yağmur yemiş sırılsıklam bir karanfil Bir tenhalığa gülümsüyor içimde Henüz silinmemiş bir ay parçası Çoktan aydınlanmış gökyüzünde Ah Galat...', ARRAY['Türk Edebiyatı','Şiir','Ali Asker Barut']::text[], 8.5, '{"poet":"Ali Asker Barut","poet_slug":"ali-asker-barut","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-yaz-daha-eskir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan O Şarkı', 'uzaktan-o-sarki-ali-asker-barut-4c2d1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzaktan o şarkı dökülüyor

Yarıncıl yanımdaki hüzzam yağmura

Yan masada kalbine kanatlar çizen adam

Ölüyor avucunun içine aldığı

Kadının ojeli parmaklarına

Sigara bulutları altında

Lulu diye seslendiği kadının

Sazlı sözlü gözleri

Bardaktaki yapma karanfillere

Hüzünle yönelen o buğulu bakışı

Daha çok rakının marifeti

Kaçır beni haydut kaçır diyor

Kendi yalnız dağlarına

Yarın bulamayabilirim bu cesareti

Göz göre göre

Bir aşk yeşeriyor yan masada

Dalgınlığıma ver

Bir anı gibi ansızın

Dalmışım da karşıki dağlara

Yarıncıl yanımdaki hüzzam yağmura

Uzaktan o şarkı dökülüyor hala

Hızını alamamış adam yan masada

Yüzünde peş peşe kuş gölgeleri

Gel boşa gitmesin canım ayışığı

Üstümüzde diyor kadına

Gözlerimiz ellerimiz ayaklarımızla

Dökülelim birbirimize

Kadınsa işin işçilik kısmında

Ufak bir ağustosböceği gibi habire

Ateş taşıyor bu aşka kanatlarında

Garson

Pardon

Bir aşk yeşeriyor yan masada

Biliyorum bir canlılık geldi

Deminden beri bardaktaki karanfillere', 'Uzaktan o şarkı dökülüyor Yarıncıl yanımdaki hüzzam yağmura Yan masada kalbine kanatlar çizen adam Ölüyor avucunun içine aldığı Kadının ojel...', ARRAY['Türk Edebiyatı','Şiir','Ali Asker Barut']::text[], 8.5, '{"poet":"Ali Asker Barut","poet_slug":"ali-asker-barut","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/uzaktan-o-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canan', 'canan-huseyin-poyraz-7xy8u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Varligin omrume dogan gunesmis

Ben ise nankordum bilmedim canan! 

Hasretin hanceri bagrimi desmis, 

Sen gittin gideli gulmedim canan...

Albumdeki resmin duvarda simdi

Sual edenlere dedim esimdi

Seni en son soran yavrum Yesim''di

Verecek bir cevap bulmadim canan...

Ne yapsam ne etsem hep aklim sende

Istahim kesildi fer yok bedende

Mecnun''danda beter oldum sayende

Bi-turlu kendime gelmedim canan! ..

Ruhumda sasirdi yasam tadini 

Olumsuz askimin essiz kadini! 

Gonul defterimden senin adini

Vallahi billahi silmedim canan...

Ozlem atesiyle daglandim, yandim! 

Bir gun af cikarir donersin sandim

Tanri''nin verdigi candan usandim, 

Carpildim, cirpindim olmedim canan...', 'Varligin omrume dogan gunesmis Ben ise nankordum bilmedim canan!  Hasretin hanceri bagrimi desmis,  Sen gittin gideli gulmedim canan... Albu...', ARRAY['Türk Edebiyatı','Şiir','Huseyin Poyraz']::text[], 8.5, '{"poet":"Huseyin Poyraz","poet_slug":"huseyin-poyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıraç', 'kirac-anil-mericelli-nrxb8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnanamadığım bir toprak kokusu ansızın

Doğu özellikli bir yağmur tuzlu sabahlarda, 

Işıksız bir yaşamaya uzanan yüz yıllardır

Bir su kadar donuk bir su kadar kahırlı

Umutsuz bir bekleyişle dünlere kadar

Çağrışımlar içinde bir toprak Urartu''lardan

Tuzlu sabahlarında kıraç toprakların

Kırk yılın yarattığı bir açlık ve yalnızlık

Yarım kilo çay bir teneke gaz

Ve inanamadığım bir toprak kokusu ansızın', 'İnanamadığım bir toprak kokusu ansızın Doğu özellikli bir yağmur tuzlu sabahlarda,  Işıksız bir yaşamaya uzanan yüz yıllardır Bir su kadar d...', ARRAY['Türk Edebiyatı','Şiir','Anıl Meriçelli']::text[], 8.5, '{"poet":"Anıl Meriçelli","poet_slug":"anil-mericelli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kirac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-anil-mericelli-4e43m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günün en yorgun saatlerinde

Şiir

Gözlerindeki ürperti gibidir

(Gökyüzünün aynasıdır gözlerin

Günün en yorgun saatlerinde)

Sünger avcılarının aradığı

Bulanık su diplerindeki

Kirli elleri kirli dudaklarıyla aradığı

Şiir

Irmağın kıyısındaki şehir

Nasıl uyanırsa geceden

Geride kalan bakışlarınla

Mevsimleri mevsim yapan

Şiir

Günün en yorgun saatlerinde

Gözlerindeki yangın gibidir.', 'Günün en yorgun saatlerinde Şiir Gözlerindeki ürperti gibidir (Gökyüzünün aynasıdır gözlerin Günün en yorgun saatlerinde) Sünger avcılarının...', ARRAY['Türk Edebiyatı','Şiir','Anıl Meriçelli']::text[], 8.5, '{"poet":"Anıl Meriçelli","poet_slug":"anil-mericelli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siir-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırgın ve Atak', 'kirgin-ve-atak-aydogan-yavasli-3v0h4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vazo kırıldı. İntizar edince ayna ve gölün dalgın

yakamozları. Sonra köpek ulumaları rüzgarlı kıyıların

çehresine donuk bir bakış gibi yapıştı. Şimdi

                                           verir (mi)   ellerini

porselen bulutlar ve o gri karmaşa (?)

insan eski bir vadinin terkedilişlere tanık olmuş

kuytularında savaşa hazırlanır ve onun gölgeli

                                 ormanında batık bir gemi

                                                                 (gibi)

                                                     arar kendini

Oysa ayna ve gölün kuşatılmış yalnızlığı

körpe bir kızla beraber yakar inmeli bedenini

Ben ki o gri karmaşadan aldım yağmurlu yüzümü

biraz da gönüllü giyindim hakkımda

verilen unutulmak hükmünü

Şimdi kim verir ellerini bana

                             ve nasıl hatırlatır paslı dilimi?', 'Vazo kırıldı. İntizar edince ayna ve gölün dalgın yakamozları. Sonra köpek ulumaları rüzgarlı kıyıların çehresine donuk bir bakış gibi yapış...', ARRAY['Türk Edebiyatı','Şiir','Aydoğan Yavaşlı']::text[], 8.5, '{"poet":"Aydoğan Yavaşlı","poet_slug":"aydogan-yavasli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kirgin-ve-atak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamana Düşer', 'zamana-duser-aydogan-yavasli-cvgwx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şiir kaçağıyım ben

Ayaklarımda akan yollarda

Rüzgar tadında bir serüven

Rüzgar tadında bir serüven

Bir karanfil düşürür

Yüzümü yakar giderken

Yüzümü yakar giderken

Eski bir nihavend sevgili

Zamana düşer erkenden

Zamana düşer erkenden

Kavuşmak bir damla suya

Yaşamla intihar sevişirken

Yaşamla intihar sevişirken

Rüzgar tadında bir serüven

Yüzümü yakar

                    Zamana düşer

Erkenden', 'Bir şiir kaçağıyım ben Ayaklarımda akan yollarda Rüzgar tadında bir serüven Rüzgar tadında bir serüven Bir karanfil düşürür Yüzümü yakar gid...', ARRAY['Türk Edebiyatı','Şiir','Aydoğan Yavaşlı']::text[], 8.5, '{"poet":"Aydoğan Yavaşlı","poet_slug":"aydogan-yavasli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zamana-duser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakir', 'bakir-kucuk-i-skender-23inu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'korkularımı tatmin eden bir et parçası gibi yükseliyor yerden

            küllü köküyle, 

sararmış koltukaltlarında geceleri kentleri saran mavi ışık

            ve nöbetçi bir sevgilinin keçe kalemle alelacale

            yazılmış, yarısı terden silinmiş telefon numarası.

-öncesi, diye soruyorum, nefesim çürük kağıt kokuyor

-öncesi, tende durmazki... diyor, ben

            ağustos böceği orospusuyum, çabuk unutulurum! 

kadın, bu: yüzyıllık bir şarabın mantarı olmaktan yorgun

            parmaklarımı sarkmış memelerine düğümlüyorum

sayılarını yitirmiş bir hedef tahtası gibi vücudu! 

            ağzına, karanlıkta, taşa sarılı bir mesaj gibi düşüyor

dudaklarındaki camı kırarak dilim...

tarz acemisiyim, aşk acemisiyim, düş acemisiyim.

on yedisindeyim: 

-hikayen, diye soruyorum, gencim, geçmişsizlikten ürküyorum, 

-hikaye, hayatta durmaz ki... diyor, ben

            ölümsüzlük bahanesiyim, çabuk kururum! 

kadın, bu: kalçalarını yerleştirirken kasıklarıma yeniden

            ayın acımasızca çektiği çaresiz deniz suyuyum...

-deminki ilkti, diye fısıldıyorum, gülümsüyor.

-benimki son değil! 

ilk''le son değil''in arasındaki bu delik deşik gürültü

örtüyor o korkunç kerhanedeki ''ortodoks'' görüntüyü.

arkadaşlar dışarda bekliyor.

hepsi annem.

ben erkek oldum.

gerisi sırra kadem.', 'korkularımı tatmin eden bir et parçası gibi yükseliyor yerden             küllü köküyle,  sararmış koltukaltlarında geceleri kentleri saran ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bakir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikaye', 'hikaye-kucuk-i-skender-gp8nv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'anladık, uzakta bir parıltı var ve

                          lirler de kırık

hüzün ve ölüm eşittir hırs oluyor orada

metrelerce geceye sarkıtılıyoruz

eski birer iki ölü gibi

                          şakaklarda mor damarlar

yetmiyor zaman dağınık düşleri

köreltilmiş gözleri sahiplenmeye

ve devam ediyor hayat

en lazım yerinden hızla incelmeye', 'anladık, uzakta bir parıltı var ve                           lirler de kırık hüzün ve ölüm eşittir hırs oluyor orada metrelerce geceye sarkı...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hikaye-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadife Şairler', 'kadife-sairler-lale-muldur-33d4g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ölüyorlar kadife şairler...

pazarların tozunda ve kulelerin sisinde gömülü

gün geceye akıyor..
..........
..........', 'ölüyorlar kadife şairler... pazarların tozunda ve kulelerin sisinde gömülü gün geceye akıyor.. .......... .............', ARRAY['Türk Edebiyatı','Şiir','Lale Müldür']::text[], 8.5, '{"poet":"Lale Müldür","poet_slug":"lale-muldur","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kadife-sairler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskil Bir Aşk Öyküsü', 'eskil-bir-ask-oykusu-lale-muldur-y9a61', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'boynumda yağmurdan bir kolye...

ıslak taşlara oturuyorum bugünlerde...

bir siyam kedisi ve ben... pek çok şeyi geriye doğru unutuyoruz...

eski rus bir sevgilim vardı...

başka birisini göze alamam bugünlerde...

öykü safir aynal
..........
..........', 'boynumda yağmurdan bir kolye... ıslak taşlara oturuyorum bugünlerde... bir siyam kedisi ve ben... pek çok şeyi geriye doğru unutuyoruz... es...', ARRAY['Türk Edebiyatı','Şiir','Lale Müldür']::text[], 8.5, '{"poet":"Lale Müldür","poet_slug":"lale-muldur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eskil-bir-ask-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayışığında Yaygara', 'ayisiginda-yaygara-reha-basogul-drtx9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçmişinin derbederliklerini 

geleceğin renklerine taşıyorum azar azar

sakın unutma! beklemeseydin beni

sevgime asla değmeyecekti nazar

Etrafımının yıkıldığı diyarda sarıldım sana

Kalbini mırıldanarak açtın bana

Çıplaklığını nefasetinle yatırdın yanıma

Mabedini esaretinle yıkattırdın bağbozumuna

Bak işte! 

Gözünün önünde! 

göl kenarında belirmiş karmaşalığımızdan bir temaşa...

Duy işte! 

Kulağının içinde! 

Ayışığında yükselmiş başbaşalığımızdan bir yaygara...

yüzlerce mum yaktıysam da çevrene

çıplaklığın parlattı geceyi 

gezindim üstünde bir seyyah gibi 

binlerce  nağme bıraktıysam da evrene 

besteledim sırtına teslimiyetini 

o an aldım elime tüyden bir kalemi

köz olmuştu çünkü katranlı yüreğime 

dudaklarının sessizliği..

Buram buram lavantalar sürdüm üzerine

delice çizdim anılarımı heryerine 

fırçamın kayan sakinliği

daireyi saran hareketleri

başladı bataklıktan çıkışımızin hikayesi

nadasa bırakılmış bir tarla gibi

şimdi meyvelerini veriyor kaçışımızın neticesi

soluk soluk nefesimle uçuşuyor yelelerin

oluk oluk renk havuzunda yüzüyor göğüslerin

karanfil pembesi, papatya sarısı

menekşe mavisi, orkide beyazı

hepsi kokusunu salıyor dipdiri resminde 

bir de kıskanç Ay''ın gümüş rengi bulaşmış tenine

sersemletiyor nemli dileğini sivriliğim

güldürüyor tüylü silleni gezinmişliğim

aniden dokunur dokunmaz ona

rengarenk saçlarınla çengelledin beni koynuna

düştüm yine çamsakızından gafletimle sırçaköşküne 

kandım yine  sızlanışımdan dişlerle cam gözlerine

boğuk bir ulumayla kanattık sızıyı

donuk bir geceyle ısıttık kanımızı

yine de taş attık şeytanın kahpeliğine 

yine de kulak tıkadık arkadan söyleneceklere

çünkü bir tek balıkçıllar kesebilirdi sözlerimizi

çünkü bir tek vücutlar tanıyabilirdi resmimizi...', 'Geçmişinin derbederliklerini  geleceğin renklerine taşıyorum azar azar sakın unutma! beklemeseydin beni sevgime asla değmeyecekti nazar Etra...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ayisiginda-yaygara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklar', 'uzaklar-reha-basogul-oroz1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve uzaklardayım şimdi

sonsuz beyaza gömüldüm

tek hissettiğim

içimdeki gücüm

etrafımdaki

bu telaşsız ahenkler

bu sayısız bitkiler

bu acısız yürekler

bu karışık sesler

hepsiyle yok oluyorum

görmüyor musun aşk bu 

kavuruyor işte 

savuruyor işte

beni birer birer

şimdi sanıksız

şimdi yargısız

şimdi kuralsız

bu eller

bu diller

bu gözler....

yalnızca aşkla başbaşayım

hükmü verilmiş topraklardayım

sonu baş olmuş yollardayım

seni koydum koynuma

sarmaladım soğukluğumla

sımsıcacık 

ve sessiz yüzünü

ve anlamadım hala

o mu beni büyütüyor

yoksa ben mi onu 

bu benzersiz diyarda

ne yaman çelişkidir ki bu

insanlardan uzaklaşınca teker teker

yüreğimde

daha mazbut

daha büyük

daha yüce 

yer edindiler

aşkın göz yaşlarını

sonsuzluğun sanrısını

olduğu gibi kabul etmek lazım

tuzsuz yaraları

ne baktığım bir seraptı

ne tattığım bir şaraptı

bal gibi gördüm seni

bal gibi gözüktün işte

niye inkar edeyim

nolur susturma beni

nolur konuş hadi

Bunca yıl

bunca sayı 

bunca kelam

hepsi bomboşmuş

yokoluş varoluşmuş

varoluş bomboşmuş

dönüyorum

duruyorum

karışıyorum işte

bir soruyorum

bir soruluyorum

adım ne

can mıyım

cansız mıyım

canan mıyım? 

Ve şimdi

gözlerim delik

dilim kesik

yüreğim ezik

ya bundan sonra

ya bulduktan sonra

nasıl dayanacak

nasıl asılacak 

nasıl kanacak

bu delik

bu kesik

bu ezik

hapsolduğum yaşama? 

Kan bu 

damardaki kan

kanayan kan

susatan kan

akıyor işte

akacak da

sarmaşık gibi

sarmış beni

saracak da

susturacak da

ne büyük acı

ne büyük yara

yakarışım bile

duyulmuyor burada

son bir defa 

son bir vefa

hadi uzatma

kırdıralım şu zamanı

yıkalım işte diye

yalvarıyorum sana

ama kan bu

akıyor işte

deli kanı bu

acı kanı bu

konuşmuyor

sokuyor işte

söylemiyor

yakıyor işte

bakmıyor

kaçıyor işte

yine çağırıyor sesin

yine ensemde nefesin

sancısız düşler diliyor

hülya meclisinde bu acizin

bu büyüklük

bu ihtişam

bu nizam 

bana çok geliyor

bana yük geliyor

oradan bakınca buralar

çook çok uzak geliyor', 'Ve uzaklardayım şimdi sonsuz beyaza gömüldüm tek hissettiğim içimdeki gücüm etrafımdaki bu telaşsız ahenkler bu sayısız bitkiler bu acısız y...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":118,"source_url":"https://www.antoloji.com/uzaklar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sular', 'sular-kadir-yarali-vd6id', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akarasınız nazlı nazlı

Bazen acı bazen tuzlu, 

Kışın akarsın buzlu, 

Size canım kurban sular.

Sunalar oynar içinde, 

Baharda başka biçimde, 

Köprüler bir bir göçünce, 

Haşmetiniz yaman sular.

Yaz ayları tatlı ılık, 

İçinde çeşitli balık, 

Su içer kaz gibi culuk, 

Sizde neşe tam sular.', 'Akarasınız nazlı nazlı Bazen acı bazen tuzlu,  Kışın akarsın buzlu,  Size canım kurban sular. Sunalar oynar içinde,  Baharda başka biçimde, ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yaralı']::text[], 8.5, '{"poet":"Kadir Yaralı","poet_slug":"kadir-yarali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarısı Yok', 'yarisi-yok-kadir-yarali-78fcc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi kırlardayım canım

Balı gördüm arısı yok.

Sende kalan resme baktım

Yarısı var yarısı yok.

Çiçek gördüm öbek öbek

Alı vardı, sarısı yok.

Hafızamda sevgi sözün

Yarısı var yarısı yok.', 'Şimdi kırlardayım canım Balı gördüm arısı yok. Sende kalan resme baktım Yarısı var yarısı yok. Çiçek gördüm öbek öbek Alı vardı, sarısı yok....', ARRAY['Türk Edebiyatı','Şiir','Kadir Yaralı']::text[], 8.5, '{"poet":"Kadir Yaralı","poet_slug":"kadir-yarali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarisi-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum Işığında', 'mum-isiginda-i-smail-ozabaci-fj0x8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu gece

hayalini almışım karşıma, 

mum ışığında

dışarda gece dar

dışarda gece ayaz

mevsimlerden kış mı, bahar mı belli değil

mum ışığında düşündüm seni, 

mum ışığında sevdim yeniden

belki de yüzüme vuran bir ışıktı

beni sana bağlayan şey, 

ve bir şarkı çalıyordu uzakta, 

seni düşündüm sevgili..

bahar dedim gözlerin, 

oysa bir mum aleviydi, 

ışıtan odamı...

bu masa, bu sigara, bu çay, yalnızlığımdır, 

bir de bahar gözlerin olmasa, 

yanmışlığımdır bu gece

titrek bir mum alevinde 

tükenişimdir..

bahar gözlerin olmasa.....', 'bu gece hayalini almışım karşıma,  mum ışığında dışarda gece dar dışarda gece ayaz mevsimlerden kış mı, bahar mı belli değil mum ışığında dü...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mum-isiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamadım', 'anlayamadim-i-brahim-ugur-toprak-jxz0f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni ne denli çok sevdiğimi, 

Uzak kalınca anladım senden.

Etrafımda bunca insan varken, 

Neden sen? Anlayamadım.

Bilmiyorum ki neydi, 

Beni sana bağlayan.

Ne vardı sende beni çağıran? 

Hala Anlayamadım.

Bir mecnun yarattın, 

Garip bir Adem''den.

Aldın beni benden, 

Ne oldu? Anlayamadım! 

Acayip, garip bir duygu bu.

Bir başkasıydın benim için.

Şimdi, canımsın, herşeyimsin.

Sorma sakın, bu nasıl oldu? 

Çünkü, ben de Anlayamadım.

11.03.99/Perşembe

   19:42/Tekirdağ', 'Seni ne denli çok sevdiğimi,  Uzak kalınca anladım senden. Etrafımda bunca insan varken,  Neden sen? Anlayamadım. Bilmiyorum ki neydi,  Beni...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anlayamadim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizmiş Gözleri', 'denizmis-gozleri-erdal-gisi-6mrtd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sözün ne hükmü var 

Bir gemi kayalıklara çarptı çarpacak...

Nerden çıktı bu deniz, 

   Ne sakat...

Aşkı çöl güneşi bilirdim! 

Denizmiş gözleri 

  Gönlüne inat...

Her şey bir kazayla başladı 

Ansızın düştü ilk damla denize 

  Başladı feryat...

Oysa ben; 

''Karı eksik olmayan 

Torosların gülüydüm 

Terlerdim her sabah 

Günle konuşmak için 

Ovaların rengiydim... 

Kelebekler konardı eğilirdim

  Fakat... 

İçine sığmazsa o hırçın deniz 

Ölümün en zoru denizde olur... 

Damlada mı denizde mi kabahat... 

Temmuz 2002

ankara-hacettepe', 'Sözün ne hükmü var  Bir gemi kayalıklara çarptı çarpacak... Nerden çıktı bu deniz,     Ne sakat... Aşkı çöl güneşi bilirdim!  Denizmiş gözle...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/denizmis-gozleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Lambası', 'sokak-lambasi-mehmet-geckin-gd05b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bak yine akşam oldu

sokak lambası yine sönük

yine çocuklar evlerine çekildi

sessizliğe terkedildi tıpkı yüreğim gibi

yürüyorum tek başıma gözlerim nemli

yağmur yüklü bulut gibi

dokunsalar patlayacak halde

kırılgan vede alıngan

tıpkı elinden oyuncağı alınmış

bir çocuk gibi..

söyleyin sokaklar bilirmisiniz..

ne olduğunu anlayamadan terk edilmenin 

burukluğunu yaşamak...', 'bak yine akşam oldu sokak lambası yine sönük yine çocuklar evlerine çekildi sessizliğe terkedildi tıpkı yüreğim gibi yürüyorum tek başıma gö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Geçkin']::text[], 8.5, '{"poet":"Mehmet Geçkin","poet_slug":"mehmet-geckin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sokak-lambasi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paramiz Yoksa Haysiyetimiz Var', 'paramiz-yoksa-haysiyetimiz-var-i-brahim-sadri-qmpsd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dünya dediginiz abiler

aha benim şu yüreğim kadar

abiler, hayat dediginiz

ne kadar gülebiliyorsak o kadar

boşverin ötesini

sallayın gitsin dünyayi

paramız yoksa da haysiyetimiz var

gözünü seveyim zeytinin, taze ekmeğin, çayın

bakmayın, benim de canım elbet çeker 

şöyle teeryağlı birbuçuk iskender

yine de olsun

kesmedikten sonra selamı bakkal ender

bi de bizim takıma gol olmadıktan sonra

ve de en kıyağından 

ve de en ağırından bi şarkı patlatınca müslüm baba

ne gam ne tasa ne fırtına ne kar

boşverin abiler

paramız yoksa da haysiyetimiz var

şimdi beni iyi dinleyin

canımdan öte ve de

en kıymetli sevdigim muhterem arkadaşlar

durumum ortadadır

hayat bana da sağlamına harbi bi çelme takmıştır.

nevrim dönmüş, midem bulanmış, gözlerim kararmıştır

cümlenize olan bilcümle borç edavatım

üç vakte kadar askıya alınmıştır.

biraz idare edebilirseniz eğer

bir de kahveci Nuri''den rica edebilirseniz

kesmezse tavşan kanı günde üç bardak çayı

elbet bu feleğin paslı çarkı

birgün benim için de döner ve düşeş gelmese de

gelirse eger zarımız mesela bir dubara ve hele de dört cahar

işi kolayladık sayın

ve de inanın ki abiler

paramız yoksa da haysiyetimiz var

dalgalan bakalım kızkulesi önündeki dalgalar gibi kalbim

hayıflan bakalım hiç kimselere belli etmeden geceleri yorganın altında

yazıklan bakalım bu da reva mıdır hayatının baharında bir delikanlıya

hep kısa çöpü ben mi çekeceğim

hep bana mı denk düşecek çarkıfeleğin iflası

hep ben bileceğim başkaları mı kapacak beşyüz milyarı

hep ben sevip eller mi alacak aslıyı leylayı

batsın bu dünya, sende mi leyla, itirazım var yalana dolana

ve ben böyle dolana dolana

ellerim cebimde dudağımda ıslığım, başımda eski alemlerin sarhoşluğu

Orhan Veli tadında basıp voleyi yürüyeceğim hayatın sonuna kadar

hiç tasalanmayın abiler

paramız yoksa da haysiyetimiz var...', 'dünya dediginiz abiler aha benim şu yüreğim kadar abiler, hayat dediginiz ne kadar gülebiliyorsak o kadar boşverin ötesini sallayın gitsin d...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sadri']::text[], 8.5, '{"poet":"İbrahim Sadri","poet_slug":"i-brahim-sadri","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/paramiz-yoksa-haysiyetimiz-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEVDİĞİM', 'sevdi-gi-m-abdullah-karaduman-xdqou', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umudum sensin şu koca dünyada

Sevdiğim, ölesiye taptığım

Aşkından deli, divane olduğum

Kalbimin sahibi biricik yarim

Sevginle ömür kattın ömrüme

Bakışlarınla girdin kalbime

Güzelliğin büyüledi, sevdim seni

Ömrümün sebebi biricik yarim

Acıyı, kederi, hasreti gömdüm kalbime kader diye

Ya sabır, 

Sabır verde bitsin bu hasret

Kavuşayım tek, 

Gönlümün sahibi biricik yarime

Bitecek, bitecek biliyorum

Ama zor, 

Ama çok zor

Bıktım artık hasret çekmekten

Ne olur allahım kavuştur artık

Sevdiğim kadar beni sevene

Karıma...

                               12/03/1994

                               Saat: 02: 30

                               Şırnak.', 'Umudum sensin şu koca dünyada Sevdiğim, ölesiye taptığım Aşkından deli, divane olduğum Kalbimin sahibi biricik yarim Sevginle ömür kattın öm...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevdigim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ', 'dag-abdullah-karaduman-oqvwu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir dağ yamacındayım yine sensiz

Uzayan yollarda hasretin bitişini seyretmek

Ve kavuşmak umuduyla dalıyor gözlerim

Ne bir yağmur damlası

Nede ansızın kopan bir fırtına

Ne doruklarda açan birkaç çiçek

Unutturamaz seni bana.

04/02/1994

Cuma Saat: 10: 38', 'Bir dağ yamacındayım yine sensiz Uzayan yollarda hasretin bitişini seyretmek Ve kavuşmak umuduyla dalıyor gözlerim Ne bir yağmur damlası Ned...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dag-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Dedikleri', 'sevda-dedikleri-mehmet-geckin-fwhb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevdalar ne kadar ucuz

sevgiler belirsiz ve sisli

gizemli bakışlar sırlı hülyalar

duygular karmaşık saflıktan uzak

bir anlık hevesmi gönülden vurmak

onarılmaz yara açar masum sinelerde

rüzgarların adı değişmiş sevda diyorlar

esip götürüyor ne varsa sende 

hazır ol sıkı dur mehmedim

ansızın esiverir poyrazdan da şiddetli

duramaz yıkılırsın kahpe rüzgardan

ne yandan ne zaman eser bilinmez.', 'sevdalar ne kadar ucuz sevgiler belirsiz ve sisli gizemli bakışlar sırlı hülyalar duygular karmaşık saflıktan uzak bir anlık hevesmi gönülde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Geçkin']::text[], 8.5, '{"poet":"Mehmet Geçkin","poet_slug":"mehmet-geckin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevda-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miskin', 'miskin-yavuz-turhan-8zacx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eskiden aşkların yatak odalarında, 

Nacar marka saatler vardı.

      Sevişme zamanlarını duyuran...

Şimdi ise, miskin miskin, 

dijital yankılar...

El yordamıyla, 

Açılamayan gözlerle, 

Sevişmeye kapatılan.', 'Eskiden aşkların yatak odalarında,  Nacar marka saatler vardı.       Sevişme zamanlarını duyuran... Şimdi ise, miskin miskin,  dijital yankı...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/miskin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleme', 'soyleme-yavuz-turhan-wp3tc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söyleme; 

Herşeyi geçersiz kılan, 

Bir yaşam bıraktın bende..

Geberesice bir yaşam..', 'Söyleme;  Herşeyi geçersiz kılan,  Bir yaşam bıraktın bende.. Geberesice bir yaşam.....', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/soyleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adin Toprak Altında Kalsın', 'adin-toprak-altinda-kalsin-huseyin-cayikli-eqz6h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yolculuktan geri döndüm

baktım daglara 

zirvelerdeki karları gördüm

yaratan askına

dua ettim

eve geldim bir lokma yedim

yaratan askına aska adandım

dedim seher vakti aglarım

aglamadım gurulandım kibirlendim

yaratan askına vazgectim

adını ezberledim

bir cuma aksamını düşündüm

tarih vakit saat yaratan askına unuttum

gidişini hatırladım

unut dedim

şimdi gurbetin askını vur

içimdeki türkümdün

yerlere döktün

yaratana sıgındım 

aldırma dedi aldırmadım

dua ettim aldırmayım dedim

belki bir destandı 

dua ettim yazılmadı

adın neydi

adın toprak altında kalsın

geldim baktım sahile 

dayadım sırtımı erenlerin topragına adadım aldırma dedım

aldırmadım

sevdim katıksız kaldım

sevdim imansız bırakıldım

sevdim tanrıya yalvardım

anladım aldırmadı

Adın toprak altında kalsın

Adına yalvardım

yarana sıgındım 

aldırmadı

Adın toprak altında kalsın...', 'yolculuktan geri döndüm baktım daglara  zirvelerdeki karları gördüm yaratan askına dua ettim eve geldim bir lokma yedim yaratan askına aska ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/adin-toprak-altinda-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık', 'sarmasik-yavuz-turhan-69xdk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutku yumağı oluyorbeynimde, 

karşı çıkışların.

          Duvar dibinde, bir sarmaşık gibi

sarmak istiyorum seni kollarıma.

           Binlerce yağmur bulutu gönderiyorum; 

sevgimi yağdırsın üstüne..

           Gülüşünle aydınlansın evren.

           Gün kavuşmasın geceye...', 'Tutku yumağı oluyorbeynimde,  karşı çıkışların.           Duvar dibinde, bir sarmaşık gibi sarmak istiyorum seni kollarıma.            Binle...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sarmasik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tamamlanmış Görünen Noktalar', 'tamamlanmis-gorunen-noktalar-elif-kerenciler-te2yy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yüzün diyorum

eksikliğe geldi

taşırken gözlerinde umutsuz ışığı

yarınlara yeşerecek sevgilere bıraktı 

şimdi yerini

geldin

taşınması zor olan yükünle

hem bana ağır 

hem kendime

bir kaç sayfa mektupsun 

bir kaç okunabilecek şiir

bir de tamamlanmış bir cümlemsin 

şimdilerde sen varsın

yalnız sen...

18: 25    17.07.2002

çarşamba

İzmir', 'yüzün diyorum eksikliğe geldi taşırken gözlerinde umutsuz ışığı yarınlara yeşerecek sevgilere bıraktı  şimdi yerini geldin taşınması zor ola...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tamamlanmis-gorunen-noktalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne çıkar?', 'ne-cikar-ahmet-agdere-9cepa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazı zaman oldu unutmak isterken seni; 

Azdı yaralarım senden uzağa her adımımda...

Düşündüm ki dünya güneşsiz ne yapar? 

Ecel, yastığım iken dizin gelse ne çıkar?', 'Bazı zaman oldu unutmak isterken seni;  Azdı yaralarım senden uzağa her adımımda... Düşündüm ki dünya güneşsiz ne yapar?  Ecel, yastığım ike...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-cikar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tasvir', 'tasvir-fahrettin-ozdemir-wvy7i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl mı? 

Bir siyah boşluk, 

Bir dipsiz körkuyu, 

Yer siyah

Gök kırmızı.

Göğsümde bir yudum nefes, 

Bıçak kadar sivri.

Kulağımda hep

Olmamışların çığlığı.

Tüm şehir, 

Bir sessiz kalabalık.

Buz kesmiş her yan

Sessizliğin soğuğundan.

Boşlukta yürüyen bir cambaz, 

Kör, sağır, dilsiz, akılsız

Efkardan sararmış duvarlarda, 

Pembe kahkaha izleri.

Tek dost gece, 

Işığa teslim olana kadar.

İşte sensizlik, 

Böyle bir şey.', 'Nasıl mı?  Bir siyah boşluk,  Bir dipsiz körkuyu,  Yer siyah Gök kırmızı. Göğsümde bir yudum nefes,  Bıçak kadar sivri. Kulağımda hep Olmamı...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Özdemir']::text[], 8.5, '{"poet":"Fahrettin Özdemir","poet_slug":"fahrettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tasvir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terliyim', 'terliyim-aylin-omer-3pjmj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle sıcak ve öyle terliyimki, 

Dokunsa Tenim sana sanki yapışacak gibiyim.

Terin karışsa terime, 

Sanki bal değmiş tatlanmış olacak gibiyim.', 'Öyle sıcak ve öyle terliyimki,  Dokunsa Tenim sana sanki yapışacak gibiyim. Terin karışsa terime,  Sanki bal değmiş tatlanmış olacak gibiyim...', ARRAY['Türk Edebiyatı','Şiir','Aylin & Ömer']::text[], 8.5, '{"poet":"Aylin & Ömer","poet_slug":"aylin-omer","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/terliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı...', 'olmadi-binay-donmez-j0rf8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölmeyi denemedim kaybolan saatlerimde

Kimi zaman zaten öldüm

Vazgeçmeyi denemedim hayattan

Yaşam benden zaten vazgeçti

Gelir geçer dedim

Kışlar bahara erer ince ince

Zamanı yakalayamadım

Yollar o kadar da yakınken 

Git git bitmez dedim

Aklımdan dönmeyi denedim

Yine olmadı karanlıklara gömüldüm

Karşımda dururken seni sevmeyi

Aynaya bakarken kendimi bilmeyi

Olmadı, yine olmadı

Beceremedim sevmeyi...', 'Ölmeyi denemedim kaybolan saatlerimde Kimi zaman zaten öldüm Vazgeçmeyi denemedim hayattan Yaşam benden zaten vazgeçti Gelir geçer dedim Kış...', ARRAY['Türk Edebiyatı','Şiir','Binay Dönmez']::text[], 8.5, '{"poet":"Binay Dönmez","poet_slug":"binay-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olmadi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hızla, Yavaş Yavaş...', 'hizla-yavas-yavas-binay-donmez-y7072', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşlerim kanatsız uçuyor şimdileri

Issız, yalın ayak yürüdüğüm sahiller

Ayaklarıma dolanıyor yavaş yavaş

Akmış saydığım tüm gözyaşlarım

Kızdırıyor beni

Dün gibi acıtırken geçmişin tozları

Su serpilmiş gibi açıyor güllerim

Ve sen eskiyorsun gözlerimde

Hızla, yavaş yavaş...', 'Düşlerim kanatsız uçuyor şimdileri Issız, yalın ayak yürüdüğüm sahiller Ayaklarıma dolanıyor yavaş yavaş Akmış saydığım tüm gözyaşlarım Kızd...', ARRAY['Türk Edebiyatı','Şiir','Binay Dönmez']::text[], 8.5, '{"poet":"Binay Dönmez","poet_slug":"binay-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hizla-yavas-yavas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-zekeriya-oz-lq40t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Garip çeker cefasını

Göremez hiç vefasını

Gider ellerin gönlüne

Eller sürer sefasını', 'Garip çeker cefasını Göremez hiç vefasını Gider ellerin gönlüne Eller sürer sefasını...', ARRAY['Türk Edebiyatı','Şiir','Zekeriya Öz']::text[], 8.5, '{"poet":"Zekeriya Öz","poet_slug":"zekeriya-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/garip-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garson', 'garson-omer-erdem-s4ozl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O zamanlar

Garsondum ben Samatyada

Ayağımda dallas marka pabuçla

Dönülmeyecek kadar uzakta

Ve bir akşam telefonda

''Cumhuriyet''dedim beni kaybettin

Sen artık Ankarada Mekteb_i Hukukta

Sesimi rüzgar olarak sakla

O zamanlar

Garsondum ben Samatyada', 'O zamanlar Garsondum ben Samatyada Ayağımda dallas marka pabuçla Dönülmeyecek kadar uzakta Ve bir akşam telefonda ''Cumhuriyet''dedim beni kay...', ARRAY['Türk Edebiyatı','Şiir','Ömer Erdem']::text[], 8.5, '{"poet":"Ömer Erdem","poet_slug":"omer-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/garson-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lal', 'lal-omer-erdem-sry3z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen nesin ki yanarsın

Sisten bir kafeste lal

İçlenişin gül yağmuru, nar

Karışır kalbe vuran sese her bahar

Dünya evvelinde sislerin de bir dili var

Ağır, dalgalı ve sessiz

Ömrün gövdesine kaybolarak dokunurlar

Bense...

Büyük bir merak yüzünden indim bu bahçeye

Ey sis bürü beni al sinene sar', 'Sen nesin ki yanarsın Sisten bir kafeste lal İçlenişin gül yağmuru, nar Karışır kalbe vuran sese her bahar Dünya evvelinde sislerin de bir d...', ARRAY['Türk Edebiyatı','Şiir','Ömer Erdem']::text[], 8.5, '{"poet":"Ömer Erdem","poet_slug":"omer-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/lal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üsküdar', 'uskudar-omer-erdem-5qob4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'üsküdar

üsküdar asyadır çine kadar

her kış

bıraksa da köpük saçlı kızlarını

kıyıya

öfkeli bir yağmurla iner rüzgar

mihrimah güneş saati

yanından ince dar bir merdiven uzar

soğuk

ve dönmez bir kilit çocuk kütüphanesi

önünden insanlar yürür ve susar

şemsipaşa

ceviz bir cami, demirinden

yan gözle cihangire bakar

demişti ki tanpınar

üsküdar uçarsa gider istanbul

yürüyemez sokaklarında çocuklar

üsküdar asyadır çine kadar', 'üsküdar üsküdar asyadır çine kadar her kış bıraksa da köpük saçlı kızlarını kıyıya öfkeli bir yağmurla iner rüzgar mihrimah güneş saati yanı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Erdem']::text[], 8.5, '{"poet":"Ömer Erdem","poet_slug":"omer-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uskudar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelimsiz', 'celimsiz-atilgan-alemdar-uyf4t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sana değil sevmeye aşıktım

ve seni sevdim aşkı değil

döne döne yoruldum

bu çelimsiz ömür içinde

kırdım seni cam gibi, buz gibi

kumdan bir heykel gibi döktüm yüzünü

şimdi hiçbir bahane kurtarmıyor

ne kalbimi ne de ömrümü

sürüyorum kendimi aynalara

aynalara artık çamur gibi akıyorum

her ne varsa yeryüzünde 

san ki senmişsin gibi bakıyorum

her ne varsa gemilerden kuşlara

böcekler çiçekler sigaralar

ve denizlerden dağlara

her ne varsa seni terk ediyor bir daha

zalim oldum cahil oldum

aşkı sevmeyi birbirine kattım

karıştırdım kendimle seni

ve bıraktım kendimi sende

faydası yok erimenin çürümenin

zararı da yok 

ben öleyim ey uzak kumrum

dayanamıyorum bu boşluğa

bu çelimsiz ömrün hiçbir tarafında

beni barındıracak bir kuytu yok

ve cigaram da yok', 'sana değil sevmeye aşıktım ve seni sevdim aşkı değil döne döne yoruldum bu çelimsiz ömür içinde kırdım seni cam gibi, buz gibi kumdan bir he...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/celimsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-atilgan-alemdar-tovqu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir iyi haber verdi bana hayat bir de kötü

kötüyü sordum iyi haber yok dedi

iyiyi soramadım

iyiyi sordum kötü haber yok dedi

bu hayatı ben anlayamadım

dalga mı geçiyor, kafa mı buluyor

yokmuş gibiyim diyeceğim

devasa bir derdim var

demek ki yaşıyorum varım

hani varım desem

bir bilen var mı

hiç mektup yazıyor muyum

...hiç', 'bir iyi haber verdi bana hayat bir de kötü kötüyü sordum iyi haber yok dedi iyiyi soramadım iyiyi sordum kötü haber yok dedi bu hayatı ben a...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mektup-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genç Kalan Duygularım', 'genc-kalan-duygularim-salih-ozalasan-vebar', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ilık bir yaz akşamı savrulup giden yüreğim

Bilmem hangi akşamın sabahında gülecek

Saçlarımın dalga dalga perçeme dönmüş akları

Birgün korkarım aynalara bakmaya küsecek

Yüreğime bir korku yalnızlığın ilk adımı

Korkarım tüm sevenlerim beni terk edecek

Sesimde inanılmaz bir titreme

Korkarım dilim sana sevdiğini söyleyemeyecek

İçimde saklı kalacak tüm duygularım

Gecelerim kabus bölünecek uykularım

Bedenime isyan edip şahlanacak

Sevgiye hasret genç kalan duygularım

Ve ben bedenimle ruhum arasında

Bir yaprak gibi savrulup gideceğim

Belki bir ıssız köşe başında sarhoş

Kimbilir belkide yapayalnız öleceğim

17-07-2002 Saat 23.45', 'Ilık bir yaz akşamı savrulup giden yüreğim Bilmem hangi akşamın sabahında gülecek Saçlarımın dalga dalga perçeme dönmüş akları Birgün korkar...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/genc-kalan-duygularim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana ve Yaşama', 'sana-ve-yasama-hakan-rodop-32qea', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bırakıyorum kendimi boşluğa

salınarak ucundan yaşamın

meraktandır güzelim bu ilgi

sana ve yaşama

ve nasıl ki bir güvercin

salarsa kendini boşluğa

çarparsa duvarlarına boşluğun

işte güzelim böyle bir ilgi

sana ve yaşama

devam edecektir, etmelidir

sonuna kadar bu merak

hasrettendir güzelim bu ilgi

sana ve yaşama', 'bırakıyorum kendimi boşluğa salınarak ucundan yaşamın meraktandır güzelim bu ilgi sana ve yaşama ve nasıl ki bir güvercin salarsa kendini bo...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-ve-yasama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfke ve Umut', 'ofke-ve-umut-hakan-rodop-x3pss', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bakışın, sessizliğin

seviyorum seni kömür gözlüm

bana tomurcuklarını saçarak gel

bana en güzel giysini giyerek

süslen de gel

gülüşünü anımsat bir kez daha

saçlarını savur istersen dağıt

öpüşürken no’lur elimden tut

gör bak! sevginden böyle sıcağım

benim adım öfke ve umut

seninki neydi kömür gözlüm?', 'bakışın, sessizliğin seviyorum seni kömür gözlüm bana tomurcuklarını saçarak gel bana en güzel giysini giyerek süslen de gel gülüşünü anımsa...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ofke-ve-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Türküsü', 'ayrilik-turkusu-hakan-rodop-su1id', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle yine sürecek bu gece

Güneşi hiç tanımamış olsan da

Al koynuna hançeri sabah için

Sapla suratına ayrılığın demiştim

Ama yaşam budur güzelim

Süprizler olun ansızın

Birikir damar damar

Patlar gün gelir

Biz hiç ayrılmadık ki

Niye söylediğim türkü yalan olsun

Sanki şart mıdır sevmek

Hiç olmaz mı ayrılık

Sorulmaz mı ölüm neyi anlatacak

Kalemim bir daha acı yazmayacak', 'Seninle yine sürecek bu gece Güneşi hiç tanımamış olsan da Al koynuna hançeri sabah için Sapla suratına ayrılığın demiştim Ama yaşam budur g...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrilik-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudakların İsyanı', 'dudaklarin-i-syani-hakan-rodop-t38mr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1.

Geceleyin geldi ansızın

Haberim bile yoktu

2.

Yatağımda sabah çırılçıplak

Buldum bir kadını

Dudaklarından yalnızca bir ad

Geriye kalan

3.

Bu öykünün başlangıcıydı

Geceydi

Sonra

Sabah

Bu öykünün bitişiydi

Buysa başlangıcı

Dudağından yalnızca bir öpücük

Geriye kalan

4.

Artık isyandır beklemek

İsyandır gelecek

İsyandır dudaklar', '1. Geceleyin geldi ansızın Haberim bile yoktu 2. Yatağımda sabah çırılçıplak Buldum bir kadını Dudaklarından yalnızca bir ad Geriye kalan 3....', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dudaklarin-isyani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalları Yeşil Bir Kadın', 'dallari-yesil-bir-kadin-hakan-rodop-ayvh2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zamandır içimde biriken

Ve söylenmesi gereken notları yazıyorum

İşte o zaman bir kadın geliyor geçmişten

Dalları yeşillenmiş, 

Ya da göğü şafaktaki gibi kızarmış

                                          bir ülkeden

Bir kadın geliyor aklıma

Aniden ürperiyor içim

Acaba Öripides’in kahramanlarının da içi

Böyle mi ürperirdi 

Böyle mi titrerdi

Ve birçok soru var sorulması gereken

Avcılara, umutları kıranlara, boşluğa

Yaşam aramak mıdır hazineyi

Yeşil dallı ve kızıl göklü bir ülkenin

Ütopyasını, 

Ya da Ütopyamızı yazıyorum

Dalları yeşil bir kadın geliyor gelecekten! 

-	Yakışmıyor size ağlamak çocuklar', 'Ne zamandır içimde biriken Ve söylenmesi gereken notları yazıyorum İşte o zaman bir kadın geliyor geçmişten Dalları yeşillenmiş,  Ya da göğü...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dallari-yesil-bir-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni', 'bekle-beni-hakan-rodop-gj3yh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ya elim pembe karanfillerle dolu

ya da kucağımda bir yığın yiyecek

geleceğim

ya avucumda senin için bir yüzük

ya da dudağımda bir çift tatlı söz

geri döneceğim

ya güneş ışınlarını vurmaya başlamadan

ya da ay gökyüzünde salınırken

seni arayacağım, bulacağım

gözlerimde belki bir garip ışıltı

sevinç, coşku, kurtuluş müjdesiyle

belki de bir sabah özgürlükte

çıkıp geleceğim ve öpeceğim yarınlarımızı

bekle beni, bekle......', 'ya elim pembe karanfillerle dolu ya da kucağımda bir yığın yiyecek geleceğim ya avucumda senin için bir yüzük ya da dudağımda bir çift tatlı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bekle-beni-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış İçin', 'baris-i-cin-hakan-rodop-i28nm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nasılsa ağladım bugün

berrak bir barış için

yoksa düşmüydü

gözyaşları, kanlar

ağladım bugün nasılsa

doyasıya bir barış için', 'nasılsa ağladım bugün berrak bir barış için yoksa düşmüydü gözyaşları, kanlar ağladım bugün nasılsa doyasıya bir barış için...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/baris-icin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin İkisinde', 'gecenin-i-kisinde-hakan-rodop-jprkd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'saat gecenin ikisi

sağımda solumda senin hayalin

berrak bir gece

siz ve kir unutulmuş

anılar gecenin karanlığında

bir balyoz gibi iniyor tepemize

kaldırmadan düşüyor

o güzelim başın

ay, karanlık ve gecede

şeytanlar, sen ve çanlar

gecenin ikisinde

sanki düğün var

halaylar, valslar, horonlar

ama ayrılık var

bir ay karanlığında ve gecede

yetinmek zorundayım resminle', 'saat gecenin ikisi sağımda solumda senin hayalin berrak bir gece siz ve kir unutulmuş anılar gecenin karanlığında bir balyoz gibi iniyor tep...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecenin-ikisinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düş', 'bir-dus-aydin-ozturk-ha9bv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzansam zerdali dalı

tarlalar bir yeşil halı

papatyalar beyaz, sarı

sarılsa baharlar boynuma

dikenli teller arada

süngüler geçik namluya

soluk mavi akşamlarda

bir hüzün dolanır ince', 'Uzansam zerdali dalı tarlalar bir yeşil halı papatyalar beyaz, sarı sarılsa baharlar boynuma dikenli teller arada süngüler geçik namluya sol...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-dus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumartesi Anneleri', 'cumartesi-anneleri-aydin-ozturk-cn1oa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'eğer yolunuz beyoğluna düştüyse

ve günlerden cumartesiyse

zaman da öğlene yaslanmışsa

yürüyüp galatasaray lisesinin

tam da önüne geldiyseniz

önce kalkanlı polisleri görürsünüz

kayışlarını zorlayan kurt köpeklerini

panzerleri, dizilmiş çelik kaskları

kiminiz hızla yürür geçersiniz

başınıza birşey gelsin istemezsiniz

kiminizin içi burkulur, onları görürsünüz

cumartesi annelerini

ellerinde yükselen kayıp fotoğraflarını

çığlıkların fotoğrafı olur mu demeyin

dönüp de bakın, gözlerindeki küllerde

sıcak sakladıkları oğul özlemlerine', 'eğer yolunuz beyoğluna düştüyse ve günlerden cumartesiyse zaman da öğlene yaslanmışsa yürüyüp galatasaray lisesinin tam da önüne geldiyseniz...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cumartesi-anneleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanır Yürek', 'dayanir-yurek-aydin-ozturk-aus33', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bilirim dayanır

dayanır bu kanlı vahşete yürek

yürek falakada

yürek ceylan döşeli

yürek iki büklüm

boylu boyunca

karanın koynundaki kuytuda

şarapnellerin parçaladığı

salınmasın diye çığlıkları

kan kırmızısı karanfillerde

yedi kat yerin altında yürek

yağız bir köylünün önceğinde

ve dudağında karabasanın

özüm özüm toprağa katılan

ve her nazlı seher yeliyle

uzak hasretlerime

elvan elvan savrulan yürek', 'bilirim dayanır dayanır bu kanlı vahşete yürek yürek falakada yürek ceylan döşeli yürek iki büklüm boylu boyunca karanın koynundaki kuytuda ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dayanir-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabesk', 'arabesk-haydar-ergulen-fhg24', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gece sevecen bir eleştirmenin uykusu kaçtı

günlüğüne genç ozanlar için şunları düştü

- bu çocuklar hiç minibüse binmemiş belli

ne de çalgılı kahvelerde sabahlamışlar

yine de bir ağız var ki şiirlerinde

yeniyetme şoförlerden külhani', 'gece sevecen bir eleştirmenin uykusu kaçtı günlüğüne genç ozanlar için şunları düştü - bu çocuklar hiç minibüse binmemiş belli ne de çalgılı...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/arabesk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atlı', 'atli-haydar-ergulen-jhw5w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Atını uzun sür, yola bağlanma, 

yollar kısa, zamana sür atını, 

peşindeki ölümü yorulur sanma

bir hançer sırtına kavuşur gibi

kavuşur ölüm de atlıya: - Göğe

doğru çevirin şunun çizmelerini! 

Hangi hana bağlasan bir oda

bulamazsın içinde gezdirdiğin yalnızca

bulsan viran ömür baksan kör kuyu

zaman zaliminin yüklediği korkuyu

yedeğine vur ve sür üstüne atını: 

Güneş ki maviyken göğe bağlıdır

o bile eğlenmedi bu siyah kasabada

onun kaybettiği çölde yol aranır mı

nice gölge yerle bir olur, çöl de

usanır gezginken eskittiği yollar da; 

ne han kalır atlıya ne yalnıza

kılavuz, atını uzun sür, ölümdür

hepimizin çobanı bu sürek avında

ölümü baştan çıkarma, hem gençsin daha

Atını uzun sür, hem zaman var daha.', 'Atını uzun sür, yola bağlanma,  yollar kısa, zamana sür atını,  peşindeki ölümü yorulur sanma bir hançer sırtına kavuşur gibi kavuşur ölüm d...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/atli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Funda İçin', 'funda-i-cin-haydar-ergulen-ljchg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'haylaz bir serçenin sesinden ısındım bu ilkyaz göğüne

eskimeyen bir güneşin ışıklarıyla tutuştu gövdem

kadınım o çocuk yüreğin nasıl yoksul komadıysa hayatımı

ela gözlerin de birer yıldızdır bu lacivert geceye düşen.', 'haylaz bir serçenin sesinden ısındım bu ilkyaz göğüne eskimeyen bir güneşin ışıklarıyla tutuştu gövdem kadınım o çocuk yüreğin nasıl yoksul ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/funda-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin', 'gelin-haydar-ergulen-p892j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gelinin yüreği karbeyaz kanaviçe

güvey hazreti hamza suretinde

birazdan güreşe soyunacak

yüzü olmayan bu dilsizin üstünde', 'gelinin yüreği karbeyaz kanaviçe güvey hazreti hamza suretinde birazdan güreşe soyunacak yüzü olmayan bu dilsizin üstünde...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gelin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişim', 'degisim-necat-cavus-1nug3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey geceyi renk alan yürek bu ne sallanış

Gözler, sabaha da vakte de hayır açılmamış

Uyuyorsa bilinir canlılığı, yoksa ölü

Yılan ki görür güneşi verir gömleğini

Yılan ki iyi ayırır mevsimleri

Ya ilk rüzgarla ya ilk düşen karla

İnsan var uyuyan dokunmayın kalkar da

Kesin azap küpüne çevirir sizi

Cin çarpar gibi çarpmasa da

Siz yine dokunun dokunun ona

İnsan değişmektedir hala', 'Ey geceyi renk alan yürek bu ne sallanış Gözler, sabaha da vakte de hayır açılmamış Uyuyorsa bilinir canlılığı, yoksa ölü Yılan ki görür gün...', ARRAY['Türk Edebiyatı','Şiir','Necat Çavuş']::text[], 8.5, '{"poet":"Necat Çavuş","poet_slug":"necat-cavus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/degisim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz ve Ateş', 'deniz-ve-ates-necat-cavus-5punt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deniz yanıyor akşam ışıklarında

Fırtınasız dalgalanmaların sularında

Bir oyun olmalı öyle sanmalı ya da

Çünkü ne deniz yanar gerçek

Ne fırtınasız dalga bu sularda

Sen gelmezsen bu denizde

Ne ateş kalır ne de oyun

Yabancı! aşkı gözlerimden anla, derim

Bir hayatın varlığı nedir, nedir anlamı

Bu aşkın acısını sızısını

Kahrını kahrını bin can çekerim', 'Deniz yanıyor akşam ışıklarında Fırtınasız dalgalanmaların sularında Bir oyun olmalı öyle sanmalı ya da Çünkü ne deniz yanar gerçek Ne fırtı...', ARRAY['Türk Edebiyatı','Şiir','Necat Çavuş']::text[], 8.5, '{"poet":"Necat Çavuş","poet_slug":"necat-cavus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/deniz-ve-ates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek', 'ekmek-necat-cavus-a7jrc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Apartman duvarlarına han kapılarına

Atıldı mı ekmek, atılsa

En yaman çağrıdır açlığa

Açlığa ve yokluk sınavına', 'Apartman duvarlarına han kapılarına Atıldı mı ekmek, atılsa En yaman çağrıdır açlığa Açlığa ve yokluk sınavına...', ARRAY['Türk Edebiyatı','Şiir','Necat Çavuş']::text[], 8.5, '{"poet":"Necat Çavuş","poet_slug":"necat-cavus","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ekmek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem Yarışçısı', 'cehennem-yariscisi-erol-cankaya-vsagj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tam gaz uçuyorum saatte 180''le

Beni yakalayamazlar beni yakalayamazlar

Porche dizayn gözlüklerimin gerisinde

İki adet madeni göz bebeği.

Bir rock ilahıyım kendine tutkun

Bir cd koyuyorum hemen değiştiriyorum

Dikiz aynasından bakınca çocukluğum

Büyük düşünmüşüm motorum 3000 cc

Bir bir solluyorum önümdekileri.

Gökyüzü pırıl pırıl Volvo mavisi

Saate bakıyorum Rolex''i beş geçiyor

Çimenler boydan boya Benetton yeşili

Bu yıl farklı bir tatil yapmalıyım

O yalı benim olmalı Boğaz''la öpüşen

Çek ya da nakit, döviz ya da kredi kartlarımla

O kadın benim olmalı fiyatı neyse

Büyük düşünmeliyim kendimi aşarcasına

Beni var kılan bir yarış bu

To be or not to be

That is the question.

Tam gaz uçuyorum rüzgarım saatte 220

Beni yakalayamazlar, they can''t catch me.

Akşam olmadan kendime ulaşacağım

Yeni bir tv alacağım 140 ekran

cd çoktan out, şimdi in DAT.

Üstelik 1200 watt olmalı kolonların gücü.

İçimdeki çığlığı bastırmak için.

Durun, biri sokuluyor arkamdan

Hıyar! Tam yetiştiğini sandığı an

Turbolarım devrede, uçuyorum.

Fakat birini geçsem önümde binlercesi

Otomatik simsiyah camların gerisinde

Cıs-çımlarında müzik setimin

Zamanın dışında ve kayboluyorum.

Cesur olmalıyım bir borsa oyuncusu kadar

Büyük düşünemliyim, beygir gücüm 320

To be or not to be, that is the question.

Çünkü ensemde habire yaklaşan birileri.

Tam gaz uçuyorum rüzgarım 250

Porche dizayn gözlüklerimin gerisinde

İki adet Betacam objektifi

Füsun mu Pınar mı, Maide mi Rita mı? 

Ferrrari mi Porche mi, Mazda mı Rover mi? 

Birden bir Lamborgini fırlıyor sağımdan

Egzoz dumanıyla kahroluyorum

Off ne yapsam ne yapsam...

Yeni bir araba mı alsam yoksa mermi mi? 

...

Belki de anlamaktan korkuyorum

Ne mermi gibi bir araba ne jet

Benim bir mermiye ihtiyacım var aslında

Yeniden var kılmak için kendimi

Başka bir uzayda', 'Tam gaz uçuyorum saatte 180''le Beni yakalayamazlar beni yakalayamazlar Porche dizayn gözlüklerimin gerisinde İki adet madeni göz bebeği. Bir...', ARRAY['Türk Edebiyatı','Şiir','Erol Çankaya']::text[], 8.5, '{"poet":"Erol Çankaya","poet_slug":"erol-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/cehennem-yariscisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Ufuklar İçin', 'uzak-ufuklar-i-cin-erol-cankaya-75avt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürek de dolunup bitince şehrin vakti

Sokağa çıkılıyor kimseyi görmemek için

Oysa yazdır, tutuştuğu görülür bir gülün

İnsan kaç umut okşar her seher belki

Sözlerin çırpınırken kafanla yürek arasında

Şehir eskir çünkü vakit kararmaktadır.

Yazık ki yaz başlıyor vakit tükenirken

Gözlerinde bir ufuk ki çağrıp durur bu yüzden

Bir vakit ki bomboştur en dolu anlarında

Sözler vardır, yaralı en sağlam yerlerinden

Sözler ki kansızdır o sıcak dudaklarda

Gözlerinde bir ufuk ki çağrıp durmaktadır.

Öyleyse varacaksın sızlayıp duran ufka

Ya bildiğin, bileklerinde vuran yerler

Bastığın bir toprağın o sabah esintisine

Ya da birini tanımak için o uzak kıyılarda

O zaman kardeşim bırakıp gideceksin

Çünkü vakit incelmiş kalbin dışarlardadır.

Elbet inatla kavrasan iyiydi bilmen fakat

Çok denedin, kaydı parmakların işte

Çaresiz bırakıp gideceksin o toprağın koynuna

Hele bu sözler kendini söyeltiyorsa böyle, 

Sanki gökte mavilik bile seyreyliyorsa yürü, 

Savul bu çalgın yürek ışısın oralarda, 

Çünkü o ufuk ki daha sözlerde parlamaktadır.', 'Yürek de dolunup bitince şehrin vakti Sokağa çıkılıyor kimseyi görmemek için Oysa yazdır, tutuştuğu görülür bir gülün İnsan kaç umut okşar h...', ARRAY['Türk Edebiyatı','Şiir','Erol Çankaya']::text[], 8.5, '{"poet":"Erol Çankaya","poet_slug":"erol-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uzak-ufuklar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlı', 'delikanli-gunel-altintas-9jel7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ey umursamazlık

ey açlık

şimdi ben sizi bir odaya kapatsam

hanginiz yıkar duvarı

hanginiz yıkar duvarı

ey bu şiirdeki dinamit

ey açlık

durmadan kanımızı bulandırıyorsun

önümüzdeki gecikmiş zamanı

arkamızda ekşi ve pörsük bırakmak için

kanımızı daha çabuk

daha çabuk bulandırıyorsun

çünkü kanımız bulanınca yüzümüz iğneden geçer

bütün yoksullar gözlerimizin önünden geçer

geçer ve birikir geceye

gece bir delikanlıdır artık

köylerde ve kenar mahallelerde oturur

öyle sessiz oturur ki bazı uykuları kaçırır

bekçilerin polislerin düdüğünü öttürür

nöbetçilerin nöbetini değiştirir

çeker günü gündüzü kulağından

önümüze getirir

gece yağız bir delikanlıdır

geçer açlığın kışlasından

ağzı

alıcı kuş ağzı', 'ey umursamazlık ey açlık şimdi ben sizi bir odaya kapatsam hanginiz yıkar duvarı hanginiz yıkar duvarı ey bu şiirdeki dinamit ey açlık durma...', ARRAY['Türk Edebiyatı','Şiir','Günel Altıntaş']::text[], 8.5, '{"poet":"Günel Altıntaş","poet_slug":"gunel-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/delikanli-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hançerin İşi', 'hancerin-i-si-gunel-altintas-pe9oy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hançer göğe baktı gök yok

dönüşüp kaleme

kurşuna çalarsaate

kara salkılar gibi hızla

hızla dağıldı kalabalığa

dağıldı kalabalığa hançer

gök şiir aşk

dağıldı hançerle beraber

bir gün bir çarşaf gibi

gerilirse gök

yağarsa şiir

bu hançerin işidir', 'hançer göğe baktı gök yok dönüşüp kaleme kurşuna çalarsaate kara salkılar gibi hızla hızla dağıldı kalabalığa dağıldı kalabalığa hançer gök ...', ARRAY['Türk Edebiyatı','Şiir','Günel Altıntaş']::text[], 8.5, '{"poet":"Günel Altıntaş","poet_slug":"gunel-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hancerin-isi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-hakan-rodop-nhtbm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'durmadan akıyor zaman

gerisine hiç aldırmadan

öyleyse dostlarım, 

savunmak gerek bu kaleyi

çünkü yaşamın aynasıdır

şiirin kendisi', 'durmadan akıyor zaman gerisine hiç aldırmadan öyleyse dostlarım,  savunmak gerek bu kaleyi çünkü yaşamın aynasıdır şiirin kendisi...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/siir-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçgenler', 'ucgenler-fergun-ozelli-p3kea', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bıçkın bir süvari, adını çoktan unuttunuz değil mi? 

gözünü kapayıp da bıyıklarıyla gülümseyince

hayat, feryat bir coğrafyada padişah zimmeti

kim bilir, kaç mecidiyeye satıldı kimsesiz cesetler? 

bir fes bir kalpağa dönüşebilirdi, ya uçuşan saçları? 

cinnetin şehvetini yudumlayan gururlu narsis

korkuyla örtmeseydi boşluğuna delinmiş postalını

kopmuş tespih tanelerinin peşindeydi gizli düşleriniz

fesleğenler, begonyalar gidince paslanan cumbalar, ah vicdan! 

zeytinyağlı, limonlu radika lezzetinde uzak bir yıldız

geceleri, mutlaka olmayan mandolin sesleriyle uyanmıştınız

trenler katar katar kol değneği tükürüyordu yüzünüze

sökülmüş ömürler bahçesinde, nasıl da sığındınız sislere

nalların taşlardan söktüğü kıvılcım yangını

acımdan vurdu usturayı ak sakallı güvercine

mis kokulu bahçelerden sonsuz bir çöle yürüdünüz yalınayak

savaş artığı divanlarda gerinen yamalı kaftan, ne garip! 

sahilde yurtsuz bir nargileye uzatmıştı kollarını

ruhunu sıkan kravat, o vicdan azabı şapka nasıl da kıllı

itiraf edin! az zamanda yırttınız hoş nakışlı dağları

kırılmış tüfekleri özleyen bir kadeh rakıydım alt tarafı

                                  yüzünüzü yalayıp geçen serin bir rüzgar

elektrik tellerine tünerken can havliyle, sordum işte: 

                                                 toprağın sahibi olur mu? 

ah! ayaklarımı bastığım yer; gövdem, yurdum

dedemin pos bıyıklarıyla gömüldü zavallı pişekar', 'bıçkın bir süvari, adını çoktan unuttunuz değil mi?  gözünü kapayıp da bıyıklarıyla gülümseyince hayat, feryat bir coğrafyada padişah zimmet...', ARRAY['Türk Edebiyatı','Şiir','Fergun Özelli']::text[], 8.5, '{"poet":"Fergun Özelli","poet_slug":"fergun-ozelli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ucgenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-hakan-rodop-1xxq8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ardından baharın dalları

üstümüze yağıyordu

seni aradık, bulduk – gerçek

o ovanın bağrında yanıyordu

               bir zamanlar sen de beni sevmiştin

               ve ayrılık sözü

               yürekte yalandı

isterdim karanlığı görmesin yüzümüz

o kötü tutuşan dalları ve çimenliğiyle

içindeki her türlü haşaratıyla

gözümüz görmesin hiç

                  gel, sesini duyar gibiyim

                  tıkanıyorum

                  yüreğim durmadan önce gel.', 'Ardından baharın dalları üstümüze yağıyordu seni aradık, bulduk – gerçek o ovanın bağrında yanıyordu                bir zamanlar sen de beni...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gel-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Kapı', 'beyaz-kapi-hakan-rodop-e65ya', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bıraksalar ovalara dağlara sığmayacağım

karanlığı seviyorum yüzler açık yalan yok

haydi gel dostum ol seveceksin beni

gereği yok birbirimizi anlatmaya

güçsüzlüğümüzü göstermeye

kıskançlık gösterisine

sarılırsak insanlık ülküsüne

vızgelir korkunç rüzgar

çünkü kötüler olsa olsa bir piyondur

korkma onlardan, 

haydi gir şu beyaz kapıdan', 'bıraksalar ovalara dağlara sığmayacağım karanlığı seviyorum yüzler açık yalan yok haydi gel dostum ol seveceksin beni gereği yok birbirimizi...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/beyaz-kapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçeye Akan Pencere', 'bahceye-akan-pencere-kubilay-koseoglu-kkehv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sigaram

Karanlıkta

Yasını tutuyor

Yağmura yakalanan

Ateşböceklerinin.', 'Sigaram Karanlıkta Yasını tutuyor Yağmura yakalanan Ateşböceklerinin....', ARRAY['Türk Edebiyatı','Şiir','Kubilay Köseoğlu']::text[], 8.5, '{"poet":"Kubilay Köseoğlu","poet_slug":"kubilay-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bahceye-akan-pencere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırgınlık', 'kirginlik-kubilay-koseoglu-xq4hx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hanımelinin saçları ateşböcekleriyle

doluydu. Küçük bir yastık daha koydu

pervaza. Beklemeye koyuldu. Ayak

uydurmaya çabalıyordu, yüreğinin

vuruşlarındaki sese, ağacın yanıp

sönüşlerindeki sessizlik.

                                      Sabah

Karga, çıplak bir dalda öttüğünde, 

''Haber? '', dedi, yaşlı kadın; onun

kolu duruyordu sabun köpükleriyle

yastığın üzerinde, gelmeyen kızın

yaşgününü unutmuş ve bu nedenle

Yaz''ı yıkmış başının yerine.

Aynanın köşesinde

gözbebekleri büyüyen resim, 

ben seni kendim kadar sevdim.', 'Hanımelinin saçları ateşböcekleriyle doluydu. Küçük bir yastık daha koydu pervaza. Beklemeye koyuldu. Ayak uydurmaya çabalıyordu, yüreğinin ...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Köseoğlu']::text[], 8.5, '{"poet":"Kubilay Köseoğlu","poet_slug":"kubilay-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirginlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurda Bir Kadın', 'yagmurda-bir-kadin-kubilay-koseoglu-u73ql', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kadın yağmuru geçip gidecek

Anılar anılarla silinir belki

Kırgınlığı yağmurda yalnız olmasından

Aşk kimleri birleştirmiş ki? 

Umut tümüyle kendini vermez

Sevinç kanat verir coşkuda unutuşla

Tam ağlarken söylemeliyiz sevdiğimizi

Ne çıkar giden birini aşmamışsa?', 'Kadın yağmuru geçip gidecek Anılar anılarla silinir belki Kırgınlığı yağmurda yalnız olmasından Aşk kimleri birleştirmiş ki?  Umut tümüyle k...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Köseoğlu']::text[], 8.5, '{"poet":"Kubilay Köseoğlu","poet_slug":"kubilay-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmurda-bir-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yontu', 'yontu-kubilay-koseoglu-cvfka', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başımda duruyorsun

Mavi gözleri olan yontu

Gömüt taşı yüreğimin-

Alınyazında adım yazılı.', 'Başımda duruyorsun Mavi gözleri olan yontu Gömüt taşı yüreğimin- Alınyazında adım yazılı....', ARRAY['Türk Edebiyatı','Şiir','Kubilay Köseoğlu']::text[], 8.5, '{"poet":"Kubilay Köseoğlu","poet_slug":"kubilay-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yontu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Adı', 'gulun-adi-hakan-rodop-moug8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamanların birinde

Artuk Hakanı

hastalanınca kızı

söyleyince hekimleri

veriyor emrini

gidin bulun gülçiçeğini

7 gün, bir ay,70 gece

aranıyor gülçiçeği

Diyarbakır’ın kuraklığında

bulunamayınca salınıyor 

Anadolu’ya haberler

no’lur getirin gülçiçeğini

veririz her istediğinizi

duyunca çobanın biri

Isparta’da buluyor çiçeği

gül getirilince Diyarbakır’a

kurtuluyor çiçek kız

Artuk Hakanı sevinçli

verince çobana armağanını

diyor ki çoban; 

-	kalsın! 

yeter ki, bu çiçeğin adı

                              hatırlansın.', 'Zamanların birinde Artuk Hakanı hastalanınca kızı söyleyince hekimleri veriyor emrini gidin bulun gülçiçeğini 7 gün, bir ay,70 gece aranıyor...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gulun-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-huseyin-avni-dede-dtpiu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'telaş kimde sorarım

sorarım kimde heyacan

merhaba şair dostlarım

merhaba osman ile can

kartınızı aldım teşekkür ederim

bildiğiniz gibi parasız pulsuzum ben gene

satırlarınızda kayboldu kederim

açılıverdi yüreğimi sıkıştıran mengene

osman fırçayı aldım elime

sandığı istediğin yere koyarız

şairlik ne kelime...

biz gökyüzünü bile boyarız', 'telaş kimde sorarım sorarım kimde heyacan merhaba şair dostlarım merhaba osman ile can kartınızı aldım teşekkür ederim bildiğiniz gibi paras...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avni Dede']::text[], 8.5, '{"poet":"Hüseyin Avni Dede","poet_slug":"huseyin-avni-dede","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mektup-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamazlar', 'bulamazlar-hakan-rodop-g9y7f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dalgıçların arayışı boşuna

beni bulamazlar

kaldığım yerde

denizlerin içinde

tavanında bile

sorulan sorulara yanıt bulamazlar

enginlerin devrildiği yerde

bazen de boşluğa sesleniyor

kendimle konuşmak zorunda

kalıyorsam eğer

yalnızlık korkunç ama

                             güzel şey

bıkkınlık verecek kadar', 'dalgıçların arayışı boşuna beni bulamazlar kaldığım yerde denizlerin içinde tavanında bile sorulan sorulara yanıt bulamazlar enginlerin devr...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bulamazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlıçıkış Çıkmazı', 'taslicikis-cikmazi-huseyin-avni-dede-tp5kd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yorgunum ölüler kentine ayak bastığım günden beri

hangi şarkıya başlasam bir kız zencefil taşır odama

bütün orospularıma yakut dağıtırım sebepsiz

çizilir alnıma taşlıçıkış çıkmazında acının ilk haritası

denizin ve dağın yorgun renklerini sırtında taşıyan

ve kum saatleriyle yaşayan duvarlara çizilen eğri

o resimlerden düşen karnavalların yeni soytarıları

yani gözleri akrebin gözlerine benzeyen kasaba zehirli su

ziya osman saba geçer gözlerimden geçer taşlıçıkış çıkmazı

gittikçe yakınlaşır kıyıyı seyreden zambakların kokusu

zamansız ağaran beton evlerin tahta balkonlarından', 'yorgunum ölüler kentine ayak bastığım günden beri hangi şarkıya başlasam bir kız zencefil taşır odama bütün orospularıma yakut dağıtırım seb...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avni Dede']::text[], 8.5, '{"poet":"Hüseyin Avni Dede","poet_slug":"huseyin-avni-dede","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/taslicikis-cikmazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hareket Olmalı', 'hareket-olmali-hakan-rodop-61azj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hareket olmalı, 

hareket

caddesinde, sokağında bu ülkenin

hareket olmalı, 

geceyarısı çocuklar top oynamalı

kızlar, erkeklerle halay çekmeli

taşmalı sinemalar, tiyatrolar

bu ülkenin evlerinde cümbüşler yaşanmalı

gülmeli yüzler, ihtiyarlar misket oynamalı

hareket olmalı, 

hareket

caddesinde, sokağında

bu ülkenin geceyarısı', 'hareket olmalı,  hareket caddesinde, sokağında bu ülkenin hareket olmalı,  geceyarısı çocuklar top oynamalı kızlar, erkeklerle halay çekmeli...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hareket-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçak', 'kacak-turkan-i-ldeniz-ldhc9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Işıkları bir yakıp söndürme Kaptan beni korkutamazsın

Beni kimse korkutamaz artık durduramaz bu yerlerde

Çünkü aklıma koydum, çünkü kaçacağım

Karanlık kişiler yolları tutmuş sürekli bekliyorlar

Yakalasalar bir - yengeç kollarıyla - hesap tamam

Ola ki birşeyler yapmadım birşeyler beklemedim onlardan

Kendimce yaşamak istedim salt-bırakmadılar.

Mutluluk yalanlarına inanmadımsa

Neden suçlarlar beni sorumlu kendileri aslında.

Sen de gezemezsen sokaklarda sere serpe

Yedi rengin yokluğunda evden hiç çıkmasan

Sesli düşünürken kırılsa ortasından kalemin

Kendini dinleyip dinleyip de kahretsen herşeye

Bu çıldırtıcı yalnızlıkta boğulduğum yetmez gibi

Kanına ekmek doğrasalar üç öğün - dediler kodularla

Böylesine kavga, böylesine insanlık, böylesine anlayış

Tasarladığım yaşantıyı tasalı sonlandırsa ilk baştan

Üstelik parsları utandıran bir bakışla Kaptan

Kasap çengelindeki ete değil sana baksalar

İşte o zaman - asıl o zaman - başlardı yıkıntın

Bunalmışlığımın nedenini anlardım

Bu güne dek nasıl direndimse yine direnmek mümkündü ama

Ne olduysa seni gördükten sonra oldu

Anbarıyla güvertesiyle gemini gördükten sonra hem

Falımda uzun yollar çıkıyor o günden beri

Bir başka sesleniyor tuttuğum şarkılar hep

Unutmak için herşeyleri kaçıp kurtulmak için herşeylerden

Alınmış sabahların uykusuz rüyalarınca

Görmediğim ülkelerin isterik çağrısına koşuyorum şimdi.

Bırak Kaptan rahat bırak ışıklar yansın

Ben de bilmiyorum kimliğimi sorma bana

Nerede ineceğimi hele hiç

Yalan söyliyemem diyorum yorgunum diyorum sorma başka şeyler

Suçsuzum, parasızım, kaçağım bütün bildiğim bu - beni anla

Anla artık uyuyacağım yeri göster.', 'Işıkları bir yakıp söndürme Kaptan beni korkutamazsın Beni kimse korkutamaz artık durduramaz bu yerlerde Çünkü aklıma koydum, çünkü kaçacağı...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kacak-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılara Ağıt', 'martilara-agit-hakan-rodop-5e7n0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Martılar! 

sevgilimi getirin bana

hani bir kış günü

deniz üstünden

almıştınız onu benden

denizlere soruyorum

bilmiyorlar, 

enginlere devriliyorum

anlamıyorlar, 

Martılar! 

sevgilimi geri getirin bana

ya da

fazla geç olmadan 

alın beni buradan.', 'Martılar!  sevgilimi getirin bana hani bir kış günü deniz üstünden almıştınız onu benden denizlere soruyorum bilmiyorlar,  enginlere devrili...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/martilara-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat Kendini', 'anlat-kendini-hakan-rodop-girm5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzat ellerini ver bana

istersen bir de öpücük kondur 

                                             yanağıma

korkma benden

çekinme

bil ki benim de yüreğim atıyor

senin sevgin için

sadece bakışlardan çekin

onların acımasızlığından

halbuki onlar da insan

dayansalar geleceğe

bulsalar doğal yolu

ama, 

nereden bileceksin seni sevdiğimi

tanıyormusun ki beni

sesimi duydun mu hiç? 

gülücüklerimi yanlış anlama

soğuktan değil

sevginden titriyorum

haydi sen anlat kendini

yalnız seni dinliyorum.', 'Uzat ellerini ver bana istersen bir de öpücük kondur                                               yanağıma korkma benden çekinme bil ki ben...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anlat-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzeldin', 'ne-guzeldin-hakan-rodop-0p2tx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni gördüm dün gece penceremde

ne güzeldin

kıvrak bir melodiydi kulakları yalayan

ne güzeldi

sanki bir ok yaydan çıkmış da

hedefini arıyormuş

işte öylesine öptüm seni

ne güzeldi

ne güzeldi ağaçlar, kuşlar ve

bahar

iyi ki geldin

öylecene oturup yanıma

türkülerini söyledin

ne güzeldi

düşünmek seni

ne güzeldin.', 'Seni gördüm dün gece penceremde ne güzeldin kıvrak bir melodiydi kulakları yalayan ne güzeldi sanki bir ok yaydan çıkmış da hedefini arıyorm...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-guzeldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirimden Aşağısı Kasımpatı', 'siirimden-asagisi-kasimpati-nuh-omer-cetinay-qhrli', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Putları yıktık Pet şişelerde yaşıyoruz artık

Hangi köşeyi dönsek bir köşe daha çıkıyor

karşımıza Yeni kararlar almaya Ne çok

don gömlek almaya aşk umut biraz da

bu yeni çıkmış almaya yıkılmış bir duvardan

imzalı küf kokulu tuğla Satalım kararmış

yağmur yüklü bulutları da yetmemiş almaya

Tıkındık para Ikındık para Sıkıştık* para

Heeey gözünü kör ettiğim paravana

Putları yıktık bir atımlık barut dilimin

ucunda unutulmuş bir mamut gülümsemesi

yanar durur avucumda: 

Bir çağa bu ne haydut ne çok? 

Tapın ulan paramparça! 

------------------------

* param yetmedi

üç nokta daha

koymaya', 'Putları yıktık Pet şişelerde yaşıyoruz artık Hangi köşeyi dönsek bir köşe daha çıkıyor karşımıza Yeni kararlar almaya Ne çok don gömlek alma...', ARRAY['Türk Edebiyatı','Şiir','Nuh Ömer Çetinay']::text[], 8.5, '{"poet":"Nuh Ömer Çetinay","poet_slug":"nuh-omer-cetinay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/siirimden-asagisi-kasimpati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-hakan-rodop-2794e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'özgürlük nedir ki

bir bağ bozumunun ortasında

bir balıkçının ağında

sevda türküsünde

ozanın sesinde

özgürlükse yaşamak

gerekirse ölmektir uğrunda

doğmaksa yeniden ay karanlığında

gülmekse özgürlük

gerekirse öfkedir sevgiliye

öyleyse özgürlük

kırabilmektir zincirleri, 

                      tam vaktinde', 'özgürlük nedir ki bir bağ bozumunun ortasında bir balıkçının ağında sevda türküsünde ozanın sesinde özgürlükse yaşamak gerekirse ölmektir uğ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozgurluk-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-ayhan-kurt-5hmzl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ateş sopalı tanrıların gölgesinde

Küfür gibi biriktim

Aşklar yanıma yöreme uğramaz artık

Yaşamın karşısında kanlı bir öğürtüyüm

Üzerimde ölüm gözcüsü gömleği

Kolları kapalı, ucunda uzun ipler

Kalabalıktılar, geldiler, kollarımı bağladılar, şeytan

                                                           düğümü attılar

Kalabalıktılar; gün boyu uçuşur, kanatları ağırlaşınca

                                              benim üzerime çullandılar

Ah artık ne yapsam boşunadır bütün yaşamaklar

Yüzümü bir kadının memelerine gömsem

Taştan bir dünyayı bir kere de dokunuşlarla tanımlasam

Boşunadır, hiçbir yaram kapanmaz

Çünkü sokağa her adım atışta

Adım yiter, yaralarım kurtlanır

Gece paldır küldür düşer

Ağaçlarda güz ağıdı başlar

Cehennem kazanları iştahlanır

Bütün ırmaklarım deltalarda boğdurulur birer birer

Haykırışlarım şehre çarpıp bana geri döner

Ben gider izbelere sığınır

Ben giderim köstebek olmaya özenirim

Ey! herkes uyuşturucu unutturucu yaşamaklar

                                           kumpanyasında mutludur da

Bir ben rolümü beceremem, köstebek olmaya özenirim

Ey! yıllardır ciğerlerimde sakladığım babamın mezarı

                                                     artık rahat durmaz olur

Ayaklanır, bir çocuğu katrana bular

Ey! ölüm çekimi kanunu uyarınca gitgide ağırlaşır

                                                                    ayaklarım

Bileklerimin kaşıntısı dayanılmaz olur! 

Kan

Toprağın en sadık oğludur!', 'Ateş sopalı tanrıların gölgesinde Küfür gibi biriktim Aşklar yanıma yöreme uğramaz artık Yaşamın karşısında kanlı bir öğürtüyüm Üzerimde ölü...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Kurt']::text[], 8.5, '{"poet":"Ayhan Kurt","poet_slug":"ayhan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yara-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-i-nonu-alpat-japy7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sürgünün hüznü

ağlattı bir arkadaşı

yıllar var ki

oğluna susamış

bir duvarı acıdan

bir duvarı umuttan renkli

çiçek kokulu o evde

abisiyle başlayan

güneş yüzlü hasret

o gün ağlattı bizi

Yaşamadım

yazamam sürgünü

tarihine atacağım imzadan başka', 'Sürgünün hüznü ağlattı bir arkadaşı yıllar var ki oğluna susamış bir duvarı acıdan bir duvarı umuttan renkli çiçek kokulu o evde abisiyle ba...', ARRAY['Türk Edebiyatı','Şiir','İnönü Alpat']::text[], 8.5, '{"poet":"İnönü Alpat","poet_slug":"i-nonu-alpat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/surgun-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün Yanaklarına Yayılır', 'gulusun-yanaklarina-yayilir-i-nonu-alpat-k9npm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlıklardan geliyorum

gözlerimde ölüm törenlerinin derinliği

dudaklarımsa acıdır benim

içmişim acem suyundan

öpmeye bile kıyamam seni

Yalnızlıklardan geliyorum

tek başına çok dolaştım bu sokakları

ölen arkadaşların adreslerini

sordum da kuşlara

kanatlarıyla yüreğimi okşadılar

Yalnızlıklardan geliyorum

gülüşün yanaklarına süzülür

duruşma günleri arama beni

şairdir derler, duruşundan belli

Yalnızlıklardan geliyorum

bir açlık grevi daha bitti

sen yoktun, gözlerimi serdim masaya

şimdi anılar sarılı kanayan yaraya', 'Yalnızlıklardan geliyorum gözlerimde ölüm törenlerinin derinliği dudaklarımsa acıdır benim içmişim acem suyundan öpmeye bile kıyamam seni Ya...', ARRAY['Türk Edebiyatı','Şiir','İnönü Alpat']::text[], 8.5, '{"poet":"İnönü Alpat","poet_slug":"i-nonu-alpat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gulusun-yanaklarina-yayilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak Düş', 'sicak-dus-hakan-rodop-trkha', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dışarıdaki karın yağışından

ürpermesin için

o da istemez seni incitmeyi

günlerin dert ortağı güllere

söylenecek sözümüz yok

onlar görevlerini yaptılar

boşluktaki güvercinlere

sesimizi ulaştırın

onlar biliyorlar

barışı, kardeşliği

alın güller, güvercinler sizin olsun

bize yalnızca yağan karı verin

düşün ki onu da evcilleştirdik

düşün ki insan soğutmaz oldu, 

                                       hayvan üşütmez! 

söyleyin, 

bundan daha sıcak düş gördünüz mü?', 'dışarıdaki karın yağışından ürpermesin için o da istemez seni incitmeyi günlerin dert ortağı güllere söylenecek sözümüz yok onlar görevlerin...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sicak-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akan Pınar Bitmeyecek Mi?', 'akan-pinar-bitmeyecek-mi-hakan-rodop-1uolc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'daha dün aldığım bir tutam çiçeği

pınarın aktığı yerin önüne bıraktım

öyle çağlıyordu ki çiçek gördüğü için

çiçekler pınarları kirletmez

sormuşlar, bu pınarlar hiç bitmeyecek mi? 

söyle onlara, bizim içtenliğimizi

yolumuzdan dönmeyeceğimizi

yardımsız çıktık yola

taşlı-tozlar yollar, bizi bıktıramaz

göz pınarlarında ki yaşları sil artık

bu kötü masal burada son bulacak

doğan güneşin altında bizi bekle

pınarların bittiği yerde', 'daha dün aldığım bir tutam çiçeği pınarın aktığı yerin önüne bıraktım öyle çağlıyordu ki çiçek gördüğü için çiçekler pınarları kirletmez sor...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/akan-pinar-bitmeyecek-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorulmam Daha', 'yorulmam-daha-cem-salih-un-u1h5f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yorulursam birgün

Yüzümde gülüşüm yorulur

Bakışlarımı yasladığım dünya

Pusa bularken siluetini

Dudaklarımdaki sessizliği kalbime batırırım

Kanatırım kendimi

Ve soysuzlaşınca bütün acılarım

Ki acımasızlıktır bunun adı

Derimi pul pul dökerim onunla

Yorulursam birgün; 

Unuturum ihanetli haziranı

Silinir o zaman

Yorgun kentlerde bıraktığım bütün yüzler

Bir cehennem yalnızlığında kaybolur geçmişim

Bir kapı çarpılır o zaman 

Ve bunu kendine milat alan zaman 

Bütün denizleri buharlaştırır

Fırtınaları dindirmek için

Ve aşkı kimse kurtaramaz artık, dostluğu kurtaramaz

Eritir beni bu yorgunluk, sessiz ve habersiz

Cılız bakışlar kalır geriye ama ıslak

Ömrümün bedeli diye', 'Yorulursam birgün Yüzümde gülüşüm yorulur Bakışlarımı yasladığım dünya Pusa bularken siluetini Dudaklarımdaki sessizliği kalbime batırırım K...', ARRAY['Türk Edebiyatı','Şiir','Cem Salih Ün']::text[], 8.5, '{"poet":"Cem Salih Ün","poet_slug":"cem-salih-un","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yorulmam-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lavanta', 'lavanta-refik-recep-pelit-v69yg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mis kokulu lavanta

Kırıstal bir vazoda

Solacak oracıkta 

Alenen ortalıkta

Ömrü belki bir hafta

Geçecek bir solukta!', 'Mis kokulu lavanta Kırıstal bir vazoda Solacak oracıkta  Alenen ortalıkta Ömrü belki bir hafta Geçecek bir solukta!...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/lavanta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Börtü Böcek', 'bortu-bocek-refik-recep-pelit-wu666', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tırtıl derler adına 

O da bir börtü böcek 

Biraz sabır lazım 

Biraz çile çekecek 

Bir kaç gün sonra 

Bir gelinlik giyecek

Her kes onun adına 

Güzel kelebek diyecek

Geçmiş günlerini 

Bir anda siliverecek 

Umut dolu neşe dolu

Mutlu günler gelecek

Ne çareki güzel günler 

Çok çok kısa sürecek 

Bir sinsi alçak örümcek 

En huzurlu gününde 

Kahvaltısında yiyecek.', 'Tırtıl derler adına  O da bir börtü böcek  Biraz sabır lazım  Biraz çile çekecek  Bir kaç gün sonra  Bir gelinlik giyecek Her kes onun adına...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bortu-bocek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzler, Altı', 'yuzler-alti-enis-batur-8qtxe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onca çil, yaz güneşi.Mat tenin gözenkleri

tuzlu su yollarına açık, gözleri balkıyor

çıkarır çıkarmaz gözlü
..........
..........', 'Onca çil, yaz güneşi.Mat tenin gözenkleri tuzlu su yollarına açık, gözleri balkıyor çıkarır çıkarmaz gözlü .......... .............', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yuzler-alti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlerin Aşkı', 'gunlerin-aski-selcuk-kulcuoglu-6wq85', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzelim ben seni

Perşembe günü gördüm

Cuma günü ise sevdim

Cumartesi peşindeydim

Pazar sevgilindim

Ah o Pazartesi günü yok mu

Hafta ile birlikte

Aşkımı da bitirdin', 'Güzelim ben seni Perşembe günü gördüm Cuma günü ise sevdim Cumartesi peşindeydim Pazar sevgilindim Ah o Pazartesi günü yok mu Hafta ile birl...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Külcüoğlu']::text[], 8.5, '{"poet":"Selçuk Külcüoğlu","poet_slug":"selcuk-kulcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunlerin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-selcuk-kulcuoglu-c5rdy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum, 

Ne düşündüğümü bilmeden.

Aslında biliyorum ama...

Düşünmek istemiyorum.

Yazdığıma göre, 

Düşünüyorum.

Bir şeyleri, 

Düşünüyorum.

Seni, sevdiğim

Seni düşünüyorum.

Hem de her an, 

Hiç bıkmadan

Hiç yorulmadan.

(30 Ocak 2002)', 'Düşünüyorum,  Ne düşündüğümü bilmeden. Aslında biliyorum ama... Düşünmek istemiyorum. Yazdığıma göre,  Düşünüyorum. Bir şeyleri,  Düşünüyoru...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Külcüoğlu']::text[], 8.5, '{"poet":"Selçuk Külcüoğlu","poet_slug":"selcuk-kulcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-dusunuyorum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı Bir Gezegenden Tuhaf Haberler', 'yabanci-bir-gezegenden-tuhaf-haberler-hermann-hesse-00lcc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''İşte çevrende hışırdıyor dalga; ve sen dalgasın; orman; ve sen ormansın, iç ve dış diye iki ayrı şey yok artık, kuşsun ve uçuyorsun havada, balıksın ve yüzüyorsun denizde, ışığı emiyorsun; ışıksın, karanlığın hazzına varıyorsun ve karanlıksın. Yollara vuruyoruz, ey ruh, sularda yüzüyor, havalarda uçuyoruz, gülümsüyor ve narin ruhsal parmaklarımızla kopmuş iplikleri yeniden birbirine bağlıyoruz, yok edilmiş titreşimleri mutluluk içinde diriltip sürdürüyoruz yeniden. Tanrıyı aramıyoruz artık, Tanrı oluyoruz. Öldürüyor, birlikte ölüyoruz; yaratıyor, düşlerimizle yeniden diriliyoruz, en güzel düşümüz mavi gökyüzüdür, en güzel düşümüz denizdir ve balıktır en güzel düşümüz, neşe saçan aydınlık sestir, neşe saçan parlak ışık - hepsi de düşümüzdür bizim, hepsi de bizim en güzel düşümüz. Az önce öldük ve toprak olduk. Az önce gülmeyi keşfettik. Az önce gökyüzüne bir burç kondurduk.

Çın çın sesler geliyor ve her ses annenin sesidir. Ağaçlar hışırdıyor ve her biri beşiğimizin üstünde hışırdadı. Yollar yıldız biçiminde ayrılıyor birbirlerinden ve her yol bizi sılaya götürüyor.''', '''İşte çevrende hışırdıyor dalga; ve sen dalgasın; orman; ve sen ormansın, iç ve dış diye iki ayrı şey yok artık, kuşsun ve uçuyorsun havada,...', ARRAY['Türk Edebiyatı','Şiir','Hermann Hesse']::text[], 8.5, '{"poet":"Hermann Hesse","poet_slug":"hermann-hesse","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yabanci-bir-gezegenden-tuhaf-haberler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-hermann-hesse-y4bbs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendi kanımızdan kan katmadığımız, sevgiyle donatmadığımız, uğrunda özverileri, ortak acıları üstlenmediğimiz, savaşımlara katlanmadığımız hiçbir ilişkinin, hiçbir dostluğun, hiçbir duygunun bize sadakat göstermediğini ve güvenilir nitelik taşımadığını her birimiz kendi günlük hayatımızda öteden beri yaşar, biliriz. Birine gönlünü kaptırmanın ne kadar kolay, gerçekten sevmenin ise ne kadar zor olduğunu bilmeyen ve yaşamayan yoktur. Bütün gerçek değerler gibi sevgi de satın alınamaz. Satın alınabilen hazlar vardır, satın alınabilen sevgiyse hayır.', 'Kendi kanımızdan kan katmadığımız, sevgiyle donatmadığımız, uğrunda özverileri, ortak acıları üstlenmediğimiz, savaşımlara katlanmadığımız h...', ARRAY['Türk Edebiyatı','Şiir','Hermann Hesse']::text[], 8.5, '{"poet":"Hermann Hesse","poet_slug":"hermann-hesse","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sevgi-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaplıcada Bir Konuk', 'kaplicada-bir-konuk-hermann-hesse-jjdgu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''..Yaşam bir hesap sorunu değil, bir matematik formülü değildir, bir mucizedir.Ömrüm boyunca da bu özelliğini yitirmemiştir.; her şey dönüp dolaşıp yeniden çıkmıştır karşıma, aynı sıkıntılar, aynı sevinçler, aynı ayartılar. Her zaman başımı aynı taşlara vurmuşumdur, aynı devlerle savaşmış, aynı kelebeklerin peşinde koşmuşumdur, aynı konum ve durumlar tekrarlanmış, öyleyken karşımda hep yeni bir oyun bulmuşumdur, yine her zaman güzel., yine her zaman tehlikeli her zaman heyecan verici. Binlerce kez taşkın davranışlarda bulundum, binlerce kez ölesiye yorgun düştüm, binlerce kez çocuk oldum, binlerce kez yaşlı ve serinkanlı ve hiçbiri uzun sürmedi, her şey dönüp dolaştı çıktı karşıma ama hiçbir zaman öncekinin aynısı değildi....''', '''..Yaşam bir hesap sorunu değil, bir matematik formülü değildir, bir mucizedir.Ömrüm boyunca da bu özelliğini yitirmemiştir.; her şey dönüp ...', ARRAY['Türk Edebiyatı','Şiir','Hermann Hesse']::text[], 8.5, '{"poet":"Hermann Hesse","poet_slug":"hermann-hesse","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/kaplicada-bir-konuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-hermann-hesse-njim7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamım ne anlam taşımıştı, bunca sevinç ve acının üzerinden geçip gitmesinin hikmeti neydi? Şimdiye kadar içimde hissettiğim, hala hissetmekte olduğum gerçek''e ve güzel''e karşı bu susamışlık nedendi? Ne diye o şuh ve dilber kadınlar uğruna inatla, gözyaşları akıtarak sevdalar ve acılar çekmiştim? Niçin bugün de başım hazin bir sevgi uğruna yine utanç ve gözyaşlarıyla eğilmişti? Madem yalnızlıklar içinde pek sevilmeden yaşayıp gitmek alnıma yazılmıştı, o işine akıl ermez tanrı, sevginin yakıp kavurucu özlemini ne diye yüreğime yerleştirmişti sanki? ''', 'Yaşamım ne anlam taşımıştı, bunca sevinç ve acının üzerinden geçip gitmesinin hikmeti neydi? Şimdiye kadar içimde hissettiğim, hala hissetme...', ARRAY['Türk Edebiyatı','Şiir','Hermann Hesse']::text[], 8.5, '{"poet":"Hermann Hesse","poet_slug":"hermann-hesse","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/yasamak-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-hermann-hesse-3ewq3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O sevdi, sonunda kendi kendini buldu. Ne var ki, insanların büyük çoğunluğu kendi kendilerini kaybetmek için sever.

Sevilmek mutluluk değildir.

Her insan kendini sever; ama mutluluk bir başkasını sevmektir.', 'O sevdi, sonunda kendi kendini buldu. Ne var ki, insanların büyük çoğunluğu kendi kendilerini kaybetmek için sever. Sevilmek mutluluk değild...', ARRAY['Türk Edebiyatı','Şiir','Hermann Hesse']::text[], 8.5, '{"poet":"Hermann Hesse","poet_slug":"hermann-hesse","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sevmek-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-hermann-hesse-wae9d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''...Oysa şimdi bu eski ve yerde bir boşluk göze çarpıyordu; küçük dünyamda bir çatlak belirmişti ve karanlık, ölüm ve dehşet gözlerini dikmiş bu çatlaktan içeri bakıyordu. (...)   Bundan böyle ne bir dal ne bir meyve koparabilecektim ağaçtan, bundan böyle dallarından birinin özgün ve fantastik mimarisini resme geçirmeye çalışmayacak, sıcak yaz öğlelerinde merdivenden inip çıkarken onun yanına uğrayarak ince gölgesinde bir an soluklanamayacaktım. (...)   Yazık, ağaçlara bel bağlamaya gelmiyor artık, onlar da insanın elinden kayıp gidebiliyor, onlar da seni beni

düşünmeden bu dünyadan göçebiliyor, insanı yüzüstü bırakıp o koyu karanlığa dalarak gözden kaybolabiliyor! ''', '''...Oysa şimdi bu eski ve yerde bir boşluk göze çarpıyordu; küçük dünyamda bir çatlak belirmişti ve karanlık, ölüm ve dehşet gözlerini dikmi...', ARRAY['Türk Edebiyatı','Şiir','Hermann Hesse']::text[], 8.5, '{"poet":"Hermann Hesse","poet_slug":"hermann-hesse","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bosluk-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-mustafa-gider-oyvgy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana

Boya kokulu bir odada

Özlemle

Yalnızlığın tadına varmış bir şekilde

Hep senle dolu olarak

Nilüfer çiçieğinin unutkanlığıyla

Kulağım müzikle dolu

Kalbim sen nidalarıyla

Yazıyorum

Adaylardan hiç biri olmayaçağını bilerek

Başka limanlara yelken çevirerek

İsyanlarla kaynayan

bir gemiyle yol alıyorum', 'Sana Boya kokulu bir odada Özlemle Yalnızlığın tadına varmış bir şekilde Hep senle dolu olarak Nilüfer çiçieğinin unutkanlığıyla Kulağım müz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gider']::text[], 8.5, '{"poet":"Mustafa Gider","poet_slug":"mustafa-gider","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aminoasit', 'aminoasit-kucuk-i-skender-vyiha', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağır bir hastalık 

gibi ilerledik masmavi kentin 

yağmalanmış, küskün âşıklarında 

Ne bir söz doğrultabildi kesik başlarını 

ne de saçlarına sıcak bir dokunuş 

kurutabildi o iltihap akıtan kalp yaralarını 

uzanıp, sanki biz kapattık ölü sevgililerinin', 'Ağır bir hastalık  gibi ilerledik masmavi kentin  yağmalanmış, küskün âşıklarında  Ne bir söz doğrultabildi kesik başlarını  ne de saçlarına...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aminoasit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pil', 'pil-kucuk-i-skender-9838n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'otomobilin altında kalmış 

peygamber. 

bir delikten içeri sızmaya çalışmış 

hayatı boyunca kan. 

kapan kapanmadan önce kararan hava 

şişirmiş komik cinlerin etli ciğerlerini. 

istanbul’a inen uçak 

avcundan su içmiş karanlığın. 

öyle yazmışsın mektubunda 

öyle dedi akıl hastanesine yatırılan postacı.', 'otomobilin altında kalmış  peygamber.  bir delikten içeri sızmaya çalışmış  hayatı boyunca kan.  kapan kapanmadan önce kararan hava  şişirmi...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/pil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pısırık', 'pisirik-kucuk-i-skender-eld4w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir benzerlik var göle düşen kayalıkla 

mezartaşlarına konan 

martı heykelleri arasında 

Hani diyorum bir akşamüstü kalksam 

gitsem çocukluğumun geçtiği 

ormana 

saçlarımı tarar mı yine ağlayarak maymunlar', 'Bir benzerlik var göle düşen kayalıkla  mezartaşlarına konan  martı heykelleri arasında  Hani diyorum bir akşamüstü kalksam  gitsem çocukluğ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/pisirik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pansuman', 'pansuman-kucuk-i-skender-8r5ph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hayalet haydar’a 

İğne deliğinden geçen hayalle dikilir 

sabaha karşı sökülen 

su kuşları: ‘Eskiden Terzi’ 

Terzilerin önünde kedi yok mu abi 

artık kumaş parçalarıyla 

örtmek için pembe dillerinin ölü kentlerini 

bir makasın iki ucu olup hayatı keser gibi iki sevgili', 'hayalet haydar’a  İğne deliğinden geçen hayalle dikilir  sabaha karşı sökülen  su kuşları: ‘Eskiden Terzi’  Terzilerin önünde kedi yok mu ab...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/pansuman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paris', 'paris-kucuk-i-skender-8g7py', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu kartı sana paris’ten atıyorum 

çok türkçe bir aşkın ortasında 

çok türkçe bir yağmurun mağarasında 

çift kâğıtlının son dumanına sinen erezyonda 

kelimelerden 

beni aşağılayan, bir hiç yerine koyan kelimelerden 

ve tehlikeli, korkunç hayvanlardan kurtulduğum, 

 kendime doğru 

bir çıkış yolu bulduğum 

 güzel bir zamanda.. 

bu kartı sana paris’ten atıyorum: 

bugün mavinin ayrı bir havası 

bugün rüzgârın özel bir şıklığı var, 

bugün kuşların yaşgünü çünkü sevgilim! 

bugün kuşlarla senden, senin 

o çok efkârlı ellerinden konuştuk uzun uzun 

bugün kuşlarla senin resmini çizdik 

 bütün karakol duvarlarına 

biraz sandviç yedik, biraz su içtik seni düşünerek 

allahına kadar fırlamaydık senin anlayacağın 

bugün kuşların yaşgünü çünkü sevgilim 

bugün kuşlara senin ismini armağan ettim! 

gereksiz eklem ağrıları ve kriz değil midir 

ışıksız gözlerime bir nebze kan 

pul pul olmuş tenime enjektör kapanları kuran, 

duran 

 sonra yürüyen 

   sonra bir daha duran 

seyyah kalbime tüm ihtişamıyla boşalan 

hap niyetine sıcak elektriğin doludizgin sersemliğinde 

üşürken, açken 

kolları kısa ceketimin yakalarını kaldırırken 

sorgumda soruyorum bunları, hep soru kalanları: 

niye ayrıldık (cevabı kullanılmış, aids riski taşıyor) 

nasıl sustuk (cevabı, kalabalık getto masallarında) 

niçin birbirimize çarpa çarpa bir suça ortak olduk 

şimdi hangi dozda hangi ekolde zırvalıyorum 

sokaklarda mora mor çalan dönme bir gitaristken 

koşabiliyor muyum, nefes alabiliyor muyum, sıçabiliyor muyum 

dehşetli yerlerimden 

en karanlık gizlerimden çalakalem vurulmuşken 

otuz üçünde kahpe bir anarşist 

sırtında yetmiş yedi hançer yarası 

bir polisten tokatlanmış magnum ve ben 

gece camlarını, orospu.mlarını yumruklarken 

ya da 

çıplak ayaklarımla boş ilaç şişelerini ezerken 

her yer, herşey kırmızıya boyanırken duruluyorum 

ölmek üzere olan birin üstünde dönenen 

puşt akbabalar gibi yüzümün üstünde dolanıyor ruhum! 

bu kartı sana ben 

sanırım 

paris’ten atıyorum! 

mamafih, 

niye gelmişim, nerden gelmişim, neden burdayım 

sanki 

ekmeğe karışmışken toprağı özleyen buğdayım! 

sevgilim, ben ne soysuz bir adamım -ki 

kopan mi telinin yerine kurumuş bir gözyaşı takıyorum 

evet! evet! 

koşuyorum, yuvarlanıyorum, bağırıyorum, ağlıyorum 

faşizme yenilmişken 

avla avcının mesafesi daralmışken 

otuz üçünde bozguna uğramış bir devrimci 

kıçında yetmiş yedi.azrak yarası 

bu kartı sana ben 

büyük ihtimal 

paris’ten atıyorum!', 'bu kartı sana paris’ten atıyorum  çok türkçe bir aşkın ortasında  çok türkçe bir yağmurun mağarasında  çift kâğıtlının son dumanına sinen er...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/paris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sulusepken', 'sulusepken-kucuk-i-skender-bdyeb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir taş devri var bu gece gökyüzünde 

ne dinzorlar ne de atalarımızın vahşeti 

bir ton açmıyor felaketi 

Kendine bile küskün bir yalnızlıkla yaklaşıyoruz 

yaralı yenik askerlerle suskun 

darmadağın bir gemiyle ağır ağır iskeleye 

kadınlarımız açlıktan çocuklarımızı yemişler', 'Bir taş devri var bu gece gökyüzünde  ne dinzorlar ne de atalarımızın vahşeti  bir ton açmıyor felaketi  Kendine bile küskün bir yalnızlıkla...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sulusepken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taraflı', 'tarafli-kucuk-i-skender-ynsb1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyku sıçratıyor boğucu yaz 

sızarken ağustosa 

sırtında kuyruklu piyanolarla 

Sahildeki küçük ağacın dallarında 

şarkı söyleyen sarhoş ve ölü balıklar 

buraları bir anlayan olmalı 

adını bilmediğim sulara deydirirken ayaklarımı', 'Uyku sıçratıyor boğucu yaz  sızarken ağustosa  sırtında kuyruklu piyanolarla  Sahildeki küçük ağacın dallarında  şarkı söyleyen sarhoş ve öl...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tarafli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Su Lütfen Biraz Su', 'su-su-lutfen-biraz-su-kucuk-i-skender-jv5ql', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'saklı kan satar sana 

acemi kalçalarıyla plastik orospular, 

darmadağın bir vücut taşır kutsal suçun da 

ve takılır kalır ilk ve son mutluluğun 

uzun çubuklar arasında bıçaklanan yataklarda. 

dön bak çıkageldiğin ömre, 

eski sevgililerin elyazılarıdır tenindeki kırışıklıklar, 

açılır, geçmişin dalgalarına boyun eğip boğulan aklın 

ölüm, hayata orada ant içirtir 

ve kapanır sahte, parlak ışıklar! 

belki de 

tam uzanıp öpecekken gerçeğin yaralı, bedbaht yüzünü 

süslerin gerisinde ansızın beliren karanlık delikleriyle 

reddedilmesi imkânsız, bir teklif olur artık intihar!', 'saklı kan satar sana  acemi kalçalarıyla plastik orospular,  darmadağın bir vücut taşır kutsal suçun da  ve takılır kalır ilk ve son mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/su-su-lutfen-biraz-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Retorik', 'retorik-kucuk-i-skender-y630c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'maalesef geç kaldınız dedi komiser kucaklarken 

askılarda kalan cesedin profil kaydını hızla, 

tespit ettik, ilişkisi varmış o serseri kızla 

sevişmelere maymun taklidi yaparken kayısı kabukları 

am! diye haykırdı en güvendiğimiz sağlam çocuk', 'maalesef geç kaldınız dedi komiser kucaklarken  askılarda kalan cesedin profil kaydını hızla,  tespit ettik, ilişkisi varmış o serseri kızla...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/retorik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhmal', 'i-hmal-kucuk-i-skender-lhe69', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerede eğilmişti ilk kez bir kadın 

nehre doğru ve şelaleye düşürmüştü 

yasak çocuğunu 

Nerede eğilmiştim ilk kez korkusuzca 

yüzüne doğru ve gözyaşlarına düşürmüştüm 

erkeksiz soyumu 

bütün resimlerimizden kesip çıkarttım gözlerimizi', 'Nerede eğilmişti ilk kez bir kadın  nehre doğru ve şelaleye düşürmüştü  yasak çocuğunu  Nerede eğilmiştim ilk kez korkusuzca  yüzüne doğru v...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ihmal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mephisto', 'mephisto-kucuk-i-skender-3m7ym', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıpranmış eski bir defter sayfasında 

kurşun kalemle çizilmiş bir saksofonun 

yanına not düşülmüş bir kent adı 

Olarak tanımlıyorum seni öperken 

yüzün yüzüme deymiş mi deymemiş mi sorma 

yeryüzüne inen iki kar tanesi gibi 

birbirine karıştıkça eriyen külah ve sade dondurma', 'Yıpranmış eski bir defter sayfasında  kurşun kalemle çizilmiş bir saksofonun  yanına not düşülmüş bir kent adı  Olarak tanımlıyorum seni öpe...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mephisto-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük İskender''in Özyaşamı', 'kucuk-i-skender-in-ozyasami-kucuk-i-skender-h7k8t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben içi 

boşaltılmış siyah bir hayvan hücresiyim 

uçan kuşun 

erkeklik organını almışım ağzıma havada 

kuruluyum 

çevir ruhumu ey hasmım canavar, vaktim yok 

camdandım 

kırılsam doğa çalınacaktı yeryüzünden 

âşık oldum mu 

kurt inerdi yüzüme 

birden fazlaydı katilim 

cesedimi bulamadı sahibim 

bir yerime yağmur yağıyordu 

ellerimden teki karşı safa geçmişti 

bağırsam, ama bir de bağırsam çağırsam ağlasam 

şair oldum sanacaklardı 

canım, güzel abim! 

bağlasana deli gömleğimi!', 'ben içi  boşaltılmış siyah bir hayvan hücresiyim  uçan kuşun  erkeklik organını almışım ağzıma havada  kuruluyum  çevir ruhumu ey hasmım can...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kucuk-iskender-in-ozyasami-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanlıcada Akşam', 'kanlicada-aksam-kerem-alisik-nglbb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O çarşamba akşamını hatırlıyormusun

Beni sensizliğe mahkum ettin biliyormusun', 'O çarşamba akşamını hatırlıyormusun Beni sensizliğe mahkum ettin biliyormusun...', ARRAY['Türk Edebiyatı','Şiir','Kerem Alışık']::text[], 8.5, '{"poet":"Kerem Alışık","poet_slug":"kerem-alisik","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kanlicada-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Çoğalan Sen', 'bende-cogalan-sen-gurcan-gunay-cxr43', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllar geçti üzerinden o puslu akşamın

Unuttum mu seni bir sor

Nakış gibi yüreğimin ucundasın öylece

Sor bana bendeki sensizliği

Bir dokun bin ah işit benden

Sen bir meltem estir geçmişten

Dalgalar taşırayım sana içimdeki denizden

Tesbih tanelerindeki sabır

Karanlık gecelerdeki kahır

Tüketiyor beni ağır ağır

Oysa aşkın büyümede çığ gibi

Okyanuslar gibi

Gökler, yıldızlar gibi

Büyüttükçe içimdeki ''Sen''i

Biraz daha tükeniyorum 

İçimde büyüyen devi

Artık çekemiyorum...', 'Yıllar geçti üzerinden o puslu akşamın Unuttum mu seni bir sor Nakış gibi yüreğimin ucundasın öylece Sor bana bendeki sensizliği Bir dokun b...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bende-cogalan-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiden Söz Etmeyen Bir Şiir Yazsam', 'sevgiden-soz-etmeyen-bir-siir-yazsam-sair-i-smihan-hansg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgiden söz etmeyen bir şiir yazsam..

Dökülse dalgın saçları gözlerine genç kızların

Boş avlulardan kuşlar havalansa

Her kanat çırpışları

Gökyüzüne olan sevgilerini anlatsa

Sevgiden söz etmeyen bir şiir yazsam

Mesela yaşama dair

Acılardan, özgürlükten söz eden

Sevmeden acı çeker mi insan? 

En zor sevgi özgürlük değil mi zaten! ..

Sevgiyle dolmasa mısralarım

Söğütlerin suya değen başlarını

Denizin nehirleri kucaklayışını yazsam

Aklıma sen gelsen

Her duruş, her ses, her dokunuş bana seni hatırlatsa

Sevgiyi unutsam, 

Seni unutsam..

Sevgiden söz etmeyen bir şiir yazsam...', 'Sevgiden söz etmeyen bir şiir yazsam.. Dökülse dalgın saçları gözlerine genç kızların Boş avlulardan kuşlar havalansa Her kanat çırpışları G...', ARRAY['Türk Edebiyatı','Şiir','Şair İsmihan']::text[], 8.5, '{"poet":"Şair İsmihan","poet_slug":"sair-i-smihan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevgiden-soz-etmeyen-bir-siir-yazsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-sair-gezgin-0hflp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğduğu günden beri

Kötü talihi bırakmadı peşini

Yine de yüreği sevgi doluydu

Sevgi dağıttı 

O''na 

buna 

herkese

Kötü bir şey getirmedi aklına bir an 

Derken 

Bir kıza sevdalandı mahzun gönlü

Kız ise başkasına sevdalı

-O''nu kimse anlayamadı.....', 'Doğduğu günden beri Kötü talihi bırakmadı peşini Yine de yüreği sevgi doluydu Sevgi dağıttı  O''na  buna  herkese Kötü bir şey getirmedi aklı...', ARRAY['Türk Edebiyatı','Şiir','Şair Gezgin']::text[], 8.5, '{"poet":"Şair Gezgin","poet_slug":"sair-gezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garip-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Mehtap Misali', 'yarim-mehtap-misali-veli-cetinkaya-ytyq2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yarım  mehtap misali

Yarım aşkmıydın.

Ne karanlıkta bıraktın

Ne tam ışıttın.

Denizde meltem niyetli

Esmedin, gittin.

Beni bırakıp gidersen

Bil ki ben bittim.

17.08.2002', 'Yarım  mehtap misali Yarım aşkmıydın. Ne karanlıkta bıraktın Ne tam ışıttın. Denizde meltem niyetli Esmedin, gittin. Beni bırakıp gidersen B...', ARRAY['Türk Edebiyatı','Şiir','Veli Çetinkaya']::text[], 8.5, '{"poet":"Veli Çetinkaya","poet_slug":"veli-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yarim-mehtap-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çileler', 'cileler-i-brahim-sadri-grssw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Minibüslerin arkasına seni ben yazdım 

Gözlerimin nasıl sev dediğini 

Sensiz bu dünyanın batması gerektiğini 

Hor görsende garibi 

Bir teselli vermeni ben istedim 

Bahtıma takılan bir karaçalı gibi 

Gönlümü tozduman bıraktığımı 

Bağrımdaki ateşi yakıp gittiğin günden beri 

Batıyor gönlümde bir akşam güneşi 

Minibüslerin arkasına seni ben yazdım 

Ben yazdım sevrek ayrılalım 

Ben yazdım 

Cennet gözlüm ben yazdım 

Ben sabahsız gecelerin kucağında bir çilekeş 

Gönlüme vazgeç demişim 

Vazgeçmemiş bu aşktan 

Kabahat seni sevende biliyorum 

Elimde bir kandil dolanıyorum 

Eğer aşka bir ceza verebilseydim 

Onun da benim gibi sevmesini isterdim 

Minibüslerin arkasına seni ben yazdım 

Bunca yıl habersiz yaşadım seninle 

Hep seninle yaşadım öldü deselerde 

Aşkından öldüğümü bilmesende 

Belki biraz üzülüp kim desende 

Gel gör şu halimi bir teselli ver 

Sevenler mesud olmaz derlerdi inanmazdım 

Şimdi mesud değilim bilseydim bağlanmazdım 

Biliyorum ben eski halimle daha mesuddum 

Dediğin gibi olsun hadi severek ayrılalım 

Ama otur son kez masaya göğsümüzü yumruklayalım. 

Bitmedi mi bitmedi mi çekilen işkence? 

Volkan misali tüten parçalanan gönlümle 

Ekilen biçilmezken kısacık ömrümüzde 

Değer verdiklerimiz gülerken halimize 

Hangi gaye 

Hangi amaç 

hangi ümit yaşatır? 

Katmerlenmiş çilelere 

Hangi vücut dayansın?', 'Minibüslerin arkasına seni ben yazdım  Gözlerimin nasıl sev dediğini  Sensiz bu dünyanın batması gerektiğini  Hor görsende garibi  Bir tesel...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sadri']::text[], 8.5, '{"poet":"İbrahim Sadri","poet_slug":"i-brahim-sadri","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cileler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına Gözlü', 'firtina-gozlu-veli-cetinkaya-8b0nm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fırtına gözlüye rastladım yolda

Hazana dönmüştü kısık gözleri

Avurtları çökmüş, benzi solmuştu

Bağı çözülmüştü ceylan dizlerin.

Yıllar oldu onu görmeyeli

Bir anda aklıma geldi sözleri.

Hani fırtınaydık, hazana kaldık

İkinci bahara bile geç kaldık

Boş gururumuza nasıl da kandık

Gençlik hep kalacak, kahrolsun kandık.

Aşkımızı nasıl savurup durduk

Şimdi boş gözlerle bakınır olduk

Çok liman dolaştık, şimdi yorulduk

Sığ sularda karaya vurduk.

Hayat ne güzeldi oysa seninle

Hani, ömrünce savaş verecektin benimle

İhanetin bedeli belki az sana

Pişmansın, hislerin belli yüzünde.

Çağırsam gelirsin belki geriye

Yüzün yok bilirim ama nafile

Söz geçiremedim deli gönlüme

Dilimden düşmeyen aşkım oldun sen.

Süngerler çekilmez geçmiş hatana

Kin ve nefretim büyürken sana

Aşka yenik düştüm, ne oldu bana

Susadım, savruldum ben............... SANA.

          17.12.2002 Antalya', 'Fırtına gözlüye rastladım yolda Hazana dönmüştü kısık gözleri Avurtları çökmüş, benzi solmuştu Bağı çözülmüştü ceylan dizlerin. Yıllar oldu ...', ARRAY['Türk Edebiyatı','Şiir','Veli Çetinkaya']::text[], 8.5, '{"poet":"Veli Çetinkaya","poet_slug":"veli-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/firtina-gozlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-sair-gezgin-yhzvt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam üzeri 

gökten boşanırcasına yağan yağmurda

karşımdan gelip yüreğimi parçalayan

ve bir an önce evine ulaşmak için -ki evin varsa-

çamurlara bata çıka 

sürünen adam; 

-senin için dua ettim ilk kez Tanrıya 

  bir daha yağmur yağmasın diye........', 'Akşam üzeri  gökten boşanırcasına yağan yağmurda karşımdan gelip yüreğimi parçalayan ve bir an önce evine ulaşmak için -ki evin varsa- çamur...', ARRAY['Türk Edebiyatı','Şiir','Şair Gezgin']::text[], 8.5, '{"poet":"Şair Gezgin","poet_slug":"sair-gezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmur-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-sair-gezgin-ojeg6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O güzel saçlarını bırak çılgın rüzgara

dalgalansın

sonra bir gül tak saçlarına 

kırmızı bir gül olsun

gülümsemeni hiç eksiltme yüzünden 

ve sıcacık ellerini 

çekme ellerimden 

ürkerek

bırak bende kalsın.

O güzel gözlerini 

ayırma bir an gözlerimden 

en güzel hayallere dalayım

bırak içinde kaybolayım.

Çekme dudaklarını 

ürkerek

bırak sonsuzluğu kucaklıyayım.', 'O güzel saçlarını bırak çılgın rüzgara dalgalansın sonra bir gül tak saçlarına  kırmızı bir gül olsun gülümsemeni hiç eksiltme yüzünden  ve ...', ARRAY['Türk Edebiyatı','Şiir','Şair Gezgin']::text[], 8.5, '{"poet":"Şair Gezgin","poet_slug":"sair-gezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öksürük', 'oksuruk-sair-gezgin-qr0c1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir geceydi

bütün geceler gibi

hayalin

sigara ve

ben.

Derken bir öksürük başladı

aniden 

Göğüs kafesimi parçalarcasına 

bir öksürük

-mendilimde kan izleri.......', 'Bir geceydi bütün geceler gibi hayalin sigara ve ben. Derken bir öksürük başladı aniden  Göğüs kafesimi parçalarcasına  bir öksürük -mendili...', ARRAY['Türk Edebiyatı','Şiir','Şair Gezgin']::text[], 8.5, '{"poet":"Şair Gezgin","poet_slug":"sair-gezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oksuruk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '72 Ölü Can', '72-olu-can-sair-gezgin-y84qt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökten boşanırcasına yağan yağmur gibi

Kurşun yağıyordu

sağdan

soldan

yukarıdan.

Yüzlercesi, binlercesi

aldı onlardan nasibini.

Yetmiş ikisinin bedeni dayanamadı

düştü toprağa.

Yaşlısıyla, genciyle

erkeğiyle, kadınıyla

yetmiş iki canın 

bedeni düştü toprağa.

Toprağa düşen 

yetmiş iki canla

yetmiş iki yerimizden vurulduk sanki.

Yetmiş iki ölü can kayıp şimdi

Ne yerleri belli, 

ne mezarları.

Onlardan kalan tek iz

vurulup düştükleri yerde

toprağa dökülen kanları 

ve yüreğimizdeki acıları..........', 'Gökten boşanırcasına yağan yağmur gibi Kurşun yağıyordu sağdan soldan yukarıdan. Yüzlercesi, binlercesi aldı onlardan nasibini. Yetmiş ikisi...', ARRAY['Türk Edebiyatı','Şiir','Şair Gezgin']::text[], 8.5, '{"poet":"Şair Gezgin","poet_slug":"sair-gezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/72-olu-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-sair-gezgin-7ykfk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saat sabahın beşi

Kapı çalındı

Uyuyordu O

Uyandırıp alıp götürdüler

O uykulu

gözlerini ovuşturuyor.

O şaşkın 

ne olup bittiğini anlayamıyor.

O çocuk 

henüz on iki yaşında.

Anası çaresiz

babası çaresiz

kardeşleri şaşkın.

Alıp götürdüler O''nu

Dövdüler.........

dövdüler..........

dövdüler..........

Ve sonunda 

İtiraf ettirdiler.', 'Saat sabahın beşi Kapı çalındı Uyuyordu O Uyandırıp alıp götürdüler O uykulu gözlerini ovuşturuyor. O şaşkın  ne olup bittiğini anlayamıyor....', ARRAY['Türk Edebiyatı','Şiir','Şair Gezgin']::text[], 8.5, '{"poet":"Şair Gezgin","poet_slug":"sair-gezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/itiraf-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asırlık Aşk', 'asirlik-ask-sair-gezgin-zsmuo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aynı anda

iki tohum düştü toprağa

aynı anda

kurumu çorak topraklara

Yaşamak zor

bu kurtlar sofrasında

yanlışlarda, 

riyalarda, 

yalanlarda, 

dolanlarda.

Tutunabilmek zor

tozu dumana katan 

fırtınalarda, 

kasırgalarda.

Fakat 

öyle bir yağmur yağdı ki

inceden inceye

sevgi''yle.......

toprağa daldılar, 

gömüldüler beraber.

Önce kök saldılar toprağa

ve önce kökleri karıştı birbirine

sarıldılar

sarıldılar yılların özlemiyle

sarıldılar dostlukla

sarıldılar sevgiyle

yalansızca, 

riyasızca, 

sarıldılar aşkla.

Ve birgün 

toprağı yarıp yeşerdiler, 

canlandılar, 

göz kırparak açtılar

yüreklerini

sevgi''li dünyaya........

Ve şimdi

asırlık iki çınarız seninle

kökleri, 

dalları, 

damarları, 

birbirine karışmış

asırlık iki çınar.

Asırlardır BEKLENEN.........', 'Aynı anda iki tohum düştü toprağa aynı anda kurumu çorak topraklara Yaşamak zor bu kurtlar sofrasında yanlışlarda,  riyalarda,  yalanlarda, ...', ARRAY['Türk Edebiyatı','Şiir','Şair Gezgin']::text[], 8.5, '{"poet":"Şair Gezgin","poet_slug":"sair-gezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/asirlik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme istersen', 'gelme-istersen-emine-sumra-6c8xn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni bekliyorum hasretle, kekik kokuları yaydığım dağlarda.

           Terimi damlattım her adımda kokumdan izimi bul diye

           Bu dağlar varya bu dağlar vede üstündeki bitkiler.

           Hepsi tek tek şahittir sensizliğime.

           Her yaprağına adını yazdım, patikalarını umutlarıma çıkardım.

           Yeşilin her tonuna bezedim seni, bakışlarını meşelere yaydım

           Yaydımki sararıp dökülsün avuçlarıma.

           Bari onlar benim olsun.

           Seni öyle özlüyorumki

           Yanımdan geçen her rüzgara, her buluta seni soruyorum

           Ne yapayım bir tanem seni çok seviyorum..', 'Seni bekliyorum hasretle, kekik kokuları yaydığım dağlarda.            Terimi damlattım her adımda kokumdan izimi bul diye            Bu dağ...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gelme-istersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk Ölüm', 'soguk-olum-salih-ozalasan-q0bwa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açılırken toz penbe güller yanağımda

Dökülürken mutluluk şarkıları dudağımda

Taşınırken bir öğle üzeri kardeş kucağında

Geldi buldu beni soğuk ölüm

Bilmezdim böylesine kara yazıldığını

Benim alnıma kader denen yazının

Bir öğle üzeri vurmasıyla yere başımın

Geldi buldu beni soğuk ölüm

Kardeş ana bacı tüm dostlarım

Yaş yerine kan döküp ağlarken başucumda

Bir yastığa baş koymadan

Geldi buldu beni soğuk ölüm

Gözlerim açık kaldı doymadım gençliğime

Ağlamak olmadı nasip başucumda sevdiğime

Bakamadan derya deniz kömür gözlü yarin yüzüne

Geldi buldu beni soğuk ölüm

Tutam tutam saçıldı yerlere sırma siyah saçım

Aktı oluk oluk yerlere kan kırmızı kanım

Sürünürken yerlerde benim bahtsız başım

Geldi buldu beni soğuk ölüm

Taşındı eller üstünde aziz naaşım

Bir avuç toprak artık benim muradım

Muradıma ermeden ömrümün baharında

Geldi buldu beni soğuk ölüm

İsmimi unutur gidermi bilmem sevdiklerim

Nazlı ceylanım anam babam kardeşlerim

Benim sevdiklerim beni candan sevenlerim

Son arzun neydi diye sormak isteyenlerim

Ben ağlarken ağlayanlarım gülerken gülenlerim

Biranlık yokluğumda yolumu sabırsız gözleyenlerim

Sizlere bir veda bile edemeden

Geldi buldu beni soğuk ölüm

(Çok sevdiğim bir gencin anısına)

Yazılış Tarihi 17-04-1981  Saat  12.45', 'Açılırken toz penbe güller yanağımda Dökülürken mutluluk şarkıları dudağımda Taşınırken bir öğle üzeri kardeş kucağında Geldi buldu beni soğ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/soguk-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül İle Bülbül', 'gul-i-le-bulbul-birol-solum-alas4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gül vardı bahçemizin en güzel köşesinde 

Katmer, katmer açılmıştı bu bahar yine 

Çağırıyordu bülbülleri 

Gel gel beni sar beni sev diye 

Bütün bülbüller hepsi bir ağızdan söylercesine 

Seni seviyorum hem de delicesine 

Ama korkuyorum 

Daha sana dokunmadan öleceğim diye 

Ama bir deli bülbül vardı içlerinde 

Şarkıların en güzelini söyleyen 

Şiirlerin en güzelini yazan 

Sevdiği için ölüme güle, güle giderdi deli bülbül 

Bülbül yaklaştı güle, yaklaştı sinsice 

Gül haykırdı daha fazla yaklaşma diye 

Ama nafile bülbül dinlemedi gülü 

Yaklaştı ve dokundu güle 

Gül istemeden sapladı hançerini bülbülün göğsüne 

Bülbül o acıyla bile güldü gülün yüzüne, 

Artık anlamıştı bülbül bu son kanat çırpışlarıydı 

Bir daha çırptı kanatlarını sanki gülü sarmak istercesine 

O gece gülü ağlarken gördün düşümde 

Gözyaşları doldu bir anda avucum un içine 

Uzanıp silmek istedim gözyaşlarını 

Ama kaçıyordu benden bütün kibirliliğiyle 

Ey gül benim bildiğim; sen ağlamaz 

Ağlatırdın hep bülbülü 

Ey gül benim bildiğim; sen kaçmaz 

Çağırırdın hep bülbülü 

Ey gül benim bildiğim; solmaz 

Soldururdun hep bülbülü 

Ben mi seni yanlış tanıdım yoksa değiştin ey gül 

Belki aldığın can için üzülüyorsun ama üzülme 

Bülbül son nefesinde olsa bile 

“kondurdu al yanağına küçük bir buse”', 'Bir gül vardı bahçemizin en güzel köşesinde  Katmer, katmer açılmıştı bu bahar yine  Çağırıyordu bülbülleri  Gel gel beni sar beni sev diye ...', ARRAY['Türk Edebiyatı','Şiir','Birol Solum']::text[], 8.5, '{"poet":"Birol Solum","poet_slug":"birol-solum","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gul-ile-bulbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudunu Yitirme', 'umudunu-yitirme-birol-solum-fksh8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soğuk bir kış gecesiydi kar adeta lapa, lapa yağıyordu. Sessiz sokaklarda ilerlerken adım, adım. Bir köşe başında, bir evin saçağı altına sığınmış bir kız gördüm. Ona doğru yaklaştıkça bana doğru yönelen ve anlam veremediğim o bakışları içimde bir kıvılcımın oluşmasına sebep oldu. Ona doğru daha da çok yaklaştığımda, soğuk ona o kadar işlemişti ki adeta tir, tir titrediğini gördüm. Usulca paltomu çıkarıp ona verdim. Evini sorduğumdaysa birkaç kilometre ileride olduğunu öğrendim. Yavaş, yavaş, sessiz ve ıssız sokaklarda ilerlerken, sanki ikimizde bu sessizliğe konsantre olmuş ve bunu bozmak istemezmişçesine bir tek kelime bile etmeden yürüyorduk. 

Karanlık ve dar bir sokağın başına geldiğimizde, dönüp dudaklarımdan öptü ve kaçarcasına gözden kayboldu. Onun o ıslak ve soğuk dudakları dudaklarıma değdiği anda beynim işlemez duruma gelmiş artık kalbimle düşünmeye başlamıştım. Hemen koşarak eve gelip, yatağıma uzanıp, yastığıma sarılarak pembe hayaller kurup. O anlam veremediğim bakışları çözmeye çalıştım. Sanki beş bilinmeyenli bir denklem gibi. İşte ne olduysa o anda oldu o bakışlardaki sırrı çözmeye çalıştıkça içimdeki kıvılcımlar bir yangına dönüp bütün bedenimi sardı. 

Sabahın erken saatlerinde en güzel kıyafetlerimi giyip, onu ilk gördüğüm o köşe başı ve vedalaştığımız, o karanlık ve dar sokakta; elimde kırmızı bir gülle günlerce bekledim. Ama nafile ne onunla ilk karşılaştığımız ne de vedalaştığımız yerde, onun tarifine uyan ne de o tarifteki birisini tanıyan birisiyle karşılaşabildim. 

Tam ümidimi kaybetmiş ve pembe hayallerimde inşa ettiğim, güllerle donatılmış, bahçeli, o küçücük kırmızı panjurlu evi yıkmaya başlamıştım ki ona bir otobüs durağında rastladım. Kader işte ona güllerle donattığım bahçedeki küçücük ve kırmızı panjurlu evimin anahtarını nasıl verebileceğimi düşünürken, o beni tanımış olmalı ki yanıma yaklaştı. İşte o anda yüzümde güller açtı. Bana o gece yaptıklarım için teşekkür etmeyi unuttuğunu ve kendisini affettirmek için de hafta sonu yapılacak düğün törenlerinde beni de görmek istediğini söyledi. İşte tam o anada yüzümde açan güller soldu ve sanki dikenleri gözüme batıyormuşçasına kanla karışık göz yaşlarım akmaya başladı. 

Kendimden habersiz saatlerce bir ayyaş gibi dolaştım sokaklarda ve kendimi bir deniz kıyısında, bir uçurumun kenarında buldum. İşte tam o anda kendimi ikiye bölünmüş gibi, içimdeki yanan o aşk ateşinin; ancak bedenimi uçurumun kenarından boşluğa, denizin kucağına atarak ve sadece denizdeki dalgaların bedenime çarparak içimdeki yanan aşk ateşin söndürülebileceğini savunan kalbimle düşünen ben ve zaman her şeye çaredir, zamanın çözemediği hiçbir şeyin bulunmadığını ve yüreğime ektiğim aşk tohumlarının belki bir gün filizlenip başka isimlerle, başka bedenlerle karşıma çıkabileceğini savunan mantıklı benle karşılaştım. Uzaktan ve sabırsızca kıyasıya süren bu yaşam mücadelesini izledim. Sonunda bu savaştan kalbimle düşünen ben galip gelmiş ve kendimi tam olarak ölüme hazırlamışken. 

Sanki bir el elime yapıştı bırakmıyordu beni ve rüzgara karışmış bir ses; yapma Birol, yapma bir kız için değmez diyordu. İşte o zamandan beri kendimi ve hayatımı bu elin ve sesin sahibini bulmaya adadım.', 'Soğuk bir kış gecesiydi kar adeta lapa, lapa yağıyordu. Sessiz sokaklarda ilerlerken adım, adım. Bir köşe başında, bir evin saçağı altına sı...', ARRAY['Türk Edebiyatı','Şiir','Birol Solum']::text[], 8.5, '{"poet":"Birol Solum","poet_slug":"birol-solum","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/umudunu-yitirme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçma Sapan Bir Aşk Hikayesi', 'sacma-sapan-bir-ask-hikayesi-birol-solum-mfme2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aynaya her baktığımda 

Artık benden geçti diyorum 

Ama bir türlü; 

Saçımdaki akların, yüzümdeki çizgilerin 

Nedenini sebebini bilemiyorum 

Artık ne kadar da sevmiyorum, sevmeyeceğim 

Desem de sevmeden de yapamıyorum 

Biliyorum eğer sevgilim ben sevmeseydim seni 

O zaman sen sevecektin beni 

Hem de deliler gibi 

Neden sevgilim 

Ben yaklaştıkça sana 

Sen benden o kadar uzaklaşıyorsun 

Neden sevgilim 

Benden köşe bucak kaçıp, saklanıyorsun 

Sadece seni sevdim diye beni suçluyorsun 

Gel, gel de eşe dosta sor beni 

Bunun sabıkası var mı hiç suç işledi mi 

Ben, ben daha karakolun yolunu bile bilmiyorum 

Sen neden beni idamla yargılıyorsun sevgilim 

Bildiğim bir tek şey var sevgilim 

Doğru bildiğin her şeyi 

Utanmadan sıkılmadan söyleyeceksin 

Baktın ki kimse dinlemiyor seni 

işte o zaman meydanlara çıkıp haykıracaksın 

eğer seni sevdim diye 

suçluyorsan hala beni 

o zaman çık meydanlara 

haykır bağır sabahlara kadar 

o beni seviyor suçlu onu asın diye 

İşte o zaman herkes sana hak verir 

Dünyanın her köşesinden insan gelir 

Sadece seni, senin yüzünü görmeye 

Sevginin kaybolmaya yüz tuttuğu 

Böyle bir dünyada kim bu; 

Sevilmekten yakınan 

Sadece bir yudum sevgi için 

Herkes milyarlar harcarken 

Sen ise beleş bir sevgi bulmuş 

Gülüp oynayacakken neden 

Oflar çekip isyan ediyorsun sevgili 

İşte sevgilim o zaman ünlü olursun 

Her gün manşetlere çıkıp boy gösterirsin 

Herkes sever baş tacı eder seni 

Ve Yeşilçam da bile yüzler güler 

Belki bir umut 

Artık Erol TAŞ’ın kadın tiplemesi bulundu diye 

Evet sevgilim bunlar sonunda olacak 

Belki de Neo Nazi’ler bile 

Hitler’in ruhu senin bedenine girdi diye 

Seni kaçırıp sana taparlar, seni ilahları yaparlar 

Bak ben seni ta nerelere kadar çıkardım 

Daha benden ne istiyorsun sevgilim 

Sıra bana gelindiğinde ise 

Herkes ama herkes beni gördüğü her yerde 

Bana küfredecek, hatta beni dövecekler 

Erkeklerin yüzkarası hatta iki yüz karası diyecekler 

Tabi ki bazı fanatiklerde çıkacak 

Bir çok terör örgütünü peşime salacak 

Sonra beni kırmızı bülten de arayacaklar 

Hatta başıma ödül bile koyacaklar 

Ben bu olanlardan sonra bile 

Bak seni hala seviyorum 

Ama sen beni yine sevmeyeceksin 

Vereceğin cevap şu olacak 

Sen benim ayarım değilsin 

Altınla teneke yan yana hiç olur mu diyeceksin 

Hatta o güzelim atasözlerini 

Kendi kötü emellerine alet edip 

Davul bile dengi dengine diyeceksin 

İşte o zaman benim sana olan sevgim 

Ve aynı anda senin ünün ve şöhretinde sönecek 

Çünkü seni hep zirvede tutan 

Benim sana olan sevgimdi 

Artık o da kalmadığına göre 

Şimdi sen de kaldırımlarda sürüneceksin 

Sen hep ağlarken ben hep güleceğim 

Herkes için felaket sayılabilecek günlere 

Ben en mutlu günüm diyeceğim 

Çünkü ben daha da kötü günleri geçirdim diye 

Ellerimin üzerinde emeklesem bile 

Yüzüm hep gülecek ellerim hala var diye 

Yoldan geçen herkes bana küfretse bile 

Ben yine güleceğim 

Kulaklarım hala duyuyor diye 

Yüzüme her tokat indiğinde sanma yüzüm kızarır utanırım 

Ben yine güleceğim 

O tokadın yerine bir tekme yemedim diye 

İşte sevgilim ben sürünmeye alışmışım 

Ama yinede gülebilecek bir şeyler bulabiliyorum 

Ya sen her gün ağlayacaksın 

Çünkü her günün bir öncekinden daha da kötü olacak 

Hayal edeceksin düşüneceksin 

O günlere bir daha dönebilir miyim diye 

İşte o zaman anlayacaksın bütün bu olanları 

Hatalarını görüp sen de seveceksin beni 

Aynen bak böyle benim gibi 

Yazacaksın aktaracaksın duygularını 

İşte o zamanlarda sen son günlerini 

Ben ise sondan bir önceki günü yaşıyor olacağım 

İkimizde çok kolay ve çabuk öleceğiz 

Gürültüler patırtılar çıkarmadan 

Öldüğümüzden hiç kimsenin haberi bile olmayacak 

Belki biz bile öldüğümüzün farkına varmayacağız 

Zaten ben hiç yaşadığımın farkına varmamıştım 

Ama ölmek senin için zor olacak be sevgilim 

Evet bu hikayede burada bitti 

Onlar birbirlerini zor da olsa sevdi 

Ama sonunda ölüm yine galip geldi 

Sizce de öylemi...... 

Hayır yanılmayın...... 

O onunla yine karşılaşacak 

Belki, başka bir zamanda 

Başka vücutlar altında 

Başka, başka olacak her şeyleri 

Sadece sevgileri aynı kalacak 

Bak yine yanlış düşünüyorsunuz 

Bunlar birbirlerini nasıl tanıyacaklar diye 

Aaa orası da biraz ayıp olmuyor mu 

O muhteşem sevgi hep gözlerinde olacaktır 

İşte o iki göz karşı karşıya geldiğinde 

Hiç düşünmeden, kendisine soru bile sormadan 

Koşup birbirlerine sarılacaklar 

Ama o zaman onlar için çok çabuk geçecek 

“ama asla ve asla bitmeyecek”', 'Aynaya her baktığımda  Artık benden geçti diyorum  Ama bir türlü;  Saçımdaki akların, yüzümdeki çizgilerin  Nedenini sebebini bilemiyorum  A...', ARRAY['Türk Edebiyatı','Şiir','Birol Solum']::text[], 8.5, '{"poet":"Birol Solum","poet_slug":"birol-solum","theme":"Türk Şiiri","is_hero":false,"total_lines":125,"source_url":"https://www.antoloji.com/sacma-sapan-bir-ask-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu Kim', 'suclu-kim-birol-solum-94t1y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sarhoşum bu gece 

Üzgünüm, hem de son derece 

Bak sevgilim ne olur beni dinle 

Kavuşturuyorum seni acı gerçeklere 

Ama şunu unutma 

Suçlu gözlerim, ben değilim 

Senden başkalarına baktı diye 

Suçlu kulaklarım, ben değilim 

Yalan sözleri duydu diye 

Dur böyle çekip gitme 

Daha söyleyeceklerim var yine 

Seni sevdiğimi bile, bile 

Nasıl gidersin baba evine 

Bak, bak da beni dinle 

Suçlu ayaklarım, ben değilim 

Güzellerin peşinde koştu diye 

Suçlu ellerim, ben değilim 

Başka elleri tuttu diye 

Kal yanımda ne olur gitme 

Bırakma beni yalnız gecelere 

Kahrolurum ben yine 

Sonunda beni diri, diri gömersin mezara 

Bunu bana yapma çünkü; 

Suçlu şu kahrolası dilim, ben değilim 

Başkalarına sevgi sözcükleri söyledi diye 

Suçlu dudaklarım, ben değilim 

Senden başkalarını öptü diye 

Hadi sevgilim fazla naz etme 

Sen de kalbinin sesini dinle 

Sonunda hak vereceksin bana 

Düşüneceksin kara, kara 

Ama suçu ne olur bende arama 

Suçlu şu deli gönlüm, ben değilim 

Senden başkalarını sevdi diye 

Suçlu damarlarımdaki kan, ben değilim 

Bütün bu olanlar için bana güç verdi diye 

Affet beni sevgilim 

Seni, hiç üzmek istemedim 

Seni senden çok sevdim 

Eğer sen yanımda olmazsan 

Bu dünyadan da çekip giderim 

Bu mısralar bittiğinde 

Suç sende diyeceksin yine 

Bunu her söylediğinde 

Kan sıçrayacak beynime 

Bak daha da üstüme gelme 

Sonra seni de veririm ateşe 

Suçlu ben değilim, suçlu sensin sevgilim, 

Ha bu gün ha yarın geleceksin diye 

Asırlarca seni boşuna bekledim 

Suçlu ben değilim, suçlu sensin sevgilim 

Senin yüzünden bu dünyada hep ezildim 

Ama yine de seni mutlu etmek için, 

Az mı beden değiştirdim 

Suçlu ben değilim, suçlu sensin sevgilim 

Seni her görmek istediğimde 

Sen bir hayal gibi yok oluverdin 

Söyle, söyle sevgilim ben seni sen olmadan 

Daha ne kadar sevebilirim.', 'Sarhoşum bu gece  Üzgünüm, hem de son derece  Bak sevgilim ne olur beni dinle  Kavuşturuyorum seni acı gerçeklere  Ama şunu unutma  Suçlu gö...', ARRAY['Türk Edebiyatı','Şiir','Birol Solum']::text[], 8.5, '{"poet":"Birol Solum","poet_slug":"birol-solum","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/suclu-kim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeyimle', 'her-seyimle-birol-solum-orbcy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani derler ya! 

Ben seni yürekten sevdim diye 

Oysa ben seni yüreğimle birlikte 

Tüm bedenim ve benliğimle sevdim 

Her yanım bir yanına aşık 

Dudaklarım dokunmadan dudaklarına 

Hiç açılmaz 

Gözlerim görmeden gözlerini 

Görmez hiçbir şeyi 

Ellerim tutmadan ellerini 

Tutamaz hiçbir şeyi 

Tenim değmeden tenine 

Hissetmez hiçbir şeyi 

Biliyorum sevdiğim sen de 

Seviyorsun beni 

Beni her gördüğünde 

Yüzünü asıp beni terslemen 

Bizde hayra yorulur 

“sevginin işaretidir” diye 

sonra adamlar tutup beni dövdürtmen 

benimle evlenmek istediğini 

Ve evime olan bağlılığımı 

Sağlamlaştırmak için değil mi 

Ha geçenlerde de ağabeyini çağırıp beni gösterdin 

Her halde bir de ağabeyin beni görsün diye 

Bugün ağabeyin yarın baban ve annen 

Annemiz..... 

Ama dedim ya ben artık söylemekten sıkıldım; 

Dudaklarım dokunmazsa dudaklarına 

Gözlerim gözlerini 

Neyleyim söyle neyleyim 

Ellerim tutmazsa ellerini 

Tenim değmezse tenine 

Neyleyim söyle neyleyim 

Uzanıp dokunamazsam saçlarına 

Öpüp okşayamazsam seni 

Nefes, nefes çekmezsem seni içime 

Neyleyim söyle neyleyim 

Söyle söyle bana 

Ben seni neyleyim', 'Hani derler ya!  Ben seni yürekten sevdim diye  Oysa ben seni yüreğimle birlikte  Tüm bedenim ve benliğimle sevdim  Her yanım bir yanına aşı...', ARRAY['Türk Edebiyatı','Şiir','Birol Solum']::text[], 8.5, '{"poet":"Birol Solum","poet_slug":"birol-solum","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/her-seyimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla', 'anla-birol-solum-u2h9i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer bir gün, 

Oturup da düşündüğünde beni. 

Kalbindeki küllenmiş 

Anılar alevlendiğinde, 

Örümcek bağlamış mektuplarımı 

Okuduğunda, 

Süzülüyorsa gözlerinden, 

Bir damlada olsa gözyaşı 

İşte, o an anla sevgilim 

Seni nasıl sevdiğimi...', 'Eğer bir gün,  Oturup da düşündüğünde beni.  Kalbindeki küllenmiş  Anılar alevlendiğinde,  Örümcek bağlamış mektuplarımı  Okuduğunda,  Süzül...', ARRAY['Türk Edebiyatı','Şiir','Birol Solum']::text[], 8.5, '{"poet":"Birol Solum","poet_slug":"birol-solum","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anla-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanım Sükût', 'i-syanim-suk-t-ahmet-kurnaz-adlf4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir beyaz bulutsun kara bahtımda

bir uzak yıldızsın, elim ulaşmaz.

Hazan yaprağına dönen şu gönlüm, 

sürünür yerlerde, haddini aşmaz.

Gözlerim hep ağlar, ağlar gizlice

gel artık hayalde durma öylece.

Biliyormusun tenim toprak kokuyor.

Bir damlacık yağmura hasret çeker yüreğim.

Küçük görme arada sıralanan dağları, 

aşamadım bir türlü, aşamadım bebeğim.

Ne olur sen gel, bir gün güneş doğmadan, 

Elbistan yollarına henüz karlar yağmadan.

Esen yeller artık getirmiyor kokunu, 

bir yaz sıcağında kavrulur bağrım.

Sanma ki sessizim, isyanım sükût, 

sana ulaşmıyor feryadım, çağrım.

Çile başımda taç, gönül cemaline aç

sensiz geçen şu ömür, vallahi sana muhtaç.

Sevda ki yüreğimden göğe yükselen fidan, 

benim için ekmek sensin, su sensin.

Güneş doğmaz dünyama, bahar bana yabancı

dur de de artık, bu boran dinsin.

Ölüm gelip, yakamı tutmadan ecel, 

ister öğle üzeri, istersen bir sabah gel.', 'Bir beyaz bulutsun kara bahtımda bir uzak yıldızsın, elim ulaşmaz. Hazan yaprağına dönen şu gönlüm,  sürünür yerlerde, haddini aşmaz. Gözler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/isyanim-sukut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün Martı', 'surgun-marti-ercan-kuzu-gqmr9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...

Çünkü bu duyduğun

son şarkısıdır

sürgün bir martının

günbatımına karşı

Gözlerinde umarsız bir

Haliç akşamı

...

(17 Temmuz 2002 -Rotterdam)', '... Çünkü bu duyduğun son şarkısıdır sürgün bir martının günbatımına karşı Gözlerinde umarsız bir Haliç akşamı ... (17 Temmuz 2002 -Rotterda...', ARRAY['Türk Edebiyatı','Şiir','Ercan Kuzu']::text[], 8.5, '{"poet":"Ercan Kuzu","poet_slug":"ercan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/surgun-marti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelime', 'kelime-enis-batur-j3fjk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''İnanılır gibi değil: Bir kelime

arıyoruz şimdi''.Kıyıya yaklasıyorlar  ''Bakma
..........
..........', '''İnanılır gibi değil: Bir kelime arıyoruz şimdi''.Kıyıya yaklasıyorlar  ''Bakma .......... .............', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kelime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Şiir', 'yarim-siir-ercan-kuzu-nbrfk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...

ve

unutma ki

ölü veya diri

duymak için çağıran sesini

ve

bir beyaz gül tomurcuğu gözbebeklerimde

ve

ıpıslak sonsuza dek

türkuaz gözlerinin kıyısında duran

bendim...

(5 Temmuz 2002 -Rotterdam)', '... ve unutma ki ölü veya diri duymak için çağıran sesini ve bir beyaz gül tomurcuğu gözbebeklerimde ve ıpıslak sonsuza dek türkuaz gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Ercan Kuzu']::text[], 8.5, '{"poet":"Ercan Kuzu","poet_slug":"ercan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yarim-siir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz', 'sessiz-ercan-kuzu-36dj0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siz hiç

ağlayan bir gül duydunuz mu? 

Ben gördüm

yüreğim göçtü! 

(Ocak 1994 -İstanbul)', 'Siz hiç ağlayan bir gül duydunuz mu?  Ben gördüm yüreğim göçtü!  (Ocak 1994 -İstanbul)...', ARRAY['Türk Edebiyatı','Şiir','Ercan Kuzu']::text[], 8.5, '{"poet":"Ercan Kuzu","poet_slug":"ercan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sessiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazma!', 'yazma-enis-batur-7ti4z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Racine yirmibeş yıl susmuş, jean, kime 

 neden bu kadar küskün, kendisine 

neden nasıl bunca kitli

tanrım nerede kırdıgım kalem, bir uçt
..........
..........', 'Racine yirmibeş yıl susmuş, jean, kime   neden bu kadar küskün, kendisine  neden nasıl bunca kitli tanrım nerede kırdıgım kalem, bir uçt ......', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yazma-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Mavi', 'yalniz-mavi-ercan-kuzu-881wk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Şu dağları delmeli''

bilirim

Ne çare ki

beş ''deniz'' ötesindesin...

(Şubat 1999 -Schiedam)', '''Şu dağları delmeli'' bilirim Ne çare ki beş ''deniz'' ötesindesin... (Şubat 1999 -Schiedam)...', ARRAY['Türk Edebiyatı','Şiir','Ercan Kuzu']::text[], 8.5, '{"poet":"Ercan Kuzu","poet_slug":"ercan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalniz-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-ercan-kuzu-g6bo3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı bahar sensiz

geçen bahar da sensiz gelmişti

Yakasında karanfiller

elinde güllerle gelmişti geçen bahar da

Yollara lale döktü ruzigar

gelirsin diye

rahmet kokuyor toprak

Bense mahzun geçiyorum çiçekçilerin önünden 

pek severdin beyaz gülleri

Papatyanın kaç çeşidini gördüm bulvarlarda

fallara inanılmaz biliyorsun

Seherlere dua

yüreğime umut ektim

sevda ektim yollarına

Sabırlı ve mütevekkil

(Nisan 1995 -İstanbul)', 'Bu kaçıncı bahar sensiz geçen bahar da sensiz gelmişti Yakasında karanfiller elinde güllerle gelmişti geçen bahar da Yollara lale döktü ruzi...', ARRAY['Türk Edebiyatı','Şiir','Ercan Kuzu']::text[], 8.5, '{"poet":"Ercan Kuzu","poet_slug":"ercan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekliyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Gecem', 'benim-gecem-sair-gizem-qqs3x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gece en soğuk ve en karanlık gecem

Seni gözlerimin önünde sabaha dek hayal ettim

Geldiğin zamanki halini

Nasıl karşılaşacağımızı

İlk sözlerimizin ne olacağını

Ve gelecekteki günlerimizi....

Bu gece en karanlık ve en yalnız gecem

Senden başka heryer zindan gibi

Karanlığın ortasında bir ışık gibisin

Yinede odayı aydınlatmadın

Gülmüyordu yüzün, gözlerini kaçırdın hep

Bir tek kelime bile çıkmadı dudaklarından

Ellerin çok uzaktı ellerimden....

Bu gece en uzun ve en sessiz gecem

Hüzzam bir şarkı dolaşıyor odamın her köşesinde

Sen yinede duymuyordun

Sabaha kadar durdun peki neden

Madem geldin neden benden uzaktın

Neden geldin ne istedin benden 

Gözlerini yumdun, ellerini çektin

Beninmleydin ama benden çok uzaklarda....

Bu gece en yalnız ve en durgun gecem

Bu gece.......', 'Bu gece en soğuk ve en karanlık gecem Seni gözlerimin önünde sabaha dek hayal ettim Geldiğin zamanki halini Nasıl karşılaşacağımızı İlk sözl...', ARRAY['Türk Edebiyatı','Şiir','Şair Gizem']::text[], 8.5, '{"poet":"Şair Gizem","poet_slug":"sair-gizem","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/benim-gecem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-ercan-kuzu-p3a21', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deniz bile yabancı

tanıdık değil

   yakamoz…

Ben böyle bilmezdim ırmakları

kanatları martıların

yabancı…

Üsküdar vapuruna binemiyorum ya

yaslanıp sapsarı saçlarına Haliç’in…

Başımda gökyüzü bile yabancı

bildik değil

   bulutlar...

Hiçbirşeye benzetemiyorum

yıldızları gecelerin

yabancı...

Orion’u seyredemiyorum ya

uzanıp bembeyaz sırtlarına Toroslar’ın...

Sonbahar bile yabancı

aynı değil

   ağaçlar...

Ben böyle yaprakdökümü görmedim

damlaları yağmurun

yabancı...

Sultanahmed’de namaz kılamıyorum ya

dalıp masmavi gözlerine kubbelerin...

(Kasım 1999 -Schiedam)', 'Deniz bile yabancı tanıdık değil    yakamoz… Ben böyle bilmezdim ırmakları kanatları martıların yabancı… Üsküdar vapuruna binemiyorum ya yas...', ARRAY['Türk Edebiyatı','Şiir','Ercan Kuzu']::text[], 8.5, '{"poet":"Ercan Kuzu","poet_slug":"ercan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yabanci-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizim', 'caresizim-sair-gizem-dli90', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah dediğim zaman bilki

İçim sızlıyor 

İçim kanıyor işte

Ne yapayım çaresizim..

Öylece resmine bakmak sızlatıyor içimi

Ah dediğim zaman bilki

Yüreğim yanıyor

Yüreğim kanıyor işte

Ne yapayım çaresizim..

öylece gözlerine bakmak kanatıyor yüreğimi

Bilki çaresizim sensizim

Bilki resmin var, gözlerin var

İçimde yüreğimde

Ah dediğim zaman bilki....

Zamanla sararacak resimler

Sen ah çektiğinde.

Belki soluk bir yüz belirecek karşında

İçin sızlarken yine çaresiz bakacaksın

Solmuş resmime

Bilmem kaç bahar, kaç kış gececek yüreğinde

Ve birgün yine ah çekerken

Bir şarkı sözü gelecek diline

Sen *KADINIM* şarkısını söylerken

Benim yüreğim yanacak sessizce

Çaresiz ve sensiz.

Sararmış resimlerde birtek

Gülen gözlerin silinmeyecek yüreğimden

Ve ben o gözlerindeki gülüşü

Yüreğim haykırırken seyredeceğim

Çaresiz ve sensiz

Belki içtiğim bir kadeh içkiye

Acımı katacağım senin yüreğin acırken

Ben asla ağlamayacağım

Seyrettiğin yüreğindeki gözlerim 

Hüzünlü bakmasınlar diye

Ellerin sıcakmı? 

Dokun yüreğime

Dokun ve hisset sana olan sıcaklığı

Dinle içimdeki fırtınayı

Dur, dinleme sadece seyret

Gözlerim sana anlatabiliyorsa eğer

Ve sen görebiliyorsan orda kendini

Belki çaresiz ama bensiz değilsin

Sen bütün sevginle içimdesin

Yıllar sonra hala atıyorsa bu yürek

İlk günün heyecanıyla doluysa

Korkuyorsa birgün duracak diye

Kendisi için değil 

İçinde sen olduğun için ölmeyecek

DURSADA BU YÜREK...', 'Ah dediğim zaman bilki İçim sızlıyor  İçim kanıyor işte Ne yapayım çaresizim.. Öylece resmine bakmak sızlatıyor içimi Ah dediğim zaman bilki...', ARRAY['Türk Edebiyatı','Şiir','Şair Gizem']::text[], 8.5, '{"poet":"Şair Gizem","poet_slug":"sair-gizem","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/caresizim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir çift gözde…', 'bir-cift-gozde-sema-senel-ex42n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çift gözde…

Huzuru  öfkeye boğan fırtınalar  dudaklarında

Gözleride hırçın dalgalar

Kimbilir kaç sevda tükettin o deniz mavisi gözlerinde

Kimbilir bu kaçıncı gemiydi limansız,  dönüşü olmayan

Kimbilir bilinmez dipsiz kuytularında uğruna kaç yürek takıldı ağında

Bir gün sende konuk olursan sahte hümayun saraylarında

Aldanırsan Gözlerdeki parıldayan sahte yakamozlara

Yelken açarsan dönüşü olmayan yolculuklara

Sende yenilirsen  güvendiğin deryalara

Süzülürse gözlerinden iki damla yaş

Ozaman işte açacağım yelkenimi sonsuza

Ve akacağım o deniz mavisi gözlerinden

Ve sen gözlerinde hapsettiğin tüm sevdalara ağlarken

Anlayacaksın sevmenin ne demek olduğunu

Ve göreceksin bir  çift gözde sevginin nasıl hükme uğradığını 

14.06.02', 'Bir çift gözde… Huzuru  öfkeye boğan fırtınalar  dudaklarında Gözleride hırçın dalgalar Kimbilir kaç sevda tükettin o deniz mavisi gözlerind...', ARRAY['Türk Edebiyatı','Şiir','Sema Senel']::text[], 8.5, '{"poet":"Sema Senel","poet_slug":"sema-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-cift-gozde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Gönül', 'aglama-gonul-sema-senel-qpx07', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vurma yerden yere dertli başını

Dinler yedi düvel ağıt yakışını

Hazırlarlar bir gün mezar taşını

Ağlama gönül sil göz yaşını

Düşürdüler aşkın dilden dillere

Sundular yüreğini yaban ellere

Sürdüler vefayı  çölden çöllere

Ağlama gönül sil göz yaşını

Çok gördü felek yeğane aşıknı

Soğuttular pişmiş sicak aşını

Sevmeyenler bilemez dertli başını

Ağlama gönül sil göz yaşını

Yürekler kör ise derdin göremez

Çektiiğin acıyı kimse bilemez

Ölenler birdaha geri dönemez 

Ağlama gönül sil göz yaşını

..02.02', 'Vurma yerden yere dertli başını Dinler yedi düvel ağıt yakışını Hazırlarlar bir gün mezar taşını Ağlama gönül sil göz yaşını Düşürdüler aşkı...', ARRAY['Türk Edebiyatı','Şiir','Sema Senel']::text[], 8.5, '{"poet":"Sema Senel","poet_slug":"sema-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aglama-gonul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dubleler', 'dubleler-sema-senel-jz86z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her  şey yalandı, 

Yasaktı sevmeler, sevilmeler.

Hepsi boş sözdü, 

Hepsi bir yere kadar...

Ben! 

Birde beni esir alan o yüzsüz, 

Üçümüz, 

Hatta dördümüz, 

Ne doğruyu bulabildik, 

Ne de yalnıştan vazgeçebildik, 

İstemeyerek göz göze geldik, 

Tüm sınırları, 

Tüm yasakları çiğneyerek.

....

......

Aslinda bu oyunu oynayan, biz değildik.

28.05.02', 'Her  şey yalandı,  Yasaktı sevmeler, sevilmeler. Hepsi boş sözdü,  Hepsi bir yere kadar... Ben!  Birde beni esir alan o yüzsüz,  Üçümüz,  Ha...', ARRAY['Türk Edebiyatı','Şiir','Sema Senel']::text[], 8.5, '{"poet":"Sema Senel","poet_slug":"sema-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dubleler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Saçlarında Ölmek', 'kirmizi-saclarinda-olmek-mehmet-caner-sumengen-wbqj1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Basit bir denklemi çözer gibi, 

Çözmek isterdim seni...

Ta ki kırmızı saçlarında, 

Bakışlarım takılıp kalana dek...

Öyle garip bir rüzgarım ki, 

Estiğimi hissetmiyorsun...

Ne kırmızı saçlarını okşayabiliyor, 

Ne de yüreğine dokunabiliyorum...

Oysa sert fırtılarda kalıp, 

Yanıbaşında ısınmak isterdim...

Yağmurum olsaydın eğer, 

İnan sırılsıklam ıslanmaktı niyetim...

Ben, kırmızı saçlarında ölmeliyim...', 'Basit bir denklemi çözer gibi,  Çözmek isterdim seni... Ta ki kırmızı saçlarında,  Bakışlarım takılıp kalana dek... Öyle garip bir rüzgarım ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirmizi-saclarinda-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Gül', 'sari-gul-sema-senel-vtyil', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bahceme üç çesit  gül diktim

Birini kırmızı, seni çok sevdiğim için  (sevgi)

Birini sarı, bırakıp gittiğin için  (ümit)

Birini beyaz, gelmeyeceğini bildiğim için  (ayrlık)

Kırmızı gül hemen soldu, sevgisiz kaldığı için

Ardından beyaz gülde soldu, gittiğin için

Ama sarı gül hala solmadı, hep umutla yeşerdiği için', 'Bahceme üç çesit  gül diktim Birini kırmızı, seni çok sevdiğim için  (sevgi) Birini sarı, bırakıp gittiğin için  (ümit) Birini beyaz, gelmey...', ARRAY['Türk Edebiyatı','Şiir','Sema Senel']::text[], 8.5, '{"poet":"Sema Senel","poet_slug":"sema-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sari-gul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Senden Başkasını Sevemem', 'ben-senden-baskasini-sevemem-sair-birtanem-w3b4q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hadi artık  dön birtanem

Buralar sensiz cehennem

Yakıp kavuruyor aşkının ateşi

Ben senden başkasını sevemem

Sevemiyeceğimi hiç düşünemem

Ben sensiz bir halt edemem

Işık saçıyor aşkının ateşi

Ben senden başkasını sevemem

Ölene kadar seni severim

Ahirette de devam ederim

Ruhuma doğuyor aşkının  güneşi

Ben senden başkasını sevemem

Ölürken elimden tutman dileğim

Hep huzurla dolsun ebediyetim 

Nur gibi parlıyor aşkının ateşi

Ben senden başkasını sevemem

17/07/2002', 'Hadi artık  dön birtanem Buralar sensiz cehennem Yakıp kavuruyor aşkının ateşi Ben senden başkasını sevemem Sevemiyeceğimi hiç düşünemem Ben...', ARRAY['Türk Edebiyatı','Şiir','Şair Birtanem']::text[], 8.5, '{"poet":"Şair Birtanem","poet_slug":"sair-birtanem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-senden-baskasini-sevemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar', 'i-ntihar-sair-gezgin-j03uv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bitkinim gülüm, 

yorgunum.

Ölümcül bir bitkinlik bu, 

ölümcül bir yorgunluk

Kapım 

ha çalındı

ha çalınacak gibi

ve ölüm 

her an girecek gibi kapıdan 

Göğsüm daralıyor

nefes alamıyorum

gözlerim dalıp gidiyor ansızın

hissediyorum gülüm 

bulacak beni

bu köhne mekanımda

bulacak beni ölüm

geliyor

ama

bir sen olsan yanımda diyorum

bir sen olsan.', 'Bitkinim gülüm,  yorgunum. Ölümcül bir bitkinlik bu,  ölümcül bir yorgunluk Kapım  ha çalındı ha çalınacak gibi ve ölüm  her an girecek gibi...', ARRAY['Türk Edebiyatı','Şiir','Şair Gezgin']::text[], 8.5, '{"poet":"Şair Gezgin","poet_slug":"sair-gezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/intihar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim', 'vazgectim-sair-gezgin-wyf7j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok şeyler yaptım

çok şeyler denedim 

sensiz olmadı

Güne sensiz başlamaya alışamadım

Rakının sensiz hiç tadı yok

Hele akşam saatleri 

hiç çekilmiyor sensiz

Masamdaki menekşeyi bilirsin

çiçek açtı

ama kokmuyor

Evimin neşesi saka kuşum

sen gittin gideli ötmüyor

Ve ben 

aldım başımı gidiyorum

yolum 

uzun

yolum 

uçzuz bucaksız

Arkamda bıraktım her şeyi

seni, 

menekşemi 

ve saka kuşumu

Ve 

vazgeçtim artık 

senden

menekşemden 

ve saka kuşumdan', 'Çok şeyler yaptım çok şeyler denedim  sensiz olmadı Güne sensiz başlamaya alışamadım Rakının sensiz hiç tadı yok Hele akşam saatleri  hiç çe...', ARRAY['Türk Edebiyatı','Şiir','Şair Gezgin']::text[], 8.5, '{"poet":"Şair Gezgin","poet_slug":"sair-gezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/vazgectim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında', 'aslinda-sair-gezgin-s2cas', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalanları 

bırak bir kenara

sen sadece gerçeklerin tut ellerinden

yanağına düşen her yağmur damlasının hazzına var

mutlulukla gülümse

seslen aşklarına yüksek sesle

bağır 

bağır alabildiğine

yankısı ulaşınca sana sesinin

üzülme

yalnız değilsin

dinle derinden gelen 

bir sevda türküsünün mırıltılarını

kapat gözlerini

görme

yüreğin hissetsin

bırak kendini deli esen rüzgara

savrul

bilmediklerine

savrul 

yenilere, yeniliklere

tanı kendini, 

tanıt kendini

Bir çocuk ol

bir çocuk büyüt

bir ümit öldür...

Bir hançer al eline

Ümitle

Sapla yüreğine korkusuzca

bırak 

aksın gitsin vücudundan geçmişin pis kanları

bırak aksın yanıbaşından

Aslıdır kalması gereken yüreğinde

özüdür insanın 

aslında

Sahi 

aslı var mıydı tüm bunların 

yoksa yalan mıydı

hayal miydi

bir çelişki

bir kaos

Sahi 

ne önemi vardı

dedim kendime

gerçek olan sensin

aslında

aslında olmayan sen.......', 'Yalanları  bırak bir kenara sen sadece gerçeklerin tut ellerinden yanağına düşen her yağmur damlasının hazzına var mutlulukla gülümse seslen...', ARRAY['Türk Edebiyatı','Şiir','Şair Gezgin']::text[], 8.5, '{"poet":"Şair Gezgin","poet_slug":"sair-gezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/aslinda-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Yaşanmıyor!', 'umutsuz-yasanmiyor-mete-parlar-cjecb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşanacaklar yaşanıyor

Alınyazısı deıklerı

Bu olsa gerek.

Peki ya umutlar? 

Yaşanacakları

Çıkarlarımız doğrultusunda

Yaşamamız için

Kuruntular mı? 

Tek bır hafta mı olmalıydı? 

Bana biçilen

Doya doya yaşam? 

Umut yok mu hiç? 

Umutsuz yaşanmıyor be gülüm

Umutsuz yaşanmıyor!', 'Yaşanacaklar yaşanıyor Alınyazısı deıklerı Bu olsa gerek. Peki ya umutlar?  Yaşanacakları Çıkarlarımız doğrultusunda Yaşamamız için Kuruntul...', ARRAY['Türk Edebiyatı','Şiir','Mete Parlar']::text[], 8.5, '{"poet":"Mete Parlar","poet_slug":"mete-parlar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umutsuz-yasanmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvardaki Resimler', 'duvardaki-resimler-mahmut-dogan-oxsfy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüznünü anlayayım diye..

İnsanların resimlerini duvarlara asarım 

Asarımda onlar görmez

birincisi rizeli yaşlı bir kadın 

Ha bire çay toplar toplarda

Kendi içmez...

İkincisi Zonguldaklı bir işçi

Ha bire kazma vurur bir dakikalık 

Sigara içimi türkü tutturur

Tutturur da nedense hep o vurulur....

Üçüncüsü Mardinli bir genç kız

Çukurovada nasırlaşmış elleri

Ve ben diyeyim deniz sende 

Okyanus kederi...

Sonuncusu ben Yaşadığım rivayetten 

Ben çok ağladım dostum...

Çare değil bari sen ağlama.', 'Hüznünü anlayayım diye.. İnsanların resimlerini duvarlara asarım  Asarımda onlar görmez birincisi rizeli yaşlı bir kadın  Ha bire çay toplar...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Doğan']::text[], 8.5, '{"poet":"Mahmut Doğan","poet_slug":"mahmut-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/duvardaki-resimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Güzel Şey', 'yasamak-guzel-sey-mahmut-dogan-jda4p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak güzel şey biliyormusun

Yaşamımızla, aşklarımızla, 

Üzüntülerimizle, sevinçlerimizle

Hele o çocukluğumuz yokmu? 

Hani oynarken kırdığımız pencereler

Kavga ettiğimiz arkadaşlarımız

Hayat ne güzel şey biliyormusun? 

Aslında hayat bir tiyatrodur 

Bazende bir sinema olabiliyor

Senaryosu önceden yazılmış

İçeriği belli olmayan bir sinema 

ancak rol arkadaşını seçme 

Ve senaryoyu oynama şansın var

Buna rağmen hayat güzel şey..

Bazen seni hatırlamak gibi

Hayalini düşünürken bile

Sen yanımda olduğunda bile

Hayat güzel şey biliyormusun

Şartlar ne olursa olsun

Sen varsın ya o yaşamın içinde

Hayat güzel şey biliyormusun

Gençliğiyle, çılgınlığıyla

Mekanıyla, konuğu, komşusu ile

Doğasıyla, saygı ve mükemelliği ile

Hayat güzel şey biliyormusun.....', 'Yaşamak güzel şey biliyormusun Yaşamımızla, aşklarımızla,  Üzüntülerimizle, sevinçlerimizle Hele o çocukluğumuz yokmu?  Hani oynarken kırdığ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Doğan']::text[], 8.5, '{"poet":"Mahmut Doğan","poet_slug":"mahmut-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yasamak-guzel-sey-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece....', 'bu-gece-gulay-atilay-n6tbs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BU GECE

Yarım asrın son hüznüyle geriye baktım

Yaşanmamışlığın puslu penceresinden.

Gecenin koynundayım yine..

Zifrinde adın saklı.

Hüzün demliyorum gözlerimde..

Ne mektup, ne resim, nede şiirler

Bir sevgi ki kelimelerle anlatılmaz

Ağlamak istiyorum....

Ağlamak için gözden yaş mı akmalı? 

Dudaklar gülerken, insan ağlayamaz mı? 

Güzel bir ruh, kalbi bağlayamaz mı? 

Ağlamak istiyorum...

Bardaktan boşalırcasına 

Sensizliğe adım adım koşarcasına 

Gökten yağmur gibi yağarcasına 

''''BU GECE'''' ağlamak, ağlamak istiyorum..

Hüznümün sevince dönüştüğü

Kalbimin sevginle güldüğü..

Dizelerimin seninle dolduğu

''''BU GECE'''' ağlamak istiyorum..

Gülay Atilay..

19 Temmuz 2002/Erenköy..', 'BU GECE Yarım asrın son hüznüyle geriye baktım Yaşanmamışlığın puslu penceresinden. Gecenin koynundayım yine.. Zifrinde adın saklı. Hüzün de...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bu-gece-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Kaldığım Bir Anda', 'yalniz-kaldigim-bir-anda-mahmut-dogan-kt702', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnız kaldığım bir anda

Aklıma düşmüştün

Gözlerinle, gülüşünle

Ve o güzel sesinle

Bilmiyorum ilk defa 

Böyle bir şey hissetmiştim 

Kalbimin hızla atışından tut

Gözlerine bakamıyışım birde

Farklı birşeydi; 

Gözlerine masum bir şekilde Bakışım.

Biraz yorgun biraz ürkek

Birazda sevgi dolu

Dedim ya farklı bir şeydi

Beni kalbinin deriniklerine 

İndirecek kadar güzel bakıyordu

Yüzündeki o temiz gülüşün vardı birde

İnsanı herşeyden arındıran

Ve sadece senin o güzel yüzüne

Tutsak eden bir gülüştü

Geçici bir heves olmadığını 

Gün geçtikçe anlamıştım.

Sanki aradığım boşluk

Sadece sendin..

Sendin sadece

Benim sevebileceğim 

Sanki içinin güzelliği 

Dışına vurmuştu.

Bir şey vardı 

Beni sana iten, 

Bie şey vardı ama ne? 

Neydi o tılsımlı 

Vazgeçemdiğim büyü

Biliyorum çok uzağız birbirimize

Ama kavuşacağız ümidiyle

Kalbimi yeminli bir şekilde 

Senin yanında bırakıyorum..

Ona iyi bak...

Ve Canından bir parçaymış gibi

Her Zaman sev sev  ve sevvv..', 'Yalnız kaldığım bir anda Aklıma düşmüştün Gözlerinle, gülüşünle Ve o güzel sesinle Bilmiyorum ilk defa  Böyle bir şey hissetmiştim  Kalbimin...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Doğan']::text[], 8.5, '{"poet":"Mahmut Doğan","poet_slug":"mahmut-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yalniz-kaldigim-bir-anda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Suya Yazılsa', 'ask-suya-yazilsa-ali-kemal-akyol-n4y09', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne gecler anlatır sana

Uğruna döktüğüm göz yaşlarımı

        ne de mehlika yıldızı

Ram olsan uğruna sevdanın

        yine anlatmaz yasemen aşkı sana

Belki bir gün 

Aşk suya yazılır

Ne hengameler kopar o gün

Gönlümden gönlüne

        işte ogün anlatır ecel kuşu

        gerçek aşkı sana.', 'Ne gecler anlatır sana Uğruna döktüğüm göz yaşlarımı         ne de mehlika yıldızı Ram olsan uğruna sevdanın         yine anlatmaz yasemen a...', ARRAY['Türk Edebiyatı','Şiir','Ali Kemal Akyol']::text[], 8.5, '{"poet":"Ali Kemal Akyol","poet_slug":"ali-kemal-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-suya-yazilsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümlü Bir İzzetle Aldandım', 'olumlu-bir-i-zzetle-aldandim-mansur-tuncay-tasci-q9nfe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Emel, tulu-emel içre beklerken

Melamet bahçesinde turlayan bendim

Efendi bendi idim bendime bela ekerken

Lam-elif miktarı hizaya çekilen bendim

Merhamet istemedi diken güya kendisini meşk etmekte gül

Anlamadı ölümlü bir izzetle aldanmakta gönül

Naz-ı imla eden nazar ham hayal

Sırra erince sıyrıldı yüzünden düştü tül

Umur dediğin durmadan aşınan bendeniz kul

Recmet  madem gölgeni, beden elbisesinden kurtul 

Merhamet dileyelim bana, naz ile niyaz eden sabilerim

Ulaklar efendisine selam edelim

Habibi Haktır imtiyaz eder selat ve selam

Aşkıyla meşk edip dönmekte alem

Mahrumiyet çölünde kuru ağaçlar gibiyim

Merhamet umulur biz acizlerce her dem

En büyük ödül bana kulluğa ehil sayılmam

Dil afeti say baştadır mazeretim

Beklemekteyim kıyamda, sınanma zinciri, kol ve bacakta

Eğer aziz kılmayı dilersen, aziz doğar çocuk, her kucakta

Niyaz ile istemek dilini çözende sensin

Nar ile tevazu doğuran günahı sunanda sen

Ah ile kibrini taşıyan taatta

Şeddad da edermiş insanı taat

Ehil kılınmakmış meğer sırrı-ihsanı

Yatırlara hatır ile dua eylemek heyhat

Meyyus eylermiş yorulmadan yorumlayan insanı

Aşk ile yanarmış meğer nar ile değil hayat

Taşıyamaz aşk ile yandı gönül

Ah yandı, o gül aşkına, bülbül

Şakıyıp döndü durdu, emeli bir pul

Can, canda canan idi, amma canım

Iradı canan boşa döndü bedenim

                                                                   Mansur Tuncay taşcı', 'Emel, tulu-emel içre beklerken Melamet bahçesinde turlayan bendim Efendi bendi idim bendime bela ekerken Lam-elif miktarı hizaya çekilen ben...', ARRAY['Türk Edebiyatı','Şiir','Mansur Tuncay Taşçı']::text[], 8.5, '{"poet":"Mansur Tuncay Taşçı","poet_slug":"mansur-tuncay-tasci","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/olumlu-bir-izzetle-aldandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Tarlası!', 'olum-tarlasi-ayhan-guler-upve8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yavaş yavaş ilerlemekte Rüzgar; 

Aynı çizgide... aynı düzlemde...

Ölüm Tarlasında sessizce

Kan kokusu sarmış heryeri

Fakat: 

Ne bir ceset, ne bir leş; ama yinede bir...

KOŞUŞTURMA

-Mükemmel bir düzen-

... ve kara yapraksız bodur ağaçlar

Asla duyulmayan bir şarkı-

Bukalemun Kralı''ın tek ulaşamadığı yer

''Ve... ''

parlak ama sessiz ve usulcana

bir...

-ÇIĞLIK-

kaybolup gider...', 'Yavaş yavaş ilerlemekte Rüzgar;  Aynı çizgide... aynı düzlemde... Ölüm Tarlasında sessizce Kan kokusu sarmış heryeri Fakat:  Ne bir ceset, n...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Güler']::text[], 8.5, '{"poet":"Ayhan Güler","poet_slug":"ayhan-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-tarlasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sol Yanım', 'sol-yanim-mustafa-ozke-4i9n8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bilmem gecenin kaçı

tenimi okşuyor yalnızlığın saçı

ağrıyor göğüs kirişlerim

ay koynuna alıyor bulutları

başlıyor yağmurun gözyaşları

raylardan bir tren geçiyor

bir tren

sesi ürkütüyor çocukları

çocuklar ağlıyor

ben ağlıyorum

gökyüzü ağlıyor

vuruyor pencereme yağmur damlaları

vuruyor pencereme yağmur

vuruyor pencereme

vuruyor

vuruyor

vuruyor

bilmem gecenin kaçı

sol yanım seni soruyor', 'bilmem gecenin kaçı tenimi okşuyor yalnızlığın saçı ağrıyor göğüs kirişlerim ay koynuna alıyor bulutları başlıyor yağmurun gözyaşları raylar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sol-yanim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca Tepesi', 'karinca-tepesi-ayhan-guler-npxf9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüzgarın uçuşturduğu kumlar; 

Dans ederken havada...

Koşuştururken çayırların üstünde...

sevişirkrn coşkuyla o ılık meltemin koynunda...

Uzakta, o yağmurun ve nemin ağırlığından.

Gezginci..! 

Gezgincinin şarkısı duyulur - pürüzsüz ve

okşarcasına.

Ama kimse onu duyamaz; 

Ruhunu kaybetmiş o melek dışında.

Günlerin o anlamsız maratonunda! ? 

Bakın, biri yolunu kaybetmiş! ! ! 

Alevlerin selamladığı o unutulmaz günde...

Bir Kelebek - takılmış dikenli tele.

Ah, o güzelim kaktüs.

... ve ansızın kapı açılır...

''Bu yumurtalar satılık mı? ''

diye sorulur kabaca...

Perseustur bu! 

Hayır (?)  cevabını asla kabul etmez.

...meltem artık yorulmuştur...

ve kumlar dibe çöker, gölün üstünden.

ve...

bu sefer...

Gezgincinin şarkısı duyulur yeniden...

(usulca uzaktan) 

... bu sefer herkes tarafından...

artık herkes durmuştur...

...

Kabus uyanır: 

''Kimdir beni uyandıran? ! ? ''

''... öyleyse başlasın o görülmemiş kaos! ''

diye buyurur.

ve bir çığlık diğerine tecavüz ederken...

- Kaos başlar, devam eder ve biter.-

Kimbilir nerede o kabuğu yosun tutmuş kaplumbağ? 

...

''Günaydın meltem...''', 'Rüzgarın uçuşturduğu kumlar;  Dans ederken havada... Koşuştururken çayırların üstünde... sevişirkrn coşkuyla o ılık meltemin koynunda... Uza...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Güler']::text[], 8.5, '{"poet":"Ayhan Güler","poet_slug":"ayhan-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/karinca-tepesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-abdullah-karaduman-wv76l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle bir saplandı ki kalbime

Aşkının oku tam ortasından

O hiç acı vermedi, hasretten başka

Hiç çıkarma olurmu onu canım.

Tutamıyorum kendimi

Önce dudaklarım titriyor

Alamıyorum kendimi

Güzelliğin büyülüyor

Bulunmaz bir kardelensin şu dünyada

Seni düşünmek, deli gibi

Uğrunda hiç bıkmadan, usanmadan

Ölmek istiyorum gözümü kıpmadan

Yani senin anlayacağın

Şu fani dünyada

Sevmekmiş önemlisi 

Bir uçan kuşun arkasından bakmakmış 

Ve yakalamakmış martının kanadını.

O martı alıp götürsün beni

Issız adalara, uçsuz bucaksız çöllere

Kalbim rüzgar kanatlı atlılara binsin

Dolaşsın tüm evreni hayalinin peşinde.', 'Öyle bir saplandı ki kalbime Aşkının oku tam ortasından O hiç acı vermedi, hasretten başka Hiç çıkarma olurmu onu canım. Tutamıyorum kendimi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kardelen-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-huseyin-kapan-ko9dg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki ben seni yarattım içimde, kim bilir belki de sen beni

Bir askın uçurumunda bırakıp gittin, bilinmeyen sonsuzluklara.

Gözlerinde görürdüm askı, seninleyken yasardım; elini tutamayınca deliye dönerdim

Gittin uzaklara, bilinmeyen sonsuzluklara, 

Bıraktın beni hem de zamansızca...

İçimden gelmiyor konusmak, gezmek, dolasmak

Mısralara döküyorum hislerimi...

Belki yasamadım böyle bir duyguyu; 

Belki de kandırıyorum kendimi, sanarak yasadıgımı

Içimden geldi iste yazıyorum...

Aklıma geldikçe çıldırır gibi oluyorum

Gözlerim doluyor, doluyor ağlayamıyorum

Bazen, bazen içime atıyorum göz yaşlarımı, 

Bazense bir kanlı kalemle mısralıyorum duygularımı...

Sen yoksun artık, ben yokum, öldürdün seni bende ve öldürdün yüreğimde.

Demiştim hatırlarsın ‘bir kalem ucu genişliğinde’ yaşamıştım aşklarımı, 

Şimdi o kalemin ucunda yazıyorum yaşadıklarımı...

Artık bayramlar o eski bayramlar değil, 

Yürek toplayan o çocuklar artık yok, 

Artık dertlerimi, acılarımı, yalnızlığımı paylaşacak bir yarim, bir dostum yok

Belki ben seni öldürdüm içimde, kim bilir belki de sen beni...

16/11/2000', 'Belki ben seni yarattım içimde, kim bilir belki de sen beni Bir askın uçurumunda bırakıp gittin, bilinmeyen sonsuzluklara. Gözlerinde görürd...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kapan']::text[], 8.5, '{"poet":"Hüseyin Kapan","poet_slug":"huseyin-kapan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/belki-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık', 'artik-huseyin-kapan-e4x54', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık ürkek bir çocuk gibi ekiyorum umutlarımı, düşler tarlasına

Orda asice yeşermeyeceklerini bile, bile

Artık konuşmuyorum buzlu aynalarla

Yaşıyorum umutsuzca, kanlı yaşlarımı sile, sile

Artık yalnızlık gemisinin tek yolcusuyum

Bilmiyorum, yorgun geminin bu son seferi niye

Artık vermiyorum sensiz sağır kalbimi de kimseye

Olurda içinde sonsuz maviliğini görürler diye

Artık bakmıyorum, geçmişi yırtık resimlere

Olurda hiçe sayarım öksüz gururumu diye

Ben galiba sensizlikle de avunamıyorum

Düşüyorum dipsiz karanlıklara, hem de bile, bile... 

14/11/2000', 'Artık ürkek bir çocuk gibi ekiyorum umutlarımı, düşler tarlasına Orda asice yeşermeyeceklerini bile, bile Artık konuşmuyorum buzlu aynalarla...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kapan']::text[], 8.5, '{"poet":"Hüseyin Kapan","poet_slug":"huseyin-kapan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/artik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyor Musun?', 'biliyor-musun-huseyin-kapan-vcl7x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biraz önce ben uyudum biliyor musun? Yine her geceki gibi, gözlerimi o soğuk tavana diktim, yine o gül yüzün canlandı karşımda... Her geceki gibi iki damla yaş süzüldü çölleşmiş kalbimin, en senle dolu yüzüne, yine canım yandı biliyor musun? Yine duygular şaha kalktı, kalkıp bu şiiri yazacaktım ama sen vardın karşımda, alamadım gözlerimi senden, olmadı...

Biraz önce bir rüya gördüm biliyor musun? Yine her geceki gibi benim olmayan seni gördüm, senin olmayan benle birlikte. Umut tarlasından bir yaşlı güvercin uçurduk birlikte, ellerin titreyen ellerime değdi, o arsız gözlerin, puslu yüreğime. Yine gözümden iki damla yaş süzüldü, bu seferde kalbimin en hoyrat köşesine...

Biraz önce ben uyandım biliyor musun? Yine sensiz kalktım o hayali rüyadan, kafamı kaldırdım, tekrar tavana baktım. Sen yoktun bu sefer, sadece bir iğrenç karartı, senin henüz dokunamadığın kalbim gibi, lanet bir karartı. Suskun gözlerimden iki damla yaş süzüldü yine kalbimin her karanlık köşesine...

Biraz önce ben öldüm biliyor musun? Yıkadılar, koydular bir tabuta, taşıdılar el üstünde. Senin evinin önünden de geçtik, eğer pencereyi aralasaydın görürdün sana son yalvarışımı, senin için kalbime akan son kanlı yaşları. Yatırdılar soğuk musalla taşına, kıldılar namazımı, tekrar omuzlarda, getirip yatırdılar o dipsiz uçuruma. Oraya inerken bile aklımda tek sen vardın, orda bile her zamanki gibi iki damla yaş süzüldü buğulu gözlerimden ama bu seferkiler kalbime değil, o kurak toprağa karıştı. Sonra herkes gitti, bir ses çarptı kulağıma, açtım gözlerimi, mezarımın başında seni gördüm, elinde hani o hep bana getirmediğin çiçekler vardı. Usulca bıraktın onları mezarımın üstüne, seninde gözünden iki damla yaş süzüldü ve karıştı toprağa. Nasıl mutlu oldum bilemezsin ve o anda anladım ki, bu sevgimi ölümün bile engelliyemeyeceğini...

Ve biraz önce ben... 

12/05/2001', 'Biraz önce ben uyudum biliyor musun? Yine her geceki gibi, gözlerimi o soğuk tavana diktim, yine o gül yüzün canlandı karşımda... Her geceki...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kapan']::text[], 8.5, '{"poet":"Hüseyin Kapan","poet_slug":"huseyin-kapan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/biliyor-musun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yaşamak', 'seni-yasamak-huseyin-kapan-r6ycv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni yasamak, seni sensiz yasamak, seni senli yasadıkca, sensizligi yasamak...

Seni sevmek, seni sensiz sevmek, seni senli sevdikce, sensizligi sevmek...

Seni özlemek, seni sensiz özlemek, seni senli özledikce, sensizligi özlemek...

Seni düsünmek, seni sensiz düsünmek, seni senli düsündükce, sensizligi düsünmek...

31/01/2001', 'Seni yasamak, seni sensiz yasamak, seni senli yasadıkca, sensizligi yasamak... Seni sevmek, seni sensiz sevmek, seni senli sevdikce, sensizl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kapan']::text[], 8.5, '{"poet":"Hüseyin Kapan","poet_slug":"huseyin-kapan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-yasamak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYATIN ANLAMI NE?', 'hayatin-anlami-ne-abdullah-karaduman-bja7o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömürler zaman içerisinde zaman yaşasalar bile

Dünler tarif edilemeyecek kadar kısa ve acımasızdır.

Velev ki o günlerde, insan ızdırap kazanında kaynamasa bile.

Beyin şeridinde acıların yada sevinçlerin

İz bıraktığı birkaç resim

Ve geriye baktıkça, insanın unutamayıp hatırladığı birkaç sözcük.

Birkaç sevap, birsürü ah vebir yığın günah.

İşte yaşamın arkasında bıraktığı sadece bunlardan ibaret...

İşte yıllar böyle doldu, bazen hızlı bazen yavaş yavaş akıp geçti

Yıllar elbette tükenip, zaman dünya durdukça ilerler, saatler yalan yanlış işler, Zaman bunların potasında eriyip gider

Nevarki hadisesiz, acısız, sevapsız, günahsız olarak değil.

Zaman ömrün akrebi ve yelkovanıdır, o çalıştıkça ilerleyen...', 'Ömürler zaman içerisinde zaman yaşasalar bile Dünler tarif edilemeyecek kadar kısa ve acımasızdır. Velev ki o günlerde, insan ızdırap kazanı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayatin-anlami-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Dostum...', 'ey-dostum-huseyin-kapan-gxcev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '‘’Biten bir dostluğun külleri, bütün bir ömrü karartmaya yeter’’. 

Ey benim bin yıllık dostum; bak karardı artık ömrüm. Ben, ben karanlıklar ülkesindeyim artık, biten dostluğumuzun savurduğu küllerle...

Ey benim bin yıllık dostum; hatırlar mısın o geçen günleri, seninle kurduğumuz hayalleri, yaşlı günlerde yazdığımız şiirleri ve tarifi olmayan o dostluk günlerini...

Ey benim çok yıllık dostum; hayat yolun açık olsun, dileklerin, özlemlerin, hayallerin hep gerçek olsun ve sana en laik insanlar hep yanında olsun...', '‘’Biten bir dostluğun külleri, bütün bir ömrü karartmaya yeter’’.  Ey benim bin yıllık dostum; bak karardı artık ömrüm. Ben, ben karanlıklar...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kapan']::text[], 8.5, '{"poet":"Hüseyin Kapan","poet_slug":"huseyin-kapan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ey-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KOLAY MI SENİ UNUTMAK?', 'kolay-mi-seni-unutmak-abdullah-karaduman-cmn9u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kolaymı gözlerinden uzak durmak? 

Alaca karanlığında özlemin, 

Kolaymı seni unutmak? 

Bulmuşken kaybolan yıllarımın içinde.

Uzayan yollara sitem etme sakın

Bizi ayıran o insafsız yollar

Yine kavuşturacak...

Sen yeterki sabret.', 'Kolaymı gözlerinden uzak durmak?  Alaca karanlığında özlemin,  Kolaymı seni unutmak?  Bulmuşken kaybolan yıllarımın içinde. Uzayan yollara s...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kolay-mi-seni-unutmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-i-rfan-cebeci-0a582', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüya! Sen misin? 

Uykudayım, uyuyorum; 

Yüzünde sürgün, 

Aklımda Sen misin? 

Rüya! Bitmesin.

Uzaktayım görüyorum; 

Yanımda resmin, 

Ay yüzlüm sen misin? 

Rüya! Gülüşün; 

Umudumuz biliyorum, 

Yaprakta sürgün, 

Avcumda gül müsün? 

Rüya! Gidişin; 

Ufuktayım görüyorum

Yağmurlar üzgün, 

Aklımda Düş müsün?', 'Rüya! Sen misin?  Uykudayım, uyuyorum;  Yüzünde sürgün,  Aklımda Sen misin?  Rüya! Bitmesin. Uzaktayım görüyorum;  Yanımda resmin,  Ay yüzlü...', ARRAY['Türk Edebiyatı','Şiir','İrfan Cebeci']::text[], 8.5, '{"poet":"İrfan Cebeci","poet_slug":"i-rfan-cebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruya-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimler', 'resimler-toprak-altinova-t53h0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüzünlü    bi  akşam  üstü, 

Kapıyı  çalan.

Ansızın  sayfalarında  kaybolup, 

Geçici şeylerle  sizi  heveslendirir, 

Resimler.

Görmek  ise  niyetiniz, 

Eğer  efkarın  resmini, 

Uluyan  kurtlar  gibidir  resimler.

Fırsat  vermez  hiç  bir  şeye, 

Ne  sevince, ne   kedere.

Bir  boşluğun   içinde, 

Size  bağırır  resimler.

Sönen  bir  kandil  gibi, 

Bir  anda  diner.

Uzun  yolculukların, 

Dönüşü  gibidir  resimler.

Eve  döndüğünüzde,                                                                                                           Yakalar  bazen sizi.

Denizin  içindeki, 

Yılan   gibidir  resimler.

Namüsait anların, 

Heveslisidir  o.

Buruk  bir  sevincin  içindeki, 

Kahredici   acıdır  resimler.

Sonsuzlukta   bir  toz   zerresi, 

Bir  odanın  içinde, 

Vahşi  bir   hayvan  gibidir, 

Resimler', 'Hüzünlü    bi  akşam  üstü,  Kapıyı  çalan. Ansızın  sayfalarında  kaybolup,  Geçici şeylerle  sizi  heveslendirir,  Resimler. Görmek  ise  ...', ARRAY['Türk Edebiyatı','Şiir','Toprak Altınova']::text[], 8.5, '{"poet":"Toprak Altınova","poet_slug":"toprak-altinova","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/resimler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım Sana', 'asigim-sana-soner-salih-e1zpr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşığım sana; 

Denizler, nehirler, dağlar gibi

Vurulmuşum sana kurşunun kalbime vurduğu gibi

Tutulmuşum sana; 

Kelepçenin ellerimi tutup sardığı gibi, 

Ayrılamam senden; 

Etin tırnktan ayrılamadığı gibi

Fakat ayrıldın benden; 

HER AŞKIN SONUDA OLDUĞU GİBİ', 'Aşığım sana;  Denizler, nehirler, dağlar gibi Vurulmuşum sana kurşunun kalbime vurduğu gibi Tutulmuşum sana;  Kelepçenin ellerimi tutup sard...', ARRAY['Türk Edebiyatı','Şiir','Soner Salih']::text[], 8.5, '{"poet":"Soner Salih","poet_slug":"soner-salih","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/asigim-sana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki-lem', 'i-ki-lem-ercan-kuzu-lborl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni bulmak

duyabilmek yürek ezgini

ne güzel...

Seni yitirmek

buldum derken

bir alaca sağır griliğinde metropolün

öylece akıp gitmek 

umarsız

kardeş yıldızları olmak

başka yörüngelerin

ne yazık...

Sahi

gitme desem

gitmesem

gitme-sen...

(Haziran 2001 -Schiedam

Haziran 2002 -Rotterdam)', 'Seni bulmak duyabilmek yürek ezgini ne güzel... Seni yitirmek buldum derken bir alaca sağır griliğinde metropolün öylece akıp gitmek  umarsı...', ARRAY['Türk Edebiyatı','Şiir','Ercan Kuzu']::text[], 8.5, '{"poet":"Ercan Kuzu","poet_slug":"ercan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/iki-lem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Sen Ol Yanımda da', 'var-sen-ol-yanimda-da-mevlut-aydin-aa9br', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Var sen ol yanımda da

Bahar istemem mevsim kış olsun

Kar yağsın dağlar önüme engel olsun

çığ düşsün peşime kaçtıkça kovalasın

Var sen ol yanımda...

Var sen ol yanımda da

Güneşi bana haram etsinler

Gece karanlığıyla dolu 

bir labirentte kaybolayım

Bardaktan boşanıcasına yağmur yağsın üstüme

Var sen ol yanımda...

Var sen ol yanımda da

Tüm sevdiklerim vefasızlık kılıncını kuşansınlar

Umut ektiğim bahçeleri sel götürsün

Su yerine zehir akıtsın çeşmeler

var sen ol yanımda...

Var sen ol yanımda da

Ölüm en soğuk en dehşetli yüzüyle 

çalsın kapımı

En samimi en sıcak duygularımla

gülümseyerek açayım çalan kapıyı

var sen ol yanımda...

(19/07/2002)', 'Var sen ol yanımda da Bahar istemem mevsim kış olsun Kar yağsın dağlar önüme engel olsun çığ düşsün peşime kaçtıkça kovalasın Var sen ol yan...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Aydın']::text[], 8.5, '{"poet":"Mevlüt Aydın","poet_slug":"mevlut-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/var-sen-ol-yanimda-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçına Ak Bulaşmadan Gel', 'sacina-ak-bulasmadan-gel-i-lhan-yuksel-s7jfg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hür uç kelebek gibi 

Şu ağlarını yırt gel 

Her an gelecek gibi 

Çöl aş deniz kurut gel 

Dağlar çiçeğe durur 

Şu dalgalar kudurur 

Bağlara meltem vurur 

Elinde demet tut gel 

Viran bağa vurmadan 

Gözyaşım kurumadan 

Sabah kalk yüz yumadan 

Güzelliğini korut gel 

Gam yüzümü germeden 

Bağında gül dermeden 

Gün kemale ermeden 

Tut şu sözünü tut gel 

Gönlüm ümidin keser 

Baykuş ötüp sam eser 

Yoksa gül bağa küser 

Olanları unut gel 

Ağaçlar sararmadan 

Havalar kararmadan 

Şu gün ufka varmadan 

Gel artık son umut gel 

Saça ak bulaşmadan 

Kemale ulaşmadan 

Şaşırıp dolaşmadan 

Hatıran bu yurtta gel', 'Hür uç kelebek gibi  Şu ağlarını yırt gel  Her an gelecek gibi  Çöl aş deniz kurut gel  Dağlar çiçeğe durur  Şu dalgalar kudurur  Bağlara me...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sacina-ak-bulasmadan-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşu Boşuna', 'bosu-bosuna-kamil-boyraz-3o9a8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nefesim buz kesti dudaklarımda

Çağlarken göz yaşım yanaklarımda, 

Başka birisi varken kollarında

Yasını tutmuşum boşu, boşuna.

İnceden bir sızıydın içerimde, 

Senin için sırt çevirdim kadere, 

Hançer vurdum seni çalan geceye, 

Talihime küstüm boşu, boşuna.

Yanarım kışa dönen baharıma, 

Acırım cehennem olan yazıma, 

Yağmurla yarışan göz yaşıma, 

Göz yaşım kurudu boşu, boşuna.

Senin şimdi yaptıkların oldu mu? 

Benimle yeşeren gülün soldu mu? 

Allahım sen affet kötü kulunu.

Sevmişim delice boşu, boşuna.', 'Nefesim buz kesti dudaklarımda Çağlarken göz yaşım yanaklarımda,  Başka birisi varken kollarında Yasını tutmuşum boşu, boşuna. İnceden bir s...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bosu-bosuna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-toprak-altinova-p78u0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat, bir uçurtma sanki, 

                               Her rüzgarda yalpalnıyor.

                               Bir bardak su içen bir daha doymuyor.

                               Hayaller, cehennem  gibi sıcak, 

                               Anıldıkları zamansa, 

                               Tek kelimetle saltanat.

                               Terk edildiklerinde, 

                               Bir ömür  boyu  ızdırap.

                              Ölüm: Korkana vahşet, 

                              İsteyene rahmet, 

                              İntaharda ise cehalet.

                             Sukut kurtulmak isteyeni bulur, 

                             Nefs, verdiçe şımarı ve kudurur

                             Ve sonsuz hatyat, 

                             Kendini  arayanı  bulur.

                            Ölüye sormuşalar: Han nasıl, yolcukar nasıl? 

                            Demiş ki: ^^Hey hat! Yatanda  da gaflet! 

                            Ayaktakinde de gaflet! 

                            Bana  kalan ise, 

                            Çürütecek bir ceset  ve yıkanacak bir ruh.

                            Ümitsizlik, ayrıl  artık yolumdan, 

                            İninde saklanan nefs, 

                            Gelme artık kalbime.

                            Ve sen hayatın  pınarı, 

                            Otur ve kalkma başımdan

                            Büyüyen çile, 

                            Yakmalıyım etrafını, 

                            Bir kor haline geldiğinde, 

                            Sağnak sağnak söndürmelirim seni', 'Hayat, bir uçurtma sanki,                                 Her rüzgarda yalpalnıyor.                                Bir bardak su içen bir da...', ARRAY['Türk Edebiyatı','Şiir','Toprak Altınova']::text[], 8.5, '{"poet":"Toprak Altınova","poet_slug":"toprak-altinova","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayat-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun Sözleri', 'yagmurun-sozleri-toprak-altinova-n71a0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmur çiseliyor, 

Saat sabahın  beşi.

Vahşi akıntılar gibi, sanki

Susamış gönüllere, 

Damla  damla  süzülüyor yağmur.

Gaibden bir ses  duyar  gibi, 

Birden ayağa kalkıyorum, 

Titreterek  ezerken kalbimi...

Yağmuru yaratana koşuyorum.

Hüzün ve sevinç; zaman ve mekan, 

Çekilin karşımdan, 

Siz evrenin buhranları.

Yağmurun vesile olduğu yolda, 

Sonsuzluğa koşanlar  hani? 

Yağmur çiseliyor, 

Saat  sabahın beşi.

Bir ağıt sesi duyuyorum, 

Ama  ne fayda, 

Uzaklarda çok uzaklarda, 

Değişik iniltiler, yakarmalar, çırpınışlar.

Yağmur çiseliyor, 

Saat sabahın beşi

Nerede insanlar? 

Nerede bir iğne  için, 

Kılı kırk  yaranlar nerede? 

Yağmur çiseliyor, 

Saat sabahın beşi.

Sıkılıyorum  yazmaktan, 

Utanıyor elim kağıda dokunmaktan.

Ne vaziyettir ki sonu elem, 

Yağmurun sesini dinleyin, 

Size yol  gösterecek  zamandan.

Yağmur çiseliyor, 

                                                    Saat sabahın beşi', 'Yağmur çiseliyor,  Saat sabahın  beşi. Vahşi akıntılar gibi, sanki Susamış gönüllere,  Damla  damla  süzülüyor yağmur. Gaibden bir ses  duya...', ARRAY['Türk Edebiyatı','Şiir','Toprak Altınova']::text[], 8.5, '{"poet":"Toprak Altınova","poet_slug":"toprak-altinova","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yagmurun-sozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ne Dostlar Gördüm', 'ben-ne-dostlar-gordum-salih-ozalasan-xo1l2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben ne dostlar gördüm

Bir elinde çiçek, bir elinde hançer.

Gerçek dostu bulmaya yetmedi ömrüm

Sen alsan ne farkeder, iki eline hançer.

Bak yıkılmadım, hala ayaktayım

Geride kalan sadece bir miğde bulantısı

Hayret gözlerime inanamıyorum, şoktayım.

Yetmez böyle birşeye insanın günlerce kusması

Belki yine yıkılıp yerlerde sürüneceğim

Dost dost diye ağlarken, aşık VEYSEL gibi

Ama asla girmeyeceğim, 

Toprağın altına, şerefsizin koynuna

Sırtımı yaslamayacağım 

Ulu bir çınar olsada arkamda

Bana yaslanacak belki bir çoban, kimbilir belki

Hayata toz pembe bakan iki aşık

Kimbilir belkide sıkı bir dost çıkacak karşıma

Yüreği temiz iki elinde güller

Ve ben asla yıkılmayacağım

Dallarıma yıldırımlar düşse bile

Tekrar yeşerecek baharda yapraklarım

Yüreğime hançer değil balta vurulsa bile

Benim yaptıklarıma kimse kusmayacak

Gerektiğinde ben vuracağım hançeri kalbime

Çok düşüp kalktım çok, çok ağladım

Geceler boyu çok, ama asla yenilmedim nefsime

Kutlarım bir şişe şampanya patlattım şerefine

Sana hoşçakal dedim, bana güle güle

Sen layık olduğunla yaşa

Ben sıkı bir dost tutacağım gönlüme

Asla acı çektirmeyeceğim

Bir gecede on yaş ihtiyarlayan yaşlı yüreğime

Ve en güzelide ne bilirmisin

Bundan sonra ben hükmedeceğim kalemime

Y.Tar.18-07-2002  Saat 10.45', 'Ben ne dostlar gördüm Bir elinde çiçek, bir elinde hançer. Gerçek dostu bulmaya yetmedi ömrüm Sen alsan ne farkeder, iki eline hançer. Bak y...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ben-ne-dostlar-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bataklıkta Solan Gül', 'bataklikta-solan-gul-salih-ozalasan-bpyp0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ne ihanetler yaşadım gördüm

Birçok geceler ağladım, ölmeden öldüm

Çok haykırdım gecelerin karanlığına

Ama hiç yıkılmadım, Kaldığım yere geri döndüm

Hüzzam şarkılarda aradım çok geceler mutluluğu

Ben boşalan kadehlere çok sevdalar gömdüm

Ömrümden ömür verdim, hain vefasızlara

Ben şu deli gönlüme çok vefasız gömdüm

Kaderin ağları çelikten kuşak

Vermedim kadere fırsat, o ağları ben ördüm

Her defasında yazdım, yazdım sayfalar boyu

Ben çok kara kaplı defter dürdüm

Tüm güller güzeldir dalında amma

Ben bataklıklarda solan çok gül gördüm

Hayat bir entrika ben bin türlüsüyle büyüdüm

Sana alkışlar böylesini ilk kez gördüm

Dün kara olan her şeyin

Bugün sütten çıkmış ak kaşık oluşunu

Hayret ve ibretle sende gördüm

Y.Tar.19-07-2002  Saat 15.00', 'Ben ne ihanetler yaşadım gördüm Birçok geceler ağladım, ölmeden öldüm Çok haykırdım gecelerin karanlığına Ama hiç yıkılmadım, Kaldığım yere ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bataklikta-solan-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senal', 'senal-necip-hikmet-onlqg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geldi yaz bitti bahar

Durur mu hikmet yerinde

Baktı şiir yok derinde

Nerede sevgili ah nerede 

O eski şiirler şarkılar

Adına  türküler yakılan kaşlar

Kala kala kaldı elimize 

Bu mouse bu bilgisayar

yaz necip yaz

seni kim tutar 

Kimseler duymazmı sesini

Karanlık ah karanlık

Bu sanal alemde yok mu 

Yanına bir destek olan 

Necip der ki arkadaşlar

Kandırmayalım kendimizi

Dünya yalan dünya

Bırakalım bu işleri

Ne güzeldir sevmek bir güzeli

Ne güzeldir sevilmek 

Ah nerede yalan orada sanal

Burdan çıkan kıssayı da senal', 'Geldi yaz bitti bahar Durur mu hikmet yerinde Baktı şiir yok derinde Nerede sevgili ah nerede  O eski şiirler şarkılar Adına  türküler yakıl...', ARRAY['Türk Edebiyatı','Şiir','Necip Hikmet']::text[], 8.5, '{"poet":"Necip Hikmet","poet_slug":"necip-hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/senal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüsran', 'husran-necip-hikmet-fe514', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sanal alemde yalnızım dostlar

Bir kafiyelik yaşamdır hayat

Ah ah gelin bana destek olun

Yazın bana şiir bana hüsran

Necip der ki zamanıdır artık yardımlaşmanın

Gelin bana sizde yazın

Kim tutar sizi ah kim tutar

Hadi bakalım ne duruyorsun', 'Bu sanal alemde yalnızım dostlar Bir kafiyelik yaşamdır hayat Ah ah gelin bana destek olun Yazın bana şiir bana hüsran Necip der ki zamanıdı...', ARRAY['Türk Edebiyatı','Şiir','Necip Hikmet']::text[], 8.5, '{"poet":"Necip Hikmet","poet_slug":"necip-hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/husran-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim', 'kalbim-filiz-beduk-q8qem', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uykusuz bir geceyi taşıyor kirpiklerim

gözlerim ufuklara çiziyor hayalini

içince sonbaharın derin sessizliğini

yine bir ney üflüyor ta içerime seni

biliyor musun belki ilk kez fena iyiyim

seni nefesliyorum kalbim duyuyor musun? 

Bir uzun esarette hasretlenen yaşlarım

özgürlüğe akıyor elâ gözelerinden

bir hüzünlü şarkıyı besteleyerek sana

yataksız ırmak gibi arıyorken sesini

gülüşün susturuyor hıçkıran sözlerimi

susuyor musun şimdi? 

Kalbim susuyor musun? 

Gecikmiş bir baharın cilveli esintisi

nefesinden karanfil kokusu getiriyor

ruhumu sağaltıyor kokunla azar azar

bulutlar uçuşuyor üstümüzde hülyalı

hepsi de sana tutkun

hepsi sana sevdalı

hepsi de aşk yağıyor kalbim kuruyor musun? 

Yağmurlar ıslatmıyor artık beni bir damla

ateşli bir deryâya kendimi kilitledim

bir zamanlar karşında tutuşan orman bendim! 

de bana, hangi ölüm böyle büyük şenlikli? 

bir ara dön de üfle yığılan küllerimi 

yangınlar başkentini kalbim görüyor musun? 

Kurtarmaya yetmiyor gerçekler beni senden

dün bitirdiğim portren birden bire canlandı

çapkınca gülümsedin kırmızı tuvalimden

hercai rengim benim 

karanlık kokan mavim 

beni bitirecekse bu sevdâ bitirecek! 

seninle bittiğimi kalbim biliyor musun? 

Damarsız yaprak gibi savruluyorum şimdi

ve kendini açıyor kilitlenen kapılar

senle cehennemde kar, cennette kor âteşim

seninle her tarafta sensiz hiçbir yerdeyim

sana savursa zaman, n’olur orada dursa? 

duruyor musun yoksa? 

Kalbim duruyor musun? 

Türk Dili Dergisi/2006', 'Uykusuz bir geceyi taşıyor kirpiklerim gözlerim ufuklara çiziyor hayalini içince sonbaharın derin sessizliğini yine bir ney üflüyor ta içeri...', ARRAY['Türk Edebiyatı','Şiir','Filiz Bedük']::text[], 8.5, '{"poet":"Filiz Bedük","poet_slug":"filiz-beduk","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kalbim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutabilsem...', 'unutabilsem-nurettin-baykal-0ts3a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim için sen yoksun artık, 

Sildim bakışlarını tül perdelerden..

Rakı şişesinin içinde boğdum seni, 

Seni öldürdüm....

Seni meyhane duvarlarına astım, 

Tüm sarhoşları sana güldürdüm.

Ama hala ağrıyorsun sol yanımda, 

Hala sokak başlarında karşıma çıkıyorsun, 

Birde plaklarda dönen sesin yok mu? 

Birde onu kulaklarımdan söküp atabilsem...

Kıracağım bir gün o hüzzam şarkıyı çalan plakları, 

Seni, 

Sesini, 

Gözlerinin rengini, 

UNUTABİLSEM......', 'Benim için sen yoksun artık,  Sildim bakışlarını tül perdelerden.. Rakı şişesinin içinde boğdum seni,  Seni öldürdüm.... Seni meyhane duvarl...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Baykal']::text[], 8.5, '{"poet":"Nurettin Baykal","poet_slug":"nurettin-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/unutabilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözün kadar', 'gozun-kadar-mustafa-ozke-y928v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gökyüzü gözün kadarsa

sızlıyorsa burnunun direği

ve geceleri sardıysan koynuna

kayan yıldızları seyret

belki yetişirsin yarına

gökyüzü gözün kadarsa

nefrete dönüyorsa hasretin

ve yalnızlığı sardıysan koynuna

kavuşmak için şafak say, yoksa

kollarının arasına yastık koy

gökyüzü gözün kadarsa

ölümlü dünyayı düşün

ve sonsuzluğu sardıysan koynuna

her güzelden tat almaya bak

geri gelmeyecek yaşadığın yaşın

29 ekim 1995 / Sarıkamış / Kars', 'gökyüzü gözün kadarsa sızlıyorsa burnunun direği ve geceleri sardıysan koynuna kayan yıldızları seyret belki yetişirsin yarına gökyüzü gözün...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozun-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-i-smail-gokce-5ha0b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensizlik ölümdür SEVGİLİM bana 

  Etme eyleme gel hadi bana 

  Nazına sazına kurbanım sana

  İnsanca yaşayalım bu aşkı kana kana 

 Sevmek en güzel duygudur

 Erenelerin aşı suyu yoludur

 Viranlarla dolu olsada SEVGİLİM

 İnsanların mutluluk yoludur

 Ya hep ya hiç seversin beni 

 Oyun aynama kırma kalbimi

 Ruhunun derinliginde yokmu sevgi

 Unutma seviyorum seni

 Mutluluğa hazırım SEVGİLİM', 'Sensizlik ölümdür SEVGİLİM bana    Etme eyleme gel hadi bana    Nazına sazına kurbanım sana   İnsanca yaşayalım bu aşkı kana kana   Sevmek e...', ARRAY['Türk Edebiyatı','Şiir','İsmail Gökçe']::text[], 8.5, '{"poet":"İsmail Gökçe","poet_slug":"i-smail-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgilim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğidi Gül Ağlatır', 'yigidi-gul-aglatir-omer-lutfi-mete-chhzr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yiğidi gül ağlatır gam öldürür

Nice namert ava çıksa, tuzak kursa, kurşun atsa; 

Yiğidi çökertmezse kahır.

Bir dem yar hüzünle baksa

Bir gönül gözüyle baksa

Yiğidi gül ağlatır, gam öldürür.

Düşman yılan olup soksa, 

Dokuz kavim taşa tutsa; 

Yiğidi çökertmez kahır.

Bir dem yar hüzünle baksa, 

Bir gönül gözüyle baksa

Yiğidi gül ağlatır, gam öldürür', 'Yiğidi gül ağlatır gam öldürür Nice namert ava çıksa, tuzak kursa, kurşun atsa;  Yiğidi çökertmezse kahır. Bir dem yar hüzünle baksa Bir gön...', ARRAY['Türk Edebiyatı','Şiir','Ömer Lütfi Mete']::text[], 8.5, '{"poet":"Ömer Lütfi Mete","poet_slug":"omer-lutfi-mete","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yigidi-gul-aglatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedim Dilber Didelerin Islanmış (Koşma)', 'dedim-dilber-didelerin-islanmis-kosma-erzurumlu-emrah-bsmfa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dedim dilber didelerin ıslanmış

Dedi çok ağladım sel yarasıdır

Dedim dilber ak gerdanın dişlenmiş 

Dedi zülfüm değdi tel yarasıdır

Dedim dilber sana yazılmış kanım

Dedi niçün böyle edesin sultanım 

Dedim teşne vermiş ince miyanın

Dedi ben sarıldım kol yarasıdır

Dedim seni saran serini vermiş

Dedi beni saran murada ermiş 

Dedim peri yanaklarının kızarmış

Dedi çiçek sokdum gül yarasıdır 

Dedim dilber Emrah aklımı aldın

Dedi sevdiğine pişman mı oldun

Dedim dilber niçin sarardın soldun

Dedi hep çekdiğim dil yarasıdır', 'Dedim dilber didelerin ıslanmış Dedi çok ağladım sel yarasıdır Dedim dilber ak gerdanın dişlenmiş  Dedi zülfüm değdi tel yarasıdır Dedim dil...', ARRAY['Türk Edebiyatı','Şiir','Erzurumlu Emrah']::text[], 8.5, '{"poet":"Erzurumlu Emrah","poet_slug":"erzurumlu-emrah","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dedim-dilber-didelerin-islanmis-kosma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Sahraların Başı', 'bizim-sahralarin-basi-erzurumlu-emrah-ci8ns', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizim sahraların başı 

Duman duman pare şimdi 

Sevişmesi ne hoş olur 

Ayrılması yaman şimdi

Erisin dağların karı 

Ben çekerim ahuzarı 

Kadir mevlam gönder yari, 

Gönül ister hemen şimdi

Benim yarim şimdi çıkar 

Çıkıp da yollara bakar 

Emrah''ı odlara yakar

Boyu selvi, revan şimdi', 'Bizim sahraların başı  Duman duman pare şimdi  Sevişmesi ne hoş olur  Ayrılması yaman şimdi Erisin dağların karı  Ben çekerim ahuzarı  Kadir...', ARRAY['Türk Edebiyatı','Şiir','Erzurumlu Emrah']::text[], 8.5, '{"poet":"Erzurumlu Emrah","poet_slug":"erzurumlu-emrah","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bizim-sahralarin-basi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda Şarkısı', 'veda-sarkisi-ernesto-che-guevara-3pa3m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1. 

Kayalıkta çakılı yelkenli 

sana bırakıyorum veda şarkımı. 

2. 

Benim uzaklardaki ölümümün kanında tohumlanışı da 

kayalar devranının altında değişken köklerle. 

Yalnızlık! geçmişe özlem çiçeği canlı duvarların. 

Yalnızlık, yeryüzünde adanmış faniliğim. 

3. 

Taşımak istemiştim heybemde 

yüreğinin gelip geçici tadını, 

ama kaldı havaya çizilmiş kesin eğrilerle, 

yadsıma oldu umudumun yiğitliğine. 

Giderim hatıradan daha uzun yıllar boyu

kapalı yalnızlığıyla gezginin, 

fakat havaya çizilmiş kesin eğri sanki bana döndü

ve bir işaret koydu pusula kaderime.

Sonu geldiğinde bütün gündelik işlerin

yol yapacağım bir geleceğim olmasa, 

gelmiş olacağım bakışında canlanmaya

kaderimin sırıtan parçası olarak.

Gideceğim hatıradan daha uzun yollar boyunca

zincir halkaları gibi eklenen elvedalarla zamanın akışında.

4.

Dimdik hatıra sonunda düşmüş yola, 

usanmış beni bir geçmişi olmadan izlemekten, 

unutulmuş yol kıyısındaki bir ağaçta.

Uzaklara gideceğim, hatıra

parçalanarak ölünceye yolun taşlarında, 

ve devam edeceğim, içimde

hep o gezginin acısı, yüzümde gülümseyiş.

Bu dönenen bakış ve güç

büyülü bir matador mendilinde.

Alıkoydu kaygı duymaktan tüm çıkarlara, 

hep yitiren bir çizgi oldu benim eğrim.

Ve bakmak istemedim seni görürüm diye

beni isteksizce davet etmeni

mutluluğumun pembe boyalı torerosu

Deniz seslenir bana sevecen elleriyle.

Çayırım -bir kıta-

Dümdüz yayılır, tatlı ve silinmezdir

alacakaranlıkta bir çan gibi.

5.

Bir sicil memuresi karşısında kurumlu bir doktor gibidir

kara bir mikroskopu gösteren bilim.

Sanat... sanat diye arzıendam eden şey

bir Leica''nın kısır mekaniğidir.

Acılar ve kaygılarla dolu bir yerli (ve tabii özlemleriyle

olup da şimdi yiten için

ve onun dönüşünde arzu gönlünde) , 

coca, alkol ve açlığın aptalca gülümsemesiyle.

Üç kuruşa satılan cinsellik

-Amerika''da pek ucuz-

Boş çarşafların umursanmaz hatırası.

Guetamala bıraktın beni

bağrımda derin bir yarayla

ve de acılarını bana emzirme

ya da emme fırsatıyla, 

kahreden bir hıçkırığın belirsiz duygusunda bulan kadını.

Kederleri teker teker birleştiren bir bağ var yine de: 

uyanan insanın haykırışıdır o da.

6.

İşte bugün böyle titrek ellerle

belirsiz bir kayıta koyuyorum prizmamı.

Ağacın olgunluğunu tüketmeden

kasalanmış meyvanın garip tadıyla.

Çağırışını farkedemiyorum bazen

yaşlı, garip kanatlanmış kulemden, 

fakat bazı günler var ki cinselliğin uyanışını hissediyor

ve bir öpücük dilenmeye dişiye gidiyorum

ve böylece beni arkadaş diye çağırmayanın

ruhunu hiçbir zaman öpemeyeceğimi anlıyorum...

Biliyorum ki tertemiz değerlerin kokusu

bereketli kanatlarla dolduracak beynimi, 

Biliyorum ki hayata geçmesi mümkün olmayan

fikirleri barındırmak gibi zevkleri bırakacağım.

Biliyorum ki ölümüne çarpışma günü

halk çocukları benimle omuz omuza verecek, 

halkın savaştığı amacın kesin zaferini

göremezsem eğer

fikri en yüksek geleceğe götürmek için

mücadele verdiğimdendir, 

eski kabuğun tüylerini yolarken

doğan umudun kesinliğiyle biliyorum bunları.', '1.  Kayalıkta çakılı yelkenli  sana bırakıyorum veda şarkımı.  2.  Benim uzaklardaki ölümümün kanında tohumlanışı da  kayalar devranının alt...', ARRAY['Türk Edebiyatı','Şiir','Ernesto Che Guevara']::text[], 8.5, '{"poet":"Ernesto Che Guevara","poet_slug":"ernesto-che-guevara","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/veda-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyar Maria', 'i-htiyar-maria-ernesto-che-guevara-lz7sx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ayağın çukurda, ihtiyar Maria, 

geldim seninle gerçekleri konuşmaya: 

Bir tesbihin dizili acıları oldu hayatın

ne seven bir erkeğin oldu, ne sağlık, ne mal mülk, 

ancak açlık vardı paylaşılan.

Geldim seninle umudundan konuşmaya, 

kızının nasıl olduğunu bilmeden

kuzuladığı o üç ayrı umuttan da.

Sarı sabunla perdahlanmış ellerinin arasına al

bir çocuğunkini andıran bu erkek elini, 

sertleşmiş nasırlarını ve kıvrılmış saf parmaklarını

doktor ellerimin yumuşak utancında ov.

Dinle, emekçi büyükanne, 

inan gelen insana, 

göremeyecek olsan da geleceğe inan.

Tüm bir hayat boyunca umudunu boşa çıkaran

acımasız Tanrıya da dua etme.

Yağlıkara okşayışlarının büyümesini görmek için

ölümden acımasını isteme; 

gökler yeşil ve karanlık hüküm sürüyor sende, 

her şeyden öte kızıl bir intikama sahip olacaksın, 

şafağı yaşayacaklar torunlarının hepsi, 

huzur içinde öl yaşlı mücadeleci.

Bir ayağın çukurda ihtiyar Maria, 

o gideceğin günlerden biri

otuz kefen tasarımı

bakışlarıyla selamlayacaklar seni.

Bir ayağın çukurda, ihtiyar Maria, 

suskun kalacak odanın duvarları

birleşince ölüm astımla

ve sevdaların boğazına dizilince.

Bronzdan dökülmüş üç okşama

(geceni hafifleten tek ışık)

açlıkla kuşanmış üç torun

her zaman bir gülümseme buldukları

yaşlı kıvrık parmaklarını özleyecekler.

Hepsi bu olacak, ihtiyar Maria.

Bir tesbihin dizili acıları oldu hayatın

ne seven bir erkeğin oldu, ne sağlık, ne mal mülk, 

ancak açlık vardı paylaşılan, 

geçti keder içinde hayatın, ihtiyar Maria.

Bulandırdığında gözbebeklerinin acısını

sonsuz dinlenmenin buyruğu, 

ömür boyu angaryadaki ellerin

son şefkatli okşayışı içine çektiğinde

onları düşüneceksin... ve ağlayacaksın, 

zavallı ihtiyar Maria.

Hayır, hayır yapma

bir hayat boyu umudunu boşa çıkaran

umursamaz Tanrı''ya kendini teslim etme, 

ölümden aman dileme, 

korkunç bir açlıkla kuşanmıştı hayatın, 

sonunda kuşandı astımla.

Fakat bildirmek istiyorum ki sana

umutların kısık ve yiğit sesiyle

intikamların en kızılı ve yiğit olanıyla, 

ideallerimin en doğru boyutuyla

yemin etmek istiyorum.

Sarı sabunla perdahlanmış ellerinin arasına al

bir çocuğunkini andıran bu erkek elini, 

sertleşmiş nasırlarını ve kıvrılmış saf parmaklarını

doktor ellerimin yumuşak utancında ov.

Huzur içinde yat, ihtiyar Maria, 

huzur içinde yat, ihtiyar mücadeleci, 

şafağı yaşayacaklar torunlarının hepsi.

YEMİN EDİYORUM Kİ...', 'Bir ayağın çukurda, ihtiyar Maria,  geldim seninle gerçekleri konuşmaya:  Bir tesbihin dizili acıları oldu hayatın ne seven bir erkeğin oldu...', ARRAY['Türk Edebiyatı','Şiir','Ernesto Che Guevara']::text[], 8.5, '{"poet":"Ernesto Che Guevara","poet_slug":"ernesto-che-guevara","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/ihtiyar-maria-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeli Otoportre', 'golgeli-otoportre-ernesto-che-guevara-ox0f1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Genç bir ülkeden, kökleri otlardan doğan, 

(o kökler ki Amerika''nın öfkesini yadsıyan) 

sizlere geliyorum, kuzeyli kardeşlerim. 

Acılı haykırış, umutsuzluk ve inanç yüklü, 

sizlere geliyorum, kuzeyli kardeşlerim. 

Biz ''homo sapiens''lerin geldiği yerden, 

nice yol aldım göçebe ayinleriyle, 

bir haç gibi taşıdığım astımımla 

ve onun özüme yakışmayan mecazıyla. 

Uzundu yol ve çok ağırdı dert 

sürmektedir bende avare adımlarımın kokusu, 

hala batık bir gemidir derinlerdeki özüm 

-kurtarıcı kıyılar görünseler bile- 

dalgalara karşı gönülsüz yüzüyorum 

batık bir gemi oluşumu koruyarak. 

Yalnızım acımasız geceye karşı 

ve biletlerin bıraktığı kesin şeker tadına. 

Avrupa çağırıyor beni yıllanmış şarabının sesiyle, 

sarı etinin soluğuyla, müzedeki eserleriyle. 

Yeni ülkelerin neşeli klarnet sesiyle 

alıyorum karşıdan geniş etkisini 

Lenin''in icra ettiği ve halkların söylediği 

Marks ve Engels şarkılarının.', 'Genç bir ülkeden, kökleri otlardan doğan,  (o kökler ki Amerika''nın öfkesini yadsıyan)  sizlere geliyorum, kuzeyli kardeşlerim.  Acılı haykı...', ARRAY['Türk Edebiyatı','Şiir','Ernesto Che Guevara']::text[], 8.5, '{"poet":"Ernesto Che Guevara","poet_slug":"ernesto-che-guevara","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/golgeli-otoportre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fidel''e Şarkı', 'fidel-e-sarki-ernesto-che-guevara-ivpl3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haydi gidelim, 

ateşli peygamberi şafağın, 

gizli patikalardan ulaşalım 

o yeşil timsahı kurtarmaya, aşkla sevdiğin. 

Haydi gidelim, 

isyankar ve marslı yıldızlarla dolu 

cepheyle aşağılanmayı bozguna uğratarak 

zafere erişmeye ya da ölümle buluşmaya yemin edelim. 

Duyulduğunda ilk atış sesi ve uyandığında 

çalılıklar bakirelere yaraşan bir şaşkınlıkla, 

orada, yanıbaşında, olgun savaşçılar olarak, 

bulacaksın bizi. 

Saçıldığında sesin dört rüzgara doğru 

adalet, ekmek, özgürlük, tarım reformu, 

oradai yanıbaşında, aynı vurgularla, 

bulacaksın bizi. 

Ve yerini bulduğunda bunca emeğin sonunda

zalime karşı doğruluğun uğraşı, 

orada, yanıbaşında, bekçilik edeeken mücadelenin sonuçlarına, 

bulacaksın bizi. 

Yaralı böğrünü yaladığı gün canavar 

milliyetçi bir mızraktır onu orada vuran, 

orada, yanıbaşında, gururlu yüreklerimizle, 

bulacaksın bizi. 

Sanma ki bozabilirler bütünlüğümüzü 

rüşvetle kuşanmış yaldızlı bitler, 

tek istediğim bir tüfek, mermiler ve bir siper. 

Başka hiçbir şey. 

Ve şayet engellerse yolumuzu demir, 

Amerika tarihine geçen 

gerillaların kemiklerini örtmek için 

bir mendil isteriz Kübalıların gözyaşlarından. 

Başka hiçbir şey.', 'Haydi gidelim,  ateşli peygamberi şafağın,  gizli patikalardan ulaşalım  o yeşil timsahı kurtarmaya, aşkla sevdiğin.  Haydi gidelim,  isyank...', ARRAY['Türk Edebiyatı','Şiir','Ernesto Che Guevara']::text[], 8.5, '{"poet":"Ernesto Che Guevara","poet_slug":"ernesto-che-guevara","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/fidel-e-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Burda', 've-burda-ernesto-che-guevara-9u6m0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haykırır paleti tutuşan ressam, ''melezim ben'', 

haykırırlar bana kovalanan hayvanlar, ''melezim ben'', 

sızlanırlar gezgin şairler, ''melezim ben'', 

tekrarlar her köşenin günlük acısında 

rastladığım insan, ''melezim ben'' 

ve altın kaplamalı tahtadan bir bakireyi okşayan 

ölü bir ırkın gizemine varır bu: 

''melezdir benden doğma bu acayip çocuk''. 

Melez değil miyim ben de bir yandan 

çarpışmasında (birleşip, ayrılan) 

aklımı karıştıran iki gücün, 

o güçler ki ağaçta daha olgunlaşmadan 

hapsolmuş meyvenin garip tadını 

hissettiğinde beni çağıran. 

Dönüyorum İspanyol Amerika''sının sınırına, 

kıtayı saran bir geçmişi tatmaya. 

Kayıp gitmektedir hatıra silinmez bir yumuşaklıkla 

bir çan sesiyle ta uzakta.', 'Haykırır paleti tutuşan ressam, ''melezim ben'',  haykırırlar bana kovalanan hayvanlar, ''melezim ben'',  sızlanırlar gezgin şairler, ''melezim b...', ARRAY['Türk Edebiyatı','Şiir','Ernesto Che Guevara']::text[], 8.5, '{"poet":"Ernesto Che Guevara","poet_slug":"ernesto-che-guevara","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ve-burda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomas''la Vedalaşma', 'tomas-la-vedalasma-ernesto-che-guevara-vtk6i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanadır, kuşatılmış arkadaşım, 

ak dağların berrak sularına, 

batık gemi düşünün seni bağladığı yere

gider ayrılık şarkım.

Uyandım bugün

yelkenlerimde kanatlanma arzusuyla, 

haberleşme mumları tutuyorum

duygusuz pusulanın gösterdiği

zaman limanına giderken gemi.

Dilimi rüzgara veriyorum

sözcüklerini gergin gergin tutmak, 

taze acılarından bir şeyler alıp götürmek için

yaşamakta olduğun şaşkınlıkları paylaşmaya.

Yastığını yeşerten

bahar da yitti gitti.

Ayrılışımı kastetmiyorum, 

artık yol almayan gemin için diyorum.

Anlıyorum seni kırık kanatlı kırlangıç, 

isterdim Kastilya çeşmesine götürmek, 

başa çıkabileceğin güçle donatmak.

Olaylara eğilmiş bir doktor olsam bile

onları değitiremiyor, ancak anlayabiliyorum.

Bununla birlikte sihirli bir çözümüm var, 

Bolivya''da bir madende, 

belki de Şili''de, Peru veya Meksika''da

ya da yıkılmış Sonora İmpataratorluğunda, 

Afrika Brezilya''sının siyahi bir limanında ya da

belki de her noktada bir kelime

öğrendiğimi sanıyorum.

Bu çözüm çok basit, 

etrafıyla ilgilenme, saldır tepeye.

Birleştir genç ellerini yaşlı kayayla, 

günden güne ufak dalgalar halinde

kıpırdayan kırmızı mercanlara nabzını daya.

Günün birinde, hatıram ufuğun ötesinde

bir yelkenli olsam bile

ve senin hatıran belleğimde demirleyen

bir gemi olsa bile

geleceğe doğru neşeyle yürüyen

ufuktaki kızıl yoldaşları gördüğümde

şaşkınlıkla haykırmaya başlayacak kuşluk vakti.

O korkunç ve beyaz soğukkanlı kötüler

şaşkınlığa uğramış gece gibi gerisin geri dönecekler.

İşte o zaman, dört duvar arasında

solgun şair, 

evrenin şarkıcısı olacaksın

ve sen bahtı kara, ince ruhlu, hasta şair

halkın güçlü şairi olacaksın.', 'Sanadır, kuşatılmış arkadaşım,  ak dağların berrak sularına,  batık gemi düşünün seni bağladığı yere gider ayrılık şarkım. Uyandım bugün yel...', ARRAY['Türk Edebiyatı','Şiir','Ernesto Che Guevara']::text[], 8.5, '{"poet":"Ernesto Che Guevara","poet_slug":"ernesto-che-guevara","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/tomas-la-vedalasma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıl', 'agil-ernesto-che-guevara-lmsz1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşayan bir şey kalmış taşlarında

ey yeşil şafakların kız kardeşi.

Gerçek mezarları şaşırtır

ellerinin sessizliği.

Rengarenk gözlüklerin türlü keyfiyle

sorumsuz kazma yaralar kalbini

ve yabancı turistin savurduğu aptalca ''oh''

çarpar yüzüne gücendiren hakareti.

Ama canlı bir şey vardır.

Kütüklerden bir kucaklayış sunar orman sana

köklerini tırmalamaktayken merhamet.

Koca bir celep gösterir övendireyi

taht uğruna zaptettiği tapınakların orda, 

ve sen ölmüyorsun hala.

Hangi güçtür seni ayakta tutan

yüzyılların ötesinden

gençlikte olduğu gibi canlı ve kıpır kıpır? 

Hangi tanrı üfler gün sonunda

hayati soluğunu mezar taşlarında? 

Tropiklerin tatlı güneşinden midir? 

Sormalı niye Chichen-Itza''da olmaz? diye.

Ormanların neşeli öpücüğü

ya da kuşların nağmeli şarkısından mıdır? 

Ve niye Quirigua''da daha derindir uykusu? 

Dağların sarp kayalıkları arasında çarparak

çınlayan kaynağın yankısından mıdır? 

İnkalar öldü, ne dersek diyelim.', 'Yaşayan bir şey kalmış taşlarında ey yeşil şafakların kız kardeşi. Gerçek mezarları şaşırtır ellerinin sessizliği. Rengarenk gözlüklerin tür...', ARRAY['Türk Edebiyatı','Şiir','Ernesto Che Guevara']::text[], 8.5, '{"poet":"Ernesto Che Guevara","poet_slug":"ernesto-che-guevara","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/agil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilizehir Bak', 'dilizehir-bak-i-hsan-uncuoglu-qooes', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Millet vatan güven içinde deki ayni ev ayni han

Düzenlen aklın yiğidim Memedim daha bu yol başından.

**

Taşını toprağını doğrusunu duyarlı görüyorsan heran

Yolundaki yapraklar bile filizlenir işte sana koca Vatan.

**

Aah bir olsa! Evin Köy`ünde bir fırsat Eğitimden 

Diyarın Yeşil, Yolun, Bağın Gülistanlık istersen

Çook konuda destek, dayanışma gereklidir herkesten.

*** *

Dam`ına göz dikenlerin gör, yolu hep birdir, değişmez uyuma

Zinde Güçlerin, birliğin için, aldanma Suyuna berrak ayna olsa.

**

Su çatlak delik dinlemez evvel tedbir al sonra geç başa

Nankör namerd çıkar, üste yaban arar hiç görmez kendini arada.

**

Ova gibi açıktan düz bir yol Eve gider görünür belirli

Dağın ardında buyol olur bin, taşlı tuzak geçişli, belli mi? 

**

Tane tane ayrı yollar yoz çıkar, çatallanır pek tehlikeli

Artık bu Vatanda aymazlar kalmasın sahip her gulyabaniyi görmeli.

**

Önce sağlama al güveni eğitim yönetim Kutlu Kutsal neyin var

Başı önü ardı gizli karanlık niyetli hepsi burda ona karşı olurlar! 

**

Heryoldan her kılıkta perde perde dost diye görünür ne tatlı

Aslızehir iğnedilli ufak ufak yabanınlan gelir çok kurnaz hesaplı.

**

Yarma başlar! aah! Baş gitti! gide gide kimi kuşağ kimi Beli

Kuşkuyok değerli ne bulursa herşeye uzanır çözer deliyaban eli! ? . 

**

Kulağına küpe ola uyan bre iki gözüm Fatihim Yavuzum uyan 

Dünyan nereye gider gör örnekleri tuzak yeme artık kalk uykudan.', 'Millet vatan güven içinde deki ayni ev ayni han Düzenlen aklın yiğidim Memedim daha bu yol başından. ** Taşını toprağını doğrusunu duyarlı g...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dilizehir-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oku', 'oku-i-hsan-uncuoglu-ce90l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eh Ali eh! Sen! .okusana sen 

VAR`mısın, YOK`musun ya Sen! . 

HAK YOL`u Kaç olur 

İçin dışın karmaşık var mı bilen, 

***

HAK Bilmek Hak emri ise yüceden 

Neden zor gizli durur herkesten 

Dünya ya güneş herbilgi yolundan 

Aydınlıkla kendini açıklıyor ortadan! 

***

Üstün başın aslın astarın 

Ölçü ile kesip dikilir Uz yolda 

Kaç eskiden kalan Bilgilerle 

Hepbir`ler niçin timarlanır ayni kaşağla, 

***

Önü ardından belli 

Hangi yoldan Akıllara halka yular takılır

Kimler kaç yoldan kimleri 

Yasaklı KÖR tutar kaç vakittenberi 

Sağduyu yolların acep kimden kapalı 

Ne dersin bu nasıl İŞ Aliş 

Bu kul`dan nasıl eylem nere gidiş

Kime Kebab kime uyarlı bu ŞİŞ. 

***

Akıl sahipleri hangi yolda var mı 

Hani kaçhan yolcusu 

Yakından iz süren tez gören varmı

Hak nerde bir nerde kaç ALEMDE! 

***

Kaynağın`dan bileni evvelce aşikare

Halka açılsın demiş anlasınlar diye 

Belli kimlerden neden 

Ne niyetlerle engellenir herkime Okumak! 

Neden kapalı anadile açılmaz kutsal Kitab! 

Sahip Emri degilmi? , 

***

Dogru`suna Sahipten mi ya kaçbilgeden 

Nasıl bir Cesaret! 

Nereden KİMLERDEN gelecek 

Gizlimi? yoksa Gizlilik mi gerek! ! . 

***

Kim kime, kimlere, fend mi düzenlimi bu hesap? 

Yenir mi şişkinmi 

Bilen kim varsa beri gelsin 

Kime ak süt`e beyaz ebyaz mı ne desin? 

HAK hak denir kimbilir kimdedir

Kimler anar onu beribak..Ahretliğim.! .., 

Hakyolun YOZ mu DOĞRU'' mu 

Nerde ney arar nerde Gezersin! ? , .', 'Eh Ali eh! Sen! .okusana sen  VAR`mısın, YOK`musun ya Sen! .  HAK YOL`u Kaç olur  İçin dışın karmaşık var mı bilen,  *** HAK Bilmek Hak emri...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/oku-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığında Yanmak', 'ay-isiginda-yanmak-ahmet-tacyildiz-jtfh4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ay ışığında yan benimle 

ay ışığı karartsın 

verdiği süt kadar beyaz memelerini

ayı ışığında ıslan benimle 

ıslak vücuduna yapışan

kumlar örtsün çırılçıplaklığını

kayalarla sevişen dalgalar

kıskansın sevişmelerimizi

ay ışığında seviş benimle

yıldızlar yorganımız olsun

kumlar yatağımız

terinin tuzu denizin tuzuna karışsın

ay ışığında durul benimle

yorgun sevişmelerimiz ardından

aç kollarını iki yana

uzanırken kumların üstüne

afrodit güzelliğini kıskansın

kybele doğurganlığını

bu tanrısal güzelliğe ay ışığında bakmalıyım

çıplaklığına asılmış her bir damlayı

elmas parlaklığında ay ışığında görmeliyim

her bir kıvrımına ellerim heyecandan titrerken

ay ışığında dokunmalıyım

dudaklarım teninden ay ışığında ıslanmalı

bedenlerimizden önce ruhlarımız sevişmeli

ay ışığında tapmalıyım sana

kumlardan yapılmış altarında

tüm tanrıları ve tanrıçaları

güzelliğin adına

aşkın adına

sevdan adına

sana kurban etmek istiyorum

ay ışığında.....', 'ay ışığında yan benimle  ay ışığı karartsın  verdiği süt kadar beyaz memelerini ayı ışığında ıslan benimle  ıslak vücuduna yapışan kumlar ör...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Taçyıldız']::text[], 8.5, '{"poet":"Ahmet Taçyıldız","poet_slug":"ahmet-tacyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ay-isiginda-yanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağın Çağrısı', 'topragin-cagrisi-ahmet-kurnaz-0aaie', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani, düşler kurduğum çocukluğum nerde, 

nerde bitmez sandığım çocukluğum.

Neredesiniz.

Ak benekli göklere kanat açardım

yıldızlar oynaşırdı gözlerimde.

Ya ümitlerim, 

Bir tutam kırmızı kanarfildi avuçlarımda.

Dünya...en büyük oyuncağım, 

kader.belki çok uzak bir dost, 

En mutlu ben, 

en büyük babam.

Ya şimdi.Can evime kor düştü

darma dağın gönül tezgâhım.

Düşlerin en sonunda ölüm

her günün başında çaresizlik.

Ağlamak, 

gözlerime yabancı, 

yüreğimden eksik olmayan haykırışım.

Bulutlara taktığım parmaklarım titriyor şimdi

ürkek dolaşıyor ayaklarım kaldırımlarda.

VE TOPRAĞIN GEL ÇAĞRISI, 

çınlar kulaklarımda.

 09.ARALIK 1991/Elbistan', 'Hani, düşler kurduğum çocukluğum nerde,  nerde bitmez sandığım çocukluğum. Neredesiniz. Ak benekli göklere kanat açardım yıldızlar oynaşırdı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/topragin-cagrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağa Bir Can Düşüyor.', 'topraga-bir-can-dusuyor-ahmet-kurnaz-gzy7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açılmıyor artık pencerem, Şardağına.

Odamda rehavet, 

dışarıda tipi.

Damarımda kanım isyan ediyor.

Yaşamak kolay, 

ölüm, ayrılıkça zor.

Senin gözlerinde yaş, 

yüreğimde kor.

Buruk sevinçleri yaşayamadım bu kış, 

düşüncelerim kördüğüm.

Hasret bir tutam od kış ortasında

yollar yine eskisi gibi uzun, 

başucumda nankör seneler

ve can sıkıntısı.

Feryadım karşı duvarda asılı, 

düşlerim is bağlamış nursuz.

Pencereme bir kuş konar ötelerden, 

gagasında bir tutam umut.

Acı bekleyişler ateş saçıyor, 

özlem bir topak kar Nurhak dağlarında

tutabilirsen tut.

Her sabah, her akşam ve de her gece, 

yüreğime kan

TOPRAĞA BİR CAN DÜŞÜYOR.

27 ARALIK 1991/Elbistan', 'Açılmıyor artık pencerem, Şardağına. Odamda rehavet,  dışarıda tipi. Damarımda kanım isyan ediyor. Yaşamak kolay,  ölüm, ayrılıkça zor. Seni...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/topraga-bir-can-dusuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar', 'hatiralar-tolga-baydar-9fgin', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Namus bildim seni sevmekten vazgeçmeyi

Aynı yatakta düşleyemem bir başka eşi

Yarimsin, cananım, herşeyimsin sen benim

İnan, hiç olmayacak hayalimde başka birisi

Arnavut kaldırımlı sokaklar dile gelse de söylese

Su içtiğimiz çeşmeler akarken, inim inim inlese

Nazar boncuklu yastıklar, oyalı, işlemeli yataklar

Hepsi şahit aşkımıza, ah keşke sevgimiz bilinse

Lükstrum çiçeğini açtığında, bil ki geri dönerim

Dünü tekrar yaşadığında bu gün, yarın seninleyim

Sana hediye ettiğim kalbim yere düşer, kırılmazsa

Ömrüm bitab olsa da, ben hep seninleyim

Anla artık beni, ağzımdan çıkmasın kötü bir sövgü

Sen beni hala seviyor olsan da, bende kalmadı sevgi

Hata, yalnış arama, vardı ikimizde de bunların hepsi

Yaşanmış onca güzel günler, hatıralarda kaldı şimdi', 'Namus bildim seni sevmekten vazgeçmeyi Aynı yatakta düşleyemem bir başka eşi Yarimsin, cananım, herşeyimsin sen benim İnan, hiç olmayacak ha...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatiralar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Kayık', 'ruzgar-kayik-i-hsan-uncuoglu-ylnqz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her Dilde altı üstü ayni yerin sanma ki ayrı çıkış gidiş belli

Birgün! gecinden olsun taşüstü Sonmüjde Sonbayram mı nedir neyki.

**

Hep bahaneyle çıka gelir biri İmam Kayığında isteyen Tek! 

Kayıklar başka farklımı, ayni tas benzer taşıt, Salatanatlı göğedek.

**

Bilinen avluda kimi kalbler kimi gözler çok yaşlı saygılı neymişsin

Kimi üzgün dostun puslu anılarında gör nasıl gezinir söylenirsin.

**

Hoca ayarlı, kısa hesap toplar sıradan, etraftan, evet, evet! Evet! 

Helalolsun Sarığına Türbanına sağa sola dua saygılarla? helal et et.

**

Kimi omuz kimi el üstü gidene gari gerisin yok değişmez! 

Borç silen haklı da gerinden ne ses verir hiiiç bilinmez.

**

Kısacık her dilden dilekler bilene yollar hep Cennet, 

Geride kalanların daha nice işleri bitmez ama sana selamet.

**

Herbir kitaptan çıkan yol, hak bilinir mi

O Dağ ardında kavşaklar kimbilir acep kaç kalemli.67', 'Her Dilde altı üstü ayni yerin sanma ki ayrı çıkış gidiş belli Birgün! gecinden olsun taşüstü Sonmüjde Sonbayram mı nedir neyki. ** Hep baha...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ruzgar-kayik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişmemişsin', 'degismemissin-ahmet-safak-kk7lf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Degismedim ben ask kokuyorum 

Insanlik gergefinde ask dokuyorum

Inadina sevgi, Inadina ask

Inadina vatan diyorum

Gozlerimde ask yuregimde sen

nasil sevdaliyim bir bilsen

Ben Ayse diyerek fasulye yerken

ah sende birde cikin demesen

Degismedim ben ask kokuyorum 

Insanlik gergefinde ask dokuyorum

Inadina sevgi, Inadina ask

Inadina vatan diyorum', 'Degismedim ben ask kokuyorum  Insanlik gergefinde ask dokuyorum Inadina sevgi, Inadina ask Inadina vatan diyorum Gozlerimde ask yuregimde se...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şafak']::text[], 8.5, '{"poet":"Ahmet Şafak","poet_slug":"ahmet-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/degismemissin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Degismemisim!', 'degismemisim-ahmet-safak-wb0d3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Degismemisim ask kokuyormusum

Egilmeyi bilmiyormusum

