INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairlerle Muhabbet', 'sairlerle-muhabbet-rakip-bay-31koa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'An gelir  insanı öyle boğar ki

İstanbul’un, kalabalık caddeleri

Alıp başımı gidesim gelir bir yokluğa

Yolum Maçka’dan geçer ansızın

Yolda Attila İlhan’a rastlarım

Başında kasketi, boynunda hiç çıkarmadığı atkısıyla

Sıkıştırmış koltuğuna çantasını, yürür yavaş adımlarla Nişantaşı’na.

Yolunu keserim, beraberce otururuz bir ağaç altına

Başlarız havadan sudan konuşmaya.

Sorarım “Hala mektupları gelir mi? “ diye, 

Gülümser, “hala” der…

Kalkarım yanından inerim Beşiktaş’a Akaretlerden

Nasihat almak için bir garip Orhan Veli’den.

Hep aynı yerdedir, sahilde izler martıları

Usulca dokunurum omzuna, ürkütmeden kuşları.

Eliyle vapurları gösterir

Bakakalır giden herbir vapurun gerisinden

Gözleri dolar, ağlayamaz

Serde erkeklik var iken

O kapatırken gözlerini İstanbul’u dinlemek için

Ben kalkarım yanından usulca

Akşam olmuştur artık, dinlemem hiç karanlığı

Eyüp Sultan’da diz çökmüş dua ederken bulurum Necip Fazıl’ı

Ürkerim, gidemem yanına uzaktan izlerim öylece

Ellerini yüzüne sürüp kalkar, tebessüm eder beni görünce

“Selamun Aleyküm” der dokunur omzuma

Benimse dilim tutulur konuşamam üstadın yanında

“Ölümden korkar mısın evlat? ” diye sorar, gülümseyerek

Nutkum tutulur, ben de gülümserim sendeleyerek.

Ben çabalarken derin bir nefes almaya, 

O başlar yüreğime inme gibi inen iki mısraya: 

“Ölüm güzel şey, budur perde ardından haber

Hiç güzel olmasaydı ölür müydü Peygamber? …”', 'An gelir  insanı öyle boğar ki İstanbul’un, kalabalık caddeleri Alıp başımı gidesim gelir bir yokluğa Yolum Maçka’dan geçer ansızın Yolda At...', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sairlerle-muhabbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fulya Camii', 'fulya-camii-rakip-bay-7090h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle kıskanıyorum ki seni

Koca mahallede bir teksin

Cemaatinle buluşunca

Ne kadar mutlu, ne kadar da şensin.', 'Öyle kıskanıyorum ki seni Koca mahallede bir teksin Cemaatinle buluşunca Ne kadar mutlu, ne kadar da şensin....', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/fulya-camii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekledim', 'bekledim-oguz-yildiz-7lybg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep kararmış ufuklarda bekledim seni, 

Islak sevdalara batmış yüreğimin üstünde yürürken, 

Gündoğumundan günsökümüne

Yağan karanlıklarda bekledim.

Her gidişinde, hüzünlere yanan 

Şehrin ışıklarıydı gözlerim.

Acemi bakışlarla süzerken hayatı, 

Ortaçağ artığı gemileri bekleyen

Bir liman gibi bekledim.

Er kişi, duygusunun üstüne gelirmiş

Ben, üstüme gelen  insanlarla bekledim.

Bütün belâlar tanır beni, 

Bütün zifirler tanır, 

Şarktan güneş doğduğunda, 

Gölgem garba uzanır.

Ey sözlerimin ilki ve sonu, 

Gizlerimin en belirgin efsunu, 

Yudumlarken sensiz  hayatı

Islak ve buruşmuş bir yürekle bekledim......

Hep yağmurlarda bekledim seni

Deniz ortasında pınar gibi, 

Sabaha çıkmayan yollarda bekledim.

Gideni durdurmaya yetmedi sesim

Benden önce kalktı, 

Kalbine giden bütün vapurlar

Geceye sessizce bağırdım adını

Karşılıksız  kalmış bir sevda gibiyim

Bir yanım hep yetim

Emirgan sahili tanır beni

Üsküdar sahili tanır, 

Bir ağlasam, 

Yağmurlar bile utanır.

Ey gözlerimin feri, 

Yalnızlık diyarının en güzel perisi, 

Seni beklerken sevdim bu şehri.

Hep  fırtınalarda bekledim seni, 

Zemherinin soğuğunda, 

Temmuz sıcağı gibi

Kurşuni şafaklarda bekledim.

Üstüme gelen gecelerde, 

Sırtından vurulmuş sesimle okudum

Yüreğe dair yazılmış şiirleri

Su gibi türküler geçirdim içimden

Arzın ıslak nameleri düşerken gönlüme

Yine de ağlamadan bekledim

Kanlıca’ nın efsunlu gecelerinde.

Yıllanmış bir yaraya, tuz basar gibiydi yokluğun

Susuzluğunda çatlayan, dudaklarımla bekledim.

Yüreğimin ateşi, denizi harlarken

Şehrin izbelerinde

Bir çınar gibi bekledim.

Gözyaşlarım su katarken,  kılıçların çeliğine

Hayata karşı isyankar duruşumla bekledim.

Kalabalıkların içinde tek başıma yürürken, 

Gözlerimi saplamışken alacakaralı bir ufka

Şiir soluklu yalnızlığımla bekledim............', 'Hep kararmış ufuklarda bekledim seni,  Islak sevdalara batmış yüreğimin üstünde yürürken,  Gündoğumundan günsökümüne Yağan karanlıklarda bek...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yıldız']::text[], 8.5, '{"poet":"Oğuz Yıldız","poet_slug":"oguz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/bekledim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altın Teller', 'altin-teller-rakip-bay-ihho9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu kahpe dünyada hiçbir şey kalp kırmaya değmez

Ola ki kırdığın bir kalbi onarmaya çalışırsın

Unutma, kırık bir kalp altın tellerle onarılsa da yerine gelmez.', 'Bu kahpe dünyada hiçbir şey kalp kırmaya değmez Ola ki kırdığın bir kalbi onarmaya çalışırsın Unutma, kırık bir kalp altın tellerle onarılsa...', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/altin-teller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarsın', 'aglarsin-rakip-bay-61nfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'An gelir boğazına düğümlenir hıçkırıklar

Sigarayı bir yudumla yarılarsın

Ellerinde bir titreme başlar

Gözlerin dolar ağlarsın.

Dindiremez hiçbir şey acını

Boş hayallere dalarsın

Düşünürsün geçmişi

Hesaplaşırsın.

Gülmeyi özlersin çocuklar gibi, 

Yalnız odanda mutluluk ararsın

Boşvermişsindir her şeyi

Gözlerin dolar ağlarsın.', 'An gelir boğazına düğümlenir hıçkırıklar Sigarayı bir yudumla yarılarsın Ellerinde bir titreme başlar Gözlerin dolar ağlarsın. Dindiremez hi...', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglarsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Desem ki', 'desem-ki-rakip-bay-d95sv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Desem ki

Benim için hava kadar gerekli

Su kadar aziz, ekmek kadar mubereksin

Bilirim inanmazsın, belki de gülersin, 

Yok ki elimde sihirli bir değneğim

Dokununca alnına her şeyi göresin

Gerçi üzülmem hiç inanmamana

Mühim olan içimdekilerdir benim

Ben hepsine inanıyorum ya...', 'Desem ki Benim için hava kadar gerekli Su kadar aziz, ekmek kadar mubereksin Bilirim inanmazsın, belki de gülersin,  Yok ki elimde sihirli b...', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/desem-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Love', 'love-rakip-bay-h6itq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I didn''t say love, for this

The love is only four letter

It can''t explain better', 'I didn''t say love, for this The love is only four letter It can''t explain better...', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/love-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür', 'omur-rakip-bay-r6mwo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ömür iki elimin arasında tuttuğum bir avuç kar

Yürürüm bir çölde güneş eritene kadar

Bakakalırım düşen herbir damlanın ardından

Bu gece de öfkem edebimi aşar.', 'Ömür iki elimin arasında tuttuğum bir avuç kar Yürürüm bir çölde güneş eritene kadar Bakakalırım düşen herbir damlanın ardından Bu gece de ö...', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/omur-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Vardır', 'gun-vardir-rakip-bay-aet69', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün vardır gelmek bilmez, 

Gün vardır geçmek bilmez

Dün çoktan geldi geçti

Dünün yarını bak yine bitti.', 'Gün vardır gelmek bilmez,  Gün vardır geçmek bilmez Dün çoktan geldi geçti Dünün yarını bak yine bitti....', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gun-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulüm', 'zulum-rakip-bay-95b1p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hakka hak demeyenin hakkıdır ölüm, 

Hak ile batılı ayıramamaktandır bunca zulüm.', 'Hakka hak demeyenin hakkıdır ölüm,  Hak ile batılı ayıramamaktandır bunca zulüm....', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/zulum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maziyi Anınca', 'maziyi-aninca-ali-ayyildiz-1rb2y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen insan dalar inceden

Kovalar kendi benliğini

Maziye dalar derinden

Kaybeder kendi kendini

Birden silkinir aniden 

Döner gerçek hayata

Ağlamaya başlar sessizce

Başlayınca maziyi anmaya', 'Bazen insan dalar inceden Kovalar kendi benliğini Maziye dalar derinden Kaybeder kendi kendini Birden silkinir aniden  Döner gerçek hayata A...', ARRAY['Türk Edebiyatı','Şiir','Ali Ayyıldız']::text[], 8.5, '{"poet":"Ali Ayyıldız","poet_slug":"ali-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/maziyi-aninca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarını Yaşıyorum', 'yarini-yasiyorum-zeki-ergin-bws4s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çocukluğumu aramıyorum artık

ne kumlardan mendirek yaptığım 

ne de köşekapmaca oynadığım günleri

şimdi  kafamı her gün gıranit kayalara çarpıyorum

hergün kolum kanadım kırılıyor

hergün binlerce kol kazanıyorum

çocukluğumu aramıyorum artık

ne gökgürültüsünden korktuğum günleri

ne de saçımın okşanmasını

dünü değil

ben artık yarını yaşıyorum

_istanbul 1974

_çorlu ekspres15tem74 sayı:3597

_çağdaş türk şiiri sayı:8 ağus74 

_dağlara ver sırtını yt:haz09', 'çocukluğumu aramıyorum artık ne kumlardan mendirek yaptığım  ne de köşekapmaca oynadığım günleri şimdi  kafamı her gün gıranit kayalara çarp...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yarini-yasiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim Seni', 'bekleyecegim-seni-bertolt-brecht-ghlep', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Savaşa gitmek mi istersin, git asker, 

Gidenin bir daha gelmediği

Kanlı, kuduran savaşa.

Burda olacağım geri dönersen, 

Yeşeren karaağaçlar altında bekleyeceğim seni, 

Bekleyeceğim çıplak ağaclar altında, 

Dönünceye dek en son asker, 

Bekleyeceğim seni daha da çok.

Sen geri gelince savaştan

Göremeyeceksin kapıda başka bir çizme.

Yanımdaki yastık hep boş kalacak.

Dokunmamış olacak dudağıma başka dudak.

Bıraktığım gibi diyeceksin her şey, 

Sen geri  gelince savaştan, 

Sen geri gelince.

(Cev. A.Bezirci)', 'Savaşa gitmek mi istersin, git asker,  Gidenin bir daha gelmediği Kanlı, kuduran savaşa. Burda olacağım geri dönersen,  Yeşeren karaağaçlar ...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt-brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekleyecegim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Generalim Tankınız Ne Güçlü', 'generalim-tankiniz-ne-guclu-bertolt-brecht-468pn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tankınız ne güçlü generalim, 

Siler süpürür bir ormanı, 

Yüz insanı ezer geçer.

Ama bir kusurcuğu var; 

İster bir sürücü.

Bombardıman uzağınız ne güçlü generalim, 

Fırtınadan tez gider, filden zorlu.

Ama bir kusurcuğu var; 

Usta ister yapacak.

İnsan dediğin nice işler görür, generalim, 

Bilir uçurmasını, öldürmesini, insan dediğin.

Ama bir kusurcuğu var; 

Bilir düşünmesini de.

Çeviren: A.Bezirci', 'Tankınız ne güçlü generalim,  Siler süpürür bir ormanı,  Yüz insanı ezer geçer. Ama bir kusurcuğu var;  İster bir sürücü. Bombardıman uzağın...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt-brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/generalim-tankiniz-ne-guclu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevği Pınarı''ma', 'sevgi-pinari-ma-salih-ozalasan-adhx7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben seninle insanları sevmesini öğrendim bunu bilesin        

Sevdiğimi sandıkların bilki intikam hevesim

Onu kurutursan  susuzluğunu nerden gidereceksin

Pınarın kaynağının sen olduğunu göreceksin

O pınardan kimbilr belki sende birgün su içeceksin

Korkarım sen bu yürekle bana düşmanlarımıda sevdireceksin

Eda lı bir bakış için neler verebileceğimi zamanla ğöreceksin

Korkarımki zaman zaman sen bile hayrete düşeceksin

Acabalarla acaba SALİH gerçekten bu kişimiydi diyeceksin

Sen hayatın anlamı sen yüreğimde bir yüreksin

Yüreğimin ta orta yerinde daima benimle 

Haydi çakkkkkk  diyeceksin

(Akçalar 25.07.2002)', 'Ben seninle insanları sevmesini öğrendim bunu bilesin         Sevdiğimi sandıkların bilki intikam hevesim Onu kurutursan  susuzluğunu nerden...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-pinari-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melahat Gecilmez', 'melahat-gecilmez-ece-ayhan-0qbyr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1.Gazetelerde ak kara bir resmi otuz yillik.Arkasinda mulki taksimatli bir harita.Komiserin odasinda agirlanirmis.', '1.Gazetelerde ak kara bir resmi otuz yillik.Arkasinda mulki taksimatli bir harita.Komiserin odasinda agirlanirmis....', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece-ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/melahat-gecilmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklarıma', 'cocuklarima-naci-orhan-u4pcn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saltanatlar servetler tümü birer oyuncak

Bu gördüğün varlıklar hepsi heba olacak

Hani hanlar hakanlar kayıp olup gittiler

Var mı bu viranede tek bir baki kalacak

Bir ibret almalısın giden öncekilerden

Bölük bölük göçenler ne götürdü bu yerden

Şu dehşet manzarayı düşünüp görmüyorsan

Demek çok kalınlaşmış o gözündeki perden

Pek bağlanma servete, şöhret, mala, kazanca

Daha vakit geç değil düşün biraz insanca

Çalış takdiri kazan o seni yaratanın

Huzur refah ondadır sapma batıl inanca

Hem hüsran hem gaflettir hak yolundan gayri yol

Huzur-i ilahide başka şey görmez kabul

Fırsat elinde iken kendine çeki düzen

Ver Allah’ın ipine sımsıkı sarıl oğul

Meyil verdiklerinin hepsi birer fanidir

Dost gördüğün bu toplum ekserisi canidir

Yutabilirler seni daima uyanık ol

Canavarın hücumu dikkat et çok anidir

İnsanı ahsen yapmış yüce hak tinetinde

Çalış öyle olmaya, insanlık hizmetinde

Seni ki farklı yapan o yüce yaradanı

Hatırla her işinde düşün her niyetinde

Herkese saygı göster olma hizipçi falan

Büyüklerle kalk otur sohbetinden yararlan

Kanun ve nizamlara daima saygılı ol

Maddi çıkar uğruna zinhar söyleme yalan

Çok mecbur kalmadıkça kullanma kaba kuvvet

Bir mevkide bulunsan daima iyi niyet

İle yaklaşım göster dürüst ol her sahada

Aklından da geçirme ne irtikap ne rüşvet

Çağırıyorlar beni yanaştım istasyona

Bir sınava gelmiştim sürem erişti sona

Yarabbi notlarımı lütfunla değerlendir

Yüzü ak bir şekilde geleyim huzuruna

Artık trene bindim tünele girmekteyim

Beyhude geçti ömrüm eli boş gitmekteyim

Evlatlar iyi olun benzemeyin Naci’ye

Elveda artık sizden hayır beklemekteyim', 'Saltanatlar servetler tümü birer oyuncak Bu gördüğün varlıklar hepsi heba olacak Hani hanlar hakanlar kayıp olup gittiler Var mı bu viranede...', ARRAY['Türk Edebiyatı','Şiir','Naci Orhan']::text[], 8.5, '{"poet":"Naci Orhan","poet_slug":"naci-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cocuklarima-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mirhasan', 'mirhasan-naci-orhan-m3tcb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canım küçük Mirhasan’ım

Tek sevdiğim torunumdur

Her şey sizin tek o benim

Cani gönülden oğlumdur

Bülbüldür konmuş dalıma 

Gece gelir hayalıma

Ortaktır bütün malıma

Küçük kanadım kolumdur

Ömrüm erişmiştir sona

Tüm sevgim bağlanmış ona

O devam etsin yoluna

Bir teselli umudumdur

Şimdiden deliktir cebi

Cömerttir babası gibi

Ona sahip çık ya Rabbi

En büyük dileyim budur

Sevimlidir hareketli

Mela’nın oğlu besbelli

Ders  çalışır çok akıllı

Bu hal en büyük arzumdur

Dersten gelirse bir konu

Hemen bırakır oyunu

Çalışarak çözer onu

Çünkü benim torunumdur

Mutlu eder annesini

Utandırmaz dedesini

Sever onu öğretmeni

Bu çok güzel bir durumdur

Oku al ilim irfanı

Üzme sakın hiç ananı

Hoşça kal dedenin canı

Mutluluğun huzurumdur

Bayramın kutlu olsun

Evinize sevgi dolsun

Bankada çok paran olsun

Fuat amcan umutludur', 'Canım küçük Mirhasan’ım Tek sevdiğim torunumdur Her şey sizin tek o benim Cani gönülden oğlumdur Bülbüldür konmuş dalıma  Gece gelir hayalım...', ARRAY['Türk Edebiyatı','Şiir','Naci Orhan']::text[], 8.5, '{"poet":"Naci Orhan","poet_slug":"naci-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mirhasan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Van', 'van-naci-orhan-bnub4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bence dünyada benzerin yoktur 

Vasfını arza yetmez beyanım 

Tarihi güzelliklerin çok çoktur

Doğa güzelliğin gölündür Vanım 

                

Tarihi eserin Hoşap Kalesi

Güzel varlıkların hem en alası

Halen mest ediyor gören herkesi

O eski ihtişam şanındır Vanım

                                                                                      

Bir cennet gibiydi kıyıda yerin                    

Eşsizdi sanatın gümüş eserin       

Dünyada meşhurdu o ustaların 

Tümü hayin çıkıp kaçtılar Vanım

Van Kalesi senin kaç bin yaşında

Bak neler yazılı her bir taşında 

Uğrunda ölenler yanı başında

Zeve’de yatıyor bir çoğu Vanım

Büyük bir tarihçen şimdi adada 

Bir başka eserin Çavuştepe’de

Çok harikaların var her yerinde  

Hoşap’ta, Gevaş’ta, Müküs’te Vanım

Var mı bir memleket ki senden gayrı 

Bembeyaz kedisi göz rengi ayrı

Bir gözü masmavi diğeri sarı 

Bunun hikmeti de sendendir Vanım         

İlçelerin güzel dillere destan                                             

Abbasiler şehri tarihi Vestan 

Hişet’teki kümbet, cami, bedestan      

Miraslar bırakıp gittiler Vanım            

     

Kehrizden akardı ab-ı haytın                                             

Kevser gibiydi o zernebatın 

İkisini de kaybedip attın  

Klorlu suyunu içemem Vanım

Gevaş’ta yaşıyor Muhtesin Deniz         

Abbasi’den kaldı onu görseniz           

Gayri ihtiyari tutar gülmeniz 

Bak nereden nereye gelmişiz Vanım           

               

Gölünde türedi bir de canavar

Gemi kiralayıp arayanlar var

Belki de bu mahluk işine yarar

Yabancılar gelip görsünler Vanım  

Medreseler hanlar yapıp vakfeden     

Din, dünya işini güzel yürüten          

O devlet adamı büyük Mirhasen                  

Müküs’te medfundur unutma Vanım

Her yerinde yatar şehit şüheda

Senin için olmuşlar tabii feda 

Halkın kimseye vermez ebeda 

Ölmeden bir çakıl taşını Vanım  

Dilerim engeller çıksın aradan

Turistler hem hava hem de karadan

Gelsin cıvıl cıvıl sahilin adan 

İnsanlarla dolsun yeniden Vanım  

             

Yedi Kilise’de bir kültür yatar                

Gün begün yok olup geçmişe batar       

Sen sahip çıkmazsan halk yıkıp atar     

Ayaktadır kısmen yıktırma Vanım', 'Bence dünyada benzerin yoktur  Vasfını arza yetmez beyanım  Tarihi güzelliklerin çok çoktur Doğa güzelliğin gölündür Vanım                  ...', ARRAY['Türk Edebiyatı','Şiir','Naci Orhan']::text[], 8.5, '{"poet":"Naci Orhan","poet_slug":"naci-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/van-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bürokrasi', 'burokrasi-naci-orhan-uilcv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fakir eden milleti devalüasyon diyorlar                  

Çare arıyor meclis, uğraşır her siyasi                      

Vatandaş rüşvet verir, bazıları yiyorlar                  

Bütün müsebbip bence bu hantal bürokrasi 

            

Bir günde sekiz kere kayıttan geçer evrak

Sanki huduttan geçer kanun dışı bir kaçak 

“İmzalayın efendim”, ”olmaz! ”masaya bırak

Çok gün incelemede bekletir bürokrasi

                                                   

Taşeron otuz kırk gün istihkak gezdiriyor               

Döner dolaşır gelir bir türlü iş bitmiyor                  

Mecbur kalınca artık rüşvet teklif ediyor                

Buna sebep sizce ne, Vallahi bürokrasi

                  

Müteahhit iki ayda inşaatı bitirir

Hak edişleri ise iki sene gezdirir

Adeta vatandaşı her haliyle ezdirir

Hiçte suçlu çıkmıyor bu haksız bürokrasi

 İş kaybı, gelir kaybı bundan kaynaklanıyor            

Gün geçtikçe fakirlik Devlete de yansıyor             

Yüzde seksen bürokrat, sorma tatil yapıyor            

Mekanizma çalışmaz; kitlenmiş bürokrasi              

Onun sende parası kalsa faiz işliyor             

Ya bekleyen parana niçin fark ödemiyor

Devlet düzenidir der, buna aklın ermiyor

Diye azarlar seni bir güzel bürokrasi

Yüz adet rahat kapı, varsa tek bir kapı zor             

Seni o zor kapıya yönlendiriyor memur                  

O elindeki dosya sanki hep suç ve kusur                   İşlemişsin, karşına dikilir bürokrasi                        

Eyer torpilin olsa bir yüksek bürokrat 

Dosyanı müstahdeme ver git artık rahat yat

Evrakın kötü imiş, yazışmaların berbat

Gam çekme düzeltecek onları bürokrasi

İstihkak almak müşkül, iş yapmak daha rahat         

Geç para vermek usul, geç iş yapmak kabahat       

Hakkını arar isen vay memura hakaret                     

Yaptın diye içeri attırır bürokrasi

                           

Torpilin yoksa eyer, unvanın düz vatandaş

Allah yardımcın olsun iki ay daha uğraş

Sinirli isen şayet ilerlemiş ise yaş

Kalpten götürür seni inan ki bürokrasi 

Sana ahbap değilse gösterir ekşi bir yüz

Evrakından çıkarır çok basit birkaç pürüz

Git düzelt getir bana, tekrar bakar, görürüz

Haftalarca oyalar böylece bürokrasi', 'Fakir eden milleti devalüasyon diyorlar                   Çare arıyor meclis, uğraşır her siyasi                       Vatandaş rüşvet verir...', ARRAY['Türk Edebiyatı','Şiir','Naci Orhan']::text[], 8.5, '{"poet":"Naci Orhan","poet_slug":"naci-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/burokrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vekaletnameya Derdan', 'vekaletnameya-derdan-naci-orhan-tte4a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Wekaletnameya derdan jı Eyyub hatiye nıkmın

Çı hed wek wi bıkem sebrê lıber êşan şukurdarbım

Azizê ber dılêmın çu nekın iru tulumelmın

Ezê hêjka bınalinım dıtırsım pê gunehkarbım

Teselli ger jınık Heq bê dılêmın belkê dermanket

Bıbêjı hernenık hevdu çı xuş mızgini ıhsanket

Jıbume lutf û ıkrame heçi ew emr û fermanket

Welew çunaj heyatêji bıbıt ezdê mınêkarbım

Pıçukey maaye hivyamın belê navek mezın wêlser

Jı Abdulmewla maye ew dıvêm jêra bıbım rehber

Seba tehsilû ırfana wi ımkanê xwe raskem ber

Belê tırsım feleklmınde ku ez mehçub û bêzarbım

Jı Miru’ra nekım xıdmet bı derd û kwıl bıçım qebrê

Lıpıştê mın perişanbıt, bıkevte mıhnet û cebrê

Xuda hıngav bıdet daykê, hınek ımkan, hınek sebrê

Bıbem secde jıbu xalıq bıvi rengê mınettarbım

Aziz çuna te hêj zubu belê Rebbête fermankır

Tıji huri, melek hatın hınan destête dermankır

Jıqehra vi fıraqate dıtırsım zehf me ısyankır

Dema behsate bê gutın, jınuve dê bırindarbım

Neşêm deryê mekanête vekım bête xırabe ew

Jımınra êdi wi xani, weki qebr û turabe ew

Hecar mırnê qebulnakım dıbêjım belki rabe ew

Tınê wek kwında kurmame belê bê dost û bê yarım

Çıkem dengê mı xweş ninej dılê sohti bıqarinım

Lıber qebrate wer runım heta mırnê bınalinım

Çıranın herdu çavêmın weki êdi tenabinım

Nema kurbın jı gıryanê dıpıştête besir nabım

Eya xalıq tu lênegre dılêmın agırê tida

Wekê komır lıser kurê bıçerxê bagerê lêda

Şewata dıl qesarnabıt heta ez bıçme qebrêda

Jı me’murê su’alê pırs bıkım ca jêxeberdarbım

Hınek Abde hınek Mewla çıxweşew dıpte navête

Nesibê te Xuda kırbu ciyê ku xwesti babête

Belê bête çıqa zore heyata Naci mamête

Nemaye zehf ku bêm cemte jı lutfa Hek şerefdarbım', 'Wekaletnameya derdan jı Eyyub hatiye nıkmın Çı hed wek wi bıkem sebrê lıber êşan şukurdarbım Azizê ber dılêmın çu nekın iru tulumelmın Ezê h...', ARRAY['Türk Edebiyatı','Şiir','Naci Orhan']::text[], 8.5, '{"poet":"Naci Orhan","poet_slug":"naci-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/vekaletnameya-derdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cabek', 'cabek-naci-orhan-m8kqx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cabek xırab hati jıdur                   

Gutın qezayek bu lırê                     

Zanim ewe çavê mı kûr                   

Fılhal bezim çum widerê                 

Mirê puçük bê faydeye                            

Mirê mezın zatêteye

Babê tefal hat cem weye

Ca nuşı ava kewserê

                                                                                              

Mındi lıser textê şuwê                     

Rahet ku razabu luwê                      

Nurek yeqin radbu jıwê                   

Huri melek hatınl serê                     

Yareb jıte telbem eve 

Disa me bine cem heve

Cırmu guneh ger derkeve

Efke qelem kêşe serê

Gazi hewar qarin jımın                                                           

Çune felek zarin jımın                     

Wê her herın nalin jımın                  

Xweş nabı derba xencerê 

Minne lıber şipanderê

Wextê ku tu rehmêlmeki

Perdêj cemala xwe veki

Secdê bıbeyn çend saleki 

Derbek lıpê tiğê sedef                      

Hate lı qulınca me xef                      

Hetta ku ez pê bım telef                   

Dê xweş bıbım ger rıh derê              

Hêj nu emê mesrur bıbin

Jıwi xıdmetê meğrur bıbin

Hetta ebed me’mur bıbin

Cavnêrê husna ekberê

Abdulmewla jımın durbu                 

Lımın çavu beser kurbu                   

Heyat bêwi çıqa zurbu                     

Wi derdê dame cenderê                   

Sûr tê bıdet bangu sela

Cuhta şehidê Kerbela                                

Bıbne xweyil Abdulmewla

Bêjın megırt mizan wer

Çıbkem jı çend rujê dınê                  

Ew çuye ez mame tınê                     

Miru bıçukl ber xwendınê               

Dê sehlbı ruza mehşerê 

Naminıtın şinu gırin

Hem xweş dıbın cerhu bırin

Ki hev bıvê wê hev bıbin

Mes’ul ezım mamel berê                                                  

                                                 

Şexsek halim ehlê sebır                   

Bul kes nekır zulmu cebır                

Lewra Xuda zujnavme bır                

Fedla şehid çu meqberê

                  

Yareb çı ebdek bê xebat 

İru bı ruyê reşve hat

Naci’ye disajte necat                                    

Zari dıke lıber derê

Yareb çı zure ev hısab

Cergu hınavl mın bun kebab                  

Mirura dêjnu bıbme bab                      

Ketme çı qeydu çemberê', 'Cabek xırab hati jıdur                    Gutın qezayek bu lırê                      Zanim ewe çavê mı kûr                    Fılhal bezim ç...', ARRAY['Türk Edebiyatı','Şiir','Naci Orhan']::text[], 8.5, '{"poet":"Naci Orhan","poet_slug":"naci-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/cabek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin Ciwan Bebek', 'hosgeldin-ciwan-bebek-recep-marasli-uusze', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yurdunun toprağı beşik olsun  ona

orda büyüsün yavrum orda

evrenin bilgileri süt olsun ona

sevdalar yeşertsin yüreciğinde

yıldızların ışığı düşsün gözlerine

ateşi görsün ama 

ihaneti görmesin', 'yurdunun toprağı beşik olsun  ona orda büyüsün yavrum orda evrenin bilgileri süt olsun ona sevdalar yeşertsin yüreciğinde yıldızların ışığı ...', ARRAY['Türk Edebiyatı','Şiir','Recep Maraşlı']::text[], 8.5, '{"poet":"Recep Maraşlı","poet_slug":"recep-marasli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hosgeldin-ciwan-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuzbeş Yaş''', 'otuzbes-yas-recep-marasli-vhjsv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıl bindokuzyüz doksanbir

Yaş otuzbeş

''Dante gibi ortasındayız ömrün''

Cahit Sıtkı... şu bizim otuzbeşlik ihtiyar

Böyle söylemiş hüzünle, yaşarken ağlayarak ölümüne...

Yaş otuzbeş yolun yarısı mı eder? 

Yoksa işin başında mıyız daha? 

Yüzüm çoktan değişti biliyorum

Ama halen çocuklar gibi seviyorum

Duvar ördüler üzerime

Bin renge boyadım her taşını

Onbeş yaş gibi seviyorum yine de

Otuzbeş yaşımı..

Ölümden korkmamak önemli bir de

Aynaya bakarken utanmamak', 'Yıl bindokuzyüz doksanbir Yaş otuzbeş ''Dante gibi ortasındayız ömrün'' Cahit Sıtkı... şu bizim otuzbeşlik ihtiyar Böyle söylemiş hüzünle, yaş...', ARRAY['Türk Edebiyatı','Şiir','Recep Maraşlı']::text[], 8.5, '{"poet":"Recep Maraşlı","poet_slug":"recep-marasli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/otuzbes-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair ve Orospu', 'sair-ve-orospu-erhan-guleryuz-yv2lr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şair veya bir orospuya, 

uğruna canını vereceği aşkını

neden aldattın diye sorulur mu? 

Zedelenmiş bir ruhtan şair, 

zedelenmemiş bir ruhta

orospu olunur mu?', 'Bir şair veya bir orospuya,  uğruna canını vereceği aşkını neden aldattın diye sorulur mu?  Zedelenmiş bir ruhtan şair,  zedelenmemiş bir ru...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sair-ve-orospu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistinli Çocuk ve Yıkık Duvar', 'filistinli-cocuk-ve-yikik-duvar-sabri-gurbuz-acpav', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Babam ''Evimiz'' demişti

Şu dört duvarın içi..

Ne oldu baba

Bu delikte neyin nesi? 

Oyuncağımdan da büyük tanklar geldi

Ne oldu baba

Çocuklar niye kefenli

Bir çivi çakmaya kıyamazken

Kimler hayalimizi yıktı

Ne oldu baba

Gittiğin yerde ne oldu

Götürdüler de gelmedin

Ne oldu

Dünya bir yığın insan demiştin

Hiçbiri bizi sevmez mi? 

Nerdeler baba, kalpleri nerde

İnsan olan gelmez mi? 

--Babanın dilinden--

Ölüm evlat

Rahat yaşam yok bize

Ölümü sevdik işte

Can verdik

Sizin hayatınız için

Ama yetmezmiş, bilemezdik

Elimizden ne gelirdi başka

İnsanlık göz yumdukça..

Hayvan ölseydi bunca

Dünya ağlardı yıllarca

İnsan olmaklığa mı kızmalı

Bizi Filistinli doğurana mı kızmalı

Biliyorum gelmen yakın buraya

Bırak o deliği

Büyüsün yüreklerde, biriksin

Artık umudumuz öte hayatta

Bırak ve gel

Başlarına kalsın o dünya

Sana yas tutacak da kalmasın

Acısını duymadıkları bir resmin kalsın

Ertesi gün unutulan bir resim..', 'Babam ''Evimiz'' demişti Şu dört duvarın içi.. Ne oldu baba Bu delikte neyin nesi?  Oyuncağımdan da büyük tanklar geldi Ne oldu baba Çocuklar ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/filistinli-cocuk-ve-yikik-duvar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraktın Gittin', 'biraktin-gittin-sicilyali-kemal-400l1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seninle mutluyduk ikimiz birden

kederim çoğalır sensiz günlerde

derdimin dermanı birtek var sende

dön gel artık benim arip sevgilim

bir avuç mutluluk  çok gördün bana

halin nedir diye sormadın bana

hep olmak isterdim ben senden yana

terk edip gittin bıraktın beni

isterdim seninle mutlu olalım

kararı sen verdin bırakıp gittin

sensizlik inanki ölümden beter

sevmiştim seni ben vefasız çıktın

senden yana şansım artmadı benim

kaderim gülmedi bu yıl sevgilim

sevgiden şevkatten mahrum bıraktın

terk edip gittin bıraktın beni', 'seninle mutluyduk ikimiz birden kederim çoğalır sensiz günlerde derdimin dermanı birtek var sende dön gel artık benim arip sevgilim bir avuç...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biraktin-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-sicilyali-kemal-1ian1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'özlüyorum babam seni

neden bırakıp gittinki

geceleri üşüyorum

sen olmazken korkuyorum

eskiden hep benimleydin

herkes kıskanırdı beni

şimdi ise gülüyorlar

sen yoksun diye yanımda

al beni götür tanrım

yalnızım ben çok yalnızım

benim tek dermanım sensin

al canımı yalvarırım

eskiden hep benimleydin

herkes kıskanırdı beni

şimdi ise gülüyorlar 

sen yoksun diye yanımda', 'özlüyorum babam seni neden bırakıp gittinki geceleri üşüyorum sen olmazken korkuyorum eskiden hep benimleydin herkes kıskanırdı beni şimdi i...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/babam-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Yarim', 'vefasiz-yarim-sicilyali-kemal-dupph', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaralı kalbimden vurdular beni

kolumdan tutular attılar beni

verin sevdiğimi almayın benden

çekipte vurdular yıktılar beni

dalından kopmuş güle döndüm

bir bülbül misalı ağladım durdum

gitmek çare değil bırakıp gittin

beyazlar içinde güldün de geçtin

simsiyah saçıma akbeyaz doldu

sensiz geçen günler zindanım oldu

hani mutluluğu bende bulmuştun 

mükafatın buymuş vefasız yarim', 'yaralı kalbimden vurdular beni kolumdan tutular attılar beni verin sevdiğimi almayın benden çekipte vurdular yıktılar beni dalından kopmuş g...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vefasiz-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Bekleyiş', 'beklenen-bekleyis-i-smail-karakus-7os5u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buldum derken,

Köşegen huzuru, 

Dizdim yine, 

Gönlümün sıratına falcıları.

Kovamadım,

Yokoluş kodunu hücrelerimden, 

Ve silemedim,

Simetrik işkenceyi beynimden..

Umut ışığımın fitili bitik,

Gazı durmakta yerinde.

Çakmaktaşı korkuları, 

Patlatır kof lambayı, 

Ve yanar ümit ormanı, 

Kalır geriye,

Sadece siyah bir tepe.

Şelalenin kenarında,

Kaktüs sıkıyorum su içmek için.

Farkındayım aslında, 

Alyans mutluluğun.

Yakalarım derken,

Boy uzatan cüce atlarını, 

Bekliyorum,

Cemreyi görmek için, 

Mor çimenlerde.

Sönen,

Boş kurtuluş kandilimin yanında...', 'Buldum derken, Köşegen huzuru,  Dizdim yine,  Gönlümün sıratına falcıları. Kovamadım, Yokoluş kodunu hücrelerimden,  Ve silemedim, Simetrik ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/beklenen-bekleyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertlerdir Benim Meskenim', 'dertlerdir-benim-meskenim-sicilyali-kemal-4gd2n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözü yaşlı anaları

başı dertli babaları

boynu bükük kardeşleri

doya doya sevmedim

dertli dertli düşünüyor

benim gibi hep ağlıyor

acep ona çektiren ne

gece güdüz hep içiyor

bu dünyaya gelen insan

dertsiz doğmaz bana inan

benim gibi seven dostlar

neden kavuşmaz o zaman

çektiğim hap çile benim

dertlerdir benim meskenim

dertsiz gecem gündüzüm yok

bana göre değil aşk yolları', 'gözü yaşlı anaları başı dertli babaları boynu bükük kardeşleri doya doya sevmedim dertli dertli düşünüyor benim gibi hep ağlıyor acep ona çe...', ARRAY['Türk Edebiyatı','Şiir','Sicilyalı Kemal']::text[], 8.5, '{"poet":"Sicilyalı Kemal","poet_slug":"sicilyali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dertlerdir-benim-meskenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahın Beşiydi', 'sabahin-besiydi-tolga-baydar-dztup', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabahın beşiydi

Yolları süpüren temizlik görevlisi

Mesaiye başlamış, etrafı tozutuyordu

Sabahın beşiydi

Köşedeki bakkal amcamız

Dükkanını yeni açmış, rafları düzeltiyordu

Sabahın beşiydi

Mahallemizin tek fırınının ustası

Ocağını yakmış, tırnaklı pide hazırlıyordu

Sabahın beşiydi

İki sokak ötedeki caminin müezzini

Minareye çıkmış, sabah ezanını okuyordu

Sabahın beşiydi

Siyah saçlı, kara gözlü Hüsniye''m

Yatakta doğrulmuş, gözleri ışıl ışıl parlıyordu

Sabahın beşiydi

Bu şekilde başlıyorken yeni bir sabah

Ben de yenilenmiş, kalemim bu satırları yazıyordu

Sabahın beşiydi

Ah

Ne de güzeldi', 'Sabahın beşiydi Yolları süpüren temizlik görevlisi Mesaiye başlamış, etrafı tozutuyordu Sabahın beşiydi Köşedeki bakkal amcamız Dükkanını ye...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sabahin-besiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saygımdandır', 'saygimdandir-tolga-baydar-pptsg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilim diyemeden ölürsem eğer, sana

Bil ki; Utandığımdandır

Saçlarına parmaklarımı dolamamışsam

Bil ki; Kıyamadığımdandır

Bir kez olsun dahi öpmemişsem, yanağından

Bil ki; Namus saydığımdandır

Evet bunların hepsini birden yapmamışsam

Bil ki; Saygımdandır', 'Sevgilim diyemeden ölürsem eğer, sana Bil ki; Utandığımdandır Saçlarına parmaklarımı dolamamışsam Bil ki; Kıyamadığımdandır Bir kez olsun da...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saygimdandir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam İnce Bir Kan Sızıntısı Değildir', 'yasam-i-nce-bir-kan-sizintisi-degildir-zeki-ergin-cx2bw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yaşamayı kucaklarken

gökyüzüne fışkıran taze dallar

gerinirken toprakta tohum

nedendir bitimsiz kaygular

gökgürültüsü değildir duyulanlar

umudun harlaması

bir yangın yeridir yürekler

sürgüne giden nışanlısına

iç çekişidir bir genç kızın

bir günah gibi taşıdıkça

bu canı

yaşam ince bir kan sızıntısıdır

durmaksızın akan

bir sona yaklaşımdır

oysa bu mudur

güneşin türküsü

hani son mektubunda

baharla geleceğim diyordun

erikler çoktan olgunlaştı

kirazlar kan fışkırıyor

ve zamanın bilmem kaçıncı noktasında

bir genç kız karanlığın böğrüne girip

kendini hançerliyor

_ferman 15tem74 sayı:279

_sevgiliye isyan yt:haz04', 'yaşamayı kucaklarken gökyüzüne fışkıran taze dallar gerinirken toprakta tohum nedendir bitimsiz kaygular gökgürültüsü değildir duyulanlar um...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yasam-ince-bir-kan-sizintisi-degildir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-huseyin-cayikli-y15g2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'isyan günlerinde aşk romanından esinlenilmiştir...

başlangıçlar mutlaka bir sonu gösterir

her ayrılıgın başında biraz göz yaşı vardır

öykü değil 

yaşamak ciddi birşeydir...

en güzel aşk isyan günlerinde yaşanır

ve ben hep yalnız kalırım

isyan günlerinde ki aşk 

yaşanılacak ve kaybedilecektir

suçlu olanlar yargılanıp asılacaktır

zor bir şey aşk ugrunda ölmek

zor şeydir aşkın bitiminde yalnız kalmak

şehir hep aydınlık kalacaktır

ışıkları sadece bizi aydınlatacaktır...

biz fosforlu ama karanlık odalara mahkumuzdur

yalnız kaldıgında anlayacaksın

aşkın bitiş tarihi 

bir insanın ölümüne mal olacaktır

ve sen kadınım dediğim 

ağlamaya sebep kıldıgım 

bir aşkın bitimi

benim isyanım olacaktır...', 'isyan günlerinde aşk romanından esinlenilmiştir... başlangıçlar mutlaka bir sonu gösterir her ayrılıgın başında biraz göz yaşı vardır öykü d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/isyan-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Biz ve Onlar', 'siz-biz-ve-onlar-aydin-hatipoglu-gxfgl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seherdir

Sokaklarda kendine şaşan tek tük ayak sesleri

Kimi kez tarlalar sürer gibi

Dalıp gider çizgisine cıgara dumanının

Bir vapur kalkar istanbuldan

Her yanı istanbul olan bir vapur

Döner çark 

Döner çıkrık

Canavar düdükleri

Polis düdükleri

Ve vapur

Uzak 

Buruk

Kanar yüreğinde yanık bir sevda türküsü

Yüreği 

Kırık

Sanki yenicamide bir güvercin vurulur

O saat venedikte güvercinler

Elleri ne kadar güvercin

Birbirine bağlanıyor

Gözleri özgür

Bıyıkları gür

Çığlık çığlığa martılar

Çark çark

Çıkrık çıkrık

Çark çıkrık

Çıkrık çark

Bir vapur köpük köpük rıhtımdan ayrılıyor

Bir vapur telaş telaş

Tırnaklarım avucumu deliyor

Cıgaramı çiğniyorum apacı

Dönen dünyadır bu gıcırtıda

Duyulur

Kara vagonlarda hiçlenen bir serserinin

Bütün bunaltısını yüklediği bir vapur

Bir vapur

Bir kelepçe

Bir abdülhamit

Dönüp bakmıyor yedi on yolcuları elleri simit

Seherdir

Kendine şaşan tek tük ayak sesleri

Doldurur sokakları

Kuşlar daha karışmamıştır şehrin gürültüsüne

Ağaçlar daha bir ağaçtır bu saatlerde

Uzak uzak yankılanır su sesleri

Uzak uzak kurbağalar

Seherdir

Yiğitlere su vermekten döner kızlar

Bir kadın uykudadır

Bir kadın uyanık

Bütün bardakları sevgiyle doldurup

Yüreklerine akıtıyorlar

Sonra bütün yüreklerini sevgiyle doldurup

Hayır diyorlar

Pişman değiliz

Vapura telaş telaş bindiriliyorlar

Vapur baştan başa istanbul

Bir vapur 

Bir kelepçe 

Bir istanbul

Döner çark 

Döner çıkrık

Çark çark 

Çıkrık çıkrık

Çark çıkrık

Çıkrık çark

Bir kadın 

Yüreği kırık

Gözleri özgür ya bu çok önemli

Başka hiçbir durumda bir insanın gözleri

Böyle özgür olamaz

Ve başka hiçbir durumda bir insanın gözleri

Bir selamı böyle sıcak alamaz

Gün doğar

Kimseleri şaşırtmadan yeşerir kavga

Bir umut

Bir çığlık

Bir yenilgi

Bir kadın bir çocuğu büyütür usulca

Nasıl büyütür kimseler bilmez

Nasıl sarar sevgilerle

Nasıl besler umutlarla

Kimseler bilmez

Bir yokluğu bir yokluğa katarak

Höllüğünü ince eler büyütür

Bir vapur

Ayırır anayı yavrusundan

Bir vapur bir tel örgü bir istanbul

Canavar düdükleri havada vızıldar

Bir ananın süt damarı sızılar

Yavrum yavrum

Başörtüsünde ömürlük çilelerin dokuması

Bir kahramanlıktır analık

Bir mermeri yontar gibi sabırla

Değişen dünyadır yeşeren kavgada

Aydın Hatipoğlu

Siz biz ve onlar

Sokaktan insanlar geçiyor

Evrenin yiğit bahçıvanları

Anıları ve umutlarıyla iç içe

İnsanlar geçiyor

Çocuk gözleriyle

Şaşarak bakıyorlar sararan yapraklara

Uzayı devşiriyor aklın tarlası

Her gün her gün yeniden

Yiten

Bir umudu simgeliyor günebakan

Bükerek boynunu

İnsanlar geçiyor sokaktan

Siz biz ve onlar

Evrenin yiğit bahçıvanları

Bir beynin hücreleri gibiyiz

Çoğul

Ve akyuvarları gibiyiz ekonominin

Durmadan yenilenen hayatın

Yazgısını yeniliyoruz durmadan

Kahraman bir dağdan inerek

Gün görmüş denizlerde çoğalan

Bulut mu yağmur mu özlemin dili

Toprağın çatlayan dudakları mı

Yumuşak sözcüklerle söylüyoruz

En katı gerçekleri

Bulutlarla çiçeklerle kuşlarla

Irmaklarla rügârlarla taylarla

Ceylan mı korku mu namluda

Ağzı köpük köpük bir atla koşuyoruz

Siz biz ve onlar

Evrenin yiğit bahçıvanları

Tespihböceğinin evreni bir kısırdöngü

Doğanın devingen yasasında karıncalar

Bilmiyorlar

Bir çocuğun elindeki çubuktan filizlenen sevinci

Bimiyorlar

Ölümün bazen nasıl bir eğlence olduğunu

Ülkemde çocuklar

Bir acıdan bir sevinç çıkarmayı biliyorlar

Burnu hırızmalı ve sümüklü

Topuğu halhallı yalınayaklı kızlar

Sıtmasını işediği çorak toprakların

Ayrı bir dünya olduğunu

Biliyorlar

Sokakta insanlar

Siz biz ve onlar

Kızaran yaprakların hüznünü anlıyoruz

İhtiyar atların içekapanışını 

Şaşmıyoruz yıldızlardan damlayan

Söğütlerin saydam ışıltısına

Gülen gözlerinde bir çocuğun

Şarkısını söyleyen bir beyaz kuşun

Çürüyen bir ağacı nasıl sarstığını

Duyuyoruz

Tutsaklığın nasıl bir sanrı olduğunu

Ölümün duvarlarına ellerini dayayıp

Hep beraber bir türküyü söylemenin coşkusunu

Kalleş bir ölüme gidenlerin

Birbirine sarılan kollarında

Yaşamanın şehvetini duyuyoruz

Siz biz ve onlar

Evrenin yiğit bahçıvanları', 'Seherdir Sokaklarda kendine şaşan tek tük ayak sesleri Kimi kez tarlalar sürer gibi Dalıp gider çizgisine cıgara dumanının Bir vapur kalkar ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Hatipoğlu']::text[], 8.5, '{"poet":"Aydın Hatipoğlu","poet_slug":"aydin-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":159,"source_url":"https://www.antoloji.com/siz-biz-ve-onlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sislenen', 'sislenen-ahmet-telli-kvtxl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gittikce puslaniyor görüntü

sislenen bir aynaya dönüyor

yakin gecmis de olsa artik

zor secebiliyoruz birseyleri

bulutlar cöküyor anilarimiza

Ama unutmus degiliz yasanani

bugulu bir düs gibi de olsa

duyumsuyoruz o kekre tadi

ve her animsayista irkiltiyor

o soluksuz birakan küf kokusu

Soluk renklere bürünse de

suyun ve gögün görüntüsü

yasanan duyurulacaktir mutlaka

anlatacaktir bir cocuga bunlari

gögsü paramparca edilen biri', 'Gittikce puslaniyor görüntü sislenen bir aynaya dönüyor yakin gecmis de olsa artik zor secebiliyoruz birseyleri bulutlar cöküyor anilarimiza...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sislenen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kadar Sevmedimki', 'bu-kadar-sevmedimki-cezmi-ersoz-i6225', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dönemem terk ettiğim hiç bir yere

Dolaşıp duruyorum sokaklarda

Dilimde o son duam

Ben hiç kimseyi bu kadar sevmedimki

Sonsuzluk gibi çıkıyordu

Bu söz içimden

Umutsuz bir yakarış gibi

Hiç bitmeyecek bir hasret gibi

Ben hiç kimseyi bu kadar sevmedimki', 'Dönemem terk ettiğim hiç bir yere Dolaşıp duruyorum sokaklarda Dilimde o son duam Ben hiç kimseyi bu kadar sevmedimki Sonsuzluk gibi çıkıyor...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-kadar-sevmedimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Kararmasin Geldiginde', 'gun-kararmasin-geldiginde-ahmet-telli-tfauy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güz yakmadan gülün pembesini

avuclarimda ol, sokul yanima

gülüsünle isinsin bedenim

ve dudaklarimda acilasan islik

adinla ciceklensin

Serceler göce dayanmaz bilirsin

ne özleyen bir bakis kalir

ne de simsicakligin

sular donar yürek üsür

sende kalir seni yakan

Ucurumlar acilir yollarinda

buharlasir ciy damlalari

Terli bir kisrak gibi gel kapima

savrulsun saclarin

yastigim kekik koksun

Uzagi yakin et

pembelessin carsafin

ölüm kapimin tokmaginda

ayriligi iyi bilirim

ferhat olmayayim daglarda

Ey gülün pembesiyle

bir gülümseyisi paylasan

kar yagiyor yatagima

avuclarim kutuplara döndü

gün kararmasin geldiginde', 'Güz yakmadan gülün pembesini avuclarimda ol, sokul yanima gülüsünle isinsin bedenim ve dudaklarimda acilasan islik adinla ciceklensin Sercel...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gun-kararmasin-geldiginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz Zürafa', 'kimsesiz-zurafa-metin-ustundag-5t0et', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimi kimsesi yoktu

Kimsesiz zürafanın

Boynu bükük dolaşırdı

Sırtını kimse kaşımazdı

Kimsesiz zürafa bir gün 

Çalı çırpı topladı

Kendi kendisini yaktı

Kimsesiz zürafanın

Acayip dumanı oldu', 'Kimi kimsesi yoktu Kimsesiz zürafanın Boynu bükük dolaşırdı Sırtını kimse kaşımazdı Kimsesiz zürafa bir gün  Çalı çırpı topladı Kendi kendis...', ARRAY['Türk Edebiyatı','Şiir','Metin Üstündağ']::text[], 8.5, '{"poet":"Metin Üstündağ","poet_slug":"metin-ustundag","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kimsesiz-zurafa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum', 'ruhum-bayram-gul-bfuiq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnız ruhum

Pencereni aç havalandır kendini

Şöyle bir temizlik yap 

Eski acılarını süpür, hüzünlerini toplayıp istifle.

Zira bir gün lazım olabilir.

Öfkelerini kolile  üst rafa kaldır.

Anı defterini toparla

Bak kırışmış kenarları. Düzelt.

Parmağını daldır

İşe yarayanları ayır at gitsin! 

Güzel çarpıcı olanları al 

Kapının yanındaki rafa koy.

Elinin altında bulunsun

Öyle yaşaki

Sen değil onlar beklemekten yorulsun.

Bak bak o kalın dosya neydiki? 

Aşk dosyasımı? 

Yırtıver gitsin.

Anılarınla idare edersin.

Acı ve hüzünden başka ne bulacaksınki? 

Onlarda zaten var.

Hem bundan sonrasına bakmalısın.

Yeni aşklara kucak açıp eskilerini unutmalısın.

Sende zamana uyup neşeli ve hoyrat olmalısın.

Onlar seni değil sen onları kullanmalısın.

Haydi çok muhabbet tez ayrılık getirirmiş

                                       Hoşça kal.

Kenndini ferah tut yaşamı sev.

Yaşam sevdikçe güzelleşirmiş.! ! ? ?', 'Yalnız ruhum Pencereni aç havalandır kendini Şöyle bir temizlik yap  Eski acılarını süpür, hüzünlerini toplayıp istifle. Zira bir gün lazım ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Gül']::text[], 8.5, '{"poet":"Bayram Gül","poet_slug":"bayram-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ruhum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl', 'col-i-smail-karakus-pji2f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıcaklardan gelen derinliğin sesi

Bir bukle serinlik verir misin

Ve bir damla su lütfen

Yüreğimin gül noktasının

Ta içine

Çöl

Ateşinle bir parça kavur lütfen,

Yanmaya amade ciğerlerimi.

Ki kabahati sana yüklemesi kolay olsun.

Çöl 

Ses ver de,

Raks etsin beynimin rakkaseleri.

Ve savur eteklerini,

Ve kavur onların da yüreklerini..

Çöl

Gel de gör,

Sen mi sıcaksın,

Yoksa gönlümün cehennemi mi? 

Gel de yakayım seni,

Kalbimin serabıyla kandırarak...

Çöl

Sıkıysa gel hadi.', 'Sıcaklardan gelen derinliğin sesi Bir bukle serinlik verir misin Ve bir damla su lütfen Yüreğimin gül noktasının Ta içine Çöl Ateşinle bir p...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/col-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örümcek Yası', 'orumcek-yasi-i-smail-karakus-y88nt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşten ödünç aldığım

Yalancı mutlulukla, 

Fikrimi kandırıyorum kendimce.

Olmayan saadeti ayartıp, 

Yukarı iniyorum,

Aşağı çıkanlara inat! 

Sinekleri kurtarıyorum

Örümcek ağından.

Örümceği kaybediyorum

Gizli dostumken.

Sararken pembe gölgeler etrafımı,

Oturuyorum kendimle,

Örümcek yasında...', 'Güneşten ödünç aldığım Yalancı mutlulukla,  Fikrimi kandırıyorum kendimce. Olmayan saadeti ayartıp,  Yukarı iniyorum, Aşağı çıkanlara inat! ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/orumcek-yasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıştım', 'alistim-huseyin-cayikli-4u7qj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen benim sevdiğim herşeyi sevdin

haksızlık yaptım

sanırım bu sefer ben suçluyum

sanırım ayrıldık

uzun süre geçti

ama hala kabullenemiyorum

ama inan

sensizliğe alıştım

artık beni uyandıracak kimse yok

sabahları kendim kalkıyorum

alıştım sensizliğe

artık kolay geliyor...', 'sen benim sevdiğim herşeyi sevdin haksızlık yaptım sanırım bu sefer ben suçluyum sanırım ayrıldık uzun süre geçti ama hala kabullenemiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alistim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuhaflık Seziyorum Pastel Bakışlarında', 'tuhaflik-seziyorum-pastel-bakislarinda-i-smail-karakus-ho9hk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tuhaflık seziyorum pastel bakışlarında.

Gönlümün girdabında,

Kaybolacak mıydın bu denli? 

Ve matlaşacak mıydın zihnimde,

Bu karanlık silüetle? 

Sen ki,

En canlı hücremdin beynimin çeperlerinde.

Dumanlı bir başkaldırıydın,

Aşkımın beyaz tünelinde.

Sendin,

Beni ben yapan bir zamanlar,

Benlerimin içinde..

Tuhaflık seziyorum pastel bakışlarında...

Perdelerden tanıyorum sesini.

Unutmuşluk yaşıyorum bir an.

Bakışındaki ölü yıkayıcıyı,

Hatırlıyorum bir yerlerden.

Efsanelerden kalan,

Mistik bir haykırış kusuyor gözlerin.

Fersiz ama kindar süzüyorsun.

Gözlerimin içini emiyor,

Sürüklüyorsun beni ve diğer benlerimi...

Tuhaflık seziyorum pastel bakışlarında.

Bir yeşil ormandayım.

Ama kapkaranlık ve ölümcül.

Bakışında haykırış,

Gülüşünde öfke var.

Duman, sis, 

Ve  korku yayıyor gözlerin.

Özlüyorum  o eski gözlerini.

Tuhaflık seziyorum pastel bakışlarında.

Kapılıyorum,

Herşeye rağmen,

Engin denizlerine.

Ve ayılamıyorum yine bir süre.

Yine dalıyorum gözlerine, 

Sonunda,

Benim olmayacağını bile bile.

Tuhaflık seziyorum pastel bakışlarında...', 'Tuhaflık seziyorum pastel bakışlarında. Gönlümün girdabında, Kaybolacak mıydın bu denli?  Ve matlaşacak mıydın zihnimde, Bu karanlık silüetl...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/tuhaflik-seziyorum-pastel-bakislarinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azad Et', 'azad-et-i-smail-karakus-ama7e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sonsuzda,

galip bir gladyötör gururu,

ve bir,

hüzün resmi,

yaşadıklarım..

sessizliğin,

o huzurlu tatlı sesi; 

ve yılgın bir ömrün,

hatıralara yaslanmış,

çaresiz yitimi.

hakikatin,

biçareliğin,

elden birşey gelmezliğin,

saplanış noktası.

fırtınada tutulan,

kuru bir

ağaç kökü,

ya da ıssız bir adada,

okuduğun son kitap artık..

neşeni kıskandırmanın,

sana tersten dönüşü.

ve de duygu nehrinde,

başkalarını yıkaman sırayla...

....

değdi mi,

girmekte olduğun,

o sır kapısından,

bir daha girememeye? 

ve göğü artık buz mavisi 

görememeye.

ve hayata asla,

senkronize

bir dalış

yapamamaya.

..

asırlarla biriken,

sendeki eşsiz 

elmas fırtınaları,

ver artık

hayatın yeni sahiplerine! 

ki  hayat azad olsun,

körelmiş

bütün bunak esaretlerden.', 'sonsuzda, galip bir gladyötör gururu, ve bir, hüzün resmi, yaşadıklarım.. sessizliğin, o huzurlu tatlı sesi;  ve yılgın bir ömrün, hatıralar...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/azad-et-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyüş', 'yuruyus-i-smail-karakus-fbdx8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'serin bir yürüyüş.

ölgün bir his yitimi.

ışığa koşuş yarışırcasına, 

elele, 

hiç tanımadıklarınla.

tehlikeli bir parkur, 

her dönüşte,

bir puan giz yazılıyor hanene.

saydam kuşların eşliğinde, 

finişe belki en yakın görmek kendini.

frenleyemeden, 

kendini gidişine  bıraktığın

o sakin yürüyüş; 

aslında, 

bitirmeyi çokça istediğin

hülyalarının

kayıp krokisi.

yürüyüş, 

ilelden ebede dek 

süren,

sürecek olan,

sürmesi gereken

ve

yaşamla kaybettiklerini,

yürüyüşünle

kazanman birer birer.

kazanman

her keskin parkurda

bir kaybettiğini, 

ve en sevdiğini belki...', 'serin bir yürüyüş. ölgün bir his yitimi. ışığa koşuş yarışırcasına,  elele,  hiç tanımadıklarınla. tehlikeli bir parkur,  her dönüşte, bir p...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yuruyus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Nasırlaştırdı Yüreğimi', 'hayat-nasirlastirdi-yuregimi-ozlem-aman-4s8zd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'canım acıyor artık çakıl taşlarından

eskisi gibi çekemiyor yüreğim 

çakıl taşının acıttığı yerler

eski kabuk bağlamış yaralarımda açılıyor birbir

ve canım herzamankinden daha çok acıyor

ne yapsa bilmiyor

yüreğim.

aklıma uysam kimse çıkmasın karşıma

çekip gideyim görmeyeyim bir daha

ama yapamıyorum

sevdalı yüreğim bir kere

kimseyi dinlemedim

kimseye kanmadım desem yalan

kendimi dinledim ve kendi kendimi kandırdı yüreğim

hayat ben sana

ne yaptım da

nasırlaştı yüreğim', 'canım acıyor artık çakıl taşlarından eskisi gibi çekemiyor yüreğim  çakıl taşının acıttığı yerler eski kabuk bağlamış yaralarımda açılıyor b...', ARRAY['Türk Edebiyatı','Şiir','Özlem Aman']::text[], 8.5, '{"poet":"Özlem Aman","poet_slug":"ozlem-aman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayat-nasirlastirdi-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Doldu', 'vakit-doldu-i-smail-karakus-nuceg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saatler  oldu nefes almayalı şöyle bir, 

Günler oldu gülmeyeli, 

Geceler oldu gelmeyeli sen

Vakit doldu, dünya durdu.

Başaklar oldu, büküldü boyunları, 

Mevsimler döndü yaşımla beraber, 

Servetler tükendi vuslatının uğruna

Vakit doldu, dünya durdu.

Zaman geçti üstüste yelkovandan, 

Akrep zaten karışmadı hiç

Anlaşılmadı yolculuk, bilinmedi kıymeti, 

Vakit doldu, dünya durdu

Rüzgarlar esti kum tepelerine, 

Ve fırtınalar koptu çölde ardarda, 

Meltem ferahlılığıyla serinlerken biz, 

Vakit doldu, dünya durdu.

Gece örtemedi gündüzünü, 

Gündüzün  gecesine sırtı dönüktü

Güneş aya çelme takarken

Vakit doldu, dünya durdu.

Balıklar uçarken gökyüzünde

Zürafalar yüzmeye heveslendi

Kuşlar koşmaya başlamışken tam, 

Vakit doldu, dünya durdu.

Verilirken tüm kararlar doğruluğa

Ve içilirken ölmeye o antlar

Tam da konulmuşken eller üstüste

Vakit  doldu dünya, durdu.', 'Saatler  oldu nefes almayalı şöyle bir,  Günler oldu gülmeyeli,  Geceler oldu gelmeyeli sen Vakit doldu, dünya durdu. Başaklar oldu, büküldü...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vakit-doldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlığımın Şehri', 'yanlizligimin-sehri-ercan-gencer-qiqlm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sonbahar...

Ağladım gözlerine, 

Hazan yaprakları gibi döküldüler senin için. 

Sana susayan

Çatlamış dudaklarımla söylediğim, 

Yalnızlığıma yaktığım bir türkü oldun. 

En zor anımda gözlerinde, 

Belirdi bir serap gibi hüznüm.

Bu sonbahar...

Dökülen yapraklar mı? 

Göz yaşlarım, saçlarım ve yağmur... 

Bir tren düdüğü alıp götürdü beni, 

Sensizliğin olduğu, 

Yanlızlığımın şehrine...

Bu sonbahar...

Benliğimi kaybettim, şehrimin yanlızlığında... 

Düğümlendi ümitlerim bu sonbahar... 

Ve hasretin bağrımı sıkıştırıyor, 

Ve sigaram arkadaşım oluyor

Bu serin gecelerinde, 

Yanlızlık şehrimin.

Bu sonbahar... 

Bu sonbahar...

Birgün kışa dönecek

Oysaki ben kışı yaşamak 

Hiç istemiyorum ki...

Karlar yağarsa 

Hasretimin üstüne, 

Bir kardelen gibi

Delecek karı özlemim

Baharın gelişini müjdeleyecek...

Birgün bahar gelirse, 

Yanlızlığın şehrine

İnan seninle olacak biriciğim...', 'Bu sonbahar... Ağladım gözlerine,  Hazan yaprakları gibi döküldüler senin için.  Sana susayan Çatlamış dudaklarımla söylediğim,  Yalnızlığım...', ARRAY['Türk Edebiyatı','Şiir','Ercan Gencer']::text[], 8.5, '{"poet":"Ercan Gencer","poet_slug":"ercan-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yanlizligimin-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sav(aşk)', 'sav-ask-ali-saglam-3-pcc84', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çiçeği çiçek yapan, 

Daldaki ayrıcalığıdır...

Aşk''ı aşk yapan, 

Geride bıraktığı...

Harabe insan yığınlarıdır! ..', 'Çiçeği çiçek yapan,  Daldaki ayrıcalığıdır... Aşk''ı aşk yapan,  Geride bıraktığı... Harabe insan yığınlarıdır! .....', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sav-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumali''ye Armağan', 'cumali-ye-armagan-salih-ozalasan-3iivr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nede sevmiştim Cumali''yi

Yüreğimde alev alev yanmıştı o zaman

Selamsızda geçmezdi ya hani

Selamı mutlaka vardı herzaman

Sohbetine olmazdı doyum

Bıkmazdım dinlemeye başlasam sabahtan

Bazen nede kavga ederdik

Kanlı bıçaklı sanırdı gören uzaktan

Nede çabuk biterdi kavgamız

Aslında ikimizde yanmıştık tuzaktan

İkimizde hasrettik yürekten bir sevgiye

Tatlı sözler çıksın isterdik dudaktan

Bazen öylede hüzünlenirdikki

Gözyaşımız akardı her iki yanaktan

Dertleşirdik bazen sabaha dek

Aslında tanışmazdık ikimizde uzaktan

O bana sormazdı ben ona

Hangimiz erkek, hangimiz bayan

Meğerse bizim cumali değilmiymiş; ? 

Yüreği sevgi dolu hoş bir bayan

Aslında bende öyle istiyordum ya

Öğrenince şok oldum biran

Şimdi Cumali yok; karşımda hep

Gözler alev gibi yürek yakan

Cumali''den bana hatıra EDA''lı bir bayan

Ama seni yinede özlüyorum 

Özlüyorum Cumali bana inan

Sen benim için olmuştun

Herşeyden öte güvenilir bir insan

Sana teşekkür, Sana sevgi, Sana selam

Seni aratmıyor bana bıraktığın

Aslında sen olan bu tatlı insan

Senin gibi sıkıdostum varken

Ben asla, ama asla yıkılmam.', 'Nede sevmiştim Cumali''yi Yüreğimde alev alev yanmıştı o zaman Selamsızda geçmezdi ya hani Selamı mutlaka vardı herzaman Sohbetine olmazdı do...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/cumali-ye-armagan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-yavuz-turhan-yzmdw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakarken bir fotoğrafta sana, 

Gözlerim, yanıyor gözlerinde.

Bedenim yırtılıyor.

Düşlerimi delip, 

             hayallerime  varıyorsun.

Alnından öperken seni, 

              kayıtsızsın.

Gözlerin kapalı yol alıyorsun.

Derken....

Yüreğim, usul usul

                sevdana değiyor.

Özlemsin; 

                Özlediğimsin; 

                                       Özlemimsin...', 'Bakarken bir fotoğrafta sana,  Gözlerim, yanıyor gözlerinde. Bedenim yırtılıyor. Düşlerimi delip,               hayallerime  varıyorsun. Aln...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ozlem-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy', 'duy-necip-hikmet-06tl5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir zaman düşündümde

Bana göre şiir yok bu alemde

Yarenler  felaket arkadaşlarım

Hepsi kendini kandırır oysa bu işle

Ne dediğimi anlamadın biliyorum

Hayatta anlamak için çok şey var zaten

Hadi sen de katıl bana 

Göster şiir nasıl yazılır bu karmaşada

Necip der ki geliyorum gümbür gümbür

Dün dündür bugünü kim düşünür

Necip bir daha der ki

Kim ki okur benim şiirimi

Etsin arkadaşlarına tavsiye 

Ah bu fani dünyada necibe 

Bundan büyük yoktur hediye', 'Bir zaman düşündümde Bana göre şiir yok bu alemde Yarenler  felaket arkadaşlarım Hepsi kendini kandırır oysa bu işle Ne dediğimi anlamadın b...', ARRAY['Türk Edebiyatı','Şiir','Necip Hikmet']::text[], 8.5, '{"poet":"Necip Hikmet","poet_slug":"necip-hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/duy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-mustafa-i-bakorkmaz-wnqx1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ateş yazıyorum tutuşmuyor kağıt

Su yazıyorum sönmüyor ateş

Onmuyor sayrılığım 

Reçetedeki ilaçlardan', 'Ateş yazıyorum tutuşmuyor kağıt Su yazıyorum sönmüyor ateş Onmuyor sayrılığım  Reçetedeki ilaçlardan...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İbakorkmaz']::text[], 8.5, '{"poet":"Mustafa İbakorkmaz","poet_slug":"mustafa-i-bakorkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sair-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-necip-hikmet-mik12', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazdım

Bir şiir yazdım 

İki şiir yazdım

İki şiir yazdım

Üç dört beş yazdım 

Sen de yaz yaz yaz

Bir tane de sen yaz

Kıskananlar çatlasın 

Kıskananlar çatlasın', 'Bir şiir yazdım Bir şiir yazdım  İki şiir yazdım İki şiir yazdım Üç dört beş yazdım  Sen de yaz yaz yaz Bir tane de sen yaz Kıskananlar çatl...', ARRAY['Türk Edebiyatı','Şiir','Necip Hikmet']::text[], 8.5, '{"poet":"Necip Hikmet","poet_slug":"necip-hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yaz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya Yakalandı Yağmurlar 2', 'sevdaya-yakalandi-yagmurlar-2-aydin-karatay-40jq5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kolay degildi biliyorum sana sevdalanmak 

yinede korkmadan koştum ben sokaklarda 

yorulmadım geceninkaranlıgından korkmadım

sevdaya yakalandı yagmurlar

bilmeni istedim seninde 

haykırdım tüm güçümle sevmeni istedim 

belki zordu benim için ama söyledim

saklamadım senden 

gizlemedim yüregimi gizleyemedim 

sen gizemdin aslında benim için 

çözülmesi gereken bir bulmaca 

zorl bir labirenttin beynimin iç diyarlarında 

çokışı bulabadım çözümü bulamadım 

sevdaya yakalandı yagmurlar 

sarhoştum döndüm geri pişman oldum

sana geldim sen gelmedin hüzünle doldum

yaşamadım saydım bir süre hayatı 

yalan oldum 

gülmeyi unutmuştum önce sonra aşkı

ve kendimi ama seni asla 

sevdaya yakalandı yagmurlar 

sevda yakaladı yagmurları

ilk önce üşümüştüm 

sonra buz oldum inçitildim su oldum 

sızandım izmirin kaldırımlarında 

kordondan yürüdüm biraz sonra 

sonrası yoktu benim için sadece sendin o an 

sevda yakaladı yagmurları 

yagmurlar sevdaya yagdı', 'Kolay degildi biliyorum sana sevdalanmak  yinede korkmadan koştum ben sokaklarda  yorulmadım geceninkaranlıgından korkmadım sevdaya yakaland...', ARRAY['Türk Edebiyatı','Şiir','Aydın Karatay']::text[], 8.5, '{"poet":"Aydın Karatay","poet_slug":"aydin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevdaya-yakalandi-yagmurlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Bil', 'i-yi-bil-i-smail-safa-ermutlu-4mkqt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gezdim devran ettim yedi düveli

Gönüller eyledim bak bir saz ile

Tutmadın söyümü oldun divane

Gönüller devirdin bır kem söz ile

Dost olup dolaşmaz Kurt ile Kuzu

Muhabbet hayatın biberi tuzu

Kaptırma elinden kötüye kozu

Belaya garg eder seni tez ile

Varlığa kul olma yemesini bil

Gönüller fethedip girmesini bil

Ağlamayı bırak gülmesini bil

Gidecegiyz bir kaç arşın bez ile', 'Gezdim devran ettim yedi düveli Gönüller eyledim bak bir saz ile Tutmadın söyümü oldun divane Gönüller devirdin bır kem söz ile Dost olup do...', ARRAY['Türk Edebiyatı','Şiir','İsmail Safa Ermutlu']::text[], 8.5, '{"poet":"İsmail Safa Ermutlu","poet_slug":"i-smail-safa-ermutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iyi-bil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönülmüyor Ne Çare', 'donulmuyor-ne-care-i-smail-safa-ermutlu-dcqak', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gurbet elden alamadım hevesim

Çekilmiyor yanlızlığın çilesin

Eşim dostum sorar oldu nerdesin

Dönülmüyor bu yerlerden ne çare

Yad ellerde yitirmişim izimi

Bildiremem yürekteki sızımı

Gurbet elden sözüm ıle sazımı

Duyuramam eşe dosta ne çare

Takılmışım gurbet elin peşine

Hasret kaldım sevdığime eşime

Memleketim girer oldu düşüme

Varılmıyor düşten gayrı ne çare

ERMUTLU''yum yaşım aldı yürüdü

Gurbet derdi bedenimi bürüdü

Ölüm için gurbet sıla bir idi

Gidilmiyor Ölmeyince ne çare', 'Gurbet elden alamadım hevesim Çekilmiyor yanlızlığın çilesin Eşim dostum sorar oldu nerdesin Dönülmüyor bu yerlerden ne çare Yad ellerde yit...', ARRAY['Türk Edebiyatı','Şiir','İsmail Safa Ermutlu']::text[], 8.5, '{"poet":"İsmail Safa Ermutlu","poet_slug":"i-smail-safa-ermutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/donulmuyor-ne-care-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Ey Yar', 'yar-ey-yar-asik-seheri-2hlo9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sana uçuyorum kırık kanatlarımla, 

kaf dağının ardında zümrüd-ü anka''msın yar! 

bende olmak şerefken senin nurlu kapında; 

beni gönül tahtına oturtan hüma''msın yar! 

güneşimsin, ışığını almasam benim kalbim kararır.

gül yüzünü görmesem garib gönlüm sararır.

hayatımın tadısın, mutluluğumun adı, 

ilk ve son aşkımsın, kara sevdamsın yar! 

hasta gönlüm senden bir şifa ister, 

lütfeyle de bana gül yüzün göster.

ruhum sevgine aç, kalbim aşkına muhtaç, 

merhametli tabibim, derdime devamsın yar! 

ağyarı terkettim, sen benim dünyamsın yar! 

gündüzleri hayalim, geceleri rüyamsın yar! 

ayrılık korkusu yakar, kül eder beni, 

kavuşma ümidiyle yaşadığım Hülya''msın yar!', 'sana uçuyorum kırık kanatlarımla,  kaf dağının ardında zümrüd-ü anka''msın yar!  bende olmak şerefken senin nurlu kapında;  beni gönül tahtın...', ARRAY['Türk Edebiyatı','Şiir','Aşık Seheri']::text[], 8.5, '{"poet":"Aşık Seheri","poet_slug":"asik-seheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yar-ey-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Ben', 'sen-ve-ben-asik-seheri-962ro', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bedenim, sen can''sın, 

Can''dan öte canansın.

Canana canım kurban, 

Sen gönlümde sultansın...', 'Ben bedenim, sen can''sın,  Can''dan öte canansın. Canana canım kurban,  Sen gönlümde sultansın......', ARRAY['Türk Edebiyatı','Şiir','Aşık Seheri']::text[], 8.5, '{"poet":"Aşık Seheri","poet_slug":"asik-seheri","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-ve-ben-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmem', 'vazgecmem-asik-seheri-g7qqw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir senden vaz geçemem, 

Herşeyden vaz geçerim.

Bin kez dünyaya gelsem; 

Yine seni seçerim..', 'Bir senden vaz geçemem,  Herşeyden vaz geçerim. Bin kez dünyaya gelsem;  Yine seni seçerim.....', ARRAY['Türk Edebiyatı','Şiir','Aşık Seheri']::text[], 8.5, '{"poet":"Aşık Seheri","poet_slug":"asik-seheri","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vazgecmem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yârim Ay', 'y-rim-ay-asik-seheri-ltoy0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde yarım ay, 

Yeryüzünde yârim ay.

Ben nasıl sabredeyim? 

Görüşemedik yarım ay...', 'Gökyüzünde yarım ay,  Yeryüzünde yârim ay. Ben nasıl sabredeyim?  Görüşemedik yarım ay......', ARRAY['Türk Edebiyatı','Şiir','Aşık Seheri']::text[], 8.5, '{"poet":"Aşık Seheri","poet_slug":"asik-seheri","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yarim-ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Qarabağ', 'qarabag-ahmet-hani-v3lxe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu toz torpaq nedir

Kimdiler atçılar! 

Yurd bizimdir

Dil bizimdir

Oba bizim

El bizimdir

Ne isteyirler bunlar? 

Laçın bizm bağ bizimdir

Ha! bu Qarabağ bizimdir.

Ne isteyirler bunlar? 

2  august  1992', 'Bu toz torpaq nedir Kimdiler atçılar!  Yurd bizimdir Dil bizimdir Oba bizim El bizimdir Ne isteyirler bunlar?  Laçın bizm bağ bizimdir Ha! b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/qarabag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit Alevinde Yangın', 'kibrit-alevinde-yangin-mehmet-dereli-50kkf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni tanıdığımda bir kibrit aleviydin

Sen şimdi yüreğimde büyük yangınsın

Rüzgarın yardımıyla sürekli büyüyorsun

Önce kalbimde şimdi vücudumun heryerindesin

Çaldın ilk gördüğümde kalbimi

Aldın sonra sevdiğimde aklımı

Canıma can oldun yüreğimeyse doldu sevgi

Bana eş, hayatıma oldun renk kuşağı

Susuzluğuma su, aş oldun açlığıma

Geceleri gördüğüm rüya

Gündüzleri kurdugum hülya

Sırdaş oldun, dertlerimi paylaşmaya

Bir buket gibi yüreğimde sevgin

Bitmez gibi bu sevişle sana aşkım

Yemin etmiş gibi sanki tüm hücrelerim

Bu sevdayla bir ömür yaşarım.', 'Seni tanıdığımda bir kibrit aleviydin Sen şimdi yüreğimde büyük yangınsın Rüzgarın yardımıyla sürekli büyüyorsun Önce kalbimde şimdi vücudum...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dereli']::text[], 8.5, '{"poet":"Mehmet Dereli","poet_slug":"mehmet-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kibrit-alevinde-yangin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sihirli Bir Nefes', 'sihirli-bir-nefes-mustafa-sureyya-sezgin-13wii', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutamadığım bir çarşamba var.

Sihirli bir nefes gibi, 

Koşarak yanıma geldin.

Şaşırdım ve

Sana belli etmeden

Öyle sevindim ki, 

O gece sabahlara dek

Rüyalarımdaydın inan...

Oysa pek uyuyamazdım

Sen girince aklıma.

Şarkı söylerim

Senin için, 

Ağlarım bazen

Sessizce yatağımda.

Bir şeyler sezersem davranışlarından, 

Surat asarım sana.

Uzaklaşıveririm hemen senden, 

Anlam veremezsin belki sen.

Anlayasın istemiyorum zaten, 

Arkadaşlığımız bozulur sonra.

Oysa ben, 

Seviyorum seni.

Yazık! ..

Seninle ikimiz

Hoşlansak da birbirimizden, 

Atlayamayız aradaki uçurumu...

Neyse bırakalım bütün bunları.

Şimdi kaçırmayayım, gelmişken, 

Şu uykumu...', 'Unutamadığım bir çarşamba var. Sihirli bir nefes gibi,  Koşarak yanıma geldin. Şaşırdım ve Sana belli etmeden Öyle sevindim ki,  O gece saba...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sihirli-bir-nefes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkım Sensin', 'sarkim-sensin-mustafa-sureyya-sezgin-h7796', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şarkı yapmak istiyorum

Bu gece senin için.

Güftem sensin

Bestem yine sen! ..

Bildiğim bütün şarkıları

Sana okumak, 

Sevinci, neşeyi, acıyı, kederi

Senin gözlerinde yaşamak...

Seni şarkılarla

Anlatmak istiyorum.

Her şarkıda sen varsın, 

Ben varım.

Karanlık bir dünya, 

Dayanılmaz bir tutku var.', 'Bir şarkı yapmak istiyorum Bu gece senin için. Güftem sensin Bestem yine sen! .. Bildiğim bütün şarkıları Sana okumak,  Sevinci, neşeyi, acı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sarkim-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmadın', 'i-nanmadin-metin-dermanli-0xa1x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnanmadın ne yapayım

Sensizlikmiş senden payım

Allahmısınki sana tapayım

Sevdim seni inanmadın

Sensiz olmuyor yapamıyorum işte

Yaktın len beni bu sın gidişte

Hiç mi aşık olupta yanmadın? 

Sevdim seni inanmadın', 'İnanmadın ne yapayım Sensizlikmiş senden payım Allahmısınki sana tapayım Sevdim seni inanmadın Sensiz olmuyor yapamıyorum işte Yaktın len be...', ARRAY['Türk Edebiyatı','Şiir','Metin Dermanlı']::text[], 8.5, '{"poet":"Metin Dermanlı","poet_slug":"metin-dermanli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/inanmadin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Tınısı', 'sevgi-tinisi-filiz-angay-ee0c0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzanmak dallara

Yaprakların damarlarını hissedercesine

                        dokunmak için, 

Gözlemek denizi

Uzaklardaki ufuk çizgisinin derinliğinde

                          kaybolurcasına, 

Dinlemek kuşları, 

Zamandan soyutlanıp cıvıltıların yansıttığı

                  coşkuyu sabitlercesine...

Haykırmak derinlerdeki heyecan, sevgi, korku çatışmasını

                                     cesur ve yürekten! 

Yaprak yerine, elleri hissetmek için uzanmak gibi, 

Ufuk yerine gözlerin derinliğinde kaybolmak gibi, 

Kuşlar yerine bir sevgi sözcüğünün tınısını dinlerken, 

                                  sadece zamanı değil, 

                             TÜM EVRENİ SABİTLER GİBİ!', 'Uzanmak dallara Yaprakların damarlarını hissedercesine                         dokunmak için,  Gözlemek denizi Uzaklardaki ufuk çizgisinin d...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgi-tinisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeler Ve Işık', 'golgeler-ve-isik-filiz-angay-kw11n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gölgeler girdi hayallerime, 

Kararttılar aydınlığımı yer yer, 

Beni uçuran ışığım zayıfladı, 

Yarı karanlık, yarı parlak bir yol oldu gittiğim bilinmezlik.

Oysa yüreğimden gözlerime yansıyan ışık, 

Ümit verirdi bana da, 

Onu görebilenlere de, 

Huzur verirdi, 

Renklerin ayrımına vardırırdı, 

Doğanın, gökkuşağının gördüğümüz renklerinin

Ve sevginin, dostluğun, güvenin göremediğimiz renklerinin.

Sebebini bilmem, ama, 

Sonra birden aydınlandı yüreğim, 

Sildi gölgeleri, 

Görebiliyorum görünen, görünmeyen tüm renkleri.

Bilinmez yolumda umut dolu ilerliyorum ışığımla.

Acaba bu gerçeklik mi, 

Yoksa rüyadan uyanacak mıyım sabah?', 'Gölgeler girdi hayallerime,  Kararttılar aydınlığımı yer yer,  Beni uçuran ışığım zayıfladı,  Yarı karanlık, yarı parlak bir yol oldu gittiğ...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/golgeler-ve-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Kraliçesi', 'gece-kralicesi-filiz-angay-lb4h7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'serin bir rüzgar girdi penceremden

okşadı yüzümü

çağırdı beni gecenin karanlığına

davetine uydum

baktım pencereden

gördüm sadece gece bir kere açan ''gece kraliçesi'' çiçeğini

kocaman, sarı-beyaz parlıyordu gecenin karanlığında

ışıl ışıl

tıpkı senin bir şeyi dikkatle dinlerken ışıldayan gözlerin gibi

pırıl pırıl

delip geçen bir ışıltı

kamaştırdı gözlerimi

dokundum çiçeğe

elim ısındı...', 'serin bir rüzgar girdi penceremden okşadı yüzümü çağırdı beni gecenin karanlığına davetine uydum baktım pencereden gördüm sadece gece bir ke...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gece-kralicesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümsemen', 'gulumsemen-filiz-angay-ebdkm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman denize baksam

Senin gözlerine dalar gibiyim.

Duyduğum her dalga sesi, 

Kuş cıvıltısı, 

Yaprak hışırtısı, 

Parmaklarının tınısıyla özdeşleşir.

Gün içinde açan her çiçek

Senin gülümsemendir.

Denize de dalsam, 

Doğayla da bütünleşsem, 

Kendimi yollara da vursam, 

Konuştuğum kişilerin yüzü silikleşir, 

Sen parlarsın karşımda gülümseyerek., 

Hala....', 'Ne zaman denize baksam Senin gözlerine dalar gibiyim. Duyduğum her dalga sesi,  Kuş cıvıltısı,  Yaprak hışırtısı,  Parmaklarının tınısıyla ö...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gulumsemen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzluk', 'umutsuzluk-filiz-angay-i5nfy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'umuttur insanı yaşatan, 

coşku veren, 

parmak uçlarıyla bile sevgiyi aşılatan...

umut bitince gözlerin feri solar, 

ne denizin mavisi, 

ne ağacın yeşili

ne güneşin pırıltısı görülür artık.

renksiz bir fanusa kapatılmış gibi

alınan taze soluk tükenir, 

bıkılır hayattan...

ben umudumu kaybettim!', 'umuttur insanı yaşatan,  coşku veren,  parmak uçlarıyla bile sevgiyi aşılatan... umut bitince gözlerin feri solar,  ne denizin mavisi,  ne a...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umutsuzluk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert Ve Coşku Girdabı', 'dert-ve-cosku-girdabi-filiz-angay-8md8n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dertliyim, 

Derdim çeker beni içine.

Çıkmaya çalıştıkça, 

Dalarım derinlere.

Coşkuluyum, 

Coşkum uçurur beni yıldızlara, 

Sevgimi, sevincimi haykırmak isterim, 

Ama korkarım, 

Anlayan olmaz diye.

Derdim ve coşkum, 

Gün be gün yorar beni.

Düşünce fırtınasıyla savrulur, 

Duygu seliyle dirilir, 

Kararsızlık denizinde boğulurum; 

Acaba sevgimi haykırmazsam, 

Birgün ''KEŞKE''der miyim, diye.', 'Dertliyim,  Derdim çeker beni içine. Çıkmaya çalıştıkça,  Dalarım derinlere. Coşkuluyum,  Coşkum uçurur beni yıldızlara,  Sevgimi, sevincimi...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dert-ve-cosku-girdabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okyanus', 'okyanus-filiz-angay-7a5op', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalgalar köpük köpük

Şaha kalkmış bir at gibi yükselmiş

Elimi uzatıyorum dokunuverecekmiş gibi.

Ilık rüzgar yüzümü okşuyor

Beni alıp uçuruverecekmiş gibi

		Dalgaların üzerinden..

Oturmuşum teknenin ucuna

Gözlüyorum gittikçe yaklaşan yeşil karayı.

Dinlediğim müzik, 

Okyanus sesini çağrıştırıyor.

Şahlanmış dalgalar, 

Ilık rüzgar, 

Okyanus esintisi, 

Yeşil kara, 

Zihnimin en derin yerlerinde savaşan düşüncelerimden

				Uzaklaştırıyor beni...

Bırakıyorum kendimi hayali okyanusumun kucağına...', 'Dalgalar köpük köpük Şaha kalkmış bir at gibi yükselmiş Elimi uzatıyorum dokunuverecekmiş gibi. Ilık rüzgar yüzümü okşuyor Beni alıp uçuruve...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/okyanus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalga', 'dalga-filiz-angay-5vik7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dalga nedir? 

Onu nasıl gördüğümüze bağlı.

Kimine göre yükselen su birikintisi

		Ucunda köpüğü olan, 

Kimine göre şahlanan duygu yoğunluğu

		Derinden gelen.

Su da olsa, duygu da olsa

Ne farkeder? 

Çağırmıyor mu bizi kucağına?', 'Dalga nedir?  Onu nasıl gördüğümüze bağlı. Kimine göre yükselen su birikintisi 		Ucunda köpüğü olan,  Kimine göre şahlanan duygu yoğunluğu 	...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dalga-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dert Beni Adam Eder', 'bu-dert-beni-adam-eder-ataol-behramoglu-86sbb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece gündüz dolaşırım tenhalarda menhalarda

Benim annem güzel annem beni koyver

Sağ yanımda bir sızı var, sol yanımda yandım aman altıpatlar

Bu dert beni verem eder

Eğri büğrü bakar oldum boyunbağı takar oldum şaşkın oldum

        şakar  oldum 

İkide bir yüreğimi dağa taşa diker oldum

Şunca yıldır karanlıkta göz kırpmak bıkar oldum

Benim annem şeker annem gençlik elden gitti gider

Dama çıktım damdan düştüm kılıç kestim esrar içtim

Şahin oldum keloğlanın külahını kaptım kaçtım

Yare ağlar güler uçtum yarı yolda yorgun düştüm

Benim annem kadın annem buna nasıl iş bana deyver

Gece gündüz düşünürüm tenhalarda menhalarda

Aman annem güzel annem beni koyver 

Sağ yanımda bir sızı var, sol yanımda dağlar duman altıpatlar

Bu dert beni adam eder', 'Gece gündüz dolaşırım tenhalarda menhalarda Benim annem güzel annem beni koyver Sağ yanımda bir sızı var, sol yanımda yandım aman altıpatlar...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-dert-beni-adam-eder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz kabuğum', 'deniz-kabugum-reha-basogul-5vk63', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlıkları arıyorum Rodos''un derin delhizlerinde

açılmamış bir deniz kabuğu saklıyor incisini

mercan mercan döküyor gözlerini

fersah fersah aşıyor kum denizlerini

inim inim inliyor edepsiz nefesleri...

Kaldır başını ey Rodos''lu! 

Kaldır ki görsünler içimizdeki deniz kabuğunu...

soysuzluğuma, sorgusuzluğuma aç soluğunu

sahipsizliğime, ölümsüzlüğüme saç onurunu...

arsızlığıma, katıksızlığıma bırak tutkunu

ve açıldı deniz kabuğu...

kabuğun kaçırdı  sakin ruhlarımı

soluğun uyandırdı sessiz çığlıklarımı

onurun araladı matem yarıklarımı

tutkun aydınlattı zevk mağaralarımı

söyle neden basit bir özveride istedin öbür yarımı

söyle neden sormadın yaralı anılarımı

söyle neden dilsizliğin sardı deli kanımı

korkarım ki ebediyen cevapsız bırakacaksın sorularımı...

karanlıktaki kürek mahkumu gibi

koşulsuz gecelerde katettin içimi

bezmedin, yenilmedin

gözyaşlarımın üzerinde çektin küreklerini...

büyülü renklerle öptük gözlerimizi

masalsı ezgilerle kokladık ellerimizi

benzersiz resimlerle boyadık bedenlerimizi

kirli perdelerle seviştirdik hayallerimizi

yoksa bu yüzden mi sevdim seni

yoksa bu yüzden mi bencilliğim üredi? 

masumluğunu koymuştun oysa ki göğsümün kenarına

derin düşler sokmuştun asırlık uykusuzluğuma

çıplak sırtında acılarım akarken

vahşi atlara bindin rüyalarında...

hani dudaklarımız hiç ayrılmayacaktı

bak işte bıçak gibi kesti şimdi onları zaman tanrısı...

Şimdi dönüyorsun seni bulduğum deryaya

kapatıyorsun kabuğunu soranlara

tek bir odan vardı denizkabuğunda

onu da biz doldurmuştuk ayışığıyla

Ay yüzün ve uluyan kurdunla

bir gün bir yerde karşılaşırsak

Kaldır başını ey Rodos''lu

Kaldır ki görsünler içimizdeki deniz kabuğunu...', 'Karanlıkları arıyorum Rodos''un derin delhizlerinde açılmamış bir deniz kabuğu saklıyor incisini mercan mercan döküyor gözlerini fersah fersa...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/deniz-kabugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yolculuk', 'son-yolculuk-ozcan-nevres-bojwr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaçınılmaz sona doğruydu bu çıktığım son yolculuk

Koskoca dağın gölgesini yutmuş sağ yanımdaki deniz

Dağın gölgesi boğulmuş denizin karanlığında

Ben boğulmuşum çektirdiğin çilelerin girdabında

Kumsalda yürüyorum kaçınılmaz sona doğru hevesle

Dalgalar ayak izlerimi siliyor

Geçmişte ne kaldıysa peşime takılmasınlar diye

Kayalar var ileride sarp mı sarp

Bilir misin o kayalarda nice aşıkların yitip gittiğini

Ve o kayaların beni davet ettiğini

Gel diyorlar bana hadi durma gel

Yitik umutların mı seni yaşama küstüren

Ne duruyorsun çık üstüme at kendini boşluğa

Umutsuz bir aşk son bulsun bir vefasız uğruna', 'Kaçınılmaz sona doğruydu bu çıktığım son yolculuk Koskoca dağın gölgesini yutmuş sağ yanımdaki deniz Dağın gölgesi boğulmuş denizin karanlığ...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/son-yolculuk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Artık Uyandım', 'ben-artik-uyandim-salih-ozalasan-hyzhe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzaklardayım diye sakın üzülüp ağlama

Sana sendende yakınım ben aslında

Beni öyle çok, çok uzaklarda arama

Açıpta şöyle bir kalbine baksana

Bak orada göreceksin

Uzaklarda sandığın birisini

Elinde bir buket çiçek

Yalnız sana adamış sevgisini

Uzağı yakın ettim

Sende yaşattım; güzel olan ne varsa

Belki hata, belki günah, belki ayıp ettim

Yakarım bu Dünya''yı, inan sensiz batarsa

Sen yüreğimin ta içinde bana bakan

Bendeki tüm Tabuları bir, bir yıkan

Uzaklara bakma gözlerine bak biran

Gözbebeklerinde beni göreceksin inan

Gözlerinden gönlüne bir ışık olup akan

Sıkıdostun sana senden de yakın

İstersen sen onu çok uzaklarda san

Ben uyandım artık sende uyan', 'Uzaklardayım diye sakın üzülüp ağlama Sana sendende yakınım ben aslında Beni öyle çok, çok uzaklarda arama Açıpta şöyle bir kalbine baksana ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-artik-uyandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-i-smail-karakus-abpyf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Semadan kop da  gel

Kutsa gövdenin arka yüzünü.

Sahibine hüküm giydir, 

Sindir alnındaki cezbeyi.

Hu ları iç de gel.

Ki kus günahları parmaklarından.

Aldır kalbindeki pıhtıları.

Ve soldur kara güllerini,

Acınla beraber.

Yaşına küs de gel

Soğut avurtlarını karanlıkların.

Kıs gözlerini geceye,

Nefesinin ardından.

Şiirden düş de gel.

Atla mısralardan başaşağı.

Kafiyelere kurşun sık,

Rediflerin arasından.

Gül hayatın renklerine,

Sevdaları sallayarak.', 'Semadan kop da  gel Kutsa gövdenin arka yüzünü. Sahibine hüküm giydir,  Sindir alnındaki cezbeyi. Hu ları iç de gel. Ki kus günahları parmak...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gel-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farklı Sanmıştım...Sevdim', 'farkli-sanmistim-sevdim-mine-aktas-ozkamali-5xvrg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Farklı sanmıştım seni.

Diğer tanıdığım tüm insanlardan farklı. 

Özü sözü bir, 

yüreği yüzüne yansıyor diyordum. 

Yarı yolda bırakmayacak kadar mert, 

hayal kırıklığı yaşatmayacak kadar insan diyordum. 

Yılların yüreğime kazıdığı acıyı bakışlarıyla, 

gülüşleriyle, sözleriyle 

hele de en son ettiği yeminle 

silecek diyordum. 

Diğer tüm insanlardan farklı sanmıştım seni. 

Kendime bile itiraf etmekten korktuğum

zayıflıklarımı itiraf ettiğim dostum, 

sırdaşım olmuştun. 

Gerektiğinde tüm sevgimi verebileceğim, 

nazlatabileceğim çocuğum olmuştun. 

İçim acıdığında, 

içim yandığımda 

içimin yangınını dindirsin diye 

kucağına sığındığım annem olmuştun.

Annem olmanı sevmiştim. 

Sevdiğim pamuk ellerinin arasındayken yüzüm

“bunların hepsi geçecek, yanındayım” dediğinde

İçimde oluşan huzuru sevmiştim

En çok da gözyaşlarımı dindirmek için 

çabalamanı sevmiştim. 

İçten içe öfkelenmelerini, 

yumruğunu sıkmalarını, 

bu çabaların çektiğin o acıların gerçek olmasını, 

onlara inanmayı sevmiştim. 

Benim için endişelenmeni, 

kötü zamanlarımda yanımda olacağını 

bilmenin rahatlığını sevmiştim. 

Ben senin beni sevmeni sevmiştim. 

“Bu iş olmaz” dedikçe beni ikna etmelerini, 

 “Sana mecburum” diyişlerini sevmiştim. 

Akşamları odamda yalnızken

pencereden esen yokluğunu sevmiştim. 

Bir dakikalığına da olsa seslerimizi duymak, 

birbirimizi görebilmek için 

yaptığımız çırpınışları sevmiştim. 

Ben istemeden verdiğin umutları, 

çocukluğumda kalan iç sevinçlerimi 

bu yaşıma çağırmanı sevmiştim. 

Seni düşünerek dinlediğim şarkıların 

kulağımda değil yüreğimde bıraktığı lezzeti

o andaki sensizliğimi, yalnızlığımı 

ve yüreğini sevmiştim.

Sevgisiz yaşanmaz diyordum... 

Çünkü benim için sevgi sendin. 

Farklı sanmıştım seni. 

Tanıdığım diğer tüm insanlardan farklı ve özel sanmıştım. 

Ve onun için sevmiştim....', 'Farklı sanmıştım seni. Diğer tanıdığım tüm insanlardan farklı.  Özü sözü bir,  yüreği yüzüne yansıyor diyordum.  Yarı yolda bırakmayacak kad...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/farkli-sanmistim-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-hakan-yavuz-63o4c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zaman, çıkrığı döndükçe derinleşen kuyu

zaman der, iç kuyudan çıkanları ve uyu

zaman, tenimde yanlış algılanan bir duyu

zaman, içimdeki değirmenin tek can suyu', 'zaman, çıkrığı döndükçe derinleşen kuyu zaman der, iç kuyudan çıkanları ve uyu zaman, tenimde yanlış algılanan bir duyu zaman, içimdeki deği...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yavuz']::text[], 8.5, '{"poet":"Hakan Yavuz","poet_slug":"hakan-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zaman-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'His Dökümü', 'his-dokumu-i-smail-karakus-n6a20', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlık akşamında

Çok uzun sürecek belli, 

Bu yorgun his dökümü

Tapon duygularım

Götürdü beni

Esmer kaderime

İsteksiz düşlerim azdı yine

Coşturdum 

Kin sanatını.

Bayat silüetleri, 

Yıkadım hizip yağmurlarıyla.

Canlandırdım 

İblis papatyaları.

Küflenmiş zevklerimde, 

Ortalama sevgileri hesapladım.

Antik sonuçlar çıktı

Eşittirin yanına.

Yalnızlık akşamında

Çok uzun sürdü

Bu yorgun 

His dökümü', 'Yalnızlık akşamında Çok uzun sürecek belli,  Bu yorgun his dökümü Tapon duygularım Götürdü beni Esmer kaderime İsteksiz düşlerim azdı yine C...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/his-dokumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçun Güvercinler', 'ucun-guvercinler-i-smail-karakus-gvn97', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haydi uçun artık güvercinler

Ve konmayın bir daha pencereme.

Haber ulaştırın kumrulara

Ve bir de serçelere

Gidiyor dostunuz 

Soğumuş ülkelere, 

Gidiyor dostunuz 

Beyaz bilinmezlere

Haydi uçun artık güvercinler,

Yetsin yasınız bu senelik.

Ve hüznünüzü dinlendirin bir süre.

Gidin penceremden,

Düşman tellere.

Gidin gökkuşağındaki,

Esrik sevgilere.

Haydi uçun artık  güvercinler.

Konmazsınız bilirim,

Bir daha pencereme.

Şarkınızı söyleyin o eflatun göklerde.

Bir kırık dallı ağaç gördüğünüzde,

Hatırlayın lütfen,

Bu dostunuzu siz de!', 'Haydi uçun artık güvercinler Ve konmayın bir daha pencereme. Haber ulaştırın kumrulara Ve bir de serçelere Gidiyor dostunuz  Soğumuş ülkeler...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ucun-guvercinler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahip', 'sahip-i-smail-karakus-erve7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sahip, 

Buyur ölümcül yalnızlığa.

Kafeslere astar çek.

Zevkleri idare etsin, 

Fikirsiz kuşların.

Yoldaşına öğreti ödünç ver,

Aşklardan bahseden.

Eflatun üfle,

Akillerin kulak zarına.

Ve Rabbiyessirli sulardan içir, 

Yeşil gözlü çocuklara.

Sahip,

Rejimleri incelt biraz,

Al havalarını yavaştan.

İblisleri çöz artık,

Mücadele öğrensin,

Acemi nefisler.

Zeki bir Nemrut gönder,

Ve eli çekiç tutmayan.

Velev yokuşlarda bekleyenleri,

Bekletme inişlerde.

Sahip,

Soruları cevapla,

Kısa olsun ve sırlı.

Bir tavsiye gönder,

Azrail''in kanatlarıyla.

Tarihi geçmiş kalabalıkları,

İade al,

Miladın en evveline.

Rahatlasın dünya,

Ve gökkuşağının son rengi...', 'Sahip,  Buyur ölümcül yalnızlığa. Kafeslere astar çek. Zevkleri idare etsin,  Fikirsiz kuşların. Yoldaşına öğreti ödünç ver, Aşklardan bahse...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sahip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılaştığımız O Yerde', 'karsilastigimiz-o-yerde-ozcan-nevres-1esc2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karşılaştığımız O Yerde

İlk karşılaştığımız o yerde

Aradan uzun yıllar geçse de

Gelişini bekledim hep boş yere

Orada yeşermişti

En güzel umutlar gönlümde

Aşkın en güzelini 

Ve ihanetin en acısını orada tattım

Orada bekledim seni 

Yitik aşkımın üstüne 

Orada ağıtlar yaktım. 

Göz yaşlarım orada kuruttu 

Gönlümde yeşeren tüm umutlarımı

Orada bekliyorum yine 

Ölüm denilen o kaçınılmaz sonu', 'Karşılaştığımız O Yerde İlk karşılaştığımız o yerde Aradan uzun yıllar geçse de Gelişini bekledim hep boş yere Orada yeşermişti En güzel umu...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karsilastigimiz-o-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak Bir Gönül Verdi Bana', 'hak-bir-gonul-verdi-bana-yunus-emre-h28l2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hak bir gönül verdi bana ha demeden hayrân olur

Bir dem gelir şâdân olur bir dem gelir giryân olur

Bir dem sanasın kış gibi şol zemheri olmuş gibi

Bir dem beşâretden doğar hoş bağ ile bostân olur

Bir dem gelir söyleyemez bir sözü şerh eyleyemez

Bir dem dilinden dür döker dertlilere dermân olur

Bir dem çıkar arş üzere bir dem iner taht-es-serâ

Bir dem sanasın katredir bir dem taşar ummân olur

Bir dem cehâletde kalır hiç nesneyi bilmez olur

Bir dem dalar hikmetlere Câlînus u Lokmân olur

Bir dem dev olur yâ peri vîrâneler olur yeri

Bir dem uçar Belkîs ile sultân-ı ins ü cân olur

Bir dem varır mescitlere yüz sürer anda yerlere

Bir dem varır deyre girer İncil okur ruhbân olur

Bir dem gelir Îsâ gibi ölmüşleri diri kılar

Bir dem girer kibr evine Fir''avn ile Hâmân olur

.

Bir dem döner Cebrâil''e rahmet saçar her mahfile

Bir dem gelir gümrâh olur miskin Yunus hayrân olur', 'Hak bir gönül verdi bana ha demeden hayrân olur Bir dem gelir şâdân olur bir dem gelir giryân olur Bir dem sanasın kış gibi şol zemheri olmu...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hak-bir-gonul-verdi-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-sair-revolver-ln5ch', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'pütürlü duvarla bugun tanıştım  ben

ewet ilk kez tavana gerçekten yanlız bakıyordum belki

yada ilk kez imdat dediğimde yoktu yanıma koşanlar

her ne olursa olsun koltuğum çok rahattı

bir koltuğa özenen ruhumu ilk kez bu gece keşfettim ben

yapayalnız bir sahil, bir deniz sadece benim girdiğim

sahipsiz bir bar ve sahipsiz biz gitar özlemim ilk kez bugün çıktı ortaya

bir oyunun bitmesine sevinmek çok kolaydı eskiden

son eğlencesi kalmış bir sarhoşun yalnızlığı, 

son sigarası bitmiş bir insanın öfkesi

ve son dostu kalmış bir insancıktan bile daha acı olan olur bazen...

ateşler yakmaz, anlamlar ifadesiz ve koliklikler kesmez insanı bazen

acı verme...', 'pütürlü duvarla bugun tanıştım  ben ewet ilk kez tavana gerçekten yanlız bakıyordum belki yada ilk kez imdat dediğimde yoktu yanıma koşanlar...', ARRAY['Türk Edebiyatı','Şiir','Şair Revolver']::text[], 8.5, '{"poet":"Şair Revolver","poet_slug":"sair-revolver","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aci-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-sair-revolver-u0prc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tomurcuklar açarken dallarda ki sevmeyi yeni öğreniyorduk ikimiz, 

yıl 97 ay baharın ilki, 

kendimi sevdirmeyi bir borç bildim aslında, 

yaş 18 tecrübe sıfırın altında.

daha elimi bile tutmadan öptün beni, ki çapkın geçinirdim sözde, 

yıl 2001 ay yine baharın ilki, 

özde aynı öz ama çapkın geçinmiyorum bilki...', 'tomurcuklar açarken dallarda ki sevmeyi yeni öğreniyorduk ikimiz,  yıl 97 ay baharın ilki,  kendimi sevdirmeyi bir borç bildim aslında,  yaş...', ARRAY['Türk Edebiyatı','Şiir','Şair Revolver']::text[], 8.5, '{"poet":"Şair Revolver","poet_slug":"sair-revolver","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bahar-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trenyolu', 'trenyolu-sair-revolver-p4uon', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu trenyolları bana hep çileyi çağrıştıracak bir ömür boyu bilesin, 

ne kavuşmayı seven bir kalbe, 

ne ayrılmayı hayatsal zorunluluklarla, 

ne ucuz ulaşım seçeneklerini, 

ne sallanan kocaman geniş koltukları, 

ne tuvalete saklanan mühendislerin öyküsü, 

ne karatren türküsü, 

bu trenyolları bana hep çileyi çağrıştıracak bir ömür boyu bilesin, 

annemin, ben küçükken açtığı yün çilesini...

karışık, dolambaçlı, gereksiz...', 'bu trenyolları bana hep çileyi çağrıştıracak bir ömür boyu bilesin,  ne kavuşmayı seven bir kalbe,  ne ayrılmayı hayatsal zorunluluklarla,  ...', ARRAY['Türk Edebiyatı','Şiir','Şair Revolver']::text[], 8.5, '{"poet":"Şair Revolver","poet_slug":"sair-revolver","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/trenyolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-sair-revolver-4pey3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'güneşin çocuklarıydık hepimiz

umut, inanç, istek ve arzıu dolu.

Davalar sahibi hakimlerdik, 

Eşitlik, Özgürlük, Hak dolu.

Aşkın insanlarıydık, insanlara aşık, 

Menfaate, bencilliği, kibire savaş açmış.

Törpülendik...

Baskılar acılar, yalanlar biledi

umutsuzluk törpüsü hepsini yendi.

Ezildik kendimizin altında, 

çabaladıkça ağırlaştık, dahada yandı canımız.

Eğitimli insanlardık, bilgili, akıllı

aklını kullanan, bilgisini paylaşan.

Doğrularımız vardı hepimizin, 

ilerici yollarda ilerici gençlerdik, 

kefenlere soktular, ama gömemediler.

Senle buluşacağız bunu bilesin.

Devasa gücümüz gün gelip yırttığında o kalın kumaşı, 

en derin dostlukların oluşturacağı, 

dökülen molozların dolduramayacağı, 

o engin sular bizi elbet ağırlayacak, 

biz tonlarca ağırlığımızın altında böcekleri ezerken...', 'güneşin çocuklarıydık hepimiz umut, inanç, istek ve arzıu dolu. Davalar sahibi hakimlerdik,  Eşitlik, Özgürlük, Hak dolu. Aşkın insanlarıydı...', ARRAY['Türk Edebiyatı','Şiir','Şair Revolver']::text[], 8.5, '{"poet":"Şair Revolver","poet_slug":"sair-revolver","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gunes-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susam Sokağı', 'susam-sokagi-sair-revolver-mjw57', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'susam sokağı çocukluklardan geçen 

gevrek insanlardık

sevgilerde mantık arayan akılsız çömezler...

içimizdeki depremlerden sığındığımız, 

prefabrik sınıflarda yetişen mühendislerdik.

yüzüne bakılmayacak insanlarla kurulan 

yüzgöz dostlukların zavallı kahramanları...

sancılarımız ortak sanma sakın, 

ne benim kadar dolar bir insan 21''inde 

ne bu derece içi boşalabilir hayat dolu bir gencin.

sancılarımız ortak sanma sakın, 

kaç gece baktın sen pütürlü tavana saatlerce? 

kaç insanı sevdin hakedilmediğini bile bile? 

sancılarımız ortak sanma sakın, 

ben fikir kırıntıları ararken çizilmiş satır aralarında

sen dövecek adam aradın, yada maça ası 13 kağıt arasında, 

sancılarımız ortak değil...', 'susam sokağı çocukluklardan geçen  gevrek insanlardık sevgilerde mantık arayan akılsız çömezler... içimizdeki depremlerden sığındığımız,  pr...', ARRAY['Türk Edebiyatı','Şiir','Şair Revolver']::text[], 8.5, '{"poet":"Şair Revolver","poet_slug":"sair-revolver","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/susam-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-sair-revolver-vln9t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne güzeldin aylardır sen

neredeyse ben bile inanacaktım aynadaki gülen suratın gerçekliğine

ama sevinmedim değil bu oyunun bitmesine

sevindim tekrar hüzünbaz adamı görmekten karşımda

yanlış anlama sakın

biliyorum hiçbirşeyi anlamıyorsun aylardır

bir hamleni bekleyen aşık gözler çekmedi değilmi seni

aylar sonra açıp baktın değilmi  senin için birşey yazmışmı diye yine o sayfayı

beter ol demeyeceğim bu kez

çünkü gerçekten olmuşsun ne güzel...

ama yinede

hoşgeldin...', 'ne güzeldin aylardır sen neredeyse ben bile inanacaktım aynadaki gülen suratın gerçekliğine ama sevinmedim değil bu oyunun bitmesine sevindi...', ARRAY['Türk Edebiyatı','Şiir','Şair Revolver']::text[], 8.5, '{"poet":"Şair Revolver","poet_slug":"sair-revolver","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hosgeldin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Vakit', 'uc-vakit-sair-revolver-ps4iv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'senden intikam almak istiyorum aylardır.

kinimi kusmak istiyorum lavabolar yerine suratına...

korkuyorum ewet birdaha sevemem diye, 

titriyor ellerim hala taze aşık gibi, 

ellerini tutarcasına

bıktım kendimi kandırmaya çalışmaktan, 

bıktım bu şehirden

bıktım bıkmaya alışmışlıktan...

istemiyorum üzerime titreyen insanları

istemiyorum bana aşık olmalarını

sevmiyorum ben bana aşık hiçkimseyi

lanet olsunki kötü alıştırmış beni 

acı çekerek sevmeye, 

mutlu olamıyacağım galiba ben 3 vakte kadar

falcıyımı öldürsem senimi karar vermedim henüz

allahtan belanımı dilesem, telefon açıp sevgimi bilmiyorum.

sen bir başdönmesi sonucu unutsanda tüm telefonlarımı

benim başım hiç durmdadan dönsede yarım yıldır

mıh gibi aklımda hepsi

ve adresini hala gözüm kapalı buluyorum her gece rüyamda

ne halt ettiğini merak etmiyorum eskinin aksina

ne halt edeceğiin ise umurumda değil

seni öldürmek istiyorum anlıyormusun yeşilköylü kadın

seni öldürmek istiyorum 

ve terkar diriltip benim olmanı istiyorum', 'senden intikam almak istiyorum aylardır. kinimi kusmak istiyorum lavabolar yerine suratına... korkuyorum ewet birdaha sevemem diye,  titriyo...', ARRAY['Türk Edebiyatı','Şiir','Şair Revolver']::text[], 8.5, '{"poet":"Şair Revolver","poet_slug":"sair-revolver","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uc-vakit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet', 'lanet-sair-revolver-utybc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kadınalar okuma yazma bilmez sevişirken! 

Tek gecelik iğrenç sevişmelerin sonunda, 

Birer imza atıp giderken erkekler vücutlarına

Onların tek gördüğü üzerlerindeki parmak izleridir, 

bir buhulu sabahın kıyısında...', 'Kadınalar okuma yazma bilmez sevişirken!  Tek gecelik iğrenç sevişmelerin sonunda,  Birer imza atıp giderken erkekler vücutlarına Onların te...', ARRAY['Türk Edebiyatı','Şiir','Şair Revolver']::text[], 8.5, '{"poet":"Şair Revolver","poet_slug":"sair-revolver","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/lanet-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Daha Erken', 'vakit-daha-erken-tolga-baydar-5564i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son bestesini çalarken yanıbaşımdaki kemancı

Doktorun yerinde son şarabımı yudumlarken

Ben şarap oluyorum meşe fıçılarda

Sanki ben yıllanıyorum mahzenlerde

Şişelere doldurulup üzerime mantar vuruluyor

Kim bilir kaç sofrayı süslüyorum beyaz

Ya da bir aşk ilanında oluyorum kırmızı

Son bestesini çalarken yanıbaşımdaki kemancı

Doktorun yerinde son şarabımı yudumlarken

Hayalimdekiler de beni yudumluyor

Garson kapatacığını söylerken usulca kulağıma

Boş ver diyorum, ben içeyim, beni içsinler

Son şarabımı yudumlarken

Diyorum ki; Vakit daha erken', 'Son bestesini çalarken yanıbaşımdaki kemancı Doktorun yerinde son şarabımı yudumlarken Ben şarap oluyorum meşe fıçılarda Sanki ben yıllanıyo...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/vakit-daha-erken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerim', 'hayallerim-tolga-baydar-o2jtx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonbahar sarısıydı yollara dökülen

Tane tane sayılabiliyordu

Aynen gözyaşlarım gibi

Ama avuçladığın an ufalanıyordu

Gel gözyaşlarımı da avuçlasana

Ufalanmayacaktır merak etme

Korkma, avuçladıkca avuçla

Sana doğru akan bir ırmak olacak

Ve o ırmakta hayallerim yüzecek

Tıpkı rüyalarımda yüzdüğü gibi', 'Sonbahar sarısıydı yollara dökülen Tane tane sayılabiliyordu Aynen gözyaşlarım gibi Ama avuçladığın an ufalanıyordu Gel gözyaşlarımı da avuç...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayallerim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiş', 'gidis-umit-kalender-fewnw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben uzayan gecelerde 

Uzayan şiirleri sana yazıyorum

Ama sen ne yazdıklarımı okuyorsun

Ne de yazlık sinemalara benle koşuyorsun

Saatlik ümitlerimi çaldın 

Ve planlarımı kabuğu soyulmuş bir elmaya benzettin

Korkar oldum yaşamaktan 

Ve sana sarılmaktan 

İçimde düğümlenen bir şeylerim var

Hayat bir trendi çocukken bana

Ve ben trenin en son vagonuna bindim

Şimdi inme vakti 

Minik bir tornetle hüznümü dindirmeye

Yetecek zamanım kaldı 

Yollardaki  izlerden bulmak istersen beni

Bulamazsın tornetimin kanatları var artık...', 'Ben uzayan gecelerde  Uzayan şiirleri sana yazıyorum Ama sen ne yazdıklarımı okuyorsun Ne de yazlık sinemalara benle koşuyorsun Saatlik ümit...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kalender']::text[], 8.5, '{"poet":"Ümit Kalender","poet_slug":"umit-kalender","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Bebek', 'koca-bebek-umit-kalender-wtd6o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle hiçbir şey imkansız değil bana

Çocukluk yıllarımı getiriyorsun bana

Kırmızı başlıklı kızın sepetinde

Uçan halılara inanırdım çocukken

Bir de öldükten sonra uyanacağıma

Ne uçan halı imkansız senle

Ne de ölüp seni bu dünyada bırakmak mümkün

Senin saflığın için uçar halılar 

Senin için dirilir ölen senin elin tuttuysa onu

Ellerimi tut aşkım 

Beni tut ve öp 

Seni çok özlüyorum bir tanem 

Uçan bir halıyla gelmek istiyorum sana

Çocukken ay dedenin benimle gelmesi gibi

Gece serinliğinde semadan sessizce 

Kollarını aç ve dudaklarını hazırla bebeğim

Koca bebeğin geliyor....', 'Seninle hiçbir şey imkansız değil bana Çocukluk yıllarımı getiriyorsun bana Kırmızı başlıklı kızın sepetinde Uçan halılara inanırdım çocukke...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kalender']::text[], 8.5, '{"poet":"Ümit Kalender","poet_slug":"umit-kalender","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/koca-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durakta, Son Yolcu', 'son-durakta-son-yolcu-okhan-ucar-gbl12', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok kötüyüm, 

Ne kadar yalnız bir yaşama sahip olduğumu anladım

Bir kez daha...

Son kez olsa keşke

Son bir kez uyusamda uyanmasam

Ey rüyaların vazgeçilmez başlangıcı

Ey ölümün o bilinmez mahmurluğu

Ve sen yaşam denilen

Nalların toprakta bıraktığı 

Uğursuz nar çiçeği kokusunda tımarsız ve umarsız büyüsü

Kapı ağzında üşümüş bekleyen kekre şurup tadında

Kaderden bozma hayat uydurması

Beklediğim ıssız ve ürkek vazgeçişlerin 

Sade durak çatı sundurmaları

Ben burda etten kemikten bekleyip

Sıkıldım artık tespih niyetine her günün sabahını 

tek tek çekmekten

Hani nerde o serin şafak kokan huzur

Hani şimdi nerde o

Dik durmak pahasına her cefasını özümsediğim gurur

Elma dedim, hadi şimdi

Armut sadece ayıların sözlüğünde anlamını bulur', 'Çok kötüyüm,  Ne kadar yalnız bir yaşama sahip olduğumu anladım Bir kez daha... Son kez olsa keşke Son bir kez uyusamda uyanmasam Ey rüyalar...', ARRAY['Türk Edebiyatı','Şiir','Okhan Uçar']::text[], 8.5, '{"poet":"Okhan Uçar","poet_slug":"okhan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/son-durakta-son-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yolcunun Ardından', 'bir-yolcunun-ardindan-ozgen-balci-qvhg8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her yolculuk biraz 

olmamis cagla kokar, 

birazda citlembik tadinda ozlem

yuzumu onarmak icin 

istanbula goturemezsin 

istesende goturemezsin degilmi sibel? 

ama yalniz, 

kitaplarin arka  bahcelerinde 

siir dagitan cocuklara soyle 

dikkat etsinler kendilerine 

bizim oralarda cunku 

arakadan vururlar cocuklari', 'her yolculuk biraz  olmamis cagla kokar,  birazda citlembik tadinda ozlem yuzumu onarmak icin  istanbula goturemezsin  istesende goturemezsi...', ARRAY['Türk Edebiyatı','Şiir','Özgen Balcı']::text[], 8.5, '{"poet":"Özgen Balcı","poet_slug":"ozgen-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-yolcunun-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İnsanlar İçin', 'biz-i-nsanlar-i-cin-kemal-baral-bt660', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutlu bir dünya arıyoruz

Tüm insanların güldüğü

Göz yaşlarının kuruduğu bir dünya

Bir yaşam peşindeyiz

Düşlerimizle süslediğimiz gibi

Arzuladığımızca güzel.

Oysa çirkin yüzlü gerçekler ile

Değeri kalmayan yaşamları bile yaşıyoruz

Arzularımızla kıvranarak, 

Ölmek isteyerek yaşıyoruz çoğu kez, 

O kocaman ödevi yaparak

Aradıklarımızla, yitirdiklerimizle

Bulamadıklarımızla ezilerek, 

Ümitlere güvenerek, düşlerle avunarak.

Saman çöpleri gibi savruluyoruz 

Delicesine bir git gelde

Zaman sırtımıza yük, ümitler avuntu, 

Gerçekler yine gerçek, 

Varlıklar yokluklar olağan

Yaşıyoruz işte

O, istemeyene dek.', 'Mutlu bir dünya arıyoruz Tüm insanların güldüğü Göz yaşlarının kuruduğu bir dünya Bir yaşam peşindeyiz Düşlerimizle süslediğimiz gibi Arzula...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/biz-insanlar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Olmak', 'ben-olmak-kemal-baral-9gx89', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pembe renkli akşamlar

Cıvıl cıvıl sokaklarda

Acısını çıkarıyorum

Yalnız akşamların.

Tek ampullü odamda

Kristal avizemi düşünüyorum

Hasır koltuğumda, ipek kanepemi, 

Ve, ampulümü hasırımı seviyorum.

Somut değer yargılarına gülüyorum

Mutluluğu ölçmek istedikleri için.

Bana yeten havayı soluyorum, isteye isteye

Aradığıma ulaştığımca, doya doya.', 'Pembe renkli akşamlar Cıvıl cıvıl sokaklarda Acısını çıkarıyorum Yalnız akşamların. Tek ampullü odamda Kristal avizemi düşünüyorum Hasır kol...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzen Üstüne (1)', 'duzen-ustune-1-kemal-baral-zu3ir', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimizde var içimizde yaratmak

Kurallar yaratmak

Tutsağı olmak için.

Yenilikler yaratmak

Eskitmek için.

Yoksulluk yaratmak

Ezilmek için.

Varlık yaratmak 

Yitirmek için.

Kavgalar yaratmak

Ölmek için.

Yaratmak bizim içimizde

Saçmalıklar yaratıyoruz artık

Kendi yarattıklarımızı yıkmak için.', 'İçimizde var içimizde yaratmak Kurallar yaratmak Tutsağı olmak için. Yenilikler yaratmak Eskitmek için. Yoksulluk yaratmak Ezilmek için. Var...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/duzen-ustune-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzen Üstüne (2)', 'duzen-ustune-2-kemal-baral-ekkbq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erdemli kişilere seslenenler

Ezildiğinden dem vuranlar

Size soruyorum

Değer misiniz siz erdemli kişilere

Biliyormusunuz ezilmişliğiniz neden.

Kaderine küfredenler

Size soruyorum

Kimin suçu alınyazınız

Biliyormusunuz ki en kötü siz değilsiniz.

Silah çekenler düzene

Kimi vurduğunuzu biliyormusunuz

Yoksa satranç tahtasında piyon mu oluyorsunuz

Her şeyi rakı sofrasında çözenler

Bol küfürlü yakınmalarınızda

Haklımısınız gerçekten

Eğer inanıyorsanız doğruluğuna

Yakınmalarınızın, isyanlarınızın

İnanıyorsanız üstüne gittiğinizin haksızlığına

Ben de sizleyim.

İnançsızlar, koyunlar, körler

Size ise ancak 

bir değnek verebilirim.', 'Erdemli kişilere seslenenler Ezildiğinden dem vuranlar Size soruyorum Değer misiniz siz erdemli kişilere Biliyormusunuz ezilmişliğiniz neden...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/duzen-ustune-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzen Üstüne (3)', 'duzen-ustune-3-kemal-baral-fdzhr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben doktorum

Belediye reisliği tam bana göre.

Ben avukatım

Mesleğimden kazanamam, meclisten kazanırım.

Ben mühendisim

En iyi işletmeci benim.

Ben iktisatçıyım

Ne olduğumu bile bilmezler.

Ben öğrenciyim

Kendime karşı savaşırım.

Ben ayyaşım

Dünyayı baan sorsunlar.

Ben memurum

Bir yılda bir aylık iş yaparım.

Ben fakirim

Beş çocuğum var Allah''ın verdiği.

Ben zenginim

Yalnız kendime faydam.

Belli dostlarım belli

Sizin yarattıklarınızla dolu

Bir ülkede yaşıyoruz.', 'Ben doktorum Belediye reisliği tam bana göre. Ben avukatım Mesleğimden kazanamam, meclisten kazanırım. Ben mühendisim En iyi işletmeci benim...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/duzen-ustune-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortak Yanımız', 'ortak-yanimiz-kemal-baral-a4jmb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söğüt dalları gibi sallanıyoruz

Tutkularımızın meltemi estikce.

Kavaklar gibi dik başımızla

Göremiyoruz kökümüzü.

Hep ulu idik sanıyoruz

Tepe dallarımıza baktıkça, 

Saymıyoruz gövdemizi

Nedense bilmek istemiyoruz

Bizi tutanı ve yaşatanı.

Kavaklar gibi dik başımızla

Görmüyoruz kökümüzü

Hep ulu idik sanıyoruz.', 'Söğüt dalları gibi sallanıyoruz Tutkularımızın meltemi estikce. Kavaklar gibi dik başımızla Göremiyoruz kökümüzü. Hep ulu idik sanıyoruz Tep...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ortak-yanimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarcı', 'mezarci-kemal-baral-w2u80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Salla kazmayı mezarcı

Yeni konuklar geliyor.

Vur mezarcı vur

Hem toprağa, hem de kadere.

Yürü mezarcı elinde kürek

Park de burası, mezarlık değil

Taşlar taş değil insan de

Zor da gelse küre aldırmadan.

Senin kaldırdığın her karış toprak

Sofrandaki ekmek

Kaderin bu

İnsanların yittiği yerden sen kazanacaksın

Göz yaşları toprağa aktıkça

Kasende çorba bulacaksın.

Dayan mezarcı, zor da gelse

Bu senin geçim kapın, alın yazın.', 'Salla kazmayı mezarcı Yeni konuklar geliyor. Vur mezarcı vur Hem toprağa, hem de kadere. Yürü mezarcı elinde kürek Park de burası, mezarlık ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mezarci-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simitçi Arkadaş', 'simitci-arkadas-kemal-baral-1eimz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu soğukta kim simit alır

Be simitçi.

Bak ellerin donmuş

Isın biraz ısın

Canın daha değerli simitlerden.

Üzülme hiç yoksul dostum

Bu Tanrıca bölünme işte

Kimine bir, kimine bin.

Sen, ben ondan iyimi bileceğiz

Aldırma arkadaş

Alın yazısı sabit kalemle yazılmış

Ne yapsan çıkmaz

Üç simitle mi değiştireceksin onu

Aklın sıra.

Dinle beni simitçi dinle

Git de ısın biraz.', 'Şu soğukta kim simit alır Be simitçi. Bak ellerin donmuş Isın biraz ısın Canın daha değerli simitlerden. Üzülme hiç yoksul dostum Bu Tanrıca...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/simitci-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zamandı?', 'ne-zamandi-kemal-baral-rtmab', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Buğulu camların ardından görüyorum seniAnıların içinde bir sarı gül gibi, 

Sarı zambak gibi.

Buğulu camlar içime devrildiler

Ardında güzel karanfiller

İçimde kalmış yabani ot gibi

Beni dalayan anılar.

Buğulu camların ardından

İnce keman sesi

Elinde karanfillerin

Yanımdasın sen

Karşımda bütün esmerliğinlesin.

Buğulu camlar dışında

Ben kral, yenik kral

Sen, , nce keman sesi, kırmızı karanfiller

Akortsuz düzenim

Ve her şeyi gölgeleyen

Buğulu camlar ardında ben varım.', 'Buğulu camların ardından görüyorum seniAnıların içinde bir sarı gül gibi,  Sarı zambak gibi. Buğulu camlar içime devrildiler Ardında güzel k...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-zamandi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Gezintisi', 'aksam-gezintisi-kemal-baral-c7kcn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazı akşam üstleri iki elim cebimde, 

Kırık dökük yürürüm yol boyunca

Ezilmişlik çöker içime iyiden iyiye.

İnsanlar gelir geçer yanımdan

Gözlerinin içine bakarım, bakabildiğimce

Hepsinde ayrı bir kırıklık sezerim.

Işıklar pırıl pırıldır vitrinlerde

Olmayan paramla alırım her beğendiğimi

Olmayan yerlerde kullanırım, düşüncemde.

Kadınlar beğenirim, 

Konuşurum onlarla yol boyunca

Onlar olmadan düşümde.

Sonra yol biter, düşler yıkılır, 

Yalnızlık gerçeği çöker üstüme, 

Bulutlardan inmiş gibi olurum yere.

Başım döner şehir denilen karınca yuvasında

Farlar canavar gözü, yol sonsuz gibi gelir, 

Yalnızlık büsbütün biner sırtıma.

Ve o zaman, gözlerimi kapatırım, 

Mırıldanırım içimden

''Evimize dönelim''', 'Bazı akşam üstleri iki elim cebimde,  Kırık dökük yürürüm yol boyunca Ezilmişlik çöker içime iyiden iyiye. İnsanlar gelir geçer yanımdan Göz...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aksam-gezintisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahşap Otel', 'ahsap-otel-kemal-baral-5ym9u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlerken geçmişteki güzelliğini

Bakıp da harabolmuş yapına

Ağlayışın mı gizli

Merdivenlerinin gıcırtısında.

Oysa biliyormusun ki ahşap otel

Hala titrer yaşlı ve genç nice kalpler

Kavuşmak için tekrar sana

Başlayarak bir kıştan, ta öbür yaza.

Farkında değil misin yoksa

Senin harap cephenden başka, 

Yok böyle gören bir ikinci yer daha

İki ezeli  sevgilinin her grup vakti buluşmasını

Denizin serin kollarıyla güneşi sevgiyle kucaklamasını', 'Özlerken geçmişteki güzelliğini Bakıp da harabolmuş yapına Ağlayışın mı gizli Merdivenlerinin gıcırtısında. Oysa biliyormusun ki ahşap otel ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ahsap-otel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşsizliğin Yıl Dönümü', 'i-ssizligin-yil-donumu-kemal-baral-diul9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayli zamandır kendi kendime

Sakin ol oğlum, 

Mantıklı ol oğlum, 

Sabret oğlum, 

Ne bekliyorsun daha oğlum, 

Birşeyler yapsana oğlum, 

Defterin dürüldü oğlum, 

Ölsene be oğlum.

Derken; 

Oğlum bir yaş daha büyüdü

Ve ben hala ölemedim.', 'Hayli zamandır kendi kendime Sakin ol oğlum,  Mantıklı ol oğlum,  Sabret oğlum,  Ne bekliyorsun daha oğlum,  Birşeyler yapsana oğlum,  Defte...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/issizligin-yil-donumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anlık Düşünce', 'bir-anlik-dusunce-kemal-baral-q8azi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nisan bin dokuz yüz seksen beş

Üstümde partal bir giysi

Teknenin kamarasında yatmış

Gözlerim tavana dikili.

Direklerin orkestrasını dinliyorum

Rüzgarın senfonisini çalıyorlar, 

Poyrazın şefliğinde bir yorum, 

Enstrümanlar; direkler, mandarlar, çarmıklar.

Geçen yıl aynı günleri düşünüyorum

Gönülde ne hoş çırpıntılar vardı, 

Başarı yolları bitmez sanıyordum

Her halde bir rüya olmalı.

Hani nerede o sevdiğim

Geceler boyu aşk yeminleri eden

Şimdi uzaklarda, bak özlediğim.

İşte bunlar beni kahreden.

Bürolar, insanlar, imzalar sanırdım sıkıldığım

İçimde beyaz bir köpük olma isteği vardı denizde

Sanırdım bir tek zamandı aradığım

Şimdi zaman denizinde bir köpüğüm de ne var elimde? 

Aylardır hep aynı açmazlar

Güneşin doğuşu sıkıntı batışı özlediğim, 

Dost görünenler bir gün bile kapıyı çalmazlar

Kaldı bir tek Allah güvendiğim.', 'Nisan bin dokuz yüz seksen beş Üstümde partal bir giysi Teknenin kamarasında yatmış Gözlerim tavana dikili. Direklerin orkestrasını dinliyor...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-anlik-dusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Kız', 'i-yi-kiz-kemal-baral-84mii', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İyi kızdın sen

Akıllıydın ve de çirkin.

Böyle söyledikçe ben, 

Karım sevgilim sandı seni.

Ve o zaman düşündüm ilk kez

Ya öyle olsaydı, 

Ne derdim acaba?', 'İyi kızdın sen Akıllıydın ve de çirkin. Böyle söyledikçe ben,  Karım sevgilim sandı seni. Ve o zaman düşündüm ilk kez Ya öyle olsaydı,  Ne d...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/iyi-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurda Gezinti', 'yagmurda-gezinti-kemal-baral-k80t6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kıskançlık kaplıyor içimi

Işıl ışıl sokaklarda yürürken

Yoksulluğuma kızıyorum

Ve de sensizliğime.

Bir şeyler arar gibiyim

Neyi aradığımı bilmeden

Seni mi arıyorum

Yoksa kendimi mi.

Düşman değilim ki mutluluğa

Küfür ediyorum mutlu insanlara, 

Neye kızdığımı bilmeden

Yoksa sana mı bu küfürler

Bilmiyorum.

Yağmur daha çok yağsın istiyorum

Alsın götürsün herşeyi senden kalan

Islatsın isterse beni iliklerime kadar

Yeter ki, yıkasın senİn izlerini benden.

Kimseler kalmadı artık sokaklarda

Yalnızlık gerçeğini yavaş yavaş kavrıyorum

Yürümek istemiyorum artık

Yorgun hiç değilim, yolun sonuna da gelmedim

Ama yürümek istemiyorum.

Bilirsin ben akıllı insanımdır

İşte bak, Evime dönüyorum

Seni, senin düşlerini 

Islak sokaklarda bırakıp

Evime dönüyorum.', 'Kıskançlık kaplıyor içimi Işıl ışıl sokaklarda yürürken Yoksulluğuma kızıyorum Ve de sensizliğime. Bir şeyler arar gibiyim Neyi aradığımı bi...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yagmurda-gezinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçma Arzu', 'sacma-arzu-kemal-baral-67rpl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurlu bir gün olsun

Paltom sırtımda, şemsiyesiz.

Saçlarımdan sular aksın

Saatler geçmek bilmesin

Seni beklerken.

Sonra uzaktan

Beyaz pardesünle

Gel yanıma, 

Şemsiyeni tut, 

Koluma gir gidelim.

Üzül biraz yaptığına

Zarar yok geldin ya yeter

Diyeyim...', 'Yağmurlu bir gün olsun Paltom sırtımda, şemsiyesiz. Saçlarımdan sular aksın Saatler geçmek bilmesin Seni beklerken. Sonra uzaktan Beyaz pard...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sacma-arzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ağlama', 'sen-aglama-ergun-yildirim-x244o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen ağlama

Gözyaşların kirletmesin

yüreğini; berak temiz duyguların

sakla birgün nasıl olsa döneceğim sana

sen ağlama; 

Irmaklar, Nehirler, Denizler ağlasın

durmaksızın, onların bitmeyen gözyaşaları

kirletmesin yeryüzün

düşünme sen yalnız kaldım diye; 

hep içinde ve yanındayın senin

senin için içim ağlıyor sesiz sakin

bıraksam yüreğim kopacak 

sesizce ağladım sen ağladın diye

sen ağlam yağan yağmurlarr benim göz yaşım

sen ağlama;', 'sen ağlama Gözyaşların kirletmesin yüreğini; berak temiz duyguların sakla birgün nasıl olsa döneceğim sana sen ağlama;  Irmaklar, Nehirler, ...', ARRAY['Türk Edebiyatı','Şiir','Ergün Yıldırım']::text[], 8.5, '{"poet":"Ergün Yıldırım","poet_slug":"ergun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-aglama-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Protesto', 'protesto-kemal-baral-4jbop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiirlerimi ver geri

Üç damla gözyaşına yazdığım sayfalarca şiiri.

Nasıl olsa aldığın başka hiçbir şeyi

Veremezsin geri.

Harcadığım geleceğimi, yitirdiğim ümitleri

Veremezsin ki.

Ve benim kaldırım kahvelerinde motorlaşan ellerim

Bir daha yazamaz öylesine ne İzmir''i, ne seni, ne de beni.

Uçup giden mutluluğu, kaybedilen geleceği istemiyorum ki, 

Sadece şiirlerimi ver geri.', 'Şiirlerimi ver geri Üç damla gözyaşına yazdığım sayfalarca şiiri. Nasıl olsa aldığın başka hiçbir şeyi Veremezsin geri. Harcadığım geleceğim...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/protesto-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kıyısı', 'deniz-kiyisi-kemal-baral-d58mv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deniz kıyısı benden bıktı, ben ondan bıkmadım

Tek düşünmediğim yer orası ölümü, 

Çaresizliğe boş verebildiğim yer orası.

Martıların çığlığında, içimin çığlıklarını

Susturabildiğim yer yine orası.', 'Deniz kıyısı benden bıktı, ben ondan bıkmadım Tek düşünmediğim yer orası ölümü,  Çaresizliğe boş verebildiğim yer orası. Martıların çığlığın...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deniz-kiyisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heybelide Bir Gün', 'heybelide-bir-gun-kemal-baral-jp2h9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün yine gayesizce yürüken

Duydum birden geçerken önünden

O küçük çam sanki bana sordu

Hani nerde o, yok mu? 

Daldım birden geçmişin mutlu gününe

Kalbim doldu buruk bir hüzünle, 

Nerede dedim, ah o nerede? 

Küçük Çam biliyorsan sen bana söyle.

Karışmıştı yeşille mavi, o güzel adada

Göz kırpan güneş, zümrüt çamlar ve billur sularda.

O zaman görmüştü demek, küçük çam bizi

Mutluluğun kollarında sevinçle birleştiğimizi.

Dalarken ağaçlar gecenin uykusuna, 

Ninni söylüyordu rüzgar yapraklar arasında, 

Mehtap okşamıştı ışığı ile saçlarımızı, 

Görmüştü sadece yıldızlar bir tek varlığımızı.

Dalmıştım uyanmak istemediğim rüyaya

Canlanırken gözümde o eşsiz hatıra, 

Küçük çam tekrar fısıldadı

Seni üzmek için sormadımdı.

O zaman uyandım geçmişin hülyasından

Yürüdüm yolumdan, zorla ama ağlamadan

Dalların arasından göz kırparken deniz

Anladım ki biz halen bizdeyiz.', 'Bu gün yine gayesizce yürüken Duydum birden geçerken önünden O küçük çam sanki bana sordu Hani nerde o, yok mu?  Daldım birden geçmişin mutl...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/heybelide-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin Çiçeği', 'kalbimin-cicegi-omer-gokhan-50ola', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duygu nedir bilir

Ona değer verirmisin

Sen benim meleğimsin

Kalbimin çiçeğisin

Sen benim içimdeki ateşimsin

Gözümün önünden gitmezsin

Sen benim meleğimsin

Kalbimin çiçeğisin

Aklımdan hiç gitmezsin

Gözümden düşmezsin

Sen benim meleğimsin

Kalbimin çiçeğisin', 'Duygu nedir bilir Ona değer verirmisin Sen benim meleğimsin Kalbimin çiçeğisin Sen benim içimdeki ateşimsin Gözümün önünden gitmezsin Sen be...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gökhan']::text[], 8.5, '{"poet":"Ömer Gökhan","poet_slug":"omer-gokhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalbimin-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskançlık', 'kiskanclik-kemal-baral-jslbf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte yine ''gideceğim'' diyorsun

Bu kaçıncı firar? 

Sana ''kal'' derken biliyordum hep

Benden değil, kendinden idi kaçışın.

Ne ılık dudaklarını, ne de sıcacık bakışlarını

Göndermemiştim seninle o zaman.

Sen yokken bile yanımdaydın

Hiç gitmemiş kadar yakın.

Şimdi nasıl '' kal'' derim sana, 

Bu kez özlem rüzgarı seni götüren.

Hep bende kalanları bile alan

Hiç bir şey bırakmadan.

Biliyorum bu gidiş başk akollara, 

Biliyorum bu sefer kaçış benden.

Kahrolmayı yeni yeni öğrenirken

Sana ''kal'' diyemem.', 'İşte yine ''gideceğim'' diyorsun Bu kaçıncı firar?  Sana ''kal'' derken biliyordum hep Benden değil, kendinden idi kaçışın. Ne ılık dudaklarını,...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiskanclik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lüks Kadına', 'luks-kadina-kemal-baral-4jxab', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gece mavi bir Nisan gecesi

Ayın kaçıdır bilmem

Ne zamandır ki takvime yabancıyım

Her halde avare olduğumdan ebri.

Mehtap doğuyor karşıdan kocaman

Yukarılara Bostancı çatılarından

Parasızlıkmış, işsizlikmiş derken

Yaşamayı unutmuşuz anlaşılan.

Çekiliyor herşey bilmeyince güzeli

Yazı görmeden kış bile

İçimde dolu sofraların özlemi

Kadehler niyetine çayla yetinmek niye? 

Gelelim en kötüsüne, 

Mehtap derken, bahar derken, 

Ve parasızlık yakamdayken

Sen şimdi kimbilir kiminle?', 'Bu gece mavi bir Nisan gecesi Ayın kaçıdır bilmem Ne zamandır ki takvime yabancıyım Her halde avare olduğumdan ebri. Mehtap doğuyor karşıdan...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/luks-kadina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtınadan Önce', 'firtinadan-once-kemal-baral-erp65', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi ve nefret ikizmiş meğer, 

Anlaman için öptüğün boynu sıkmak istemen yeter; 

Seni çağıran yüzler bir başka sıkıyorsa yüreğini

Parçalamak içinse koşup gitme arzusu

İkizlerden biri öldü, kalanın adı nefrettir.

İşte yine hayalin hep Gözümün önünde, 

Artık oymak isteği ile görüyorum gözlerini

Damlasına can verebileceğim kanını

Şarap niyetine içmek zevk olmalı.', 'Sevgi ve nefret ikizmiş meğer,  Anlaman için öptüğün boynu sıkmak istemen yeter;  Seni çağıran yüzler bir başka sıkıyorsa yüreğini Parçalama...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/firtinadan-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemek', 'ozlemek-kemal-baral-irll3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen bilmezsin güzelim

Ne kadar zor, onun yanında seni özlemek

Ve ne zor senin yanında da onu.

Bizler üçgene sıkışmış dar açıların sıkıntısında

Hep üzgün, hep çaresiz.

Bilmezsin güzelim

Serin yağmurlu akşamlarda sıcacık evden kaçmak ihtiyacını

Sahilin yosun kokularında, adanın titrek ışıklarına bakıp

Seni özlemek, ne demek! 

Bilirsin sen de güzelim

Üstümüze güneş doğan sabahların güzelliğini

Birbirimizin kollarında iken mutlu

Sanki bir martının kanatlarında yükselmeyi.

Fakat, yine de bilemezsin ki güzelim

Her sarıştaki pişmanlığı, her dönüşteki garipliği

İç çekişmelerin kıskacında çırpınırken

O kahredici özlemi yeniden duymayı.

Bak, işte sensiz bir gece daha

İhtimal senin için de bensiz, 

Yıldızsız bir gökyüzü gibi

Yarına ümitsiz.', 'Sen bilmezsin güzelim Ne kadar zor, onun yanında seni özlemek Ve ne zor senin yanında da onu. Bizler üçgene sıkışmış dar açıların sıkıntısın...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozlemek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Hikayesi', 'bir-ask-hikayesi-kemal-baral-2mng5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir uysal gecenin ortasında

Üstümüzde göz kırpan yıldızlar

Pırıl pırıldı samanyolu

Sıcaklığın dolduruken kollarımı.

Deniz en güzel şarkılarını mırıldanıyordu

Güneş sihirli elleriyle okşuyordu çıplaklığımızı, 

Sen almadığın tadlardan tadıyordun

Yalan mıydı? 

Saçların buğday başakları ile bütünleşmişti

Van Gogh''u  anımsıyordum sarı buğday tarlalarında

Gelincikler kadar kısa ömürlü olduğu

Anlaşılmıyordu ki sevginin.

Gecenin birinde, sanki çağırarak kaçmıştın benden

Geldiğimde ılık lezzeti vardı dudaklarında bekleyişin

Karanlıklar örtüyordu çıplaklığını, piyanonun tuşlarında Chopin

Dudaklarında ıslaklığı öpüşmenin

Solunumlar burun kanatlarında.

En güzel sabahlarını, en mavi gecelerini

Bizim için mi saklamıştı Ege.

Venüs ve Eros serin sularında kucaklaştılar körfezin

Bembeyaz çıplaklığımızda bizimle el ele.

Karadeniz kızgındı sana o  gece

Benim yandaşımdı ve senin kadar hırçın

Poyraz sarındığımız battaniyeleri aralayabilmişti

Dudaklarımızı kenetlerken bütün şiddeti ile.

Sirkeciye yağmur yağıyordu, paltom ağırlaşmış

Gecenin ortalık yerinde, son vapur çoktan kalkmış

Hayli yolum var, yoldaşım berduşlar, 

Üşümüyordum, sıcaklığı ile istasyondaki busenin.

Martılarla yarışıyorduk, yelken açmış denizde

Fırtına varmış, tekne dümensiz kalmış, kime ne

Ufuklar pembe idi rotamızda

O zaman bir boşluk yoktu ortamızda.

Neydi o kıskançlık denizindeki fırtınalar

Boşuna değil miydi bütün hırçınlıklar

Kimse yoktu ki beni paylaştığın

Seninle bütünleşmiştim, anlayamadın.

Sonunda kalabalıkta kaybettik birbirimizi

Bir itiş kakış ve sürükleyip götürdüler bizi

Ellerimiz mi eremedi, gücümüz mü kalmadı ne

Yakalayamadık bir daha nedense sevgimizi.

Ve şimdi sen içki kadehlerine teslim, kadehi uzatanlara

Ben kadehlerle dost bunları bildiğim için

Bilemezsin nasıl yanıyor içim.

Dinmez artık sızım, seni kollarıma alsam da.', 'Bir uysal gecenin ortasında Üstümüzde göz kırpan yıldızlar Pırıl pırıldı samanyolu Sıcaklığın dolduruken kollarımı. Deniz en güzel şarkıları...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bir-ask-hikayesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorumlar', 'yorumlar-kemal-baral-cqr6j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin saçlarını okşamak güzelim

Rüzgarların önünde koşuşan, dalga köpüklerinde

yol almak kadar güzel.

Senin kokunu duymak güzelim

Serin bahar günlerinde, yeni açan bademlerin

Kokusunu duymak kadar güzel.

Seni özlemek güzelim

Açık denizlerde bir kara parçası

Aramak kadar güzel.

Seni sorduğum zaman yıldızlara

Dinlemek hikayeni, 

Yosun kokularında sarhoş olmakla eş.

Sen uyanan tabiat gibisin

Bahar rüzgarları   gibi çarpıcı, özlenen.

Bilirsin böcekler de mutlu olur

Kelebekler ve kuşlar kadar.

O halde mutluluk

İkimizin de hakkı tabiat kadar.', 'Senin saçlarını okşamak güzelim Rüzgarların önünde koşuşan, dalga köpüklerinde yol almak kadar güzel. Senin kokunu duymak güzelim Serin baha...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yorumlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İskenderin Moteli', 'i-skenderin-moteli-kemal-baral-0n654', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Torbanın dalgaları

Okşarken kıyıları

Denizin kucakladığı palmiyenin gölgesinde

Kadın mahcup, 

Başını erkeğinin koluna yasladı.

En güzel sessizlik şarkısı o zaman başladı.

Rüzgar ve yapraklar dans ederken

Kadın, şen kahkahalarla neşeyi tattı.

Tam o sırada üç dinamit patladı

Üç koca balık daha haklandı

Bodrumun boş tablaları için hemen saklandı.', 'Torbanın dalgaları Okşarken kıyıları Denizin kucakladığı palmiyenin gölgesinde Kadın mahcup,  Başını erkeğinin koluna yasladı. En güzel sess...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iskenderin-moteli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz', 'guz-i-smail-karakus-ndyip', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sunduğun laleler

Çürüdü gönlümde birer birer.

Ve ıskaladı, 

Zamanın esrik değirmenleri,

Geçen günleri bir çağlayan hızıyla.

Ey güz daha da soğu! 

Dondur,

Şımarık hanendelerini beynimin.

Öldür onların benliklerini, 

Benimkinden hemen sonra.

Ve kışı çağır akabinde, 

Çabuk olsun seri cinayetlere.

İçimin kardanadamları 

Çoktan astılar kendilerini, 

Kışın geldiğini bilselerdi keşke.

Ey güz; 

Soldurduğun yaprakların ahı, 

Gözlerimde tutuşurken,

Sen misin, 

Masum ve ağlamaklı uğultular fısıldayan? 

Affetmem! 

Yaprakların ayini bitmeden, 

Ve ölülerini gömmeden boşluğa.

Ey güz! 

Gönlümü salıverdin, 

Kendi yalnızlığına.

Gel de bir laleden dinle,

Azrailsiz ölüm seanslarını. 

Ve başıboş cemrelere sor,

Ölen tüm aşklarını.

Sunduğun laleler

Çürüdü gönlümde birer birer.

Ve ıskaladı, 

Zamanın esrik değirmenleri,

Geçen günleri bir çağlayan hızıyla.', 'Sunduğun laleler Çürüdü gönlümde birer birer. Ve ıskaladı,  Zamanın esrik değirmenleri, Geçen günleri bir çağlayan hızıyla. Ey güz daha da s...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/guz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrum', 'bodrum-kemal-baral-hmcqm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bodrum, bodrum

İnsan selinde boğuldun

Sende seninle değil

Sevdiğimle oldum.

Kimbilir bu yıl yine neler doldurdun

Kaç yaşam, kaç defter, kaç karın

Seninle  kimse düşünmedi ne olacak yarın

Söyle, bunlardan mutlu mu oldun.

Seni değil  sevdiğimi yaşarsam

Denizin, kumun, esnafın güzel

Konu yalnız sen isen, biraz daha düzel.

Mutlu dönmek senden, o  herşeyden daha güzel.', 'Bodrum, bodrum İnsan selinde boğuldun Sende seninle değil Sevdiğimle oldum. Kimbilir bu yıl yine neler doldurdun Kaç yaşam, kaç defter, kaç ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Baral']::text[], 8.5, '{"poet":"Kemal Baral","poet_slug":"kemal-baral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bodrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaka', 'saka-sedat-demirkaya-v1zqe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yanlışlıkla bir yola gir

ne keşifler yaparsın ne buluşlar

paran olsun yeter ki

hata yapmadan öyle yol alırsın ki

aylardır yolunu gözlediğim her şey

aynı yumurtayı zorlar, sığmaz bir pabuca

anlarsın bütün sıcak tavaların

soğuk bir tava gibi göründüğünü uzaktan', 'yanlışlıkla bir yola gir ne keşifler yaparsın ne buluşlar paran olsun yeter ki hata yapmadan öyle yol alırsın ki aylardır yolunu gözlediğim ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Demirkaya']::text[], 8.5, '{"poet":"Sedat Demirkaya","poet_slug":"sedat-demirkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saka-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Mapustum', 'ben-mapustum-erol-altinsoy-ry52l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben mapustum 

mapustum şeytana küfretmekten

Oysa ben sevdalıydım

sevdalıydım katar kuşlara

Hücrelere atıldım prangalara bağlandım

Bir parlak gök taşını

sana getirdiğim bir tutam kurumuş otu

koynumda sakladım

ben yinede vermedim.

Mapustaydım

oysa ben, ben bir çoçuktum

Tanrılara baş kaldırdım

kutsal kitapları yaktım

Cehennemde yandım

kızgın dalgalarla boğuştum

bir namlunun seyrinde

çıkan kurşunla taıştım.

Ölmedim sana geldim

cocuksu korkularımıda yanımda getirdim

Ve sen ey Tanrıların yaveri

Şeytanca çırılçıplak sarıl boynuma

Ben mapustum, mapustum ben diyorum

Kanımı içtiğin gecelerde', 'Ben mapustum  mapustum şeytana küfretmekten Oysa ben sevdalıydım sevdalıydım katar kuşlara Hücrelere atıldım prangalara bağlandım Bir parlak...', ARRAY['Türk Edebiyatı','Şiir','Erol Altınsoy']::text[], 8.5, '{"poet":"Erol Altınsoy","poet_slug":"erol-altinsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ben-mapustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''na', 'o-na-i-smail-karakus-qsrny', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Emekli bir gülüştü

Ta uzaktan yolladığın.

Kutsal metinleri yıkayıp,

Ah''ları mı topladın yıllardır.

Sevgindeki, 

Anaç duyguları kilitle,

Ve sevda göynüğünden,

Savur tebessümlerini.

Uzat bir tutam elini

Ellerden kalan nasırlara.

Çiçek açsın 

Tayinler damgalarda.

Konuştur Tevrat rüzgarlarını

Ve sigaya çek

Mezmurları bir bir.

Suçla Yusuf ''u,

Affet Züleyha''yı

Sağ yanına, 

ölüm sun.

Miladı ödünç ver,

İsanın saçlarına.

Sahibine Hu gönder

Az da olsa yüreğinden.', 'Emekli bir gülüştü Ta uzaktan yolladığın. Kutsal metinleri yıkayıp, Ah''ları mı topladın yıllardır. Sevgindeki,  Anaç duyguları kilitle, Ve s...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/o-na-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatlak Dudaklarda Susuzluğum', 'catlak-dudaklarda-susuzlugum-fahrettin-ustun-ybwkg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmuru beklerken yaz sıcağında

toprak susuz, toprak çatlak, toprak aç...

ve susamışsa suyu sevgi gibi

seni beklemek gibi...

bir sevinç yağmur damlalarının ilklerinde, toprak çatlak dudak çatlak...

yagmurla gelen koku toprak kokusu en güzelinden...

sen yoksun, kokun yok elde hasretin tanımadan.

Susamışlığım sana toprak gibi...

dudaklarım çatlak dudaklarım susuz dudaklarım sensiz, dorukta yaşıyorsam duygularım dopdoluysa 

Yağmur öncesi yağmur bulutları gibi...

bil ki neler olur gizemlikler sonunda...

seni zirvelere taşırım

zirveler seni taşır

yağmurla ıslatırım dudaklarını

saçlarında yağmur kokusu hasret duyduğum

ve sen yağmurla gel sellerinde coşayım balık olayım', 'Yağmuru beklerken yaz sıcağında toprak susuz, toprak çatlak, toprak aç... ve susamışsa suyu sevgi gibi seni beklemek gibi... bir sevinç yağm...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Üstün']::text[], 8.5, '{"poet":"Fahrettin Üstün","poet_slug":"fahrettin-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/catlak-dudaklarda-susuzlugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garibin Ölümü', 'garibin-olumu-fahrettin-ozdemir-va3br', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kağıt parçasıydı aşkın, 

Üzerini hergün göznuruyla, 

Nakış nakış işlediği

Buruşturup atamadı.

Atsaydı yaşayabilirdi belki, 

Ama ölmeyi yeğledi garip.', 'Bir kağıt parçasıydı aşkın,  Üzerini hergün göznuruyla,  Nakış nakış işlediği Buruşturup atamadı. Atsaydı yaşayabilirdi belki,  Ama ölmeyi y...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Özdemir']::text[], 8.5, '{"poet":"Fahrettin Özdemir","poet_slug":"fahrettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/garibin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ki Yükselesin', 'ki-yukselesin-zeki-ergin-4ibd2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '___emel budak için-

ey çocuk

biliyor musun

sen bu gün

ilk yaz gülümsemenle

yarınların umudusun

sen

sen olmak istersen eğer

özvarlığınla büyümelisin

ki yükselesin

yarın 

üstüne bir karabasan gibi inecektir

acımasız

yadsımayacaksın sen bunları

çünkü bileceksin herşeyi

18 yaşına girmeden

bileceksin 

aslanın ağzında olduğunu 

ekmeğin  ve mutluluğun

ve işte o zaman haykıracaksın

haykıracaksın

yaşamak için doğduğunu

ve de insanların kardeş olduğunu

_emel 10temmuz1974 sayı:4197', '___emel budak için- ey çocuk biliyor musun sen bu gün ilk yaz gülümsemenle yarınların umudusun sen sen olmak istersen eğer özvarlığınla büyü...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ki-yukselesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mağrur Beste', 'magrur-beste-rakip-bay-bwjjj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni hatırlattığı için dinliyorum

İçimi titreten bu mağrur besteyi, 

Her notasına adını koymuşum

Herbir mısrasına adını

Şimdi sen uzaklardasın

Duymuyorsun ağlayan kemanın sesini

Bense yalvarıyorum bir deli rüzgara

Ulaştırsın diye sana bu mağrur besteyi.

Kızgın bir su damlası iner içime

Ne zaman duysam bu melodiyi

Alır götürür beni olmayan bir meçhule

Bir başka ben olurum her dinlediğimde.

Aklımda yine sen, kulaklarımda bu mağrur beste

Anlayacağın hiçbir şey değişmedi bu gece de, 

Gücüm yeter belki kapamak için kulaklarımı ama; 

Nasıl söz geçirebilirim bu delikanlı yüreğime

Varken aklımda sen, kulaklarımda bu mağrur beste.', 'Seni hatırlattığı için dinliyorum İçimi titreten bu mağrur besteyi,  Her notasına adını koymuşum Herbir mısrasına adını Şimdi sen uzaklardas...', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/magrur-beste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemin Öğütleri', 'annemin-ogutleri-rakip-bay-vy51p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Annem yazma oğul derdi yazma

Yazık ediyorsun ödev yapacağın sayfalara, 

Önünde koca bir hayat beklerken seni

Geçirme bu güzel yıllarını boşuna.

Şairlik de neymiş, oku adam ol önce

Şairler el pençe divan durur

Cebindeki parayı görünce.

Bırak bu hevesleri doktor olmalısın sen

Belki bir yararını göremem ben de, 

Ama şifa arayanlar iyi olur sayende.

Yıllar geçti, şöyle bir eskiye bakıyorum

Değişen hiçbir şey yok

Hala ödev yapacağım kağıtlara yazıyorum.

Ne doktor olabildim, ne de bir şair

Ne annem sevindi buna, ne de bu fakir.', 'Annem yazma oğul derdi yazma Yazık ediyorsun ödev yapacağın sayfalara,  Önünde koca bir hayat beklerken seni Geçirme bu güzel yıllarını boşu...', ARRAY['Türk Edebiyatı','Şiir','Rakip Bay']::text[], 8.5, '{"poet":"Rakip Bay","poet_slug":"rakip-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/annemin-ogutleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkili Bir İkindi', 'i-kili-bir-i-kindi-selim-temo-8w9vn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adım şakir

tabancamı orta gözde saklarım

bütün zilleri çaldım

her kız en az bir kere terketti beni

adım Şakir

bekarım

Adım Şakir

sakat bir atın mümkünse burnuyum

gururluyum

yaşadım ve savaştım

sümüklü bir fil gibi

aslen özürüm

çolak bir boksörüm ötekinin ringinde

adım Şakir

sakarım

Adım Şakir

bana katil diyen türbedar

olmadımsa birimi klonlarım

adı Şakir

adım Şakir

şoparım...', 'Adım şakir tabancamı orta gözde saklarım bütün zilleri çaldım her kız en az bir kere terketti beni adım Şakir bekarım Adım Şakir sakat bir a...', ARRAY['Türk Edebiyatı','Şiir','Selim Temo']::text[], 8.5, '{"poet":"Selim Temo","poet_slug":"selim-temo","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ikili-bir-ikindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüdün Bebeğim', 'buyudun-bebegim-huseyin-cayikli-5de9o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Büyüdün bebeğim

ayakların yere basınca anlayacaksın

hayat sana oyun gibi gelecek

sen yakan top oynarken

günler sana gelen top gibi acıtacak

hayat senden vefakarlıgını bekleyecek

Büyüyeceksin bebeğim 

ütopyaların olacak

savunacağın değerlerin

ve ay ışıgın olacak.

birgün aşık olacaksın

o tadı alcaksın

ve birgün terkedilmeyi öğreneceksin

birde terketmeyi 

sonra en güzel aşkı yaşayacaksın

yalnızlık seni saracak 

ağlayacaksın

sana ağlamayıda öğretecekler

doğduğunda yanında olan hiçbir insan

bir hiç olup yanında olmayacak

doğduğun gibi ağlayacaksın...

yalnız kalıp yürüyeceksin

polis sirenleri ambulans sesleri

barikatlar 

her barikatı aşcaksın

özgür olacaksın

gerektiğinde özgürlüğün için 

yaşamından ödün vereceksin

ve yaşayacaksın

herşey doğumunla başladı

ve herşey o günle devam edecek

ölüm yoktur aslında bebeğim 

sen ölümü düşünürsen ölürsün

insanları sev

sev ki 

insanlaş 

sev ki

hayata karşı bir değerin olsun', 'Büyüdün bebeğim ayakların yere basınca anlayacaksın hayat sana oyun gibi gelecek sen yakan top oynarken günler sana gelen top gibi acıtacak ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/buyudun-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç İşte Kendi Kendime Konuşuyorum', 'hic-i-ste-kendi-kendime-konusuyorum-sair-poet-6zl2v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1.

Saban demiriyle ilk tohumunu arıyorum sevgimin.

Tutunduğum taşlara akıyor vücut sıcaklığım.

Bir ilk çağ mağarası gibi ruhumu kumarda kaybettim

Derimin ötesine çökmüş yanaklarım.

Alnımdaki kırışları, uzak şimşeklerin çakışı aydınlatıyor.

Buğulanan camlar hayallerimi engelliyor.

Hayat, derimi kemiğinden yüzen bir rüzgar gibi, 

Kimi zaman ay gibi donar kanım.

Tavanı alçak bir gökyüzü, 

Sevişmeyi unutmuş gövdeme abanır....

2.

Küllerimin önünde arıyorum kendimi.

Ya da yağmurda, siste, rüzgarda....

Kenti gömerek kaldırımlara....

Denizin kenarında yüzüme bakarım..

Kirpiklerim sulara sürtünür.

''Sen varsın'' diye fısıldar kulağıma.

Nasıl öleceklerini bilmediğim dostlarımın 

ağırlıklarını omuzumda taşıyorum.

Ölümün de kendine özgü bir doğruluğu vardır.

Öyle şeyler geçti ki gözümün önünden

şimdi hiç bir şeyi görmez oldular.

Başarabilecek miyim kendimce ölmeyi? 

Biraz daha dayansam, 

belkide, 

göreceğim çiçeklendiğini ömrümün..

Benim sonumun geldiği yerde, 

bir gün, yaşayacak olanlar, 

beni hissedebilecekler mi? 

3.

Memleketimin taşları elimi, avucumu yırtarken, 

yaz yazabilirsen

elindeki son deniz kabuğuna

tarihi, adını, yeri....

Ve fırlat denize...

Her kaçışımda bir derin acıydı tutunabileceğim.

Kendi gövdemi işte böyle tanıdım.

Ah, 

bir başkası başlayabilse 

benim yolumun sona erdiği bu yerden.

bu göğün altında balık olan biziz, 

ağaçlar yosun......

4.

Öğle güneşi tutuştururken damarlarımı, 

çömelip otlara seyrettim zamanı...

Süsle saçlarını karakız, dikenleriyle güneşin.

Bir martının kanadının denizi yırtması gibi, 

memeler kadar birbirinden uzak hafızalar...

Hani, 

geceleri, ıssız dağ yollarında, birden, 

bir hayvan gözleri parlar ya karşıdan...

işte öyle, 

Sana  olanca aydınlığım ve karanlığımla bakarım...

5.

Bir geneleve dönen bu şehrin güzelliklerinin

çığırtkanlığını yapıyor artık godoşlar.

Erkek buzağı üstüne binsin diye

bir inek postuna bürünüyor

köpüklerden doğan kız...

Benim saçlarım ağarıp, döküldükten sonra başımdan, 

senin sırma saçlarını istemiyorum...

6.

Yıldızlara basa basa yürürüm ıslak kaldırımlarda

Gördüğüm her bir çift gözü sana tamamlarım.

Sen binlerce yaşayasın diye...

Gökyüzünü katlayıp bir köşeye koyarım.

Yanaklarında  çiban izi taşıyan kadınlar için.

Kadınlar! 

varlığın bize geri dönen tarafı.....

7.

İnsan ne değilse o olmayı ister.

Yitirilen aşk, yürekten arzu edilendir.

Her gün bizden bir parça sokakları dolaşır.

Vurup gider akşamın yollarında düş kurarak.

Hafızamda anılar nankörce filizlenir.

Hiç bir şeye inanmamakla övündüğüm, 

o ikinci cahillik dönemlerimden kalma....

8.

İsterim ki dizelerimi bırakayım.

Bir komutanın kılıcını bıraktığı gibi.

Onun şanı, şöhreti 

erkek elinde savrulmasındandır.

Demircinin iyi su vermesinden değil.

Bir yumuşak, katıksız akşamda

dinlensin ham kütlem.

Çünkü, 

Bozkırda ağırdan alır bahar gelmeyi.

9.

Uzaklarda dağlar uyur, 

sarınarak sislere.....

Hatıralar da uyuya kalsın 

bir pınar taşlığında...

Bir hüzünlü ağıt yayılsın.

- Sevgili toprağımın türküsü.-

Tuz basarsın aşka...

...unutursun o zaman.

10.

Aklı aşar aşk dediğin, 

Yılını kendi bilir.

gününü, saatini, ezgisini; 

hatta aşığa maşuğu bile yaratır.

Denemeyle olmaz aşk.

Maşuğa ''varsın'' demez hiç bu alemde.

Silinip gider geçmiş saatlerin şarkısı.

....-Şarkıma soğukluk kattın sen! -....

11.

O kadar zavallıyım ki kendimle kaldığımda, 

Bir başıma gezerken

kendimle bir anlaşabilsem....

Bir hayalet gibi yürümesem sokaklarda, 

alevlerin çıtırtısıyla yaşadım seni, 

Sıcaklığının kokusu yetti.....

12.

Geceyi beklerim geceyi! 

Yalnızlığımdan bir kovuk örerim.

Bütün gece içinde saklanasın diye.

Bol ışıklar biçimini değiştirir senin.

Konuşmak, 

kucaklamak kadar bereketli olur yokluğunla, 

Sen güpe gündüz, ben karanlık gece..

Birebirimize verecek ellerimiz var.

Yalnızlık heykel gibi dikilir.

Gülüşler küfür gibi...

Kendimde yaşatıyorum şimdi, 

kendimde seni...

-inleyecek kadar gücüm var.-

13.

Hiç bir zaman tam karanlık değildir gece, 

Her acının sonunda açık bir pencere vardır.

Yaşıyorum ölüme karşı, 

sonsuz düşler içinde yaşıyorum...

Yaşıyorum taş gibi kalabalığın çölünde..

- Parlamayan yıldızın yıldızlığı neye yarar.-

14.

Bir şimşek soyup çırıl çıplak etti beni.

etim yerlere döküldü.

Utancın da bir yumuşaklığı vardır.

Kendisinden tiksiniyormuşcasına

sırtını dönüp kaçan saatlerin ardından, 

üzgün üzgün bakarım.

15.

Mavi damarlı, inci çiçekli güzel, 

akıl almaz varlığını öveyim diye

özel kalem müdürlüğüne mi atadın beni? 

O beyaz kollar benim ufkum oldu.

Ama, sisler yıldızların örümceğidir.

Yangın, 

Tavus kuşunun kuyruğundaki bir gül...

16.

İnsan geçmişini nasıl anlatır ki, 

Sinekler sokmasın diye sigaraya başladım.

Yaşamak aynı zamanda

kendini dünyaya kaydetmek değil midir? 

...ve şarkı söylenebilir korkuya karşı.

Bir gün görürsün sana güldüğünü bir taşın.

Kapasan gözlerini üşüşür üstüne geçmiş.

Çekip giden, diğerlerini, 

kendisiyle yalnız başına taşır.

- kelimeler, kağıda çaktığımız bir çivi değildir.-

17.

Düşünceme su dökün, 

boğun onu.

Dalarak, durgun sularına dilin

inci çıkartırım.

Ayak ucuma fırlatılmış beni seyrederim.

Bir kuşun çalıya bıraktığı

mavi tüyünü seyreder gibi...

18.

Yaşıyor olmak, 

yaşamakla bağdaşmaz her zaman.

İnsan ne yaparsa yapsın, 

ne söylerse söylesin, 

bir bir kalacaktır bunlar yaşamın içinde...

19.

Ben biraz ertesi gün gibiyim.

eksiğim, unutkanım...

Yılkı atlarının ayak sesleri yankılanır içimde.

Bir sigara gürültüsü ürpertir beni.

Boşluğun diş izleri morartır yüreğimi.

Hüznün ve çaresizliğin eklem yerlerinden

ağrılar fışkırır...

20.

Ya ben senden gideyim ya da sen bana gel, 

Karanlığın kulak zarını delelim.

geceyi kaldır omuzlarımdan

kalbin kalbimin belasıdır..

lav içmeye mahkumum.

Resimlerden alırım gülücük demetini.

+

Artık şiirleri aşağıdan yukarı okuyorum.

Seni şimdi bir görsem, 

Kendimi bir yerlerden hatırlar

ama çıkartamam.

*

Bu yaşta ölmek fazla acemice...

Aşkın sonu önünden iyidir....

--------ben de iyiyim--------', '1. Saban demiriyle ilk tohumunu arıyorum sevgimin. Tutunduğum taşlara akıyor vücut sıcaklığım. Bir ilk çağ mağarası gibi ruhumu kumarda kayb...', ARRAY['Türk Edebiyatı','Şiir','Şair Poet']::text[], 8.5, '{"poet":"Şair Poet","poet_slug":"sair-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":198,"source_url":"https://www.antoloji.com/hic-iste-kendi-kendime-konusuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Mektubu Değil', 'ask-mektubu-degil-fatih-cinar-oskfk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'merhaba

aşktan anlamayan sevgili

hatırlıyormusun geçen yaz görmüştüm seni ilk kez

sen mağazada tezgahtar

bense haylaz bir öğrenci bir tezgahtarla bir öğrencinin aşkı

aslında sadece bir öğrencinin ölümüne sevdası

ben hep sevdim hep sevdim

fakat sen nefret ettin sevgimden

senin işten çıkmanı beklerdim köşe başında

ah diliolsada konuşsa o taşlar

sensizliğin nağmelerinde dilimdeki şarkılar

hep bugün söyliyeceğim derdim seni sevdiğimi

hep bugün hep bugünler yarınlara kaldı

sen bazen dilimde güz gülleri

bazen batsın bu dünya

bazende aşkın kanunu olurdun

yazardım seni

bazen güzel kağıtlara 

bazen yırtık bir gazete parçasına

işte böyle geçerdi günler

geceleri hep seni düşünür sana küser

sabahlarıysa yine aklıma gelirdin barışırdım

ah sevildiğini bilmeyen sevgili

arkadaşlarıma anlatırdım seni

ve seni nasıl sevdiğimi

nasıl sevdiğimi söyliyemediğimi

onlarda bana nasihat verir ve git konuş derlerdi

son pişmanlık trenleri gardan kalkmadan 

tabi yine yarınlara kalan geç kalmışlığın korkusu

benliğimi sarsa bile konuşamazdım seninle

önümden öyle geçip giderdin

bazen tebessüm ederdin

sanki geçtiğin yollarda yüreğimi ayaklarınla ezerdin

ve ben yine elimde sigara serseri sokaklarda geceyi beklerdim

sensizliğin gecelerinde

bir karanlığı süpüren çöpçüler

bir hayata küsmüş keşler 

ve boynu bükük bir ben

ah gözleri yalan sevgili

en sonunda

tüm utancın yükünü sırtıma alıp

yanağımdaki kızarıklığı saklayıp

sana seni çok sevdiğimi söyledim

söyledim amma nafile

çünkü sen aldırmadın 

o sözlerin sanki cam kırığı oldu yüreğimi kanattın

ve aşka yalan dedin sen aşkı kirlettin

sende inanma yalan dedin

dedin ya olsun

ben seni o kara günden sonrada sevdim

ve taş kalbine inat hep seveceğim yemin ederim

ah aşka inanmayan sevgili

sen belki bu mektubu umarsızca okuyacaksın

ben senin bunu okurken parmağınla yanağına dokunduğunu

gözlerini hafifçe kıstığını

saçlarını kulağının arkasına topladığını

ve alaycı kahkahalar attığını görmiyeceğim

sen benim bunu yazarken

elimin uzanamadığı yerlere

kelimelerle sokulmaya çalışmanın

kırılgan harflerden kurulmuş

görünmez bir köprüden sana doğru yürürken

düşmekten öylesine korkmanın

ismi bile olmayan bir çok duyguya

isimler bulmaya uğraşmanın

beni nasıl yaralayıp nasıl yorduğunu bilmeyeceksin

çünkü sen aşka kin güdenlerdensin

ben

ileride bana anlaşılmaz görünecek olsalarda

şu anda bana

kendime saplamak için elimde tuttuğum 

solgun bir bıçak gibi sade

ve içmeye hazırlandığım zehirli su gibi

berrak gözüken duygularımın

keskin ve yakıcı tadını

onları üstünü örten sözcüklerin altından

çıkarıp çıkarmamakta duyduğum karasızlığı

sana hiç anlatamayacağım

ah sevgiye yalan diyen sevgili sana nasıl yalvardığımı 

hiç işitmeyeceksin

sıradan bir merhaba sözcüğünü saklayacak o gözlerimdeki yalvarışı görmeyeceksin

ama bütün bunlar

bu sahte kibirin bu alaycı gülüşün

bu sıradan bir merhabayı anlamayan taş görünüşün

içimdeki seli dindirmeyecek

bütün bunlara hiç aldırmadan

bana sarılmanı beni sevmeni bekleyeceğim

ah sevgili! 

o kadar sadeki duygularım

kırılgan bir köprüden sana doğru yürüyorum

sana ulaşamazsam

sesim ve kelimelerim değmezse sana

ve sevmezsen beni

inanmazsan sevdama

işte ozaman 

sensiz ve sonsuz bir boşluğa düşeceğim

ve işte ozaman

senin aşka inandığını ve sevdayı anladığını

görmeden öleceğim...', 'merhaba aşktan anlamayan sevgili hatırlıyormusun geçen yaz görmüştüm seni ilk kez sen mağazada tezgahtar bense haylaz bir öğrenci bir tezgah...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/ask-mektubu-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkından Sonra Aşk', 'kirkindan-sonra-ask-salih-ozalasan-1319r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda bu nezaman gelir

Bilinmezki başa

Adını yazarsın nokta, nokta

Ama diyemessin hiçbir dosta

Birgün tutulmaya gör

Başında eser kavak yelleri

Bakmassın yaşın kırkından sonrasına

Sana göre sevdanın yaşı olmazda

Onu gelde anlat eşe, dosta

Konuşamassın, kelimeler düğümlenir

Yüreğin atar artık bir başka

Ah be dostum, kırkından sonra

Nereden tutuldun sen bu aşk''a

Dizini döversin niye erken gelmişim? 

Ah doğsaydım şöyle bir on yıl sonra

Doğmadın say da bakalım

O zaman o çıkacakmıydı karşına

Yine yüreğine bir kor alev düşecekmiydi? 

Bakalım karşılık verecekmiydi aşkına

Ya sen, diyebilecekmiydin, ? Seni Seviyorum

Söyleyebilecekmiydin pervasızca

Her gördüğüne, onu çok ama çok sevdiğini

Hiç sanmıyorumya, varsayki söyledin

Bakalım o sevecekmiydi seni

Karşılık bulabilecekmiydin duygularına, ? 

Şimdiki gibi çaresiz kıvranmayacağını

Nereden bilebilirsinki? 

Bilemessin, bilemessin, çünki sen

Hiç bir zaman sevdiğini söyleyemessin

Kırkından önce de böyleydin, 

Kırkından sonramı değişeceksin, ? 

Bırak güldürme beni Allah aşkına

Dönsen kendi Dünya''na

Kırkından sonrada olsa

Dilediğin gibi sev, dilediğin gibi yaşa

Olmasın hiç kimse umrunda

Bence aşk daha güzel kırkından sonra', 'Sevda bu nezaman gelir Bilinmezki başa Adını yazarsın nokta, nokta Ama diyemessin hiçbir dosta Birgün tutulmaya gör Başında eser kavak yelle...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kirkindan-sonra-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yak Ve Git', 'yak-ve-git-tuncay-kocaman-a9x6b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hamur pişince ekmek

Çamur pişince toprak

Çocuk pişince delikanlı

Delikanlı da adam olurmuş

Bana biraz daha vakit ver

Senden tek isteğim vakit

Haydi

Şimdi içimi yak ve git', 'Hamur pişince ekmek Çamur pişince toprak Çocuk pişince delikanlı Delikanlı da adam olurmuş Bana biraz daha vakit ver Senden tek isteğim vaki...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Kocaman']::text[], 8.5, '{"poet":"Tuncay Kocaman","poet_slug":"tuncay-kocaman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yak-ve-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin Ya?', 'sen-gittin-ya-emel-cengiz-7r9wp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gittin ya! 

Güneş aykırı doğmayacak

Çiçekler tenin gibi asla kokmayacak

Kahırların bini bir para olan yalnızlar rıhtımında

Bir ben olacağım..

Karanlık gecelerde gökyüzünde ışıyan yıldızlarca..

Yalnız, yapayalnız

Seni yüreğimde yaşatacağım riyasız, yalansız

Özlemler beklenenlere, 

Özlemler hakedenlere

Bu yürek selini hissedenleredir..

.

Sen gittin ya! 

Yarın düşleri yokolmuş nesil gibi olacak

Ayazları ruhumu üşütüp, donduracak..

Geceler bir başka kararacak

Gündönümleri yaşanmayacak

Çocuksu öpücüklerin olmayacak

Çılgınlıklar doyasıya yaşanmayacak

Her şarkı, yeniden elvedaları hatırlatacak

Dizeler sensizliğe ağlayacak

Acı çekmekse aşk, 

Yürek, doyumu acı çekmekte yakalayacak.

.

Sen gittin ya! 

Arzu nöbetleri tutacağım geceden sabaha

Ufuklarda gezdireceğim gözlerimi

Sen düşeceksin ansızın aklıma

Yokolan mutluluklarda takılı kalacağım

Delicesine sevdiğime asla pişmanlık duymayacağım

Dedim ya! Ötesi yok

Seni asla, 

Asla seni unutmayacağım..', 'Sen gittin ya!  Güneş aykırı doğmayacak Çiçekler tenin gibi asla kokmayacak Kahırların bini bir para olan yalnızlar rıhtımında Bir ben olaca...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-gittin-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Desen', 'gel-desen-mustafa-sureyya-sezgin-4s30t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir tek bakışınla

Davet ediversen, 

Bir tek sözünle

Gel deyiversen.

Hemen koşarım sana

Kanatlanarak, 

Tüm geçmişi unutarak.

Gözlerim yeniden ıslanır belki, 

Dalgalandıkça içimde

Gözlerinin deniz mavisi...

Yeter ki sen

Gel desen! ..

Bir tek kelime

Ne kadar kolay! ..

Önce bir '' gel '' deyiver, 

Sonra istersen '' öl '' deyiver.

Söyle meleğim bak bekliyorum.

Gözlerim dudaklarında, 

Hasretim sana! ..

Yollarını dalga dalga sevilerle döşedim.

Ne olur haydi

Gel deyiver bana...', 'Bir tek bakışınla Davet ediversen,  Bir tek sözünle Gel deyiversen. Hemen koşarım sana Kanatlanarak,  Tüm geçmişi unutarak. Gözlerim yeniden...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gel-desen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş Oluyorum', 'sarhos-oluyorum-mustafa-sureyya-sezgin-d4chi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek seni her gece

Ve unutmamak bir daha

İçmek senin şerefine

Biraz daha, biraz daha.

Bu özlemi ben her zaman

Ölesiye duyuyorum

Düşündükçe seni her an

İnan sarhoş oluyorum.', 'Sevmek seni her gece Ve unutmamak bir daha İçmek senin şerefine Biraz daha, biraz daha. Bu özlemi ben her zaman Ölesiye duyuyorum Düşündükçe...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sarhos-oluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamımsın', 'yasamimsin-mustafa-sureyya-sezgin-bru1d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim dalmış boşluğa, 

Elimde bir sigara

Seni anımsıyorum...

Tüm yokluğun içinde, 

Yaşıyorsun benliğimde

Tek gerçeksin...

Dünden bugüne yol bulan

Yarınlarıma uzanan

Umut köprümsün...

Dünüm, bugünüm, yarınımsın, 

Sevgilim, sen tek kelimeyle, 

Yaşamımsın! ..', 'Gözlerim dalmış boşluğa,  Elimde bir sigara Seni anımsıyorum... Tüm yokluğun içinde,  Yaşıyorsun benliğimde Tek gerçeksin... Dünden bugüne y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasamimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-ozlem-aman-daxkj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'okadar kararsızki yüreğim

sakın sevmediğimi düşünmeyin

deli gibi

anlatamadıklarımla seviyorum ben..

ama karşımdaki olamaya görsün zalim

ama karşımdaki itmesin beni boş duvarlara

yalnızlığa..

birgün sizede dedimi biri

yokum artık

mutlu olamnı isteyip çekip gidiyorum

yok kardeşim böylesine sitemlik bir oyun

belki oyun belki

tuzak

bilmiuorum

kanmam mı gerek

sevgimden mi gitmem gerek

hayat ne yaptım sana be

nasırlaştırdın yüreğimi

ve sen hayat

dediğim sensin elbet

ve ben yine seni seviyorum...', 'okadar kararsızki yüreğim sakın sevmediğimi düşünmeyin deli gibi anlatamadıklarımla seviyorum ben.. ama karşımdaki olamaya görsün zalim ama ...', ARRAY['Türk Edebiyatı','Şiir','Özlem Aman']::text[], 8.5, '{"poet":"Özlem Aman","poet_slug":"ozlem-aman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilmiyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbini Bir Issızlığa Emzirirsin', 'kalbini-bir-issizliga-emzirirsin-cezmi-ersoz-edlfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İncitir tenini 

Kim olursa olsun sevişmek, 

İncitir yüzleri olmayan bedenlerin 

Kimsesiz hazları... 

Çarmıha gerilmiş ruhlar 

Döner boşluğun çarkında. 

Bir elin burada, bu aşksız zamanlarda, 

Bir elin yorgun kalbinde, 

Döner bir gün döner diye beklersin, 

Tenini incitmeden kalbinin kapısını açacak el, 

Eldeki incetilmiş büyü, sabır, yangın... 

Beklersin, beklersin... 

Beklerken, 

Kalbini bir ıssızlığa, umut dolu bir yokluğa emzirirsin...', 'İncitir tenini  Kim olursa olsun sevişmek,  İncitir yüzleri olmayan bedenlerin  Kimsesiz hazları...  Çarmıha gerilmiş ruhlar  Döner boşluğun...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kalbini-bir-issizliga-emzirirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanyolu', 'zamanyolu-ali-saglam-3-4s12h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kadife bir elbise üzerinde, 

Sevgin diz altı, 

Yalnızlığın kolu kısa olmalı, 

Dansederken seninle zamanyolu''nda, 

Üzerindeki tek takı, 

Cennet gözlerin Olmalı,', 'Kadife bir elbise üzerinde,  Sevgin diz altı,  Yalnızlığın kolu kısa olmalı,  Dansederken seninle zamanyolu''nda,  Üzerindeki tek takı,  Cenn...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zamanyolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''a Dair Yorumsuz Kelimeler', 'ask-a-dair-yorumsuz-kelimeler-ali-saglam-3-j2ami', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk nedir? ...

Aşk ne benim seni sevmemdir, 

Nede, 

Senin beni sevmendir...

Çünki kimse ilk anda birbirini sevemez, 

Aşk aynı şeyleri sevmekle başlar...', 'Aşk nedir? ... Aşk ne benim seni sevmemdir,  Nede,  Senin beni sevmendir... Çünki kimse ilk anda birbirini sevemez,  Aşk aynı şeyleri sevmek...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-a-dair-yorumsuz-kelimeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sentetik Aşk', 'sentetik-ask-ali-saglam-3-f6sj7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk...

Aşk... Olalı

Benim gibi aşık görmedi, 

Ki...

Bende Aşk''ı görmedim...

Ben aslında saklambaç oynuyorum, 

Aşk''la...

Lakin...

Kimsenin bilmediği sentetik zamanlarda! ..', 'Aşk... Aşk... Olalı Benim gibi aşık görmedi,  Ki... Bende Aşk''ı görmedim... Ben aslında saklambaç oynuyorum,  Aşk''la... Lakin... Kimsenin bi...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sentetik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben En Çok Seni Sevdim', 'ben-en-cok-seni-sevdim-ali-saglam-3-fggx4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açmasın güller! ! ! 

                Gönül bahçemde! ! ! 

Senden

Güzel

Çiçek

Tanımam

Ben...! 

Dünya güzel doluymuş, 

            ''Banane..! ''

Gönlümdeki

Biricik

Güzellik

Sensin

Birtanem...!', 'Açmasın güller! ! !                  Gönül bahçemde! ! !  Senden Güzel Çiçek Tanımam Ben...!  Dünya güzel doluymuş,              ''Banane..! ...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-en-cok-seni-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Kadar', 'sevgili-kadar-ali-saglam-3-ekqnb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her 

