INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dal', 'dal-mansur-tuncay-tasci-7tuzc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dal..., 

Daldım

Bir rüyaya / bir hazan mevsimi

Daldım

Hüzün yaprakları savrulan

Dalakta bir hayaldim

Daladım

Karşımda duran kendi gölgemdi

Dala-kaldım

Dalgın sularda

Daldan dala

Bir dalga attı beni

                                                              mansur', 'Dal...,  Daldım Bir rüyaya / bir hazan mevsimi Daldım Hüzün yaprakları savrulan Dalakta bir hayaldim Daladım Karşımda duran kendi gölgemdi D...', ARRAY['Türk Edebiyatı','Şiir','Mansur Tuncay Taşçı']::text[], 8.5, '{"poet":"Mansur Tuncay Taşçı","poet_slug":"mansur-tuncay-tasci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndüm Durdum', 'dondum-durdum-reha-basogul-b94t0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gece baktım, bir rüya gözüktü gözüme

bir ışık süzmesi, bir sayı ve bir kelime

bana dedi, aşk için dön hadi! 

sonra yokoldu gitti

ama neyin etrafında döneceğimi hiç söylemedi....

bir gece baktım, bir sikke gözüktü gözüme

harcadık durduk onunla tüm gece

dedim aşk bu olmalı...

çizdim bir çember çevresine

ve döndüm durdum onun üstünde

bir gece baktım, bir kitap gözüktü gözüme

okuduk durduk onunla tüm gece

dedim aşk bu olmalı...

çizdim bir çember çevresine

ve döndüm durdum onun üstünde

bir gece baktım, bir yıldız gözüktü gözüme

parladık durduk onunla tüm gece

dedim aşk bu olmalı...

çizdim bir çember çevresine

ve döndüm durdum onun üstünde

bir gece baktım, bir mektep gözüktü gözüme

öğrendik durduk onunla tüm gece

dedim aşk bu olmalı...

çizdim bir çember çevresine

ve döndüm durdum onun üstünde

bir gece baktım, bir alim gözüktü gözüme

araştırdık durduk onunla tüm gece...

dedim aşk bu olmalı...

çizdim bir çember çevresine

ve döndüm durdum onun üstünde

bir gece baktım, bir sayı kümesi gözüktü gözüme

saydık durduk onunla tüm gece

dedim aşk bu olmalı...

çizdim bir çember çevresine

ve döndüm durdum onun üstünde

bir gece baktım, bir bestekar gözüktü gözüme

çaldık durduk onunla tüm gece

dedim aşk bu olmalı...

çizdim bir çember çevresine

ve döndüm durdum onun üstünde

bir gece baktım, bir rahip gözüktü gözüme

günah çıkardık durduk onunla tüm gece

dedim aşk bu olmalı...

çizdim bir çember çevresine

ve döndüm durdum onun üstünde

bir gece baktım, bir ressam gözüktü gözüme

boyadık durduk onunla tüm gece

