INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmesini de Bileceksin Gitmesini de', 'sevmesini-de-bileceksin-gitmesini-de-mesut-uzunlu-mhewd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koşulsuz Sevmek.

Sevmesini de bileceksin gitmesini de.

İnsanı seveceksin, 

Çiçekleri, böcekleri, hayvanları, 

Bitkileri, denizleri, ovaları...

Dünyayı seveceksin.

Zaman gelecek rakana bakmadan gideceksin.

Yaşamayı seveceksin.

Acıları, kederleri, dertleri, 

Mutlulukları, sevinçleri, güzellikleri...

Hayatı seveceksin.

Gün gelecek hepsini bırakıp gideceksin.

Güzelleri seveceksin.

Bakışları, gülüşleri duruşları, 

Yüzleri, gözleri, sözleri...

Kızları seveceksin.

Gerekirse hançeri bağrına saplayıp gideceksin.

Sevmesini de bileceksin gitmesini de.

Sevilecekleri seveceksin.

Gerekirse de bırakıp gideceksin.

Sevmesini de bileceksin gitmesini de.

Yaşamasını da bileceksin ölmesini de.

Sevdiklerin sevecek ve yaşayacak, 

Sevdiklerin için gidecek ve öleceksin.

Dostların için sevecek ve yaşayacak, 

Dostların için gidecek ve öleceksin.

Kadrini bilen için sevgi ve yaşam verecek, 

Bilmeyen için gidecek, ölsen bile gideceksin.

Sevmesini de bileceksin gitmesini de.

Yaşamasını da bileceksin ölmesini de.

Sevgiyi kirlettikleri zaman; 

Yüreğinden kan sızarak gideceksin.

Temizliğini korumak için aşkın; 

Gerekirse gözünü kırpmadan öleceksin.

11.02.2002 - Develi / Kayseri', 'Koşulsuz Sevmek. Sevmesini de bileceksin gitmesini de. İnsanı seveceksin,  Çiçekleri, böcekleri, hayvanları,  Bitkileri, denizleri, ovaları....', ARRAY['Türk Edebiyatı','Şiir','Mesut Uzunlu']::text[], 8.5, '{"poet":"Mesut Uzunlu","poet_slug":"mesut-uzunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sevmesini-de-bileceksin-gitmesini-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döneceğim... Bekle...Diyordun....', 'donecegim-bekle-diyordun-savan-gunay-pca9w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Döneceğim bekle beni diyordun...

Belki bir temmuz sabahı, daha kuşlar uyanmadan, 

Belkide zemheri bir kasım ayazı hava henüz pusmadan 

Tarih vermiyordun....

Ama bekle diyordun......

Kaç Kasım, kaç Temmuz sensiz geçti geçti

Kasımlarda yüreğim kar, temmuzlar yüreğim kor....

Hasretlik adama aslında her mevsimde   kor.....

Tarih vermiyordun, 

Döneceğim  bekle diyordun..

Benim  sana özlemimi.,  elime tarih olarak vermiş 

Gitmiştin....

Takvimler bir  türlü uyuşmuyordu 

Yüreğim bir türlü tutuşmuyordu....

Haziranla Kasım bir türlü buluşmuyordu....

 Ben her  Kasım soğuktan buğulanmış camlara 

 Yaşlı, yorgun parmaklarımla adını yazıp

Geldin mi sevdiğim derim......

Ve ben her Temmuz sabahı  hani sensizlikten sonra 

Tek tük kalan dostlardan kuşlara    biraz ıslak ekmek atarken, 

Seni düşler Tam gelmek üzre derim......

Geldin mi geldin mi.... yoksa  Aşk.....! ! ! ..', 'Döneceğim bekle beni diyordun... Belki bir temmuz sabahı, daha kuşlar uyanmadan,  Belkide zemheri bir kasım ayazı hava henüz pusmadan  Tarih...', ARRAY['Türk Edebiyatı','Şiir','Savan Günay']::text[], 8.5, '{"poet":"Savan Günay","poet_slug":"savan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/donecegim-bekle-diyordun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayın ve Tutku', 'mayin-ve-tutku-deral-baran-su8um', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu yenilgi benim 

Dağılmış bir ordu kadar yalnızım

Bakışlarında boğuluyorum 

Her gece...

Antik bir şehirsin 

Bütün hayaller sende gizli

Gerdanın hayallerimi süsler 

Tutkuyla...

Parmaklarımda ateş 

Damlar 

Her dokunuşta.

Felaketim olur gözlerin

İki çocuk var 

Ateş çemberinde

Yenilmiş bir gerillayım 

Gül yaprağına sarılı 

Başımı pusuda bıraktım 

Murdar bir haykırış 

Semayı kaplar

Narin ellerin boğazımda 

Ruhumu çarmıha gerer 

Her şafak...

Bana deniz tattır son kez

Bakışlarınla dirilt

Yoksa...

Dilim tutulur 

Ellerim kanar 

İstanbul üstüme devrilir

Kız kulesi son kez intihar eder.

Ve

Süleymaniye

 Günahlarımı sayıklar 

Girmek için zindanlarına Yedikulenin

Bağışla beni İstanbul

Yoluna mayınlar döşedim...

Başımı göğsüne koymak için

Son kez

Ölmeden önce....', 'Bu yenilgi benim  Dağılmış bir ordu kadar yalnızım Bakışlarında boğuluyorum  Her gece... Antik bir şehirsin  Bütün hayaller sende gizli Gerd...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/mayin-ve-tutku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevdam', 'benim-sevdam-murat-cetin-qt16z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevda suya düşse ıslanır mı arkadaş 

benim sevdam sele karıştı gidiyor 

unutsam mazide paslanır mı arkadaş 

benim sevdam küle karıştı gidiyor 

dik yamaçlar dostum olacak 

yarenlik etmedeyim rüzgara 

haykırışı kulağıma dolacak 

yanacak bir tutamlık nara 

bir buket kır menekşesi 

güzelliğinin büyüleyen sesi 

bayramlık pabuçları ayağında 

top oynamanın ilk hevesi 

yüreğime tutunan sarmaşık 

kendine o halde barışık 

üzme artık yağmuru gülüm 

ıslanır yoksa zavallı aşık 

kıvrım kıvrım döner arşa yükselir sada 

çarpar suratıma geri döner aksi nida 

yaşam mı bizi yaşar eze eze acımadan 

biz mi yaşamı ezeriz öldüresiye yada 

sevda suya düşse ıslanır mı arkadaş 

benim sevdam sele karıştı gidiyor 

unutsam mazide paslanır mı arkadaş 

benim sevdam küle karıştı gidiyor 

.... 

Ağustos 2002', 'sevda suya düşse ıslanır mı arkadaş  benim sevdam sele karıştı gidiyor  unutsam mazide paslanır mı arkadaş  benim sevdam küle karıştı gidiyo...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/benim-sevdam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavimtrak', 'mavimtrak-murat-cetin-r15lk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mavi gökyüzünden 

masmavi yüreğe düşer 

mavi hayaller 

mavi mavi dizilir 

avuç açar eller 

mavi duygu sezilir 

mavi gözbebeği maviye bakar 

mavi düşünür mavi söyler 

... 

mavimsi hareketle süzülür 

mavi martılar 

mavi düşümde 

mavi giymiş mavişim 

maziyi hatırlar 

mavi kağıda 

mavi kalemle 

mavi sözcükler dökülür 

mavi gözbebekleri için. 

... 

sonra 

mavi 

kallavi 

selamlar sızar 

mavi, maviye kaçar. 

..... 

maviliklerde taht kurmuş, 

masmavi yüreklilere maviman saygılar 

Ağustos 2002', 'mavi gökyüzünden  masmavi yüreğe düşer  mavi hayaller  mavi mavi dizilir  avuç açar eller  mavi duygu sezilir  mavi gözbebeği maviye bakar  ...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mavimtrak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğit', 'yigit-murat-cetin-ji8hh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'küheylanın yelesine teğet 

dört nala bir gölge geçer 

torosların eteğinden 

.. 

şimşek edasında çekilir kınından kılınç 

rüzgarı yararda geçer 

havada daire çizer 

gökgürültüsü naralar 

ve sonra iner çelik gürz 

keser ayakları yerden 

kılıç sesiyle rakseder 

yüzü peçeli bir yiğit 

bilek gücü şovu sergiler 

ve tadar imzasını 

imza atılası yüzler 

... 

korku salar 

kılınç çalar 

anlasalar... 

... 

kılınçları sevda suyuyla dövülmüş 

aşk ateşinde şekil almış 

at, avrat ve silah 

ve birde 

cenk meydanlarında seyyah 

ya şehit ol ya gazi 

tarihe nakşedilsin 

altın harfli yazı 

... 

.... 

... 

gün döner, şafak söker 

kasatura gölgesinde 

bir komando serinler.. 

göğsünde ay yıldız 

alnında ay yıldız.. 

hazırız der hazırız... 

... 

kahpe pusulardan arta kalan zamanında 

hasretlerini gönderir kucak kucak 

g3lerin şaklayan sesleri arasında 

kısıkça bir ninni söyler 

kundaktaki yavrucağına 

... 

top ağacın ardındaki namluya gülümser 

gülümser göğsünde açan güle 

matarasındaki son yudumluk su 

sevindirir kır menekşesini 

... 

desturuna kayıtsız kalmaz can meleğinin 

tam gidecekken döner ardına 

el sallar son kez 

yerini alan yavrucağına 

.... 

Ağustos 2002', 'küheylanın yelesine teğet  dört nala bir gölge geçer  torosların eteğinden  ..  şimşek edasında çekilir kınından kılınç  rüzgarı yararda geç...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/yigit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yüz', 'i-ki-yuz-kayahan-nacar-zess5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki yüzlüğümdür ben

Biri gülen hayatı umursamaz

Hayatla dalga geçen

Diğeri gerçek ben

Kahkahaların arkasına gizlenmiş

Hırsımın esiri olan

Saf, gülen adam rolüne girip, 

herkesin kim olduğunu öğrenmeye çalışan, 

Ama kimse beni tanıyamaz

Kendimi korur, gizlenirim

Beni çözmenin yolu: 

Karmaşık labirentlerden geçip, 

Yalanlarımı aşıp, 

Vücudumun içinde sakladığım, 

Benim dümyamın anahtarının bulunmasıyla olur

Daha o anahtarı bulan biri yok, 

Ama labirentte dolaşan çok mahluk var.', 'İki yüzlüğümdür ben Biri gülen hayatı umursamaz Hayatla dalga geçen Diğeri gerçek ben Kahkahaların arkasına gizlenmiş Hırsımın esiri olan Sa...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Nacar']::text[], 8.5, '{"poet":"Kayahan Nacar","poet_slug":"kayahan-nacar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/iki-yuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözcükler', 'sozcukler-kayahan-nacar-vokaw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gündüzlerin gürültüsünü, 

Gecenin sessizliğine tercih ederim.

O zaman benim dünyamın gürültüsü başlar.

Uzun geceler, 

Dünyamı heceler.

; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; 

; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; ; 

İki söz, iki nota

Bir cismi başka alemlere taşır.', 'Gündüzlerin gürültüsünü,  Gecenin sessizliğine tercih ederim. O zaman benim dünyamın gürültüsü başlar. Uzun geceler,  Dünyamı heceler. ; ; ;...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Nacar']::text[], 8.5, '{"poet":"Kayahan Nacar","poet_slug":"kayahan-nacar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sozcukler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Korkusu', 'ask-korkusu-kayahan-nacar-h0bmi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşktan korkuyorum

Aşkın beni aldatmasından ürküyorum

Her şey dışarıdan hoş ve güzel

Ya aşık olunca

Kalbini tutsak edince, 

Kim kurtaracak beni? 

Sen mi?', 'Aşktan korkuyorum Aşkın beni aldatmasından ürküyorum Her şey dışarıdan hoş ve güzel Ya aşık olunca Kalbini tutsak edince,  Kim kurtaracak be...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Nacar']::text[], 8.5, '{"poet":"Kayahan Nacar","poet_slug":"kayahan-nacar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-korkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narsist Aşk', 'narsist-ask-sair-folidor-g8bfp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevmekse birbirini

sevmenin gereği

ne sen sevdin beni

ne de ben seni

biz hep sevdik kendimizi

ama aslında sen hep ben değil miydin

ben ise hep sen

kendimizi çok sevmemiz 

hep, hep bu yüzden', 'sevmekse birbirini sevmenin gereği ne sen sevdin beni ne de ben seni biz hep sevdik kendimizi ama aslında sen hep ben değil miydin ben ise h...', ARRAY['Türk Edebiyatı','Şiir','Şair Folidor']::text[], 8.5, '{"poet":"Şair Folidor","poet_slug":"sair-folidor","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/narsist-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklemek', 'seni-beklemek-sukru-soyarslan-nhd4f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretin en güzeli Seni beklemek

Sevdanın en yücesi Seni beklemek..

Bir ömür gelmiyeceğini bilerek

Bir gün gelirsin diye Seni beklemek..', 'Hasretin en güzeli Seni beklemek Sevdanın en yücesi Seni beklemek.. Bir ömür gelmiyeceğini bilerek Bir gün gelirsin diye Seni beklemek.....', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-beklemek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerini Bana Ver..', 'gozlerini-bana-ver-sukru-soyarslan-08ei8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Simsiyah tel tel saçın

Kokusunu bana ver.

Esir olduğum kalbin

Sevgisini bana ver.

İşte yirminci yaşın

Mağrur sevdalı başın

Kirpiğin ile kaşın

Gözlerini bana ver.

Selviye benzer boyun

Güzeldir iyi huyun.

Şimdi ellerin oldun

Resmini de bana ver.', 'Simsiyah tel tel saçın Kokusunu bana ver. Esir olduğum kalbin Sevgisini bana ver. İşte yirminci yaşın Mağrur sevdalı başın Kirpiğin ile kaşı...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerini-bana-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzeli...', 'en-guzeli-sukru-soyarslan-jgjmn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevmek; aşkların en güzeli

Sevgindir; mutluluğun en güzeli.

Dünyada gözüm yok güzelden yana

Sen sevdiğim, dünyanın en güzeli.', 'Seni sevmek; aşkların en güzeli Sevgindir; mutluluğun en güzeli. Dünyada gözüm yok güzelden yana Sen sevdiğim, dünyanın en güzeli....', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/en-guzeli-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlem', 'gozlem-kayahan-nacar-v5c8k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir hikaye bin hikaye

Herkesin var bir hikayesi

Vapurdaki gözler, 

Dalmış kendi alemine

Sessizliği bozmuş motor sesi

İnsanlar kendi aleminde.', 'Bir hikaye bin hikaye Herkesin var bir hikayesi Vapurdaki gözler,  Dalmış kendi alemine Sessizliği bozmuş motor sesi İnsanlar kendi aleminde...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Nacar']::text[], 8.5, '{"poet":"Kayahan Nacar","poet_slug":"kayahan-nacar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gozlem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu', 'anadolu-kayahan-nacar-77r6d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yedi kardeştİk

Babamız vefat edince, 

Aile dışındakilerin  kışkırtmasıyla, 

Doğuyla, güneydoğu aileden ayrılmak istediler.

Tam onbeş yıl kavgalı oldular, 

Diğer  beş kardeşleriyle.

Ama anaları ANADOLU

Barışı sağladı

Kşkırtanları dışladı

Yedi kardeş barıştı.

ANADOLU hasta yatağından kalktı.

Kırık kolu kaynamıştı artık

Kollarını açtı, 

Çocuklarına sıkı sıkıya sarıldı.

Bir daha ayrılmasınlar diye kanını sundu TANRIYA.', 'Yedi kardeştİk Babamız vefat edince,  Aile dışındakilerin  kışkırtmasıyla,  Doğuyla, güneydoğu aileden ayrılmak istediler. Tam onbeş yıl kav...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Nacar']::text[], 8.5, '{"poet":"Kayahan Nacar","poet_slug":"kayahan-nacar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/anadolu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin.', 'nerdesin-ahmet-kurnaz-ukn0v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Titreyen mum ışığında

titreyen gönlüm sana yöneldi, 

Nerdesin.

Ses verdim, duymadın, 

söyledim, anlamadın

kafana taktın uzaklara gitmeyi

ve, belki de dönmemeyi.

Bilemezdin dönülmez yollarda yürüdüğünü, 

bilemezdin, gurbet akşamlarınınkâbusluğunu.

Hangi zamanlarda, hangi akşamlardasın? 

Nerdesin? 

Sen gurbete mahkûm, 

ben sılada esirim bıraktığın hatıralara.

Sabahlara yelken açan düşlerim, 

akşamlarda batarlar.

Tel tel dökülürüm, darmadağın olurum

ve toplayan bir el uzanmaz uzaklardan.

Sende yoksun, 

nerdesin? 

Biliyorum, 

gözyaşın ıslatıyor gurbet gecelerini.

Özlüyorsun, yanıyorsun hasretten.

Issız kalıyorsun duygularında

anlamıyorlar seni.

Tutuyorlar, hep tutuyorlar prangalar misali, 

isyan ediyor, kahroluyorsun.

Bulamıyorsun kendini, 

kayboluyorsun.

Nerdesin? 

Mevsimler, hazandan kışa döndüler, 

yalnızım, üşüyorum.

Dört tarafım bomboş, 

dört tarafım cehennem oldu, yanıyorum.

Çaresizim, dertliyim, sensin ilâcım.

Seni istiyorum, seni hep seni.

Sana muhtacım.

Nerdesin? 

            15 ARALIK 1997/Elbistan', 'Titreyen mum ışığında titreyen gönlüm sana yöneldi,  Nerdesin. Ses verdim, duymadın,  söyledim, anlamadın kafana taktın uzaklara gitmeyi ve,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/nerdesin-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-kayahan-nacar-jof7l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceler ah sessiz geceler, 

Hep ilham olmuş şairlere

Şiirler yazılır milyarlarca, 

Tek biri hatırlanır yıllarca.', 'Geceler ah sessiz geceler,  Hep ilham olmuş şairlere Şiirler yazılır milyarlarca,  Tek biri hatırlanır yıllarca....', ARRAY['Türk Edebiyatı','Şiir','Kayahan Nacar']::text[], 8.5, '{"poet":"Kayahan Nacar","poet_slug":"kayahan-nacar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siir-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İrade', 'i-rade-ahmet-kurnaz-19nrm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyorum

delilik bu yaptığım.

Hakkım yok seni sevmeye.

Sevgimi içime gömüp, 

yüreğimi kanatmalıydım yokluğunla.

Gözlerine türküler yakıp, 

saçlarını okşamalıydım hayallerimde.

Bir sabır taşı olup

sabretmeliydim.

Korkuyorum.

Ölüm gibi, hasret gibi

sessizlik gibi korkuyorum.

Senin yüreğine kor düşürüp, 

beni sevmenden korkuyorum.

Dipsiz kuyular gibi akşamlarımda

körpe sabahlarını boğmaktan korkuyorum.

Düşüncelerim arap saçı, 

kahroluyorum, 

kahrolmalıyım.

Ben ağlıyorum sevdana

sen gülüyorsun seni sevdiğime.

Gülüyorsun değilmi? 

Biliyorum, 

sen haklısın, sevemezsin beni.

Ben köpük köpük dert ırmağıyım.

Sen, Şardağının mor sümbülüsün.

Ben yanarım, kor olmuşum aşk ocağında

sen, bahar sabahlarının gonca gülüsün.

Ben koklayamam seni, 

koklamamalıyım.

Ne olur susma, 

kıble yeli edasıyla birşeyler söyle, 

nefretini haykır, 

yada acıma duygularını vur yüzüme.

Sevdiğini söylemeni beklemiyorum.

Yeter ki gülme bana, 

bir şeyler söyle

ne olur susma.

Tut ki deliyim.

Duygularıma prangalar vurup, 

irademi koyamadım ortaya.

Sevdim, sevdim, sevdim.

Karşılık beklemeden sevdim

suç mu işledim.

Akşamlarımı seninle doldurup, 

rüyalarımı sana adadım.

İşte böyleyim, 

Tut ki deliyim.', 'Biliyorum delilik bu yaptığım. Hakkım yok seni sevmeye. Sevgimi içime gömüp,  yüreğimi kanatmalıydım yokluğunla. Gözlerine türküler yakıp,  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/irade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevince (Sen)', 'sevince-sen-ahmet-kurnaz-g7v81', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin sevgin benim başımın tacı, 

Bendeki sevdayı bilmiyorsun sen.

O kara gözlerin, ruhun ilacı

Derdimin dermanı olmuyorsun sen.

Gergefte nakışsın, bürgüde oya

Kurbanım ben senin çektiğin soya.

Hasretin sığmıyor haftaya, aya

Bir gece yanımda kalmıyorsun sen.

Yemyeşil çimensin, kan kırmızı gül, 

Bembeyez köpüksün, çiçek çiçek tül.

Bense gülistanda bir garip bülbül, 

Bir nefes içime dolmuyorsun sen.

Ovada çeşmesin, dağlarda pınar, 

Göllerde nilüfer, bahçede çınar.

Sen ağlarsan benim yüreğim yanar.

Bir kere yüzüme gülmüyorsun sen.

               11 Aralık 1984/Elbistan', 'Senin sevgin benim başımın tacı,  Bendeki sevdayı bilmiyorsun sen. O kara gözlerin, ruhun ilacı Derdimin dermanı olmuyorsun sen. Gergefte na...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevince-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gonca''sın...', 'gonca-sin-sukru-soyarslan-k8h98', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ey güzel! Ne karanfil, ne de gül

Henüz açmamış, taze bir Gonca''sın..

O siyah saçların, ipekten bir tül

Endamın, selvi boyunla Gonca''sın.

Dudakların ateşten bir karanfil

Güzel yüzünle, kalbe doğan ay''sın..

İsteseydin, gönlümü verirdim bil

Ben kurumuş dikenim, Sen Gonca''sın.

Kirpiklerin sanki ok, dişler inci

Tüm güzelliklerde bil ki; Sen varsın..

Ümit versen, gönlün olur sevinci

Gönüllere hayat veren GONCA''sın.', 'Sen ey güzel! Ne karanfil, ne de gül Henüz açmamış, taze bir Gonca''sın.. O siyah saçların, ipekten bir tül Endamın, selvi boyunla Gonca''sın....', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonca-sin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldi Geçti', 'geldi-gecti-nesrin-gocmen-mqlg1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geldi Geçti

En çok denizi sevdi

Belki mavisindendi 

Özgürlüğündendi belki

Hep yağmuru bekledi

Bereketindendi tabi

Çok sevdi, belki sevildi

Terk etti mi bilemedi

O hep terk edilendi 

Her şeyi bağışladı

Af etmedi ihaneti

İstemezdi hiç hüznü

Belki ağladı, üzüldü

Belli etmedi, güldü

İşte o

Herhangi biri

Yaz günü esen yel gibi

Sessizce geldi geçti

10 Ağustos 2002', 'Geldi Geçti En çok denizi sevdi Belki mavisindendi  Özgürlüğündendi belki Hep yağmuru bekledi Bereketindendi tabi Çok sevdi, belki sevildi T...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/geldi-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mırıldanmalar', 'mirildanmalar-i-brahim-tenekeci-d0ph0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I 

içimden dedim beraber yürüyelim olur mu 

varsın gemilerimizi taşıyamasın sular 

varsın yarı yolda uyuya kalsın 

bize gönderilen bahar 

içimden dedim beraber yürüyelim olur mu 

varsın gölgemiz olsun hüzün 

dilediği gibi uzatsın canevimize ayaklarını 

varsın annemiz olsun tütün 

hayat daha sert vursun yumruklarını 

II 

içimden dedim ilmeği kaçmış bir hayat bizimkisi 

nedir alnımızdan öpmek için izimizi süren 

kalmış mıdır kalesi düşmüş bir şehrin cazibesi 

nedir yalnız bize yakışan bu serüven 

bu serüven ki 

bizden biri yaptı sırtımızdaki hançeri 

ve terketti bizi huzur denen sevgili 

kalakaldık, şaşkınlığın avuçlarında 

billur bir kuş gibi 

III 

içimden dedim gömülü bir ırmağın yalnızlığıdır bu 

beraber yürüyelim olur mu…', 'I  içimden dedim beraber yürüyelim olur mu  varsın gemilerimizi taşıyamasın sular  varsın yarı yolda uyuya kalsın  bize gönderilen bahar  iç...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tenekeci']::text[], 8.5, '{"poet":"İbrahim Tenekeci","poet_slug":"i-brahim-tenekeci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mirildanmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-zeki-avsar-4kn2m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece o kadar sessiz ki, sigaramın yanışını bile duyuyorum.

İçimdeki tufan da sessiz aynı bu gece gibi, 

Bağırıyorum ama ben bile duyamıyorum, 

Boğuluyorum....', 'Gece o kadar sessiz ki, sigaramın yanışını bile duyuyorum. İçimdeki tufan da sessiz aynı bu gece gibi,  Bağırıyorum ama ben bile duyamıyorum...', ARRAY['Türk Edebiyatı','Şiir','Zeki Avşar']::text[], 8.5, '{"poet":"Zeki Avşar","poet_slug":"zeki-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sessizlik-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Gece', 'sessiz-gece-zeki-avsar-d2iml', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece o kadar sessiz ki, sigaramın yanışını bile duyuyorum.

İçimdeki tufan da sessiz aynı bu gece gibi, 

Bağırıyorum ama ben bile duyamıyorum, 

Boğuluyorum....

Yıldızların arasına gidesi geliyor insanın bu gece.

Sessizliğe, 

Hiç geri gelmemek üzere...', 'Gece o kadar sessiz ki, sigaramın yanışını bile duyuyorum. İçimdeki tufan da sessiz aynı bu gece gibi,  Bağırıyorum ama ben bile duyamıyorum...', ARRAY['Türk Edebiyatı','Şiir','Zeki Avşar']::text[], 8.5, '{"poet":"Zeki Avşar","poet_slug":"zeki-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sessiz-gece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soyismi Dağ', 'soyismi-dag-nesimi-aday-2fmvd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hoş bolduk gece

benim annem öldü

üstünü ört ölü kardeşimin

üşüyorum

uykusuz aşklardan geldim

cevapsız mektuplardan

sesim mavi

sazım akşam sofrası

soyismi dağ olan şehrin

tanrısız misafiriyim

karanlık dağ yollarında

sokak lambalarını özlüyorum

köylü fenerlerini

eşgali eskimiş bir gezginim

kent kaçağıyım

köylerimi yakmayın

babam ölmedi daha

babam ölmedi.. daha ölmedi babam.. ölmedi daha...', 'hoş bolduk gece benim annem öldü üstünü ört ölü kardeşimin üşüyorum uykusuz aşklardan geldim cevapsız mektuplardan sesim mavi sazım akşam so...', ARRAY['Türk Edebiyatı','Şiir','Nesimi Aday']::text[], 8.5, '{"poet":"Nesimi Aday","poet_slug":"nesimi-aday","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/soyismi-dag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuzey', 'kuzey-nesimi-aday-zre7y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'iki kadın uzanır geceye

saçlarında hovarda rüzgar

şenlenir odalar, kuytuda şehvet

iner sokağa bir kedi lanetli zamanlarda

üşür eşik altlarına sığınan yoksulluk

kimseye sormaz adresini kaybeden mektup

üzülür saksıda çiçek, gökte incelen ay

eskir merhabalar iki el uzak kalınca

dostun selamı yırtık bir fistan gibi mahçup kalır

sabahçı kahvelerinde şekerli de olsa acıdır çaylar

bunu ancak bir yurtsuz bilir yorgun sandalyeler

iki damla gözyaşı biriktirir kendini arayan adam

hep kuzeyi gösterir gidilmeyen yolların pusulası

gidilse de atlasları buz tutan kuzey gurbetine

düşecektir ardına nar çiçekleri, dağda rüzgar sesi

sonra bir vagon hep boş duracaktır yüreğinde', 'iki kadın uzanır geceye saçlarında hovarda rüzgar şenlenir odalar, kuytuda şehvet iner sokağa bir kedi lanetli zamanlarda üşür eşik altların...', ARRAY['Türk Edebiyatı','Şiir','Nesimi Aday']::text[], 8.5, '{"poet":"Nesimi Aday","poet_slug":"nesimi-aday","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kuzey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-mehmet-yazici-dgru5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün, 

Lodos değişiklik yapmak istese

Kuzeyden esse

Kadıköy-Karaköy vapuru karar değiştirse

Kanlıca’ya yanaşsa

Erguvan çiçekleri hoşluk yapıp ağustosa kadar uzatsa

Boğaziçinde misafirliklerini

Martılar kedileri yemeğe davet etse

Gülfidan’ın kocası pazardan eve iki file dolusu zerzevatla gelse

Aşık olsa

Varoşların bütün kızları...

İşte, 

Ben, 

O zaman kutlarım doğum günümü

Emirgan’daki çay bahçesinde', 'Bir gün,  Lodos değişiklik yapmak istese Kuzeyden esse Kadıköy-Karaköy vapuru karar değiştirse Kanlıca’ya yanaşsa Erguvan çiçekleri hoşluk y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yazıcı']::text[], 8.5, '{"poet":"Mehmet Yazıcı","poet_slug":"mehmet-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dilek-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acının Arka Yüzündeyim', 'acinin-arka-yuzundeyim-akif-kurtulus-hbhrq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anlamasanız da olur, sesim parçalamak içindir dudaklarımı

büyük yaralardan geçtim, kız çocuğunun dizlerinde kanadım.

dipsiz kuyuların ağzına tuttum gövdemi

(anlaşılan artık yakışmıyorum deli sulara)

uyumayı kabus görmek, anıları unutmak için seçtim

eylül bitti, bütün bir yaz kim vurduya gittim.

gül değil, toprak değil, rüzgar kokuyorum.

yeni tiklerim oldu, acının arka yüzündeyim

kalbim açmazda, sarışın oynar, kumral üç hamlede mat

anlamasanız da olur, bir yalnızlığa büyüdüğümü.', 'anlamasanız da olur, sesim parçalamak içindir dudaklarımı büyük yaralardan geçtim, kız çocuğunun dizlerinde kanadım. dipsiz kuyuların ağzına...', ARRAY['Türk Edebiyatı','Şiir','Akif Kurtuluş']::text[], 8.5, '{"poet":"Akif Kurtuluş","poet_slug":"akif-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/acinin-arka-yuzundeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çardaklardan Kaçırdığım', 'cardaklardan-kacirdigim-akif-kurtulus-kk9lt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bozkırda koşan posta katarına sor mektuplarımı

ben yakalar söylerim ozanlara, birini buldum

daha kaç dört yıl senin gölgende durulanırım

yüzünün güneş almayan yanında, ağacın yosununda

gözüm güneşe dalacak kadar çocuk olurum görürsün

ilişecek pervaz arar yüzüm eylül yağmurlarında

postacının hep aradığımız ellerine sor mektuplarımı

ben yapışır söylerim ozanlara, bu aşk ansızın bitmez

eteği güneş geçiren, çocukluğu öcülerle korkutulmuş

kuşburunlu sevgilim de bilir öğrenci yatağımdayken

kasabamın gölgeliklerine çekilir, ırmaklarında sevişirim

korularında öğrenirim göğsümün rüzgar alan yanını

yol kıyısına kurulan çingene çadırına sor mektuplarımı

ben çağırır söylerim ozanlara, yoksa yitirdim mi

yine arka sokaklara, arnavut kaldırımlarına çağır

yanağımdan yangınları söndürür, küllerini kazırım

eğilir usulca öptürürüm denize, bu martılar içindir

koynumu bir dağın devrilmesine hazırlarım, bu da senin

sahil kahvesinde anlatmış kıyıda odun toplayanlar

her ikindi günbatışı moruna koşuyormuşum çıplak ayak

saçımı değdirip dalgalara, afacan yunusla düşe kalka

balıkçılar ağlarını toplarken görmüşler

o yaz akşamlarına sığmayan, çardaklardan kaçırdığım

dizlerini ezberliyormuşum mercanların dibinde', 'bozkırda koşan posta katarına sor mektuplarımı ben yakalar söylerim ozanlara, birini buldum daha kaç dört yıl senin gölgende durulanırım yüz...', ARRAY['Türk Edebiyatı','Şiir','Akif Kurtuluş']::text[], 8.5, '{"poet":"Akif Kurtuluş","poet_slug":"akif-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cardaklardan-kacirdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkindiler Kaçırır', 'i-kindiler-kacirir-akif-kurtulus-r61bg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kasabalar da ağlar, avuçlarına alıp ateşböceklerini

kızlar entarilerini yayarlar taşlık söyleşilerine

birbirleriyle dans ederler düğünlerde, öyle yalnız

esintimi gömerim toz toprak okul yollarına, yüreğimi

ateş böcekleriyle değişir yüreğim, şarkılar başlatır

kasabalar da ağlar, sığınıp vadinin serinliğine

anayı kent pavyonlarından yaralar çok çocuklu baba

rakıyı kuytu köşelerde çay bardağıyla içer

emeklilerin cep saatlerine bakışı, kanayan dudağım

vadiyle değişir dudağım, denize ırmaklar götürür

kasabalar da ağlar, sarılıp vardiya düdüğüne

alnımı akşama yaslayıp tıklarım camını

yağan her kardan sonra, yanlış evinin adresi

leblebi kavrulan sokaklar, işçi arabaları, çığlığım

vardiya düdüğüyle değişir çığlığım, ikindiler kaçırır

kasabalar da ağlar, sinip suğla gölünün kıyısına

benzin kokan minibüslerle koşarım yanına, kaçarım

oğlakların uzandığı dallarınla örtersin gözlerimi

turnalar kalkar yüzümden, girer çıkarlar güneşe

suğla gölüyle değişir yüzüm, sabahlara seslenir', 'kasabalar da ağlar, avuçlarına alıp ateşböceklerini kızlar entarilerini yayarlar taşlık söyleşilerine birbirleriyle dans ederler düğünlerde,...', ARRAY['Türk Edebiyatı','Şiir','Akif Kurtuluş']::text[], 8.5, '{"poet":"Akif Kurtuluş","poet_slug":"akif-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ikindiler-kacirir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ürkek Bir Anı Oldum', 'urkek-bir-ani-oldum-akif-kurtulus-y0ur4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-I-

hep akşamı tutar günlüklerinde yitik çocuklar, bir kızın

vücuduna serptiği ışıklarda sabahı bulmaya çalışan bir cesur

çocuk da çıkar kimi zaman. (o’nun çığlığa çalan susuşunda, 

seviştikten sonra bacaklarını karnına çekip oturuşunda, 

kalkıp perdeyi aralayışında) 

boşunadır çabası, bir cesur çocuk olarak adı hayatın yanlışları

üzerine kurulmuştur ve hiçbir şey yanlışlardan daha iyi anlatamaz o’nu.

her zaman hazır tutacaktır sevinçli yerlerine batırmak için bir dikeni

-II-

tren ayrıldı, unutuldum bir takvimin son yaprağında

kum saatinde bir ''yitik çocuk'' olarak kaldım

zaman’ın dışında yer verilmişti, ne kadar sevsem de

sevgilimin gözlerine bir leke gibi bıraktım sessizliği

yazdıklarımdan o’nun kumral hayatına sızamayacak kadar usluydum

tren ayrıldı tuttum koyu bir karanlıkta, yırttım kendimi

resim oldum, ürkek bir anı oldum, artık kim olsa kırar beni.', '-I- hep akşamı tutar günlüklerinde yitik çocuklar, bir kızın vücuduna serptiği ışıklarda sabahı bulmaya çalışan bir cesur çocuk da çıkar kim...', ARRAY['Türk Edebiyatı','Şiir','Akif Kurtuluş']::text[], 8.5, '{"poet":"Akif Kurtuluş","poet_slug":"akif-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/urkek-bir-ani-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bir Dağsın Esmer Adamların Durmadan Kazdığı', 'sen-bir-dagsin-esmer-adamlarin-durmadan-kazdigi-altay-oktem-m0ehe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir dünya varsa eğer kitapların yazdığı

babamın anlattığı doğruysa yani; öyle bir dünya

sen dışındasın hem de merkezisin bir anlamda

eğri bir biçimsin birlikte yakalandığımız

kendisiyiz hep suçlanan bir sesin

yağmurda kaybolmuş bir kedinin korkusuyuz

ya da buna benzer bir şeyiz; hiçbirşeyiz

az çekilen bir ceza gibi tırmanmıştık hayatı

anımsa; aşk uzun süren uykusuydu evcil bir kışın

ya da öyle sanmıştık; bütün suçları işledik ne güzel

şimdi güpegündüz ben bir dağı kazmaya gidiyorum

sen bir dağsın esmer adamların durmadan kazdığı

hep başkalarının kollarında seviyoruz hayatı

raydan çıkan tren ne kadar severse enkazını

o kadar. onun kadar seviyorum inan suçlarını

aşk tek kişiliktir, bütün deliler bilir sayı saymasını

ve sarılıp yatmanın anlamı yoktur kaldırımlarda

eğer fazla yaşlanmışsak bir anda. fazla ıslanmışsak

hiçbir acı dönüşmez başka bir acıya

bir dünya varsa eğer kitapların yazdığı

yırt bütün kitapları. beni sevdiğini kanıtla

yatağını açık tut bütün aşklara', 'bir dünya varsa eğer kitapların yazdığı babamın anlattığı doğruysa yani; öyle bir dünya sen dışındasın hem de merkezisin bir anlamda eğri bi...', ARRAY['Türk Edebiyatı','Şiir','Altay Öktem']::text[], 8.5, '{"poet":"Altay Öktem","poet_slug":"altay-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-bir-dagsin-esmer-adamlarin-durmadan-kazdigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklar Tekin Değil', 'sokaklar-tekin-degil-altay-oktem-8awn6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yüzüme sevgi dolu

bakarken canımı acıtıyorsun, sokaklar tekin değil

kuytu bir köşe bile bırakmadılar bize

rasgele işlenen cinayette tek ipucu sözlerin

onlar da konuştukça kusmuk gibi dilinde

sokaklar tekin değil, hava soğuk, üşürsün

yün eldiven tak, parmak izin bulaşmasın kente

haydi son kez sevişelim o yanlış evlerde

o trenin vagonuna asalım derimizi

nazlanma; yanlış bir adres daha ver bana

bak bir elmanın tombul kurdu gibiyiz

kırık bir şemsiyenin sapı gibiyiz senle

yüzüme sevgi dolu

bakma; içimden silah sesleri geliyor

bir adam bir sancıyı kudurtuyor içimde

sokaklar tekin değil, zar tutarken hırpalanan biri var

büyük bir ihtimalle

bir güle ceza veren yeniyetme çocukları

olur olmaz yerlerde öldürmekten yoruldum

olduğun gibi gel, olduğun yerde soyun! 

yani terli ve kırışık, yani solgun ve kirli

yani tuzlu bir gölde biriken cesetler gibi

benim dilim yetmez diye delileri topladım

yalamaya hazırız çürüyen yerlerini

yüzüme sevgi dolu

bakarken canımı acıtıyorsun, sokaklar tekin değil

iyisi mi kendine çevir dur

tüm serseri mermileri', 'yüzüme sevgi dolu bakarken canımı acıtıyorsun, sokaklar tekin değil kuytu bir köşe bile bırakmadılar bize rasgele işlenen cinayette tek ipuc...', ARRAY['Türk Edebiyatı','Şiir','Altay Öktem']::text[], 8.5, '{"poet":"Altay Öktem","poet_slug":"altay-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sokaklar-tekin-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından', 'ardindan-aydin-ozturk-az0vl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'giderken

gözlerin

iki paslı çiviydi

çakıldı yüreğime', 'giderken gözlerin iki paslı çiviydi çakıldı yüreğime...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ardindan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaz Bir Ankara Gecesinde', 'ayaz-bir-ankara-gecesinde-aydin-ozturk-zdy92', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yapraksız dallarına ışıklar giymiş

ağaçlarla göz gözeyken

nasıl da düştün aklıma böyle

yankılanıp yamaçlardan büyüyerek

ayaz bir ankara gecesinde', 'yapraksız dallarına ışıklar giymiş ağaçlarla göz gözeyken nasıl da düştün aklıma böyle yankılanıp yamaçlardan büyüyerek ayaz bir ankara gece...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayaz-bir-ankara-gecesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın', 'ayriligin-aydin-ozturk-r4s4o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ayrılığın

güncemdir

her gün

yenisini

yazdığım', 'ayrılığın güncemdir her gün yenisini yazdığım...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayriligin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çığ Sökün Eder de', 'bir-cig-sokun-eder-de-aydin-ozturk-5ud6b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hep tanımlamak istedim

onlar geçerken önümden

içimdeki umutlara çizilen coşkularını

sanki dağlar kıpırdanır yerinden

bir çığ sökün eder de

yürür ayazlarda sesime', 'hep tanımlamak istedim onlar geçerken önümden içimdeki umutlara çizilen coşkularını sanki dağlar kıpırdanır yerinden bir çığ sökün eder de y...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-cig-sokun-eder-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
