INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-hafize-zuluflu-ulcwa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen

Derin uykularımda

Rüyalarıma giren

Günahlarımsın

Göze aldığım

Sen

Apansız yoluma çıkan

Yasaklarımsın

Hiçe saydığım

Sen

Karasevdamsın

Önünde dize geldiğim', 'Sen Derin uykularımda Rüyalarıma giren Günahlarımsın Göze aldığım Sen Apansız yoluma çıkan Yasaklarımsın Hiçe saydığım Sen Karasevdamsın Önü...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-172-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza Dek', 'sonsuza-dek-hafize-zuluflu-sf8kh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzne kesmiş akşam

Yokluğun düşmüş

Yorgun gönlüme

Rüyalarım çaresiz

Hasretinleyim

Bilir misin senden dolayı

Ben hasretini de severim

Yumak yumak sarıp

Bir çekişte bitirdiğim

Günleri

Teslim edip zamana

Seni

Sonsuza dek beklerim', 'Hüzne kesmiş akşam Yokluğun düşmüş Yorgun gönlüme Rüyalarım çaresiz Hasretinleyim Bilir misin senden dolayı Ben hasretini de severim Yumak y...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sonsuza-dek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beterin Beteri', 'beterin-beteri-hafize-zuluflu-vb319', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzağında değilim

Düşen yağmurla

Saçının telindeyim

Sana tutsak yüreğim

Ki o kadar yakınında

Avucunda elindeyim

Can acıda sevdalarda

Sensiz

Beterin beterindeyim', 'Uzağında değilim Düşen yağmurla Saçının telindeyim Sana tutsak yüreğim Ki o kadar yakınında Avucunda elindeyim Can acıda sevdalarda Sensiz B...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beterin-beteri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim', 'duslerim-hafize-zuluflu-bdf9i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İğnelendi uykularım

Dar geçitlerinde hasretin

Seni aradı bütün hücrelerim

Yokluğunda acı çekti 

Bedenim

Başkaldırdı duygularım

Aştı mesafeleri

Gelip kapına dayandı

Baş eğmedi yasaklara

Alabildiğine özgür

Alabildiğine deli

Yaşandı düşlerim', 'İğnelendi uykularım Dar geçitlerinde hasretin Seni aradı bütün hücrelerim Yokluğunda acı çekti  Bedenim Başkaldırdı duygularım Aştı mesafele...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duslerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyana Geleceğim', 'ruyana-gelecegim-hafize-zuluflu-fo9te', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arala uykularını

Rüyana geleceğim

Bu gece

Sabaha karşı sar

Beni yüreğine

Sev yeter ki

Tuzağına düşeceğim

Gizlice

Kırbaçla gönül atını

Saçlarıma tak yıldızları

Avuçlarımda unut sıcaklığını

Senin olacağım

Bu gece', 'Arala uykularını Rüyana geleceğim Bu gece Sabaha karşı sar Beni yüreğine Sev yeter ki Tuzağına düşeceğim Gizlice Kırbaçla gönül atını Saçlar...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruyana-gelecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felsefe', 'felsefe-hafize-zuluflu-5dbgz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşünmekse var olmak

Ya da var olmaksa düşünmek

Sen bendesin

Ben sende varım', 'Düşünmekse var olmak Ya da var olmaksa düşünmek Sen bendesin Ben sende varım...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/felsefe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Vurduk', 'aski-vurduk-hafize-zuluflu-arbqd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İkimiz aynı kutupta

Gittikçe uzaklaştık

Yan yana

Gülücükler arkasına

Saklarken kırgınlıkları

Yüreğimiz acıdı

İkimiz bir olup

Aşkı rüzgara savurduk

O vapurda

Hasretin yerine

Aşkı vurduk İstanbul’da..', 'İkimiz aynı kutupta Gittikçe uzaklaştık Yan yana Gülücükler arkasına Saklarken kırgınlıkları Yüreğimiz acıdı İkimiz bir olup Aşkı rüzgara sa...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aski-vurduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Alarm', 'sari-alarm-hafize-zuluflu-op3wd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana bu yakışır

Üstüme üstüme

Yolla yokluğunu

İnadına arama

Ez hırpalama yüreğimi

Ellere ver, yollara ver

Unut gitsin adımı

Bir gün

Dönüp geldiğinde

Şüphesiz yüzüne kapanmayacak

Kapım

Ama belki

Ben seni

Hatırlamıyor olacağım', 'Sana bu yakışır Üstüme üstüme Yolla yokluğunu İnadına arama Ez hırpalama yüreğimi Ellere ver, yollara ver Unut gitsin adımı Bir gün Dönüp ge...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sari-alarm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmeli', 'gelmeli-hafize-zuluflu-8j7wn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir “ben” var bende, 

Benden ayrı

Biraz isyankar

Biraz deli

Laftan anlamıyor

Hasreti mahkum etti

Müebbete

Gelmeli diyor

Gelmeli...', 'Bir “ben” var bende,  Benden ayrı Biraz isyankar Biraz deli Laftan anlamıyor Hasreti mahkum etti Müebbete Gelmeli diyor Gelmeli......', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gelmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevdiğim', 'benim-sevdigim-hafize-zuluflu-hgu2r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim sevdiğim

Gözü kara benim gibi

Biraz da deli

Yüreğimin sessizliğine

Kulak verip taa

Uzaklardan

Bir gece vakti

(zamansız)

Çıkıp gelivermeli', 'Benim sevdiğim Gözü kara benim gibi Biraz da deli Yüreğimin sessizliğine Kulak verip taa Uzaklardan Bir gece vakti (zamansız) Çıkıp geliverm...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/benim-sevdigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceza', 'ceza-hafize-zuluflu-r2a7f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Katıksız hücre cezasına 

Çarptırıldı yüreğim

Sanık

Sevmekten sizi

Şimdi

Karanlıklara yansıyan

Yalnızlığımın sesi

Yıldızlı aydınlığında gecelerin

Sevişen sevdalılara düşman

Sayısız cezalara çarptırılsa da

Ele vermez

Şüphesiz gözlerinizi

Uçsuz bucaksız sonsuzluğunda

Evrenin

Siz değilsiniz veren

Bana sevginizi

Ben layık gördüm

Kendime zat-ı alinizi', 'Katıksız hücre cezasına  Çarptırıldı yüreğim Sanık Sevmekten sizi Şimdi Karanlıklara yansıyan Yalnızlığımın sesi Yıldızlı aydınlığında gecel...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ceza-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Öfkeli', 'sana-ofkeli-hafize-zuluflu-ad2ix', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçinden geçeceğim belli belirsiz

Düşüncelerinin

Yıldızlar anlamını yitirecek

Yokluğumu içeceksin yudum

Yudum gecede

Suskun yüreğin, suskun dilin

Bir geceye, bir bardağa

Bakıp delice

Yağmursuzluğu saracaksın

O koca şehirde ben diye

Hasret kalacak ellerin

Saçlarımın her bir teline

Ve

Ben sana deli

Sana öfkeli

Seni düşünüyor

Olmayacağım', 'İçinden geçeceğim belli belirsiz Düşüncelerinin Yıldızlar anlamını yitirecek Yokluğumu içeceksin yudum Yudum gecede Suskun yüreğin, suskun d...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-ofkeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytana Uy', 'seytana-uy-hafize-zuluflu-d3fxo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ay uyurken suda

Bir esinti duyarsan

Kuytuda

Durma şeytana uy

Çal beni geceden

Acıt canımı

Bil ki bu esen

Başımda sevda

Aklımda sevgilidir

İşte bu rüzgar

Seni sevdiğimin

Resmidir', 'Ay uyurken suda Bir esinti duyarsan Kuytuda Durma şeytana uy Çal beni geceden Acıt canımı Bil ki bu esen Başımda sevda Aklımda sevgilidir İş...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seytana-uy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-hafize-zuluflu-szi63', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklaştığın o yolda

Yalnızlığım dönüyor

Seni yürüyorum kendimle

El ele kaldırımlarda

Rüzgarını yürüyorum

Denizinizi yudumluyorum

Gecelerde

Her zamankinden

Çok seviyorum seni

İstanbul', 'Uzaklaştığın o yolda Yalnızlığım dönüyor Seni yürüyorum kendimle El ele kaldırımlarda Rüzgarını yürüyorum Denizinizi yudumluyorum Gecelerde ...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizligim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Uyur', 'dusler-uyur-hafize-zuluflu-y7d82', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yenik düşer geceye

Düşe dalar uykular

Alır başını gider

Yalnızlığım

Düşler uyur

Sevdalar büyür', 'Yenik düşer geceye Düşe dalar uykular Alır başını gider Yalnızlığım Düşler uyur Sevdalar büyür...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dusler-uyur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eryaman’da', 'eryaman-da-hafize-zuluflu-b8zmy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yağmur bastırır

Aniden

Aklına düşerim

Her damlada

Sen sevdadan sırılsıklam

Yağmurlara bile

Söyleyemezsin adımı

Sensizliği dörde katlarım

Eryaman’da

Ben bu yaz akşamında...', 'Bir yağmur bastırır Aniden Aklına düşerim Her damlada Sen sevdadan sırılsıklam Yağmurlara bile Söyleyemezsin adımı Sensizliği dörde katlarım...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eryaman-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Bıraktın', 'sevda-biraktin-hafize-zuluflu-6y6um', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçmiş zamanlardan

Ayak izlerin

Kaldırımlarda

Aynada bakışların

Gecede sıcaklığın

Bana canımdan yakın

Sevda bıraktın', 'Geçmiş zamanlardan Ayak izlerin Kaldırımlarda Aynada bakışların Gecede sıcaklığın Bana canımdan yakın Sevda bıraktın...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevda-biraktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-hafize-zuluflu-wehb7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söküp yerinden yüreğimi

Fırlatıp atsam

Bir taş gibi

Vazgeçer miydim

Sevmekten seni

Can terketmeyince bedeni', 'Söküp yerinden yüreğimi Fırlatıp atsam Bir taş gibi Vazgeçer miydim Sevmekten seni Can terketmeyince bedeni...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bilmiyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Gittin', 'yine-gittin-hafize-zuluflu-152il', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gittin o gidiş

Hüzünlere terkettin

Yüreğimi

Ne geldin

Ne de selam

Gönderdin

Yine gecelere verdin

Beni', 'Gittin o gidiş Hüzünlere terkettin Yüreğimi Ne geldin Ne de selam Gönderdin Yine gecelere verdin Beni...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yine-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceydi', 'geceydi-hafize-zuluflu-l8r75', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana geldim

Aklımda anılar

İçimde özleminle

Geceydi

Saçlarımda inciler

Yıldızlar gözlerimdeydi', 'Sana geldim Aklımda anılar İçimde özleminle Geceydi Saçlarımda inciler Yıldızlar gözlerimdeydi...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/geceydi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Nasıl Sensizlik', 'bu-nasil-sensizlik-hafize-zuluflu-znes9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve

Yine

Giderken sen

Yokluğundu bakışlarımda

Yüreğim alev alev

İçimde fırtınalardı

Kocaman bir boşluk

Ardında

Bir hasret

Bir de anılardı

Bu nasıl acı

Bu nasıl sensizlik

İçimde yanan

Sevda değil

Aslılardı...', 'Ve Yine Giderken sen Yokluğundu bakışlarımda Yüreğim alev alev İçimde fırtınalardı Kocaman bir boşluk Ardında Bir hasret Bir de anılardı Bu ...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-nasil-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizi Diledim', 'sizi-diledim-hafize-zuluflu-g706m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gece önceydi

Sizi diledim

Yedi tepeden

Gözlerimi bir kapayışta

Geliverdiniz

Bir düş mola verdi

Bedenimizde

Nefeslendi ayrılık

Ve 

Biz gece boyu

Seviştik

Yoksa sevdiğim

Siz hep

Bende miydiniz', 'Bir gece önceydi Sizi diledim Yedi tepeden Gözlerimi bir kapayışta Geliverdiniz Bir düş mola verdi Bedenimizde Nefeslendi ayrılık Ve  Biz ge...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sizi-diledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Harp Gemileri', 'simdi-harp-gemileri-hafize-zuluflu-jxg9q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soyutla benden kendini

Giyin “öfke” zırhını

Saklan zavallı biri gibi

Kışkırt hasreti

Çevir üzerime dünyanın

Bütün gelişmiş silahlarını

Ben

Karşı koysam da

Bütün gücümle

Kendime yenileceğim

Nasıl olsa

Şimdi harp gemileri

Geçiştedir boğaz’da..', 'Soyutla benden kendini Giyin “öfke” zırhını Saklan zavallı biri gibi Kışkırt hasreti Çevir üzerime dünyanın Bütün gelişmiş silahlarını Ben K...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/simdi-harp-gemileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yağacağım', 'ben-yagacagim-hafize-zuluflu-96h7t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yağmurları düşün

Yağmurları dinle

Derinliğinde sessizliğin

Sarıl damla damla

Düşen acılara

Sokul hatta

Yağmurun koynuna

Ilık bir düş gibi

Yana yakıla

Nasıl olsa

Ben yağacağım

Her damlada aklına', 'Sen yağmurları düşün Yağmurları dinle Derinliğinde sessizliğin Sarıl damla damla Düşen acılara Sokul hatta Yağmurun koynuna Ilık bir düş gib...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-yagacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam Samanyolu’nda', 'sevdam-samanyolu-nda-hafize-zuluflu-80d4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ateş yaktım

Aşka dair

Solgun bir mum ışığında

Üfledim bir orman kuytusuna

Bir şarkı fısıldadım

Rüzgarın kulağına

Geçip ağaçtan ağaca

Getirsin diye sana

Sakladım sevdamı yıldızlara

Sana göz kırpar her gece

Samanyolu’nda', 'Bir ateş yaktım Aşka dair Solgun bir mum ışığında Üfledim bir orman kuytusuna Bir şarkı fısıldadım Rüzgarın kulağına Geçip ağaçtan ağaca Get...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdam-samanyolu-nda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmamış Anılar', 'yasanmamis-anilar-hafize-zuluflu-0e1mf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vur

O hançer parıltılı

Bakışlarınla canımı

O zaman belki diner

Yaramın acıları

Bu sevdaya sığmaz

Yaşanan yasakların sırları

Deler geçer günahları

Beni sana bağlayan

Sevgimin görünmez bağları

Almış arkasına

Tüm yürekliliğiyle

Aşkın rüzgarını

Sana uçurur

Başı boş yollarda

Yaşanmamış anıları', 'Vur O hançer parıltılı Bakışlarınla canımı O zaman belki diner Yaramın acıları Bu sevdaya sığmaz Yaşanan yasakların sırları Deler geçer güna...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasanmamis-anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun başı', 'yolun-basi-mustafa-ozke-h31g2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'iki yılım geçti

kızım mina ile

ağladı güldü

açtı soldu

iki yılım değişti

kızım mina ile

ağladım güldüm

açtım soldum

ben yeniden doğdum

ben de iki yaşındayım

kızım mina ile

daha yolun başındayım', 'iki yılım geçti kızım mina ile ağladı güldü açtı soldu iki yılım değişti kızım mina ile ağladım güldüm açtım soldum ben yeniden doğdum ben d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yolun-basi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-hakki-hakan-kaya-dipy9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kömür gözlerin yakıyor gönlümü

En deli rüzgarlar bile söndürmüyor

Bu ayrılık özletiyor bana ölümü

Görmeyince seni can çekilmiyor

Tabiplerin kifayetsiz kalır merhemi

Hiç kimseler çare bulamaz yarama

Yoktur bu dünyada derdimin çaresi

Yarimden başka, gayri ötesini arama

Sarı saçların kalem olur rüyada

İçimdeki sevdamı nasıl yazayım

Bir hayalim şu gerçek dünyada

Aşk elinde kırık gönül sazıyım', 'Kömür gözlerin yakıyor gönlümü En deli rüzgarlar bile söndürmüyor Bu ayrılık özletiyor bana ölümü Görmeyince seni can çekilmiyor Tabiplerin ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezsin', 'bilemezsin-hakki-hakan-kaya-hgbxq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her boşluğa adım atışımda sana, 

Biraz daha yaklaştığımı bilemezsin.

Mavi gözlerle her bakışında bana, 

Yeniden yaşadığımı, bilemezsin.

Geçmiş zamanı çeksemde sineye, 

Razıyım elinden ağu yemeye, 

Sarılıp sarılıpta beyaz geceye, 

Ecelimle yattığımı, bilemezsin.

Parçaladı sevdan göğsümü yine, 

Bu acı döndürdü beni deliye, 

Hislerime tercuman olan yok diye, 

Ruhumu sattığımı, bilemezsin.

Derdi olupta devasız yatana, 

Aşkı mal sanıpta çarşıda satana, 

Seveni, sevdayı alaya katana, 

Yolunu verdiğimi, bilemezsin...', 'Her boşluğa adım atışımda sana,  Biraz daha yaklaştığımı bilemezsin. Mavi gözlerle her bakışında bana,  Yeniden yaşadığımı, bilemezsin. Geçm...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilemezsin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısmet', 'kismet-hakki-hakan-kaya-ju9d6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni deliler gibi sevdiğini söylüyorsun, 

Ama sevmek ve sevilmek kısmet güzelim.

Sensiz bu dünyada yaşayamam diyorsun, 

Ama yaşamak ve ölmek kısmet güzelim.

Ben hayranım eskiye, nedir bu rağbet yeniye, 

Suya attığım güller, dönermi bir gün geriye, 

Al kalbimi diyorsun, buda benden hediye, 

Ama almak ve vermek kısmet güzelim.

Dolu dolu yaşamış, dolu dolu gülmüşüm, 

Kah gökte uçmuş, kah yerde sürünmüşüm, 

Yedi cihanı gezmişte, bir tek şey bilmişim, 

Hatırlanmak ve unutulmak kısmet güzelim.

Söylediğim sözler, yayılırmı cihana, 

Senin sıcak gözlerin, merhem olmaz yarama, 

Elbet bu bedende toprak olacak ama, 

Cennet yada cehennem kısmet güzelim.', 'Beni deliler gibi sevdiğini söylüyorsun,  Ama sevmek ve sevilmek kısmet güzelim. Sensiz bu dünyada yaşayamam diyorsun,  Ama yaşamak ve ölmek...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kismet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-fatma-pamukcu-55d1b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayallerim vardı

Mutluluk için, aşk için

Ümitlerim vardı

Gelecek için, ikimiz için

Hayallerimden geri kalan

Kırık bir kalp ve gözyaşları

Her damla gözyaşından geri kalan

Yeni bir acı ve tükeniş

Çok sevdim ve seveceğim

Sevilmesem de seveceğim

Özlenmesem de özleyeceğim

Seni ebediyen kalbimde saklayacağım

Gündüz güneşin sıcaklığında buldum seni

Gece yıldızların parlaklığında

Sanki her an sen varsın yanımda

Gece rüyalarımda

En güzel duyguları seninle yaşadım

En büyük acıları da

Aşkın güzelliği senin olsun

Acılar, hüzünler benim

Sevgi sensin, aşk sensin

Senden sonrası olmayacak

Sen konuşmasan da

Benim kalbim hiç susmayacak

Seviyorum, seveceğim...

(11.08.2002 - 21.50)', 'Hayallerim vardı Mutluluk için, aşk için Ümitlerim vardı Gelecek için, ikimiz için Hayallerimden geri kalan Kırık bir kalp ve gözyaşları Her...', ARRAY['Türk Edebiyatı','Şiir','Fatma Pamukçu']::text[], 8.5, '{"poet":"Fatma Pamukçu","poet_slug":"fatma-pamukcu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ask-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Benim', 'canim-benim-fatma-pamukcu-d437n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün yine özlemlerimin doruğundaydım, 

Ulaşabilsem demiştim o mahmur gözlerine, 

Evet, seviyorum diyebilmeme bir daha

İstemiştim gözlerimle anlatmaya, 

Ne güzel baktın gözlerime başını kaldırarak istekle, 

Hoşgeldin dediğin sesin yankılandı kalbimde

Heyecanlıydım yine ilk günkü karşılaşmamız gibi

Sanki Seni Sevmeden yaşayamam dercesine

Aynı frekanslardaydık kalbimizle, 

Eline dokunmak istedim, ''hayır'' dedin o titrek sesinle

Espriydi tabii ki ben de öyle anladım

Yüzüme bakmadan, bana sırtın dönük 

Küçük çocuğun utangaçlığyla birtanem, 

Üşüyorum dedin ve diyorsun

Ama ben daha fazla donmaktayım

Bunu anlatabilmek kolay aslında

Sana sarılarak ''SENİ SEVİYORUM''

Kulağına sıcak fısıltılarla ulaşmak, 

Ama eğildim, fısltılarla diyemedim, 

Evet şimdi diyorum; 

ve  ''seni çok  seviyorum''.

(Fatoşuma -16 Kasım 2001)', 'Dün yine özlemlerimin doruğundaydım,  Ulaşabilsem demiştim o mahmur gözlerine,  Evet, seviyorum diyebilmeme bir daha İstemiştim gözlerimle a...', ARRAY['Türk Edebiyatı','Şiir','Fatma Pamukçu']::text[], 8.5, '{"poet":"Fatma Pamukçu","poet_slug":"fatma-pamukcu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/canim-benim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimsin', 'kalbimsin-fatma-pamukcu-46x1h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ulaşamamak ne denli zor, 

Bana öğretmek istediğin, 

Halbuki bunu  çok iyi biliyorum, 

Çünkü seni çok seviyorum.

Seni düşlemek çok güzel, 

Bana göstermek istediğin, 

Yaşıyorum bunları sürekli

Çünkü seni çok seviyorum.

Gözlerini ezberledim, beynimde, 

Görememek ızdırap her saniye, salise, 

Özlüyorum kahverengi anlatımlarını, 

Çünkü seni çok seviyorum.

Kolların anlatıyor, sarılırcasına hayalimde, 

Rüyalarımı hep onlar süslesin, sıcaklığıyla, 

Bekliyorum düşlerimi sırılsıklam, yokluğunda, 

Çünkü seni çok seviyorum.

Özlüyorum renklerini kırmızı, bordo sıcaklığında, 

''Aşkım benim'' dercesine, sana yardımcı olduklarını, 

Sanki herşey hep seni anlatıyor  boğazımdaki acı bile, 

Çünkü seni çok seviyorum.

''Senin İçin Aşkım '' yakarışların hala kulaklarımda, 

Hiçbir zaman sönmeyecek bu çınlamalar, 

Gözyaşlarım hep seni ağlıyor içimde, 

Gözyaşlarına düğümlenen........

''Herşeye Rağmen Seni Çok Seviyorum''

Bitanem.......................... Fatoşuma

(04/08/2002 - 22.12)', 'Ulaşamamak ne denli zor,  Bana öğretmek istediğin,  Halbuki bunu  çok iyi biliyorum,  Çünkü seni çok seviyorum. Seni düşlemek çok güzel,  Ba...', ARRAY['Türk Edebiyatı','Şiir','Fatma Pamukçu']::text[], 8.5, '{"poet":"Fatma Pamukçu","poet_slug":"fatma-pamukcu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kalbimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün Yemekte Aşk Var!', 'bu-gun-yemekte-ask-var-cigdem-simsek-pxkz1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşka aç ruhunla gel, 

Gel dinle beni...! ! 

Ruhunu hiç bir zaman doyuramazsın! 

Gümüş tepsilerde sunulmuş aşkı, 

Çatal kaşıkla mı yiyeceksin? 

Bırak kibarlığı! 

Sıva kollarını! 

Avuçla aşkı her tarafından...', 'Aşka aç ruhunla gel,  Gel dinle beni...! !  Ruhunu hiç bir zaman doyuramazsın!  Gümüş tepsilerde sunulmuş aşkı,  Çatal kaşıkla mı yiyeceksin...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-gun-yemekte-ask-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal...', 'masal-cigdem-simsek-ddkxq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşadığımız her şey; 

Hayatlarımız, sevdalarımız... 

Bir masal! 

Anlatılır, dinlenir ve biter. 

Önemli olan bittikten sonra, , 

Aklımızın damağında kalan tatdır. 

Bir masal prensi gibi, 

Sür atını dört nala... aşka! 

Gel! gökyüzünde pamuktan yatağımızda, 

Yer yüzünü seyrederken, 

Uzan kollarıma... 

Hiç bitmeyecekmiş gibi sana, 

Sevdamın masalını anlatayım...', 'Yaşadığımız her şey;  Hayatlarımız, sevdalarımız...  Bir masal!  Anlatılır, dinlenir ve biter.  Önemli olan bittikten sonra, ,  Aklımızın da...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/masal-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün', 'birgun-sair-eftelya-j7tlj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birgün

Hergün ağlattığın şu gönlümü

gözlerin yaşlı arayacaksın birgün

sana sunduğum tertemiz sevgimi

yıllar sonra özleyeceksin birgün

Hergün penceremde seni bekleyeceğim

hasretime bin hasret ekleyeceğim

sensiz akşamlarda gözyaşı dökeceğim

sen de benim için ağlayacaksın birgün

Yıllar sonra pişman olup döneceksin

geldiğinde bir yığın hatıra bulacaksın

gözünde yaşlar mezarımı soracaksın

ayrı geçen günlerimize yanacaksın o gün

(Ankara 1979)', 'Birgün Hergün ağlattığın şu gönlümü gözlerin yaşlı arayacaksın birgün sana sunduğum tertemiz sevgimi yıllar sonra özleyeceksin birgün Hergün...', ARRAY['Türk Edebiyatı','Şiir','Şair Eftelya']::text[], 8.5, '{"poet":"Şair Eftelya","poet_slug":"sair-eftelya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/birgun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-sair-eftelya-m06fe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiliye

Ağlamak, hasret kaldığım güzel endam için

en büyük saadettir virane gönlüm için

karanlık sevda deryasında bir tek ışık için

yıllarca ümitle beklemek kolay mı bilmem...

(Ankara 1979)', 'Sevgiliye Ağlamak, hasret kaldığım güzel endam için en büyük saadettir virane gönlüm için karanlık sevda deryasında bir tek ışık için yıllar...', ARRAY['Türk Edebiyatı','Şiir','Şair Eftelya']::text[], 8.5, '{"poet":"Şair Eftelya","poet_slug":"sair-eftelya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevgiliye-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hatırlarım', 'seni-hatirlarim-sair-eftelya-bre2c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni Hatırlarım

Seni hatırlarım yapayalnız hasretinle inlerken

seni hatırlarım tanrıdan mutluluk dilerken

Seni düşünürüm uzaklardan bir hüzünlü ses gelse

seni düşünürüm ahu gözler bir yerde sevdiğine gülse

Yokluğun bir volkan hüsran dolu gönlümde

yaşamak ölmek gibi sensiz dünyamda

Seni hatırlarım ovalarda rüzgarlar estiği an

seni hatırlarım bahçede bülbüller sustuğu an

Seni ararım hayalin gözlerimden kaybolurken

seni beklerim sonbaharda yapraklar savrulurken

Birgün gelecek herşey hayal olup gidecek

biliyorum giden sevgililer dönmeyecek...

(Ankara 1979)', 'Seni Hatırlarım Seni hatırlarım yapayalnız hasretinle inlerken seni hatırlarım tanrıdan mutluluk dilerken Seni düşünürüm uzaklardan bir hüzü...', ARRAY['Türk Edebiyatı','Şiir','Şair Eftelya']::text[], 8.5, '{"poet":"Şair Eftelya","poet_slug":"sair-eftelya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-hatirlarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım İsyandır Benim', 'askim-i-syandir-benim-nurullah-genc-yo2re', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yanarım; öyle bakma yüzüme yağmur gibi

dağıt kalbini saran hasret bulutlarını

parlasın gözlerinde sonsuzluk usaresi

dalgınlık evlerinin en güzel melikesi

sevemem, tozlu raflar arasına girmeden

çöllerim kandır benim

sevemem,  karanlığı bir daha devirmeden

aşkım  isyandır benim', 'yanarım; öyle bakma yüzüme yağmur gibi dağıt kalbini saran hasret bulutlarını parlasın gözlerinde sonsuzluk usaresi dalgınlık evlerinin en g...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askim-isyandir-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-sair-eftelya-ahg4b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derin uğultularla esme bugün

bütün fırtınalar dinsin gönlümde

bak inleyen ağaçlara

bak savrulan yapraklara

herbiri halinden şikayetçi

ayırıp onları atma uzaklara.

Anlıyorum senin derdin başka

hasret kalmışsın aradığın aşka

hep koşuyorsun ağlayarak

bazan ovalarda, bazan vadilerde çağlayarak.

Ne olur rüzgar esme bugün 

inleme yeter penceremin önünde

gönlümdeki fırtınayı bilmiyorsun

istiyorum susmanı, dinmiyorsun.

Gün gelecek hep eseceksin durmaksızın

mezarımı dolanacaksın yorulmaksızın

selvileri sallayacaksın, duyacağım

sen estikçe ben rahat uyuyacağım...

(Ankara 1979)', 'Derin uğultularla esme bugün bütün fırtınalar dinsin gönlümde bak inleyen ağaçlara bak savrulan yapraklara herbiri halinden şikayetçi ayırıp...', ARRAY['Türk Edebiyatı','Şiir','Şair Eftelya']::text[], 8.5, '{"poet":"Şair Eftelya","poet_slug":"sair-eftelya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ruzgar-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabus', 'kabus-damla-calisir-8l5w7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başım çatlıyor..

ıssız odamda kabus mırıltıları..

Beklenmedik bir çığlık gibi kulağumu tırmalıyor

Yanıbaşımda yanan mumun titrek alevi

Ürpertiyor beni bu gece

Etrafa bir sis yayıyor büyüyü bozarcasına

Karanlığın gizli masumluğundan yardım istiyorum

Duymuyor beni

Besbelli gecenin içinde kaybetmiş kendini

Titremeye başlıyorum korkudan mıdır bilmem

Aynı bitmekte olan mumun alevlerini belirsizce savurduğu gibi..

Avaz avaz bağırmak istiyorum 

oLmuyor..

Ya ben bağıramıyorum

Yada kimse duyamıyor

Yan odadaki saatin tik taklarımı hızlanıyor ne

Issızlığı delmek istercesine..

Akreple yelkovan delice yarışıyor gibi

Zaman durmak bilmiyor

sıcak daha bir yoğunlaşıyor sanki

Kabusun üstünlüğünü onaylar gibi

Göz yaşlarım dudaklarımı ıslatıyor..

Geceden utanıp saklamaya çalışıyorum gözyaşlarımı

Ben sakladıkça daha bi ortaya çıkıyor

Yanaklarımdan kayıp gidiyor yetişemiyorum

Damlaların berraklığı odamı aydınlatıyor

Gözlerimi kamaştırırcasına

Siste dağılıyor gitgide

Mum bitmiş bile

Alevleri son titremelerini yaşıyor

Bitti bitecek kabusum gibi

Saate bakıyorum 

Akreple yelkovan nefes nefese kalmışçasına yerinde sayıyor

Tik takların yerini kalp atışlarım alıyor

Sessizliği yarıyor kalbimin heyecanlı çırpınışları

Penceremi aralayan rüzgar

Hayatı fısıldıyor tekrar bana

Islanmış dudakların en sevdiğim şarkıyı mırıldanıyor

Gecenin son nefesinde

Ölümün asiliği terkediyor beni

Alacakaranlığın huzurunda kaybediyorum kendimi..

                   (12.07.2000 tekirdağ)', 'Başım çatlıyor.. ıssız odamda kabus mırıltıları.. Beklenmedik bir çığlık gibi kulağumu tırmalıyor Yanıbaşımda yanan mumun titrek alevi Ürper...', ARRAY['Türk Edebiyatı','Şiir','Damla Çalışır']::text[], 8.5, '{"poet":"Damla Çalışır","poet_slug":"damla-calisir","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kabus-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstediğim', 'i-stedigim-damla-calisir-w04v8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sus artık! 

Duymak sitemiyorum

Kenetle dudaklarını birbirine

Birdaha açmazcasına

Pembe bulutlar yok artık

Öpüşen balıklarımda öldüler

Melekler ağlamıyor artık bizim için

Sen ne dersen de 

Meleklerin gözyaşlarını gizleyecek saçlarıda yoktur zaten

Sus konuşma diyorum sana

Küçük şeytanın gidiyor hiç olmadığı  tutsaklıklara..

Senden artan zincirler saçılıyor

Zincirlerinide seni de istemiyorum..

Özgürlük kokusu ciğerlerimi dolduruyor

Bi nefes daha

Bi nefes..

Küçük mutluluklar sarıyor her bir yanımı

Yeni yaşamalar yeni haykırışlar aldatıyor ruhumu..

Öpülmemiş dudaklarda dansetme arzusu..

Gencecik bir ruhun delice tutkusu

Tıpkı bir kelebek gibi uçup gitmek buralardan

O kısacık ömrü yaşamak doyasıya

Yeni sularda kayıp gitmek uçarcasına

Gökyüzünün maviliğinde süzülmek kaybolmuşçasına

..ve

Ve aniden yudumlamak aşkı 

İlk yudumda sarhoş olmuşçasına

Tek istediğim bu..

                 (12.07.2000 tekirdağ)', 'Sus artık!  Duymak sitemiyorum Kenetle dudaklarını birbirine Birdaha açmazcasına Pembe bulutlar yok artık Öpüşen balıklarımda öldüler Melekl...', ARRAY['Türk Edebiyatı','Şiir','Damla Çalışır']::text[], 8.5, '{"poet":"Damla Çalışır","poet_slug":"damla-calisir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Topla Gözyaşlarını Kaldırımlardan', 'topla-gozyaslarini-kaldirimlardan-semih-tanriver-tae3u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerin mi titredi, yüreğin mi. 

Umutlarımı vurmaya çalıştığın silahın kabzası sevgiden mi yoksa. 

Beni yine öldüremedin, kalamadın pişmanlıklarınla sevdiceğim. 

Hasrettin ellerine değdiğimde tutuşmaya, 

Muhtaçtın sevdama, sana dair her cümlenin sonuna uluorta öpmelerinle nokta koymaya. 

Yine döndün bana. 

Dönmedi yüreğim ihanetin kırmızısına, 

Yalnızlık ilmeğini geçiremedim boynuma, kabullenemedim asla bir başınalığımı 

Sarkaçlı saatimin tik taklarıyla birlikte geçip gidiverdi hüzünlerim Vuslatı andıkça. 

Saksısını yitirmiş bir sardunya olmadım asla 

Gitmelerin dönmelerin eksiltmedi sevdamı, alıştırıvermişim yüreciğimi ister istemez 

Düşlerimi, hayallerimi budayamadı o gül makası uzak kalışların, arayışların 

Ağlama ne olur kaldır başını 

Mahalleye yıldızsız çöküveren geceler utanmadı kendinden, yalnızlığımı götüremediğinden. 

Sende utanma kendinden tabularımız olmadı ki asla 

Emindim, işte yine bana döndün sevdiceğim. 

Yorgun teknelere takılıp kalmışken, özdeşleştiriyorken kendimi, azgın dalgalarla seni 

Döndün işte alabildiğine muhtaç, utangaç, bir o kadar çaresiz, ıslak 

O sarmaşık sarmalarının sahibi sen değilmişsin gibi, 

Kollarına düşünce, dudaklarıma yapışınca kurtulamayan ben değilmişim gibi 

döndün işte olsa da bir yabancı gibi 

''Şimdi topla gözyaşlarını kaldırımlarından 

Gitmeliyiz ıslık çalarak Yalnızlığımdan.'' 

Semih TANRIVER

(10 Temmuz 2002)', 'Ellerin mi titredi, yüreğin mi.  Umutlarımı vurmaya çalıştığın silahın kabzası sevgiden mi yoksa.  Beni yine öldüremedin, kalamadın pişmanlı...', ARRAY['Türk Edebiyatı','Şiir','Semih Tanrıver']::text[], 8.5, '{"poet":"Semih Tanrıver","poet_slug":"semih-tanriver","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/topla-gozyaslarini-kaldirimlardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Damlaları', 'yagmur-damlalari-damla-calisir-v2x0j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur durmazcasına yağıyor

Yalnızlığımı bir sel misali alıp götürüyor bu gece.

Delicesine çarpışan yağmur damlaları

Dansa davet ediyor umarsızca beni

Damlaların berraklığına kaptırıyorum kendimi

Sevişircesine dans ediyoruz sabaha kadar

Paramparça kadehler  dudaklarımı kesiyor

Kadehimdeki dudak izlerin umutsuzca terk ediyor geceyi

Lanetler yağdırırcasına..

Sımsıcak kan damlaları süzülüyor dudaklarımdan

Ama bozamıyor mayhoşluğumu bu gece..

Meçhulden geleb güneş pırıltıları 

Sabahı vurguluyor ürkütürcesine

Sırılsıklam ediyor bedenimi 

Utanmadan arınmış gecenin yağmurları

Tanimde sevişmenin hazzı

Kulaklarımda seni aldatmanın sessiz çığlıkları

Geceyi noktalayan güneşin ilk pırıltıları

Bozulmuş yasakların ilk sızlanışlarıydı gece

Dün gece yağmur  damlalarıyla aldattım seni 

Dün gece..

                (13.07.2000 tekirdağ)', 'Yağmur durmazcasına yağıyor Yalnızlığımı bir sel misali alıp götürüyor bu gece. Delicesine çarpışan yağmur damlaları Dansa davet ediyor umar...', ARRAY['Türk Edebiyatı','Şiir','Damla Çalışır']::text[], 8.5, '{"poet":"Damla Çalışır","poet_slug":"damla-calisir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yagmur-damlalari-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk Ediliş', 'terk-edilis-omer-karatepe-ufkp7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hatırlamak

nasıl vurulduğumu

yavruları sırtından akreple sevişirken

kadının hatirasında

sahrayı keşfetmek

havva''nın vahasında

kovuldugu bahçenin

tadında Adem

hatırlamak

gerek kalmasın tarihe 

yatagımdan önce

soğuyor bedenim

ölümün en çok sakızcı çocukları 

aşınmış masaları ağlatan

ölümün

bir duvara karşı

beklemek sızacak su', 'hatırlamak nasıl vurulduğumu yavruları sırtından akreple sevişirken kadının hatirasında sahrayı keşfetmek havva''nın vahasında kovuldugu bahç...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karatepe']::text[], 8.5, '{"poet":"Ömer Karatepe","poet_slug":"omer-karatepe","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/terk-edilis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızıdan Süzerken', 'kirmizidan-suzerken-omer-karatepe-nferk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sus! sesimde çıban

sus dokunuşta

ben degilsem gölgemdeki

haydi söyle

kararmadan aynalar

bir batımda

kaç hüzün dogurur gözlerim ey şiir!', 'sus! sesimde çıban sus dokunuşta ben degilsem gölgemdeki haydi söyle kararmadan aynalar bir batımda kaç hüzün dogurur gözlerim ey şiir!...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karatepe']::text[], 8.5, '{"poet":"Ömer Karatepe","poet_slug":"omer-karatepe","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kirmizidan-suzerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şişedeki Mektup', 'sisedeki-mektup-omer-karatepe-633mb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kimliğimi kırdım safraya

biri bağdaş kurmuş geceye 

o

tarihi çocuğum rüyanın ülkesinde

yoksul akıntı

ölü anlar dogururken

sen kırmızıya boyadıkça

ağlayan nehir o

rahat sırtıma

kızılcıgın kökünü sularken su

günbatan nasıl aunulursa kadına

öyle gelip geçiyor

tam çiçek açacak yalan

sus! 

acı büyüyor diyor annem

şiir olcak

yüreginde bir kalem kırıyor çacuk', 'kimliğimi kırdım safraya biri bağdaş kurmuş geceye  o tarihi çocuğum rüyanın ülkesinde yoksul akıntı ölü anlar dogururken sen kırmızıya boya...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karatepe']::text[], 8.5, '{"poet":"Ömer Karatepe","poet_slug":"omer-karatepe","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sisedeki-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk..', 'mutluluk-sair-birtanem-8r9fr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutluluğu bana sorsalar seni tarif ederdim

Senin gibi içimi içime sığdırmayan, 

Çoğaldıkça ağlatan 

Kaybettikçe hep peşinde koştuğum

Sen gibi derim.

Mutluluğu bana sorsalar seni tarif ederdim

Bir saniyelik ayrılıkta özleten, 

Yokluğunda hayata küstüren, 

Kokukunu duyanca heyacanlandığım 

Sen gibi derim. 

Mutluluğu bana sorsalar seni tarif ederdim

Her zafer sonrası hissedilen, 

Kazandıkça havalara uçuran, 

Sevindiğimde kucaklamak istediğim 

Sen gibi derim.

Mutluluğu bana sorsalar seni tarif ederdim

Hayatımın anlamı olan

Beş duyumun toplamı

Deliler gibi sevdiğim 

Sen gibi derim', 'Mutluluğu bana sorsalar seni tarif ederdim Senin gibi içimi içime sığdırmayan,  Çoğaldıkça ağlatan  Kaybettikçe hep peşinde koştuğum Sen gib...', ARRAY['Türk Edebiyatı','Şiir','Şair Birtanem']::text[], 8.5, '{"poet":"Şair Birtanem","poet_slug":"sair-birtanem","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mutluluk-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Gemi', 'yalniz-gemi-sair-birtanem-71off', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Okyanusta dümeni kırılmış gemiyim.

Rotam istediğim yönden çok uzağa

Akıntı ise inatlaşıyor beni senden uzaklaştırmaya

Rüzgar bile esmiyor ki gideyim senin olduğun diyara.

Kalbimde ise bir fırtına aşk rüzgarlarıyla

Denizdeki fırtına hiç bunun yanında.

İçimde birşeyler var hep senden yana

Yelken açmak için çırpınıyor yüreğim sana

Bildiğin duygular, tanıdığın esintiler

Konuşurken bana bakmıyor artık o gözler

Yoksa seni rahatsız mı ediyor bu sözler

Bunu için mi  yüzüme bakmıyorsun 

Neden Birtanem gözlerini kaçırıyorsun, 

Sevdiğimi, özlediğimi mi duymak istemiyorsun

En değerli şey  bir havadan soluduğum  oksijen

Bir de herşeyinle bana hayat veren sen

Anlıyormusun benim için ne kadar önemlisin

Bu gemi sensiz mutluluğa yelken açamaz

Dostluğa, sevgiye sensiz yol alamaz

Bu gemiye götürecek tek güç; dostluğumuz

Sevgimiz, güvenimiz, arkadaşlığımız

Tut elimden, bin hadi dostluk gemimize

Son hızla gidelim geleceğimize

Sevgimiz dümen,  dostluk rotamız olsun

Ve Birtanem,  bir ömür bereaberlik amacımız olsun.', 'Okyanusta dümeni kırılmış gemiyim. Rotam istediğim yönden çok uzağa Akıntı ise inatlaşıyor beni senden uzaklaştırmaya Rüzgar bile esmiyor ki...', ARRAY['Türk Edebiyatı','Şiir','Şair Birtanem']::text[], 8.5, '{"poet":"Şair Birtanem","poet_slug":"sair-birtanem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalniz-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsim', 'dort-mevsim-sair-birtanem-oxbkl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlkbaharın önemi yok artık benim için

Beni kendine dört mevsim aşık ettin

Ne baharda kokusu açan  çiçeklerin 

Ne de kışın karların yadığı umrumda, 

Sen bana dört mevsimlik aşkı öğrettin', 'İlkbaharın önemi yok artık benim için Beni kendine dört mevsim aşık ettin Ne baharda kokusu açan  çiçeklerin  Ne de kışın karların yadığı um...', ARRAY['Türk Edebiyatı','Şiir','Şair Birtanem']::text[], 8.5, '{"poet":"Şair Birtanem","poet_slug":"sair-birtanem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dort-mevsim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hissedebiliyorum', 'hissedebiliyorum-sair-birtanem-q0u31', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hissedebiliyorum dokunmasamda teninin yumuşaklığını

Hiç güneş görmemiş gibi beyazlığını

Herzaman hayalimde saklayacağım

Beynime kazıdığım kadınlığını

Hissedebiliyorun  koklayamsamda mis kokunu

Baharda açan çiçekler gibi yoğunluğunu

Herzaman hayalimde saklayacağım

Yüzünün güzelliğindeki  duruluğu

Hissedebiliyorum güzelliğinden bahsettiğimde utangaçlığını

Sıkıldığında yanaklarına basan kırmızılığını

Herzaman içimde saklayacağım

Bacağındaki benin sana yakıştığını

Hissedebiliyorum birgün söyleyeceksin  beni sevdiğini

Uzaklardayken beni özleyeceğini

Bir ömür boyu haykıracağım 

Bu aşkın hiç bitmeyeceğini.

13/08/2002', 'Hissedebiliyorum dokunmasamda teninin yumuşaklığını Hiç güneş görmemiş gibi beyazlığını Herzaman hayalimde saklayacağım Beynime kazıdığım ka...', ARRAY['Türk Edebiyatı','Şiir','Şair Birtanem']::text[], 8.5, '{"poet":"Şair Birtanem","poet_slug":"sair-birtanem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hissedebiliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Dediğin Yazar…', 'sair-dedigin-yazar-sair-birtanem-wtv6c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şair dediğin duygularını, etkilendiklerini yazar 

Benim etkilendiğim, duygulandığım tek sensen

O zaman ben başka ne için şiir yazacam ki

Duygularımı yazmadıktan sonra

Şair dediğin gözünü kapadığında hayal ettiğini yazar

Benim gözümü kapadığımda hayal ettiğim tek sensen

O zaman ben başka ne için şiir yazacam ki

Ben hayal ettiğimi yazmadıktan sonra

Şair dediğin Birtanesini özlediğinde şiir yazar

Özlediğimde hasretinden şiir yazdığım tek sensen

O zaman ben ne için şiir yazacağım ki

Özlemimi kelimelere dökmedikten sonra

Şair dediğin aşkına sevdiğini söylemek için şiir yazar

Benim en büyük aşkın tek sensen

O zaman ben ne için şiir yazacağım ki

Aşkıma sevdiğimi söylemedikten sonra..

13/08/2002', 'Şair dediğin duygularını, etkilendiklerini yazar  Benim etkilendiğim, duygulandığım tek sensen O zaman ben başka ne için şiir yazacam ki Duy...', ARRAY['Türk Edebiyatı','Şiir','Şair Birtanem']::text[], 8.5, '{"poet":"Şair Birtanem","poet_slug":"sair-birtanem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sair-dedigin-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ateşi-2-', 'ask-atesi-2-bayram-tunca-8u5d4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk otağını kalbime kurdu

Aşk ateşi ta tavana vurdu

Demek ki, aşk ateşi buydu

Bu aşkı cümle alem duydu

O yarle göz göze gelip bakıştık

Birbirimize çok mu çok yakıştık

İlk aşk ateşimizi o gün yakmıştık

Sönmesin diye de hep körükledik

Bu aşkla hangi deryaya girsem kururdu

Bu aşkla hangi ağacı yaslansam kururdu

Bu aşkla hangi dağa yaslansam kül olurdu

Aşk ateşim ancak deryanda sükun bulurdu 

B. Tunca/11.04.2002-10.55', 'Aşk otağını kalbime kurdu Aşk ateşi ta tavana vurdu Demek ki, aşk ateşi buydu Bu aşkı cümle alem duydu O yarle göz göze gelip bakıştık Birbi...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-atesi-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma', 'askima-seyhan-demiroglu-qrrr9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni 13  lülü yaşlarda sevdim, 

20  li yaşlarda sevdimi

35  li yaşlarda hala seviyorum..

Senin o masumiyetini, 

Onurluluğunu, 

Kaçamak bakışlarını sevdim..

Senin o esmerliğini, 

Üçgen vücudunu, 

Cinsel arzularını sevdim..

Senin o ayak parmak ucundan

Saçının en uzun teline, 

Noktadan virgülüne, 

A  dan  Z  ye kadar

Herşeyini sevdim..

Seni, senden 24 saat ayrılmamak 

İstercesine sevdim..

Seni sevdim, sevdim hep sevdim..

Ama sen bir yıldız gibi

Kayıp gitmeyi tercih ettin yüreğimden..

Elveda aşkım elveda..

Sadece gidiş biletin var yanında........', 'Seni 13  lülü yaşlarda sevdim,  20  li yaşlarda sevdimi 35  li yaşlarda hala seviyorum.. Senin o masumiyetini,  Onurluluğunu,  Kaçamak bakış...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Demiroğlu']::text[], 8.5, '{"poet":"Seyhan Demiroğlu","poet_slug":"seyhan-demiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askima-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynadır! *', 'aynadir-bayram-tunca-dcfu8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şems, gündüzün güzelliğini gösteren bir aynadır

Ay ise, gecenin gizemliliğini gösteren bir aynadır

Eşler de birbirlerinin güzelliğini yansıtan aynadır

Tüm cisimler, O’nun güzelliğini gösteren aynadır

29.03.2002-17.35', 'Şems, gündüzün güzelliğini gösteren bir aynadır Ay ise, gecenin gizemliliğini gösteren bir aynadır Eşler de birbirlerinin güzelliğini yansıt...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aynadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bastıramadım', 'bastiramadim-bayram-tunca-f3cs5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duygularımı bir türlü bastıramadım

Sayısız şiirler yazdım bastıramadım

Kitaplaştırıp dostları ulaştıramadım

Anca, internet sayesinde ulaştırdım 

Bu hususta arşınlamadığım yol kalmadı

Aşındırmadığım yayınevi kapısı kalmadı

Dil dökmediğim editör, yayıncı kalmadı

Şairlik adına da aşkım, şevkim kalmadı

Şiirlerimi, hangi editöre gösterdimse, 

Çoğunun gözü korkup, dediler şöyle; 

Sen şiir değil, destan yazmışsın kardeşim

Diyemedim onlara, şiirlere sığmazdı çilem

Buna rağmen, yazmaya devam ediyorum

Bir gün bir yayınevi basar ümit ediyorum

Bu temennimle yazmaya devam edeceğim

Ta ki bu can tenden çıkana dek yazacağım

B. TUNCA/25.10.2000-16.37', 'Duygularımı bir türlü bastıramadım Sayısız şiirler yazdım bastıramadım Kitaplaştırıp dostları ulaştıramadım Anca, internet sayesinde ulaştır...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bastiramadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum Bitmez', 'umudum-bitmez-hakan-akyurt-u4c8s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün gelir de bende yollara düşerim, 

Gönlüm için, dağları aşar geçerim.

Umudum bitmez bu sevdamın yolunda, 

Senin için ben, her çileyi çekerim.

Şiir yazarım, aşk türküsü söylerim.

Divaneyim ben, diyar diyar gezerim.

Umudum bitmez bu sevdamın yolunda, 

Uğruna senin, kara toprağa girerim.', 'Gün gelir de bende yollara düşerim,  Gönlüm için, dağları aşar geçerim. Umudum bitmez bu sevdamın yolunda,  Senin için ben, her çileyi çeker...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umudum-bitmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Pervane', 'ask-i-pervane-yavuz-sayin-dwubo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk,

 bir pervane böceğinin

    mum ışığına olan

  mecnuni tutkusudur

böyle bir tutkunun sonu 

              illaki; 

hazin bir yanık kokusudur

asena''ya Ankara; (2000)', 'Aşk,  bir pervane böceğinin     mum ışığına olan   mecnuni tutkusudur böyle bir tutkunun sonu                illaki;  hazin bir yanık kokusu...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sayın']::text[], 8.5, '{"poet":"Yavuz Sayın","poet_slug":"yavuz-sayin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-i-pervane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttuklarım Yüzünden', 'unuttuklarim-yuzunden-i-dris-ozyol-vg30a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yeşil kalbim benim

sarıdan ve maviden oluşmayan yeşil kalbim

rehin bıraktım üstüne kustuğum toprakları

gözlediğim incirler yarım durdu orada

bir su kendi çoğuluna aktı

bir kadın vazgeçti doğumdan

kalbim beni dövmüyor artık

gitmek en güzel halidir gözdemin

bunu bilmek aykırı bir damar beynimde

unuttuklarım yüzünden seviyorum seni

çok düşündüm ve uyanıp attım yüzümü

şimdi sen taşıyor olmalısın gözlerimi

ne çok şey unutmuşum ben böyle

kalbim kendi sınırlarına yabancı

hiç nar yemediğimi hatırlıyorum

hatırladığım son şey bu sen öncesi

sen öncesi sanki bir adım vardı benim

sanki diye konuşunca dil küsüyor

kendimden öte birşeyim oluyorsun

kaybolsak gideceksin ve bir hayvan

mesela ben yarasını dişleyecek gözlerinde

kalbim basmayı unuttuğumuz zil

ben bir fotoğrafı oğul belledim

cebimde bir delilik ötesi yok

ve hangi sen alnımı indirsem

hangi sokağı dönsem ilk apartman 

kayıtsız şartsız isminle başlıyor

gitmeli burdan bir gidişe gitmeli

kalbim kuduz bir köpek

kalbim ısırdı beni

ama kanayan sen', 'yeşil kalbim benim sarıdan ve maviden oluşmayan yeşil kalbim rehin bıraktım üstüne kustuğum toprakları gözlediğim incirler yarım durdu orada...', ARRAY['Türk Edebiyatı','Şiir','İdris Özyol']::text[], 8.5, '{"poet":"İdris Özyol","poet_slug":"i-dris-ozyol","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/unuttuklarim-yuzunden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emirden', 'emirden-atalay-demirci-eviix', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakarsın bir güzele gönülden

Göz yaşı akıtırsın hayaline içten

Seversin ta damardan, derinden

Ve kader onu sana getirir

Sanki emirden

Uğruna ölürsen öldürürsün

Vurur, kırarsın

Şehri yakarsın belki

Hayatını silersin defterinden

Ve kader onu götürür

Sanki emirden

Yine anlamaz akıllanmazsın

Peşine düşersin duygularının ölümüne

Dostlar kırarsın

Ve mutlaka yalnız kalırsın

Bu kez kader seni ona götürür

Sanki emirden

Sonra sevemez olursun kimseyi 

Hayaliyle yatarsın gecel

Ellerin boş yüreğin ağzına kadar yar doludur

Bu kezde kader ölüm der

Yine emirden', 'Bakarsın bir güzele gönülden Göz yaşı akıtırsın hayaline içten Seversin ta damardan, derinden Ve kader onu sana getirir Sanki emirden Uğruna...', ARRAY['Türk Edebiyatı','Şiir','Atalay Demirci']::text[], 8.5, '{"poet":"Atalay Demirci","poet_slug":"atalay-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/emirden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İnsanoğluyuz', 'biz-i-nsanogluyuz-atalay-demirci-h5geb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne istediğimizi bilmeyiz çoğu zaman

 Babanın, tabutunu taşırken anlarız kıymetini

 Sevgiliyi elden gidene kadar sevemeyiz

 Mutluluk dibimizdedir kör olur göremeyiz.

 Biz insanoğluyuz! 

 Rüyaya dost''dan daha fazla inanırız

 Bardak kırar gibi kalp kırar

 Doğruluk gün gibi ortadayken

 Yalanı arar bulmak için kıvranırız

 Biz insanoğluyuz! 

 Gerçekten seveni nerdeyse döveriz

 Eğer kaçarsa nefret eden mutlaka yetişiriz

 Derdi varsa birinin, en uzağına gider

 İyi gününde, ondandaha fazla güleriz

 Biz insanoğluyuz! 

 Anayı ölümüne yakın hatırlarız

 Paraya her şeyden daha fazla aşığız

 Ümitlerimiz daha yeşermeden koparır

 Sevgimizi gösteremez herkesten sakınırız

 Biz insanoğluyuz! 

 Kötünün niyetini, iyinin şevkatini

 Ecel kapısı çalana kadar anlamayız

 Yardımı her şeyden çok bekler

 Küfrü ağızdan asla atmayız

 Biz insanoğluyuz! 

 Rahatlığın en yücesi hep hayalimiz

 Darlıktan ders almak en zor işimiz

 Burnumuz kanasa isyan eder

 Kuru ekmek, zeytine şükretmeyiz

 ÇÜNKÜ BİZ

             İNSANOĞLUYUZ! ..', 'Ne istediğimizi bilmeyiz çoğu zaman  Babanın, tabutunu taşırken anlarız kıymetini  Sevgiliyi elden gidene kadar sevemeyiz  Mutluluk dibimizd...', ARRAY['Türk Edebiyatı','Şiir','Atalay Demirci']::text[], 8.5, '{"poet":"Atalay Demirci","poet_slug":"atalay-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/biz-insanogluyuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlığa', 'i-nsanliga-erol-altinsoy-4faa8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu şehir yalnızlık şehri

Kanayan yarama merhem yerine bir bir basılıyor tuz

Sevdalar terk ediyor

Aşklarda ise bir telaş 

Tren garları dolu

Otobüs garlarında gargaşa

Boşalıyor bu şehir terk ediyor sevdalar bir bir

Yalnızlığın ucu bende yakıyor canımı

Ağlamak istiyorum doyasıya Hece hece ezberlediğim şarkının bir yerlerinde

Bu şehir yalnızlık şehri diyorum anlamıyormusun

Tanrılar şeytana bıraktı

Bomboş kalan caddeleri

Bir ben bir yalnızlığım 

Ölüm olsa ucunda gideceğim

Varıp kapına yalvaracağımı sanma

Kanayan yarama tuz basıyor ömrüm

Ve beni şeytana sattı

Otuzdört senelik yalvardığım Tanrım.....

Bu şehir beni öldürüyor

Havasında yalnızlığım karbondioksit

Bir bir yoluyor canımı cımbızla

Kanayan binbir yaramda tuz

Canım yanıyor boğazım düğümleniyor

Medetmisinki sıcak yatağımda yatan korkum

Sarılsam çırılçıplak uyusam

Sonraları öpsem seni hayasızca dişlerimde kan

Onların kitabına besmeleylemi girdim ki sevdam seni bir başkasına satsam

Yaram kanıyor tuz basılıyor canım yanıyor

Bir telaş bu şehirde yavaş yavaş terk ediliyor

Üryan oluyor bu şehir üryan

Anadan doğma çırlçıplak

Ve ben çırılçıplak giriyor koynuma 

Sevişmek istercesine (şeytanca)

Kollarımda hayasızca 

Ayın şavkısıyla boğuyor gözlerimi

Cığlık karışıyor sezsiz gecelere

Yaralara merhem yerine tuz basıldıkça

Bu şehir yalnızlık şehri diyorum anlıyormusun

Tanrılar şeytana bıraktı

Bomboş kalan caddeleri.......

                                Erol Altınsoy', 'Bu şehir yalnızlık şehri Kanayan yarama merhem yerine bir bir basılıyor tuz Sevdalar terk ediyor Aşklarda ise bir telaş  Tren garları dolu O...', ARRAY['Türk Edebiyatı','Şiir','Erol Altınsoy']::text[], 8.5, '{"poet":"Erol Altınsoy","poet_slug":"erol-altinsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/insanliga-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana mektup', 'sana-mektup-erol-altinsoy-s3ran', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sol şakağıma dayanmış soğuk bir namlu

Gözlerim yarı açık saçlarım rüzgarın konuğu

Misafirinim şimdi odanı gören yıldızlarda

Kapatma pencerini seyrindeyim gülüm seyrinde

Sana ulaşmak hayalde olsa öpmek sarmak

Mayın tarlarından daha zor olsa gerek

Sana dönük sevdalarıma kahpe bir pusu

Dedimya gülüm sol şakağımda soğuk bir namlu', 'Sol şakağıma dayanmış soğuk bir namlu Gözlerim yarı açık saçlarım rüzgarın konuğu Misafirinim şimdi odanı gören yıldızlarda Kapatma pencerin...', ARRAY['Türk Edebiyatı','Şiir','Erol Altınsoy']::text[], 8.5, '{"poet":"Erol Altınsoy","poet_slug":"erol-altinsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sana-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilale Ağıt', 'bilale-agit-erol-altinsoy-7shqz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vay Bilal bir ağat yaktım sana

derin gecelerin sezsizliğinde

Bir sevda ağlanmaz derdin Bilal

Halayına durdum ölümün eşşiğinde

Yere oturdum ışıkları saydım

Yıldızları saydım ben ağlamadım

Yere oturdum hasretin koynunda

Mahallemizdeki simitçi amcayı

Boyboya dizilmiş gençlerin katliamlarını

Cihan harbinden kalmış dilenci amcayı

Karşı komşu Zeliha ablanın

ekmek parası için kendini sattığını

Bana sevda dersleri verdiğini

Kahpe insanların dünyası dediğini

Daracık ufkumda silahların gölgesinde

Hep bunları düşündüm Bilal

Kahpe kurşunlar adresini sorana kadar

Hep bunları düşündüm Bilal.....', 'Vay Bilal bir ağat yaktım sana derin gecelerin sezsizliğinde Bir sevda ağlanmaz derdin Bilal Halayına durdum ölümün eşşiğinde Yere oturdum ı...', ARRAY['Türk Edebiyatı','Şiir','Erol Altınsoy']::text[], 8.5, '{"poet":"Erol Altınsoy","poet_slug":"erol-altinsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bilale-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dotlara', 'dotlara-erol-altinsoy-z6cto', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş kızıllıklarında özlemin demlenirken

Titrek ellerin bir cigara sararken

Özlemim bir huysuz at gibi iplerini koparınca

Yüreğimin ateşinde kızıl çiçekler açınca

Varacağım demiştim gözlerin ağir ağır kapanınca

Varacağım demiştim bilinmeyen bir mevsimde

Her yanında halden bilmez hasiyetsiz namlu

Belki vurulursun bağrında sızlayan yara

Sen topraklara düşersinzaman geç olmuş olabilir

Üzerimde yatıyorsun kokla beni o zaman', 'Güneş kızıllıklarında özlemin demlenirken Titrek ellerin bir cigara sararken Özlemim bir huysuz at gibi iplerini koparınca Yüreğimin ateşind...', ARRAY['Türk Edebiyatı','Şiir','Erol Altınsoy']::text[], 8.5, '{"poet":"Erol Altınsoy","poet_slug":"erol-altinsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dotlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fakirlerin aşkı', 'fakirlerin-aski-erol-altinsoy-exczt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çizgileri birbirine karıştırarak bir resim çiz

Yaprakları dalları taşları toprakları

Dünyanın kanunlarını hepsini tersine çiz

Bulutlarda bir deniz ortasında bir sandal

Yıldızlardan kök salmış dünyaya çiçekleri çiz

Beynin zorla düş dünyasıda olsa

Onları zengin kendini fakir beni düşünme

Beni kurşun seviyorum sözcüğünü namlu

Sana yönelmiş bir kurşun çiz hayalde olsa

Sevmek bütün imkansızlığı yıkar diyorsan

Bir dünya çiz toz pembe olsada çiz

Zamanın günlerini yıllara dök çizerken

Beyazlaşan saçlarımı siyaha boya boyarken

Alnımdaki kırışıklıkları al eski resimlerime bakmadan

Kendini piyononun başına yap

Duymadığım bir müüzik çal

Sözleri benim olsun ama bana yabancı gelsin

İmkansız diye bir şey yoksa dünyada

Bana başka bir kimlik çiz nasıl çizersen çiz

Seni çizmek imkansız diye bağırırsan

Gözleri boyalı dudakları kat kat rujlu kız

Benim sevmemde seni o kadar imkansız', 'Çizgileri birbirine karıştırarak bir resim çiz Yaprakları dalları taşları toprakları Dünyanın kanunlarını hepsini tersine çiz Bulutlarda bir...', ARRAY['Türk Edebiyatı','Şiir','Erol Altınsoy']::text[], 8.5, '{"poet":"Erol Altınsoy","poet_slug":"erol-altinsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/fakirlerin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni nasıl sevmiştim', 'seni-nasil-sevmistim-erol-altinsoy-2mjew', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceler uzasada geçer bu günler

Rüzgarlar esede savrulur küller

Ben seni yazarım seni

Lafımı olur gülüm ağlamazmı pözler

Ben yörürümde dünyamı durur

Bir gül solarda baharmı ölür

Gelsen benim kollarıma bu günlerde

Cehennem yeryüzünemi taşınır

Bu günlerde yıldızlar konuğum olurda

Bir dem demlersek hasretten yana

Birde masal anlatılırsa kaf dağında

Saçlarını dağıtan rüzgarlardamı yalan olur

Eller açılırda susuz topraklarda

Fakir insanında yalvarışı Allaha

Rabbim seni bana bağışlasın diye

Açsam ellerimi sevdalarmı yalan olur

Ben seni yazarım hece hece

Kalbimde tertemiz bir bilmece

Kalemi versem senin ellrine

Sende yazabilirmisin seviyorum diye....', 'Geceler uzasada geçer bu günler Rüzgarlar esede savrulur küller Ben seni yazarım seni Lafımı olur gülüm ağlamazmı pözler Ben yörürümde dünya...', ARRAY['Türk Edebiyatı','Şiir','Erol Altınsoy']::text[], 8.5, '{"poet":"Erol Altınsoy","poet_slug":"erol-altinsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-nasil-sevmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlıksız', 'basliksiz-erol-altinsoy-dfquj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayrılığın kokusunu  getiriyor yine rüzğarlar

Dalından kopan yapraklar perişan ben perişan

Umut kasırgasında parçalanan gemimde 

Hayaller perişan ben perişan', 'Ayrılığın kokusunu  getiriyor yine rüzğarlar Dalından kopan yapraklar perişan ben perişan Umut kasırgasında parçalanan gemimde  Hayaller per...', ARRAY['Türk Edebiyatı','Şiir','Erol Altınsoy']::text[], 8.5, '{"poet":"Erol Altınsoy","poet_slug":"erol-altinsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/basliksiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sözler', 'son-sozler-erol-altinsoy-6xq1i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haydi bir buse kondur yanağıma

Giden ömrümüde getiremessin bana

Sevmiş olsanda devri alemdeyim

Her şey yazılıda mezar taşımda

Sallanda boyuna bakayım 

Gülde sonkez baharı yaşayım

Saçlarını dağıtta bağrıma

Daha çok yatarım karın altında

Ne olur son bir kez bak

Sitemimde ahu gözlerinde kalmasın

Sanki bir senmisin beyazlar içinde

Nasibim olsun bir taşımda sana

Kederli günümde geçme yanımdan 

Bahçemde yem attığım uşlardan

Gözyaşımı bıraktığım nisan yağmurlarından

Bir mektup sana gelemem yanına', 'Haydi bir buse kondur yanağıma Giden ömrümüde getiremessin bana Sevmiş olsanda devri alemdeyim Her şey yazılıda mezar taşımda Sallanda boyun...', ARRAY['Türk Edebiyatı','Şiir','Erol Altınsoy']::text[], 8.5, '{"poet":"Erol Altınsoy","poet_slug":"erol-altinsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-sozler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum Ölmesin Yeter...', 'ruhum-olmesin-yeter-gulay-atilay-gz1ns', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ruhum Ölmesin Yeter...

sensiz gecenin sabahı

sanki başka doğuyor güneş

sanki başka ötüyor kuşlar 

sanki baska bir şehirde dolanıyorum

uzak diyarlardaki dağlar kadar yanlızım.. 

bir sıcaklık ararken yanılmışım.

sevdamı haykırıken aldanmışım.. 

sevdiğimi sanarken kendimi kandırmışım.. 

sensiz gecenin sabahıda oluyor.. 

dostlaıım yanımda olsun yeter dersin o da bir gün elinden kayıp gider.. 

hayatı sözcüklerde......... 

insaları kalbimde yaşatırsam belki mutlu olurum derdim yanılmışım..

kelimeler neden tükenmiyor..

yazdıkça yazasım geliyor neden.? 

ben bu kadar dertlimiyim? .. 

hayatım neden olumsuzluklarla geçiyor? 

neden ler nedeni bilinmezler...! ! ! 

yalnızım, yapayalnız sensiz..

gecenin karanlığını yanlızlığımla kutluyorum

yanlızım ve mutluyum diye kendime yalanlar haykırıyorum

kimseye ihtiyacım yok derken kaderime kahrediyorum

eskileri hatırlayıp gözlerimden akan yaşları tutuyorum.

anlamsız gülüşlerde içimde çaglayanları durduruyorum..

boş masamdaki dostuma kadeh kaldırıyorum..

elimdeki kuru çiçege bakıp kendimi anımsıyorum

her dokunuşta kırılan, birşeylerini kaybeden kendime acıyorum

kalabalığın içinde bile kendimi arıyorum

elimden akıp giden hayatımın peşinde kosuyorum...

nefret etsemde sevdalımdan, ben yinede tüm insaları seviyorum..

ihaneti tadsamda hayatla savaşıyorum.. 

kadehler elimden düşer elbet, belki sigaramda düşer..

ruhum ölmesin yeter..........', 'Ruhum Ölmesin Yeter... sensiz gecenin sabahı sanki başka doğuyor güneş sanki başka ötüyor kuşlar  sanki baska bir şehirde dolanıyorum uzak d...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ruhum-olmesin-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak İzlerim', 'ayak-i-zlerim-cengiz-hakki-zaric-cnvls', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Yanlıştı kentin gözlerindeki çakılı halimin yanıtları 

 Suskundu 

 İntihara meyilli sağır avcılar beni ruhsatlı tümceleriyle vurdu''

Demir tellerin pası çıkmaz sokakların ağıyla sardı serüvenimi 

Kovuldum kamudan plastik gülüşlerin ağzını öpmedim diye 

Omzumda dinlendirdim sevdiğim kadını ve kekre sözcüklerimi

Taşa tutulmuş bir ayna gibi yadırgandım 

Talana kalkıştılar cinnetimi ve öfkemi, kışkırdım 

Binlerce görüntünün toplamıydım, paramparçaydım

Kentin gözlerindeki çakılı halimin yanıtları yanlıştı 

Yanlıştı şaklaban kalabalığın hesapsız olduğu 

Ay yüzeyindeki ayak izlerim kadar yalnızdım

Tekin değildim, yanlıştım, yanıtsızdım! ..', '''Yanlıştı kentin gözlerindeki çakılı halimin yanıtları   Suskundu   İntihara meyilli sağır avcılar beni ruhsatlı tümceleriyle vurdu'' Demir t...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Hakki Zaric']::text[], 8.5, '{"poet":"Cengiz Hakki Zaric","poet_slug":"cengiz-hakki-zaric","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayak-izlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişi Andım Yine', 'gecmisi-andim-yine-ozcan-nevres-ltbyo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün dostlarımızla dertleştik 

Seni sordular görüşüyor musunuz diye

Unuttum onu dedim ama 

Titreyen dudaklarım gerçeği söyledi

Göz yaşlarımı gizleyemedim

Ne derinmiş gönlümde açtığım yara

Unuturum demiştim ama unutamadım

Sen de unuttum diyormuşsun ama

Unuttuğuna inanamadım

Unutmak benim için çok zor

Senin için kolay olacağını sanmıyorum

Unutulur mu birlikte geçirdiğimiz o güzel günler

Yüzümde halen duruyor

Seni ilk öperken tırnaklarının açtığı izler

En karanlık sokaklara dalardık

Kem gözlerden uzak olmak 

Ve uzun uzun öpüşmek için

Tüm kuytu yerler

Aşk oyunumuza sahne olurdu

Seyircilerimiz kuşlar ve böceklerdi

Anımsar mısın kaya kertenkelesini

Nasıl da uzun uzun seyretmişti bizi

Avuçları olsaydı alkışlayabilseydi

Mutlaka patlardı avuçları

Gerçekten bir aşk oyunu muydu bizimki

Nedensiz terk edişin senaryonun gereği miydi

Yazarı kimdi bu senaryonun

Ya rejisörü kimdi bu oyunun

Mutlu etti mi seni

Beni böylesine acılar içinde koyup gidişin

Mutlu olduysan eğer

Bu sana son sitemimdir bunu bil yeter', 'Dün dostlarımızla dertleştik  Seni sordular görüşüyor musunuz diye Unuttum onu dedim ama  Titreyen dudaklarım gerçeği söyledi Göz yaşlarımı ...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gecmisi-andim-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Sokaklarına', 'i-stanbul-sokaklarina-hayalet-kral-2wstc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalvaran duygularım döküldü ağır ağır

Bir piyanonun tuşlarına, 

Çaresiz aşkıma besteler yaptım

Saldım hepsini; ISTANBUL SOKAKLARINA...

Dinledim bir kemanın, boynu bükük

Hasretle figan eden tınısını

Aradım yıllarca gönlümün sevdasını

Sordum seni; ISTANBUL SOKAKLARINA...

Dudağımdan dökülen kelimeler

Sevenlere ve aşklarına, 

Kendimi yerle bir, aşkınıda azad ettim

Gömdüm senide; ISTANBUL SOKAKLARINA...', 'Yalvaran duygularım döküldü ağır ağır Bir piyanonun tuşlarına,  Çaresiz aşkıma besteler yaptım Saldım hepsini; ISTANBUL SOKAKLARINA... Dinle...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istanbul-sokaklarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varmısın..', 'varmisin-hayalet-kral-6uran', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl da farkedemedik

Zamanın bir çırpıda geçtiğini, 

Boş yere yüreğimizin hemen dibinden

Sular seller gibi akıp bittiğini.

Ne yazık ki; daha sana hiç bilinmeyen

Elle tutulup, gözle görülmeyen hikayeler anlatacaktım, 

Biryerlerde, yüzüne yüz sürülmeyen hayatı

Bir kalemde sıralayacaktım! ...

Var mısın? Yerlere göklere fısıldayalım tekrar

Sürgünlere taş çıkartacak aşkımızı; 

Var mısın? Bu vicdan seni arar

Çalkantısı zaten baştan kırmızı...

Kararı çoktan verilen

Cezası çoktan kesilen... Sevdamızı! .', 'Nasıl da farkedemedik Zamanın bir çırpıda geçtiğini,  Boş yere yüreğimizin hemen dibinden Sular seller gibi akıp bittiğini. Ne yazık ki; dah...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/varmisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Muhteşem Aşk İmkansız Olandır', 'en-muhtesem-ask-i-mkansiz-olandir-hayalet-kral-4ajsc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Apayrı hislerle başlarsın

Herşeyi silbaştan yaparsın, 

Tamam! O senin kadınındır

En muhteşem aşk imkansız olandır! 

Yeni bir çehre çizersin

Gamı kederi uçuruma itersin, 

Miadı dolanlar geride kalır

En muhteşem aşk imkansız olandır! 

Gördüğün insanlar, yürüdüğün yollar

Yediğin içtiğin bir başkadır, 

Hedeflerin olağanüstü farklıdır

En muhteşem aşk imkansız olandır! 

Kifayetsizce seyr’edersin romantizmi

Düşünmezsin ne olacak sonunda, 

Hayatın şimdi daha güçlü ve anlamlıdır

En muhteşem aşk imkansız olandır! 

Dağarcığı kısa ve netdir kelimelerin

Böyle aşkta, böyle sevgi ve hüzünlerin, 

Nitekim birçoklar alttan alınır

En muhteşem aşk imkansız olandır! 

Anlamsız çizgiler çekersin dört bir yana

Pembe gözlükler kırılmış; ne bir utanç, ne bir haya

Cevapsız sorular kafalara kazınır

En muhteşem aşk imkansız olandır! 

Onu kaybettiğinde ilkin anlamazsın

Seninle dahada büyüyeceğini farketmezsin, 

Sadece ufak tarifsiz bir sızıdır

En muhteşem aşk imkansız olandır! 

Bu yoğun çarpık bir bitiş noktasıdır

Ne sesi ile, ne yüzü ile müşerref, 

Şimdi sevgin mantık dışı bir sınırdadır

En muhteşem aşk imkansız olandır! 

Geçmişin unutulanlar mutfağına kaldırmak istersin onu

Ama maalesef oynatamazsın kolunu, 

Nihayet anlarsın biçare...

O senin gerçek sevdandır

En muhteşem aşk imkansız olandır!', 'Apayrı hislerle başlarsın Herşeyi silbaştan yaparsın,  Tamam! O senin kadınındır En muhteşem aşk imkansız olandır!  Yeni bir çehre çizersin ...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/en-muhtesem-ask-imkansiz-olandir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bile Bile', 'bile-bile-hayalet-kral-abw93', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimden akan kızgın yanardağ lavları

Eritiyor hafızamdaki

O eski buz tutmuş anıları...

Geliyorlar yine dört koldan

Benliğimi delik deşik etmeye, 

Özen gösterip uğraşıyorum

Hayatımdaki iz bırakanlarını seçmeye! 

Herbirinin ayrı

Herbirinin vefakar ve sadık

Sanki birer ruhu var, 

Alemleri kayıp hatıralar... 

Sınırsızca bütünüm şimdi sizlerle

Sayfalarınızı usulca çevirip

Tekrar tekrar, bıkmadan okuyorum

Aşk ile dostluk ile; 

Sonra gözlerimi duvara dikip

Kimseler duymadan ağlıyorum

Beni bırakıp gittiğinizi bile bile................', 'Yüreğimden akan kızgın yanardağ lavları Eritiyor hafızamdaki O eski buz tutmuş anıları... Geliyorlar yine dört koldan Benliğimi delik deşik ...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bile-bile-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırımda Birşey Var', 'hatirimda-birsey-var-hayalet-kral-863fz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırımda birşey var; 

Acı ile demlenirken...

Yüregimde yaralayan sözler, gülen dudaklar

Birbaşına ve yapayanlız halimde

Geri tepen o vurdumduymaz silahlar! 

Hatırımda birsey var; 

Canhıraş, bilinçsizce didinip

Hafızamdan silmek istedigim, 

Bir sevda uğruna tükenip te

‘Ya kırk katır, ya da kırk satır’ denilip

Alıpda başımı diyar diyar gezdigim...

Hatırımda birşey var; 

Çılgınca sevdigim ve yaşadığım andığım

Sadece İstanbul’du...

Düştü ellerimden çelimsiz varlığım

Yazdığım binbir hece tuz buz oldu................', 'Hatırımda birşey var;  Acı ile demlenirken... Yüregimde yaralayan sözler, gülen dudaklar Birbaşına ve yapayanlız halimde Geri tepen o vurdum...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatirimda-birsey-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun Sonunda', 'yolun-sonunda-hayalet-kral-lsvfn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaybolup gidiyor birer birer

Dünün şerefi ve şanı, 

Ne kadarda kısaldı bu günler

Yazdığım bir sevda yalanı! 

Kısacık hayatları rengarenk boyayıp

Varlığımızı topyekün değiştirebilen, 

Dağ gibi bedenleri, dal misali bırakıp

Bir ağlatıp bir güldürebilen! 

Halbuki başlarken bilinir 

Seni bırakıp kaçacak bir gün, 

Yanlızlık asası ile dikildiğinde karşına

Ellerinde açacak çiçeği hüznün...

Günlerini sancılarla geçirip

Yıllarını tüketeceksin, onsuz ama onunla, 

Ağarmış saçlarına baktığında anlayacaksın

Aşkın ve işte yolun sonunda...', 'Kaybolup gidiyor birer birer Dünün şerefi ve şanı,  Ne kadarda kısaldı bu günler Yazdığım bir sevda yalanı!  Kısacık hayatları rengarenk boy...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yolun-sonunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşluk Vakti', 'kusluk-vakti-hayalet-kral-9z6gc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşerken; sabah vakti 

Toprağa çiğ damlaları, 

Haber getirir senden bana

Beyaz bir güvercinin kanatları.

Yakarsa; öğle vakti

Tenini güneş ışıkları, 

Düşün uğruna göze aldığım

Tekrarı olmayacak çılgınlıkları! 

Gelipte; akşam vakti

Yanlızlık tüm bedenimi sardığında, 

Farzederim seni; kuşluk vakti

Bir dua okurken mezarımın başında...', 'Düşerken; sabah vakti  Toprağa çiğ damlaları,  Haber getirir senden bana Beyaz bir güvercinin kanatları. Yakarsa; öğle vakti Tenini güneş ış...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kusluk-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Kaptan', 'vefasiz-kaptan-hayalet-kral-ur2zt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüzgarsız havada yelkeni can çekişen

Teknemin vefasız kaptanıyım, 

Gönder bir küçük meltemde olsa

Usulca limanına yanaşayım...

Halatlarımla sıkıca sarayamki

Kimsenin çözmeye gücü yetmesin, 

Seni ağlatıp üzen gözler

Ömrünün sonuna kadar hiç gülmesin! 

İstemezsen şayet, denizlerimde beni ve sevgimi

Teknem su alır...

Batar yok olurum, karışırım maviliklere

Aşkım bir yerde, 

limanın bir yerde kalır.', 'Rüzgarsız havada yelkeni can çekişen Teknemin vefasız kaptanıyım,  Gönder bir küçük meltemde olsa Usulca limanına yanaşayım... Halatlarımla ...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vefasiz-kaptan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Bir Gül', 'islak-bir-gul-hayalet-kral-stz5p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alemlerin doruğunda uyandı sana

Sevgi dolu güçsüz kollarım, 

Renginde yeşerdi, büyüdü

Varlığın ile tamamlandı doldu

Heba olan bomboş yıllarım.

Hayatın en derin, en ince

Çizgilerini yakaladım seninle nihayet, 

Anlatılması akla zarar bir hikaye

Yaşanıldığında anlaşılır ancak bu hidayet! 

Yağmuru çok severdin bilirim

Camın önünde oturup, saatlerce bakmasını

Kadere bak ki; senelerim yağmurla doldu taştı

Beceremedim bir türlü şu bulutlardan kaçmasını.

Bak! Zağmur başladı yine

Nasılda bardaktan boşalırcasına yağıyor, 

Hey sen! Bu havada elinde bir gül ile bekleyen adam; 

Evine git be dostum, bitti artık herşey

Dikkatlice seyret... yağmur değil..

Elindeki gülü gözyaşlarım ıslatıyor..', 'Alemlerin doruğunda uyandı sana Sevgi dolu güçsüz kollarım,  Renginde yeşerdi, büyüdü Varlığın ile tamamlandı doldu Heba olan bomboş yılları...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/islak-bir-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saatler 12’yi Vurduğunda', 'saatler-12-yi-vurdugunda-hayalet-kral-i5z39', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık hayallere dalarım

Her gece aynı zamanlarda, 

Ellerinin beyazlığını ararım

Saatler hep 12’yi vurduğunda.

Fal taşı olur açılır gözlerim

Ansızın uykuların en gizli yerinde, 

Engel olamam titrer sözlerim

Saatler hep 12’yi vurduğundaç

Soğuk ülkelerin; yanardağ misali

Sımsıcak prensesi gibisin

Uzaklarda çınlıyor artık sesin

Saatler hep 12’yi vurduğunda.

Unutamam seni

Görmek duymak mümkün olmasada, 

Ne olur sende beni unutma prensesim; Ama

Saatler TAM 12’yi vurduğunda...', 'Karanlık hayallere dalarım Her gece aynı zamanlarda,  Ellerinin beyazlığını ararım Saatler hep 12’yi vurduğunda. Fal taşı olur açılır gözler...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saatler-12-yi-vurdugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Daha Yaşanmayacak', 'bir-daha-yasanmayacak-hayalet-kral-u53xu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayal bile edemezdim

Bir kadının beni yaşarken ölüye çevireceğini, 

Unutmak istiyorum baş harfini bile adının

Unutursam bilki; bedenimin bir anda devrileceğini! 

Rüyamda görmek isteyeceğim seni

Ne kadar çırpınsam bu da olmayacak, 

Bırakıp giderken beni söz vermiştim

‘Artık gözlerim senin için dolmayacak’

Hayatımda bulursam yine sevgiyi

Aşk güllerim hiç solmayacak, 

Kimse kandıramayacak artık bu deliyi

‘Çünkü’

Senden sonra hiçbir aşk bana bu kadar koymayacak! ..', 'Hayal bile edemezdim Bir kadının beni yaşarken ölüye çevireceğini,  Unutmak istiyorum baş harfini bile adının Unutursam bilki; bedenimin bir...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-daha-yasanmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Mutlu Kalman Dileğiyle Hoşçakal...', 'hep-mutlu-kalman-dilegiyle-hoscakal-yalnizlik-hastasi-f41eo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüyalarımda görmek için geceyi beklerdim, 

Gündüzün kalabalık yalnızlığına inat.

Beklerdim ya hala beklerim....

Geceler sensiz çekilmiyor be gülüm

Bazen rüyalar yetişiyor imdada

Hasretini dindirmek için.

Zaten rüyalarımda olmasa ben ölürüm...

Mutluysan sorun yok ayrı kalalım.. 

Yalnızlık en çok geceleri yaşanır be gülüm! ! ! ! ....', 'Rüyalarımda görmek için geceyi beklerdim,  Gündüzün kalabalık yalnızlığına inat. Beklerdim ya hala beklerim.... Geceler sensiz çekilmiyor be...', ARRAY['Türk Edebiyatı','Şiir','Yalnızlık Hastası']::text[], 8.5, '{"poet":"Yalnızlık Hastası","poet_slug":"yalnizlik-hastasi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hep-mutlu-kalman-dilegiyle-hoscakal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalarımdasın', 'ruyalarimdasin-yalnizlik-hastasi-m6gfr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaybolmuştum gecenin karanlığında

Kendimi buldum rüyanın derinliğinde

Sen yoktun gene yanımda

Yalnızdım yatağımda bile

Ama mutluydum genede

Çünkü umutluydum gündüzlerin tersine

İçim kararsada bu insan kalabalığının içinde

Olsun rüyalarımda sen varsın benim

Yalnız olsam bile.....', 'Kaybolmuştum gecenin karanlığında Kendimi buldum rüyanın derinliğinde Sen yoktun gene yanımda Yalnızdım yatağımda bile Ama mutluydum genede ...', ARRAY['Türk Edebiyatı','Şiir','Yalnızlık Hastası']::text[], 8.5, '{"poet":"Yalnızlık Hastası","poet_slug":"yalnizlik-hastasi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ruyalarimdasin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim', 'kalbim-duygu-gunkut-8k84i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbim silindi...

Henüz kimse görmeden

Güzelliğini.

Kimse görmesin diye, 

Saklamıştım kalbimi

Silindi gitti...

İki göğsümün arasına yapılmış

Bir dövme idi.

Kalbim, silindi gitti...', 'Kalbim silindi... Henüz kimse görmeden Güzelliğini. Kimse görmesin diye,  Saklamıştım kalbimi Silindi gitti... İki göğsümün arasına yapılmış...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kalbim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Alınıp Götürülmek Var', 'simdi-alinip-goturulmek-var-aydin-ozturk-gzznj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şimdi

alınıp götürülmek var

geceyarıları

sokaklar çürük kokusu

gölgeler

hırıltılı bir soluk

peşinizde

her şeyi

umutlu

sınırsız

sıcacık düşlemişken

atılmak

bir karakol penceresinden

şimdi

alınıp götürülmek var

geceyarıları', 'şimdi alınıp götürülmek var geceyarıları sokaklar çürük kokusu gölgeler hırıltılı bir soluk peşinizde her şeyi umutlu sınırsız sıcacık düşle...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/simdi-alinip-goturulmek-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz İnce Bir Sızıdır', 'temmuz-i-nce-bir-sizidir-aydin-ozturk-dy5pn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şimdi

bu sokaklardan

çekip aldılar mı sesinizi

bütün denizlerden gözlerinizi

çizilirken

bir kent gecesine

sarmalayıp yeditepeyi

yaralarının kabuğu ışıltılarla

ateş çiçekleriydi yarasa nişangahlarında

suların bitimsiz düşüydü

morgun soğuk mermerlerinde

yarası uğuldayan ateşler içinde

şimdi

ardından kemanların koştuğu

o can tılsımı senfoni

yarım mı kaldı

bir ufkun

şafaklara değişi yarım', 'şimdi bu sokaklardan çekip aldılar mı sesinizi bütün denizlerden gözlerinizi çizilirken bir kent gecesine sarmalayıp yeditepeyi yaralarının ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/temmuz-ince-bir-sizidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Bir Ütopya Değil', 'uzak-bir-utopya-degil-aydin-ozturk-3v33b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'düşündün mü hiç

sonra

ne taşır seni

insan ömrü kısalığınca

ışık hızı varılmayan yıldızlara

şair düşünden başka', 'düşündün mü hiç sonra ne taşır seni insan ömrü kısalığınca ışık hızı varılmayan yıldızlara şair düşünden başka...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uzak-bir-utopya-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gibi', 'yagmur-gibi-aydin-ozturk-a4yi3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seninle

sokakları yıkayan

yağmurun sesiyle

uyumak tadındadır

zaman', 'seninle sokakları yıkayan yağmurun sesiyle uyumak tadındadır zaman...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yagmur-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarasına Acılar Düşer Kuşların', 'yarasina-acilar-duser-kuslarin-aydin-ozturk-szvv7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sanki

yokluğuna kahırlanan kent

ah çeker

yarasına acılar düşer kuşların

ay uzak tepelere çekilir

sular kararır', 'sanki yokluğuna kahırlanan kent ah çeker yarasına acılar düşer kuşların ay uzak tepelere çekilir sular kararır...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yarasina-acilar-duser-kuslarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek', 'gitmek-ayten-mutlu-wisl2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gün gelir insan anlayıverir

tek başına yaşlanan bir ağaç olduğunu

o yüzden kederi yazmak isteyebilir

rüzgarın gövdesinde açtığı yaralara

sonbaharda şaşarak öğrenirsin

yaprakların rengine inanmamayı

ve zamanın o müthiş yalanını

o müthiş yalanını tutkunun, ihtirasın

anların, anıların, 

çılgın bir nehir gibi kör koşularda

yaşadıklarının ve yaşayamadıklarının

dağlarda, odalarda, avunmalarda

çoğaldın sandığın azalmalarda

ışığını yitirmiş o ölü yıldızlarda

düşen bir yaprağın son gülüşünde açan

yankısız çığlıklarda

şaşarak öğrenirsin

zamanın ve hayatın büyük sırrını

gök sadece yağmura anlatır sonsuzluğu

oysa unutur damla toprağa değer değmez

yağmurun da kederli bir ülke olduğunu

unutmaktan başka güz yokmuş gibi

ve hayattan daha gerçek bir yalan

toprağa ne söyler yağmurun sesi

bir şarkı mı, bir şiir mi, bir güz hikayesi mi

yaşlı bir ağaç olsan, çırılçıplak bir ağaç

ne söylerdin, kalbinde esip duran rüzgara? 

''beni terk et

içimde sonbahardan başka bahar kalmadı''

belki de gitmektir aşk, sadece gitmek

avare bir kederi sarıp yaralarına

rüzgarın devirdiği bir ağaç gibi

köklerini sessizce bırakarak toprağa', 'gün gelir insan anlayıverir tek başına yaşlanan bir ağaç olduğunu o yüzden kederi yazmak isteyebilir rüzgarın gövdesinde açtığı yaralara son...', ARRAY['Türk Edebiyatı','Şiir','Ayten Mutlu']::text[], 8.5, '{"poet":"Ayten Mutlu","poet_slug":"ayten-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gitmek-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Taneleri', 'kar-taneleri-ayten-mutlu-grjkh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ellerinden yağardı

en güzel yalanından dünyanın

bedenimde titreyen kar taneleri

hangi sevişme bir vedadan daha uzundur

nedir ki aşk çağımızda bir merhabadan başka? 

demiştin ya, aşk

kış yorgunluğu gibi yürürken aramızda

bir merhaba yeterdi güneşi ısıtmaya

gecenin gömdüğü gümüş bir yıldız gibi

mermer bir unutuşun mücevherine

bağışladım kar sesini

yüreğinde

donup kalmış kışın merhametine

kurudu bir içdeniz, güneş çekildi

bir mevsim gözlerini bırakıp gitti

kar kokan bir rüzgârı çıkarıp sandığından

derken bir “merhaba” sildi kendini

içimdeki ülkelerin haritasından

gecenin gömdüğü gümüş bir yıldız gibi

öyle sevdim ki, unuttum sevmeyi

bağışlamaz beni artık hiçbir hatıra', 'ellerinden yağardı en güzel yalanından dünyanın bedenimde titreyen kar taneleri hangi sevişme bir vedadan daha uzundur nedir ki aşk çağımızd...', ARRAY['Türk Edebiyatı','Şiir','Ayten Mutlu']::text[], 8.5, '{"poet":"Ayten Mutlu","poet_slug":"ayten-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kar-taneleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Gibi', 'olum-gibi-ayten-mutlu-o1rs6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'işte sevişmek bitti

ölüm gibi devam ediyor gece

aşk henüz gidilmemiş bir ülkedir, diyorsun

ne kadar uzak gitsen çıkamazsın teninden

kendinden çıkamazsın ne kadar yakın gelsen

sessizce dinliyorum gecenin çanlarını

açık bir yara gibi çalıyor çanlar

vuruluyor sesinde çanların hayvanları

çıkamıyorum senden ne kadar uzak gitsem

sana varamıyorum

ne kadar yakın gelsem

gözlerinde

acının ürperen tenini okşuyorum

nereye akar, hangi ölü denize

istiridyeden koparılan incinin kanı

biliyorum

ölüm gibi devam ediyor gece

susamış bir yangını söndürerek kalbimde

çekiyorum körelmiş bir ateşin bayrağını

sesindeki çanların en yüksek kulesine

kapanıyor gecenin ağır kapısı

sonsuz mavi bir cam kırılıyor içimde

öpüyorum

öper gibi gözlerini son defa

ölüm gibi bir aşkın gözyaşlarını', 'işte sevişmek bitti ölüm gibi devam ediyor gece aşk henüz gidilmemiş bir ülkedir, diyorsun ne kadar uzak gitsen çıkamazsın teninden kendinde...', ARRAY['Türk Edebiyatı','Şiir','Ayten Mutlu']::text[], 8.5, '{"poet":"Ayten Mutlu","poet_slug":"ayten-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olum-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçsizliğe', 'hicsizlige-turgut-uyar-cttbr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanrı sen ne kadar güzelsin

bir hiç olarak

ormansın belki bilmiyorum

belki ormanda bir ağaçsın şuncacık

bir pazartesi günüsün

insanları dupduru
..........
..........', 'Tanrı sen ne kadar güzelsin bir hiç olarak ormansın belki bilmiyorum belki ormanda bir ağaçsın şuncacık bir pazartesi günüsün insanları dupd...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hicsizlige-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keçiyolu', 'keciyolu-i-lhan-berk-dg7lb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bomboş oturdum rüzgarı dinledim

(yay burcundan dönen) . Irmağın

dediklerine geçtim sonra.

Geçip gidiyordum beni g
..........
..........', 'Bomboş oturdum rüzgarı dinledim (yay burcundan dönen) . Irmağın dediklerine geçtim sonra. Geçip gidiyordum beni g .......... .............', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"i-lhan-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/keciyolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ki', 'ki-rasih-yilmaz-la7z4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir mevsim dönüşürken diğerine, 

altın sarısı geçişleri

karanlığa hapsediyordu toprak

        -ki toprak aşktan önceydi

hep aynı vedada kaldığımı gösteriyordu

kaybolduğum mor kuytuluk

unutur olmuştum düşlerimi sokaklarda

         -ki düşlerin öznesi yoktu

bakışlarımla avuçluyordum

öfkeme yapışmış kan pıhtılarını 

esriyen acıların son demini yaşıyorum

          -ki yaşam ölümün ilk adıydı…', 'bir mevsim dönüşürken diğerine,  altın sarısı geçişleri karanlığa hapsediyordu toprak         -ki toprak aşktan önceydi hep aynı vedada kald...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ki-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-rasih-yilmaz-hdrc1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'avuçlayabilir misin karanlığı

sonlandırabilir misin bıçaksırtı bekleyişleri

durdurabilir misin kendini…

hayır

kaybedişlerin efendisisin sen

rezil, aptal ve ahmak…

çarmıha çivilenmiş iraden

düşlerin etrafını çevreleyen dikenli tellerin var.

geçmişte yaşadıkların ile geleceğe ait ipoteklerin, 

her an patlamaya hazır özlemlerin…

korkma aynalar yalan söylemez sana

gözyaşların imrendirir timsahları

kabil’in habil’i öldürüşü kadar acımasızdır nurdan yoksun vicdanın 

durmaksızın yokluğunun acısını içersin beyaz yürekli ülkenin 

ve bilirsin; 

ayrılığım sertliğini, 

kendi ölümünün yumuşaklığı bertaraf eder yalnızca', 'avuçlayabilir misin karanlığı sonlandırabilir misin bıçaksırtı bekleyişleri durdurabilir misin kendini… hayır kaybedişlerin efendisisin sen ...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Beyaz Ölüm', 'bir-beyaz-olum-rasih-yilmaz-gj1b3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aç gözlü kargaların

kan kokan nefeslerinden korurken

kendimizi

ölümler dost oldu aşkımıza

metal bir soğukluk kaplıyordu cümlelerimizi

ateşle oynayan bir yalandı dudaklardan dökülen

/biz aşıktık

gülüşün

sisli bir yalnızlıktı/

ayrılırken

iğreti bir yaşam vaat ediyordu düşlerimiz…

bakışlarımıza kar yağıyordu

bir beyaz ölüm kaplıyordu gözbebeklerimizi

sığınak anların efendisi', 'aç gözlü kargaların kan kokan nefeslerinden korurken kendimizi ölümler dost oldu aşkımıza metal bir soğukluk kaplıyordu cümlelerimizi ateşle...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-beyaz-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '‘A’ Hali…', 'a-hali-rasih-yilmaz-baq0z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sığınak anların efendisi

ay’ın intiharını izlerken güneşten

anlat bana

aşkın ‘a’ halimi acı olan

yoksa

gecenin zifiriliğine kan damlatması mı

aşkı acı kılan', 'sığınak anların efendisi ay’ın intiharını izlerken güneşten anlat bana aşkın ‘a’ halimi acı olan yoksa gecenin zifiriliğine kan damlatması m...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/a-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Güzeli', 'ay-guzeli-rasih-yilmaz-9puvh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'geçmiş düşüm çocuksu yüzüm yürek kıpırtım

aybikem

derin mavide bir kuştun kondun düşlerimizin içine

sesin bozdu sessizliğimizi

hayatımızı kavuran güzdü yokluğun, 

sen geldin yağdın yüreklerimize

filizlenen çiçekler değildi ıslaklığın ardından

geleceğimizdi seninle

doğumun yıllar öncesine aitti

aslında

ancak teşrifin uzun sürdü

aramıza

bilemedik açacağın toprağı

senin seçeceğini.

gül yüzlü kızım

alnında bir rüzgar öpücüğü getirdin

serin kıldın zamanın yalnızlığını

kaybedişin siyah beyaz bir resmi saydık varlığını…

zamansız ülke çocuğu

doğuşun değildi aslında acı olan

henüz yaşanmamış geçmişindi babanı yıkan, , , 

sana dairdi gelecek olan mevsimlerin hazırlığı, 

aslında beklenen bir düştün o kadar: ama şeker tadında

olsun doğdun

zühre yıldızım, aygüzeli kızım aybikem

ya doğmasaydın o zaman ne yapardı baban', 'geçmiş düşüm çocuksu yüzüm yürek kıpırtım aybikem derin mavide bir kuştun kondun düşlerimizin içine sesin bozdu sessizliğimizi hayatımızı ka...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ay-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Dost', 'eski-dost-rasih-yilmaz-3tb44', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gemilerin pervaneleri döverken denizi

günahların süngüleri parlak bir gülüşle

parçalıyordu aşkın dilenci bakışlarını

düşlerin yüreği, bir martı ağzında

götürülürken ıssızlığa

şairler satırlarında kaparken gözlerini

naftalin kokusu sarıyordu 

şehri

kadife adımların yazıldığı tarih

kristal bir zamana kaydediliyordu

sıcak bir acı gibi akıyordu gözlerden 

kan…

ölüm

eski dost

birkez daha

ziyarete geliyordu bizi…', 'gemilerin pervaneleri döverken denizi günahların süngüleri parlak bir gülüşle parçalıyordu aşkın dilenci bakışlarını düşlerin yüreği, bir ma...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eski-dost-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş', 'ates-rasih-yilmaz-kjub7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'suya değil ateşe yazı yazmak bizimkisi

düşünde yanıp ateşin

külünden can çıkartmak yaptığımız…

kavrulurken yangınıyla yüreğin

dans ederken kızılların ciniyle

ateşin teridir içtiğimiz..

mavi akşamlarda

saatlerin ayrılığı vurduğu anlarda

garip bir acıdır

yaşamın kayıt defterine düştüğümüz…', 'suya değil ateşe yazı yazmak bizimkisi düşünde yanıp ateşin külünden can çıkartmak yaptığımız… kavrulurken yangınıyla yüreğin dans ederken k...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ates-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Bahar', 'bir-baska-bahar-rasih-yilmaz-zukpd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'acı

yeni yanmaya başlamış

taze sarma bir tütünken

sen

kendimi kurutup soldurduğum

aşk yamaçlarında

kardelen olarak çıktın karşıma…

zaman kan oluyor

hayatıma sızıyor

sebebi ölümüm benim

acının doyumsuzluğu yalarken yüreğimi

kurulamayan düşlerin içinde

varlığının kokusunu arıyorum

istemesem e artık 

bir başka baharı yaşıyorum', 'acı yeni yanmaya başlamış taze sarma bir tütünken sen kendimi kurutup soldurduğum aşk yamaçlarında kardelen olarak çıktın karşıma… zaman kan...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-baska-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkıntı Zikirleri', 'sikinti-zikirleri-rasih-yilmaz-f1nn5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kaos odalarında çekilen

sıkıntı zikirleri…

emrine amade bir beyin, 

vecd halinde kendinden geçen zamanlar…

isimsiz bir yılgınlığa doğru savrulan bakışlardan kurtulamayıp kuruyan

tek kuyu

öz bunalımların gelgitler yaşattığı zihin zonklamaları

peşimde hep aynı müzik..

kulakmemelerime tutkun, 

sanırsın sonu yok…

tenha bir elvedada geldi

mavi gözlü ölüm

anladım

kaçış yok', 'kaos odalarında çekilen sıkıntı zikirleri… emrine amade bir beyin,  vecd halinde kendinden geçen zamanlar… isimsiz bir yılgınlığa doğru savr...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sikinti-zikirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fosforlu Bir Günah', 'fosforlu-bir-gunah-rasih-yilmaz-myb09', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bohem zamanlarda

nedensiz başı boş yalnızlıklar

içimi acıtıyor

dudaklarımdan öperken

yalın bir zehir ayrılık

karanlık sızıyor gözlerimden

düşlerimde kazıdığım mavi

fosforlu bir günah oluyor

taşra aşklarının parçalanmış çiçekleri

lekeliyor düşlerimi

soğuyorum

elimde ay ışığının bilinmezliği ile

sürgününde inançsızlığımın

kapı kapı dolaşarak

intiharımı arıyorum', 'bohem zamanlarda nedensiz başı boş yalnızlıklar içimi acıtıyor dudaklarımdan öperken yalın bir zehir ayrılık karanlık sızıyor gözlerimden dü...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/fosforlu-bir-gunah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-rasih-yilmaz-p9h5i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'damarlarındaki toprağa

kasıklarındaki bütün sancılara rağmen

ölüler acı hissetmezmiş 

yalan!', 'damarlarındaki toprağa kasıklarındaki bütün sancılara rağmen ölüler acı hissetmezmiş  yalan!...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalan-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Ölümleri', 'eylul-olumleri-rasih-yilmaz-4ik2n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir resmin peşi sıra ‘ıslak adımlarla’ aranan ne varsa

-aşka, yani sana dair-

kaybettiğim bütün  yüzlere denk düşürüyordu yokluğunu…

/hiçbir ayrılık güzel değildi ölüm kadar. oysa ki

güzel olur derlerdi ‘eylül ölümleri’/

bu yüzden olsa gerek, git de diyemiyorum..kal da.

iki yokluk arasında kayboluş..

zamanın son nefesini çekiyorum içime.

susmanın ölüm.

ölümün eyvallah diye beklendiği bir kapı

aralığında.

gözlerimde karanlığın sessizliği…

ne kadar uzun zaman oldu

-unuttum-

yalvarmaya durmayalı geceye…

bir kadavra öpüşü soğukluğu sararken bedene…

/çizilmemiş bir resme veremediğimiz ruhun, 

yaşanabilirliğini hiç görememek mi bizi delirten..

yoksa morgunda bekletilen cesedin gözlerindeki

hikayenin sonunu bilememek mi

yaşamı anlamlı-anlamsız kılan/

ruhuna dokunuyorum 

ellerimde yalnızlık

git de diyemiyorum…kal da.

yusuf’un bakışlarındaki mermer saraylara hapsettiğim

resmin, 

bende tamamlayamadan esaretini, 

darağacına göndereceğim bütün sisli ‘sin’leri…

ve o ‘sin’lere inat seveceğim 

tanrısal masumluğunda seni…', 'bir resmin peşi sıra ‘ıslak adımlarla’ aranan ne varsa -aşka, yani sana dair- kaybettiğim bütün  yüzlere denk düşürüyordu yokluğunu… /hiçbir...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/eylul-olumleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen', 'beklenen-rasih-yilmaz-ff6oj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kaybolacağım beyazın

derinliğinde

sen beni gümüş

yüreğimden tanıyacaksın

şövalyeler olacak 

etrafımda

-ki onlar zamansız ülke

atlılarıdır-

mızraklarıyla çizecekler

umut haritalarını

kızıl gözlü yokluğun

simgesi

sen

gelene dek

mataramda bir yudum

dahi düş kalsa

sahile kıyısı olmayan

çöllerde

hep beklenen olacaksın', 'kaybolacağım beyazın derinliğinde sen beni gümüş yüreğimden tanıyacaksın şövalyeler olacak  etrafımda -ki onlar zamansız ülke atlılarıdır- m...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beklenen-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabesk', 'arabesk-rasih-yilmaz-b4ek3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'alaturka bir kabuk bağladı sensizliğim

üstü pul pul olmuş yara ile her oynayışımda

akan kıpkırmızı aşk oluyor

kan değil..

arabeskin bütün renkleri sarıyor yokluğunu; 

sarı, yeşil, mavi, kırmızı

göğüs uçlarına elektrik verilen sazın acıyla bağırışına

hırslı hırslı çalan darbuka gülüyor..

pembe dudaklı parlak elbiseli kadın 

cızırtılı mikrofonu elinde

pavyon bir şarkı ile aşkın çözümsüzlüğünü çığırıyor

/karmaşa ve sessizlik

tek gerçek yokluğun…/', 'alaturka bir kabuk bağladı sensizliğim üstü pul pul olmuş yara ile her oynayışımda akan kıpkırmızı aşk oluyor kan değil.. arabeskin bütün re...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/arabesk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynada Yanan Yüz', 'aynada-yanan-yuz-rasih-yilmaz-t7pgp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'anlamsızlıkların namlu ucuna verilmiş öldürücü kurşunum, 

açıklanamayan korkularımın çıkış noktası, 

bir bakışa hapsolabilen sarhoş gülüşüm…

aynada yanarken yüzüm

ben

yüreğimle ödüyordum

sana dair

utancımın bedelini…', 'anlamsızlıkların namlu ucuna verilmiş öldürücü kurşunum,  açıklanamayan korkularımın çıkış noktası,  bir bakışa hapsolabilen sarhoş gülüşüm…...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aynada-yanan-yuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-rasih-yilmaz-ch28r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'öznesi

kaybedişi

olan bir cümlenin

son noktası duyulan ‘keder’ sesi

elveda ise

Dila’nın dudaklarından dökülen 

son veda kelimesi', 'öznesi kaybedişi olan bir cümlenin son noktası duyulan ‘keder’ sesi elveda ise Dila’nın dudaklarından dökülen  son veda kelimesi...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/veda-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmi Konulmayan', 'i-smi-konulmayan-rasih-yilmaz-suvdt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çıplak bakışlarını kaybetmiş şehrin

sokaklarındaydım

yoktun

yalnızlığın infilakıydı şakaklarımda patlayan

ziyan bir zamandı harcadığım

tramvaylar geçiyordu özlemlerimin içinden

kan süzüyordu

sigaramdan duman çalan 

yorgun bulut

gülüşün

doğuşumdu

gidişin

ölümüm

sorgusuz sualsiz ayrılıktı gözlerini ufka gömüşün

tenime bulaşmıştı teneşir rutubeti

aşkın mevsimsiz sancılarına tutulmuştum

zemheri bir vuslatta

alacak haneme yazılmış güneşleri

sana esir ediyordum

anladım ki

‘ismini koyma’ dediğin bir vurgunu yaşıyordum…', 'çıplak bakışlarını kaybetmiş şehrin sokaklarındaydım yoktun yalnızlığın infilakıydı şakaklarımda patlayan ziyan bir zamandı harcadığım tramv...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ismi-konulmayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk''lüğümü Arıyorum', 'turk-lugumu-ariyorum-sukru-soyarslan-814ur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Asırlardır benliğimi

Müslümanlık din’liğimi

Anlı şanlı kimliğimi

Türk’lüğümü arıyorum.

Yeri inlete inlete 

Geliyor Oguz-Han Mete..

Zeval olmaz bu devlete

Türk’lüğümü arıyorum.

Bu ülkeyi bana vatan

Şehit kanlarıyla yapan

Büyük hükümdar Alparslan

Türk’lüğünü arıyorum.

Atam Ertuğrul-Han Gazi

Gözlerimden geçer mazi

Edeb-Âli, Osman-Gazi

Türk’lüğünü arıyorum.

Mısır’ı fetheden Yavuz

Olmuştur Türk’e kılavuz

Hükmetmeli; değil uyuz! 

Türk’lüğümü arıyorum.

Saysam daha neler neler

Konstantin’i alan erler

Ömr’de bir gelir Fatih’ler

Türk’lüğümü arıyorum.

Okunur kubbede ezan

Büyük usta Mimar Sinan

Duy, ey Kanun-i Süleyman

Türk’lüğümü arıyorum.

Nasıl etmem onları yad? 

Rabbim, ruhları olsun şad.

Bağdat’ın fatihi Murad

Türk’lüğünü arıyorum.

Bilge Tonyukuk, (kür)  Şad Teğin

Abdülhamid Han’a değin..

Öksüz, garip, bencileyin

Türk’lüğümü arıyorum.

Söz yetmez, nasıl medhetsin? 

Dilim anlatamaz, yetsin.

Unuttuklarım affetsin

Türk’lüğümü arıyorum.

İslam’ı yüce din bilen

Bütün dünyaya hükmeden

Düşmana boyun eğmeyen

Türk’lüğümü arıyorum.

Soysuza fırsat vermeyen

Başlar alıp, baş eğmeyen..

Aman! Diyene, değmeyen

Türk’lüğümü arıyorum.

Yedi düvele nam salan

Ülkeler fethedip, baç alan

Şimdilik; bi-çare olan

Türk’lüğümü arıyorum.

Türk evladı, olmaz bön

Yaşamına, vermeli yön.

Sen “ Titre ve kendine dön”

Türk’lüğümü arıyorum.

Türk doğdum, İslam’dır dinim

Yok asla, kimseye kinim..

Soyarslan’dır namım benim

Türk’lüğümü arıyorum.', 'Asırlardır benliğimi Müslümanlık din’liğimi Anlı şanlı kimliğimi Türk’lüğümü arıyorum. Yeri inlete inlete  Geliyor Oguz-Han Mete.. Zeval olm...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/turk-lugumu-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hançer..?', 'hancer-sukru-soyarslan-3pa27', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hançerle vursan, bu kadar olmazdı derin? 

Gün, senin günün; sevin ey güzelim, sevin..

Bitmez sevdaydın, kalbimdeydi senin yerin

Gün, senin günün; sevin ey güzelim, sevin..', 'Hançerle vursan, bu kadar olmazdı derin?  Gün, senin günün; sevin ey güzelim, sevin.. Bitmez sevdaydın, kalbimdeydi senin yerin Gün, senin g...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hancer-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İste Ben''den...', 'i-ste-ben-den-sukru-soyarslan-xzy08', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin elinde ferman

Kalmasa ben’de derman

Ömrüm yoluna kurban

Yeter ki, iste ben’den..

Gel de, gelivereyim

Sev de, sevivereyim

Öl de, ölüvereyim..

Yeter ki, iste ben’den..

Dişler sedef, dudak lal

Kaşlar; gökteki hilal

De ki; gitme..ben’le kal

Yeter ki, iste ben’den..

Al, bu gönül senindir

Aşkım, kalpte derindir.

Candan sev de, sevindir

Yeter ki, iste ben’den..

Sana, açtığım kucak

Sönmez sevgim, sımsıcak..

Deme, sonu n’olacak? 

Yeter ki, iste ben’den..

Dört mevsim, on iki ay

İstesen, ömrümden pay..

Emret güzelim; hay hay..

Yeter ki, iste ben’den..', 'Senin elinde ferman Kalmasa ben’de derman Ömrüm yoluna kurban Yeter ki, iste ben’den.. Gel de, gelivereyim Sev de, sevivereyim Öl de, ölüver...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iste-ben-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviden de Beyaz', 'maviden-de-beyaz-abdurrahman-kaan-koker-a8q13', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ki bir mısranın

olur olmaz  yerinde gülümseyen

hayalsin, 

mavisin, maviden de beyaz.

Belki gökyüzüsün 

belki deniz,

bilirim umutsun

başı sonu belirsiz.

Belki sehersin; aydınlık veren,

belki meltem, ferahlatan,

rüyasın ya

masal gibi

ya da destan; olunası...

Ama sevdasın, yüreğimi yakan,

bir mum alevi kadar

titrek ve narin,

bir bahar yaprağı kadar umut dolu,

okyanus kadar derin, gökyüzü kadar mavi...

Bensin, bendesin, yüreğimdesin

iyi ki varsın

İyi ki sensin.

Hani bir de yoksun ya

acısın en derinden yakan

korsun, çeliği de eriten

en onulmaz yaralarımı depreştiren

kasırgasın yıkıp geçen

belki selsin umutları söndüren 

Olmayan sabaha 

kavuşmak olsa da 

gecenin inadı 

sen yıldızlara tutunup 

gelmez misin bana

ve dahi olmaz mısın bana

mavi.', 'Sen ki bir mısranın olur olmaz  yerinde gülümseyen hayalsin,  mavisin, maviden de beyaz. Belki gökyüzüsün  belki deniz, bilirim umutsun başı...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Kaan Köker']::text[], 8.5, '{"poet":"Abdurrahman Kaan Köker","poet_slug":"abdurrahman-kaan-koker","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/maviden-de-beyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-roni-margulies-cfb2t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her akşam, her akşam, her akşam, 

her şeyi baştan düşünüyor olmasam, 

 tartmasam baştan niye ve neden

 kaybetmeyi seçtiğimi seni ve yeniden

 yaşama fırsatım olsa herşeyi

 yine aynı yaşardım hepsini diye

 düşündüğümde bile, pişman değilken yani, 

 mutsuz olmasam, kızmasam sana ve kendimi

 suçlamasam, n''apalım desem, kabullensem, 

 anlatmasam her akşam sana olup bitenleri

 gün boyunca, silsem yani seni hayatımdan, 

 tek başıma  yaşlansam, yakınmadan, sensiz.

 Ne olur? Kaç yıldır görüşmemişiz

 Kaç kadın girmiş o günden bu yana hayatıma.

 Ne olur? Her şeyi her akşam 

 baştan düşünüyor olmasam, 

 sensiz yaşlanıyor olduğumun bilincinde olmasam her akşam

 Ve sensiz geçen her günümün 

 farkında olmasam  sensiz geçtiğinin? 

ama değerli geliyordu bana sevgim o zaman, 

 yapmam gerektiğini düşünüyordum elimden gelen her şeyi, 

 her şeye rağmen, meydan okurcasına

 olması gerekirken olmayan her şeye; 

 yetersiz, aksak, çevresindeki herşeyden etkilenen, 

 gereklerini yerine getiremeyenbir SEVGİYDİ

 Doğru.Ama gerçekti.Direnmişti her şeye

 Ondandı değerli bulmam.

 Yerindeymiş uzun etmem, zorlamam, uğraşmam.

 Şimdi de değerli buluyorum yine çünkü düşündükçe her akşam.

 Ve kuşkum olmayacak hiçbir zaman: 

 Uğrunda mücadale etmeye değer  değerli olan her şey.', 'Her akşam, her akşam, her akşam,  her şeyi baştan düşünüyor olmasam,   tartmasam baştan niye ve neden  kaybetmeyi seçtiğimi seni ve yeniden ...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni-margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mektup-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkarsız Sevgim', 'cikarsiz-sevgim-erol-sen-xz9u9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beklentilerin sevgisi

Olmaz olası beklenti sevgisi

Benim gönlüm ne saray ister ne para

Sevginin çıkarcıları! ! ! ! 

Ferhat ile Şirin gibi

Örnek alınacak sevgiler isterim

Parayla satın alınan 

Yada makam ve mevkiyle değil

Seveceksen beni sev 

Benliğimi, özümü sevgimi sev

Sonradan çıkan gerçek yüzünle

Sahte sevgini geri al....', 'Beklentilerin sevgisi Olmaz olası beklenti sevgisi Benim gönlüm ne saray ister ne para Sevginin çıkarcıları! ! ! !  Ferhat ile Şirin gibi Ör...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cikarsiz-sevgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaparım Bilirsin', 'yaparim-bilirsin-erol-sen-962tg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatlar gördüm yitip gitmiş yıllara

Yaşamlar gördüm sahte yapmacık

Riyakar ve ikiyüzlü

Duygusuz insafsız

Hayatın gelmiş sonbaharında

Macera yaşamaya dayanmaz yürekler

Bilinmez sonu olmayan kumarlara

Kaybedilen kumarın yenisi olurmu? 

Hele insafsız riyakar ikiyüzlü

Sahte yapmacık yaşantılarla

Yaşadığını sanan zavallılarla

Doğarken sevgi görmeyen sevgisizlerle

Acımasız dünyanın dönen çarkına

Ayak uydurdum sevgisiz yaşama

Bir insafsız olamadım ama

Yemin ettim çomaklamaya...

15.08.2002', 'Hayatlar gördüm yitip gitmiş yıllara Yaşamlar gördüm sahte yapmacık Riyakar ve ikiyüzlü Duygusuz insafsız Hayatın gelmiş sonbaharında Macera...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yaparim-bilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Gizemi', 'yalnizligin-gizemi-sair-rami-6lrto', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalnızlık mıydı tünellerde yakaladığı

ışıklarla bezediği örümcek ağları mı

bir kuş yosunlarla sevişmişti düşünde

bir balık elim-sende oynadı bulutlarla

iki damla süzülmüştü kirpiğinden

güneşe mi konmuştu

yoksa

güneş mi ağlıyordu

saklanmak için mi dünyanın köşeleri

uzaklar yalnızlar için mi uzak

kamışlar kırılır yudumlarken hayatı

isimler mi, şahıslar mi sunulur yalnızlığa

yoksa

toplumlar mı yaratır yalnızlığı

birbirine dökülen yıldızlar mı yoksa yürek

okyanus miskinliği mi düşünceyi çağıldatan

göz açıp kapamak mı sonsuzluğu kavramak

yoksa

kavranan sonsuzluk mu yalnızlığa atan', 'yalnızlık mıydı tünellerde yakaladığı ışıklarla bezediği örümcek ağları mı bir kuş yosunlarla sevişmişti düşünde bir balık elim-sende oynadı...', ARRAY['Türk Edebiyatı','Şiir','Şair Rami']::text[], 8.5, '{"poet":"Şair Rami","poet_slug":"sair-rami","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yalnizligin-gizemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Böyle Bilirim+', 'seni-boyle-bilirim-bayram-tunca-m5fx8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aysız bir geceyi sensizlik bilirim

Güneşsiz bir günü sensiz bilirim

Seni Ay’ım, Güneş’im gibi bilirim

Bir gün dahi görmesem deliririm

01.04.2002-17:05

Aşk Ateşten Gömlek', 'Aysız bir geceyi sensizlik bilirim Güneşsiz bir günü sensiz bilirim Seni Ay’ım, Güneş’im gibi bilirim Bir gün dahi görmesem deliririm 01.04....', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-boyle-bilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye Rağmen, Herşey Güzel', 'herseye-ragmen-hersey-guzel-ali-saglam-3-ovzs3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yanıp, bir sönen

Işıklara bak...

Elele tutuşan, 

Aşıklara bak...

Boşver üzülmeyi, 

Yaşamaya bak...

Hayat çok güzel, 

Herşeye rağmen! ! ! 

Acılar hayatın, 

Tuzu biberi...

Bir gün çok ararsın, 

Geçen günleri...

Sevmek zorundayız

Birbirimizi...

Yaşamak çok güzel, 

Sensizliğe rağmen! ! ! 

Herşeye rağmen! ! !', 'Bir yanıp, bir sönen Işıklara bak... Elele tutuşan,  Aşıklara bak... Boşver üzülmeyi,  Yaşamaya bak... Hayat çok güzel,  Herşeye rağmen! ! !...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/herseye-ragmen-hersey-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor, Sor Çekinme', 'sor-sor-cekinme-ali-saglam-3-pmqbi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kördüğüm gibisin beni bağlayan, 

Kapanmayan yarasın, bende kanayan, 

Benimle birlikte kan ağlayan, 

Gökteki yıldızlara sor...

Senden ayrılmam artık imkansız, 

Toprağa gönderir beni zamansız, 

Teselli veren sazlar faydasız, 

Seni seviyorum diyen dudaklara sor...', 'Kördüğüm gibisin beni bağlayan,  Kapanmayan yarasın, bende kanayan,  Benimle birlikte kan ağlayan,  Gökteki yıldızlara sor... Senden ayrılma...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sor-sor-cekinme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye''yse-Dilek', 'niye-yse-dilek-ali-saglam-3-j99ov', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çiçekten aldığın güzel renkleri, 

Meltemli gecelerin pembelikleri, 

Evrenin tüm güzellikleri

Sana mutluluk versin dilerim...

Niye''yse...

Ayaklarına serilsin bahar, 

Gözlerinde parlasın tüm yıldızlar, 

Kimsenin duymadığı ılık bir rüzgar, 

Sana sevgiler getirsin dilerim...

Niye''yse...', 'Çiçekten aldığın güzel renkleri,  Meltemli gecelerin pembelikleri,  Evrenin tüm güzellikleri Sana mutluluk versin dilerim... Niye''yse... Aya...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/niye-yse-dilek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Bir An', 'huzunlu-bir-an-cirmiktili-asik-wxmom', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir an durmak ve bakmak

yaşamın iki biçiminde

iki ayrı tadında şöyle bir süzülmek geleceğe.

sormak mı yoksa cevabını mı vermek

susmak mı yoksa bağırmak mı

bir çelişkidir giden yaşamın bağrında

of...

sızıdır yüreğe akan 

ve gözyaşıdır toprağı sulayan bu anlarada

ve sadece yapılacak olanın

yapıldığı ve

tadılacak olanın tadıldığı

bir bilinmezlikte 

ve bir de ölüm de görülen hüznün

sade bir telaşıdır.

işte bu anlarda durmak ve bakmak.

yaşamın iki biçiminde...', 'bir an durmak ve bakmak yaşamın iki biçiminde iki ayrı tadında şöyle bir süzülmek geleceğe. sormak mı yoksa cevabını mı vermek susmak mı yok...', ARRAY['Türk Edebiyatı','Şiir','Çırmıktılı Aşık']::text[], 8.5, '{"poet":"Çırmıktılı Aşık","poet_slug":"cirmiktili-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzunlu-bir-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen''sizim', 'sen-sizim-ali-saglam-3-ms5is', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerime bakıpta aglama diyorsun.

Sensizlik ne acı bilmiyorsun.

Yalnızlığın karanlık dünyasında.

Aşkımla sensizin anlıyormusun...

Aklıma geldiğin her anda, 

Ağlamamak çok zor oluyor.

İçime çektiğim her sigarada, 

Acılarım kat kat artıyor...

Uzak yollara bakan gözlerim, 

Dalar gider bir anda, 

Dar geliyor bu yerler, 

Sensizim bu ellerde

Sensizim sevgilim...', 'Gözlerime bakıpta aglama diyorsun. Sensizlik ne acı bilmiyorsun. Yalnızlığın karanlık dünyasında. Aşkımla sensizin anlıyormusun... Aklıma ge...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'World', 'world-ali-saglam-3-sz3yg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimini yaşarken öldürüyorsun, 

Kimini canından bezdiriyorsun, 

Kimini de saraylarda yaşatıyorsun, 

Yalancı değil de sen nesin dünya...', 'Kimini yaşarken öldürüyorsun,  Kimini canından bezdiriyorsun,  Kimini de saraylarda yaşatıyorsun,  Yalancı değil de sen nesin dünya......', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/world-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadığımsın', 'anlatamadigimsin-ali-saglam-3-z2b1n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen Allah''a dilediğim dilek, 

Göklere uzanan ellerimsin.

Sen yaşadığım bir ömür, 

Tattığım güzel dünlerimsin.

Sen mutluluğa duyulan özlem, 

Tek çarem kaderimsin.

Sen anlatmak isteyipte anlatamadığım, 

Kelimelerle ifade edemediğimsin.', 'Sen Allah''a dilediğim dilek,  Göklere uzanan ellerimsin. Sen yaşadığım bir ömür,  Tattığım güzel dünlerimsin. Sen mutluluğa duyulan özlem,  ...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlatamadigimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımam', 'tanimam-ali-saglam-3-tsb8e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni görmeyeli, 

Tam bir yıl olmuş.

İçimdeki anıların, 

Artık yok olmuş.

Yüzünü sorsalar, 

İnan hatırlamam.

Görsemde artık birtanem, 

İnan 

Yarım yamalak bırakıp, 

Gittin aşkımızı.

Şimdi yalnız dinliyorum, 

Bizim şarkımızı.

Birgün geri dönsen, 

Kapansada yaram.

Görsemde artık seni, 

İnan', 'Seni görmeyeli,  Tam bir yıl olmuş. İçimdeki anıların,  Artık yok olmuş. Yüzünü sorsalar,  İnan hatırlamam. Görsemde artık birtanem,  İnan  ...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tanimam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkediliş', 'terkedilis-ali-saglam-3-ez5uy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerini sevdim gökyüzüne bakarak, 

Yüreğini sevdim gözlerine bakarak, 

Seni sevdim yüreğine bakarak, 

Sen ise terkettin beni, 

Gecenin karanlığına bakarak, , ,', 'Gözlerini sevdim gökyüzüne bakarak,  Yüreğini sevdim gözlerine bakarak,  Seni sevdim yüreğine bakarak,  Sen ise terkettin beni,  Gecenin kar...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/terkedilis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Sen', 'sensiz-sen-ali-saglam-3-rwaz4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Telefonun her çalışında, 

Yoldan geçenlerin, 

Ayak sesini duyduğumda, 

Her geleni sen sandığımda, 

Kendimden korkuyorum...

Yalnızlığı düşündüğümde sen.

Ölümü düşündüğümde sen.

Herşeyi düşündüdüğümde sen.

Birtek seni düşündüğümde

Sen gelmezsin aklıma...', 'Telefonun her çalışında,  Yoldan geçenlerin,  Ayak sesini duyduğumda,  Her geleni sen sandığımda,  Kendimden korkuyorum... Yalnızlığı düşünd...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensiz-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız Sevgi', 'anlamsiz-sevgi-ali-saglam-3-7amxt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayattan elimi çektiğimden beri, 

Bir sevinç doldu gönlüme, 

Bazen düşündüğümde eski günleri, 

Ahh... ne kadar aptalmışım, 

Anlayamadım bir türlü, 

Neden sevdim Seni..................!', 'Hayattan elimi çektiğimden beri,  Bir sevinç doldu gönlüme,  Bazen düşündüğümde eski günleri,  Ahh... ne kadar aptalmışım,  Anlayamadım bir ...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlamsiz-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Allah''a Mahsustur', 'yalnizlik-allah-a-mahsustur-ali-saglam-3-vh59l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Yalnızlık Allah''a mahsustur'' derler.

Bazen insanda yalnız kalabiliyor.

Çok sevdiği insanlardan, 

Birgün gelip ayrılabiliyor.

Bende şimdi senden ayrıldım.

Artık bende yalnız biriyim, 

Birgün yeni birini sevsemde, 

İnan sensiz yaşayamam bilirim.', '''Yalnızlık Allah''a mahsustur'' derler. Bazen insanda yalnız kalabiliyor. Çok sevdiği insanlardan,  Birgün gelip ayrılabiliyor. Bende şimdi se...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizlik-allah-a-mahsustur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlü Melek', 'kara-gozlu-melek-ali-saglam-3-ubc2a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karagözlüm...

Can yoldaşım, hayat arkadaşım.

Soframda kaşığım, ekmeğim, suyum.

Karanlık gecelerde yıldızım, 

Sen benim herşeyim canım cananım.

Karagözlüm...

Muhtacım şimdi senin ellerine, 

Sıkı sıkı sarılıp kollarına.

Dizlerinde ağlamak istiyorum.

Senin yanında olayım yeter, 

Her şey sende, 

Herşey seninle güzel, 

Sen yanımdayken.

Ağlamak, ölmek bile güzel...', 'Karagözlüm... Can yoldaşım, hayat arkadaşım. Soframda kaşığım, ekmeğim, suyum. Karanlık gecelerde yıldızım,  Sen benim herşeyim canım cananı...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kara-gozlu-melek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürüngen', 'surungen-ali-saglam-3-w6gpc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Silahı belinde, 

Sigarası elinde, 

Daha onyedisinde, 

Hep sürünmekte...

3 yıl sonra...

Hala sürünüyor.', 'Silahı belinde,  Sigarası elinde,  Daha onyedisinde,  Hep sürünmekte... 3 yıl sonra... Hala sürünüyor....', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/surungen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünden Sonra, Yarından Önce', 'dunden-sonra-yarindan-once-ali-saglam-3-nvmju', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllardır bu sokaktan geçer dururum.

Sen yıllar önce göçüp gittin bu sokaklardan ama

Hayallerimiz koşuşuyor sokağın her köşesinde, 

Yarınlar bizim demiştin, 

Hani şimdi nerde o yarınlar.

Ben göremiyorum..! 

Yoksa orayamı çekip gittin, 

Hani şuuu...

Öve öve bitiremediğin yarınlara.

Ne yarınlar

Ne Dünler

Umrumda değil artık.

Ben

Dünden sonra, yarından önce

Hala seviyorum seni', 'Yıllardır bu sokaktan geçer dururum. Sen yıllar önce göçüp gittin bu sokaklardan ama Hayallerimiz koşuşuyor sokağın her köşesinde,  Yarınlar...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dunden-sonra-yarindan-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün, Bir gün daha olmayacak...', 'bir-gun-bir-gun-daha-olmayacak-ali-saglam-3-b2ndb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün...

Seninde hayallerin özlemlere dönüşecek, 

Seninde kalbinde sevgiler yeşerecek.

Bir gün...

Hatırlayacaksın, bir sevdiğim vardı diyeceksin, 

İşte o an aklına ben geleceğim. 

Bir gün...

Düşüneceksin, bir zamanlar, bir zamanlar

Çılgın gibi aşıktım diye yanıp kahrolacaksın.

Bir gün...

Yürüyeceksin, ardına bile dönüp bakmadan, 

Her köşe başında aklına ben geleceğim.

Bir gün...

Ağlayacaksın, Üzüleceksin, işte o an, 

Gözyaşlarını inan sevgilim ben silmeyeceğim.

Bir gün...

Unutacaksın, düşünmeyeceksin bile, 

İşte o an seni çok seven biri olmayacak...', 'Bir gün... Seninde hayallerin özlemlere dönüşecek,  Seninde kalbinde sevgiler yeşerecek. Bir gün... Hatırlayacaksın, bir sevdiğim vardı diye...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-gun-bir-gun-daha-olmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğe Satılan Aşklar', 'gelecege-satilan-asklar-ali-saglam-3-moa6m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm bazen, 

Sendende yakın oluyor bana.

Sana ihanet etmek istemiyor ruhum ölümle.

Ama sen bana ihanet ettin birtanem.

Hemde hiç sevmiyorum.

Dediğin biriyle...

Para için değermiydi, 

Bu sevdayı yıkmaya.

Sende haklısın, 

Sevgi herşeye çare değil.

Ama unutma, , , 

Herşey değildir para, 

Sen olmadan da yaşanmaz ki, 

Benim için bu dünya...!', 'Ölüm bazen,  Sendende yakın oluyor bana. Sana ihanet etmek istemiyor ruhum ölümle. Ama sen bana ihanet ettin birtanem. Hemde hiç sevmiyorum....', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gelecege-satilan-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Tanem', 'hayat-tanem-ali-saglam-3-ci91h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçurumlar kadar derin bu sevda

Ve o kadar parça parça, 

Ayrılık kazınmış alnıma, 

Silemem ki sileyim, 

Nur tanem...

Ölüm kadar gerçek bir sevgiydi, 

Aramızdaki engellere rağmen.

Sen benim herşeyimdin, 

Sevgi çölünde açmış çiçeğimdin, 

Gül tanem...

Sevgi pınarı, kurumuşsa ne olur sanki, 

Gözyaşlarım var ya..! 

Bu sevda denizi ikimize dar geldi, 

Artık haram oldu yaşamak.

Bir tanem...

Aramız belki bir adım, 

Belki yıllarca uzaklıktayız.

Umudumu soldurmuyorum, 

Seni hep özlüyorum, 

Hayat tanem...', 'Uçurumlar kadar derin bu sevda Ve o kadar parça parça,  Ayrılık kazınmış alnıma,  Silemem ki sileyim,  Nur tanem... Ölüm kadar gerçek bir se...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayat-tanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana da Böyle Acı Çekmek Yakışır.', 'bana-da-boyle-aci-cekmek-yakisir-ali-saglam-3-86cum', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acılarla çilelerle geçiyor ömrüm, 

Ömrümün sonuna gelmiş gibiyim, 

Böyle vuruyorken sırtımdan sen, 

Belkide çoktan ölmüş gibiyim...

Seninle birgün sanki bir dakika.

Sensiz birgün sanki bir asır.

Tarifi yok çektiğim acıların

Banada böyle acı çekmek yakışır...', 'Acılarla çilelerle geçiyor ömrüm,  Ömrümün sonuna gelmiş gibiyim,  Böyle vuruyorken sırtımdan sen,  Belkide çoktan ölmüş gibiyim... Seninle ...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bana-da-boyle-aci-cekmek-yakisir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdare Ediyorum İşte', 'i-dare-ediyorum-i-ste-ali-saglam-3-frkk8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat

Düşündüğün

Kadar

Tatlı olsaydı

Birtanem

Yaşaman 

İçin 

Bir

Anlam

Kalmazdı

Biliyormusun

Sensizde

İdare 

Ediyorum

Ama

Yinede

Seni

Çok

Seviyorum....', 'Hayat Düşündüğün Kadar Tatlı olsaydı Birtanem Yaşaman  İçin  Bir Anlam Kalmazdı Biliyormusun Sensizde İdare  Ediyorum Ama Yinede Seni Çok Se...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/idare-ediyorum-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine De', 'yine-de-ercan-cetin-2cyek', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gülüşünü yakalamak içindi, 

Parçalayışım kendimi.

Liseli kızlar gibi tatlıydı gülüşlerin, 

Aklım benim değildi artık.

Kendimi kaybedişimi kimse sezmesin diye, 

Uzak durdum senden kan ağlayarak.

Kalbimi tutup eline koymak istedim, 

Anlatamazdım çünkü başka türlü aşkımı.

Çok konuşan ama gerekenleri söyleyemeyenlerdenim.

Ne yapalım yaratılışımız bu, 

Bu yüzden çekiyorum acıları, belkide daha azını.

İlk reddedilişim beni öyle yaraladı ki, 

Kanatırsam durduramam diye korkuyorum birdaha.

Tüm ceseretimi topayıp bir kere daha denemek, 

Sana seni seviyorum demek istiyorum yinede.', 'Bir gülüşünü yakalamak içindi,  Parçalayışım kendimi. Liseli kızlar gibi tatlıydı gülüşlerin,  Aklım benim değildi artık. Kendimi kaybedişim...', ARRAY['Türk Edebiyatı','Şiir','Ercan Çetin']::text[], 8.5, '{"poet":"Ercan Çetin","poet_slug":"ercan-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yine-de-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaf Dağının Ardına', 'kaf-daginin-ardina-ercan-cetin-4y1yf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cesaretimi toplayıp sana, 

Seviyorum seni demek, 

Sonra tüm dünyanın hazinelerinden vazgeçmek, 

Sonra herşeyden umarsızca kaçmak istedim.

Tuttum kendimi, sıktım yüreğimi kendi ellerimle.

Her seni görüşte böyle mi çarpılacaktım? 

Böyle mi gidecekti aklım kaf dağının ardına,', 'Cesaretimi toplayıp sana,  Seviyorum seni demek,  Sonra tüm dünyanın hazinelerinden vazgeçmek,  Sonra herşeyden umarsızca kaçmak istedim. Tu...', ARRAY['Türk Edebiyatı','Şiir','Ercan Çetin']::text[], 8.5, '{"poet":"Ercan Çetin","poet_slug":"ercan-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kaf-daginin-ardina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmam', 'sanmam-ercan-cetin-hwda5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aklımdan gitmiyorsun.

Aklım kalbime savas açıyor.

Olmaz diyor, uymaz sana.

Hep kaybediyor, hep

Hep sarı saçların aklımda.

Gözlerin gözlerimde

Umut vermesende

Yarınım hep senle

Nasıl özlemem ben seni

Bir gel desen durdurur mu

Kalbimi aklım? 

sanmam..', 'Aklımdan gitmiyorsun. Aklım kalbime savas açıyor. Olmaz diyor, uymaz sana. Hep kaybediyor, hep Hep sarı saçların aklımda. Gözlerin gözlerimd...', ARRAY['Türk Edebiyatı','Şiir','Ercan Çetin']::text[], 8.5, '{"poet":"Ercan Çetin","poet_slug":"ercan-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sanmam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pes Etmek Yok Öyle', 'pes-etmek-yok-oyle-ali-saglam-3-3ceqn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamaya mecbursun, 

Kendi için olmasa bile, 

En azından benim için, 

Sevdiklerin, sevenlerin için

Yaşamaya mecbursun, 

Şöyle göğsünü gere gere, 

Karşı koymalısın dertlere, 

> dedirtmek için.

Yaşamaya mecbursun, 

Hayat acımasız olsada, 

Kahrını çekemesen de, 

Çekmelisin yaşamak için.

Yaşamaya mecbursun, 

Şöyle bağıra bağıra, 

Gözlerimin içine baka baka, 

Mutluyum demek için.', 'Yaşamaya mecbursun,  Kendi için olmasa bile,  En azından benim için,  Sevdiklerin, sevenlerin için Yaşamaya mecbursun,  Şöyle göğsünü gere g...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pes-etmek-yok-oyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Nefretimsin', 'en-buyuk-nefretimsin-ali-saglam-3-u0q8h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yokluğunla doldururum ben kadehleri, 

Yalnızlığımla yıkarım hep geceleri, 

Kaldırımlarda oldum bir serseri, 

Yıllardır böyle avuturum ben kendimi...

Derbeder diyorlar, görenler halimi.

Sormadılar bir kez olsun derdimi, 

Senki içimdeki sevginin katili, 

Yıllardır böyle bilirim ben seni, 

Eze eze bitirdim ben gururumu, hislerimi

Yana yana bitirdim içimdeki hasreti, 

Ama bir türlü bitiremedim bendeki seni, 

Yıllardır böyle kazandın nefretimi', 'Yokluğunla doldururum ben kadehleri,  Yalnızlığımla yıkarım hep geceleri,  Kaldırımlarda oldum bir serseri,  Yıllardır böyle avuturum ben ke...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/en-buyuk-nefretimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Sevgi', 'i-cimdeki-sevgi-ali-saglam-3-4js4d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgi içimde

Yeşil bir ağacın

Dökülen yaprakları gibi, 

Yalnızlık içimde

Kahverengi gözlerden

Dökülen yaşlar gibi, 

Sen içimde

bir binanın 

Sökülen taşları gibisin birtanem...', 'Sevgi içimde Yeşil bir ağacın Dökülen yaprakları gibi,  Yalnızlık içimde Kahverengi gözlerden Dökülen yaşlar gibi,  Sen içimde bir binanın  ...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/icimdeki-sevgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Mutlu Yıllara', 'nice-mutlu-yillara-ali-saglam-3-0f4qb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeni yıllar yeni umutlar

Ve nice zorluklar

Korkmayalım yaşayalım

Gel...

Bazen sevinçten

Bazı zaman kederden

Korkmayalım ağlayalım

Gel...

Yeni yıllar yeni felaketler

Ve nice umutsuzluklar

Korkmayalım dimdik duralım

gel...', 'Yeni yıllar yeni umutlar Ve nice zorluklar Korkmayalım yaşayalım Gel... Bazen sevinçten Bazı zaman kederden Korkmayalım ağlayalım Gel... Yen...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nice-mutlu-yillara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Adım', 'adim-adim-ali-saglam-3-fk0bn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir adım atar

Yıkılırsın

Bir adım atar

Mutlu olursun

Bİr Adım Atar

Hüzün bulursun

Bir adım atar

Sevinçten boğulursun

Bir adım atar

Feryat edersin

Bir adım atar

sevdiğini haykırırsın

Bir adım atar

Umutlarını yitirirsin

Bir adım atar

Ümitlere boğulursun

Bir adım atar

Kaybolursun

Bir adım atar

Beni bulursun

Bir adım atar

Üzülürsün

Bir adım atar

Kollarımda uyursun

Benim olursun, , ,', 'Bir adım atar Yıkılırsın Bir adım atar Mutlu olursun Bİr Adım Atar Hüzün bulursun Bir adım atar Sevinçten boğulursun Bir adım atar Feryat ed...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/adim-adim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bir Yaşam İksir''i', 'ask-bir-yasam-i-ksir-i-ali-saglam-3-roz5n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yaşam iksiridir gülmek

Acıları azaltır

Mutluluğu çoğaltır

Ve her gülüş, insanın ömründe

Ummadığı depremler yaratır...

Bir yaşam iksiridir aşk

Hüzünleri azaltır

Sevgiyi Çoğaltır

Ve her aşk, insanın kalbinde

Ummadığı yaralar yaratır...

Bir yaşam iksiridir gözler

Yalanları azaltır

Gerçekleri çoğaltır

Ver her göz, insanın gözünde

Ummadığı yaşlar yaratır...

Bir yaşam iksiridir ölüm

Herşeyi azaltır

Hiçbişeyi çoğaltır

Ve her ölüm, insanın yaşamında

Ummadığı ölümler yaratır...', 'Bir yaşam iksiridir gülmek Acıları azaltır Mutluluğu çoğaltır Ve her gülüş, insanın ömründe Ummadığı depremler yaratır... Bir yaşam iksiridi...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-bir-yasam-iksir-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimin Derinliğinde Boğulacaksın', 'gozlerimin-derinliginde-bogulacaksin-ali-saglam-3-2e3ce', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki unutulmazsın

Belki şahanesin

Belki muhteşemsin

Ama riyakarsın

Ama yalancısın

Ama hainsin

Seni hep sevecek

Bu gönül

Hep kalbimde yaşayacaksın

Ne var ki

Adını her andığımda

Gözlerimin derinliğinde 

Gözyaşlarımda boğulacaksın...', 'Belki unutulmazsın Belki şahanesin Belki muhteşemsin Ama riyakarsın Ama yalancısın Ama hainsin Seni hep sevecek Bu gönül Hep kalbimde yaşaya...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerimin-derinliginde-bogulacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok(luk) sun', 'yok-luk-sun-ali-saglam-3-fa01h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç anlamayacaksın değil mi? 

Senin güzelliğinin hayata kattığı, 

Bir anlam yok...

Ne kolu kısa sevdalarının

Ne mini etek boyu düşüncelerinin

Ne de güneş gözlüğü karası ümitlerinin

Paçavra kadar değeri yok...

Kronik bir yarasın aslında

Bazen sünizit

Kimi zaman gastrit

Ama en çokta

Anjiyoluk kalp krizleri

İnan içimde bundan başka 

Hiç bir anlamın yok...

Fiziğini çözmek zor 

Kimyanı imkansız

Beni en çok yoran

Garip psikolojin

Beynindeki her nöron''u

Ezbere bilsemde

Anaforlarına alışmanın çaresi yok...

Sana yazılan destanları

Unut yırt at

Sevgili ayağa kalk

Artık kendine bir anlam kat...', 'Hiç anlamayacaksın değil mi?  Senin güzelliğinin hayata kattığı,  Bir anlam yok... Ne kolu kısa sevdalarının Ne mini etek boyu düşüncelerini...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yok-luk-sun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek', 'tek-murat-yapakci-tn5y1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz kalmak mı acı veriyor, 

Yoksa seninleyken sana doyamamak mı? 

Ben bir güneşi bu kadar sıcak bilirdim, 

Sana dokunmadan önce.

Ben bir annemi bu kadar güsel bilirdim, 

Seni görmeden önce.

Ben ne oldum böle? 

Tek sen varsın, tek olacaksın.

Bir bakışın olacak.

Karşında ben, 

Seninle daha mutlu günler adına...', 'Sensiz kalmak mı acı veriyor,  Yoksa seninleyken sana doyamamak mı?  Ben bir güneşi bu kadar sıcak bilirdim,  Sana dokunmadan önce. Ben bir ...', ARRAY['Türk Edebiyatı','Şiir','Murat Yapakçı']::text[], 8.5, '{"poet":"Murat Yapakçı","poet_slug":"murat-yapakci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorular', 'sorular-can-akin-2-hslox', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha ne kadar dayanabilirim söylesene, 

öpmemek için o güzel dudakları, 

her yalnız kalışımızda? 

Daha ne kadar uzak tutabiliriz kendimizi söylesene, 

aşkın o kavurucu sıcaklığından? 

Daha ne kadar kaçabiliriz kendimizden, 

hissedip de içimizdeki o ateşi, 

yayılırken tüm bedenimize yavaş yavaş? 

Daha ne kadar avutabilirim kendimi şiirlerle sevdiğim? 

Daha ne kadar susabilirim söylesene? 

Daha ne kadar dayanabilirim? 

Dayanmam gerek mi peki?', 'Daha ne kadar dayanabilirim söylesene,  öpmemek için o güzel dudakları,  her yalnız kalışımızda?  Daha ne kadar uzak tutabiliriz kendimizi s...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sorular-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sen?', 'ya-sen-can-akin-2-tq8xw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben, karşında en yalın, en çıplak halimle durdum, bütün maskelerimden arınmış olarak…

Ben, ben oldum senin karşında herşeyden vazgeçip yıllar sonra…

Yalansız, art niyetsiz ve içten...

Sadece bir sevi sıcaklığıydı istediğim, gördüğüm o sımsıcak bakışlarında...

Yapmacıksız ve gerçek olan...

(Belki de bir halüsinasyondu gördüğüm - artık çok geç nasılsa..) 

Ben, üşüdüm be gülüm anlıyormusun beni? 

Üşüdüm...Çok üşüdüm senden önce...

Belki de bunlar son çabalarım, 

O donuk taşyürekli insanlara benzememek için...

O maskeli baloya gitmemek için...

O soğuk, o acımasız oyunu oynamamak için...

Donarak ölmemek için...

Peki ya Sen?', 'Ben, karşında en yalın, en çıplak halimle durdum, bütün maskelerimden arınmış olarak… Ben, ben oldum senin karşında herşeyden vazgeçip yılla...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ya-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-mehmet-geckin-7uc60', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu akşam o kadar sıcakki yıldızlar

içime koskoca bir yanardağ akıyor

yüreğimin etrafında bir meçhul geziniyor

ağlıyor sensizlik yağmurunda.bir garip

dua dua yalvarıyor bakışları ufukta

sahipsiz bir at koşuyor muştulanan sabahta

koskoca bir yürek yanıyor..şu aralar..

bu akşam kelimeler o kadar soğukki

yüreğime sanki kar yağıyor..

titriyor gözbebekleri yıldızların

hesap veriyor yapraklar ölürcesine..

üşüyen bir deniz sarıyor benliğimi

taşıyamaz oluyor yükünü yıllar..

yüreğime sanki kar yağıyor...

bu akşam o kadar uzuyorki zaman

gül rengi bir sonsuzluk gizli yüreğimde 

sere serpe uzanıyor sular boşluğa..

mevsimler eriyor..dallarında sevdanın

en hissedilmez kokular bürüyorki sensizliğimi..

bir sonzuzluk gizli yüreğimde.bu sıralar

bu akşam o kadar özledimki seni

gökyüzü bile ağlıyor..

talihsiz sevgiler konuyor avuçlarıma 

rüzgarın saçlarında kayboluyor ellerim

beyaz bir şimşek vuruyor bizi

ellerin en ulaşılmaz vuslat oluyor

hasret deniyor artık gözlerinin rengine 

katlanılmaz bir acı kaplıyor hayalerimi

seni o kadar özlüyorumki

yüreğim bile şaşıyor

bu akşam yıldızlar bile ağlıyor..

ve bütün yıldızlar senin için 

yüreğime akıyor...', 'bu akşam o kadar sıcakki yıldızlar içime koskoca bir yanardağ akıyor yüreğimin etrafında bir meçhul geziniyor ağlıyor sensizlik yağmurunda.b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Geçkin']::text[], 8.5, '{"poet":"Mehmet Geçkin","poet_slug":"mehmet-geckin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bu-aksam-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Adına', 'senin-adina-mehmet-geckin-m46kw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlıyor sensizlik yağmurunda bir adam

Reyhan kokusuyla karışmış misk kokulu gül bahçem

Mevsimler eriyor dallarında sevdanın 

Al rengi bir gül gibi sonsuzluk gizli yüreğimde

Gurup eden güneşi yakalarcasına yalvaran talihsiz

Ardına bakmadan ufukta vefalı dost gözleyen garip

Neyi varsa fedadır bir sevdalı yüreğe...', 'Ağlıyor sensizlik yağmurunda bir adam Reyhan kokusuyla karışmış misk kokulu gül bahçem Mevsimler eriyor dallarında sevdanın  Al rengi bir gü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Geçkin']::text[], 8.5, '{"poet":"Mehmet Geçkin","poet_slug":"mehmet-geckin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/senin-adina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamın', 'anlamin-serhat-cagdas-px31j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlamın büyük olmalı

İri sevdalar taşımalı ellerin

Düşünce  derde

Bir türkü tutturup

Sonsuzluğuna yelken açabilmeliyim

Anlamın büyük olmalı

İsmini harflere böldüğümde

Her harfinden bir yaşam bulmalıyım

Yani

Düş vermeli

Umut vermeli bana

Adını her söyleyişimde 

Anlamın büyük olmalı

Büyük kavgalara girebilmeliyim senin için

Bir ülkeyi

Baştan başa dolaşabilmeliyim ardından

Gecenin bir vaktinde yalnızlığıma katabilmeliyim seni

Yoldaşım gibi.......

Anlamın büyük olmalı

Güzel yarınlar 

Düşündürtmeli insana yüzün

Güzel günler

Can verebilmelisin 

Sözgelimi 

Yağmur tanesiyle, kuruyan dallara

Tükenmişliğin kıyısında bir şehre

Nefes olabilmelisin

Mavi olabilirsin gökyüzünde

Bakınca sana

Özgürlük diyebilmeliyim bütün sevincimle

Dağlarda bir çığlık......

Duyunca sesini

Peşinden sürüklenebilmeliyim gizemli doruklara

Anlamın büyük olmalı

Ki gülüşün....

Müjdesiyse baharın

Anlamında yaşamın başlangıcı

Anlamında sevmenin.......

Anlamın büyük olmalı

Geceler boyu düşündüğüme değmeli.......', 'Anlamın büyük olmalı İri sevdalar taşımalı ellerin Düşünce  derde Bir türkü tutturup Sonsuzluğuna yelken açabilmeliyim Anlamın büyük olmalı ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çağdaş']::text[], 8.5, '{"poet":"Serhat Çağdaş","poet_slug":"serhat-cagdas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/anlamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-serhat-cagdas-ppj1s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şaşırıp durma öyle! 

Sokaktan 

Çocuk seslerinin gelmediğine

Sabahtan

Sana gelirken

Ben  topladım

Hepsini kendimde

Şimdi

Sokaklar sessiz

Ama 

Yüreği kalabalık

Yüreği çocuk

Bir adam

Duruyor kapında! ! ! ! ! ! ! ! 1', 'Şaşırıp durma öyle!  Sokaktan  Çocuk seslerinin gelmediğine Sabahtan Sana gelirken Ben  topladım Hepsini kendimde Şimdi Sokaklar sessiz Ama ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çağdaş']::text[], 8.5, '{"poet":"Serhat Çağdaş","poet_slug":"serhat-cagdas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cocuk-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-ozcan-ozcan-2qqlj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sana iç çekesin, 

İçin için ağlayasın, 

Gözyaşı dökesin diye

Bakmadım.

Ben sana güzel gözlerinde

Kır çiçekleri, kırmızı karanfiller, 

Mor menekşeler ve

Tomurcuk güller

Açsın diye 

Baktım inan.', 'Ben sana iç çekesin,  İçin için ağlayasın,  Gözyaşı dökesin diye Bakmadım. Ben sana güzel gözlerinde Kır çiçekleri, kırmızı karanfiller,  Mo...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özcan']::text[], 8.5, '{"poet":"Özcan Özcan","poet_slug":"ozcan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozyasi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demir Kapılar', 'demir-kapilar-ozcan-ozcan-nhzde', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllardır ne demir kapılar kapadım

Şu yüreğimin üstüne

Kah kilitledim

Kah  sürgüledim

Onları içeriden

O kapıların önünden

Kimler  geçmedi  ki

Esmerleri

Sarışınları

Ve  de

Kumralları

Gün oldu

Hep birlik oldular

Yürüdüler üstüme  üstüme

Beynimi ve yüreğimi

Teslim almaktı  niyetleri

Bense ne  boyun eğdim

Ne  teslim oldum

Yıllara meydan  okurcasına

Direndikçe  direndi

O  sevdalı  yüreğim

Ama  bir  gün

Nerede olduğunu

Sen  de çok iyi  biliyorsun

Ansızın çıkıverdin karşıma

Beynimdeki  şifreyi çözerek

Kor  ateşler gibi 

Düştün yüreğime

İşte o an

Ne  açılmadık kapı

Ne  kırılmadık

Kilit bıraktın', 'Yıllardır ne demir kapılar kapadım Şu yüreğimin üstüne Kah kilitledim Kah  sürgüledim Onları içeriden O kapıların önünden Kimler  geçmedi  k...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özcan']::text[], 8.5, '{"poet":"Özcan Özcan","poet_slug":"ozcan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/demir-kapilar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben''den Vazgeçtim..', 'ben-den-vazgectim-sukru-soyarslan-6nyl2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi için aşk yoluna baş koydum

Bir vefasız için, ser’den vazgeçtim.

Aşk’ta yalan olmaz, yalana doydum

Bana cefa veren yar’dan vazgeçtim.

Aşk ölümsüz, Sevgi kutsal bilirdim

Gel..dese sevgili, koşar gelirdim.

Sevgim için, canım bile verirdim

Faydası olmayan can’dan vazgeçtim.

Aşk’a dair ne yazıp, ne söyleyim? 

Aşk’a köle olurum; ben, böyleyim.

Aşk’ım olmasa, serveti neyleyim? 

Hepsi sizin olsun, mal’dan vazgeçtim.

Dilim tek seni anar, yalnız seni

Bir yabancı sararken güzel teni.

Sorma, ne haldesin diye bende’ni

Seni saramayan, ten’den vazgeçtim.

Sen’den gelen cefaya boyun eğdim

Her türlü hakarete, göğüs gerdim.

Gururu, kibiri yerlere serdim

Haya’yı unuttum, ar’dan vazgeçtim! 

Hüzünlerle örülmüş aşkın yolu

Gözüm göremez oldu, sağı solu.

Her günüm sana ait, Sen’le dolu

Beni alıp gittin, Ben’den vazgeçtim.', 'Sevgi için aşk yoluna baş koydum Bir vefasız için, ser’den vazgeçtim. Aşk’ta yalan olmaz, yalana doydum Bana cefa veren yar’dan vazgeçtim. A...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-den-vazgectim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Ölecekmisin', 'sende-olecekmisin-sedat-can-cultk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşkından döksem gözyaşlarımı 

elinle bir defa silecekmisin

uğrunda döksem saçlarımı

saçından bir tel verecekmisin

derinden derine seni düşünsem

ömrüne yazık diyecekmisin

hasretinle bir gün ağlarsam

bana acıyıp gülecekmisin

bu temiz kalbimi sana bağlasam

yaşadıkça beni sevecekmisin

her geçen gün seni ansam

bir defalık sevgilim diyecekmisin

hatırlarsın diye resmimi yollarsam

eline alıp öpecekmisin

gecemde gündüzümde sen desem

ben ölünce SENDE ÖLECEKMİSİN', 'aşkından döksem gözyaşlarımı  elinle bir defa silecekmisin uğrunda döksem saçlarımı saçından bir tel verecekmisin derinden derine seni düşün...', ARRAY['Türk Edebiyatı','Şiir','Sedat Can']::text[], 8.5, '{"poet":"Sedat Can","poet_slug":"sedat-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sende-olecekmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahilde Dün Gece', 'sahilde-dun-gece-ozcan-ozcan-4cqre', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüyamda  gördüm

Seni yine

Misafir  oldun  bana

Sahilde dün  gece

Sere serpe uzanıp

Dayayıp bir elini kumlara

Bir  elini kalem yaparak

O güzel sözleri

Gülümseyip heceleyerek

Yazdın  kumlara

Hatırlamıyor musun? 

Tanığın bir  ben oldum

Bir  de deniz

Bahar bitmeden

Gelmişti yaz 

Sahilde o gece

İkimizin hatırına

Ne esen deli rüzgarlar

Kopan fırtınalar

Ne sağanak yağmurlar

Azgın dalgalar

Kumlara yazılmış

O güzelim  sözleri

Silemediler

Dokunamadılar

Ne  bir cümlesine

Ne  de bir  hecesine

O  sözler

Sadece yazılmadılar

Sahildeki kumlara

Kazındılar elbet  çoktan

Beyinlere yüreklere', 'Rüyamda  gördüm Seni yine Misafir  oldun  bana Sahilde dün  gece Sere serpe uzanıp Dayayıp bir elini kumlara Bir  elini kalem yaparak O güze...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özcan']::text[], 8.5, '{"poet":"Özcan Özcan","poet_slug":"ozcan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sahilde-dun-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bir Yerden Tanıyorum', 'seni-bir-yerden-taniyorum-ozcan-ozcan-yan7g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben   seni   bir  yerden

Tanıyorum

Sorup   sorguluyorum

Seni  bilmem  ama

Gözlerin hiç   yabancı 

Değil  bana

Seni   bir   yerden  tanıyorum

Öyle  tanıdık

Öyle  bildik gibisin

Sanki  kırk  yıllık

Dost  gibisin

Seni   bir  yerden   tanıyorum

Bir  an çocukluk   arkadaşım  gibi

Geldin  bana

Ne  yalan  söyleyeyim sana

Sanki aynı bahçede el   ele   dolaştık

Kol  kola  girip oyunlar  oynadık    

Sevinçle   neşeyle  sınıfları  doldurduk

Hep   bir  ağızdan marşlar okuduk 

Yüreğimiz yerinden oynacarcasına                                                                              

Seni  bir  yerden tanıyorum                                                    

Çok  geçmedi  anlamam

Seni   nereden tanımam

Bu    gizin   farkına  varmam

Çok   geçmedi

Seni  bir  yerden   tanıyorum

Ben   seni

Bir  yerden  değil

Can  arkadaşlığından

Yosun  renkli, gülen

Güzel  gözlerinden

Doğal   güzelliğinden  tanıyorum 

Hiç  yabancı   değilsin  bana

Güzel   olmasan

SEN Ne   tanıdık, bildik  olurdun

Ne  dost  gibi  gelirdin   bana

Gerçeği  söylüyorum  inan    sana

Şu  kısacık zamanda  kanım  kaynadı  sana

En   çok  sevdiğimden daha  yakınsın  bana

Hiç   yabancı   değilsin   BANA', 'Ben   seni   bir  yerden Tanıyorum Sorup   sorguluyorum Seni  bilmem  ama Gözlerin hiç   yabancı  Değil  bana Seni   bir   yerden  tanıyorum...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özcan']::text[], 8.5, '{"poet":"Özcan Özcan","poet_slug":"ozcan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/seni-bir-yerden-taniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oguldan Babaya', 'oguldan-babaya-unal-akbaba-tcqaa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gurbet mahkumuyum aldi ömrümü

Hasretle zulümle sardi gönlümü

Dert edinme kam edinme sözümü

Saygiyla hürmetle ricadir baba

Sitemli sözleri alma kaleme

Kagit diye yazma dertli sineme

Oglun ünal, sana dargin belleme

Gözlerimde hasret dilde hecedir baba

Bu bahtim karali talih aglatir

Gözler görmeyince gönül iragdir

Gurbetde ünalin bagri yaradir

Sorsan ahvalimi görsen nicedir baba

Güldürürmü bilmem aglatan kader

Siladan cüdayim gurbetden heder

Yastigim gözyasi  yorganim keder

baharim güz günüm gecedir baba

Kiyamam diyemem derdimi sana

Dökülmez kaleme dönmez kelama

Af eyle darilma, gücenme bana

Üstümüzde yüce mevlam, kutsaldir baba', 'Gurbet mahkumuyum aldi ömrümü Hasretle zulümle sardi gönlümü Dert edinme kam edinme sözümü Saygiyla hürmetle ricadir baba Sitemli sözleri al...', ARRAY['Türk Edebiyatı','Şiir','Ünal Akbaba']::text[], 8.5, '{"poet":"Ünal Akbaba","poet_slug":"unal-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oguldan-babaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetde Ahvalim', 'gurbetde-ahvalim-unal-akbaba-4cwql', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana derler ne bu keder ne bu kam

bir ömrü gurbetde harcayan benim

Tütüyor burnumda o güzel silam

Rüyamda görübte aglayan benim 

Bak yine süslendi bahceler baglar

Simdi yesermisdir bizim yaylalar

Bir bir göc eyledi gurbetden kuslar

Garib baykus gibi tüneyen benim

Gurbet ana olmus kardasdir zulüm

Yaban  diyarlarda acidir ölüm

Bitmez bu askerlik cikmaz teskerem benim

Gurbet ocagini bekleyen benim', 'Bana derler ne bu keder ne bu kam bir ömrü gurbetde harcayan benim Tütüyor burnumda o güzel silam Rüyamda görübte aglayan benim  Bak yine sü...', ARRAY['Türk Edebiyatı','Şiir','Ünal Akbaba']::text[], 8.5, '{"poet":"Ünal Akbaba","poet_slug":"unal-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbetde-ahvalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bahtsiz Basim', 'bu-bahtsiz-basim-unal-akbaba-1nmu4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ari oldum ciceklere

Kondum barin alamadim

Gönül oldum güzellere 

Aktim yari bulamadim

Ünalim ceva agini 

Ne ettiysem bölemedim

Dost  dedim verdim canimi

Dost, dan dostluk göremedim

Toprak oldum yollarina 

Yürüdüler of demedim

Kostum her bir dertlerine 

Kötü oldum yaranmadim

Hayal oldu ümitlerim 

Murat ettim göremedim

Uzak oldu hep yollarim

Ben menzile varamadim

Bumudur hayatda gaye

Hep agladim gülemedim

Gurbetde günleri aya

Saydim yila bölemedim

Zararmiydi bu hayatim

Karim neydi tartamadim

Bir gün okunur fermanim

Yasadimmi anlamadim', 'Ari oldum ciceklere Kondum barin alamadim Gönül oldum güzellere  Aktim yari bulamadim Ünalim ceva agini  Ne ettiysem bölemedim Dost  dedim v...', ARRAY['Türk Edebiyatı','Şiir','Ünal Akbaba']::text[], 8.5, '{"poet":"Ünal Akbaba","poet_slug":"unal-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-bahtsiz-basim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firar İster Yüreğim', 'firar-i-ster-yuregim-altug-can-aldanmaz-2azti', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mahpus damında, duvarlarına ince çizgiler kazınmış

En aydınlık köşesi güneşi günde bir saat gören

Ranzaları ümitsizliğin karasıyla boyanmış 

Ve bacasından yalnızlık dumanları tüten

Emsali cehennemde bir hücredir benim yüreğim

Mevsimsiz bir yağmura benzer ya da

Esen rüzgara meydan okur damla damla

Ritminde en hüzünlü şarkıların fısıltısı vardır

Vefa olsun diye arada bir mutluluğu ansa da

Ensesini her zaman yalnızlığın nefesi okşamaktadır', 'Mahpus damında, duvarlarına ince çizgiler kazınmış En aydınlık köşesi güneşi günde bir saat gören Ranzaları ümitsizliğin karasıyla boyanmış ...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Can Aldanmaz']::text[], 8.5, '{"poet":"Altuğ Can Aldanmaz","poet_slug":"altug-can-aldanmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/firar-ister-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Soruyorlar', 'seni-soruyorlar-ozcan-ozcan-gqodf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana, 

Seni soruyorlar

Kimdir? 

Neyin nesidir 

Gibisinden

Ben de

Diyorum ki

O, 

Yüreğimle

Beynim arasında

Sürekli dans eden

Bir balerin kadar 

İnce ve narin

Ve

Bir kraliçe kadar

Güzel mi güzel

Diyorum

Bilmem, 

Seni anlata bildim mi? 

Bence

Yeter de 

Artar bile...', 'Bana,  Seni soruyorlar Kimdir?  Neyin nesidir  Gibisinden Ben de Diyorum ki O,  Yüreğimle Beynim arasında Sürekli dans eden Bir balerin kada...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özcan']::text[], 8.5, '{"poet":"Özcan Özcan","poet_slug":"ozcan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seni-soruyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhakeme', 'muhakeme-okkes-yuksek-o2leo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünya, hayat ve ölüm; bunlar birer bilmece, 

İnsan hiç düşünmez mi nedir sırlar kendince? 

Akıl fikir ve zeka; bunlar birer vasıta, 

Yücelerin yücesi hakîkata varmaya, 

Zevk, sefahat, eğlence unutmaya vesile, 

Unutmak çare değil, varılacak menzile, 

Gurur, inat ve inkar bunlar birer isyandır, 

Rab''be isyan edenin sonu mutlak hüsrandır.', 'Dünya, hayat ve ölüm; bunlar birer bilmece,  İnsan hiç düşünmez mi nedir sırlar kendince?  Akıl fikir ve zeka; bunlar birer vasıta,  Yüceler...', ARRAY['Türk Edebiyatı','Şiir','Ökkeş Yüksek']::text[], 8.5, '{"poet":"Ökkeş Yüksek","poet_slug":"okkes-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/muhakeme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Ulaşmak', 'gule-ulasmak-okkes-yuksek-u6qii', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nabzımda zamanın kalb atışları, 

An be an öteler çağırır beni.

Her yanım masiva çalılıkları, 

Güle ulaşmaktan alıkor beni.', 'Nabzımda zamanın kalb atışları,  An be an öteler çağırır beni. Her yanım masiva çalılıkları,  Güle ulaşmaktan alıkor beni....', ARRAY['Türk Edebiyatı','Şiir','Ökkeş Yüksek']::text[], 8.5, '{"poet":"Ökkeş Yüksek","poet_slug":"okkes-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gule-ulasmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gün Dünden Bir Fazla', 'her-gun-dunden-bir-fazla-omer-karatepe-i080b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamın utanan yüzü

bakirlik masalı anlatıyor 

kırbacın ucu

kan 

iğreti teni aynanın

atmacanın düşlediği

sis cennetinde dokunuş

şehrin fireri sokaklarında

dudak izleri

şarap testilerinde

yüzyıllardır

kaçarak büyüyor cenim

ellerinden çivilenmeyi beklerken

yalnız senin ve benim bildigim

o kutsal anda

yedi katlı bir mezardan gelmiyor sesim

öylesi çıplak

örtün beni! 

örtün! 

''''oku! ''''diyor

içimdeki ses

yedi geceye susuyorum', 'Yaşamın utanan yüzü bakirlik masalı anlatıyor  kırbacın ucu kan  iğreti teni aynanın atmacanın düşlediği sis cennetinde dokunuş şehrin firer...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karatepe']::text[], 8.5, '{"poet":"Ömer Karatepe","poet_slug":"omer-karatepe","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/her-gun-dunden-bir-fazla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesaplaşmadan', 'hesaplasmadan-omer-karatepe-zrr7h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şaşarım sana ay ışıgı

Yangın ekmiyorum

Bir ölmüşün taklidi yazı

Geceye boyasam sunmadıklarımla

Sonra kapıyı da kırarak

Çıkıp gelecek

İmbikte unutulmuş sarhoşluk

Öyle davetlimsin

Yangın ekmiyorum 

Bir ölmüşün taklidi yazı

Son hesaplaşmadan

usumda kalan

Ölümcül sus işareti

Bir öpüşe

Rüyalar sokakğında

Sorgularlar adamı

 _ki öyledir ifadem_

Beyaz saçların ihbarlandığında

susan şiirler yazıyorum

Öyle davetlimsin', 'Şaşarım sana ay ışıgı Yangın ekmiyorum Bir ölmüşün taklidi yazı Geceye boyasam sunmadıklarımla Sonra kapıyı da kırarak Çıkıp gelecek İmbikte...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karatepe']::text[], 8.5, '{"poet":"Ömer Karatepe","poet_slug":"omer-karatepe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hesaplasmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimliksiz', 'kimliksiz-omer-karatepe-d1x1x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölüm uyandı

Tarla kuşlarıyla

Sevişinde

Öksüz kasımpatı kapıları

Ardına kadar açık

Bir demli çaya

Esirlikten söz edilir

Gel!', 'Ölüm uyandı Tarla kuşlarıyla Sevişinde Öksüz kasımpatı kapıları Ardına kadar açık Bir demli çaya Esirlikten söz edilir Gel!...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karatepe']::text[], 8.5, '{"poet":"Ömer Karatepe","poet_slug":"omer-karatepe","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kimliksiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derinde Kör Balık Mavisi', 'derinde-kor-balik-mavisi-bilge-karasu-dbmvw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben derin deniz balıklarının yüzüşünde kör dalgın

yosunlara sürünen karnımın arıklığı içinde onların

rengini bilemeden

Karanlığın içinde yukarının ışığını unutmuşçasına unutmamışçasına

arar bulur yitirirken maviyi bir daha

bulamayacakmışçasına yitirmiş

Gözlerimizin yanından yanlarından akan soğukları serinleri

ısınmaz sanıp ağzımı loş sulara boş sulara diri etlere saplanan

dişlerime kal etmiş

Usta dalgıçların serptikleri gök taşlarını zümrütleri yakutları

kırallarını eğlendirmek için dalıp ciğerlerini

kusasıya kovaladıklarında

can taşlarını onlardan önce bulup kapan ciğerlerini daha kolay

kusmaları için derine daha derine kendi sularımın

karanlığına çeken

Soğuğun tükenmeyeceğini ışığın çekildiğini diplere

hiçbir zaman erişemeyeceğini sanan ben birden

bir çukurdan

Ağan maviyi gördüm kara değil boz değil yeşil bile değil

susuz bitkisiz doruksuz maviyi ısınan suların içinden

unuttum

her şeyi suyun yüzü olduğunu mavinin güneşe karıştığı yerde

başka mavilerle birleştiğini suyun

ısındığı yerde

unuttum yokoldu onlar dip suları ısınmaz artık

bir yerde herşey bitti mavide yaşıyoruz

Ben derin deniz balıklarının yüzüşünde kör dalgın

maviyle çarpıştığımız mavileştiğim balıklaştığı

körlüğümüzün aydınlandığı

yerde.', 'Ben derin deniz balıklarının yüzüşünde kör dalgın yosunlara sürünen karnımın arıklığı içinde onların rengini bilemeden Karanlığın içinde yuk...', ARRAY['Türk Edebiyatı','Şiir','Bilge Karasu']::text[], 8.5, '{"poet":"Bilge Karasu","poet_slug":"bilge-karasu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/derinde-kor-balik-mavisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam Benden Hiçbir Şey Anlamıyor', 'babam-benden-hicbir-sey-anlamiyor-baris-pirhasan-9w8dy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sırıtarak başka yol yok diyorlar

Çözmek için nice nice düğümü

Yapışacak birazcık izin versem

Avucuma İskender''in kılıcı

Biraz uyusam bir parça aklım yatsa

En azından sinirlerim düzelir

Siperimde mışıl mışıl uyurken

Kördüğümler soykırımla çözülür

Biliyorum İskender''in kılıcı

Bileylendi binlerce fabrikada

Kabzası tam ellerimize göre

Havada mis gibi kan kokusu

Yumuşasam azıcık inat etmesem

Şiddeti hep dağıtmasam gövdeme

İskender''in kördüğüm anısını

Yaşatmayı istemez miyim ben de

Kurşun marş ve bayraklar arasında

Biliyorum insan nasıl bilenir

Kördüğüme vurunca keskin çelik

Mızmız dünya çizgisinden boşanır

Ama sular yükseliyor boğuyor

İçimdeki kahramanı usulca

İki büklüm gülüyorum verirken

Anlamını bu karanlık sevince

Babam benden hiçbir şey anlamıyor

Yürüyoruz şeytanımla elele

Pişmanlığın yakıcı özlemini

Taşıyarak kalbimizde dörtnala...', 'Sırıtarak başka yol yok diyorlar Çözmek için nice nice düğümü Yapışacak birazcık izin versem Avucuma İskender''in kılıcı Biraz uyusam bir par...', ARRAY['Türk Edebiyatı','Şiir','Barış Pirhasan']::text[], 8.5, '{"poet":"Barış Pirhasan","poet_slug":"baris-pirhasan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/babam-benden-hicbir-sey-anlamiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmak', 'olmak-yasar-kurt-0jxo5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olmak 

Ya da  olmus gibi gostermek herseyi

Bir renkli gozluk cami gibi ince 

Siyahin en korkuncu kadar kustah 

Sanirim ayrilik kadar acidir tekrar gorusmek

Yeniden ayrilacagini bilerek

Ancak sayilabilecek kadar cok zaman var

Konusacak hicbir sey kalmayincaya dek

Güne düsmüs yarasalar gibi 

Aptal ve saskin bir halde bakismak

Olmasini istemek 

Keske olsaydi demekten 

Baska care kalmamis', 'Olmak  Ya da  olmus gibi gostermek herseyi Bir renkli gozluk cami gibi ince  Siyahin en korkuncu kadar kustah  Sanirim ayrilik kadar acidir ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kurt']::text[], 8.5, '{"poet":"Yaşar Kurt","poet_slug":"yasar-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olmak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keyif', 'keyif-behcet-necatigil-i2xqg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Meyhane sen güzelsin, 

Satıcıların olmasa.

Ezilir siteminde ufalmış gözlerin

Masalar, bir masa

İhtiyar adam gelir, açlıktan kalma, yanık

Börek satar, taze.

Aldınız, yiyemezsiniz, 

Oturur midenize.

Siz kızarsınız başka, irin gibi yüzlü, 

Çiçekçi kad
..........
..........', 'Meyhane sen güzelsin,  Satıcıların olmasa. Ezilir siteminde ufalmış gözlerin Masalar, bir masa İhtiyar adam gelir, açlıktan kalma, yanık Bör...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/keyif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-huseyin-ucak-ffys2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bende sevdim herkes gibi arkadaş

Uğruna ne acılar ne ızdıraplar çektim

Geceler aşılmaz geldi

Ardından inanılmaz bir darbe indi

Şimdi sana soruyorum arkadaş

Bütün bunların sonunda ne oldu? 

Bütün bu acıların bütün bu hasretin

Sonunda ne oldu haa? 

Bir elveda bile etmeden

İnsafsızca acımadan çekti gitti

Şimdi anladımki arkadaş

Şu üç şey yalanmış

Aşk, sevgi, mutluluk

Bütün bunların sonunda arkadaş

Terk edilmek varmış.', 'Bende sevdim herkes gibi arkadaş Uğruna ne acılar ne ızdıraplar çektim Geceler aşılmaz geldi Ardından inanılmaz bir darbe indi Şimdi sana so...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Uçak']::text[], 8.5, '{"poet":"Hüseyin Uçak","poet_slug":"huseyin-ucak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/arkadas-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırımlar', 'kaldirimlar-huseyin-ucak-xdzad', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birtek şu kaldırımlar bilir

Sana olan sevgimi aşkımı

Yüreğimdeki patlayan volkanları

Kaç kere şahit olmuştur

Güzlerimden akan yaşlara ve

Seni düşünürken dalgın yürüyüşüme

Herşeye şahit olduğu gibi

Şimdide ayrılığımıza şahit oldu

Bu soğuk taş kaldırımlar', 'Birtek şu kaldırımlar bilir Sana olan sevgimi aşkımı Yüreğimdeki patlayan volkanları Kaç kere şahit olmuştur Güzlerimden akan yaşlara ve Sen...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Uçak']::text[], 8.5, '{"poet":"Hüseyin Uçak","poet_slug":"huseyin-ucak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kaldirimlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sivrisinekler', 'sivrisinekler-hilmi-tanrikulu-0frwd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazda geliyor, 

Şehirdeki bütün sivrisinekleri öldüreceğim...

Sahip olmaktan aciz olduğum bedenine, 

Dokunmasınlar, 

Hakkım olan kanında içmesinler diye...', 'Yazda geliyor,  Şehirdeki bütün sivrisinekleri öldüreceğim... Sahip olmaktan aciz olduğum bedenine,  Dokunmasınlar,  Hakkım olan kanında içm...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sivrisinekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerini açmadı hayat', 'gozlerini-acmadi-hayat-hilmi-tanrikulu-gmzso', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerini kapattı hayat.

Ölümle sevişmekten gelen, 

Kuşlar kondu, 

Sırayla alnına.

Gözlerini açmadı hayat...', 'Gözlerini kapattı hayat. Ölümle sevişmekten gelen,  Kuşlar kondu,  Sırayla alnına. Gözlerini açmadı hayat......', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gozlerini-acmadi-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzün', 'yuzun-cezmi-ersoz-ap3l5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim kaderim bu, 

öylece karşına oturup seyrediyorum

yüzünden geçen zamanları...

Küçük bir çocuk olan yüzün

annesinin kalbinin kapılarında kalmış...

Kırgın düşlerinde sakladıgın...

İlk gençlik oluyor sonra yüzün

öyle eksik, öyle yarım kalmış büyümelerden durgun...

Sevdayla ışıyan, 

çaresiz aşkların şiirlerinde mısra mısra yaşlanan yüzün...

Benim kaderim bu

öylece karşına oturup 

seyrediyorum zamanın içinden geçen yüzlerini...

Bana sevdalı bir yüzün vardı eskiden

o şimdi yalnız içimde saklı...', 'Benim kaderim bu,  öylece karşına oturup seyrediyorum yüzünden geçen zamanları... Küçük bir çocuk olan yüzün annesinin kalbinin kapılarında ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yuzun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzümün Aynadaki Boşlugu', 'yuzumun-aynadaki-boslugu-cezmi-ersoz-5ldse', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uçurum dibinde nasıl göründügümü

Merak edreim hep.

Yüzümün aynadaki boşluguna hep bakmak isterdim.

İnançlarımın kırık döküldügü yeri anlamak için

kalabalıklar içindeki yalnızlıgıma dokunmak isterdim...

Aşktı adın uçurumda, yanı başımda

aynadaki suretimdi yüzüm, 

aykırı kanardı bana.

İnançlarımın çogu yalanmış

alay ederdi benimle.

Çok geç anladım, kalabalıklar arasındaki

senmişsin dokunamadıgım...

Yalnızlıgım diye küçümsedigim senin sevginmiş, 

Geceleri ansızın uyanıp

incitilp durdugum senin yoklugunmuş...

Onca sevişmeden sonra degişememişsem, 

sihirli bir aydınlıkta, 

içimde bir yer sonsuz hasret kaldıgı içinmiş...

İşte onca yalan geçen hayatımda

buymuş tek gerçegim...', 'Uçurum dibinde nasıl göründügümü Merak edreim hep. Yüzümün aynadaki boşluguna hep bakmak isterdim. İnançlarımın kırık döküldügü yeri anlamak...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuzumun-aynadaki-boslugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Olduğunu Bilmediğim Birine', 'kim-oldugunu-bilmedigim-birine-cezmi-ersoz-t3cmg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karşılıksız aşkının zehrini taşıyordu bana 

Kokusu sinmişti inatçı ruhuma, kitalarıma, ellerime... 

Öyle çok öpüşürdük ki, 

Ağzının tadıyla yerdim yemeklerimi... 

Öylesine inanıyordu ki dünyadaki son aşkla beni sevdiğine, 

Bir gün ansızın korkunç bir özlem duymaya başlamıştım 

Kim olduğunu bilmediğim birine... 

Şimdi ağzımda karşılıksız aşkın o aç tadı... 

Karşımda o... 

Yine hüzünlü, yine yenik... 

Ama eşitiz artık, 

Damarlarımızda karşılıkız aşkın o zehirli kanı...', 'Karşılıksız aşkının zehrini taşıyordu bana  Kokusu sinmişti inatçı ruhuma, kitalarıma, ellerime...  Öyle çok öpüşürdük ki,  Ağzının tadıyla ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kim-oldugunu-bilmedigim-birine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmail Deniz', 'i-smail-deniz-halil-i-brahim-korkmaz-dqkg8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Silahıma çiçek ektim

Artık Barış olsun

İsmini İsmail Deniz koydum

Barış senin olsun', 'Silahıma çiçek ektim Artık Barış olsun İsmini İsmail Deniz koydum Barış senin olsun...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ismail-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Koyun-2-', 'el-koyun-2-bayram-tunca-aic57', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'El koyun, melemez oldu

O yârden, haber gelmez oldu

Yârimi, askerde acep ne oldu

Onun hasreti bana çok koydu

Ah el koyun ne olur, dön gel koyun

Dönmezsen, hep bükük kalır boyun

Tâ ezelden Yörüktür, benim soyum

Onsuz hiç yaşamam daha çok toyum

El koyun, güzel mi güzel çanlı

Benim sevdiğim geliyor, anlı şanlı

Yârim, şehit olmuş, elbisesi kanlı

Şehitler ölmez, benim yarim canlı

Kurt, el koyunu yemiş, el koyun melemiyor

Sevdiğim yar, şehit olmuş, kendi gelemiyor

Ah kuzum, meleme, gelmez el koyun geri

Yaban gülü, ağlama, gelmez o yarin geri

B. TUNCA/05.07.2000', 'El koyun, melemez oldu O yârden, haber gelmez oldu Yârimi, askerde acep ne oldu Onun hasreti bana çok koydu Ah el koyun ne olur, dön gel koy...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/el-koyun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağulu Bir Hüzün', 'agulu-bir-huzun-ahmet-telli-rr069', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beklenmedik bir anda terk edilmişsindir bütün sevdiklerince

Suçlamak istemesende hiç kimseyi üzünçle yanmakta yüzün

Adını bile koyamadığın bir boğunç dolmakta şimdi yüreğine

Ve usulca ağmaktadır gözlerinin peteğine ağulu bir hüzün...', 'Beklenmedik bir anda terk edilmişsindir bütün sevdiklerince Suçlamak istemesende hiç kimseyi üzünçle yanmakta yüzün Adını bile koyamadığın b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/agulu-bir-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Meyhaneci', 'selam-meyhaneci-yildiray-coban-4ytli', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selam meyhaneci

Selam içki denizinin ünlü tayfaları

Şaşırdınız biliyorum

Güpegündüz ne işi var buralarda

Ama ne gelir elden

Dertlerim taşar oldu gecelerden

Neyse biz keyfimize bakalım

Haydi garson tazele herkesin kadehlerini

Kendine de dodur aşçıbaşına da

Ama bana en güzelini doldur

Adı ölüm içkisi olsun 

İstersen tarifini ben yapayım

Başla; 

O en büyük bardağı al eline

İçine bir kadeh viski 

Sevgi nedir bilmeyenler için

Sonra bir kadeh şarap

Sevipte sevilmeyenler için

Ardından bir kadeh rakı

Canevinden vurup terkedenler için

Son olarak bir parça zehir koy bardağa

Maneviyat uğruna yanıp tutuşanlar için

Şimdide yavaşça karıştır bardağı

Haydi garson haydi dostlar haydi tayfalar

Kadehleri kaldıralım

Şu iğrenç düzenin şerefine içelim

Şerefsizliğine içelim.....', 'Selam meyhaneci Selam içki denizinin ünlü tayfaları Şaşırdınız biliyorum Güpegündüz ne işi var buralarda Ama ne gelir elden Dertlerim taşar ...', ARRAY['Türk Edebiyatı','Şiir','Yıldıray Çoban']::text[], 8.5, '{"poet":"Yıldıray Çoban","poet_slug":"yildiray-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/selam-meyhaneci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Sözüm...', 'i-lk-sozum-ercan-gencer-fl96w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Demek sevgin gibi hasretim de çok büyükmüş 

Aşk benim için büyük bir  yaraymış 

Seni o gözyaşlarım bile teselli edememiş 

Akmış bunca zaman delicesine

Dedin ya bana ''sabret geçer zaman''

İşte o an 

Canlı canlı mezara koydun beni 

Anladım ki hasretin öldürücek beni 

Senin sevgini yaşayamadan

Ya da seni sevmeyi doyamadan 

Sanki bir hançer sapladın kalbime 

Vurdun acımasızca zaman diyerek beni

Eğer vursaydın kalbimdeki seni 

İşte o zaman gerçekten öldürmüş olurdun beni. 

Sen unuttun demek bütün zamanı

Kolay olmuş anlaşılan 

Kolay mı unutmak sensiz geçen zamanı 

Söyle bende bileyim yöntemini 

Belki o zaman katlanırım

Sensiz saniyelere 

Ama şunu bilki 

Dün sevmedim seni 

Seni bugün de sevmedim 

Ben seni yarın sevdim. 

Çünkü yarınlar hiç bitmezmiş 

Benim sevgimde ömrümün sonunda da bitmeyecek. 

Sen yoktun  yanımda 

Bana kalan 

Üç beş  resimle gözyaşlarım. 

Bide senden aldığım kipriğin.

Evet duruyor eskisi gibi senden aldıklarım

Sana yazdığım şiirlerle birlikte... 

Alışmaya çalışıyorum senli sensizliğime

Geceler uykusuzca sırdaşım olmuş 

Karanlık günler ise kabusum. 

Ve... 

İşte geldi zamanı 

Kalkıyor kavuşma treni 

Nice sevdalıları yanında götürürken 

Öyle sevecen öyle sevinçli

Nasılda gülüyor güldürüyor dertsiz ve gamsız... 

Ben binmiş trene geliyorum! 

Geride kalanlar  için gözyaşı bile dökmüyoum 

Bu nasıl sevgi anlayışı Allah''ım? 

Birde üstüne üstlük gülüyorum

Oysa neler demiştim kendi kendime: 

''Sensiz ölüyorum galiba

Ayrılık biter gelmesin aklına

Senden çok uzağım

Dayanamam hasretine

Acımadan kıyarım canıma....

Bu sana ne son sözüm nede sona yakın 

Bu benim sana hep ilk sözüm

Seni Seviyorum....', 'Demek sevgin gibi hasretim de çok büyükmüş  Aşk benim için büyük bir  yaraymış  Seni o gözyaşlarım bile teselli edememiş  Akmış bunca zaman ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Gencer']::text[], 8.5, '{"poet":"Ercan Gencer","poet_slug":"ercan-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/ilk-sozum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım', 'aklim-oguzkan-bolukbasi-iee5s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aklım açık denizlerde

yelkensiz ve rüzgarsız seyrediyor

bilcümle elalem

deliydi zaten beklenirdi diyor

sen aklımı denizlerinde yüzdürdüğüm kadın

bir liman ayırdın mı bana

birgün sığınacağım

ve huzur bulacağım', 'aklım açık denizlerde yelkensiz ve rüzgarsız seyrediyor bilcümle elalem deliydi zaten beklenirdi diyor sen aklımı denizlerinde yüzdürdüğüm k...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aklim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Arzular (Ayrılık Kavağı)', 'o-arzular-ayrilik-kavagi-ensar-aktas-d8mn8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nedense bu akşam

Diğerlerinden biraz farklı

Biraz daha kederliyim

Biraz daha sensizim

Hani o arzular varya

Seni bana hatırlatan

Özleminle yakan

İşte bu akşam

O arzular içimde

Büyüdü büyüdü

Dallı budaklı

Bir kavak gibi serpildi

İçime sığmaz oldu

Boynum büküldü

Gözlerim doldu

Hani dokunsalar

Çocuklar gibi ağlayacağım

Hani o arzular diyorum

Beni ağlatmak yerine

Alsa götürseler

Beni benden uzaklara

Senin yanına

İşte o zaman

Akşamlar daha farklı olur

Gözlerim keder yerine

Huzur bulur

Seni bulur

Mevsim sonbahar olur

O ayrılık kavağı sararıp solar

Yaprak döker

Kurur, odun olur

Yanar içimi ısıtır

Kül olur, yok olur

Mevsim ilkbahar olur

O arzular yeniden yeşerir

Aşk olur, sen olur

Gönlüm sana kavuşur

Yeniden huzur bulur

Şen olur

Gülşen olur

Rotterdam,31.10.1991', 'Nedense bu akşam Diğerlerinden biraz farklı Biraz daha kederliyim Biraz daha sensizim Hani o arzular varya Seni bana hatırlatan Özleminle ya...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/o-arzular-ayrilik-kavagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benimsin Sevgilim', 'sen-benimsin-sevgilim-ensar-aktas-cc1l6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim yüreğimde büyüttüğüm çiçeğimsin

Sen benim gözlerimde tüttürdügüm hasretimsin

Sen benimsin sevgilim

Sen benim yaşlı gözlerimdeki sevincimsin

Sen benim her aldığım nefesimsin

Sen benimsin sevgilim

Sen benim etrafımda dolaşan meleğimsin

Sen benim yanımdayken bile özlediğimsin

Sen benimsin sevgilim

Sen benim gönlümden içeri bir gönülsün

Sen benim aşk bahçemin gonca gülüsün

Sen benimsin sevgilim

Sen benim tek amacım tek gayemsin

Sen benim herşeyim, birtanemsin

Sen benimsin sevgilim

Sen benim her tebessümde güldüğümsün

Sen benim uğrunda severek öldüğümsün

Sen benimsin sevgilim

Rotterdam,08.11.1991', 'Sen benim yüreğimde büyüttüğüm çiçeğimsin Sen benim gözlerimde tüttürdügüm hasretimsin Sen benimsin sevgilim Sen benim yaşlı gözlerimdeki se...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-benimsin-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerefine', 'serefine-ensar-aktas-jhr8h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tek sigara geçti elime

Rafları düzeltirken dün gece

Hâlâ teninin kokusu vardı, 

Birde kuru tütün kokusu üzerinde

Yıllar öncesi geldi gözümün önüne

Tanışmamıza bu sigara olmuştu vesile

O yüzden içmeyip saklamıştım onu

Senden bana tek hatıra diye

Aşkımız kısa sürmüştü seninle

Ama izleri silinmedi bende senelerce

Bu sigarayı içime çekip avundum

Sabahı olmayan sensiz gecelerde

Şimdi şerefine kaldırıyorum sigaranı

Ve yakıyorum bak bütün anılarını

Sağlığına, mutluluğuna içiyorum

Ve iade ediyorum sana

İade ediyorum bende unuttuğun aşkını

Rotterdam,26.07.2002', 'Bir tek sigara geçti elime Rafları düzeltirken dün gece Hâlâ teninin kokusu vardı,  Birde kuru tütün kokusu üzerinde Yıllar öncesi geldi göz...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/serefine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşyüzüncü Şiir', 'besyuzuncu-siir-ensar-aktas-wpfl4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu beşyüzüncü şiirim

Ve beşyüzikinci çoçuğum

Gizem bir, Ethem iki

Toplam beşyüziki

Dile bile kolay değil tabi

Ama, hayatta yok başka

Bir dikili taşım, ağacım

Neyim var neyim yoksa

Bir eşim, birde çocuklarım

Rotterdam,10.08.2002', 'Bu beşyüzüncü şiirim Ve beşyüzikinci çoçuğum Gizem bir, Ethem iki Toplam beşyüziki Dile bile kolay değil tabi Ama, hayatta yok başka Bir dik...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/besyuzuncu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-altug-alper-pbyml', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'biz biz iduk

ikimiz ikimiz iduk

üçümüz üçümüz iduk

hepimiz da bitlisliydik iduk...

bil bakalım 

baaa

biz kim iduk...

bre....', 'biz biz iduk ikimiz ikimiz iduk üçümüz üçümüz iduk hepimiz da bitlisliydik iduk... bil bakalım  baaa biz kim iduk... bre.......', ARRAY['Türk Edebiyatı','Şiir','Altuğ Alper']::text[], 8.5, '{"poet":"Altuğ Alper","poet_slug":"altug-alper","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdesin', 'i-cimdesin-arslan-alp-uu0i1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçine çektiğin hava kadar yakındayım, 

Çepeçevre sarmışım seni, 

Kalbimin en güzel yeri senin, 

Uzakta sanma kendini', 'İçine çektiğin hava kadar yakındayım,  Çepeçevre sarmışım seni,  Kalbimin en güzel yeri senin,  Uzakta sanma kendini...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/icimdesin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Hacımusa', 'bizim-hacimusa-sabit-i-nce-sy8tt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dedesinin adı konmuş, 

Biraz ufacık boyluymuş, 

Azgınmış, deli huyluymuş, 

Bizim küçük hacımusa.

Ağzı kuş misali küçük, 

Gözü açık mı ki, açık.

Kafası biraz ufacık, 

Bizim küçük Hacımusa.

Sesi erkek gibi çıkar, 

Ağlayınca yaşlar akar.

Malına da iyi bakar, 

Bizim küçük Hacımusa.

Alıyım der, verme sevmez, 

İnat eder laf dinlemez, 

Babasından ayrı gezmez, 

Bizim Küçük Hacımusa.

Çöttür çöttür yürür gider, 

Anasına pek naz eder.

Sevenleri o da sever, 

İnce, azgın Hacımusa.', 'Dedesinin adı konmuş,  Biraz ufacık boyluymuş,  Azgınmış, deli huyluymuş,  Bizim küçük hacımusa. Ağzı kuş misali küçük,  Gözü açık mı ki, aç...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bizim-hacimusa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Yoğiken', 'biz-yogiken-sabit-i-nce-le14o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu yalan dünyada kalırım sanma, 

Makama, mevkiye sakın aldanma.

Evlada, iyale, mala güvenme, 

Kim varımış biz burada yoğiken? 

Anandan üryanda geldin dünyaya, 

Kullan aklını da bağlan hüdaya.

Gaflete düşüp de uyman modaya, 

Kim varımış biz burada yoğiken? 

Nic''oldu da Karacaoğlan nic''oldu, 

Dünya boşalıp kaç kere doldu.

Sultan Süleyman''a acep ne oldu? 

Kim varımış biz burada yoğiken? 

Yedi defa devran döner durulur, 

Sanki ''Dünya Benim'' derde kurulur.

Çok yakında sur düdüğü vurulur, 

Kim varımış biz burada yoğiken? 

İNCE''yim insanım, halifeyim ben, 

Ahsen''i takvimsin eğer bilirsen, 

Yaradana sağlam ıkrar verirsen, 

Ölmez baki kalır bu can sağiken.', 'Şu yalan dünyada kalırım sanma,  Makama, mevkiye sakın aldanma. Evlada, iyale, mala güvenme,  Kim varımış biz burada yoğiken?  Anandan üryan...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biz-yogiken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşa...', 'bosa-sabit-i-nce-oa2e8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boşa çaldım çabaladım

Şu sevdaya yenik düştüm

O kaçtıkça kovaladım

Şu sevdaya yenik düştüm

Aşk atına binem dedim

Şu dünyada gülem dedim

ben yoluna ölem dedim

şu sevdaya yenik düştüm

gecelerim gündüz ettim

tükendim eridim bittim

kahbe felek sana n''ettim

şu sevdaya yenik düştüm

sevem dedim sevdirmedi

kim olduğun bildirmedi

çok ah çektim aldırmadı

şu sevdaya yenik düştüm

kader dedi de aldattı

elim ayağım bağlattı

yaktı, kül etti dağlattı

şu sevdaya yenik düştüm

İNCE yarayı sarmadı

bir gün halimden sormadı

yeter dedim ya durmadı

şu sevdaya yenik düştüm', 'Boşa çaldım çabaladım Şu sevdaya yenik düştüm O kaçtıkça kovaladım Şu sevdaya yenik düştüm Aşk atına binem dedim Şu dünyada gülem dedim ben ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bosa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Deprem', 'bu-deprem-sabit-i-nce-t7sbt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Taze yavruların gözleri açık, 

Göçtüler dünyadan bu deprem ile.

Ey gafil, ey hain çık ortaya çık, 

Takken düştü gene bu deprem ile.

			

Can pazarı Marmara da kuruldu, 

Acı haber geldi alarm vuruldu.

Enkazın altında canlar yok oldu, 

Kesen şişti gene bu deprem ile.

Çimentodan çaldın demir koymadın, 

Dürüstçe haykıran sesim duymadın.b

Kanunlara, nizamlara uymadın, 

Miden çoştu gene bu deprem ile.

Karga gibi gelip cesede konma, 

Ettiğin yanına kalacak sanma, 

Arsızlık edip de peşim dolanma, 

Fırsat geçti gene bu deprem ile.

Arlanmaz, utanmaz namussuz arsız, 

Bilirim yapaman parasız, karsız, 

Seni pek tanırım dinsiz, imansız, 

Vurup kaçtı gene bu deprem ile.', 'Taze yavruların gözleri açık,  Göçtüler dünyadan bu deprem ile. Ey gafil, ey hain çık ortaya çık,  Takken düştü gene bu deprem ile. 			 Can ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-deprem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-sabit-i-nce-geadu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel güzel seninle muhabbet edek, 

Yollar şarkımızı söylesin bugün.

El ele verek de düğüne gidek, 

Diller sevdamızı söylesin bugün.

Hüseyin dardadır imdada yetek, 

Hüda rahmetini yollasın bugün.

Acizlik var iken şöhreti nidek, 

Su çıkmayan gözler ağlasın bugün.

İNCE, dertlerimin dermanı yoktur, 

Güzel tabibini salmasın bugün.

Ehl-i Beyt acısı kalbimde oktur, 

Sinem de yarayı sarmasın bugün.', 'Gel güzel seninle muhabbet edek,  Yollar şarkımızı söylesin bugün. El ele verek de düğüne gidek,  Diller sevdamızı söylesin bugün. Hüseyin d...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bugun-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulursun Kızım', 'bulursun-kizim-sabit-i-nce-qxi15', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Niye elin yanağında duruyon, 

Bilmediğin büyüklerden soruyon

Biliyorum sen de O’nu arıyon, 

Zamanı gelince bulursun kızım.

Niye inatlanıp benlik satıyon, 

Öğrenmek dururken niye yatıyon, 

Büyüklerin sözlerini tutuyon, 

Inşaallah Rabia olursun kızım.

Sana değil yaradana tapıyom, 

Biliyorsun gözüm gibi bakıyom.

Kulağına küpeleri takıyom, 

Dilerim ibretler alırsın kızım.

Bir ince’yim gözlerinden okuyom, 

Aşk ateşin şu özümde yakıyom, 

Bir güzelin cemaline bakıyom, 

Inşallah cemali görürsün kızım.', 'Niye elin yanağında duruyon,  Bilmediğin büyüklerden soruyon Biliyorum sen de O’nu arıyon,  Zamanı gelince bulursun kızım. Niye inatlanıp be...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bulursun-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çift-lik', 'cift-lik-duygu-gunkut-dfw81', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana bir deliler evinin en güzel manzarasını satın al, 

Çocukluk fotoğraflarımızdan oluşmuş bir parka baksın.

Beni sal sonra, gideyim alabildiğine

Sensiz ve kimsesiz, 

Kendi şapkamı sana bırakayım.

Bana, içine yaşamımı sokabileceğim bir çember al, 

Onun dışına çıkayım.

Hayatımı kaybettiğim yerde, 

Onu yeniden bulayım.

Bana bir tavşan al, 

Kırmızı gözlerinin içine bakayım, 

Sonra bir de sana, 

Bir daha tavşana, 

Ve tabii ki aynaya! 

Aynadan kendime bakıp, 

Senden kurtulayım.

Bana seni al, 

Yargılayayım.', 'Bana bir deliler evinin en güzel manzarasını satın al,  Çocukluk fotoğraflarımızdan oluşmuş bir parka baksın. Beni sal sonra, gideyim alabil...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cift-lik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbülüm', 'bulbulum-sabit-i-nce-vjirb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen de benim gibi ah-ü zar etme, 

Benim fiğanlarım yeter bülbülüm.

Sakın ha şaşırıp yad el''e gitme, 

Benim derdim senden beter bülbülüm.

Seher vakti esen yelde kokusu, 

Enva çiçeklerde vardır dokusu, 

Uyandırma dursun, yarin uykusu, 

Koynu hasbahçedir, öter bülbülüm.

Hasbahçe içinde gezer şakırsın, 

Feryat fiğan ile hasret dokursun.

Hangi gözle nasıl yare bakarsın, 

Ağlatma İNCE''yi yeter bülbülüm.', 'Sen de benim gibi ah-ü zar etme,  Benim fiğanlarım yeter bülbülüm. Sakın ha şaşırıp yad el''e gitme,  Benim derdim senden beter bülbülüm. Seh...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bulbulum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama Sebebi', 'yasama-sebebi-duygu-gunkut-xrolg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağzımın kenarında kırıntılar, 

Kelimeler ve tebessümlerden arda kalan

Uyuyorum, 

Zihnime yaslanmış berraklığı

Mert bir kalbin

Bir erkeğin

İlk kez

Benim değiştirmeyeceğim.

İlk kez

Kırıntılar zihnimde

Uyuyorum.

Belki de son kez.

Ne de olsa

Hepimizin

Yaşam sebepleri aynıdır.

Ben sabahları artık

Değiştirmek için değil dünyayı, 

Affetmek için uyanıyorum.', 'Ağzımın kenarında kırıntılar,  Kelimeler ve tebessümlerden arda kalan Uyuyorum,  Zihnime yaslanmış berraklığı Mert bir kalbin Bir erkeğin İl...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasama-sebebi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cahil Kalmasın', 'cahil-kalmasin-sabit-i-nce-xvdcr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uygarlığa bir yol bulayım dersen, 

Okul yap da okut, cahil kalmasın.

Bu dünyada baki kalmak itersen, 

Okul yap da okut, cahil kalmasın.

''İlim Çin de olsa git al'' diyenin, 

Emrin tut ta okut, cahil kalmasın.

''En hakiki mürşit ilim'' diyenin, 

Yolun tut da okut, cahil kalmasın.

''Bir harf öğretenin kölesi ol'' da, 

Karanlık aydınlat cahil kalmasın.

Rızayı bulursun Mevla''da, kulda, 

Hak nurunu parlat, cahil kalmasın.

İNCE ilmin sonu bulunmaz asla, 

Sonsuzluğu anlat, cahil kalmasın.

Bilenle bilmeyen bir mi kıyasla, 

Oku, bilgi anlat, cahil kalmasın.', 'Uygarlığa bir yol bulayım dersen,  Okul yap da okut, cahil kalmasın. Bu dünyada baki kalmak itersen,  Okul yap da okut, cahil kalmasın. ''İli...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cahil-kalmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cani Sırplar', 'cani-sirplar-sabit-i-nce-ffzak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bosna-Hersek kan ağlıyor, 

Acılar yürek dağlıyor.

Gelinler kara bağlıyor, 

Aman Allah imdat eyle...

Cani Sırplar akıtmış kan, 

Bu zulüme dayanmaz can.

Sırplar vermiyorlar aman, 

Aman Allah imdat eyle...

Ecdat yurdu harab olmuş, 

Hastaneler ceset dolmuş.

Dindaşlar çaresiz kalmış, 

Çare Allah imdat eyle...

Boşnaklar zulüm altında, 

Müslüman saltanatında.

Mazlumların feryatında, 

Rahmet Allah imdat eyle.

Rahim olan büyük hüda, 

Acıma yok mu bu dünyada? 

Ses ver artık bu feryada, 

Arşı tuttu imdat eyle...

İNCE''nin kalbi sızlar, 

Kara mıdır bu yazılar? 

Acımıyor şu haçlılar, 

Hilal ağlar imdat eyle.', 'Bosna-Hersek kan ağlıyor,  Acılar yürek dağlıyor. Gelinler kara bağlıyor,  Aman Allah imdat eyle... Cani Sırplar akıtmış kan,  Bu zulüme day...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cani-sirplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çevremiz', 'cevremiz-sabit-i-nce-owhyo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çevremiz temiz olmalı, 

Kıymetini bilmeliyiz.

Herkes mutlu yaşamalı, 

Hem sevip, sevilmeliyiz.

Yemyeşil bir çevre için, 

Vazifemiz yapmalıyız.

Ormanı keseriz niçin, 

Bizler ağaç dikmeliyiz.

Türkiyem bozkır olmasın, 

Erezyon düşmanım olsun.

Kimse havasız kalmasın, 

Heryer pırıl pırıl olsun.

Temiz çevre temiz toplum, 

Olmalı Türk’ün düsturu.

Kuraklığa olma mahkum, 

Yeşil olsun gözüm nuru.

İnce çevreye aşıktır, 

Hep çevreci olmalıyız.

Yeni nesile yazıktır, 

Çevreyi korumalıyız.', 'Çevremiz temiz olmalı,  Kıymetini bilmeliyiz. Herkes mutlu yaşamalı,  Hem sevip, sevilmeliyiz. Yemyeşil bir çevre için,  Vazifemiz yapmalıyı...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cevremiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Severim', 'cok-severim-sabit-i-nce-0808h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hak yoluna gidenleri, 

Çok severim, çok severim.

Her farzını bilenleri, 

Çok severim, çok severim.

Durmayıp da zikredeni, 

Çok severim, çok severim.

Varlığını fikredeni, 

Çok severim, çok severim.

Sünnetini yapanları, 

Çok severim, çok severim.

Ulu emre uyanları, 

Çok severim, çok severim.

Garipliğin bilenleri, 

Çok severim, çok severim.

Daim Allah diyenleri, 

Çok severim, çok severim', 'Hak yoluna gidenleri,  Çok severim, çok severim. Her farzını bilenleri,  Çok severim, çok severim. Durmayıp da zikredeni,  Çok severim, çok ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Film Müziği (After)', 'bir-film-muzigi-after-duygu-gunkut-q4est', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sınırı aşma şansımı kaybettim, 

Kendimi eleverdim.

Üzerime çevrili spot ışıkların

Çıplak aydınlığında, 

Kendi şarkımı söyledim.

Çekici mi buluyordu beni

Evrenin enerjisi? 

Benden bir paratoner gibi

Faydalanıyor muydu tüm bu enerji? 

Yoksa bir ip cambazının

İnancı ile yarattığı

Yumuşacık düşme yastığı etkisi

Tüm korkuları gideren, 

Bana hediye mi edilmişti? 

Gitme, 

Bırakma beni! 

Kaçmanın bir anlamı yok

Gözlerin

Yüreğimi

Kirlettiğinden beri.

Çırılçıplak kaldım

Aydınlığında

Üzerime çevrili spot ışıkların, 

Kendi şarkımı söylediğimden beri.

Sınırı aşma şansımı kaybettim

Ben, 

Kendimi eleverdim.', 'Sınırı aşma şansımı kaybettim,  Kendimi eleverdim. Üzerime çevrili spot ışıkların Çıplak aydınlığında,  Kendi şarkımı söyledim. Çekici mi bu...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-film-muzigi-after-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceylanlara', 'ceylanlara-sabit-i-nce-a482s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Havva da ilk anamızdır, 

Gölde yüzen sunamızdır.

Elimizde kınamızdır, 

Ne güzeldir elde kına.

Memet Muhammetten gelir, 

Dost uğruna canı verir, 

Bir gün eve gelin gelir, 

Kılıç girer o gün kına.

Semra da esmer güzeli, 

Güzel ruhlu taa ezeli, 

Ne hoş huylarla bezeli, 

Teline dokun da sına.

Selda’nın gülümser yüzü, 

Çok temizdir, paktır özü, 

Ceylan bakışlıdır gözü, 

Salınıp geçer bir suna.

Gülay’ın gözleri kara, 

Ne ararsan onda ara, 

Allah düşürmesin dara, 

Keder gelmesin uykuna.

İnce bildiğini yazdı, 

Ne söylesem gene azdı.

Dudakları bal, kirazdı, 

Siz kalmayın kusuruna.', 'Havva da ilk anamızdır,  Gölde yüzen sunamızdır. Elimizde kınamızdır,  Ne güzeldir elde kına. Memet Muhammetten gelir,  Dost uğruna canı ver...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ceylanlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Film Müziği (Before)', 'bir-film-muzigi-before-duygu-gunkut-1eslf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yemyeşil yapraklı bir nane

Yeşeriyor içimde.

Tazeyim, 

Tazeleniyorum yeniden, 

Bir kozadan

Bu kez bir örümcek olarak doğuyorum, 

Bir akrebin namusu filizlenirken içimden.

Yılmayacağım, 

İsyanlarım, 

Bu kez

Sessiz olacak, 

Çıngıraklı yılan

Çıngırağı çalmadan sokacak.

Ben sessiz ve derinden

Yeniden yeşerirken.

Bir örümcek, 

Sabırlı, 

Sabrı bir ipek böceğinden

Ve

Akrebin namusunu bilen, 

Çıngıraklı bir yılanı

Terbiye edebilen.

Filizleniyor içimde

Yemyeşil yapraklı bir nane gibi

Sessiz ve derinden.', 'Yemyeşil yapraklı bir nane Yeşeriyor içimde. Tazeyim,  Tazeleniyorum yeniden,  Bir kozadan Bu kez bir örümcek olarak doğuyorum,  Bir akrebin...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-film-muzigi-before-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bürosyalist', 'burosyalist-kadir-polat-gh7td', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen

Vantilatörle

Üfürüklen

Masa başında

Benim

Kasırgalar tarasın

Islak ve iyot kokulu

Saçlarımı', 'Sen Vantilatörle Üfürüklen Masa başında Benim Kasırgalar tarasın Islak ve iyot kokulu Saçlarımı...', ARRAY['Türk Edebiyatı','Şiir','Kadir Polat']::text[], 8.5, '{"poet":"Kadir Polat","poet_slug":"kadir-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/burosyalist-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Dedigin', 'adam-dedigin-fikret-gorken-lx2t7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adam dedigin bakinca bir yere

Kor arinin gozlerine

Dikis atabilecek kadar ince bakacak

Balistik o gozlerdeki bakisi cozemeyecek

Balistik siska bir comez

Oyle bir sertlik olacak ki o

Aramakla bulamayacak hic kimse

Mohs''un olceginde bile.

Mermidir inanmak

Ask alasi bir huner gerekir yetismek icin ona

Adam dedigin once kendi adamligina inanacak

Her seyden ve herkesten sorumlu tutacak kendini

Saygi duyacak egrelti otuna bile

Insan kromozomlarina sirf

Benziyor diye.

Adam dediginin 

Dilinin altinda civili takozlari yok

Adam dedigin caki boyunda hep

Tok bitlerle yasamayacak o

Yeni ac bitlerin gelmesinden korkmayacak

Gammazin cadirinda oturmayacak 

Adam dedigin saglam duracak

kirik bir iskemlede ne kadar dik durabilirse bir insan

Azi oksar ya basini

yine de onlar icin oynayacak 

cigliklari raflara dizilenler icin grosmarketlerde

Bir eksi elmaya bile flort etmeyecek yuzu

Ala bir suyun kavalindan akacak

Adam dedigin yanik al gullerin durusu

gulusu cigdemsakiz

sozu sirasindan ic

Adam dedigin beyin

serasinda bir animasyon degildir', 'Adam dedigin bakinca bir yere Kor arinin gozlerine Dikis atabilecek kadar ince bakacak Balistik o gozlerdeki bakisi cozemeyecek Balistik sis...', ARRAY['Türk Edebiyatı','Şiir','Fikret Gorken']::text[], 8.5, '{"poet":"Fikret Gorken","poet_slug":"fikret-gorken","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/adam-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedenlerin Sende Kalsın', 'nedenlerin-sende-kalsin-hasim-altunsoy-jmx2s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bende sana mecburum, bilmiyorum... 

Adımı kaç kere yazdın kör duvarlara 

Ve kaç kere fısıldadın 

Akşamüstü kızıllığına 

Deli etme beni 

Bir daha gitme ansızın 

Bu şehir zayıf 

Bu şehir ürkek 

Aklar gözlerinin mavisini 

Bakamaz ardından... 

Oysa biliyorsun 

Nasıl baktığını martıların 

Son uçuşlarında denize... 

Bekliyorum seni 

Olmadığın saatlerin serserisi 

Ve sesine hasret 

Hadi konuş şimdi... 

Anlat neden gittiğini... 

Yada bırak kalsın 

Nedenlerin sende 

Nasıl olsa biliyorum 

Yeter, üzme beni...', 'Bende sana mecburum, bilmiyorum...  Adımı kaç kere yazdın kör duvarlara  Ve kaç kere fısıldadın  Akşamüstü kızıllığına  Deli etme beni  Bir ...', ARRAY['Türk Edebiyatı','Şiir','Haşim Altunsoy']::text[], 8.5, '{"poet":"Haşim Altunsoy","poet_slug":"hasim-altunsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nedenlerin-sende-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesim Senindir Hala', 'sesim-senindir-hala-hasim-altunsoy-x251g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kirlensin istemedim mısraların 

Buğulansın istemedim 

Sana verdiğim deniz 

Sesim senindir hala 

Elinden düşürme bu aç yüreğimi 

Ve beynini verme ellerime 

Ben kadir bilmem... 

Sen damla değilsin denizde 

Sen denizin kendisisin 

Enginliğin yordu beni 

Tutuldum...', 'Kirlensin istemedim mısraların  Buğulansın istemedim  Sana verdiğim deniz  Sesim senindir hala  Elinden düşürme bu aç yüreğimi  Ve beynini v...', ARRAY['Türk Edebiyatı','Şiir','Haşim Altunsoy']::text[], 8.5, '{"poet":"Haşim Altunsoy","poet_slug":"hasim-altunsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sesim-senindir-hala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Görmek', 'guzel-gormek-bayram-tunca-8uvik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her güzellin bir çirkin yanı vardır

Her çirkinin bir güzel yanı vardır

Güzel gören,  ekseriyetle güzel düşünür

Güzel düşünenler de hayattan lezzet alır

B. TUNCA/01.05.2001-10.30', 'Her güzellin bir çirkin yanı vardır Her çirkinin bir güzel yanı vardır Güzel gören,  ekseriyetle güzel düşünür Güzel düşünenler de hayattan ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guzel-gormek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askin Boş Zarfiymiş', 'askin-bos-zarfiymis-sair-karagozlum-ciih1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana askim derdin ayrilmadan önce, 

saclarimi oksardin beni görünce, 

seni birakmam sen benimsin derdin, 

seninlie dünya evine girecegim derdin.

Bir gün olurda ayrilirsak dügününe gelecegim, 

ve son bir defa seninle dans edecegim derdin, 

ben sana bu sözlerine cok kizar ''ALLAH KORUSUN''

yoksa askimiza acimadan kiyarlar derdim sakasini bile ettirmezdim.

Bir gün gercek olacagini düsünemezdim, 

aklini kaybetmis deliye döndüm

gözleim inanamadi davetiyini görünce, 

beyaz bir zarf icinde kutuya attmistin, 

üzerin sakin aglama mecburum yazmistin.

Kötü kader beni bulmustu, 

yüregimi seller bogmustu, 

ve böyle bir darbe alarak yüregim cökmüstü.

Zor topladim kendimi ve girdim salona, 

sana sarilmak isterdim o an 

lacivetler icinde görünce, 

cok yakismisti damatlik üzerinde, 

göz göze geldigimiz o an 

bir kursun yedim gönlüme.

anlatamam dizlerim tutmuyor

basimdan asaga sicak sular akiyordu

ve seni sevdigim icin icim yaniyordu, 

ya senin.....

seninse gözlerinin ici gülüyordu

Bana yine baktiginda gözlerinin ici doldu, 

sira takiya gelince kendimi sasirmistim, 

ellerim titreye titreye bir beyaz zarf eline vermistim, 

Sana ''bunlar senin '' diyerek salonu aglaya aglaya terk ettmistim.

Sen zarfimi korkarak acmis cok sasirmissin, 

soguk bir gülücük yaparak insanlara bakmissin

yasli dedemiz davetlilerin arasinda görmüs yanina cagirmissin.

''bos bir zarf verdi bana acaba ne demek istedi'' demissin, 

Dedemiz ise sana gülümseyerek''o bos degil ki oglum ici cok dolu hatta zarfin icine sigdaramamis ''demis.

sen bitkin bir halde dikili kalmis yanindaki beyazlari saran hanim ise korku basmiti

seni kaybetme korkusu yasiyor ama yinede sevenleri acimadan ayiriyor.

Son olarak bana bir mektup yazmistin sözlerin söyle basliyordu: 

Canim askim affet beni, 

acimasizca terk ettim seni, 

nedenlerini sorma bana

anlatamam ama mecburdum.

Sana birsey daha söylemek istiyorum ne olursun beni hic unutma cünkü ben hala seni seviyorum

seni icimde tasiyorum

eger bir gün olurda kizim olursa sonsuz askim senin ismini koyucagim

ona bakarak seni hatirlacagim

bu tükenmez askimizi böyle yasatacagim.

ona sanki senmisin gibi bakacagim kavusamadik diye kendimi böyle avutacagim.

sana mutluluklar dilerim

sevenini birakip

batakliga mahkum eden

hayirsiz sevgilin.

Bunu okuduktan sonra

beynimden vurulmusa döndüm

ve bir anda nasil oldugunu hatirlamiyorum kendimi bicakladigimi hatirliyorum

sayisiz gecen günlerim hastanade artik faydasiz

ve kendimi burdan kurtarmis

ardimda hayirsiz seveni  birakmistim

ama ismimi tasiyacak olacak kizini göndermistim.

O büyüdükca kahroluyordun

ona baktikca beni görüyordun

geceleri basini yorganin altina sokup acindan

agliyordum

allaha  benim de canimi al diye yalvariyordun

ve beni bir saniye unutmadan seneler boyu icinde yasatiyordun.

ben nasil aci cektimse sende böyle cekiyordun.+', 'Bana askim derdin ayrilmadan önce,  saclarimi oksardin beni görünce,  seni birakmam sen benimsin derdin,  seninlie dünya evine girecegim der...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/askin-bos-zarfiymis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini Arayan İnsan', 'kendini-arayan-i-nsan-murat-gezer-jp4qx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşey bir soruyla başlar.

Ben neden yaratıldım? 

Beni kim yarattı? 

Pusuda bekleyen katil sorular! 

Akıl mantığın silahı,kurtulmak işten değil

Ya delirmek ya da unutmak var birde işin içinde

Sorular soru

Cevaplar mantığımızın olmazları içinde

Herşey dediğimiz birkaç şey

Akıl ve mantığın çerçevesinde

Akıl ve mantığı aşan ilahi sırlar

Samimiyet,gerçek aşk (ihlas)     dairesinde! 

Herşey bir soruyla başlar.

Cennet ve cehennem? 

Ölümden sonra yaşam varmı? 

Şüpheler zihinlerdeki korkunç dolgular! 

Bilgi delinin oyuncağı,çıldırmak işten değil

Ya keşfetmek ya da öylesine yaşamak var birde işin içinde

Nedenler niçin

Hakikatler bilmediklerimizin olurları içinde

Varlık dediğimiz birkaç şey

Hayat ve ölüm çerçevesinde

Hayat ve ölümü aşan ilahi sırlar

Teslimiyet,gerçek aşk (iman)     dairesinde! 

M.gezer

Bu Şiir; 

Bayat Abisinin Birtanesi :) 

Canımdan da Öte Canım, 

En Kıymetlim "Şevval" Hanıma Armağan Olsun...', 'Herşey bir soruyla başlar. Ben neden yaratıldım?  Beni kim yarattı?  Pusuda bekleyen katil sorular!  Akıl mantığın silahı,kurtulmak işten de...', ARRAY['Türk Edebiyatı','Şiir','Murat Gezer']::text[], 8.5, '{"poet":"Murat Gezer","poet_slug":"murat-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kendini-arayan-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum Kanat CIRPIYOR.', 'ruhum-kanat-cirpiyor-gulay-atilay-s6b7v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabahın ilk ışıklarında 

Okuduğum mısralarda 

Zihnim allak bullak olurken 

Güclü arzular hisseden bedenim 

Bedenini sevgiyle sarıyor 

Mısraların döküldüğü yüreği sarmak.. 

Yazan parmakları avuclarına alıp 

Doyasıya öpmek koklamak ister gibi.. 

Güçlü arzular hisseden beden. 

Zamana isyan mı ediyor ne? 

*** 

Ah bir görebilsem bir tutabilsem ellerini 

Sevebilsem sarabilsem arzulu bedenini 

Ellerimin avuclarında kayboluşunu hissedebilsem 

Zaman ve arzular isyan ediyor evet.. 

Ruhum kanat çırpıyor. hırçın, yüreğim 

Sana sevgine uçmak istiyor.. 

17/08/2002', 'Sabahın ilk ışıklarında  Okuduğum mısralarda  Zihnim allak bullak olurken  Güclü arzular hisseden bedenim  Bedenini sevgiyle sarıyor  Mısral...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruhum-kanat-cirpiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler Armonisi-10-', 'guzel-sozler-armonisi-10-bayram-tunca-zp3b0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçanların hava, kaçanların ise, karadır meskenleri

Uçanların yüksekte, kaçanların alçaktadır yuvaları

B. Tunca/11.11.2002-11.11

Dünya görüp, duyduğumuz şeylerden ibaret değildir

Görmeyip, duymayıp, fakat hissettiğimiz de dahildir

ADEMOĞLU/28.03.2002-17.10

Gönderdiğin güller kucağıma, sevgin içime sığmadı

Gönderdiğin resmin cebime, aşkın kalbime sığmadı

ADEMOĞLU/03.07.2001-16.30

Bunca Hizmetime Rağmen Bir Dikili Ağacım Olmadı

Çok Görülmezse, Mezar Taşım Bari Ağaçtan Olsaydı

ADEMOĞLU/06,09,2001,14,30

Ay geceleri, Güneş gündüzleri gökyüzünü arşınlıyor

Şair Bayram, gece/gündüz senin yollarını arşınlıyor

10.12.2002-12.10

Paramızı kaybetsek, bir şekilde tekrar kazanabiliriz

Fakat kaybettiğimiz zamanımızı tekrar kazanamayız

ADEMOĞLU/22.06.2002-08.22

Azrail’in ayak seslerini hep şah damarımda hissettim

Duyduğum gıcırtıları da, hep tabutumunki zannettim

B. Tunca/08.11.2002-12.58

Her kim benden çok annesini severse, onu kıskanırım

Her kim anasını öf derse onun adına üzülür/utanırım

B. Tunca/07.10.2002/13.35

İnsan kendini yenilemeli ki yeniliklere yenilmemeli

Tıpkı, bedenimizdeki hücrelerin yenilendikleri gibi

ADEMOĞLU/15.03.2002/15.15

Ne Kadınsız, Ne de Erkeksiz Bir Hayat Düşünülemez

Her İkisi de Birbirinin Mütemmim Cüzüdür Ayrılmaz

ADEMOĞLU/17,09,2001,10,30', 'Uçanların hava, kaçanların ise, karadır meskenleri Uçanların yüksekte, kaçanların alçaktadır yuvaları B. Tunca/11.11.2002-11.11 Dünya görüp,...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/guzel-sozler-armonisi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler Demeti-1-', 'guzel-sozler-demeti-1-bayram-tunca-7fof2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş, sabah yar gibi yaklaşır

Akşamları da el gibi uzaklaşır

Ay akşamları yar gibi yaklaşır

Sabahları da el gibi uzaklaşır

B. Tunca/05.09.2002-15.05

Öldüğümde cennete koysalar

Arzu/isteğin ne diye sorsalar

Seni, hurilere tercih ederdim

Zaten burda da öyle ederdim

B. Tunca/07.12.2002-07.12

Bir çift göze, bir çift göz gerek

Bir çift söze, bir çift söz gerek

O da “Seni Seviyorum” demek

Onu yürekten söylemek gerek

ADEMOĞLU13.06.2002-18.08

Kınamayınız ellerimin nasırını

Görseydiniz kalbimin yarasını

Acırdınız benim, garip halime

Anlatamadım halimi o zalime

B. Tunca/07.12.2002-07.12

Gelini gece kaldırırlar oyuna

İyiden iyiye bakarlar boyuna

Övgüler yağdırırlar 7 soyuna

Sonunda verirler elin oğluna

ADEMOĞLU25.08.2002-15.15

Yazdığım şiirlerim, beş yüzü aştı

Dayanılmaz özlemin sabrımı aştı

Gözlerimden akan sel değil yaştı

Şair Bayram ne yapacağına şaştı

ADEMOĞLU/20.10.2002-10.20

Bugünün işini etme yarına tehir

Bak felek hiç etmez mevti tehir

Ömür değin nedir ki sanki nehir

Zayi edersen, yarının olur zehir

ADEMOĞLU24.08.2002-14.24', 'Güneş, sabah yar gibi yaklaşır Akşamları da el gibi uzaklaşır Ay akşamları yar gibi yaklaşır Sabahları da el gibi uzaklaşır B. Tunca/05.09.2...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/guzel-sozler-demeti-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler Demeti-2-', 'guzel-sozler-demeti-2-bayram-tunca-mv88m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Estikçe rüzgar, yaprak yelleniyor

Ağacın gölgesindekiler eğleniyor

Leyla’mın ipek saçları yelleniyor

Sevdalı baş sağa sola sendeliyor

ADEMOĞLU/26.08.2002-16.46

Kamil olan anlar sözden/közden

Ben de sizi kamil biri sanmıştım

Ulvi hislerle yanınıza varmıştım

Meğer, sormalıymışım birinden

ADEMOĞLU25.08.2002-15.25

Nice şiirler yazdım, deste deste

Paylaştım dost/düşman herkesle

Bazen taşlanıp, bazen taçlandım

Çile çekmekten çabuk yaşlandım

B. Tunca/18.08.2002-18.18

Önce yaşadım, daha sonra yazdım

Yazarken anılarımı tekrar yaşadım

Ben de şaştım bunu nasıl başardım

Çünkü ne ilmim vardı ne de irfanım

B. Tunca/05.09.2002/10.55

Dağlarda/sahralarda geçti ömrüm

Dağlarda yankı buldu çile türküm

Ateşten bir gömlekti, aşk kürküm

Aşkından da buram buram tüttüm

B. Tunca/07.12.2002-07.12

Çekilmez çilem ve ahu zarım vardı

Gayri ihtiyari olarak, şairlik sardı

Atılan taşlar şu aciz başımı yardı

Bayramın bunda ne kusuru vardı 

ADEMOĞLU/ 20.06.2002-17.30

Bak arkadaş, ne yaş kaldı ne de baş

Bu sözüm, sana ibret olsun arkadaş

Zor günde dost bile el olur arkadaş

O vakit gözlerinden dinmez hiç yaş

20.09.2002-09.20', 'Estikçe rüzgar, yaprak yelleniyor Ağacın gölgesindekiler eğleniyor Leyla’mın ipek saçları yelleniyor Sevdalı baş sağa sola sendeliyor ADEMOĞ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/guzel-sozler-demeti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler Demeti-3-', 'guzel-sozler-demeti-3-bayram-tunca-wxy5f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu fani dünya iki duraklı bir yoldur

Birisinden binilir, diğerinden inilir

Şu yalan dünya iki kapılı bir handır

Birisinden girilir, diğerinden çıkılır

ADEMOĞLU/22.05.2002-15.35

Her gün kimileri gider, kimileri kalır

Kalanlar da sanki kendini baki sanır

Yarın kendisi de gider başkası kalır

Kıyamet kapunca, dünyada ne kalır

ADEMOĞLU/ 26.08.2002-16.26

Beni, dünün nesli hiç anlayamadılar

Bu günün nesli de çok az anlıyorlar

Belki yarının gençleri anlayacaklar

Ama, onlarda beni göremeyecekler

ADEMOĞLU/15.05.2002-08.35

Her gülün kokusu ve dokusu farklıdır

Her gülün kokusu, bülbülüne hoş gelir

Ama, bir başkasına çok nahoş gelebilir

Bu da gülün, yapısı ve dokusundandir

ADEMOĞLU/ 11.01.2002-15.30

Sönmez sevdanla, diyar diyar gezerim

Bulamazsam seni, bu candan bezerim

Yıllarca senin için aşk şiirleri yazarım

Aşkınla, geçit vermez dağları kazarım

ADEMOĞLU/27.08.2002-17.27

Ne sevgisiz aşk ne de aşksız sevgi olur

İkisi birlikte olursa, esas aşk o an olur

Sevgi, yan etkisi olmayan, en iyi ilâçtır

Hakiki aşk, sevginin damıtılmış şeklidir

B. Tunca/19.12.2002-19.12

Düştüğümü görenlerin kimisi of çektiler

Kimisi de görmemezlikten gelip geçtiler

Kimisi de sağır rolüne bürünüp geçtiler

Sonunda onlar da bu alemden göçtüler

ADEMOĞLU/28.06.2002-14.38', 'Şu fani dünya iki duraklı bir yoldur Birisinden binilir, diğerinden inilir Şu yalan dünya iki kapılı bir handır Birisinden girilir, diğerind...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/guzel-sozler-demeti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler Demeti-4-', 'guzel-sozler-demeti-4-bayram-tunca-skkbl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En Değerli İki Tablo

Hayatımda en değerli iki tablo gördüm, 

Bunların biri yeryüzü, diğeri gökyüzüm

Ne vakit, birinden diğerini seyretse gözüm

Büyülenip, Ressamını görmek ister gözüm

ADEMOĞLU/23.01.2001-08.45

Yaptığım kar topları elimde su gibi eridi

Gözlerine baktığım Leylâ mum gibi eridi

Onun yaşı, daha henüz on altı/on yediydi

Aşka davet ettiği her halinden de belliydi

B. Tunca/12.12.2002.12.12

Gördüğüm tüm güller harman yapılsaydı

Aralarından birini seçme şansım olsaydı

İçlerinden sadece seni seçerdim inan ki

Zaten öyle yapmadığımı söylemezsin ki

ADEMOĞLU/28.06.2002-14.38

Sen benim en güzel ilham kaynağımsım

Senden gelen esintilerle çağlar coşarım

Şiir yolunda çocuk gibi neşeyle koşarım

Sen varken durdurmak isteyeni şaşarım

ADEMOĞLU/28.02.2002-15.05

Dişimi öyle sıktım ki ağzımı bıçak açmaz

Dilimi öyle ısırdım ki bir daha konuşmaz

Gözlerimi öyle kapadım ki daha açılmaz

Artık bundan sonra ölümden kaçınılmaz

ADEMOĞLU/20.06.2002-07.17

Eğer ki çok çekmişse, kayınpeder adayın

Bil ki bunda bir değil, bin hikmet vardır

Elbette onu bu çileyi çektiren biri vardır

Dikkat et benzer biri de seni çektirmesin

ADEMOĞLU/07.03.2002-09.40

Renklerin büyüleyici armonisi gözlerinde

Kokuların harmanlanmış şekli bedeninde

Dört mevsimin meyve aroması dudağında

Al rengin albeniliği gül pembe yanağında

B. Tunca/07.12.2002-07.12', 'En Değerli İki Tablo Hayatımda en değerli iki tablo gördüm,  Bunların biri yeryüzü, diğeri gökyüzüm Ne vakit, birinden diğerini seyretse göz...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/guzel-sozler-demeti-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler Demeti-5-', 'guzel-sozler-demeti-5-bayram-tunca-fmm92', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırmızıyı sevmem, her yerde dur der beni

Sarıyı birazcık severim, çünkü uyarır beni

Yeşili gördüğümde alıkoyamaz kimse beni

Yâr için delerim dağları, yararım denizleri

B. Tunca/20.12.2002-17.12

Seninle paylaştıklarımı kimseyle paylaşamam

Ben sensiz dünyada, bir gün dahi yaşayamam

Yaşarsam da sanki, canlı cenaze gibi yaşarım

Seni benden koparacak olanın aklını şaşarım

B. Tunca/30.08.2002-14.30

Kemerimi sıka sıka kemerde delik kalmadı

Dişlerimi sıka sıka ağzımda dişim kalmadı

Daha henüz aybaşı cepte metelik kalmadı

Cefadan gözde fer, dizde derman kalmadı

B. Tunca/12.12.2002.12.12

Duydum, yokluğumda dün gelin olmuşsun

Daha dün benimken, bugün elin olmuşsun

Dün tomurcuk bir gülken bugün solmuşsun

Yine de, uçan turnalardan beni sormuşsun

B. Tunca/12.12.2002.12.12

Her gördüğünü, görüldüğü gibi mi sanırsın

Eğer öyle sanırsan, bil ki sen de yanılırsın

Onların kimisi veli, kimisi de deli gibidirler

Kimisi, patlayacak atom bombası gibidirler

ADEMOĞLU/16.04.2002-09.55

Mutluluk ve acının zirvesine aşkla ulaştım

Tasmalı bir köle gibi, ömür boyu dolaştım

Ah bilmem ki bu aşkı nereden de bulaştım

Kurtulmak için de bir ömür boyu uğraştım

ADEMOĞLU/12.06.2002-14.14

Selamı duymadıkça, benim için merak etme

Bil ki yaptıklarına rağmen daha hayattayım

Eğer selamı duyarsan, o an hiç merak etme

O zaman da, göndermek istediğin yerdeyim

ADEMOĞLU/16.04.2002-09.55', 'Kırmızıyı sevmem, her yerde dur der beni Sarıyı birazcık severim, çünkü uyarır beni Yeşili gördüğümde alıkoyamaz kimse beni Yâr için delerim...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/guzel-sozler-demeti-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-okan-sozener-g8kn9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zanman olur, bakarım gözlerim kapalı

Hayat denen meçhule

Zaman olur, öpmeye çalışırım

Rüyamdaki kelebeği

Yada, denerim geriye saymayı

Geçen zamanı, bir nefeste

Ama; bu beyhude çaba niye

Yoksan eğer aldığım nefeste

İçtiğim suda aksin yansımıyorsa, 

Sigaramın dumanı gibi

İçime çekemez seni, 

Nabzımın atıp atmadığından 

Kime ne?', 'Zanman olur, bakarım gözlerim kapalı Hayat denen meçhule Zaman olur, öpmeye çalışırım Rüyamdaki kelebeği Yada, denerim geriye saymayı Geçen ...', ARRAY['Türk Edebiyatı','Şiir','Okan Sözener']::text[], 8.5, '{"poet":"Okan Sözener","poet_slug":"okan-sozener","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zaman-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkediş', 'terkedis-okan-sozener-h50id', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey dünya, sıkıldım riyakar gülüşlerden, 

Tutulmayan sözlerden, 

Paylaşılmayan sevgilere artık oruçluyum.

Elveda sevgi, elveda iyi hayat bakışı

Ben bunlarsızda yaşarım.

Yaşamı, yaşamış olmak için yaşarken, 

Etrafımda kırılacaklar olursa

Şimdiden af ola, 

Zira bunu ben istemedim

Arkamdan ittiler......!', 'Ey dünya, sıkıldım riyakar gülüşlerden,  Tutulmayan sözlerden,  Paylaşılmayan sevgilere artık oruçluyum. Elveda sevgi, elveda iyi hayat bakı...', ARRAY['Türk Edebiyatı','Şiir','Okan Sözener']::text[], 8.5, '{"poet":"Okan Sözener","poet_slug":"okan-sozener","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/terkedis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Geceler', 'kara-geceler-okan-sozener-sjiwi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gene oldu akşam

Gene kaldım bir başıma

Seni getirmek istemiyorum aklıma 

Ama, geliyorsun.

Nasıl kaçacağım bu lanet oyundan 

Mızıtmakta para etmiyor 

En iyisi galiba çekip sineye, 

Senin ısdırabınla yaşamak 

Bak! Uzakta bir fener çaktı

Balıklar daldı uykuya

Bana kaldı gene kara geceler.......', 'Gene oldu akşam Gene kaldım bir başıma Seni getirmek istemiyorum aklıma  Ama, geliyorsun. Nasıl kaçacağım bu lanet oyundan  Mızıtmakta para ...', ARRAY['Türk Edebiyatı','Şiir','Okan Sözener']::text[], 8.5, '{"poet":"Okan Sözener","poet_slug":"okan-sozener","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kara-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Bayram Var', 'yuregimde-bayram-var-okan-sozener-5k3le', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece sabah dek kutlamam var, 

Onlarsız yapamadığım iki şeyle beraber

Birsi kadehim, diğeri sigaram

Kutlayacağız beraberce, dostlarım

Yüreğimin özgürlüğünü.

Şölenim var dostlarım şölenim

Aşk sandığım şeyi gömüp ezele, 

Taze bir yürekle bakıyorum geleceğe....

İşte bunu kutlamak için eğer, 

Yetmez ise gece

Sabahta devam edecek eğlence...!', 'Bu gece sabah dek kutlamam var,  Onlarsız yapamadığım iki şeyle beraber Birsi kadehim, diğeri sigaram Kutlayacağız beraberce, dostlarım Yüre...', ARRAY['Türk Edebiyatı','Şiir','Okan Sözener']::text[], 8.5, '{"poet":"Okan Sözener","poet_slug":"okan-sozener","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yuregimde-bayram-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin', 'hasretin-bayram-tunca-ubm2o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasretin vurdu sevdalı başıma

Hayalin dikiliyor, tam karışıma

İki de bir; çıkıp durma, karşıma

Bir gün seni kaçırırsam şaşırma

Âdemoğlu/03.07.2001-16.30', 'Hasretin vurdu sevdalı başıma Hayalin dikiliyor, tam karışıma İki de bir; çıkıp durma, karşıma Bir gün seni kaçırırsam şaşırma Âdemoğlu/03.0...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hasretin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-okan-sozener-pzxxj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siz kim siniz? 

Ben sizi tanıyor muyum? 

Hüzün yüklü dudaklarınızın 

Gülümseyişi neden? 

Neden bakıp bakıpta bana, 

Sonra çevirip gözlerinizi gök yüzüne

Bana gülümsüyor sunuz? 

Tanıştık mı evvelden? 

Hah..'' Şimdi hatırladım; 

Bir keresinde

Bir otomobil tamponunun üzerine oturmuş, 

Diğerbir keresinde

Beni boğan dumanın içinde

Gözlerinize rastladım, 

Ve son kez 

Bir bıçak parıltısında tanışmıştık.

Siz o sunuz

Ve ben sizi tanıyorum.

Nasılsınız Bay ÖLÜM..

Tanıştığımıza memnun oldum.', 'Siz kim siniz?  Ben sizi tanıyor muyum?  Hüzün yüklü dudaklarınızın  Gülümseyişi neden?  Neden bakıp bakıpta bana,  Sonra çevirip gözleriniz...', ARRAY['Türk Edebiyatı','Şiir','Okan Sözener']::text[], 8.5, '{"poet":"Okan Sözener","poet_slug":"okan-sozener","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/merhaba-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-erhan-guleryuz-73ot0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne geceler ne gündüzler gördüm

En vazgeçilmez yeminlerden döndüm

Görmedim senin gibi sevmedim hiçkimseyi

Yapayalnızım şimdi unuttum gülmeyi.........

Sen

Vaktinden çok sonra gelen

Sevdalı bir yağmur gibisin

Çisil çisil gözlerimden......

Sen 

Çıldırmış şairlerin

Titreyen mısralarında

Bahsettiği o perisin

Pencereler önünde çürürken

Senden kalan çiçekler

Hayalin gözlerimin önünde

Bize ağlıyorum.......

Pencereler önünde çürürken

O güzelim yıllarım

Hayalin gözlerimin önünde 

Bize ağlıyorum...

Güneş doğduğunda başka bir şehrin sabahında olacağım

Her insanın bir öyküsü vardır ya

Benimki de böyle işte.....

Bu sabah pencereden bak

Bu koca şehri sana bıraktım

Başka bir şehrin sabahından

Başka bir dilde 

Elveda....', 'Ne geceler ne gündüzler gördüm En vazgeçilmez yeminlerden döndüm Görmedim senin gibi sevmedim hiçkimseyi Yapayalnızım şimdi unuttum gülmeyi....', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-173-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiten Umutlarım', 'yiten-umutlarim-ali-kemal-c6fu9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessiz, sedasız, hergün

Bilinmez köşelere

Gömüyorum umutlarımı

Ne defin ruhsatı

Ne mezar taşı

Ve nede...

Birilerinin

Başsağlıgı dilegi, 

Göz yaşı', 'Sessiz, sedasız, hergün Bilinmez köşelere Gömüyorum umutlarımı Ne defin ruhsatı Ne mezar taşı Ve nede... Birilerinin Başsağlıgı dilegi,  Göz...', ARRAY['Türk Edebiyatı','Şiir','Ali Kemal']::text[], 8.5, '{"poet":"Ali Kemal","poet_slug":"ali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yiten-umutlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustosun Ortasında', 'agustosun-ortasinda-oguzhan-emre-unal-r89c0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaygısıydı ölüm, 

Yaşayabileceğim son günün.

Yarınım olacak mı? 

Bilemiyorum.

Veya yarın, 

Ben olacak mıyım? 

Kar yağacak mı yine

Nefes alışlarıma? 

Kirpiklerim buz tutacak mı, 

Ağustosun ortasında? 

Yalınayak yürüyorum, 

Karlar üzerinde.

Ve duygu çıkmazlarım

Çırılçıplak.

Yalınayak yürüyorum, 

Şehrin ara sokaklarında.

Kurtulamayacağım anne.

İnan kurtulamayacağım.

Unut beni anne.

Unut beni..

Unut...

Bir daha gelmeyeceğim 

Buralara anne.

Ve inan, 

Bir daha hiç sevmeyeceğim.

Çığ düşüyor yarınlarıma anne! 

Ağustosun ortasında.', 'Kaygısıydı ölüm,  Yaşayabileceğim son günün. Yarınım olacak mı?  Bilemiyorum. Veya yarın,  Ben olacak mıyım?  Kar yağacak mı yine Nefes alış...', ARRAY['Türk Edebiyatı','Şiir','Oğuzhan Emre Ünal']::text[], 8.5, '{"poet":"Oğuzhan Emre Ünal","poet_slug":"oguzhan-emre-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/agustosun-ortasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Buradayım', 'bak-buradayim-atabay-guveloglu-vd6he', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki çılgın aşık iken dünyada, 

Çekip gittin, bir anlamı var mıydı? 

Sanki iki kumru iken bir dalda, 

Uçup gittin, bir anlamı var mıydı? 

         Hadi koş gel, çık gel bak buradayım, 

         Tanıştığımız yer, Ankara''dayım.

         Hadi koş gel, çık gel bak buradayım, 

         Memleketim, canım Adana''mdayım.

Tam on yıldır, gül yüzünü görmedim, 

Sensiz mutlu olup, içten gülmedim.

Hala şaşıyorum, nasıl ölmedim, 

Ölümlerle, ayrılıklar bir miydi? 

           Hadi koş gel, çık gel bak buradayım, 

           Çam kokulu güzel toroslardayım.

           Hadi koş gel, çık gel bak buradayım, 

          Aşk yuvamız Mersin kıyısındayım.

Ben sensiz, sen bensiz olmaz bebeğim, 

Biliyorum, sen daha çok özledin.

Bazen içip, gözyaşını gizledin, 

Bazen dünya sanki sana dar mıydı? 

          Hadi koş gel, çık gel bak buradayım, 

          Hep arzu ettiğin İstanbul''dayım.

          Hadi koş gel, çık gel bak buradayım, 

          Dumanlı başımla, Marmara’dayım.

Sen gittikten sonra şaşırdım kaldım, 

Nazara inandım, fala inandım.

Ağlayarak rüyalardan uyandım, 

Aman tanrım, başkasına yar mıydı? 

         Hadi koş gel, çık gel bak buradayım, 

         Artvin''in, Rize''nin yaylasındayım.

         Hadi koş gel, çık gel bak buradayım, 

         Trabzon''da hamsi takasındayım.

Gururu atmanın zamanı geldi, 

Kini unutmanın zamanı geldi, 

El ele tutmanın zamanı geldi, 

Ayrılmak kolay da, gelmek zor muydu? 

           Hadi koş gel, çık gel bak buradayım, 

           Marmaris, Çeşme''nin sularındayım.

           Hadi koş gel, çık gel bak buradayım, 

           Akşamları kordonda bir bardayım.

Hadi koş gel, çık gel bak buradayım, 

Türkiye''mde, güzel vatanımdayım.

Haydi çık gel, koş gel bak buradayım, 

Nerede istersen, hep yanındayım! ..', 'İki çılgın aşık iken dünyada,  Çekip gittin, bir anlamı var mıydı?  Sanki iki kumru iken bir dalda,  Uçup gittin, bir anlamı var mıydı?     ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bak-buradayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci Oldum', 'dilenci-oldum-atabay-guveloglu-i2gwc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerde bir dilenci görsem acırdım, 

Sana avuç açtım, dilenci oldum! 

Şefkatine, gülüşüne muhtacım, 

Sana avuç açtım, dilenci oldum! 

Uykusuz gecede, horoz öterken, 

Yollarına çıktım ezanla erken.

Dünyanın nimeti gerek değilken, 

Sana avuç açtım, dilenci oldum! 

Kimden ne istesem, acır verirdi, 

Aradığım üç-beş kuruş değildi.

Aşık gönlüm bir tek seni istedi, 

Sana avuç açtım, dilenci oldum! 

Geçmedin bu yoldan, on yılım geçti, 

Hasretin birikti, boyumu aştı.

Gönlüm rüzgar ekti, fırtına biçti, 

Sana avuç açtım, dilenci oldum! 

Gözüm kimse görmez, sensiz amayım, 

Sakatım, gezemem olsa sarayım.

Ekmek değil, gelişine muhtacım, 

Sana avuç açtım, dilenci oldum! 

Elim açık, seni bulana kadar, 

Burda kalacağım, gelene kadar.

Kimseden dilenmem ölene kadar, 

Sana avuç açtım, dilenci oldum! 

Haklı imiş aşk yolunda ölenler, 

Üzülüyor, sevgimizi bilenler.

Gülüyorlar bu halimi görenler, 

Sana avuç açtım, dilenci oldum! 

Bunca acizliğe ben layik miyim? 

Böyle cimri miydin, ey sevdiceğim? 

Ölünceye kadar bekleyeceğim, 

Sana avuç açtım, dilenci oldum, 

Sana avuç açtım, dilenci oldum! ..', 'Nerde bir dilenci görsem acırdım,  Sana avuç açtım, dilenci oldum!  Şefkatine, gülüşüne muhtacım,  Sana avuç açtım, dilenci oldum!  Uykusuz ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dilenci-oldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılmadan Önce', 'ayrilmadan-once-atabay-guveloglu-4xjkt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dur, gitme ne olur karşımdan, 

Gözlerinde kaybolayım bu gece.

Sarhoş olayım delice.

Hiç konuşmayalım ayrılıktan, 

Ellerimden gitmeden ellerin.

Beraber söyleyelim şarkıları, 

Mehtabı seyrederken yanak yanağa.

Kapılalım o çılgın mutluluğa.

Unutalım maziyi, hüzün dolu anıları, 

Gözlerimden gitmeden gözlerin...', 'Dur, gitme ne olur karşımdan,  Gözlerinde kaybolayım bu gece. Sarhoş olayım delice. Hiç konuşmayalım ayrılıktan,  Ellerimden gitmeden elleri...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayrilmadan-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum Seni', 'ozluyorum-seni-atabay-guveloglu-5n9h0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar ol toroslardan kopan, 

Üfle özlemin yaktığı bağrıma.

Bu ruhtu sana yıllarca tapan, 

Bu kalpti bakılmayan feryadına.

Bir bulut ol, yumak yumak üstümde, 

Enginlerde, gölgende kalayım tek...

Seni, hep sen gibi bilirim gönlümde, 

Güneşte göreyim gülüşünü hevenk hevenk.

Bir kaynak ol kaderimin aksine berrak, 

Aşkımın, sevdamın misaline coşkun.

Damlan haramdır ele, içime ak, 

Sen yaktın, seninle soğusun.

Bir yar ol bana, yıllar öncesi gibi, 

Ser saçlarını yüzüme, mehtap kıskanmasın.

Eriyorum, çölde su gibi özlüyorum seni, 

İnsaf; bir çift göz için, bir ömür yanmasın.', 'Bir rüzgar ol toroslardan kopan,  Üfle özlemin yaktığı bağrıma. Bu ruhtu sana yıllarca tapan,  Bu kalpti bakılmayan feryadına. Bir bulut ol,...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozluyorum-seni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu Yok', 'suclu-yok-atabay-guveloglu-c9gdy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İsyan ediyorum bazı geceler; 

''Kahrolsun gözyaşı ve kadehler de! ''

Biliyorum, çare değil içkiler, 

Geceler de suçsuz, o kadehler de...

Seni benliğimden çıkartmak için, 

Teselli aradım çok güzellerde.

Sabahlara kadar içmeler niçin? 

Geceler de suçsuz, o kadehler de...

Her akşam oluşta yanıp, özleyip, 

Takılıp kalmışım hep bir yerlerde.

Unutmak ne mümkün kafa demleyip, 

Geceler de suçsuz, o kadehler de...

Kimseye kahretmek hakkımız değil, 

Yazan yazmış onu, çook öncelerde...

Bir kabus olmuşsa sensiz bu şehir, 

Geceler de suçsuz, o kadehler de...', 'İsyan ediyorum bazı geceler;  ''Kahrolsun gözyaşı ve kadehler de! '' Biliyorum, çare değil içkiler,  Geceler de suçsuz, o kadehler de... Seni ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/suclu-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değiştir', 'degistir-atabay-guveloglu-xlujs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Takılıp kalma dostum, 

Takılıp kalma zorlandığında! 

Takma kafana, bunaldığında, 

Değiştir, değişim gerek

Gerektiğinde...

Anlıyorsun değil mi? 

Düzeni değiştiremiyorsan, 

Düzen değişse bile, 

Düzülen benim, diyorsan

Takma kafana! 

Gittiğinde sandık başına

Düşün, sonra ver oyunu.

Düşünceni değiştir, 

Boz bu oyunu! 

Anlıyorsun değil mi? 

Şehirini beğenmiyorsan? 

Takma kafana! 

Sokulup kalma istemiyorsan, 

Sıkıntını bitir.

Git başka tarafa, 

O şehiri değiştir! 

Anlıyorsun değil mi? 

Mahalleni mi beğenmiyorsun? 

Sakın oturma orada! 

Hiç durma, takma, 

Yükle, taşın başka diyara.

Değiştir mahalleni, evini, 

Kafana göre bulursun, ara! 

Anlıyorsun değil mi? 

Sevgilin mi sıktı? 

Karın mı bıktırdı? 

Sakın takma! 

Dert etme Allah aşkına.

Ayrıl gitsin! 

Umutla bak yarına, 

Geçmişi at bir tarafa.

Anlıyorsun değil mi? 

Bunalım mı takılıyorsun? 

Hayattan mı yakınıyorsun? 

Yoksa, yaşam mı angarya.

Ben kimim mi diyorsun? 

Kafanı mı beğenmiyorsun

O zaman durma, 

Git meyhaneye her akşam, 

Kafanı değiştir, 

Anlıyorsun değil mi?', 'Takılıp kalma dostum,  Takılıp kalma zorlandığında!  Takma kafana, bunaldığında,  Değiştir, değişim gerek Gerektiğinde... Anlıyorsun değil m...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/degistir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenimi Anarım', 'ogretmenimi-anarim-atabay-guveloglu-e6f09', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk okuldan, ilk sınıftan

Kara önlük ve tahtadan.

Her şehirden, her okuldan

Öğretmenimi anarım.

Benim gerçek annem olan, 

Babam olan, yuvam olan.

Neş''em olan, tasam olan, 

Öğretmenimi anarım.

Sıra yapıp alkış tutan, 

Bizi işleyip donatan.

Bilgi örüp, anıt yapan, 

Öğretmenimi anarım.

Işık saçan, kararmayan, 

Yanılmayan ve şaşmayan.

Bıkmayan ve usanmayan, 

Öğretmenimi anarım.

Kimdi bedene can katan, 

Bunca varlığı yaratan? 

Allah''ı, kitabı tanıtan, 

Öğretmenimi anarım.

İstiklal marşı öğreten, 

''Türküm, doğruyum''söyleten.

Bakışıyla söz dinleten

Öğretmenimi anarım.

 Bilimin her dalıydı O, 

 Uygarlığın yoluydu O.

 Bilgi, kültür doluydu O, 

 Öğretmenimi anarım.

Atatürk''ü örnek alsam, 

İlkelerini savunsam.

Bir gün ben öğretmen olsam, 

Öğretmenimi anarım...', 'İlk okuldan, ilk sınıftan Kara önlük ve tahtadan. Her şehirden, her okuldan Öğretmenimi anarım. Benim gerçek annem olan,  Babam olan, yuvam ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ogretmenimi-anarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elde Var Sıfır', 'elde-var-sifir-atabay-guveloglu-dnffi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Okullu olduk! 

Kalktık sabahları gün doğmadan

Uykumuzun en tatlı yerinde.

Küçücük yaşımız, 

Kocaman umutlarımızla

Dirsekler, önlükler, pabuçlar

Çürüttük nice uzun seneler boyunca.

Mühendisler, doktorlar, 

Pilotlar olacaktık.

Uçacaktık, açacaktık, yapacaktık.

Hasılı, adam gibi, adam olacaktık.

Babamız bizimle, biz büyüklerimizle

Gurur duyacaktık.

Yapacağını yapan da, 

Uçup kaybolan da, 

O güzelim yıllarımız oldu.

Ne umduk, ne bulduk, 

Diplomalı işsizler ordusunun

Kıdemli birer askeri olduk.

Sonuç; 

Sıfıra sıfır, 

Elde var sıfır! 

Devrimci olduk! 

Eşitliği sağladık şehrin varoşlarında.

Herkesin yoksulluğu, cahilliği birdi orada.

Baksanıza ne  sonuç aldık! 

Onlar fakirliklerinden memnundu, 

Nutuklar atarak birbirimize

Her akşam sarıldık kadehlerimize.

Düzeni değiştirdik rakı sofralarında.

Devrim nikahı yaptık sevgilimize, 

Lenin''i okuduk, Marks''ı savunduk

Liberallik yakıştı bize.

Cezaevlerinde kaldı

Ömrümüzün en verimli yılları, 

Bedenimiz yıprandı.

Düzenden yakınanların oyları

Sonunda sağa kaydı.

Bunca söz, bunca çaba askıda kaldı.

Sonuç; 

Sıfıra sıfır, 

Elde var sıfır! 

Aşık olduk! 

Pembe hayeller düşledik.

Pembe pancurlu bir ev yerine

Umut verebildik sevdiğimize.

Ateşimiz azalarak seviştik

Birşeyler koptu zamanla

Yabancı olduk birbirimize.

Yoksulluk sınavında tekledik, 

Birbirimizi terkettik.

Hızlı başladık, 

Çabuk bitirdik, kıymet bilemedik.

Elbette, böyle olsun istemezdik, 

Ama bu sonu başardık.

Sonuç; 

Sıfıra sıfır, 

Elde var sıfır, 

Sonuç; 

Elde var, kocaman bir sıfır!', 'Okullu olduk!  Kalktık sabahları gün doğmadan Uykumuzun en tatlı yerinde. Küçücük yaşımız,  Kocaman umutlarımızla Dirsekler, önlükler, pabuç...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/elde-var-sifir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk Kim''mi Çocuğum', 'ataturk-kim-mi-cocugum-atabay-guveloglu-olxvj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Parçalamışlarken ülkemizi, 

Çıkartamıyorken sesimizi.

Takip ettik bir önderimizi, 

O, en büyük Türk.O, Atatürk! ..

Hepimiz askerdik, yön verdi bize, 

Nice devletleri getirdik dize.

İşgalci düşmanı döktük denize, 

O, en büyük Türk.O, Atatürk! ..

Böylece kuruldu genç Cumhuriyet, 

Bundan sonra siz gençlere emanet.

Haydi, Anıt Kabir''inde bir teşekkür et, 

O, en büyük Türk.O Atatürk! ..', 'Parçalamışlarken ülkemizi,  Çıkartamıyorken sesimizi. Takip ettik bir önderimizi,  O, en büyük Türk.O, Atatürk! .. Hepimiz askerdik, yön ver...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ataturk-kim-mi-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet Yetmiş Beşinci Yılında', 'cumhuriyet-yetmis-besinci-yilinda-atabay-guveloglu-4jdp7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kahraman milletim, yiğit askerim, 

Teşekkürler sana, yetmiş beş kere! 

Sorumlu, cefakar, çalışkan halkım, 

Teşekkürler sana, yetmiş beş kere, 

Teşekkürler sana, binlerce kere! 

Özgür bir devletiz, kökümüz Göktürk, 

Sömürge olmayı kabul etmez Türk! 

Cesur önderimiz, yüce Atatürk, 

Teşekkürler sana, yetmiş beş kere, 

Teşekkürler sana, binlerce kere! 

Cumhuriyetimi yaşatacağım, 

Uzanan elleri kopartacağım! 

Türklüğün sembolü, şanlı bayrağım, 

Teşekkürler sana, yetmiş beş kere, 

Teşekkürler sana, binlerce kere! 

Çağ dışı dönemi attık geriye, 

Yürü ileriye, hep ileriye! 

Bilim yolundaki çağdaş Türkiye, 

Teşekkürler sana, yetmiş beş kere, 

Teşekkürler sana, binlerce kere! ..', 'Kahraman milletim, yiğit askerim,  Teşekkürler sana, yetmiş beş kere!  Sorumlu, cefakar, çalışkan halkım,  Teşekkürler sana, yetmiş beş kere...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cumhuriyet-yetmis-besinci-yilinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Türk''tür', 'herkes-turk-tur-atabay-guveloglu-94sbc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Milletimiz bir bütündür, 

Türk''üm diyen herkes Türk''tür! 

Farklı olsa, din, dil, kültür, 

Türk''üm diyen herkes Türk''tür! 

Yasa karşısında biriz, 

İnsan olarak severiz.

Irkçılığa yok yerimiz, 

Türk''üm diyen herkes Türk''tür.

Kenetlenmiş tek bir eliz, 

Doğu, batı, tek milletiz.

Kucak açmış bir devletiz, 

Türk''üm diyen herkes Türk''tür! 

Okulumuzda okusun,   

Vergi verip, asker olsun.

Bayrağıma saygı duysun, 

Türk''üm diyen herkes Türk''tür! 

İnsan hakları öndedir, 

Kozmopolit bir ülkedir.

Kürttür, Lazdır, bilmem nedir, 

Türk''üm diyen herkes Türk''tür! 

Alevisi, sünnisiyle, 

Kitabın dört türlüsüyle.

Kardeşiz her birisiyle, 

Türküm diyen herkes Türk''tür.

Doğu, batı bir biliriz, 

Saygı duyar, gülümseriz.

Her ile hizmet veririz, 

Türk''üm diyen herkes Türk''tür! 

Nankör olup, hain çıkma, 

Bu sofraya bıçak sokma! 

Devletine güven, korkma, 

Türk''üm diyen herkes Türk''tür! 

Atabay’dan dinle öğüt, 

Atatürk''ün izinden git! 

Alnı açık, gönlü yiğit, 

Türk''üm diyen herkes Türk''tür!', 'Milletimiz bir bütündür,  Türk''üm diyen herkes Türk''tür!  Farklı olsa, din, dil, kültür,  Türk''üm diyen herkes Türk''tür!  Yasa karşısında bi...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/herkes-turk-tur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arenada', 'arenada-atabay-guveloglu-qkyus', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bağımsızlık savaşçısı idim, 

Orta çağda.

Halkımı ayaklandırıyordum

Açlığa, zulüme karşı Roma''da.

Krallıklar sarsılıyordu adımlarımızla, 

Titriyorlardı saraylarında.

Gafil avladılar bir gün, kralın askerleri

İşkenceler gördüm zindanlarında.

Önce vücudumu dağladılar

Kızıllaşmış demir çubuklarla, 

Sonra kollarımı bağladılar

Zincirleşmiş ağır halkalarla.

İşte, orada karşılaştım ilk kez

İnsan kılığına girmiş şeytanlarla, 

Vahşetin ve zulümün sembolü arenada! 

Kral ve asilzadeler yanında, 

On binlerce izleyici vardı etrafımda.

Çığlıklar atıyorlardı sadistçe

''Hurra, hurra''diye! 

İçlerinde, yoktu halkımdan hiç kimse, 

Bana faydaları olamazdı içeride.

Önce, eğilmemi emrettiler kralın önünde, 

Duymadım ve uymadım! 

Sonra, iki dev adamın kırbacı şakladı

Mermerleşmiş sert bacaklarımda, 

Kemikleşmiş gövdemde, kollarımda! 

Nara atıyor, adeta uluyorlardı, 

İnsan değilmişim gibi vuruyorlardı...

Saatlerce dövmekten usandılar, 

Yorulup, bittiğimi sandılar.

Ardından, duyulunca boru sesleri

Açılıyor sandım kaplan kafesleri! 

Ama kaplanlar değildi bu gelen, 

Gördüğümde, iliklerim dondu, 

Bu, ünlü gladyatör Şimon''du! 

İki metrelik boyu, dev cüssesi ile, 

Adeta, zırhlara bürünmüş bir dinazordu! 

Bir gardiyan yanıma koştu, 

Sol bileğimdeki kelepçeyi açtı.

Sağ elimde zincir, sol elim boştu! 

Yürüyen çelik yığını, korkunç bir kılıç

Sallanarak geliyordu, zevkten sarhoştu.

Alkışlar ve sesler arasında, 

Çevremde dolaşıyordu.

Bir an önce kellemi, 

Krala sunmak istiyordu.

Hiç beklemediği bir anda

Dalarak attım kendimi bacaklarına.

Sarsıldı koca dev, sonra düştü yanına.

Sol omuzumu yarıp geçen kılıcına

Sağ kolumdaki zinciri dolayıp

Tüm ağırlığımla aniden boynuna dayayıp

Yükleniverdim üzerine! 

Gözleri dışarı fırlarken

Kanlar doluyordu ciğerlerine.

Ölümün sessizliği sararken arenayı, 

İsyan eden halkım, çoktan sarmıştı sarayı.

Gerçekleşiyordu bağımsızlık düşü, 

Artık bitmişti, 

Hem Şimon''un, hem kralın işi! ..

               * * * * *

Özgür bir boğa idim kırlarda

Yeni çağda, 

Tezatlar ülkesi İspanya''da.

Hem müziklerin en güzelini çalıyor, 

Dansların en güzelini yapıyorlar, 

Hem de masum kanı akıtıyorlardı burada.

Lanet ediyordum, bir boğa olarak, 

İspanya''da doğduğuma.

Önce özgürlüğümü aldılar elimden, 

Yakalayıp, doğup büyüdüğüm yerlerden, 

Bir görkemli ahıra hapsettiler.

Döktüler önüme her çeşit yemlerden, 

Hem semirttiler, hem eğittiler.

Bakıcılarımı dost, 

Matadorları düşman bellettiler.

İspanya''nın bir güneşli gününde, 

On binlerce seyirci önünde, 

Alıp çıkardılar muhteşem arenaya.

Vahşetin ve kalleşliğin sergilendiği sahaya! 

Süslü püslü elbiseler içinde, 

Gücüm ve heybetimle alay eder biçimde

Birileri dönüyordu etrafımda.

Yaklaştırmıyordum yanıma, 

Çünkü özgürlük vardı kanımda! 

Sonra, korkunç bir alkış çınladı kulaklarımda.

Bu, izleyici rekorları kıran, 

Her hafta bir boğanın kanını akıtan

Mavi gözlerini para hırsı bürümüş, 

Boğazın kıyısında büyümüş, 

Her boğanın korkusu olan bir matadordu, 

Ve tüm haşmetiyle arenaya giriyordu.

Anladım ki, tam zevklerine göre

Bir kavga olacaktı aramızda! 

Vahşetin ve masumiyetin iki temsilcisi, 

İki düşman, ya da iki sevgili

Gibi kucaklaşacaktık arenamızda! 

Önce boydan boya dolaşarak, 

Göz ucu ile beni kollayarak, 

Arenadaki tüm izleyicileri selamladı, 

Sonra da yanıma yaklaşarak 

Alay edercesine, bir süre benimle oynadı.

Kırmızıdan nefret ettiğimi sanarak, 

Pelerinini dalgalandırarak, 

Etrafımda salladı, boynuma doladı.

Sol elini çıkartıp koynundan, 

Gözlerime bakarak yanıma dolandı! 

Birden, kırmızı pelerininin arkasından

Kürek başlarıma bir şeyler saplandı.

Yarısı kızıla boyanıp, sallanan, 

Sanki steplerden gelmiş, püsküllü iki yılandı.

Kanım indi ayaklarıma, 

Dizlerim titredi, canım yandı.

Anladım ki, bu adam oyun oynamıyordu, 

Kurtlardan daha beter bir düşmandı! 

Ben, bu acının şaşkınlığını yaşıyorken, 

Vahşetin zevkine, kanım akıyorken, 

Usta matador, bir kahraman gibi, 

Dakikalarca alkışlandı! 

Madrit''ten, Meksiko''ya kadar

''Oley, oley''sesleri yankılandı! 

''Ben, erkekliğin ve gücün 

Değişmez sembolüyüm''dedim, 

Can almayı meslek yapmış matadorun, 

Sarhoş kitleyi selamlamasını bekledim. 

Reverans yaparak eğildiği anda, 

Tüm gücümü topladım dizlerimde ve boynuzlarımda.

Yaydan çıkmış bir ok gibi fırlayıp, 

Başımı bacaklarının arasına sokup, 

On metre uzağa fırlattığımda

Matador bu alemden kopup, 

Eşşekler cennetine vardığında

Tanık oldum, toparlanıp, 

Tüm ağrılarımın kaybolduğuna...

******************

Bir bilim savaşçısı idim 

Yakın çağda, 

Yirminci yüzyılın sonunda.

Vebanın, cüzzamın dışında, 

Çeşit çeşit adlar altında

Çaresiz hastalıklar buluyordu

İnsanları, ezrailin kanatlarında.

Dur demeliydim doğanın gücü ile, 

Şifa dağıtmalıydım tüm hastalara.

On yıl çok çalışmış, yorulmuştum ama, 

Kazanmıştım, galiptim, 

Yenmiştim tüm zorlukları sonunda.

İnsan sağlığında

Bir reform yapmıştım ama, 

Tam zaferimi ilan ettiğim anda, 

Ve bu yorgunlukta! 

Bulmuştum kendimi, yine arenada! 

Bu defa, üzerime gönderilen, 

Reyting rekorları ile izlenilen, 

Kökü Kırcaali''den gelmiş, 

İyi beslenip, semirtilmiş

İri ve azgın bir köpekti, 

Kendi sınıfında tekti! 

Daha önce de pek çok masuma

Korku salmış, katil bir naletti.

Her Arena faciasının sonunda

Uğur olmuştu, altın olmuştu, 

Sadık kaldığı patronlarına...

Hemen saldırdı arenanın bu azgın köpeği

Ama işi zordu benimle! 

''Yeter'' dedim, ''havlama, sus! ''

Olanca gücümle sol bir yumruk vurdum.

Zira ben, Spartakus''tum, Benhur''dum, 

Aristo, Galillo, İbni-Sina ve Precelsus...

Bu, bağımsızlık adına, 

Bu, özgürlük adına, 

Bu, bilim ve insanlık adına, 

Bu, demokrasi ve hukuk adına dedim, 

Vurdum, adalet yumruğunu tam alnına! 

Boğazını iyice sıktım, ama öldürmedim

Köpek de olsa, onu yaratanın aşkına...

Sadece havlaması çınlamıştı

Benim ve izleyicilerin kulaklarında.

Urbama da biraz çamur atmıştı, 

Ama o izler de kalmadı zamanla.

Arenanın köpeği, sahte bir yiğitti! 

Dürüst bir düşman yoktu karşımda, 

Alt tarafı, azgın bir itti! ..

Bu kavganın sonunda

Ben yine dimdik ayaktayım ama, 

Onun itliği bitti! ..', 'Bir bağımsızlık savaşçısı idim,  Orta çağda. Halkımı ayaklandırıyordum Açlığa, zulüme karşı Roma''da. Krallıklar sarsılıyordu adımlarımızla, ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":186,"source_url":"https://www.antoloji.com/arenada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-guven-turan-sevc0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üç duvar arasında

Avluda

Asmanın altında

Oturmuş denize bakıyor

Düşünüyor: 

Avluda asmanın altında

Oturup düşünüyor

Denize bakarak

Üç yanı duvar: 

Asmanın altında: 

Avluda: 

Deniz karşısında

Düşünüyor:', 'Üç duvar arasında Avluda Asmanın altında Oturmuş denize bakıyor Düşünüyor:  Avluda asmanın altında Oturup düşünüyor Denize bakarak Üç yanı d...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayna-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakış', 'bakis-guven-turan-685oj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gelmiş bir geçmiş

Uykumun arasında

Fırtına

Pencerenin önünde ıtırlar ezik

Yerde dalcıklar

Sapsarı dibi cevizin

İskele yok yerinde

Gene de

İsketeler bitleniyor tozun içinde

Toprak çatlak

Kavruk dağlar bulutsuz göğe', 'Bir gelmiş bir geçmiş Uykumun arasında Fırtına Pencerenin önünde ıtırlar ezik Yerde dalcıklar Sapsarı dibi cevizin İskele yok yerinde Gene d...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bakis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim', 'sevgim-gulay-yildiz-t20wu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanın en gerisinde bir yerlerde 

Sadece canımı acıtan değil gözyaşı

Beynimi uyuşturan o koku, 

Senden kopup gelen.

O dört meleği bile şaşırtan sevda; 

Yani gözlerin...

Bilmediğim, görmediğim, duymadığım, sadece hissettiğim; 

Yani sevgim...', 'Zamanın en gerisinde bir yerlerde  Sadece canımı acıtan değil gözyaşı Beynimi uyuşturan o koku,  Senden kopup gelen. O dört meleği bile şaşı...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diriliş', 'dirilis-gulay-yildiz-fs4mk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin, ölümün yankısı olan sesin

Benim, aksini karşılayan tenim...

Uzak köşeleri ıskalarcasına yuvarlanan

3 hatta 4 farklı bilardo topu...

Çarptıkça hızlanıyor sesin, 

Çarptıkça hızlanıyor kalbim...

Sadece son durağına sesinin

Yankı çiğleşiyor, sesim üşüyor...

Her noktanın noktası olup

Her virgülün son çizgisine takılmak...

Bak; 

Anlattım seni ve hatta beni, 

Engelleri...

Ve içinde bulunduğun, bulunduğum çarkı

Yalanlı, korkulu, aldatmacalı çarkı.

Gözlerin belki sessiz ve masum

Ya yüreğin...

Bana bakan herşey benden yana

Ya başkasına bakanlar? ...

Ölüm sessizlikse, kalbim can çekişiyor.

Ölüm yeni bir dirilişse, 

Az kaldı kalbim diriliyor....', 'Senin, ölümün yankısı olan sesin Benim, aksini karşılayan tenim... Uzak köşeleri ıskalarcasına yuvarlanan 3 hatta 4 farklı bilardo topu... Ç...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dirilis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zebani', 'zebani-gulay-yildiz-91q6i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yorgun düşmüş iki kara zebani

Uykumun derinliklerinden geri dönüyor

Evet! O senli gecenin sonu...

Onsuzluk ve onluluk çizgisinin çizildiği

Nefesin ısınıp sonra dondurulduğu uyku...

Yağmur; kaçamağı seven su damlaları...

Yüzüne çarpan sonra boynundan süzülen

Kaçamak dolu damlalar...

Hava da asılı kalmış bin bir düşüncenin

Zebanilerin iz düşümünde, yüzüne vurduğu damlalar...

Elini götürüp te silebileceğin, akışını engelleyebileceğin

Ama engellemediğin, engelleyemediğin damlalar...

En asisinin bile beceremeyeceği asiliği, 

Bir daha geri dönmeksizin yaşayan damlalar...

Onlar benim kurtarıcım...

Onlar benim avuntum ve inan bana

Hepsi, birer birer, her defasında da ayrı ayrı sonum...

Zebaniler eşliğinde, belki de onların içinde

Özgürlüğe koşan ama ömür boyu kafeste kalacak olan

Karmakarışık bir yağmurun damlaları, 

Düşüp düşüp kalkıp gene düşen, 

Düşmek için kalkan, yükselen 

Belki de

Yükselmek için düşen damlalar

Onlar benim senim, 

Onlar benim senden kalan, sana kalan

En güzel düşlerim...

Her şeyin başlangıcı olan sonda sunacağım

                                              En karamsar izlerim...', 'Yorgun düşmüş iki kara zebani Uykumun derinliklerinden geri dönüyor Evet! O senli gecenin sonu... Onsuzluk ve onluluk çizgisinin çizildiği N...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/zebani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-gulay-yildiz-hsqdn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin birer hayalin yansıması artık

Hayal bile değil…

Ellerin sadece birer resim…

Nefesinden çok rüzgarın beni delirten

Gülümsemenden çok çakmak çakmak gözlerin

Ilık, sevecen bir sevgi sözcüğü beklenen! 

Arsız küfürlerin ardından sana kalan kalıntılar değil…

Senden bana kalanlar nefes oluyor bana

Onlarla dolaşıyor damarlarımda kanım 

Adını bile bilmiyorsun bende 

Bilmemezlik değil bu; aklına bile gelmemezlik

Sen! 

Sevginin her zerresini yaşamışlığında bitiriyorsun beni

Bense daha önce yaşadıklarıma lanetlerle

Gözyaşlarımda  yaşıyorum seni…', 'Gözlerin birer hayalin yansıması artık Hayal bile değil… Ellerin sadece birer resim… Nefesinden çok rüzgarın beni delirten Gülümsemenden çok...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-174-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım'' a', 'askim-a-gulay-yildiz-93ta9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen adını bir türlü anamadığım gizli gözyaşım

Karanlıkları içimden taşırıp atan gizli aşkımsın...

Değil ki kuru toprakla buluşsa yağmur, 

İnan ki sevinemez gözlerim

Değdikleri anda ki kadar sana 

Ve yüzbin yıldız eşlik etse şarkıma, 

Yüzbin uçurtma uçursa yüreğim

Sevgin benim olduysa

Yansın umrumda değil yüreğim....', 'Sen adını bir türlü anamadığım gizli gözyaşım Karanlıkları içimden taşırıp atan gizli aşkımsın... Değil ki kuru toprakla buluşsa yağmur,  İn...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/askim-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bittin', 'bittin-gulay-yildiz-i4yw0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüksek, kalın duvarlar ördüm etrafıma

Dışarı çıkmak istemiyorum

İzin vermez bekçilerim bir daha içeri de girmene

Sildim ayak izlerimi, girişi bulamazsın bile

Anla artık seni istemez yürek

Kabullen, bak! Isıtamıyorsun ellerimi

Bitmiş o sağanak duygular içimde

Yüreğimin çırpınışları artık senin için değil

Başka gözler için yanıyor gözlerim

Başka teni düşler ellerim

Hayaldin, istemdin belki ama artık BİTTİN...', 'Yüksek, kalın duvarlar ördüm etrafıma Dışarı çıkmak istemiyorum İzin vermez bekçilerim bir daha içeri de girmene Sildim ayak izlerimi, giriş...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bittin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-gulay-yildiz-ldwiu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kararttı gece ışıklarımı

Gözlerim ağlamaklı kapanır artık

Seni düşler, seni özler seni diler sesim

Her solukta adını sayıklar iki defa

İlk önce hava olup dolarsın ciğerlerime

Sonra zehir olup karışırsın odama

Kalbim seni atar iki defa

Önce adını söyler, sonra sevdiğim der

Ve beynim, o yüzlerce kere seni işler bana

Dokunduğum her yer birden sen olur

Baktığım her yer gözlerin

Yastığım dizlerin oluverir

Cebim ellerin

Her yer sen oluverir, her yer sen kokar

Anlarım ki özlem seni kazır içime

Her defasında bir daha asla gitmemecesine', 'Kararttı gece ışıklarımı Gözlerim ağlamaklı kapanır artık Seni düşler, seni özler seni diler sesim Her solukta adını sayıklar iki defa İlk ö...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gibi', 'sen-gibi-gulay-yildiz-q9hek', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gece öylesine çarptı gözüme

Gökyüzünün en parlak yıldızıydı

Tıpkı sen gibi...

O derin siyahın en deli ışığıydı

Aynı sen gibi...

Binlercesinin içinden göze çarpıyordu

Senin gibi erişilmez, senin gibi mağrur...

Elimi uzatsam yakalarım belki

Belki çoktan içime işledi

Aynen senin gibi...', 'Bir gece öylesine çarptı gözüme Gökyüzünün en parlak yıldızıydı Tıpkı sen gibi... O derin siyahın en deli ışığıydı Aynı sen gibi... Binlerce...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-gibi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tılsım ve Trajedi', 'tilsim-ve-trajedi-enis-batur-e3ofx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ucunda Trajedi vardı bu kalemin, 

Tılsım öteki ucunda. Uyuduğumda kim 

uyanıyordu içimde, hangimiz sürdürüyordu

gündüşlerini, hangi yüzüm kanıyordu, 

neden bir ucu seçip sivriltiyordum da 

köreliyordu o an öteki uçtaki güdülerim, 

kalemin bir ucunda Trajedi, Tılsım 

benden yanaydı: Nereye çevirirsem çevireyim 

öfke doğuruyordu hüzün doğuruyordu öfke: 

İki ucunda kalemin

ebabil kuşları taş topluyordu.

Gelecek ardımda kalmış bir melek: 

Defterim dolmuş, bir tek hece taşım için

karasız bir beyit oyalıyor şimdi beni.

Köprüler, dehlizler ve tünellerden geçtim, 

oğullarım dağınık bir başkaldırı kavmi, 

kızlarım sonsuza ayarlı birer arayış tohumu, 

bu kadını sevmiştim: Koptu gitti dünyamdan, 

sönmüş fer. Bu kadını da: doyamadığım.

Bir de onu: Yanıbaşımda fırtına gibi yaşayan, 

tül gibi ölen. Yalnızım artık, nasıl yalnız

yaşamışsam gamlı bir şahinken.

Defterlerim dolu:
..........
..........', 'Bir ucunda Trajedi vardı bu kalemin,  Tılsım öteki ucunda. Uyuduğumda kim  uyanıyordu içimde, hangimiz sürdürüyordu gündüşlerini, hangi yüzü...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tilsim-ve-trajedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğim', 'gidecegim-harun-kesik-g80m7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gideceğim, 

Nerde bu çocuk diyecek

Yurdumu bilmeyeceksiniz

Belki kilyos açıklarında 

Ufak bir ada

Tahtadan bir kamara

Belki de adapazarında 

Yatacağım yer 

Ufak bir baraka

Gideceğim 

Öldü mü acaba diyecek

Çok merak edecek

Mezarımı bilmeyeceksiniz

Belki zincirlikuyu son sapak

Numara 42

Belki de Cumhuriyet Lisesi

Ellerin tuttuğum yerin

Bir adım ötesi

Numara 1742', 'Gideceğim,  Nerde bu çocuk diyecek Yurdumu bilmeyeceksiniz Belki kilyos açıklarında  Ufak bir ada Tahtadan bir kamara Belki de adapazarında ...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gidecegim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Laf Lafı Açar+', 'laf-lafi-acar-bayram-tunca-mfljs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Atalarımız hani demişler ya “laf lafı açar”

Tıpkı, o günkü ağzımdan kaçan o söz gibi

Bazen insanoğlunun başına ne işler açar

Tıpkı, o şiir yazan veya okuyanlarınki gibi

14.03.2002-15:15

Aşm Ateşten Gömlek', 'Atalarımız hani demişler ya “laf lafı açar” Tıpkı, o günkü ağzımdan kaçan o söz gibi Bazen insanoğlunun başına ne işler açar Tıpkı, o şiir y...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/laf-lafi-acar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-ceyhun-yilmaz-q1dbu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duramıyorum, ağlamaktan utanıyorum, 

utandıkça ağlıyorum! 

Belki bir tek gözyaşının çözebileceği bir dert değildir bu

Ağlamamak lazım öyleyse

Sevindirmemek lazım kederleri

ya da böyle avutmamak lazım geceleri

Yalnızlığımı, yapayalnızlığımı, yalpalayan yalnızlığımı..

Yanlızlığımı çekmek ağır geliyor omuzlarıma

..ve arka arkaya birbiriyle tanışan sigaralar

Her nefes gece...her gece içimde...

Gündüz ellerimde

Ağla yüreğim ağla

Ne kadar dert varsa birbirine bağla...', 'Duramıyorum, ağlamaktan utanıyorum,  utandıkça ağlıyorum!  Belki bir tek gözyaşının çözebileceği bir dert değildir bu Ağlamamak lazım öyleys...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizligim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sokaklar Benden Sorulur', 'bu-sokaklar-benden-sorulur-kagan-altindal-9lrvp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yollara düştüm.

Puslu bir vakitti.

Hva soğuk, ellerim çıplak.

Rüzgardan savrulan pardesüm.

Bu sokaklar benden sorulur...

Bir elimde tesbihim, diğerinde sigaram

Hava zifiri karanlık.

Sokaklar ölüm sessizliğinde.

Bense kendi derdimdeyim.

Bu sokaklar benden sorulur...

Yine yalnızlık yanımda

Sen hayalimde

Ayrılığın acısı hala yüreğimde

Bu sokaklar benden sorulur...

İlk kavgamı bu sokaklarda yapmıştım.

İlk kez bu sokakta ağlayıp, 

İlk sigaramı bu sokaklarda yakmıştım.

Hatta ilk kez bu sokaklarda vurulmuştum.

Bu sokaklar benden sorulur...

Akan kanımın soğuktan donduğunu hissediyordum.

Boşalan kan elimi ısıtıyordu ama

İçimi soğutuyordu.

Ben o gün sevdamla başbaşaydım.

Bu sokaklar benden sorulur...

Şimdi gider oldum bu sokaklardan.

Sevdam beni yeni bir diyara sürüklüyor.

Buraları son kez gördüğümü biliyorum ama

Yine de arkama bakmadan gidiyorum.

Bu sokaklar benden sorulur...', 'Yollara düştüm. Puslu bir vakitti. Hva soğuk, ellerim çıplak. Rüzgardan savrulan pardesüm. Bu sokaklar benden sorulur... Bir elimde tesbihim...', ARRAY['Türk Edebiyatı','Şiir','Kağan Altındal']::text[], 8.5, '{"poet":"Kağan Altındal","poet_slug":"kagan-altindal","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bu-sokaklar-benden-sorulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-birsen-ertana-3yx8w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırlarmısın sabahlara kadar, 

Başımda beklediğin geceleri anam

Yavrun rahat uyusun diye

Gözlerini bile kırpmadığın geceleri; 

Gençliğini bilemeden 

Aldın ilk bebeğini kollarına

Onu büyütmeyi öğrenirken 

Bir diğeri geldi kucağına, 

Ne anladın geçliğinden söyle annem? 

Onca sıkıntı onca çektin

Bizler iyi bir evlat ve insan olarak yetişelim diye

Başardında, 

Her türlü kaygıya ve yokluğa rağmen

Bumuydu hayattan beklediğin ve istediğin annem, 

Hele bizim için ne çok şey yaptın

Bunu dizelere sığdıramam

Kendin için ne yaptın annem? 

Her şeyden önemlisi; 

Biz senin için ne yaptık anne? 

Hakkını nasıl öderiz söyle annem

Tabiiki bu yükün altından  kalkamayız

Ömür boyu borçluyuz sana

Hakkını helal et annemm', 'Hatırlarmısın sabahlara kadar,  Başımda beklediğin geceleri anam Yavrun rahat uyusun diye Gözlerini bile kırpmadığın geceleri;  Gençliğini b...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ertana']::text[], 8.5, '{"poet":"Birsen Ertana","poet_slug":"birsen-ertana","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/annem-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat İki Buçuk', 'saat-i-ki-bucuk-cem-dogan-tas-byf2y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat İki Buçuk; 

Ne işim var benim bu saatte ayakta? 

Başka ihtimal yok uyuyorsun..

Hayalin benim yanımda, Senbenden uzakta.

Saat iki buçuk; 

Bu bendeki ölme arzusu niye? 

Gözlerim kapanmak istiyor, beceremiyor, 

Yüreğim unutmak istiyor, beceremiyor, 

Neden bendeki sen korkusu? ..

Saat iki buçuk...

.............', 'Saat İki Buçuk;  Ne işim var benim bu saatte ayakta?  Başka ihtimal yok uyuyorsun.. Hayalin benim yanımda, Senbenden uzakta. Saat iki buçuk;...', ARRAY['Türk Edebiyatı','Şiir','Cem Doğan Taş']::text[], 8.5, '{"poet":"Cem Doğan Taş","poet_slug":"cem-dogan-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/saat-iki-bucuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostuma', 'dostuma-birsen-ertana-kwinc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostluğu gerçek anlamıyla bana tattırdın

Hüzünlerime gözyaşı, mutluluğuma kahkaha oldun.

Dertlerimle başbaşayken

Sende benımle dertlendin

Paylaştın yanlızlığımı.

Anlatabilsem ne güzel şey senle olmak; 

Tüm benliğinle bütünleşmek, 

Yanında senin gibi bir dost olduğunu bilmek

Öyleki; 

Artık yürürken ayaklarım oluyorsun, 

Gözlerim oluyorsun bakarken gökyüzüne, 

Irmak olıyorsun hayallerimde, 

Gönlüme akıyorsun durmadan.

Sennnn en iyi dostumm

Paylaştığımız en gizli sırlarımız geliyor aklıma :)

Birden dalıyorum geçmişe vee

Birden gelecek oluyorum seninle, 

Kimbilir hayat gelecekte nice paylaşılmayı bekleyen 

sırlara ve düşlere gebe

Ve beraberce yürüyoruz paylaşılmayı bekleyen 

Sırlara ve düşlere.

Seni seviyorum arkadaşımm', 'Dostluğu gerçek anlamıyla bana tattırdın Hüzünlerime gözyaşı, mutluluğuma kahkaha oldun. Dertlerimle başbaşayken Sende benımle dertlendin Pa...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ertana']::text[], 8.5, '{"poet":"Birsen Ertana","poet_slug":"birsen-ertana","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dostuma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadım, Ölüyorum!', 'yasadim-oluyorum-cem-dogan-tas-2516d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşadım ve; 

Günü geldi ölüyorum! 

Geriye dönüp düşünüyorum 

Güldüğüm bir tek günü bilmiyorum.', 'Yaşadım ve;  Günü geldi ölüyorum!  Geriye dönüp düşünüyorum  Güldüğüm bir tek günü bilmiyorum....', ARRAY['Türk Edebiyatı','Şiir','Cem Doğan Taş']::text[], 8.5, '{"poet":"Cem Doğan Taş","poet_slug":"cem-dogan-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasadim-oluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özet', 'ozet-cem-dogan-tas-yw5p1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaş yirmibeş; 

Yolun yarısındayım..

Farkına bile varmadan, 

Çok degil yarın; sonundayım 

Sen yanımda olmadan! ..', 'Yaş yirmibeş;  Yolun yarısındayım.. Farkına bile varmadan,  Çok degil yarın; sonundayım  Sen yanımda olmadan! .....', ARRAY['Türk Edebiyatı','Şiir','Cem Doğan Taş']::text[], 8.5, '{"poet":"Cem Doğan Taş","poet_slug":"cem-dogan-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ozet-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cyrano Ölünce', 'cyrano-olunce-sabri-gurbuz-n3pt5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cyrano ölünce

Aşığa kim sufle verecek

Serenat beyaz yalandı

Evliliği kim sürdürecek

Başucumda kemikleşmiş hayaller

Şevkimi ne süsleyecek

Yağmurlar bekle ki temizlesin

Bulutları kim yıkayacak

Söze ve kaleme küsmüş

Yalanı kim besleyecek

Umudunda çürük koku

Meryem''i kim aklayacak

Ateş, ateş, ateş

Heryan koku, heryan yangın

Mancınıkta serbest yürek

Bahçeyi gezmeye gidecek

Cyrano ölünce

Aşığa kim sufle verecek

Pamuk ipliğinde hayat bitince

Ayağımı kim yerden kesecek', 'Cyrano ölünce Aşığa kim sufle verecek Serenat beyaz yalandı Evliliği kim sürdürecek Başucumda kemikleşmiş hayaller Şevkimi ne süsleyecek Yağ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cyrano-olunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-sair-karagozlum-apm70', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben dertlerimi denize attim

o dalgalandikca rahatlarim.

Yalnizligimi yildiza firlattim

geceleri bana pencereden parlayinca onu hatirlarim

Gülüsümü günese hediye ettim

görmedikce gülümsemeyi unuttum diye bilirim.Ve seni güzelim gökyüzüne astim

sana baktikca dertleri unutur

yalnizligimi giderir

ve gülmeyi dostlugun sayesinde ögreniyorum

ve 

senin gibi bir dostun üzülmesine dayanamiyorum.

Ben sadece sn mutlu oldukca mutlu olabiliyorum.', 'Ben dertlerimi denize attim o dalgalandikca rahatlarim. Yalnizligimi yildiza firlattim geceleri bana pencereden parlayinca onu hatirlarim Gü...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dostum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Böyledir', 'ask-boyledir-sair-karagozlum-fhkuc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecen gündüzün birbirine karisir

bu kalb nasil böyle ayriliga alisir

her gecn gün hasret daha cok sana yaklasir

ask dedigin sey iste insana böyle bulasir.

Ya sor kalbe nasil dayanir

yüregini felaket depremler sarsar

sesiz esen ask rüzgarlarindan firtinalar kopar

ve bak su kalbe ici üzüntü ve aci ile dolar.

Hersey bir bakisla baslar

birbirlerinden haric kimseyi görmez asiklar

dilkleri ise bir ömür boyu bitmeyen sevdalar

kurulan hayaller ve toz pembe hikayeler

dedimya böyle baslar büyük asklar.

Sor asiga dilegin nedir diye

Asik derki en derinden gelen sesle

bizi ayirmasinlar kavustursunlar bu benim icin en güzel hediye

ask dedigin seye tutuldugun zaman veremezsin geriye.

Ne söz yeter ne kelime 

Ne düsler kurulur ne hayaller yasatir

daha önce yasamadinsa iste bu asktir

bir gün onsuz yasayamazsin

Onu düsler onunla hayal kurarsin

günün birinde elinde bir demet güllerle beklersin

özlemler bitmek bilmez hasret dersen icinden gitmez

eger aski ask gibi yasayabiliyorsan 

ozaman sunu bilki bu ask hic tükenmez.', 'Gecen gündüzün birbirine karisir bu kalb nasil böyle ayriliga alisir her gecn gün hasret daha cok sana yaklasir ask dedigin sey iste insana ...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ask-boyledir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-dilek-gullu-xaxp2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sev de nasıl seversen sev, ama yine sev, 

Elimi uzatacağım, korkuyorum.. tutmazsın diye, 

Nedeni yok, her şeye rağmen, ben yine seviyorum, 

İnsanoğlu sevemez mi? severse suç mu? .. severse cezamı? .. 

Seni sevdiğimi, seninde sevdiğini, 

Elimi uzattığımda, tuttuğunda anlıyorum, 

Ve işte haykırıyorum, SENİ SEVİYORUM... 

İstiyorum, son kez de olsa, seni sevdiğimi söylemek istiyorum. 

Ya aramazsa, ya sormazsa diye hep korkarım, 

Onun sevgisi tutar beni ayakta, o zorlar beni yaşamaya, 

Rahat bırakın beni artık, 

Unutmak istesem de olmuyor, 

Madem ki olmuyor, ben sevmeye mahkumum...', 'Sev de nasıl seversen sev, ama yine sev,  Elimi uzatacağım, korkuyorum.. tutmazsın diye,  Nedeni yok, her şeye rağmen, ben yine seviyorum,  ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Güllü']::text[], 8.5, '{"poet":"Dilek Güllü","poet_slug":"dilek-gullu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek Çıkmazı', 'melek-cikmazi-cezmi-ersoz-qx62i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşamları boynundaki merhamete sıgınan

aşkın ölü kuşlar, 

daha sabah olmadan

seni tükettiklerini anlar anlamaz, 

kirli ve acımasız bir dalgınlıga uçarlardı.

Kıstırdıgın sokaga adını vermişlerdi: 

Melek çıkmazı...

Gidecek evi olmayan bulutsu bir misafirdin, 

ezilen kanatlarından sunulmuştu sana tek okşayış...

Öyle sert ve öyle belrsizdi ki her şey, 

ona uymayınca çogalırdı

dünyada hazır buldugun boşluk...

Tutundugunda boşluk sana, 

yüzünün ışıgını öperdi yüzün.

Yalnızlık küçümsediginde seni

gögün içindeki aslını görürdün.

Gögün içindeki, 

senden çıkan her şeyin konakladıgı o sonsuz evi...', 'Akşamları boynundaki merhamete sıgınan aşkın ölü kuşlar,  daha sabah olmadan seni tükettiklerini anlar anlamaz,  kirli ve acımasız bir dalgı...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/melek-cikmazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onyedi Ağustos Unutulurmu', 'onyedi-agustos-unutulurmu-salih-ozalasan-prgua', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '17 Ağustos toprağın yarılıp

İnsanları yuttuğu kötü bir gece

Saatler usul usul gelirken bir bitişe

Masum insanların yok olduğu bir gece

Unutmak mümkünmü böyle bir geceyi

Aradan çok, çok uzun yıllar geçsede

Unutulurmu kulakları parçalayan

Gecenin karanlığını delen çığlık sesleri

Unutulurmu toprağın altına gömmek

Pırıl pırıl o masum Güneş''leri

Unutulurmu annesini arıyan

Yavrusunu kaybeden anne sesleri

Unutmak ne mümkün, Unutulmaz

Yüreğimizde hep o acı gecenin izleri

Biranda kaybettik anne, bacı, çocuk ve eşleri

Seni hiç unutmayacağız 17 Ağustos depremi', '17 Ağustos toprağın yarılıp İnsanları yuttuğu kötü bir gece Saatler usul usul gelirken bir bitişe Masum insanların yok olduğu bir gece Unutm...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/onyedi-agustos-unutulurmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Sızan Tebessüm', 'kan-sizan-tebessum-cezmi-ersoz-ryqbx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dayanamadın, çıktın artık

seni sakladıgım derinliklerden

ışık yagıyor, şimdi mutlu yagmurlar

kan sızan tebessüme...

Öyle yitiksin ki

alıp götürebilirmisin beni ve hayatımı

ardımızda ne bu akşam

ne de kan sızan tebessümün...', 'Dayanamadın, çıktın artık seni sakladıgım derinliklerden ışık yagıyor, şimdi mutlu yagmurlar kan sızan tebessüme... Öyle yitiksin ki alıp gö...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kan-sizan-tebessum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçime Boşal', 'i-cime-bosal-cezmi-ersoz-ao5bk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Emerdim, emerdim gövdeni...

İçine girip, kendime boşalmak isterdim.

İsterdim ki teslim olmam yetmesin sana, 

seni sevdikçe büyüyen korkularımdan

beni sevdikçe çogolan inaçsızlıgından

bir ev yapayım kendime, 

bir ev, 

annemin talan edilmiş saf rahmi gibi

sonsuza kadar kendimi onunla yakacagım...', 'Emerdim, emerdim gövdeni... İçine girip, kendime boşalmak isterdim. İsterdim ki teslim olmam yetmesin sana,  seni sevdikçe büyüyen korkuları...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/icime-bosal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşlık Hataları', 'arkadaslik-hatalari-cezmi-ersoz-81h12', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşkün bir prenstin

muhtaç kalmıştın bu dünyada görünmeye

bitmeyen arzularına muhtaç kalmıştın

Sadece fakir biriydin sana göre

beni görünce öylesine kaptırmştın ki

o eski muhteşem günleri anmaya

fark edememiştin beni

Yine de küllerini getirdin bana

bu kayıp dünyanın sayıklıyan tarihine

benimle geçmek istedin...

Oysa düşkünde olsalar

prensesler iyi bilmeliydi

kimlerle tarihe geçeceklerini

vurulmuş bir insanla kurtulmayı düşlemenin

onu bir kez daha vurmak oldugunu...

Hem artık sayıklayan tarihin bile çok vakti yoktu

düşkün prenseslerin arkadaşlık hatlarını bagışlamaya...', 'Düşkün bir prenstin muhtaç kalmıştın bu dünyada görünmeye bitmeyen arzularına muhtaç kalmıştın Sadece fakir biriydin sana göre beni görünce ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/arkadaslik-hatalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karnındaki Bıçak İzi', 'karnindaki-bicak-i-zi-cezmi-ersoz-8tu3n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir baş dönmesiydi bıraktıgın

içindeki bilgeligi taşırmak için

küçülüyordun karşımda

bütün suçlarımı üzerine alıyordun...

Anlatmaktan yorulmuş bir veda oluyordun

beni ölüme hazırlamak için

küçülüyordun karşımda

bütün suçlarımı üzerine alıyordun

Bir baş dönmesiydi bıraktıgın

kirli, susuz, kutsal sızı

küçülüyordun karşımda

karnındaki bıçak izi yastıgımdı...', 'Bir baş dönmesiydi bıraktıgın içindeki bilgeligi taşırmak için küçülüyordun karşımda bütün suçlarımı üzerine alıyordun... Anlatmaktan yorulm...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karnindaki-bicak-izi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Beklediğim', 'son-bekledigim-faruk-nafiz-camlibel-25i53', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ufkumda bulutlar kümelerken kara bahtım, 

Ben her gönül ufkunda doğan sabahtım.

Devran herkese taslarla zehir sundu da birden

Ben herkese bir neşe yarattım o zehirden.

Bir köprü kurup, zulmetin ardında, seherle, 

Bildim gülüp eğlenmeyi ömrümce kederle.

Aln
..........
..........', 'Ufkumda bulutlar kümelerken kara bahtım,  Ben her gönül ufkunda doğan sabahtım. Devran herkese taslarla zehir sundu da birden Ben herkese bi...', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlıbel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlıbel","poet_slug":"faruk-nafiz-camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/son-bekledigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fidandı Sevdam', 'fidandi-sevdam-suna-gunes-66h9m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şubat fidanım, sevdam tezeciğim

yeni sürgünlerin vardı ilkbaharda

okşamaya doyamadığım, kıyamadığım

minik yaprakların vardı.

kavurdumu, yaz seni benzin sarardı

çokmu suladım toprağını, .dalını, 

nefes alamadınmı sevdam.

boynunu büktün, yüzünü döndün, 

boy atacaktın semaya başın dik, 

meyvelerin olacaktı sevdadan.

şimdi, benimde dalarım eğik sensiz

sonbaharı  bile göremedik sevdam...', 'şubat fidanım, sevdam tezeciğim yeni sürgünlerin vardı ilkbaharda okşamaya doyamadığım, kıyamadığım minik yaprakların vardı. kavurdumu, yaz ...', ARRAY['Türk Edebiyatı','Şiir','Suna Güneş']::text[], 8.5, '{"poet":"Suna Güneş","poet_slug":"suna-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fidandi-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alçıdan Heykel', 'alcidan-heykel-faruk-nafiz-camlibel-bbz8n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanıştığım günden beri enginle

Bir taşın üstünde hayale daldım.

Bulacaksın koymuş gibi elinle, 

Ben nerde doğmuşsam o yerde ka
..........
..........', 'Tanıştığım günden beri enginle Bir taşın üstünde hayale daldım. Bulacaksın koymuş gibi elinle,  Ben nerde doğmuşsam o yerde ka .......... .....', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlıbel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlıbel","poet_slug":"faruk-nafiz-camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/alcidan-heykel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Nostalji', 'sevgiye-nostalji-okan-sozener-rpv45', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece dikmiş gözlerini gözlerime

Bir şeyler görmemi istiyor

Kirpiklerim sımsıkı kapalıyken 

Bir mesaj iletmekte

Anlamayana, anlayıp sormayana.....

Geziyorum adayı, serseri adımlarla

Çakıl taşları yansıtmakta günün yorgunluğunu

Düş bahçeleri, sensiz ürpermekte

Yarınsız yarınları karşılarken, 

Uzakta, çok uzakta bir yerde

Bir ibibik kuşu ötmekte

Orman o gün uyanırken doğaya....

Gece gözlerini dikmiş gözlerime

Beni, benimle sorgulamakta

Dipsiz kuyuya düşen taş

Yankılanmakta evrenin sonsuzluğunda

Oysa; 

Ben kör bastonu elimde

Bakar kör gözlerimle

Gök kuşağının altından geçmekteyim

Sarsak adımlarla......

Karşı köprü başını tutan 

Mağrur salkım söğüt

Sanki eğilmemi öğütlemekte

Eh..''Klavuzda karga ise, 

Ne işi var burnumun kafdağının karında......

Hayat böyle gelmiş böyle gider

Ruhunda arıyorsan eğer, 

Bir izdüşümü mutluluğa

Sen, seni sen yapan değerlerden ayrılma..''', 'Gece dikmiş gözlerini gözlerime Bir şeyler görmemi istiyor Kirpiklerim sımsıkı kapalıyken  Bir mesaj iletmekte Anlamayana, anlayıp sormayana...', ARRAY['Türk Edebiyatı','Şiir','Okan Sözener']::text[], 8.5, '{"poet":"Okan Sözener","poet_slug":"okan-sozener","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevgiye-nostalji-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Doğuş', 'yeniden-dogus-okan-sozener-fx3bv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umut yorgunu güneş

Beklerken düş dağlarının ardında

Hayat vapuru, kalktı tam saatinde limandan

Sonsuzluğa yolculuğunda

Herkes biletsiz...

Ayrılık acısı yüreğimde

Bıraktı izlerini, 

Vapurun ardında bıraktığı gibi.! ! ! 

Oysa; 

Zaman zaman, 

Üşüdüğüm olmuştu düşlerimde

İsyan ettiğim yalnızlığım

Kucaklama beni yeniden 

Toprağın altında değil üstünde

Yemyeşil yaşamak istiyorum.

Hayat; 

Ertelenmiş bir yudum sevgi borçlusun bana! 

O sevgiyi, doyasıya yaşamak istiyorum

Paylaşan bir sevgilim olduğunda

Sanmaki sevginin sınırı yok

Oda çerçeveli

Verdiği kadar almakla....! 

Paylaşacağım bir sevgili yoksa eğer, 

Neye yarar sevginin balı, çiçekte

Yaşayamazsın ruhum, özgür olmazsan

Bu sevgiyi, yalın, çırılçıplak

Asude, kem gözlerden ırak...', 'Umut yorgunu güneş Beklerken düş dağlarının ardında Hayat vapuru, kalktı tam saatinde limandan Sonsuzluğa yolculuğunda Herkes biletsiz... Ay...', ARRAY['Türk Edebiyatı','Şiir','Okan Sözener']::text[], 8.5, '{"poet":"Okan Sözener","poet_slug":"okan-sozener","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yeniden-dogus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-yusuf-alper-4xo5m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anladım bir yeryüzü sürgünü olduğumu yeniden

Neresinden tutacağımı bilemediğim bu hayat

hoyrat insanların tornasında eğilen, bükülen

Acıyla, elemle herkesin birbirini ve beni

yemesini seyreden, yeniden ve yeniden...

Anladım iflah olmaz biri olduğumu, yeniden

Beynime çevrilmiş silah, göğsüme dayanmış hançer, 

kalbime sokulmuş dinamit; binbir söz, binbir yüz

Anladım, ağaçta kızaran elma, tarlada büyüyen buğday, 

saksıda yeşil fesleğen, rüzgarla savrulan yaprak, 

tepelerde dönen kartal, anladım anladım

Anladım görür görmez ''işte bencileyin bir adam'' der, Celal Usta

Saçma bir dünyada hayatın anlamını arayan

‘Herşeyin ama herşeyin bir anlamı'' olduğunu

bilen, bildiren ruh marangozu

Alnımın ortasındaki o derin çizgiden kendi çizgisine anlam taşıyan

Anladım, hayatın kıyısında, yalnız, kendince, bilge

Alnının ortasında derin çizgiyle...

Anladım, insanlar insanları öldürebilir, ciğerlerini sökebilir, 

çarmıha gerebilir, kazığa oturtabilir, çiğ çiğ yiyebilir

Ben kusarım. Bütün ölenler için öldürenlere

Irmaklarca, denizlerce... tiksintiyle, elemle

Adımı insan hanesinden siliyorum

Siliyorum, siliyorum, tiksiniyorum

Anladım, yeniden anladım; insan hanesinden adımı siliyorum', 'Anladım bir yeryüzü sürgünü olduğumu yeniden Neresinden tutacağımı bilemediğim bu hayat hoyrat insanların tornasında eğilen, bükülen Acıyla,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Alper']::text[], 8.5, '{"poet":"Yusuf Alper","poet_slug":"yusuf-alper","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yeniden-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İz', 'i-z-yusuf-alper-8sl11', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çöz çöz bitmeyen bir yumağın ilmiğiyiz

Başı sonu belirsiz, yolcusuz yol gibiyiz

Kimimiz bir deniz dinginliğinde duru

Kimimiz kayalara çarpan dalga gibiyiz

Karanlığın ortasında bir çıra

Bir kandil ışığıyla yanar gibiyiz

Bir avuç buğday, sonyaz tarlasında

Tınaz türküsünün serin ezgisi gibiyiz

Günü, geceyi savuran, zamanı eleyen yürek

Dünü yarına bağlayan yollarda bir iz gibiyiz', 'Çöz çöz bitmeyen bir yumağın ilmiğiyiz Başı sonu belirsiz, yolcusuz yol gibiyiz Kimimiz bir deniz dinginliğinde duru Kimimiz kayalara çarpan...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Alper']::text[], 8.5, '{"poet":"Yusuf Alper","poet_slug":"yusuf-alper","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinden', 'i-cinden-yusuf-alper-5pyqw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçinden tren geçen bir yüreğim ben

Nasılsa kıyıya düşmüş, nasılsa yalnız

Nasılsa anlaşılmaz bir yüreğim ben

İçinden tren geçen, ezen geçen

Anlaşılmaz bir gizem adım başında

Kanadı kırık kuşlar gibi insanlar

Kartal, akbaba gibi insanlar

Kanadı kırık kuş gibi biriyim ben

Nereden başlasam, nasıl başlasam? 

Kendi yüreğine sürgünüm ben

At değiştir at tokuştur, boş bunlar

Kendi yüreğine kurşunum ben

Irmak kıyısı, yeşil tepeler

Yağmurla ıslanmak yalçın bir dağda

Ateş yakmak, üşümek hep üşümek

Kendi dağında bir yangınım ben

Nereye gitsem, kime söylesem? 

İçimdeki ben, dışımdaki ben

Kanadı kırık bir kırlangıcım ben

İçindeki ben, içimdeki ben!', 'İçinden tren geçen bir yüreğim ben Nasılsa kıyıya düşmüş, nasılsa yalnız Nasılsa anlaşılmaz bir yüreğim ben İçinden tren geçen, ezen geçen A...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Alper']::text[], 8.5, '{"poet":"Yusuf Alper","poet_slug":"yusuf-alper","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/icinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Düşünü', 'gulun-dusunu-yusuf-alper-135fu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buğday tarlasında devedikeni

Nasıl da kaydı yıldızlarımız

Nasıl da kaçırdık narın rengini

Sincabın hüznünü, gülün düşünü

Attığın adımda çukur olabilir

Baktığın gözlerde derin kuyular

Kuyular ki dibi sonsuza uzar

Gecenin şafağı tutkuyla öptüğü

Bu bakış, bu masum yüz...

Atlarımız nerde kaldı, nerde kalmıştık? 

Saban demirimiz nasıl sivrilirdi? 

Kıldan heybemizde ekmeğe katık neydi? 

Maveraünnehr’e at sırtında kaç zamanda gidilir? 

Kaç ok kaç mızrak almalı yanına? 

Semerkant Buhara Taşkent yollarında

Bir derviş gibi duru hüzünle

Bin yüzün çarptığı ayna kırıldı

Dağıldı içimde o sonrasız aşk

Buraya nasıl geldik, şimdi nerede..? 

Kalbin incele incele yürek olduğu', 'Buğday tarlasında devedikeni Nasıl da kaydı yıldızlarımız Nasıl da kaçırdık narın rengini Sincabın hüznünü, gülün düşünü Attığın adımda çuku...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Alper']::text[], 8.5, '{"poet":"Yusuf Alper","poet_slug":"yusuf-alper","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gulun-dusunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Av', 'av-yusuf-alper-dbkoh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Avcı tüfeğini doğrulttuğunda, kanadım olsun isterdim

Çalılıklardan fırlayarak göğe uzanmak isterdim

Yaralı, yalnız bir kuş olmak, ölmek yerine

Sonsuza uçan otuz kuş olmak isterdim.

Avcı tüfeğini doğrulttuğunda ona çevirmek isterdim

İçinde havai fişekler olsun isterdim

Yaralanmasın, ölmesin isterdim

Beni vurmasın isterdim

Avcı ay olsun isterdim

-Diyorum ya siz inanmayın-

Sınırsız bir ülkede

Ne av ne avcı olsun isterdim', 'Avcı tüfeğini doğrulttuğunda, kanadım olsun isterdim Çalılıklardan fırlayarak göğe uzanmak isterdim Yaralı, yalnız bir kuş olmak, ölmek yeri...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Alper']::text[], 8.5, '{"poet":"Yusuf Alper","poet_slug":"yusuf-alper","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/av-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Bitti', 'zaman-bitti-yildirim-turker-ztbvd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkma sevgilim

Zaman bitti! 

Kendine dönen

sadece akrep değil şimdi.

Dünyadan silkindik gergin inadımızla.

Hızımızdaki yara

sarıldı geçti böylece

aşkımız Zaman''ın yanından.

Cama yaslanıp seyrettik

içerden bir ölüdoğa gibi.

Dişlerinde durakladı önce o parıltı.

Benim ellerim biraz titredi.

Korkma sevgilim

Zaman bitti! 

Gül değil

bir gül resmi tuttu sırrımızı

birbirimize astık hızımızı

soyunduk ilmeğinden bu mevsimin.

Baktık duru aynalar gibi birbirimize

aramızda duran gövdelerimize.', 'Korkma sevgilim Zaman bitti!  Kendine dönen sadece akrep değil şimdi. Dünyadan silkindik gergin inadımızla. Hızımızdaki yara sarıldı geçti b...', ARRAY['Türk Edebiyatı','Şiir','Yıldırım Türker']::text[], 8.5, '{"poet":"Yıldırım Türker","poet_slug":"yildirim-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaman-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Et', 'hayal-et-yildirim-turker-flw43', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerin hayalet gibi... koynumda

Beni kaldıran yolcu eden hayal aynası

Öptükçe nefret bulaşıyor ağzıma

İnce sinsi acıbadem kokusu

Şehvet kostümlüydü o kış aramızda

Aşk ve Opera

Aşk ve Opera!', 'Ellerin hayalet gibi... koynumda Beni kaldıran yolcu eden hayal aynası Öptükçe nefret bulaşıyor ağzıma İnce sinsi acıbadem kokusu Şehvet kos...', ARRAY['Türk Edebiyatı','Şiir','Yıldırım Türker']::text[], 8.5, '{"poet":"Yıldırım Türker","poet_slug":"yildirim-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hayal-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzler ve Günler', 'yuzler-ve-gunler-yavuz-ozdem-9pn08', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mükemmel bir bedel ödenecek hissediyorum ya

sen yoksun bir de yokluğuna aşık oluyorum

bu yüzden

faydalı korkularımız ballanıyor dudaklarında

buluşmanın en çok

odamız sabahlandırılıyor kuşları ışıklandırılıp

vapurlar zamanında kalkıyor tam bunun 

onuruna koşuyoruz

uzağa / uzaklara yazıyorum ama

öfkeden doğmayan konuşmalara

yalnız asıl korktuğunu bakmalara

utanca boğulmanın inkarına

beşiktaşta alınan öpücüklere - hergüne

şahsa

bireye yakına

hayatla

mükemmel bir bedel ödenecek biliyorum.', 'Mükemmel bir bedel ödenecek hissediyorum ya sen yoksun bir de yokluğuna aşık oluyorum bu yüzden faydalı korkularımız ballanıyor dudaklarında...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Özdem']::text[], 8.5, '{"poet":"Yavuz Özdem","poet_slug":"yavuz-ozdem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuzler-ve-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylemlik', 'eylemlik-yavuz-ozdem-b182b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklım yaz yağmurlarına takılınca

yüzüne bakıyorum

yüzündeki zamana

bir temmuz peyda oluyor

çocukluğumdan, kurumuş ot kokularından

geçmiş bir hoşluktan ve huzurdan

şaşırıyorum hangi zenaatı tutacağımı', 'Aklım yaz yağmurlarına takılınca yüzüne bakıyorum yüzündeki zamana bir temmuz peyda oluyor çocukluğumdan, kurumuş ot kokularından geçmiş bir...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Özdem']::text[], 8.5, '{"poet":"Yavuz Özdem","poet_slug":"yavuz-ozdem","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/eylemlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Televizyonu Sevmiyorum', 'televizyonu-sevmiyorum-yalvac-ural-2-xl047', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskiden yaz akşamları

Babamla sinemaya giderdik

Gazoz, çekirdek alırdık

Evimize televizyon geldi

Yazlık sinema kapandı

Ben bu değişimden memnun değilim

Çünkü istediğim filmi göremiyorum

Sanki zorunluymuşum gibi

O ne isterse onu seyrediyorum.', 'Eskiden yaz akşamları Babamla sinemaya giderdik Gazoz, çekirdek alırdık Evimize televizyon geldi Yazlık sinema kapandı Ben bu değişimden mem...', ARRAY['Türk Edebiyatı','Şiir','Yalvaç Ural 2']::text[], 8.5, '{"poet":"Yalvaç Ural 2","poet_slug":"yalvac-ural-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/televizyonu-sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğinden Ayrılmak Zarar Yaşama', 'sevdiginden-ayrilmak-zarar-yasama-yalvac-ural-2-3hn4l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söyle gabardıç

Söyle

Döksem yüreğimin kederlerini

Acıgöle

Daha da mı acı olur dersin

Bassam

Tuzgölünün

Tüm tuzlarını yaralarıma

Kanaması durur mu acep

Yaralarımın

Ya çıksam

Dağların

Duman yüklü başına

Söndürür mü rüzgarların esintisi

İçimin yangınını

Vurur mu gümbürtüsü ormanların

Başıma

Yoksa ağlar döner miyim

Ben bu sevdadan

Söyle gabardıç söyle

Ağlar döner miyim', 'Söyle gabardıç Söyle Döksem yüreğimin kederlerini Acıgöle Daha da mı acı olur dersin Bassam Tuzgölünün Tüm tuzlarını yaralarıma Kanaması dur...', ARRAY['Türk Edebiyatı','Şiir','Yalvaç Ural 2']::text[], 8.5, '{"poet":"Yalvaç Ural 2","poet_slug":"yalvac-ural-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdiginden-ayrilmak-zarar-yasama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-unal-ersozlu-lzjdh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin için bir şiir yazmalıyım bu gece

mesela anlatmalıyım aşk için

ne kadar kahraman olmadığımı

aşkın aşka nasıl yenildiğini

bir de aşk için nasıl çıldırdığını aşkın', 'Senin için bir şiir yazmalıyım bu gece mesela anlatmalıyım aşk için ne kadar kahraman olmadığımı aşkın aşka nasıl yenildiğini bir de aşk içi...', ARRAY['Türk Edebiyatı','Şiir','Ünal Ersözlü']::text[], 8.5, '{"poet":"Ünal Ersözlü","poet_slug":"unal-ersozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmamış Sevgiye', 'yasanmamis-sevgiye-okan-sozener-t35di', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana olan özlemim

Kazanıyor ivme her saniye

Seni yüreğimden çabaladıkça atmaya 

Bir bataklık misali sanki 

Daha çok batıyorum.

Kafamın içindeki delik

Gün geçtikçe büyümekte

Biliyorum bu bir karadelik

Bütün benliğimi çekti aldı oradan

Geriye kalan hücrelerimde

Artık tamamen sen varsın

Ama nedense bir tanem 

Varlık içinde yokluk çekiyorum

Bilir misin sen karşılıksız sevmeyi? 

Ben işte onu yaşıyorum..

Seni kalbimin içine hapsedip

Anahtarını denize atmışlar

Çıkaramıyorum o nedenle 

Seni oradan....

Eğer olsaydı bir zere umut

Dalıp bulurdum onu 

Deniz büyük umut küçük demeden...', 'Sana olan özlemim Kazanıyor ivme her saniye Seni yüreğimden çabaladıkça atmaya  Bir bataklık misali sanki  Daha çok batıyorum. Kafamın içind...', ARRAY['Türk Edebiyatı','Şiir','Okan Sözener']::text[], 8.5, '{"poet":"Okan Sözener","poet_slug":"okan-sozener","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yasanmamis-sevgiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua-Temenni', 'beddua-temenni-sair-zevat-sxfof', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benliğin  aslında sensiz bir düşman....

nede olsa kalbinde açmıyor mu tohumu isyan.....

çağırsa da mutluluk somutluğunda beni sana..

artık sen yoksun benim için bunu sakın unutma....

dağlar kadarda olsa sevdan.....

onu yıkacak ufak bir hezeyan....

ve bunu başaracaksa gene sendeki o karanlık dünyan....

bahçelerinde bitmesin kaktüsten başka bahar.....

rüyalarını çepeçevre sarsın ağırbasanlar.....

söylediğin her sözde gözlerin dolsun....

ettiğin tüm bedduaların birer birer seni bulsun.... 

ama tüm karanlıklarının arkasında benim gölgemde mutluluğun saklı olsun.......                                                   inşallah kalbinde binbir sızıdan ziyade bensizliğin pişmanlığı dolsun....

çilelerin gelir geçer.....

ama bensizliğin sonsuz çile olsun......

dönüp dolaşıp, yanıla yakıla arayacağın kapı benim kapım olsun....

...

Rüyalarında tüm gerçeklik yüzüne vursun...

Gecelerin gözyaşlarına gebe olsun...

Uzaklara baktıkça gözlerinden değil kalbinden yaş gelsin..

Beklediklerin, beklentilerin seni hep bekletsin..

Seni anlayacaklarda birer birer seni terketsin..

Nedensizce günlerin boşlukta, gözlerin geçmişte gezsin

Nedenini anlamaya çalıştıkca zaman seni senden vazgeçirsin..

Ölüm senden uzak olsun...kalbinde bensizliğin pişmanlığı...

Yıllarca seni üzenler alsın intikamımı..

Ama ellerin uzansa da telefona 

çevirdiğinde hayıfların duyulsun her nefes alışında.

Gözlerinde geçmişin acısı...kulaklarında verdiğin sözlerin...

Her damla gözyaşı saatlerini alsın, 

unutmak istedikçe seni sarıp sarmalasın.

Kollarında bensizlik fırtınaları, 

Kafanda yalnızlık ağrıları

Tüm vücudunda unutamamanın sızıları

Ellerinde boşluğun titreyişleri seni paklasın..

Ama ne olursa olsun.. Bu sözlerin hiç biri senin hayatında olmasın....

Mutluluk sana benden kalan tek dost...

Gülümseme sana benden kalan tek umut...

Sendeki kalbimde sana benden koruyucu tek meleğin olsun..', 'Benliğin  aslında sensiz bir düşman.... nede olsa kalbinde açmıyor mu tohumu isyan..... çağırsa da mutluluk somutluğunda beni sana.. artık s...', ARRAY['Türk Edebiyatı','Şiir','Şair Zevat']::text[], 8.5, '{"poet":"Şair Zevat","poet_slug":"sair-zevat","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/beddua-temenni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıt', 'yanit-guven-turan-6gkcz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimdeki derinlik, 

Engelliyor yaklaşmayı başkalarına

Hep uzaktan konuşuyorum

Benim başımı döndürenden

Neye borçluyum ürkmeyişini

Geçtiğin ya da takılıp kaldığın

Sevgilere mi

Yoksa seni de derinleştiren

Bilinmezliğine mi içinin

Yalnızlığı keşfetmiştik

Konuştuğumuzda

Birbirine doluyor

İki uçurum', 'İçimdeki derinlik,  Engelliyor yaklaşmayı başkalarına Hep uzaktan konuşuyorum Benim başımı döndürenden Neye borçluyum ürkmeyişini Geçtiğin y...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yanit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışım', 'bakisim-guven-turan-o30ve', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Balık denizden

Denizden ocağı canlı tutan

Tahta

Dağılan bir kayığın

Kıyıdaki izdüşümü

Olarak karşıma çıkan

Bir gün

Suya veririz

Kendi teknemizi de

Bir döküntü düşer

Bir başka kıyıya

Ateş olur akşam

Aşının altına', 'Balık denizden Denizden ocağı canlı tutan Tahta Dağılan bir kayığın Kıyıdaki izdüşümü Olarak karşıma çıkan Bir gün Suya veririz Kendi teknem...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bakisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklentiler', 'beklentiler-guven-turan-02234', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nereye kadar giderim

Durduğum yerde

Hep o soru var

Sevişmemde

Yediğim yemekte

Bir mektubun altına

Attığım imzada

Yıllar önce yaşanacak olandı

Bugüne ertelenen

Bugünden yarına

Ertelemeye devam ettiğim

Çatışmalar yaşamın kısa tanımı

Oysa

Durgunluk gelir

Fırtınadan önce.', 'Nereye kadar giderim Durduğum yerde Hep o soru var Sevişmemde Yediğim yemekte Bir mektubun altına Attığım imzada Yıllar önce yaşanacak oland...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beklentiler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kent ve Kendisi', 'bir-kent-ve-kendisi-guven-turan-r7w30', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denize bakarken bile

Deniz düşlemek

İşte bu yaptığı çoktandır

Ve kendini bir kentte tasarlıyor

Sokaklarında tramvaylar dolaşan

Kesme sarı taş binalarda

Kararmış demir balkonlar

Güvercin sisi güvercin

Tersi camlarda

Ama düş bunlar

Ne karşısında ne

Yok', 'Denize bakarken bile Deniz düşlemek İşte bu yaptığı çoktandır Ve kendini bir kentte tasarlıyor Sokaklarında tramvaylar dolaşan Kesme sarı ta...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-kent-ve-kendisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birikintiler Anıtı', 'birikintiler-aniti-guven-turan-p3dws', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dumanlar sarmaşığı bir sevda

Örüyor geçeneklerimi

Uçurumlar taşıyan yaz

Dağılıyor denizin üstünde

Ağır yapışkan bunluğuyla düşler

Anılarımdan alıp kaynağını

Salıyor kuduz imlerini üstüme

İçimin balçığında tükeniyorum

Sokaklar kokuşuyor

Kimsede anlamını bulamadığım kentte

Beklemekten usanınca tohumu

Kendi yaramı deşiyorum

Bir ad umuduyla birleşince

Daha kolay uzuyor günler

Kızgınlık ter ve yorgunluk

İzleri bırakıyor kasıklarımda

Yalın yufka yaşamalardan geçip

Delici çağıltılarla

Katılaştırıyorum tortuları

Fazlasını bağışlayabilirim sana.', 'Dumanlar sarmaşığı bir sevda Örüyor geçeneklerimi Uçurumlar taşıyan yaz Dağılıyor denizin üstünde Ağır yapışkan bunluğuyla düşler Anılarımda...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/birikintiler-aniti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalışkan', 'caliskan-guven-turan-psbv4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gece, balkonda sevişmiştik.

Ay, bulutlar, yıldızlar, 

Geçen bir uçağın ışıkları

Yansımıştı gövdelerimizde; 

Aydınlanmıştı gece, 

Bir nabız gibi atmıştı Ada''nın

Toprağı, 

Neden sonra fark etmiştik

Karanlık denizi, 

Karşı kıyıyı ve 

Ayak ucumuzda uyuyan kenti.

Anıların biri bu; 

Ötekisi gülüşün

Penceresiz bir odada, bir

Keşiş odasında, 

Nag Hammadi Kitaplığı Yazmaları''nı

Okurken gecenin ikisinde.', 'Bir gece, balkonda sevişmiştik. Ay, bulutlar, yıldızlar,  Geçen bir uçağın ışıkları Yansımıştı gövdelerimizde;  Aydınlanmıştı gece,  Bir nab...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/caliskan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünüm', 'gorunum-guven-turan-c26ni', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu çılgın geometrisi

Bir çocuğun rastgele dizip

Dağıttığı

Eski püskü küplerin

Yığını üst üste

Üst üste binmiş karanlık

Üzerlerine sıvaşmış ışık

Damlalarıyla

Geceyi bile ağırlaştıran

Kent', 'Bu çılgın geometrisi Bir çocuğun rastgele dizip Dağıttığı Eski püskü küplerin Yığını üst üste Üst üste binmiş karanlık Üzerlerine sıvaşmış ı...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gorunum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırlent', 'kirlent-guven-turan-4u0p4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kokularıyla Mayıs

Ve sesleriyle öğle sonraları

Akşamla... Akşam: 

Ketenler ve baharlar

Sıcak ve soğuk

Yağmurlu bir ışık

Grinin aydınlığı

Kırlangıç göğsünde', 'Kokularıyla Mayıs Ve sesleriyle öğle sonraları Akşamla... Akşam:  Ketenler ve baharlar Sıcak ve soğuk Yağmurlu bir ışık Grinin aydınlığı Kır...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kirlent-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış ve Düş', 'kis-ve-dus-guven-turan-52rc7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ocağı yakıp küle

Bir patates gömüyorum; 

Çocukluğumu diriltmeye...

Şaşıyorum, 

Donmuş çamaşırların

Hiç su bırakmadan

Çözülmesine; 

Kar getirmesine

Güneşin.

Yeniden

Kuş peşine de düşebilirim, 

Belki de.', 'Ocağı yakıp küle Bir patates gömüyorum;  Çocukluğumu diriltmeye... Şaşıyorum,  Donmuş çamaşırların Hiç su bırakmadan Çözülmesine;  Kar getir...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kis-ve-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Hasat', 'kutlu-hasat-guven-turan-dtkiz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ölü bir denizleyin, hani o, 

kargaların uysal hasatlarında, 

şaşkınlığı, saçması, ovalar, ya da

sisi çökmüş göklerin rıhtımlarından, 

sanrılı türkülerin intihar

dallarından kırılmış bir salıncak.

üşümüş, denizleyin yalnızlığı

sorandır hep, hangi kaldırımlar

boğaların ürktüğü çürük

yüzlerinde ekmekler taşıyanlar? 

hep günlerin burçları kamçılı

boğulan kadırganın kanadı', 'ölü bir denizleyin, hani o,  kargaların uysal hasatlarında,  şaşkınlığı, saçması, ovalar, ya da sisi çökmüş göklerin rıhtımlarından,  sanrıl...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kutlu-hasat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesel', 'mesel-guven-turan-3ef9t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlkyaz güneşi gebe bırakıyor

Dokunduğu yeri

Yeni açmış bir çiçeğin üstünde

Yeni peydahladı

Kitaplara bile adı geçmemiş

Böceği

Şimdi elimin üstünde

Yeni bir el nakışlıyor

Ağzın

İnce bir su akıyor

Hızla çitler arasında

Derin

Sürükleyip götürüyor

Ne çıktıysa önüne

Kıssadan hissesi yok

Bu meselin de.', 'İlkyaz güneşi gebe bırakıyor Dokunduğu yeri Yeni açmış bir çiçeğin üstünde Yeni peydahladı Kitaplara bile adı geçmemiş Böceği Şimdi elimin ü...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mesel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarraf', 'sarraf-guven-turan-nf0qf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eski mezarlıklar

Üç dinin tapınaklarıyla

Yaşıyor şehir

Kendini aldatıyor takvimlerle

Oyalanıyor yenilediğini sanarak

Yüreğini

Bir düşte binlerce yıldan beri

Esvap değiştiriyor durmadan

Çıkmıyor odasından

Habersiz değil gene de

Olup bitenlerden

Lodos ayıklıyor

Boğaz meyhanelerinden çekilen

Balıkları biliyor

Soluğu daralıyor

Yeni semt adlarını saydıklarında

Gelip gideni eksik değil hala

Geceleri

Nicedir kaç yaşında gösterdiğini

Soruyor bana', 'Eski mezarlıklar Üç dinin tapınaklarıyla Yaşıyor şehir Kendini aldatıyor takvimlerle Oyalanıyor yenilediğini sanarak Yüreğini Bir düşte binl...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sarraf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyran', 'seyran-guven-turan-ggltl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neler devşirmedim

O hercai gözden

Bol şimşekli gök gürültülü

Sağanakların ardından

Gökkuşağı ayçalı sabahlar mı

Başlamadı

Uzak sevişmeler mi düşlemedim

Yanımda uyuyan bir kadından

Umarsız bir sürgün

Diye mi adlandırmadım kendimi

Yine bir yaşam coşkusunun

Hışmına uğramışken

Bir başka Eylülde şimdi

Diken diken bir mevsim

Sürüklenmekte', 'Neler devşirmedim O hercai gözden Bol şimşekli gök gürültülü Sağanakların ardından Gökkuşağı ayçalı sabahlar mı Başlamadı Uzak sevişmeler mi...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seyran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınama', 'sinama-guven-turan-ycy7p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ekim yarıladı; 

Güneş bir gövde sıcaklığıyla

Sarılıyor.

Çamur içinde akıyor ırmak; 

Belli belirsiz aktığı.

''Sabah kuzeyden güneye

Akşam güneyden kuzeye akar.

Serttir, ''

Dedi.

Yaşlıydı, yüzü

İçine kaçmıştı.

''Bu ağacı ben dikmiştim.

Kestiler...''

Hiç sürgün vermemişti

Oturduğu omaca.

''Şimdi nasıl akıyor? ''

Kıpırtısızdı güz.

Beynim, yüreğim oradaydı; 

Uzakta...

Gözlerim burada...

''Günün başında mıyız

Sonunda mı? '' diye yanıtladı.

Bakmadan bana.', 'Ekim yarıladı;  Güneş bir gövde sıcaklığıyla Sarılıyor. Çamur içinde akıyor ırmak;  Belli belirsiz aktığı. ''Sabah kuzeyden güneye Akşam güne...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sinama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşilden Kaçan', 'yesilden-kacan-guven-turan-r24pd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle sıkıdüzen

Döşemişler ki mermeri

Kuşkusuz

Yer kalmamış ağaca

Kentlerinde

Bir asma örtmüş

Avlularını belki

Belki şu küçük

Ortası delik, yuvarlak

Döşeme taşı

Çevreliyordu

Kibar, utangaç

Hafifmeşrep gene de

Bir nar ağacını', 'Öyle sıkıdüzen Döşemişler ki mermeri Kuşkusuz Yer kalmamış ağaca Kentlerinde Bir asma örtmüş Avlularını belki Belki şu küçük Ortası delik, y...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yesilden-kacan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustos Güzden Sayılır', 'agustos-guzden-sayilir-halim-safak-sdtv1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben bu acıyı eski bir caddeden alıp

ağustos eylül ekim bir güze bıraktım

ama savruldum sararmış yapraktım

kim bilir kimin ömrüne düştüm

yalnızca ölüm sarıydı van gogh’dan beri

upuzun ben o sarıya vardım

ölüm dedikçe yaşarım sandım olmadı

ömrümü güze bıraktım en büyük yalnızlık

yaşamaktı ki her şey sil baştan sarıya boyandı

ölüm hayatla çoktan yer değiştirdi

esme dedikçe rüzgar gövdemde dolandı durdu

çıkmaz bir sokakta anılar metruk

aşkları unuttum neydi hepsinin anlamı

hangi cadde yanıtlayabilir yalnız kalmanın sorusunu

dokunmadan kim kimi anlayabilir

ne zaman güz gelse kendime geçerim

yapraklarım dökülür sonra

toplayanım olmaz çöpçüler gelir süpürür

götürür elleri yapraklar içinde sarıdan

sarı dünya ölümü ifade eder yalnızca

hatırlanmayan arkadaşlıklardır

kimse bilmezse bilmesin güz ömrümün fotoğrafı

şipşak bir pastanede kaldıysa kaldı

mitingde kimselerin uğramadığı bir parkta

caddeden geçip giden son model taşıtların ışıklarında

bekleyenlerin gelmeyecek olduğu akşam

üstülerinde ben yapraklarımı toplarım

“ağustos yazdan sayılmaz caddede” anılar

sararıp solsun diye ömrümün arta kalanını

dağılırım caddede hezeyanlarım cebimde

taşıyacak hiçbir şeyim yok

ben bu ömrü bir acıdan aldım ama

güze bıraktım kendimin yalancısıyım

ağustos güzden sayılır eylül ekim

bıraktım bırakmasına ama savruldum ve öğrendim

pimi çekilmiş bir dünyada en büyük yalnızlıktır yaşamak!', 'ben bu acıyı eski bir caddeden alıp ağustos eylül ekim bir güze bıraktım ama savruldum sararmış yapraktım kim bilir kimin ömrüne düştüm yaln...', ARRAY['Türk Edebiyatı','Şiir','Halim Şafak']::text[], 8.5, '{"poet":"Halim Şafak","poet_slug":"halim-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/agustos-guzden-sayilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balkondan Aşağı Sarkmış Çocuğum', 'balkondan-asagi-sarkmis-cocugum-halim-safak-agtmg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerimi kapatıp yüzüne bakıyorum

yalnızca karanlığa dalıyorum olmazsa

birazdan gidip geleceğim içime

doğru fesleğenler uzanacak bıraksam

her şeyi anımsayacağım birden bire

mektubun gelmiş olacak sesin

gövdemde dolanacak ve bulacak

dokunduğun en yalnız yerlerimi

birbirine sürteceğim

sen yoksun acı kalıyor döndüğüm yerlerden geriye

gidip bütün fotoğraflarda yerimi alıyorum

siyah beyaz bir sokağın sonunda

beni kimse beklemiyor oluyor

olsun kimse beklemesin sen konuşursun uzaktan

uzağa çiçekleri sularsın olmazsa itaat

ettiğim hayatı sana bırakırım acıdan

kalan ne varsa yeniden yaşarız yaşamasına

ama arzularım beni her gün biraz daha

incitiyor durmaksızın kırılıyorum unufak

kanım içime akıyor sen varsan bundan sonra

yeterince tutarsız olurum hayatımda başıboş

dolaşırım evin odalarının hiç birinde uzun süre kalmam

duvarlardaki resim ve fotoğrafların önünde hiç durmam

geçer giderim mutfak tuvalet banyo oturma odası balkon

ama yoksun anılar ardımdan geliyor

üstüm başım bana benzemiyor yüzümü tanımıyorum

şimdi gidecek olsam dostlarım siyah acılar sunar gecenin

içinde bardaklar dolar boşalır üstüme her aşk

bende bir leke bırakır kimse çıkaramaz

büyür kocaman beni içine alır senden habersiz

her gece gözlerimi kapatarak yüzüne baktığımda; 

balkondan aşağı sarkmış çocuğum

düşer düşmez kendini kucaklayacak!', 'gözlerimi kapatıp yüzüne bakıyorum yalnızca karanlığa dalıyorum olmazsa birazdan gidip geleceğim içime doğru fesleğenler uzanacak bıraksam h...', ARRAY['Türk Edebiyatı','Şiir','Halim Şafak']::text[], 8.5, '{"poet":"Halim Şafak","poet_slug":"halim-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/balkondan-asagi-sarkmis-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birdenbire', 'birdenbire-halim-safak-r4pdx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yeni sulanmış fesleğen

desin ki gece

oyuklar bırakır içinde

küskü vurur daha derine

her yerine

kuş kafesinde öylece

desin ki sözcükler

güze bakan oda

masa anılar

toparlanmadı öylece bırakıldı

birdenbire pencere dışında

desin ki yangınlar

sessizce', 'yeni sulanmış fesleğen desin ki gece oyuklar bırakır içinde küskü vurur daha derine her yerine kuş kafesinde öylece desin ki sözcükler güze ...', ARRAY['Türk Edebiyatı','Şiir','Halim Şafak']::text[], 8.5, '{"poet":"Halim Şafak","poet_slug":"halim-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birdenbire-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarpışma', 'carpisma-halim-safak-a412v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ömrüm yalnızca ölüm haberleri

bekliyor telefon her çaldığında

yapraklar sararmaya başlıyor

sonra dökülüyor üstüme usulca

ölüm bir rüzgar ki savurdukça

savuruyor anıları oradan oraya

ölümden başkasını aklımda

tutmuyorum anımsadığım ne varsa

hepsi benden uzaklaşıyor solmuş

fotoğraflar ölüm ilanlarından taşıyor kimse

yetişemez artık kendine mezar açmaya

gücüm yetmiyor her şeyi birbirinin üstüne

aniden deviriyorum ömür

sessizlikle geçiştiriyor artakalan

acısını birikiyor hangi kente

gitsek susuyoruz aşk yalnızca

ayrılık değilse nedir

yalnızlıktan başka neyimiz kaldı

belediye hoparlörleri mektuplar

illa ki telefonlar her gün biraz daha

ömrümü biçiyor orta yerinden kanırtılmış

ağacın dalına benziyor her geçen gün

giritli recep ferdinaz asım kimlerse

gitseler dönmüş olurlardı şimdiye

kadar ne yaşadıysak hepsi illüzyon

ömür biteviye yaşamak kadar ölmektir

yoksa ben yalnızca acı mı demiştim.

artık ben yaşadığımı ancak ölümle biliyorum

bundan sonra her güz bir cinnet

çağında yaşamaya zorlanmaktır oysa

ben her gün kendimle çarpışıyorum

ve telefon her çaldığında ömrüm

yalnızca ölüm haberleri bekliyor

sanki sararmış yaprakları bir o toplayacak!', 'ömrüm yalnızca ölüm haberleri bekliyor telefon her çaldığında yapraklar sararmaya başlıyor sonra dökülüyor üstüme usulca ölüm bir rüzgar ki ...', ARRAY['Türk Edebiyatı','Şiir','Halim Şafak']::text[], 8.5, '{"poet":"Halim Şafak","poet_slug":"halim-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/carpisma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Geç Kaldım', 'cok-gec-kaldim-halim-safak-zxh97', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gece ağırlaşarak üstüme yıkılıyor

öldüm sanıyorum

beni bu saatte uyanık tutan şarkılar birazdan

odanın içinde yavaş yavaş kaybolup gidecek

puslu bir hava dört duvarı dolanıp

doğru çıkacak balkona

masada unutulmuş kitabın sayfaları hep açık

harfler sözcükler kendini tekrar ediyor

aynı dizeleri kurup duruyor durmadan

ölüm çıkıyor her şiirin üstünü kazıdığımda

omzumdan çocukluğum bana bakıyor

aklımda kalanları hatırlamaya çalışıyorum

geceleyin odam pencerelerini üstüme kapatıyor ne varsa

balkon kapısı çarpıp duruyor ömrüme

yabancı ne varsa dağılıyor odaya

ben bir tek hayatı anlamıyorum ölüm neyse

o da odur demeye nedense dilim varmıyor

terimi ıslak bir mendille siliyorum dünya

bundan sonra naklen bir savaştan başkası hiç değil

şiir geri çekiliyor harfleri dağılıyor alfabenin

hiçbiri yerli yerinde durmuyor her şey baştan

başa ölüm kokuyor üstüme fesleğen dalları atıyorum

destimin suyunu bu kez ben dolduruyorum

mezarımın bakacağı yönü belirliyorum

her şey üst üste yığılsın dursun

ne çıkar bundan

birini aramadıysam adını anmadıysam

mektup yazmadıysam telefon açmadıysam güz

muhitimize çoktan gelmiştir ve hiçbir zaman gitmez

sararmış bir hayatı dökülürcesine yaşadım durdum

yaşadığım kent her geçen gün daha fazla mezarlığa benzedi

apartmanlar mezar taşı balkonlar çok oldu

çiçek saksıları yıllar var ki sulanmadı ben anladım

ölüm gitsin diye hayata seferler düzenledim

gecenin en derin yerine kendimi bıraktım

kimse çıkarmadı

geriye ölümden başka ne kaldı

bu soruyu sormak için çok geç kaldım

çok geç kaldım bundan epeyidir benim bile haberim yok!', 'gece ağırlaşarak üstüme yıkılıyor öldüm sanıyorum beni bu saatte uyanık tutan şarkılar birazdan odanın içinde yavaş yavaş kaybolup gidecek p...', ARRAY['Türk Edebiyatı','Şiir','Halim Şafak']::text[], 8.5, '{"poet":"Halim Şafak","poet_slug":"halim-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/cok-gec-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ev Hali', 'ev-hali-halim-safak-rla8e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'senin bildiğin güz bir ev hali

ruhunu her yerinden oyuyor yaprakların

dalından kopup düşüyor yatağının ortasına

sen orda yuvarlanıp durursun önce

okuduğun kitaplar eskir elinde sonra

unutursun kapını bir başkasına açmayı

ne yapsan giydiğin her şey siyaha keser ne olursa

olsun ömrün hep ayrılığı öğütler sana

durmadan yalnızlığını yineler yüzüne karşı

sarıdır yılın on iki ayı sana güzdür mütemadiyen

siyaha döndürürsün örtünmek için karanlığını

kimseyi anlamazsın seni kimse anlamaz

odalar yalnız bırakır sokaklar desen öyle

yaşamak dediğin şey artık büyük bir vesvese

başka neyin acısı kalabilir ki insana

ve ''derin kesiği'' kim kime nasıl anlatır

fesleğen nasılsa kuruyacak

güz neresinden baksan sararmış

yapraklar kadar içine dolmuş ne yapsan yazın

yerini tutmaz çünkü bütün pankartlar inmiştir

sessizlik külünk gibi en derinine senin

bildiğin güz bir ev hali belki bilmediğin neydi kim bilir!', 'senin bildiğin güz bir ev hali ruhunu her yerinden oyuyor yaprakların dalından kopup düşüyor yatağının ortasına sen orda yuvarlanıp durursun...', ARRAY['Türk Edebiyatı','Şiir','Halim Şafak']::text[], 8.5, '{"poet":"Halim Şafak","poet_slug":"halim-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ev-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fesleğen Ömrü', 'feslegen-omru-halim-safak-o8n1o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'masayı toplamıyor da

dağıtır gibi yapıyoruz

her şey nasıl bırakılmışsa

öyle hatırlıyor kendini

insan boğulacak kadar

bilir yüzmeyi

suyu şişesine dolduruyoruz

ömrümüzün bir duldası bile yok

ne duvar gibiyiz

ne de taraçayız denize bakan

aşk her şeyi suskunluğa vermenin adıymış

ruhumuz nasılsa kuruyacak su birikintisi

yağmuruz ıslanmışız kendimizi öpüyoruz

ölüm hayatta olduğunu sanmaktan başka ne

adres defterleri saklanmış mektuplar

ayrılık demekmiş sığındığımız oda

biz ki hiçbir çiçeği incitmeden

tutamadık elimizde

ne kadarsa bir fesleğen ömrü

yaşadık ve öldük

yaşadık ve öldük', 'masayı toplamıyor da dağıtır gibi yapıyoruz her şey nasıl bırakılmışsa öyle hatırlıyor kendini insan boğulacak kadar bilir yüzmeyi suyu şişe...', ARRAY['Türk Edebiyatı','Şiir','Halim Şafak']::text[], 8.5, '{"poet":"Halim Şafak","poet_slug":"halim-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/feslegen-omru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşım Mavi', 'arkadasim-mavi-engin-turgut-9rjiw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'babil''in eskimeyen diliyle yıkansak seninle

inceliğimizi giyinsek, dayansak arkadaşlığın kapısına

gündüzün ısrarıyla geceyi yorgun düşürsek

eski bir lezzetti günah

kederli bir serçeydi kalbimizin ötüşü

zaman annesizdi, unutmadık masallardaki

o çocuğun masmavi bakan gözlerini

kokumuzdan şarap yaptılar, unutmadık onyedi ağustosu

kolu kanadı kırık bir sandalın deniz diye diye inlediğini

güneş kibirliydi, su dalgın, ruhumuz kilitli

gül kustuk, hasta yatağından uyandırdık ıssız rüyalarımızı

ağaçlar yağmura acıkırdı, üzgün bir evdi sessizliğimiz

süt kokardı dualarımız

bulutlarını bana bağışla, ellerinin ışığını göster

bu deli ve ıslak yüzümüz adamı öldürür

uçurur beni iyiliğin koynunda beslediğin yaz

beli ince bir rüzgarın boşluğuna dolandı yaralarımız

ah, doğunun o sıcak kalbiyle sarıldık birbirimize...', 'babil''in eskimeyen diliyle yıkansak seninle inceliğimizi giyinsek, dayansak arkadaşlığın kapısına gündüzün ısrarıyla geceyi yorgun düşürsek ...', ARRAY['Türk Edebiyatı','Şiir','Engin Turgut']::text[], 8.5, '{"poet":"Engin Turgut","poet_slug":"engin-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/arkadasim-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkasının Kuğusu', 'baskasinin-kugusu-engin-turgut-zzh21', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siz benim meleklerimden daha saydamsınız, 

kirlenmeyen bir tek arzumuz kaldıysa

bağışlayın! rüzgarımızın arasına kibirden

bir cümle, yanlış bir hayal girmesin diye

sabahtan akşama kadar yalnızlığımı

sulara çarpıyorum! 

İçimde hep bir hançer sıkıntısı var

her yanım delik deşik, bir köpek gibi

havlıyorum durmadan, birbirimizi bir

daha görsek boğulacağız, nefesini içime

dök, başım dönüyor bahçenizin nazından, 

ruhumu ısırıyorum! ..

aşk için deniz susuyor, yaprak titriyoruz

aşk için kelimelerden sihir yapıyoruz

yağmurun sokağında çocuk oluyoruz

dünyanın küçük ve güzel huylarını kapıyoruz

arkadaşlığın gövdesini sütümüze banıyoruz

gül parlatıyor, keder yontuyoruz

zamanın çıtı çıkmıyor, iştah sızıyor ışığımızdan

kanımız çalışkan, çıkarın şu yabancıyı aramızdan

siz benim aşktaki dalgınlığımı anlamadınız, 

gururunuz, içinizde fenalık biriken çıkmaz

bir taşraydı! başkası birimize hep fazlaydı! 

size her gün zarfsız mektuplar yazar, 

gönderemediğim için pula dönerdim! siz

acı bir şarap, zalim bir bahane, başkasının

kuğusu değil miydiniz? 

bakın şuranızdan uslanmayan hevesim geçiyor

çılgınlık işte! ateşinizle oynuyorum! ..', 'Siz benim meleklerimden daha saydamsınız,  kirlenmeyen bir tek arzumuz kaldıysa bağışlayın! rüzgarımızın arasına kibirden bir cümle, yanlış ...', ARRAY['Türk Edebiyatı','Şiir','Engin Turgut']::text[], 8.5, '{"poet":"Engin Turgut","poet_slug":"engin-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/baskasinin-kugusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buselik', 'buselik-engin-turgut-1ljug', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok içtim gamzesinden şarabın

ay tutulması yüzüne söz verdim.

Sonbahar eğilimli sokaklardan sana çıktım

kalbim şarkılarda kaldı, içime yalnızca seni aldım.

Kendimi sana ayırdım, beyaz güllere öykündüm

güzelliğin sende kalsın, sana çok çalışkanım.

Bana benzemem kolay olmadı, bileklerim gerilir

kalbim dağılır, seni nasıl sevmem, hayat delirir.

Seninle canlara gidelim, içim canına sarhoş

bir tenha kuşuyum sana ben, ölürüm kalbinden düşersem.', 'Çok içtim gamzesinden şarabın ay tutulması yüzüne söz verdim. Sonbahar eğilimli sokaklardan sana çıktım kalbim şarkılarda kaldı, içime yalnı...', ARRAY['Türk Edebiyatı','Şiir','Engin Turgut']::text[], 8.5, '{"poet":"Engin Turgut","poet_slug":"engin-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/buselik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçın', 'kacin-engin-turgut-hmspl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'o çocuğun gözleri ağzımdan akıyor

meleklerin nefesi süt kokmuyor artık! 

bilmeseniz de olur, dağların göllere aktığını

kaderimden kaçın! ..

aşk sokağında herkes büyüdü, ben kaldım

siz eskimeyen bir zamandınız, anladım

nice hayatlar kırıldı, boynumuz üzgün

çığlığımdan kaçın! ..

burası mavi kasaba, burası siyah kahır! 

her şey kalpte başlar, kalpte biterdi

ah, ne bitmez vesveseymiş bu

ışığımdan kaçın! ..

ipeğe dokundum, esridim, yanıldım! 

ben sizi öbür çarşıdan tanıyor muydum

panik yok! umulmayanı ummak mevsimindeyiz

hayallerimden kaçın! ..

ölümden daha genç bir hakikat var mıdır? 

saadet kırılgan, umut kahpe, aziz bir şey kalmış mıdır? 

dönüp nereye baksam, yalnızlık oluyorum

korkularımdan kaçın! ..

bu şehrin sıkıntısı, vedalara benziyor

kimse yok karanlıktan başka, evler ansızın yırtılıyor

herkesin mektubu yolda kaldı, dünya hepimizi yalnız bıraktı

her şey yarım, hayat önümüze çıktı, kaçın! ..', 'o çocuğun gözleri ağzımdan akıyor meleklerin nefesi süt kokmuyor artık!  bilmeseniz de olur, dağların göllere aktığını kaderimden kaçın! .. ...', ARRAY['Türk Edebiyatı','Şiir','Engin Turgut']::text[], 8.5, '{"poet":"Engin Turgut","poet_slug":"engin-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kacin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmıştır', 'kalmistir-engin-turgut-nkakx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'siz kederin gözlerine sığmazsınız

yazgıdan yumuşak bir şey kalmıştır

hangi kalp bir mektuba sığmıştır

dünya nafile, oyun dışarıda kalmıştır

bu yüzleri aynalarda bulamazsınız

kapılar kapanır, anlam sizde kalmıştır

o bildiğiniz sancı gelir, yalnızlığa dalarsınız

şarkısı ıssız, kalbi kırık bir hasret kalmıştır

rüzgar böyledir, ışık ısırır, anlamazsınız

geceden yorgun ipekten ince bir yol kalmıştır

mazi böyledir, yeni hatıralar yaratırsınız

rüyalar kemirir yazları, susmanın hançeri kalmıştır

sevişmek böyledir, yaraya tuz basarsınız

deniz de biter, size kum bana çakıl kalmıştır

sonbahar böyledir işte, saçlarınızı yağmur sanırsınız

şarabın sözleri sonsuz size gitmek kalmıştır

yazlar böyledir, gecenin mürekkebine dağılırsınız

renkler yorgun, pastel dalgın kalmıştır

incelikler böyledir, sessizliğinizi bırakırsınız

kelimeler susuz, yokluğun gölgesi kalmıştır

anların muhteşem derinliğine bağlanırsınız

elinizde kala kala hayalleriniz kalmıştır

hayat böyledir işte, düştüğü yeri acıtır

aşk, adresinde yoktur, sesinizde veda kalmıştır...', 'siz kederin gözlerine sığmazsınız yazgıdan yumuşak bir şey kalmıştır hangi kalp bir mektuba sığmıştır dünya nafile, oyun dışarıda kalmıştır ...', ARRAY['Türk Edebiyatı','Şiir','Engin Turgut']::text[], 8.5, '{"poet":"Engin Turgut","poet_slug":"engin-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kalmistir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Herkese Yağmaz', 'yagmur-herkese-yagmaz-engin-turgut-8t6u0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eski anne, eski çocuk, eski kumrallığımızdı

kendimize sarılırdık

Sokaklara sarkardık, küçücük şeylerle

dalgındık, birden uzardı kırılganlığımız...

Yırtılmazdı hayallerimiz

Kalbimiz yosun tutmazdı

Her şeyi hesapsız ve çılgın yaşayan

sezgi çocuklarıydık...

Senden başka gemi görmedim bizi bırakıp giden

Senden başka güvercin görmedim, içimizde patlayan

Eskimeyen zarif bir yalnızlığa geri dönüyorsam

Maskesiz bir rüyayım artık, ayırmayın beni kendimden

Geçemezsin kalbimin kederinden, 

Aşk, beni kandıramazsın

Geçemezsin yağmurun derdinden...', 'Eski anne, eski çocuk, eski kumrallığımızdı kendimize sarılırdık Sokaklara sarkardık, küçücük şeylerle dalgındık, birden uzardı kırılganlığı...', ARRAY['Türk Edebiyatı','Şiir','Engin Turgut']::text[], 8.5, '{"poet":"Engin Turgut","poet_slug":"engin-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yagmur-herkese-yagmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşsız Yabancı', 'yassiz-yabanci-engin-turgut-l52yw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kardeşiyim ağaçların, ırmakların ve taşta uyuyan yalnızlığın

korkular çağında sürgüne yem oldum, sanki gurbet yaşındayım

ruhum kırık, ruhum dalgın, ruhum isyan

ay içer, güneş yerim, sanki ölüm yaşındayım

rüyacı buldu beni, çöl adam yaptı beni

mor bir kuyu bu şehir, kendime çıkmak yaşındayım

mavi bir gündüzdüm eskiden, şimdi gecelerin karnındayım

nar suyuyla yıkandım da büyüdüm, artık vedalar yaşındayım

doldum taştım bu viranede, sanki can lokmasıyım

şarabımdan sarhoş oldu derya kuşları, sanki uçmak yaşındayım

gül ve hüzün aynı şey değil de nedir, ikisi de fazla duman

gitmek duman, kalmak duman, güzel bakan kadınların yaşındayım

yazların kalbinde dağıldım, çocukların gözleriyle şaşırdım

tenimin içinde saklandım, her şeyi hatırlamak yaşındayım

son hamlede anladım, dünya bir ceset, sanki anılar hurdası

sizin siyahınız çifte kavrulmuş, unutmak ve bağışlamak yaşındayım

bende uzak olanın, akan suların görgüsü var

hem mağrur hem kalenderim, sesime saplanan yıldızların yaşındayım

ağrıyan yerlerime suçlarınızı bırakıp kayboldunuz

yüzünüzü ben uydurmuştum, kış renkli bir orman yaşındayım

nerede olsa tanırım ömrümün beyaz kokusunu

ışıktan bir canım var, ısırılmış bir elmanın yaşındayım

susmayan bir hasret edindim kendime, doğudan koparılmış

acıyor gövdemin uykusuzluğu, aşık kalmak yaşındayım...', 'kardeşiyim ağaçların, ırmakların ve taşta uyuyan yalnızlığın korkular çağında sürgüne yem oldum, sanki gurbet yaşındayım ruhum kırık, ruhum ...', ARRAY['Türk Edebiyatı','Şiir','Engin Turgut']::text[], 8.5, '{"poet":"Engin Turgut","poet_slug":"engin-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yassiz-yabanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Kollarımda Öldü', 'yaz-kollarimda-oldu-engin-turgut-xlcnz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mektubumu açmayın

ırmaklarım dökülür

gecenin bacaklarını tutar mısın

bulutlarım üşüyor

şu gövdemi açar mısın

bak mavilerim susadı

keşke böyle uçmasaydın

dağlarında kar göründü

beni tenine kilitle

bana dumanından getir

dalgınlığımın tadını çıkar

kokunu üzerime sapla

uçların sonsuz git git bitmiyorsun

zamanı katlayıp cebime koydum

lirik bir mucizesin

aşkın da karnı acıkır

yabancısı değilsin saflığın

hakikat kadar derindesin

nemli bir akşamsın ah o mana

ıslığın başını döndürensin

hadi bana kuytularını göster

uzaklığını ben tutarım

ışığını çözme boşluğum acır

sesinde kaybolurum

beni ateşine sürgüle

suyumdan ısır

sözcüklerim kaygandı

beyazdı ağzımın kuşları

şehla yerlerine dokunuyorum

öpüldükçe melek oluyorsun

eskimiyor sendeki tenha

yağmurun kalbini sevindiriyorsun

gözlerin denizdendi

yüzünde gül yüzdürüyordum

mistik bir şehirdi gövdem

ruhumun teğelleri söküldü

oralarında kaybolurdum

boynumuz ıssız bir köydü

kalbimi sana ayırdım

soy beni elmalarım büyüdü

ah şimdi sen yoksun

yaz kollarımda öldü! ..', 'mektubumu açmayın ırmaklarım dökülür gecenin bacaklarını tutar mısın bulutlarım üşüyor şu gövdemi açar mısın bak mavilerim susadı keşke böyl...', ARRAY['Türk Edebiyatı','Şiir','Engin Turgut']::text[], 8.5, '{"poet":"Engin Turgut","poet_slug":"engin-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yaz-kollarimda-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahliye', 'tahliye-emirhan-oguz-owbhx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Martılar çığlıklarla geçtiler

bunlar ritsos''un - martıları dedim

hayır, bunlar benim martılarım - dedi

Bir dost şubat''ta çıkacakmış - dedim: anımsadın mı, hani bir kurşun

kurşunların erişemediği gizli bir ufku vardır diyen...

Anımsadım - dedi: elleri midye kesiği, ayak bileklerinde mavi diken

ve saçlarında yosun lifleri vardı; dizkapağında, soğuyan kurşun

Nasıldır içerden çıkmak - dedim: ilk adımın kara değmesi

toprak çok mu farklıdır eskisinden, nasıldır rüzgarın sesi...

İncecik bir kar tanesinin karanlıkta ışımasına benzer - dedi

sevgisizliğe karşı direnebilmektedir yaşamın öz türkçesi

Çok sürmez, sen de gideceksin - dedim: kente kar düşerken, akşam üzeri belki

defterde yarım kalır şiir; bir de pencerede, yaz''dır kuruyan kayısı çekirdeği...

Gideceğim - dedi: evet, belki karlı bir gün, gelip son kez mazgaldan

elini sıkacağım, gözlerimde kardeşliğin dil vermez lehçesi

O zaman hoşçakal - dedim: unutma, hava kararırken seninle bir gün

kızıl saçlı bir çocuğun martılarından söz ettiğimizi...

Demirörgünün üstünde gökkafes; unutmam onlar ordalar - dedi

dostlar göz erimi uzakta, emek kendi yurdunda sürgün

Martılar çığlıklarla geçtiler

bunlar kimin martıları - dedim

bunlar senin martıların - dedi', 'Martılar çığlıklarla geçtiler bunlar ritsos''un - martıları dedim hayır, bunlar benim martılarım - dedi Bir dost şubat''ta çıkacakmış - dedim:...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Oğuz']::text[], 8.5, '{"poet":"Emirhan Oğuz","poet_slug":"emirhan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tahliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kimin?', 'deniz-kimin-halil-gokhan-dbyqs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-I-

taşıldır su: ağırdır, yol yorgunu ve zahmet içindedir

ermiş bir yelken takılır açılmaz kulaçlarına

deniz serindir: bizim teknelerimiz var oysa

çölün kalçasından bir borda

kıçsız bir tekne, sağrısı insan derisiyle kaplı

kitaplar yazmıyor bunu, deniz sizindir

-II-

taştı su: ama gördüm yarılan denizleri de

susuz ama suya çalan yüzleri

ağrıyı andıran yurdumun serap ektiğin seferlerini

gördüm, ama topladım bakışlarımı

denizin bekletildiği bir kan çanağının içinde

ama başka kaplardan bekliyordum ben

gece ele geçen ve şafakla batan suları

bir ülkenin bütün manzaralarının üstüne

-III-

yaralıyım: hiç kimse yarasız olduğumu söylemeye yanaşmıyor

bu yara ve onun bilinen kardeşleri

aynı gövdeden aldılar kanayan deriyi

aynı sularda göründüler, üç sularında örneğin

-IV-

ben de o saatlerde geçtim şehri

ve arkamda bir geçmiş bıraktım sürmekte olan

içi dışı gibi, kirlilik toplayan bir deniz

ve geometriden daha saf bir coğrafya

-V-

sordun diye söylüyorum. deniz kimin? 

şenlik olduğu söyleniyor denizle akraba çıkmanın

onun ana olduğunu da çıkarmışlar: bir mesafe kantarı söylüyor', '-I- taşıldır su: ağırdır, yol yorgunu ve zahmet içindedir ermiş bir yelken takılır açılmaz kulaçlarına deniz serindir: bizim teknelerimiz va...', ARRAY['Türk Edebiyatı','Şiir','Halil Gökhan']::text[], 8.5, '{"poet":"Halil Gökhan","poet_slug":"halil-gokhan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/deniz-kimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırıncının Makası', 'firincinin-makasi-halil-gokhan-q8lh0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülerken dudakları çatlıyor.

Soğuk hava gibi gülüyor da ondan.

Kapılar açılmamış ama geçmişti o.

Zildeki isimden girdi içeri.

İsim onu tanıdı.

Zile dokunan parmağından...

Başka yöne bakıyordu dikiz camı.

Kaçıncı kata çıktığını bilmiyor, 

çünkü kum üstünde yürür gibi inanıyor verilen adrese.

Bir şey taşıyor. Ne taşıdığını bilmemenin

hafifliğiyle dolu bu şeyin oluşturduğu hacimde bir suç barınıyor.

Bu suçun ortaklığı mutlak yalnızlık.

Deniz de yardım etti. Deniz ne açabilirse önüne...

Kum talaşı, balıkların gölgesi, sandalların kalbi, 

iskele ve kanıtlanmış fakirlik.

Denizin belgesi, her sabah ufka doğru yuvarlanan cisimlerin silueti.

Avlanan adamlar. Yoketme isteği, yoketme içgüdüsünden önce öldü...

Saldırın, diyemiyor çünkü gülerken dudakları çatlıyor.

Yokederken gülmek ne acı...

Surat asabilseydi soğuk havada elbette daha becerikli sayardı kendini...

Yapabildiği sadece bir makasa iki parmağını geçirmek

ve suyu kesmenin soğuk mimarisi...

Üst kattan fırına inerken dudakları çatlıyor.

Onu kimse görmedi, çünkü bir kumda yürür gibi

inandı ekmeksizliğe. Açlar yalancıdır.

Bütün müşteriler ya toktur ya yarı doymuştur ya da göz oburudur.

Bütün fırıncılar misafir, müşteriler makasın gerçek sahipleri...

Su akıyor bir pencereden, kumlar odanın içinde, gülmek önemli bir suç.', 'Gülerken dudakları çatlıyor. Soğuk hava gibi gülüyor da ondan. Kapılar açılmamış ama geçmişti o. Zildeki isimden girdi içeri. İsim onu tanıd...', ARRAY['Türk Edebiyatı','Şiir','Halil Gökhan']::text[], 8.5, '{"poet":"Halil Gökhan","poet_slug":"halil-gokhan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/firincinin-makasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı', 'zamani-halil-gokhan-uleel', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ya gelmeli ya çıkmalı bir yerlerden

gideceğim hiçbir yolda mesafe yok

sabahları ağaç gövdelerine kazınmış görünce gölgemi diyorum: 

zamanı

geç kaldık ama galiba geceleri dolaşınca bulunan bir şehre gidecektik

hepimiz bir menzil sohbetine aldanıyor ama konuşmuyorduk

kervanlarımız yollarımızdan çıkarılmıştı; demiştim ki bunun üzerine: 

zamanı

her yerde tıkanmış bir kalabalığın izi var

uğramadığı kıyıların yalnızlıklarından oluşan

bir liman geçtiyse az önce anlaşıldı: kalabalık

zamanı

taş üstünde kaya, gönül üstünde göz; ama gök yırtılmamış

anıtlardan, kitaplardan, tabletlerden herkesin yazısı öylesine geçmiş

geçiş yerlerinde sadece sıfatları yurt tutmuşlar; ama bilmezlerdi kimin, neyin

zamanı

gökyüzü bir ev hastalığı geçirdi; sıkıntı, bir buyruk sandı kendini, bir yanlış anlaşılma

yemek salonları bir kara treni arzuladı

yokuş bir ten istedi kimsenin ezmediği, bekleyenin kalmadı

zamanı

bir şey söylemek isteyince konuşur

bir şey anlatmak isteyince susardı; yürüdü gitti, kulakların bir sözlükte, 

dilin bir gözde oturduğunu anladığı gün; alıp yanına, kalan

zamanı

..................

şimdi bir ev var bütün yüreklerin olduğu yerde

herkes mutluluğu gençken istedi, mutsuzluğu 

ve ruhunu sattı kırılmak yerine; ayrılık bu yüzden ölmek

zamanı', 'ya gelmeli ya çıkmalı bir yerlerden gideceğim hiçbir yolda mesafe yok sabahları ağaç gövdelerine kazınmış görünce gölgemi diyorum:  zamanı g...', ARRAY['Türk Edebiyatı','Şiir','Halil Gökhan']::text[], 8.5, '{"poet":"Halil Gökhan","poet_slug":"halil-gokhan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Olmasaydı', 'ask-olmasaydi-feriha-altiok-9gv9a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk olmasaydı

ne çarpardı böyle

bu bahar

ne böyle kokardı

çiçeğinde portakal', 'Aşk olmasaydı ne çarpardı böyle bu bahar ne böyle kokardı çiçeğinde portakal...', ARRAY['Türk Edebiyatı','Şiir','Feriha Altıok']::text[], 8.5, '{"poet":"Feriha Altıok","poet_slug":"feriha-altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-olmasaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hele Bir Düşün', 'hele-bir-dusun-feriha-altiok-w0687', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bıçak sırtı bir yolda yürüyorum

tutunarak yılgılara

ve şaşkınım güz göğünde bir kırlangıç kadar

sürülürken paralelime hep özlemlerim

yağlı urganların gölgesindendir

başımı eğikliğim

ve bu yüzden dağlıyor gözlerimi

kendi alazıyla yüreğim

ey sığmayan dünyalara

yeni boyutları zorlayan çağım

yüzyıllardan beri yoldayım

nicedir de kapını çalmaktayım

omuzumda en ağır yükün

hele bir yokla uygarlığını

hele bir düşün', 'Bıçak sırtı bir yolda yürüyorum tutunarak yılgılara ve şaşkınım güz göğünde bir kırlangıç kadar sürülürken paralelime hep özlemlerim yağlı u...', ARRAY['Türk Edebiyatı','Şiir','Feriha Altıok']::text[], 8.5, '{"poet":"Feriha Altıok","poet_slug":"feriha-altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hele-bir-dusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-hakan-savli-b70i6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İpek bir girdap

Sis bir labirent

İşlemeli kalb şeklinde küçük bir yastık

Ya da

Mor bir pelerindi yalnızlık

O zamanlar

İçinde yaşardım hiç farketmeden

Sarı bir kederin dalgınlığında

Ve bilmem neden

Dönüp dolaşıp

Kiliselere

Giderdim ağlamaya

Loş bir köşede yanan

Mum ışığında simli

Anılardı yalnızlık

Dantel acılar

Elimde verdiğin o resimli mendil

Derken bir düt

Usulca başlar

Düşlerimle org arasında

Bir aşk başlardı bach''ın acılarından

Takılırdı vitrayların dudaklarında

Buğulu bir ırmak karlar içinde

Çocuklar gülümserken uykularında

Sanki bir peruk

Nasıl desem: yazseli...

Gözyaşlarından

Şeffaf bir mektup

Bir ova dolusu ölü beyaz kanguru

Süngülenip yırtılmış keselerinden

Ağlara takılan genç insan ölüleri

İstiridyenin içinde eski

Doğulu bir öykü

Ya da gizli bir

Balerindi yalnızlık

Kapardım gözlerimi

Kış güneşi vururken tomurcuklara

Anlardım tutunca bir an elimi İsa

Buluşup ayrıldıkça içimdeki beyazla

Süslerdim yollarını

Sim sinen dakikalar

Karanlıkta konuşurdum içimden

Açılırdı masalların çekmeceleri

Org susar

Sessizce

Alkışlardı ölü arkadaşlar.', 'İpek bir girdap Sis bir labirent İşlemeli kalb şeklinde küçük bir yastık Ya da Mor bir pelerindi yalnızlık O zamanlar İçinde yaşardım hiç fa...', ARRAY['Türk Edebiyatı','Şiir','Hakan Savlı']::text[], 8.5, '{"poet":"Hakan Savlı","poet_slug":"hakan-savli","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/yalnizlik-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çamaşır Sepeti', 'camasir-sepeti-halil-i-brahim-ozcan-a7m0q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sabahlayan hırsızın mutluluğu

çıkmak ve girmek olunca usula

ürkek bir gül dalgalanır deli - divane

zamanın sırrında yıkar gökkuşağını

dergahta sevişilir alışkanlıklarla

sulara sızar gün kararır', 'sabahlayan hırsızın mutluluğu çıkmak ve girmek olunca usula ürkek bir gül dalgalanır deli - divane zamanın sırrında yıkar gökkuşağını dergah...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özcan']::text[], 8.5, '{"poet":"Halil İbrahim Özcan","poet_slug":"halil-i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/camasir-sepeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giz', 'giz-ahmet-telli-e0fd7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kadar uzak mıydı

git git bitmiyor yol

görünmüyor dağın ardı

Oysa bilmem kaç yıl

bu yollardan yürünmüş

Şimdi sanki bir masal

Bu dilsiz dağ ve taş

nerde saklar kuşları

hangi gizle sarmaşdolaş

Anlamak zor susuşları', 'Bu kadar uzak mıydı git git bitmiyor yol görünmüyor dağın ardı Oysa bilmem kaç yıl bu yollardan yürünmüş Şimdi sanki bir masal Bu dilsiz dağ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/giz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir ve Yaşam', 'siir-ve-yasam-ahmet-telli-wc2mi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-I-

Yaşananı aşan sevda yorumu

Şiirn kanıyla yoğrulmamışsa

Gülün hevengini coşturan bengisu

Verilmemiştir çeliğin damarına

-II-

Şiirden söz açılınca

Diyor ki bana konuğum

- Başka söze gerek yok

Aşktır onun tarihçesi', '-I- Yaşananı aşan sevda yorumu Şiirn kanıyla yoğrulmamışsa Gülün hevengini coşturan bengisu Verilmemiştir çeliğin damarına -II- Şiirden söz ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/siir-ve-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adanmış Olan', 'adanmis-olan-ali-riza-ertan-21ot7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tez savrul dostum, kümelen

Şafağı erit, günü tazele

Yorgun kapısına dikil akşamın

Hesap sor alnındaki birikmiş terle

Ey adanmış olanla gelen', 'Tez savrul dostum, kümelen Şafağı erit, günü tazele Yorgun kapısına dikil akşamın Hesap sor alnındaki birikmiş terle Ey adanmış olanla gelen...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ertan']::text[], 8.5, '{"poet":"Ali Rıza Ertan","poet_slug":"ali-riza-ertan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/adanmis-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek', 'gitmek-ergin-gunce-qna2v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidip başbaşa dinleniş serindir sabah

Kuru mum çiçekleri kulaklarında

Bir faytonu durdurarak çekip gidiş

Nerdeyse öğle, deniz, kıyı bir yol ve kule

Çoban köpekleri, durgun sularda uyuyan ses

Nerden bu ağlayış ki annem kadar eski

Hüzne bir türlü yakışmayan ağzımda

Nerdeyse öğle, deniz kıyı bir yol ve kule.', 'Gidip başbaşa dinleniş serindir sabah Kuru mum çiçekleri kulaklarında Bir faytonu durdurarak çekip gidiş Nerdeyse öğle, deniz, kıyı bir yol ...', ARRAY['Türk Edebiyatı','Şiir','Ergin Günçe']::text[], 8.5, '{"poet":"Ergin Günçe","poet_slug":"ergin-gunce","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gitmek-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmak ya da Vurmak Öldürmek', 'olmak-ya-da-vurmak-oldurmek-ergin-gunce-z30tu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir suç oluyorum ben de külümü karıştırınca

Kimleri, kimleri, kimleri vursam

Önce kendimden mi başlasam şakalaşmaya

Önce kendimden mi başlasam

Ben istesem Horoz gibi öterim

Alıngan ve içli çocuk olduğum için

Rahatlarım Bankanın camını kırsam

Sularım sonra atımı bir derede

Ne zaman ne zaman kırlara kaçsam

Ben istesem Kilidimi kırarım

Kumral bir Yaz peşimdedir, dolaşırım ben

Altı yaşında tütüne gittim, oğlak güttüm, çırak

Neler de çıkıyor eşelenince

İnsan büyüyor adam vurarak

Ben istesem Pusu bile kurarım

Duygulu ve sivri bir öğrenci oldum

Ateş okudum kitap yakarak

Artı-değer kavramını ve günlerce Matematik

Bıçaklar edindim Bursa''ya giderek

Benim şimşir Kazıklarım vardır

Ne zaman seni vursalar öcünü komam

İpekli dokunur gibi işliyor zaman

Öfke çiçeğim, av borum, işlek çıngırak

Bütün gün kan içinde yoğruluyorum

Yorulmam dersem Yalan olacak

Bir suç oluyorum ben de külümü karıştırınca

Kimleri, kimleri, kimleri vursam

Önce senden mi başlasam şakalaşmaya

Önce senden mi başlasam', 'Bir suç oluyorum ben de külümü karıştırınca Kimleri, kimleri, kimleri vursam Önce kendimden mi başlasam şakalaşmaya Önce kendimden mi başlas...', ARRAY['Türk Edebiyatı','Şiir','Ergin Günçe']::text[], 8.5, '{"poet":"Ergin Günçe","poet_slug":"ergin-gunce","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/olmak-ya-da-vurmak-oldurmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek', 'bilmek-hilmi-hasal-vg8zk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dizlerimi radyatör peteğine dayamışım sayıklıyorum: 

gerçekte dizlerim mi ısınan, yoksa beynimdeki kayma

sıcaklık algısı mı, zamanı bütünleyen; sormuyorum

dünya yanmak kavramı hakkında öğrenilecek şeylerse

demirdöküm peteğin dil(im)  inden dersler almaya bağlı

eklemlerim o hazzı şimdi keşfediyormuşcasına mutlu

bu, dizlerime yettiği gibi, dizelerime de yeter tabi

bir de, metal denen nesnenin canlıya sunduğu anlam

bilmeyi gerektirmiyordu hiçbir şeyi... hiçbir şey bilmiyordum

bedenimin mutlu olması, beynimin ve yüreğimin de

mutluluğu algıladığı anlamına mı gelirdi -gelmezdi-

yoksa (s)  ayrılığın umarsızlığını mı gösteriyordu ateş

ve yiten her an: yanılsama işte, sanrı... var''dayken bilmemek

ne güzel haklılık oluyormuş meğer, yok''ta uçan halı

ölümü bilmiyor bedenim henüz; görünürde hiçbir şey

yok, yararı yok yaslanmanın; kıvamınca yanıyor petek

belleğimde boşluk, yitmiş ömür şakaları; belki anlam

bilmemek, nedenini ve adresini yaklaşan sonsuzluğun...

gözlerimi radyatör peteğine dayamışım, uyukluyorum.', 'dizlerimi radyatör peteğine dayamışım sayıklıyorum:  gerçekte dizlerim mi ısınan, yoksa beynimdeki kayma sıcaklık algısı mı, zamanı bütünley...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Haşal']::text[], 8.5, '{"poet":"Hilmi Haşal","poet_slug":"hilmi-hasal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bilmek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilsiz Şiir', 'dilsiz-siir-hilmi-hasal-eukpn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sessizliğin keşfine çıkmıştım; 

                    bir ırmak akıyordu...

konuştum kuşkuyu ve suça bulandım söz''le

çünkü kav tutkuyla geçmiştim kendimden

(tutku öz''dür, toz''dur bazı hallerde...)

öteki fer''e ulaştığımı sanmıştım, közde

gömülüydü ''nebi'' yanım; ''söz yanılgıdır''

dediğimde korkuyla, lavdan bir ırmak

akıyordu, yanılgım öyle akıyordu...

ben: ''artık hiç seçim yapmıyorum

       ne güzel, özgürlük bu mu yoksa? ''

                 mucize...

buldum sanırken

görmekle yürüdüm günahımı, yanmakla

                 bir ırmak akıyordu...

ışık ırmağı tanrının: akmak...

    ''en büyük belirti, belki mi tin? ''

keşke bütün bildiğim kipte düş olsaydı

(bilmek başa beladır tüm hallerde...)

bilmek susmaktır: tanrı-da tek kalırken? ..

kül yanım doğada, tanığımdır sıvışan su

artık

bir cenazeye bakar gibi bakıyorum hayata

''suskun'' aya, ''küskün'' güneşe, ''kaçkın'' buluta.

ilk sallantıdan sonra araladım küflü ruhumu; 

ölüm upuzun bir ıssızlıktı kaburgalarımda...

hiçbir şey seçmek zorunda değilim artık

ne mutlu çöl yanıma, özgürüm kumul kadar.', 'sessizliğin keşfine çıkmıştım;                      bir ırmak akıyordu... konuştum kuşkuyu ve suça bulandım söz''le çünkü kav tutkuyla geçmiş...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Haşal']::text[], 8.5, '{"poet":"Hilmi Haşal","poet_slug":"hilmi-hasal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dilsiz-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döngü', 'dongu-hilmi-hasal-dkm3z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'herkes yanındakinin yüzünü eskitiyor, karşısındakinin

eskittiğini sanıyor, sadece sanıyor herkes her şeyi

eskimenin eprime, erime acısını unutabileceğini

yüzündeki etkin vadileri ve dağları bırakmış yalanı

''cesaretini topla ve sürdür eskitilmeyi'' diyor

tepedeki gece konuğu, güney yıldızı

''cesaretini topla ve yine davet et gündüzü ömrüne''...

eskisin

eskiyebildiğince

eskime-

ler...

eksile eksile

ek

sil

e

.

.

.', 'herkes yanındakinin yüzünü eskitiyor, karşısındakinin eskittiğini sanıyor, sadece sanıyor herkes her şeyi eskimenin eprime, erime acısını un...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Haşal']::text[], 8.5, '{"poet":"Hilmi Haşal","poet_slug":"hilmi-hasal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dongu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıvam', 'kivam-hilmi-hasal-sz3kh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şehirlerarası bir yalnızlıktı gittiğim

otobüsler mola yerlerine sokulgan ama küs

kalkıp, bozkırda tanyeri gibi ağırbaşlı

kımıldarken; düşünceli, değiyordum acı ufka

turuncuydu, yalnızlık çeşitlerinde bulunan

bilir; paylaşılmaz mı ne, toprağı çınlasın

Özdemir Asaf püskürtmüş son bulutları, belki

bize düşen o yalnızlık buketi, hani gidilir...

düne bak, kışa basıyor artık bağlı ayaklarımız

buzlanan gün dağarıdır, soğuksa ömürden değil

sıcak sözcükler damıtırken kılavuzsuz aşk göğü

birbiriyle olgunlaşan yalnızlıklardık biz, harlı.', 'şehirlerarası bir yalnızlıktı gittiğim otobüsler mola yerlerine sokulgan ama küs kalkıp, bozkırda tanyeri gibi ağırbaşlı kımıldarken; düşünc...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Haşal']::text[], 8.5, '{"poet":"Hilmi Haşal","poet_slug":"hilmi-hasal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kivam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melodi', 'melodi-hilmi-hasal-4mme9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''cep dünyası işte'' diyor, kendi kendine, aşılmıyor

aşı-lamıyor atlası içsesin, cılız, siyah kül iksiri...

telefonun ''zil tipi'' menüsünden, ''misina ve yem''...

3 nolu melodiyi açıyor avlanırken seçeneklerde...

zaman dünyaya, dünya zamana yem değil mi, salt gam

öyle ya; var''la - yok''la oyalanılan yanılsamalar

oyunu; cılız ses, ne kadar cılız, zanlı evrene

ölümü unutturan ses, ölüm ne ki, gürbüz nesne için

bilinmiyor, aşılmıyor aşkın güz sayfası: adı yok...

''cep dünyası işte'', diyor koynundaki karıncaya, ah

aşılamıyor hayal adresi hayatın, meyyal kalmaya

cebinde acı bir tespih gibi siyah çektiği boşluk...

şimdi, konumunu sorgulayacak değil; uzak melodi

uzayda ölümcül devinim: olmak, yansıyan yansı...

kuşkusu edilgenliğe saplı hançerdir, okuduğu yüz

çeviriyor ki, kendine polen, sonsuz döngüdeki küre

bırak diyor, bedenini saçma tin sarmalına öyleyse...

soru sormak özgürlüğe takılı pranga, çözgüsü yok

özünden öteye yanıt bulamaz hiçbir nesne, nesneye

yankıyan yankı; ya da üfürdüğü ilk korku hayata

neyse hepsi o: ağlamak, cılız nefes... son melodi.', '''cep dünyası işte'' diyor, kendi kendine, aşılmıyor aşı-lamıyor atlası içsesin, cılız, siyah kül iksiri... telefonun ''zil tipi'' menüsünden, ''...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Haşal']::text[], 8.5, '{"poet":"Hilmi Haşal","poet_slug":"hilmi-hasal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/melodi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otogar', 'otogar-hilmi-hasal-wovpo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hem bekleyen hem uğurlayan

olunur mu. ''olunur'' diyor

lir ıslığıyla ikindi rüzgarı; ceza

avunmak için konaklayana

peronlar dolup boşalıyor ''yok''la

kurşun püskürtüyor gen

izlere kış otobüsleri, günün

rahmine ağulu dakikalar düşürtüyor

kararan hava mı sesler mi

otogar vurgunu yürekte, sanık

hem bekleyen hem giden: kim

çığırtkanlar bilemez; gece acı iniyor', 'hem bekleyen hem uğurlayan olunur mu. ''olunur'' diyor lir ıslığıyla ikindi rüzgarı; ceza avunmak için konaklayana peronlar dolup boşalıyor ''y...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Haşal']::text[], 8.5, '{"poet":"Hilmi Haşal","poet_slug":"hilmi-hasal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/otogar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç ve Dal Masalı', 'agac-ve-dal-masali-hilmi-hasal-nmi93', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kökünden kopup kurutulmuş ağaç yok

göğe doğru dalları duacı (salkımsöğüt hariç)

söz geçiremezken zamana yaprakları

büyüdükçe sararır inatla aşktan düşer

yüreğim atardamar basıncına ezik gül

yüzyirmi sayısına rahvan uçuyor görünmez

çılgın koşardamar soyut yeleleri şiir

başına buyruk kökünden yaramaz kaçkın

sonsuz an yok nerde bakraç olmuş dal

öngünleri ertegünlere taşıyan dengelik

gövde dilini dinlemeyen yaprak gönlüm

düşüp sıkıyor bileklerimi de kesiyor düşüp

kökü sevda olan ağaç tanımlıyor dileklerimi

ve beynimi kendi özgürlüğünce masal

kuruyup kütük olduktan sonraya dek kereveti

gider ama sızlar yara izi derin sayfalar', 'kökünden kopup kurutulmuş ağaç yok göğe doğru dalları duacı (salkımsöğüt hariç) söz geçiremezken zamana yaprakları büyüdükçe sararır inatla ...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Haşal']::text[], 8.5, '{"poet":"Hilmi Haşal","poet_slug":"hilmi-hasal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agac-ve-dal-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurt/Su', 'yurt-su-mustafa-ziyalan-vj04e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne yerde ne gökte/iki üç dudağın arasında

daralan su! 

Geçmeyen geçirmeyen/gayyadan derin

sırattan ince su! 

Demeyen dedirmeyen/surdan sesli

hızırdan sessiz su! 

Öpmeyen öptürmeyen/Habil''den azgın

karadan önce su! 

Yad su, yabancı su, kanayan su', 'Ne yerde ne gökte/iki üç dudağın arasında daralan su!  Geçmeyen geçirmeyen/gayyadan derin sırattan ince su!  Demeyen dedirmeyen/surdan sesli...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ziyalan']::text[], 8.5, '{"poet":"Mustafa Ziyalan","poet_slug":"mustafa-ziyalan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yurt-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ad Bulamadığım', 'ad-bulamadigim-mustafa-ziyalan-alnkv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uykular ülkesinde yastıkları yorganları dolduran

günyanığı yollarda çitlembik serperek ardısıra

uyur selvilere takılır da uyur

teninde geçtiği portakalların dokusu rengi

ormanda köpekler havlayınca nefes nefese

yol kıyısında bir atkestanesine yaslanır

gözkapakları incelir pembeleşir yanar da işte

kul olur gözleri günü kamaştıran mavi bir ışık

mavi-mor-

hani o korularda okşadığı kazların yumuşaklığı', 'uykular ülkesinde yastıkları yorganları dolduran günyanığı yollarda çitlembik serperek ardısıra uyur selvilere takılır da uyur teninde geçti...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ziyalan']::text[], 8.5, '{"poet":"Mustafa Ziyalan","poet_slug":"mustafa-ziyalan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ad-bulamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakıp Gördüğüm Dünya', 'bakip-gordugum-dunya-haluk-aker-oqdna', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'herkes gibi ben de

bakıyor muyum görüyor muyum

bordasına tutunmaya çalışıp geminin

biliyorum aşkları var ama nasıl

tarabya''da aşk ya da terman''da

kuşkusuz bir sözcük bağlar bizi

tarabya''da da terman''da da

kendi gerçeğini bulan ermiş

kuşkusuz doğruyu söylüyordu

bulaştırmıyor hiç değilse gökyüzünü

baktığı topraktan kurmuş evini

ben nice günler düşündüm

babam yalan söyleme derdi

anam doğrusunu arardı her işin

gerçek ama kimin

gerçeğin de yalanın da

nice değişken olduğunu anladım

kimin devşirilmiş düşüncesi dedim sonra

gülmeyi elimle kıyıya bıraktım

anladım yalan da olsa kendi yalanın

sahih olsun dedim içimden

durdum düşündüm gerçeği

erdem bağına oturdum

zaten hep törecisin derdi bana

sahi uslanır durulurken gördüm

gerçek bir yorumumdu dünyada

evi ev, kutuyu kibrit yapan sözden

böylece bütün ahlakları eskittim

bakılıp görülen şeyleri eskittim

kendini aç bana, kendin ol

nasıl olursan ol da kendin

eskimemiş güzelliğin tadında

mezarcılar işlerinin başında

zor ama ne iyi

her yeni söz yeni bir insan yaratır', 'herkes gibi ben de bakıyor muyum görüyor muyum bordasına tutunmaya çalışıp geminin biliyorum aşkları var ama nasıl tarabya''da aşk ya da term...', ARRAY['Türk Edebiyatı','Şiir','Haluk Aker']::text[], 8.5, '{"poet":"Haluk Aker","poet_slug":"haluk-aker","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bakip-gordugum-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanrılı Yolculuk', 'sanrili-yolculuk-erdem-avsar-doac3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanıdık cümleler, sözler

Dönüp dolaşıyor çevremde

Güç kayboluyor zamanla

Güç güçsüzlügün maskarası oluyor

Hayatımı kaldırmak yaşamdan

Bana ihtiyacı yok kimsenin

Onca zaman ugraşılan şeyler  dönüp dolaşıyor çevremde.

Acı verici..

Delilik belki..Döne döne inmek..

Saklamak istiyorum her yaptığımı

Sanrılı bir yolculuk olsa gerek bu

Ölümün içinde bir yaşam

Beklemek sadece

Beklemeye alınmak

Bir dönem

En verimli

Kullanılamayan

Yaşanmayan, yaşatılan

Evet, evet sanrılı bir yolculuk bu hayat

Beynin kıvrımlarında yapılan

Keşfedilen şey sadece

Bizden öte bir biz..

Herseyi bilen

Ama unutan..', 'Tanıdık cümleler, sözler Dönüp dolaşıyor çevremde Güç kayboluyor zamanla Güç güçsüzlügün maskarası oluyor Hayatımı kaldırmak yaşamdan Bana i...', ARRAY['Türk Edebiyatı','Şiir','Erdem Avşar']::text[], 8.5, '{"poet":"Erdem Avşar","poet_slug":"erdem-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sanrili-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Feneri', 'deniz-feneri-bilal-sahin-g5drd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir deniz feneri gibi

Bekledim seni

Sakın yanlış anlama

Gelmeni değil ama

Yalnıca gelip geçmeni', 'Bir deniz feneri gibi Bekledim seni Sakın yanlış anlama Gelmeni değil ama Yalnıca gelip geçmeni...', ARRAY['Türk Edebiyatı','Şiir','Bilal Şahin']::text[], 8.5, '{"poet":"Bilal Şahin","poet_slug":"bilal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deniz-feneri-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Yıldızı*', 'seher-yildizi-bayram-tunca-sc6l0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayım, güneşim, yıldızım

Ah benim muhacir kızım

Aşkın alev alev yakıyor beni be kızım

Sen gelmezsen bitmez içimdeki sızım

O muhacir kızı, sevgiyle giyindirilmiş

En güzel inci mercanla süslendirilmiş

Nar çiçeği açmış pembe yanaklarından

Anzer balı akıyor, o tatlı dudaklarından

Şeker şerbet akıyor o tatlı dillerinden

Lâl ü güher damlıyor tatlı sözlerinden

Işık saçıyor o yıldızlı yeşil gözlerinden

İpek saçı tel tel sarkmış omuzlarından

Maharet akıyor, on parmağının onundan

Ay yıldızlı küpeler sarkmış kulaklarından

Ay yıldızlı altın tuğra sarkmış göğsünden

Gül kokusu yayılıyor gülpembe teninden

Daha da anlatamam kalemim düştü elimden

Ah bir bilsen, neler geçmekte şu gönlümden

Şu an ne yazmak, ne de konuşmak istiyorum

Sadece ve sadece, sana kavuşmak istiyorum

09.07.2001-10.10', 'Ayım, güneşim, yıldızım Ah benim muhacir kızım Aşkın alev alev yakıyor beni be kızım Sen gelmezsen bitmez içimdeki sızım O muhacir kızı, sev...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seher-yildizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selvi Boylum*', 'selvi-boylum-bayram-tunca-gnkgr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizlik vurdu sevdalı başıma

Daha yeni girdim, reşit yaşıma

Hele bir baksan, kor gibi yanan alnıma

O zaman inanırsın senin için yandığıma

Bil ki sana olan aşkım, çook ezeli ve ebedidir

Benim nazarımda o yar sanki huriler güzelidir

Onun beni sevdiği o yeşil gözlerinden bellidir

Leyla''m ince belli, servi boylu, pembe tenlidir

Selvi boylumun resmini alıp, cebime koydum

Siluetini alıp belleğimin tam ortasına koydum

Hülya ve rüyalarımda aşkını kalbime koydum

Selvi boylumu sevdiğimde, daha çok toydum

Ah selvi boylum, yine kulağımı çınlattın benim

Azıcık aklım vardı, yine başımdan aldın benim

Hülya veya rüyamda rahat bırakmıyorsun beni

Ne olur siluetten veya sireten rahat bırak beni

Bu denli çok seviyorsan söyle de isteteyim seni

Allah’ın emri, peygamberin kavliyle alayım seni

Ben sana, sen bana, sarılalım ikimiz birbirimize

Ölümümüz ayırırsa, ayırsın ancak her ikimizi de

10.07.2001-10.10', 'Sensizlik vurdu sevdalı başıma Daha yeni girdim, reşit yaşıma Hele bir baksan, kor gibi yanan alnıma O zaman inanırsın senin için yandığıma ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/selvi-boylum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimdin...', 'hayalimdin-gulay-atilay-b94nr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayalimdin... 

Gerçeğim ol istedim 

Yanına geldiğimde yüreğim titredi 

Hayalimdin.... 

Yanlız yatağıma uzandığımda..

Bir burukluk vardı içimde

Hayalimdin...

Umutluydum, gerçeğim olcaktın.. 

Sonunda anladım ki...

Kırık bir cam parçasıydı, 

kalbime batan 

Hayalimden geri kalan bir parça 

Tüm bedenime dağılmıştı 

Toplayamazdım.. 

Karanlıkla dertleştim 

Sensizliğime kahrettim

Kendime, sensizliğime kızdım..

Bir tek sana kızamadım 

Ben yüreğim elimde gelmek

istedim kapına 

Ve düştü o yürek kara toprağa...', 'Hayalimdin...  Gerçeğim ol istedim  Yanına geldiğimde yüreğim titredi  Hayalimdin....  Yanlız yatağıma uzandığımda.. Bir burukluk vardı içim...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayalimdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Değil', 'elimde-degil-mete-tugluk-xsrv5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'demeter''in persephone''e kavuştuğunda başlar başkalığım

bir sevinç kaplar nedense beni mutlanırım

ışınları sızar güneşin yırtılan bulutlar arasından

gökyüzü artık bakire değildir

parmaklarım şaşırır

tüylerim ürperir

okşadığı zaman bahar

yüreğim artık benim değildir

sizindir

severim

severim daha çok

elimde değil...', 'demeter''in persephone''e kavuştuğunda başlar başkalığım bir sevinç kaplar nedense beni mutlanırım ışınları sızar güneşin yırtılan bulutlar ar...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/elimde-degil-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi', 'gibi-mete-tugluk-mrjh5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir şeyi sevmek

bir şey olmaktır

bir çiçekle çiçek

bir taşla taş gibi

bütünleşmektir

birleşmektir sevmek

aynı biçimde

aynı anda

aynılaşmaktır aşk gibi...', 'bir şeyi sevmek bir şey olmaktır bir çiçekle çiçek bir taşla taş gibi bütünleşmektir birleşmektir sevmek aynı biçimde aynı anda aynılaşmaktı...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gibi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle...', 'dinle-binay-donmez-hfnka', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anılardan tarih yazamazsın

Ya da mevsimlerden ayaz...

Sen sen olalı söndüremezsin bu alevi

Bir sise tesli olmuşken yüreğin.

Veremezsin titrek ellerini yüreğime

Gözlerini kamaştırma boşuna 

Rüya değildir karşında duran o asil yağmur

Altında ıslan, ıslan da ağla şimdi

Şimdi yaz tarihi anılara

Mevsimleri ayaza vur, vurda dinle

Bir güneşe aldanmışken yüreğin

Dudaklarındaki şarkıyı son kez dinle

''Seni Seviyorum'' diye...', 'Anılardan tarih yazamazsın Ya da mevsimlerden ayaz... Sen sen olalı söndüremezsin bu alevi Bir sise tesli olmuşken yüreğin. Veremezsin titre...', ARRAY['Türk Edebiyatı','Şiir','Binay Dönmez']::text[], 8.5, '{"poet":"Binay Dönmez","poet_slug":"binay-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçkimiçekime', 'i-ckimicekime-mete-tugluk-pw3xy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kuşlar yaptın gözlerden ile çiçekler dudaktan

ve kelebek renkler suskunluktan

kapı mıydı usulca

belki bahardı çaldığım

bir anda dokunup seninle senliği kavradım

su mu akan kollardan yoksa bulut mu

bir kayganlık ki

ses gibi

koku gibi

saçlar mı dalgalar mı belirsiz

isimsiz sarısıcakdevingen bir deniz gibi gizemsiz

birden sustum eller çoğalınca

diller yıldırımdı parmaklar yalım

hüzün sarınca ortasını dokunmaların

tümlüğüm tek tek ve yitip giderek

parçalara parçalandım

bir oyuncak maymun olup

trampet çalmaya başladım', 'kuşlar yaptın gözlerden ile çiçekler dudaktan ve kelebek renkler suskunluktan kapı mıydı usulca belki bahardı çaldığım bir anda dokunup seni...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ickimicekime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Hatıra', 'benden-hatira-huseyin-ucak-ix73d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arkadaş bu sözlerim sana

Kulak ver bu söylediklerime

Benden sana bir yar hediyi

Onu benim gözüm ve benim kalbimle sev

Yabana atma bu duyguları

Değer ver bu sevgiye

Sonunda acı çekmek yada mutlu olmak var

Bütün bu imkanlar sizin elinizde

Arkadaş bu sözlerim sana

Kulak ver bu söylediklerime

Siz sevip ve sevilmeye layık olansınız

Mutlu olmak sizin elinizde

Düşün şimdi hak verirsin bana

Bu güne kadar yaşananları

Kim sana bu kadar değer verebilir

Kim senin için ölmeyi göze alabilir

Seni sevenin kıymetini bil

Diğer her şey yalan, yanlış, boş

Arkadaş bu sözlerim sana

Kulak ver bu söylediklerime

Bu dizeler benden size hatıra

Mutlu günler sizi beklemekte', 'Arkadaş bu sözlerim sana Kulak ver bu söylediklerime Benden sana bir yar hediyi Onu benim gözüm ve benim kalbimle sev Yabana atma bu duygula...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Uçak']::text[], 8.5, '{"poet":"Hüseyin Uçak","poet_slug":"huseyin-ucak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/benden-hatira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allahsız', 'allahsiz-huseyin-ucak-6kvro', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi nedir bilirmisin Allahsız

Bilemezsin bilemezsin tabi

Hiç sevdinmiki bilesin

Seni sevene değer verdinmi hiç

Birine ölümüne gönül verdin mi? 

Gecelerce onu düşündünmü hiç

Uğruna ağıtlar yaktınmı ki

Onun bir gülüşüne dünyaları 

Feda ettinmi Allahsız

Sen sevgiden ne anlarsın be

Sen ve senin gibiler sevgiyi

Gönül eylendirmek sandınız hep

Öyle değil, öyle değil Allahsız

Birini sevdin mi ölümüne seversin

Gerekirse canını seve, seve verirsin

Siz durmadan sevgiden konuşursunuz

Nedir diye sorunca

Afallayıp durursunuz

Lafta sevmek daima kolaydır Allahsız

Gerçek sevgiyi sen sevene sor

Kıymetini bilmeden yaşadınız hep

Sen gel sevgiyi birde bana sor

Bana sor ALLAHSIZ birde bana sor', 'Sevgi nedir bilirmisin Allahsız Bilemezsin bilemezsin tabi Hiç sevdinmiki bilesin Seni sevene değer verdinmi hiç Birine ölümüne gönül verdin...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Uçak']::text[], 8.5, '{"poet":"Hüseyin Uçak","poet_slug":"huseyin-ucak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/allahsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Rüzgarları', 'guz-ruzgarlari-huseyin-ucak-kzq64', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dolandım yine sensiz sokaklarda kendimce

Seni düşündüm seni andım kendimce

Hiç çıkmadın aklımdan bir kere bile

Sevdim seni güzel kız çaresizce

Güz rüzgarları esmeye başladı çevremde

Senin ateşin ısıttı o yanlız gecelerde

Aşkından yandım tutuştum mecnun oldum peşinde

Sen dönüpte bu kim diye bakmadın bile

Güz rüzgarlarında savrulurken

Yağmur altında sensiz ıslanırken

Sensizliğe ümitsiz alışmaya çalışırken

Şu göz yaşlarım hiç dinmediki

Bir mendil al eline sevgilim

Sil şu kanlı göz yaşlarımı

Bir kere olsun gör bu çaresiz adamı

Şu ömrümü sana adadım sen anlamadınki

Bakma bana artık ümit verici gözlerle

Eziyet çektirme artık seni seven bu gönlüme

Gidiyorsun işte güz rüzgarları içinde

Sakın ola beni düşünüp kendini üzme

Ben alıştım artık sensiz geçen kara gecelere', 'Dolandım yine sensiz sokaklarda kendimce Seni düşündüm seni andım kendimce Hiç çıkmadın aklımdan bir kere bile Sevdim seni güzel kız çaresiz...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Uçak']::text[], 8.5, '{"poet":"Hüseyin Uçak","poet_slug":"huseyin-ucak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guz-ruzgarlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-ese-ese-ttwb1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'rüzgara yazı yazdım

ve harf harf döküldü yağmur

sen hala

kupkurusun', 'rüzgara yazı yazdım ve harf harf döküldü yağmur sen hala kupkurusun...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ruzgar-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-egemen-bilgin-5uq63', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Of be çekik gözlüm

Yorulmuşum sensiz gecelerin fırtınalarında

Gemim alabora olmuş sensiz dalgalar arasında

Bütün yollarım çıkmaz sokaklara dönmüş sensiz arayışlarda

Ah be yay kaşlım

Bağlamam ağlar olmuş sensiz türkülerde

Saatim yavaşlamış, zaman geçmez olmuş sensiz anlarda

Dilim tutulmuş, konuşamaz olmuşum sensiz sohbetlerde

Gel be dinmez vuslatım

Özlemin dolmuş da taşmış benden sensiz diyarlarda

Her soluğum yarım kalmış, tüm gülüşlerimde bir gözyaşı gizli

Kalmışım sensiz, sensizliğin hüküm sürdüğü sensiz cehennemlerde', 'Of be çekik gözlüm Yorulmuşum sensiz gecelerin fırtınalarında Gemim alabora olmuş sensiz dalgalar arasında Bütün yollarım çıkmaz sokaklara d...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizlik-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zannetme Ki Ayrıyız', 'zannetme-ki-ayriyiz-egemen-bilgin-if9pm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen bir damla yağmur olacağım, bazen de bir yıldız. Göreceğim yüzünü

Bazen nefesin olacağım, sormadan dolacağım içine

Bazen gözyaşın olacağım, derdini kederini alıp götüreceğim

Zannetme ki ayrıyız, ben hep yanı başında bir buruk sevinç olacağım....', 'Bazen bir damla yağmur olacağım, bazen de bir yıldız. Göreceğim yüzünü Bazen nefesin olacağım, sormadan dolacağım içine Bazen gözyaşın olaca...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zannetme-ki-ayriyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiraz Çiçekleri', 'kiraz-cicekleri-itir-i-zgi-4ltnh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Açmadan daha kiraz çiçekleri, 

Bahar dalları kışa yenildi...', 'Açmadan daha kiraz çiçekleri,  Bahar dalları kışa yenildi......', ARRAY['Türk Edebiyatı','Şiir','Itır İzgi']::text[], 8.5, '{"poet":"Itır İzgi","poet_slug":"itir-i-zgi","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kiraz-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimde Sen Vardın', 'duslerimde-sen-vardin-hidir-baspinar-9yjdg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir düş kurmak olsaydı amacımız seninle.

Yalnız bende sen sende ben olmalıydık.

Ateş gibi yanan o dudaklarına dokunuşta.

Alevin benim içimide ısıtmalıydı.

Geceler küsmüş konuşmuyordu benimle.

Pencerem yalnız senin için açık.

Rüzgar serin yelini bana gönderiyordu.

Ama ben seni düşünüyordum.', 'Bir düş kurmak olsaydı amacımız seninle. Yalnız bende sen sende ben olmalıydık. Ateş gibi yanan o dudaklarına dokunuşta. Alevin benim içimid...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Başpınar']::text[], 8.5, '{"poet":"Hıdır Başpınar","poet_slug":"hidir-baspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/duslerimde-sen-vardin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasana', 'anlasana-egemen-bilgin-stlmf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elimi uzatıyorum; tutsana.

Durmadan izini arayan, 

Bir dervişim, 

Bir tebessümle, çağırsana.

Çalıyorum kapını; açsana.

Her gece gökyüzünde, 

Yıldızlarla eleleyim, 

Bir kerecik, baksana.

Bir kibritim; yaksana.

Seni deli gibi seven, 

Bir divaneyim, 

Bedenimi bedeninle, sarsana.

Gönlüm senindir; alsana.

Hep ağlayan, 

Bir mazlumum, 

Bir damla gözyaşım olsana.

Var gücümle haykırıyorum; duysana; 

Acılar içinde kıvranan, 

Bir yalnızım, 

Seni seviyorum, anlasana.', 'Elimi uzatıyorum; tutsana. Durmadan izini arayan,  Bir dervişim,  Bir tebessümle, çağırsana. Çalıyorum kapını; açsana. Her gece gökyüzünde, ...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlasana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmek Yasak!', 'gecmek-yasak-ali-saglam-3-k1swa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dur yolcu...! 

Burası evrenin merkezi, 

Kalbimdir..! 

Her yürek aşamaz gönül dağımı, 

Rakım''ı yüksektir, 

Fena çarpar adamı...!', 'Dur yolcu...!  Burası evrenin merkezi,  Kalbimdir..!  Her yürek aşamaz gönül dağımı,  Rakım''ı yüksektir,  Fena çarpar adamı...!...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gecmek-yasak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-egemen-bilgin-r0a13', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uçsuz bucaksız bir çölde, 

Bir damla suya hasret bir çiçeğim ben.

Eni sonu belli olmayan bir denizde, 

Bir dalgadan bir dalgaya salınan bir salım ben.

Hiç kimse tarafından bilinmeyen bir adreste, 

Yaşayan mahcup bir kimsesizim ben.

Yalnız ve yüksek bir tepede, 

Dost bekleyen bir yalnızım ben.

Sarp ve acımasız bir uçurumun köşesinde, 

Düşmeye hazır bir gerçeğim ben.

Sadece imamının namaza durduğu bir camide, 

Gönüllere yayılmayı bekleyen taze imanım ben.

Unutulmuş yüreklerde, 

Unutulmamayı bekleyen bir acizim ben! ..', 'Uçsuz bucaksız bir çölde,  Bir damla suya hasret bir çiçeğim ben. Eni sonu belli olmayan bir denizde,  Bir dalgadan bir dalgaya salınan bir ...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyor Musun?', 'seviyor-musun-egemen-bilgin-f9acx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neredesin? Gelsene.

Tutsana şu ellerimden, 

Adımı sorsana, 

Öpsene yanağımdan.

Kiminlesin? Kaçsana.

Sarılsana şu belimden, 

Adını fısıldasana, 

Koklasana saçımdan.

Nasılsın? Anlatsana.

Sokulsana sağ yanımdan, 

Gözlerime baksana, 

Vursana kalbimden.

Seviyor musun? Söylesene.

Girsene sahipsiz gönlüme, 

Benliğimi kavrasana, 

Götürsene beni benden.', 'Neredesin? Gelsene. Tutsana şu ellerimden,  Adımı sorsana,  Öpsene yanağımdan. Kiminlesin? Kaçsana. Sarılsana şu belimden,  Adını fısıldasan...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyor-musun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ne Biçim Hikâye', 'bu-ne-bicim-hik-ye-egemen-bilgin-96cj9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi size bir yok oluş hikâyesi anlatacağım

Hiç başlamamış ve hiç bitmemiş bir hikâye

Bütün kahramanları savaşmış ölesiye

Eğer ölen varsa da bu mücadelede; ben yaşatacağım

Sorumsuzluğun ve umursamazlığın acı faturası

İnsanı mahveden sebepsizce kahrolası

İstiyorsan bu hikâyede oynamayı ası

Sen de kazanmalısın bu savaşı

Tam hikâyenin sonunun geldiğini zannedersin

Fakat son bulan esas kendinsin

Zannetme ki biter bu hikâye

Sen bitirmeden o da bitmez

Kim yazmış bu hikâyeyi bilinmez

Ne zamandır devam eder bilinmez

Bazen aynı olayları yaşatır sana

Ama sen fark edemezsin inadına

Yine mi bitti zannettin

Biten sadece bu hikâyeyi anlatan şiirdir

Daha nice hikâyelerden sadece biridir

Benden de, senden de ötedir.', 'Şimdi size bir yok oluş hikâyesi anlatacağım Hiç başlamamış ve hiç bitmemiş bir hikâye Bütün kahramanları savaşmış ölesiye Eğer ölen varsa d...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-ne-bicim-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olumsuzluk', 'olumsuzluk-egemen-bilgin-7ilny', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kulağıma garip bir ses geliyor, 

Fakat duyamıyorum.

Gözüme rengârenk ışıklar geliyor, 

Fakat göremiyorum.

Tenime yumuşacık bir şeyler dokunuyor, 

Fakat hissedemiyorum.

Burnuma mis kokular geliyor, 

Fakat koklayamıyorum.

Ağzıma baldan şerbet konuluyor, 

Fakat tadamıyorum.

Birisi saçımı okşuyor, 

Fakat istemiyorum.

Uzaklardan bir rüzgâr üşütüyor her şeyi, 

Fakat ben üşümüyorum.

Tanımadığım biri seviyor beni, 

Fakat ben sevmiyorum.', 'Kulağıma garip bir ses geliyor,  Fakat duyamıyorum. Gözüme rengârenk ışıklar geliyor,  Fakat göremiyorum. Tenime yumuşacık bir şeyler dokunu...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olumsuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Söz', 'bir-soz-egemen-bilgin-vhbqc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzün dolu bir günün ardından sadece bir söz yetti

Mutlu bir yarın ummaya

Karanlık yollarda, bir başına ve çaresiz yürüyen bu yolcuya

Bir mum vermek gibiydi

Korkuların içinde sırılsıklam terleyen bir kaybetmişe

Cesaret vermek gibiydi

Aşkından gözyaşları içinde kalakalmış bir aşığa

Aşk öldürmez demek gibiydi

Bana hergün söyle bu sözü

Hergün bir öncekinden daha güzel olsun

Ne olur her an söyle

Her an bir öncekinden güzel olsun

Bana beni sevdiğini söyle

Çünkü ben; ben seni seviyorum...', 'Hüzün dolu bir günün ardından sadece bir söz yetti Mutlu bir yarın ummaya Karanlık yollarda, bir başına ve çaresiz yürüyen bu yolcuya Bir mu...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Ey Yâr', 'neredesin-ey-y-r-egemen-bilgin-am00i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Varlığım sukût içinde eriyor

Bedenim acılar içinde kıvranıyor

Kalbim; kalbim atmaya mecâl bulamıyor

Neredesin ey al yanaklım

Günlerim zindan oldu, hayat durdu

Saatim ilerlemez, zaman geçmez oldu

Bugünümü, dünümü karıştırır oldum

Neredesin ey çekik gözlüm

Hep yarınlar var aklımda 

Vuslatın adım adım yaklaşması var yolumda

Özlüyorum seni bir tanem sılada

Neredesin  ey yay kaşlım

Telefonum çalmaz, kapım açılmaz oldu

Gülen dostlarımın hepsi ağlayan düşman oldu

Kalbim buruk, sevincim yok oldu

Neredesin ey Cânan', 'Varlığım sukût içinde eriyor Bedenim acılar içinde kıvranıyor Kalbim; kalbim atmaya mecâl bulamıyor Neredesin ey al yanaklım Günlerim zindan...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neredesin-ey-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garipsenmeyen yalnızlık', 'garipsenmeyen-yalnizlik-riza-aslan-czin5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yeni birşeylerin içinde

herzamaki 

o tanıdık 

o bildik 

artık varlığı garipsenmeyem

yalnızlığımın içerisindeyim', 'yeni birşeylerin içinde herzamaki  o tanıdık  o bildik  artık varlığı garipsenmeyem yalnızlığımın içerisindeyim...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/garipsenmeyen-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazi''nin Mazi''si', 'mazi-nin-mazi-si-ali-saglam-3-tzg6e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelecekte bir gün geçmiş olacak, 

Ve her geçen saniye...

Mazinin cehennem halkasına, 

Eklenerek çoğalacak...

Bilmiyorum Ömrümün neresindeyim.

Belki başında, belki sonunda, 

Yada ortasında kimbilir? 

Umrumda bile değil...

Ben geçmişi seviyorum, 

Mazinin nane kokulu yıllarında.

Ömrümün en derin, en güzel

En tatlı soluklarını alıyorum...

Gelecek acı verecek bana, 

Yeni acılar çekmek istemiyorum, 

Geçmişte de acılar var ama.

Döndüler artık gözyaşımla sönmüş volkana...

Gölgemi geçmek için hep, 

Güneşe yürüdüm, yürüdüm başaramadım.

Ben artık gelecegin cennetinde yanmak değil, 

Geçmişin cehenneminde mutlu olmak istiyorum...', 'Gelecekte bir gün geçmiş olacak,  Ve her geçen saniye... Mazinin cehennem halkasına,  Eklenerek çoğalacak... Bilmiyorum Ömrümün neresindeyim...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mazi-nin-mazi-si-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bana Beni Sana Yazardım', 'seni-bana-beni-sana-yazardim-salih-ozalasan-iwiqy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaderimi yeniden yazmak

Elimde olsa neler vermezdim

Seni bana, beni sana yazardım

Senden asla vazgeçmezdim

Yüreğim böyle sızlamazdı

Her geçen gün biraz daha tükenmezdim

Yakmazdı yataklar sırtımı

Karabasan nedir bilmezdim

Gözlerim gülerken ağlamazdı yüreğim

Sahte bir mutluluğa asla bürünmezdim

Tükenmezdim her gün damla damla

Her gece bir yaş daha çökmezdim

İçim daralmazdı böyle gün boyu

Heran kötü bir haber beklemezdim

Beklemek ve özlemek benim kaderim

Demiyeceğim asla, bilsem asla sevmezdim', 'Kaderimi yeniden yazmak Elimde olsa neler vermezdim Seni bana, beni sana yazardım Senden asla vazgeçmezdim Yüreğim böyle sızlamazdı Her geçe...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-bana-beni-sana-yazardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sadece ölmek', 'sadece-olmek-atilgan-alemdar-hstk5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yine yazdım gözlerini dün gece

bulutların sakladığı ayın çehresine

parmak uçlarımdan kan damlıyordu

vurulmuştum ölüyordum gizlice

başım yıldızların etrafında dönüyordu

mumun ürkek aydınlığı çaresiz

ben çaresiz...

yaram tüm sıcaklığıyla kanıyordu

vurulmuştum ölüyordum gizlice

yıldırım mı düşmüştü ciğerime

yıllarca birikip patlayan bir deprem mi

lâvlar akıyordu san ki üzerime

yer sallanıyor gök parçalanıyordu ya

vurulmuştum ölüyordum sadece

yüzün akmasa damarlarımdan, yaşamak istemezdim

ama yüzün akıyor, şimdi ölüm de nesi

sensiz de olsam mutluydum seni sevdikçe

dün gece bozuldu mermiler coştu birden

kırmızı güller açıyordu gölgem

vurulmuştum ölüyordum ince ince', 'yine yazdım gözlerini dün gece bulutların sakladığı ayın çehresine parmak uçlarımdan kan damlıyordu vurulmuştum ölüyordum gizlice başım yıld...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sadece-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay Üstü Sigara''lı Hayaller', 'cay-ustu-sigara-li-hayaller-ali-saglam-3-x6pud', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ahh sigara''m...

Biricik sevgilim, 

Melek bakışlım, Şeytan yakışlım

Değeri bilinmeyenim...

Bir sevgiliden, 

Bir dosttan, 

Daha yakınsın bana...

Elimi attığımda cebimde

Elime aldığımda dudağımda

Dudağıma değdiğinde ciğerlerimdesin.

Seni hissetmek ne güzel...

Kimbilir kaç kişiyi öldürdün, 

Kurtardıklarından fazla olduğuna, 

Eminim! ! ! 

Olsun...

Gül''ler dikensizmi sanki, 

Sende gül''sün herkesin gözünde, 

Ama dikenlerin zehirli...

Senden kurtulmak istesemde, 

Kurtulamıyorum...! 

Hani aklıma gelmiyor değil.

Acaba kurtulmak mı istemiyorum...

Terkeder giderdin biliyorum.

Cebimde üç kuruşum kalmasa

Hangi ilişki menfeatsiz gerçi, 

Keşke dostluklar, aşklar

Senden menfeatçi olmasa...', 'Ahh sigara''m... Biricik sevgilim,  Melek bakışlım, Şeytan yakışlım Değeri bilinmeyenim... Bir sevgiliden,  Bir dosttan,  Daha yakınsın bana....', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cay-ustu-sigara-li-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Affetsin', 'allah-affetsin-sezer-usluoglu-j644s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sende mutlumusun benim gibi

Yabancı kollarda, yalancı aşklarda

Boşa geçirdiğin zamanlarda

Anlıyormusun sende

Benim seni andığım gibi

Ağlıyormusun

Anlatıyormusun hala beni dostlarına

Yanıyormusun

Pişmanmısın beni bıraktığına

Şöyle dönüp arkana baktığında 

Hatırla, bana gülüyordunya

Hãla gülebiliyormu o bal rengi gözlerin

Yoksa sadece kanmı ağlıyor

Daha dur, daha yeni başlıyor

Ne acılar çekeceksin daha

Nefes alamiyacak hale geleceksin hıçkırmaktan

Başını hangi duvara vuracağını şaşıracaksın

ALLAH''a yalvaracaksın beni affetsin diye

Seni ALLAH affetsin

Benide...', 'Sende mutlumusun benim gibi Yabancı kollarda, yalancı aşklarda Boşa geçirdiğin zamanlarda Anlıyormusun sende Benim seni andığım gibi Ağlıyor...', ARRAY['Türk Edebiyatı','Şiir','Sezer Usluoğlu']::text[], 8.5, '{"poet":"Sezer Usluoğlu","poet_slug":"sezer-usluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/allah-affetsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-sezer-usluoglu-9dtkf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah hayat ah

Ne yaptım ben sana

Bu kadar kötü bir insanmıym ben

Aldın bütüm sevdiklerimi elimden

Ne kaldıki başka

Bide canım var

Bu kadar çok şey kaybettikten sonra

O vız gelir

Hazırım zaten gelde al

Alda kurtulayım bu iğrenç dünyadan

Belki başka zaman

Başka bir dünyada

Başka bir bedenle yenerim seni

Hoşçakal bile demeden

Son duamı etmeden

Daha fazla sürünmeden

Ne geliyorsa yap elinden

Al şu canımıda

Sende kurtul benden', 'Ah hayat ah Ne yaptım ben sana Bu kadar kötü bir insanmıym ben Aldın bütüm sevdiklerimi elimden Ne kaldıki başka Bide canım var Bu kadar çok...', ARRAY['Türk Edebiyatı','Şiir','Sezer Usluoğlu']::text[], 8.5, '{"poet":"Sezer Usluoğlu","poet_slug":"sezer-usluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isyan-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı Gemi', 'yarali-gemi-hayalet-kral-zo9jh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dev dalgalarla boğuşmuş

Yaralı bir gemi gibiyim, 

Sen maviliklerimde dolaş 

Ben o denizin derinlikleriyim.

Bir fırtınadan kurtulsam yakalanıyorum bir başkasına

Faydasız... demir atamıyorum

Senden başka bir sahil kasabasına...! 

Dinerse şayet bu fırtınalar

Denizimiz süt liman olacak, 

Senin içinse tüm hissettiklerim

Sonsuza dek bakii kalacak...', 'Dev dalgalarla boğuşmuş Yaralı bir gemi gibiyim,  Sen maviliklerimde dolaş  Ben o denizin derinlikleriyim. Bir fırtınadan kurtulsam yakalanı...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yarali-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahroluyorum Sokaklarda', 'kahroluyorum-sokaklarda-hayalet-kral-9bz7p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaban otları gibi büyümek istedin

Gönlünce heryerde, 

Tatlılığınla beni sürüklemek

Aniden hayatından çıkmak istercesine.

Kır çiçekleri açarken hep birlikte

İnadına gez, gününü gün et oralarda

Aynı çiçekler solarken sensizliğinde

Yüreğime hapsettim seni karanlık sokaklarda.

Ömür boyu çekmek istercesine cezamı

Kahrediyorum kendimi sabah akşam, 

Yapacağım başka bir şey var ise söyle 

Aaahh yine seni bıraktığım yerlerde bulsam...', 'Yaban otları gibi büyümek istedin Gönlünce heryerde,  Tatlılığınla beni sürüklemek Aniden hayatından çıkmak istercesine. Kır çiçekleri açark...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kahroluyorum-sokaklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemedin', 'i-stemedin-hayalet-kral-xuhfr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsterdimki; soluduğun hava ile

Ruhuna dolup taşayım, 

İsterdimki; kokladığın gül ile

Adını baştan başa göklere yazayım! ...

İstermiydin? ; denizleri senin için Kızıl’a boyamamı

İstermiydin? Aşkın uğruna cehennem ateşlerinde yanmamı...

İsteseydin; binlerce kilometre uzaktan

Dokunurdun aşkın bamteline, 

İsteseydin; kar yağınca üşüyüp soğuktan

Sokulurdun bu adamın tanyeline...', 'İsterdimki; soluduğun hava ile Ruhuna dolup taşayım,  İsterdimki; kokladığın gül ile Adını baştan başa göklere yazayım! ... İstermiydin? ; d...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istemedin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazideki Seferim', 'mazideki-seferim-hayalet-kral-3798s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ummadığın anlarda yaşıyorsun

Hayatın acısını tatlısını, olmaz haberin; 

Nitekim onları vakitsiz buluyorsun

Çaresiz... önceden yazılmıştır kaderin! ...

Tam yanındayım sensiz akşamların

Lapa lapa üstüme yağıyor kar, 

Eski dostlardan kalan sadece

Mazideki gülümseyen bakışlar...

Dünya var oldukça aranacak

Hep eski yaşadıklarımız, 

Biz konuşmasakta, onlar konuşacak

Hep geride bıraktıklarımız...

Şimdi uzaklarındayım güneşlerin

Yazdan bahardan yok haberim, 

Bir başlasam hiç bitmeyecek

Vakti geçmiş sonu meçhul seferim! ...', 'Ummadığın anlarda yaşıyorsun Hayatın acısını tatlısını, olmaz haberin;  Nitekim onları vakitsiz buluyorsun Çaresiz... önceden yazılmıştır ka...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mazideki-seferim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahpe Zaman', 'kahpe-zaman-hayalet-kral-s8zis', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir çırpıda uzanabilsem

Gökkubbenin ulaşılmaz maviliklerine, 

Bir dal çiçek açsa uzaklarda

Bakmayın o ağaç kupkurudur dediklerine.

Kalemimle mısraları sıralasam

Karbeyazı bulutların tam üzerine, 

Yağmur değilde güklerden ben yağsam

Buz tutmuş yürekleri eritircesine! ...

Şimşeklerin hızıyla anlatabilsem

Solmayan aşkımı tanımadığım sevgilime, 

Yaşanamayan anılara dönebilsem

Bakarken aynada cansız gözlerime...

Geriye döndüğümde, hayali bir tek

Hatırımda umutsuzca kalan, 

Onuda gün ışıkları usulca yok edecek

İşte çalıyor seni benden Kahpe Zaman! ...', 'Bir çırpıda uzanabilsem Gökkubbenin ulaşılmaz maviliklerine,  Bir dal çiçek açsa uzaklarda Bakmayın o ağaç kupkurudur dediklerine. Kalemimle...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kahpe-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlar Caddesinde', 'yalnizlar-caddesinde-hayalet-kral-jpkhg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün mor menekşeler açıyor

Sabahında hüsranlar çiçeği yüreğimde, 

Bir bakıyorum heryer ışıl ışıl parlıyor

Birden kalıyorum bulutların gölgesinde.

Hapsedilmiş veryansın tohumlarını

Salsam bazen gecenin karanlığında, 

Geri döner çekerim sancılarını

Hele birde senin yokluğunda...

Kelimeler sonsuz aşkıma bulansın

Sonu kaçınılmaz fani bedenimde, 

Ve o an yer gök ağlasın...

Terk edilmiş yanlızlar caddesinde! ...', 'Bir gün mor menekşeler açıyor Sabahında hüsranlar çiçeği yüreğimde,  Bir bakıyorum heryer ışıl ışıl parlıyor Birden kalıyorum bulutların göl...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlar-caddesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Kalırsın', 'bir-sen-kalirsin-hayalet-kral-dcqr4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir damla yaş düştüğünde

Mazide köklenen selvi yapraklarına, 

Yeşerir anılar istem dışı

Sen bile şaşırırsın hatırladıklarına! 

‘HERKES GİDER BİR SEN KALIRSIN’

Meltemler lodosları izler

Fırtınalar tümünden beter olduğunda, 

Küçük sırlar kendini gizler

Unutulur inan zamanın boşluğunda! 

‘HERKES GİDER BİR SEN KALIRSIN’

Müstesna anların bahtiyar çiçekleri

Birden döküverir yapraklarını, 

Hatırlatır insana yaşamın gerçekleri

Vakit ile kapatırsın göz kapaklarını! 

‘HERKES GİDER BİR SEN KALIRSIN’

Filmin sonu her kula aynıdır

Yaşlıya, gence; fakire, zengine, 

İşte adresin bir avuç topraktır

Dualar okunurken kavuşursun Rabbine! 

‘HERKES GİDER BİR SEN KALIRSIN’...', 'Bir damla yaş düştüğünde Mazide köklenen selvi yapraklarına,  Yeşerir anılar istem dışı Sen bile şaşırırsın hatırladıklarına!  ‘HERKES GİDER...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-sen-kalirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim Yar Neyleyim', 'neyleyim-yar-neyleyim-hazni-cetin-vqh7t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünyadeki her şeyden, sen bana sevimlisin

Beni Hayatta tutan Bedende Can gibisin

Su Balığa ne ise sende bana öylesin

Balık Sussuz nasılsa bende sensiz öyleyim.

Neyleyim Yar neyleyim sensiz Dünya neyleyim

Öleyim ahh öleyim sensiz Hayat neyleyim.

Duam odur ki benim seni kimse sevmesin

Benden başka hiç kimse Gönlünde yer etmesin

Bülbüle Gül ne ise sende bana öylesin

Gülsüz Bülbül nasılsa bende sensiz öyleyim

Neyleyim Yar neyleyim sensiz dünya neyleyim

Öleyim ahh öleyim sensiz Hayat neyleyim.

Kara Sevdalın oldum Sevda nedir bilirsin

Sende biraz sev beni garip Gönlüm sevinsin

Mecnuna Leyla neyse sende bana öylesin

Mecnun Leylasız deli bende sensiz öyleyim.

Neyleyim Yar neyleyim sensiz dünya neyleyim

Öleyim ahh öleyim sensiz Hayat neyleyim', 'Dünyadeki her şeyden, sen bana sevimlisin Beni Hayatta tutan Bedende Can gibisin Su Balığa ne ise sende bana öylesin Balık Sussuz nasılsa be...', ARRAY['Türk Edebiyatı','Şiir','Hazni Çetin']::text[], 8.5, '{"poet":"Hazni Çetin","poet_slug":"hazni-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/neyleyim-yar-neyleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Bir Şiir', 'oylesine-bir-siir-hayalet-kral-jf99r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öylesine sıkıntılar vardırki 

Çıkmaz sokaklarında acılar veren, 

Öyle çıkmazlar vardırki

O sokakları yerle bir eden! 

İnsan çoğunda yol bulamaz 

Sanki hep orada yaşamak ister gibi, 

Bulsada bırakmaz...

‘KAL BURADA’ der göremediğin biri...

Söylediğini bir sen duyarsın

Yazdığın yüzlerce sayfayıda, 

Gördüğünü bir sen yaşarsın

Tuttuğun gül dalınıda...

Şimdi; hiç solmayan o ‘GÜL’ yaprağının

‘PEMBE’ gülüşünü anıyorum, 

Dedimya üylesine bir şiirdi

Bıkıp usanmadan öylesine yazıyorum...', 'Öylesine sıkıntılar vardırki  Çıkmaz sokaklarında acılar veren,  Öyle çıkmazlar vardırki O sokakları yerle bir eden!  İnsan çoğunda yol bula...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oylesine-bir-siir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimler Ölmez mi?', 'resimler-olmez-mi-ali-saglam-3-obv2t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Resmin bende kalsın ha...

Ne büyük lütuf, 

Şimdi sevinçten ağlamalımıyım, 

Yada gözyaşlarım acıların mı, 

Tutsağı olmalı? 

Hangi suçumun cezasısın, 

Yok yok...

Sen başımın tacısın, 

İnkar edemem.

Senden geriye resmin kalacak şimdi öylemi, 

Sen öyle san...

İçimde öyle kocaman kalacaksın ki.

Gözlerinin boyu

Bakmaya yetmeyecek...

Hep yanlış anladın beni, 

Yanlış savurdun tokadı, 

Ben kroşe bekliyordum, 

Boş bulundum affet...

Sevgim mi ağır geliyor insanlara

Yoksa ben mi sevgide ağır kalıyorum, 

Bilmiyorum umrumda da değil ayrıca...

Sensiz ne umrumda sanki...

Oda umrumda değil...

Bir elimde sigaram, 

Bir elimde resmin, 

Fanteziye bak...

Sen yoksan resmi''nin ne anlamı var ki... 

Sadece...

Yanmış kül olmuş bir evin

Elde kalan anahtarı misali...

Bomboş gözlerle salla dur...

Mutluluğu, dostluğu

Salla dur, uyusunlar güzelce ha...

Benim yüreğim beşik mi yaa...!', 'Resmin bende kalsın ha... Ne büyük lütuf,  Şimdi sevinçten ağlamalımıyım,  Yada gözyaşlarım acıların mı,  Tutsağı olmalı?  Hangi suçumun cez...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/resimler-olmez-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce Rabbime', 'yuce-rabbime-hayalet-kral-ptbgb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey büyük allahım; 

Nasılda yaratmışsın bizleri 

Topraktan, sudan, ateşten; 

Sarmış ‘ADIN’ sevgi dolu kalpleri

Seninle iken yolumuz geçmez kederden.

Ez yüce tanrım; 

Şükürler olsunki, verdiğin nimetlerle yaşıyoruz

Ele güne muhtaç olmadan, 

Bağışla bizleri, bazen yalancı günlerle şaşırıyoruz

Yanlışın farkında bile olmadan! 

Ey yüceler yücesi; 

Sana olan sevgimi ifade etmeme

Yetmez şu naçizhane dizeler, 

Gözümde tüter doğup büyüdüğüm toprağım

Ezan sesi ve camiiler...', 'Ey büyük allahım;  Nasılda yaratmışsın bizleri  Topraktan, sudan, ateşten;  Sarmış ‘ADIN’ sevgi dolu kalpleri Seninle iken yolumuz geçmez ke...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yuce-rabbime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlar Altında', 'karlar-altinda-hayalet-kral-r38li', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar baharları bitmeyen

Şimdi karlı dağlarımdan sesleniyorum, 

Bu son seslenişim sana, Bak; 

Gözlerine bir çığ gibi düşüyorum.

Kimselere değişemem saçının bir tek telini

Bırak hüzünleri bir başına uzat artık bana ellerini...

Sesimi duymazsan, 

Korkarım aşkım karlar altında kalacak, 

Senden uzaklarda kalemim kağıdımla 

Hayatım gözlerinde son bulacak...', 'Bir zamanlar baharları bitmeyen Şimdi karlı dağlarımdan sesleniyorum,  Bu son seslenişim sana, Bak;  Gözlerine bir çığ gibi düşüyorum. Kimse...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/karlar-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzyıllara Sığmaz', 'yuzyillara-sigmaz-hayalet-kral-km52z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Masal kahramanı olsam bir an

Aşkım uğruna savaşsam diyorum, 

Mutluluğu sana verip kederleri ben alsam

Senin için destanlar yazsam diyorum.

Adına layık bir siir yazabilsem

Kerem ile Aslı’yı kıskandıracak kadar, 

Tükenmeyecek içimdeki yangın birtanem

Söyleyecegim daha çok şeyler var.

Söyleyeceklerimi değil günlere

Aylara, yüzyıllara sığdıramazsın, 

Gel harap etmeyelim aşkımızı

Böyle bir aşkı ömrünü versen bulamazsın...', 'Masal kahramanı olsam bir an Aşkım uğruna savaşsam diyorum,  Mutluluğu sana verip kederleri ben alsam Senin için destanlar yazsam diyorum. A...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuzyillara-sigmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basit Şair', 'basit-sair-ali-saglam-3-6ajw2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben dört heceli hayatın. 

Basit şaiiriyim, 

Basit şiirlerin

Basit kelimelerin, 

Hırçın sesiyim...

Eleştirilecek yanı yok şiirlerimin, 

Şiir olduğundan bile şüpheliyim, 

Daha güzeli arasamda, 

Kimbilir ne zaman bulabilirim, , , 

Aşklar basit''e kaçtıkça, 

Dostluklar basit oldukça, 

Basit basit kaldıkça, 

Utanmıyorum! 

Ben basit şaiirim...

Ben basit şaiirim...

Eleştirilmeye bile değmez, 

Yüreğimde ''Küçük İskender'' fırtınası, 

Aklımda ''Cezmi Ersöz'' oldukça...

Şiir''im koca çınar olur...

Hiçbir şeye boyun eğmez...', 'Ben dört heceli hayatın.  Basit şaiiriyim,  Basit şiirlerin Basit kelimelerin,  Hırçın sesiyim... Eleştirilecek yanı yok şiirlerimin,  Şiir ...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/basit-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Parmak İzin Var.', 'senin-parmak-i-zin-var-hazni-cetin-y8w0o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin ile elele bir yuva kuracaktık

Sevgiye giden yolun adresi olacaktık

Hani Aşka Sevdaya bir ömür doyacaktık? 

Bana oyun oynadın belanı bulacaksın

Hani Kar tanesi değil Koca Dağdı Sevdamız? 

Hani Baharın rengi Yeşil Bağdı Sevdamız? 

Keremle Aslı gibi Hani Aştı gıdamız

Aşkımızı öldürdün diyet ödeyeceksin

Nasıl ihanet ettin o Güzel anılara

Mahkum ettin Ömrümü çekilmez acılara

Aydınlıktı Önümüz gömdün karanlıklara

Sevdamızı öldürdün Cezanı çekeceksin.

Şeke şüpheye yer yok katil sensin Güzel Yar

Aşkımızın katlinde Senin parmak izin var....', 'Senin ile elele bir yuva kuracaktık Sevgiye giden yolun adresi olacaktık Hani Aşka Sevdaya bir ömür doyacaktık?  Bana oyun oynadın belanı bu...', ARRAY['Türk Edebiyatı','Şiir','Hazni Çetin']::text[], 8.5, '{"poet":"Hazni Çetin","poet_slug":"hazni-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/senin-parmak-izin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-hayalet-kral-qwlyo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tam yaşamaya başlamışken

Hayatın inişlerini çıkışlarını, 

Unut, unutabilirsen beni ey sevgili

Kapat yattığın odanın ışıklarını.

Rüyama gir buğulanan hayalinle

Ayak basılmamış diyarlar bulalım, 

Erişelim mutluluk tepelerine

İnsanlara toz pembe masallar anlatalım.

Yemyeşil kırların ortasında

Masmavi deniz berraklığında

Hür ve güçlü kılalım sevgimizi

Göçmen kuşlar kanat çırptığında.

Her sabah korkuyla uyanırım

Allahım hiç bitmesin bu rüya, 

Dönme bensiz sakın

Şimdi mışıl mışıl uyuduğun odaya.

Son bulmasını istemediğimiz

Her güzel şey çabuk bitermiş, 

İnsanı hayata bağlayan

İçten dostluklar, gönülden sevgilermiş.

Yine gün ağarıyor, güneş doğuyor

Saçların tımsali aynı yerden, 

Dudakların usulca ‘Elveda’ diyor

Kokusunu önceden aldığım hüzünlerden! ...

Sabahın ilk aydınlığı ile ‘Dur’ desemde

Küçük bir tebessümle doludizgin gidiyorsun, 

Ben halen bıraktığın yerdeyim

Şimdi sen çizgini kendin çiziyorsun...

İşte; hayalde rüyada olsa

Yaşadık beraber yaşanmayanları, 

Bir gece değil, bir ömür böyle son bulsa

Dolaşırım seninle hep aynı rüyaları...', 'Tam yaşamaya başlamışken Hayatın inişlerini çıkışlarını,  Unut, unutabilirsen beni ey sevgili Kapat yattığın odanın ışıklarını. Rüyama gir b...', ARRAY['Türk Edebiyatı','Şiir','Hayalet Kral']::text[], 8.5, '{"poet":"Hayalet Kral","poet_slug":"hayalet-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ruya-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunun 24. Saati', 'yoklugunun-24-saati-onur-uysal-ltmhj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgilim, 

Mektubunda, 

Neler yapıp ediyorsun, 

neler hissediyorsun demişsin.

Her bir satırını okuduktan sonra 

defalarca ve doyasıya

Karar verdim içimi sana açmaya.

İşte yapıp ettiklerim, 

Yokluğunun yirmi dördüncü saatinde 

işte sana karşı hissettiklerim...

Özlüyorum seni, hem de delicesine, 

Öyle böyle değil, tükenecek gibi hiç değil, 

Bir özlem ki, 

Yirmi saatinde günümün, sen vardın aklımda, 

Yemek yerken oturdun karşımda, 

Ve eksik olmadın hiç, dost sohbetlerinin arasında.

Ne yazık ki sensiz kaldım dört saat, 

Seni düşünmekten yorgun düşüp sızdığım

				salondaki koltukta.

Merak ediyorum seni, hem de çıldırasıya, 

Vardın mı yerine, yerleşebildin mi? 

Yeni gördüğün yerlerin tadını çıkarabildin mi? 

Rahat bıraktı mı seni sarhoş Finliler, 

		o çöp bacaklı sarı civcivler? 

Ve bakıp da otobüsün penceresinden uzaklara, 

Ya da giden bir geminin pruvasında

Görebildin mi beni, 

Ayrılırken ıslak unutup gittiğin gözlerimi? 

Ve hüznü var biraz da içimde yarım kalmışlığın, 

Kocaman bir sevdayı iki aya sığdırmışlığın.

Yılların dostları senle tanıştırılmayı, 

Boğazın balıkları güzel ellerine yakalanmayı, 

Adalar, ve ada insanı senle tanışmayı, 

Bizim için yazılmış şiirler -elbet mum ışığında-

	kulağına fısıldanmayı bekliyorlar.

Ve cazın en güzel parçaları, 

Çalınmadı henüz, çalınmıyor

Dans salonları illa ki seni istiyor...

Ve mutluyum, memeye saldıran bebeler gibi

Ya da çölün ortasında, 

dayanmanın son noktasında

Pınara koşan gezginler gibi.

Mutlu olmaz mı insan, 

Buluverince birden karşısında, 

Gözlerinde kaybolup giden heyecanı, 

	yıllar yılı arayıp da bulamadığını.

Umuttur sevdiğim bir de, 

Parıltılı gözlerde taşıdığım.

Bize dair hayallerdir beni umutlandıran, 

Elimi uzatınca dokunacak kadar yakın olan.

Onlarca kez gittim seninle memleketin doğusuna, 

Çoktan gezdirdim seni Antalya sokaklarında, 

Ve fark etmedin biliyorum ya, 

Şu salonlarda çınlanan alkışlar bizedir, 

Tangonun en ateşlisi elbet bizim eserimizdir.

Geldim sözlerimin sonuna, 

geldim duyguların en tutkulusuna.

Arzudur içimi yiyip bitiren

Ve her türlü hissin önüne geçen.

Hiçbir şeye değişmem bilesin, 

Koyun koyuna geçen küçücük bir anı

Dibine kadar yaşadığımız zamanları.

Bunlardır içimde hissettiğim, 

Bunlardır sana söylemek istediğim.

Ve ne yazık ki sözlerden başka bir şey kalmadı

Sana bu kadar uzakken verebildiğim.', 'Sevgilim,  Mektubunda,  Neler yapıp ediyorsun,  neler hissediyorsun demişsin. Her bir satırını okuduktan sonra  defalarca ve doyasıya Karar ...', ARRAY['Türk Edebiyatı','Şiir','Onur Uysal']::text[], 8.5, '{"poet":"Onur Uysal","poet_slug":"onur-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/yoklugunun-24-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil ki', 'bil-ki-nami-keskinbora-no5fq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günün birinde beni özlersen gökte ara! 

Yıldızımla beraber belki dolaşmaktayım.

Gökyüzü çalıyorken bir kızıla, bir mora, 

Belki de yağmur gibi süzülüp akmaktayım.

Gökyüzünde yıldızlar ışıldamakta parlak, 

O benim Yıldız''ım ki: En güzel ve en berrak.

En süslü renkleriyle Yıldız''a yakışacak, 

Bahar çiçeklerinden bil ki taç yapmaktayım.

Bil ki güzelliğine bakıp da dalmaktayım, 

Yalnız onunla iken sonsuz zevk almaktayım.

İnan ki, o Güzelle pek mutlu olmaktayım.

Haber alamıyorum, ''nasıldır? '' meraktayım.', 'Günün birinde beni özlersen gökte ara!  Yıldızımla beraber belki dolaşmaktayım. Gökyüzü çalıyorken bir kızıla, bir mora,  Belki de yağmur gi...', ARRAY['Türk Edebiyatı','Şiir','Nami Keskinbora']::text[], 8.5, '{"poet":"Nami Keskinbora","poet_slug":"nami-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bil-ki-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-kadircan-keskinbora-0rb6d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşamın kaynağı sevgi, 

Sevgi tutku, 

Tutku amaç, 

Amaç paylaşmak, 

Paylaşmak dostluk, 

Dostluksa hatırlamak.

''Aklımdasın.''', 'Yaşamın kaynağı sevgi,  Sevgi tutku,  Tutku amaç,  Amaç paylaşmak,  Paylaşmak dostluk,  Dostluksa hatırlamak. ''Aklımdasın.''...', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevmek-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onsuz', 'onsuz-nami-keskinbora-ungku', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neş''e benden uzakta, dertler bana zevk oldu, 

Hayat ne kadar zalim, gülüm çiçeğim soldu.

Ömür, doldur küpünü acılardan, kederden, 

Onsuz yaşıyor diye gönül zaten dert doldu.', 'Neş''e benden uzakta, dertler bana zevk oldu,  Hayat ne kadar zalim, gülüm çiçeğim soldu. Ömür, doldur küpünü acılardan, kederden,  Onsuz yaş...', ARRAY['Türk Edebiyatı','Şiir','Nami Keskinbora']::text[], 8.5, '{"poet":"Nami Keskinbora","poet_slug":"nami-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/onsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-kadircan-keskinbora-8rhpc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimde silinmez hayalle kal sevgilim! 

Aşkını ta kalbime, ruhuma sal sevgilim! 

Hoşsun, canımın içi, o kadar tatlısın ki; 

Gönlüm senin peteğin, sen onda bal sevgilim.', 'Gözlerimde silinmez hayalle kal sevgilim!  Aşkını ta kalbime, ruhuma sal sevgilim!  Hoşsun, canımın içi, o kadar tatlısın ki;  Gönlüm senin ...', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgilim-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem (1)', 'sitem-1-nami-keskinbora-jp4ff', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Madem ki hercai bir aşkın vardı, 

Neden bana verdin ey zulmü seven? 

Gözüme gönlüme taarruz eden, 

İçimi kavuran bakışın sardı.

Gözlerim o günden şimdiye kadar,

Görmemecesine bir başkasını,

Kavuşamamanın tutar yasını,

Dinmemiş, hala ilk ağrıyla yanar.', 'Madem ki hercai bir aşkın vardı,  Neden bana verdin ey zulmü seven?  Gözüme gönlüme taarruz eden,  İçimi kavuran bakışın sardı. Gözlerim o g...', ARRAY['Türk Edebiyatı','Şiir','Nami Keskinbora']::text[], 8.5, '{"poet":"Nami Keskinbora","poet_slug":"nami-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sitem-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahların İşlendiği Yerde', 'gunahlarin-i-slendigi-yerde-mine-hoscan-bilge-y2vqf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana beni ne kadar yalancı olduğumu söylemişmiydim

Seni çoktan unuttuğumu

Seni hiç görmek istemediğimi

Söylemişmiydim zaten seni hiç sevmedim

Ellerini tutmak 

Seni doyasıya öpmek istemiyorum

Gözlerine bakıp bakıp dalmak

Sabahlara kadar uykusuz kalmak istemiyorum

İstemiyorum seni. Sevgini

Yollarını gözlemek her gece ağlamak

Kollarında uyumak istemiyorum

Seni hayal edip uykularıma girmeni

Bana gülmeni istemiyorum

İstemiyorum seni. Sevgini

O dokunuşunu

Bana sarılışını

Tenimin teninle buluşmasını

İstemiyorum

Beni arama

Benimle konuşma

Seni seviyorum deme

İstemiyorum,  istemiyorum

Bak gene yalan söyledim

Seni sevdiğimi gizlemek istedim

Gene beceremedim.', 'Sana beni ne kadar yalancı olduğumu söylemişmiydim Seni çoktan unuttuğumu Seni hiç görmek istemediğimi Söylemişmiydim zaten seni hiç sevmedi...', ARRAY['Türk Edebiyatı','Şiir','Mine Hoşcan Bilge']::text[], 8.5, '{"poet":"Mine Hoşcan Bilge","poet_slug":"mine-hoscan-bilge","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gunahlarin-islendigi-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birinci Temrin: Kurban', 'birinci-temrin-kurban-selim-temo-fvhjy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Süleyman öldü, yaşasın şakir! 

şimdi şiir dediniz biri sıkılıp gitti

bendim o sefil üşümüş elinizde

belki çok şey değildir aşkın ölümü

gerekirse aranır öpülmüş resimlerde

Japon bir sevgilim var -demek sizin de

makyajlı bir Meryem gibi yitirmiş masumiyetini

kiss diyor sex anlıyorum niyeyse

merdivenim belki de onca bol ihanetten 

garsonu vurun lütfen çok tıkırtı yapıyor

doğru ya saat şu kaşar resmiyeti

dilimledi durdu en nazik günlerimi

bazen de kıştı sakın bir dakka

Gilda posterimi öpmeyin çok kıskancımdır

ben sevdim mi çamına korum yorgun akşamlarda

ekşın aktörleri gibi abazan kalırım

hadi lale ezelim biri paydos mu dedi

neden sakinsin kahrolası duygusal cin

ezan okuyor varoşlar faşist içinde

ve seçkinler cümle piçleri orta sınıfın

devlete koşuyorlar uygun adımla bir kii

sıfır hasarla marjinal cahil tenyalar

oysa müezzin gibi bekledim sendeleyerek

ağzımda tuz sustum kaç ışık yılı

sakalımda sevimli beyazlar erittim suya

kudurdu yaramdaki kurt o kiralık keder

bennn bakımsız Şakir çarmıhına gönüllü

baba sirklerinde çocuk ol hikayat-ı semender

ağladı dizlerim yassı bir cüret halinde

balkonda mıyız neyiz üç bira bir yahudi', 'Süleyman öldü, yaşasın şakir!  şimdi şiir dediniz biri sıkılıp gitti bendim o sefil üşümüş elinizde belki çok şey değildir aşkın ölümü gerek...', ARRAY['Türk Edebiyatı','Şiir','Selim Temo']::text[], 8.5, '{"poet":"Selim Temo","poet_slug":"selim-temo","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/birinci-temrin-kurban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinnet A.Ş.', 'cinnet-a-s-duygu-gunkut-vln2s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küçük bir işimiz var, 

Kendi cinayetlerimizi

Gömen bir servis kısaca.

İşin adı bile alıntı, 

Kuzenimden

Kelimelerle ismlendirmede

Fazlasıyla iyi

Eski bir gazeteciden.

Nitekim, 

Çok müşterimiz de oldu

Kendi cinayetlerini

Başkalarına anlatmak isteyen, 

Değişti bizim işin boyutu...

Uğursuzluklar, 

Batıl inançla, 

Karamsarlık, 

Hüsran ve üzüntüdür

Çalışanlarımızı

Hayata bağlayan.

İş motivasonudur

Hepimizin

Başarısızlıklar.

Hırsızlığın

Çok beğenildiği, 

Cinayetlerin bile çalındığı

Bir ülkemiz var.

Cinnet A.Ş.

Bizim küçük işimiz, 

Bu büyük ülkede, 

Kendi cinayetlerimizi bari

Kaptırmayalım hırsızlara diye

Gömmeye çalışan.', 'Küçük bir işimiz var,  Kendi cinayetlerimizi Gömen bir servis kısaca. İşin adı bile alıntı,  Kuzenimden Kelimelerle ismlendirmede Fazlasıyla...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cinnet-a-s-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnci Tanem', 'i-nci-tanem-baris-temel-qb6c5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gece gelsem kapını calmadan, 

içeriye girsem tatlı uykunda, 

sokulup gizlensem kuytunda, 

koklasam seni gül gibi İNCİ TANEM.

Gölgen olsam yanında, 

Gitme diye sarılırmısın, 

seni bırakıp gidersem, 

bana küsüp darılırmısın İNCİ TANEM...', 'Bir gece gelsem kapını calmadan,  içeriye girsem tatlı uykunda,  sokulup gizlensem kuytunda,  koklasam seni gül gibi İNCİ TANEM. Gölgen olsa...', ARRAY['Türk Edebiyatı','Şiir','Barış Temel']::text[], 8.5, '{"poet":"Barış Temel","poet_slug":"baris-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/inci-tanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim', 'yuregim-nese-bora-wrl8s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hala onun peşindesin, 

yalvardım dinlemedin yüreğim

sen istedin bitirdim, 

hala sözünde değilsin yüreğim.

geçer dedim, unutursun dedim

dinletemedim.

O bir yalancı, 

nafile..

O bir kalp hırsızı, 

boşuna...

neden dinlemedin beni yüreğim.

Ellerin onun elleri, 

gözlerin onun gözleri, 

nefesin onun

ne istedin benden yüreğim

Gece rüyanda, 

gündüz hayalinde 

kurtul ondan yüreğim.

sen istedin ben bitirdim

niyedir zorlaman yüreğim.

Bırak artık onu, 

umutlar, ümitler

hepsi yelken açtı senden önce ufka.

dinlememeliyim seni artık yüreğim

ne olur bir dur, bir kere dinle

atma artık bu kadar deli gibi

o bitti, dinmeli artık bu sevda seli

yalnız senmisin aşık olan, 

bak niceleri var unutan

nedir bu hayasız isyan? 

sen istedin ben bitirdim, 

niyedir zorlaman yüreğim', 'Hala onun peşindesin,  yalvardım dinlemedin yüreğim sen istedin bitirdim,  hala sözünde değilsin yüreğim. geçer dedim, unutursun dedim dinle...', ARRAY['Türk Edebiyatı','Şiir','Neşe Bora']::text[], 8.5, '{"poet":"Neşe Bora","poet_slug":"nese-bora","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yuregim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halapçe''li Bir Şairin Son Mısralarına Tanıklık-1', 'halapce-li-bir-sairin-son-misralarina-taniklik-1-eren-tarik-vk9bn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'varsılların ülkesinde bakışları dokuz doğuran güneşim

                                                    bir sis bulutuna takıldım

hadi bu sefer bırakalım 

şehrimize yaslanan zakkumların görüntüsünü

ve burukluğumdan izin alarak 

bütün çocukları üst üste yığalım arkadaşlarım

atisi olmayacaksak onların mazisi hiç olmayalım

            birileri bağırıyor kim onlar

                çok susamış çocuklar

                     çok susamış erkekler 

                         çok susamış kadınlar...

bu oyunun burada biteceği varmış demek

bu kuralı olmayan vahşi oyunun

bu kül ile karışık bu aptal oyunun

şehrimin son görüntüsü olacağı varmış demek

          birileri bağırıyor kim onlar

              yalnız oyuncular

                  deli oyuncular

                      yok oyuncular...

nasıl''a başvuran herkes gibi çaresizim

çürüyen omuzlarıma çare bulacak mı hekimler

işte göğsümün altına (görüyorsunuz degil mi?)    kalbime

işlemiş olan bu görünmez illetin

bu boğazımı sıktıkça susayan illetin

ille de suya dur durak bilmeden suya

mor kelimelerin tenhasından

bir âlâ gökkuşağından bir tanrıçadan

bir oraktan bir başaktan bir ağaçtan

değmesi olasıysa eğer kızılca

kan değen her yer aşktan bir parça

                   birileri kanıyor kim onlar

                          ah kan yok ortalıkta

                           bizimkiler bunlar

                              çok susamışlar

                                 iliklerinden susamışlar

                                       ölümüne susamışlar...

varsılların ülkesinde güneş dağıtan çocuğum

                  öksüzlüğüm duvara çarptı

oyunun bitiminde silahların bırakılacağını duydum

bırakılmadı

ve kesik başlı erkeklerin ağlamasında delindi dünya

tuvali sarı bir hevese kucak açmış bu oyunun 

ismi kasırga

ismi tuhaf aslında; ama yepyeni bir bırakışın sesi

yepyeni savaşım''ın sesi

kasılıp kavrulan bıçak kılıç zehir ve falçata ve

kurşun

ve asi torak ve nehir ve insan

             birileri savaşı değiştiriyor kim onlar

                                       kulelerden bakanlar

                                                 korkanlar

                                                     kankıranlar

içim bir hoş mercan, içim ölüm tuzagında

içim darmadağın bir duman, bir leyla, bir antika

tarih oldum; bir baktım bağdat''a bakyorum

ihtiyar gerdanımı sıktım, delinin biriyim

gaz odasıyım, hitler musolloni veya sisli bir bomba

zehir zemberek çocuklarım avuçlarımda

                    birileri ölümü soruyor kim onlar

                                    tanrım ne çok ölüyorlar

                                              patır patır ölüyorlar

kimi suçlasam önüme kocaman bir ''''ben'''' çıkıyor

şimdi bu tufanda yanan bir ben miyim? 

ve gecelerin alnına izdihamını bırakan bu soluk

sırçalanan etimin deniz kokmasından mı? 

bundan mı sahi kadınlarımın sayısız yaşlanması

bu bir savaş mı

bir anda bütün bir halkın kırılması mı yoksa? 

                                   birileri ölüyor kim onlar

                                         tanrım! çok ölüyorlar

                                                sayısız ölüyorlar

yalnızlığa otağ kuracağım birazdan, ışıklar sönüyor

vardiyalar degişiyor, her biri yeniden bir ölüm

taptaze bir alınganlık

ve bu küflenmiş sandıktan çıkardığım yalnız, 

yapayalnız

dünden bugüne sarkan kekremsi cellatlarım, büyücülerim

bir de sevgilimin eşsiz bakışları

                              tanrım ölüyorlar

                                      çok susayarak!', 'varsılların ülkesinde bakışları dokuz doğuran güneşim                                                     bir sis bulutuna takıldım hadi bu ...', ARRAY['Türk Edebiyatı','Şiir','Eren Tarık']::text[], 8.5, '{"poet":"Eren Tarık","poet_slug":"eren-tarik","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/halapce-li-bir-sairin-son-misralarina-taniklik-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabilem(L) e Nazlı Seslenmeler', 'kabilem-l-e-nazli-seslenmeler-eren-tarik-b8izr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'belki bir çocuk taşıyorum göğsümde

elleri ileriye uzanmış öylece duran köprü

o biçimini rengarenk halklardan alan zamanlardan

o geçişi hıçkırıklarla kutlanan zamanlardan

o adam gibi adamlarla işlenen zamanlardan

kopardığım yassı bir hüzünle kalemimi dirilttim

ve ilkel namluların serüveninden geçtim

sevincim baruttu

elbisem yüzyıllık çınar

yanık kokuyordu göğsüme taktığım herşey

yalnız bir kere haykırabiliyordum benden olanı

iki kere haykırsam hıçkırıklarda boğulurdum

ister istemez gözlerimden çoğalıyordu deniz

rüzgar atını kuytularımdan almıştı

evet ağlıyordum orta çağdan kalma ağıtlarla

kürtçe ağlıyordum, şairler anlıyordu etimin rengini

günahın nemli işvesi altında sırılsıklam bir neron, 

bir iskender hıncıydı gözyaşlarım. 

griyi anıyor kabilem; çoğalan bir büyücüyüm ne de olsa

iyi bir içiciyim, ırmaklarını tükettim

demiri erittim sezgimin alın yazısıyla

belki yalan tüm bunlar, örümcek ağı

belki şairliğim yalan, 

belki derimin cüzamlanışıdır heryer! 

yaktığım tüm serenatlar yalan

ama ağlıyorum ey kabilem 

en çok saksafonla bir ağıtın bileşkesi cıvan haco''yla

en çok zine''nin kırılmış kalbiyle

en çok ortadoğudan yükselen o şeylerle

ve sızımın dinişi bir kentin bitişiydi bu kez

ekmek tutan elimin lalliği sizi şaşırtıyor

karaborsacı dünyalar yüklenmiş hürriyetleri astım

ve uzun boylu hüzünleri (kolay değil)  

bir çırpıda geçtim 

çok gerçek bir şeye değindim alın yazım bu

kana doydum örneğin; 

midemin askısı bir çöle endeksli 

peygamberlerle beraber çembere yakınlığım

ve kar tuttum efendilerim bembeyaz yangını bana sorun

işte görünüyor boynu bükük

yıldızlar kardeş olmuş birbirlerine

güzel görünüyor gerçeğin kucağında ateş

rakkaselerin barutlu belinde kanlı bir bıçak

! 

olmuyor kardeşlerim gerçekten olmuyor

yalandan olmuyor; iki büklüm kaldım kasırgada

kabilemi terk ettim - bir şair başka ne yapabilir? 

menekşe mi toplar cennetlerinden? 

yoksa kendiyle çelişik aşklar mı döller 

en mahrem yataklarda raksederek

ne yapabilir bir şair; göç etmekten başka! 

bir çelimisiz ağlamak tutturdum gidiyor 

büyüyor çocukluğum, sevgilim yağmur

ve yalandan göğsüm bütün sevecenliğiyle

mum gibi açılıyor kökü biraz sıcak biraz soğuk

yine sevimli fakat! kana doydu! 

zine''nin  içli  akdeniz bakışları var! 

asırlar boyu bir içim su bakar gider

çünkü bu sabırsız gökyüzü 

zine''nin fırtınasında bir tuhaf sabır! 

zine''nin türküsüne yaslandım iyice esrik

şimdi ona tanık kaç adam varsa toplansın artık

kaç sakson varsa hepsi birden

bitimin vaktinde yoksullara yetişsin için umut

aş dağıtsın diye körpecik aşıklara

çocuklar gecelerede yıldızlarla eğlendsin diye

çalsın! cıvan haco söylesin! güzelce söylesin

hikayeleri bir bir ve yanık

hikayeleri kürt bakışlı toprak olan

ağlasın barut, namlu geceye yüz

ve üç dilli bir zamana endekslensin hayat! 

ve hançer ve kan ve umut! 

çocuğu anıyor kabilem, ben onu göğsümde taşıyorum!', 'belki bir çocuk taşıyorum göğsümde elleri ileriye uzanmış öylece duran köprü o biçimini rengarenk halklardan alan zamanlardan o geçişi hıçkı...', ARRAY['Türk Edebiyatı','Şiir','Eren Tarık']::text[], 8.5, '{"poet":"Eren Tarık","poet_slug":"eren-tarik","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/kabilem-l-e-nazli-seslenmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Acı Gibi', 'ask-aci-gibi-ceyhun-kuburlu-6lf85', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün; 

Başıboş yangınlarla

Dolaştım sokaklarda.

Amaçsızca... Birazda...

Yanağımı ıslatan

Damlaları seyrettim, 

Yağmurun gölgesine uzanıp.

Su birikintilerinin notalarını dinledim.

Sonra alabildiğine yürüdüm, 

Bir yere yetişme mücadelesi vermeden, 

Bekleyenim olmadan.

Ellerim cebimde, 

Yankılı bir ıslıkla

Resmini çektim

Romanın son sayfasını

Bekleyen acı gibi aşkın...', 'Bu gün;  Başıboş yangınlarla Dolaştım sokaklarda. Amaçsızca... Birazda... Yanağımı ıslatan Damlaları seyrettim,  Yağmurun gölgesine uzanıp. ...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-aci-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Yeni''deki Ruh Yansımaları-1', 'i-kinci-yeni-deki-ruh-yansimalari-1-eren-tarik-mexei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şarkısını tutturduğumuz kuzey yarımkürenin 

ıslanmış kirpikleri donatıyor yüzümüzü

yalnız, sevgili halkım söyleyişimde bir eksiklik var.

tadını şiirlerle aldıgım soluklanmayı

yine şiir tadında söyleyemem

mesela turgut uyar şöyle seslenmiş sevgilisine

''''bir yağmur yağsa da ıslansak'''' sonra cemal abi

''''işte gidiyorsun git'''' unuyla oyalamış şiiri

benim söylecek sözüm kalmadı yakınımdaki yağmur

benim kalbimin yankısı ol desem çok ağır

benim bileyleyecek gücüm hiç yok

kapılarıma yaslanmış kederli elleri

toparlanıp dizlerini karnına çekmiş karanlık; 

eski zaman şarkısı gibi; hariçten bir gazel gibi

mey gibi; bade gibi; fuzuli baki ve nedim gibi

yuvarlanmış yüzümüzün yarım küresine.

mel''un yahu işte öylece mel''un; kızıştırıyor

kar diyor; belli bir özetlemedir yer için! 

yani kalkıp burada aşk şarkısı yazacak olsam

ilkin; çeki düzen vermem gerek karanlığa

sonra usuldan süzülmem gerek şehir nehirlerine; 

notaların karanlık sokaklarında raksetmem

ve bir o oranda sessiz kalmam gerek

yani kalkıp burada şiir gibi aşk şarkısı söylesem

çok bedelle sipariş etmiş olmam gerek kendime

şöyle kendimin etrafında dönüyorum; 

bulut gibi hafifim alimallah 

biraz daha salınsam; sis olurum

kafam hoş olur ''''sezai karakoç''un'''' ''''ilk'''' şiirinde

ama en çok edip abi kanıma işlemiş ne yalan söyleyeyim

en cok onun mısraları mıh gibi oturmuş kalbime

en çok onun ahmet abisi acıklı bir şarkı

''''ilhan berk''''; adam kafayı yemiş imgeyle 

helal olsun; kafa yenip yazılan şiire

helal olsun imgeye, derin derin soluklanan 

mısrası uçuk bir aşk olan şiire', 'şarkısını tutturduğumuz kuzey yarımkürenin  ıslanmış kirpikleri donatıyor yüzümüzü yalnız, sevgili halkım söyleyişimde bir eksiklik var. tad...', ARRAY['Türk Edebiyatı','Şiir','Eren Tarık']::text[], 8.5, '{"poet":"Eren Tarık","poet_slug":"eren-tarik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ikinci-yeni-deki-ruh-yansimalari-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Yeni''deki Ruh Yansımaları-2', 'i-kinci-yeni-deki-ruh-yansimalari-2-eren-tarik-5vikw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'II

zarifoğlu yayılıyor ortalığa ''''sultan''''ıyla

kement atmak için özel yapmış elbisesini 

yıpranmayan halkalarla donatmış çevrenini

sakal aralığından uzayıp giden şiirini

her haziran alıp öpüyorum kıvrım kıvrım

ece ayhan mıydı Maveraünnehir''in sahibi? 

yani o muydu yüzyirmisekiz! kürt şiirin sahibi! 

''''meçhul öğrenci anıtı'''' nı diktiren eller kimin

kimdi cancığım kimdi ortaokul sıralarında can veren

ölümün çoçuk renlklerini anlatıp

''''solgun halk çocuklarının kalbine''''akan..

kimdi? 

ece ahyan mıydı Maveraünnehir''in sahibi?', 'II zarifoğlu yayılıyor ortalığa ''''sultan''''ıyla kement atmak için özel yapmış elbisesini  yıpranmayan halkalarla donatmış çevrenini sakal ara...', ARRAY['Türk Edebiyatı','Şiir','Eren Tarık']::text[], 8.5, '{"poet":"Eren Tarık","poet_slug":"eren-tarik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ikinci-yeni-deki-ruh-yansimalari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğulu Camlar', 'bugulu-camlar-ceyhun-kuburlu-oxd3w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşmüş bir defa gözlerimizin ucuna, yüreğimize

Ve şehrin karanlık sokaklarında, 

Gizli kalmış lambalara düşmüş sis

O sisli otogarda bir Cuma akşamı 

Bildik bir görüntü; 

Camekanların ardına vuran sevgiler, sevinçler, gözyaşları        

Ve tüm duyguların yaşandığı vakit

Sisli bir İstanbul filmi.

Kim bilir belki sabah postacı çalacak kapımı                 

Son mektup  verecek adressiz.

Belki ayrılığın ilk güneşinde aşık olacak aynı kıza 

Ve aynı mekana

Ve belki de hayatında ilk defa buğulu camları silecek 

Hem de hasret kokarak gözleri

Belki de çayın dumanından çıkan sıcaklıkla selamlayacak güneşi

Ve güneş görmüş tüm gözlere seslenecek ‘camlar buğulu’ diyerek.', 'Düşmüş bir defa gözlerimizin ucuna, yüreğimize Ve şehrin karanlık sokaklarında,  Gizli kalmış lambalara düşmüş sis O sisli otogarda bir Cuma...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bugulu-camlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Yeni''deki Ruh Yansımaları-3', 'i-kinci-yeni-deki-ruh-yansimalari-3-eren-tarik-arr0c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'III

yani şimdi oturup güzelce çarpışacağız

güzelce şarkı okuyacağız ağızlarınızdan

yol gören hanına döneceğiz biraz abartıyla

bir onluk atacağız masaya bahşiş olsun

küfredeceğiz yücel''ciğim; akşamdan bahsederken.

şiir çevirirken masamızda kırmız şarap

masamızda küllük; yar sevinçli mektuplar

masamızda anlık delirmeler bırakarak 

göz açıp-kapayana değin mavi bir şeyler geçecek

kahrolacağız! yahut yakacağız 

aşktan yana olan her nesneyi, her kırılmış çocuğu, 

her özneyi fiillerden uzakta, seyrettireğiz.

zorba olacağız yücelciğim. -yiteceğiz-

kendimizin aynası imgeler toplayarak dünyalardan

dar geçitler bularak, ille de dar geçitler bularak

düşmeyigözönündebulundurarak veya türevinigözealarak 

kahrolacağız yücelciğim

içimizde bir türkiye ağlayacak; ağlasın

içimizde istanbul manzaralı bir kürt ağlayacak

içimizde kükürt kokusu çekilmezliğinde cıva mertliği

hani vaktimize dokunsa demir asaleti 

bir yerlerimnizde bakır dönekliği bırkarak, ağlayacak.

ne yaparsın yücelciğim, şiir bu, çarpışır, ağlar

anlarsın, böyle gelmiş böyle gider; değiştiremeyiz', 'III yani şimdi oturup güzelce çarpışacağız güzelce şarkı okuyacağız ağızlarınızdan yol gören hanına döneceğiz biraz abartıyla bir onluk atac...', ARRAY['Türk Edebiyatı','Şiir','Eren Tarık']::text[], 8.5, '{"poet":"Eren Tarık","poet_slug":"eren-tarik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ikinci-yeni-deki-ruh-yansimalari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Yeni''deki Ruh Yansımaları-4', 'i-kinci-yeni-deki-ruh-yansimalari-4-eren-tarik-doja9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'IV

uysal bir agzım var sevişecek

beynelminel uzaklığında serin vadileri delerek

el yordamıyla karanlığı delerek

delerek delerek delerek şi''rin yağız türküsünü

bir şeyler söyleyecek.

lakırdıdan uzak

''''acz tutan ismi''''yle 

nemrut kasırgasından gecerek

lalelere boyun eğerek; güllere boyun eğerek

gülerek

bir şey söyleyecek 

uysal bir ağzım var dörtnala sevişecek

böylelikle bu şiir devam edebilir!', 'IV uysal bir agzım var sevişecek beynelminel uzaklığında serin vadileri delerek el yordamıyla karanlığı delerek delerek delerek delerek şi''r...', ARRAY['Türk Edebiyatı','Şiir','Eren Tarık']::text[], 8.5, '{"poet":"Eren Tarık","poet_slug":"eren-tarik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ikinci-yeni-deki-ruh-yansimalari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ders Notu Sevdalar', 'ders-notu-sevdalar-ceyhun-kuburlu-c4jfs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamın kaçıncı sayfasındayız

Hangi ırmakta sürükleniyoruz

Ve neyin matematik konumunu ölçüyoruz

Camların ardındaki 

Mili metrik bakışlarla

Hangi limanın sahillerinde 

Kuruyoruz kağıt gemilerin hayallerini

Hangi coğrafi bilginin 

Rüzgarları güney yarım küremizde 

Ve ılıman iklimli mevsim

Neremizde yaşanmakta

Sanırım yaşamın önsözünü

Yeni bitirdik.....

Birkaç güzel el yazı

Hatırası bırakıp gitmiş, 

Camların ardındaki bakışmalardaysa

İşlem hatası yapılmış

Kağıt gemiler fırtınalara 

Terk edilmiş enkaz halinde, 

Ilıman iklimli mevsim sadece 

Benim yüzümde yaşanmaktaymış, 

Ve her sevgiye yetecek 

Kadar bahar biriktirmişim içimde...', 'Yaşamın kaçıncı sayfasındayız Hangi ırmakta sürükleniyoruz Ve neyin matematik konumunu ölçüyoruz Camların ardındaki  Mili metrik bakışlarla ...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ders-notu-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtı Susmalarda Saklı Küheylan', 'bahti-susmalarda-sakli-kuheylan-eren-tarik-kyth9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yayılsın koltuğuna tanburuyla dede efendi

tabut''a yakın çalınacak şeyler vardır belki

bütün tornavidaları eledim yüzümün kelepçelerinde

kirlerimin zengin besmelesi olmasa ne yapardım sanki? 

ne yapardı tamburi dede efendi; caz makamında bir

kürd-i hicaz şarkısı mı çalardı; okyanusu geçerdi belki

boynu bükük bir gökyüzü uzağımdan geçiyor

yıldızlarıyla

sanrılar geçiyor çepeçevre ölümle sarmalanmış

kıyılardan melekler geçiyor

ölüme kaçıyor aşkı sorgulanan bütün leylaklar

ve deniz bir yahudiyi karşılar gibi karşılıyor beni

martılar alelacele ve acemice çığlıklarda kayıp

beynelminel kılıcı yok artık denizin; kan damlıyor

bağlanmış gözlerimde son bir istek peydahlanıyor: 

şehirler diyor kirli esvaplı şehirler! 

bir uzaklaşmak bir yakınlaşmak duran tutkusunda

derisi yüzülmüş şehirler! 

uzak durmalı değil mi bu son ganimetimden.

dünyanın kalp gibi çarptığını hissettim sevgilim

benim bitişimle başladığını hissetim bütün dinlerin

evrenselliğim yıkıldı. dinler başladı insan için

böyle elenmiş sıcaklarla başladı herşey! 

büyük şeyler konuşuyordum alacakaranlıkta

şafağa karşı konuşuyordum dağlar kalemle çizilmiş

uzun bir resim sanılıyordu her bakışta

casuslar sessiz hinlikleriyle

kara kaputlarını giymiş bir hükümdarmışımcasına

peşimsıra koşmaktaydılar

aşksız güneş gözlükleri takıyordular gördüm

ben bu asrın yalnız serüveni 

hantal bakıcısı yüzyılların

şarkılarımdaki melodiye bakın bir şair akacak

hüzün ardı sıra yayılacak o dipsiz vahaya

ve bir yahudi hınzırlığı toslayacak duvara

batının gölgesini doğuya bırakacağı kadar kesin

olasılıklar düşüyor koşuda yorulmuş ayaklarıma

dişil bir titreşimle sarsılıyor baldırlarım

tüy kasılması diyorum bu esmer kırıcılığa

göğsüm  asil bir kan taşımış küheylan

ben böyle anlaşılmaz biriyim işte böyle çavlan

belki töresi azizliğe uğramış bir aydın sofrasından

bir gün batımından etkilendim ve yaktım benliğimi

kül ve kuşlar

kül ve aşklar

kül ve hayatlar benden sonra! 

güneşini arayan benlik kuşların son şarkısını söylüyor

arıyorum devasa olan her yeri, her imge birer altın

görüyorum ölüme yakın gözlerimle

tüm büyük olanların altında turkuaz bir kan

bütün şiirlere baktım bütün şiirlerde kan 

ellerde kan adamlarda kan ve tanbur

dede efendi susmaya sıra geldi degil mi? 

şimdi susabilirim bir yahudinin sustuğu gibi', 'yayılsın koltuğuna tanburuyla dede efendi tabut''a yakın çalınacak şeyler vardır belki bütün tornavidaları eledim yüzümün kelepçelerinde kirl...', ARRAY['Türk Edebiyatı','Şiir','Eren Tarık']::text[], 8.5, '{"poet":"Eren Tarık","poet_slug":"eren-tarik","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/bahti-susmalarda-sakli-kuheylan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralar', 'yaralar-ceyhun-kuburlu-byyqv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En zor çıraklığını yapıyorum

Gülüşlerimin

Usta bir öğreticiden yoksun

Kolunu, bacağını, kanatan

Bir çırağım

Ve sırf çırak olduğumdan

Tüm gülüşlerim

Kısa bir süre sonra 

Ayrılıyor; 

Yüzümün gövdesinden', 'En zor çıraklığını yapıyorum Gülüşlerimin Usta bir öğreticiden yoksun Kolunu, bacağını, kanatan Bir çırağım Ve sırf çırak olduğumdan Tüm gül...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yaralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filim Bandı Aşk', 'filim-bandi-ask-ceyhun-kuburlu-ufxxs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangi dile çevrilemez 

Sevda başlıklı öyküler

Ve çocukların gizli kalmış 

Oyun bahçelerinde

Hangi şarkılar söylenir.....

Dokunmanın yakınlığında

Sevginin uzağındayken

Bir yolda yürümek kadar uzak mıdır Aşk...

Ya da hiç duymadığımız 

Bir klasik sonbahar mıdır 

Öykünün kapağında ki mevsim...

Ve oyun bahçelerinden, 

Öksüz gökyüzüne kadar

Uzanan bir film bandıdır

Yaşamın gizemindeki Aşk...

Çocukluğumuzun yarım kalmışlığı gibi AŞK...', 'Hangi dile çevrilemez  Sevda başlıklı öyküler Ve çocukların gizli kalmış  Oyun bahçelerinde Hangi şarkılar söylenir..... Dokunmanın yakınlığ...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/filim-bandi-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk aşk', 'i-lk-ask-hidir-baspinar-fo1e1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne güzel başlamıştı seninle aşkımız

Gözlerimiz  ayrılmıyordu ellerimiz gibi

Ellerinin elime deydiği anda yüreğindeki

Dev bir dalgayla boğuşurcasına yürekli

Bir anda aklından geçenleri hissetmesi

Yüreğindeki çarpıntının şiddeti onu ilk 

Kez öptüğümde kafasından kızgın sular

Akıyormuş gibi hissetmesi nedendir.

Bilemem ilk kez aşık olmasıydı  belkide

Yalnız günlerimi paylaştığım sen

Kış soğuk, titreyiş ve dinmeyen

Lanet ses şimdi üşüyen ayaklarımı

Sen olmadan da ısıtabilirmiyim ki

İçime doğru çekip bedenime sarılıp da

Kafama yorganımı çekip tüm nefesimi

İçime verişim yeterli olmuyorken

Seni düşünüp terliyorum adeta

Yalnızlığı bir balıkçı kayığını inceleyi

Atıyorum martının 

denize süzülüşünü

Kendimce yorumlayıp ve  ne kadar saf

Hey sevgilim sende bu kadar temizsin

Seni benden çok seven insan adını 

Kumsala yazıp dalganın hızından 

Silinmesine engel olandır diyorum 

İlk aşkım seni seviyorum.....................', 'Ne güzel başlamıştı seninle aşkımız Gözlerimiz  ayrılmıyordu ellerimiz gibi Ellerinin elime deydiği anda yüreğindeki Dev bir dalgayla boğuşu...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Başpınar']::text[], 8.5, '{"poet":"Hıdır Başpınar","poet_slug":"hidir-baspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ilk-ask-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Gökyüzü', 'bir-baska-gokyuzu-eren-tarik-j6as2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şiir miydi! ama yok yok bilirim: 

en güzel gökyüzüdür yüzün 

mavi bakar ucuruma, dipsiz 

mavi bakar gözleriyle leyl(a)   (k)  

& 

yankı oluyor avuclarımda 

yassı düşlerde konaklayarak 

en güzel gökyüzüdür yüzün 

şiir miydi, o masmavi şehir 

kanırtılır mıydı evimizin göçer kuşları 

martıları da göçer miydi yolumuzun 

en güzel kar bizim beyazımızdı değil mi 

ikiye sıfır ekleyerek tekrar tekrar; bölerek ikiye 

ikiye çömelişi ekliyerek ama ikiye 

bire dönüşün hülyasımıydı dudağımızdaki sıcaklık 

& 

kansız; kancıksız; ağlamaksız bir şiir olsun 

istiyordum belki de 

kırmızısız bir şiir 

istiyordum be kuzum; yani duvağımla duvagın 

gözlerimle gözlerin 

ellerimle ellerin dert görmesin 

yani istiyordum; harbiden istiyordum 

sinema heyecanları, tiyatrolar, sahil düşleri 

günbatımları, süslesin bu şiiri 

bu şiiri düşümüzle onarmak istiyordum 

topragımızla; adam akıllı kerpiç damlarımızla 

dogu''muzla kutsayarak 

batı''mızı yıkayarak hintli bir kadın 

veya japon, malezyalı bir yüz; darmadagın ve memnun 

darmadağın ve mesut darmadagın ve yüzün 

darmadağın, napolili keşişin ayiniyle toparlanan 

bir şarkı olsundu 

ve hiç durmasındı için; kayıklar nehirler aksındı 

kuşlar güzelleştirsindi yüzünü, yani tam da böyle 

tam da senin kenarları işlemeli yazmana vurularak 

kürt kızarışlar beslesindi 

hiç bitmesindi bu şarkı hiç bitmesindi 

işçiler memnun kalsındı geceleri eve giderken 

salyangoz satıcısı müslümanlarla iyi geçinsindi 

nehirler aksın aksın akısındı 

için bir şiir düşlüyordum ölümsüz 

öksüz yaşlanmalar dilemiyorum sana 

yetimlikler dilemiyorum mutsuzluklar dilemiyorum 

bitiştirmiyorum bütün bu kücük şeyleri 

küçük şeyleri hoş karşılamıyor cünkü gökyüzü 

gökyüzü ve mavi ve kızıl ve mor ve siyah 

gökyüzü yani yüzün 

temeli avuclarımda kalsın 

ne demiş cemal süreyya 

''''üstü kalsın'''' 

bembeyaz gökyüzüdür cünkü yüzün.', 'şiir miydi! ama yok yok bilirim:  en güzel gökyüzüdür yüzün  mavi bakar ucuruma, dipsiz  mavi bakar gözleriyle leyl(a)   (k)   &  yankı oluy...', ARRAY['Türk Edebiyatı','Şiir','Eren Tarık']::text[], 8.5, '{"poet":"Eren Tarık","poet_slug":"eren-tarik","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/bir-baska-gokyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz karanlık', 'sensiz-karanlik-hidir-baspinar-8a8li', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece yarısı saat yalnız ’ı karanlık geçiyor.

Dışarıda kimseler yok hepsi susmuş yatıyor.

Tahta kalemime sarılıp üzerine oturduğum; 

Eski kırık sandalyeden  beyaz sayfalara.

Yazıyorum yazdıklarımı beğenmeyip.

Siliyorum taburemden gelen gıcır gıcır.

Sesler daha zorlama beni kırılacağım.

Dercesine titriyor dur kimseler uyanmasın.

Silmiyorum seni artık sessiz yazıyorum.

Kendime soruyorum acaba benim için; 

Kalemini oda terletecek mi? 

Ay gece karanlığını azaltıyor sanki 

Hava aydınlanmak üzereyken susuyorum

Kuşların güzel sesleri hep artıyor.

Artık yatmalıyım sabah oluyor.

Sevgililer görünür birazdan el ele 

Kendimi bir akşam sefasına benzetirim

Gece açan gündüz çiçeklerini kapayan

Şimdi gün yüzünü gösteriyor bense; 

Aydınlık sabahla karanlığa dalıyorum', 'Gece yarısı saat yalnız ’ı karanlık geçiyor. Dışarıda kimseler yok hepsi susmuş yatıyor. Tahta kalemime sarılıp üzerine oturduğum;  Eski kır...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Başpınar']::text[], 8.5, '{"poet":"Hıdır Başpınar","poet_slug":"hidir-baspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sensiz-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlarken', 'baslarken-eren-tarik-lzxof', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalın anlatımla eğer başlamak gerekirse söze: 

her ordu en az bir kez bozguna uğramıştır tarihinde', 'yalın anlatımla eğer başlamak gerekirse söze:  her ordu en az bir kez bozguna uğramıştır tarihinde...', ARRAY['Türk Edebiyatı','Şiir','Eren Tarık']::text[], 8.5, '{"poet":"Eren Tarık","poet_slug":"eren-tarik","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/baslarken-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adının Yalanı', 'adinin-yalani-ceyhun-kuburlu-9huhg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şiirin son cümlesisin, 

Bir daha anılmayacaksın sohbetlerde, 

Bir daha duyulmayacak sesin duraklarda, 

Bir daha karanfillerle karşılanmayacaksın.

Biliyorum; 

Bu sevda ağır geldi, 

Eşine hiçbir yerde rastlanmayan yalanlarına.

Bir daha bakamayacaksın gözlerime, 

Bir daha bu kenti güzel göremeyeceksin, 

Bir daha gelemeyeceksin.

Biliyorum; 

Bu sevda ağır geldi, 

Eşine hiçbir yerde rastlanmayan yalanlarına.

Çünkü adın en çok, 

Bu şiirin yalanlarında güzel durdu.

Benim yalanlarım 

Seninkilerden daha berrak olsa gerek

Yalanlarımda tüm güzelliğini görür oldum...

(NİSAN 2002)

(İSTANBUL)', 'Bu şiirin son cümlesisin,  Bir daha anılmayacaksın sohbetlerde,  Bir daha duyulmayacak sesin duraklarda,  Bir daha karanfillerle karşılanmay...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adinin-yalani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islığım Ömrümün Uçurumundayken', 'isligim-omrumun-ucurumundayken-ceyhun-kuburlu-uuxrh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nisan yağmurunun tutsak aldığı İstanbulda

Dışarı da usulca güneş süzülür

Bir tarafta sağanak başlar

Sokaklar tarih kokar, 

Çocukluk başımızda dans eder, 

Islığım ömrümün uçurumundayken 

Gitmek lazım İstanbul un güzelliğinden 

Ezberimdeki hayatı unutmadan

Bir kez olsun ettiğim yemini tutma zamanıdır.....

Mutluluğu sarabilmem için hayatıma 

İnsanlığın hayat öğelerini çözebilmeliyim önce, 

Sonra hüznü cellatların

Cinayet saatlerine atmalıyım, 

Kuşların azaldığı ikindi saatlerinde

Gülleri açtırmalıyım dağlarda

Akşam kızıllığına, 

Mutluluğu sarabilmem için hayata 

Baharda uçurtmaları seyretmeliyim

Geceleri yolculukları azaltmalıyım

İstanbul un kirli kimliğini

Issız bir mezara gömmeliyim.

Evet  ıslığım ömrümün uçurumundayken

Gitmek lazım İstanbul un güzelliğinden 

Ezberimdeki hayatı unutmadan 

Bir kez olsun ettiğim yemini tutma zamanıdır.....', 'Nisan yağmurunun tutsak aldığı İstanbulda Dışarı da usulca güneş süzülür Bir tarafta sağanak başlar Sokaklar tarih kokar,  Çocukluk başımızd...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/isligim-omrumun-ucurumundayken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İspanyol Yosmalı Sabah', 'i-spanyol-yosmali-sabah-ceyhun-kuburlu-rl35p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saat sabahın beşi

Bir İspanyol kırmızısı gökyüzü

Elimde bir İstanbul hatırası

Bir özlem kitaplarda

Şehir radyosunda sözsüz bir nota

Yollarda dokunaklı bir sabah

Saat sabahın beşi

Bir İspanyol kırmızısı gökyüzü

Denizin gidip gelmesinde gözüm

İspanyol bir yosmanın

Saçlarında elim 

Bir İstanbul sevdasında gönlüm

Yasak şarkıların buğulu

Buğulu imzalarında sözüm...

Saat sabahın beşi

Bir İspanyol kırmızısı gökyüzü...', 'Saat sabahın beşi Bir İspanyol kırmızısı gökyüzü Elimde bir İstanbul hatırası Bir özlem kitaplarda Şehir radyosunda sözsüz bir nota Yollarda...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ispanyol-yosmali-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerelerdesin Kırçiçeğim', 'nerelerdesin-kircicegim-ceyhun-kuburlu-ffjdc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şiir altında hüzünlü bir gece

Her gecenin içinde eskitilmiş şarkılar

Tüm bunların gerçeğinde

Küçük bir aşk ve güzel bir kız yatar

Şimdi her şiirin mürekkebinde

Şarkıların dilinde

Gecenin loş karanlığında sen varsın

Düşlerimin kır çiçeği nerelerdesin', 'Her şiir altında hüzünlü bir gece Her gecenin içinde eskitilmiş şarkılar Tüm bunların gerçeğinde Küçük bir aşk ve güzel bir kız yatar Şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nerelerdesin-kircicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Mevsim', 'zamansiz-mevsim-ceyhun-kuburlu-cuzy6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerden başladı 

Böyle zamansız 

Bu sağanak 

Şimdi yine her yer ıslak yani

Her yer çamur 

Ve içinden çıkamadığımız 

Bir İstanbul klasiği demek

Bütün sonbaharlarını 

Yaşadım sanıyordum AŞKIN

Oysa yaşanmadık 

Bir sen kalmışsın 

Beşinci mevsimde

Sonuna inceltme işaretini koymadığımız 

Bir sen demek...

Nerden başladı

Böyle zamansız 

Bu sağanak

Bu yağmur neyin nesidir şimdi

Anlaşılan bu mevsimde uzun geçecek

Ağaçlar erken çiçeklenip

Geç meyvelenicek

Ne olurdu bilmem 

Bir mevsimi zamanında yaşasaydık

Mesela zamanında ıslansaydık

Ve geç kalmasaydık 

Gün batımı İstanbul’a

Bu sağanak 

Bu ansızın yağmurlu mevsim

Sis çökmüş şehir

Ve ansızın sen 

Mevsimsiz ağaçlar 

Gibi çiçeklendik', 'Nerden başladı  Böyle zamansız  Bu sağanak  Şimdi yine her yer ıslak yani Her yer çamur  Ve içinden çıkamadığımız  Bir İstanbul klasiği deme...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/zamansiz-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Olan Ne Vardı', 'yanlis-olan-ne-vardi-ceyhun-kuburlu-tf19l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılıklara dair

Hiçbir kelime türetmedi kalemim

Ayrılık adlı hiçbir şiire başlık atmadı ellerim

Ve yağmurlarda hiç yalnız yürümemişti bedenim

Ve bu kadar ıslak değildi yollarım

Daha önce de gitmelerim olmuştu

Uzun yolculuklara çıkmıştım

Edebiyatını, dilini bilmediğim şehirlerin

Yabancı isimli vücutlarıyla sevişmiştim

Denizlerinin, martılarının ve hatta akşamlarının 

Resimlerini çizip

Çiçeklerini okşamıştım

Ve hiç bu kadar soğuk çayların tatsızlığında

Yalanları söylememişti bu dilim

Bir camdan kayan damlayı düşün 

O kadar çabuk geçmişti bu aşk

Peki neydi bu kadar çabuk kuruyan

Aramızda

Açmaya çalışırken ansızın kuruyan neydi

Bu kadar çabuk kurumamalıydı

Çünkü bu aşkta üç mevsim vardı

Adını bile hatırlamaya üşendiğin üç yağmurlu mevsim

Ve içinde filizlenmesine bile izin vermediğin 

Koskoca bir ertesi gün

Hazır düşünürken birde 

Tadı ağzımızda kalan Nisanı düşün

Üzerinden koskoca bir 

Mevsim daha geçmesi gerek şimdi

Yüzümüzde başka bir tenin açması için

(NİSAN 2002) 

(İSTANBUL', 'Ayrılıklara dair Hiçbir kelime türetmedi kalemim Ayrılık adlı hiçbir şiire başlık atmadı ellerim Ve yağmurlarda hiç yalnız yürümemişti beden...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yanlis-olan-ne-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçüncü Temrin: Ardiye', 'ucuncu-temrin-ardiye-selim-temo-368zx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kimse beni oynamasın kaybettim

mesire mahalli aç öpüşler tok öpüşler içinde

ayıldı gururlu bir bardak gibi ay

çözüldü giz kim sadık bir ağzı öpmüş ki

ulan Şakir kötü finnaler buluyorsun her aşka

peripetie mi dedin ben orada değilim

yırttım epey beklemiş dürüst eğilim

ve hürmetli yalınlık eliyle kisvemi

ağlasam mı birileri gibi vakara

skorer gözüyle kaç cima hesabına kârlı

kaybetmek işimdir toplama bilmem

vefaysa iftiradır berabere bitmemiş

bir aşkın uzatma dakikalarında', 'kimse beni oynamasın kaybettim mesire mahalli aç öpüşler tok öpüşler içinde ayıldı gururlu bir bardak gibi ay çözüldü giz kim sadık bir ağzı...', ARRAY['Türk Edebiyatı','Şiir','Selim Temo']::text[], 8.5, '{"poet":"Selim Temo","poet_slug":"selim-temo","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ucuncu-temrin-ardiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önceleri', 'onceleri-ceyhun-kuburlu-w7ay0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Önceleri sınırsızdı

Tüm sevdalarımın kredileri

Ve herkes bir miktar çalıyordu

Habersizce yüreğimden

Ulu orta bırakmıştım 

Tüm sevdalarımı

Şimdi hiçbir aşk

Borç bile vermiyor', 'Önceleri sınırsızdı Tüm sevdalarımın kredileri Ve herkes bir miktar çalıyordu Habersizce yüreğimden Ulu orta bırakmıştım  Tüm sevdalarımı Şi...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/onceleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Kuşları', 'yagmur-kuslari-ceyhun-kuburlu-g6rfj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adı yoktu belki 

Sana yazdığım şiir defterinin

Ne coğrafya defteriydi

Ne edebiyat

Ne zaman yağmur kuşları geçerdi 

Buğulu lise camının önünden

Gitmeler düşerdi

Yazılı saatlerinde aklıma 

Adı yoktu belki 

Sana yazdığım şiir defterinin 

Ne coğrafya defteriydi

Ne edebiyat

Kendi halimizde düşlerimizi mırıldanırdık

Bir türkü düşerdi ağzımıza 

Ağlardık...

Ve ne zaman yağmur kuşları geçerdi

Buğulu lise camının önünden

İstanbul düşerdi 

Yazılı saatlerinde aklıma

Ve adı da yoktu 

Sana yazdığım şiir defterinin

Ne coğrafya defteriydi

Ne edebiyat

Yalnızca adın vardı

Mutluluk yüklü

Lise sıralarının ardında batan.', 'Adı yoktu belki  Sana yazdığım şiir defterinin Ne coğrafya defteriydi Ne edebiyat Ne zaman yağmur kuşları geçerdi  Buğulu lise camının önünd...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yagmur-kuslari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuşun', 'sususun-ceyhun-kuburlu-5h7um', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatın öyle bir yerinde

Susuyoruz ki, 

Deniz hafiften bir dalga, 

Estiriyor saçlarında, 

Rengi zaten belirsiz, 

Bir şiir okunuyor radyoda, 

Sesi solmuş bir fon müziği arkada

Oysa bizim arkamıza 

Alabildiğimiz sevdamızdı, 

Bir çift bakıştı, 

Bu kadar kolay solabilir miydi, 

Ve radyodaki mısralarda

Gitmeli kafiyeler kurulduğunda

Biz bu kadar kolay 

Gide bilir miydik gözlerinden....

Hayatın öyle bir yerinde 

Susuyoruz ki, 

Kekeme sözcükler 

Söylemeye çabalıyoruz, 

Sonra yüzün öyle bir yere dönüyor ki

Martıları gösteriyor gözlerin

Ve kimsesiz sevdiğim

Hayatın öyle bir yerinde

Susuyoruz ki

Geride kalan sadece

Kavuşamayan düşler oluyor.....', 'Hayatın öyle bir yerinde Susuyoruz ki,  Deniz hafiften bir dalga,  Estiriyor saçlarında,  Rengi zaten belirsiz,  Bir şiir okunuyor radyoda, ...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sususun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktaki Sana', 'uzaktaki-sana-ceyhun-kuburlu-ijtwy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saat 22.00, yer Paris, mevsim yaz

Güneş burada geç batıyor yarim

Bir bulut çöküyor

Sonra tepenin ardına vuruyor kızıllık

Yollar uzadıkça diller çoğalıyor

Diller çoğaldıkça seninle özleşiyor kelimeler

Sat 22.00, yer Paris, mevsim yaz

Gözlerin düşüyor yollardaki farlara

Adın geçiyor dost muhabbetlerinde

Türküler söyleniyor sefaletimizde

Ve ben son bir kere daha aşık oluyorum

Ve ben seni son kez seviyorum

Saat 22.00, yer Paris, mevsim yaz

Üç aydır sesini bile duymamış yarim benim

Gözlerinin içindeki umut gülmekte mi

Yoksa ağlamakta mı

Saçlarının rengi hala aynı mı bilmiyorum

Oysa söylenecek öyle çok şey var ki

Kelimeleri birleştirmenin bu kadar zor olduğunu bilmiyordum.

Saat22.00, yer Paris, mevsim yaz

Seni ve şehrimiz İstanbul’u düşünüyordum

Ve sana dair ne varsa özlüyordum

O sırada fark ettim

Otobüsün camına yansıyan başka bir güzellikmiş o

Otobüs koltuğunda yitirdiğim yarim, özür dilerim.', 'Saat 22.00, yer Paris, mevsim yaz Güneş burada geç batıyor yarim Bir bulut çöküyor Sonra tepenin ardına vuruyor kızıllık Yollar uzadıkça dil...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uzaktaki-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Roman', 'yasak-roman-ceyhun-kuburlu-6ph7a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzak denizlerin limanlarında

Bekleyen uyruksuz bir şiirden çıkıp geldim, 

Gözlerinin kafiyesiz sözlerine, 

Bir romana başlıyordum, 

Giriş paragrafında, 

Yasak bir kadına aşık oldum.....

Sevda yüklü bulutlar süzülüyordu 

Bir türlü kavuşmadan geçiyorlardı, 

Suskun çocuğun yüreğinden, 

Bir romana başlıyordum

Giriş paragrafında, 

Yasak bir kadına aşık oldum....

Martılar ağlıyordu düşlerimizdeki sahillerde

Şarkınınsa flütlü notasındaydı parmaklar, 

Suskun çocuğun şiirindeydi sıra, 

Bir romana başlıyordum 

Giriş paragrafında, 

Yasak bir kadına aşık oldum.......', 'Uzak denizlerin limanlarında Bekleyen uyruksuz bir şiirden çıkıp geldim,  Gözlerinin kafiyesiz sözlerine,  Bir romana başlıyordum,  Giriş pa...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasak-roman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dördüncü Temrin: Kekeme', 'dorduncu-temrin-kekeme-selim-temo-hwgv7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pompei''nin göklerinde anason ve malt

düşüyor kuytu adımlarıyla müteşair

düşüyor hatırlamanın çarkına yara dediğin

zatülcenp tavuklar geçiyor laklı kapaklardan ilh ilh ilh

ey sırı dökülen aynalardan geçen ince mülk

sat resim çektirir gibi bakan yağlı suratları

(anılarını satarak geçinen bir gazi tanımıştım

siyahlar içinde cüzzamlı)

taşıyor foseptik çukurları belediye çaresiz

son blues çalıyor ama ne kadar basitsiniz

kentleri dolaşan söylen

dolara endeksli gölge bulmuş vitrinini

geçiyorum zavallı mankenlere basarak

balgam olup akıyor afiş aşkları

barlarda üstsüz garsonlar şiir okuyor

mutsuz hanımlar kadehte boğuyor kocalarını

''''şeyy'''' diyor biri ''''amuda da kalkar mısınız? ''''

''''adım Şakir'''' diyorum ''''törpü taşımam! ''''

duymuyor kimse orada değilim çünki', 'Pompei''nin göklerinde anason ve malt düşüyor kuytu adımlarıyla müteşair düşüyor hatırlamanın çarkına yara dediğin zatülcenp tavuklar geçiyor...', ARRAY['Türk Edebiyatı','Şiir','Selim Temo']::text[], 8.5, '{"poet":"Selim Temo","poet_slug":"selim-temo","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dorduncu-temrin-kekeme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Bir Aşktı', 'baska-bir-askti-ceyhun-kuburlu-u0e8j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kollarını açıp 

Nerde kaldın diye sarılmadın bana, 

Sesimi duyduğunda uysal bir sessizlikten çıkıp geldin 

Her defasında yanıma, 

Dokunmadan sevdin hep, hiç özlemedin oysa; 

Yalnızca güzel sözleri sevdin, bir çiçeği suya değdirmeyi sevdin, 

Ve susuz bırakmaya aşıktın tüm sevgilerimi, 

Yabaniydin bu sevginin ana düşüncesindeki aşka; 

Kollarını açıp

Nerde kaldın diye sarılmadın  bana, 

Yanında hüzünlü bir yüzü seçtin, 

Gözleri dolu bakışları sevdin, 

Ve gülmeye aşıktın intihar düşlerin yanında, 

Gel demedin, kapını açık bırakmadın, 

Her defasında kapında beklememi istedin 

Bazen yağmurlardan ve bir çocuk haykırışı gibi

Uğuldayan rüzgarlardan irktin, 

Yanına aldın, ve bekleyen yorgun bedenimle tüm öfkemi aldı bakışların, 

Usulca girdim; 

Aslında yağmurların ve rüzgarların geçici olduğunu duymuştum annemden, 

Biliyordum geçiciydi bu ürkekliğin bitecekti bir gün, 

Ve hiç düşünmeden kapını ardına kadar kapatacaktın, 

Bekleyen, yorgun ve öfkeli bedenime, 

Kapatacaktın ve bir notla tekrar huzur bulduğun uykularına kavuşacaktın

Bense son notunun getirdiği huzur ve mutlulukla, 

Yorganımı, yastığımı ve dört duvarı kandıran düşler kuracağım tek başıma, 

Belki bir gün...

Hiç inanamadın bu sevginin doğruluna, yalanlarına benzettin yalnız kaldığında, 

Hiç beklemedin beni, sormadın eşe, dosta, 

Hiç özlemedin ve sevmemi istemedin...

Düşlerim yorulduğunda; yağmurlar başladı buralarda diye bir tıkırtıyla uyandım 

Kapalı pencerelerimin ardında, 

Yine korkular uyanmıştı evinin yalancı bahçesinde gömülü toprakların renginde, 

Ve hüzünlü bakışları özlemiştin, 

Çağırdın ve yine geldim; 

Hayatımın bir filim bandından ibaret olduğunu unutarak başa sardım tekrar, tekrar ve tekrar...', 'Kollarını açıp  Nerde kaldın diye sarılmadın bana,  Sesimi duyduğunda uysal bir sessizlikten çıkıp geldin  Her defasında yanıma,  Dokunmadan...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/baska-bir-askti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyordum', 'biliyordum-ceyhun-kuburlu-0ebza', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yaşama sevinci 

Akşamüstü İstanbul baharı

Meltemler okşuyor 

Dallardaki hışırtıları

Ve gün batımı sefası gözlerinde

Saçlarının sarı edası bir güneş

Gözlerinin mavisi  bir gök yaşıyorum

Boynu bükük kalan tüm çiçeklerim

Açıyor şimdi 

Biliyordum, 

Biliyordum ya

Bu bahar bana hiç 

Ummadığım mavilikler sunacaktı

Biliyordum

Çıkacaktın bir tepenin ardından

Doğan sabahla beraber

Beni martı yalnızlığına 

Bırakmayacaktı bu şehir

Yağmurları özleyene kadar 

Doğacaktın her sabah yanı başımda

Biliyordum

Biliyordum ya 

Bu bahar bana 

Mucizelerle dolu bir demet sunacaktı

Gün rengi bir tenle

Şimdi baharım bahar 

Şimdi güneşim güneş

Şimdi hiçbir çiçek küs değil benle', 'Bir yaşama sevinci  Akşamüstü İstanbul baharı Meltemler okşuyor  Dallardaki hışırtıları Ve gün batımı sefası gözlerinde Saçlarının sarı edas...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/biliyordum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menekşe', 'menekse-ceyhun-kuburlu-fzagn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sihirli lambam olsaydı, 

Seni düşünmeden uyanmak isterdim bulutsuz sabahlara.

Geceleri gök yüzünde bir yıldız olup kaysaydım, 

Tuttuğun dileğin en büyük yalanı olmak isterdim.

Ve penceremden sızan rüzgarın uğultusuyla, 

Seni umutlara gebe bırakmak isterdim.

Güneşin bir sabah ansızın yollarıma düşmesini, 

Ve tüm menekşelerin sana özel dikeni olsun isterdim.

Tıpkı yağmurlu bir akşam vakti, 

Beni hüzne bırak gidişin gibi, 

Bir gün geri dönmeni isterdim.

Şimdi tüm çiçeklerin ve kafiyelerin adına, 

Küçük masum bir veda sana, 

Umutlarımı yılanlarına  terk etme...', 'Bir sihirli lambam olsaydı,  Seni düşünmeden uyanmak isterdim bulutsuz sabahlara. Geceleri gök yüzünde bir yıldız olup kaysaydım,  Tuttuğun ...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/menekse-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-ceyhun-kuburlu-84coe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir oyundu sadece bu

Yalancıktan evimiz vardı, 

Yalancıktan seviyorduk

Ve yalancıktan güzeldin

Ne masaldı, 

Ne de rüya, 

Çocukların oyuncaklarından 

Çalınarak yapılmış 

Gizli bir hayaldi yalnızca.

Bahar rengi bir bahçede

Tüm güzelliklerin yaşandığı

Mavi düşlerdik.

Ve gerçek evimize girdiğimizde

Tüm oyunu başka bir

Güneşli güne ertelemek için

Yeterince sebebe hazırdık.', 'Bir oyundu sadece bu Yalancıktan evimiz vardı,  Yalancıktan seviyorduk Ve yalancıktan güzeldin Ne masaldı,  Ne de rüya,  Çocukların oyuncakl...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oyun-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Aynı Yol', 'yol-ayni-yol-ceyhun-kuburlu-ay6hd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yolumuz vardı aynı adımlardan oluşan

Aynı camda birleşen bakışlarımızın tomurcuğu

Bir sözümüz vardı aynı duygunun beşiği

Aynı midenin lokması

Bir gökyüzümüz vardı kuşbakışı sevdalara uçan

Bir şarkı vardı birbirimizi kaybettikçe bizi bulan

Ne kadar uzaksak güneşe, bahara ve aya

Bir o kadar yakındık birbirimize

Bulmak istediğimiz her şeyden kaçan 

Tutuk bir cümle kurmaya çalışıyorduk 

Bir yıldızın kayışına tutukluyduk 

Kendimizi de yıldızlardan sanıyorduk

Hep eksenlerimizin uzağınaydı bu yolculuk

Aynı baharda aynı düşü kuran

Aynı uçurtmada aynı çocukluğu yatan bir biz vardık sanki

Yaşadıkça soğuk iklimleri seviyor

Sıcak iklimlerde soğuyorduk.

Bir gitar sesinin titrekliğinde ıslanıyorduk

Kadehlerde yalancı sonları bırakıyorduk

Gitmek istiyorduk ayrı kıtalara

Ama birbirimizden bir şeyler arıyorduk 

Kaçtığımız kimliklerde

Aslında dağın dağa kavuşmasından daha kolaydı öykümüz

Ama biz bizsizliğe kavuşuyorduk

Kim bilir belki yoktuk gerçekten

Kim bilir belki hala rüyadayız ya da bir düşte

Nasılsa uyanırız tıpkı baharın yalnızlığına uyandığımız gibi

Biz sizlikten de uyanırız bir gün

Şimdi usulca kaçıyoruz yine 

Güneşi, baharı ve ayı terk edercesine

Haritasını beraber çizdiğimiz yola 

Ayrı noktalardan başlıyoruz...

Yolculuğun ilk dakikaları biraz uykulu

Ve gittikçe bitmeyen yolun baş ağrısı yaratan

Yaşları gibi hatırlanıyor bu sevda...

Biliyorum...', 'Bir yolumuz vardı aynı adımlardan oluşan Aynı camda birleşen bakışlarımızın tomurcuğu Bir sözümüz vardı aynı duygunun beşiği Aynı midenin lo...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yol-ayni-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Günlü Sözcükler', 'bir-gunlu-sozcukler-ceyhun-kuburlu-1tnpg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her oyun da yeniliyor 

İnsan kendine, 

Her zar atışında 

Biraz daha paylaşıyor, 

Zorlukları vücudunda, 

Ve hep arkasında

Belki bir günlü sözcükler 

Bırakarak gidiyor... 

Her kapı eşiğine geldiğinde

Takılmadan geçemiyor...

Ve her defasında

Zor olan 

Kapının anahtarını

Arıyor cebinde....

Ve her yenilişinde

Bir daha yemin 

Ediyor insan

Bir daha gelsem dünyaya

Yine aynı 

Kapının eşiğine

Takılıp sürüklenirim

Diye...', 'Her oyun da yeniliyor  İnsan kendine,  Her zar atışında  Biraz daha paylaşıyor,  Zorlukları vücudunda,  Ve hep arkasında Belki bir günlü söz...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-gunlu-sozcukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz Sokağı''nın uğultusu', 'temmuz-sokagi-nin-ugultusu-selim-temo-nuiih', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben Menaf; hayatın şaşmaz mağduru

bir kez olsun güldüğüm iftiradır.diye

söylüyor türküsünü ceketçilerin.alnında

bitkin bir ter soğuk ve nasılsa kavruk

biz yani Gençlik Parkı''nı severiz.sevgilimiz

tedirgin çıkmıştır mahellenin o bildik solgunluğundan

daha çok kışı atlatır yaza boza yürüdüğümüz.diye

söylüyor türküsünü bekârhanlarının.elinde

Tekel Birası.ve tek sap leylakla

çiziyor güvenilmez bir maviyi 

burada çalınmış kepler, postallar

kürtçe ve Artvin ve Çerkeş, Sivas

suyun tonları ve ışığı dinlenmiş lambaların.diye

söylüyor türküsünü hamalların.sırtında

unutulmuş bir şive.Türkçeyi öpüyor

yabancı kaldığım bir yerinden

bense bütün dillerde söylüyorum

emeğin uzun tarihini.ve fakat

Temmuz Sokağı''nda işler kesat!', 'ben Menaf; hayatın şaşmaz mağduru bir kez olsun güldüğüm iftiradır.diye söylüyor türküsünü ceketçilerin.alnında bitkin bir ter soğuk ve nası...', ARRAY['Türk Edebiyatı','Şiir','Selim Temo']::text[], 8.5, '{"poet":"Selim Temo","poet_slug":"selim-temo","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/temmuz-sokagi-nin-ugultusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süper Yapıştırıcı', 'super-yapistirici-dark-blues-5wj6z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden öğrendim

Girerken sormamayı.

Kapı çalmak kabalık oldu artık

Kendini tanıtmak bile...

Gözlere bakıp yalanda söylüyorum

Gece sarılıp yatıp, 

Sabah arkadaşız da diyorum.

Öğretmenim iyiydi...

Pembeyi hep sevdim

Ona bir laf edemem

Ne de papatyalara

Hiç birşeyden habersiz 

Hala açıyorlar...

Yeni bir yapıştırıcı bulunmuş.

Süper bişi, iz bile bırakmıyormuş.

Ondan alacağım bir tane.

Senden farklı bir çizgim olsun önümde diye.', 'Senden öğrendim Girerken sormamayı. Kapı çalmak kabalık oldu artık Kendini tanıtmak bile... Gözlere bakıp yalanda söylüyorum Gece sarılıp ya...', ARRAY['Türk Edebiyatı','Şiir','Dark Blues']::text[], 8.5, '{"poet":"Dark Blues","poet_slug":"dark-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/super-yapistirici-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sekiz Renkli Gökkuşağının Altında', 'sekiz-renkli-gokkusaginin-altinda-egemen-bilgin-ej7zl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Susuz bir çiçeğin gözyaşında, 

Kurumuş bir dalın yapraklarında, 

Sekiz renkli bir gökkuşağının altında, 

Bekle beni.

Ağlayan bir göz yaşının pınarında, 

Çilesiz bir gurbet akşamında, 

Sekiz renkli bir gökkuşağının altında, 

Bekle beni.

Tek yıldızlı bir gecenin koynunda, 

Kırmızı ayın parlak ışığında, 

Sekiz renkli bir gökkuşağının altında, 

Bekle beni.

Ben de isterim olmak yanında, 

Ama bir engel var, 

Sen unuttun, benim ise hatırımda, 

Her gece ruhuma fatiha okuduğunda, 

Hatırla beni.', 'Susuz bir çiçeğin gözyaşında,  Kurumuş bir dalın yapraklarında,  Sekiz renkli bir gökkuşağının altında,  Bekle beni. Ağlayan bir göz yaşının...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sekiz-renkli-gokkusaginin-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Sen', 'bende-sen-ahmet-kurnaz-7biro', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha gelmek için ne bekliyorsun.

Dertler kök mü salsın kara bağrımda.

Kader oyununu oynaya dursun, 

Zaten senin sevda''n yara bağrımda.

Sabaha ulaşmaz sensiz uykular, 

Açılır gözlerim yaşlarla dolar.

Soğutmaz rüzgârlar, söndürmez sular

Hayatım tutuşan çıra bağrımda.

Gün boyu özlerim, düşte ararım, 

Bastığın toprakta, taşta ararım.

Sessizce döktüğüm yaşta ararım, 

Gel, sende kendini ara bağrımda.

Sineme taş bastım senin yerine, 

Yokluğun dert oldu, indi derine.

Siyah sürmeleri çek gözlerine

İpek saçlarını tara bağrımda.', 'Daha gelmek için ne bekliyorsun. Dertler kök mü salsın kara bağrımda. Kader oyununu oynaya dursun,  Zaten senin sevda''n yara bağrımda. Sabah...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bende-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakla', 'sakla-okan-sozener-0uxjh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlemlerimi sakla

             Sende kalsın

Uykuya dalmış yıldızlı bir günde

             Geçerken alırım

Ama eskitme.........', 'Özlemlerimi sakla              Sende kalsın Uykuya dalmış yıldızlı bir günde              Geçerken alırım Ama eskitme............', ARRAY['Türk Edebiyatı','Şiir','Okan Sözener']::text[], 8.5, '{"poet":"Okan Sözener","poet_slug":"okan-sozener","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sakla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Jilet Yiyen Kız', 'jilet-yiyen-kiz-attila-i-lhan-jset3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'o kızı nerede nasıl görsem 

aklımı başımdan alır ağzı 

saçları şıra köpüğü desem 

kaşları bıçak izi kırmızı 

yakut pulları mı? bu ne görkem 

kanlı gözbebeklerindeki yazı 

beni nasıl büyüledi bilmem 

kirpikleri örümcek kırmızı 

kızıl demirden bir ünlem 

salınması yangın yalnızı 

korkmasam öpmeye eğilsem 

dişleri elektrik kırmızı 

çarpılmışım başım sersem 

sevdim jilet yiyen kızı 

göğsündeki kumrulara değsem 

gagaları zehirli kırmızı 

gece gündüz tek düşüncem 

kasıklarımdaki ince sızı 

artık kimseyle sevişemem 

anladım sevişmek kırmızı 

jilet yiyen kız merih''li gecem 

birlikte bulacağız belâmızı 

sonumuz kuşkusuz cehennem 

kırmızı kırmızı kırmızı', 'o kızı nerede nasıl görsem  aklımı başımdan alır ağzı  saçları şıra köpüğü desem  kaşları bıçak izi kırmızı  yakut pulları mı? bu ne görkem ...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/jilet-yiyen-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Be Güzelim', 'ah-be-guzelim-salih-ozalasan-abmqz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugüne kadar aşk''ı sevdayı yazmıştım

Bundan sonra yazmayıveririm be güzelim

Hep sevdaları yazacak değilim ya 

Bir konu bulurum be güzelim

Sevdalar gelir geçer, tıpkı mevsimler gibi

Bazılarının yüreklerde kalsada izi

Sevilmiyorsanız olmuştur artık acı bir mazi

Yüreğimden izin birgün silinir gider be güzelim

Ben insanları hep sevdim

Sevdiklerim için çok geceler üzüldüm tükendim

Bana bir verene ben bin verdim

Ben dosta aşığım ne farkeder be güzelim

Dostlarımı sevmiyorsan beni zaten sevemessin

Yüreğin bölmektir dostluk sen bilemessin

Dostun yoksa zaten hayat boyu gülemessin

Sıkı dostum demiştim sana yazık oldu be güzelim

Sevdalar yaşanırken yazılır diyenmi var

Benim sevdalı onlarca dostum var

Bundan sonra kalemim onların sevdasını yazar

SALİH bir kendini sevmezdi anlayamadın be güzelim', 'Bugüne kadar aşk''ı sevdayı yazmıştım Bundan sonra yazmayıveririm be güzelim Hep sevdaları yazacak değilim ya  Bir konu bulurum be güzelim Se...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ah-be-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökte Aşk Var', 'gokte-ask-var-gulseren-onay-2wkr8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yıldız gördüm

İnerken akşam şehrin üstüne

Masum pembeliğin yerini

Gri maviye terkettiği gökte...

Karşısında koyu renk peçesiyle

Yüzünün yarısını saklayan

Utangaç ay.....

Yıldız mı aya göz kırpıyordu 

Yoksa

Mahçup gülümseyen ay mı yıldıza 

Bilemedim.....

Tek gördüğüm 

Göz kırpıyorlardı

Yasak meyveyi yemiş suçlu insanlar gibi

Birbirlerine....', 'Bir yıldız gördüm İnerken akşam şehrin üstüne Masum pembeliğin yerini Gri maviye terkettiği gökte... Karşısında koyu renk peçesiyle Yüzünün ...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gokte-ask-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-kursat-usalan-0t4n1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tenimde kanıyordun

Anlayamadım

Hep bedenim önümde gider

düşüncemle düzleştiririm herşeyi

anlayamadın

Neyin bedelini ödüyorum

bilmiyorum

Ama sen de ödeyeceksin', 'Tenimde kanıyordun Anlayamadım Hep bedenim önümde gider düşüncemle düzleştiririm herşeyi anlayamadın Neyin bedelini ödüyorum bilmiyorum Ama ...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bedel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teklif', 'teklif-atilgan-alemdar-40ehh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'baharda pencerelerine yaprakların değdiği

iki katlı ahşap mavi bir evimiz olsun isterdim

şehire hayli uzak ıssız bir yerde

kışın rüzgârın adamakıllı hissedildiği

denize en fazla iki saatlik mesafemiz olsun

hafta sonu bazen çoluk-çocuğu kapıp

ailecek gezmeye gideriz

tezekten tiksinmeyeceğini bilsem

ineklerimiz de olsun isterdim

sonra kınalı kınalı tavuklar

bunlarla geçineceğimizi bilsem

okulu bırakır hemen askere giderdim

az değil ki tereyağı, peynir...yumurta

baharda 

ve yahut kışta

seninle

pencereleri olan herhangi bir yerde

sonsuza dek

yaşamak isterdim.', 'baharda pencerelerine yaprakların değdiği iki katlı ahşap mavi bir evimiz olsun isterdim şehire hayli uzak ıssız bir yerde kışın rüzgârın ad...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/teklif-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni', 'ozledim-seni-abdullah-karaduman-1ncyd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Parktayım ve yine yağmur yağıyor

Sensizliği çekiyorum içime

Hava, toprak sen kokuyor

Yokluğunda ağlıyor gökyüzü

Özlemiş toprak yağmura

Ağaçlar hasretle susamış 

Sarılıyor topraklar damlaları

Bense sessizce eriyorum

Gülen gözlerine susamışım

Yalnızım ve üşüyorum

Güler mi gözlerin dün gibi

Tut, tut elimi üşüyorum

Kalbim bir kuş oldu 

Uçtu gitti engin denizlere

Hasretten yoruldum, özledim

Tut, tut elimi düşüyorum

O güzel gözlerini

Sıcak sesini, ılık nefesini

Teninin kokusunu

Anlıyormusun özledim seni.', 'Parktayım ve yine yağmur yağıyor Sensizliği çekiyorum içime Hava, toprak sen kokuyor Yokluğunda ağlıyor gökyüzü Özlemiş toprak yağmura Ağaçl...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozledim-seni-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-egemen-bilgin-6p22l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bekliyorum dar bir kapının ağzında

Kaç dakika oldu artık bilmiyorum

Geriye dönemiyorum her yer boşluk

Sana gelemiyorum kapının kolu yok

Bari sen gel, gel de kurtar beni buradan

Sonu olmayan bir boşluğa kaymış ayağım

Tutsan elimden belki kurtulurum

İnan sade bir tebessüm etsen yüzüm güleç ölürüm

Gelmeyeceksen de gelmiyorum deme

Bırak kalsın içimde bir demet umut

İstesen de geriye dönemem bundan böyle

Gelmeyeceksen dur orada öyle', 'Bekliyorum dar bir kapının ağzında Kaç dakika oldu artık bilmiyorum Geriye dönemiyorum her yer boşluk Sana gelemiyorum kapının kolu yok Bari...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Diyâr', 'bir-diy-r-egemen-bilgin-7cavr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlemlerin yakıp kavurduğu, 

Acıların bir kuru ot misali savurduğu, 

Sevgilerin mutluluk değil, acı verdiği, 

Bir diyardan sesleniyorum.

Gözlerin bakıp görmediği, 

Kafaların anlayıp düşünmediği, 

İnsanların bencilleştiği, 

Bir diyardan sesleniyorum.

Zamanın anlamsızca akıp gittiği, 

Dört duvar arasına kilitlenmiş

Sabit fikirlerin türediği, 

Bir diyardan sesleniyorum.

Kuşların uçamadığı, 

Uçurtmaların iplerini kopardığı, 

Soğuğun can aldığı, 

Bir diyardan sesleniyorum.

Öyle bir diyar ki

Cehennem bile cennettir yanında.

Sonu olsa da olmasa da

Kurtuluşu olmayan bir diyardan sesleniyorum.', 'Özlemlerin yakıp kavurduğu,  Acıların bir kuru ot misali savurduğu,  Sevgilerin mutluluk değil, acı verdiği,  Bir diyardan sesleniyorum. Göz...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-diyar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenmelidir', 'beklenmelidir-riza-aslan-dkyxu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'beklenmelidir

günlerin bir gün

düzlüğe çıkacağı umudu

süregelen gelgitlerin ardından

uykulara çöken 

karabasanlara inat

devam eden

belirsizliklere rağmen

beklenmelidir

günlerin bir gün

düzlüğe çıkacağı umudu

uzak

çok uzaklardayken umudun

ellerin boşlukta sallanırken

seni görmediğini bildiğin 

sevdiklerine

dokunamazken sevdiğine...

beklenmelidir

günlerin bir gün

düzlüğe çıkacağı umudu

gözleri, gözlerinin önünde

arada yüzlerce kilometrenin

çaresizlik veren soğukluğu

gözyaşların

yer altından akan

bir ırmak gibidir 

görülmez

herşeye rağmen

beklenmelidir

günlerin bir gün

düzlüğe çıkacağı umudu

***', 'beklenmelidir günlerin bir gün düzlüğe çıkacağı umudu süregelen gelgitlerin ardından uykulara çöken  karabasanlara inat devam eden belirsizl...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/beklenmelidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Gülü', 'ruzgar-gulu-nurullah-alkan-01w88', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yarım kalan üç kelime sen ben 

üçüncüsü dilde değil ama yine sen 

Vakit sen düş sen yanlız olan bir ben 

Binbir sedada sessiz kalan yine bir ben

Hayal içinde varlık varlık içinde yokluk

Sonsuzluga bir bilet bu oyun tek perdelik

sil gözlerini seyreyle bu oyun tek kişilik

Hikayenin adu hiçlikteki sensizlik

Artık perileri uyutuyorum odamda

Sessiz gemimle yol alıyorum bu deryada

Yanan mumu seyrederken bugulu camda 

Boguyorum yanlızlıgımı en yanlızlımda

Bu dünyada renk nakış lezzet ne varsa küsüm

Alemde cümbüş var bense kabuslara öksüzüm

Gözümde korku yüzümde azraile bir tebessüm

Demek bana geldiği zaman böyle gelicek ölüm

Yokluk o donduran buz o söndüren karanlık

Geçmiş ninnilerle avunmuyor bu yanlızlık

Sürmeli matem nefretle bu vakitte uyanık

İçimde budaklanıyor bu zehirli sarmaşık

Çiselerde üstüma tane tane mavi ateş 

Ruhumda ahenk ahankki ölümsüzlüğe eş

Siyahın vehminde gölge ararda aciz güneş

Geçit vermez gece geceki ışıga kalleş

Yetim cocuklardır artık mağmurlaşan gözüm

Mısralardamı saklısın söyle söyle rüzgar gülüm

Ölüm bize ne uzak nede yakın ölüm

Ölümsüzlüğü tattık biz bize ne yapsın ölüm', 'Yarım kalan üç kelime sen ben  üçüncüsü dilde değil ama yine sen  Vakit sen düş sen yanlız olan bir ben  Binbir sedada sessiz kalan yine bir...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Alkan']::text[], 8.5, '{"poet":"Nurullah Alkan","poet_slug":"nurullah-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ruzgar-gulu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızım', 'yanlizim-nurullah-alkan-v0zzh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine yanlızım bir ben birde o

Odada bir senfoni inceden 

Bir ben duyarım birde o

Bozar sükutu bir kibrit 

Başlar koyu bir muhabbet

Bir ben anlarım birde 

Kavusur dudaklar yarene

Sarılır parmaklar ince bedene

Bir ben cosarım birde o

Üflerim bir nefeste nefretleri

Gelir aklıma sakladıgım gözyaslarım

Bir ben aglarım birde o

Dagılan külleridir sanki hayatım

Dumanlar içinde maziden bir resim 

Bir ben görürüm birde o

Ve biter her sey son nefeste

Yanlızım bir ben bir ben bir ben yanlızım.....', 'Yine yanlızım bir ben birde o Odada bir senfoni inceden  Bir ben duyarım birde o Bozar sükutu bir kibrit  Başlar koyu bir muhabbet Bir ben a...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Alkan']::text[], 8.5, '{"poet":"Nurullah Alkan","poet_slug":"nurullah-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yanlizim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Rengi', 'gecenin-rengi-nurullah-alkan-lpwzk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece titrek kalemime bir ruh geldi 

Her gece oldugu gibi yine vakit erişti

Mucize saatim caldıda ufkumda

İncecik gümüşten bir yay halinde

O eskimez kararmaz hilali gördüm

Aşk bestelerini ne kadarda özlemişim

Gümüşten incecik bir kolye gibi

Ay birden cıkageldi

Karanlıgın örtemediği sisin caresizliğine

Mazide sızım sızım geceye geldi

Baktım artık gece gece değildi

Gecede som yanlızlıgı gördüm 

Ah ben yanlızlıgı gördüm

Bir ordudan daga güçlü yanlızlığı gördüm

Yanlız değildim yapayanlızdım

Birden yanlızlık sarardı  sonbaharı yasadı

Sonra kırmızılaştı kışın ateşinde yandı

Sonra morardı sönmüş bir köz oldu

Ve yeşile döndü baharı başladı

Sonra ilk rengini aldı siyah oldu

Öteki siyahın tam tersi

Ölümün yok oldugu boşlugun rengi

Gercek yoklugun rengi

Baktım artık yanlızlıktan ses yok

Onun yerine yanı başımda bir ses

Ötelerden hafif, serin bugulu, sazende bir ses geldi

Gece artık ne siyahtı nede beyaz

Som bir kristaldi inci gibi billur gibi yagmur gibi

Oda sicim sicim gözyaşım olduda yüreğime aktıda geldi', 'Bu gece titrek kalemime bir ruh geldi  Her gece oldugu gibi yine vakit erişti Mucize saatim caldıda ufkumda İncecik gümüşten bir yay halinde...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Alkan']::text[], 8.5, '{"poet":"Nurullah Alkan","poet_slug":"nurullah-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gecenin-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Kelebek', 'anneme-kelebek-nurullah-alkan-0eatk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaten her şey güzeldi o küçük gözlerimde

Hiç bir acım yoktu 

Ayaklarımı sıkan pabuçlarımı saymazsak

Zaman kavramım olmasada yinede telaşlıydım

Ağaçlara tırmanmalı zıplamalı koşmalıydım

Koşuyordum amacsızca özgürce cocukca

Ne kimse ile yarısyordum

Nede bir yerlere yetişme endişem vardı

Küçük ayaklarımda derman kalmamıştıki onu gördüm 

Ne güzeldi

Zaten her şey güzeldi küçük gözlerimde

Birden uçuverdi

Koşuyordum onu tutmalı anneme götürmeliydim

Koşuyordum ümütle heyecanla hırsla 

Engel tanımıyordum..

Ayaklarımı sıkan pabuçlarımı saymazsak

Ve yığılmıştım her yerim acıyordu

O ise hala ucuyordu 

Salına salına hala bana inat

Artık onu kaybetmiştim özgürlüğe uçmuştu

O kısacık hayatına ne denli bağlıydı

Her anı yaşamak için uçmuştu

El salladım ardından 

Anneme bir papatya götürdüm kelebeğin yerine

Ne güzel bir gündü o gün 

Zaten her sey güzeldi cocuk gözlerimde...', 'Zaten her şey güzeldi o küçük gözlerimde Hiç bir acım yoktu  Ayaklarımı sıkan pabuçlarımı saymazsak Zaman kavramım olmasada yinede telaşlıyd...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Alkan']::text[], 8.5, '{"poet":"Nurullah Alkan","poet_slug":"nurullah-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anneme-kelebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmayınca', 'sen-olmayinca-asuman-kaymak-ertem-lfeik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi sen varsan var, 

Aşk sen varsan var, 

Gönlüm hırçın yokluğunda, 

Yaşam anlamsız...

Sevgi yok, aşk yok

Senin yokluğunda, 

Ben bir hiçim sen olmayınca...

Özlüyorum seni ve sevgini, 

Yalanda olsa yeminlerini, 

Yaşayamıyorum sensizliği, 

İstemiyorum böyle kaderi, 

Ben bir hiç oluyorum, 

Sen olmayınca...

 Asuman (Kaymak) Ertem', 'Sevgi sen varsan var,  Aşk sen varsan var,  Gönlüm hırçın yokluğunda,  Yaşam anlamsız... Sevgi yok, aşk yok Senin yokluğunda,  Ben bir hiçim...', ARRAY['Türk Edebiyatı','Şiir','Asuman (Kaymak) Ertem']::text[], 8.5, '{"poet":"Asuman (Kaymak) Ertem","poet_slug":"asuman-kaymak-ertem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-olmayinca-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehir Zakkum Zamanlar', 'zehir-zakkum-zamanlar-nilay-ozer-hdq60', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ömrüme zarar veren erkekler sevdim

cam kırıklarıyla sundular bana tenlerini

seviştikçe çoğalan ellerine inandım

uzun...çok uzun ayrılıklardan sonra

sabırsız bir çarmıh gibi açılan kollarına

çarmıh sarmaşığıydım usul usul dolandım

bana nazlı ölümler

korsan ürpertiler bana

bana aklı çelinmiş geceler kaldı

ömrüme zarar veren şiirler sevdim

aşka ait bir damar kesilmiş gibi

kızıl atlar boşandı içimin aynasından

kanadım sözlerde gözlerde pıhtılandım

infilaktı ihtilaldi laneti üstümeydi

sözlerin yalanından yılanından gözlerin

bana düş bana gizem

bana zehir zakkum zamanlar kaldı

ömrüme zarar veren şehirler sevdim

yıkılmayı sevdim hep o enkaz halimi

bir depremi tek başıma karşılayabilmek için

boşaltılmış şehirleri bekledim

harçsız kuleler örüp kaldırım taşlarından

gençliğimi felaket müjdesinde denedim

bana çığ bana boran

ve umarsız aysarı

ah! bunca zararına sevmenin

neresinden dönsem geçmiş zamandı', 'ömrüme zarar veren erkekler sevdim cam kırıklarıyla sundular bana tenlerini seviştikçe çoğalan ellerine inandım uzun...çok uzun ayrılıklarda...', ARRAY['Türk Edebiyatı','Şiir','Nilay Özer']::text[], 8.5, '{"poet":"Nilay Özer","poet_slug":"nilay-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/zehir-zakkum-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Güneş Sistemimdin ya bi aralar..', 'hani-gunes-sistemimdin-ya-bi-aralar-sair-leyliasude-oio22', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinden yıldızlar kayardı

Ve ben gözlerine her baktığımda dilek tutardım

Bendeki yıldızları farketmen için.

Olmadı....

Sen de yıldızlardaki büyüyü anlayamayanlardanmışsın...

Ve, 

Gözlerinden kayıp giden yıldızlar, 

Meğer yüreğinin parıltısının yok oluşuymuş; 

Her yıldız kayışında samanyolundaki ışığın, 

Karanlığa yerini bırakması gibi...............', 'Gözlerinden yıldızlar kayardı Ve ben gözlerine her baktığımda dilek tutardım Bendeki yıldızları farketmen için. Olmadı.... Sen de yıldızlard...', ARRAY['Türk Edebiyatı','Şiir','Şair Leyliasude']::text[], 8.5, '{"poet":"Şair Leyliasude","poet_slug":"sair-leyliasude","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hani-gunes-sistemimdin-ya-bi-aralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırışlarım', 'haykirislarim-mehmet-caner-sumengen-r15yi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yollara düştüm de dur diyen olmadı

Yerlere düştüm de kaldıran olmadı 

Ömrümü tükettim aşka ermek için

Haykırışlarıma aldıran olmadı...', 'Yollara düştüm de dur diyen olmadı Yerlere düştüm de kaldıran olmadı  Ömrümü tükettim aşka ermek için Haykırışlarıma aldıran olmadı......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/haykirislarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Güle Sormalı', 'aski-gule-sormali-mehmet-caner-sumengen-53kk6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkı güle sormalı, anlatır bülbül gibi 

Sevgi öğretilmezmiş, yaşanır rüya gibi 

Koklanmalı her çiçek, bir tutam sümbül gibi 

Leyla ile Mecnun''lar, varolur dua gibi...', 'Aşkı güle sormalı, anlatır bülbül gibi  Sevgi öğretilmezmiş, yaşanır rüya gibi  Koklanmalı her çiçek, bir tutam sümbül gibi  Leyla ile Mecnu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aski-gule-sormali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum Desem Yalan', 'seni-dusunuyorum-desem-yalan-vedat-sinan-c5ghl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni düşünüyorum desem yalan, 

gelme üstüme! 

hiç yalan söyleyesim yok bu akşam! ! !', 'seni düşünüyorum desem yalan,  gelme üstüme!  hiç yalan söyleyesim yok bu akşam! ! !...', ARRAY['Türk Edebiyatı','Şiir','Vedat Sinan']::text[], 8.5, '{"poet":"Vedat Sinan","poet_slug":"vedat-sinan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/seni-dusunuyorum-desem-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkilem', 'i-kilem-can-akin-2-8jks9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben ne kadar senle olmak istesem, 

O kadar olmamam gerek…

Sen ne kadar benden kaçsan, 

O kadar daha kaçman gerek…

Madem öyle, 

Söylesene sevdiğim bunca şiir neye gerek?', 'Ben ne kadar senle olmak istesem,  O kadar olmamam gerek… Sen ne kadar benden kaçsan,  O kadar daha kaçman gerek… Madem öyle,  Söylesene sev...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ikilem-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-can-akin-2-0tyqh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sıcaklıktı belki aradığımız üşümüş yüreklerimizde, 

Yitip gitmek özlemiydi belki o gözbebeklerinin ta derinlerinde, 

Belki de, tenin teni çekmesiydi en yalın kelimelerle…

Tutkunun, o en vahşi haliyle çağrısıydı bedenlerimize: 

Bütün yasaklar kadar çekici, 

Bütün engeller kadar aşılası, işlenesi bir günahtı belki özlediğimiz…

Biliyorum, dinmeyecek bu arzu, 

O simsiyah saçların değmedikçe tüm bedenime, 

sarılıp sımsıkı birbirimize, 

sevişmedikçe kendimizden geçercesine, 

uyanmadıkça yanyana sımsıcak, 

gözlerimiz sevgiyle başlamadıkça yepyeni bir güne umut dolu, 

susmayacak o vahşi çağrısı aşka susamış tenlerimizin...

Haydi gel! Durmasana öyle...', 'Bir sıcaklıktı belki aradığımız üşümüş yüreklerimizde,  Yitip gitmek özlemiydi belki o gözbebeklerinin ta derinlerinde,  Belki de, tenin ten...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cagri-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-can-akin-2-mhq24', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aldım resmini karşıma, 

Bir kaç kadeh de seninle içtim sevdiğim...

Gözlerin üstümde...Ne de tatlı gülümsüyorsun bana öyle...

Kokladım: Üzerime sinmiş kokun, bak çıkmamış hala...

Dudaklarımda dudaklarının tadı, 

Herşeyden tatlı...

Öylesine güzelsin ki sevdiğim...

Yok, yok tarif etmeyeceğim güzelliğini, 

O bakışlar, o gözler, o saçlar, o endam...kimseler bilmesin...

Bir ben bileyim yeter...

Bir ben anlayayım bakışlarındaki özlemi, hasreti...

Bir ben bileyim beni arzuladığını...

Dur! Bir kadeh daha içelim gitmeden...

Ayrılamıyorum işte resminden...

Hatırladıkça o güzel dudakları...

Beni o sımsıcak öpüşünü...

O alev alev yanışını...

Nasıl da birmiş özlemlerimiz böylesine...

O susamışlığımız aşka, sevilmeye...

Alev alev yanmaya..

İçelim be sevdiğim..''Bize! ''

Dedim ya karşılıklı içiyoruz diye...

Bu gidişle sonunda olacağımız: 

Ben bir alkolik, 

Sen bir mutfak kölesi! (anlayan anladı)

İşte içkim de bitti! yatma vakti...

Yanıma gelsene be sevdiğim....', 'Aldım resmini karşıma,  Bir kaç kadeh de seninle içtim sevdiğim... Gözlerin üstümde...Ne de tatlı gülümsüyorsun bana öyle... Kokladım: Üzeri...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/resim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-can-akin-2-npq4c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne acı! 

Yoksun...

Seni böylesine delice arzularken, 

İçmekten başka bir şey yapamıyorum yalnızlığımla...

Seni arayamıyorum, sesini bile duyamıyorum...

Vazgeçemeyeceğimiz yaşantılarımız, 

Narin, kırılgan engellerimiz var bizi birbirimizi ayıran...

Değerli konfor çemberimizin içinde, 

Küçücük mutluluklarla yetinmeye çalışıyoruz belki de...

Bizler memur çocuğuyuz be sevdiğim...Alışmışız işte bir kere...

Bizler, ya harçlıklarımızı biriktirir alırız ne alacaksak, 

Ya da ay başını bekleriz...Fazlasını istemeyiz...

Ben istiyorum be sevdiğim...Seni istiyorum...

Herşeyden fazla...

Yalnız seni...

Yoksun...

Ne acı!', 'Ne acı!  Yoksun... Seni böylesine delice arzularken,  İçmekten başka bir şey yapamıyorum yalnızlığımla... Seni arayamıyorum, sesini bile duy...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aci-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-can-akin-2-ahm6g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyormusun, herkes yalan söylüyor bugünlerde birbirine...

Beyazından, biz bile söylüyoruz...

Sen söyleme bana be gülüm...söyleme olur mu? 

İnanmak istediğim yalanlar olsa bile...

Bir şey Ne ise, O''dur sadece...

Ne biraz fazla, ne biraz eksik...', 'Biliyormusun, herkes yalan söylüyor bugünlerde birbirine... Beyazından, biz bile söylüyoruz... Sen söyleme bana be gülüm...söyleme olur mu? ...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalan-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl', 'kizil-tokatli-kemal-nv3h0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim hiç fahriye ablam olmadı

Hep yaşıtlarımla takıldım

Beklide

Ondan kaybettim…', 'Benim hiç fahriye ablam olmadı Hep yaşıtlarımla takıldım Beklide Ondan kaybettim…...', ARRAY['Türk Edebiyatı','Şiir','Tokatlı Kemal']::text[], 8.5, '{"poet":"Tokatlı Kemal","poet_slug":"tokatli-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kizil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mermi', 'mermi-tokatli-kemal-fgjw1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk defa 

Bir kurşun atımı kadar yakın

Yıldızlar kadar uzak

Olduğun akşam

Alışkanlığının 

Önüne geçemediğin

Dudaklarına hakim olmadığın 

Akşam Söyledin

…………Hayatım

Bedenin namlu 

Dilin tetikti sanki

Ateşlenmiş yedi altmış beşlik 

Mermi gibi

Geçip  gitti kulağımın yanından 

Ağlar bağlamış beynime

Saplanıp kalsın isterdim

Geçti gitti

Hadi ne duruyorsun

Ateşle 

Bu defa tutması dileği ile', 'İlk defa  Bir kurşun atımı kadar yakın Yıldızlar kadar uzak Olduğun akşam Alışkanlığının  Önüne geçemediğin Dudaklarına hakim olmadığın  Akş...', ARRAY['Türk Edebiyatı','Şiir','Tokatlı Kemal']::text[], 8.5, '{"poet":"Tokatlı Kemal","poet_slug":"tokatli-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mermi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-tokatli-kemal-0mrgt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Niceleri 

Geldi geçti

Başını koydu

Sıcaklığını, 

Terini, 

Bıraktı gitti.

Sana

Zaman geldi

Duvarın tozunu aldın.

Eskidin, 

Yıprandın, 

Beni

Af edecek misin

Yastığım.', 'Niceleri  Geldi geçti Başını koydu Sıcaklığını,  Terini,  Bıraktı gitti. Sana Zaman geldi Duvarın tozunu aldın. Eskidin,  Yıprandın,  Beni A...', ARRAY['Türk Edebiyatı','Şiir','Tokatlı Kemal']::text[], 8.5, '{"poet":"Tokatlı Kemal","poet_slug":"tokatli-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zaman-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınar', 'cinar-tokatli-kemal-k98my', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çınar düşün 

Kollarınla saramadığın

Kargaların mesken tuttuğu, 

Öpüştüğünde, 

Kimsenin görmediği, 

Bir çınar düşün

Ebedi uykusunda 

İnsanın

Başında dimdik', 'Bir çınar düşün  Kollarınla saramadığın Kargaların mesken tuttuğu,  Öpüştüğünde,  Kimsenin görmediği,  Bir çınar düşün Ebedi uykusunda  İnsa...', ARRAY['Türk Edebiyatı','Şiir','Tokatlı Kemal']::text[], 8.5, '{"poet":"Tokatlı Kemal","poet_slug":"tokatli-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cinar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-tokatli-kemal-nn6u9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni bağlasalar zincirlerle

Kilitler vursalar

Sayısını bilmediğim

İsyanım bir sebebi olsa

Görünmeyen, 

Hissettiğim, 

Bağlarımdan kurtulsam

Dağlasınlar, 

Kızgın demirlerle

Beynimi

Sayılı günler bittince

İşlemeyecek nasıl olsa

Zincirleyin beni

Zincirle bağlayın ki

İsyanımın bir adı olsa', 'Beni bağlasalar zincirlerle Kilitler vursalar Sayısını bilmediğim İsyanım bir sebebi olsa Görünmeyen,  Hissettiğim,  Bağlarımdan kurtulsam D...', ARRAY['Türk Edebiyatı','Şiir','Tokatlı Kemal']::text[], 8.5, '{"poet":"Tokatlı Kemal","poet_slug":"tokatli-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/isyan-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür', 'omur-tokatli-kemal-n1zr5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kelimeler arasında kayboldum

Bu akşam.

Başka bir dünya burası

Düşüncelerim, 

Kelime, kelime çıkıyor karşıma

Yanımda olsan şimdi

Her yerde, 

Senin düşüncelerin

Nasılda okurdum onları

Hiç usanmadan, 

Bıkmadan

Bir ömür kaybolurdum', 'Kelimeler arasında kayboldum Bu akşam. Başka bir dünya burası Düşüncelerim,  Kelime, kelime çıkıyor karşıma Yanımda olsan şimdi Her yerde,  ...', ARRAY['Türk Edebiyatı','Şiir','Tokatlı Kemal']::text[], 8.5, '{"poet":"Tokatlı Kemal","poet_slug":"tokatli-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/omur-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karalama', 'karalama-tokatli-kemal-u3rhq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar sende benimdin. 

Bedeninle gittin başkasının oldun. 

Unuttun.

Ruhun bende kaldı

Keşke onu alsaydın

Benden

Bedenin kalsaydı) 

**              **

O iki kelimeyi 

Çok duydum

Yine de bu sıkıntı niye

Acı çekmek bu kadar 

Sevindirmezdi beni

Geçmişi düşünürken

Seni bulmak

Kelimelerle oynuyorum yine

Biraz rahatlatır diye 

Nere varacak bu mısralar

Bilmiyorum

Al işte sana ve senden sonralarına

Yazılmış bir karalama', 'Bir zamanlar sende benimdin.  Bedeninle gittin başkasının oldun.  Unuttun. Ruhun bende kaldı Keşke onu alsaydın Benden Bedenin kalsaydı)  **...', ARRAY['Türk Edebiyatı','Şiir','Tokatlı Kemal']::text[], 8.5, '{"poet":"Tokatlı Kemal","poet_slug":"tokatli-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karalama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşuyorum', 'kosuyorum-tokatli-kemal-t34hr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

Tanımadıkları insanlar için öldüler

Adını bile koyamadıkları 

Duygunun esiriydiler.

Özgürlüklerine koştular

                  II

Enerjiye dönüştüğümde

Hala nefesini alabiliyorsan 

Bir gülün kokusunda, peteklerde

Havada, suda, her yerde olacaksam 

Koşuyorum bende özgürlüğüme.', 'I Tanımadıkları insanlar için öldüler Adını bile koyamadıkları  Duygunun esiriydiler. Özgürlüklerine koştular                   II Enerjiye ...', ARRAY['Türk Edebiyatı','Şiir','Tokatlı Kemal']::text[], 8.5, '{"poet":"Tokatlı Kemal","poet_slug":"tokatli-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kosuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-tokatli-kemal-qbjkk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sürgüne gönderdiğim

Duygularla buluştum

Bu kadar acımaz sanmıştım

Yanılmışım aldanmışım

Kanayan bir yaraya döndü

Bak şimdi gözlerime

İstemediğini söyle 

Kelimeler düğümlenirse

Bir buse ver 

Dön git sürgün yerine', 'Sürgüne gönderdiğim Duygularla buluştum Bu kadar acımaz sanmıştım Yanılmışım aldanmışım Kanayan bir yaraya döndü Bak şimdi gözlerime İstemed...', ARRAY['Türk Edebiyatı','Şiir','Tokatlı Kemal']::text[], 8.5, '{"poet":"Tokatlı Kemal","poet_slug":"tokatli-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/surgun-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgüne', 'surgune-tokatli-kemal-yh79l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sürgüne gönderdiğim

Duygularla buluştum

Bu kadar acımaz sanmıştım

Yanılmışım aldanmışım

Kanayan bir yaraya döndü

Bak şimdi gözlerime

İstemediğini söyle 

Kelimeler düğümlenirse

Bir buse ver 

Dön git sürgün yerine', 'Sürgüne gönderdiğim Duygularla buluştum Bu kadar acımaz sanmıştım Yanılmışım aldanmışım Kanayan bir yaraya döndü Bak şimdi gözlerime İstemed...', ARRAY['Türk Edebiyatı','Şiir','Tokatlı Kemal']::text[], 8.5, '{"poet":"Tokatlı Kemal","poet_slug":"tokatli-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/surgune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatım Alt Üst Olmuşken', 'hayatim-alt-ust-olmusken-beyhan-oral-bayram-did5r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hadı sende vur bır tekme daha

Yerden yere at benı

Hadı sende ıhanet et

Hadı sende yuzume gul ve oylece gıt

Hadi

Hayatım altust olmusken sakın vazgecme

Yıkıldıgım gun bugun

Elınden gelenı ardına koyma

En zayıf anım sımdı

Bak

Ellerım ayaklarım tutmuyor

Dızlerımın bagı sensız cozulmus

Hadı hadı gec kalma

Sende vur bır tekme daha

Goruyorsun dımı caresızlıgımı

Aglayısmı

Sen olusumu 

YoklugunuBıtıp tukenmıslıgım son haddınde

Kırık bır dal gıbı oylece duruyorum yerde

Hadı hadı gecıkme

Yetımlıgım boynu bukuklugum

Hazır cıgnıyorken benı

Bır sakız gıbı

Hadı sende vur

Hadı sende gul

Hadı sende gelme

Hadı ne cok acı var bak bende

Hayatım altust olmusken

Zıncırlerım sımdı cozukken

Hadı bak gecıkmeden

Hazır ben yokken 

Hazır sen de yokken

Hadı bız ölmusken

Ne duruyorsun

Neden korkuyorsun gozlerıme bakarken

Neden seslenemıyorsun gıttıgın yerden

Neden gelemıyorsun tukenmıslıgımın ıcınden

Neden yoksun sımdı sen

Neden ıcımde olupta yanımda olmayısın

Neden bu garıp ıntıkamın

Soylesene nedır bızı bızden koparan

Nedır hayatımızda eksık olan

Bılıyorsun dımı 

Gozlerımdekı bosluk sensın

Dızlerımdekı kırık sensın

Ayaga kalkamıyorum goruyorsun dımı

Yalnızım anlıyorsun degılmı

Sokakta bır sıgara kagıdı gıbıyım

Yerım yurdum yok sankı

Evımdeyım ama mısafırım

Sahıbım cok

Oysa ben senın sahıplıgıne alıskınım

Ayak dırıyorum hayata 

Yokluguna

Ama bıtıyorum gunden gune

Ianan cok zor gelıyor

Zorrrrrrrrrr

Bıkıyorum dıyorum 

Ama

Yınede yasamaya devam edıyorum

Ozluyorum dıyorum

Ama

Yokluguna dayanıyorum

Aglıyorum dıyorum

Gozyasımı da sılıyorum

Gucumu nerden alıyorum

Tukendımmı onu bıle bılmıyorum

Bak 

Hazır erıyıp gıtmısken

Bak bugunde bıtmısken

Yarını da ıstemıyorken

Henuz vakıt varken

Hayatım altust olmusken

Durma 

Hala ayaktayken

Yalnızlıgıma boylesıne baglıyken

Dusuncelerım yol almısken

Durmasana

Durma

Hala sensızken bır tekmede sen vur

Bır daha gelme 

Hadı

Hadı benı sevme

HADİ......', 'Hadı sende vur bır tekme daha Yerden yere at benı Hadı sende ıhanet et Hadı sende yuzume gul ve oylece gıt Hadi Hayatım altust olmusken sakı...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/hayatim-alt-ust-olmusken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel De', 'gel-de-beyhan-oral-bayram-ide3l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aydınlanmayan karanlık yüreklerde

Sabahlar nasıl olur bilirmisin? 

Ya özlemekten deliye dönen kalbin acısını? 

Her gün biraz daha mum misali eriyen, 

Ve o mumun aleviyle yanıp yanıp tükenen

Sadece umut ederek yaşayan insanlar gördün mü? 

Arzularını bastırıp içindeki karanlık kuyuya, 

Günden güne solan çiçeklere rastladın mı? 

Gör! Sevenleri gör.

Sevgimi gör.

Sana olan tutkumu gör.

Ben göstermeden gör.

Ben söylemeden duy.

Ben sevmeden sev.

Karşılıksız, katıksız sev.

Sev ki karanlık yüreğim aydınlansın.

Dön de özleyen kalbimin acısı dinsin.

Seslen bana çok uzaklardan, 

Yalnızca gel de.

Gel de canım.

Küllenmiş ateşimle, 

Bastırılmış arzularımla, 

Sevgilerden yapılmış bir demetle  sana geleyim canım...', 'Aydınlanmayan karanlık yüreklerde Sabahlar nasıl olur bilirmisin?  Ya özlemekten deliye dönen kalbin acısını?  Her gün biraz daha mum misali...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gel-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitttt...Hayır Gitme', 'gitttt-hayir-gitme-beyhan-oral-bayram-1cwyo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoklugunun sıvrı ucu yıne merkezımde donuyor

Yıne karanlık bır kuyuda gıbıyım

Yıne sensızlıkten olecegım

Iste baslıyoruz yıne

Bıkkınlıgımı sensızlıkle kankardesı yaparken

Icımde yıne bır yorgunluk

Ellerım ayaklarım yıne tutmuyor

Yıne soylenecek sozum yok 

Yıne gozlerım dolmus

Ha agladım ha aglayacagım

Yıne sensız yokolacagım

Kelımelerın boynu bukuk

Yetmıyor benı anlatmaya cumleler

Noktayı koyamadıgım bır cumle ıcınde

Sensızlıkle olecegım yıneYıne tukenecegım

Yıne sensızlık

Yıne yokluk

Boynu bukukluk

Govdem yıne bıtkın nedense

Gıdıyormusun yıne

Neden bu senlı sensızlık

Nereye? 

Nereye

Nereye dıyorum

Cevap vermenı beklemıyorum

Cunkı gıdecegın yerı bılıyorum

Ama nedense merak 

Durtuyor ıcımı oyuyor

Tırmalıyor cevabını bıldıgım sorular 

Bynımın sakın koselerını

Bıktımmmmmm

Daha sımdıden yıkıldım

Daha sımdıden yokoldum

Gıtme demek ne zor

Gıdecegını bılmek

Yada gelısını beklemek

Nolur gıtme

Yokoldum yıne

Surgunlerın ıcınde kayboldum

Nolur gıtme

Hayır gıt ve cabuk gel

Yokolmadan ben sensızlıkle

Cabucak 

Anlamadan

Bana hıssettırmeden gıt ve gel

Nolur canım gecıkme

Benı bekletme

Tuketme

Nolur

 gıt hadı

Bakmadan gıt

Sarılma hatta

Bavulunuda alma

Nolur benı bırakma

Ah canım

Sen bana bakma

Gıt yasyacaklarımızı tamamlayalım

Gıt acıyı sındırelım 

Gıt de ogreneceklerımızı ogrenelım

Gıt artık dıreneceksek dırenelım

Gıt ama benı de al yanına

Benı yarım koyma burda

Gecelerın ortasında sogukta bırakma

Uguldasın ruzgar aldırma

Nolur benıde al yanna

Benı burda sensız koyma

Nolur canım

Benı bırakma

Benı bırakma...', 'Yoklugunun sıvrı ucu yıne merkezımde donuyor Yıne karanlık bır kuyuda gıbıyım Yıne sensızlıkten olecegım Iste baslıyoruz yıne Bıkkınlıgımı s...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/gitttt-hayir-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesit', 'kesit-beyhan-oral-bayram-htlrn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensiz bir günüm daha geçti.

Her batan gün bir mutluluk, 

Her doğan günse 

Sensizse azap canım.

Özlüyorum! 

Dilim bu kelimeyi ezberledi artık

İsmin, özlemin dilimden dökülüveriyor bir bir.

Sabahları böyle sensiz etmek zor geliyor

Ömrümden büyük bir kesit aldım, 

En güzel yeri sensin canım....', 'Sensiz bir günüm daha geçti. Her batan gün bir mutluluk,  Her doğan günse  Sensizse azap canım. Özlüyorum!  Dilim bu kelimeyi ezberledi artı...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kesit-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne', 'ne-beyhan-oral-bayram-kz8jq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne seni unutmak için bir çabam var

Ne de aşkımı körükleyen bir rüzgar.

Ne seni görmeden durabilecek kadar güçlüyüm, 

Ne de görmeye dayanacak kalbim var.

Ne gündüzüm gündüz, ne gecem gece, 

Umutlarım bir bir yola çıktılar.

Ne seninle yaşayabilecek kadar mutluyum, 

Ne de hayatımdan çıkarabilecek cesaretim var.

Ne sevgiden artan bir tatlı sözüm, 

Ne de içimde, hoş hatıralar.

Aynada gördüğüm bomboş bir yüzüm, 

Susmaya alışkın dudaklarım var.

Ne filizlenmiş körpe duygular, 

Ne de gözlerimde, diri bakışlar.

Titremeye alışmış minik bir yürek, 

Beklemeyi öğrenmiş bir çift gözüm var.

Ne huzurluyum, ne de huzursuz, 

Ne korkuyorum, ne de korkusuz.

Sanki günden güne kuru ve susuz, 

Yıkıldı yıkılacak bir bedenim var.

Ne hayatta direnecek çok fazla gücüm, 

Ne de destek olacak bir yoldaşım var.

Biliyorum artık bende büyüdüm, 

Ama öğrenecek fazla şeyim var...', 'Ne seni unutmak için bir çabam var Ne de aşkımı körükleyen bir rüzgar. Ne seni görmeden durabilecek kadar güçlüyüm,  Ne de görmeye dayanacak...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Bu Boşluk', 'neden-bu-bosluk-beyhan-oral-bayram-rbolb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nedendir böyle kalakalmışlığım

Yalnızlığım yitikliğim neden? 

Ya suskunluğum! 

İçimde dolduramadığım bir boşluk var neden? 

Neden ağlamaklı oluşum hep gülerken.

Yarım mı kaldım, yoksa eksikmi gövdem

Yokluğunu mu sürüklüyorum yoksa peşimden

Sana soruyorum NEDEN? 

Dinliyormusun 

İşte şuramda bir sancı var bul bula bilirsen

Magripte sen maşrukta ben

Gelgelebilirsen

Hatırladın dimi

Kekili dinliyorum ama sensiz eksik 

Sözleri silinmiş sanki

Müziği ise gayibten bir ses gibi

En sevdiğim şarkılarda bile bir boşluk

Söyle canım NEDEN? 

Ne gariptir tarifi olmayışı

Oysa tarif ederdim duygularımı seninleyken

Kızardım zaman zaman

Hatta deli olurdum 

Ama zorlanmazdım sensizlik gibi

Olmazdım böyle tarifsiz ve boş

Olmazdım 

Gel demek istiyorum biliyorum gelemezsin

Bırakıverseler ayaklarını prangasız

Düşüncelerini talimsiz

Biliyorum koşarsın

Yorgun ayaklarını düşünmeden

Gitmeyi unutarak koşarsın bana

Sonuna nokta konmamış cümleler gibiyim

Hatta taşı olmayan mezarlar

Gelde artık bilineyim

Gelde cümlemi sona erdireyim...

GELLLLLLLL.', 'Nedendir böyle kalakalmışlığım Yalnızlığım yitikliğim neden?  Ya suskunluğum!  İçimde dolduramadığım bir boşluk var neden?  Neden ağlamaklı ...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/neden-bu-bosluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliksizlik', 'sensizliksizlik-beyhan-oral-bayram-xj9ff', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sözlerim nereye kayboldular? 

Neden suskunlugumun anlamlı yol alışı? 

Neden bekliyorum bitip tükenmez geceyi? 

Bitip tükenmez dediğime bakma sen

Nasıl geçtigini bile anlamıyorum çoğu zaman

Ama bıtmesını ıstemedıgımden bıtıp tukenmez deyısım

Kendımı aradıgım bu zaman yolculugunda senın payına dusen ne

Yalnızlıgımı paylasan duslerımın arasında ne ısın var

Ne ısın var dunyamın ortasında

Nedendır kapılarımı sana aralayısım

Nedendır bu kılidın arkasındakı cılıngırın ben olusum

Sorular arasında bogulurken zaman zaman

Cevabı buldugum anda yanımda olusunu neden sevıyorum

Neden yolculuguma katıksız ekmek gıbı ortak olman

Neden

Derın bır gol kenarında dıngınlıgımı buldugumu sandıgım anda

fırtınan ortasında kalmamı neden lakayıtce seyredısın

bılıyorsun

evet bıldıgınden

 fırtınadan cıkınca gelecegım yer dusuncelerının dıngın koyu

ve sakınsın 

cunkı bılıyorsun dalgalarla oynamayı sevıyorum

korksamda gerı adım atmak ıcın cok gec oldugunun farkındasın

korkularımla yuzlesırken ben

sen denız fenerı gıbı uzaksın bana

uzaksın 

ancak ısgın kadar uzak

nedense korkuyorum yıne 

yıne bır kabuk arayısı 

fanusumu kaybettım

aramaya takatım kalmamıs

bulmama yardım etmezsın bılıyorum

ama nolur koyma benı cansımıtsız dıye yalvarırken 

birden

bırden farkedıyorum dalagaların o kadarda buyuk olmadıgını

bırden anlıyorum senden korkmadıgımı

bırden hıssedıyorum hayata doymadıgımı

bırden dusuyorum aklının yıldızsız gecesıne

hersey bır an ıste

 yolumu kaybedısım 

korkularımı arayısım

senınle karsılasısım

ve sonu gelmeyen SENSİZLİKSİZLİK......', 'Sözlerim nereye kayboldular?  Neden suskunlugumun anlamlı yol alışı?  Neden bekliyorum bitip tükenmez geceyi?  Bitip tükenmez dediğime bakma...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sensizliksizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-beyhan-oral-bayram-rrfa9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykuyu unuttum

Yemegı hıc tanımıyorum

Kımseyı gormek ıstemıyorum

Eger yalnız bıraktıysan benı

Yalnız kalmalıyım

Yalnızlık ıstıyorum

Sadece ozlemını yasamak

Sadece senınle olmak 

Nıye anlamıyorsunuz benı

Neden rahat bırakmıyorsunuz 

Yalnızlıgımı onunla paylasmak ıstıyorum

Bılıyorum o da yalnız

Bılıyorum bılmezmıyım ben onu

Bılmedıgım nesı varsa bıle 

Hepsı sımdı gozumun onunde

Bagırmak ıstıyorum

Olesıye 

Sesım tukenesıye

Derdımı anlatasıya kadar

Kım duyar kı bu sessız cıglıgı senden baska

Bagırmak ıstıyorum 

Icımden acıyı koparasıya kadar

Artık gecelerı erkenden uyuya kalmıyorum

Sabah kahvaltısıda etmıyorum

Artık kokunuda duymuyorum

Ustumden cıkarmadıgım gıysılerınde kokun azaldı

Koklayamıyorum

Unutmak ıstıyorum yoklugunu

Ama unutamıyorum

Gecırmeye calıstıgım zıfırı karanlıkgunlerın ıcınde

Kısık bır fıtıl gıbı yanıyorsun

Maksadım gun doldurmak

Nasıl gecırdıgımı bılıyorsun

Manasız ve bos 

Hatta uykusuz ve sarhos

Gozlerımın altı cukurlasıyor

Dıslerımı sıkmaktan konusamıyorum

Neden susuyorsun dıyorlar

Konusacak neyım kaldı hayata daır

Son ses actıgım muzıkler cıglıgımı bastırsa dıyorum

Susuyorum

Susuyorum

Ah bır gelse dıyorum

Ama bılıyorum......

Bılıyorum

Bılıyorum

Bılıyorum', 'Uykuyu unuttum Yemegı hıc tanımıyorum Kımseyı gormek ıstemıyorum Eger yalnız bıraktıysan benı Yalnız kalmalıyım Yalnızlık ıstıyorum Sadece o...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/biliyorum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Doğası', 'askin-dogasi-beyhan-oral-bayram-qoztm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gece düşün sevgilim! 

Mehtapla deniz dost olmuş, 

Yıldızlar daha bir parlak, 

Dalgalar sahille sarmaş dolaş, 

Ağaçlar rüzgarla dans ediyor.

Ve biz yalnızlığın tadını çıkarıyoruz.

Bütün gözlerden uzakta 

Sadece sen ve ben....

Kendimize doğadan dostlar buluyoruz.

Onları aşkımıza şahit ediyor, 

O anın güzelliğini hep birlikte yaşıyoruz.

Mehtap aşkımız gibi parlak, 

Dalgalar arzular kadar coşkulu, 

Rüzgar dokunuşun gibi yumuşak, 

Yıldızlar bakışın kadar net ve berrak.

Bütün geceyi rüzgarla elele, yıldızlarla gözgöze geçiriyor

Ve seni,  seni sevgilim

Kalbimin en sığ köşelerinde bekliyorum....', 'Bir gece düşün sevgilim!  Mehtapla deniz dost olmuş,  Yıldızlar daha bir parlak,  Dalgalar sahille sarmaş dolaş,  Ağaçlar rüzgarla dans ediy...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/askin-dogasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüncede', 'dusuncede-beyhan-oral-bayram-r8a8g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece yine seni düşünüyorum birtanem

Dumanlı derin bakışın gözümün önünden geçiyor

Bakıyor bakıyor doyamıyorum

Sarılıyor kollarıma alamıyorum

Yanıma gelişinle mutlu oluyor

Ayrılığa dayanamıyorum

Zor geliyor sevgilim zor

Sensiz buralarda olamıyorum....', 'Bu gece yine seni düşünüyorum birtanem Dumanlı derin bakışın gözümün önünden geçiyor Bakıyor bakıyor doyamıyorum Sarılıyor kollarıma alamıyo...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dusuncede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gelde-anlat', 'gelde-anlat-beyhan-oral-bayram-x6jnf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vakit çok geç olmuş herkes uyuyor, 

Zaman geçmek bilmiyor saat duruyor, 

Gözlerimden damla damla uyku akıyor, 

Yokluğunu gel de gönlüme anlat.

Sevdalar dizilmiş bir bir sıraya, 

Aşkın kalıntısı vurmuş karaya, 

İnsan baktığı yere bazen dalar ya, 

Gelde ayrılığı gözlere anlat.

Zaman gelir duramazsın durduğun yerde, 

Elin kolun bağlanır göz göre göre, 

Bir mektup yazarım sıladan yare, 

Gelde sensizliği gönlüme  anlat.', 'Vakit çok geç olmuş herkes uyuyor,  Zaman geçmek bilmiyor saat duruyor,  Gözlerimden damla damla uyku akıyor,  Yokluğunu gel de gönlüme anla...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelde-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençliğimde Yaşlılık', 'gencligimde-yaslilik-beyhan-oral-bayram-kbs37', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günaydın! 

Bir sabaha daha merhaba

Yeni mutluluklara, yeni umutlara 

Hüzünlere, acılara merhaba.

İnsanliğa ve barışa hasret bir dünyaya

Sevgi dolu sözlere, mutlu bakan gözlere

Özlem duyan aşklara gönülden bir merhaba.

Bir gün daha başladı işte.

İnsanlar bir bir sokaklara döküldü

Bir koşuşturmaca aldı yürüdü

Kimi işine gücüne gidiyor

Kimide oturmuş benim gibi

Camdan geleni geçeni seyrediyor.

Neler görüyor bu gözler neler...

Neleri hatırlatıyor gördüklerim

Alıp başımı geçmişe gidiyor, 

Seyyar satıcının sesiyle bugüne dönüyor, 

Sonra yine eskilere dalıyorum..

Bugünün yaşam tarzına uyup

Geçmişe büyük bir özlem duyup, 

Zamanın insafsızlığına boyun eğip, 

Hayatımın eksik bölümlerini tamamlamaya, 

Ve günü yaşamaya devam ediyorum.

Böylece; 

Akşamın doyum olmaz güzelliğini görmek için

Sabahtan akşama kadar maziyle dertleşiyor

Sonunda akşamı ediyorum.

Nasıl aşkların son günü ilk günü kadar haz verirse, 

Pişman olurmuyum diye düşündürürse, 

Güneşte en tatlı rengiyle öyle veda ediyor biz insanlara

Bir daha göremeyebilirsin 

Doya doya bak bana der gibi bir ayrılış

Ve elveda.

Gitti işte.

Gökyüzü tatlı kızıllığını kaybediyor yavaş yavaş

Tüm agırlığıyla karanlık çöküyor üzerimize

Bakıyorum kimseler kalmamış sokaklarda

Evlerinse lambaları yanıyor.

Kimi evlerin ışıkları ise sönük.

Belkide bir daha hiç yanmayacak

Düşünüyorum! 

Yaşamak arzusuyla dolup taşan insanlar, 

Kendi dünyalarının ışıklarını söndürüp, 

Bir anda nereye kayboluyorlar? 

Hayal oluyor, 

Geçmişte kalıyor, 

Ve

Günün birinde unutuluyorlar.

Bakıyorum yıldızlara; 

Hiçbirşeye umursamazcasına bizleri seyrediyor, 

Belkide

Herşeyin gerçek yüzünü bizden daha iyi biliyorlar

Yıldızlar bir yana 

Gökyüzünde daha ne dünyalar var

Birde dünya içinde dünyalar var ki

Benim dünyamı da aydınlatan

Tek bir ay, tek bir yıldız, tek bir güneş var

Sen; 

Beni göklere çıkaran

Bazen güldüren bazen ağlatan

Deli dolu aşkların en güzelini yaşatan sen! 

Bugünümdesin, 

Yarınımda olacaksın, 

Yaşlılığımda da yanımdan ayrılmayacaksın.

Çünki sen

Bana yaşama gücü veren 

Tek ama tek insansın....', 'Günaydın!  Bir sabaha daha merhaba Yeni mutluluklara, yeni umutlara  Hüzünlere, acılara merhaba. İnsanliğa ve barışa hasret bir dünyaya Sevg...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/gencligimde-yaslilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemenin Acı Tadı', 'ozlemenin-aci-tadi-beyhan-oral-bayram-1zqpr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutamıyorum  kendimi

İçim acıyor özledikçe

Sızlıyor parçalanıyor

Tükenmişliğimin içinde

Kurumuş dudaklarımla seni sayıklıyorum

Elimden birşey gelmeyişini seyrederken

Çaresizliğin içinde yitik yorgun yıkılıyorum her gece

Yalnızca ben biliyorum ben hissedebiliyorum

Biliyorum ki anlamıyor beni hiçkimse

Yalnızca anlamaya çalışıyorlar

Bilenip her gün 

İçimi oyan keskin bir çakı  ayrılık

Bitmiyor ki 

Bitti derken yeniden başlayan bir tükenmezlik

Uzadıkça uzayan bir sürgün

Saatler gün, günler ay, aylarsa yıl gibi 

Özlemenin acı tadı derdim hep

Tadı tuzu kalmadı bu özlemin

Şimdiden çöktü yorgun dizlerim

Sahipsizliğim sensizlikten

Yetimliğim sensizlikten

Sensizliğimse HASRETLİKTEN CANIM....', 'Tutamıyorum  kendimi İçim acıyor özledikçe Sızlıyor parçalanıyor Tükenmişliğimin içinde Kurumuş dudaklarımla seni sayıklıyorum Elimden birşe...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ozlemenin-aci-tadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-beyhan-oral-bayram-3yigm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şarkıdaki en yumuşak ses, 

Gülün yaprağındaki bir damla çiğ, 

Zirvedeki bembeyaz kar, 

Bir mum alevindeki parıltısın.

Hergünün başlangıcı ve bitişi, 

Yaşadıklarımızın gözümün önünden geçişi, 

İçkiyi içer gibi  bir aşığın aşkı içişi, 

Kalbimin neşesi, günümün güneşisin.

SEN VAR YA CANIM SEN; 

YAŞAMAM İÇİN SEBEP 

VE

SEVEBİLECEĞİM TEK KİŞİSİN...', 'Bir şarkıdaki en yumuşak ses,  Gülün yaprağındaki bir damla çiğ,  Zirvedeki bembeyaz kar,  Bir mum alevindeki parıltısın. Hergünün başlangıc...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-175-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Güzel', 'seninle-guzel-beyhan-oral-bayram-wb6d1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş; 

Altın saçlarını salmış

Işığıyla yakıyor beni adeta.

Bulutlar; 

Maviler arasında uçan bir kuş kadar hür.

Çiçekler ise; 

Hayli üzgün hayli solgun.

Bir tek dal oynamıyor ağaçlarda.

Esmiyor o delice esen rüzgar.

Sanki  küskün baharlar bana

Yok hiçbirşeyin tadı sen olmayınca

Ne ağaçlar, ne çiçekler

Ne gökyüzü ne de güneş.

Rüzgar ise umurumda değil

Oysa; 

Oysa seninle güzeldi rüzgarın yüzüme esişi

Seninleyken güneş güne anlam katardı

Seninleyken ağaçlar yeşillenir, 

Seninleyken çiçekler daha bir güzel açardı....', 'Güneş;  Altın saçlarını salmış Işığıyla yakıyor beni adeta. Bulutlar;  Maviler arasında uçan bir kuş kadar hür. Çiçekler ise;  Hayli üzgün h...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seninle-guzel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senli Zamanlar', 'senli-zamanlar-beyhan-oral-bayram-u9kxp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acı mı gerek

Yada hüzün, ayrılık 

Yazmak için seni sensiz mi olmalıyım? 

Ama yazmak değil amacım

Ben seni kuru kuruya yaşamalıyım

Sevişmeliyim senle sabahlara dek

Geceyi gündüzü birbirine katmalıyım

Hayattan kopmalıyım 

Eve kapanmalıyım seninle 

Acıyı dindirene dek 

Sevişmelisin benle

Doyup doyup acıkmalıyım yeniden

Yeter dediğim anda yeniden başlamalıyım

Durmamalıyım

Zamanı durdurmalıyım ama ben durmamalıyım

Köhne bir sahil kasabasında 

Gözlerinin içinde boğulmalıyım

Güneşin merkezinde sevişmelisin benimle

Terden sırılsıklam olmalıyım

Sevişmek böyle güzelken seninle

Yorulmamalıyım

Yorulmamalıyım...', 'Acı mı gerek Yada hüzün, ayrılık  Yazmak için seni sensiz mi olmalıyım?  Ama yazmak değil amacım Ben seni kuru kuruya yaşamalıyım Sevişmeliy...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/senli-zamanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sona Sığdıramadıklarım', 'sona-sigdiramadiklarim-beyhan-oral-bayram-0jn65', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geldiğinden beri acı bir veda gibi bana bakışın

Sanki gelen sen değilsin

Biliyorum gideceksin

Gideceğini bile bile gelmek acı

Beklemek dahada kötü gitmeni

Gideceğini bile bile hiç gitmeyecekmiş gibi yaşamak bu günü

Yada yarını

Hangi yarın 

Yarınmı kaldı 

Bitti işte 

Bugün son

Birdahaki görüşe kadar son 

Hatta son saat birliteyiz

Sayasım geliyor saniyeleri bile

Neyim varsa yanında gönderesim geliyor 

Ne tutkulu bir his 

Anlayamadığım hatta anlayıp ifadesiz kaldığım bir durum

Tutup kolundan esir edesim geliyor

Gitme diyesim geliyor

Ama yapamıyorum

Son dakikaya tüm hayatımı sığdırasım geliyor

Son dakikada yaşayasım geliyor tüm yaşanacakları

Bitmişim gibi hissediyorum

Ve senin bitişini de görebiliyorum

Herkesin göremediği

Bir yürek burkuntusu yakalıyor boğazımdan

Sıkıyor tüm gücüyle

Bitsin istiyorum yaşamım

Ama yine yaşıyorum

Nefes alamamak gibi hatta 

Susuz bir gırtlak

Ayıramıyorum  hislerimi birbirinden

Ne diyeceğimi bilmiyorum

Bak susuyorum

Daha gitmeden suskunluğum tuttu kolumdan

Çekiyor beni sensiz bir çığlığın ortasına

Gidiyorum 

Gidiyorum

Bagırıyorum

Duymuyorsun

Hayır gidiyorsun

Ve sessiz bir çığlık gibi susuyorsun.....', 'Geldiğinden beri acı bir veda gibi bana bakışın Sanki gelen sen değilsin Biliyorum gideceksin Gideceğini bile bile gelmek acı Beklemek dahad...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sona-sigdiramadiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokoluyorum', 'yokoluyorum-beyhan-oral-bayram-jeb9m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Omzunu ozledım

Aglamayı da

Dırenır gorunmekten yorgunum 

Herkes gucten bahsedıyor 

Hangı guc 

Hangı 

Dayanmalıymısım

Bana bılmedıgım bır sey soyleyın

Nasıl dayanabılecegımı ogretın

Bana benımdısımda bırsey gosterın

Bana huzur verın

Kımsesız senı beklemek ıstıyorum

Kımsesız ozlemek

Kımsesız cekmek bu acıyı

Kımsesız dıyorum

Cunkı benı anlayacak kımseyı goremıyorum

Bak burnumu bır havluyla sılıyorumJ

Bak omzunda aglıyorum

Bak yıne soylenıyorum

Kızıp bagırıyorum

Bak senı yıne ozluyorum

Hergun yenıden baslıyorum sana

Hergun hıc usanmadan

Senı ozlemeye doymadan

Sınıyorum koseme

Boynumuda bukuyorum

Gunden gune ezılıyorum

Gunden gune tukenıyorum

Dırenıyorum

Hayır dırenemıyorum

Yalan soyluyorum

Bıktım yapmacık guluslerın ardına saklanmaktan

Mutlu gorunmekten bıktım

Sensızlıgı sındırmıs olmaktan bıktım

Ictıgım sıgaranın haddı hesabı yok

Bak senı yıne ıcıme cekıyorum

Duman oluyorum

Bak yokoluyorum...', 'Omzunu ozledım Aglamayı da Dırenır gorunmekten yorgunum  Herkes gucten bahsedıyor  Hangı guc  Hangı  Dayanmalıymısım Bana bılmedıgım bır sey...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yokoluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım sanma.', 'yalnizim-sanma-ahmet-kurnaz-kipw8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karamsar duygular sararsa seni, 

Yanında ben varım, yalnızım sanma.

Uykusuz geceler, yorarsa seni, 

Yanında ben varım, yalnızım sanma.

İstersen bir dost de, ister sevgili.

Yeter ki çevirme uzanan eli.

Aksa gözlerinden gözünün seli, 

Yanında ben varım, yalnızım sanma.

Uğruna uykular düşler bölünsün, 

İsterse yıldızlar akşamdan sönsün.

Aldırma, geceler seneye dönsün.

Yanında ben varım, yalnızım sanma.

Gönlün mutlu olsun, gülsün gözlerin, 

Ruhumun gamını silsin gözlerin.

Her gece düşüme gelsin gözlerin, 

Yanında ben varım, yalnızım sanma.

Sahte gülücükler kandırsa seni, 

Geceler, ateşe yandırsa seni.

Sabahlar buz olsa, dondursa seni, 

Yanında ben varım.Yalnızım sanma.', 'Karamsar duygular sararsa seni,  Yanında ben varım, yalnızım sanma. Uykusuz geceler, yorarsa seni,  Yanında ben varım, yalnızım sanma. İster...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizim-sanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aybalam', 'aybalam-huseyin-akgul-ka7mh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın cisimsiz düşünceleri, 

Ağlamakla ıslanmıyor Aybalam.

Bu sine yaşadı geçti neleri, 

Talih bana yaslanmıyor Aybalam.

Sabır tende damla damla erirken, 

hatıralar dönüp dönüp çürürken, 

Dakikalar kurşun olup vururken, 

Gönül aynı uslanmıyor Aybalam.

Gökyüzü değişmez simsiyah sema, 

Aklıma umutlar olmuş yama, 

İçerimde yangınlar yanıyor ama, 

Sözcüklerim islenmiyor Aybalam.

Türküler hançer, nağmeler okşaşıyor, 

Herkes bir doğrunun ucunda bekleşiyor, 

Nefesim sıklaştı, mutlak göç yaklaşıyor 

kalp hayalle beslenmiyor Aybalam', 'Yalnızlığın cisimsiz düşünceleri,  Ağlamakla ıslanmıyor Aybalam. Bu sine yaşadı geçti neleri,  Talih bana yaslanmıyor Aybalam. Sabır tende d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Akgül']::text[], 8.5, '{"poet":"Hüseyin Akgül","poet_slug":"huseyin-akgul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aybalam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De Yüreğim De', 'de-yuregim-de-murat-cetin-ntiv7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'duydum ki 

dertler kemirmiş içini 

ayrılığın gözleri yere bakar 

cevapsız kalmış niçini 

sevdanın uçtuğu yere bakar 

kor ateşi attım, yandı yüreğimde 

zalimsin işte zalim, de yüreğim de 

duydum ki 

mahzun gözlerin gökte yıldız arar 

ay suskun, samanyolu perişan 

hayal kaçmış, kolların boşluk sarar 

yok artık yok işte sana karışan 

gözyaşı akıttım, kandı yüreğimde 

hainsin işte hain, de yüreğim de 

duydum ki 

çatlamış dudaklar, adımı sayıklar 

rüya sırt dönmüş, kabusa gün doğar 

vicdan kalbe sızmış, hata ayıklar 

hatalar dağ olmuş, taşar seni boğar 

aşkın, sevdan, kandı, candı yüreğimde 

öldün işte öldün, de yüreğim de 

duydum ki 

uykuyu sallarsın ninniyle dizinde 

saç yolarmış zaman, suskun mazin 

isyan başgösterirmiş ayak izinde 

bana ters istikametteki yollar hazin 

sarayındı, tahtındı, handı yüreğimde 

yıktın işte yıktın, de yüreğim de 

duydum ki 

şarkılara ağıtların eşlik edermiş 

delinmiş dağlar, yüreğin tarumar 

azrail elim varmıyor dermiş 

aşkı kaybettin kazandı kumar 

karabasandı gidişin, zandı yüreğimde 

gerçeksin işte gerçek, de yüreğim de 

duydum ki 

adımı talim eder solgun dudaklar 

gözleri gözlerinde son nefesin 

öptüğüm karanfil seni kundaklar 

sıkışmış sonkez göğüs kafesin 

vedan kıpkırmızı kandı yüreğimde 

ölecektin işte öldün, de yüreğim de 

duydum ki 

kuruyan gözpınarımdan sakladığım 

iki damla gözyaşı 

geride bırakmış 

ıslak bir mezartaşı 

.....................................18/08/2002', 'duydum ki  dertler kemirmiş içini  ayrılığın gözleri yere bakar  cevapsız kalmış niçini  sevdanın uçtuğu yere bakar  kor ateşi attım, yandı ...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/de-yuregim-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Mutluluk', 'tek-mutluluk-murat-cetin-99jh8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çift kişi solumak dünyayı 

aynıyı görmek iki çift gözde 

en gözde hayallerimden..... 

yarımı tamamlayıp tüm olmak 

sarmaşdolaş 

tümü 

tek bedene, tek kalbe koymak 

yaşam terazisi kefesini 

eşitlikte sabit kılmak 

aynı göz hizasında bakmak hayata 

aynı dudakta aynı melodi 

aynı bardakta aynı parmak izi 

zaman, aynı pembe dizi 

yastığım sevdiğimin dizi 

dizim sevdiğime yastık 

dışkapıya astık 

''ben''liklerimizi.. 

''biz'' buyur etti, buyurduk 

tebessümle büyürdük 

büyüdük 

uçurtmanın kuyruğuna astık umutlarımızı 

mavi gökyüzü aldı emaneti 

tatlı meltem gözetti 

poyraz aştı dağı 

bize bizden sözetti 

gökkuşağı selamladı 

minik yağmur taneleri arasından 

taneler damladı 

avucumuzdaydı 

aldık onu 

ait olduğu yere koyduk. 

ne de güzel yakışmıştı 

kalbimize ''mutluluk.'' 

... 

denklanşöre basıyor zaman 

harıl harıl... 

hadi! 

ben, bene sarıldım 

sende sene sarıl. 

..............................18/08/2002', 'çift kişi solumak dünyayı  aynıyı görmek iki çift gözde  en gözde hayallerimden.....  yarımı tamamlayıp tüm olmak  sarmaşdolaş  tümü  tek be...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/tek-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-murat-cetin-s028j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'leylaklı gecelerin hasretleri derin olur 

sezilmez sevdanın ayak sesleri 

karşı koymak imkansız 

direnmek nafile 

aşk şırıngası serin olur 

kar suyu misali işler bedene 

sırma saçın aşağısından 

yeşil gözlerden süzül kalbe 

orası mutluluk yerin olur 

sıkı tutun, hayata gibi 

büyü iyice büyü 

kapla dört bir yanı 

boş çevirme anı 

sevginle satın al sevgiyi 

sevgiyi sevgiyle yıka 

sevgiyle sar, sarmala 

tek hayalin 

tek düşün 

tek aşkın.. 

düşün 

kimbilir kaderin olur. 

susma 

boyun bükme 

el sallama 

uyanma sakın 

belkide kederin olur. 

kaybetme 

kaybetme sakın 

hederin olur. 

vedalaşılmış kalpte 

sevginin izi derin olur. 

ölümün nefesi 

serin olur. 

kara toprak 

yerin olur. 

kalk nolur 

at ilk adımını 

o seni bulur. 

..................................18/08/2002', 'leylaklı gecelerin hasretleri derin olur  sezilmez sevdanın ayak sesleri  karşı koymak imkansız  direnmek nafile  aşk şırıngası serin olur  ...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/nasihat-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Zamansızlığı', 'zaman-zamansizligi-erdem-avsar-ycy4r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çirkinleşmek gitgide

Saptırılmak

Yoldan çıkarılmak

Nedenin önemli olmadığı

Ama sonucunda bir o kadar önemsiz olduğu bir yerde

Çirkinleşiyorum gitgide

Herşey başladığı yerde bitmiyor

Herşeyi öğrenmek

En büyük sırlara ulaşmak

Neden acı verir hep? 

Bir o kadar korkutucu, bir o kadar çekici

Dar bir ara sokakta

Karanlık vakitlerde

Arkandakinin degil, kendinin kim oldugunu bilmek

Anlamı olmadığını bilerek devam etmek

Sebepsizce

Sevmek

Ölmek

Hep zamansızdır

Bir zamansızlık

Aslında zamanın ta kendisidir.

Kanıtlar

Böyle bir sey olmadığını

Zaman..

Kısıtlayıcı etkenler dünyasından

Zaman yok, rüya yok..

Bildiğimiz şeyler ne kadar yanlış..

Geç farkedecegiz.

Inandığımız şeyler bizi bırakınca ancak.', 'Çirkinleşmek gitgide Saptırılmak Yoldan çıkarılmak Nedenin önemli olmadığı Ama sonucunda bir o kadar önemsiz olduğu bir yerde Çirkinleşiyoru...', ARRAY['Türk Edebiyatı','Şiir','Erdem Avşar']::text[], 8.5, '{"poet":"Erdem Avşar","poet_slug":"erdem-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/zaman-zamansizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa', 'kisa-erdem-avsar-bsj00', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendini düşünmek

Tek çare gibi belki

Evet evet kesinlikle öyle..', 'Kendini düşünmek Tek çare gibi belki Evet evet kesinlikle öyle.....', ARRAY['Türk Edebiyatı','Şiir','Erdem Avşar']::text[], 8.5, '{"poet":"Erdem Avşar","poet_slug":"erdem-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kisa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğuzlama', 'oguzlama-basri-gocul-hgllt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kiyir kiyir kişneşiyor

Atlar yeri eşe eşe! 

Gün doğusu kızıllaştı, 

Yayılalım dağa, taşa! 

“Tayma! Tayma! ” nâraları

Korku salsın uçar kuşa! 

Bir uğurdan saldıralım

Çarpıyorken oklar döşe! 

Gözümüzün pekliğinden

Düşmanların aklı şaşa! 

Hanlar, beğler aramızda; 

Emeğimiz gitmez boşa! 

Can kaygısı çekmek olmaz, 

Yazılanlar gelir başa! 

Kırılmakla tükenmeyiz; 

Bakmamalı üçe, beşe! 

Tunç topuzlar yüz dağıta, 

Kunt cıdalar bağır deşe! 

Dahi kılıç çarpışından

Baş, bacaklar ayrı düşe! 

Cenk meydanı dolusunca

Üşmelidir kuzgun leşe! 

        ...', 'Kiyir kiyir kişneşiyor Atlar yeri eşe eşe!  Gün doğusu kızıllaştı,  Yayılalım dağa, taşa!  “Tayma! Tayma! ” nâraları Korku salsın uçar kuşa!...', ARRAY['Türk Edebiyatı','Şiir','Basri Gocul']::text[], 8.5, '{"poet":"Basri Gocul","poet_slug":"basri-gocul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/oguzlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şizofren Aşk', 'sizofren-ask-esref-erdem-cgrhv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şizofren aşklarla tükenirken ömrüm

Unutuldu umarsız bekleyişler

Kırılan kalpleri bir celladın toprağına gömdüm

Hatırlanır mı bilemem 

Esrik ve o denli masum öpüşler', 'Şizofren aşklarla tükenirken ömrüm Unutuldu umarsız bekleyişler Kırılan kalpleri bir celladın toprağına gömdüm Hatırlanır mı bilemem  Esrik ...', ARRAY['Türk Edebiyatı','Şiir','Eşref Erdem']::text[], 8.5, '{"poet":"Eşref Erdem","poet_slug":"esref-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sizofren-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Beni ANNE', 'al-beni-anne-salih-ozalasan-38fmu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni düşünüp senin için ağladım bugün

Göz yaşlarımı görüp silemedin anne

Hıçkırıklarım gecenin karanlığını delip geçti

Ama sen hiç birini duyamadın anne

Yalnızım çok yalnız, anlatılır gibi değil

Senin sevgine bugün çok muhtacım anne

Her günüm zindan geceler karadan kara

Sensiz bahtım da karardı benim anne

Artık gönül yaşım 25 diyemiyorum

Yüreğim ihtiyarladı tir tir titriyor anne

Bakma saçlarımın siyah duruşuna

İçinin ilikleri ağarıp soldu anne

Bulamadım sensiz bir gün mutluluğu 

Mutluluk avuçlarımdan kaçıp gitti anne

Yüreğim sevdalara yelken açtı, uzak denizlere

Deniz ortasında gemimi batırdılar anne

Dalgalara kapılmış gidiyorum çaresiz

Boğulmak üzereyim tut ellerimden anne

Koca bir ömür bitti, geldi gelecek

Nerede benim mutlu olacağım gün anne

Yirmi Eylül şartmıydı doğmam için

Keşke beni hiç doğurmasaydın anne

Doğmasaydım, çekmeseydim bunca çileyi

Artık çile çekecek gücüm kalmadı anne

Yüreğim verdiklerim koparıp aldılar yüreğimi

Ben artık yüreğimi de kaybettim anne

Bir sen anlardın beni, 

bir sen kol kanat gererdin üzerime

Artık her geçen bir daha vuruyor anne

İsyana çeyrek var, kalmadı artık sabrım

Ben isyankar olmak üzereyim anne

Artık ramak kaldı, söylemek istemiyorum

Lânet olsun doğduğum güne anne

Doğmasaydım çekmeseydim bunca çileyi

Doğmamamın yokmuydu bir çaresi anne

Artık dayanacak gücüm kalmadı

Ya sen gel, ya beni de al yanına ANNE

Y.tarihi 21-08-2002 Saat 13,35', 'Seni düşünüp senin için ağladım bugün Göz yaşlarımı görüp silemedin anne Hıçkırıklarım gecenin karanlığını delip geçti Ama sen hiç birini du...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/al-beni-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bir Teselli Olmaktan Çıkıyor Artık', 'ask-bir-teselli-olmaktan-cikiyor-artik-i-smail-bingol-4r7r5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuşkularımız hep galip gelmekte

İnancımızı yitirdik birbirimize

Narin gövdeler vurdukça kıyılara

Aşk bir teselli olmaktan çıkıyor artık

Bir şiirin anlaşılmazlığı gibi

Girince araya mesafeler

Çoğaldıkça çoğalır hüzün

Vurur şahdamarımızdan bir ince sızı

Aşk bir teselli olmaktan çıkıyor

Aşka inananlar için

Gücü mü tükeniyor aşkın

Gücü mü tükeniyor aşıkların', 'Kuşkularımız hep galip gelmekte İnancımızı yitirdik birbirimize Narin gövdeler vurdukça kıyılara Aşk bir teselli olmaktan çıkıyor artık Bir ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Bingöl']::text[], 8.5, '{"poet":"İsmail Bingöl","poet_slug":"i-smail-bingol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-bir-teselli-olmaktan-cikiyor-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leylâ', 'leyl-i-smail-bingol-1shri', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağıt saçlarını Leylâ

Dağıt

Her teli bir acıyı götürsün

Aşıkların yüreğine

Dağıt saçlarını Leylâ

Dağıt

Acıma sevenlerine

Acıma

Seni sevmeye cüret edenlere

Acıma

Karşılıksız sevgin için

Kendini sebîl edenlere

Sen ki aşksın

Sen ki

Aşkın adı olan leylâsın

Kerem edensin

Lûtfedensin

An geldiğinde / Ölümüne ferman edip

Öldüren

An geldiğinde / Dirilişi muştulayıp

Diriltensin

Sen ki aşksın

Sen ki

Aşkın adı olan leylâsın

Sen ki

Akıllılığa sebep

Ve ruhları delirtensin

Leylâsız olmak da zor

Leylâyı arzulamak ta

Sür kanadını sür

Seni arzulayanların yüzüne

Artık dağıt saçlarını Leylâ

Dağıt / Her teli bir acıyı götürsün / Aşıkların yüreğine...', 'Dağıt saçlarını Leylâ Dağıt Her teli bir acıyı götürsün Aşıkların yüreğine Dağıt saçlarını Leylâ Dağıt Acıma sevenlerine Acıma Seni sevmeye ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Bingöl']::text[], 8.5, '{"poet":"İsmail Bingöl","poet_slug":"i-smail-bingol","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/leyla-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anama', 'anama-i-smail-bingol-ecbek', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve bütün analara...

Hangi oğul bilir? 

Anasının hikâyesini

Hangi dil anlatabilir? 

Anaların çilesini

Kim bilir hangi çizgi

Hangi hüznün eseri...

İradenin ipini kavrayan

Nasırlı ve damarlı ellerin

Birer sevda çiçeği

Ve yorgun bakışların...

O bakışlar ki

Çağrıştırır seferberlik senelerini

Asırlardır yaşıyor

Asırların yükünü taşıyor gibisin

Bilemez hiç kimse

Sen hangi sevdanın eserisin

İnancın zırhını kuşandın

Gece ve gündüz

Yandın ha yandın! 

Haksızlığa ve yokluğa

Olmadı hiç seferin

Nice acılara mekân kıldığın yüreğin

Şefkatin ocağında pişti hep

Merhametsizler yol düşüremedi sinene

Ve sen

Geçit vermez dağlar gibi

Direndin ha direndin...', 'Ve bütün analara... Hangi oğul bilir?  Anasının hikâyesini Hangi dil anlatabilir?  Anaların çilesini Kim bilir hangi çizgi Hangi hüznün eser...', ARRAY['Türk Edebiyatı','Şiir','İsmail Bingöl']::text[], 8.5, '{"poet":"İsmail Bingöl","poet_slug":"i-smail-bingol","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/anama-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tabletler -I-', 'tabletler-i-mahmut-bingul-nn50o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tabletler...

-I-

Bir gün daha bitiyor

sensiz, 

kederli. 

Ve yine sabahın seherinde

gözlerim iki kara gözü arayacak

gökyüzünün 

turuncuya işlemiş zamanında', 'tabletler... -I- Bir gün daha bitiyor sensiz,  kederli.  Ve yine sabahın seherinde gözlerim iki kara gözü arayacak gökyüzünün  turuncuya işl...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tabletler-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tabletler -II-', 'tabletler-ii-mahmut-bingul-7vje8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-II-

Dışarıda kar 

tüm esnekliğiyle 

dalıveriyor aşağıya

Bende ise 

Sevginin yüzü saklıdır

yansıtamıyorum dışarıya', '-II- Dışarıda kar  tüm esnekliğiyle  dalıveriyor aşağıya Bende ise  Sevginin yüzü saklıdır yansıtamıyorum dışarıya...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tabletler-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-egemen-bilgin-ycqu9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel artık dinmez vuslatım

Kapanmaz yaram dön bana

İstemiyorum sensiz diyarlarda dolaşmayı

Varsın ateşlerde yürüyeyim ama seninle olsun

İçtiğim zehir, yediğim ölüm olsun

Sensiz sofralarda tabağıma kan dolsun

Senden ayrı bir gülüşüm varsa

Sonsuza kadar kahır olsun', 'Gel artık dinmez vuslatım Kapanmaz yaram dön bana İstemiyorum sensiz diyarlarda dolaşmayı Varsın ateşlerde yürüyeyim ama seninle olsun İçtiğ...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali Munzur', 'ali-munzur-sair-suphi-fta93', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açıldı ömrümün haritası 

Bir omzu düşük ağır delikanlı 

Ey Ali Munzur, ey dağların kartalı 

Sağ yanım bıçak yarası sol yanım hicran 

Ve emanet kalmıştır bir köylü kızında kalbimin yarası 

Ey Ali Munzur, ey dağların kartalı 

Benim ömrümde, bir kırlangıç ağıdı vardır bildiğim 

Benim ömrümde, tel örgüler kuşluk ayazında 

Kör karanlık yağlı kurşun 

Birde yanık türküsü anamın 

Her biri bir başka seherinde güz dönümümün 

Vurup gitmiştir sessizce oğulları 

Şu gurbet denen şu belalı buğ yılanı, şu bilinmez sefere 

Benim ömrümde, bir ırmak vardır 

Durup önünde taş yüzdürdüğümüz ak köpüklerinde 

Sesine sesimizi kattığımız 

Ve anamızın patiskadan biçtiği uzun donlarımızla 

Bir turna balığına gençliğimizi sattığımız 

Aylandığımız, 

adamdan sayılıp delikanlı halaylarına karıştığımız 

Yıldızların altında, dam bacalarında aşık attığımız 

Benim ömrümde, yarı çıplak popil delikanlısı ortalığın 

yağmurların sevdalısı ve parlayan yusuftutan kuşları 

Benim ömrümde, mor menekşe 

Yediveren gülleri ve böğürtlen 

Birde sen! 

İçime işleyen ah sen! 

Ondokuz yaşımın 

Ve ırmağımın 

Ve toprağımın hakkına birde sen! .. 

Bulutlarıma kına yaktığım sebebin 

Namerd olayım sevmedim hiç kimseyi böyle bu kadar! .. 

Ya da sevemedim 

Ey Ali Munzur, ey dağların kartalı 

Sağ yanım bıçak yarası sol yanım hicran 

Ve emanet kalmıştır bir köylü kızında kalbimin yarası 

Bu da bir gurbettir yıkar adamı içine 

Bu da bir rivayettir, on iki yıl bilmem kaç bin gece 

Bir türkü sesinde.. 

Dumanlı dağları duman kaplamış 

Yine mi gurbetten kara haber var? 

Seher vakti bu yerlerde kimler ağlamış? 

Çimenler üstünde gözyaşları var.. 

Benim ömrümde.. 

Şimdi vur, vur içine onca talanı 

Onca sevdayı vur, vur Ali Munzur 

Bu sol yandaki hicran yarası öyle çok ki.. 

Benim ömrümde çiçeğin bozamadığı 

Karanlığın düşemediği yüzüm 

Bana mahsus kor ayazda üşüdüğüm 

Hercanın yeşili, Cemilin üzüm gözlü güzeli 

Ve hüzün yaprağını dökende dut ağacın 

Kalbime bir gül dikeni, fikrime sevda batanda. 

Kemahın istasyonuna doğu expresi demir atanda 

Murat suyu Fırata karışır üç gün üç gece kan akanda 

Ben belki bin gece sayanda gurbet akşamlarında yıldızları 

Emanetime iyi bakasın köylü kızı 

O elinde tuttuğun kanayan şey Ali Munzurun kalbinin yarası 

Benim ömrümde, yarı çıplak popil delikanlısı ortalığın 

Yağmurların sevdalısı 

Ve parlayan yusuftutan kuşları 

Benim ömrümde, mor menekşe 

Yediveren gülleri ve böğürtlen 

Birde sen! 

İçime işleyen ah sen! 

Ondokuz yaşımın ve ırmağımın ve toprağımın hakkına 

Birde sen! 

Bulutlarıma kına yaktığım sebebin 

Namerd olayım sevmedim, hiç kimseyi böyle bu kadar 

Ya da sevemedim. 

Ey Ali Munzur, ey dağların kartalı 

Sağ yanım bıçak yarası sol yanım hicran 

Ve emanet kalmıştır bir köylü kızında kalbimin yarası 

Açıldı ömrümün haritası..', 'Açıldı ömrümün haritası  Bir omzu düşük ağır delikanlı  Ey Ali Munzur, ey dağların kartalı  Sağ yanım bıçak yarası sol yanım hicran  Ve eman...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/ali-munzur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtasar Cinnet Risalesi', 'muhtasar-cinnet-risalesi-mehmet-ozger-n2d3s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1. 

   korkuyorum 

   beynimin gergefine 

   umut işlemekten 

   ve yaklaşmaktan çeperine 

   bir adım bir adım daha 

   ufkum aydınlık yanan gemilerle 

   gemiler ki som akıldır 

   sayhası şavkıyor sularda 

   II. 

   fecri harmanladığımda leyli saçlarından 

   o besteydi çalınan ay ayininde 

   dalgaların arzuyla kayaları öpüşü 

   yıldız katarlarında Leyla ve Mecnun 

   iki sevda yalımı 

   kadim oyuncuları gök tiyatrosunun 

   devam ediyor pandomim 

   leyla  aharlayarak  firari duyguları 

   ayrılıyor  bir ah mersiyesiyle mecnundan 

   sarınarak samanyolunu kendine 

   mecnun çöl orkestrasında şef 

   rüzgar güneş kum ve serap 

   baykuş ıssızlığıyla kapanıyor perde 

   fonda zencir şakırtısı kanonuyla 

   III. 

   sen babil devrinde yazılmış kitabe 

   bingün yılı sahifelerinde billurlaştığım 

   sen çöl kabileleri kadar mütevekkil 

   bilinmezlik ülkesinde kurulu ehram 

   boyuna tütsülediğim 

   sen şebnemsin gülün yüreğinde domuran ter 

   imge yüzüğünün kaşında firuze 

   /you are a letter without letters / 

   nasıl bir çocuksun ki bulamıyorum seni 

   içimin labirentlerinde 

   kaybediyorum bu saklanbaç oyununu 

   girersem yanarım zerrelerime 

   yine de teberüken bulsam seni 

   ilk gözlerime süreceğim 

   artçıları gümrahlaşan bu depremde 

   IV. 

   iki naif sandal olan kaşların 

   alnının okyanusunda  aheste yalpalar 

   bense rotasız kalır alabora olurum 

   eremeden gözlerinin kıyısına 

   hilal sana aşıkmış rivayet bu 

   akşamları iple çekermiş 

   nafile ağzı biraraya gelmez 

   kuş bile tutamaz o 

   V. 

   bende tortulandın güneş korosu izdüşümleriyle 

   yaz güneşi kış güneşi ilkbahar güneşi 

   cinnet helezonları tuttu  beni dört yolağzında 

   ateş şelaleleri tırmanırken damarlarıma 

   harladım bileyledim nefesimle harfleri 

   semenderden öğrendim yalazları sevmeyi 

   ve kargışladım mizacını doğanın 

   /I  SAID THE  UNSAYABLE/ 

   başladı bitmek kaygısı olmayan savaş 

   dilimi  kemiriyor kelimeler 

   çiçek kitap tesbih ve tabut 

   sensizlik girdabında boynum giyotine teşne 

   bilirim zehir emzirmekte mahirdir hayat 

   sadağında ihanet çırpınış ayartma 

   HAY  AT 

   dizginlerini sıkı tut dostlukların 

   her daim L  çizmeyebilir at 

   VI. 

   bir nokta olmayacaktıysam 

   beni niçin sancadın atlas tebessümüne 

   duvarına asmayacaktın madem 

   beni neden resmettin tualine 

   ölüm ve dirim  arasında salınan sarkaca 

   kalbimin kafesini  rabteyledim 

   ki sen avutulmayı çok seversin 

   gövdemin yanardağında dönenen lav ırmakları 

   çağla ve yak anılarımı 

   handiyse patlayacağım', '1.     korkuyorum     beynimin gergefine     umut işlemekten     ve yaklaşmaktan çeperine     bir adım bir adım daha     ufkum aydınlık yana...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özger']::text[], 8.5, '{"poet":"Mehmet Özger","poet_slug":"mehmet-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/muhtasar-cinnet-risalesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerilla', 'gerilla-sair-suphi-mh5kf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şehit Bilal‘in anısına 

Dağlar geçit vermez sisli bulanık 

Yalçın zirvelerinde Hindikuşların 

Onurlu başlarını okşar bulutlar 

Karlı tepelerin ve ıssız yamaçların 

Aniden sessizliği bozar 

Gittikce yükselen tekbir sesleri 

Ve peşinden kudurur durmaz 

Ateş kusan canavarlar 

Keskin barut dumanlari 

Kurşun vınlamaları sarapnel ıslıkları 

Gerillanın burnunda tüter 

Sicacik ana kucagi gibi hasret 

Bir gurbet özlemi ki ulasmaz ellerin 

Patlamaya hazır bir yanardag 

Her saniye tetiktedir er meydanlarında 

Ölümü kuşanan tüm yiğitlerin 

Düsmanla burun buruna oldugu gün 

Yankilanir özgürlügün kavgasi 

Bir mızrak boyu ilerdedir düğün 

Ansızın bir yıldız kayması ile 

Tutuşur ve alev alır gece 

Yükselir zafer karanlığın üstüne 

Bir daha bir daha bir daha 

Yıkılır gerilla gölgeleri 

Paramparca dökülür dağlar 

Kıristal parçaları gibi yere 

Her birinin terli alınlarından öper 

Toprak ananın susamış dudakları 

Gecenin dipsiz karanliginda 

Haberler ulaşmadan daha 

Hasret yüklü yüreklere 

Uykuları katledilir annelerinin 

Anaların bacıların rüyalarına has 

Doyumsuz bir arzudur özlem 

Ki anlatılmaz hayatta 

Zulüm gözyaşlarıyla beslenir 

Kan gülleri ağarmadan şafakta 

Uzaklardan yüreğimize 

Yankılanır bu sevda 

Ulasir kuşaktan kuşağa bir ses 

Ilım ılım namlulara sürülen 

Kurşunlardır şehitler 

Her an patlamaya hazır 

Mü‘minlerin gönlünde 

Bir kader gününde', 'Şehit Bilal‘in anısına  Dağlar geçit vermez sisli bulanık  Yalçın zirvelerinde Hindikuşların  Onurlu başlarını okşar bulutlar  Karlı tepeler...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gerilla-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gerilanın türküsü', 'gerilanin-turkusu-sair-suphi-j87nr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her bakısına 

binlerce  binlerce kursun yanlızlıgı

anımsatır ölüm her ne kadar 

uzak olmasada sevdaya kursun işlemez 

gerillanın türküsünü söyler

dilinde düşmeyen bir ezgi 

dersim dagları way lele way 

bir dag ceylanın gözlerinde kalır

kendi bedeni bir şahanlar ucar 

sevdası özgürlük kendi dilinde

 savruluru düşmana kan kusturan

 namlu sesinde 

bir seni birde sevdamı düşünürüm 

ölüm sesisizligi cöktügünde bedenimde 

soguk bir munzur yeli eser ama sıcaktır 

bedenim o kerwanın yolcusuyum 

gerilanın türküsünü söyler 

munzurdan, cudilere, toroslara, 

 eser kendi yelinde gerilanın türküsünü hep söyler

dilinde düşmeyen bir sevda yüreginde

 sakladıgı sevgili gibidir bu sevda 

binlercesi düşer topraga savrulur diyardan diyara

 bir türkü söylenir gerilanın son bakısları 

arasında o özgürlük türküsü..... gerilanın türküsü', 'her bakısına  binlerce  binlerce kursun yanlızlıgı anımsatır ölüm her ne kadar  uzak olmasada sevdaya kursun işlemez  gerillanın türküsünü s...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gerilanin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nimet''e', 'nimet-e-turan-akdeniz-nyscp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düğüm düğüm şarkıdır sana hasretim, 

Kuru toprağa düşen yağmur gibidir.

Menzile ulaşmaktı bütün gayretim, 

Yollarım engebeli çamur gibidir.

Gittiğimiz yollar taşlı, dikenli, 

Zaman zaman neş''eli; bazen elemli

Olsa da mutluyum seninle, sen''li

Yanında dakikalar ömür gibidir.

Bir lahza ayrılığı hiç düşünmedim, 

Sensiz mutluluk haram, sensiz gülmedim.

Bin bir meşakkat çeksem hiç of demedim. 

Yoksan günler kapkara kömür gibidir.

17/08/2002', 'Düğüm düğüm şarkıdır sana hasretim,  Kuru toprağa düşen yağmur gibidir. Menzile ulaşmaktı bütün gayretim,  Yollarım engebeli çamur gibidir. ...', ARRAY['Türk Edebiyatı','Şiir','Turan Akdeniz']::text[], 8.5, '{"poet":"Turan Akdeniz","poet_slug":"turan-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nimet-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil', 'karanfil-mukerrem-mete-6fidm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buranın gecelerinde yıldızlar bile karanlık

Sigaranın dumanını göremezsin

Göz yaşlarına vurur yakamoz

Perişandır hali güneşin ayın

Bir karanfil uzatırlar

Bu da karanlıktan senin payın', 'Buranın gecelerinde yıldızlar bile karanlık Sigaranın dumanını göremezsin Göz yaşlarına vurur yakamoz Perişandır hali güneşin ayın Bir karan...', ARRAY['Türk Edebiyatı','Şiir','Mükerrem Mete']::text[], 8.5, '{"poet":"Mükerrem Mete","poet_slug":"mukerrem-mete","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/karanfil-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller', 'guller-mukerrem-mete-hlvvr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutmasam da o elleri

Ben abartmadım

Sanki gözlerinde ışık

Alnında yazıydılar

Yolundaki o gülleri

Ben sarartmadım

Dalları yeni kırık

Döktüğümde kırmızıydılar', 'Tutmasam da o elleri Ben abartmadım Sanki gözlerinde ışık Alnında yazıydılar Yolundaki o gülleri Ben sarartmadım Dalları yeni kırık Döktüğüm...', ARRAY['Türk Edebiyatı','Şiir','Mükerrem Mete']::text[], 8.5, '{"poet":"Mükerrem Mete","poet_slug":"mukerrem-mete","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guller-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuktum', 'cocuktum-vedat-sinan-amz15', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocuktum, 

     oyunsuz, 

     oyuncaksız bir çocuk 

     ne kadar çocuksa. 

     Fesatsam biraz, 

     Eğer paranoyaksam hep bundan, 

     Biline! 

     Biline ki benle oyun oynanmaz, 

     Ki bilir bütün mahalle! 

     Ya kaş çıkarırım ya göz, 

     Oyun oynanacaksa bana söylenmez. 

     Ki söylemez di bütün mahalle! 

     Anlatırlar 

     yaşıtlarım hala ballandıra, ballandıra 

     Bir tel, bir tekerlek al sana araba! 

     Dokuzuma kadar o da olmadı şükür, 

     Amenna miskette oynadım, 

     Kibritte, 

     Cam da kırdım. 

     Oyun değil bizimkisi, profeesssyonellikten, 

     Harçlık parası... 

     Kazanmak zorunda olduğuna oyun denirse eyvallah! 

     Amenna 

     miskette oynadım, 

     kibritte 

     bisikletim bile oldu, 

     onbeşim de..... 

     Yanılmayasın! 

     Alınteri, 

     Misketten kazandıklarımla! 

     Ondan gayrı hiç bir bok istemedim, 

     Ta ki ne zaman aklıma düştü sevda. 

     Mevsimlerden güz, 

     Bir karış hava da aklımla 

     Ve tam da yirmibirimde. 

    .............. 

     Şimdi gelmişken otuzuma, 

     Nicedir oyunlar çekmez oldu beni, 

     Tevekkelli, 

     büyüdüm 

     ve 

     dünyaları istiyorum. 

     Ve biliyorum istemekle olmuyor! ! !', 'Çocuktum,       oyunsuz,       oyuncaksız bir çocuk       ne kadar çocuksa.       Fesatsam biraz,       Eğer paranoyaksam hep bundan,       ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Sinan']::text[], 8.5, '{"poet":"Vedat Sinan","poet_slug":"vedat-sinan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/cocuktum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilgece bir aşk!', 'bilgece-bir-ask-vedat-sinan-bx909', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve adam çıktı yola, 

Derin bir sessizlik, 

Kırık dökük, 

Ve buruk anılar bırakarak ardında...

Güneşin doğduğu yere değin uzanıyordu sanki yol.

Kadının saçlarını buldu ışıklarda, 

Kollarını çizdi, 

Dudaklarını, gözlerini....

Gözlerindeydi hüzün, 

Küçük, güzel dudaklarından eksilmeyen kıvrımların ucunda! 

Ve hasret hiç eksilmeyen...

Oturdu kadının yanına, 

Yan yana oturdular, 

Böyle zamanlarda  akşamın sessizliğini sarartan.

Hüzünlerin esrik çığlığı değil miydi, 

Ölesiye inanıyordu adam buna, 

Her yolculuk bir vazgeçiştir.

Her yolculuk bir vazgeçiştir.

Her yolculuk bir vazgeçiştir....

Her yolculuk! 

Bir  sevgili...

Her sevgili! 

Bir yolculuk....

Her gidiş bir yok oluştur sonunda! 

Ölesiye inanıyorduk buna...

Bir sevdanın doyumsuzluğunu yaşamaktı oysa; 

Kucak kucağa uyumaları, 

Her sabaha hır, gür başlamaları.

Şimdi başka şehirlerde, 

Belki biri birinden habersiz

Yeni bir günü ağartıyorlar! 

Elbet gün dağların ardındadır şimdi, 

Ve kırlangıçlar geçiyor, 

Kırlangıçlar, 

Çooook uzaklardan!', 'Ve adam çıktı yola,  Derin bir sessizlik,  Kırık dökük,  Ve buruk anılar bırakarak ardında... Güneşin doğduğu yere değin uzanıyordu sanki yo...', ARRAY['Türk Edebiyatı','Şiir','Vedat Sinan']::text[], 8.5, '{"poet":"Vedat Sinan","poet_slug":"vedat-sinan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bilgece-bir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir Uyudu!', 'sehir-uyudu-vedat-sinan-xh4gr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'birer, birer sönüyor ışıklar, 

göz kapakları kapanır gibi usulca, 

bir hayali görmek ister gibi uzanıyorken boylu boyunca.

kafası yastığa değdi değecek.

bir günü, 

kötü bir günü bitirmek istermişcesine, 

erkenden uyuyor bu gece şehir, 

usulca!', 'birer, birer sönüyor ışıklar,  göz kapakları kapanır gibi usulca,  bir hayali görmek ister gibi uzanıyorken boylu boyunca. kafası yastığa de...', ARRAY['Türk Edebiyatı','Şiir','Vedat Sinan']::text[], 8.5, '{"poet":"Vedat Sinan","poet_slug":"vedat-sinan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sehir-uyudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Aşk', 'son-ask-onur-karanak-ti7sy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulabileceğim bir aşk olmalı; 

Yada bulmak istediğim, 

Kendisine fazla rastlanmayan 

Yada az bulunan. 

Yada kendisinden fazla bahsettiren; 

Ama unutulmayan. 

Üzerine yeminler edilen

Ve sonu olmayan.

Usulca gelen bir aşk olmalı

Kendisinde beni bulabileceğim 

Yada kendimi kaybedeceğim

Seni arayabileceğim

Yada seni özleyeceğim...', 'Bulabileceğim bir aşk olmalı;  Yada bulmak istediğim,  Kendisine fazla rastlanmayan  Yada az bulunan.  Yada kendisinden fazla bahsettiren;  ...', ARRAY['Türk Edebiyatı','Şiir','Onur Karanak']::text[], 8.5, '{"poet":"Onur Karanak","poet_slug":"onur-karanak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz ve Zaman', 'soz-ve-zaman-hilmi-yavuz-atjav', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir dağın uzantısı olmak

sana yetmediği zaman

gör ki sıradağlar talanda...

sözlere bak, bağı çözük çiçekler

gibi ortada, dağılmış duruyor

nerdesin? hangisinde? solmakta mısın

                          doğrularda ve yalanda? 

işte hangi uçurum dillerinin

dip kuytularında olmak

beni sana göre daha sınırda kılar? 

ve aramızdaki sınır

                          hangi kaybolmalarda? 

tenhayla çizilmiştir? 

her şeydir, savrulur, ama bir şey

direnir o hala bende kalanda

kayboldum akarsudan sözlerde

aktıkça yıpranan şiirlerde

ve en yabanıl olanda...

şimdi kim dindirecek, erguvanları bende? 

çünkü Söz''üm ben, Söz''üm, 

                           hem bulandım

hem de arındım aynı zamanda', 'bir dağın uzantısı olmak sana yetmediği zaman gör ki sıradağlar talanda... sözlere bak, bağı çözük çiçekler gibi ortada, dağılmış duruyor ne...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/soz-ve-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehri-emin', 'sehri-emin-vedat-sinan-tjwls', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ayyaşlar sızmıştı çoktan, her biri bir köşeye.

bir iki yankılanıp, kayboldu ara sokaklar da

son naraları da! 

pezevenk parmak uçlarında yürüyorken, 

engin bir sukunet denizinde boğulmaktadır şehir.

sessizliği bozmaya kimsenin yok cesareti! 

fahişe son müşterisini uğurlayalı çok oldu, 

bir müsekkin aldı az önce, 

şimdiyse  yudumlayıp sigarasını, 

küfürler yağdırıyor, 

hatırlayabildiklerine.

uzaktan bir kadın çığlığı duyuluyor, 

ürperiyor gece, 

pezevenk parmak uçlarında yürüyorken, 

fahişe son müşterisini uğurlayalı çok oldu, 

bir ben yalnızım bu saatlerde, 

birde, 

yolculuk hissi veren sokak lambaları.', 'ayyaşlar sızmıştı çoktan, her biri bir köşeye. bir iki yankılanıp, kayboldu ara sokaklar da son naraları da!  pezevenk parmak uçlarında yürü...', ARRAY['Türk Edebiyatı','Şiir','Vedat Sinan']::text[], 8.5, '{"poet":"Vedat Sinan","poet_slug":"vedat-sinan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sehri-emin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küller ve Zaman', 'kuller-ve-zaman-hilmi-yavuz-hsgvk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman, dilsiz çocuk, Zaman...

bana neler söylemek istedin? 

sözcüklere yağan kar''dın

izini yitirdim bakışlarda

bir külün içinden okuyuşlarda

kar''dın, kendini küredin

Zaman, dilsiz çocuk, Zaman...

ince aşklarla yırtılan

sendin, yollarla erguvan

sunulmuş lanetli kışlardan

aldığım belirsiz dokunuşlardan

kopan tenini dinledin

Zaman, dilsiz çocuk, Zaman...

sözcüklerin ardında duran

melektin, kendini okuyan

Söz''ün geldiği durumu

yaprak ve külden olduğumu

belki onlarda söyledin

Zaman, dilsiz çocuk, Zaman...', 'Zaman, dilsiz çocuk, Zaman... bana neler söylemek istedin?  sözcüklere yağan kar''dın izini yitirdim bakışlarda bir külün içinden okuyuşlarda...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kuller-ve-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kharybdis ile Skylla', 'kharybdis-ile-skylla-hilmi-yavuz-qkdul', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ölümle yeşil arasında

ne var? bir mağara durur

ve ötekini dinler, mağrur

bir çocuk sığınmıştır dağa

at biner gibi biniyor

tadılan bir şey midir akşam

bir sözün bulutunda

bir uçurumun yasında? 

ölümle yeşil arasında

hep onlar var! terkideki

çocukta bir dağ, bir daha

ötekinin yerini alıyor

çoktan terkedildi bir bahara

ebruli sözler: teyze, hala

bir ev yılanının saçlarında

bir büyünün kokusunda

ölümle yeşil arasında

kimler onlar? anne, baba

daha sağlar, dağlar ne yapıyor

diye dışarı uzandı biri

bir yalnızlık ötekine karıştı

baba ıssız, anne tenha

bir kentin yaprağında

bir nehrin yarasında

çocuğuysa işte öylece andım

ölümle yeşil arasındandım

yollar da oralıdırlar', 'ölümle yeşil arasında ne var? bir mağara durur ve ötekini dinler, mağrur bir çocuk sığınmıştır dağa at biner gibi biniyor tadılan bir şey mi...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kharybdis-ile-skylla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü''sün, Yaz!', 'buyu-sun-yaz-hilmi-yavuz-s0in6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben hep yollar düşledim

derin yollarda yürürken

yollar gül sesleridir

beni yazın ta içine çağıran

gitsem mi? yoksa daha 

                              erken

mi akşamın kovanında

anılar oğul verirken

senin gittiğin yollar

bana dolanan yollardır

solduğum bir büyük

ormandır acılarım

                  geçmişten ve gürgen

ve derin bulut sözleri olarak

yazlar kalbime girerken

ah bellek, acı bellek! 

hem arısın sen

hem kimbilir hangi gülden

                     kalma diken? 

ve ne uzun bir büyü''sün, yaz! 

gurbetler senin ülken, yalnızlar senin ülken

ben hep yollar düşledim

derin yollarda yürürken', 'ben hep yollar düşledim derin yollarda yürürken yollar gül sesleridir beni yazın ta içine çağıran gitsem mi? yoksa daha                     ...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/buyu-sun-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldatmak Üzerine Sorular', 'aldatmak-uzerine-sorular-can-akin-2-xx0sp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerden aklıma geldi bilmiyorum: 

Seni bir başkasıyla aldatsam, 

Kızarmısın bana sevdiğim? 

Bu mülkiyetsiz ilişkimizde, 

zaten sahipli hayatlarımızı, 

Bir başkasıyla daha paylaşsam, 

Kızarmısın bana? 

Terk mi edersin beni yaşlı gözlerle? 

O suskun, acımasız bakışlarına bürünüp, 

Yavaş yavaş öldürürmüsün beni yoksa gün be gün...

Peki, kızmaktan öte, 

Böyle olmaması için birşeyler yaparmısın? 

Çabalarmısın beni kaybetmemek için sevdiğim? 

Aşkınla gözlerimi kör edermisin? 

Ellerimi hiç bırakmamacasına tutar, 

Birşeyleri göze alabilirmisin? 

Yoksa zaten, 

Bu yıkıntılara alışkınmısın sevdiğim, söylesene? 

Ya sen, 

Sen birtanem, 

Sen beni aldatırmısın bir başkasıyla daha? 

Öyle sırf canın çekiverdi diye, 

Bana kızdın diye, 

Sana uzak kaldım diye, 

Şundan diye, bundan diye...

Yaparmısın sevdiğim söylesene? 

Sonra, hiç bir şey olmamış gibi, 

Yorgun ruhlarımıza yüklenen bütün rolleri, 

Oynayabilirmisin tüm rahatlığınla sevdiğim? 

Zaten yılgın, zaten üşümüş bedenlerimizi, 

Gömermisin yaşamın soğuk yoz okyanuslarına bir kez daha? 

Bonkörce, umarsızda tüketilmiş sevdalara, umutlara, 

Eklermisin bir yenisini daha?', 'Nerden aklıma geldi bilmiyorum:  Seni bir başkasıyla aldatsam,  Kızarmısın bana sevdiğim?  Bu mülkiyetsiz ilişkimizde,  zaten sahipli hayatl...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aldatmak-uzerine-sorular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göründüğün Gibi Değilsin, Anladım', 'gorundugun-gibi-degilsin-anladim-can-akin-2-ckria', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün sana çok kızdım sevdiğim, 

Anladım: Göründüğün gibi değilsin sen...

O masum, o çocuksu sevecen yüreğin, 

Bir de karanlık yanı var ara sıra kıpırdanan...

Belki de bir sevda değil, 

Acımasızca bir oyun bu

O karanlık tarafın bana oynadığı...

Niçin bana güvenmiyorsun sevdiğim? 

Nasıl bekleyebiliyorsun bunları benden? 

Kendimi çok kötü hissettim yahu...

Kırıldım...Parçalandım birden bire...

Oralı bile olmadın sense...

Takınıverdin o buz gibi, o beni delirten bakışlarını...

Göründüğün gibi değilsin sevdiğim, 

Anladım, 

Ağladım...', 'Bugün sana çok kızdım sevdiğim,  Anladım: Göründüğün gibi değilsin sen... O masum, o çocuksu sevecen yüreğin,  Bir de karanlık yanı var ara ...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gorundugun-gibi-degilsin-anladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalandım', 'sevdalandim-tolga-aus-duisburg-99r58', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kurban olayim o güzel dudaklarina, 

Ne olur gel gir artik koynuma, 

Ismini sayiklamaktan aptal oldum

Gel Gel artik gel birtanem yanima.', 'Kurban olayim o güzel dudaklarina,  Ne olur gel gir artik koynuma,  Ismini sayiklamaktan aptal oldum Gel Gel artik gel birtanem yanima....', ARRAY['Türk Edebiyatı','Şiir','Tolga aus Duisburg']::text[], 8.5, '{"poet":"Tolga aus Duisburg","poet_slug":"tolga-aus-duisburg","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevdalandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam Benim Canim Anam', 'anam-benim-canim-anam-sair-anonym-lvg2q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bebektim baktin, egittin büyüttün beni, 

Her lokmandan koparip pay ettin asima, 

Bak simdi geldim yasima! 

Sayende anam sayende yasiyorum ben bu hayati! 

Ayagina bag oldum, sen aldirmadin

Yüreginde dert oldum, bir anda silip attin! 

Ana yüregi buna derler! 

Hem ilac olur derde, hem yar olur serde! 

Anam benim Canim anam, kizini büyüten anam

Elleri catlak saci beyaz anam, 

Tüm derdime devam, Gelinlik kiz ettin beni

Hasretine dayanamam, gözlerine bakamam.', 'Bebektim baktin, egittin büyüttün beni,  Her lokmandan koparip pay ettin asima,  Bak simdi geldim yasima!  Sayende anam sayende yasiyorum be...', ARRAY['Türk Edebiyatı','Şiir','Şair Anonym']::text[], 8.5, '{"poet":"Şair Anonym","poet_slug":"sair-anonym","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anam-benim-canim-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akışkanlar Mekaniği', 'akiskanlar-mekanigi-duygu-gunkut-a574x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gereksiz sevişmelerin

Ertesi sabah hüzünlerinden

Unutulmaya mahkum

Kadınları sarmış sarmalamış, 

Onları bir hediye paketi gibi açmış, 

Kendilerini onlara hediye etmiş, 

Sonra da sessizce sarıp

Fiyonkları ince boyunlarına, 

Bana gelmek üzereydin.

Bana sarılmak üzereydin.

Işığını kaybetmiş bir deniz feneri gibi, 

Kör karanlıklardan kendini geri çağıran

Kadın bendim.

Sirenlerin çığlıklarını, 

Işığını bulmak için çağılmış zanneden.

Kanatları kirli, ağzı kanlı

Tüm martıları

Yalnızlığının üzerinde konuk eden.

Kör kadın bendim.

Ben kendi kahkahamı özlemiştim, 

Sen ise bendeki hüznü sevmiştin, 

Gitgide daha hüzünlü beni...

Sarılmak istediğin gerçekte, 

Ben miydim, 

Yoksa hüzün mü söyle? 

Aşktı iki kişilik bir yalnızlık, 

Yalnızlık tam iki kişilik bir aşktı.

Bu devirde bu tam da

Arzu edilen bir frekanstı.

İki kişinin birbirine akması, 

Önce doldurması, 

Sonra boşaltması, 

Sırayla ruhun bedeni

Ve sonra da bedenin aşkı

Tekrar dolabilsinler diye.

Ve karşılıklı.

Sonsuzluktur bu

Aşkı aşk, 

Seni ben

Ve beni sen yapan

İki kişilik bir yalnızlık yaratan.

Sadece sarılmayı düşlemiştik

Birbirimizin hüznüne

Nazikçe, 

Düşen bir gül gibi

Sedef bir sandukanın üzerine.

Sonra görmek istedik, 

Görünce ışığı, akmak istedik

İvme alarak akışkanlar mekaniğinden

Birbirimizin hüzün seline.

Korkutan bilinmezliktir

Ne kaybedeceğini bile bilememek

El yordamıyla ilerlenen

Karanlık dehlizlere girmek.

Korkuyorum, 

Kendimi kaybetmekten, 

Kendimden önemli

Neyi kaybedebilirim, bilememekten.

Haydi, 

Bana beni anlat! 

Bana kendimi hatırlat...', 'Gereksiz sevişmelerin Ertesi sabah hüzünlerinden Unutulmaya mahkum Kadınları sarmış sarmalamış,  Onları bir hediye paketi gibi açmış,  Kendi...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/akiskanlar-mekanigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YC''ye....', 'yc-ye-ahmet-salih-ekici-2y4c2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollar bitirdi tükenmez sandığımız sevdayi

Mesafeler hep vardı ben açmadım arayı

Beyaz soyunmuş ruhuma sen giydirdin karayı

Kanatan gelsin iyileştirsin bu yarayı...', 'Yollar bitirdi tükenmez sandığımız sevdayi Mesafeler hep vardı ben açmadım arayı Beyaz soyunmuş ruhuma sen giydirdin karayı Kanatan gelsin i...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Salih Ekici']::text[], 8.5, '{"poet":"Ahmet Salih Ekici","poet_slug":"ahmet-salih-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yc-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbullu Zweig', 'i-stanbullu-zweig-husrev-hatemi-bjlbh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İkinci Dünya Savaşı yıllarını yaşamış, 

Ne kuş var ne kedi ne köpek çevremde...

Beyazıttaki çınar, 

Ve Üniversite kapısı da olmasa

Kendimi Kamerde bileceğim.

Mecidiyeköy dutlukları çoktan

Ezelî Arşivde yer aldılar

Ve Beyazıttaki Çınar

-Hatıra-i celâdet topunu görmüş olarak-

''Burada bir de havuz vardı'' diyor

Ben ise Zweig''ın Viyana''yı, 

Petropolis''ten özlediği gibi

Eski İstanbul''a Petropolis kadar uzak

Yeni İstanbul''da, 

Eski İstanbul''u özlüyorum.', 'İkinci Dünya Savaşı yıllarını yaşamış,  Ne kuş var ne kedi ne köpek çevremde... Beyazıttaki çınar,  Ve Üniversite kapısı da olmasa Kendimi K...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istanbullu-zweig-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Say ki', 'say-ki-bilal-sahin-k2a7x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Say ki

Dışarıda yağmu yağıyormuş

Islak bir kedi 

Çaresiz camdan içeri bakıyormuş

Serçelerse yok ortalıklarda

Belli ki

Sığınmışlar saçk altlarında

Ve kaldırımlar yalnız

Ah o kaldırımlar kucak açmış

Yorgun dallarından düşmüş

Solgun yapraklara

O yapraklar ki

Ölüm gibi

En derin uykuda

Say ki

Dışarda fırtına varmış

Deniz kabarmış

Çılgın dalgalar sahile vuruyormuş

Sandallar kızağa çekilmiş

Yalnızlığa bağlanmış yanı

Oysa ki

Gönülleri

Sevdalarında kalmış

Islak gözlerle 

O yare

Bakmakta hepsi

Ve martılar

Ah o martılar

Yağmur duasına çıkmış gibi

Açmışlar kanatlarını

Her çığlıkları

Birer şükür, birer amin

İşte öyle bir şey sensizlik

Seni sevmek

Severken ayrı düşmek

Ve vuslatı beklemek

Yağmur bulutları dağıldığında

Doğacak Güneşi özlemek...', 'Say ki Dışarıda yağmu yağıyormuş Islak bir kedi  Çaresiz camdan içeri bakıyormuş Serçelerse yok ortalıklarda Belli ki Sığınmışlar saçk altla...', ARRAY['Türk Edebiyatı','Şiir','Bilal Şahin']::text[], 8.5, '{"poet":"Bilal Şahin","poet_slug":"bilal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/say-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuşum', 'unutulmusum-umit-besen-k7n1o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Maziye gömülmüş bir hayal gibi

Anladım ne yazık unutulmuşum

Dilinde çok eski bir masal gibi

İnandım ne yazık unutulmuşum

Oysa ki kalbimde bitmez ümittin 

Sen benim gönlümde dinmez hasrettin

Kanımdın canımdın gerçek aşkımdın 

Yanıldım ne yazıkunutulmuşum

Ben seni kendime güneş sanırdım

Aşkınla tutuşan ateş sanırdım 

Bir sevgili bir dost bir eş sanırdım

Aldandım ne yazık unutulmuşum', 'Maziye gömülmüş bir hayal gibi Anladım ne yazık unutulmuşum Dilinde çok eski bir masal gibi İnandım ne yazık unutulmuşum Oysa ki kalbimde bi...', ARRAY['Türk Edebiyatı','Şiir','Ümit Besen']::text[], 8.5, '{"poet":"Ümit Besen","poet_slug":"umit-besen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutulmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-gulseren-onay-rugg9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç kimseyi böylesine sevmedim, bebeğim

Seni sevdiğim kadar, 

Hiç kimsenin gözlerine bakmadım

Senin gözlerine baktığım gibi, 

Hiç kimseyi istemedim 

Seni istediğim kadar....

Duydun mu sazların fısıldadığı

O hüzzam şarkıyı

Veda ederken o akşam kızıllığında

Ay tanrıçası Artemis

Yol boyunca gizli gizli döktüğüm 

Gözyaşlarını anlattı mı? 

Ya yıldızlar

Söylediler mi? 

Yüreğimdeki burukluğun nedenini sana....

Ben senden ayrılmayı hiç istemedim, bebeğim

Senden kopmayı asla....

Ben hiç kimseyi senin kadar sevmedim, bebeğim

Hiç kimseye dokunmak istemedim

Sana dokunmak istediğim kadar

Hiç kimseye..........', 'Hiç kimseyi böylesine sevmedim, bebeğim Seni sevdiğim kadar,  Hiç kimsenin gözlerine bakmadım Senin gözlerine baktığım gibi,  Hiç kimseyi is...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/itiraf-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili''ye....', 'sevgili-ye-candan-aydogan-lb5k5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ne hoştur bilirmisin; 

Seni düşünerek, çıplak tenin çarşafla sevişmesi....

Ve dinlemek, 

Sabah serinliğinde öten serçeleri....', 'Sen ne hoştur bilirmisin;  Seni düşünerek, çıplak tenin çarşafla sevişmesi.... Ve dinlemek,  Sabah serinliğinde öten serçeleri.......', ARRAY['Türk Edebiyatı','Şiir','Candan Aydoğan']::text[], 8.5, '{"poet":"Candan Aydoğan","poet_slug":"candan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgili-ye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '17 Ağustos', '17-agustos-abdullah-karaduman-2vrtc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tarih 17 Ağustos 1999 

Saat 03.00 

Günlerden Salı 

Karabir acı  masalı, 

Karanlıktan bir ses duyuluyor, 

Karanlıktan binler duyuluyor 

Uykunun en tatlı yerinde 

Yırtarcasına sessizliği. 

Anneeeee! 

Nerdesiiiiin? 

Ah, yanımdaymışsın. 

Bir an korktum beni bıraktın diye, 

Çünkü biliyorum bensiz yapamazsın 

Ellerin neden buz gibi oldular anne? 

Oysa hava çok sıcaktı akşam yatarken! ! ! 

Gece bir rüya gördüm biliyor musun? 

Sen beni bırakmış ve cennete gitmiştin. 

Arkandan seslendim. 

Ağladım ama beni duymadın 

Arkana bile bakmadın. 

Çok korktum anne, çok. 

Ellerin neden buz gibi? 

Yanaklarında öyle! 

Gözlerin bembeyaz olmuş, 

Saçlarına yıldız düşmüş, 

Hani tatilde dağa çıkacaktık ya 

Ve sen yüksekler soğuk olur, 

Nefes almak ta zordur derdin ya 

Anne, anneciğim. 

Yükseklerden mi geldin.? 

Yoksa ben uyurken oralara mı gittin? 

Hani beraber gidecektik? 

Anne üşüyorum. 

Gözlerime toprak doluyor. 

Nereden geliyor bu sesler. 

Anne, üşüyorum tut ellerimi 

Gözüm yanıyor, içim kanıyor, 

Kalbim acıyor. 

Neden karardı hava? 

Anne, anneee, anneciğim nerdesiinnn…? 

Anne! Buradaymışsın? 

Biliyordum. 

Biliyordum beni bırakmayacağını. 

Bak babamda burada, abim, ablam 

Tüm komşular, herkes gelmiş… 

Anne! ? ! ? ! ? 

Burası neresi? 

…………………………. 

- Cennet yavrum! ! !', 'Tarih 17 Ağustos 1999  Saat 03.00  Günlerden Salı  Karabir acı  masalı,  Karanlıktan bir ses duyuluyor,  Karanlıktan binler duyuluyor  Uykun...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/17-agustos-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım Firari', 'umutlarim-firari-hakan-sengun-rudju', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce gurur terk etti 

Sonra sen

Sonrasında akşam oldu zaten

Uyumadım sabahına dek.

Güneşin batışına

Kaç sefer şahit olduki gözlerim

Korkmadan diyebilsin

‘’ bende özlerim ‘’ diye

Giden sevgiliye.

Batışını özlesin, doğuşunu özlesin

Sanki hala varmışcasına

Yollarını gözlesin 

Taparken ay ışığına.

Umutlar bedenimi geceleri terk eder

Karanlıkta kaçarlar.

Nede olsa bedenimde tutuklu yaşar onlar.

Peşlerinde arta kalan hasreti ve yokluğu

Aydınlıkta alırlar bir çırpıda soluğu.

Ben oldum olası hiç sevmedimki soğuğu

Yinede inadına yalnız geçti soğuk günler

Ve anlatmaya değmeyen klişe geceler.', 'Önce gurur terk etti  Sonra sen Sonrasında akşam oldu zaten Uyumadım sabahına dek. Güneşin batışına Kaç sefer şahit olduki gözlerim Korkmada...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/umutlarim-firari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yassı Hüzünler', 'yassi-huzunler-duygu-gunkut-qqwue', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yassı hüzünlerim oldu

Yalnız yaşamımda

Ağlayamadım.

Sınırlara dayalı

Ve sınırlara kadar dayanan

Dilsizliğim

En pahalı suskunluklarımdı, 

Belki de

Bir yaşama malolan…

Yassı hüzünlerimi

Suskunluğumda

Bir taş gibi kaydırdım.

Bu ustalıkla

Herkesi kandırdım.

Gidiyorum şimdi

Futursuzca.

Tek bir çocuğun yanağına

Bir tek öpücük bile kondurmadan.

Suya atılan

Dilsiz bir taş gibi

Hüzünleri suskunluğa

Ve suskunluğu hüzünlere taşıyan, 

Ustalıkla, aranızdan…', 'Yassı hüzünlerim oldu Yalnız yaşamımda Ağlayamadım. Sınırlara dayalı Ve sınırlara kadar dayanan Dilsizliğim En pahalı suskunluklarımdı,  Bel...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yassi-huzunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nelere Değer', 'nelere-deger-huseyin-akgul-3dgw8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabır dağımda bir papatyasın, 

Tazecik açışın nelere değer.

Bu ağız her daim seni söylesin, 

Bir kez dinleyişin nelere değer.

Yürek iki parça kimle eklesin, 

Gece güneşi, yıl asrı beklesin, 

Gelme diyorlar allah saklasın, 

Ayak seslerin nelere değer.

Ummanlardan öz bir soru

Gözlerdir sevenin yolu, 

ol çileyen yağmur, ol haşin dolu

Bakıverişin nelere değer.

Cefalar dertler beni kahretsin, 

Ayak çölde kafam buzulda gezsin, 

Gücü yeten kalem varsa yazsın, 

Bir gülüverişin nelere değer.', 'Sabır dağımda bir papatyasın,  Tazecik açışın nelere değer. Bu ağız her daim seni söylesin,  Bir kez dinleyişin nelere değer. Yürek iki parç...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Akgül']::text[], 8.5, '{"poet":"Hüseyin Akgül","poet_slug":"huseyin-akgul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nelere-deger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın 1', 'adin-1-huseyin-akgul-q9c7n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne adını ben anabildim, ne kalem, 

Duygu bağım çöl çöl oldu kurudu...

kalbimdi hasmıma yıkılmaz kalem, 

Duvarları toz toz oldu kurudu...

Bahar diye yaşadığım kara kış, 

Sevda denen hem gerçek, hemde düş, 

Akıl almaz, sır mayalı ince iş, 

Kaderini iz iz kendi aradı...

Aşk niyetse tatmalıdır her gönül, 

Umuda ter dökmelidir; her gönül, 

Geceden ak sökmelidir her gönül, 

Akgül göz göz söktü kurudu...

Olacağa ve öleceğe olmaz çare, 

Bulurum derdime yeniden çare, 

dilimde, kalemde o eski çare

Adın yine az az aktı yürüdü...', 'Ne adını ben anabildim, ne kalem,  Duygu bağım çöl çöl oldu kurudu... kalbimdi hasmıma yıkılmaz kalem,  Duvarları toz toz oldu kurudu... Bah...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Akgül']::text[], 8.5, '{"poet":"Hüseyin Akgül","poet_slug":"huseyin-akgul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adin-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznün Kuşları', 'huznun-kuslari-cemal-sureya-6g11n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben bütün hüzünleri denemişim kendimde 

canımla besliyorum şu hüznün kuşlarını 

bir bir denemişim bütün kelimeleri 

yeni sözler buldum seni görmeyeli 

kuliste ya
..........
..........', 'ben bütün hüzünleri denemişim kendimde  canımla besliyorum şu hüznün kuşlarını  bir bir denemişim bütün kelimeleri  yeni sözler buldum seni ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/huznun-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Moskofname', 'moskofname-osman-yuksel-serdengecti-xbavc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dedelerimden kalma intikam var kanımda

geçmişini s... bulgarın moskofun da

bir domuz görmüş gibi ayaklanır hislerim

alçakların sesini dinlerken mikrofonda.

o kadar gururlanma, o kadar mağrur olma

dün daha kölemizdin mahvolmuştun Prutta Yalnız şunu isterim yalnız şunu hatırla Yatmıştı katerina Baltacının koynunda', 'Dedelerimden kalma intikam var kanımda geçmişini s... bulgarın moskofun da bir domuz görmüş gibi ayaklanır hislerim alçakların sesini dinler...', ARRAY['Türk Edebiyatı','Şiir','Osman Yüksel Serdengeçti']::text[], 8.5, '{"poet":"Osman Yüksel Serdengeçti","poet_slug":"osman-yuksel-serdengecti","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/moskofname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Salih Varmış', 'bir-salih-varmis-salih-ozalasan-m8xp0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevip sevilmek çok güzeldi ya

Sevmesini bileni bulmak lazımmış

Yüreğin vermek yetmiyor insana

Yüreği olanı bulmak lazımmış

Sevip sevilmeniz yetmezki mutluluğa

Sevgiyi yaşatmaya sabır lazımmış

Elinizi uzatsanız el tutulmazki

Karşıdan elini uzatacak biri lazımmış

Yüreğiniz küçücük sığrıramassınız sevdiğinizi

Ama hayat bu, sevgileri paylaşmak lazımmış

Bir sen bir ben olurmu hayatta

Sende öğren, bir kaç dost bulmak lazımmış

Sevgiler kıskanılır, bülbülün gülü kıskandığı gibi

Sende anla sevene çok sabır lazımmış

Sevdiğim bir bana kalsın diyemessin

Bileceksin hayatta vazgeçilmez dostlar varmış

Aslında bilirsin ama işine gelmez

Mutluluk için biraz özveri lazımmış

Salih garip bir deli divane derdim ya

Meğerse ne çok seven dostu varmış

Dostlarım size yürekler dolusu teşekkür

Bilinki sizi çok seven bir SALİH varmış

Y.Tarihi 22-08-2002 Saat 10.00', 'Sevip sevilmek çok güzeldi ya Sevmesini bileni bulmak lazımmış Yüreğin vermek yetmiyor insana Yüreği olanı bulmak lazımmış Sevip sevilmeniz ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-salih-varmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tabletler -III-', 'tabletler-iii-mahmut-bingul-ou1cs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Var mı biri 

Beni bana anlatan, 

Sonsuz boşluktaki noktaya bakan 

Bakışlarımı kıracak, 

İçimi bana anlatacak.

Yüreğimde depolanan hevesimi

Benden habersiz okuyacak

Yaşamın doğallığını 

Sonsuzluğun yaratılış nedenini

Biri var mı bana beni anlatan...', 'Var mı biri  Beni bana anlatan,  Sonsuz boşluktaki noktaya bakan  Bakışlarımı kıracak,  İçimi bana anlatacak. Yüreğimde depolanan hevesimi B...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tabletler-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tabletler -IV-', 'tabletler-iv-mahmut-bingul-3a5tr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessizlik! 

Dünya sessiz

Gece sessiz 

Yapraklar durgun, sakin

Bir sarhoşun narası bozuyor

karanlığın sessiz rengini

ve aşklarımız bitiyor

sessiz çığlıklar içinde.

bitiyor, 

bitiyor saatler

bitiyor zaman

tükeniyor sevgiler...', 'Sessizlik!  Dünya sessiz Gece sessiz  Yapraklar durgun, sakin Bir sarhoşun narası bozuyor karanlığın sessiz rengini ve aşklarımız bitiyor se...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tabletler-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tabletler -V-', 'tabletler-v-mahmut-bingul-f1p1r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saat 04: 20

Bir sigara sarıverdim kendime

Çekince! 

Sen geliverdin içime

Başım dönüverdi kendince

Reyhana baka durduk seninle! ...', 'Saat 04: 20 Bir sigara sarıverdim kendime Çekince!  Sen geliverdin içime Başım dönüverdi kendince Reyhana baka durduk seninle! ......', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tabletler-v-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arz u Hal', 'arz-u-hal-mahmut-bingul-kxli4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve İstanbul''dayım

Alışamadım

İETT otobüslerinde 

seyahat yapmanın yorgunluğundayım

Bir çay içmek istemiştim, 

Türk çayını verdiler.

Kaçak çayı aradım

Yorgunluğumu atamadım

Aspirin içtim

Kesilmedi başımın ağrısı

Ranzama uzandım, 

Başımı yastığa koydum, 

Rengi solmuş, 

Kirlilikten yeni renk kazanmış

Yurt-Kur damgalı yastık

İsmim 

kulaklarımı çınlatacak diye

kulaklarım anonsların sesinde 

belki sıcaklığını özlediğim ailem 

ya da 

yalnızlığımı paylaşacak bir arkadaş

aranmayı bekliyor gönlüm

Denizin 

o mavi dar boğazında

vapurlar 

denizle hırçın hırçın sevişirken

Kalbim 

Kız Kulesi''ne hapsedilmiş 

Ben ise

Cansız ve ruhsuz

Dolaşıyorum İstanbul sokaklarında 

Ekim 1997

H.A.Y. Yurdu / İçerenköy', 'Ve İstanbul''dayım Alışamadım İETT otobüslerinde  seyahat yapmanın yorgunluğundayım Bir çay içmek istemiştim,  Türk çayını verdiler. Kaçak ça...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/arz-u-hal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Doğuyor', 'gunes-doguyor-mahmut-bingul-o4cay', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Patlamış ayışığı altındayım

Saçlarıma süzülür ay parıltısı 

temiz ve berrak

Seheri beklerim

Horozların ötüşüyle 

Doğ güneş doğ! 

Doğ ki tabiat canlansın

Karıncalar fışkırsın yuvalarından 

Ana kuşlar yem aramaya koyulsun 

Sürüler sürülsün kavallar çalınsın

Doğ ki 

sıcaklığın tenimi okşasın...', 'Patlamış ayışığı altındayım Saçlarıma süzülür ay parıltısı  temiz ve berrak Seheri beklerim Horozların ötüşüyle  Doğ güneş doğ!  Doğ ki tabi...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunes-doguyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Sitem', 'gule-sitem-mahmut-bingul-xctx1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küstün mü bana 

Benden habersiz 

Dağı, taşı haberdar eden gül.

Gülüvermedin, 

tebessümlere, 

gülüşlere hasret yüzüme

Doğayla barışık, 

benimle dargın

Suyunu topraktan 

ışığını güneşten aldın diye

doğayla barışık benimle küskün.

Pragmatistler gibi

karşılıksız gülüvermedin yüzüme

Seni koklamadan, 

içimi gıcıklatan

yumuşak kokunu, 

çekmeden önce.', 'Küstün mü bana  Benden habersiz  Dağı, taşı haberdar eden gül. Gülüvermedin,  tebessümlere,  gülüşlere hasret yüzüme Doğayla barışık,  benim...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gule-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Doğdu Bebeğim', 'olu-dogdu-bebegim-mahmut-bingul-xhafq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk bebeğim doğdu! 

Ne umutlarla bekledim onu 

bir bilseniz, 

ne acılar çektim.

Sevgimi sakladım, gizledim

Zavallı annesi 

nasıl da taşıdı karnında dokuz ay

Ne acılar çekti bir bilseniz 

Cinsiyeti önemli değildi

Bir insandı! 

Ve bir sevginin tohumuydu

Ama 

ölü doğdu sevgimiz, 

Ölü doğdu bebeğim', 'İlk bebeğim doğdu!  Ne umutlarla bekledim onu  bir bilseniz,  ne acılar çektim. Sevgimi sakladım, gizledim Zavallı annesi  nasıl da taşıdı k...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olu-dogdu-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Gemisi', 'askin-gemisi-mahmut-bingul-mc56r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğine demir atan 

bir aşk teknesiyim 

Titretirsin tenimi okşayışınla

Bir o yana bir buna yana

sallanır dururum içinde

Ne sen bırakırsın beni 

ne de ben seni

Alır götürürsün beni

bilinmezliklere

en tenha yerlere

İçine alırsın beni

Fırtınalara verirsin 

Acımazsın bana! 

Üşürüm-üşürüm 

Ateşe atarsın beni

yanarsın.

En son derin bir çığlık

durdurur seni

sakinleşir 

durulursun 

Ve şimdi! ...

Masum bir kedinin sessizliğidir

suskunluğun

Korkma! 

Terleyişimizdendir ıslaklığımız

sevişmelerimizden...', 'Yüreğine demir atan  bir aşk teknesiyim  Titretirsin tenimi okşayışınla Bir o yana bir buna yana sallanır dururum içinde Ne sen bırakırsın b...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/askin-gemisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senmi?', 'senmi-sair-karagozlum-a7wr8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zannedin ki kendini

senmi ögrettin bana sevmeyi? 

yoksa seviyormus gibi yapip terketmeyimi

Sanmaki senden baskasini bulamam

sanmaki senden haric kimseye baglanamam

Gecti artik sildim seni hayatimdan

sen kimsinki? 

Benim icin bir hic

bes para etmez bir alcak

senmi sevgiye layik olan

senmi avuc icinde tutulan

Artik bittin sen

benim icin yoksun ve hic olmadin

zannetmeki aglarim ardindan

zannetmeki yanarim askindan

benim icin sen öldün

sirtimdan vurdunya iste o anda gömüldün

ozamanlar utanmadinki yaparken

simdimmi aklin basina geldi ayrilirken

cok arasin artik beni

ama bulamazsin

bulsanda ben seni farketmemki

icimde besledigim sevgi

artik kalbimin 

EN BÜYÜK NEFRETI', 'Ne zannedin ki kendini senmi ögrettin bana sevmeyi?  yoksa seviyormus gibi yapip terketmeyimi Sanmaki senden baskasini bulamam sanmaki sende...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/senmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiyem', 'turkiyem-sair-karagozlum-iegc6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siir yazar türkü söylerim

yere göge sigdirarmam memleketim diye överim

vatanimi diyar diyar gezerim

NE MUTLUM TÜRKÜM diye gururla söylenirim.

Tasimi dersin topraginimi

yoksa tertemiz havasinimi

ya daglardan varoslardan akan suyunami

esi yoktur memleketinim

iste TÜRKIYEM kirmizi beyaz bayragim benim.

Ne türküler söyletti

ne destanlar yazdirdi

alin teriyle bizim icin böyle feth edildi

her kösesinden okunanan ezanlar hic bir zaman dinmedi

Dinmezde dinmeyecek

bu vatan ezanlarla ayakta kalacak

üzerine ayyildiz örtülecek

ve karinca misalih türkler cogalacak

Ey avrupa duy sesimizi

bu gelen Türkiyenin hedefli sözleri

sanmaki sensin dünyanin lideri

yazacaktir elbet Tarih kitaplari Türkiyenin

zaferini.

Bizler Türküz Türk de kalacagiz

Bayragimizi gururla sunacagiz

kendimizi NE MUTLU TÜRKÜM diyerek anacagiz

dünya döndükce nesiller büyüdükce

hep sizlerle karsilacagiz

Bu bayrak inmez inmeyecekdir

Tasina kazinmis TÜRKIYEM silinmeyecektir

Mehmetcikler tükenmez zaferimiz bitmeyecektir

bu gözyaslari ey memlektim senin icin dinmeyecektir.

Acimiz büyüktür yarali olan Mehmetcikler

vatani icin sehit olan liderler

arkada gözüyasli analar

BABA diye bagirip yetim yavrular.

Birde hasret acisi ceken sevdalilar.

Gururluyum mutluyum böyle vatanin insani olarak 

bizler oldukca bu vatan hic solmayacak

NE MUTLU TÜRKÜM  diyene............................', 'Siir yazar türkü söylerim yere göge sigdirarmam memleketim diye överim vatanimi diyar diyar gezerim NE MUTLUM TÜRKÜM diye gururla söylenirim...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/turkiyem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni, Benim Seni Görebileceğim Biçimde Ara', 'beni-benim-seni-gorebilecegim-bicimde-ara-emre-ugur-kucukyagci-9dhx8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni aramaya çıkarsa düşlerin 

Hüznün ruhuna çizdiği resimlerdeyim 

Gamsız bir gecenin karanlığında değil 

Yüreğinde kanayan kesimlerdeyim 

Aklına düşerim hani olur da 

Güzelliklerin görünmeyen yüzünde ara 

Sevginin menfaate döndüğü yerde 

Bir gönül yarasının izinde ara 

Yıkılmış umutların enkazından geç 

Öksüz bir çocuğun gözünde ara 

Ağıtların tüttüğü evlere uğra

Bir ananın boş kalmış dizinde ara 

Beni yıldızlarda arama boşa

Yüreğini yasa boğan sızılardayım 

Dertlerinle bulursun beni başbaşa 

Senin gibi karayazılardayım 

Sahte sevgileri tanımaz kalbim 

Beni seven gönüllerin ocağında ara 

Menfaatle bakmasını bilmez gözlerim

Beni gerçek dostlukların kucağında ara

Mutluluğu anlatan şarkılarda değil 

Yaralı yüreklerin ağıtlarında ara

Beni menfaat ve ihanetten uzakta 

Yağacak sevgi bulutlarında ara

Öyle senden çok uzaklarda değilim 

Görmesini bilen gözlerin bakışındayım

Belki sana senden daha yakın bir yerde 

Çarpan kalbinin her atışındayım

Aklına düşerim hani olur da 

Beni sığmadığın duyguların içinde ara 

O kadar da kolay bulurum sanma

Beni benim seni görebileceğim biçimde ara.', 'Beni aramaya çıkarsa düşlerin  Hüznün ruhuna çizdiği resimlerdeyim  Gamsız bir gecenin karanlığında değil  Yüreğinde kanayan kesimlerdeyim  ...', ARRAY['Türk Edebiyatı','Şiir','Emre Uğur Küçükyağcı']::text[], 8.5, '{"poet":"Emre Uğur Küçükyağcı","poet_slug":"emre-ugur-kucukyagci","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/beni-benim-seni-gorebilecegim-bicimde-ara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımlayamadığım Tamamlayamadığım', 'tanimlayamadigim-tamamlayamadigim-kursat-usalan-zklbi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneşte bir gül açmış

Yaprağında şebnem durusu

	Duruşu…

Taze bir sen

	Ben…

Yedi iklim zamparası

	Dahası…

Gözlerin gözlerimin aynası

Ve gecenin bir vaktinde

Patlayacağız belki de

Kül ve dumanlar içinde

			04.01.1994

			ANKARA', 'Güneşte bir gül açmış Yaprağında şebnem durusu 	Duruşu… Taze bir sen 	Ben… Yedi iklim zamparası 	Dahası… Gözlerin gözlerimin aynası Ve gecen...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tanimlayamadigim-tamamlayamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim', 'o-benim-emre-ugur-kucukyagci-scn4l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ararsa ellerin ellerimi, 

Gözlerinde yağmurlar, 

Üzülme... 

Yum gözlerini usuldan. 

Bak yüreğindeyim. 

Estirme hüzün rüzgârlarını, 

Kov sahilinden deli dalgaları.

Sakin, serin pınarlarda 

.............çağlar damlalarım... 

Dağlardan esen meltemlerde, 

Akan çeşmende benim. 

Yıka yüreğini temiz sularımda, 

Gönlünde melankoli kalmasın, 

Şifalıdır damlalarım, 

Ben yağmurum, 

Yağmur, 

Benim...', 'Ararsa ellerin ellerimi,  Gözlerinde yağmurlar,  Üzülme...  Yum gözlerini usuldan.  Bak yüreğindeyim.  Estirme hüzün rüzgârlarını,  Kov sahi...', ARRAY['Türk Edebiyatı','Şiir','Emre Uğur Küçükyağcı']::text[], 8.5, '{"poet":"Emre Uğur Küçükyağcı","poet_slug":"emre-ugur-kucukyagci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-benim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleğim', 'melegim-emre-ugur-kucukyagci-0upjq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani bulutlarla bana haber yollayacaktın, 

Sen her yağmur damlasına bir kelime yazacak; 

bende o damlaları avuçlarıma alıp, 

yazdığın mektubu okuyacaktım.

Kokunu çiçeklere iliştirip yollayacaktın hani? 

Söz vermiştin...

Bülbüller sözlerini getirecekti bana. 

Dalgalar, vurup vurup hasretini solumayacak mıydı? 

Yıldızlar, sana giden yolu gösterecek, 

mehtap, yolumuzu aydınlatacaktı.

Aşkımıza ondan başka kimse şahit olmayacaktı

Öyle sevecektik ki bibirimizi, 

sorgusuz sualsiz girecektik cennete.

Kıskanacaktı nur''umuzu melekler bile... 

Şimdi neden solgunsun böyle bir tanem, 

Niçin açıp gözlerini ellerimden tutmuyorsun? 

Uzat ellerini, al beni de yanına.

Bunca hasret yetmez mi çıkmak için katına, 

Yoksa gittin ve unuttun mu beni; 

Unuttun mu oralarda? 

Göz kırp bana yıldızlardan.

Bir an bile durmam buralarda inan; 

Davetini bekliyorum

Çağır geleyim artık, 

Çağır meleğim artık.', 'Hani bulutlarla bana haber yollayacaktın,  Sen her yağmur damlasına bir kelime yazacak;  bende o damlaları avuçlarıma alıp,  yazdığın mektub...', ARRAY['Türk Edebiyatı','Şiir','Emre Uğur Küçükyağcı']::text[], 8.5, '{"poet":"Emre Uğur Küçükyağcı","poet_slug":"emre-ugur-kucukyagci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/melegim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akan', 'akan-kursat-usalan-g7xu3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşle güzeliz hepimiz

Karanlıkta yokuz

Tarihle anlaşılır

Eylemde anlamlanırız

Bilinçle kurar, anlatırız

Şiir yazarız

Şarkı söyler

Aşklar yaşarız

Diyar diyar

Gönül gönül dolaşır

Kavgalara tutuşur, 

Barışlara kavuşuruz

Bir ırmaktır hikayemiz

Sonsuza akarız

Ne de olsa 

İnsanlarız

06.01.1994

ANKARA', 'Güneşle güzeliz hepimiz Karanlıkta yokuz Tarihle anlaşılır Eylemde anlamlanırız Bilinçle kurar, anlatırız Şiir yazarız Şarkı söyler Aşklar y...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/akan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Acil Değil!', 'ask-acil-degil-erdinc-ozdemir-n63v0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahın ilk saatleri

Güneş gözlerini açmış çiçekleniyor başlayan güne

İşe gidiyor güneşi unutan akşamlaşmış insanlar

Giysileri solmuş yürekleri yağmur dolu

Evlerin birinde bir nine takma dişleriyle gençliğini çiğniyor

Eksik düğmeli kadınlar kapatılmışlar odalara

Günün her saati cinsellik pazarlanıyor

Bir kadın biraz dalgın

Duvardaki fotoğrafa takılı kalmış gözü

Ne güzel kaydırak oynuyormuş çocukken

Simsarlar dört dağılmış aşka zar atıyorlar

Tamamı ıslanmamış günler ve sokaklar

Çantaların içine sinmiş imtiyazlı evraklar

Anahtarsız şarkılarla

Suçu yok masalarda patlatılıyor şampanyalar

Bütün köşelere kara eldivenli adamlar tünemiş

Geride ayak izlerini bırakan gün geceyi giyerken

Kendine yas ilan etmiş bir flüt çalıyor', 'Sabahın ilk saatleri Güneş gözlerini açmış çiçekleniyor başlayan güne İşe gidiyor güneşi unutan akşamlaşmış insanlar Giysileri solmuş yürekl...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Özdemir']::text[], 8.5, '{"poet":"Erdinç Özdemir","poet_slug":"erdinc-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-acil-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecedir Insani Insan Yapan', 'gecedir-insani-insan-yapan-sair-anonym-9qihg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecedir insani insan yapan o güzel duygulari tattiran, 

Elinde kalem önünde kagit, hadi yaziver

Duygularini, 

Kimselere anlatmaya kiyamadiklarini! 

Gecmisten sakladiklarini, esirgeme bizden', 'Gecedir insani insan yapan o güzel duygulari tattiran,  Elinde kalem önünde kagit, hadi yaziver Duygularini,  Kimselere anlatmaya kiyamadikl...', ARRAY['Türk Edebiyatı','Şiir','Şair Anonym']::text[], 8.5, '{"poet":"Şair Anonym","poet_slug":"sair-anonym","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gecedir-insani-insan-yapan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kınalı Kar', 'kinali-kar-gamze-ozer-gob2s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ötelerde bak bir köy var

Güneşi az, eksik bahar

Ayırmışlar seni beni

Unuttun mu köyünü yar

Göğe doğru avcum kanar

Duam sana, alma nazar

Sensiz geçen günlerime

Hasret ektim azar azar

Kınalı Kar Kınalı Kar

Sende büyük bir ahım var

Gelinlerin güveylerin

Kavuşmaz mı yüce dağlar

Nar çiçeğim, masal yüzlüm

Teni goncam, kömür gözlüm

Kınan Karda bitecekse

Varsın alsın beni ölüm', 'Ötelerde bak bir köy var Güneşi az, eksik bahar Ayırmışlar seni beni Unuttun mu köyünü yar Göğe doğru avcum kanar Duam sana, alma nazar Sens...', ARRAY['Türk Edebiyatı','Şiir','Gamze Özer']::text[], 8.5, '{"poet":"Gamze Özer","poet_slug":"gamze-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kinali-kar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göreceksin', 'goreceksin-erhan-sesli-wk1sz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görebilmektir her şeyin anahtarı, göreceksin

Güneşin doğuşunu, yağmurun yağışını, ırmağın akışını

Şu koskoca evrende devinimi göreceksin

Rüzgarın esişini göreceksin

Göreceksin ki rüzgarla beraber eseceksin..

Dikeni değil gülü, 

Gülün kokusunu göreceksin

Bataklığı değil, yaşamı göreceksin

Kelebekleri, böcekleri, kuşları

Kurbağaları, salyangozları, larvaları

Balıkların yüzüşünü, kuşların ötüşünü göreceksin

Göreceksin sesleri, kokuları

Sıcağı, soğuğu göreceksin..

Geçmişini göreceksin, ordan da geleceğini

İneni göreceksin ki çıkasın

Düşeni göreceksin ki kalkasın

Bileni göreceksin ki bilesin

Güleni göreceksin ki gülesin

Seveni göreceksin ki.......', 'Görebilmektir her şeyin anahtarı, göreceksin Güneşin doğuşunu, yağmurun yağışını, ırmağın akışını Şu koskoca evrende devinimi göreceksin Rüz...', ARRAY['Türk Edebiyatı','Şiir','Erhan Sesli']::text[], 8.5, '{"poet":"Erhan Sesli","poet_slug":"erhan-sesli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/goreceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-edip-ozan-karaoglu-5xx31', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tıkanıyor hüznünüm aşka çalan mavisi 

ben sanki kimse değil gibi yürüyorum kaldırımlarda 

ayaklarıma vurulan prangaları tarihin 

geliyor doymak bilmez pençeleriyle üstüme 

karanlığa daha çok küfrediyorum daha çok 

anlaşılsın istiyorum yalanların dünyası 

suskunluğum yüzünden mi başıma gelenler 

bildiğim her şeyi bağırmadığım için mi tersine dönüyor dünya 

çirkinim biliyorum ve en çok ben kirletiyorum dünyayı 

tarihin en kafir ve en acımasız çocuğu bildim kendimi 

ölümle bir anlaşma yaptım 

kendi kandırmacamın arkasına sığındım 

sonu geldi artık zamanın 

çünkü ben gökten aldığımı çaldırdım çözümsüzlüğe

ve bütün senetlerini yaktım kaybolan günlerimin 

bulamadım dağ kuytusunun suskunluğunu 

yaşamanın en zor yanı buydu 

deli saçlarında yıldız takılıyken

dikenli tellerin arkasında 

uzaktan göz kırpmak aşka 

varlığın iki adım ötedeyken 

ben bir yanardağ ile boğuşurdum geceleri 

çünkü anlamazdı aydınlık ateşin dilinden 

ateş ve kavga ve aşk 

kimin adının üstünde yükselmişse 

o çağırıyor artık şeytanın ayaklarını 

başlıyor tarihin kaygan sayfaları 

durduğun kabahat diyorsun bana 

durmamak elde mi

kalbim bir ağacın dalında asılıyken 

artık daha çabuk eriyor karlar 

ama kimsenin baharlardan bir şey beklediği yok 

bekledim bütün baharları 

çözülsün istedim sır 

çünkü ben ne zaman koşsam bir yanardağa doğru

sırtımdaki yükün ağırlığı katlandı

şimdi atmak için bütün yüklerimi

baştan başlıyorum küfrü deşmeye 

anlıyorum neydi kul olmanın hikmeti 

neden bırakmaya çalıştım aciz olmanın güzelliğini

boyun eğmek nerelere götürür insanı anladım 

anladım O’nun benden bir parça olduğunu!', 'tıkanıyor hüznünüm aşka çalan mavisi  ben sanki kimse değil gibi yürüyorum kaldırımlarda  ayaklarıma vurulan prangaları tarihin  geliyor doy...', ARRAY['Türk Edebiyatı','Şiir','Edip Ozan Karaoğlu']::text[], 8.5, '{"poet":"Edip Ozan Karaoğlu","poet_slug":"edip-ozan-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sir-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşça Kal', 'hosca-kal-mustafa-sureyya-sezgin-en47f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzakların özlemi var içimde

Gitmeliyim.

Sonu yok mu, 

Zaten başlangıcı olan her şeyin? 

Bu bir veda değil

Elveda! 

Hani bazı laflar vardır

İçi boştur, kopuktur anlamından

Öylesine usulen söylenir işte! 

Usulen yaşadığımız, 

Usulen seviştiğimiz gibi.

Zamanı geldi sanırım

Dur diyenim yok nasılsa

Artık ben de gitmeliyim

Hoşça kal

Görüşürüz! 

(İstanbul,23.08.2002)', 'Uzakların özlemi var içimde Gitmeliyim. Sonu yok mu,  Zaten başlangıcı olan her şeyin?  Bu bir veda değil Elveda!  Hani bazı laflar vardır İ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hosca-kal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmez mi Birden', 'bitmez-mi-birden-cumhur-turan-sbkpn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ağır ağır

çekerken balık ağını

balıkçı

yüreği ağdadır

umudu

düşü

o ağın içinde çırpınmaktadır

sanki yaşamdır çekilen

ağlarda

yüzyıllardır

umut ve düşün

hüzünle sevincin

gelgitlerinde

yarında ne var 

derken

yaşamda bitmez mi

birden', 'ağır ağır çekerken balık ağını balıkçı yüreği ağdadır umudu düşü o ağın içinde çırpınmaktadır sanki yaşamdır çekilen ağlarda yüzyıllardır um...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bitmez-mi-birden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sakalım', 'kara-sakalim-asik-i-hsani-ox8ei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sakal seni güzel için taşırım

Ben seni kesemem kara sakalım

Güzel görünce hafifce kaşırım

Ben seni kesemem kara sakalım

Hacı gibi üç beş karı almadan

Sofu gibi yanlış namaz kılmadan

Camilerde halı kilim çalmadan

Ben seni kesemem kara sakalım

İhsaniyem sakal değil gözümsün

Kullanmağa elde büyük kozumsun

Halkı kandırmağa bana lazımsın

Ben seni kesemem kara sakalım', 'Sakal seni güzel için taşırım Ben seni kesemem kara sakalım Güzel görünce hafifce kaşırım Ben seni kesemem kara sakalım Hacı gibi üç beş kar...', ARRAY['Türk Edebiyatı','Şiir','Aşık İhsani']::text[], 8.5, '{"poet":"Aşık İhsani","poet_slug":"asik-i-hsani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kara-sakalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlüyorum', 'seni-ozluyorum-erhan-sesli-axykp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şeyde sen

Her yerde sen çıkıyorsun karşıma

Evimin her odasında sen oturuyorsun

Her bir köşeye sen sinmişsin

Baktığım her yerde sen oluyorsun

Sokağa çıkıyorum, yine sen

Otobüse biniyorum, sen

Denize bakıyorum, gökyüzünü seyrediyorum

Sen....Hep sen...

Kime baksam senden bir şeyler görüyorum

Bir kadın senin çantanı taşıyor

Bir diğeri en sevdiğin eteğini giymiş

Birisinin gülüşü tuhaf bir şekilde seninkini andırıyor

Garip, uzaktan herkesi  sana benzetiyorum

Kokunu alıyorum bazen gaipten

Sesin çınlıyor odamın duvarlarımda

Belki sensindir diye ümid ederekten

Heyecanlanıyorum telefonum her çaldığında 

Sonra aynı sıkıntı, aynı yalnızlık... 

En sevdiğin yemeği pişirdim bu gün

Oturup en sevdiğin programı izledim

Sana ilk kez seni sevdiğimi söylediğimde

Radyoda çalan şarkıyı defalarca dinledim

Sonra senin sigarandan yaktım bir tane, hiç içmediğim halde

Öksürmedim bile 

Hava basık, bulutlu

O yüzden yıldızımızı göremedim gökyüzünde

Böyle havalarda daha çok sıkılıyorum

Yine böyleydi çünkü çekip gittiğinde

Özlüyorum

Konya, 2002  yazı', 'Her şeyde sen Her yerde sen çıkıyorsun karşıma Evimin her odasında sen oturuyorsun Her bir köşeye sen sinmişsin Baktığım her yerde sen oluyo...', ARRAY['Türk Edebiyatı','Şiir','Erhan Sesli']::text[], 8.5, '{"poet":"Erhan Sesli","poet_slug":"erhan-sesli","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seni-ozluyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merdivenleri Usul Usul', 'merdivenleri-usul-usul-erdem-ozsoysal-k5vsx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merdivenleri usul usul çıkarken; 

yaşamda bıraktığım her bir halka

bilinmiyen yüklerin ağırlığıyla ezilirken

benden çoktan gitmiş aşklara; 

görecelik kuramlarıyla karşı çıktım

ve bana emanet  edilen bedene ihanat ettim.

Tek suçum seni sevmekti...', 'Merdivenleri usul usul çıkarken;  yaşamda bıraktığım her bir halka bilinmiyen yüklerin ağırlığıyla ezilirken benden çoktan gitmiş aşklara;  ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özsoysal']::text[], 8.5, '{"poet":"Erdem Özsoysal","poet_slug":"erdem-ozsoysal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/merdivenleri-usul-usul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklersin', 'beklersin-emrah-olgun-cuyvg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beklersin, gün gelse rüzgar esse; 

Yardan haber getiren...

Gün gelse yagmur yagsa; 

Yalnızlıgını temizleyen...

Gün gelmez, can, gün gelmez..

Ölüm gelir sessiz sessiz, gün gelmez...

Kara toprak çeker canı; 

''Umut'' izin vermez..

(2002, İzmir)', 'Beklersin, gün gelse rüzgar esse;  Yardan haber getiren... Gün gelse yagmur yagsa;  Yalnızlıgını temizleyen... Gün gelmez, can, gün gelmez.....', ARRAY['Türk Edebiyatı','Şiir','Emrah Olgun']::text[], 8.5, '{"poet":"Emrah Olgun","poet_slug":"emrah-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beklersin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorular', 'sorular-arsima-muhammet-dereci-ujakv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne giydiğini yaz bana! Sıcak tutuyor mu? 

Uyuduğun yeri yaz bana! Yumuşak mı? 

Nasıl göründüğünü yaz bana! Yüzün aynı mı? 

Neyi özlediğini yaz bana! Kolumu mu? 

Nasıl olduğunu yaz bana! Rahat mı? 

Sana neler yaptıklarını yaz bana! Cesaretin yetti mi? 

Ne yaptığını yaz bana! iyi şeyler mi? 

Neler düşündüğünü yüz bana! Beni mi? 

Sorulardır sana bütün verebildiğim 

Ve gelen yanıtları kabullenmeliyim 

Yorgunsan, uzatamam sana elimi. 

Ya da açsan seni besleyemem 

sanki bu dünyada hiç yokmuşum 

Unutmuşum gibi seni.', 'Ne giydiğini yaz bana! Sıcak tutuyor mu?  Uyuduğun yeri yaz bana! Yumuşak mı?  Nasıl göründüğünü yaz bana! Yüzün aynı mı?  Neyi özlediğini y...', ARRAY['Türk Edebiyatı','Şiir','Arsima Muhammet Dereci']::text[], 8.5, '{"poet":"Arsima Muhammet Dereci","poet_slug":"arsima-muhammet-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sorular-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serap', 'serap-murat-serbetci-ck2pz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben en çok annemi sevdim

Bir de seni

Ne çok benziyorsunuz

O beni dünyaya getirdi

Sen ise öldürdün!', 'Ben en çok annemi sevdim Bir de seni Ne çok benziyorsunuz O beni dünyaya getirdi Sen ise öldürdün!...', ARRAY['Türk Edebiyatı','Şiir','Murat Şerbetçi']::text[], 8.5, '{"poet":"Murat Şerbetçi","poet_slug":"murat-serbetci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/serap-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Seni Bekledim', 'hep-seni-bekledim-arsima-muhammet-dereci-la7h0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzümün bu kadar aydınlık olması niye biliyor musun? 

Neden bu kadar içten gülüyorum? 

Yaşamdan bu denli keyif almamın nedeni ne? 

Kendime baktığım zaman sadece seni görüyorum artık.

Sesini duydukça yenileniyorum, mutlu oluyorum, keyifleniyorum

Hep seni bekledim ben, seni aradım.

Başka yüzlere sen diye baktım.

Başka kollara sen diye sarıldım.

Herkesi sen sandım ama yanıldım.

Senin gibi olamazdı hiçbiri.

Ne gülüşleri sendin, ne gözleri

Onlar sadece birer süretti.

Ruhu, Ateşi, Yüreği olmayan birer süret....

Kızdım kendime.

Seni yeterince aramadığım için suçladım kendimi.

Yoruldum aramaktan.

Kabuğuma çekildim, 

Sustum.

Gecelerimi yıldızsız kıldım, 

Gündüzlerimi ışıksız.

Her mevsim seni yaşadım.

Yağmur olup ıslattın beni, 

Kar olup üşüttün.

Sonbaharda ağaç olup yapraklarını döktün üzerime

Baharda renk renk çiçek olup açtın bahçemde

Yazın Sarı sıcak güneş olup ısıttın beni.

Kadeh kadeh içki oldun, içtim.

Bana bakıp “Ne Oluyor Sana” diyenlere cevap bile vermedim.

Seni unuttuğumu, 

Artık aramadığımı sansınlar istedim.

Güldüm.

Gülüşümle aldattın onları.

İnandılar.

Seni yaşamaktan hiçbir zaman vazgeçmedim oysa

Uzaktaydın sen.

Ama bir o kadar da içimdeydin

Beni izliyordun biliyordum.

Seni göremesem de oralarda bir yerde bana baktığını biliyordum.

Sana sakladım içimde yıllardır biriktirdiğim sevgiyi.

Yüreğimde ki heyecanı, 

Gözlerimde ki yeşili, 

Dudaklarımda ki ateşi, 

Ellerimde ki titremeyi, 

Küçük dokunuşları, 

Sana sakladım

Ve bir gün, 

Çıktın karşıma.

Şimdi seni bulduğum içindir bu çucuksuluğum.

 Seni bulmanın coşkusudur bu içimden dışarıya taşan..

Yepyeni bir hayatın başladığını biliyorum

Ve bu hayatın içinde vazgeçilmez kıldığım tek şeyin 

SEN OLDUĞUNU da......

				 	ARSiMA', 'Yüzümün bu kadar aydınlık olması niye biliyor musun?  Neden bu kadar içten gülüyorum?  Yaşamdan bu denli keyif almamın nedeni ne?  Kendime b...', ARRAY['Türk Edebiyatı','Şiir','Arsima Muhammet Dereci']::text[], 8.5, '{"poet":"Arsima Muhammet Dereci","poet_slug":"arsima-muhammet-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/hep-seni-bekledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Aklıma Getiren', 'seni-aklima-getiren-mine-unlu-927ty', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susmaktı, düşünmekti seni aklıma getiren.

Bazen gözlerimin uzaklara dalmasıydı.

Bazense anıları üstüste koyup, hayal etmekti gelmeni.

Mevsimler hep hazana çalıyordu içimde, sen yoktun.

Uzaktaydın, bilemezdin üşüdüğümü düştüğüm sensizlikte.

Oysa durmak bilmez özlemin farklı hüzünler giydiriyordu bedenime.

Beklemenin bile buruk bir tadı vardı ardından gelecek sen isen.

Susmaktı, düşünmekti gene bu gecede, seni aklıma getiren.

                                                                                 16.5.2002', 'Susmaktı, düşünmekti seni aklıma getiren. Bazen gözlerimin uzaklara dalmasıydı. Bazense anıları üstüste koyup, hayal etmekti gelmeni. Mevsim...', ARRAY['Türk Edebiyatı','Şiir','Mine Ünlü']::text[], 8.5, '{"poet":"Mine Ünlü","poet_slug":"mine-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-aklima-getiren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sandukalar', 'sandukalar-asaf-halet-celebi-g1ped', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sandukalarda can yatıyor

canlar içinde bir can var

canlar içindeki

câaan

sandukalarda yazılar var

kendi kendini okuyor

kendi kendini okuyan

yazılar

sandukalar öd ağacından

misk ile amber kokuyor

cânımda tüten bir koku var

câaan', 'sandukalarda can yatıyor canlar içinde bir can var canlar içindeki câaan sandukalarda yazılar var kendi kendini okuyor kendi kendini okuyan ...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sandukalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fransa İçin Şiir', 'fransa-i-cin-siir-asaf-halet-celebi-i9nf1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çocukluk arkadaşım petit-poucet

yamyam devin kilerindedir

küçük kızkardeşi ormanda ağlıyor

tin tin eder kabâcik

beni bırakıp giden babâcık

ormanlardan

güneşli tarlalara koşan çizmeli kedi

ne olur

kurtar benim marquis de carabasse''imi

yanan paris''in çocuklarını

öperek ağlamak istiyorum

belki masallarımla uyurlar

(1940)', 'çocukluk arkadaşım petit-poucet yamyam devin kilerindedir küçük kızkardeşi ormanda ağlıyor tin tin eder kabâcik beni bırakıp giden babâcık o...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/fransa-icin-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretinin Böylesi', 'hasretinin-boylesi-ercan-gencer-40mcz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İsmini koyamadığım bir burukluk var  içimde

Bütün dostukları bir kalemde silmiş gibi 

Bir sıcacık alo''n çınlar kulaklarımda 

Hasretinin böylesine dayanılmaz 

Her an seni görmeyi arzularım delicesine

İmkanlarımı  zorlarım bir saniye sesini duyayım diye

Çoğu zaman bir hayal kırıklığı yaşarım 

Hasretinin böylesi çekilmez

Nedir beni sana bağlayan bir bilebilsem 

Keşke aradaki sanallığı kaldırabilsem 

Yazmak, duymak  bir tarafa ellerine değebilsem 

Hasretinin böylesi yakmazmı

Ben hasret denizinde senden  yoksun çaresiz 

Kendiyle başbaşa kalmakta 

Neredesin duygularımı harmanlayan biriciğim

Hasretinin  böylesi öldürmezmi

Sen bebeğimsin yüzünü göremediğim 

Duygularımın sağanak yağmuru, sevdiğim 

Gönül yaram, zaman geçmiyor... 

Hasretinin  böylesi çekilirmi canım biriciğim...', 'İsmini koyamadığım bir burukluk var  içimde Bütün dostukları bir kalemde silmiş gibi  Bir sıcacık alo''n çınlar kulaklarımda  Hasretinin böyl...', ARRAY['Türk Edebiyatı','Şiir','Ercan Gencer']::text[], 8.5, '{"poet":"Ercan Gencer","poet_slug":"ercan-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasretinin-boylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik', 'lirik-kursat-usalan-7173u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'LİRİK

I-

Bir yağmur düşü kurdum kendime

Hesapsız, sımsıcak.

Bir açtım avuçlarımı gökyüzüne, 

Uçuverdi bütün güvercinler.

Ardlarına bakmadan terkettiler

Sonra…yalnız kalmasını öğrendim, 

Ağlayamamasını da.

Yanlışlarım olmuş, ama hesaplı.

Karanlık, puslu havaları anımsatan.

Öyle havaların bile vardır bir güzelliği.

O kahrolası hesapların yok.

Terkeden sevgilililer gibi acımasızlaştı yaşam

Balıklar gibi sessiz kaldım.

Bir şarkı, bir şiir, 

uzaklardan bir mektup? … yok! 

Kuruttum dünün düşlerini

II-

Yeniden yolculuklara gebe kalacak mıyım acaba? 

Koca koca dağların ardından deniz görünecek mi ansızın? 

O denizler ve içim kıpır kıpır.

Bahar akşamüstülerinin koyu yeşil dalları 

ve Apollon, 

güzel bir kız, tatlı ve koyu bir şöyleşi, 

kitaplar üzre, sansürsüz.

Ardına bakmadan terketmenin kahramanca doyumu

ve…

yorulmuş bir günün gecesinde, 

sabahın tazeliğine özlenmiş deliksiz bir uyku.

III-

Küsmezmiş insanlara güvercinler, 

Diyorum kendi kendime

Yorulmadan kurmalı o düşü.

Sanırım birer çakıl taşıyız hepimiz

Aşındıkça güzel.

Sayamayız ki kendimizi

Güzel olmalı en hırçın dalgaların 

Kucağında yaşamak

Küsmez insanlara güvercinler.

Mutlaka döner konarlar, 

Ayışığında çakıl ellerimize.

Yüreklerimizin kıpır kıpır esintisiyle coşar, 

Kanat sesleriyle melodilendirirler sahili

Bir uçtan bir uça.

Okaynusların esintisini taşırlar ebemkuşağı renginde

O zaman gece de bir ateş yakar

başlar dansetmeye o ateşin çevresinde.

Isınır yüreklerimiz…

Başlar tekrar kan pompalamaya…

Yaşam pompalamaya…

Düş pompalamaya…

Kimbilir? 

Yağmur düşleri belki.

				13.01.1994

				ANKARA', 'LİRİK I- Bir yağmur düşü kurdum kendime Hesapsız, sımsıcak. Bir açtım avuçlarımı gökyüzüne,  Uçuverdi bütün güvercinler. Ardlarına bakmadan ...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/lirik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metazori', 'metazori-kursat-usalan-d6qsf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'METAZORİ

Uykusuzlar

Nasıl yaşarlar bilir misiniz? 

Ne zaman düş görürler? 

Gecenin bir yarısı, 

Dem buğusu bir bardak çayı

Ne niyetine içerler? 

İki göz kapağının vuslatına özlem dışında, 

Neyi özlerler bilir misiniz? 

Ve bilir misiniz ki, 

asla bilmezler: 

Gün, 

hergün aynı yerden doğar; 

üç aşağı beş yukarı

hep aynı esintiyle.

				17.01.1994

				ANKARA', 'METAZORİ Uykusuzlar Nasıl yaşarlar bilir misiniz?  Ne zaman düş görürler?  Gecenin bir yarısı,  Dem buğusu bir bardak çayı Ne niyetine içerl...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/metazori-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıdık', 'tanidik-kursat-usalan-se3hy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'TANIDIK

Söz oldu, sakındım seni.

Kaçındım köşe bucak dertetmelerinden

Tren düdükleri böldü

gecelerimi iki eşit parçaya

Ama öğrendim ki artık; 

sen de  yabancısın benim kadar bu kente

				08.05.1994

				İSTANBUL', 'TANIDIK Söz oldu, sakındım seni. Kaçındım köşe bucak dertetmelerinden Tren düdükleri böldü gecelerimi iki eşit parçaya Ama öğrendim ki artık...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tanidik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sukut-u Hayal', 'sukut-u-hayal-kursat-usalan-t3ysf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SÜKUT-U HAYAL

Beklenmedik aşkların albenisinde buluyoruz

en  serseri yolculuklarımızı

Ben bir denizaltıyım şimdi.

Denizi soluyorum ama, 

şiir  yazamıyorum ona.

Ne mavisini biliyorum, ne bulutunu görüyorum.

Balıklar kayınvalidem kadar çirkin.

Oysa İstanbul öyle miydi dostlar? 

Buraların baharı güzü yok.

Düğünleri tango ile açan gelin ve damatları…

geceleri ince ince dokuyan liman serserileri…

balıkçıları, içkicileri…

ayışığı…

yok.

Çok sevdiğim denizi yaşıyorum

ama, 

bilmiyorum kardeşlerim! 

Aşık olmadıkça

sosisli sandöviç gibi bir şey yaşam

doymuyorum

				31.05.1994	

				İSTANBUL', 'SÜKUT-U HAYAL Beklenmedik aşkların albenisinde buluyoruz en  serseri yolculuklarımızı Ben bir denizaltıyım şimdi. Denizi soluyorum ama,  şii...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sukut-u-hayal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik Kalmış Yutkunmalar', 'eksik-kalmis-yutkunmalar-hasan-sabah-i1ydh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hüzünle esiyor, 

Eylül evvelinde yalnızlıklar

Hafakanlar titretiyor gecemi

Yapraklar sararmıyor, 

Gurbet, 

Canımı acıtıyor...

Yarınarı heceliyorum, 

Lime lime olmuş

Sevda vurgunları yüreğimde, 

İhtiyacım var özlemeye, 

Özlenmeye, 

Son kez, ilk defa

Yalan söylüyorum, 

Yüreğime.

Geceler sabahsız olmuyor

Sözüme çektiriyor damağımda, 

Şak şak, şok mutsuzluklar.

Gülümsemeye ağlamaklı, 

Rüzgarlar, 

Dalgalara aşık

yalnız kıyılar.

Aşk ah aşk

Mutsuzluklar.

dağlanmış günümde

Güneş saklı bulutların ardında, 

Eksik kalmış yutkunmalar

Boğazımda düğüm düğüm, 

Adımlarımı sıklaştırıyorum

Kaçarken geçmiş zamandan

Ağlıyorum, 

Süzülürken gözümden yaşlar, 

Yavaş yavaş

Ölüyorum.', 'Hüzünle esiyor,  Eylül evvelinde yalnızlıklar Hafakanlar titretiyor gecemi Yapraklar sararmıyor,  Gurbet,  Canımı acıtıyor... Yarınarı hecel...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sabah']::text[], 8.5, '{"poet":"Hasan Sabah","poet_slug":"hasan-sabah","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/eksik-kalmis-yutkunmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İnsan Bile Değilsin', 'sen-i-nsan-bile-degilsin-ali-saglam-3-q07th', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan doğar, büyür, yaşar ve ölür

Diye geçer tıp literatüründe, 

Sen bir insan bile değilmişsin, 

Doğdun, büyüdün, yaşadın 

Ama ölmedin içimde...! ! !', 'İnsan doğar, büyür, yaşar ve ölür Diye geçer tıp literatüründe,  Sen bir insan bile değilmişsin,  Doğdun, büyüdün, yaşadın  Ama ölmedin içim...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-insan-bile-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstisna Kadınlar - Kadın Severse Tam Sever', 'i-stisna-kadinlar-kadin-severse-tam-sever-ali-saglam-3-pfhhi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ketrin''e...

Ah be güzelim.

Bir insan o kadar mı sever? 

O kadar mı duygulu, 

O kadar mı sevdalı olabilir? 

Sevecenlikse sende, 

İçtenlikse sende, 

Duyguysa sende, 

Aşksa sende, 

Görmedim senin gibisini, 

Tanımadım yüreğin böylesini

Ruhun rehin kalsada, 

Bir bebeğin, 

Cansız bedeninde...

Ah be güzelim

Yaşıyor inan, 

Aşkın her hali, 

Senin gözbebeklerinde, 

Doğuştan aşk yazılmış senin kaderine, 

Bir sevda kurşunuyla vurulup ölsende, 

Toprağında rahat uyu...

Aşkın yaşıyor dillerde, 

Sen yaşamıyor olsan bile,', 'Ketrin''e... Ah be güzelim. Bir insan o kadar mı sever?  O kadar mı duygulu,  O kadar mı sevdalı olabilir?  Sevecenlikse sende,  İçtenlikse s...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/istisna-kadinlar-kadin-severse-tam-sever-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ce Sevmek', 'ben-ce-sevmek-ali-saglam-3-6v0uj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi elle tutulmayan

Gözle görülmeyen, 

Sevgi bakışlarda başlayan

Kalpte hissedilen, 

Sevgi damarlarda dolaşan

Gözlerde hapsedilen

Sevgi sonunda hüsran

Devamında elem, 

Olan bir duygudur....', 'Sevgi elle tutulmayan Gözle görülmeyen,  Sevgi bakışlarda başlayan Kalpte hissedilen,  Sevgi damarlarda dolaşan Gözlerde hapsedilen Sevgi so...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ben-ce-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Veda', 'son-veda-ali-saglam-3-14yx7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne umut bıraktın seven gönlümde, 

Ne sabır bıraktın, ne kalacak hal, 

Baktığın gözlerde sevgi bırakmadın, 

Gidiyorum sevgilim hoşçakal...

Yarınım dünden beter olsa da, 

Hasretin içimi hergün yaksa da, 

Bir sevdiğim sendin şu diyarda, 

Gidiyorum sevgilim hoşçakal...

Her gün ağlasamda maziye bakıp, 

Bir daha yalvarmam önünde diz çöküp, 

Böyle yaşayamam boynumu büküp, 

Gidiyorum sevgilim hoşçakal...

Burası senin yaşa gönlünce, 

Yalvarsan da dönmem geri ömrümde, 

Bu şarkım son vedam çünki bu gece, 

Gidiyorum sevgilim hoşçakal...', 'Ne umut bıraktın seven gönlümde,  Ne sabır bıraktın, ne kalacak hal,  Baktığın gözlerde sevgi bırakmadın,  Gidiyorum sevgilim hoşçakal... Ya...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-veda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Yağmuru', 'yaz-yagmuru-ali-saglam-3-857ze', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün seni gördüm yeniden

Tam hatırladığım gibi, 

Yine o sarı uzun saçlar, 

Sımsıcak bakışlar, 

Yine o aynı heyecan, 

Ve karşımda herşeyinle sen.

Unutulmayacak kadar güzel, 

Arındırılmayacak kadar billursun...

Baha kucak açmış toprak gibisin, 

Yine herşeyinle biraz durgun

Ama herzaman şen-şakrak, 

Baharda açan kırçiçekleri gibi, 

Başı dumanlı dağlar gibi

Bent vurulmaz seller gibi

Yine coşkunsun, deli ırmaklar gibi...

Ve yine duruyorsun gözlerimde, 

Bir yaz yağmuru gibi...', 'Bu gün seni gördüm yeniden Tam hatırladığım gibi,  Yine o sarı uzun saçlar,  Sımsıcak bakışlar,  Yine o aynı heyecan,  Ve karşımda herşeyinl...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yaz-yagmuru-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Arkadaş', 'seviyorum-arkadas-ali-saglam-3-za86o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'S-eviyorum seviyorum demekten, 

E-n güzel hayallerle avunmaktan, 

V-e saatlerce seni düşünüp beklemekten, 

İ-nan canım inan o iki kelimeyi bekledim senden

Y-arınlarımda, bugünlerimde tüm benliğimde

O-güzel gülüşün yüreğimde

R-azıyım ölüme ve herşeye seninle birlikte

U-zak olsanda kavuşulması zor olsanda

M-utluluğa koşarım seninle birlikte birtanem...', 'S-eviyorum seviyorum demekten,  E-n güzel hayallerle avunmaktan,  V-e saatlerce seni düşünüp beklemekten,  İ-nan canım inan o iki kelimeyi b...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seviyorum-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak Seslerin', 'ayak-seslerin-ali-saglam-3-qpq7o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir fısıltı duyarım yalnız kaldığımda

İçim ürperir birden

Kulaklarımı kabartırım hemen bu sese

Sen geldin sanırım birden, 

Bakarım ki gelen sen değilsin, 

Sen değil ayak seslerin...

Bir gün geleceksin diye

Beklerim ezelden beri, 

Beklerken hayallere dalarım, 

Kapı çalınır birden, 

Koşup açarım hemen, 

Yine gelen sen değilsin

Sen değil ayak seslerin...', 'Bir fısıltı duyarım yalnız kaldığımda İçim ürperir birden Kulaklarımı kabartırım hemen bu sese Sen geldin sanırım birden,  Bakarım ki gelen ...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayak-seslerin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Canım Dedim Demez Olaydım.', 'sana-canim-dedim-demez-olaydim-ali-saglam-3-t64fi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana canım dedim, 

Canımda can bırakmadın, 

Sana sevdiğim dedim, 

İçimde sevgiden eser bırakmadın, 

Sana yarim dedim, 

Ellerimi bırakıp, el olup gittin

Sana güzelim dedim, 

Demez olaydım, 

Aydınlık dünyamda güzellik bırakmadın, gittin...', 'Sana canım dedim,  Canımda can bırakmadın,  Sana sevdiğim dedim,  İçimde sevgiden eser bırakmadın,  Sana yarim dedim,  Ellerimi bırakıp, el ...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-canim-dedim-demez-olaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin o sevgi dediğin', 'senin-o-sevgi-dedigin-ali-saglam-3-bx8mn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok yabancı şimdi, gözlerin.

Hani bitmeyecekti sevgin.

Hani bozulmayacaktı yeminin.

Yalan söylemekmi yoksa.

Senin o sevgi dediğin? ? ? 

Düşünüyorumda taştan mı yoksa kalbin.

Sevgi diye ağlamaz mı gözlerin.

Yalandan başka şey bilirmi sözlerin.

Yalan söylemekmi yoksa.

Senin o sevgi dediğin? ? ?', 'Çok yabancı şimdi, gözlerin. Hani bitmeyecekti sevgin. Hani bozulmayacaktı yeminin. Yalan söylemekmi yoksa. Senin o sevgi dediğin? ? ?  Düşü...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/senin-o-sevgi-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
